-- Ejercicios actuales (909): textos reescritos, categoría y código externo.
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0016', descripcion = 'Fortalece los isquiotibiales en posición tumbado boca abajo, mejorando la flexión de rodilla y el equilibrio muscular del muslo.', instrucciones = ARRAY['Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.', 'Pide a un compañero o usa una banda elástica para sujetar tus tobillos.', 'Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'db6711e0-100d-4e01-ae83-14f1de81f7f2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0025', descripcion = 'Trabaja el pectoral mayor con apoyo de hombro anterior y tríceps, ejercicio básico para ganar fuerza y masa en el tren superior.', instrucciones = ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '4ec3e18b-cf6d-4d18-9c73-8cca787c7fb3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0033', descripcion = 'Enfatiza la porción inferior del pectoral con inclinación negativa, útil para completar el desarrollo del pecho y la fuerza de empuje.', instrucciones = ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'a5551c39-a5d5-458f-9140-ebc9ceea9f3b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0051', descripcion = 'Variante de sentadilla con barra sujeta entre las piernas que carga cuádriceps y glúteo, mejorando fuerza y control postural.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.', 'Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Empuja con los talones para volver a ponerte de pie en la posición inicial.', 'Repite el movimiento, alternando el pie delantero y el trasero en cada repetición.']::text[], actualizado_en = now() WHERE id = 'acdd8429-6384-4829-aafe-dedfa174a2a7';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '0053', descripcion = 'Sentadilla explosiva con barra que desarrolla potencia de piernas y reclutamiento rápido de fibras en cuádriceps y glúteos.', instrucciones = ARRAY['Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.', 'Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.', 'Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '47fc1c71-16d3-46b3-8b58-84922dbfdc3f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0065', descripcion = 'Press unilateral en el suelo que trabaja pectoral y tríceps, corrigiendo desequilibrios y limitando el rango para proteger el hombro.', instrucciones = ARRAY['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.', 'Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.', 'Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = '70536d8d-f050-4f11-bab9-a7561db0f27d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0066', descripcion = 'Peso muerto a una mano que exige fuerza de glúteo e isquiotibiales junto a estabilidad del core y control antirotación.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.', 'Mantén la espalda recta y el core activado.', 'Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.', 'Baja la barra tanto como puedas manteniendo una buena forma.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], actualizado_en = now() WHERE id = '35d3cf24-bf4d-4a98-a644-c2e6e7f25193';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0069', descripcion = 'Sentadilla con barra sobre la cabeza que combina fuerza de piernas con estabilidad de hombro y core, muy exigente técnicamente.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.', 'Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'cc8c3d83-ffa3-4eaf-91c4-da5442df5c71';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0078', descripcion = 'Zancada hacia atrás con barra que fortalece cuádriceps y glúteo, mejorando el equilibrio y reduciendo carga en la rodilla delantera.', instrucciones = ARRAY['Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.', 'Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.', 'Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.', 'Empuja con el talón izquierdo para volver a la posición inicial.', 'Repite con la otra pierna.']::text[], actualizado_en = now() WHERE id = '272725c4-2cd1-47c1-9d1d-2b827b811366';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0114', descripcion = 'Subida al cajón con barra que desarrolla fuerza unilateral de cuádriceps y glúteo, útil para potencia y estabilidad de piernas.', instrucciones = ARRAY['Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda.', 'Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.', 'Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla.', 'Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial.', 'Repite con la pierna contraria.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '1fc5adcc-5fb6-4c49-80a2-fe0eb437692b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fondos en banco que trabajan pectoral, hombro anterior y tríceps, buen ejercicio para empuje con material mínimo.', instrucciones = ARRAY['Siéntate en el borde del banco con las manos a los lados y las rodillas flexionadas, pies apoyados en el suelo.', 'Desliza la cadera fuera del banco y baja el cuerpo flexionando los codos hacia atrás hasta notar estiramiento en el pecho.', 'Empuja con las palmas para subir hasta extender los codos sin bloquear del todo, manteniendo el core activo.', 'Evita encoger los hombros hacia las orejas y no bajes más de lo que controle tu hombro.']::text[], actualizado_en = now() WHERE id = 'e8032a86-2426-4226-95da-ad980eac661a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0149', descripcion = 'Extensión de tríceps en polea alternando brazos, aislando el tríceps y permitiendo concentrarse en la técnica de cada lado.', instrucciones = ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados.', 'Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite con el brazo izquierdo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '78e0e0a3-e9d6-483c-8c2c-7fed38537fa9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0158', descripcion = 'Aperturas en polea con inclinación declinada que aíslan el pectoral inferior y controlan la tensión durante todo el recorrido.', instrucciones = ARRAY['Ajusta la máquina de cable a una posición declinada.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti.', 'Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.', 'Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'f5228249-0c02-4d10-933f-e46131e04585';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0164', descripcion = 'Elevación frontal en polea que trabaja el deltoides anterior con tensión constante, útil para hombros y empuje vertical.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.', 'Mantén la espalda recta y el core activado.', 'Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.', 'Continúa levantando hasta que los brazos queden paralelos al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '3bab2141-81e7-4abd-8104-14b39107ee57';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0169', descripcion = 'Press inclinado en polea que carga el pectoral superior con tensión continua, complementando el desarrollo del pecho y hombro.', instrucciones = ARRAY['Ajusta el banco a una inclinación de 45 grados.', 'Sujeta las agarraderas del cable a las poleas altas.', 'Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo.', 'Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros.', 'Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd77416f9-974d-4bdd-8b89-fc0756c2d121';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0173', descripcion = 'Aísla el tríceps braquial en estiramiento para ganar fuerza y volumen en la parte posterior del brazo.', instrucciones = ARRAY['Ajusta la máquina de cable a una posición de polea baja.', 'Sujeta una barra recta al cable.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza.', 'Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.', 'Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '653f1c1f-8454-45ad-8f33-25fac3939414';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0187', descripcion = 'Trabaja el tríceps en posición tumbada para aislar el brazo y mejorar la extensión del codo.', instrucciones = ARRAY['Túmbate en el suelo o banco con la polea baja detrás de la cabeza y agarra la cuerda con los codos apuntando al techo.', 'Extiende los codos llevando las manos hacia delante sin mover los brazos de su sitio.', 'Controla la vuelta dejando que el codo se flexione despacio hasta notar estiramiento.', 'Evita abrir los codos hacia los lados y mantén las muñecas firmes durante todo el recorrido.']::text[], actualizado_en = now() WHERE id = '63d29626-9cda-485b-9f01-783fae04ebde';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0188', descripcion = 'Abre el pectoral desde media altura para trabajar la parte interna del pecho con tensión constante.', instrucciones = ARRAY['Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho.', 'Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro.', 'Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados.', 'Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante.', 'Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio.', 'Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '68fc6dd4-bdaa-4557-a619-4ddbd6e7d6df';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0195', descripcion = 'Aísla el bíceps con el brazo apoyado, evitando balanceos y buscando máxima congestión.', instrucciones = ARRAY['Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.', 'Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino.', 'Mantén la espalda recta y los codos pegados a los costados.', 'Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento.', 'Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '2eb1a4f0-09c7-42aa-837e-5df08d20ac8e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0204', descripcion = 'Activa el core y los oblicuos con un tirón controlado que también estabiliza la zona lumbar.', instrucciones = ARRAY['Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina.', 'Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti.', 'Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento.', 'Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'b8dfd691-6ddb-4897-ae02-737247667a99';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0207', descripcion = 'Extiende el tríceps con agarre supino para incidir más en la cabeza medial y el antebrazo.', instrucciones = ARRAY['Sujeta una barra recta a una máquina de cable con polea alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.', 'Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos.', 'Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '727e743c-cced-432b-8e9d-d0f778c05ea9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0225', descripcion = 'Cruza los brazos en polea alta para trabajar el pectoral desde un ángulo poco habitual.', instrucciones = ARRAY['Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros.', 'Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros.', 'Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante.', 'Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio.', 'Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo.', 'Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '87ad871b-6bba-4ce4-8884-3fb1d0d62ff5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el core con un jalón de pie que exige estabilidad y control de la respiración.', instrucciones = ARRAY['Colócate de pie frente a la polea alta con la cuerda agarrada a la altura de la cara y las rodillas ligeramente flexionadas.', 'Contrae el abdomen y tira de la cuerda hacia el pecho llevando los codos atrás.', 'Aguanta un segundo apretando el core y vuelve despacio a la posición inicial.', 'Evita arquear la espalda o tirar con los brazos; el movimiento nace del abdomen.']::text[], actualizado_en = now() WHERE id = 'b5edfebf-042a-4ace-a899-4f5d0f580919';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0289', descripcion = 'Empuja el pectoral con mancuernas para ganar fuerza y amplitud en el tren superior.', instrucciones = ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho.', 'Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.', 'Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '517168a7-2e3c-44b5-8050-06eb4c6ebfb6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0301', descripcion = 'Inclina el banco para incidir en la porción inferior del pectoral con un recorrido más corto.', instrucciones = ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante.', 'Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.', 'Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '2952ad74-83c0-46c5-b199-7cc99c0c7600';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0303', descripcion = 'Presiona con agarre neutro en declive para trabajar el pecho bajo y proteger el hombro.', instrucciones = ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.', 'Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados.', 'Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'fb0d7050-eb31-4f4d-a705-acba677b7389';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0307', descripcion = 'Combina apertura y giro en declive para estirar el pectoral y activar fibras internas.', instrucciones = ARRAY['Túmbate en un banco declinado con la cabeza más baja que las caderas.', 'Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.', 'Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.', 'Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '5e45f33b-66d2-463a-86a8-bc7d0915fcdc';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0318', descripcion = 'Curl en banco inclinado que estira el bíceps y aumenta el rango de movimiento.', instrucciones = ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adelante.', 'Apoya los brazos superiores en el banco inclinado y deja que los codos cuelguen hacia abajo, extendiendo completamente los brazos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'a3c48b0f-8296-425b-9f0d-88937085e408';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0325', descripcion = 'Eleva el brazo tumbado para aislar el deltoides medio sin ayuda del impulso.', instrucciones = ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.', 'Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.', 'Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'bc0ec0f8-405d-4ab7-8c4d-de452dc9a49d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0335', descripcion = 'Encadena elevación lateral y frontal para trabajar todo el deltoides en un solo movimiento.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.', 'Mantén la espalda recta y activa el core.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'ca3b12f6-202a-436b-8c25-afcb2a96e615';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0341', descripcion = 'Aísla la parte posterior del hombro y mejora la estabilidad escapular, útil para equilibrar el empuje y prevenir lesiones.', instrucciones = ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro.', 'Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo.', 'Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna.', 'Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'e79f06d3-4e33-4a2c-834e-ef38bffb0fe6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0343', descripcion = 'Trabaja el pectoral de forma unilateral e implica más el core para estabilizar, corrigiendo desequilibrios entre lados.', instrucciones = ARRAY['Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo.', 'Sostén la mancuerna a la altura del hombro con la palma hacia adelante.', 'Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], actualizado_en = now() WHERE id = 'b529f4a3-560f-4631-8024-853485971f0e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0354', descripcion = 'Fortalece la espalda y los romboides retrayendo la escápula, ayudando a mejorar la postura y el control del hombro.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.', 'Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento.', 'Baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], actualizado_en = now() WHERE id = '1ca05ab7-42a0-4036-a7f0-cc360aeb68bb';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0363', descripcion = 'Activa el deltoides medio y el trapecio para ganar fuerza en el tirón vertical y estabilidad del hombro.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.', 'Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo.', 'Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], actualizado_en = now() WHERE id = '341f6e49-236a-4c8c-a340-4742c66adf6f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0368', descripcion = 'Refuerza el antebrazo y el agarre con extensión de muñeca, mejorando la fuerza para sujetar pesos y prevenir molestias.', instrucciones = ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo.', 'Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.', 'Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'eb992b8f-4219-4dca-91f6-19cf07860a1e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0384', descripcion = 'Trabaja el bíceps y el antebrazo con agarre prono, aislando el brazo y mejorando la fuerza de flexión.', instrucciones = ARRAY['Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.', 'Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba.', 'Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps.', 'Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'bcac55c4-f788-442e-8da3-3bce6af313e7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0388', descripcion = 'Desarrolla fuerza de empuje vertical en hombros y tríceps, con trabajo alterno que exige control y estabilidad del core.', instrucciones = ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.', 'Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.', 'Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo.', 'Baja la mancuerna de vuelta a la altura de los hombros.', 'Repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd02f5b8b-1e70-41f7-9959-8571d436c8d4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0403', descripcion = 'Aísla el bíceps con agarre prono y apoyo en el muslo, enfocándose en la contracción y en la fuerza del antebrazo.', instrucciones = ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.', 'Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'ced13bab-276a-4212-b8f0-b525e41aa888';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0410', descripcion = 'Fortalece cuádriceps y glúteo de forma unilateral, mejorando el equilibrio y la estabilidad de rodilla y cadera.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón.', 'Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo.', 'Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], actualizado_en = now() WHERE id = '5d9993e3-47c3-4cdd-af20-5611bca0ad0e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0423', descripcion = 'Aísla el tríceps en extensión por encima de la cabeza, trabajando la porción larga y mejorando la fuerza de empuje.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.', 'Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.', 'Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo.', 'Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd62a4819-4312-4d75-a91d-c61bb37e883e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0425', descripcion = 'Refuerza el antebrazo y el braquiorradial con agarre prono, mejorando el agarre y la estabilidad de la muñeca.', instrucciones = ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono.', 'Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo.', 'Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], actualizado_en = now() WHERE id = '3de9345e-20d7-458a-a6d7-401123e9490c';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0427', descripcion = 'Trabaja hombros y tríceps en empuje vertical con agarre neutro, exigiendo estabilidad del core al estar de pie.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro.', 'Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '39c05914-80ad-4ca1-924d-02cadf670c94';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0429', descripcion = 'Fortalece el antebrazo y el braquiorradial con agarre prono, útil para mejorar el agarre y prevenir molestias en el codo.', instrucciones = ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'aefc0539-a364-4805-b090-3620d7c8747e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0439', descripcion = 'Combina flexión con agarre supino y descenso prono, trabajando bíceps y antebrazo en un mismo movimiento.', instrucciones = ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante.', 'Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.', 'En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo.', 'Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '61e1f37f-31b1-4e84-89a9-8508ef7de9a2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0446', descripcion = 'Aísla el bíceps con agarre cerrado en barra EZ, aumentando la tensión y reduciendo la molestia en muñecas.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros.', 'Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.', 'Sube la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '624707a5-2fc9-4282-bce6-1a27b2c6781a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0450', descripcion = 'Trabaja el pectoral con apoyo de hombro y tríceps, útil para ganar fuerza en press y mejorar el empuje del tren superior.', instrucciones = ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '495bfac8-c144-4fbc-9251-117b4f5a0ea7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0452', descripcion = 'Fortalece bíceps y antebrazo con agarre prono, ideal para equilibrar el codo y mejorar la fuerza de agarre.', instrucciones = ARRAY['Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo.', 'Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros.', 'Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo.', 'Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.', 'Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'cdd8adb4-1027-43a1-a743-c8ef6711a78b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0453', descripcion = 'Aísla el tríceps en posición sentada, perfecto para ganar volumen y fuerza en la extensión del codo.', instrucciones = ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.', 'Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos.', 'Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '76d23cdf-7b4c-4fab-954a-54f502a6172a';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '0462', descripcion = 'Moviliza la columna cervical y la zona dorsal alta, aliviando tensión por horas de estudio y mejorando la postura.', instrucciones = ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Lleva la barbilla hacia el pecho despacio hasta notar estiramiento en la nuca.', 'Vuelve al centro y luego inclina la cabeza hacia atrás sin forzar, mirando al techo.', 'Respira profundo en cada posición y evita hacer círculos completos con el cuello.']::text[], actualizado_en = now() WHERE id = 'b37748ec-cac6-4d89-b07d-056b6088be25';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '0471', descripcion = 'Ejercicio avanzado que fortalece pectoral, hombro y tríceps mientras exige control total del cuerpo invertido.', instrucciones = ARRAY['Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia.', 'Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino.', 'Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta.', 'Empuja con las manos y extiende los brazos para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '96affd73-0025-4dc1-b81a-5bec47ec2a4e';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '0513', descripcion = 'Potencia piernas y glúteos con componente explosivo, mejorando salto, velocidad y resistencia muscular.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Salta de forma explosiva, extendiendo por completo las caderas y las rodillas.', 'Aterriza suavemente sobre la punta de los pies y de inmediato baja el cuerpo de nuevo a una posición de sentadilla.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'bb96106c-1671-4156-9aab-c0171570e54f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0520', descripcion = 'Press unilateral que trabaja pecho y hombro mientras exige estabilidad del core y corrige desequilibrios entre lados.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.', 'Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo.', 'Baja la pesa rusa de nuevo a la altura de los hombros.', 'Repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd508e15a-7fe5-4e07-82af-ea390bb0bead';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0527', descripcion = 'Movimiento explosivo que desarrolla potencia de hombro y pierna, coordinando todo el cuerpo en un solo gesto.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.', 'Flexiona ligeramente las rodillas y activa el core.', 'Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.', 'Flexiona las rodillas y baja rápidamente a una sentadilla parcial.', 'Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba.', 'Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas.', 'Ponte de pie recto y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '77bb838c-fbd4-480e-8bd7-5fcbfb5e18d3';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0529', descripcion = 'Ejercicio balístico que mejora la potencia de hombro y la coordinación, con gran demanda cardiovascular y de core.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros.', 'Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.', 'Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '0cfbf153-aa8f-4482-b3ab-404c3bc9499c';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0537', descripcion = 'Combina cargada y envión para trabajar hombro, pierna y core, mejorando potencia y coordinación unilateral.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.', 'Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas.', 'Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.', 'Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza.', 'Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '664e2e3f-9573-43ca-8717-d65b51be4fab';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0540', descripcion = 'Press con impulso de piernas que permite mover más carga, desarrollando potencia de hombro y sincronía corporal.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.', 'Flexiona ligeramente las rodillas y activa el core.', 'Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas.', 'Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], actualizado_en = now() WHERE id = '06fcfa8d-40d0-4f30-93d1-75836102f6e8';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0542', descripcion = 'Movimiento explosivo unilateral que entrena potencia de hombro, coordinación y estabilidad del core.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas.', 'Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.', 'Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro.', 'Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo.', 'Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'ae09b765-00f5-45d3-a416-035c04a2af2b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0546', descripcion = 'Press sentado que aísla el empuje de hombro y pecho, reduciendo la ayuda de piernas y mejorando la fuerza vertical.', instrucciones = ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante.', 'Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.', 'Baja las pesas rusas de vuelta a la altura del hombro.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '1977e79f-d121-4d7f-b297-661f3f418a4c';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0550', descripcion = 'Combina sentadilla y press en un solo movimiento, elevando pulsaciones y trabajando todo el cuerpo con fuerza.', instrucciones = ARRAY['Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra.', 'Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta.', 'Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza.', 'Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo.', 'Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'b11be821-9962-4e8c-ba68-85d7798aeb8f';
UPDATE ejercicios SET categoria = 'olympic', codigo_externo = '0552', descripcion = 'Cargada que desarrolla potencia de cadera y hombro, enseñando a recibir la pesa con control y técnica.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti.', 'Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.', 'Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros.', 'Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo.', 'Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '452a59e6-1e46-46aa-aaee-47b032440a04';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0553', descripcion = 'Fortalece hombros y tríceps empujando la kettlebell por encima de la cabeza, mejorando la estabilidad y la fuerza del tren superior.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.', 'Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.', 'Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '4b07f302-26df-4f4b-bffd-65351030c644';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0575', descripcion = 'Aísla el bíceps con resistencia guiada por la máquina, ideal para ganar volumen y controlar el recorrido sin balanceos.', instrucciones = ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.', 'Sujeta las asas con un agarre supino, con las palmas hacia arriba, y mantén los codos cerca de los costados.', 'Exhala y flexiona las asas hacia arriba, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '05ae23ed-60cb-49bb-89f3-dea8b0364a16';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0592', descripcion = 'Trabaja el bíceps con el brazo apoyado, evitando trampas y logrando una contracción intensa y segura en el rango completo.', instrucciones = ARRAY['Ajusta la altura del asiento y colócate en la máquina de palanca.', 'Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino.', 'Mantén la espalda recta y los codos colocados sobre la almohadilla.', 'Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '92a736f1-0542-4703-b756-121b874c112e';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira la parte frontal del muslo y la cadera, alivia tensión tras entrenar y mejora la movilidad de la rodilla.', instrucciones = ARRAY['Túmbate de lado con las piernas estiradas y la cabeza apoyada en el brazo inferior.', 'Flexiona la rodilla de arriba y sujeta el tobillo con la mano para llevar el talón al glúteo.', 'Mantén las rodillas juntas y la cadera neutra mientras respiras despacio durante 20-30 segundos.', 'Evita tirar del pie con fuerza ni arquear la zona lumbar; suelta si notas dolor en la rodilla.']::text[], actualizado_en = now() WHERE id = '85947ab5-39e0-4e1e-bd24-728bd5b303c0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece cuádriceps y glúteos en isométrico mientras la marcha añade control y resistencia en la parte baja.', instrucciones = ARRAY['Apoya la espalda en la pared y desliza hasta que muslos y rodillas formen unos 90 grados.', 'Mantén la espalda pegada y el peso en los talones durante todo el ejercicio.', 'Levanta un pie unos centímetros y vuelve a apoyarlo, alternando lados sin perder la postura.', 'Respira de forma continua y evita que las rodillas se vayan hacia dentro.']::text[], actualizado_en = now() WHERE id = '40dd67f0-6993-4af2-a516-ae316d9b641e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja la potencia de cuádriceps y glúteos con un salto explosivo que mejora la fuerza y el control al aterrizar.', instrucciones = ARRAY['Colócate de espaldas a la pared, a un paso de distancia, con los pies a la anchura de las caderas.', 'Baja en sentadilla llevando la cadera atrás y los brazos al frente para coger impulso.', 'Salta de forma explosiva y aterriza con las rodillas alineadas y el peso en los talones.', 'Amortigua el aterrizaje flexionando las caderas y evita caer con las rodillas hacia dentro.']::text[], actualizado_en = now() WHERE id = 'dae7d7dd-7d3b-4e39-bd66-bf0179b590d7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece pecho, hombro y tríceps con una superficie inestable que exige más control del core.', instrucciones = ARRAY['Coloca las manos sobre el bosu, a la anchura de los hombros, y extiende las piernas atrás.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones y activa el abdomen.', 'Baja el pecho flexionando los codos hacia atrás hasta rozar la superficie.', 'Empuja para subir sin hundir la cadera y evita abrir los codos en exceso.']::text[], actualizado_en = now() WHERE id = 'bbb2f31e-77b4-4190-b36d-cb9dd32453e1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece pecho, hombros y tríceps con una versión suave y segura que permite controlar la carga fácilmente.', instrucciones = ARRAY['Apoya las manos en la pared a la altura de los hombros, algo más anchas que estas.', 'Da un paso atrás y mantén el cuerpo recto, con el abdomen activo.', 'Flexiona los codos acercando el pecho a la pared y empuja para volver.', 'Evita sacar la cadera o encoger los hombros durante el movimiento.']::text[], actualizado_en = now() WHERE id = '7eb6c689-c38a-475c-a9e7-c4120b168975';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa oblicuos y abdomen con un movimiento controlado que mejora la estabilidad del tronco sentado.', instrucciones = ARRAY['Siéntate con la espalda apoyada en la pared y las rodillas flexionadas.', 'Coloca las manos detrás de la cabeza sin tirar del cuello.', 'Inclina el tronco hacia un lado acercando el codo a la cadera y vuelve al centro.', 'Alterna lados despacio y evita encorvar la espalda o tirar del cuello.']::text[], actualizado_en = now() WHERE id = '5038f97e-7445-47a0-baf2-9e21c5061824';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '0713', descripcion = 'Alivia la tensión del cuello y los escalenos, mejora la movilidad cervical y ayuda a prevenir molestias por posturas prolongadas.', instrucciones = ARRAY['Siéntate o ponte de pie con la espalda recta y los hombros relajados.', 'Inclina la cabeza hacia un lado llevando la oreja al hombro sin subir el hombro.', 'Puedes apoyar suavemente la mano del mismo lado para aumentar el estiramiento.', 'Mantén 20-30 segundos respirando y evita girar o forzar la cabeza.']::text[], actualizado_en = now() WHERE id = 'b21fc186-bb69-40c3-8dbe-5a32c5bde541';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '0716', descripcion = 'Estira el cuello y los escalenos con una presión suave, aliviando la tensión cervical y mejorando la movilidad tras el estudio.', instrucciones = ARRAY['Ponte de pie o siéntate erguido con los hombros relajados.', 'Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.', 'Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.', 'Mantén el estiramiento durante 15-30 segundos.', 'Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.', 'Repite el estiramiento 2-3 veces en cada lado.']::text[], actualizado_en = now() WHERE id = '20e65d3e-1098-4d76-8e6a-9a95d41ffb85';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0748', descripcion = 'Empuja la barra guiada para trabajar el pecho con trayectoria estable, permitiendo cargar más y centrarte en la técnica.', instrucciones = ARRAY['Ajusta la altura de la barra de la máquina Smith a la altura del pecho.', 'Túmbate en el banco con los pies firmemente apoyados en el suelo.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa por un momento cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'bfd11d79-d75a-4370-8d12-5001b48a37af';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0751', descripcion = 'Variante con agarre estrecho que enfatiza el tríceps y la parte interna del pecho, con la seguridad de la barra guiada.', instrucciones = ARRAY['Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo.', 'Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.', 'Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '46d98603-2944-4750-98b1-5a630d673663';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0757', descripcion = 'Inclina el banco para incidir en la porción superior del pecho y los hombros, con recorrido controlado por la máquina.', instrucciones = ARRAY['Ajusta el banco a una inclinación de 30-45 grados.', 'Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo.', 'Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '10ed066e-e390-4eb8-8631-38947e4ae0e4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0774', descripcion = 'Empuja la barra guiada por encima de la cabeza para ganar fuerza en hombros y tríceps con trayectoria segura.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante.', 'Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '9084518d-26ce-411a-acdc-7b4a2c08f541';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece gemelos y sóleos en isometría mientras el toque de pies activa el tibial anterior y mejora el control del tobillo.', instrucciones = ARRAY['Apoya la espalda en la pared y desliza el cuerpo hasta que rodillas y caderas formen unos 90 grados.', 'Mantén los pies apoyados y eleva alternativamente las puntas sin despegar los talones.', 'Respira de forma continua y evita aguantar la respiración durante la isometría.', 'No dejes que las rodillas se vayan hacia dentro ni que la espalda se separe de la pared.']::text[], actualizado_en = now() WHERE id = '75b33f3d-3465-4619-9ea7-968f2afd1b47';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el tríceps y sus sinergias del brazo mientras el fitball añade inestabilidad y demanda control del tronco.', instrucciones = ARRAY['Apoya el abdomen sobre el fitball con los pies fijos en el suelo y el cuerpo alineado.', 'Sujeta la carga con los codos pegados al cuerpo y flexiona los antebrazos hacia la cabeza.', 'Extiende los codos para volver arriba sin mover los hombros ni arquear la espalda.', 'Controla el descenso durante dos segundos y evita balancear el tronco para impulsarte.']::text[], actualizado_en = now() WHERE id = 'bda04ebc-bf14-4a95-95d6-42d0763c8a8f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0854', descripcion = 'Refuerza la musculatura del antebrazo y la fuerza de agarre apretando las manos con resistencia, útil para mejorar el rendimiento en ejercicios de tracción.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano.', 'Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.', 'Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos.', 'Mantén la contracción durante unos segundos y luego suelta.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '81a8a522-f3dd-47b8-aa71-8dbf7dcef863';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0859', descripcion = 'Desarrolla flexores y extensores del antebrazo enrollando y desenrollando el peso, mejorando la fuerza de agarre y la resistencia de la muñeca.', instrucciones = ARRAY['Sujeta un peso a un extremo de una cuerda o barra.', 'Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti.', 'Enrolla lentamente el peso hacia las manos flexionando las muñecas.', 'Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '603c5647-db40-4198-b982-2be5589ec686';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps con tensión constante de la polea, ideal para ganar fuerza y control en la flexión del codo.', instrucciones = ARRAY['Colócate de pie frente a la polea baja y agarra el maneral con las palmas hacia arriba.', 'Mantén los codos pegados al torso y flexiona hasta llevar las manos cerca de los hombros.', 'Baja controlando el movimiento sin dejar que el peso tire de los brazos.', 'Evita balancear el tronco o adelantar los codos para completar la repetición.']::text[], actualizado_en = now() WHERE id = 'd3bbc1a9-4891-41fb-9c02-51b174a48da1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0978', descripcion = 'Fortalece el deltoides anterior elevando el brazo contra la banda, con apoyo de trapecio y tríceps en la fase final.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.', 'Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'ac6592c1-723e-4a53-b73b-06710df33220';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '0985', descripcion = 'Activa recto abdominal y oblicuos con un crunch rotado de rodillas, sumando control del transverso y estabilidad lumbar.', instrucciones = ARRAY['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.', 'Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.', 'Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd1007b7b-bab5-43ba-83b6-feb410240729';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1007', descripcion = 'Trabaja abdomen y oblicuos de pie con rotación contra banda, mejorando la fuerza del core en posición erguida.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.', 'Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.', 'Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '638a33c0-b37a-4ec7-86de-2142cff4d747';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2122', descripcion = 'Moviliza y fortalece la musculatura lateral del tronco con apoyo, mejorando la estabilidad y el control de la columna.', instrucciones = ARRAY['Colócate de pie con los pies a la anchura de las caderas y apóyate en la asistencia.', 'Inclina el tronco hacia un lado controlando el recorrido sin rotar el torso.', 'Vuelve al centro usando la musculatura lateral y repite hacia el otro lado.', 'Evita arquear la espalda o usar impulso para completar el movimiento.']::text[], actualizado_en = now() WHERE id = '55ca7e92-cbec-4576-9c0a-ed8fb47c9700';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1029', descripcion = 'Fortalece el pectoral con empuje guiado en máquina, implicando deltoides anterior y tríceps de forma segura.', instrucciones = ARRAY['Ajusta el asiento para que los agarres queden a la altura del pecho y siéntate con la espalda apoyada.', 'Empuja las asas hacia delante extendiendo los codos sin bloquear las articulaciones.', 'Vuelve despacio hasta notar estiramiento en el pecho sin soltar la tensión.', 'Evita encoger los hombros o rebotar al final del recorrido.']::text[], actualizado_en = now() WHERE id = 'b9e911ce-9795-4dd7-9a5b-f5764aa3c6d8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1030', descripcion = 'Aísla el pectoral juntando los brazos en máquina, con ayuda del deltoides anterior y el tríceps en el cierre.', instrucciones = ARRAY['Siéntate con la espalda apoyada y coloca los antebrazos o manos en las almohadillas.', 'Junta los brazos hacia el centro apretando el pecho sin adelantar los hombros.', 'Abre lentamente hasta sentir estiramiento sin forzar la articulación.', 'Evita usar impulso o encoger el cuello durante el movimiento.']::text[], actualizado_en = now() WHERE id = '84c57798-133b-49a8-8f9c-77ab935f6ea9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1032', descripcion = 'Trabaja el bíceps de forma alterna y guiada en máquina, con apoyo de braquial y braquiorradial en la flexión.', instrucciones = ARRAY['Ajusta el asiento y apoya los brazos en el soporte con los codos alineados al eje.', 'Flexiona un brazo hasta arriba sin despegar el codo del apoyo.', 'Baja controlando y repite con el otro brazo de forma alterna.', 'Evita balancear el tronco o tirar con el hombro para subir el peso.']::text[], actualizado_en = now() WHERE id = 'a705a2c3-8e67-4254-8efc-65b62999fcef';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '1044', descripcion = 'Mejora la fuerza de pinza y el agarre sosteniendo un disco entre los dedos, clave para antebrazo y muñeca.', instrucciones = ARRAY['Coloca un disco en el suelo y pellízcalo con el pulgar por un lado y los dedos por el otro.', 'Levántalo manteniendo la muñeca neutra y el brazo relajado junto al cuerpo.', 'Sostén el tiempo indicado respirando con normalidad y baja con control.', 'Evita apoyar el disco en la pierna o curvar la muñeca para aguantar más.']::text[], actualizado_en = now() WHERE id = '5df5601b-f8e3-4051-86d7-8985d5e8b2f8';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1059', descripcion = 'Estira el cuádriceps y la parte anterior del muslo, mejorando la movilidad de cadera y rodilla tras el entrenamiento.', instrucciones = ARRAY['De pie, apóyate en una pared si necesitas equilibrio y flexiona una rodilla llevando el talón al glúteo.', 'Sujeta el pie con la mano del mismo lado manteniendo las rodillas juntas.', 'Lleva la cadera ligeramente hacia delante hasta notar estiramiento sin dolor.', 'Mantén la postura respirando despacio y evita arquear la espalda.']::text[], actualizado_en = now() WHERE id = '81a26abc-dba8-452e-b0df-baef11824d1e';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira abdomen y oblicuos tumbado boca abajo, liberando tensión en el tronco y mejorando la extensión de la columna.', instrucciones = ARRAY['Túmbate boca abajo con las manos apoyadas bajo los hombros y las piernas extendidas.', 'Empuja suavemente el suelo para elevar el pecho sin despegar la pelvis.', 'Mantén la posición respirando despacio y sin forzar la zona lumbar.', 'Baja con control y evita levantar la cabeza en exceso o hacer rebotes.']::text[], actualizado_en = now() WHERE id = '8ba992a0-da6b-4e42-9e63-bf764681971f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1228', descripcion = 'Trabaja el bíceps y el antebrazo con las palmas hacia arriba, útil para ganar fuerza en la flexión del codo.', instrucciones = ARRAY['Colócate de pie con una mancuerna en cada mano y las palmas mirando hacia delante.', 'Mantén los codos pegados al torso y los hombros relajados durante todo el recorrido.', 'Sube las mancuernas flexionando los codos sin balancear el cuerpo y baja controlando el movimiento.', 'Evita mover los hombros hacia delante o usar impulso de la espalda para subir el peso.']::text[], actualizado_en = now() WHERE id = '14c3a82f-156c-4e99-afa3-ff649a6edb70';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1233', descripcion = 'Fortalece bíceps y braquial con agarre neutro en banco inclinado, aislando el codo y reduciendo el impulso.', instrucciones = ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano y los brazos colgando.', 'Gira las palmas hacia dentro para un agarre neutro y mantén los codos cerca del cuerpo.', 'Flexiona un codo a la vez hasta acercar la mancuerna al hombro y baja despacio.', 'Evita echar el brazo hacia atrás o despegar la espalda del respaldo al subir.']::text[], actualizado_en = now() WHERE id = '100b006a-fa8d-4e14-9748-8aa7a900b92a';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '1246', descripcion = 'Isométrico de core que activa abdomen y oblicuos, mejora la estabilidad del tronco y la postura.', instrucciones = ARRAY['Túmbate boca arriba y presiona la zona lumbar contra el suelo.', 'Eleva los hombros y las piernas manteniendo la espalda baja pegada al suelo.', 'Extiende los brazos hacia atrás o al frente según tu control y respira de forma constante.', 'Evita arquear la lumbar o aguantar la respiración durante el tiempo de trabajo.']::text[], actualizado_en = now() WHERE id = '051749b4-a7c7-4c51-be33-1449b92288f2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de core que trabaja oblicuos y abdomen con rotación controlada de las piernas.', instrucciones = ARRAY['Túmbate boca arriba con las piernas flexionadas y elevadas a unos noventa grados.', 'Extiende los brazos a los lados para estabilizar el tronco y presiona la lumbar contra el suelo.', 'Baja las rodillas juntas hacia un lado sin tocar el suelo y vuelve al centro para cambiar de lado.', 'Evita despegar la espalda baja o girar con impulso en lugar de controlar el movimiento.']::text[], actualizado_en = now() WHERE id = '54bf8de7-b3c6-487e-9224-26549643538d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1254', descripcion = 'Press de pecho con banda que trabaja pectoral, hombro anterior y tríceps, ideal para fuerza sin cargas altas.', instrucciones = ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Extiende los brazos por completo, empujando las bandas alejándolas del pecho.', 'Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '591ed22e-7867-4f34-9522-824e92cc7a2d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1261', descripcion = 'Press declinado en polea que incide en la porción inferior del pectoral con tensión constante.', instrucciones = ARRAY['Ajusta la máquina de cable a una posición declinada.', 'Siéntate en el banco declinado frente a la máquina de cable.', 'Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho.', 'Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco.', 'Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos.', 'Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho.', 'Inhala y vuelve lentamente las agarraderas a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '0dae8f6e-071a-4728-8cfd-261d52774751';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1262', descripcion = 'Apertura unilateral en polea que aísla el pectoral y mejora el control y la simetría entre lados.', instrucciones = ARRAY['Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado.', 'Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha.', 'Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo.', 'Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro.', 'Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio.']::text[], actualizado_en = now() WHERE id = '293a6235-5eb3-4d24-b23b-2bc31b7025ae';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1263', descripcion = 'Apertura a una mano sobre fitball que trabaja el pectoral añadiendo inestabilidad y control del core.', instrucciones = ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo.', 'Mantén el codo ligeramente flexionado y la palma hacia adelante.', 'Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], actualizado_en = now() WHERE id = 'c9e0d643-67b5-42cc-b6f7-38a406da2fd2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1264', descripcion = 'Apertura inclinada unilateral sobre fitball que incide en el pectoral superior con demanda de estabilidad.', instrucciones = ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.', 'Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro.', 'Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro.', 'Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'd5821888-4f96-4871-bdd2-bbb0f500d1bc';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1270', descripcion = 'Cruce de poleas que enfatiza la porción superior del pectoral y mejora la definición del pecho.', instrucciones = ARRAY['Coloca los mangos en los cables a la altura del pecho.', 'Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro.', 'Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.', 'Mantén una ligera flexión en los codos y activa el core.', 'Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro.', 'Aprieta los músculos del pecho en el punto máximo del movimiento.', 'Suelta lentamente los cables de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'c5c0468d-7b79-498c-ba64-a800000493d5';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1271', descripcion = 'Estiramiento que relaja pectoral y hombro anterior, útil para mejorar movilidad y postura tras entrenar.', instrucciones = ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Extiende los brazos rectos frente a ti a la altura de los hombros.', 'Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo.', 'Entrelaza los dedos y presiona las palmas entre sí.', 'Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros.', 'Mantén el estiramiento durante 20-30 segundos, luego suelta.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '47e19b29-463d-4ee6-bf79-9775432d4c37';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1276', descripcion = 'Apertura declinada unilateral con mancuerna que aísla el pectoral inferior y equilibra ambos lados.', instrucciones = ARRAY['Túmbate en un banco declinado con una mancuerna en una mano, apoyándola sobre el muslo.', 'Usando el muslo para ayudar a levantar la mancuerna, álzala hasta la altura de los hombros con la palma mirando hacia el torso.', 'Gira la muñeca de modo que la palma de la mano quede mirando hacia adelante.', 'Mientras inhalas, baja la mancuerna lentamente hacia el lado hasta sentir un estiramiento en el pecho.', 'Exhala y usa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = '55ec5fa3-14af-4c8f-b7af-83aba60611c1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1279', descripcion = 'Apertura inclinada a una mano que trabaja el pectoral superior y mejora el control unilateral.', instrucciones = ARRAY['Ajusta el banco inclinado a un ángulo de 30-45 grados.', 'Siéntate en el banco con una mancuerna en una mano, apoyándola sobre el muslo.', 'Recuéstate en el banco, manteniendo los pies apoyados en el suelo.', 'Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho.', 'Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.', 'Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento para llevar la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'b199b152-8df6-4ae2-af41-838f07f699c0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1281', descripcion = 'Press inclinado unilateral que incide en el pectoral superior y exige estabilidad del tronco.', instrucciones = ARRAY['Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.', 'Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante.', 'Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], actualizado_en = now() WHERE id = '621d49b2-9ba4-469a-8fe8-ec1ec831e776';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1283', descripcion = 'Press inclinado sobre fitball que trabaja el pectoral superior añadiendo inestabilidad y control del core.', instrucciones = ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante.', 'Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.', 'Empuja las mancuernas hacia arriba, extendiendo completamente los brazos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '7e0a4b7e-a5f2-4989-8d99-cf1b6d6d6df8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1284', descripcion = 'Trabaja el pectoral y la espalda alta mientras el fitball obliga a estabilizar el tronco y mejora la movilidad del hombro.', instrucciones = ARRAY['Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón.', 'Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho.', 'Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '92bbf8be-e1f2-44df-b1e2-942a242d9f5d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1285', descripcion = 'Aísla el pectoral con un recorrido amplio y controlado, útil para corregir desequilibrios entre los dos lados del pecho.', instrucciones = ARRAY['Siéntate en un banco plano con una mancuerna en una mano, apoyándola sobre el muslo.', 'Recuéstate en el banco, manteniendo la mancuerna presionada contra el muslo.', 'Usando la mano libre, ayuda a levantar la mancuerna hasta la posición inicial.', 'Sostén la mancuerna directamente sobre el hombro con el brazo extendido y la palma hacia adentro.', 'Baja la mancuerna hacia el lado describiendo un amplio arco, manteniendo una ligera flexión en el codo.', 'Haz una pausa cuando el brazo esté paralelo al suelo, luego invierte el movimiento y lleva la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo y repite.']::text[], actualizado_en = now() WHERE id = '214f9641-00cd-4482-b312-cb68327dcc36';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1296', descripcion = 'Fortalece hombros y tríceps con el peso corporal mientras el fitball añade inestabilidad y exige control del core.', instrucciones = ARRAY['Comienza en posición de flexión de brazos con las manos en el suelo y las espinillas apoyadas sobre el balón de estabilidad.', 'Activa el core y levanta las caderas hacia el techo, haciendo rodar el balón hacia las manos.', 'Mantén las piernas rectas y el cuerpo en posición de pica, formando una V invertida.', 'Dobla los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo la cabeza alineada con las manos.', 'Empuja con las manos y extiende los brazos para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '3469cfd2-e9e9-4e3e-bfb1-a20a09b3d297';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1298', descripcion = 'Prensa el pectoral desde el suelo limitando el rango del hombro, ideal para ganar fuerza de empuje con mayor seguridad.', instrucciones = ARRAY['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.', 'Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo.', 'Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo.', 'Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], actualizado_en = now() WHERE id = 'ded95a1c-0f2b-4908-bc0c-dba9fc6687d3';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '1306', descripcion = 'Desarrolla potencia y fuerza explosiva en pecho y tríceps con un salto que exige aterrizaje controlado y buen frenado.', instrucciones = ARRAY['Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.', 'Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.', 'Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo.', 'Aterriza suavemente con las manos de vuelta en la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'f26f6bfd-1ad8-4efa-943d-a728d5c16f1b';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '1368', descripcion = 'Moviliza el tobillo y activa la circulación antes de entrenar, preparando la articulación para sentadillas, saltos o carrera.', instrucciones = ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Levanta una pierna del suelo y rota el tobillo con un movimiento circular.', 'Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.', 'Repite con la otra pierna.']::text[], actualizado_en = now() WHERE id = '5bf5616c-7a8e-45b0-959d-659df15b0936';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1370', descripcion = 'Fortalece la pantorrilla con la barra sobre las rodillas, un ejercicio sencillo para ganar fuerza y volumen en el gemelo.', instrucciones = ARRAY['Coloca una barra en el suelo frente a ti.', 'Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.', 'Sujétate de un objeto estable para mantener el equilibrio si es necesario.', 'Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '4b5874f7-58e5-4e5e-8153-0812b7d5baf7';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2123', descripcion = 'Estira la musculatura lateral del tronco y mejora la movilidad de la columna, aliviando tensiones tras el entrenamiento.', instrucciones = ARRAY['Colócate de pie con los pies separados y agarra un apoyo firme con una mano.', 'Inclina el tronco hacia el lado contrario al apoyo y alarga el brazo libre por encima de la cabeza.', 'Mantén la cadera estable y respira despacio durante veinte o treinta segundos.', 'Evita rebotar o girar el tronco: busca una tensión cómoda y constante.', 'Cambia de lado y repite el mismo tiempo para equilibrar la musculatura.']::text[], actualizado_en = now() WHERE id = 'fd025742-0892-473a-a5ee-9b76b480ccf0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1376', descripcion = 'Trabaja el gemelo de forma unilateral con tensión constante de la polea, útil para corregir diferencias entre piernas.', instrucciones = ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujétate de la máquina de cable para apoyarte.', 'Levanta una pierna del suelo y equilíbrate sobre la otra pierna.', 'Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], actualizado_en = now() WHERE id = '4dce22b9-ac15-4a6f-9599-7b9a3fc59b75';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1377', descripcion = 'Estira el gemelo y el sóleo apoyándote en la pared, aliviando la tensión de la pantorrilla después de correr o saltar.', instrucciones = ARRAY['Ponte de pie frente a una pared con los pies separados a la altura de las caderas.', 'Coloca las manos contra la pared a la altura de los hombros.', 'Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta.', 'Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo.', 'Mantén el estiramiento durante 20-30 segundos.', 'Cambia de pierna y repite el estiramiento.']::text[], actualizado_en = now() WHERE id = 'fcbb4a4b-3e15-48f7-b1d6-78139449f17a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1383', descripcion = 'Permite cargar la pantorrilla con el respaldo de la máquina hack, ganando fuerza en el gemelo con un recorrido estable.', instrucciones = ARRAY['Ajusta la máquina de trineo a un peso adecuado.', 'Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando.', 'Sujétate de las asas para mantener el equilibrio.', 'Levanta los talones lo más alto posible empujando con la punta de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'db71dc98-bd7c-4366-bd57-d6dd0dd74429';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1386', descripcion = 'Aísla el gemelo a una pierna con el tronco inclinado, aumentando el rango de estiramiento y la intensidad del trabajo.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.', 'Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra.', 'Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada.', 'Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], actualizado_en = now() WHERE id = '95733c77-b48c-4d66-906c-8730548421d6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1392', descripcion = 'Trabaja la pantorrilla a una pierna en la prensa, permitiendo una carga alta y un recorrido controlado del tobillo.', instrucciones = ARRAY['Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.', 'Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros.', 'Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados.', 'Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '2d5905fe-b7c1-43e6-81f2-400104e54ae0';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1407', descripcion = 'Estira la pantorrilla empujando contra la pared, una opción cómoda para ganar flexibilidad de tobillo y prevenir sobrecargas.', instrucciones = ARRAY['Ponte de pie frente a una pared con los pies separados a la altura de las caderas.', 'Coloca las manos contra la pared a la altura de los hombros.', 'Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta.', 'Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Cambia de pierna y repite el estiramiento.']::text[], actualizado_en = now() WHERE id = '961fccf4-40cd-4d82-bb81-417b05869341';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1414', descripcion = 'Fortalece el bíceps y el antebrazo con agarre prono, mejorando la fuerza de prensión y el equilibrio entre músculos del brazo.', instrucciones = ARRAY['Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino.', 'Baja lentamente la mancuerna hasta que el brazo quede completamente extendido.', 'Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.', 'Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'aad0a12a-0db0-47e2-97ed-10d4f1130987';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece hombros y tríceps con una sentadilla frontal guiada que mejora la estabilidad del tronco.', instrucciones = ARRAY['Coloca la barra en la máquina Smith a la altura de los hombros y sujétala con agarre de cargada.', 'Ponte debajo con los codos altos y la barra apoyada en la parte delantera de los hombros.', 'Baja en sentadilla manteniendo el tronco erguido y los codos apuntando al frente.', 'Empuja con los talones para subir y evita que los codos caigan durante el recorrido.']::text[], actualizado_en = now() WHERE id = 'a2047822-7d3b-4184-8c64-f8da244a4775';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1436', descripcion = 'Fortalece cuádriceps, glúteos e isquiotibiales, mejorando la potencia de piernas y la estabilidad del tronco en el levantamiento.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.', 'Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'afa5fb32-ea6d-40e2-97f2-077dfbf9c2f1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1454', descripcion = 'Fortalece hombros y tríceps con un empuje guiado que permite trabajar con seguridad y control.', instrucciones = ARRAY['Ajusta el asiento para que las agarraderas queden a la altura de los hombros.', 'Siéntate con la espalda apoyada y sujeta las asas con los codos hacia abajo.', 'Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos.', 'Baja de forma controlada y evita arquear la espalda o encoger los hombros.']::text[], actualizado_en = now() WHERE id = '8906a091-713b-4dd6-a1e1-43f30bf5cdc7';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1489', descripcion = 'Aísla el cuádriceps con gran tensión en la rodilla, útil para hipertrofia y control del equilibrio sin material.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujétate de un objeto estable para mantener el equilibrio si es necesario.', 'Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido.', 'Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '327cc5aa-7eeb-432d-8d3a-575009d685a1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece gemelos y sóleo con un rango completo que mejora el equilibrio y la fuerza del tobillo.', instrucciones = ARRAY['Colócate de pie con la punta de los pies en el borde del escalón y sujétate para mantener el equilibrio.', 'Baja los talones por debajo del escalón hasta notar estiramiento en la pantorrilla.', 'Empuja con la punta de los pies para subir lo máximo posible.', 'Sube y baja despacio, evitando rebotar o perder la alineación del tobillo.']::text[], actualizado_en = now() WHERE id = '94a7b1d8-c6d1-4c11-9f0c-4367668441e3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja deltoides y trapecio con una tracción vertical que mejora la fuerza del hombro y la postura.', instrucciones = ARRAY['Pisa la banda con los pies a la anchura de las caderas y sujeta los extremos con las manos.', 'Lleva las manos hacia arriba pegadas al cuerpo hasta la altura del pecho.', 'Sube los codos hacia los lados manteniendo las muñecas relajadas.', 'Baja despacio y evita encoger los hombros o tirar con la espalda.']::text[], actualizado_en = now() WHERE id = 'b72014d8-11aa-411c-8dff-f596ef00fc62';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1503', descripcion = 'Fortalece la espalda alta y los rotadores externos, mejora la postura y contrarresta el trabajo de pecho.', instrucciones = ARRAY['Sujeta la banda con las manos a la anchura de los hombros y los brazos estirados al frente.', 'Mantén los codos ligeramente flexionados y el abdomen activo.', 'Separa las manos abriendo los brazos hasta que la banda toque el pecho.', 'Vuelve despacio y evita encoger los hombros o arquear la espalda.']::text[], actualizado_en = now() WHERE id = '93fcf550-e621-4e46-828f-162d41e06ca1';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1546', descripcion = 'Fortalece cuádriceps y glúteos en isométrico, mejora la resistencia muscular y la estabilidad de la rodilla.', instrucciones = ARRAY['Apoya la espalda en la pared y desliza hasta que los muslos queden paralelos al suelo.', 'Separa los pies a la anchura de las caderas y apoya el peso en los talones.', 'Mantén la posición con el abdomen activo y la espalda pegada a la pared.', 'Respira con normalidad y evita que las rodillas se vayan hacia dentro o sobrepasen los pies.']::text[], actualizado_en = now() WHERE id = '49485222-c9d8-4a08-8fe5-67712d4cf317';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1557', descripcion = 'Fortalece cuádriceps y glúteos con desplazamiento, mejorando el equilibrio y la estabilidad de rodillas y cadera.', instrucciones = ARRAY['Colócate de pie con una mancuerna en cada mano a los lados y el torso erguido.', 'Da un paso largo al frente y baja la rodilla trasera hasta rozar el suelo.', 'Empuja con el talón delantero para avanzar y repite con la otra pierna.', 'Mantén el tronco vertical y evita que la rodilla delantera pase demasiado la punta del pie.']::text[], actualizado_en = now() WHERE id = '5d5e0dc9-084e-4c8c-b7a2-07156c59c271';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1562', descripcion = 'Refuerza cuádriceps y glúteos en isométrico apoyado en la pared, ideal para resistir y cuidar la espalda.', instrucciones = ARRAY['Apoya la fitball contra la pared y coloca la espalda baja sobre ella.', 'Desliza el cuerpo hacia abajo hasta que muslos y rodillas formen unos 90 grados.', 'Mantén la posición con los pies al ancho de hombros y la espalda pegada a la pelota.', 'Respira con normalidad y evita bajar tanto que la espalda se despegue.']::text[], actualizado_en = now() WHERE id = 'f6fd88ce-9380-47df-9fab-96cae834015f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1571', descripcion = 'Aísla la extensión de rodilla para trabajar el cuádriceps y corregir desequilibrios entre piernas.', instrucciones = ARRAY['Siéntate en la máquina con el rodillo justo sobre el empeine y la espalda apoyada.', 'Ajusta el respaldo para que la rodilla quede alineada con el eje de la máquina.', 'Extiende la pierna de forma controlada hasta casi bloquear la rodilla y baja despacio.', 'Evita dar tirones o usar impulso del tronco para subir el peso.']::text[], actualizado_en = now() WHERE id = '6a5dea6b-195b-44b2-ba3c-60522a02e20f';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4989', descripcion = 'Trabaja el core y la coordinación con puñetazos cruzados en equilibrio, mejorando la estabilidad del tronco.', instrucciones = ARRAY['Siéntate en el suelo con las piernas elevadas formando una V y el torso inclinado atrás.', 'Lleva las manos al pecho con los codos flexionados y el abdomen activo.', 'Lanza un puñetazo cruzado hacia delante y alterna el brazo sin perder el equilibrio.', 'Evita redondear la espalda o dejar caer los pies durante el movimiento.']::text[], actualizado_en = now() WHERE id = 'b4a3db81-7494-401a-b33a-59c9bbd1dad6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1586', descripcion = 'Fortalece los isquiotibiales de forma unilateral, corrigiendo diferencias de fuerza y protegiendo la rodilla.', instrucciones = ARRAY['Siéntate en la máquina con el rodillo sobre el tobillo y la espalda bien apoyada.', 'Ajusta el respaldo para que la rodilla coincida con el eje de giro.', 'Flexiona la pierna llevando el talón hacia el glúteo y vuelve despacio.', 'Evita despegar la cadera del asiento o usar impulso para completar la repetición.']::text[], actualizado_en = now() WHERE id = 'ebb4ec0c-43a3-40ca-844d-04ce2ea46006';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1590', descripcion = 'Aísla los isquiotibiales tumbado, útil para ganar fuerza posterior y equilibrar el trabajo de cuádriceps.', instrucciones = ARRAY['Túmbate boca abajo en la máquina con el rodillo sobre el tobillo.', 'Alinea la rodilla con el eje de la máquina y agarra las asas.', 'Flexiona la pierna llevando el talón hacia el glúteo y baja controlando.', 'Evita levantar la cadera del banco o balancear el peso con impulso.']::text[], actualizado_en = now() WHERE id = '14769987-3ba8-4b3c-8ace-f7d14f488282';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1595', descripcion = 'Trabaja cuádriceps y glúteos con barra guiada, permitiendo cargar más y mantener el torso erguido.', instrucciones = ARRAY['Coloca la barra sobre los deltoides delanteros con los codos altos y los pies al ancho de hombros.', 'Desbloquea la barra y desciende flexionando rodillas y cadera con el pecho arriba.', 'Baja hasta donde puedas mantener la espalda recta y empuja con los talones para subir.', 'Evita inclinar el tronco hacia delante o dejar que los codos caigan.']::text[], actualizado_en = now() WHERE id = '99a99bd9-e5f1-41b1-8269-c7bb3d14a852';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1610', descripcion = 'Fortalece el agarre y los flexores de los dedos, útil para mejorar la sujeción en peso muerto y dominadas.', instrucciones = ARRAY['Sujeta la barra por detrás de la espalda con las palmas hacia atrás y los brazos extendidos.', 'Deja que la barra ruede hasta la punta de los dedos sin soltarla.', 'Cierra la mano para enrollar la barra y subirla, apretando el antebrazo.', 'Baja la barra de forma controlada hasta la punta de los dedos y repite.', 'Evita balancear el torso o usar impulso; el movimiento sale solo de las manos.']::text[], actualizado_en = now() WHERE id = '194b2e40-8f3f-42fa-8461-0a5fe01c11a5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1615', descripcion = 'Aísla el bíceps con agarre neutro en máquina, reduciendo tensión en muñeca y codo.', instrucciones = ARRAY['Ajusta la altura del asiento y colócate en la máquina de palanca.', 'Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella.', 'Sujeta las asas con agarre neutro (palmas una frente a la otra).', 'Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'c4e18039-624f-442e-b021-ba9afe72a594';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1624', descripcion = 'Trabaja el pectoral desde un ángulo invertido, sumando deltoides anterior y tríceps con control.', instrucciones = ARRAY['Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas.', 'Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies.', 'Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos.', 'Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados.', 'Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '26d1af77-110f-4714-935b-dbf1c064cb26';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1630', descripcion = 'Curl en polea con agarre cerrado que enfatiza el bíceps y el braquial con tensión constante.', instrucciones = ARRAY['Coloca una barra recta en una máquina de cable con polea baja.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.', 'Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '91ac0791-89f6-4e61-9e97-8018b73b5697';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1632', descripcion = 'Variante de curl que desplaza el codo hacia atrás para aislar el bíceps con tensión continua.', instrucciones = ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.', 'Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '7a2774ed-468e-4970-8be1-f2be26b303de';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1633', descripcion = 'Curl predicador unilateral en polea que aísla el bíceps y corrige desequilibrios entre brazos.', instrucciones = ARRAY['Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.', 'Mantén la espalda recta y el core activado.', 'Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de brazo y repite el ejercicio.']::text[], actualizado_en = now() WHERE id = '1dd68741-908a-4486-8e21-d955728108e2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1634', descripcion = 'Curl tumbado en polea que mantiene el brazo fijo y aísla el bíceps con tensión constante.', instrucciones = ARRAY['Coloca una barra recta en una máquina de cable con polea baja.', 'Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Extiende los brazos por completo, manteniendo los codos cerca de los costados.', 'Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'adf87c99-54ca-4987-b39d-5deb02c6c194';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1639', descripcion = 'Curl predicador con cuerda y agarre neutro que trabaja bíceps y braquial con muñeca estable.', instrucciones = ARRAY['Sujeta un accesorio de cuerda a una máquina de cable con polea baja.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra).', 'Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados.', 'Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la cuerda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '48d7ab36-4d2a-4aa3-a0b3-f794b9736d67';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1643', descripcion = 'Curl sentado con polea alta que estira el bíceps en posición overhead y refuerza el pico.', instrucciones = ARRAY['Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.', 'Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.', 'Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados.', 'Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'de02d48f-a53a-47c3-b336-5d5722d16e9b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1648', descripcion = 'Curl martillo alterno sentado que trabaja bíceps, braquial y antebrazo con agarre neutro.', instrucciones = ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo.', 'Mantén la espalda recta y los codos cerca del torso.', 'Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el movimiento con el brazo izquierdo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'cc9dee30-8b93-4005-bfac-c898abdac5b3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1654', descripcion = 'Curl con agarre prono que carga más el antebrazo y el braquiorradial junto al bíceps.', instrucciones = ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd201bc4b-ca41-4fc9-b915-8e7b0f8814d8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1658', descripcion = 'Ejercicio combinado que suma trabajo de piernas y glúteo con curl de bíceps para ganar coordinación.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo.', 'Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.', 'Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados.', 'Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd6717944-8f49-4d08-8acb-32f1c40666b0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1663', descripcion = 'Curl predicador unilateral con agarre neutro que aísla bíceps y braquial corrigiendo asimetrías.', instrucciones = ARRAY['Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla.', 'Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo).', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = 'cea26c4f-2ad5-4fbd-b63c-0797d02c029d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1664', descripcion = 'Curl con recorrido alto que mantiene tensión en el bíceps en el rango final del movimiento.', instrucciones = ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.', 'Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'b5925323-4676-458c-88d7-3da25fb51ebf';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1670', descripcion = 'Curl de pie a una mano que aísla el bíceps y permite corregir diferencias entre brazos.', instrucciones = ARRAY['Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido.', 'Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = '8d8005e0-9791-4277-a420-6a314963b4c6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1671', descripcion = 'Trabaja el bíceps y los músculos del antebrazo con un agarre neutro que reduce la tensión en la muñeca.', instrucciones = ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.', 'Mantén los codos cerca del torso y los brazos superiores quietos.', 'Exhala y flexiona las pesas mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '43f77e45-ac9b-4c4f-8324-411c9b8f0bd2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1675', descripcion = 'Aísla el bíceps desde un ángulo invertido, incidiendo en el braquial y mejorando la fuerza de agarre.', instrucciones = ARRAY['Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '08b0d9dc-e2b7-4b97-aaf4-fa183f603064';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1678', descripcion = 'Fortalece el bíceps y el antebrazo sentado, evitando balanceos y controlando mejor la fase excéntrica.', instrucciones = ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '027b6866-8d96-44a9-85a5-f4b9ae2988a1';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1688', descripcion = 'Combina fuerza de piernas y rotación de tronco, mejorando el equilibrio y la coordinación en el movimiento.', instrucciones = ARRAY['Comienza de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '0aeff8c7-6666-4a38-aa42-39f9adb0f92b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1700', descripcion = 'Desarrolla potencia de hombros y pecho usando el impulso de piernas para mover más carga en el press.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.', 'Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza.', 'Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '72fea207-9824-4dc8-8c21-60d07bebbeb4';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1705', descripcion = 'Refuerza cuádriceps y glúteos sobre superficie inestable, mejorando el control postural y la propiocepción.', instrucciones = ARRAY['Coloca el bosu en el suelo con el lado plano hacia arriba.', 'Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu.', 'Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.', 'Mantén el pecho elevado y el peso en los talones.', 'Baja hasta que los muslos queden paralelos al suelo.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '4aeda02f-a124-4a7c-9aea-840286b56c77';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1708', descripcion = 'Relaja la pantorrilla tumbado con ayuda, aliviando tensión en gemelo y sóleo tras entrenar o correr.', instrucciones = ARRAY['Túmbate sobre tu espalda con las piernas extendidas.', 'Flexiona una rodilla y coloca el pie plano sobre el suelo.', 'Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta el estiramiento y repite con la otra pierna.']::text[], actualizado_en = now() WHERE id = '5de76858-4ce6-49bd-8b15-f48a9993bc53';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1723', descripcion = 'Aísla el tríceps en polea con un brazo, corrigiendo desequilibrios y mejorando la definición del brazo.', instrucciones = ARRAY['Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho.', 'Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable.', 'Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Comienza con el brazo completamente extendido y perpendicular al suelo.', 'Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido.', 'Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], actualizado_en = now() WHERE id = '72154382-a809-4cff-88fe-10f03e966e96';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1725', descripcion = 'Estira el tríceps en polea desde un ángulo inclinado, aumentando el rango de movimiento y la tensión.', instrucciones = ARRAY['Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo.', 'Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza.', 'Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.', 'Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '5402b97b-4a4d-4671-88f0-c2be0a9c6b94';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '1750', descripcion = 'Trabaja la potencia del pecho lanzando el balón tumbado, útil para deportes que requieren empuje explosivo.', instrucciones = ARRAY['Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo.', 'Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho.', 'Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible.', 'Atrapa el balón medicinal y repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd3693118-650e-405d-abf6-30c35e6d28c6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1752', descripcion = 'Fortalece el tríceps en máquina guiada con inclinación, permitiendo cargas altas con trayectoria segura.', instrucciones = ARRAY['Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.', 'Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho.', 'Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza.', 'Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'c96b0c41-e9ae-4cfd-9355-41404d9977d3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1754', descripcion = 'Sobrecarga pecho y tríceps con fondos entre bancos, añadiendo lastre para ganar fuerza y volumen.', instrucciones = ARRAY['Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.', 'Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos.', 'Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'ade945b6-89e1-45af-bad9-ece0cf722dd0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1755', descripcion = 'Potencia pecho, hombro y tríceps con fondos lastrados, exigiendo control y estabilidad del tronco.', instrucciones = ARRAY['Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.', 'Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti.', 'Mantén la espalda cerca del banco y los codos ligeramente flexionados.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '3bc3ab9a-5d19-42e1-9b4b-f4c84de7f1e8';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '1769', descripcion = 'Activa el bíceps tumbado de lado usando el peso corporal, ideal para principiantes o trabajo de aislamiento.', instrucciones = ARRAY['Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.', 'Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '25daea65-2a3b-42c5-ae89-3375e07ee44d';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1778', descripcion = 'Abre el pecho y el hombro de pie con apoyo, aliviando la tensión acumulada por posturas encorvadas.', instrucciones = ARRAY['Colócate de pie junto a una pared o poste y apoya la palma de la mano a la altura del hombro.', 'Gira el tronco despacio hacia el lado contrario hasta notar estiramiento en el pecho.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita forzar el hombro o encogerlo hacia la oreja durante el estiramiento.', 'Cambia de lado y repite el mismo tiempo para equilibrar ambos pectorales.']::text[], actualizado_en = now() WHERE id = '67647f8e-37ea-45e2-bc2c-8d2b7ab2fd1c';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1779', descripcion = 'Abre el pecho y mejora la movilidad de hombros, útil tras sesiones de empuje o muchas horas sentado estudiando.', instrucciones = ARRAY['Siéntate con la espalda recta y las manos entrelazadas detrás de la nuca.', 'Lleva los codos hacia atrás y abre el pecho sin arquear la zona lumbar.', 'Respira profundo y mantén el estiramiento entre veinte y treinta segundos.', 'Evita tirar del cuello: el movimiento sale de los hombros, no de la cabeza.']::text[], actualizado_en = now() WHERE id = 'a788ef7c-2038-4448-9912-309323b2eac1';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1780', descripcion = 'Estira el pectoral y la parte frontal del hombro para recuperar amplitud tras entrenar empujes.', instrucciones = ARRAY['Coloca un brazo flexionado a noventa grados con el antebrazo apoyado en una pared.', 'Gira el tronco despacio hacia el lado contrario hasta notar tensión en el pecho.', 'Mantén la posición veinte segundos respirando con calma y cambia de lado.', 'No fuerces el hombro ni gires la cabeza; mantén el cuello relajado.']::text[], actualizado_en = now() WHERE id = '682402ad-814b-4e25-bf79-1255f5a538da';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1781', descripcion = 'Libera tensión del pectoral y del deltoides anterior, mejorando la postura y la movilidad escapular.', instrucciones = ARRAY['Apoya los antebrazos en las dos paredes de una esquina a la altura de los hombros.', 'Da un paso hacia la esquina y deja que el pecho se abra sin encoger los hombros.', 'Respira hondo y aguanta entre veinte y treinta segundos.', 'Evita sacar las costillas o arquear la espalda baja durante el estiramiento.']::text[], actualizado_en = now() WHERE id = '7959eb55-1c86-4b88-af87-e0267b448ce3';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '2135', descripcion = 'Refuerza el core de forma isométrica, mejorando la estabilidad del tronco y la protección lumbar.', instrucciones = ARRAY['Comienza tumbándote boca abajo en el suelo.', 'Coloca los antebrazos en el suelo, con los codos justo debajo de los hombros.', 'Extiende las piernas rectas hacia atrás, con la punta de los pies en el suelo.', 'Activa el core y levanta el cuerpo del suelo, equilibrándote sobre los antebrazos y la punta de los pies.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Mantén esta posición durante el tiempo deseado.', 'Baja el cuerpo de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '1f82f7ba-e8fb-4300-91be-8c526218aabe';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1784', descripcion = 'Gana amplitud en el pectoral con una tracción suave que permite regular la intensidad del estiramiento.', instrucciones = ARRAY['Siéntate o túmbate con un brazo extendido hacia un lado y el hombro relajado.', 'Pide a tu compañero que lleve el brazo despacio hacia atrás sin tirones.', 'Comunica la intensidad: debe ser cómoda, nunca dolorosa.', 'Respira de forma pausada y mantén unos veinte segundos por lado.']::text[], actualizado_en = now() WHERE id = 'd37e961c-2edc-43fc-a127-05ed9ddd70e8';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1789', descripcion = 'Mejora la movilidad del hombro y estira el pectoral tumbado, ideal para relajar tras el entrenamiento.', instrucciones = ARRAY['Túmbate boca arriba con los brazos rectos abiertos en cruz.', 'Pide a tu compañero que presione suavemente los brazos hacia el suelo.', 'Mantén los hombros bajos y respira profundo durante veinte segundos.', 'Evita levantar la espalda o forzar si notas pinchazo en el hombro.']::text[], actualizado_en = now() WHERE id = 'f7c6a406-3d57-4d20-905f-cc6f92459d47';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1816', descripcion = 'Estira el tríceps y el antebrazo para recuperar movilidad del codo después de empujes y fondos.', instrucciones = ARRAY['Levanta un brazo y flexiona el codo llevando la mano hacia la nuca.', 'Con la otra mano empuja suavemente el codo hacia abajo sin forzar.', 'Mantén la espalda recta y respira con calma veinte segundos.', 'Evita arquear la zona lumbar o tirar del codo con brusquedad.']::text[], actualizado_en = now() WHERE id = 'e71e5e38-1ed2-46dd-8240-aa188e39f621';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1826', descripcion = 'Alivia la tensión de manos y antebrazos, muy útil tras escribir o usar el móvil muchas horas.', instrucciones = ARRAY['Extiende un brazo al frente con la palma hacia arriba y los dedos relajados.', 'Con la otra mano lleva los dedos suavemente hacia abajo hasta notar tensión.', 'Mantén quince o veinte segundos y cambia de mano.', 'No estires hasta el dolor ni bloquees la respiración.']::text[], actualizado_en = now() WHERE id = 'f9811b68-e44d-41a4-b5cc-2ec8034c549c';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1831', descripcion = 'Relaja el cuello y los escalenos, reduciendo la rigidez típica de estudiar muchas horas frente al ordenador.', instrucciones = ARRAY['Siéntate erguido y gira la cabeza despacio hacia un lado.', 'Baja ligeramente la barbilla y mantén la posición sin forzar.', 'Respira con calma durante quince segundos y cambia de lado.', 'Evita girar rápido o llevar la cabeza hacia atrás.']::text[], actualizado_en = now() WHERE id = 'eec4090e-3aee-45e0-9ae8-5b08c4cc083f';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1836', descripcion = 'Estira la parte posterior del cuello y los escalenos, aliviando la tensión cervical acumulada.', instrucciones = ARRAY['Siéntate con la espalda recta y los hombros relajados.', 'Baja la barbilla hacia el pecho sin encoger los hombros.', 'Puedes apoyar suavemente una mano en la nuca para acompañar el movimiento.', 'Mantén veinte segundos respirando despacio y evita tirar con fuerza.']::text[], actualizado_en = now() WHERE id = '7a4452f5-58f0-464a-82b0-0207fe3d4f76';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1838', descripcion = 'Trabaja la movilidad cervical y estira los extensores del cuello para reducir rigidez y tensión.', instrucciones = ARRAY['Siéntate erguido y gira la cabeza hacia un lado mirando por encima del hombro.', 'Inclina ligeramente la barbilla hacia abajo para aumentar el estiramiento.', 'Mantén quince segundos sin forzar y cambia de lado.', 'Evita encoger el hombro o girar el tronco junto con la cabeza.']::text[], actualizado_en = now() WHERE id = 'f14777bb-f84c-45e7-aa4f-c42cd29533aa';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1840', descripcion = 'Estira los flexores del cuello y los escalenos, mejorando la movilidad cervical tras el estudio.', instrucciones = ARRAY['Siéntate con la espalda recta y los hombros bajos.', 'Gira la cabeza hacia un lado y lleva la barbilla ligeramente hacia arriba.', 'Mantén la posición quince segundos respirando con calma.', 'No fuerces la extensión ni aguantes la respiración.']::text[], actualizado_en = now() WHERE id = '7db5321b-9ca0-4518-aec3-f833cb4f4a17';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1844', descripcion = 'Estira la parte lateral del cuello y el trapecio, aliviando la tensión de hombros y cervicales.', instrucciones = ARRAY['Siéntate erguido y lleva una oreja hacia el hombro del mismo lado.', 'Deja caer el brazo contrario para aumentar suavemente el estiramiento.', 'Mantén veinte segundos respirando despacio y cambia de lado.', 'Evita subir el hombro hacia la oreja o girar la cabeza con brusquedad.']::text[], actualizado_en = now() WHERE id = '3fc90d79-7db2-48cd-bf66-ac86c872a59e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '1861', descripcion = 'Aísla el bíceps con tensión constante en polea, útil para ganar volumen y controlar el recorrido.', instrucciones = ARRAY['Colócate de pie frente a la polea baja y agarra la barra en V con las palmas hacia arriba.', 'Pega los codos al torso y flexiona los antebrazos sin mover los hombros.', 'Sube controlando y baja en dos o tres segundos sin dejar caer el peso.', 'Evita balancear el tronco o adelantar los codos para levantar más carga.']::text[], actualizado_en = now() WHERE id = '93949e49-7070-4a82-99dd-46601a57b545';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1891', descripcion = 'Mejora la movilidad de tobillos y pies, útil para sentadillas profundas y para aliviar tensión plantar.', instrucciones = ARRAY['Colócate en cuclillas apoyando las puntas de los pies y elevando los talones.', 'Mantén el pecho alto y las rodillas alineadas con los pies.', 'Aguanta veinte o treinta segundos respirando con calma.', 'Si molesta, reduce la profundidad y evita cargar todo el peso en los dedos.']::text[], actualizado_en = now() WHERE id = 'd0f66a05-8fbe-4b6e-90a0-c0145c7b4268';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1893', descripcion = 'Estira el tendón de Aquiles y la pantorrilla, mejorando la movilidad del tobillo para sentadillas y zancadas más profundas.', instrucciones = ARRAY['Colócate en cuclillas con los pies planos y las rodillas alineadas con los dedos.', 'Desplaza el peso ligeramente hacia delante sin levantar los talones del suelo.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita que las rodillas se metan hacia dentro para no forzar la articulación.']::text[], actualizado_en = now() WHERE id = '237a419b-519e-4ec5-b23a-2dc8563a79e7';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1908', descripcion = 'Alarga los isquiotibiales y glúteos de pie, útil para aliviar tensión tras estar sentado o antes de entrenar piernas.', instrucciones = ARRAY['De pie con las piernas casi extendidas, flexiona ligeramente las rodillas.', 'Inclina el tronco hacia delante llevando las manos hacia los pies.', 'Mantén la espalda recta y respira despacio durante veinte o treinta segundos.', 'No rebotes ni fuerces hasta el dolor para proteger la zona lumbar.']::text[], actualizado_en = now() WHERE id = 'e0367478-ce2b-4dce-ad49-1370ddbe1f94';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1913', descripcion = 'Estira los isquiotibiales desde el suelo con la punta del pie hacia arriba, ganando flexibilidad en la parte posterior del muslo.', instrucciones = ARRAY['Arrodíllate con una pierna extendida al frente y el pie en flexión dorsal.', 'Lleva las caderas hacia atrás manteniendo la espalda recta.', 'Inclínate suavemente sobre la pierna estirada hasta notar el estiramiento.', 'Respira de forma pausada y evita curvar la zona lumbar.']::text[], actualizado_en = now() WHERE id = '602269cf-7ed0-46e9-be95-ec41bd21a37f';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1923', descripcion = 'Estira los isquiotibiales tumbado con ayuda externa, ideal para relajar la pierna y mejorar el rango de flexión de cadera.', instrucciones = ARRAY['Túmbate boca arriba con una pierna extendida y la otra relajada.', 'Pide a tu asistencia que eleve tu pierna estirada hasta donde toleres.', 'Mantén la rodilla casi recta y respira durante veinte o treinta segundos.', 'No permitas que la cadera se despegue del suelo ni que el estiramiento sea brusco.']::text[], actualizado_en = now() WHERE id = '45422747-73e5-43a9-9857-0df97c9bd1c1';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1930', descripcion = 'Estira gemelos y sóleo en cuclillas con el talón atrás, mejorando la movilidad del tobillo para correr y saltar.', instrucciones = ARRAY['Colócate en cuclillas con un pie adelantado y el otro con el talón apoyado detrás.', 'Empuja la cadera hacia atrás manteniendo el talón trasero en el suelo.', 'Siente el estiramiento en la pantorrilla y respira durante veinte o treinta segundos.', 'Evita levantar el talón o girar el pie hacia fuera.']::text[], actualizado_en = now() WHERE id = '95f8bfb6-1398-4c87-a1f1-78517e1f0091';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1959', descripcion = 'Estira la parte delantera de la espinilla con el pie elevado, útil para equilibrar la tensión tras correr o caminar.', instrucciones = ARRAY['Apoya el empeine de un pie sobre una superficie elevada detrás de ti.', 'Mantén la rodilla cerca del suelo y el tronco erguido.', 'Presiona suavemente el pie contra la superficie y respira durante veinte o treinta segundos.', 'No fuerces la rodilla ni cargues todo el peso sobre el pie elevado.']::text[], actualizado_en = now() WHERE id = '0715316d-8c8d-44bf-bb87-6abe63b7a2a9';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1961', descripcion = 'Estira los dedos de los pies en sentadilla, mejorando la movilidad del pie y aliviando tensión en la planta.', instrucciones = ARRAY['Colócate en cuclillas con los dedos de los pies flexionados bajo el cuerpo.', 'Reparte el peso de forma uniforme y mantén los talones apoyados.', 'Respira con calma durante veinte o treinta segundos.', 'Evita cargar demasiado peso sobre los dedos para no dañar las articulaciones.']::text[], actualizado_en = now() WHERE id = '368174c6-3400-4d40-a8b9-d3a50ee37b76';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece pectoral, hombro anterior y tríceps con una flexión cerrada de rodillas, ideal para progresar hacia el fondo completo.', instrucciones = ARRAY['Colócate de rodillas con las manos bajo los hombros y los codos cerca del cuerpo.', 'Baja el pecho flexionando los codos hasta rozar el suelo.', 'Empuja para volver arriba exhalando y mantén el abdomen firme.', 'Evita abrir los codos en exceso o dejar caer la cadera.']::text[], actualizado_en = now() WHERE id = 'deacf15d-d718-4443-9765-46119dd6ebab';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1970', descripcion = 'Estira el hombro y el deltoides de pie, aliviando tensión tras entrenar o pasar tiempo frente al ordenador.', instrucciones = ARRAY['De pie, entrelaza las manos por delante del cuerpo.', 'Eleva los brazos estirados por encima de la cabeza sin encoger los hombros.', 'Mantén la posición respirando durante veinte o treinta segundos.', 'No arquees la espalda ni subas los hombros hacia las orejas.']::text[], actualizado_en = now() WHERE id = '62f1d547-6c34-4366-bf2d-fadea34a90e7';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1974', descripcion = 'Estira el deltoides posterior y la parte alta de la espalda, mejorando la movilidad del hombro y la postura.', instrucciones = ARRAY['De pie, lleva un brazo estirado por delante del pecho.', 'Con la otra mano, empuja suavemente el codo hacia el cuerpo.', 'Mantén el hombro bajo y respira durante veinte o treinta segundos.', 'Evita girar el tronco o forzar el codo en exceso.']::text[], actualizado_en = now() WHERE id = '99c1c9f4-e39b-4019-abb2-bfa6f50e85df';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1980', descripcion = 'Estira el pectoral y el hombro anterior cruzando el brazo sobre el pecho, útil para contrarrestar posturas encorvadas.', instrucciones = ARRAY['De pie, cruza un brazo estirado sobre el pecho a la altura del hombro.', 'Con la otra mano, sujeta el codo y acércalo al cuerpo.', 'Mantén el hombro relajado y respira durante veinte o treinta segundos.', 'No eleves el hombro ni gires el tronco para forzar el estiramiento.']::text[], actualizado_en = now() WHERE id = '51d80fd7-fdc9-4392-95de-cfd6082c37ec';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '1986', descripcion = 'Estira los rotadores externos del hombro con el brazo elevado, mejorando la movilidad y previniendo molestias articulares.', instrucciones = ARRAY['De pie, eleva un brazo y flexiona el codo con la mano detrás de la cabeza.', 'Con la otra mano, presiona suavemente el codo hacia atrás.', 'Mantén el tronco erguido y respira durante veinte o treinta segundos.', 'Evita arquear la espalda o tirar con fuerza del codo.']::text[], actualizado_en = now() WHERE id = '7e6db321-73e8-45a0-ab74-6f70eec9f7aa';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2091', descripcion = 'Estira los flexores y extensores del antebrazo con los dedos hacia abajo, aliviando tensión de muñeca y codo.', instrucciones = ARRAY['Extiende un brazo al frente con la palma hacia abajo.', 'Deja caer la muñeca y apunta los dedos hacia el suelo.', 'Con la otra mano, presiona suavemente el dorso de la mano hacia ti.', 'Mantén el codo casi recto y respira durante veinte o treinta segundos.']::text[], actualizado_en = now() WHERE id = 'd43c1060-a561-4759-88c6-b28219884b1f';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2102', descripcion = 'Estira gemelos y sóleo sentado tirando de los dedos del pie, útil para relajar la pantorrilla tras el ejercicio.', instrucciones = ARRAY['Siéntate con una pierna extendida y la otra flexionada.', 'Sujeta la punta del pie estirado y llévala suavemente hacia ti.', 'Mantén la rodilla casi recta y respira durante veinte o treinta segundos.', 'Evita tirar con brusquedad o levantar la rodilla del suelo.']::text[], actualizado_en = now() WHERE id = '3a949df1-3daf-4e30-9da7-e70389eef889';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2107', descripcion = 'Moviliza la columna y abre el pecho en la postura de la vaca, mejorando la flexibilidad de espalda y cuello.', instrucciones = ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Inhala mientras arqueas la espalda y elevas la mirada al frente.', 'Exhala volviendo a la posición neutra y repite el movimiento con control.', 'Evita forzar el cuello hacia atrás o hundir los hombros.']::text[], actualizado_en = now() WHERE id = '639c47cb-14d4-40c3-82e9-31ab8fd2ab70';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2116', descripcion = 'Estiramiento para relajar glúteos y zona lumbar, mejorando la movilidad de la cadera y aliviando tensión.', instrucciones = ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos en cruz.', 'Flexiona una rodilla y cruza la pierna por encima de la otra, dejando caer la rodilla hacia el suelo.', 'Gira la cabeza hacia el lado contrario y respira despacio manteniendo el estiramiento.', 'Evita forzar la rodilla contra el suelo; deja que el peso de la pierna haga el trabajo.']::text[], actualizado_en = now() WHERE id = '37c88b6b-75fe-46b8-a28b-a939fadf654e';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2119', descripcion = 'Estiramiento para alargar la musculatura lateral del tronco y mejorar la movilidad de la columna.', instrucciones = ARRAY['Ponte de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Eleva un brazo por encima de la cabeza y llévalo hacia el lado contrario inclinando el tronco.', 'Mantén las caderas estables y respira profundo sin rebotar.', 'Evita arquear la espalda hacia atrás; inclínate solo hacia el lado.']::text[], actualizado_en = now() WHERE id = 'dc1f0e5a-e820-4708-a9e2-d352a8cd5e14';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2121', descripcion = 'Ejercicio de fuerza para oblicuos y estabilidad del core, útil para controlar la inclinación lateral del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Eleva ligeramente la cabeza y los hombros y lleva una mano hacia el talón del mismo lado.', 'Vuelve al centro y repite hacia el otro lado con un movimiento controlado.', 'Evita tirar del cuello con las manos; mantén la mirada hacia arriba.']::text[], actualizado_en = now() WHERE id = '8529ff20-6fa0-4258-b4ab-41c94cffdb1b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '2189', descripcion = 'Aislamiento de tríceps para ganar fuerza y volumen en la parte posterior del brazo.', instrucciones = ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza.', 'Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.', 'Extiende los brazos y sube la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd4a5d3a7-c330-4dca-9fbf-c80a5e1c57d5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '2206', descripcion = 'Trabajo abdominal que incide en el recto abdominal y oblicuos mediante la elevación controlada de la pelvis.', instrucciones = ARRAY['Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti.', 'Coloca el rodillo entre los pies y sujétalo con los dedos de los pies.', 'Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '9c4d3f8c-84df-49a8-9e50-8eff3035aa6b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de fuerza para cuádriceps y glúteos que mejora el equilibrio y la estabilidad de la pierna.', instrucciones = ARRAY['Sujeta una mancuerna en cada mano y ponte de pie con los pies a la anchura de las caderas.', 'Da un paso largo hacia atrás y baja la rodilla trasera hasta acercarla al suelo.', 'Empuja con el pie delantero para volver a la posición inicial y alterna las piernas.', 'Mantén el tronco erguido y evita que la rodilla delantera pase por delante de la punta del pie.']::text[], actualizado_en = now() WHERE id = '8b6c5ea0-4643-414a-8aeb-9641a1e94a21';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de fuerza para piernas que mejora la potencia y el control del equilibrio al subir a una superficie.', instrucciones = ARRAY['Coloca un escalón estable delante de ti y sujeta una mancuerna en cada mano.', 'Apoya un pie entero sobre el escalón y empuja con esa pierna para subir.', 'Extiende la cadera arriba sin bloquear la rodilla y baja controlando el movimiento.', 'Evita impulsarte con la pierna de abajo; el trabajo debe hacerlo la pierna que sube.']::text[], actualizado_en = now() WHERE id = '3cd49e82-dbcf-4514-b02b-f00f2cf363a9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de empuje para pectoral y hombro anterior que fortalece el tren superior con apoyo de las piernas.', instrucciones = ARRAY['Siéntate en la prensa con la espalda apoyada y los pies en la plataforma.', 'Agarra las asas y empuja hacia delante extendiendo los brazos sin bloquear los codos.', 'Vuelve despacio a la posición inicial controlando el recorrido.', 'Evita despegar la espalda del respaldo o bloquear las rodillas al empujar.']::text[], actualizado_en = now() WHERE id = '5a2ae49c-8466-4797-b1a8-cad8a761b2c5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de fuerza para cuádriceps y glúteos que mejora el equilibrio y la coordinación con carga.', instrucciones = ARRAY['Coloca la barra sobre los trapecios y ponte de pie con los pies a la anchura de las caderas.', 'Da un paso largo hacia atrás y baja la rodilla trasera hasta acercarla al suelo.', 'Empuja con el pie delantero para volver a la posición inicial y alterna las piernas.', 'Mantén el tronco erguido y evita que la rodilla delantera se desplace hacia dentro.']::text[], actualizado_en = now() WHERE id = '17e0794c-2838-404f-81e7-7fcbf9bf946f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de fuerza para cuádriceps y glúteos que trabaja la estabilidad lateral de la pierna.', instrucciones = ARRAY['Coloca la barra sobre los trapecios y ponte de pie con los pies juntos.', 'Da un paso amplio hacia un lado y flexiona esa rodilla llevando la cadera hacia atrás.', 'Empuja con la pierna que has abierto para volver al centro y alterna los lados.', 'Mantén la punta del pie alineada con la rodilla y evita que se meta hacia dentro.']::text[], actualizado_en = now() WHERE id = '673234e9-2c6f-4b22-bb38-7f85c3cdd63b';
