UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '2329', descripcion = 'Trabaja oblicuos y recto abdominal movilizando la columna, útil para calentar el core y mejorar la rotación torácica.', instrucciones = ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.', 'Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.', 'Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'a1fbda1e-8b00-45c4-b5fa-ef1d6eebb44e';
