UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio global con barra que implica piernas, espalda y core, mejorando la coordinación y la potencia del cuerpo.', instrucciones = ARRAY['Sujeta la barra con las manos a la anchura de los hombros y los pies separados.', 'Inclina el tronco llevando la cadera atrás mientras flexionas las rodillas.', 'Baja la barra de forma controlada y empuja con los talones para volver a la posición inicial.', 'Mantén la espalda neutra y evita redondear la zona lumbar durante el recorrido.']::text[], actualizado_en = now() WHERE id = '5aae662e-54e6-4c32-ad1a-7cee751a54bb';
