UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '2993', descripcion = 'Abre la cadera y mejora la profundidad de la sentadilla mientras trabajas cuádriceps y glúteo con carga ligera.', instrucciones = ARRAY['Sujeta la kettlebell a la altura del pecho con ambas manos y los codos hacia dentro.', 'Baja en sentadilla profunda manteniendo el torso erguido y los talones en el suelo.', 'Permanece unos segundos abajo y empuja suavemente las rodillas hacia fuera con los codos.', 'Sube controlando la respiración y evita que la espalda se redondee.']::text[], actualizado_en = now() WHERE id = '7ff77b9f-8153-4ac7-9c50-9c14477b50d9';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '2998', descripcion = 'Gana dorsiflexión de tobillo para sentarte más profundo y reducir tensión en la parte baja de la pierna.', instrucciones = ARRAY['Siéntate en una silla y cruza un tobillo sobre la rodilla contraria.', 'Sujeta la punta del pie y llévala suavemente hacia ti hasta notar estiramiento en la parte delantera del tobillo.', 'Mantén la posición entre 20 y 30 segundos respirando con calma.', 'Evita forzar ni rebotar; suelta despacio y cambia de lado.']::text[], actualizado_en = now() WHERE id = '26dcb183-0ed1-4155-91f3-5bcb7f1208d8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja piernas y glúteo con un gesto funcional que mejora la capacidad cardiovascular y la fuerza de empuje.', instrucciones = ARRAY['Colócate frente a un tramo de escaleras con el torso erguido y la mirada al frente.', 'Sube apoyando el pie completo en cada escalón y empujando con el talón.', 'Sube a un ritmo constante sin inclinarte hacia delante ni agarrarte a la barandilla.', 'Baja controlando el movimiento y repite durante el tiempo indicado.']::text[], actualizado_en = now() WHERE id = 'dfdc7ee5-f85c-4fce-b866-0404261fef0e';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3021', descripcion = 'Activa la musculatura escapular y estabiliza el hombro, útil como calentamiento antes de empujes.', instrucciones = ARRAY['Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.', 'A medida que bajas, junta las escápulas y empuja el pecho hacia delante.', 'Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '427658d2-129c-4c11-875c-1baed5efb8b8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza cuádriceps y glúteo con la barra al frente, mejorando la postura y el control en sentadilla.', instrucciones = ARRAY['Coloca la barra sobre los deltoides frontales con los codos altos y los pies a la anchura de los hombros.', 'Baja controlando hasta tocar el banco con los glúteos, manteniendo el pecho alto.', 'Empuja con los talones para subir sin perder la posición de los codos.', 'Evita que las rodillas se metan hacia dentro y no dejes caer los codos.']::text[], actualizado_en = now() WHERE id = 'b92e4a49-94f0-4007-a124-fd4f96d03dd3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el antebrazo y el braquiorradial, mejorando el agarre y la estabilidad de la muñeca.', instrucciones = ARRAY['Siéntate con los antebrazos apoyados en los muslos y sujeta la barra con las palmas hacia abajo.', 'Deja que la muñeca baje lentamente hasta donde puedas controlar.', 'Sube la barra flexionando la muñeca sin mover los antebrazos.', 'Evita usar impulso y mantén un rango de movimiento cómodo.']::text[], actualizado_en = now() WHERE id = '83c51071-92da-4f67-8514-499035bb7a2f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3030', descripcion = 'Trabaja cuádriceps y glúteo de forma unilateral con barra, mejorando fuerza y estabilidad de la pierna.', instrucciones = ARRAY['Coloca la barra sobre la espalda alta y da un paso amplio hacia atrás con un pie.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con el talón delantero para volver a la posición inicial.', 'Evita que la rodilla delantera se desplace hacia dentro y mantén el abdomen activo.']::text[], actualizado_en = now() WHERE id = '77b04cb2-4454-4c34-9cd1-ad4507f10951';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el pectoral con un ángulo inclinado que enfatiza la parte superior del pecho y el hombro.', instrucciones = ARRAY['Colócate entre las poleas con un mango en cada mano y el banco inclinado detrás.', 'Apoya la espalda en el banco y abre los brazos con los codos ligeramente flexionados.', 'Junta las manos al frente describiendo un arco amplio y controlado.', 'Evita bloquear los codos o usar impulso; controla la vuelta.']::text[], actualizado_en = now() WHERE id = 'a50fab04-2aba-4161-8ba2-96163cdc4dcc';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps tumbado en polea, reduciendo el impulso y manteniendo tensión constante.', instrucciones = ARRAY['Túmbate en el suelo o banco con la polea baja y agarra el mango con las palmas hacia arriba.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Baja controlando la extensión hasta casi estirar del todo.', 'Evita despegar los codos del torso o usar el balanceo del cuerpo.']::text[], actualizado_en = now() WHERE id = '546200c0-fe7e-400c-a8b5-7cce5c0a45ce';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el pectoral y el tríceps en polea sentado, con tensión constante y recorrido seguro.', instrucciones = ARRAY['Siéntate frente a la polea con los mangos a la altura del pecho y la espalda apoyada.', 'Empuja los mangos hacia delante hasta extender los brazos sin bloquear los codos.', 'Vuelve despacio controlando la tensión y manteniendo los omóplatos estables.', 'Evita arquear la zona lumbar o encoger los hombros durante el empuje.']::text[], actualizado_en = now() WHERE id = 'c284ab81-5963-4d4e-8981-ce16f9f4a084';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el recto abdominal y los oblicuos elevando la pelvis desde una posición declinada, mejorando el control del core.', instrucciones = ARRAY['Túmbate boca arriba en un banco declinado con las piernas flexionadas y las manos agarradas al borde superior.', 'Contrae el abdomen y eleva la pelvis acercando las rodillas al pecho sin balancearte.', 'Espira al subir y baja de forma controlada en dos o tres segundos.', 'Evita tirar del cuello o usar impulso con las piernas para no perder la tensión abdominal.']::text[], actualizado_en = now() WHERE id = 'c53019ff-ec36-4d4f-aba9-c93ff10162cb';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece gemelos y sóleo mediante la extensión del tobillo contra la resistencia de la máquina, mejorando el empuje y la estabilidad del pie.', instrucciones = ARRAY['Colócate en la máquina con los hombros bajo las almohadillas y la punta de los pies en la plataforma.', 'Baja los talones hasta notar estiramiento en los gemelos sin perder el equilibrio.', 'Empuja con la punta de los pies y eleva los talones lo máximo posible.', 'Aguanta un segundo arriba y baja despacio, evitando rebotar en la posición baja.']::text[], actualizado_en = now() WHERE id = '8e4383ef-36e5-4956-bdd3-f931fc8a2923';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio básico de piernas que activa cuádriceps, glúteos e isquiotibiales, útil para mejorar la fuerza y la técnica de sentadilla.', instrucciones = ARRAY['Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando caderas y rodillas como si te sentaras en una silla, manteniendo el pecho erguido.', 'Llega hasta donde puedas sin que la espalda se curve y empuja con los talones para subir.', 'Evita que las rodillas se metan hacia dentro y controla la bajada durante dos segundos.']::text[], actualizado_en = now() WHERE id = '59301335-51d5-4d24-a3d0-d9dbf83a0940';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3119', descripcion = 'Sentadilla sin material que fortalece cuádriceps, glúteos e isquiotibiales, base para el trabajo de piernas y la movilidad de cadera.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.', 'Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.', 'Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'aa11b94f-356d-4efb-86fb-6ea78a84889f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Elevación de talones de pie que trabaja la pantorrilla y el equilibrio, útil para la estabilidad del tobillo y la fuerza del tren inferior.', instrucciones = ARRAY['Colócate de pie con las manos apoyadas en una pared o silla para mantener el equilibrio.', 'Eleva los talones lo máximo posible y mantén la punta de los pies en el suelo.', 'Aguanta un segundo arriba y baja los talones de forma controlada.', 'Evita inclinarte hacia delante o rebotar para no perder la tensión en los gemelos.']::text[], actualizado_en = now() WHERE id = 'e5eb2a3a-0247-49de-b26f-7d6de5344f39';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Flexión que enfatiza la protracción escapular para activar el pectoral y estabilizar la escápula, útil como preparación al push-up.', instrucciones = ARRAY['Colócate en posición de plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Mantén los codos rectos y empuja el suelo separando las escápulas para redondear ligeramente la espalda alta.', 'Vuelve despacio a la posición inicial sin dejar caer el pecho.', 'Evita hundir la cadera o bloquear la respiración durante el movimiento.']::text[], actualizado_en = now() WHERE id = '46ea4b99-a6e6-4bc8-88de-949f4878fdc4';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '3150', descripcion = 'Ejercicio de control cervical que fortalece la musculatura profunda del cuello y mejora la postura de la cabeza.', instrucciones = ARRAY['Siéntate o túmbate con la espalda recta y la mirada al frente.', 'Lleva la barbilla hacia atrás como si hicieras una doble papada, sin inclinar la cabeza.', 'Mantén la posición dos o tres segundos y respira con normalidad.', 'Evita empujar con fuerza o mover los hombros hacia arriba durante la retracción.']::text[], actualizado_en = now() WHERE id = 'cd77e172-cb14-4cc8-af0a-4ff743640e19';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Retracción cervical que activa la musculatura profunda del cuello para corregir la postura adelantada de la cabeza.', instrucciones = ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Desliza la barbilla hacia atrás sin bajar la vista, como si quisieras hacer una doble papada.', 'Mantén la posición unos segundos y suelta despacio.', 'Evita inclinar la cabeza hacia abajo o tensar el cuello en exceso.']::text[], actualizado_en = now() WHERE id = 'fce74275-f151-4847-abf1-517481a05aac';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Variante asistida de retracción cervical que fortalece el cuello profundo y mejora el control postural de la cabeza.', instrucciones = ARRAY['Colócate sentado o tumbado con la espalda apoyada y los hombros bajos.', 'Lleva la barbilla hacia atrás ayudándote ligeramente con la mano si lo necesitas.', 'Mantén la retracción dos o tres segundos sin aguantar la respiración.', 'Evita tirar fuerte de la cabeza o encoger los hombros durante el ejercicio.']::text[], actualizado_en = now() WHERE id = '1c6db8be-6a23-4c5a-8384-cb975a672150';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3234', descripcion = 'Apertura de pectoral con mancuerna que trabaja el pecho y el deltoides anterior, mejorando la amplitud y el control del hombro.', instrucciones = ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.', 'Manteniendo una ligera flexión en los codos, baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'f1526653-8f96-4871-a6da-305c41312c88';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3237', descripcion = 'Elevación lateral con landmine que activa el deltoides medio y el trapecio, útil para ganar fuerza y estabilidad en el hombro.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros.', 'Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '4634a213-c607-4e51-8d5f-77687a61fa05';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Crunch en el suelo con pies apoyados en un banco que trabaja el recto abdominal y los oblicuos con mayor control y menos tensión lumbar.', instrucciones = ARRAY['Túmbate boca arriba con los pies apoyados en el banco y las rodillas flexionadas.', 'Coloca las manos en las sienes o cruzadas sobre el pecho sin tirar del cuello.', 'Eleva la parte alta de la espalda contrayendo el abdomen y espira al subir.', 'Baja despacio sin apoyar del todo la cabeza y evita usar impulso con las piernas.']::text[], actualizado_en = now() WHERE id = 'ffbb8ae5-32e4-4c27-8782-34c771adf01a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3281', descripcion = 'Sentadilla profunda guiada en máquina Smith que fortalece cuádriceps, glúteos e isquiotibiales con mayor estabilidad.', instrucciones = ARRAY['Configura la máquina Smith con la barra a la altura de los hombros.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.', 'Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.', 'Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable.', 'Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.', 'Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita.', 'Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'ebf96214-16c7-4271-a855-4e4b10d46d67';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3295', descripcion = 'Repeticiones de front lever que trabajan el core y la espalda en suspensión, mejorando la fuerza isométrica y el control corporal.', instrucciones = ARRAY['Cuélgate de una barra de dominadas con agarre prono, palmas hacia afuera.', 'Activa el core y lleva los omóplatos hacia abajo y atrás.', 'Manteniendo el cuerpo recto, levanta las piernas hasta que queden paralelas al suelo.', 'Mantén esta posición todo el tiempo que puedas, intentando llegar a 10-20 segundos.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '7151c8ed-61d3-4948-9a9e-65eb82764962';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '3296', descripcion = 'Front lever isométrico que fortalece el core, la espalda y los hombros manteniendo el cuerpo horizontal en suspensión.', instrucciones = ARRAY['Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros.', 'Activa el core y lleva los omóplatos hacia abajo y atrás.', 'Flexiona las rodillas y llévalas hacia el pecho.', 'Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo.', 'Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal.', 'Para soltar, baja lentamente las piernas y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '415861eb-0236-4289-9b8b-7dbc393c9d6e';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '3299', descripcion = 'Trabaja el core con máxima tensión isométrica y sirve para progresar hacia la plancha completa en calistenia.', instrucciones = ARRAY['Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante.', 'Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo.', 'Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos.', 'Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.', 'Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'dab2a0ef-5482-4c6b-a157-1ddcf42589f0';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '3301', descripcion = 'Activa abdomen y oblicuos en posición de plancha con rodillas recogidas, ideal como paso previo a la plancha completa.', instrucciones = ARRAY['Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos.', 'Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta.', 'Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho.', 'Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '3d90d0e2-0769-48cd-8140-043ca97ba21c';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '3302', descripcion = 'Fortalece manos, muñecas y dedos mientras entrenas el equilibrio invertido y la estabilidad del core.', instrucciones = ARRAY['Busca un espacio abierto con suficiente espacio para hacer un pino.', 'Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante.', 'Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio.', 'Una vez en posición de pino, activa los tríceps para sostener el peso corporal.', 'Mantén el pino el mayor tiempo posible mientras conserves el equilibrio.', 'Para bajar, lleva lentamente las piernas de vuelta al suelo.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '44c6c67f-6207-44f2-8625-09393743b57b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3333', descripcion = 'Trabaja el pectoral de forma unilateral con apertura amplia, mejorando fuerza y control de cada lado.', instrucciones = ARRAY['Túmbate en el banco con una mancuerna en una mano y el brazo extendido sobre el pecho.', 'Abre el brazo hacia el lado con el codo ligeramente flexionado hasta notar estiramiento en el pecho.', 'Empuja la mancuerna hacia arriba hasta la posición inicial mientras exhalas.', 'Mantén el hombro estable y evita bajar más allá de la línea del torso.']::text[], actualizado_en = now() WHERE id = '0e434d8a-8614-455c-b9a5-5906e1b0b441';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3334', descripcion = 'Aísla el pectoral con apertura unilateral en el suelo, limitando el rango para proteger el hombro.', instrucciones = ARRAY['Túmbate en el suelo con una mancuerna en una mano y el brazo extendido hacia el techo.', 'Baja el brazo hacia el lado con el codo algo flexionado hasta que el hombro roce el suelo.', 'Sube la mancuerna de vuelta arriba controlando el movimiento y exhalando.', 'Evita arquear la espalda o dejar caer el brazo de golpe.']::text[], actualizado_en = now() WHERE id = '9342b145-a8a5-4ac3-a1e4-1e121f0d542d';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '3337', descripcion = 'Refuerza oblicuos y core en isométrico lateral, añadiendo carga para aumentar la exigencia.', instrucciones = ARRAY['Colócate de lado apoyando el antebrazo en el suelo y sujeta la mancuerna con la mano libre.', 'Eleva la cadera hasta formar una línea recta entre cabeza, tronco y pies.', 'Mantén la posición con la mancuerna pegada al cuerpo y respira con normalidad.', 'Baja la cadera con control al terminar y evita que el hombro se hunda.']::text[], actualizado_en = now() WHERE id = '4fef06c3-05aa-4789-838f-3c75bbc9d5e0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3342', descripcion = 'Trabaja el deltoides medio con trayectoria en Y, útil para mejorar la estabilidad del hombro.', instrucciones = ARRAY['Colócate frente a la polea baja con los mangos en las manos y los brazos extendidos.', 'Eleva los brazos en diagonal formando una Y hasta la altura de los hombros.', 'Baja lentamente controlando la polea y mantén el core activo.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], actualizado_en = now() WHERE id = '003d2d71-7128-4bbe-b687-facfee6b7b7b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3345', descripcion = 'Fortalece antebrazo y muñeca con resistencia de muelle, mejorando el agarre y la prevención de lesiones.', instrucciones = ARRAY['Sujeta el fortalecedor de muelle con la palma hacia arriba y el antebrazo apoyado.', 'Flexiona la muñeca lentamente venciendo la resistencia del muelle.', 'Vuelve a la posición inicial de forma controlada sin dejar que el muelle se cierre de golpe.', 'Mantén el codo fijo y evita mover el antebrazo durante el recorrido.']::text[], actualizado_en = now() WHERE id = '2bb34c42-2bd8-4eae-b75c-aa80c925366e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja cuádriceps y glúteo con carga frontal, reforzando la postura erguida y el control del core.', instrucciones = ARRAY['Colócate de espaldas a la polea baja con el mango a la altura del pecho y los codos altos.', 'Baja en sentadilla manteniendo el tronco erguido y las rodillas alineadas con los pies.', 'Empuja con los talones para subir mientras exhalas y mantienes la tensión en la polea.', 'Evita inclinarte hacia delante o dejar que las rodillas se metan hacia dentro.']::text[], actualizado_en = now() WHERE id = '2882fd06-6b2e-48cf-a42c-0945ec63cf76';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3359', descripcion = 'Trabaja el pectoral de pie con polea, mejorando la estabilidad del core y la fuerza de empuje.', instrucciones = ARRAY['Sujeta los mangos de la polea a la altura del pecho con un pie adelantado.', 'Empuja las manos hacia delante extendiendo los brazos sin bloquear los codos.', 'Vuelve lentamente a la posición inicial controlando la polea.', 'Mantén el core firme y evita arquear la espalda al empujar.']::text[], actualizado_en = now() WHERE id = 'cff4d094-eb2a-475f-8732-d89d985baa13';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio guiado en máquina que trabaja el pectoral con empuje controlado y seguro.', instrucciones = ARRAY['Siéntate en la máquina con la espalda apoyada y los mangos a la altura del pecho.', 'Empuja los mangos hacia delante extendiendo los brazos sin bloquear los codos.', 'Vuelve despacio a la posición inicial mientras inspiras.', 'Ajusta el asiento para que los codos queden alineados con los hombros.']::text[], actualizado_en = now() WHERE id = 'eb7b9c66-65c3-4494-b203-111453a7b119';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Variante de flexión que enfatiza el pectoral superior y los hombros usando dos bancos.', instrucciones = ARRAY['Coloca las manos en dos bancos separados y eleva la cadera formando una pica.', 'Baja la cabeza entre los bancos flexionando los codos con control.', 'Empuja hacia arriba hasta extender los brazos mientras exhalas.', 'Mantén la cadera alta y evita que la espalda se hunda.']::text[], actualizado_en = now() WHERE id = 'b363e3e5-4ddb-4cd4-924e-0306cec16507';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3723', descripcion = 'Trabaja cuádriceps y glúteo con patrón cruzado, mejorando estabilidad y coordinación de piernas.', instrucciones = ARRAY['Coloca la barra sobre los trapecios y da un paso cruzado por detrás de la otra pierna.', 'Baja flexionando ambas rodillas manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se desplace hacia dentro o que el tronco se incline.']::text[], actualizado_en = now() WHERE id = '4669b455-a51d-4ec4-acca-9837ed53837f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Flexión en pica con apoyo en sillas que enfatiza hombros y pectoral superior sin material de gimnasio.', instrucciones = ARRAY['Apoya las manos en dos sillas separadas y eleva la cadera formando una pica.', 'Baja la cabeza entre las sillas flexionando los codos con control.', 'Empuja hacia arriba hasta extender los brazos mientras exhalas.', 'Mantén la cadera alta y evita que los codos se abran en exceso.']::text[], actualizado_en = now() WHERE id = 'b20c9550-de07-4048-a7fe-e2e8359a486b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3415', descripcion = 'Trabaja isquiotibiales con curl inverso asistido, útil para fortalecer la parte posterior del muslo.', instrucciones = ARRAY['Colócate en la máquina o apoyo con las piernas extendidas y el cuerpo alineado.', 'Flexiona las rodillas llevando los talones hacia los glúteos con ayuda de la asistencia.', 'Vuelve lentamente a la posición inicial controlando el movimiento.', 'Evita arquear la espalda o usar impulso para completar la repetición.']::text[], actualizado_en = now() WHERE id = 'f019245e-c1f7-44e1-b7c0-71150e71fe94';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3418', descripcion = 'Trabaja dorsal y romboides con fuerza y control, mejorando tu capacidad de tracción y la estabilidad del core.', instrucciones = ARRAY['Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.', 'Cuélgate con los brazos completamente extendidos y el cuerpo recto.', 'Activa los dorsales y los bíceps para llevar el cuerpo hacia arriba en dirección a la barra, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '79e1d903-915c-49fe-919f-1dd48d7f3bb7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3422', descripcion = 'Fortalece el recto abdominal y los oblicuos, mejorando la estabilidad del core y la protección de la zona lumbar.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y el balón medicinal sujeto con las manos frente al pecho.', 'Contrae el abdomen y eleva la parte superior de la espalda del suelo sin tirar del cuello.', 'Sube exhalando y baja inspirando de forma controlada, sin dejar caer la cabeza.', 'Evita impulsarte con los brazos o balancear el balón para no perder la tensión abdominal.']::text[], actualizado_en = now() WHERE id = 'dce707e6-0f79-41c6-aad6-ea49c30523c4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el pectoral mayor y mejora la apertura torácica, útil para equilibrar el trabajo de empuje y la postura.', instrucciones = ARRAY['Túmbate boca arriba con una mancuerna en cada mano y los brazos extendidos sobre el pecho.', 'Abre los brazos en arco con los codos ligeramente flexionados hasta notar estiramiento en el pecho.', 'Vuelve a la posición inicial juntando las mancuernas sin bloquear los codos.', 'Exhala al cerrar e inhala al abrir, evitando bajar más de lo que controlas.']::text[], actualizado_en = now() WHERE id = '2b6db2a6-e662-46d9-888e-208ace58b7cc';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el pectoral mayor con presión interna, mejorando la conexión neuromuscular y la estabilidad del hombro.', instrucciones = ARRAY['De pie o sentado, sujeta el lastre con las palmas enfrentadas a la altura del pecho.', 'Presiona las manos una contra otra mientras extiendes los brazos al frente.', 'Mantén la presión dos segundos y vuelve despacio al pecho.', 'Evita encoger los hombros o arquear la espalda durante el movimiento.']::text[], actualizado_en = now() WHERE id = 'b561495b-5a43-4dab-9b99-168a2a42abcb';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el deltoides posterior y mejora el equilibrio del hombro, ayudando a corregir la postura encorvada.', instrucciones = ARRAY['Inclínate hacia delante con la espalda recta y sujeta una mancuerna en cada mano.', 'Con los codos ligeramente flexionados, eleva los brazos hacia los lados hasta la altura de los hombros.', 'Baja las mancuernas de forma controlada sin dejar caer los brazos.', 'Evita usar impulso del tronco o encoger el cuello al subir.']::text[], actualizado_en = now() WHERE id = 'd07d1ec7-b4a5-4c4c-910d-e9f5645d37b0';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3438', descripcion = 'Trabaja el core y la cadera en un rango amplio, mejorando el control pélvico y la fuerza abdominal inferior.', instrucciones = ARRAY['Siéntate en el banco declinado y sujétate por detrás con las manos.', 'Eleva las piernas y la cadera juntas contrayendo el abdomen.', 'Baja despacio sin dejar que la espalda se arquee en exceso.', 'Exhala al subir e inhala al bajar, evitando balancearte con impulso.']::text[], actualizado_en = now() WHERE id = 'ed93fad4-4833-4256-bddf-558c6de0209a';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3443', descripcion = 'Fortalece pecho y tríceps con el peso corporal, ideal para progresar hacia fondos completos en el suelo.', instrucciones = ARRAY['Coloca las manos en el suelo a la altura de los hombros y apoya las rodillas o los pies.', 'Baja el pecho flexionando los codos cerca del cuerpo hasta rozar el suelo.', 'Empuja hacia arriba extendiendo los brazos sin bloquear los codos.', 'Mantén el abdomen firme y evita que la cadera se hunda o suba demasiado.']::text[], actualizado_en = now() WHERE id = '92c35f01-3eaf-4340-b56c-9929d927ef9a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el recto abdominal y los oblicuos con control, mejorando la flexión de tronco y la estabilidad del core.', instrucciones = ARRAY['Túmbate boca arriba con las piernas extendidas y sujeta una mancuerna con ambas manos.', 'Eleva brazos y piernas a la vez formando una V, contrayendo el abdomen.', 'Baja despacio sin dejar que la espalda se arquee ni que la mancuerna golpee el suelo.', 'Exhala al subir e inhala al bajar, evitando impulsarte con las piernas.']::text[], actualizado_en = now() WHERE id = '6182d7bb-3eda-4bf0-8f65-55feb85f00d2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece cuádriceps y glúteos en un plano lateral, mejorando la estabilidad de rodilla y cadera.', instrucciones = ARRAY['De pie con una mancuerna en cada mano y los pies juntos.', 'Da un paso amplio hacia un lado flexionando la rodilla de esa pierna.', 'Empuja con la pierna de apoyo para volver al centro manteniendo el tronco recto.', 'Evita que la rodilla pase por delante de la punta del pie o que el tronco se incline.']::text[], actualizado_en = now() WHERE id = '9f4e4db6-a48e-4bb7-bef3-04736b21b1c8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3449', descripcion = 'Trabaja oblicuos y recto abdominal con rotación, mejorando la fuerza rotacional y la estabilidad del core.', instrucciones = ARRAY['Siéntate con las rodillas flexionadas y el tronco ligeramente inclinado hacia atrás.', 'Sujeta la mancuerna con ambas manos frente al pecho.', 'Gira el tronco hacia un lado y luego hacia el otro de forma controlada.', 'Mantén la espalda recta y evita tirar de los brazos o balancearte con impulso.']::text[], actualizado_en = now() WHERE id = 'f593fa04-9768-4d41-9ff4-bb7233b3521c';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3452', descripcion = 'Activa el pectoral mayor con presión interna, mejorando la conexión neuromuscular y la estabilidad del hombro.', instrucciones = ARRAY['De pie o sentado, sujeta una mancuerna con ambas palmas enfrentadas a la altura del pecho.', 'Presiona la mancuerna entre las manos mientras extiendes los brazos al frente.', 'Mantén la presión dos segundos y vuelve despacio al pecho.', 'Evita encoger los hombros o arquear la espalda durante el movimiento.']::text[], actualizado_en = now() WHERE id = 'edfef66d-c17f-4383-aaca-5897b03bbf4a';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3459', descripcion = 'Activa el core y la cadera con pulsos cortos, mejorando el control pélvico y la resistencia abdominal.', instrucciones = ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas ligeramente flexionadas.', 'Eleva la cadera del suelo contrayendo el abdomen y los glúteos.', 'Haz pulsos cortos hacia arriba sin bajar del todo la cadera.', 'Mantén la respiración constante y evita arquear la zona lumbar.']::text[], actualizado_en = now() WHERE id = 'ec1109dc-c212-46d0-a078-40361aff87c9';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '3500', descripcion = 'Mejora la movilidad de cadera y tobillo en sentadilla profunda, facilitando patrones de sentadilla más seguros.', instrucciones = ARRAY['Colócate con los pies a la anchura de los hombros y las puntas ligeramente hacia fuera.', 'Baja en sentadilla profunda manteniendo los talones en el suelo y el pecho erguido.', 'Permanece en la posición baja respirando profundo y relajando la cadera.', 'Evita que las rodillas se metan hacia dentro o que los talones se despeguen.']::text[], actualizado_en = now() WHERE id = '1b244103-0821-4d09-b6a8-e37e33879314';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el core y los oblicuos con antirotación, mejorando la estabilidad lumbar y el control postural.', instrucciones = ARRAY['Colócate en plancha frontal con los codos bajo los hombros y el cuerpo alineado.', 'Eleva una pierna del suelo sin mover la cadera ni el tronco.', 'Mantén la posición dos segundos y baja la pierna con control.', 'Evita que la cadera se hunda o se eleve demasiado durante el movimiento.']::text[], actualizado_en = now() WHERE id = '85797f27-84bf-4b3f-b1af-c8fb50570e64';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '3504', descripcion = 'Estira el cuádriceps y mejora el equilibrio y la movilidad de cadera, útil tras entrenar piernas.', instrucciones = ARRAY['De pie, sujétate a una pared o silla para mantener el equilibrio.', 'Flexiona una rodilla y lleva el talón hacia el glúteo sujetando el pie con la mano.', 'Mantén las rodillas juntas y la cadera hacia delante durante el estiramiento.', 'Respira profundo y evita arquear la espalda o tirar del pie con fuerza.']::text[], actualizado_en = now() WHERE id = '137048c0-cd16-42cd-b53d-dae8fa67f399';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el bíceps braquial y los flexores del codo con resistencia manual, útil para ganar fuerza en casa sin material.', instrucciones = ARRAY['Colócate de rodillas o sentado con la espalda recta y un brazo extendido hacia delante.', 'Con la otra mano agarra tu muñeca y ofrece resistencia mientras flexionas el codo.', 'Sube despacio controlando el movimiento y baja aún más lento sin soltar la tensión.', 'Mantén el codo pegado al costado y evita balancear el tronco para no hacer trampa.']::text[], actualizado_en = now() WHERE id = 'fd5a1105-d52b-4102-9d89-ee60386da5ec';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3510', descripcion = 'Activa el recto abdominal y los oblicuos con un movimiento corto y controlado que mejora la estabilidad del core.', instrucciones = ARRAY['Túmbate boca arriba con las lumbares pegadas al suelo y las manos junto a la cabeza.', 'Eleva ligeramente los hombros y las piernas formando una pequeña curva en V.', 'Acerca las rodillas al pecho mientras llevas los codos hacia ellas y vuelve a estirar.', 'Espira al recoger y evita tirar del cuello con las manos.']::text[], actualizado_en = now() WHERE id = 'a9b54506-051e-476e-9045-8e673a9b08bd';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3512', descripcion = 'Refuerza el recto abdominal y los oblicuos manteniendo la columna estable mientras brazos y piernas se mueven.', instrucciones = ARRAY['Túmbate boca arriba con brazos extendidos hacia el techo y rodillas a 90 grados.', 'Presiona las lumbares contra el suelo y mantén la tensión en el abdomen.', 'Baja un brazo y la pierna contraria sin arquear la espalda y vuelve al centro.', 'Alterna lados despacio y evita aguantar la respiración durante el movimiento.']::text[], actualizado_en = now() WHERE id = 'f33e44dd-3105-4223-a232-b1a17155f541';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '3513', descripcion = 'Mejora la movilidad del hombro y estira deltoides y tríceps, útil tras sesiones de empuje o para ganar rango.', instrucciones = ARRAY['Sujeta una banda con una mano por delante y pasa la otra por detrás de la espalda.', 'Estira suavemente la banda separando las manos hasta notar tensión en el hombro.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita encoger el hombro o forzar el rango si aparece dolor.']::text[], actualizado_en = now() WHERE id = '68e4635d-424a-489d-94f2-053cb83fc704';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3514', descripcion = 'Fortalece isquiotibiales y glúteos con un puente deslizante que exige control y estabilidad de cadera.', instrucciones = ARRAY['Túmbate boca arriba con un talón sobre una toalla y la otra pierna elevada.', 'Empuja con el talón para elevar la cadera y desliza el pie hacia ti.', 'Mantén la cadera alta un instante y vuelve a estirar la pierna despacio.', 'Evita arquear la lumbar y no dejes caer la cadera durante el recorrido.']::text[], actualizado_en = now() WHERE id = 'f4d58a69-69cf-4748-8ff0-8d225310f08f';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3515', descripcion = 'Trabaja oblicuos y recto abdominal con una torsión que mejora el control rotacional del tronco.', instrucciones = ARRAY['Túmbate boca arriba con brazos y piernas extendidos y ligeramente elevados.', 'Sube el tronco y las piernas a la vez llevando una mano hacia el pie contrario.', 'Vuelve al centro controlando la bajada y repite hacia el otro lado.', 'Evita tirar del cuello y mantén el abdomen activo en todo el recorrido.']::text[], actualizado_en = now() WHERE id = 'fe2a66da-70df-4b3f-9c62-da1f1d541c45';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = '3516', descripcion = 'Abre el pecho y los hombros en extensión de columna, ideal para contrarrestar posturas encorvadas de estudio.', instrucciones = ARRAY['Colócate de pie con las manos entrelazadas detrás de la espalda.', 'Abre el pecho y lleva los brazos hacia atrás mientras extiendes suavemente la columna.', 'Mantén la posición sin forzar la lumbar y respira de forma pausada.', 'Evita sacar las costillas en exceso o echar la cabeza demasiado atrás.']::text[], actualizado_en = now() WHERE id = '87265d35-ed47-4d52-b235-95267db72d75';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3541', descripcion = 'Activa el deltoides medio en un ángulo que mejora la estabilidad del hombro y la postura en el banco inclinado.', instrucciones = ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.', 'Inclínate ligeramente hacia adelante y deja que los brazos cuelguen rectos hacia abajo, manteniendo una ligera flexión en los codos.', 'Levanta los brazos hacia los lados y hacia arriba formando una Y hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'd24e22e0-3054-4d2c-9fc3-c4af5ab7001b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3542', descripcion = 'Refuerza el deltoides medio y la musculatura escapular con una elevación en T que mejora el control del hombro.', instrucciones = ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.', 'Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo.', 'Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una ''T'' con el cuerpo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '5d3cc4a2-33b6-4546-938a-19c9e3fc4635';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3545', descripcion = 'Trabaja el pectoral mayor y el deltoides anterior con un press alterno que exige estabilidad en el banco inclinado.', instrucciones = ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.', 'Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.', 'Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante.', 'Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos.', 'Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados.', 'Repite el número de repeticiones deseado, alternando los brazos.']::text[], actualizado_en = now() WHERE id = 'f1acae0b-b652-4702-aa82-ed3be9b3de7b';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3553', descripcion = 'Fortalece pectoral, hombro y tríceps añadiendo una rotación que activa el core y mejora el control escapular.', instrucciones = ARRAY['Colócate en plancha alta con las manos algo más anchas que los hombros.', 'Baja el pecho flexionando los codos manteniendo el cuerpo en línea.', 'Al subir, gira el tronco y eleva un brazo hacia el techo.', 'Vuelve a la plancha y alterna lados sin dejar caer la cadera.']::text[], actualizado_en = now() WHERE id = '0b200f57-51e2-4c32-95e6-6c827dfb674a';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3557', descripcion = 'Trabaja el pectoral y el tríceps con una variante de rodillas y manos abiertas, ideal para iniciarse en flexiones.', instrucciones = ARRAY['Apoya las rodillas y las manos más anchas que los hombros con el cuerpo alineado.', 'Baja el pecho despacio manteniendo el abdomen firme y los codos abiertos.', 'Empuja para volver arriba sin bloquear del todo los codos.', 'Evita dejar caer la cadera o adelantar la cabeza al bajar.']::text[], actualizado_en = now() WHERE id = 'f37e4d9e-261d-4fce-93c3-8567b88e2593';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '3569', descripcion = 'Libera tensión en el pectoral y el hombro anterior, mejorando la movilidad y reduciendo molestias tras entrenar.', instrucciones = ARRAY['Coloca una pelota en la pared y apoya el pectoral sobre ella.', 'Presiona suavemente y busca puntos de tensión moviendo el brazo.', 'Mantén la presión unos segundos respirando despacio hasta notar alivio.', 'Evita presionar sobre el hueso o zonas con dolor agudo.']::text[], actualizado_en = now() WHERE id = 'db52d55e-b312-4a8d-b4f8-20c808b512f3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3571', descripcion = 'Ejercicio global de potencia que activa cadena posterior, core y agarre en un movimiento explosivo de cadera.', instrucciones = ARRAY['Coloca la kettlebell delante con los pies a la anchura de los hombros.', 'Haz una bisagra de cadera y agarra el asa con ambas manos.', 'Impulsa la cadera para llevar la pesa hasta la altura del pecho.', 'Deja que baje entre las piernas y evita redondear la espalda o usar los brazos.']::text[], actualizado_en = now() WHERE id = 'd218c1d5-097a-434a-8716-e1bfc4cc7460';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3572', descripcion = 'Fortalece hombro y tríceps con un press vertical estricto que exige estabilidad del core y control postural.', instrucciones = ARRAY['Sujeta la kettlebell a la altura del hombro con el codo pegado al cuerpo.', 'Presiona hacia arriba sin arquear la espalda y aprieta el abdomen.', 'Baja la pesa controlando hasta la posición inicial.', 'Evita usar impulso de piernas o inclinarte hacia atrás.']::text[], actualizado_en = now() WHERE id = '6d21659c-b70e-4bca-ab03-97ba1bbc556f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3575', descripcion = 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad de rodilla.', instrucciones = ARRAY['Sujeta la kettlebell a la altura del pecho y colócate de pie con los pies a la anchura de las caderas.', 'Da un paso largo hacia atrás y baja la rodilla trasera hasta rozar el suelo, manteniendo el torso erguido.', 'Empuja con el pie delantero para volver a la posición inicial y alterna las piernas.', 'Inspira al bajar y espira al subir, controlando el descenso.', 'Evita que la rodilla delantera se vaya hacia dentro o pase de la punta del pie.']::text[], actualizado_en = now() WHERE id = '9dcdc0e1-ccac-44c9-ae9b-0758ea6df2ab';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '3582', descripcion = 'Trabaja cuádriceps y glúteos con un gesto explosivo que mejora la potencia y la coordinación del tren inferior.', instrucciones = ARRAY['Comienza de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Empújate con el pie derecho y salta al aire, cambiando la posición de los pies en pleno vuelo.', 'Aterriza suavemente con el pie izquierdo hacia adelante y baja inmediatamente el cuerpo a una posición de zancada.', 'Continúa alternando entre zancadas y saltos el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '019b5721-8c8c-421d-983e-bf0e09afd9fd';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3585', descripcion = 'Desarrolla glúteo e isquiotibiales con control unilateral, mejorando el equilibrio y la estabilidad de cadera.', instrucciones = ARRAY['Colócate de pie sobre una pierna con la rodilla ligeramente flexionada y los brazos extendidos.', 'Inclina el torso hacia delante mientras llevas la pierna libre hacia atrás, manteniendo la espalda recta.', 'Vuelve a la vertical y sube la rodilla libre hasta la altura de la cadera antes de repetir.', 'Mantén la mirada al frente y respira de forma constante durante todo el movimiento.', 'Evita redondear la espalda o perder la alineación de la cadera.']::text[], actualizado_en = now() WHERE id = 'b2187051-7614-4403-99bb-ed609337f02b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el tren inferior y los estabilizadores globales con un patrón dinámico que mejora la coordinación y el equilibrio.', instrucciones = ARRAY['Colócate de pie con los pies juntos y el torso erguido.', 'Da un salto abriendo las piernas y cruzando los brazos al frente, aterrizando con las rodillas flexionadas.', 'Vuelve a saltar para juntar los pies y repetir el gesto de forma continua.', 'Aterriza suavemente con la parte media del pie y mantén el abdomen activo.', 'Evita que las rodillas se hundan hacia dentro al caer.']::text[], actualizado_en = now() WHERE id = 'c39844b7-c153-4739-8b7f-9e466c2d3736';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3587', descripcion = 'Refuerza glúteos y estabilizadores de cadera con una elevación unilateral que mejora el control y la fuerza del tren inferior.', instrucciones = ARRAY['Coloca el lastre sobre la cadera o sujétalo con las manos y túmbate boca arriba.', 'Sube una pierna manteniéndola estirada mientras la otra queda apoyada con la rodilla flexionada.', 'Eleva la cadera del suelo apretando el glúteo hasta formar una línea recta con el torso.', 'Baja de forma controlada sin apoyar del todo y repite las repeticiones.', 'Evita arquear la zona lumbar en la parte alta del movimiento.']::text[], actualizado_en = now() WHERE id = '176c830a-5be5-4259-b83b-fa4f49c2eb1f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3644', descripcion = 'Trabaja cuádriceps y glúteos con un patrón de zancada dinámico que mejora la estabilidad y la coordinación.', instrucciones = ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos.', 'Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo.', 'Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '8439f237-9264-494f-9c1f-3a4df410f6db';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '3663', descripcion = 'Fortalece el core y los erectores espinales con una plancha invertida que mejora la estabilidad y la extensión de cadera.', instrucciones = ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies.', 'Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa.', 'Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo.', 'Mantén la posición por un momento y luego baja la pierna de nuevo.', 'Repite con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = 'df50648c-3a0e-4be8-bf04-c0e77e4b0eee';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3670', descripcion = 'Trabaja el recto abdominal y los oblicuos con un recorrido completo que aumenta la fuerza y el control del core.', instrucciones = ARRAY['Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies.', 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], actualizado_en = now() WHERE id = '833098d6-0112-4c08-8a42-05d346f8f8c3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '3682', descripcion = 'Aísla el bíceps en un ángulo estirado que favorece el rango completo y el crecimiento del brazo.', instrucciones = ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano y los brazos colgando.', 'Flexiona un codo llevando la mancuerna hacia el hombro sin mover el brazo del sitio.', 'Baja lentamente hasta estirar del todo el brazo y repite con el otro lado.', 'Espira al subir y controla el descenso en dos o tres segundos.', 'Evita balancear el torso o despegar la espalda del respaldo.']::text[], actualizado_en = now() WHERE id = '47af766b-3ead-41a5-99a4-e7575446b1ad';
