UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4746', descripcion = 'Trabaja el core y los oblicuos con control rotacional, mejorando la estabilidad del tronco y la coordinación.', instrucciones = ARRAY['Colócate de pie con los pies más anchos que los hombros y una mancuerna en la mano derecha.', 'Lleva la cadera hacia atrás y baja la mancuerna por la pierna derecha mientras la izquierda se eleva.', 'Mantén la espalda recta y la mirada al frente, sin redondear la zona lumbar.', 'Sube apretando el oblicuo y respira al volver a la posición inicial.', 'Evita girar el tronco en exceso; el movimiento debe ser lateral y controlado.']::text[], actualizado_en = now() WHERE id = '56841be3-a036-49b6-b1fb-837c840c9231';
