UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4798', descripcion = 'Activa dorsal y romboides alternando brazos, mejorando la estabilidad escapular y la extensión torácica.', instrucciones = ARRAY['Túmbate boca abajo con los brazos extendidos al frente y el core activado.', 'Eleva un brazo y la pierna contraria a la vez, manteniendo el cuello neutro.', 'Aguanta un segundo arriba y baja con control antes de cambiar de lado.', 'Respira de forma constante y evita arquear la zona lumbar.', 'No levantes la cabeza ni fuerces el cuello; la mirada va al suelo.']::text[], actualizado_en = now() WHERE id = '85a68840-53e0-475c-b1d5-d1e2790effbe';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el abdomen y los oblicuos con control en suspensión, mejorando la estabilidad del core y la coordinación.', instrucciones = ARRAY['Colócate en posición de plancha con las manos en el suelo y el cuerpo alineado.', 'Lleva las rodillas hacia el pecho de forma controlada sin perder la alineación.', 'Extiende las piernas de nuevo lentamente, manteniendo el abdomen activo.', 'Exhala al recoger y evita que la cadera suba o baje.', 'No dejes caer la zona lumbar; mantén el core firme en todo el recorrido.']::text[], actualizado_en = now() WHERE id = 'a40d630d-6c79-4271-9e15-582cff039b97';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Moviliza y fortalece los oblicuos de pie, mejorando la flexibilidad lateral del tronco y el control postural.', instrucciones = ARRAY['De pie con los pies a la anchura de los hombros y los brazos relajados.', 'Inclina el tronco hacia un lado deslizando la mano por la pierna, sin girar.', 'Vuelve al centro con control y repite hacia el otro lado.', 'Respira de forma fluida y evita rebotar en el estiramiento.', 'No fuerces más allá de tu rango cómodo; mantén la cadera estable.']::text[], actualizado_en = now() WHERE id = '56661966-a176-4664-b7a5-885f0a278418';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza oblicuos y core en isométrico, mejorando la estabilidad lateral y la resistencia del tronco.', instrucciones = ARRAY['Túmbate de lado apoyando el antebrazo y el codo bajo el hombro.', 'Eleva la cadera hasta alinear tobillo, cadera y hombro.', 'Mantén la posición apretando el abdomen y respirando con normalidad.', 'Evita que la cadera caiga o que el cuerpo se gire hacia delante.', 'Baja con control y cambia de lado.']::text[], actualizado_en = now() WHERE id = '542733d1-bd85-4506-94e6-88065cd4c032';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4820', descripcion = 'Fortalece el abdomen con un despliegue inverso en anillas, mejorando el control excéntrico y la estabilidad del core.', instrucciones = ARRAY['Sujeta las anillas y colócate en posición de plancha con el cuerpo alineado.', 'Lleva las rodillas hacia el pecho manteniendo los brazos firmes.', 'Extiende las piernas lentamente controlando la bajada.', 'Exhala al recoger y evita balancear el cuerpo.', 'No dejes caer la cadera; mantén el abdomen activo en todo momento.']::text[], actualizado_en = now() WHERE id = 'a7877844-f559-4676-9d06-2a37b5263020';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4830', descripcion = 'Activa el pectoral y los tríceps desde una postura de yoga, mejorando la fuerza de empuje y la movilidad torácica.', instrucciones = ARRAY['Colócate en postura del niño con las palmas en el suelo y los brazos extendidos.', 'Manteniendo la cadera atrás, flexiona los codos y baja el pecho hacia el suelo.', 'Empuja con las palmas para volver, sin perder la posición de la cadera.', 'Exhala al bajar y evita arquear la zona lumbar.', 'No bloquees los codos al extender; mantén un ligero control.']::text[], actualizado_en = now() WHERE id = '8245c246-fb0c-4b48-8884-b0c1490e7c94';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4832', descripcion = 'Trabaja el deltoides posterior tumbado, mejorando la fuerza de la espalda y la estabilidad del hombro.', instrucciones = ARRAY['Túmbate boca abajo con los brazos extendidos hacia los lados y las palmas al suelo.', 'Eleva los brazos hacia arriba apretando los omóplatos.', 'Aguanta un segundo y baja con control sin tocar el suelo.', 'Exhala al subir y evita encoger el cuello.', 'No uses impulso; el movimiento debe ser lento y controlado.']::text[], actualizado_en = now() WHERE id = '4ff800bb-1b64-481f-ad4c-5cb577e04d7a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4838', descripcion = 'Aísla el bíceps con polea unilateral, mejorando la fuerza y el control del brazo en un rango completo.', instrucciones = ARRAY['Colócate frente a la polea con el mango en una mano y el codo pegado al torso.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo.', 'Baja lentamente controlando la resistencia.', 'Exhala al subir y evita balancear el tronco.', 'No despegues el codo del costado durante el recorrido.']::text[], actualizado_en = now() WHERE id = 'b1695c1a-20b1-40c8-ae6a-8e673f702834';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4845', descripcion = 'Fortalece el pectoral y los tríceps tumbado en el suelo, mejorando el empuje con un rango seguro.', instrucciones = ARRAY['Túmbate boca arriba con una kettlebell en cada mano a la altura del pecho.', 'Empuja hacia arriba extendiendo los brazos sin bloquear los codos.', 'Baja controlando hasta que los codos toquen el suelo.', 'Exhala al empujar y evita arquear la zona lumbar.', 'No dejes que las kettlebells se abran hacia los lados; mantén las muñecas firmes.']::text[], actualizado_en = now() WHERE id = '117cf942-b017-41ca-aa2c-9c9d33ececf5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4848', descripcion = 'Trabaja los cuádriceps con sentadilla frontal desde soportes, mejorando la fuerza y la técnica de empuje.', instrucciones = ARRAY['Coloca la barra en los soportes a la altura de los hombros y sujétala en posición frontal.', 'Baja flexionando las rodillas y la cadera manteniendo el torso erguido.', 'Empuja con los talones para subir, apretando el core.', 'Exhala al subir y evita que los codos caigan.', 'No dejes que las rodillas se metan hacia dentro; mantenlas alineadas con los pies.']::text[], actualizado_en = now() WHERE id = 'cd4c0c14-faca-4fd3-be99-b7d4a90fd30b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4866', descripcion = 'Fortalece el pectoral y los hombros sentado en el suelo, mejorando la estabilidad del core y el empuje vertical.', instrucciones = ARRAY['Siéntate en el suelo con las piernas extendidas y la barra a la altura del pecho.', 'Empuja la barra hacia arriba extendiendo los brazos sin bloquear los codos.', 'Baja controlando hasta el pecho manteniendo el torso erguido.', 'Exhala al empujar y evita arquear la espalda.', 'No uses impulso con las piernas; el movimiento nace del tren superior.']::text[], actualizado_en = now() WHERE id = '0a00fc88-367e-4a6d-b9b0-ce95bc447554';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el core y los estabilizadores con una presión isométrica, mejorando la conciencia corporal y la fuerza postural.', instrucciones = ARRAY['Junta las palmas de las manos a la altura del pecho con los codos hacia fuera.', 'Presiona las palmas una contra otra manteniendo el abdomen activo.', 'Aguanta la tensión respirando con normalidad.', 'Evita encoger los hombros o contener la respiración.', 'Relaja lentamente al terminar, sin soltar de golpe.']::text[], actualizado_en = now() WHERE id = 'c3792d42-f1a3-440c-9a45-4af0611b6890';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el deltoides medio y los estabilizadores del hombro, mejorando la fuerza y el control escapular.', instrucciones = ARRAY['Túmbate de lado con el brazo inferior extendido y el cuerpo alineado.', 'Eleva el brazo hacia arriba hasta la vertical sin mover el tronco.', 'Baja con control y repite sin dejar caer el brazo.', 'Exhala al subir y evita encoger el cuello.', 'No gires el torso; mantén la cadera estable durante todo el movimiento.']::text[], actualizado_en = now() WHERE id = '42ce929b-ef07-4afa-8400-b3fc9e8f380d';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4891', descripcion = 'Trabaja el core y los oblicuos en suspensión, mejorando el control rotacional y la estabilidad del tronco.', instrucciones = ARRAY['Cuélgate de una barra con agarre firme y el cuerpo extendido.', 'Lleva las piernas juntas hacia un lado mientras giras la cadera, sin balancearte.', 'Controla el descenso y repite hacia el lado contrario con movimiento lento.', 'Evita arquear la zona lumbar manteniendo el abdomen activo en todo momento.']::text[], actualizado_en = now() WHERE id = 'cfee9378-a6e7-47cd-bf99-3b8d11858704';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4922', descripcion = 'Aísla el pectoral con apertura controlada en anillas, ganando fuerza y estabilidad en el hombro.', instrucciones = ARRAY['Colócate entre las anillas con brazos extendidos y pies apoyados.', 'Abre los brazos despacio dejando que el pecho descienda entre las anillas.', 'Junta de nuevo las manos apretando el pectoral al final del recorrido.', 'Mantén los codos ligeramente flexionados y evita bajar más de lo que controlas.']::text[], actualizado_en = now() WHERE id = '0afb6cd7-e401-4643-9c13-08abc816d6bc';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira gemelos y sóleo para mejorar la movilidad del tobillo y aliviar tensión tras el entrenamiento.', instrucciones = ARRAY['Túmbate boca arriba con las piernas extendidas.', 'Lleva una pierna hacia el pecho y agarra la punta del pie con la mano.', 'Tira suavemente del pie hacia ti hasta notar el estiramiento en el gemelo.', 'Mantén la posición respirando despacio y sin rebotar.']::text[], actualizado_en = now() WHERE id = '10fb2759-453a-4d70-8708-d37eb35c7b09';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira el gemelo de forma unilateral para ganar movilidad y corregir desequilibrios entre piernas.', instrucciones = ARRAY['Apoya las manos en una pared y da un paso atrás con una pierna.', 'Mantén la pierna trasera extendida con el talón pegado al suelo.', 'Inclina el cuerpo hacia delante hasta notar tensión en el gemelo.', 'Evita levantar el talón y mantén la respiración relajada.']::text[], actualizado_en = now() WHERE id = 'd1327435-8fc9-4d3a-93c0-763e35ed6101';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el core y los estabilizadores con un movimiento circular que mejora el control del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas flexionadas.', 'Dibuja círculos lentos con las piernas sin despegar la zona lumbar del suelo.', 'Cambia el sentido del giro tras varias repeticiones.', 'Evita arquear la espalda y mantén el abdomen apretado.']::text[], actualizado_en = now() WHERE id = 'e317e9ec-cec8-44c2-9e6c-a7e3a1553c07';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Abre el pecho y activa el pectoral de forma isométrica, útil para mejorar la postura encorvada.', instrucciones = ARRAY['De pie, entrelaza las manos detrás de la espalda.', 'Estira los brazos hacia abajo y atrás abriendo el pecho.', 'Mantén la contracción sin encoger los hombros durante unos segundos.', 'Respira con normalidad y evita forzar la zona lumbar.']::text[], actualizado_en = now() WHERE id = '51b157ff-aef7-4daa-8797-1a3c83027aa4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4946', descripcion = 'Trabaja el pectoral con apertura y cierre controlado, ideal para activar el pecho sentado.', instrucciones = ARRAY['Siéntate erguido con los brazos extendidos al frente.', 'Abre los brazos hacia los lados juntando las escápulas.', 'Cierra de nuevo apretando el pecho al final del movimiento.', 'Mantén los hombros bajos y evita encogerlos.']::text[], actualizado_en = now() WHERE id = 'be34f779-d1ab-4ff7-acfb-cf91de4cc802';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4947', descripcion = 'Fortalece la musculatura cervical y mejora la movilidad del cuello con un gesto controlado.', instrucciones = ARRAY['Siéntate erguido con los hombros relajados.', 'Mira hacia el techo extendiendo el cuello sin forzar.', 'Mantén unos segundos y vuelve despacio a la posición neutra.', 'Evita echar la cabeza atrás bruscamente y respira con calma.']::text[], actualizado_en = now() WHERE id = '94141ef5-4219-4791-9fea-493ff4b126f2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4960', descripcion = 'Aísla el tríceps en polea para ganar fuerza y definición en la parte posterior del brazo.', instrucciones = ARRAY['Colócate frente a la polea con los codos pegados al cuerpo.', 'Extiende los antebrazos hacia abajo hasta estirar del todo el tríceps.', 'Vuelve despacio controlando el retorno sin mover los codos.', 'Evita abrir los codos y mantener los hombros elevados.']::text[], actualizado_en = now() WHERE id = '44fde817-9762-406a-b4bb-03ef26b5ceca';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '4961', descripcion = 'Trabaja el tríceps en posición prona con mancuerna, mejorando la extensión y el control del brazo.', instrucciones = ARRAY['Túmbate boca abajo con una mancuerna en la mano y el codo pegado al cuerpo.', 'Extiende el antebrazo hacia atrás hasta estirar el tríceps.', 'Baja despacio controlando el movimiento sin girar el torso.', 'Evita balancear el brazo y mantén el hombro estable.']::text[], actualizado_en = now() WHERE id = 'e8486e5e-0f2e-4b28-a132-51551561602d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el core y los flexores de cadera con elevación controlada de piernas tumbado.', instrucciones = ARRAY['Túmbate boca arriba con las piernas extendidas y las manos bajo la cadera.', 'Eleva las piernas juntas hasta formar un ángulo recto.', 'Baja despacio sin despegar la zona lumbar del suelo.', 'Evita arquear la espalda y controla la respiración.']::text[], actualizado_en = now() WHERE id = 'e1182fbb-815e-4f76-b761-26cfbb4c79f6';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4982', descripcion = 'Trabaja el core con un descenso excéntrico exigente que mejora la fuerza y el control abdominal.', instrucciones = ARRAY['Cuélgate de una barra y sube las piernas hasta quedar en vertical.', 'Mantén el cuerpo recto como una tabla y baja despacio y controlado.', 'Evita arquear la zona lumbar apretando el abdomen.', 'Repite el descenso sin dejar caer las piernas de golpe.']::text[], actualizado_en = now() WHERE id = '6c773c82-3b49-48a3-aeee-f70e6b82035d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Variante de flexión que trabaja el pectoral y el tríceps con menor carga y control postural.', instrucciones = ARRAY['Apoya las rodillas en el suelo con las manos algo adelantadas.', 'Baja el pecho hacia el suelo llevando la cadera atrás.', 'Sube empujando con los brazos y extendiendo el pecho.', 'Evita hundir la zona lumbar y mantén el abdomen activo.']::text[], actualizado_en = now() WHERE id = 'baf22ad4-e66c-4428-b936-9466c99525f8';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4990', descripcion = 'Activa oblicuos y recto abdominal con un crunch que combina flexión y acercamiento de rodillas.', instrucciones = ARRAY['Túmbate boca arriba con las manos detrás de la cabeza.', 'Eleva el torso y lleva las rodillas hacia el pecho girando ligeramente.', 'Aprieta el abdomen al final del movimiento y baja despacio.', 'Evita tirar del cuello con las manos.']::text[], actualizado_en = now() WHERE id = 'e8525f99-777e-4ded-ad29-cc9b41a388f1';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4992', descripcion = 'Trabaja oblicuos y recto abdominal con un crunch cruzado que mejora la coordinación del core.', instrucciones = ARRAY['Túmbate boca arriba con las manos detrás de la cabeza y rodillas flexionadas.', 'Lleva un codo hacia la rodilla contraria elevando el torso.', 'Vuelve al centro y alterna hacia el otro lado.', 'Evita tirar del cuello y mantén el movimiento lento y controlado.']::text[], actualizado_en = now() WHERE id = '32864c35-afdd-4133-9e98-08c4c0e8abd4';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '4994', descripcion = 'Activa el core y los estabilizadores de la cadera, mejorando el control del tronco y la coordinación cruzada.', instrucciones = ARRAY['Túmbate boca arriba con los brazos en cruz y las piernas estiradas.', 'Eleva las piernas hasta la vertical y cruza una sobre la otra sin tocar el suelo.', 'Alterna el cruce de forma lenta y controlada, manteniendo la zona lumbar pegada al suelo.', 'Evita arquear la espalda baja: si se despega, reduce el rango del movimiento.']::text[], actualizado_en = now() WHERE id = '5bab91a4-6292-42d3-a98a-98b69e1ed058';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el recto abdominal y los oblicuos con apoyo de rodillas, ideal para iniciarse en el trabajo isométrico del core.', instrucciones = ARRAY['Colócate en cuadrupedia y apoya los antebrazos en el suelo con los codos bajo los hombros.', 'Apoya las rodillas y extiende las caderas hasta formar una línea recta desde la cabeza hasta las rodillas.', 'Aprieta el abdomen y los glúteos, y respira de forma pausada sin aguantar el aire.', 'Evita hundir la zona lumbar o subir las caderas: mantén la pelvis neutra.']::text[], actualizado_en = now() WHERE id = '6369ed3a-25c7-4b16-b58e-ec0ef30cd54a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el recto abdominal y los oblicuos con un recorrido completo, mejorando la fuerza y el control del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las piernas rectas y los brazos extendidos hacia los pies.', 'Eleva el tronco y las piernas a la vez hasta tocar los pies con las manos.', 'Baja de forma controlada sin apoyar del todo la espalda y repite.', 'Evita tirar del cuello o usar impulso: inicia el movimiento con el abdomen.']::text[], actualizado_en = now() WHERE id = '3bb4e938-30e5-42b2-9adf-611d7215035c';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '5009', descripcion = 'Fortalece la pantorrilla y mejora la estabilidad del tobillo, útil para la propulsión al caminar y correr.', instrucciones = ARRAY['Colócate de pie con la punta de los pies sobre una plataforma y los talones al aire.', 'Baja los talones lentamente hasta notar estiramiento en la pantorrilla.', 'Empuja con la punta de los pies para elevarte lo máximo posible y aguanta un segundo arriba.', 'Evita rebotar o perder el equilibrio: controla el descenso en cada repetición.']::text[], actualizado_en = now() WHERE id = '46b4d420-3cad-4303-804b-e3741d59f52b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '5010', descripcion = 'Enfatiza la parte inferior del pectoral y mejora la fuerza en el punto de salida del press con una pausa controlada.', instrucciones = ARRAY['Túmbate en el banco declinado con los pies bien anclados y agarra la barra a la anchura de los hombros.', 'Baja la barra al pecho de forma controlada hasta tocar la línea inferior del pectoral.', 'Haz una pausa de un segundo sin rebotar y empuja hasta extender los brazos.', 'Evita abrir los codos en exceso o despegar la espalda del banco.']::text[], actualizado_en = now() WHERE id = 'a5a3ec66-454a-428d-8cba-7c96277b3d62';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '5011', descripcion = 'Incide en la porción superior del pectoral y el deltoides anterior, ganando fuerza y control con la pausa en el pecho.', instrucciones = ARRAY['Siéntate en el banco inclinado y agarra la barra algo más ancha que los hombros.', 'Baja la barra hasta la parte alta del pecho con los codos a unos 45 grados.', 'Detente un segundo en el pecho y empuja de forma explosiva hasta extender los brazos.', 'Evita arquear demasiado la espalda o rebotar la barra contra el pecho.']::text[], actualizado_en = now() WHERE id = '1a01dcbe-f702-4267-abb4-3ce1749c5c2f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '5013', descripcion = 'Desarrolla la fuerza del pectoral y los tríceps con una pausa que mejora el control y la técnica en el press.', instrucciones = ARRAY['Túmbate en el banco con los pies firmes en el suelo y agarra la barra a la anchura de los hombros.', 'Baja la barra al pecho con los codos ligeramente cerrados y las escápulas retraídas.', 'Haz una pausa de un segundo tocando el pecho sin rebotar.', 'Empuja la barra hasta extender los brazos y evita despegar los glúteos del banco.']::text[], actualizado_en = now() WHERE id = 'f65cf0d8-02e2-4735-861e-ea8b75464211';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = '5030', descripcion = 'Combina flexión y salto de piernas para trabajar pecho, tríceps y core con un extra de coordinación y cardio.', instrucciones = ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho hacia el suelo flexionando los codos.', 'Al subir, separa los pies de un salto y vuelve a juntarlos al bajar.', 'Evita hundir la cadera o adelantar la cabeza: mantén el tronco firme.']::text[], actualizado_en = now() WHERE id = 'caa469bc-2c8d-4c2b-973e-dd30ec187dd8';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '5031', descripcion = 'Refuerza el abdomen y los flexores de cadera con carga ligera, mejorando el control del tronco y la pelvis.', instrucciones = ARRAY['Túmbate boca arriba con el balón medicinal entre los pies y las piernas estiradas.', 'Sujeta el balón con los pies y elévalos hasta la vertical sin despegar la zona lumbar.', 'Baja las piernas de forma lenta y controlada sin tocar el suelo.', 'Evita usar impulso o arquear la espalda: aprieta el abdomen en todo el recorrido.']::text[], actualizado_en = now() WHERE id = 'a979de06-f4fe-4ce2-bddb-2984fb8f804a';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '5032', descripcion = 'Trabaja los oblicuos y el recto abdominal combinando elevación de piernas y rotación, mejorando la estabilidad del core.', instrucciones = ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas elevadas a 90 grados.', 'Eleva el tronco y lleva un codo hacia la rodilla contraria mientras estiras la otra pierna.', 'Alterna los lados de forma controlada sin tirar del cuello.', 'Evita arquear la zona lumbar: mantén la pelvis neutra durante todo el movimiento.']::text[], actualizado_en = now() WHERE id = 'a0264ccb-57e1-4365-98b7-f8ab1627be78';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '5045', descripcion = 'Fortalece el core, glúteos y extensores de la espalda con una plancha invertida que mejora la postura y la estabilidad.', instrucciones = ARRAY['Siéntate en el suelo con las piernas estiradas y apoya los antebrazos detrás de la cadera.', 'Eleva la pelvis hasta formar una línea recta desde la cabeza hasta los talones.', 'Aprieta glúteos y abdomen, y respira de forma pausada.', 'Evita dejar caer la cadera o encoger los hombros: mantén el pecho abierto.']::text[], actualizado_en = now() WHERE id = '272ae59b-f36e-474b-b992-a99a33140fdc';
UPDATE ejercicios SET categoria = 'calisthenics', codigo_externo = '5046', descripcion = 'Activa el abdomen y los oblicuos con un movimiento dinámico que mejora la coordinación y el control del tronco.', instrucciones = ARRAY['Siéntate en el suelo con las piernas elevadas y el tronco ligeramente inclinado atrás.', 'Mantén el equilibrio sobre los glúteos con la espalda recta.', 'Lleva las manos hacia los pies alternando toques de forma controlada.', 'Evita redondear la espalda o aguantar la respiración: espira en cada toque.']::text[], actualizado_en = now() WHERE id = 'dfc8ccea-9b04-4eeb-a5cf-76cf7a543d16';
