UPDATE ejercicios SET categoria = 'mobility', codigo_externo = '5060', descripcion = 'Refuerza los extensores del cuello y la musculatura cervical, ayudando a mejorar la postura y prevenir molestias.', instrucciones = ARRAY['Túmbate boca abajo con los brazos relajados y la frente mirando al suelo.', 'Eleva la cabeza y el cuello lentamente sin mover los hombros.', 'Aguanta un segundo arriba y baja de forma controlada.', 'Evita hacer movimientos bruscos o forzar el rango: mantén el gesto suave.']::text[], actualizado_en = now() WHERE id = '6eb3ff4c-4d23-4c2d-ae7e-e50cf1c6bda0';
