UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el core y los estabilizadores globales para mejorar el control postural en movimientos cotidianos.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Cruza los brazos sobre el pecho sin tirar del cuello.', 'Eleva ligeramente los omóplatos del suelo contrayendo el abdomen y exhala.', 'Baja despacio sin apoyar del todo y repite manteniendo la tensión.', 'Evita tirar del cuello o arquear la zona lumbar.']::text[], actualizado_en = now() WHERE id = 'ffa3f010-abda-4621-8798-acfe089a3fa5';
