UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el core y los estabilizadores contra la pared para ganar control y resistencia en isometría.', instrucciones = ARRAY['Apoya las manos en la pared a la altura de los hombros con los pies atrás.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Presiona la pared con pulsos cortos y controlados sin mover la cadera.', 'Respira de forma continua y evita aguantar la respiración.', 'No dejes caer la cadera ni bloquees los codos.']::text[], actualizado_en = now() WHERE id = '26e5bda9-c834-4b6c-a5ed-45de6fea70bb';
