UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el recto abdominal con piernas extendidas, mejorando la fuerza del core y el control del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las piernas rectas y las manos en las sienes.', 'Flexiona el tronco elevando los omóplatos del suelo sin tirar del cuello.', 'Baja controlando y exhala durante la subida.', 'Evita arquear la zona lumbar o usar impulso de brazos.']::text[], actualizado_en = now() WHERE id = 'c1e9332c-02c9-48ac-8e78-6f7473b4821d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Combina sentadilla y alcance lateral para activar cuádriceps, glúteos y core, mejorando equilibrio y coordinación.', instrucciones = ARRAY['De pie con los pies a la anchura de los hombros y el pecho erguido.', 'Baja en media sentadilla llevando la cadera atrás y las rodillas alineadas.', 'Al subir, extiende un brazo hacia el lateral y alterna cada repetición.', 'Evita inclinar el tronco o juntar las rodillas durante el descenso.']::text[], actualizado_en = now() WHERE id = 'ca1f21a0-15e0-46d2-9ffc-6a6e958e90d2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja recto abdominal y oblicuos con rotación, útil para fortalecer el core y mejorar la estabilidad del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos en las sienes.', 'Flexiona el tronco y gira el hombro hacia la rodilla contraria.', 'Vuelve al centro y alterna lados exhalando en cada giro.', 'Evita tirar del cuello o girar solo con los brazos sin mover el tronco.']::text[], actualizado_en = now() WHERE id = '1dca51fd-b4c1-49eb-a4b5-b2c59906db11';
