UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece pectoral, hombro anterior y tríceps con empuje horizontal, mejorando la fuerza del tren superior.', instrucciones = ARRAY['Túmbate boca arriba con rodillas flexionadas y botellas a la altura del pecho.', 'Empuja las botellas hacia arriba extendiendo los codos sin bloquear del todo.', 'Baja controlando hasta la altura del pecho y exhala al empujar.', 'Evita arquear la espalda baja o abrir los codos en exceso.']::text[], actualizado_en = now() WHERE id = '6a6ced5c-1122-4918-b63b-a9693b596668';
