UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece deltoides anterior y trapecio, mejorando la fuerza del hombro en elevaciones frontales controladas.', instrucciones = ARRAY['De pie con botellas delante de los muslos y palmas hacia el cuerpo.', 'Eleva los brazos al frente hasta la altura de los hombros.', 'Baja controlando y exhala al subir.', 'Evita balancear el tronco o subir por encima de los hombros.']::text[], actualizado_en = now() WHERE id = '8957e8b4-bac2-4d8a-bd9c-994f42724391';
