UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el pectoral y los hombros con un movimiento de empuje vertical que puedes hacer en casa sin material.', instrucciones = ARRAY['Colócate de pie con los pies a la anchura de los hombros y sujeta una botella en cada mano a la altura de los hombros.', 'Empuja las botellas hacia arriba hasta estirar los brazos sin bloquear del todo los codos.', 'Baja despacio controlando el movimiento hasta la altura inicial y exhala al subir.', 'Evita arquear la zona lumbar: mantén el abdomen firme y las costillas abajo durante todo el recorrido.']::text[], actualizado_en = now() WHERE id = 'f3ad9838-e07e-4326-9251-9c25d50bb3e2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Movimiento circular que activa los hombros y la parte alta de la espalda, útil como calentamiento o trabajo de fuerza.', instrucciones = ARRAY['De pie con los pies a la anchura de los hombros, sujeta el lastre con las dos manos delante del pecho.', 'Dibuja un círculo amplio llevando el peso cerca de la cabeza, pasando por un lado y volviendo por el otro.', 'Mantén el abdomen firme y los codos ligeramente flexionados mientras respiras de forma constante.', 'Evita encoger los hombros hacia las orejas y controla el ritmo sin usar impulso del tronco.']::text[], actualizado_en = now() WHERE id = 'b81c2396-9333-49df-8865-309a20c7f9df';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el core y los oblicuos en isometría, mejorando la estabilidad lateral del tronco y la postura.', instrucciones = ARRAY['Apóyate de lado sobre el antebrazo, con el codo bajo el hombro y las piernas estiradas o flexionadas.', 'Eleva la cadera hasta formar una línea recta desde la cabeza hasta los pies.', 'Lleva el brazo libre por encima de la cabeza como si hicieras un jalón y vuelve a bajarlo sin perder la alineación.', 'Evita que la cadera caiga o se gire: mantén el abdomen apretado y respira con normalidad.']::text[], actualizado_en = now() WHERE id = 'bf801cd7-39d2-4349-9067-d643caac9df8';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Mejora la movilidad de cadera y tobillo y prepara las piernas para sentadillas más profundas y seguras.', instrucciones = ARRAY['Colócate de pie con los pies algo más anchos que los hombros y los dedos ligeramente hacia fuera.', 'Baja en sentadilla hasta donde puedas sin que los talones se levanten.', 'Desde abajo, gira el tronco y lleva un brazo hacia el techo, mirando la mano, y vuelve al centro.', 'Alterna los lados sin subir del todo y evita redondear la espalda o forzar la rodilla hacia dentro.']::text[], actualizado_en = now() WHERE id = '10ec9802-1c74-4364-8cbe-5ac1727737a4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio de fuerza y control que implica al tronco y los hombros con un movimiento de rotación guiado.', instrucciones = ARRAY['De pie con los pies a la anchura de los hombros, sujeta una mancuerna con las dos manos delante del pecho.', 'Gira el tronco como si movieras un volante, llevando el peso hacia un lado y luego hacia el otro.', 'Mantén la cadera estable y acompaña el giro con la respiración, sin bloquear el aire.', 'Evita usar impulso de las piernas o girar solo los brazos: el movimiento nace del tronco.']::text[], actualizado_en = now() WHERE id = '594ed45e-ae2b-418e-bf18-8e9cee968db7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza la zona media con una flexión de tronco que suma carga y exige control del abdomen.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna con las dos manos, brazos estirados hacia el techo.', 'Eleva la parte alta de la espalda separando los omóplatos del suelo, sin tirar del cuello.', 'Baja despacio hasta rozar el suelo y repite manteniendo los brazos rectos y el abdomen apretado.', 'Evita impulsarte con las piernas o balancear el peso: el movimiento debe ser lento y controlado.']::text[], actualizado_en = now() WHERE id = 'b8210b46-44b0-4ae2-97f9-c7b60965f1f2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6147', descripcion = 'Aísla el bíceps y el antebrazo con un agarre neutro, ganando fuerza y volumen en el brazo.', instrucciones = ARRAY['De pie con los pies a la anchura de los hombros, sujeta una mancuerna en cada mano con las palmas mirándose.', 'Flexiona un codo llevando la mancuerna hacia el hombro sin mover el brazo de su sitio.', 'Baja despacio hasta estirar el codo y alterna con el otro brazo, exhalando al subir.', 'Evita balancear el tronco o adelantar el hombro: mantén los codos pegados al costado.']::text[], actualizado_en = now() WHERE id = '2f6afd92-cfe2-41ea-b31e-9fb112de0c95';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6149', descripcion = 'Variante de curl que trabaja el bíceps con el codo detrás del cuerpo, aumentando la tensión en el estiramiento.', instrucciones = ARRAY['Siéntate en un banco con la espalda recta y sujeta una mancuerna en cada mano con las palmas hacia arriba.', 'Lleva los codos ligeramente hacia atrás y pega los brazos al tronco.', 'Sube las mancuernas deslizándolas cerca del cuerpo hasta la altura del pecho y baja controlando.', 'Evita echar el tronco hacia atrás o encoger los hombros para completar la repetición.']::text[], actualizado_en = now() WHERE id = 'bb9cc94e-5ee9-49ba-a244-cbdc799a87d0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6162', descripcion = 'Abre el pecho desde un banco inclinado con las mancuernas bajas, buscando estiramiento y control del pectoral.', instrucciones = ARRAY['Túmbate en un banco inclinado con una mancuerna en cada mano y los brazos abiertos a la altura del pecho.', 'Con los codos ligeramente flexionados, junta las mancuernas por delante del pecho sin bloquear los codos.', 'Abre despacio hasta notar estiramiento en el pecho y vuelve a subir exhalando.', 'Evita bajar demasiado o rebotar: mantén los omóplatos juntos y los pies firmes en el suelo.']::text[], actualizado_en = now() WHERE id = '8502d7e4-ec8c-4503-9329-dbdf117f3a19';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6406', descripcion = 'Curl en banco predicador que aísla el bíceps y limita el impulso del cuerpo para ganar fuerza.', instrucciones = ARRAY['Siéntate en el banco predicador con los brazos apoyados y sujeta la barra EZ con las palmas hacia arriba.', 'Flexiona los codos subiendo la barra hasta cerca del hombro sin despegar los brazos del apoyo.', 'Baja despacio hasta estirar casi del todo el codo y exhala al subir.', 'Evita extender el codo por completo de golpe o ayudarte con el tronco: controla siempre la bajada.']::text[], actualizado_en = now() WHERE id = '10f58436-8168-4adf-904d-7c0956d4f287';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el abdomen y los oblicuos con un movimiento corto y controlado, ideal para el core en casa.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Eleva la parte alta de la espalda y lleva una mano hacia el talón del mismo lado.', 'Vuelve al centro y alterna hacia el otro lado manteniendo el abdomen apretado.', 'Evita tirar del cuello con las manos o despegar la zona lumbar del suelo.']::text[], actualizado_en = now() WHERE id = '5b304d0a-e19d-4cd7-93f7-d5c813709413';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio básico de empuje para pecho y tríceps, con apoyo de pies que aporta estabilidad y seguridad.', instrucciones = ARRAY['Túmbate en el banco con los pies apoyados en el suelo y sujeta la barra a la anchura de los hombros.', 'Baja la barra de forma controlada hasta rozar el pecho con los codos algo cerrados.', 'Empuja hacia arriba hasta estirar los brazos y exhala durante el ascenso.', 'Evita rebotar en el pecho o levantar la cadera: mantén los omóplatos juntos y los pies firmes.']::text[], actualizado_en = now() WHERE id = '02dadca0-72e7-473e-9229-2f872f5a2a6c';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja los oblicuos con flexión lateral desde la polea, buscando control y rango sin tirones.', instrucciones = ARRAY['Colócate de rodillas junto a la polea y sujeta el mango con una mano por encima de la cabeza.', 'Flexiona el tronco hacia el lado de la polea llevando el codo hacia la cadera.', 'Vuelve despacio a la posición inicial resistiendo la tensión y exhala al bajar.', 'Evita girar el tronco o tirar con el brazo: el movimiento es lateral y nace del abdomen.']::text[], actualizado_en = now() WHERE id = '691cd1c1-a749-410a-8919-6d454060e253';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece la pantorrilla y el tobillo con una elevación controlada que mejora el equilibrio y la estabilidad.', instrucciones = ARRAY['De pie con los pies a la anchura de la cadera, sujeta la kettlebell con las dos manos delante del cuerpo.', 'Eleva los talones hasta ponerte de puntillas y mantén un instante arriba.', 'Baja despacio hasta apoyar los talones sin dejarte caer y repite respirando con normalidad.', 'Evita balancearte o apoyarte en la pared: mantén el abdomen firme y el peso repartido.']::text[], actualizado_en = now() WHERE id = '181ce771-5fbb-4cc8-a1ad-1fe7e7cf5b21';
