UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el recto abdominal y los oblicuos para ganar control del core y proteger la zona lumbar.', instrucciones = ARRAY['Colócate de pie de espaldas a la polea con los pies a la anchura de las caderas.', 'Sujeta la cuerda a la altura del pecho y baja el torso flexionando el tronco, sin tirar de los brazos.', 'Exhala al bajar y controla la subida en dos o tres segundos.', 'Evita redondear la espalda o tirar con los brazos en lugar del abdomen.']::text[], actualizado_en = now() WHERE id = '79cf12a1-c624-416e-befb-b7e8b5acf233';
