UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja recto abdominal y oblicuos con rotación para ganar fuerza en el core.', instrucciones = ARRAY['Túmbate boca arriba con las piernas flexionadas y sujeta la mancuerna con ambas manos.', 'Eleva el tronco y gira hacia un lado llevando la mancuerna hacia la rodilla contraria.', 'Baja despacio y repite hacia el otro lado.', 'Evita tirar del cuello o usar impulso para subir.']::text[], actualizado_en = now() WHERE id = '68e350e4-491f-46c9-8717-f3d9d8a7605c';
