UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6801', descripcion = 'Fortalece hombros y core con un press sentado que exige estabilidad y control.', instrucciones = ARRAY['Siéntate en el suelo con las piernas estiradas y las mancuernas a la altura de los hombros.', 'Empuja las mancuernas hacia arriba mientras recoges las piernas.', 'Baja las mancuernas y estira las piernas de forma controlada.', 'Evita arquear la zona lumbar o usar impulso para empujar.']::text[], actualizado_en = now() WHERE id = '4b139e68-e529-45b7-912a-486828638ba1';
