UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6805', descripcion = 'Trabaja el recto abdominal y los oblicuos, mejorando la estabilidad del core y la coordinación cruzada.', instrucciones = ARRAY['Túmbate boca arriba con las piernas estiradas y sujeta una mancuerna con ambas manos por encima del pecho.', 'Eleva el tronco y una pierna a la vez, llevando la mancuerna hacia la punta del pie contrario.', 'Baja con control y repite hacia el otro lado, manteniendo el abdomen apretado.', 'Exhala al subir e inhala al bajar, sin tirar del cuello ni arquear la zona lumbar.']::text[], actualizado_en = now() WHERE id = 'b51b5c64-0913-4616-b8a9-24cd64d252bf';
