UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6890', descripcion = 'Fortalece el pectoral y los hombros desde una posición sentada que exige más control del core.', instrucciones = ARRAY['Siéntate en el suelo con las piernas estiradas y una mancuerna en cada mano a la altura del pecho.', 'Empuja las mancuernas hacia arriba hasta extender los brazos sin bloquear los codos.', 'Baja con control hasta la altura del pecho manteniendo el tronco firme.', 'Exhala al empujar y evita arquear la espalda para ganar impulso.']::text[], actualizado_en = now() WHERE id = '6fcd88c8-b636-4fff-abde-0aa76cd3fb86';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '6891', descripcion = 'Trabaja el pectoral y los hombros de forma alterna, mejorando la estabilidad y la coordinación.', instrucciones = ARRAY['Siéntate en el suelo con las piernas estiradas y una mancuerna en cada mano a la altura del pecho.', 'Empuja una mancuerna hacia arriba mientras la otra permanece abajo.', 'Baja con control y alterna el brazo en cada repetición.', 'Exhala al empujar y mantén el tronco firme sin balancearte.']::text[], actualizado_en = now() WHERE id = '052df851-cfed-425a-a638-3efea36811ca';
UPDATE ejercicios SET categoria = 'yoga', codigo_externo = NULL, descripcion = 'Moviliza la columna y estira el pecho y el abdomen, mejorando la flexibilidad y la respiración.', instrucciones = ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Inspira y arquea la espalda hacia arriba, elevando el pecho y mirando al frente.', 'Exhala al volver a la posición neutra y repite con movimiento fluido.', 'Evita forzar el cuello y mantén el abdomen activo.']::text[], actualizado_en = now() WHERE id = '1fbd465d-1097-454a-aef3-b6bc848837e4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el pectoral, los hombros y los tríceps con un rango de movimiento profundo en barras paralelas.', instrucciones = ARRAY['Sujeta las barras paralelas y eleva el cuerpo con los brazos extendidos.', 'Baja con control hasta que los hombros queden por debajo de los codos.', 'Empuja hacia arriba hasta extender los brazos sin bloquear los codos.', 'Exhala al subir y evita balancear el cuerpo.']::text[], actualizado_en = now() WHERE id = '481a5511-ea91-4eed-9bfd-05a139e03162';
