UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece los flexores de los dedos y la mano, mejorando el agarre y la estabilidad de la muñeca.', instrucciones = ARRAY['De pie, sujeta una mancuerna con el brazo extendido y la palma hacia abajo.', 'Gira la muñeca lentamente hacia dentro y hacia fuera con control.', 'Mantén el codo pegado al cuerpo y evita mover el hombro.', 'Exhala al girar y repite sin balancear el brazo.']::text[], actualizado_en = now() WHERE id = 'd0fe0dfa-f4b3-4b8f-8465-7a7b733750f5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el tríceps en la máquina, mejorando la fuerza y la definición del brazo.', instrucciones = ARRAY['Siéntate en la máquina con la espalda apoyada y los codos alineados con el eje.', 'Extiende los brazos hasta estirarlos sin bloquear los codos.', 'Baja con control hasta la posición inicial manteniendo el tronco firme.', 'Exhala al extender y evita usar impulso del cuerpo.']::text[], actualizado_en = now() WHERE id = 'b3122603-cd72-42da-80de-273211e64728';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el pectoral y los hombros con una variante a una pierna que añade demanda de estabilidad.', instrucciones = ARRAY['Colócate en la máquina con una pierna apoyada y la otra elevada.', 'Empuja la plataforma extendiendo la pierna sin bloquear la rodilla.', 'Baja con control y añade una elevación de gemelos al final del recorrido.', 'Exhala al empujar y evita que la rodilla se desvíe hacia dentro.']::text[], actualizado_en = now() WHERE id = '23f32e42-254b-4ac4-bb6b-9003cedbe18a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el pectoral y los hombros con una variante de prensa que exige control y estabilidad.', instrucciones = ARRAY['Siéntate en la máquina con la espalda apoyada y los pies en la plataforma.', 'Empuja la plataforma extendiendo las piernas sin bloquear las rodillas.', 'Baja con control hasta la posición inicial manteniendo el abdomen apretado.', 'Exhala al empujar y evita que las rodillas se junten.']::text[], actualizado_en = now() WHERE id = '5d4abcf5-8e7c-476f-8935-f314e489e7ed';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el pectoral y los hombros a una pierna, añadiendo demanda de estabilidad y control.', instrucciones = ARRAY['Siéntate en la máquina con una pierna apoyada y la otra elevada.', 'Empuja la plataforma extendiendo la pierna sin bloquear la rodilla.', 'Baja con control hasta la posición inicial manteniendo el tronco firme.', 'Exhala al empujar y evita que la rodilla se desvíe hacia dentro.']::text[], actualizado_en = now() WHERE id = '0b4add5d-b2ba-4a0b-9acc-09d2ab0625e2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el deltoides medio y los estabilizadores del hombro, mejorando el control escapular y la fuerza en movimientos por encima de la cabeza.', instrucciones = ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo. Mantén la zona lumbar pegada al suelo en todo momento. Eleva las piernas rectas hasta unos 45 grados sin arquear la espalda. Baja despacio controlando el movimiento y evitando que los talones toquen el suelo. No bloquees la respiración: exhala al subir y evita tirar del cuello.']::text[], actualizado_en = now() WHERE id = '075a200d-9d08-4bd4-b1d3-4403fd2728d9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el core y los oblicuos manteniendo la estabilidad del tronco mientras las piernas se abren y cierran.', instrucciones = ARRAY['Colócate en plancha sobre antebrazos con codos bajo los hombros y cuerpo alineado. Aprieta el abdomen y los glúteos para mantener la cadera neutra. Abre y cierra las piernas de forma controlada sin balancear la cadera. Respira de forma continua y evita que la zona lumbar se hunda. Si pierdes la alineación, reduce la amplitud del movimiento.']::text[], actualizado_en = now() WHERE id = 'b5af6fa2-ee19-4823-910a-398b1a21d8b5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece los rotadores internos del hombro y mejora la estabilidad de la articulación, útil para prevenir lesiones.', instrucciones = ARRAY['Túmbate de lado con el codo pegado al costado y flexionado a 90 grados. Gira el antebrazo hacia el abdomen manteniendo el codo fijo contra las costillas. Controla el retorno a la posición inicial sin dejar caer el brazo. Evita mover el hombro o el tronco para compensar. Respira de forma pausada durante todo el recorrido.']::text[], actualizado_en = now() WHERE id = '83d14c8d-d4e6-4307-84e9-16c258bc06d9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '7231', descripcion = 'Trabaja el deltoides medio y los estabilizadores del hombro con un gesto en Y que mejora la fuerza escapular.', instrucciones = ARRAY['Colócate inclinado con el pecho apoyado y una mancuerna en la mano libre. Extiende el brazo en diagonal formando una Y con el cuerpo. Eleva la mancuerna sin encoger el hombro ni usar impulso. Baja despacio controlando el peso en todo el recorrido. Evita rotar el tronco para no perder la postura.']::text[], actualizado_en = now() WHERE id = '3345fd53-1c93-468a-b3f9-741b26a4d8c9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Desarrolla la fuerza de empuje del pectoral y los hombros, mejorando la estabilidad del tren superior en press vertical.', instrucciones = ARRAY['Sujeta la barra hexagonal a la altura de los hombros con agarre firme. Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos. Mantén el abdomen apretado y evita arquear la zona lumbar. Baja la barra de forma controlada hasta la altura inicial. No uses impulso de piernas ni rebotes para subir.']::text[], actualizado_en = now() WHERE id = '535e1227-ed8e-4523-a511-abf2f46cc36a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el cuádriceps en máquina, fortaleciendo la extensión de rodilla con una ligera rotación interna de las puntas.', instrucciones = ARRAY['Siéntate en la máquina con la espalda apoyada y los tobillos bajo el rodillo. Orienta las puntas de los pies ligeramente hacia dentro sin forzar. Extiende las rodillas de forma controlada hasta casi la totalidad del recorrido. Baja despacio sin dejar caer el peso de golpe. Evita despegar la espalda o la cadera del asiento.']::text[], actualizado_en = now() WHERE id = '0e271de3-49da-4da9-84ca-15300901e735';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el core en isométrico apoyado en la pared, ideal para aprender a mantener la alineación sin carga lumbar.', instrucciones = ARRAY['Apoya los antebrazos en la pared con los codos a la altura de los hombros. Da un paso atrás y alinea el cuerpo en diagonal recta. Aprieta el abdomen y los glúteos para mantener la posición. Respira con normalidad sin hundir la zona lumbar. Si aparece tensión en el cuello, relaja los hombros y aleja las orejas.']::text[], actualizado_en = now() WHERE id = 'f9f345dc-3413-4fcf-a04e-92ae009f6a88';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el recto abdominal y los oblicuos con un crunch guiado por la pared que mejora el control del tronco.', instrucciones = ARRAY['Colócate de espaldas a la pared con la zona lumbar apoyada. Flexiona las rodillas y apoya los pies en el suelo. Eleva el tronco curvando la columna sin tirar del cuello. Exhala al subir y baja de forma controlada. Evita despegar la lumbar de la pared durante el movimiento.']::text[], actualizado_en = now() WHERE id = 'e51bba6f-8ccd-4530-94d4-80361026530f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el pectoral y los tríceps en fondos sobre paralelas, mejorando la fuerza de empuje y la estabilidad del hombro.', instrucciones = ARRAY['Sujétate en las barras paralelas con los brazos extendidos y el cuerpo firme. Baja flexionando los codos hasta que los hombros queden a la altura de los codos. Mantén el pecho ligeramente adelantado y el abdomen apretado. Empuja hacia arriba sin balancear las piernas. Evita bajar más de lo que controlas para no forzar el hombro.']::text[], actualizado_en = now() WHERE id = '161cbab7-65ef-4ec1-9d85-d64f7eb47aca';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el pectoral con aperturas en polea, mejorando la fuerza y el control en el rango final del empuje.', instrucciones = ARRAY['Colócate de pie entre las poleas con un mango en cada mano y agarre neutro. Lleva las manos al frente con los codos ligeramente flexionados. Junta las manos sin bloquear los codos y aprieta el pecho. Vuelve despacio controlando la apertura. Evita encoger los hombros o usar impulso del tronco.']::text[], actualizado_en = now() WHERE id = '9dea39e6-9072-48cb-bf2f-2c3f97d9dd46';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el recto abdominal y los oblicuos con un crunch completo que mejora la flexión controlada del tronco.', instrucciones = ARRAY['Túmbate con las piernas apoyadas en el banco y los brazos extendidos. Eleva el tronco curvando la columna de forma progresiva. Mantén los brazos estirados y evita tirar del cuello. Exhala al subir y baja controlando el movimiento. No uses impulso de brazos ni de piernas para subir.']::text[], actualizado_en = now() WHERE id = 'd34a9a55-99d9-4190-a85f-68208a448e1f';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira el pectoral y la parte anterior del hombro, mejorando la movilidad y liberando tensión tras el entrenamiento.', instrucciones = ARRAY['Coloca el antebrazo en el marco de la puerta con el codo a la altura del hombro. Da un paso adelante hasta notar estiramiento en el pecho. Mantén el tronco recto y el hombro relajado. Respira despacio y sostén el estiramiento sin rebotar. Evita forzar si aparece dolor en el hombro.']::text[], actualizado_en = now() WHERE id = 'e44d9f5f-34d8-456e-8794-bb26e4faec51';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '7578', descripcion = 'Fortalece el cuádriceps y los glúteos con una sentadilla frontal en polea que mejora la estabilidad del tronco.', instrucciones = ARRAY['Sujeta la barra en V con las manos a la altura del pecho y los codos altos. Separa los pies a la anchura de los hombros y baja flexionando las rodillas. Mantén el pecho erguido y la espalda neutra durante el descenso. Empuja con los talones para subir controlando el movimiento. Evita que las rodillas se metan hacia dentro.']::text[], actualizado_en = now() WHERE id = '19b384ca-4984-4804-8d5f-b1c578f7a3c3';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja los oblicuos y el recto abdominal con un giro y elevación que mejora la rotación controlada del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados. Eleva el tronco girando ligeramente hacia un lado. Mantén el movimiento controlado y sin tirones del cuello. Baja despacio y alterna el giro en cada repetición. Exhala al subir y evita usar impulso de brazos.']::text[], actualizado_en = now() WHERE id = 'fc469226-82fd-4273-a414-3e66534f79a2';
UPDATE ejercicios SET categoria = 'isometric', codigo_externo = '7588', descripcion = 'Mantiene activo el deltoides anterior en isométrico, mejorando la resistencia y el control del hombro.', instrucciones = ARRAY['Eleva los brazos al frente hasta la altura de los hombros con un peso ligero. Mantén la posición con los codos ligeramente flexionados. Aprieta el abdomen y evita arquear la espalda. Respira con normalidad durante toda la isometría. Baja los brazos de forma controlada al terminar el tiempo.']::text[], actualizado_en = now() WHERE id = '768b79fe-a7f6-4c4b-bf88-805eab96f4be';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza la parte posterior del hombro y la postura, equilibrando el empuje y protegiendo el manguito rotador.', instrucciones = ARRAY['Túmbate boca arriba en el suelo con los pies apoyados y la polea a la altura de la cara.', 'Agarra la cuerda con las palmas enfrentadas y los brazos estirados hacia el techo.', 'Tira de la cuerda hacia la frente separando las manos y llevando los codos hacia fuera.', 'Aprieta los omóplatos al final y vuelve despacio controlando el retorno.', 'Evita encoger los hombros o arquear la zona lumbar durante el movimiento.']::text[], actualizado_en = now() WHERE id = '1f18acfc-25e2-4804-99d7-0618846c1232';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '7620', descripcion = 'Trabaja el pecho con resistencia creciente en la fase final, ganando fuerza explosiva y estabilidad en el press.', instrucciones = ARRAY['Coloca las bandas en los extremos de la barra y ancladas a la base del banco.', 'Túmbate con los pies firmes, escápulas retraídas y agarre algo más ancho que los hombros.', 'Baja la barra al pecho controlando la tensión de las bandas.', 'Empuja hacia arriba hasta estirar los codos sin bloquear bruscamente.', 'Evita rebotar en el pecho y mantén las muñecas alineadas con los antebrazos.']::text[], actualizado_en = now() WHERE id = '258e7b13-d649-41af-893f-d84500f29fd0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps en estiramiento, favoreciendo el rango completo y el control en la fase excéntrica.', instrucciones = ARRAY['Inclina el torso hacia delante con la espalda recta y las rodillas ligeramente flexionadas.', 'Deja colgar los brazos con las mancuernas y las palmas hacia delante.', 'Flexiona los codos llevando las mancuernas hacia el hombro sin mover el tronco.', 'Baja despacio hasta estirar del todo el bíceps y repite.', 'Evita balancear el cuerpo o encoger los hombros para subir el peso.']::text[], actualizado_en = now() WHERE id = '4e766619-43b5-4e61-bf3e-f73a490cc2fe';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = '7743', descripcion = 'Fortalece el deltoides posterior y mejora la estabilidad del hombro trabajando desde una base más estable.', instrucciones = ARRAY['Colócate de rodillas con una pierna adelantada frente a la polea alta.', 'Agarra la cuerda con las palmas enfrentadas y los brazos estirados.', 'Tira hacia la cara separando las manos y llevando los codos altos y abiertos.', 'Junta los omóplatos al final y regresa controlando la tensión.', 'Mantén el tronco erguido y evita tirar con la espalda baja.']::text[], actualizado_en = now() WHERE id = '39bc89ac-794b-4397-95c7-694c33f542d0';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza los isquiotibiales con carga excéntrica, mejorando la prevención de lesiones y la fuerza del tren inferior.', instrucciones = ARRAY['Arrodíllate con el torso erguido y pide a alguien que te sujete los tobillos.', 'Mantén caderas, tronco y rodillas alineados mientras bajas el cuerpo hacia delante.', 'Frena la caída con los isquiotibiales todo lo que puedas antes de apoyar las manos.', 'Empuja con las manos para volver a la posición inicial ayudándote de las piernas.', 'Evita arquear la espalda o doblar la cadera durante el descenso.']::text[], actualizado_en = now() WHERE id = 'dc6f3f89-34e0-4e8e-8944-becb764a8c23';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el deltoides medio y los estabilizadores de la escápula, mejorando la postura y la salud del hombro.', instrucciones = ARRAY['Túmbate boca abajo con una mancuerna ligera en cada mano y los brazos en forma de W.', 'Mantén la frente apoyada y el cuello relajado.', 'Eleva los codos y las manos del suelo juntando los omóplatos.', 'Aguanta un segundo arriba y baja despacio sin perder la posición.', 'Evita encoger el cuello o usar demasiado peso que rompa la forma de W.']::text[], actualizado_en = now() WHERE id = 'decdaec7-00ae-4dbf-bb8f-9aa3eb6b8698';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Enfoca el pectoral interno y la estabilidad del hombro manteniendo las mancuernas juntas durante el recorrido.', instrucciones = ARRAY['Túmbate en el banco con una mancuerna en cada mano y júntalas sobre el pecho.', 'Baja las mancuernas hacia el pecho manteniéndolas pegadas entre sí.', 'Empuja hacia arriba sin separarlas y estira los codos al final.', 'Controla la bajada y respira al empujar.', 'Evita abrir los codos en exceso o perder el contacto entre las mancuernas.']::text[], actualizado_en = now() WHERE id = '9992f954-b135-4515-8edd-d8fdb5082155';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece braquial y antebrazo con agarre neutro, mejorando el grosor del brazo y la fuerza de prensión.', instrucciones = ARRAY['De pie con las mancuernas a los lados y las palmas enfrentadas.', 'Flexiona los codos llevando las mancuernas hacia los hombros sin girar las muñecas.', 'Mantén los codos pegados al torso durante todo el recorrido.', 'Baja despacio hasta estirar los brazos y repite.', 'Evita balancear el tronco o adelantar los codos para subir el peso.']::text[], actualizado_en = now() WHERE id = 'bd87a19a-63ee-447f-9894-7c8b4837c0ef';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el bíceps y los extensores del antebrazo con agarre prono, reforzando la muñeca y el codo.', instrucciones = ARRAY['De pie con las mancuernas a los lados y las palmas hacia abajo.', 'Flexiona los codos llevando las mancuernas hacia los hombros sin girar las muñecas.', 'Mantén las muñecas firmes y los codos junto al torso.', 'Baja controlando el movimiento hasta estirar los brazos.', 'Evita usar impulso del cuerpo o doblar las muñecas hacia arriba.']::text[], actualizado_en = now() WHERE id = '459c76a1-da10-488f-b2e5-605d434b8b6b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio avanzado de calistenia que exige gran fuerza de core y hombros para mantener el cuerpo horizontal.', instrucciones = ARRAY['Cuélgate de la barra con un solo brazo y el cuerpo extendido.', 'Activa el core y eleva las piernas hasta quedar horizontal boca abajo.', 'Mantén la posición con el cuerpo recto y la mirada al frente.', 'Respira de forma controlada y baja con seguridad al notar fatiga.', 'Evita arquear la espalda o perder la alineación del cuerpo.']::text[], actualizado_en = now() WHERE id = 'fdc75e51-562c-4b53-ab73-470402b43857';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps con tensión constante de la polea, favoreciendo el control y la congestión muscular.', instrucciones = ARRAY['Colócate frente a la polea baja con la barra recta agarrada en supinación.', 'Mantén los codos pegados al torso y la espalda recta.', 'Flexiona los codos llevando la barra hacia el pecho sin mover los hombros.', 'Baja despacio hasta estirar los brazos y repite.', 'Evita balancear el tronco o separar los codos del cuerpo.']::text[], actualizado_en = now() WHERE id = '082985e8-3915-4574-984d-c82a21319a6e';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el braquiorradial y los extensores de la muñeca con tensión continua, mejorando el agarre y el antebrazo.', instrucciones = ARRAY['Sitúate frente a la polea baja con la barra agarrada en pronación.', 'Mantén los codos junto al torso y las muñecas firmes.', 'Flexiona los codos llevando la barra hacia el pecho sin girar las manos.', 'Baja controlando la tensión hasta estirar los brazos.', 'Evita doblar las muñecas o usar impulso del cuerpo.']::text[], actualizado_en = now() WHERE id = '7d0643be-34e6-4bcd-b418-14d326f80071';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja braquial y antebrazo con agarre neutro y tensión de polea, mejorando el grosor del brazo.', instrucciones = ARRAY['Colócate frente a la polea baja con la cuerda agarrada con las palmas enfrentadas.', 'Mantén los codos pegados al torso y la espalda recta.', 'Flexiona los codos llevando la cuerda hacia los hombros sin girar las muñecas.', 'Baja despacio hasta estirar los brazos y repite.', 'Evita balancear el tronco o separar los codos del cuerpo.']::text[], actualizado_en = now() WHERE id = 'cbdbab59-50ed-478a-97d2-1b0fa7c83569';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps con una barra que reduce la tensión en las muñecas, permitiendo un agarre más cómodo.', instrucciones = ARRAY['De pie con la barra EZ agarrada en supinación a la anchura de los hombros.', 'Mantén los codos pegados al torso y la espalda recta.', 'Flexiona los codos llevando la barra hacia el pecho sin mover los hombros.', 'Baja despacio hasta estirar los brazos y repite.', 'Evita balancear el tronco o adelantar los codos para subir el peso.']::text[], actualizado_en = now() WHERE id = 'd874ea26-ffca-4659-a2d3-fab81f6951f1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el braquiorradial y los extensores del antebrazo con agarre prono, mejorando el agarre y la muñeca.', instrucciones = ARRAY['De pie con la barra EZ agarrada en pronación a la anchura de los hombros.', 'Mantén los codos junto al torso y las muñecas firmes.', 'Flexiona los codos llevando la barra hacia el pecho sin girar las manos.', 'Baja controlando el movimiento hasta estirar los brazos.', 'Evita doblar las muñecas o usar impulso del cuerpo.']::text[], actualizado_en = now() WHERE id = 'aae11dce-0046-4023-9f88-2ef8120cea67';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece antebrazo y braquial con agarre prono, útil para mejorar el agarre y la estabilidad de la muñeca.', instrucciones = ARRAY['Coloca el banco a la altura de la cadera y apoya los antebrazos sobre él con las palmas hacia abajo.', 'Agarra la barra recta con las manos a la anchura de los hombros y los codos ligeramente flexionados.', 'Sube la barra flexionando los codos sin mover los antebrazos del banco y baja controlando el movimiento.', 'Evita balancear el tronco o extender las muñecas para no perder tensión en el antebrazo.']::text[], actualizado_en = now() WHERE id = 'df2b1025-decf-4783-8be4-a6aa06fccbf2';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla el bíceps con el brazo apoyado en el banco predicador, ideal para ganar fuerza y control en la flexión.', instrucciones = ARRAY['Siéntate en el banco predicador y apoya la parte posterior de los brazos sobre el soporte.', 'Agarra la barra recta con las palmas hacia arriba y los codos alineados con los hombros.', 'Flexiona los codos para subir la barra hasta cerca del hombro y baja despacio hasta extender casi por completo.', 'No despegues los brazos del soporte ni uses impulso del tronco para subir el peso.']::text[], actualizado_en = now() WHERE id = '81dfc9eb-254f-4803-aea3-f4eb70455d9f';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el braquiorradial y el antebrazo con agarre prono, mejorando el agarre y la fuerza del codo.', instrucciones = ARRAY['Ponte de pie con los pies a la anchura de las caderas y sujeta la barra con las palmas hacia abajo.', 'Mantén los codos pegados al torso y los hombros hacia atrás durante todo el recorrido.', 'Sube la barra flexionando los codos sin mover los hombros y baja controlando el descenso.', 'Evita balancear el cuerpo o encoger los hombros para no restar tensión al antebrazo.']::text[], actualizado_en = now() WHERE id = '6ea86f7f-04bf-4f55-943e-1d44651dbbc5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja el tríceps en estiramiento con polea, útil para ganar fuerza y volumen en la parte posterior del brazo.', instrucciones = ARRAY['Colócate de espaldas a la polea baja y sujeta la cuerda con ambas manos por detrás de la cabeza.', 'Da un paso al frente con los codos apuntando hacia arriba y el tronco ligeramente inclinado.', 'Extiende los codos para llevar la cuerda hacia delante y arriba, y vuelve despacio a la posición inicial.', 'Mantén los codos cerca de la cabeza y evita arquear la espalda o mover los hombros.']::text[], actualizado_en = now() WHERE id = 'e87635c5-4065-49ce-b5ff-c093768ed589';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Activa el glúteo mayor con empuje de cadera, mejorando la potencia y la estabilidad de la pelvis.', instrucciones = ARRAY['Apoya la espalda alta en el banco y coloca la barra con la almohadilla sobre la cadera.', 'Agarra la barra con las manos y apoya los pies a la anchura de los hombros con las rodillas flexionadas.', 'Empuja con los talones para elevar la cadera hasta alinear tronco y muslos, y baja controlando.', 'Aprieta los glúteos arriba y evita arquear la zona lumbar o empujar con las puntas de los pies.']::text[], actualizado_en = now() WHERE id = '696cabda-d659-46bf-8fcd-2482408be5b1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Aísla bíceps y braquial con barra EZ en banco predicador, reduciendo tensión en muñecas.', instrucciones = ARRAY['Siéntate en el banco predicador y apoya los brazos sobre el soporte con las palmas hacia arriba.', 'Agarra la barra EZ por las curvas y mantén los codos alineados con los hombros.', 'Flexiona los codos para subir la barra y baja despacio hasta casi extender los brazos.', 'No separes los brazos del soporte ni uses impulso del tronco para completar la repetición.']::text[], actualizado_en = now() WHERE id = '4deba64d-96b0-4659-aaf0-303b8c610529';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece cuádriceps, glúteo y aductores con una sentadilla amplia, mejorando la fuerza de piernas.', instrucciones = ARRAY['Ponte de pie con los pies más anchos que las caderas y las puntas ligeramente hacia fuera.', 'Sujeta la mancuerna con ambas manos delante del pecho o entre las piernas.', 'Baja flexionando caderas y rodillas con el pecho alto y sube empujando con los talones.', 'Mantén las rodillas alineadas con los pies y evita que se metan hacia dentro.']::text[], actualizado_en = now() WHERE id = '00f5a2d2-7b1f-42f7-89a7-231adec4b6c4';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Enfoca el pectoral inferior y tríceps con press declinado, útil para completar el desarrollo del pecho.', instrucciones = ARRAY['Túmbate en el banco declinado con los pies sujetos y la espalda apoyada.', 'Agarra la barra con las manos algo más anchas que los hombros y baja hasta el pecho bajo.', 'Empuja la barra hacia arriba extendiendo los codos y vuelve a bajar controlando.', 'No rebotes la barra en el pecho ni levantes la cadera del banco.']::text[], actualizado_en = now() WHERE id = '78a17f84-9e20-4339-b7fb-39c71cdfc382';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira dorsal y hombro anterior contra la pared, aliviando tensión tras entrenar espalda o pecho.', instrucciones = ARRAY['Colócate de frente a la pared con los pies a un paso de distancia.', 'Apoya las manos en la pared a la altura de los hombros con los dedos hacia arriba.', 'Inclina el tronco hacia delante llevando el pecho hacia el suelo y mantén la espalda recta.', 'Respira despacio y evita forzar el hombro o encoger el cuello durante el estiramiento.']::text[], actualizado_en = now() WHERE id = 'c3668831-ed4b-4b3a-9a77-eed38af2ad14';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa romboides y trapecio medio para mejorar la postura y estabilizar la escápula.', instrucciones = ARRAY['Apoya la espalda y la cabeza contra la pared con los pies separados a la anchura de las caderas.', 'Lleva los codos a 90 grados y las manos hacia delante, pegando los omóplatos a la pared.', 'Junta los omóplatos como si sujetaras un lápiz entre ellos y mantén la tensión unos segundos.', 'No arquees la zona lumbar ni subas los hombros hacia las orejas.']::text[], actualizado_en = now() WHERE id = '62553325-ab33-439d-af2e-e8294dceb72a';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Mejora la movilidad torácica y la extensión de la espalda alta, útil para contrarrestar posturas encorvadas.', instrucciones = ARRAY['Colócate de espaldas a la pared con los talones, glúteos y espalda alta en contacto.', 'Pon las manos en la nuca con los codos abiertos y la barbilla ligeramente recogida.', 'Extiende la espalda alta llevando los codos hacia la pared sin arquear la zona lumbar.', 'Respira al extender y evita sacar las costillas o adelantar la cabeza.']::text[], actualizado_en = now() WHERE id = 'e3a03875-1dae-45c6-9c58-2a1d7965ea83';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece el bíceps con mancuernas de pie, mejorando la fuerza y el control del brazo.', instrucciones = ARRAY['Ponte de pie con los pies a la anchura de las caderas y una mancuerna en cada mano.', 'Mantén los codos pegados al torso y las palmas hacia delante.', 'Sube las mancuernas flexionando los codos y baja despacio hasta extender los brazos.', 'Evita balancear el tronco o mover los hombros para subir el peso.']::text[], actualizado_en = now() WHERE id = '9af44e3e-a44d-408f-91f9-836403668e77';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja dorsal y romboides con remo en polea, mejorando la fuerza de espalda y la postura.', instrucciones = ARRAY['Siéntate en la polea baja con los pies apoyados y las rodillas ligeramente flexionadas.', 'Agarra el maneral estrecho con los brazos extendidos y la espalda recta.', 'Tira del maneral hacia el abdomen juntando los omóplatos y vuelve despacio a la posición inicial.', 'Evita encorvar la espalda o tirar con los brazos sin activar la espalda.']::text[], actualizado_en = now() WHERE id = '9d363c80-69f0-4864-81d8-7f9eef455f14';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el abdomen y el iliopsoas elevando las piernas, mejorando el control del core.', instrucciones = ARRAY['Túmbate boca arriba en la colchoneta con las piernas extendidas y los brazos a los lados.', 'Pega la zona lumbar al suelo y eleva las piernas hasta unos 90 grados.', 'Baja las piernas despacio sin tocar el suelo y vuelve a subir controlando el movimiento.', 'Evita arquear la espalda o usar impulso para subir las piernas.']::text[], actualizado_en = now() WHERE id = 'beaa4352-4d61-46a6-84bc-ce465f63b1fb';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa el abdomen con tijeras verticales, mejorando la coordinación y la resistencia del core.', instrucciones = ARRAY['Túmbate boca arriba en la colchoneta con las piernas elevadas y los brazos a los lados.', 'Mantén la zona lumbar pegada al suelo y el abdomen contraído.', 'Cruza las piernas alternando arriba y abajo con movimientos cortos y controlados.', 'Respira de forma constante y evita arquear la espalda o bajar demasiado las piernas.']::text[], actualizado_en = now() WHERE id = '5cf3b029-cf3f-402c-98bd-ea12b0e93ede';
