UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Sentadilla unilateral que carga el cuádriceps y exige equilibrio, mejorando fuerza y estabilidad de cada pierna por separado.', instrucciones = ARRAY['Coloca el empeine del pie trasero en el banco y sujeta una mancuerna en cada mano.', 'Baja la rodilla delantera controlando hasta que el muslo quede casi paralelo al suelo.', 'Empuja con el talón delantero para subir sin perder el equilibrio.', 'Mantén el torso erguido y evita que la rodilla delantera se vaya hacia dentro.']::text[], actualizado_en = now() WHERE id = '31db4af5-d1be-49d4-90ed-e4530332d354';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Peso muerto a una pierna que fortalece isquiosurales y glúteo, además de mejorar el equilibrio y la estabilidad del core.', instrucciones = ARRAY['Sujeta la mancuerna con una mano y apóyate con la otra en el soporte.', 'Inclina el torso llevando la cadera atrás mientras la pierna libre se eleva.', 'Baja hasta notar estiramiento en el isquiosural y vuelve apretando el glúteo.', 'Mantén la espalda recta y evita redondearla o girar la cadera.']::text[], actualizado_en = now() WHERE id = '7b378550-73db-44e4-b0b4-8abb2f9b4713';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Extensión de cadera con mancuerna que activa el glúteo mayor y refuerza isquiosurales y core para mejorar la potencia de cadera.', instrucciones = ARRAY['Apoya la espalda alta en el banco y coloca la mancuerna sobre la cadera.', 'Con los pies firmes, sube la pelvis hasta alinear tronco y muslos.', 'Aprieta el glúteo arriba y baja controlando sin apoyar del todo.', 'Evita arquear la zona lumbar; el movimiento sale del glúteo.']::text[], actualizado_en = now() WHERE id = '379fba13-aab3-4f6f-abd3-9cd0bdc797bf';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Elevación de gemelos unilateral que incide en el gastrocnemio, útil para ganar fuerza y volumen en la pantorrilla.', instrucciones = ARRAY['Coloca la punta del pie en el escalón y sujeta la mancuerna con una mano.', 'Baja el talón por debajo del escalón hasta notar estiramiento.', 'Sube el talón lo máximo posible y aprieta el gemelo arriba.', 'Haz el recorrido lento y evita rebotar o perder el equilibrio.']::text[], actualizado_en = now() WHERE id = 'c165a8ec-3ab6-43d8-9f3c-68e827b67030';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Apertura que trabaja el pectoral con apoyo de deltoides anterior y serrato, útil para dar amplitud y control al pecho.', instrucciones = ARRAY['Túmbate en el banco inclinado y agarra las poleas bajas con las palmas enfrentadas.', 'Con los codos ligeramente flexionados, junta las manos delante del pecho.', 'Abre los brazos controlando hasta notar estiramiento en el pecho.', 'Evita arquear la espalda o bloquear los codos durante el recorrido.']::text[], actualizado_en = now() WHERE id = 'fd2057fb-b467-4c50-a715-7c71b7d41115';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Cruces que enfatizan el pectoral inferior y ayudan a definir y controlar el pecho con apoyo de tríceps y deltoides anterior.', instrucciones = ARRAY['Colócate entre las poleas altas y agarra los manerales con los codos algo flexionados.', 'Lleva las manos hacia abajo y al centro hasta juntarlas delante de la cadera.', 'Vuelve despacio controlando la apertura sin perder la postura.', 'Evita encorvar el torso o tirar con los brazos en lugar del pecho.']::text[], actualizado_en = now() WHERE id = '0e13a191-5231-49b8-ab3c-74cf18cc1eee';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fondos que trabajan pecho y tríceps, mejorando la fuerza de empuje y el control del tren superior.', instrucciones = ARRAY['Sujétate en las paralelas con los brazos extendidos y el torso ligeramente inclinado.', 'Baja controlando hasta notar estiramiento en el pecho sin forzar el hombro.', 'Empuja para subir extendiendo los codos y exhala al final.', 'Evita bajar demasiado o encoger los hombros hacia las orejas.']::text[], actualizado_en = now() WHERE id = '7d508ec0-f841-4a2e-b44e-e3234f5f4d21';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja la parte superior del recto abdominal y los oblicuos, mejorando la fuerza del core y la estabilidad del tronco.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos en la nuca sin tirar del cuello y lleva el mentón ligeramente hacia el pecho.', 'Eleva la parte alta de la espalda despegando los omóplatos mientras exhalas, sin llegar a sentarte.', 'Baja controlando el movimiento e inhala; evita tirar del cuello con las manos.']::text[], actualizado_en = now() WHERE id = 'c199ae58-2d85-4348-8846-cb8234027598';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece la zona inferior del abdomen y los flexores de cadera, útil para el control pélvico y la estabilidad lumbar.', instrucciones = ARRAY['Túmbate boca arriba con las piernas estiradas y las manos a los lados o bajo los glúteos.', 'Presiona la zona lumbar contra el suelo antes de empezar.', 'Sube las piernas juntas hasta la vertical exhalando, sin arquear la espalda.', 'Baja despacio sin tocar el suelo y repite; evita balancear las piernas por inercia.']::text[], actualizado_en = now() WHERE id = '364579bc-51f9-474c-8414-35183032a55a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Activa los oblicuos y el recto abdominal con rotación, mejorando la coordinación y la fuerza rotacional del core.', instrucciones = ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas elevadas con rodillas flexionadas.', 'Lleva el codo derecho hacia la rodilla izquierda mientras extiendes la pierna derecha.', 'Alterna el lado como si pedalearas, exhalando en cada rotación.', 'Mantén la zona lumbar pegada al suelo y evita tirar del cuello.']::text[], actualizado_en = now() WHERE id = '93640250-668e-433f-8f99-836e78f820e7';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Isométrico que activa el recto y el transverso abdominal, mejorando la rigidez del core y la estabilidad global.', instrucciones = ARRAY['Túmbate boca arriba y eleva ligeramente los hombros y las piernas del suelo.', 'Presiona la zona lumbar contra el suelo y estira los brazos por encima de la cabeza.', 'Mantén la posición con respiración corta y controlada durante el tiempo indicado.', 'Evita arquear la lumbar o aguantar la respiración; si pierdes la posición, descansa.']::text[], actualizado_en = now() WHERE id = '1f4afaa9-c1fc-4f4b-b853-5d4e7885be63';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza los erectores espinales y los glúteos, mejorando la extensión de la columna y la postura en general.', instrucciones = ARRAY['Túmbate boca abajo con los brazos extendidos al frente y la frente apoyada.', 'Eleva un brazo y la pierna contraria a la vez, manteniendo el cuello neutro.', 'Aguanta un instante arriba y baja controlando, alternando lados.', 'Evita arquear en exceso el cuello o la lumbar; el movimiento debe ser suave.']::text[], actualizado_en = now() WHERE id = '6e062368-ba10-42a0-95f0-76ddec599883';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio clave para glúteo e isquiosurales que mejora la fuerza de la cadena posterior y el patrón de bisagra de cadera.', instrucciones = ARRAY['De pie con la barra frente a los muslos, agarre prono al ancho de hombros y espalda recta.', 'Empuja la cadera hacia atrás bajando la barra pegada a las piernas con rodillas semiflexionadas.', 'Baja hasta notar estiramiento en isquiosurales sin redondear la espalda.', 'Sube apretando glúteos y exhalando; evita hiperextender la lumbar arriba.']::text[], actualizado_en = now() WHERE id = 'b2d6c601-e607-4e66-8a9f-ce5b83b51f03';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Enfocado en isquiosurales y glúteos, mejora la flexibilidad y fuerza de la cadena posterior con piernas casi rectas.', instrucciones = ARRAY['De pie con la barra frente a los muslos y los pies al ancho de caderas.', 'Con las rodillas casi extendidas, lleva la cadera atrás bajando la barra pegada a las piernas.', 'Detente cuando notes tensión en la parte posterior del muslo, sin curvar la espalda.', 'Sube extendiendo la cadera y exhalando; evita bloquear las rodillas con fuerza.']::text[], actualizado_en = now() WHERE id = '939bb51c-06dc-45bd-aa63-435812158a7b';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Variante unilateral que combina fuerza de glúteo e isquiosurales, corrigiendo desequilibrios entre piernas.', instrucciones = ARRAY['Sujeta la barra frente a los muslos con una pierna ligeramente adelantada o apoyada.', 'Lleva la cadera atrás bajando la barra pegada a la pierna de apoyo con espalda recta.', 'Baja hasta notar estiramiento en isquiosurales y sube apretando el glúteo.', 'Evita redondear la espalda o cargar el peso en la puntera.']::text[], actualizado_en = now() WHERE id = '064d6666-4475-4446-a853-8de8cd9bc967';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio avanzado que fortalece hombros, trapecio y core, mejorando el equilibrio y el control corporal global.', instrucciones = ARRAY['Coloca las manos en el suelo al ancho de hombros y apoya la cabeza entre los brazos.', 'Impulsa las piernas hacia arriba hasta quedar invertido con el cuerpo alineado.', 'Aprieta el core y los glúteos para mantener la vertical y respira con control.', 'Baja con cuidado; evita arquear la lumbar o perder el control del cuello.']::text[], actualizado_en = now() WHERE id = 'd0328f97-2c74-4411-af93-e301c8785588';
UPDATE ejercicios SET categoria = 'yoga', codigo_externo = NULL, descripcion = 'Isométrico que activa erectores y multífidos, útil para mejorar la resistencia y estabilidad de la columna.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Presiona la zona lumbar contra el suelo activando el abdomen y los glúteos.', 'Mantén la posición sin mover la pelvis durante el tiempo indicado.', 'Respira de forma continua y evita aguantar la respiración o despegar la lumbar.']::text[], actualizado_en = now() WHERE id = 'da6ea9d1-e7dd-438b-bc7f-46373d350640';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Movilidad que descomprime la columna y estira erectores y trapecio, ideal tras sesiones de carga o muchas horas sentado.', instrucciones = ARRAY['Túmbate boca arriba con los tobillos cruzados y las manos en la nuca.', 'Estira los brazos y las piernas buscando alargar la columna sin despegar la lumbar.', 'Mantén la elongación respirando profundo durante el tiempo indicado.', 'Evita tirar del cuello con las manos o forzar la curva lumbar.']::text[], actualizado_en = now() WHERE id = '3c51bd06-897c-4755-b729-d3116d0aa734';
UPDATE ejercicios SET categoria = 'yoga', codigo_externo = NULL, descripcion = 'Postura de descarga que relaja la zona lumbar y estira aductores, útil para recuperar tras el entrenamiento.', instrucciones = ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Junta las plantas de los pies y deja caer las rodillas hacia los lados.', 'Apoya los brazos relajados y respira profundo manteniendo la postura.', 'Evita forzar la apertura de caderas o despegar la lumbar del suelo.']::text[], actualizado_en = now() WHERE id = '756c68c7-542f-4c5c-b335-4a778a0dca0e';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Movilidad rotacional que estira cuadrado lumbar y erectores, aliviando tensión y mejorando la flexibilidad del tronco.', instrucciones = ARRAY['Túmbate boca arriba con los brazos en cruz y las piernas flexionadas.', 'Cruza la pierna izquierda por encima de la derecha y déjala caer hacia el lado derecho.', 'Gira la cabeza al lado contrario y respira profundo manteniendo el hombro apoyado.', 'Evita forzar la rotación o despegar el hombro del suelo.']::text[], actualizado_en = now() WHERE id = '04913118-6a9f-468b-bce3-230eef36aad1';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Estiramiento rotacional que trabaja cuadrado lumbar y aductores, mejorando la movilidad de la columna y la cadera.', instrucciones = ARRAY['Túmbate boca arriba con los brazos en cruz y las piernas flexionadas.', 'Cruza la pierna izquierda sobre la derecha y déjala caer hacia el lado izquierdo.', 'Mantén los hombros apoyados y gira la cabeza al lado contrario respirando profundo.', 'Evita rebotar o forzar la rotación más allá de lo cómodo.']::text[], actualizado_en = now() WHERE id = '02a2387a-f845-4a21-9603-c9b757eeca78';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Rotación suave que estira cuadrado lumbar y aductores, útil para descargar la espalda y ganar movilidad.', instrucciones = ARRAY['Túmbate boca arriba con los brazos en cruz y las piernas flexionadas.', 'Cruza la pierna derecha sobre la izquierda y déjala caer hacia el lado derecho.', 'Gira la cabeza al lado contrario y mantén el hombro apoyado respirando profundo.', 'Evita forzar la rotación o levantar el hombro del suelo.']::text[], actualizado_en = now() WHERE id = 'b5d27de0-ec6d-4b88-bce8-43916978c660';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Trabaja glúteos y cuádriceps con impacto cardiovascular bajo, ideal para mejorar resistencia y acondicionamiento sin castigar las articulaciones.', instrucciones = ARRAY['Colócate de pie sobre los pedales con la espalda recta y las manos en las asas. Sube alternando los pies a un ritmo constante y controlado. Mantén el tronco erguido y evita apoyarte en los brazos. Respira de forma acompasada y no des pasos demasiado largos para no perder el equilibrio.']::text[], actualizado_en = now() WHERE id = '11678653-f918-429a-a8c0-9eaa2679cc2e';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Mejora la resistencia cardiovascular y fortalece piernas y core, útil para quemar calorías y ganar fondo físico de forma progresiva.', instrucciones = ARRAY['Sube a la cinta y engancha el clip de seguridad antes de empezar. Comienza caminando y aumenta la velocidad poco a poco hasta tu ritmo de carrera. Apoya el pie de forma natural, sin talonear en exceso, y mira al frente. Mantén los brazos relajados y no te agarres a las asas durante la carrera.']::text[], actualizado_en = now() WHERE id = 'eb8b0c59-c6a7-4dae-8dd0-23b6b149e4e7';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Actividad cardiovascular suave que activa piernas y core, perfecta para calentar o para sesiones de bajo impacto y recuperación activa.', instrucciones = ARRAY['Colócate sobre la cinta con el clip de seguridad puesto. Empieza a caminar a ritmo cómodo y ajusta la velocidad según tu sensación. Da pasos naturales apoyando todo el pie y mantén el tronco erguido. Evita agarrarte a las asas y respira con normalidad durante toda la marcha.']::text[], actualizado_en = now() WHERE id = '4929a81d-f32b-4aee-abc4-99762c078dbc';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza la zona baja del abdomen y el transverso, mejorando la estabilidad del core y el control lumbar en decúbito supino.', instrucciones = ARRAY['Túmbate boca arriba con las manos bajo la zona lumbar y las piernas elevadas. Baja una pierna estirada mientras la otra sube, alternando con control. Mantén la lumbar pegada al suelo y el abdomen activado en todo momento. Evita arquear la espalda o bajar las piernas demasiado rápido.']::text[], actualizado_en = now() WHERE id = 'fdaf38ca-a38d-42a9-b4bb-078448b47797';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Ejercicio explosivo que fortalece piernas y glúteos mientras eleva la frecuencia cardíaca, mejorando potencia y coordinación.', instrucciones = ARRAY['Da un paso al frente y baja en zancada hasta que la rodilla trasera casi toque el suelo. Impúlsate con fuerza y salta cambiando de pierna en el aire. Aterriza con la rodilla alineada con el pie y amortigua la caída. Mantén el tronco erguido y evita que la rodilla delantera se vaya hacia dentro.']::text[], actualizado_en = now() WHERE id = '3c6f1464-2626-44c0-a851-70292c176e73';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Mejora la coordinación, la resistencia cardiovascular y el trabajo de hombros y core mediante golpes al aire sin material.', instrucciones = ARRAY['Adopta una postura de guardia con los puños cerca de la cara y las rodillas ligeramente flexionadas. Lanza golpes rectos y curvos alternando brazos sin bloquear el codo. Mantén el core activo y muévete ligeramente sobre los pies. Respira de forma continua y evita golpear con los hombros encogidos.']::text[], actualizado_en = now() WHERE id = 'f410a94f-5ae4-4083-b9aa-b147c82b14c1';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Desarrolla potencia de piernas y glúteos con un gesto explosivo que mejora la capacidad de salto y la reactividad neuromuscular.', instrucciones = ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas. Flexiona rodillas y caderas y salta con fuerza hacia el cajón. Aterriza con ambos pies a la vez y las rodillas alineadas, amortiguando el impacto. Baja con control y evita saltar desde demasiado lejos o con el tronco inclinado.']::text[], actualizado_en = now() WHERE id = 'ecbcb22c-7806-47ac-b60e-04d70c087870';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Ejercicio metabólico que fortalece piernas y glúteos y eleva el pulso, mejorando la potencia y la resistencia muscular.', instrucciones = ARRAY['Separa los pies a la anchura de los hombros y baja en sentadilla con el pecho alto. Impúlsate con fuerza y salta extendiendo las piernas. Aterriza con las rodillas ligeramente flexionadas y amortigua el golpe. Mantén las rodillas alineadas con los pies y evita que se junten hacia dentro.']::text[], actualizado_en = now() WHERE id = '320dbe39-8edf-4f41-8e5b-2355caae7b76';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Trabajo metabólico intenso que activa hombros, espalda y core, mejorando la resistencia y la coordinación de la parte superior.', instrucciones = ARRAY['Sujeta un extremo de cada cuerda con las rodillas ligeramente flexionadas y el core activo. Mueve los brazos arriba y abajo alternando para crear ondas continuas. Mantén el tronco estable y evita balancear todo el cuerpo. Respira de forma constante y ajusta la intensidad para no perder la técnica.']::text[], actualizado_en = now() WHERE id = 'e5b19fcf-dadd-4ed9-a479-37154b5d7a02';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Mejora la agilidad, la coordinación y la rapidez de pies, con implicación de pantorrillas, cuádriceps y core.', instrucciones = ARRAY['Colócate al inicio de la escalera con las rodillas ligeramente flexionadas. Entra pisando cada hueco con un pie y avanza con pasos rápidos y cortos. Mantén la vista al frente y los brazos activos acompañando el movimiento. Evita mirar los pies o pisar los bordes para no tropezar.']::text[], actualizado_en = now() WHERE id = 'cae0cc54-2ddc-4a69-80ae-96316ed0ec27';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece los oblicuos y el core rotando el tronco con carga, mejorando la estabilidad y la fuerza en movimientos de giro.', instrucciones = ARRAY['Siéntate con las rodillas flexionadas y sujeta el balón con las dos manos frente al pecho. Inclina ligeramente el tronco hacia atrás manteniendo la espalda recta. Gira el tronco a un lado y a otro llevando el balón junto a la cadera. Evita tirar solo de los brazos y mantén el abdomen activo durante el giro.']::text[], actualizado_en = now() WHERE id = 'ab1e2d3f-ce11-4209-a01c-39bc5651ff8a';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Ejercicio metabólico que trabaja el recto abdominal y los flexores de cadera con coordinación y transferencia de balón.', instrucciones = ARRAY['Túmbate boca arriba con las piernas y los brazos estirados y el balón entre las manos. Eleva tronco y piernas a la vez formando una V y pasa el balón a los pies. Baja con control y repite el movimiento alternando la transferencia. Mantén la lumbar apoyada y evita impulsarte con un tirón brusco.']::text[], actualizado_en = now() WHERE id = 'abf24955-949f-473c-935f-06250a32fb5d';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el core y el transverso con inestabilidad, mejorando el control postural y la estabilidad de hombros y cadera.', instrucciones = ARRAY['Apoya las manos sobre el fitball y coloca el cuerpo en plancha con los pies separados. Lleva una rodilla hacia el pecho y vuelve, alternando piernas a ritmo controlado. Mantén la cadera estable y el abdomen activado sin hundir la espalda. Evita mover el fitball o balancear el tronco durante el movimiento.']::text[], actualizado_en = now() WHERE id = '0b00c8a0-885a-41e3-8301-17ac51a6c6d5';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Ejercicio avanzado que fortalece hombros, tríceps y core, mejorando la estabilidad y el control del cuerpo invertido.', instrucciones = ARRAY['Coloca las manos en el suelo a la anchura de los hombros y apoya la cabeza en el suelo formando trípode. Eleva las piernas con control hasta quedar invertido y mantén el core activo. Presiona el suelo con las manos y evita arquear en exceso la lumbar. Baja con control y no intentes el pino sin dominar la posición contra la pared.']::text[], actualizado_en = now() WHERE id = 'e931b524-d296-4807-b03f-043c83b19bae';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Movimiento balístico que activa glúteos e isquiosurales y eleva el pulso, mejorando potencia de cadera y resistencia metabólica.', instrucciones = ARRAY['Sujeta la kettlebell con las dos manos y separa los pies a la anchura de los hombros. Lleva la cadera atrás con la espalda recta y balancea la pesa entre las piernas. Extiende la cadera con fuerza para impulsar la kettlebell hasta la altura del pecho. Mantén los brazos relajados y evita redondear la espalda o usar los hombros para subir el peso.']::text[], actualizado_en = now() WHERE id = 'e06d1952-cb61-4aaa-b458-a928b6f66243';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Eleva las rodillas alternando piernas a ritmo rápido para subir las pulsaciones y mejorar la coordinación.', instrucciones = ARRAY['Colócate de pie con el torso erguido y los brazos relajados.', 'Salta alternando rodillas altas, llevándolas hacia el pecho.', 'Apoya la parte delantera del pie y mantén un ritmo constante.', 'Coordina la respiración con el movimiento sin aguantar el aire.', 'Evita inclinar el tronco hacia atrás o golpear el suelo con fuerza.']::text[], actualizado_en = now() WHERE id = '4f75fc4c-e4d4-4327-bdf5-1ea397e91096';
