UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza pecho, tríceps y estabilidad del hombro manteniendo una posición isométrica exigente en anillas.', instrucciones = ARRAY['Sujeta las anillas y colócate en posición de plancha con los brazos extendidos.', 'Aprieta el abdomen y los glúteos para mantener el cuerpo en línea recta.', 'Mantén la posición respirando de forma constante sin dejar caer la cadera.', 'Evita bloquear la respiración o dejar que las anillas se separen demasiado.']::text[], actualizado_en = now() WHERE id = '96b8b655-eda9-41d4-a9c8-656851bfcb61';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Mejora la movilidad de hombros y tobillos mientras refuerza el core y las piernas en una sentadilla profunda.', instrucciones = ARRAY['Sujeta la barra por encima de la cabeza con los brazos extendidos y los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo la barra alineada sobre el centro del cuerpo.', 'Empuja el suelo con los talones y sube apretando el abdomen.', 'Evita perder la verticalidad de la barra o dejar que los talones se levanten.']::text[], actualizado_en = now() WHERE id = '38f72a45-bd77-4808-bfff-850e89b77dd9';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece hombros, tríceps y core manteniendo el cuerpo invertido sobre las paralelas, mejorando el equilibrio y la estabilidad.', instrucciones = ARRAY['Agarra las barras paralelas con los brazos extendidos y los hombros por encima de las manos.', 'Sube las piernas flexionadas y apóyate en las barras hasta quedar invertido con el core firme.', 'Mantén la posición con la mirada al frente y respira de forma controlada sin aguantar el aire.', 'Evita arquear la espalda o encoger los hombros; baja con control si pierdes la postura.']::text[], actualizado_en = now() WHERE id = 'cffd65fb-9388-4561-97f6-a55e7c33cb1a';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Trabaja piernas y core mientras la barra sobre la cabeza exige estabilidad y control postural en cada zancada.', instrucciones = ARRAY['Sujeta la barra por encima de la cabeza con los brazos extendidos y el core activo.', 'Da un paso al frente y baja la rodilla trasera hasta rozar el suelo con control.', 'Empuja con la pierna delantera para volver a la posición inicial y alterna el lado.', 'Mantén la barra alineada sobre los hombros y evita que la espalda se arquee.']::text[], actualizado_en = now() WHERE id = 'edc8b5e5-a621-4f6e-ae35-a9fdcb234d0b';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Mejora la movilidad de tobillos, caderas y hombros mientras el core estabiliza la barra sobre la cabeza.', instrucciones = ARRAY['Coloca la barra sobre la cabeza con los brazos extendidos y los pies a la anchura de los hombros.', 'Baja en sentadilla profunda manteniendo el pecho alto y la barra sobre la línea media.', 'Empuja el suelo con los talones para subir y respira al ascender.', 'Evita adelantar la barra o perder el equilibrio; reduce la profundidad si es necesario.']::text[], actualizado_en = now() WHERE id = 'a2b82c3c-b9b6-44fe-a4f1-e0d1551fbda9';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Estira isquiosurales y lumbares y fortalece el core y los flexores de cadera colgándote de la barra.', instrucciones = ARRAY['Cuélgate de la barra con las manos a la anchura de los hombros y los brazos extendidos.', 'Activa el core y sube las piernas rectas hasta tocar la barra con los pies.', 'Baja despacio controlando el descenso y sin balancearte.', 'Evita usar impulso o encoger los hombros; mantén la espalda estable.']::text[], actualizado_en = now() WHERE id = '65de3a22-a14c-49d7-908f-e1efd0d9aa8f';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Eleva la frecuencia cardiaca y fortalece piernas y glúteos con un gesto explosivo y controlado sobre el cajón.', instrucciones = ARRAY['Colócate frente al cajón con una mancuerna en cada mano y el pie completo sobre la superficie.', 'Empuja con la pierna de apoyo para subir y extiende la cadera arriba sin bloquear la rodilla.', 'Baja con control hasta el suelo y alterna la pierna en cada repetición.', 'Evita impulsarte con la pierna de abajo o dejar caer el peso de golpe.']::text[], actualizado_en = now() WHERE id = '45e94f61-45ec-4a29-b116-83e3777985d6';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza hombros, tríceps y core en posición invertida con la pared como apoyo para ganar confianza.', instrucciones = ARRAY['Apoya las manos en el suelo separadas del muro y coloca los pies en la pared.', 'Sube caminando con los pies por la pared hasta quedar boca abajo con el cuerpo alineado.', 'Mantén el core activo y respira con normalidad durante el tiempo indicado.', 'Evita arquear la zona lumbar; baja caminando con control si pierdes la alineación.']::text[], actualizado_en = now() WHERE id = 'ffd195e2-f7cc-4f8a-8abb-66f71a84df72';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece tríceps y pectoral con el peso corporal, mejorando la fuerza de empuje y la estabilidad del hombro.', instrucciones = ARRAY['Sujeta la barra fija con las palmas hacia delante y el cuerpo colgando con los brazos extendidos.', 'Flexiona los codos y baja el pecho hacia la barra manteniendo el core firme.', 'Empuja para volver arriba extendiendo los codos sin balancearte.', 'Evita encoger los hombros o usar impulso; controla el descenso.']::text[], actualizado_en = now() WHERE id = '329b2103-0a2d-45b6-bc89-eb74a3f30754';
UPDATE ejercicios SET categoria = 'cardio', codigo_externo = NULL, descripcion = 'Mejora la coordinación, la resistencia cardiovascular y la potencia de pantorrillas con un salto doble por giro.', instrucciones = ARRAY['Sujeta la comba con los codos cerca del cuerpo y salta con los pies juntos.', 'Gira la cuerda dos veces por cada salto manteniendo un ritmo constante.', 'Aterriza con las rodillas ligeramente flexionadas y el core activo.', 'Evita saltar demasiado alto o encoger los hombros; usa las muñecas para girar.']::text[], actualizado_en = now() WHERE id = '43e921fb-baaf-4ba5-9240-87bb1a855247';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Desarrolla fuerza y control en hombros y core avanzando en posición invertida sobre las manos.', instrucciones = ARRAY['Entra en el pino con los brazos extendidos y el core firme.', 'Desplaza el peso hacia una mano y da pequeños pasos con la otra para avanzar.', 'Mantén la mirada al frente y respira de forma controlada.', 'Evita arquear la espalda o dar pasos demasiado largos; prioriza el equilibrio.']::text[], actualizado_en = now() WHERE id = '66df55b5-6985-45c1-950a-9146a819e652';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Potencia piernas y glúteos con un salto explosivo que también mejora la coordinación y la resistencia.', instrucciones = ARRAY['Colócate con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.', 'Baja en una sentadilla corta y salta hacia arriba extendiendo brazos y piernas.', 'Aterriza con las rodillas flexionadas y el core activo para amortiguar.', 'Evita caer con las piernas rígidas o juntar las rodillas hacia dentro.']::text[], actualizado_en = now() WHERE id = '452a8b7e-b929-4810-a795-7e44838e9af3';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Movimiento explosivo que trabaja cadena posterior, hombros y core, mejorando la potencia y la coordinación.', instrucciones = ARRAY['Sujeta la mancuerna con una mano entre las piernas y la espalda recta.', 'Impulsa con las caderas y sube la mancuerna hasta por encima de la cabeza en un solo gesto.', 'Baja con control hasta la posición inicial y repite o cambia de mano.', 'Evita redondear la espalda o usar solo el brazo; la fuerza nace de las caderas.']::text[], actualizado_en = now() WHERE id = '2dc1da6b-ffe9-494c-9f31-fd1d41915466';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece cuádriceps y glúteos con un patrón de zancada que mejora el equilibrio y la estabilidad de la rodilla.', instrucciones = ARRAY['De pie con los pies juntos y las manos en la cintura o libres.', 'Da un paso al frente y baja la rodilla trasera hasta rozar el suelo.', 'Empuja con la pierna delantera para volver y alterna el lado.', 'Evita que la rodilla delantera pase muy por delante del pie o que el tronco se incline.']::text[], actualizado_en = now() WHERE id = '13a3dadd-a811-4593-91a4-9685d8930569';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Fortalece agarre, trapecio y core caminando con peso, mejorando la resistencia y la postura erguida.', instrucciones = ARRAY['Sujeta una mancuerna en cada mano con los brazos extendidos junto al cuerpo.', 'Camina con pasos cortos manteniendo el pecho alto y los hombros atrás.', 'Respira con normalidad y mantén el core activo durante todo el recorrido.', 'Evita encoger los hombros o inclinarte hacia los lados.']::text[], actualizado_en = now() WHERE id = '0da462cf-0b39-4e2d-92a4-ddc6f3beae3e';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Trabaja piernas y glúteos con el peso corporal, mejorando la resistencia y el patrón básico de sentadilla.', instrucciones = ARRAY['Colócate con los pies a la anchura de los hombros y los brazos al frente.', 'Baja flexionando caderas y rodillas con el pecho alto y la espalda recta.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita que las rodillas se junten hacia dentro o que los talones se levanten.']::text[], actualizado_en = now() WHERE id = 'a09d9d7d-dffd-4aca-beee-75801c3616e5';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Movimiento balístico que activa glúteos, isquiosurales y core, mejorando la potencia de la cadena posterior.', instrucciones = ARRAY['Sujeta la kettlebell con ambas manos y los pies a la anchura de los hombros.', 'Lleva la cadera atrás y balancea la pesa entre las piernas con la espalda recta.', 'Impulsa la cadera al frente para que la kettlebell suba hasta la altura del pecho.', 'Evita usar los brazos para levantarla o redondear la espalda.']::text[], actualizado_en = now() WHERE id = 'e1af806a-cf94-464a-a280-cb422934dd99';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Trabaja cuádriceps y glúteo con un salto explosivo al cajón, mejorando potencia y capacidad metabólica.', instrucciones = ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas.', 'Flexiona rodillas y caderas y salta con fuerza para subir al cajón.', 'Aterriza con ambos pies suaves y rodillas alineadas con los pies.', 'Baja controlado y repite sin perder la postura.', 'Evita saltar desde demasiado lejos o aterrizar con rodillas hacia dentro.']::text[], actualizado_en = now() WHERE id = '603cb7f4-2d34-4ac0-ae18-e8c7699f5c98';
UPDATE ejercicios SET categoria = 'plyometrics', codigo_externo = NULL, descripcion = 'Lanzamiento explosivo que activa piernas, hombros y core, ideal para potencia y acondicionamiento metabólico.', instrucciones = ARRAY['Sujeta el balón a la altura del pecho con los codos cerca del cuerpo.', 'Flexiona ligeramente las rodillas y carga el peso en los talones.', 'Lanza el balón contra la pared extendiendo piernas y brazos.', 'Recoge el balón tras el rebote y repite con ritmo constante.', 'Evita lanzar solo con los brazos sin usar las piernas.']::text[], actualizado_en = now() WHERE id = '59807c2e-bf06-4edc-9781-4a262c55a1fb';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece los oblicuos y estabiliza el tronco, útil para mejorar la postura y prevenir molestias lumbares.', instrucciones = ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado.', 'Mantén el tronco erguido y los pies a la anchura de las caderas.', 'Inclina el tronco hacia el lado contrario a la banda de forma controlada.', 'Vuelve despacio a la posición inicial resistiendo la tensión.', 'Evita balancear el cuerpo o tirar con el brazo en lugar del oblicuo.']::text[], actualizado_en = now() WHERE id = 'b8bfea1f-044f-4c07-a33c-21901b62262f';
UPDATE ejercicios SET categoria = 'stretching', codigo_externo = NULL, descripcion = 'Estira isquiosurales y gemelos, mejorando la flexibilidad posterior y aliviando tensión tras el entrenamiento.', instrucciones = ARRAY['Túmbate boca arriba y engancha la banda en la planta de un pie.', 'Sujeta los extremos con las manos y eleva la pierna estirada.', 'Tira suavemente de la banda hasta notar estiramiento sin dolor.', 'Mantén la respiración relajada durante veinte o treinta segundos.', 'Evita levantar la cadera del suelo o forzar la rodilla bloqueada.']::text[], actualizado_en = now() WHERE id = '42cb7228-023e-4c70-809c-4143d0ac9931';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Refuerza el deltoides anterior y tríceps, mejorando el empuje vertical y la estabilidad del hombro.', instrucciones = ARRAY['Pisa la banda con ambos pies y sujeta los extremos a la altura de los hombros.', 'Activa el core y mantén las muñecas alineadas con los antebrazos.', 'Empuja las manos hacia arriba hasta extender los brazos sin bloquear.', 'Baja controlado hasta la altura de los hombros y repite.', 'Evita arquear la espalda o encoger los hombros al empujar.']::text[], actualizado_en = now() WHERE id = '2fdfb134-efbc-4bd9-8721-038c60c2fad1';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece dorsal ancho y bíceps con ayuda elástica, ideal para progresar hacia dominadas completas.', instrucciones = ARRAY['Coloca la banda en la barra y engancha una rodilla o el pie en el extremo.', 'Agarra la barra con las palmas hacia delante y los brazos extendidos.', 'Tira del cuerpo hacia arriba llevando el pecho a la barra.', 'Baja controlado hasta extender los brazos sin soltar la tensión.', 'Evita balancearte o encoger los hombros al iniciar la subida.']::text[], actualizado_en = now() WHERE id = '0ed342bf-7373-4959-906b-e921a08920d3';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Activa el deltoides posterior y romboides, mejorando la movilidad y salud del hombro.', instrucciones = ARRAY['Sujeta la banda frente al pecho con los brazos extendidos.', 'Mantén los codos ligeramente flexionados y el core activo.', 'Separa las manos hacia los lados hasta abrir el pecho.', 'Vuelve despacio al centro controlando la banda.', 'Evita encoger los hombros o arquear la espalda.']::text[], actualizado_en = now() WHERE id = 'c3c7bea1-e41e-4615-9878-b58ebc34bd35';
UPDATE ejercicios SET categoria = 'strength', codigo_externo = NULL, descripcion = 'Fortalece deltoides posterior y manguito rotador, equilibrando el hombro y mejorando la postura.', instrucciones = ARRAY['Fija la banda a la altura de la cara y sujeta los extremos.', 'Da un paso atrás con los brazos extendidos y el core activo.', 'Tira de la banda hacia la cara separando los codos.', 'Aprieta los omóplatos al final y vuelve controlado.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], actualizado_en = now() WHERE id = '42fd751e-37ef-4c1d-ab13-91f9e3472f4b';
UPDATE ejercicios SET categoria = 'mobility', codigo_externo = NULL, descripcion = 'Mejora la movilidad del hombro y activa el manguito rotador, preparando la articulación para el entrenamiento.', instrucciones = ARRAY['Sujeta la banda frente al cuerpo con las manos separadas.', 'Mantén los brazos casi extendidos y el core activo.', 'Lleva la banda por encima de la cabeza hasta detrás de la espalda.', 'Vuelve despacio al frente sin perder el control.', 'Evita forzar si notas pinchazo o arquear la zona lumbar.']::text[], actualizado_en = now() WHERE id = 'e2cf00db-5ef1-4bbb-935e-90c4a9878a5c';

-- Ejercicios nuevos (4536), sin vídeo.
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('aa1eb31f-beca-5c30-b2a2-9b1cac36f538', 'Ejercicio de agilidad 1-2 con palo', ARRAY['Coloca el palo en el suelo y sitúate a un lado con rodillas ligeramente flexionadas.', 'Da un paso rápido al otro lado y vuelve con dos apoyos alternos.', 'Mantén el pecho alto y los brazos activos durante el movimiento.', 'Aumenta el ritmo progresivamente sin perder el control.', 'Evita mirar al suelo todo el tiempo o cruzar los pies.']::text[], 'intermedio', 'Mejora la coordinación y la frecuencia de pies, elevando la capacidad cardiovascular y la agilidad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5965'),
('71984756-9b94-5e21-bdda-2266a3f85518', 'Salto de cajón de 1 a 2', ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas.', 'Flexiona rodillas y caderas y salta con fuerza hacia el cajón.', 'Aterriza con ambos pies suaves y rodillas alineadas.', 'Baja controlado y repite manteniendo el ritmo.', 'Evita aterrizar con las rodillas hacia dentro o el tronco muy inclinado.']::text[], 'intermedio', 'Desarrolla potencia de piernas con saltos explosivos, mejorando cuádriceps, glúteos y coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4209'),
('b501d245-26e5-5277-8133-c83d4f6c5d28', 'Ejercicio 123 hacia atrás', ARRAY['Sitúate de pie con las rodillas ligeramente flexionadas.', 'Da tres pasos rápidos hacia atrás alternando los pies.', 'Mantén el tronco erguido y los brazos activos.', 'Vuelve al inicio y repite con ritmo constante.', 'Evita cruzar los pies o mirar solo al suelo.']::text[], 'intermedio', 'Entrena la coordinación y la capacidad cardiovascular con desplazamientos rápidos hacia atrás.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5984'),
('2eb6d191-0acd-57e5-af4f-b0de8e6a5668', 'Salto de cajón de 2 a 1', ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas.', 'Flexiona rodillas y caderas y salta con fuerza al cajón.', 'Aterriza con ambos pies suaves y rodillas alineadas.', 'Baja controlado y repite sin perder la postura.', 'Evita saltar desde demasiado lejos o aterrizar con rodillas hacia dentro.']::text[], 'intermedio', 'Mejora la potencia de piernas y la coordinación con saltos explosivos sobre el cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4208'),
('8dc15237-5a71-5e94-a40e-74169e4690a9', 'Chaturanga con tres piernas', ARRAY['Parte de plancha alta con las manos bajo los hombros.', 'Flexiona los codos hacia atrás manteniéndolos cerca del cuerpo.', 'Eleva una pierna mientras bajas el tronco de forma controlada.', 'Mantén el core activo y la mirada al frente.', 'Evita abrir los codos o dejar caer la cadera.']::text[], 'intermedio', 'Fortalece tríceps, pecho y core mientras mejora el equilibrio y la estabilidad del hombro.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5915'),
('622c6552-d6c1-58d3-8d16-f7958b96a8e0', 'Postura del perro con tres patas', ARRAY['Parte de perro boca abajo con manos y pies apoyados.', 'Eleva una pierna hacia arriba manteniendo la cadera cuadrada.', 'Lleva el pecho hacia los muslos sin forzar la espalda.', 'Respira profundo y mantén la postura unos segundos.', 'Evita abrir la cadera o bloquear los codos.']::text[], 'intermedio', 'Estira isquiosurales y gemelos, mejora la movilidad del hombro y la estabilidad del core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5887'),
('dfd3d5a0-1b3a-5531-93d2-c8279d4430e5', 'Abdominal tres cuartos', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la zona abdominal con un recorrido parcial que reduce la tensión lumbar y resulta ideal para principiantes.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0001'),
('40fd9173-ce93-5ef8-a94e-be7a760c19cf', 'Salto a una pierna en cuatro direcciones', ARRAY['Colócate sobre una pierna con la rodilla ligeramente flexionada y el tronco erguido.', 'Salta hacia delante, atrás y a ambos lados manteniendo el equilibrio en cada aterrizaje.', 'Amortigua con la rodilla y el tobillo al caer, sin bloquear la articulación.', 'Evita que la rodilla se vaya hacia dentro y controla el ritmo de los saltos.']::text[], 'intermedio', 'Fortalece gemelos y tobillos con apoyo unipodal, mejorando la estabilidad y la potencia en los desplazamientos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9066'),
('bdf0089e-181b-5a49-b392-1e51ef2acde9', 'Abdominal bicicleta con giro', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas elevadas.', 'Lleva el codo hacia la rodilla contraria mientras extiendes la otra pierna.', 'Alterna los lados de forma fluida y controlada, sin tirar del cuello.', 'Espira al girar y evita arquear la zona lumbar en ningún momento.']::text[], 'intermedio', 'Activa rectos y oblicuos con un movimiento cruzado que mejora la coordinación y la rotación del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5265'),
('c18217ef-d989-5014-9dc3-2aeeb9e16d2e', 'Extensión de cadera a 45 grados', ARRAY['Apoya la cadera en el soporte a 45 grados con los pies bien fijados.', 'Sube la pierna extendida apretando el glúteo hasta alinear el tronco.', 'Baja despacio sin perder la tensión y sin hiperextender la espalda.', 'Evita balancearte y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Aísla el glúteo en un banco inclinado, útil para reforzar la cadera y prevenir molestias lumbares.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4937'),
('59ce787a-827b-5d95-a7c3-871e60104c19', 'Hiperextensión a 45 grados', ARRAY['Colócate en el banco a 45 grados con los brazos cruzados sobre el pecho.', 'Baja el tronco de forma controlada hasta notar estiramiento en la espalda.', 'Sube hasta alinear el cuerpo sin arquear en exceso la zona lumbar.', 'Mantén el cuello neutro y evita dar tirones con la espalda.']::text[], 'intermedio', 'Refuerza la musculatura espinal y los glúteos, mejorando la postura y la resistencia de la cadena posterior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5813'),
('cd5e300a-addf-5498-9678-d3517c7e1446', 'Hiperextensión a 45 grados a una pierna', ARRAY['Apoya una pierna en el banco a 45 grados y cruza los brazos al pecho.', 'Sube el tronco apretando el glúteo de la pierna de apoyo.', 'Baja despacio manteniendo la cadera alineada y sin rotar.', 'Evita compensar con la lumbar y controla el equilibrio en cada repetición.']::text[], 'intermedio', 'Trabaja glúteo y femoral de forma unilateral, corrigiendo desequilibrios y mejorando el control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1170'),
('fb75866f-935e-5b41-931e-d28c79521f66', 'Hiperextensión a 45 grados con giro', ARRAY['Colócate en el banco a 45 grados con las manos en la nuca.', 'Sube el tronco y gira suavemente hacia un lado al llegar arriba.', 'Alterna el giro en cada repetición sin forzar la zona lumbar.', 'Mantén el movimiento lento y evita arquear la espalda al girar.']::text[], 'intermedio', 'Combina extensión espinal y rotación para trabajar oblicuos y cadena posterior con control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1171'),
('0a63ac39-73fa-506d-a5d5-8345638e6a19', 'Extensión de espalda a 45 grados', ARRAY['Apoya la cadera en el banco a 45 grados con los pies bien sujetos.', 'Baja el tronco con control hasta sentir estiramiento en la espalda.', 'Sube hasta alinear el cuerpo sin hiperextender la lumbar.', 'Respira de forma constante y evita impulsarte con las piernas.']::text[], 'intermedio', 'Fortalece erectores espinales y glúteos, mejorando la postura y la estabilidad del tronco en el día a día.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4455'),
('fe85e34d-c0eb-523b-bfee-5e3d3a7b1852', 'Extensión de espalda a 45 grados con aducción escapular', ARRAY['Colócate en el banco a 45 grados con los brazos extendidos al frente.', 'Sube el tronco y junta las escápulas al final del recorrido.', 'Baja despacio manteniendo el control y la espalda neutra.', 'Evita encoger los hombros y no hiperextiendas la zona lumbar.']::text[], 'intermedio', 'Refuerza espalda alta y romboides junto a la cadena posterior, mejorando la postura y la retracción escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8895'),
('5a606485-0306-531b-9251-a6d941fc283c', 'Flexión lateral a 45 grados', ARRAY['De pie con los pies a la anchura de los hombros y los brazos relajados.', 'Inclina el tronco hacia un lado de forma controlada sin rotar.', 'Vuelve al centro apretando el oblicuo del lado contrario.', 'Evita balancearte y mantén la cadera estable durante todo el movimiento.']::text[], 'intermedio', 'Trabaja oblicuos y estabilizadores laterales del tronco, mejorando la fuerza y el control de la cintura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5699'),
('2e728f82-ad6f-510a-aa59-317e9b884540', 'Flexión lateral', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.', 'Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa oblicuos y zona lateral del abdomen, ayudando a estabilizar el tronco y mejorar la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0002'),
('d98f5505-295e-5c25-8623-d12593504843', 'Toque de talón a 90 grados', ARRAY['Túmbate boca arriba con las rodillas flexionadas a 90 grados y los pies apoyados.', 'Eleva ligeramente el tronco y lleva una mano hacia el talón del mismo lado.', 'Alterna los lados de forma lenta y controlada sin despegar la lumbar.', 'Espira al tocar el talón y evita tirar del cuello.']::text[], 'intermedio', 'Trabaja la zona abdominal baja y los oblicuos con un gesto controlado que mejora la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4007'),
('2fe6de64-683c-56c2-8687-73b4100f8fb8', 'Estiramiento de glúteo a 90 y 90 con press', ARRAY['Siéntate en el suelo con las piernas formando un ángulo de 90 grados.', 'Inclina el tronco hacia delante sobre la pierna delantera con la espalda recta.', 'Presiona suavemente la rodilla hacia el suelo sin forzar.', 'Respira profundo y mantén el estiramiento sin rebotes.']::text[], 'principiante', 'Estira glúteos y rotadores de cadera, mejorando la movilidad y aliviando la tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10565'),
('e8b0a3d3-fd34-5e34-8209-19dd4e437381', 'Estiramiento 90 a 90', ARRAY['Siéntate con las piernas flexionadas formando ángulos de 90 grados.', 'Mantén la espalda erguida y lleva el tronco hacia delante con control.', 'Sostén la posición respirando de forma profunda y relajada.', 'Evita forzar la rodilla y no rebotes durante el estiramiento.']::text[], 'principiante', 'Mejora la movilidad de cadera y estira glúteos y aductores, útil para prevenir molestias y ganar rango.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6560'),
('26cfeca4-bd2a-5e3b-8ebc-1c10d53efd8b', 'Abdominal con colchoneta', ARRAY['Túmbate sobre la colchoneta con las rodillas flexionadas y los pies apoyados.', 'Sube el tronco con control llevando el pecho hacia las rodillas.', 'Baja despacio sin apoyar del todo la espalda para mantener la tensión.', 'Espira al subir y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Refuerza la zona abdominal con un recorrido completo, mejorando la fuerza del core y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6555'),
('ce653e7e-97b0-5045-882b-7609930542c3', 'Abdominal con rueda', ARRAY['Colócate de rodillas con la rueda en el suelo bajo los hombros.', 'Agarra los mangos y avanza despacio hacia delante manteniendo la espalda neutra.', 'Tira con el abdomen para volver a la posición inicial sin arquear la zona lumbar.', 'Evita sacar la cadera o dejar caer la barriga durante el recorrido.']::text[], 'intermedio', 'Trabaja el abdomen y el core en profundidad, mejorando la estabilidad y la fuerza del centro del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2269'),
('74fdcf21-406f-5b7e-a9f6-ef041553c463', 'Abdominal encogido en suelo', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Encoge el tronco llevando las costillas hacia la pelvis sin tirar del cuello.', 'Espira al subir y baja controlando el movimiento.', 'No enganches las manos detrás de la cabeza ni uses impulso.']::text[], 'intermedio', 'Activa la parte alta del abdomen y los flexores de cadera para ganar fuerza en el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6033'),
('5e6bee9b-cfa6-5e1d-a008-c471c09bcd57', 'Abdominal en cuatro apoyos', ARRAY['Colócate en cuadrupedia con manos bajo hombros y rodillas bajo caderas.', 'Activa el abdomen y mantén la espalda recta sin hundir la zona lumbar.', 'Respira de forma constante mientras aguantas la posición.', 'Evita elevar la cadera o dejar caer la cabeza.']::text[], 'intermedio', 'Fortalece el core y los hombros en isométrico, mejorando la estabilidad y el control postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4348'),
('17598694-04c4-556f-a95f-8727db2354f4', 'Estiramiento abdominal', ARRAY['Túmbate boca abajo con las manos bajo los hombros.', 'Empuja el suelo para elevar el pecho manteniendo la cadera apoyada.', 'Respira profundo y mantén el estiramiento sin forzar la lumbar.', 'No subas demasiado si notas molestia en la espalda baja.']::text[], 'principiante', 'Estira el abdomen y los flexores de cadera, aliviando tensión tras entrenar el core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3244'),
('91ddf07d-865c-582d-acd7-6a39eff02646', 'Estiramiento de abducción de una pierna con flexión', ARRAY['Siéntate con una pierna extendida y la otra flexionada.', 'Lleva la pierna flexionada hacia fuera y acerca el pie a la ingle.', 'Inclínate suavemente hacia la pierna extendida manteniendo la espalda recta.', 'Respira y evita rebotar para no forzar la articulación.']::text[], 'principiante', 'Estira aductores e ingles, mejorando la movilidad de la cadera y la flexibilidad interna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1906'),
('49b1cbc0-5e29-580e-a20c-1a12d2078822', 'Estiramiento de pecho sobre la cabeza', ARRAY['De pie, entrelaza las manos y estira los brazos por encima de la cabeza.', 'Lleva los brazos ligeramente hacia atrás abriendo el pecho.', 'Mantén la espalda recta y respira de forma pausada.', 'Evita arquear en exceso la zona lumbar.']::text[], 'principiante', 'Estira el pectoral y la parte frontal del hombro, útil tras empujes y para mejorar la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1777'),
('356569df-c192-5a32-95e9-bcaf6b71dd16', 'Estiramiento de aducción de mano con codo extendido', ARRAY['Extiende un brazo al frente con el codo recto y la palma hacia abajo.', 'Con la otra mano, lleva los dedos hacia abajo suavemente.', 'Mantén el estiramiento sin dolor y respira con calma.', 'Evita forzar la muñeca o rebotar.']::text[], 'principiante', 'Estira antebrazo y muñeca, aliviando tensión tras agarres y trabajo de fuerza.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2098'),
('7a270b98-b3a3-5ae5-957d-977bf44492df', 'Estiramiento de aducción del brazo hacia la espalda', ARRAY['Lleva un brazo por detrás de la espalda con el codo flexionado.', 'Con la otra mano, empuja suavemente el codo hacia dentro.', 'Mantén el pecho abierto y respira de forma constante.', 'No fuerces si notas pinchazo en el hombro.']::text[], 'principiante', 'Estira el hombro y el tríceps, mejorando la movilidad del brazo detrás del cuerpo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1977'),
('74b85603-80d9-51a2-b62e-f4322c6f470d', 'Estiramiento de aductores', ARRAY['Siéntate con las plantas de los pies juntas y las rodillas hacia fuera.', 'Sujeta los pies y acerca los talones al cuerpo sin forzar.', 'Inclínate ligeramente hacia delante manteniendo la espalda recta.', 'Respira y evita presionar las rodillas hacia abajo con fuerza.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, mejorando la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4512'),
('46cf31f0-1682-517a-a814-5a3457c1a4d3', 'Ejercicio de agilidad con balón', ARRAY['Coloca el balón delante y adopta una postura atlética con rodillas flexionadas.', 'Realiza desplazamientos rápidos y toques al balón alternando pies.', 'Mantén el abdomen activo y la mirada al frente.', 'Evita perder la postura por ir demasiado rápido.']::text[], 'intermedio', 'Mejora la coordinación, la agilidad y la capacidad cardiovascular con cambios rápidos de ritmo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5967'),
('8d91d959-7200-5310-b39c-72f3c352ee97', 'Bicicleta en el aire', ARRAY['Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.', 'Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.', 'Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.', 'Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.', 'Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con pedaleo en el suelo, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0003'),
('0b19982e-4d9f-5ed6-96e3-a7413e4e4381', 'Sentadilla al aire', ARRAY['Ponte de pie con los pies a la anchura de los hombros.', 'Baja flexionando rodillas y cadera como si fueras a sentarte.', 'Mantén el pecho alto y las rodillas alineadas con los pies.', 'Empuja con los talones para subir y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con el propio peso, mejorando fuerza y control en piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3948'),
('d9e29048-0e48-5feb-89f4-9ceeab5f1858', 'Abdominal con giro en el aire', ARRAY['Túmbate boca arriba con las manos detrás de la cabeza y las piernas elevadas.', 'Encoge el tronco y gira el torso llevando un codo hacia la rodilla contraria.', 'Alterna los lados con control y espira en cada giro.', 'Evita tirar del cuello o usar impulso.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con rotación, mejorando la fuerza y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5266'),
('ed54259c-97b2-52aa-a646-325598c9482b', 'Estiramiento en cuadrupedia', ARRAY['Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.', 'Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.', 'Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.', 'Mantén esta posición durante 20-30 segundos.', 'Cambia de pierna y repite el estiramiento del otro lado.']::text[], 'principiante', 'Estira cuádriceps, isquiotibiales y glúteos en cuadrupedia, aliviando tensión y mejorando la movilidad de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1512'),
('3e92ed8e-2bd6-5dda-82bd-c57aee0b9ee0', 'Sentadilla con toque alterno de talón y patada lateral', ARRAY['De pie, baja en sentadilla manteniendo el pecho alto.', 'Al subir, toca un talón y lanza una patada lateral controlada.', 'Alterna los lados manteniendo el abdomen activo.', 'Evita perder el equilibrio por hacer el movimiento demasiado rápido.']::text[], 'intermedio', 'Combina fuerza de piernas y core con coordinación, mejorando el equilibrio y la agilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3479'),
('a1bcdd15-12f8-5f22-932e-4c1df88cddc3', 'Toque alterno de talones', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Extiende los brazos hacia los lados, paralelos al suelo.', 'Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.', 'Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con un gesto corto y controlado, ideal para calentar el core antes de entrenar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0006'),
('b19cfe23-004b-5b7d-9db1-87085e28f872', 'Salto alto alterno', ARRAY['Colócate de pie con los pies a la anchura de las caderas y el tronco erguido.', 'Salta hacia arriba alternando la pierna que impulsa y cae suavemente con la rodilla ligeramente flexionada.', 'Mantén los brazos activos acompañando el salto y respira de forma rítmica.', 'Evita caer con las piernas rígidas o juntar las rodillas hacia dentro.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y potencia piernas y glúteos con un trabajo explosivo de bajo impacto articular si se controla la caída.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4918'),
('4cb02f06-f3a4-591b-8651-0ce3ea1611da', 'Jalón lateral alterno', ARRAY['Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal y los romboides con un tirón lateral que también solicita bíceps, útil para ganar amplitud de espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0007'),
('0fabcb59-942e-568a-879d-514910f366a3', 'Elevación de piernas alterna', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos a los lados o bajo la cadera.', 'Eleva una pierna hasta unos 90 grados manteniendo la zona lumbar pegada al suelo.', 'Baja la pierna despacio sin tocar el suelo y alterna con la otra.', 'Evita arquear la espalda o usar impulso para subir la pierna.']::text[], 'intermedio', 'Fortalece el abdomen bajo y los flexores de cadera alternando piernas, mejorando la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4826'),
('e17d699e-ba90-512f-b3e8-784726582d9b', 'Elevación alterna de piernas con cabeza arriba', ARRAY['Túmbate boca arriba con las piernas estiradas y eleva ligeramente la cabeza y los hombros.', 'Mantén la zona lumbar apoyada y el abdomen activo durante todo el ejercicio.', 'Sube una pierna hasta unos 90 grados y bájala controlando, luego alterna.', 'Evita tirar del cuello con las manos o despegar la lumbar del suelo.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con la cabeza elevada, reduciendo la tensión cervical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4001'),
('6fd8ce16-538e-5ac9-8819-64a7c98de5a9', 'Elevación alterna de piernas tumbado en el suelo', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Activa el abdomen y pega la zona lumbar al suelo antes de empezar.', 'Eleva una pierna hasta unos 90 grados y bájala despacio sin tocar el suelo, alternando.', 'Evita arquear la espalda o balancear las piernas con impulso.']::text[], 'intermedio', 'Refuerza el abdomen bajo y los flexores de cadera desde el suelo, mejorando el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3590'),
('03881f7f-09c5-58df-a670-b68b4e9cd28e', 'Golpes alternados', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y las manos a la altura del pecho.', 'Lanza un puñetazo al frente y recógelo mientras lanzas el otro, alternando.', 'Mantén el abdomen activo y rota ligeramente el tronco con cada golpe.', 'Evita bloquear los codos o encoger los hombros durante el movimiento.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa hombros, tríceps y core con golpes alternos, mejorando la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3531'),
('6b4b27b9-c933-5a75-bc3c-4929eb97252c', 'Flexión alterna de hombro de espaldas a la pared', ARRAY['Colócate de espaldas a la pared con talones, glúteos y cabeza en contacto.', 'Eleva un brazo estirado por delante hasta donde puedas sin despegar la espalda.', 'Baja despacio y alterna con el otro brazo manteniendo el abdomen activo.', 'Evita arquear la lumbar o encoger el hombro al subir el brazo.']::text[], 'principiante', 'Mejora la movilidad del hombro y la postura, activando deltoides y estabilizadores del tronco contra la pared.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4394'),
('d4211910-4901-5ffc-bd27-5ece646d3165', 'Zancada de sprinter alterna', ARRAY['Colócate de pie y da un paso largo al frente como si fueras a esprintar.', 'Baja la rodilla trasera y apoya la mano delantera en el suelo si te ayuda a estabilizarte.', 'Impulsa con la pierna delantera para cambiar de lado de forma dinámica.', 'Evita que la rodilla delantera se vaya hacia dentro o que el tronco se hunda.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquiotibiales con un gesto explosivo, mejorando la potencia y el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3480'),
('14d1cacf-55c5-5030-9ab7-fe6dd7a0d003', 'Elevación alterna de piernas rectas en bosu', ARRAY['Túmbate boca arriba con la zona lumbar apoyada sobre el bosu y las piernas estiradas.', 'Sube una pierna recta hasta la vertical mientras la otra permanece a pocos centímetros del suelo.', 'Baja la pierna con control sin arquear la espalda y alterna el movimiento.', 'Espira al subir y evita impulsarte con la lumbar o despegar la cadera del bosu.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera mejorando el control del core sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1186'),
('0226df03-9351-5919-9b50-e0e8e94c94e2', 'Toque alterno de punta con elevación de pierna', ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas a unos noventa grados.', 'Baja una pierna hasta tocar el suelo con la punta del pie sin despegar la lumbar.', 'Vuelve a subirla y repite con la otra pierna de forma alterna.', 'Mantén el ombligo hacia dentro y evita arquear la espalda al bajar la pierna.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un gesto controlado que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5106'),
('7657327f-c406-5111-998b-8b9eb827fd33', 'Colgado alterno en barra', ARRAY['Cuélgate de la barra con las manos a la anchura de los hombros y los brazos estirados.', 'Relaja los hombros y deja que el peso del cuerpo estire la columna.', 'Balancea suavemente el cuerpo de lado a lado sin perder el control.', 'Respira de forma pausada y evita soltar la barra de golpe al terminar.']::text[], 'principiante', 'Estira la espalda y los dorsales mientras fortalece el agarre y descomprime los hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10438'),
('35f944b2-1967-5456-be94-d3ec3ec12cf2', 'Curl de femoral alterno con golpes', ARRAY['Túmbate boca abajo con las piernas estiradas y los brazos flexionados junto al pecho.', 'Flexiona una rodilla llevando el talón al glúteo mientras das un golpe al frente con el brazo contrario.', 'Baja la pierna y alterna el lado manteniendo el abdomen activo.', 'Evita arquear la lumbar y mantén un ritmo constante durante toda la serie.']::text[], 'intermedio', 'Combina trabajo de isquios y glúteos con un estímulo cardiovascular de brazos para elevar las pulsaciones.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4437'),
('b020207f-21b3-555a-90f6-e2a760ae2381', 'Paso de rodillas a media rodilla', ARRAY['Colócate de rodillas con la espalda recta y el abdomen activo.', 'Adelanta un pie y apoya la planta para quedar en media rodilla.', 'Empuja con la pierna delantera para volver a la posición de rodillas y alterna.', 'Mantén la cadera estable y evita inclinar el tronco hacia los lados.']::text[], 'principiante', 'Mejora la movilidad de cadera y la fuerza de glúteos con un patrón de arrodillarse controlado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10058'),
('b6811733-6bff-5188-9f61-f6288e75bd97', 'Paso lateral alterno', ARRAY['De pie, con las rodillas ligeramente flexionadas y el pecho erguido.', 'Da un paso amplio hacia un lado y lleva el peso a esa pierna.', 'Junta la otra pierna y repite hacia el lado contrario de forma alterna.', 'Mantén un ritmo ágil y evita cruzar los pies o perder el equilibrio.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca con un desplazamiento lateral que activa piernas y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4436'),
('bdf47ae0-ce5a-5cac-ab05-5d5f80311a50', 'Superman alterno', ARRAY['Túmbate boca abajo con los brazos estirados por delante y las piernas rectas.', 'Eleva a la vez el brazo derecho y la pierna izquierda separándolos del suelo.', 'Mantén dos segundos arriba y baja con control antes de cambiar de lado.', 'Respira de forma constante sin aguantar el aire en la posición alta.', 'Evita arquear en exceso el cuello mirando siempre al suelo.']::text[], 'intermedio', 'Fortalece la zona lumbar y los glúteos mientras mejora la estabilidad del core y la extensión de la columna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4702'),
('802c51ab-d650-57d5-bacc-cd3475212b2b', 'Postura de descanso del animal', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Desplaza las caderas hacia atrás sentándote sobre los talones.', 'Estira los brazos hacia delante y apoya la frente en el suelo.', 'Respira profundo y mantén la postura entre treinta segundos y un minuto.', 'Evita levantar los talones o forzar las rodillas si notas molestia.']::text[], 'intermedio', 'Estira la columna, los dorsales y las caderas, liberando tensión tras sesiones intensas o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4365'),
('67791fef-7df6-5569-90f1-29bd20b0b0c2', 'Dorsiflexión de tobillo', ARRAY['Siéntate o túmbate con la pierna estirada y el pie relajado.', 'Lleva la punta del pie hacia la tibia sin mover la rodilla.', 'Mantén la posición dos segundos y vuelve despacio a la posición neutra.', 'Realiza entre diez y quince repeticiones por pie respirando con calma.', 'Evita girar el pie hacia fuera para compensar la falta de rango.']::text[], 'principiante', 'Gana movilidad en el tobillo y activa la tibial para mejorar la sentadilla y prevenir molestias en la rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2761'),
('6a8dbcb2-1ea4-5c9c-bcb2-7f618fb2d73e', 'Flexión plantar de tobillo', ARRAY['Siéntate con la pierna estirada y el pie sin apoyar tensión.', 'Empuja la punta del pie hacia delante como si pisaras un pedal.', 'Aguanta un segundo abajo y regresa de forma controlada.', 'Haz de diez a quince repeticiones por pie con respiración fluida.', 'Evita mover la rodilla o rotar el pie durante el recorrido.']::text[], 'principiante', 'Moviliza el tobillo y activa gemelos y sóleo, mejorando el empuje en carrera y en los saltos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2762'),
('35337c62-ae62-5908-8dcf-f8bcf81c4360', 'Bicicleta acuática', ARRAY['Siéntate en la bicicleta sumergida con la espalda apoyada y los pies en los pedales.', 'Pedalea a un ritmo cómodo durante dos minutos para entrar en calor.', 'Aumenta la cadencia o la resistencia manteniendo el torso estable.', 'Respira de forma rítmica sin bloquear los hombros ni encorvar la espalda.', 'Baja el ritmo al final para recuperar antes de salir del agua.']::text[], 'intermedio', 'Trabajo cardiovascular de bajo impacto que fortalece piernas y core aprovechando la resistencia del agua.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10729'),
('e0c83aa2-19b4-59a0-ab7f-07c29244942e', 'Dominada arquero', ARRAY['Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.', 'Activa el core y lleva los omóplatos hacia abajo y atrás.', 'Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.', 'Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.', 'Alterna los lados en cada repetición.']::text[], 'avanzado', 'Variante unilateral de dominada que aumenta la exigencia de dorsales y bíceps y prepara para la dominada a una mano.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3293'),
('527daa6b-45e4-5c5f-963c-81ce03da61ea', 'Flexión arquero', ARRAY['Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.', 'Extiende un brazo hacia el lado, paralelo al suelo.', 'Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.', 'Empuja hacia arriba para volver a la posición inicial.', 'Repite del otro lado, extendiendo el brazo opuesto hacia el lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'avanzado', 'Flexión unilateral que carga más un pectoral y exige control del core y de los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3294'),
('0a1f7ea5-46e6-52e9-a3e0-fe9f22388551', 'Postura de torsión sentada', ARRAY['Siéntate con las piernas estiradas y flexiona la rodilla derecha cruzando el pie por fuera.', 'Gira el torso hacia la derecha y apoya la mano izquierda en la rodilla.', 'Alarga la columna al inspirar y profundiza la torsión al espirar.', 'Mantén de treinta segundos a un minuto y cambia de lado.', 'Evita tirar del cuello o forzar la rodilla si notas molestia.']::text[], 'intermedio', 'Torsión de yoga que moviliza la columna, estira oblicuos y caderas y mejora la rotación torácica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6121'),
('16db134a-ea64-5ef2-a140-c7ca075a37ec', 'Círculos de brazos', ARRAY['Ponte de pie con los brazos extendidos en cruz a la altura de los hombros.', 'Dibuja círculos pequeños hacia delante aumentando el radio poco a poco.', 'Completa quince repeticiones y cambia el sentido del giro.', 'Respira con normalidad y mantén los hombros lejos de las orejas.', 'Evita encorvar la espalda o mover el torso para acompañar el gesto.']::text[], 'principiante', 'Calienta hombros y manguito rotador, mejora la movilidad del hombro y prepara para el entrenamiento de tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3905'),
('83f075ce-1603-5dc0-b39e-a2b11fb29fb0', 'Estiramiento de rotadores con brazo abajo', ARRAY['Ponte de pie y lleva el brazo estirado por delante del cuerpo a la altura del pecho.', 'Con la otra mano empuja suavemente el codo hacia el pecho.', 'Mantén el hombro relajado y la espalda recta durante veinte o treinta segundos.', 'Respira despacio y cambia de brazo.', 'Evita tirar del codo con fuerza o encoger el hombro estirado.']::text[], 'principiante', 'Estira el manguito rotador y la parte posterior del hombro, aliviando tensión tras empujes o presses.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1987'),
('b3771702-02e8-5c11-b582-8a5eff6bf76c', 'Elevación de brazos con paso en el lugar', ARRAY['Ponte de pie con los brazos a los lados y el abdomen ligeramente activo.', 'Marcha en el sitio elevando las rodillas mientras subes los brazos por encima de la cabeza.', 'Baja los brazos al tiempo que apoyas el pie y alterna el ritmo.', 'Mantén un ritmo constante durante uno o dos minutos respirando sin agobios.', 'Evita encorvar la espalda o golpear el suelo con fuerza al pisar.']::text[], 'intermedio', 'Ejercicio cardiovascular suave que eleva la frecuencia cardíaca y activa hombros, cuádriceps y gemelos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '6014'),
('375960c1-7828-5267-ab44-886eebe4f4de', 'Colgado con piernas flexionadas', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.', 'Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y la fuerza de agarre colgado de la barra, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2355'),
('db59f4fa-344d-561c-b5de-840e21c3fb4c', 'Estiramiento de oración sin brazos', ARRAY['Arrodíllate y siéntate sobre los talones con el torso inclinado hacia delante.', 'Estira los brazos hacia delante apoyando las palmas en el suelo.', 'Baja el pecho hacia las rodillas sin levantar la cadera de los talones.', 'Respira profundo y mantén entre veinte y treinta segundos.', 'Evita forzar el cuello o separar los glúteos de los talones.']::text[], 'principiante', 'Estira dorsales y hombros desde una posición baja, aliviando tensión de la espalda tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6539'),
('ef833d94-2209-5b6b-93f3-179db1b3c162', 'Toque de pies en círculo con brazos abiertos', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.', 'Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.', 'Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.', 'Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Movilidad dinámica que activa glúteos, isquios y cuádriceps mientras mejora la coordinación y el rango de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3214'),
('d00cde26-6f7c-536b-ac1d-344e5bf9ba05', 'Abdominal completo con brazos sobre la cabeza', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Extiende los brazos por encima de la cabeza, manteniéndolos rectos.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el recto abdominal y los flexores de cadera con un recorrido completo del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3204'),
('b5d3e0a9-9673-599d-b4ae-a03b475bfb0b', 'Estiramiento de brazos sobre un apoyo', ARRAY['Coloca las manos sobre un apoyo a la altura de la cadera con los dedos hacia atrás.', 'Da un paso atrás y baja el pecho hacia el suelo manteniendo los codos casi rectos.', 'Siente el estiramiento en bíceps y antebrazos y respira despacio sin rebotar.', 'Evita bloquear los codos o forzar el hombro si notas pinchazo.']::text[], 'principiante', 'Estira bíceps y antebrazos, alivia la tensión del tren superior y mejora la movilidad del hombro tras entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1817'),
('121f71bb-bb37-5af1-a680-8416720193f1', 'Superman alrededor del mundo', ARRAY['Túmbate boca abajo con brazos y piernas extendidos y el cuello en línea.', 'Eleva brazos, pecho y piernas del suelo apretando glúteos y espalda.', 'Dibuja círculos amplios con los brazos manteniendo el tronco elevado.', 'Respira de forma continua y evita arquear en exceso el cuello.']::text[], 'intermedio', 'Fortalece la espalda baja y los glúteos mientras activa escápulas y cadena posterior en control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4935'),
('b4979d18-31f7-50b3-a382-83fb9290f2b3', 'Sostén de superman alrededor del mundo', ARRAY['Túmbate boca abajo con brazos extendidos al frente y piernas estiradas.', 'Eleva brazos, pecho y piernas y mantén la posición sin tocar el suelo.', 'Desplaza los brazos en círculo lento manteniendo el tronco elevado.', 'Respira con normalidad y evita levantar la cabeza en exceso.']::text[], 'intermedio', 'Isométrico que activa glúteos y espalda baja, mejorando la estabilidad del tronco y la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3483'),
('c0074f1a-7451-5917-ba8d-94730069cafc', 'Carrera en bicicleta assault', ARRAY['Ajusta el sillín y siéntate con la espalda recta y las manos en los manillares.', 'Empieza pedaleando suave para entrar en calor durante un minuto.', 'Aumenta el ritmo alternando empuje con brazos y piernas de forma coordinada.', 'Mantén la respiración constante y evita encorvar la espalda al fatigarte.']::text[], 'principiante', 'Trabajo cardiovascular intenso que implica piernas y tronco, ideal para mejorar resistencia y capacidad pulmonar.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3893'),
('06cf7b49-f58f-50c3-95d7-b54c8ddd2a51', 'Carrera assault', ARRAY['Colócate de pie con el torso erguido y la mirada al frente.', 'Comienza a trotar en el sitio elevando las rodillas de forma progresiva.', 'Acelera el ritmo y acompaña el movimiento con los brazos.', 'Respira de forma rítmica y evita caer hacia delante con el tronco.']::text[], 'intermedio', 'Carrera de alta intensidad que eleva la frecuencia cardíaca y fortalece piernas y glúteos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4229'),
('750da399-0fcc-5f99-8bfb-912969b4c1e5', 'Sentadilla búlgara asistida', ARRAY['Apoya el empeine del pie trasero en un banco y sujétate a un apoyo delante.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo con control.', 'Empuja con el talón delantero para subir manteniendo el torso erguido.', 'Evita que la rodilla delantera se vaya hacia dentro y respira al subir.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4442'),
('6fcaa184-677f-5cb3-ab3a-f9bef5e512e5', 'Fondos para pecho asistidos de rodillas', ARRAY['Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.', 'Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja pectorales y tríceps con ayuda de la máquina, ideal para progresar hacia fondos completos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0009'),
('daad15bc-dfe3-592a-a08b-9c20c36e45e6', 'Dominadas asistidas supinas en barra baja', ARRAY['Agarra la barra con las palmas hacia ti a la anchura de los hombros.', 'Cuelga con los brazos extendidos y los hombros activos sin encogerlos.', 'Tira de los codos hacia abajo hasta llevar el pecho cerca de la barra.', 'Baja de forma controlada sin soltar la tensión y evita balancearte.']::text[], 'principiante', 'Refuerza dorsales y bíceps con agarre supino, facilitando el aprendizaje de la dominada completa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4716'),
('b9573a9d-9a37-5071-8d7a-0ce0ada8783b', 'Dominadas asistidas supinas con agarre cerrado', ARRAY['Agarra la barra con las palmas hacia ti y las manos juntas.', 'Cuelga con los brazos estirados y el core activado.', 'Sube llevando el pecho a la barra sin encoger los hombros.', 'Baja despacio controlando el movimiento y evita usar impulso.']::text[], 'principiante', 'Enfoca dorsales y bíceps con agarre estrecho, aumentando la fuerza de tracción del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1222'),
('0116b537-b0de-562b-9ec6-1f0642c82a57', 'Dominada comando asistida', ARRAY['Coloca una mano delante y otra detrás en la barra con agarre mixto.', 'Cuelga con los brazos extendidos y el tronco firme.', 'Tira hacia un lado llevando el hombro hacia la barra y alterna lados.', 'Mantén el core activo y evita girar la cadera al subir.']::text[], 'principiante', 'Trabaja dorsales y oblicuos con agarre mixto, mejorando la fuerza y la coordinación del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4717'),
('d8702b95-7fdc-5cb2-823b-ee644d3621c8', 'Elevación de rodillas colgado asistida', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.', 'Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el abdomen y los flexores de cadera con apoyo, ideal para progresar en core colgado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0011'),
('513ebb68-f76c-5202-ad49-176eba3850f9', 'Elevación de rodillas colgado asistida con lanzamiento', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.', 'Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.', 'Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado.']::text[], 'principiante', 'Potencia abdomen y flexores de cadera con un gesto explosivo controlado en suspensión asistida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0010'),
('0112768b-a614-5ca1-9f4b-9c9ed50d74c9', 'Estiramiento asistido de aductores acostado', ARRAY['Túmbate boca arriba con las piernas flexionadas y los pies apoyados.', 'Abre las rodillas hacia los lados y sujeta los pies con las manos o un apoyo.', 'Acerca suavemente las plantas de los pies y siente el estiramiento en la ingle.', 'Respira profundo y evita forzar si notas molestia en la rodilla.']::text[], 'principiante', 'Relaja la cara interna del muslo y la ingle, mejorando la movilidad de la cadera tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1907'),
('e9c99086-f038-502e-8592-71db78c27f24', 'Estiramiento de glúteos acostado asistido', ARRAY['Túmbate sobre tu espalda con las piernas extendidas.', 'Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.', 'Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta y repite del otro lado.']::text[], 'principiante', 'Libera tensión en glúteos y cadena posterior, mejorando la movilidad de la cadera y el confort lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1709'),
('5df4e2f6-8f33-5816-a918-741463349f19', 'Estiramiento de glúteo y piriforme acostado asistido', ARRAY['Túmbate sobre tu espalda con las piernas extendidas.', 'Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.', 'Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta el estiramiento y repite del otro lado.']::text[], 'principiante', 'Alivia la tensión del glúteo y el piriforme, ayudando a prevenir molestias lumbares y de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1710'),
('d64cf06f-255d-58fa-9744-802b434e7dd9', 'Estiramiento de cadera tumbado boca arriba', ARRAY['Túmbate boca arriba con las piernas flexionadas y los pies apoyados.', 'Cruza un tobillo sobre la rodilla contraria formando una figura de cuatro.', 'Lleva suavemente la rodilla hacia el pecho ayudándote con las manos.', 'Mantén la respiración lenta y evita tirar del cuello o forzar la cadera.']::text[], 'principiante', 'Estira glúteos y flexores de cadera para aliviar la tensión lumbar y mejorar la movilidad de la pelvis.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1932'),
('7aef175a-2af3-5068-abc0-3c70f6810a9b', 'Elevación de piernas tumbado con lanzamiento lateral', ARRAY['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.', 'Coloca las manos debajo de los glúteos como apoyo.', 'Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.', 'Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.', 'Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.', 'Repite el movimiento hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los oblicuos con un gesto controlado que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0012'),
('42575710-80ea-594a-93ed-a0b69f7fff20', 'Elevación de piernas tumbado con lanzamiento', ARRAY['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.', 'Coloca las manos debajo de los glúteos como apoyo.', 'Activa el core y levanta las piernas del suelo, manteniéndolas rectas.', 'Eleva las piernas hasta que queden perpendiculares al suelo.', 'Baja las piernas de vuelta a la posición inicial.', 'Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.', 'Eleva las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la zona abdominal baja y los flexores de cadera con un movimiento dinámico y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0013'),
('24650567-097d-5f69-9219-d4b6796dd8ca', 'Giro ruso', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.', 'Sostén el balón medicinal con ambas manos frente al pecho.', 'Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.', 'Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.', 'Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos rotando el tronco para ganar fuerza y control en la cintura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0014'),
('dbcfa398-1ef6-5653-94c4-a3e86589a936', 'Estiramiento de oblicuos y dorsal en balón', ARRAY['Colócate de rodillas o sentado junto al balón y apoya un antebrazo sobre él.', 'Desliza el balón hacia delante mientras alargas el costado contrario.', 'Mantén la cadera estable y respira despacio sin rebotar.', 'Evita arquear la zona lumbar o girar el tronco en exceso.']::text[], 'principiante', 'Estira la espalda y el costado para descargar la zona lumbar y ampliar la movilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1715'),
('8c934c37-2d08-5c51-a933-7559c84dacd4', 'Estiramiento de oblicuos y glúteo medio', ARRAY['Siéntate o túmbate con una pierna cruzada sobre la otra.', 'Inclina el tronco hacia el lado contrario hasta notar el estiramiento.', 'Ayúdate con la mano para aumentar la tensión de forma progresiva.', 'Respira lento y evita forzar la rodilla o la espalda.']::text[], 'principiante', 'Alivia la tensión en la cadera y el costado, mejorando la movilidad lateral y la comodidad al caminar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1711'),
('891ba3af-738f-5dc6-9005-b10b9238bacf', 'Extensión de pierna asistida', ARRAY['Siéntate o túmbate con la espalda apoyada y una pierna flexionada.', 'Estira la otra pierna despacio ayudándote con las manos o una banda.', 'Mantén la rodilla alineada y el muslo relajado.', 'Evita bloquear la rodilla de golpe o rebotar al final del recorrido.']::text[], 'principiante', 'Mejora la movilidad del cuádriceps y la cadera preparando la pierna para gestos más amplios.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1952'),
('0ce2909f-31b1-52fe-ba2d-602cb2fbc8dc', 'Dominada asistida con agarre cerrado paralelo', ARRAY['Ajusta la máquina al peso y la altura deseados.', 'Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.', 'Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.', 'Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de las barras.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda y los bíceps con un agarre neutro que reduce la tensión en los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0015'),
('83684f6c-5e64-5b91-ace7-db407fef6fe5', 'Sentadilla pistol asistida con sábana', ARRAY['Sujeta la sábana con las dos manos y colócate de pie sobre una pierna.', 'Baja despacio llevando la cadera atrás y la otra pierna al frente.', 'Usa la sábana como apoyo para controlar el descenso y la subida.', 'Mantén la rodilla alineada con el pie y evita que se meta hacia dentro.']::text[], 'avanzado', 'Desarrolla fuerza y equilibrio en una sola pierna trabajando cuádriceps, glúteos y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3747'),
('c44a6305-dd84-5bd4-81ed-41001f5e2b92', 'Estiramiento de cuádriceps boca abajo', ARRAY['Túmbate boca abajo en el suelo con las piernas extendidas.', 'Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.', 'Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.', 'Mantén el estiramiento durante 20-30 segundos, luego suelta.', 'Repite con la pierna derecha.']::text[], 'principiante', 'Relaja la parte delantera del muslo para mejorar la movilidad de la rodilla y la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1713'),
('6f6f4e7c-d6f9-5144-8432-435ea8ab7f9c', 'Estiramiento del recto femoral boca abajo', ARRAY['Túmbate boca abajo en el suelo con las piernas rectas.', 'Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.', 'Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta y repite del otro lado.']::text[], 'principiante', 'Estira la parte alta del cuádriceps y la cadera, útil tras sesiones de carrera o sentadillas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1714'),
('399a585d-2394-5267-a5f8-eb0bdeb548fd', 'Dominada asistida', ARRAY['Ajusta la máquina a los valores de peso y altura deseados.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.', 'Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda y los brazos con ayuda de la máquina para progresar hacia dominadas completas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0017'),
('4e806e25-101f-5bed-b356-e1da4d3616e8', 'Estiramiento de pecho boca abajo', ARRAY['Túmbate boca abajo con un brazo extendido hacia el lado.', 'Gira el tronco hacia el brazo estirado mientras el compañero o el apoyo fija el hombro.', 'Mantén el cuello relajado y respira de forma pausada.', 'Evita levantar el hombro o forzar el giro más allá de lo cómodo.']::text[], 'principiante', 'Abre el pecho y los hombros para contrarrestar posturas encorvadas y mejorar la respiración.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1790'),
('ef53402c-90d4-5d21-9c25-c6b0ee99bbe4', 'Estiramiento de cuello con rotación asistido', ARRAY['Siéntate con la espalda recta y los hombros relajados.', 'Gira la cabeza hacia un lado ayudándote con la mano.', 'Mantén unos segundos sin tirar fuerte ni levantar el hombro.', 'Respira despacio y evita girar en exceso o hacer movimientos bruscos.']::text[], 'principiante', 'Alivia la tensión del cuello y la parte alta de la espalda, mejorando la movilidad cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1843'),
('0a84bb6b-7069-524a-8394-90ffb0872b33', 'Estiramiento de pectoral sentado en balón', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.', 'Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.', 'Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.', 'Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira el pecho y los hombros sentado para descargar la zona anterior del tronco y respirar mejor.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1716'),
('138e42ee-625f-58b8-9aae-088c1061def8', 'Estiramiento de aductores tumbado de lado', ARRAY['Túmbate de lado con las piernas rectas y apiladas una sobre la otra.', 'Flexiona ligeramente la pierna de abajo para mayor estabilidad.', 'Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.', 'Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.', 'Mantén el estiramiento durante 20-30 segundos.', 'Regresa a la posición inicial y repite del otro lado.']::text[], 'principiante', 'Alarga la cara interna del muslo y la cadera, mejorando la movilidad y aliviando tensiones tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1712'),
('d8d1a3c2-842b-58d7-8a98-e43caf1c377e', 'Prensa a una pierna asistida', ARRAY['Coloca el pie sobre la plataforma con la rodilla alineada con el pie.', 'Empuja la plataforma extendiendo la pierna sin bloquear del todo la rodilla.', 'Baja de forma controlada hasta unos 90 grados de flexión.', 'Evita que la rodilla se meta hacia dentro durante el recorrido.', 'Respira soltando el aire al empujar y cogiéndolo al bajar.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1027'),
('246f2664-8def-58fb-abcf-fe612ae651df', 'Abdominal asistido', ARRAY['Siéntate en el borde de un banco o pide a alguien que te sujete los pies.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el recto abdominal y los flexores de cadera, ayudando a ganar fuerza en el core con apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1758'),
('0eec20f9-fec9-5253-b28d-0a7f2ba7edc7', 'Estiramiento de hombro inverso sentado', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Lleva el brazo estirado hacia atrás y agárralo con la mano contraria.', 'Tira suavemente del brazo sin forzar el hombro ni el cuello.', 'Mantén la posición respirando despacio y sin rebotes.', 'Evita encorvar la espalda o subir el hombro mientras estiras.']::text[], 'principiante', 'Estira la parte anterior del hombro y el pecho, útil para contrarrestar posturas encorvadas y ganar movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1973'),
('4c9946f1-a080-5669-a94f-572dd0efc7b6', 'Dominada supina asistida', ARRAY['Ajusta la máquina al nivel de asistencia deseado.', 'Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.', 'Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece dorsales y bíceps con agarre supino, ideal para progresar hacia dominadas completas con menos carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1431'),
('9dc247a4-7064-50b4-8f00-d7a83e0542fd', 'Dominada de pie asistida', ARRAY['Ajusta la máquina a los valores de peso y altura deseados.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Activa los dorsales y los bíceps, y levántate hacia las agarraderas.', 'Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.', 'Bájate lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda y los brazos con ayuda de la máquina, permitiendo dominar el patrón de tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1432'),
('6c6ade29-00e5-5eb0-ae13-6319d8154c44', 'Fondos de tríceps asistidos de pie', ARRAY['Sujeta las asas y colócate con los brazos extendidos y el cuerpo estable.', 'Baja flexionando los codos hacia atrás sin abrirlos en exceso.', 'Detente cuando los codos lleguen a unos 90 grados.', 'Empuja para volver arriba sin encoger los hombros.', 'Evita bajar más de la cuenta o perder la postura del tronco.']::text[], 'principiante', 'Fortalece tríceps, pecho y hombros con apoyo, útil para aprender el patrón de fondos de forma segura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1028'),
('067db4d1-fae8-5d73-8dd6-52ff3a24e4d8', 'Extensión de tríceps asistida con toalla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.', 'Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.', 'Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.', 'Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con ayuda de una toalla, mejorando la fuerza y el control en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0018'),
('8a49cad0-bc27-59eb-afc9-9630b98d9528', 'Fondos de tríceps asistidos de rodillas', ARRAY['Ajusta la máquina al peso y la altura deseados.', 'Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas.', 'Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece tríceps y pecho con asistencia, permitiendo practicar el fondo con menor carga corporal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0019'),
('26db3d97-ad62-5213-87e9-c1ceb6b50cee', 'Estiramiento de pecho con flexión de tronco', ARRAY['Colócate con las manos apoyadas y los brazos abiertos a la altura del pecho.', 'Flexiona el tronco hacia delante llevando la cadera atrás.', 'Siente el estiramiento en el pecho sin forzar los hombros.', 'Respira despacio y mantén la posición sin rebotar.', 'Evita arquear la zona lumbar o encoger el cuello.']::text[], 'principiante', 'Abre el pecho y los hombros mientras flexiona el tronco, mejorando la movilidad torácica y aliviando tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1786'),
('e4db589e-2f80-5c38-8e87-6a4af484a26a', 'Flexión asistida con peso', ARRAY['Coloca las manos algo más anchas que los hombros y el cuerpo alineado.', 'Baja el pecho de forma controlada manteniendo el core firme.', 'Empuja para volver arriba sin bloquear los codos de golpe.', 'Mantén el cuello neutro y evita que la cadera se hunda.', 'Respira cogiendo aire al bajar y soltándolo al empujar.']::text[], 'intermedio', 'Trabaja pecho, tríceps y core con carga añadida y apoyo, ideal para progresar en flexiones.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '1172'),
('096914f6-3c91-59d8-b0ec-97ad4c008daf', 'Fondos para pecho asistidos con agarre abierto', ARRAY['Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.', 'Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfatiza el pecho con un agarre amplio y asistencia, mejorando fuerza y control en el fondo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2364'),
('bd4b3444-7bf5-51ed-9d2f-0628398f8a05', 'Saltos con piernas abiertas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.', 'Salta explosivamente hacia arriba, extendiendo las piernas y los brazos.', 'Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados.', 'Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y glúteos con un ejercicio pliométrico sencillo y explosivo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3220'),
('dd7549da-2bf2-5711-b6cf-cd025dc59e86', 'Paso adelante y atrás', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.', 'Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.', 'Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.', 'Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.', 'Repite durante la duración o el número de repeticiones deseado.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la coordinación mientras activa piernas, glúteos y pantorrillas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3672'),
('d91f062d-68e2-5f6f-9549-0071a2181a09', 'Extensión de espalda en balón', ARRAY['Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.', 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la musculatura de la columna y los glúteos, mejorando la extensión y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1314'),
('cea14060-3ef3-5ea2-a682-e7cd10f8c911', 'Balanceo de pierna adelante y atrás', ARRAY['Apóyate en una pared o barra y mantén el tronco erguido.', 'Balancea una pierna hacia delante y hacia atrás con control, sin forzar el final del recorrido.', 'Deja que el pie llegue alto delante y atrás, pero sin dolor.', 'Respira de forma continua y evita arquear la zona lumbar.', 'Cambia de pierna al terminar la serie.']::text[], 'principiante', 'Moviliza isquiotibiales y flexores de cadera, mejora el rango de zancada y prepara las piernas antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3502'),
('9c544d80-4252-52ba-bc02-7f2030244139', 'Patada atrás con press sobre la cabeza', ARRAY['Colócate de pie con los pies a la anchura de las caderas y el core activo.', 'Lleva una pierna atrás mientras elevas los brazos por encima de la cabeza.', 'Impulsa con la pierna de apoyo y aterriza suave con la rodilla ligeramente flexionada.', 'Evita arquear la espalda al subir los brazos; mantén las costillas abajo.', 'Alterna las piernas y controla el ritmo para no perder el equilibrio.']::text[], 'intermedio', 'Ejercicio pliométrico que combina extensión de cadera y empuje vertical para potenciar hombros y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6097'),
('3c5466f5-8c82-5e01-a30b-8a7bb8765161', 'Back lever', ARRAY['Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Activa el core y lleva los omóplatos hacia abajo y atrás.', 'Flexiona las rodillas y llévalas hacia el pecho.', 'Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.', 'Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Isométrico avanzado que fortalece la espalda alta, bíceps y core manteniendo el cuerpo horizontal en suspensión.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3297'),
('dd0d86a9-cff4-58c7-864e-35611e13e282', 'Estiramiento de espalda y pecho', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Extiende los brazos rectos frente a ti, paralelos al suelo.', 'Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.', 'Entrelaza los dedos y gira las palmas alejándolas del cuerpo.', 'Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.', 'Mantén el estiramiento durante 15-30 segundos, luego suelta.', 'Repite del lado opuesto.']::text[], 'principiante', 'Estira dorsal ancho, hombros y pectoral, aliviando la tensión acumulada por posturas encorvadas frente al ordenador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1405'),
('133cee02-515f-53cb-be73-e3f77954cdc4', 'Relajación de espalda', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Abraza las rodillas hacia el pecho sin levantar la cabeza.', 'Mantén la postura respirando lento y profundo entre 20 y 30 segundos.', 'Baja las piernas despacio y evita hacer rebotes bruscos.', 'Si notas molestia lumbar, apoya los pies en el suelo antes de soltar.']::text[], 'principiante', 'Estiramiento suave que descomprime la columna y relaja lumbares y glúteos tras sesiones largas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1315'),
('72877802-b54f-5b14-a86f-00cf0f4c09be', 'Estiramiento abrazándote la espalda', ARRAY['De pie, cruza los brazos delante del pecho y abraza tus hombros.', 'Redondea la espalda alta mientras llevas los omóplatos hacia delante.', 'Mantén la posición 20 segundos respirando de forma pausada.', 'Evita encoger el cuello; mantén la barbilla ligeramente recogida.', 'Suelta despacio y repite una segunda vez.']::text[], 'principiante', 'Abre escápulas y espalda alta, liberando tensión en hombros y rhomboides después de estudiar o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3995'),
('c7c04840-fd8e-5ccb-b54a-c1a52fa5f387', 'Estiramiento de espalda', ARRAY['Siéntate en el suelo con las piernas estiradas o cruza una pierna.', 'Alarga los brazos hacia delante y redondea la espalda sin forzar.', 'Mantén la posición respirando profundo durante 20 o 30 segundos.', 'Evita tirar de la cabeza con las manos; deja que el cuello caiga relajado.', 'Sube despacio vértebra a vértebra al terminar.']::text[], 'principiante', 'Alarga la musculatura dorsal y lumbar, mejorando la movilidad de la columna y reduciendo rigidez diaria.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1404'),
('38420f06-4275-5330-92f5-77b6e4294f5a', 'Elevación de brazo con dorso de la mano', ARRAY['De pie, extiende los brazos a los lados con las palmas hacia abajo.', 'Eleva los brazos hacia atrás con el dorso de la mano guiando el movimiento.', 'Aprieta los omóplatos al final del recorrido sin encoger los hombros.', 'Baja con control y evita usar impulso del tronco.', 'Respira al elevar y mantén el core activo.']::text[], 'intermedio', 'Trabaja deltoides posterior y espalda alta, útil para equilibrar el empuje y mejorar la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4663'),
('70881f33-8ed8-57a0-8c3c-bcfd624a1c6a', 'Estiramiento abdominal hacia atrás', ARRAY['Túmbate boca abajo con las manos bajo los hombros.', 'Empuja el suelo y eleva el pecho mientras llevas la cadera hacia delante.', 'Mantén la posición 15 o 20 segundos sin forzar la lumbar.', 'Evita echar la cabeza atrás; mira al frente.', 'Baja despacio y repite si lo necesitas.']::text[], 'principiante', 'Estira abdomen y flexores de cadera, contrarrestando el acortamiento por estar muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4006'),
('d4dbfb7a-3f64-57da-8898-1c0434b2d1f6', 'Salto hacia atrás', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.', 'Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Pliometría que desarrolla potencia en cuádriceps, glúteos y gemelos, mejorando la explosividad y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1473'),
('09f3f907-ccc2-5d63-8fa3-caa5d5d17909', 'Movilización de hombros con empuje atrás', ARRAY['De pie, lleva los brazos a la altura de los hombros con los codos flexionados.', 'Empuja los codos hacia atrás abriendo el pecho sin arquear la lumbar.', 'Mantén un segundo al final y vuelve despacio al frente.', 'Evita encoger los hombros hacia las orejas.', 'Respira de forma continua durante toda la serie.']::text[], 'principiante', 'Moviliza el hombro y el manguito rotador, preparando la articulación antes de empujes y presses.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11795'),
('e90b1096-559d-584b-b066-99f82c4cc885', 'Carrera hacia atrás', ARRAY['Busca un espacio despejado y llano para correr hacia atrás.', 'Mantén el tronco erguido y mira por encima del hombro para orientarte.', 'Da pasos cortos y rápidos apoyando la planta del pie con suavidad.', 'Evita inclinarte demasiado hacia atrás; mantén el core activo.', 'Empieza con tramos cortos y aumenta la duración de forma progresiva.']::text[], 'intermedio', 'Cardio que activa cuádriceps, gemelos y glúteos, mejorando la coordinación y la fuerza de la cadena posterior.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4258'),
('4e1e2cec-aac5-5220-9536-0c13379d2c04', 'Equilibrio con toque de punta en tres puntos', ARRAY['Apóyate en una pierna con la rodilla ligeramente flexionada.', 'Toca el suelo con la punta del otro pie delante, al lado y detrás.', 'Mantén la cadera nivelada y el core activo en cada toque.', 'Evita bloquear la rodilla de apoyo o perder la verticalidad.', 'Cambia de pierna al completar los tres puntos.']::text[], 'principiante', 'Mejora el equilibrio y la estabilidad de glúteo medio, tobillo y core sobre una sola pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11790'),
('4aee8ebd-b34f-532b-8e94-a9a9288b4ac2', 'Tabla de equilibrio', ARRAY['Coloca la tabla de equilibrio sobre una superficie plana.', 'Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.', 'Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.', 'Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.', 'Repite el ejercicio con el otro pie.']::text[], 'principiante', 'Entrena la propiocepción y estabilidad del tobillo, mejorando el control postural y previniendo esguinces.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0020'),
('828d5153-8e8b-574e-8a6e-fbfd79b5b42b', 'Equilibrio a una pierna en tabla de equilibrio', ARRAY['Súbete a la tabla de equilibrio y apoya una sola pierna en el centro.', 'Mantén la rodilla ligeramente flexionada y la mirada al frente.', 'Activa el core y evita bloquear la cadera.', 'Aguanta entre 20 y 30 segundos respirando con normalidad.', 'Baja con control y cambia de pierna.']::text[], 'principiante', 'Trabaja gemelos, tobillo y core manteniendo el equilibrio sobre una pierna en superficie inestable.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10733'),
('f4f525b2-79dc-54fd-b731-e67c94222f12', 'Equilibrio a una pierna sobre almohadilla', ARRAY['Coloca la almohadilla en el suelo y apoya un pie en el centro con la rodilla ligeramente flexionada.', 'Eleva la otra pierna y mantén la mirada al frente con el abdomen activo.', 'Aguanta la posición respirando con normalidad durante el tiempo indicado.', 'Evita bloquear la rodilla o inclinar el tronco; corrige apoyando el pie libre si pierdes el equilibrio.']::text[], 'principiante', 'Trabaja tobillos, gemelos y core para mejorar la estabilidad y prevenir esguinces en superficies inestables.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10734'),
('81749c1a-73d5-5e41-bedc-3a25abc043fa', 'Aducción isométrica de cadera tumbado con balón', ARRAY['Túmbate boca arriba con las rodillas flexionadas y coloca el balón entre ellas.', 'Aprieta el balón con las rodillas sin mover las piernas y mantén la presión.', 'Respira de forma continua y evita aguantar la respiración durante la contracción.', 'No eleves la pelvis ni arquees la zona lumbar; mantén el abdomen activo.']::text[], 'principiante', 'Activa los aductores y la cara interna del muslo manteniendo una presión constante que refuerza la estabilidad de la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9994'),
('7f87f6b7-f74c-5fd4-a6de-9e8cc1f0658d', 'Aducción de cadera tumbado con balón', ARRAY['Túmbate boca arriba con el balón entre las rodillas flexionadas y los pies apoyados.', 'Aprieta el balón juntando las rodillas de forma controlada y mantén un segundo arriba.', 'Vuelve despacio a la posición inicial sin dejar caer el balón.', 'Evita empujar con la zona lumbar o subir la pelvis durante el movimiento.']::text[], 'principiante', 'Fortalece los aductores y la cara interna del muslo con un movimiento controlado que mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10014'),
('55ee4e23-f33a-5485-bae1-d0083bcb5d8a', 'Abdominal en balón', ARRAY['Siéntate sobre el balón con los pies fijos en el suelo y las manos en la nuca.', 'Baja el tronco siguiendo la curva del balón y sube contrayendo el abdomen.', 'Espira al subir y controla la bajada sin dejarte caer.', 'Evita tirar del cuello con las manos; mantén la barbilla separada del pecho.']::text[], 'principiante', 'Refuerza el recto abdominal y los oblicuos con un recorrido más amplio gracias a la superficie curva del balón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0021'),
('2ce29437-d660-5828-b612-f9207f5164f5', 'Ejercicio con globo', ARRAY['Coloca el globo en el suelo y sitúate de pie frente a él con los pies a la anchura de las caderas.', 'Salta por encima del globo con un impulso rápido y cae con las rodillas ligeramente flexionadas.', 'Amortigua cada aterrizaje y mantén el tronco erguido durante el salto.', 'Evita caer con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Combina saltos y control postural para potenciar cuádriceps, glúteos y core con un trabajo pliométrico ligero.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5985'),
('44311140-c59c-5312-b312-1918a83734b4', 'Curl de bíceps a 45 grados con banda', ARRAY['Pisa la banda con los pies y sujeta los extremos con las palmas hacia delante.', 'Lleva los codos ligeramente atrás y flexiona los brazos hasta unos 45 grados.', 'Sube contrayendo el bíceps y baja controlando la banda sin dejar que tire de ti.', 'Evita balancear el tronco o adelantar los codos para completar la repetición.']::text[], 'principiante', 'Aísla el bíceps y el braquial desde un ángulo que mantiene tensión constante en la parte media del recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4087'),
('8cec28e8-3102-51bc-80fb-8621517c7101', 'Bicicleta en el aire con banda', ARRAY['Túmbate boca arriba con la banda sujeta con las manos y los pies en el aire.', 'Lleva una rodilla hacia el pecho mientras extiendes la otra pierna y alterna.', 'Mantén la zona lumbar pegada al suelo y espira en cada acercamiento.', 'Evita tirar del cuello o arquear la espalda al cambiar de pierna.']::text[], 'principiante', 'Trabaja el abdomen, los oblicuos y los flexores de cadera con un movimiento alterno que exige control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4699'),
('551a6e84-36a5-59bd-9633-8b0ec2219369', 'Curl de bíceps alterno con banda', ARRAY['Pisa la banda con los pies y sujeta los extremos con los brazos extendidos.', 'Flexiona un codo llevando la mano al hombro y baja despacio antes de cambiar.', 'Mantén los codos pegados al torso y espira al subir.', 'Evita girar el tronco o usar impulso para levantar la banda.']::text[], 'principiante', 'Fortalece bíceps y antebrazos con un trabajo alterno que permite concentrarte en cada brazo por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0005'),
('e5c73725-9ac6-5bd5-b034-50e73e506adf', 'Press de pecho inclinado alterno con giro y banda', ARRAY['Ancla la banda a la espalda o a un punto bajo y sujeta los extremos a la altura del pecho.', 'Empuja una mano hacia delante y arriba girando el torso de forma controlada.', 'Vuelve despacio y alterna con el otro brazo manteniendo el abdomen activo.', 'Evita arquear la espalda o girar solo con los brazos sin acompañar el tronco.']::text[], 'principiante', 'Trabaja el pectoral superior, el tríceps y el core con un empuje diagonal que añade rotación al movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3324'),
('ac50a338-55ca-576e-bfc0-3c1564dcb193', 'Jalón al pecho alterno con giro y banda', ARRAY['Ancla la banda en alto y sujeta los extremos con los brazos extendidos.', 'Tira de una mano hacia el pecho girando ligeramente el tronco y vuelve despacio.', 'Alterna los brazos manteniendo los hombros lejos de las orejas.', 'Evita tirar con impulso o encoger los hombros durante el jalón.']::text[], 'principiante', 'Fortalece dorsales y espalda alta con un tirón alterno que suma rotación y trabajo del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3326'),
('5196862f-f842-5556-b319-1622f7606285', 'Apertura baja alterna de pecho con banda', ARRAY['Ancla la banda a un punto bajo y sujeta los extremos con los brazos abiertos.', 'Junta una mano hacia delante y arriba en arco y vuelve controlando la banda.', 'Alterna los brazos manteniendo una ligera flexión de codo.', 'Evita bloquear el codo o encoger los hombros al cerrar el movimiento.']::text[], 'principiante', 'Aísla el pectoral desde un ángulo bajo y añade trabajo de hombro y bíceps en el recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4078'),
('59b3137b-587c-58c1-89a1-7cf6f2aecc11', 'Remo bajo alterno con giro y banda', ARRAY['Ancla la banda a un punto bajo y sujeta los extremos con los brazos extendidos.', 'Tira de una mano hacia la cadera girando ligeramente el tronco y vuelve despacio.', 'Alterna los brazos manteniendo la espalda recta y el abdomen activo.', 'Evita redondear la espalda o tirar solo con el brazo sin acompañar el giro.']::text[], 'principiante', 'Refuerza la espalda alta y los dorsales con un tirón alterno que incorpora rotación del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3325'),
('d7cab064-8b20-56d0-b9fb-0b44202dc04e', 'V-up alternado con banda elástica', ARRAY['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.', 'Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.', 'Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.', 'Repite el movimiento, alternando la posición de las piernas en cada repetición.', 'Continúa durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con una flexión cruzada que exige control y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0969'),
('d4da1846-b8c0-5765-a899-eb5700f9855f', 'Dominada supina asistida con banda', ARRAY['Coloca la banda en la barra y apoya un pie o la rodilla en ella para recibir asistencia.', 'Cuélgate con agarre supino y los brazos extendidos.', 'Sube llevando el pecho hacia la barra y baja controlando el descenso.', 'Evita balancearte o encoger los hombros al iniciar la subida.']::text[], 'principiante', 'Fortalece dorsales y bíceps con un agarre supino que facilita el trabajo de la espalda y los flexores del codo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4718'),
('03270c66-a128-54bd-9046-a0d3d7e25c9b', 'Fondos asistidos con banda', ARRAY['Coloca la banda en las paralelas y apoya las rodillas o los pies en ella.', 'Sujétate en las paralelas con los brazos extendidos y el tronco ligeramente inclinado.', 'Baja flexionando los codos hasta un ángulo cómodo y sube empujando con los brazos.', 'Evita bajar demasiado o abrir los codos hacia fuera sin control.']::text[], 'principiante', 'Trabaja tríceps, pecho y hombros con una ayuda elástica que permite controlar el descenso y la subida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4205'),
('afbda8f1-c3fa-5508-95a7-2ef580180074', 'Elevación de glúteos e isquios asistida con banda', ARRAY['Colócate de rodillas con la banda anclada delante y sujeta a la altura del pecho.', 'Inclina el torso hacia delante manteniendo la cadera extendida y la espalda neutra.', 'Baja controlando el cuerpo hacia el suelo sin perder la línea de cadera y tronco.', 'Empuja con los isquios para volver arriba y evita arquear la zona lumbar.']::text[], 'principiante', 'Fortalece isquios y glúteos en cadena posterior, mejorando la extensión de cadera y la estabilidad de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4985'),
('a78f28d3-0fd4-5aca-9640-86d15c493945', 'Muscle-up asistido con banda', ARRAY['Cuelga de la barra con la banda anclada bajo los pies o las rodillas.', 'Tira con fuerza llevando el pecho hacia la barra y aprovecha el impulso.', 'Gira las muñecas y empuja para pasar por encima de la barra.', 'Controla la bajada y evita balancearte para no perder tensión.']::text[], 'avanzado', 'Progresión de dominada explosiva que trabaja dorsal, bíceps y tríceps para ganar fuerza en el tirón y el empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5801'),
('8554e1d2-ed01-5893-bf2d-177c90c5c557', 'Dominadas asistidas con banda', ARRAY['Sujeta la barra con agarre prono y coloca la banda bajo los pies o las rodillas.', 'Inicia el tirón bajando los omóplatos y llevando el pecho hacia la barra.', 'Sube hasta pasar la barbilla y evita encoger los hombros.', 'Baja de forma controlada hasta la extensión completa de brazos.']::text[], 'principiante', 'Refuerza dorsal y bíceps con ayuda elástica, ideal para progresar hacia dominadas estrictas sin perder técnica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2997'),
('8eb78080-1ba2-558c-a584-5a82c8c87b73', 'Flexión asistida con banda', ARRAY['Coloca la banda alrededor de la espalda y sujeta los extremos con las manos en el suelo.', 'Mantén el cuerpo alineado y baja el pecho controlando el movimiento.', 'Empuja para subir sin bloquear los codos de golpe.', 'Evita que la cadera caiga o se eleve durante el recorrido.']::text[], 'principiante', 'Trabaja pectoral, tríceps y hombro con ayuda elástica, útil para construir fuerza en flexiones completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6959'),
('e1b3e37f-1f7e-509e-ad5a-8c533d807f7d', 'Carrera de sprinter asistida con banda', ARRAY['Ancla la banda a la cintura y colócate en posición de salida con tensión.', 'Corre hacia delante con zancadas cortas y rápidas manteniendo el tronco erguido.', 'Empuja el suelo con la punta del pie y evita dar zancadas excesivas.', 'Mantén la respiración constante y frena de forma progresiva al final.']::text[], 'principiante', 'Mejora la velocidad y la potencia de piernas con resistencia elástica, activando glúteos, cuádriceps y gemelos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3653'),
('44315b3f-c992-5ca8-825f-a59460ce0243', 'Rodillo abdominal asistido con banda', ARRAY['Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.', 'Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.', 'Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.', 'Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el core y la zona lumbar con ayuda elástica, controlando la extensión del abdomen en el rodillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0971'),
('ddd319ce-6355-5cf5-8060-53717215e9e1', 'Extensión de espalda con banda', ARRAY['Sujeta la banda delante con los brazos extendidos y el torso inclinado.', 'Extiende la cadera llevando el tronco hacia arriba sin arquear la lumbar.', 'Aprieta glúteos arriba y mantén un segundo la posición.', 'Baja controlando el movimiento y evita usar impulso.']::text[], 'principiante', 'Refuerza la musculatura espinal y glútea para mejorar la postura y proteger la zona lumbar en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0891'),
('41620d82-cc56-53ed-9d4b-b93e2accd687', 'Press de hombros tras nuca con banda', ARRAY['Pisa la banda y sujeta los extremos a la altura de los hombros, detrás de la cabeza.', 'Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos.', 'Mantén el core activo y evita arquear la espalda baja.', 'Baja controlando hasta la altura de las orejas y repite.']::text[], 'principiante', 'Desarrolla deltoides y tríceps con resistencia elástica, mejorando la fuerza de empuje por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1499'),
('9fb5f2b0-314e-542c-88a0-ad5d47bcb64f', 'Extensión de cadera inclinado con banda', ARRAY['Inclina el torso hacia delante con la banda anclada al frente y sujeta los extremos.', 'Extiende la cadera llevando la pierna atrás sin mover la lumbar.', 'Aprieta el glúteo arriba y mantén la posición un instante.', 'Vuelve despacio y evita balancear el cuerpo.']::text[], 'principiante', 'Activa glúteos e isquios en cadena posterior, mejorando la extensión de cadera y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4035'),
('5a080bbf-3466-54e6-b750-01816081818b', 'Jalón inclinado con banda', ARRAY['Ancla la banda arriba y sujeta los extremos con el torso inclinado hacia delante.', 'Tira de la banda llevando los codos hacia las costillas.', 'Junta las escápulas al final del recorrido y evita encoger los hombros.', 'Vuelve controlando la tensión de la banda.']::text[], 'principiante', 'Trabaja dorsal y espalda alta con tracción elástica, útil para mejorar la fuerza del tirón vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4144'),
('a1a3f839-22a7-5477-a91e-2b951e3e63ee', 'Apertura posterior inclinado con banda', ARRAY['Inclina el torso con la banda sujeta delante y los brazos casi extendidos.', 'Abre los brazos hacia los lados llevando las escápulas atrás.', 'Mantén los codos ligeramente flexionados y evita encoger el cuello.', 'Vuelve despacio controlando la banda.']::text[], 'principiante', 'Refuerza deltoides posterior y espalda alta, equilibrando el hombro y mejorando la postura frente al ordenador.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4682'),
('f743b969-d753-5824-9f55-2a018214746b', 'Elevación lateral posterior inclinado con banda', ARRAY['Inclina el torso con la banda bajo los pies y sujeta los extremos.', 'Eleva los brazos hacia los lados hasta la altura de los hombros.', 'Mantén los codos ligeramente flexionados y el cuello relajado.', 'Baja controlando y evita usar impulso.']::text[], 'principiante', 'Aísla el deltoides posterior y la espalda alta, mejorando la estabilidad del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3971'),
('06c11242-4b16-5415-94da-d2e16b44ae6c', 'Remo inclinado con banda', ARRAY['Pisa la banda o anótala delante y sujeta los extremos con el torso inclinado.', 'Tira de la banda llevando los codos hacia atrás y juntando escápulas.', 'Mantén la espalda neutra y evita redondear la zona lumbar.', 'Vuelve controlando la tensión sin dejar caer el tronco.']::text[], 'principiante', 'Fortalece espalda alta, dorsal y bíceps con tracción elástica, mejorando la postura y la fuerza del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3899'),
('67d17c7a-7ba3-5761-a0a1-8ef465e095be', 'Remo inclinado con agarre abierto y banda', ARRAY['Sujeta la banda con agarre abierto y el torso inclinado hacia delante.', 'Tira de la banda llevando los codos hacia fuera y juntando escápulas.', 'Mantén el core activo y evita arquear la lumbar.', 'Vuelve despacio controlando la tensión.']::text[], 'principiante', 'Trabaja espalda alta y deltoides posterior con agarre amplio, mejorando la fuerza y la postura escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4452'),
('76377a7e-b9d8-53e3-9dc0-f685b11aa408', 'Abdominal bicicleta con banda', ARRAY['Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.', 'Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.', 'Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.', 'Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja recto abdominal y oblicuos con resistencia elástica, mejorando la estabilidad del core y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0972'),
('cf2f3297-b850-5e97-8bad-93f8bb9ba1e3', 'Elevación de gemelos con banda elástica', ARRAY['Pisa la banda con la parte delantera del pie y sujeta los extremos a la altura de la cintura.', 'Sube los talones todo lo que puedas manteniendo las rodillas estiradas y el core firme.', 'Aguanta un segundo arriba y baja el talón de forma controlada hasta el suelo.', 'Evita rebotar o cargar el peso en la punta del pie: controla todo el recorrido.', 'Respira al subir y mantén el equilibrio sin inclinarte hacia delante.']::text[], 'principiante', 'Fortalece los gemelos y el sóleo, mejorando el empuje del pie y la estabilidad del tobillo en carrera y saltos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0894'),
('079c943d-b19a-5a25-a7f3-2e09da4f09dc', 'Apertura de pecho con banda elástica', ARRAY['Ancla la banda a la espalda a la altura del pecho y sujeta un extremo en cada mano.', 'Con los codos ligeramente flexionados, abre los brazos hacia los lados hasta sentir el estiramiento del pecho.', 'Junta las manos al frente de forma controlada sin encoger los hombros.', 'Mantén el pecho alto y el core activo durante todo el movimiento.', 'Evita arquear la espalda o bloquear los codos al juntar las manos.']::text[], 'principiante', 'Trabaja los pectorales y la parte anterior del hombro, mejorando la fuerza de empuje y la apertura del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4075'),
('8378ea64-2623-53a9-89c0-23fdba80e4de', 'Curl de bíceps con agarre cerrado y banda elástica', ARRAY['Pisa la banda con los pies a la anchura de las caderas y sujeta los extremos con las palmas hacia arriba.', 'Con los codos pegados al torso, flexiona los brazos hasta llevar las manos cerca de los hombros.', 'Baja despacio controlando la banda sin dejar que tire de ti.', 'Mantén las muñecas firmes y evita balancear el tronco para subir.', 'Respira al subir y no bloquees la respiración en la parte alta.']::text[], 'principiante', 'Aísla el bíceps y el braquial con un agarre cerrado, aumentando la fuerza y el volumen del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4138'),
('51e36287-5ae9-5fad-a199-e35a59d65966', 'Remo con agarre cerrado y banda elástica', ARRAY['Ancla la banda a un punto fijo a la altura del pecho y sujeta los extremos con las palmas enfrentadas.', 'Con las rodillas ligeramente flexionadas y la espalda recta, lleva los codos hacia atrás pegados al cuerpo.', 'Junta las escápulas al final del recorrido y aguanta un instante.', 'Vuelve despacio sin dejar que los hombros se vayan hacia delante.', 'Evita encorvar la espalda o tirar con los brazos en lugar de con la espalda.']::text[], 'principiante', 'Refuerza la espalda alta y los romboides, mejorando la postura y la retracción escapular en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4145'),
('a5a0384e-a2d6-595b-9d71-dc0eb3546604', 'Jalón al pecho con agarre cerrado y banda', ARRAY['Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.', 'Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.', 'Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.', 'Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.', 'Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los dorsales y los bíceps con un tirón vertical que mejora la fuerza de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0974'),
('f3b511a6-b2a8-5a65-b1a7-bd02c6f355ff', 'Flexiones con agarre cerrado y banda', ARRAY['Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.', 'Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.', 'Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Incrementa la exigencia de tríceps, pecho y hombros con una flexión de manos juntas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0975'),
('674f3c3e-2fc9-55a8-9a52-85c8cea07683', 'Curl concentrado con banda', ARRAY['Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo.', 'Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado.', 'Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla.', 'Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Aísla el bíceps con un movimiento lento y controlado que mejora el pico del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0976'),
('27096fc6-b7ed-5c1a-adc6-3087c8ef75a3', 'Abducción cruzada con banda elástica', ARRAY['Coloca la banda por encima de las rodillas o en los tobillos y adopta una postura erguida con los pies a la anchura de las caderas.', 'Lleva una pierna hacia el lado contrario por delante de la otra, manteniendo el tronco estable.', 'Vuelve a la posición inicial de forma controlada y alterna el lado.', 'Mantén el core activo y evita inclinarte o girar la cadera.', 'Respira con normalidad y no des pasos demasiado amplios que descontrolen la banda.']::text[], 'principiante', 'Activa los abductores y glúteos, mejorando la estabilidad de la cadera y previniendo molestias en la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4136'),
('e034826d-84b9-50e6-8f22-e713d3217cb2', 'Press de pecho cruzado a un brazo con banda elástica', ARRAY['Ancla la banda a la espalda a la altura del pecho y sujeta un extremo con una mano.', 'Con el codo flexionado y pegado al cuerpo, empuja la mano hacia delante y ligeramente cruzada.', 'Extiende el brazo sin bloquear el codo y vuelve despacio a la posición inicial.', 'Mantén el core firme y evita girar el tronco para compensar la tensión.', 'Respira al empujar y controla la vuelta sin dejar que la banda te arrastre.']::text[], 'principiante', 'Trabaja el pectoral de forma unilateral con apoyo del core y los oblicuos, corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4076'),
('00224747-52f7-5555-aacf-efda064c59ff', 'Curl de bíceps cruzado al pecho con banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado, palma hacia arriba.', 'Flexiona el codo llevando la mano hacia el hombro contrario, manteniendo el codo pegado al torso.', 'Aprieta el bíceps arriba y baja despacio controlando la banda.', 'Evita mover el hombro o balancear el tronco para completar la repetición.', 'Respira al subir y mantén la muñeca neutra durante todo el recorrido.']::text[], 'principiante', 'Aísla el bíceps con un recorrido cruzado que aumenta la tensión y mejora la fuerza del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4088'),
('cd4dc38d-e073-56b0-8f78-97ef824bc71f', 'Peso muerto con banda elástica', ARRAY['Pisa la banda con los dos pies y sujeta los extremos con las manos delante de los muslos.', 'Con las rodillas ligeramente flexionadas, lleva la cadera hacia atrás manteniendo la espalda recta.', 'Baja hasta notar el estiramiento en los isquiotibiales y vuelve empujando la cadera hacia delante.', 'Aprieta los glúteos arriba sin hiperextender la espalda.', 'Evita redondear la espalda o tirar con los brazos: el movimiento nace de la cadera.']::text[], 'principiante', 'Fortalece glúteos, isquiotibiales y espalda baja, mejorando el patrón de bisagra de cadera y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4618'),
('d9c2b0bf-fc66-5855-bf8b-a3e8848a460f', 'Peso muerto con remo a un brazo y banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria, con la espalda recta.', 'Haz una bisagra de cadera llevando el glúteo hacia atrás hasta notar el estiramiento.', 'Desde ahí, tira del codo hacia atrás pegándolo al cuerpo y junta la escápula.', 'Baja el brazo y vuelve a subir empujando la cadera hacia delante.', 'Evita girar el tronco o redondear la espalda durante el remo.']::text[], 'principiante', 'Combina bisagra de cadera y tracción unilateral para trabajar glúteos, isquiotibiales y espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3771'),
('71f1e598-b0ee-5099-b023-42d535a01b24', 'Abdominal declinado con banda elástica', ARRAY['Ancla la banda por encima de la cabeza y sujeta los extremos contra el pecho.', 'Túmbate en un banco declinado con las rodillas flexionadas y los pies sujetos.', 'Sube el tronco enrollando la columna sin tirar del cuello con las manos.', 'Baja despacio controlando la banda y sin dejar caer el tronco de golpe.', 'Evita impulsarte con las piernas o arquear la espalda al subir.']::text[], 'principiante', 'Refuerza el recto abdominal y los flexores de cadera con mayor recorrido, mejorando el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1498'),
('48d7b4ea-c88b-5f00-8393-bda6a0c6981a', 'Giro de abajo hacia arriba con banda elástica', ARRAY['Ancla la banda abajo a un lado y sujeta el extremo con las dos manos.', 'Con los brazos extendidos, lleva las manos en diagonal hacia arriba y al lado contrario.', 'Gira el tronco de forma controlada manteniendo la cadera estable.', 'Vuelve despacio a la posición inicial sin dejar que la banda tire de ti.', 'Evita usar solo los brazos: el giro debe nacer del tronco.']::text[], 'principiante', 'Trabaja oblicuos y core con un giro diagonal, mejorando la rotación y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4696'),
('ed98791e-bc2e-5015-ae07-5461de6ca076', 'Curl con agarre cerrado y barra EZ con banda elástica', ARRAY['Pisa la banda con los pies y sujeta la barra EZ por la parte central con agarre cerrado.', 'Con los codos pegados al torso, flexiona los brazos hasta llevar la barra cerca del pecho.', 'Aprieta el bíceps arriba y baja la barra de forma controlada.', 'Mantén las muñecas firmes y evita balancear el tronco para subir.', 'Respira al subir y no bloquees los codos en la parte baja.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con un agarre cerrado que reduce la tensión en las muñecas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1506'),
('72de06fc-027b-5b00-9361-62e19e835a73', 'Jalón al pecho con agarre cerrado y banda elástica', ARRAY['Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.', 'Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.', 'Agarra la banda con un agarre cerrado, con las palmas hacia ti.', 'Mantén la espalda recta y activa el core.', 'Tira de la banda hacia el pecho, juntando los omóplatos.', 'Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.', 'Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los dorsales y los bíceps tirando de la banda hacia el pecho con los codos pegados al cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3117'),
('6f4c8011-fc36-5314-8df5-0df8bddf82ce', 'Jalón al pecho con agarre supino y banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.', 'Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.', 'Activa el core y junta los omóplatos.', 'Tira de la banda hacia el pecho, guiando el movimiento con los codos.', 'Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.', 'Suelta lentamente la tensión de la banda y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales, bíceps y romboides con las palmas hacia arriba, mejorando la tracción vertical y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3116'),
('cd315b37-6b47-5154-9c7d-447148b9c71c', 'Elevación lateral frontal con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.', 'Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa el deltoides y la parte alta de la espalda elevando los brazos al frente contra la resistencia de la banda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0977'),
('20c9adbd-36ec-5b56-9b3a-4b9d85ba9ff5', 'Plancha frontal con jalón a un brazo y banda elástica', ARRAY['Colócate en plancha frontal con la banda anclada a un lado y sujeta el extremo con una mano.', 'Mantén el cuerpo recto y el abdomen apretado mientras tiras de la banda hacia el pecho.', 'Controla el retorno de la mano sin dejar que la cadera rote ni se hunda.', 'Respira de forma constante y evita arquear la zona lumbar durante el movimiento.', 'Cambia de brazo y repite el mismo número de repeticiones.']::text[], 'principiante', 'Combina isometría de core con tracción unilateral para trabajar abdomen, oblicuos y dorsales sin perder la alineación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3777'),
('e157840f-4c20-5beb-905e-00950029d94e', 'Buenos días con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de las caderas y colócala sobre la espalda alta.', 'Con las rodillas ligeramente flexionadas, empuja la cadera hacia atrás manteniendo la espalda recta.', 'Baja hasta notar tensión en los isquiotibiales y vuelve a subir apretando los glúteos.', 'Evita redondear la espalda o flexionar demasiado las rodillas durante el descenso.', 'Respira inhalando al bajar y exhalando al subir con un tempo controlado.']::text[], 'principiante', 'Fortalece isquiotibiales, glúteos y zona lumbar con una bisagra de cadera controlada bajo tensión de banda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1513'),
('6b2ca67f-288c-5580-ab29-39fb1f12c64d', 'Curl martillo con banda elástica', ARRAY['Pisa la banda con los pies y sujeta los extremos con las palmas enfrentadas.', 'Con los codos pegados al torso, flexiona los antebrazos hacia los hombros.', 'Aprieta el bíceps arriba y baja controlando la banda sin dejar que tire de golpe.', 'Evita balancear el tronco o mover los codos hacia delante para hacer más fuerza.', 'Respira exhalando al subir y mantén las muñecas neutras.']::text[], 'principiante', 'Trabaja bíceps y braquial con agarre neutro, ganando fuerza y grosor en la parte anterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0897'),
('02c9659c-cfb0-5403-9751-00be7049d673', 'Apertura alta con banda elástica', ARRAY['Ancla la banda por encima de la cabeza y sujeta un extremo con cada mano.', 'Con los brazos abiertos y ligeramente flexionados, junta las manos delante del pecho.', 'Aprieta el pecho al final del recorrido y abre despacio controlando la banda.', 'Evita encoger los hombros o arquear la espalda al juntar las manos.', 'Respira exhalando al juntar y mantén el core activo.']::text[], 'principiante', 'Trabaja el pectoral superior y los hombros juntando las manos al frente desde una posición elevada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3757'),
('ff02948f-1c2b-5ac3-9e40-e001e8106981', 'Zancada con rodilla alta y remo a un brazo con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta un extremo con una mano.', 'Da un paso y sube la rodilla contraria mientras tiras de la banda hacia la cadera.', 'Mantén el tronco erguido y el abdomen firme durante todo el movimiento.', 'Baja la rodilla y controla el retorno del brazo antes de repetir.', 'Evita girar el tronco o perder el equilibrio al tirar de la banda.']::text[], 'principiante', 'Ejercicio global que combina piernas, glúteos y espalda, mejorando equilibrio, coordinación y fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3772'),
('42f6a9f6-b2a6-50e9-a30d-7f0a309bfb35', 'Abducción de cadera con banda elástica', ARRAY['Coloca la banda alrededor de los tobillos o muslos y adopta una postura estable.', 'Separa la pierna del cuerpo de forma controlada manteniendo el tronco recto.', 'Aprieta el glúteo al final del recorrido y vuelve despacio a la posición inicial.', 'Evita inclinarte hacia el lado contrario o compensar con la cadera.', 'Respira exhalando al abrir y mantén el abdomen activo.']::text[], 'principiante', 'Fortalece los abductores y glúteos medios, mejorando la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4031'),
('3a44ba64-4c56-56f1-a55f-23ecea0ce9aa', 'Aducción de cadera con banda elástica', ARRAY['Coloca la banda alrededor del tobillo y fíjala a un punto lateral bajo.', 'Lleva la pierna hacia el centro del cuerpo de forma controlada.', 'Aprieta la cara interna del muslo al juntar la pierna y vuelve despacio.', 'Evita girar la cadera o inclinar el tronco para acompañar el movimiento.', 'Respira exhalando al acercar la pierna y mantén el apoyo firme.']::text[], 'principiante', 'Trabaja los aductores y la cara interna del muslo, mejorando la estabilidad y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4029'),
('7eb21339-606c-5df4-99c8-4e804f0c4797', 'Extensión de cadera con banda elástica', ARRAY['Ancla la banda al tobillo y fíjala a un punto bajo delante de ti.', 'Con el tronco ligeramente inclinado, lleva la pierna hacia atrás sin arquear la lumbar.', 'Aprieta el glúteo al final del recorrido y vuelve despacio.', 'Evita compensar con la zona lumbar o girar la cadera.', 'Respira exhalando al extender y mantén el abdomen firme.']::text[], 'principiante', 'Activa glúteos e isquiotibiales llevando la pierna hacia atrás, útil para fortalecer la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0901'),
('414a5150-2b9e-574f-bcb1-616e397eb31f', 'Flexión de cadera con banda elástica', ARRAY['Ancla la banda al tobillo y fíjala a un punto bajo detrás de ti.', 'De pie y con el tronco recto, sube la rodilla hacia el pecho de forma controlada.', 'Aprieta el abdomen abajo y baja la pierna despacio sin dejar que la banda tire.', 'Evita arquear la espalda o balancear el cuerpo para subir la rodilla.', 'Respira exhalando al subir y mantén el apoyo estable.']::text[], 'principiante', 'Fortalece flexores de cadera y abdomen inferior elevando la rodilla contra la resistencia de la banda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1507'),
('358a7d27-3cff-598b-8c2a-b03db6c593bf', 'Elevación de cadera con banda', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca una banda elástica justo por encima de las rodillas.', 'Activa los glúteos y los músculos del core.', 'Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece glúteos e isquiotibiales elevando la cadera contra la banda, mejorando la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1408'),
('17e0870f-e23e-511d-b03f-f4edc4688f8f', 'Curl de bíceps horizontal con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta los extremos con las palmas hacia arriba.', 'Con los codos pegados al torso, flexiona los antebrazos hacia los hombros.', 'Aprieta el bíceps arriba y vuelve despacio controlando la banda.', 'Evita echar los codos hacia atrás o balancear el tronco.', 'Respira exhalando al flexionar y mantén las muñecas firmes.']::text[], 'principiante', 'Trabaja el bíceps con una tracción horizontal que añade tensión constante y mejora el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4084'),
('89f70667-1417-50b2-a5fb-6838f2175cf6', 'Pallof press horizontal con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.', 'Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros.', 'Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda.', 'Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.', 'Activa el core y mantén una postura estable.', 'Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo.', 'Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core.', 'Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabajo isométrico de core y oblicuos que enseña a resistir la rotación manteniendo el tronco estable.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0979'),
('fe4442e0-a6ff-51c3-ad98-c1df54d6852f', 'Press pallof horizontal con sentadilla y banda elástica', ARRAY['Ancla la banda a la altura del pecho y colócate de lado con los pies a la anchura de los hombros.', 'Sujeta la banda con ambas manos frente al esternón y baja en sentadilla manteniendo el pecho alto.', 'Empuja las manos al frente extendiendo los brazos sin dejar que la banda te gire el tronco.', 'Aguanta un segundo arriba, vuelve a flexionar los codos y sube de la sentadilla.', 'Evita que la cadera se desplace hacia el ancla y mantén el abdomen apretado todo el tiempo.']::text[], 'principiante', 'Trabaja cuádriceps y core mientras resistes la rotación; mejora la estabilidad del tronco en posiciones de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3524'),
('2a671e7e-432f-5adf-bad8-0ae18690d255', 'Hiperextensión con banda elástica', ARRAY['Sujeta la banda con los pies y pásala por detrás de la nuca, con el torso inclinado hacia delante.', 'Mantén la espalda neutra y las rodillas ligeramente flexionadas.', 'Extiende la cadera hasta quedar alineado sin arquear la zona lumbar.', 'Aprieta los glúteos arriba un segundo y baja controlando el movimiento.', 'Evita tirar con la espalda o hiperextender el cuello al final del recorrido.']::text[], 'principiante', 'Fortalece la musculatura lumbar y los glúteos, útil para mejorar la extensión de cadera y prevenir molestias de espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0902'),
('b7280f49-0d98-599d-b2d2-f3a07a11efd8', 'Press de banca inclinado con banda elástica', ARRAY['Pasa la banda por debajo del banco inclinado y sujeta un extremo en cada mano.', 'Túmbate con los omóplatos retraídos y los codos a unos 45 grados del torso.', 'Empuja las manos hacia arriba y adelante hasta extender los brazos sin bloquear de golpe.', 'Baja controlando la banda hasta notar estiramiento en el pecho.', 'Evita arquear la lumbar o abrir los codos en exceso durante el empuje.']::text[], 'principiante', 'Trabaja el pecho superior, hombros y tríceps; mejora el empuje horizontal con resistencia elástica progresiva.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4544'),
('3481028c-6946-5192-a477-b861674b157e', 'Abdominal navaja con banda elástica', ARRAY['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.', 'Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el recto abdominal y los flexores de cadera; mejora el control del tronco en flexión dinámica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0981'),
('2e516418-e1fd-5a91-a0e7-c241df3884f8', 'Zancada con salto y remo a un brazo con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta un extremo con una mano, con los pies juntos.', 'Da un paso y baja en zancada mientras llevas el codo hacia atrás en remo.', 'Impulsa con ambas piernas para saltar y cambiar de pierna en el aire.', 'Aterriza suave con las rodillas alineadas y repite el remo en la nueva posición.', 'Evita que la rodilla delantera pase muy por delante del pie y mantén el tronco erguido.']::text[], 'principiante', 'Combina potencia de piernas con tracción unilateral; mejora la coordinación, el equilibrio y la fuerza de espalda.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3782'),
('0c7fad57-781d-5223-a32f-26e45a5e8481', 'Patada trasera con banda elástica', ARRAY['Ancla la banda a una altura baja y sujeta un extremo con una mano.', 'Inclina el torso hacia delante con la espalda recta y el codo pegado al costado.', 'Extiende el brazo hacia atrás hasta estirar el codo por completo.', 'Aprieta el tríceps un segundo y vuelve despacio a la posición inicial.', 'Evita mover el hombro o balancear el torso para completar la repetición.']::text[], 'principiante', 'Aísla el tríceps y mejora la extensión del codo; útil para tonificar la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0903'),
('53ec9de6-b5eb-52fb-a702-c07ab5552f9e', 'Abdominal de rodillas con banda elástica', ARRAY['Ancla la banda arriba y sujeta los extremos junto a la cabeza, arrodillado.', 'Mantén la cadera fija y el abdomen apretado.', 'Flexiona el tronco hacia delante llevando las costillas hacia la pelvis.', 'Vuelve despacio sin dejar que la banda te tire hacia atrás.', 'Evita tirar con el cuello o las manos durante el movimiento.']::text[], 'principiante', 'Trabaja el recto abdominal y los oblicuos; mejora la flexión controlada del tronco con resistencia constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4080'),
('968e4f83-5b33-5f01-a636-fc66190f649e', 'Press inclinado de rodillas con banda elástica', ARRAY['Ancla la banda a una altura baja y sujeta un extremo en cada mano, arrodillado.', 'Lleva las manos a la altura del pecho con los codos hacia abajo y atrás.', 'Empuja hacia arriba y adelante hasta extender los brazos.', 'Baja controlando la banda y mantén el abdomen firme.', 'Evita arquear la espalda o encoger los hombros al empujar.']::text[], 'principiante', 'Trabaja el pecho superior, hombros y tríceps; mejora el empuje diagonal con control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4684'),
('b5768284-d378-5f49-bf76-3805327d8408', 'Jalón de rodillas con banda elástica', ARRAY['Ancla la banda por encima de la cabeza y sujeta un extremo en cada mano, arrodillado.', 'Extiende los brazos arriba con el pecho alto y los omóplatos descendidos.', 'Tira de la banda hacia el pecho llevando los codos hacia abajo y atrás.', 'Aprieta la espalda un segundo y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o balancear el torso para tirar.']::text[], 'principiante', 'Trabaja el dorsal ancho y la espalda alta; mejora la tracción vertical y la postura con resistencia elástica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4358'),
('9a65db2b-4fd2-5fbf-8a3a-22c3d3201198', 'Jalón de rodillas a un brazo con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.', 'Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.', 'Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.', 'Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.', 'Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'avanzado', 'Trabaja el dorsal y el bíceps de forma unilateral; mejora la simetría y el control de la escápula.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0983'),
('c32609bf-b509-56c2-bf5e-9fae557d6622', 'Curl predicador de rodillas con banda elástica', ARRAY['Ancla la banda a una altura baja y sujeta un extremo con una mano, arrodillado.', 'Apoya el codo en el muslo o en una superficie estable con el brazo extendido.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo.', 'Aprieta el bíceps arriba y baja controlando la banda.', 'Evita separar el codo del apoyo o usar el hombro para completar la repetición.']::text[], 'principiante', 'Aísla el bíceps y el braquial; mejora la flexión del codo con tensión constante y sin balanceo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4085'),
('f124c71d-00e4-5ee3-86b5-59d5723419ae', 'Patada trasera de rodillas con banda elástica', ARRAY['Ancla la banda a una altura baja y sujétala en el tobillo, arrodillado a cuatro apoyos.', 'Mantén la espalda neutra y el abdomen apretado.', 'Empuja la pierna hacia atrás y arriba hasta extender la cadera.', 'Aprieta el glúteo un segundo y vuelve despacio sin tocar el suelo.', 'Evita arquear la lumbar o girar la cadera al levantar la pierna.']::text[], 'principiante', 'Trabaja el glúteo mayor y los isquios; mejora la extensión de cadera y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0906'),
('fecfd12b-1f42-50fa-a06f-cc434865a6f6', 'Remo horizontal de rodillas a un brazo con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta un extremo con una mano, arrodillado.', 'Inclina ligeramente el torso con la espalda recta y el brazo extendido.', 'Tira del codo hacia atrás llevando la mano hacia la cadera.', 'Aprieta el omóplato un segundo y vuelve controlando la banda.', 'Evita rotar el tronco o encoger el hombro durante la tracción.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta de forma unilateral; mejora la tracción horizontal y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10668'),
('44d970c1-6193-5f5b-bd89-2ae8583ea966', 'Patada a una pierna de rodillas con banda elástica', ARRAY['Ancla la banda a una altura baja y sujétala en el tobillo, arrodillado a cuatro apoyos.', 'Coloca las manos bajo los hombros y mantén la espalda neutra.', 'Levanta una pierna hacia atrás y arriba sin girar la cadera.', 'Aprieta el glúteo arriba y baja despacio sin apoyar del todo.', 'Evita arquear la lumbar o levantar la pierna más de lo que controlas.']::text[], 'principiante', 'Trabaja el glúteo y los isquios de forma unilateral; mejora la extensión de cadera y el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4677'),
('4490e9ee-09bd-5abd-be03-9d67af064fe7', 'Elevación lateral con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta un extremo en cada mano.', 'Mantén los codos ligeramente flexionados y el torso erguido.', 'Eleva los brazos hacia los lados hasta la altura de los hombros.', 'Baja despacio controlando la banda sin dejar caer los brazos.', 'Evita encoger los hombros o usar impulso para subir los brazos.']::text[], 'principiante', 'Trabaja el deltoides medio y el manguito rotador; mejora la elevación del brazo y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0907'),
('fff3c71b-9383-5772-acb6-c251613dea3f', 'Caminata lateral con banda elástica', ARRAY['Coloca la banda por encima de las rodillas o en los tobillos y adopta una postura semisentada con los pies a la anchura de los hombros.', 'Da pasos laterales cortos manteniendo la tensión de la banda y las rodillas alineadas con los pies.', 'Mantén el tronco erguido y respira de forma constante durante todo el recorrido.', 'Evita juntar los pies o dejar que las rodillas se metan hacia dentro en cada paso.']::text[], 'principiante', 'Fortalece los abductores y glúteos, mejorando la estabilidad de cadera y la prevención de lesiones en deportes de desplazamiento lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6607'),
('aad1f65a-b9bf-541d-8a66-350154ce7455', 'Press bajo alterno de pecho con banda elástica', ARRAY['Sujeta la banda a la altura baja y colócate de espaldas con un pie adelantado para tener estabilidad.', 'Empuja un brazo hacia delante y arriba hasta extenderlo, manteniendo el codo ligeramente flexionado.', 'Vuelve despacio a la posición inicial y repite con el otro brazo de forma alterna.', 'No arquees la zona lumbar ni bloquees la respiración al empujar.']::text[], 'principiante', 'Trabaja el pectoral con un brazo a la vez, activando tríceps y hombro, y ayuda a corregir desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4077'),
('3f38900f-7aed-57fc-8852-5ac59d268651', 'Apertura baja de pecho con banda elástica', ARRAY['Ancla la banda abajo y sujeta los extremos con los brazos extendidos hacia delante.', 'Abre los brazos en arco hasta notar el estiramiento del pecho, sin bloquear los codos.', 'Junta las manos de nuevo delante del pecho apretando la musculatura y controlando la vuelta.', 'Evita encoger los hombros o usar impulso del tronco para cerrar los brazos.']::text[], 'principiante', 'Aísla el pectoral en un recorrido ascendente, trabajando también el hombro y la parte superior del pecho con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4073'),
('bfc24b41-8c2a-5403-b2b4-c671ad026a9d', 'Press bajo de pecho con banda elástica', ARRAY['Fija la banda a la altura baja y sujeta los extremos con las manos a la altura del pecho.', 'Empuja ambos brazos hacia delante y ligeramente arriba hasta extenderlos sin bloquear los codos.', 'Regresa despacio a la posición inicial manteniendo la tensión de la banda.', 'Mantén el abdomen activo y evita sacar las costillas hacia delante al empujar.']::text[], 'principiante', 'Fortalece el pectoral y la parte superior del pecho con empuje horizontal, implicando tríceps y hombros de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4074'),
('38d6e430-a278-5322-a288-55dc90b8d632', 'Apertura baja con banda elástica', ARRAY['Ancla la banda en un punto bajo y sujeta los extremos con los brazos extendidos al frente.', 'Abre los brazos hacia los lados describiendo un arco amplio y sin forzar el hombro.', 'Cierra lentamente juntando las manos delante del pecho y aprieta la musculatura.', 'No balancees el cuerpo ni dejes que los codos se flexionen en exceso durante la apertura.']::text[], 'principiante', 'Trabaja el pectoral y la parte superior del pecho con un movimiento de apertura controlado que también solicita el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0908'),
('be4382a3-6d0c-5ad1-9a5c-a5da939cca6d', 'Zancadas con banda elástica', ARRAY['Coloca la banda en los tobillos o bajo los pies y da un paso al frente para iniciar la zancada.', 'Baja flexionando ambas rodillas hasta que la trasera quede cerca del suelo, manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial y alterna las piernas.', 'Evita que la rodilla delantera se vaya hacia dentro o que el talón se levante del suelo.']::text[], 'principiante', 'Refuerza cuádriceps, glúteos e isquiotibiales con un patrón de zancada que mejora el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0909'),
('29dd360b-c8f4-50ad-9b8d-812795bee05f', 'Prensa de piernas alterna acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda sujeta en los pies o anclada para ofrecer resistencia.', 'Empuja una pierna hacia arriba y adelante extendiendo la rodilla sin bloquearla del todo.', 'Flexiona la rodilla para volver despacio y repite con la otra pierna de forma alterna.', 'Mantén la zona lumbar pegada al suelo y evita empujar con la espalda.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con un empuje de pierna tumbado, útil para trabajar la fuerza sin carga axial.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4681'),
('92d4019f-5865-5615-8c2f-c642e32fd4af', 'Elevación de rodilla flexionada acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda sujeta en los pies y las rodillas flexionadas.', 'Lleva las rodillas hacia el pecho elevando la cadera ligeramente del suelo.', 'Baja despacio hasta la posición inicial sin dejar que la banda tire de ti.', 'Evita arquear la lumbar o usar impulso; controla el descenso en cada repetición.']::text[], 'principiante', 'Activa el abdomen y los flexores de cadera con un movimiento controlado que mejora la estabilidad del core tumbado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6810'),
('0326ff53-8fea-5607-b405-9ea009ecc9ce', 'Rotación externa de cadera acostado con banda elástica', ARRAY['Túmbate de lado con la banda en los tobillos y las rodillas flexionadas a unos 90 grados.', 'Mantén los pies juntos y abre la rodilla superior rotando la cadera hacia fuera.', 'Vuelve despacio a la posición inicial sin dejar que la rodilla caiga de golpe.', 'No gires el tronco ni separes la cadera del suelo durante el movimiento.']::text[], 'principiante', 'Fortalece los rotadores externos de cadera y glúteos, mejorando la estabilidad de la articulación y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0982'),
('b67c5aa4-1d96-5ee6-bf54-96d3ee145705', 'Rotación interna de cadera acostado con banda elástica', ARRAY['Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.', 'Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.', 'Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.', 'Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza la cadera hacia la rotación interna, mejorando el rango articular y la coordinación de la musculatura glútea.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0984'),
('b7d6c9cf-d93c-5f94-acd4-3d7f1f655ed0', 'Elevación de pierna y cadera acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda sujeta en los pies y las piernas extendidas.', 'Eleva las piernas y separa ligeramente la cadera del suelo apretando el abdomen.', 'Baja despacio hasta la posición inicial manteniendo la tensión de la banda.', 'Evita arquear la zona lumbar o dejar caer las piernas sin control.']::text[], 'principiante', 'Trabaja el abdomen y la parte baja del core con una elevación de piernas y cadera que exige control lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0910'),
('f184ca67-ea46-5a5d-b617-c0bbd10533a4', 'Curl de pierna acostado con banda elástica', ARRAY['Túmbate boca abajo con la banda anclada delante y sujeta en los tobillos.', 'Flexiona las rodillas llevando los talones hacia los glúteos contra la resistencia.', 'Baja despacio hasta estirar las piernas sin dejar que la banda tire de golpe.', 'Mantén la cadera pegada al suelo y evita arquear la espalda al flexionar.']::text[], 'principiante', 'Fortalece los isquiotibiales con una flexión de rodilla tumbado, ayudando a equilibrar la fuerza del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0911'),
('f7790560-3004-5eb6-b170-b56332663f2d', 'Elevación de pierna acostado con banda elástica', ARRAY['Túmbate de lado con la banda en los tobillos y las piernas estiradas.', 'Eleva la pierna superior hacia el techo manteniendo el pie en flexión neutra.', 'Baja despacio hasta la posición inicial sin dejar que la pierna caiga.', 'Evita girar el tronco hacia atrás o compensar con la cadera.']::text[], 'principiante', 'Refuerza abductores y glúteos con una elevación lateral de pierna que mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0912'),
('572b641d-2a95-5e33-b49d-6ddd6911bcfd', 'Extensión de tríceps acostado con agarre inverso y banda elástica', ARRAY['Túmbate boca arriba con la banda anclada por encima y sujeta con agarre inverso.', 'Extiende los codos llevando las manos hacia los pies sin mover los brazos del sitio.', 'Flexiona despacio los codos para volver a la posición inicial manteniendo la tensión.', 'Evita abrir los codos hacia los lados o usar impulso del tronco.']::text[], 'principiante', 'Aísla el tríceps con un empuje en agarre inverso que también solicita antebrazo y hombro de forma controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4142'),
('815bbad0-e847-51d5-b35d-faab6c68ec0e', 'Elevación de piernas rectas acostado con banda elástica', ARRAY['Túmbate sobre tu espalda con las piernas rectas y los pies juntos.', 'Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.', 'Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con una elevación de piernas rectas que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1002'),
('d41a31ee-ea85-582c-ba2a-86c048264cee', 'Apertura media con banda elástica', ARRAY['Sujeta la banda con las dos manos y colócala a la altura del pecho, con los brazos ligeramente flexionados.', 'Abre los brazos hacia los lados hasta notar tensión en el pecho, sin bloquear los codos.', 'Vuelve despacio a la posición inicial controlando la banda en todo momento.', 'Mantén los hombros bajos y evita arquear la espalda al abrir.']::text[], 'principiante', 'Trabaja el pectoral y la parte frontal del hombro, mejorando la apertura y el control del pecho en movimientos de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0913'),
('434edbcf-9bfb-5df5-8c98-55f4f47d1c02', 'Remo alto con agarre estrecho y banda elástica', ARRAY['Pisa la banda o ancla el extremo y agarra el otro con las manos juntas a la altura de la cintura.', 'Tira de la banda hacia el pecho llevando los codos hacia arriba y hacia atrás.', 'Junta las escápulas al final del recorrido y mantén un segundo de tensión.', 'Baja la banda de forma controlada sin perder la postura erguida.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides, ayudando a mejorar la postura y la estabilidad de los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4147'),
('0a8827cf-90ed-5d5c-a208-f779f702fec7', 'Curl de bíceps sobre la cabeza a un brazo con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.', 'Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.', 'Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Aísla el bíceps desde una posición elevada, aumentando la tensión en el rango final del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0986'),
('7bf6c0ae-2f5f-5781-8d4f-1dd8aae96891', 'Sentadilla búlgara a un brazo con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.', 'Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.', 'Sujétate de un apoyo con una mano para mantener el equilibrio.', 'Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.', 'Empuja con el talón para regresar a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'principiante', 'Trabaja el cuádriceps y el glúteo de forma unilateral, mejorando el equilibrio y la fuerza de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0987'),
('28a91281-a9a5-5a08-bab4-c85af0cbe327', 'Remo bajo de pie a un brazo con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje estable a la altura de la cintura.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Tira de la banda hacia la cintura, juntando los omóplatos.', 'Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Refuerza la espalda alta y el bíceps, mejorando la postura y la fuerza de tracción de un solo lado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0988'),
('3cb2a357-1541-5306-b541-96ddcef9b946', 'Remo bajo de pie a un brazo con agarre abierto y banda elástica', ARRAY['Ancla la banda a la altura de la cintura y agarra el extremo con una mano, con el brazo extendido.', 'Tira de la banda hacia la cadera llevando el codo hacia atrás y hacia el costado.', 'Aprieta la escápula al final del recorrido y mantén el torso estable.', 'Vuelve despacio a la posición inicial sin dejar que la banda te arrastre.']::text[], 'principiante', 'Activa el dorsal y la espalda alta con un agarre amplio, mejorando la amplitud y el control del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4453'),
('16b5d813-395c-5d95-be35-a6c400cf8ae9', 'Press de pecho con giro a un brazo y banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente a la altura del pecho.', 'Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.', 'Aléjate del punto de anclaje para generar tensión en la banda.', 'Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.', 'Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.', 'Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.', 'Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.', 'Cambia de lado y repite el ejercicio con la otra mano.']::text[], 'principiante', 'Trabaja el pectoral con rotación, mejorando la fuerza de empuje y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0989'),
('40d3215c-0eec-5978-8de6-a1ad2b78af66', 'Remo sentado con giro a un brazo y banda elástica', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.', 'Sostén la banda con una mano y extiende el brazo completamente frente a ti.', 'Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.', 'Al mismo tiempo, gira el torso hacia el lado del brazo que tira.', 'Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'principiante', 'Fortalece la espalda alta con rotación, mejorando la movilidad y el control escapular de un lado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0990'),
('59e54f42-663f-50f9-8064-f5655660a649', 'Flexión lateral por encima de la cabeza con banda elástica', ARRAY['Sujeta la banda por encima de la cabeza con las dos manos y los brazos extendidos.', 'Inclina el torso hacia un lado manteniendo la cadera estable y sin girar.', 'Vuelve al centro de forma controlada y repite hacia el otro lado.', 'Evita tirar con los brazos: el movimiento debe salir del tronco.']::text[], 'principiante', 'Trabaja los oblicuos y el core, mejorando la estabilidad lateral del tronco y la fuerza abdominal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4082'),
('a4098d73-b718-5996-998f-b9ab6daae8a3', 'Extensión de tríceps a un brazo sobre la cabeza con banda elástica', ARRAY['Ancla la banda por debajo o písala y sujeta el extremo con una mano detrás de la cabeza.', 'Extiende el codo hacia arriba hasta estirar el brazo por completo, sin mover el hombro.', 'Baja despacio hasta notar el estiramiento del tríceps y repite.', 'Mantén el codo apuntando al frente y evita arquear la espalda.']::text[], 'principiante', 'Aísla el tríceps en estiramiento, mejorando la fuerza y el tono de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4140'),
('622eb504-c9b4-5d02-8be1-ae0c6cc9af79', 'Extensión de tríceps sobre la cabeza con banda elástica', ARRAY['Pisa la banda o ancla el extremo y sujeta el otro con las dos manos detrás de la cabeza.', 'Extiende los codos hacia arriba hasta estirar los brazos, manteniendo los hombros estables.', 'Baja de forma controlada hasta notar el estiramiento del tríceps.', 'Evita abrir los codos hacia los lados y mantener el abdomen activo.']::text[], 'principiante', 'Trabaja el tríceps en posición elevada, mejorando la fuerza y la estabilidad del brazo y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3939'),
('e24a41af-586f-50d2-bc8f-fd65890fabe6', 'Pull through con banda elástica', ARRAY['Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.', 'Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.', 'Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.', 'Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.', 'Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.', 'Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa el glúteo y los isquiotibiales con un movimiento de cadera, mejorando la fuerza del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0991'),
('d0e6b763-2280-5614-b7d1-074278ff4e89', 'Abdominal con empuje y banda elástica', ARRAY['Sujeta la banda de forma segura a un punto de anclaje estable.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen con resistencia añadida, mejorando la fuerza del core y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0992'),
('09e6f98e-ae70-5765-8552-e20a7cf3d6f2', 'Flexión con banda elástica', ARRAY['Coloca la banda por la espalda sujetándola con las manos en el suelo, en posición de flexión.', 'Baja el pecho hacia el suelo manteniendo el cuerpo alineado y el abdomen activo.', 'Empuja hacia arriba hasta extender los brazos sin bloquear los codos.', 'Evita que la cadera se hunda o se eleve durante el movimiento.']::text[], 'principiante', 'Refuerza el pectoral, el tríceps y el core con resistencia extra, mejorando la fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0915'),
('426f17c4-66f6-5621-9129-ef8c42b5e3e1', 'Extensión de tríceps con banda elástica', ARRAY['Ancla la banda en un punto alto y sujeta el extremo con las dos manos, codos pegados al cuerpo.', 'Extiende los codos hacia abajo hasta estirar los brazos por completo.', 'Vuelve despacio a la posición inicial sin separar los codos del torso.', 'Mantén la espalda recta y evita balancear el cuerpo para tirar.']::text[], 'principiante', 'Aísla el tríceps en polea con banda, mejorando la fuerza y el tono de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1502'),
('331e7e75-5758-535c-949c-86bea17739a2', 'Remo para deltoide posterior con banda elástica', ARRAY['Sujeta la banda con ambas manos frente a ti, brazos extendidos a la altura de los hombros.', 'Tira de la banda hacia el pecho separando los codos hacia fuera y juntando las escápulas.', 'Aguanta un segundo arriba y vuelve despacio controlando la banda.', 'Evita encoger los hombros hacia las orejas durante todo el recorrido.']::text[], 'principiante', 'Fortalece la parte trasera del hombro y la espalda alta, mejorando la postura y el equilibrio muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1006'),
('f97df25b-1f8f-5aac-a86c-4847d01f13da', 'Dominada supina con banda elástica', ARRAY['Coloca la banda en la barra y pisa o engancha la rodilla para que te asista.', 'Cuelga con agarre supino a la anchura de los hombros y el core activo.', 'Sube hasta pasar la barbilla por la barra y baja controlando sin dejarte caer.', 'Evita balancearte o encoger los hombros al iniciar el tirón.']::text[], 'principiante', 'Trabaja la espalda y los bíceps con agarre supino, ideal para progresar hacia dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4415'),
('469cb160-6bc2-5293-b7e0-e3631716e9e6', 'Abdominal reverso con banda elástica', ARRAY['Túmbate boca arriba con la banda anclada y enganchada en los pies o tobillos.', 'Lleva las rodillas al pecho despegando la pelvis del suelo con suavidad.', 'Exhala al subir y baja despacio sin arquear la zona lumbar.', 'Evita tirar con el cuello o impulsarte con las piernas.']::text[], 'principiante', 'Activa la zona baja del abdomen y el core, útil para controlar la pelvis y estabilizar el tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4081'),
('add179ce-b094-58b4-9d00-b05ceb4c5d5d', 'Curl inverso con banda elástica', ARRAY['Pisa la banda y sujeta los extremos con las palmas hacia abajo.', 'Flexiona los codos pegados al cuerpo llevando las manos hacia los hombros.', 'Baja despacio manteniendo la muñeca firme y neutra.', 'Evita mover los hombros o balancear el tronco para subir.']::text[], 'principiante', 'Refuerza antebrazos y agarre con un movimiento de flexión, mejorando la fuerza en la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0917'),
('4f086104-45a7-5a97-9c25-86853c04febf', 'Apertura invertida con banda elástica', ARRAY['Sujeta la banda a un objeto fijo a la altura del pecho.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.', 'Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.', 'Junta los omóplatos en la parte superior del movimiento.', 'Baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el deltoide posterior y la espalda alta, ayudando a compensar el trabajo de pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0993'),
('f85004c5-5426-5389-aa2b-1e83a3ae221f', 'Curl de muñeca inverso con banda elástica', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo.', 'Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.', 'Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.', 'Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los extensores del antebrazo, mejorando la estabilidad de la muñeca y el agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0994'),
('00d014c2-4fef-511c-9c8c-58555a2c9c09', 'Abducción de cadera sentado con banda elástica', ARRAY['Siéntate con la banda alrededor de los muslos, por encima de las rodillas.', 'Separa las rodillas contra la resistencia manteniendo los pies apoyados.', 'Aguanta un segundo y vuelve despacio sin dejar que la banda te cierre.', 'Evita inclinar el tronco o compensar con la espalda.']::text[], 'principiante', 'Activa glúteo medio y abductores, clave para la estabilidad de la cadera y la alineación de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6785'),
('75792eda-2b16-506b-9357-be588f4e6818', 'Rotación externa de cadera sentado con banda elástica', ARRAY['Siéntate con la banda enganchada en un punto fijo y en el tobillo o rodilla.', 'Gira la pierna hacia fuera manteniendo el muslo estable y el core activo.', 'Vuelve despacio controlando la banda sin dejar que tire de ti.', 'Evita girar todo el tronco o levantar la cadera del asiento.']::text[], 'principiante', 'Fortalece los rotadores externos de la cadera, mejorando el control y la estabilidad de la pelvis.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0995'),
('209f9080-369b-5176-9981-57fe6c15a561', 'Rotación interna de cadera sentado con banda elástica', ARRAY['Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.', 'Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.', 'Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.', 'Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los rotadores internos de la cadera, complementando el equilibrio muscular de la zona.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0996'),
('36607e7a-cc16-529c-a2b5-b92b1a2adc20', 'Extensión de piernas sentado con banda elástica', ARRAY['Siéntate con la banda anclada delante y enganchada en el tobillo.', 'Estira la rodilla contra la resistencia hasta casi bloquearla.', 'Aguanta arriba un segundo y baja despacio sin soltar la tensión.', 'Evita dar tirones o despegar la espalda del respaldo.']::text[], 'principiante', 'Aísla el cuádriceps fortaleciendo la rodilla, útil para la estabilidad y el control del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3518'),
('c45f448e-f3ae-5bcd-9d28-dc214982a42f', 'Remo sentado con banda elástica', ARRAY['Siéntate con la banda anclada delante y sujeta los extremos con los brazos extendidos.', 'Tira de la banda hacia el abdomen juntando las escápulas y con el pecho alto.', 'Vuelve despacio controlando la resistencia sin perder la postura.', 'Evita encorvar la espalda o tirar con los hombros subidos.']::text[], 'principiante', 'Fortalece la espalda media y los brazos, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3896'),
('d9cd04e7-e761-5905-8cce-33b49792ee84', 'Remo sentado con espalda recta y banda elástica', ARRAY['Siéntate erguido con la banda anclada delante y sujeta los extremos.', 'Tira de la banda hacia el abdomen manteniendo la espalda recta y el core activo.', 'Junta las escápulas arriba y vuelve despacio sin redondear la espalda.', 'Evita arquear la zona lumbar o usar impulso del tronco.']::text[], 'principiante', 'Refuerza los dorsales y la espalda alta manteniendo una postura erguida durante la tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3121'),
('22ac6f17-fa30-53dc-a4b4-350353c56f83', 'Giro sentado con banda elástica', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.', 'Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.', 'Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.', 'Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.', 'Repite el giro hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los oblicuos y el core con rotación controlada, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1011'),
('0d6d8d6e-68f4-5625-a597-90de5bf7caf8', 'Remo sentado con agarre supino y banda elástica', ARRAY['Siéntate con la banda anclada delante y sujeta los extremos con las palmas hacia arriba.', 'Tira de la banda hacia el abdomen llevando los codos cerca del cuerpo.', 'Junta las escápulas y vuelve despacio manteniendo el pecho alto.', 'Evita encorvarte o tirar con los hombros hacia las orejas.']::text[], 'principiante', 'Trabaja dorsales y bíceps con agarre supino, aumentando la fuerza de tracción y el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5005'),
('1fa19d0e-d85d-5f7f-86ff-b06d5b0f2b97', 'Remo sentado con agarre abierto y banda elástica', ARRAY['Siéntate con la banda anclada delante y sujeta los extremos con agarre amplio.', 'Tira de la banda hacia el pecho separando los codos hacia fuera.', 'Junta las escápulas arriba y vuelve despacio controlando la resistencia.', 'Evita encoger los hombros o balancear el tronco para tirar.']::text[], 'principiante', 'Fortalece la espalda alta y los deltoides posteriores con un agarre amplio que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4454'),
('00e2f527-8948-50d4-a97f-804714584aa5', 'Press de hombros con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.', 'Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.', 'Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los deltoides y los tríceps, mejorando la estabilidad del hombro y la fuerza al empujar por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0997'),
('ebfb1a8f-c6f0-5a74-b571-6dabd88e52f3', 'Encogimiento de hombros con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.', 'Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.', 'Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.', 'Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los trapecios superiores para mejorar la postura y la fuerza de la cintura escapular en la vida diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1018'),
('b06e66f2-edda-5487-9ae6-e14167df21e9', 'Flexión lateral con banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado, con el brazo pegado al cuerpo.', 'Inclina el tronco hacia el lado contrario a la banda manteniendo la espalda recta y sin rotar.', 'Vuelve despacio resistiendo la tensión de la banda y exhala al subir.', 'Evita tirar con el brazo o encoger el hombro; el movimiento nace del costado.']::text[], 'principiante', 'Activa los oblicuos y el core para ganar estabilidad lateral del tronco y controlar la inclinación del torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3841'),
('91170afe-72ce-5593-b2c5-584e5040e332', 'Press lateral con banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria a la altura del hombro.', 'Empuja el brazo hacia arriba mientras inclinas ligeramente el tronco hacia el lado de la banda.', 'Vuelve al centro controlando el descenso y exhala en cada empuje.', 'No arquees la zona lumbar ni bloquees la respiración durante el recorrido.']::text[], 'principiante', 'Combina empuje de hombros y flexión lateral para trabajar deltoides, oblicuos y core en un solo gesto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4700'),
('a3057e24-c1be-5e12-8d5d-e3de33962243', 'Abdominal lateral con banda elástica', ARRAY['Sujeta la banda por encima de la cabeza con el brazo estirado y los pies a la anchura de las caderas.', 'Flexiona el tronco hacia el lado de la banda acercando las costillas a la cadera.', 'Vuelve despacio a la posición inicial resistiendo la tensión y exhala al contraer.', 'Evita tirar con el brazo o rotar el torso; el movimiento es solo lateral.']::text[], 'principiante', 'Fortalece oblicuos y core mediante una flexión lateral resistida, útil para estabilidad y control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1020'),
('187d4c00-8fe0-5271-a499-e837dd80a52d', 'Remo en plancha lateral con banda elástica y compañero', ARRAY['Colócate en plancha lateral con el codo apoyado y el cuerpo alineado de cabeza a pies.', 'Sujeta la banda con la mano libre y pide a tu compañero que mantenga la tensión.', 'Tira del codo hacia la cadera llevando la mano al costado y vuelve despacio.', 'Mantén las caderas altas y evita rotar el tronco durante el remo.']::text[], 'principiante', 'Refuerza dorsales y oblicuos manteniendo la plancha lateral mientras remas contra la banda que sujeta tu compañero.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1501'),
('50f3f7f3-07b7-556f-a0e3-701e9ac8d67a', 'Paso lateral con sostén pallof horizontal y banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujétala con las dos manos delante del esternón.', 'Da pasos laterales manteniendo la banda tensa y el tronco sin rotar.', 'Respira con normalidad y mantén las rodillas ligeramente flexionadas.', 'Evita que el torso gire hacia el anclaje o que los pies se junten demasiado.']::text[], 'principiante', 'Trabaja abductores, glúteos y core mientras resistes la rotación de la banda en un desplazamiento lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3776'),
('6b2fca06-b660-5338-9089-4fe22d256501', 'Extensión de tríceps lateral con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo.', 'Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo.', 'Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos.', 'Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con una extensión lateral resistida, mejorando la fuerza y el tono de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0998'),
('c234f571-43a8-5d79-a79d-22382e26e9d3', 'Press de hombros a un brazo con banda elástica', ARRAY['Pisa la banda con el pie contrario y sujeta el extremo con una mano a la altura del hombro.', 'Empuja el brazo hacia arriba sin bloquear del todo el codo y mantén el abdomen firme.', 'Baja despacio controlando la banda y exhala al empujar.', 'Evita inclinarte hacia el lado contrario o encoger el hombro al subir.']::text[], 'principiante', 'Fortalece deltoides y tríceps de forma unilateral, exigiendo además al core para evitar compensaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2996'),
('449b02fd-a40c-55ba-923f-fc79e36b1c01', 'Elevación de gemelos a una pierna con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo.', 'Sujétate de un objeto estable para mantener el equilibrio si es necesario.', 'Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia a la pierna derecha.']::text[], 'principiante', 'Fortalece los gemelos de forma unilateral, mejorando el equilibrio y la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0999'),
('f92a9986-f242-5540-81c8-1796aae932ee', 'Elevación de gemelos inversa a una pierna con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.', 'Sujétate de un objeto estable para mantener el equilibrio.', 'Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia a la otra pierna.']::text[], 'principiante', 'Trabaja la parte anterior de la pierna y los flexores del tobillo, complementando el entrenamiento de gemelos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1000'),
('e54ee9fd-bece-565f-bc55-1eb0c7fad1e8', 'Hiperextensión inversa a una pierna con banda elástica', ARRAY['Túmbate boca abajo sujetando la banda con las manos y engánchala en un pie.', 'Con la pierna estirada, eleva el pie hacia el techo apretando el glúteo.', 'Baja despacio sin dejar que la banda tire de la pierna y exhala al subir.', 'Evita arquear la lumbar en exceso; el movimiento sale de la cadera.']::text[], 'principiante', 'Activa glúteos e isquiotibiales extendiendo la cadera contra la banda, con control del core y la lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4701'),
('8faa9def-3ae3-591e-ac30-f7f6dbbb7da6', 'Sentadilla búlgara con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.', 'Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.', 'Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.', 'Empuja con el talón derecho para regresar a la posición inicial.', 'Repite del otro lado.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la fuerza en cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1001'),
('e16a070c-1f65-582c-aa15-f8214624d0a9', 'Peso muerto rumano a una pierna con banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria, de pie sobre esa pierna.', 'Con la rodilla ligeramente flexionada, lleva la cadera atrás y baja el tronco manteniendo la espalda recta.', 'Baja hasta notar el estiramiento en el isquiotibial y vuelve apretando el glúteo.', 'Evita redondear la espalda o perder el equilibrio hacia un lado.']::text[], 'principiante', 'Trabaja isquiotibiales y glúteos con apoyo unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0919'),
('9ca7bfdd-3a5a-58cf-b130-5815fbe62384', 'Peso muerto a una pierna con remo a un brazo y banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria, con el tronco inclinado y la espalda recta.', 'Baja la cadera atrás mientras la pierna libre se eleva, manteniendo la alineación.', 'Desde esa posición, tira del codo hacia la cadera y vuelve a estirar el brazo.', 'Sube controlando la banda y evita rotar el tronco o redondear la espalda.']::text[], 'principiante', 'Combina cadena posterior y espalda en un ejercicio unilateral que exige equilibrio, coordinación y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3773'),
('128cfe0a-7f62-516c-8d3d-85f8f569e679', 'Esquiador con banda elástica', ARRAY['Sujeta la banda anclada a la altura del pecho y da un paso atrás para crear tensión.', 'Inclina el tronco hacia delante con la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la banda hacia las caderas llevando los codos atrás mientras extiendes las piernas.', 'Vuelve al inicio controlando el movimiento y manteniendo el abdomen firme.', 'Evita redondear la espalda o tirar solo con los brazos.']::text[], 'principiante', 'Trabaja dorsal, glúteos y core con un tirón explosivo que mejora la potencia y la coordinación de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3779'),
('8ed53e6e-647a-5282-9c6c-14977338ef1b', 'Rompecráneos con banda elástica', ARRAY['Ancla la banda por encima de la cabeza y sujeta los extremos con las palmas hacia delante.', 'Coloca los codos altos y pegados a la cabeza con los antebrazos apuntando arriba.', 'Extiende los codos hasta estirar los brazos sin mover los hombros.', 'Sube y baja despacio, controlando la vuelta en dos o tres segundos.', 'Evita abrir los codos hacia los lados o arquear la espalda.']::text[], 'principiante', 'Aísla el tríceps con extensión de codos, útil para ganar fuerza y tono en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1504'),
('f4b91cb4-db1e-5534-9922-bfd98c5cc813', 'Salto dividido con remo a un brazo y banda elástica', ARRAY['Sujeta la banda con una mano y colócate en zancada con el pie contrario adelantado.', 'Salta cambiando de pierna mientras tiras de la banda hacia la cadera con el codo pegado.', 'Aterriza suave con las rodillas flexionadas y el tronco estable.', 'Alterna el remo en cada salto manteniendo el abdomen firme.', 'Evita aterrizar con las piernas rígidas o perder el equilibrio al tirar.']::text[], 'principiante', 'Combina salto pliométrico y remo para potenciar piernas, glúteos y espalda en un gesto explosivo y coordinado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3781'),
('a21cdeb8-cfa7-5ff9-8cae-212b349dfaa9', 'Sentadilla dividida con banda elástica', ARRAY['Pisa la banda con el pie delantero y sujeta los extremos a la altura de los hombros.', 'Da un paso atrás y baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el talón delantero para subir sin bloquear la rodilla.', 'Mantén la rodilla delantera alineada con el pie durante todo el recorrido.', 'Evita inclinarte hacia delante o dejar que la rodilla pase muy por delante del pie.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con una zancada estática que mejora el equilibrio y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4135'),
('6fdf3a6d-ac52-5c21-bbd4-dfa589ba16c8', 'Sentadilla dividida con sostén pallof horizontal y banda elástica', ARRAY['Ancla la banda a un lado y sujétala con las dos manos delante del pecho.', 'Colócate en zancada con el pie delantero apuntando al frente y la banda en tensión.', 'Baja y sube en sentadilla dividida sin dejar que la banda te gire el tronco.', 'Mantén el abdomen apretado y la mirada al frente durante todo el movimiento.', 'Evita rotar el torso o encoger los hombros al resistir la tensión.']::text[], 'principiante', 'Suma antirotación al trabajo de piernas, entrenando cuádriceps, glúteos y oblicuos para un core más estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3775'),
('64d5fbf7-7deb-5348-ab4d-12ef339f4615', 'Sentadilla con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.', 'Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.', 'Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa glúteos y piernas con resistencia extra, ideal para tonificar y mejorar el patrón básico de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1004'),
('f5cdff63-ba5b-52ca-a458-7849fb8e44af', 'Remo en sentadilla con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.', 'Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.', 'Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Combina sentadilla y remo para trabajar glúteos, piernas y espalda en un solo movimiento funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1003'),
('84e4114a-bb06-5335-8aab-e9a6f78bc80d', 'Sentadilla con sostén pallof horizontal y banda elástica', ARRAY['Ancla la banda a un lado y sujétala con las dos manos delante del pecho.', 'Separa los pies a la anchura de los hombros con la banda en tensión.', 'Baja en sentadilla manteniendo el tronco recto y sin girar hacia la banda.', 'Sube empujando con los talones y aprieta el abdomen en todo el recorrido.', 'Evita que la banda te desplace el torso o que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Añade antirotación a la sentadilla para reforzar cuádriceps, glúteos y oblicuos con un core sólido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3774'),
('fd5a3b7e-49e5-5e60-a079-6196f08fcfc2', 'Sentadilla con remo a un brazo y banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria.', 'Baja en sentadilla con el tronco erguido y el brazo estirado hacia delante.', 'Al subir, tira de la banda hacia la cadera llevando el codo atrás.', 'Baja el brazo de forma controlada mientras desciendes de nuevo.', 'Evita rotar el tronco o encoger el hombro al remar.']::text[], 'principiante', 'Combina sentadilla y remo unilateral para entrenar piernas, glúteos y dorsal con control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3770'),
('48735537-4329-5f41-a036-0d69e1c9c1b0', 'Curl de bíceps estándar con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de las caderas y sujeta los extremos.', 'Mantén los codos pegados al torso y las palmas hacia delante.', 'Flexiona los codos subiendo las manos hacia los hombros sin mover los hombros.', 'Baja despacio controlando la banda hasta estirar casi del todo.', 'Evita balancear el tronco o adelantar los codos para subir más.']::text[], 'principiante', 'Aísla el bíceps y el antebrazo con tensión constante, perfecto para tonificar el brazo en cualquier lugar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4086'),
('03f80e62-0a6f-5475-8620-aec0e97fddb2', 'Press de pecho alterno de pie con banda elástica', ARRAY['Ancla la banda detrás de ti a la altura del pecho y sujeta un extremo con cada mano.', 'Da un paso adelante con los codos flexionados y las manos junto al pecho.', 'Empuja un brazo hacia delante hasta estirarlo sin bloquear el codo.', 'Vuelve despacio y repite con el otro brazo manteniendo el abdomen firme.', 'Evita girar el tronco o dejar que la banda te lleve hacia atrás.']::text[], 'principiante', 'Trabaja pectoral, tríceps y core con un press unilateral que exige estabilidad y control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4079'),
('dab8a929-9caf-5720-8d7f-f70131d55267', 'Press militar tras nuca con banda elástica', ARRAY['Pisa la banda con los pies separados y sujeta los extremos detrás de la cabeza.', 'Coloca los codos hacia delante y las manos a la altura de las orejas.', 'Empuja hacia arriba hasta estirar los brazos sin arquear la espalda.', 'Baja despacio hasta la posición inicial manteniendo el abdomen apretado.', 'Evita sacar las costillas o encoger los hombros al empujar.']::text[], 'principiante', 'Refuerza hombros, tríceps y trapecio con un press vertical que mejora la fuerza por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4686'),
('7108fee1-d4be-5371-8cae-8f73f74e10ac', 'Press de pecho de pie con banda elástica', ARRAY['Ancla la banda detrás de ti a la altura del pecho y sujeta los extremos.', 'Da un paso adelante con los codos flexionados y las manos junto al pecho.', 'Empuja las manos hacia delante hasta estirar los brazos sin bloquear los codos.', 'Vuelve despacio controlando la banda y manteniendo el tronco recto.', 'Evita arquear la espalda o adelantar los hombros al empujar.']::text[], 'principiante', 'Fortalece pectoral, tríceps y hombros con un empuje de pie que también activa el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3780'),
('6f83b02e-17da-5b95-9765-64eb91836ded', 'Abdominal de pie con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.', 'Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.', 'Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.', 'Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.', 'Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja recto abdominal y oblicuos con un encogimiento de pie que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1005'),
('f9d41784-3503-5942-a47d-92ca3816bf13', 'Rotación externa de hombro con banda elástica', ARRAY['Ancla la banda a la altura del codo y colócate de lado con el codo pegado al cuerpo.', 'Flexiona el codo a noventa grados con el antebrazo apuntando al frente.', 'Gira el antebrazo hacia fuera sin separar el codo del torso.', 'Vuelve despacio a la posición inicial manteniendo el hombro abajo.', 'Evita encoger el hombro o girar el tronco para ganar recorrido.']::text[], 'principiante', 'Refuerza el manguito rotador y la parte posterior del hombro, clave para prevenir lesiones y mejorar la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0921'),
('c5e0f3ae-db17-553c-8f11-5d826d7fa5ec', 'Curl martillo de pie con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de las caderas y agarra los extremos con las palmas enfrentadas.', 'Mantén los codos pegados al torso y sube las manos hacia los hombros sin mover los brazos.', 'Baja controlando la banda hasta estirar casi del todo el codo.', 'Evita balancear el tronco o adelantar los codos para no perder tensión.']::text[], 'principiante', 'Fortalece bíceps y braquial con agarre neutro, mejorando la fuerza del brazo y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4619'),
('43a0f9ef-f64e-5df5-b7cd-69876118e344', 'Extensión de cadera de pie con banda elástica', ARRAY['Ancla la banda a un punto bajo y colócala en el tobillo, con el cuerpo de espaldas al anclaje.', 'Apóyate en una pared o silla y lleva la pierna hacia atrás sin arquear la zona lumbar.', 'Aprieta el glúteo al final del recorrido y vuelve despacio a la posición inicial.', 'Mantén el abdomen firme y evita girar la cadera hacia fuera.']::text[], 'principiante', 'Activa glúteos y femorales para mejorar la extensión de cadera y estabilizar la pelvis al caminar o correr.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4034'),
('f8b885ea-e151-57d2-8dbd-ae457aa9bf76', 'Press de pecho inclinado de pie con banda elástica', ARRAY['Ancla la banda a un punto bajo detrás de ti y sujeta los extremos a la altura del pecho.', 'Da un paso adelante para crear tensión y mantén un pie delante del otro.', 'Empuja las manos hacia arriba y adelante hasta estirar los brazos sin bloquear los codos.', 'Vuelve despacio controlando la banda y evita arquear la espalda.']::text[], 'principiante', 'Trabaja el pectoral superior y los tríceps con una trayectoria ascendente que también implica a los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0923'),
('e5c29567-c1ec-515b-b190-6071b477cda6', 'Rotación interna de hombro con banda elástica', ARRAY['Ancla la banda a la altura del codo y colócate de lado con el codo pegado al cuerpo y flexionado 90 grados.', 'Gira el antebrazo hacia el abdomen manteniendo el codo fijo contra el costado.', 'Vuelve despacio a la posición inicial sin soltar la tensión.', 'Evita mover el hombro o el tronco para no compensar el movimiento.']::text[], 'principiante', 'Refuerza el manguito rotador y la estabilidad del hombro, útil para prevenir molestias en press y remos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0924'),
('f09772dd-52a9-5615-b636-ccd42f66c0e0', 'Elevación lateral de pie con banda elástica', ARRAY['Pisa la banda con los pies juntos y sujeta los extremos con las palmas hacia dentro.', 'Sube los brazos por los lados hasta la altura de los hombros con los codos ligeramente flexionados.', 'Baja controlando la banda sin dejar que tire de los brazos.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'principiante', 'Aísla el deltoide medio para ganar amplitud de hombro y mejorar la estética de la parte superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0793'),
('6e0da076-9761-5fc2-bc4d-ab7bdd2bc618', 'Curl de pierna de pie con banda elástica', ARRAY['Ancla la banda a un punto bajo y colócala en el tobillo, con el cuerpo de frente al anclaje.', 'Apóyate en una pared y flexiona la rodilla llevando el talón hacia el glúteo.', 'Aprieta el femoral arriba y baja despacio hasta casi estirar la pierna.', 'Mantén la cadera estable y evita arquear la espalda.']::text[], 'principiante', 'Fortalece los isquiotibiales y mejora el control de la rodilla, complementando sentadillas y zancadas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4033'),
('468c7587-695b-5207-a083-43636ad15965', 'Extensión de pierna de pie con banda elástica', ARRAY['Ancla la banda a un punto bajo y colócala en el tobillo, de espaldas al anclaje.', 'Apóyate en una pared y estira la rodilla llevando el pie hacia delante.', 'Aprieta el cuádriceps arriba y vuelve despacio sin dejar caer la pierna.', 'Evita bloquear la rodilla con fuerza o balancear el tronco.']::text[], 'principiante', 'Aísla el cuádriceps y refuerza la rodilla, útil para mejorar la estabilidad en la marcha y la carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0926'),
('0ecd101c-1536-5525-bdb2-50930a8b1711', 'Elevación de pierna de pie con banda elástica', ARRAY['Ancla la banda a un punto bajo y colócala en el tobillo, de espaldas al anclaje.', 'Apóyate en una pared y sube la rodilla hacia delante hasta la altura de la cadera.', 'Baja la pierna despacio manteniendo el abdomen firme.', 'Evita arquear la zona lumbar o inclinarte hacia atrás.']::text[], 'principiante', 'Trabaja flexores de cadera y cuádriceps, mejorando el control de la pierna y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1021'),
('d40dd5dd-66e5-51c3-99b1-786891d55c37', 'Abducción a una pierna de pie en bosu con banda elástica', ARRAY['Coloca la banda por encima de las rodillas o en el tobillo y súbete al bosu con un pie.', 'Mantén el tronco erguido y separa la pierna hacia fuera sin inclinarte.', 'Aprieta el glúteo al final y vuelve despacio al centro.', 'Evita bloquear la rodilla de apoyo o perder el equilibrio por mirar al suelo.']::text[], 'principiante', 'Fortalece abductores y glúteo medio sobre superficie inestable, mejorando el equilibrio y la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10651'),
('2eabfdcb-80d9-5570-831e-1b5e3ba18366', 'Remo de pie para deltoide posterior con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.', 'Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Tira de la banda hacia el pecho, juntando los omóplatos.', 'Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la parte trasera del hombro y la espalda alta, mejorando la postura y el equilibrio muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1022'),
('7a4ed40d-f894-5b00-85c0-4baf3603c454', 'Curl inverso de pie con banda elástica', ARRAY['Pisa la banda con los pies y agarra los extremos con las palmas hacia abajo.', 'Mantén los codos pegados al cuerpo y sube las manos hacia los hombros.', 'Baja controlando la banda hasta estirar los codos casi del todo.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'principiante', 'Refuerza antebrazos y extensores de la muñeca con agarre prono, mejorando la fuerza de agarre y la salud del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6195'),
('71bd23fd-17d3-562c-b7b0-236190faf38e', 'Remo de pie con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta los extremos con los brazos estirados.', 'Da un paso atrás para crear tensión y mantén las rodillas ligeramente flexionadas.', 'Tira de los codos hacia atrás juntando las escápulas sin encoger los hombros.', 'Vuelve despacio y evita arquear la espalda o tirar con los brazos.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides, mejorando la postura y compensando el trabajo de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0930'),
('7166b266-4fb2-5518-bb1b-1978a48f9041', 'Flexión lateral de pie con banda elástica', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado.', 'Inclina el tronco hacia el lado de la banda manteniendo la cadera estable.', 'Vuelve despacio a la posición erguida apretando el oblicuo.', 'Evita girar el tronco o usar impulso para no cargar la lumbar.']::text[], 'principiante', 'Trabaja oblicuos y core con un movimiento controlado que mejora la estabilidad lateral del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4685'),
('d7116796-055d-56d5-aae1-5a41c2ade5f0', 'Remo de pie a un brazo con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta un extremo con una mano.', 'Da un paso atrás y apoya la otra mano en la cadera o en una pared.', 'Tira del codo hacia atrás llevando la mano a la cintura sin girar el tronco.', 'Vuelve despacio y evita encoger el hombro o rotar la cadera.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta de forma unilateral, mejorando la fuerza y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4575'),
('a7acf581-20d4-5bd8-8412-6fed58b8a618', 'Remo de pie a un brazo con giro y banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta un extremo con una mano.', 'Da un paso atrás y tira del codo hacia atrás mientras giras el tronco hacia el lado del remo.', 'Vuelve despacio a la posición inicial controlando la rotación.', 'Evita girar la cadera o tirar con el brazo en lugar de la espalda.']::text[], 'principiante', 'Combina dorsal y oblicuos en un remo unilateral con rotación, mejorando fuerza y control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4146'),
('79daa2ee-2e72-5b4e-8d26-21a38eff668d', 'Remo al mentón a un brazo con banda', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado, brazo extendido y espalda recta.', 'Tira del codo hacia arriba y hacia fuera hasta la altura del hombro, manteniéndolo por encima de la muñeca.', 'Baja despacio controlando la banda y repite sin balancear el tronco.', 'Evita encoger el hombro hacia la oreja: mantén el cuello relajado y el abdomen activo.']::text[], 'principiante', 'Trabaja el deltoides y el trapecio para ganar fuerza y estabilidad en el hombro y la parte alta de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4695'),
('cd41fa03-f3ab-5d01-9713-a3138c7304e5', 'Jalón con brazos rectos con banda', ARRAY['Sujeta la banda por encima de la cabeza con los brazos estirados y una ligera inclinación del tronco.', 'Lleva las manos hacia los muslos manteniendo los codos casi rectos y el pecho abierto.', 'Aprieta el dorsal abajo y vuelve arriba despacio sin perder la tensión.', 'No arquees la zona lumbar: mantén las costillas abajo y el abdomen firme.']::text[], 'principiante', 'Aísla el dorsal ancho para mejorar la fuerza de tracción y la postura, con trabajo secundario de tríceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4576'),
('6e8bebab-f2cc-5d82-9675-02d76d263f54', 'Elevación de pierna recta con banda', ARRAY['Ancla la banda al tobillo y al suelo o a un punto bajo, y sujétate a algo estable.', 'Con la pierna estirada, elévala hacia delante sin doblar la rodilla hasta donde controles.', 'Baja lentamente resistiendo la banda y mantén el tronco erguido todo el tiempo.', 'Evita arquear la espalda o balancearte: el movimiento sale de la cadera.']::text[], 'principiante', 'Refuerza el cuádriceps y los flexores de cadera, útil para estabilidad de rodilla y control del equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0927'),
('ebba9a80-c2ba-5629-8ce9-97317b095aa1', 'Extensión de tríceps de pie con banda', ARRAY['Pisa la banda y sujeta el extremo con las manos detrás de la cabeza, codos apuntando arriba.', 'Estira los codos llevando las manos hacia arriba sin mover los brazos del sitio.', 'Baja despacio hasta notar el estiramiento del tríceps y repite.', 'Mantén los codos cerca de la cabeza y evita abrirlos hacia los lados.']::text[], 'principiante', 'Fortalece el tríceps y mejora la extensión del codo, con apoyo del hombro y el core para estabilizar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4680'),
('1f683974-5fc2-5804-bfb8-4d2587773c73', 'Subida al cajón con banda', ARRAY['Coloca una banda alrededor de los muslos, justo por encima de las rodillas.', 'Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.', 'Sube a la plataforma con el pie derecho, empujando con el talón.', 'Extiende la pierna izquierda hacia atrás, manteniéndola recta.', 'Baja el pie izquierdo de nuevo hasta el suelo.', 'Repite subiendo a la plataforma con el pie izquierdo.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa glúteos y cuádriceps para ganar fuerza unilateral y estabilidad en la cadera y la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1008'),
('5ca56c0a-18b8-5714-bb8b-20a31bf139f1', 'Peso muerto con piernas semirrígidas con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos.', 'Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.', 'Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo.', 'Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente.', 'Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales.', 'Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja glúteos e isquios con un patrón de bisagra de cadera que refuerza la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1009'),
('07a5637c-2863-5bee-9fb2-2892491f1c0c', 'Jalón con brazos rectos y banda elástica', ARRAY['Ancla la banda en un punto alto y sujétala con ambas manos, brazos estirados al frente.', 'Lleva las manos hacia los muslos manteniendo los codos casi rectos y el pecho arriba.', 'Aprieta el dorsal abajo y vuelve arriba controlando la banda.', 'No flexiones los codos ni redondees la espalda durante el recorrido.']::text[], 'principiante', 'Aísla el dorsal ancho para mejorar la fuerza de tracción y la postura, con ayuda de tríceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0928'),
('822abf6f-3b63-56d6-8b85-8689394e9dec', 'Peso muerto con piernas semirrígidas y espalda recta con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas.', 'Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.', 'Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo.', 'Siente el estiramiento en los isquiotibiales mientras bajas la banda.', 'Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza glúteos e isquios con bisagra de cadera, cuidando la alineación de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1023'),
('75196ccf-d8dd-514b-94c2-8411710616ff', 'Peso muerto con piernas rectas con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies.', 'Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos.', 'Activa el core y mantén una ligera flexión en las rodillas.', 'Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Baja la banda hacia el suelo manteniendo las piernas rectas.', 'Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la cadena posterior y los erectores espinales para mejorar la fuerza y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1010');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('5e9042dd-7c0b-5221-a309-9c032426a100', 'Balanceo con banda', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta el extremo con ambas manos.', 'Haz una bisagra de cadera llevando el culo atrás y la banda entre las piernas.', 'Empuja la cadera hacia delante con fuerza para subir la banda hasta la altura del pecho.', 'Mantén la espalda neutra y evita tirar con los brazos: la fuerza sale de la cadera.']::text[], 'principiante', 'Potencia glúteos e isquios con un movimiento explosivo de cadera que también exige core y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4678'),
('9c98634f-710a-54b3-86eb-5e7a52caf37e', 'Thruster con banda', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta los extremos a la altura de los hombros.', 'Baja en sentadilla con el pecho alto y las rodillas alineadas con los pies.', 'Sube con fuerza y, al extender las piernas, empuja la banda por encima de la cabeza.', 'Baja la banda a los hombros y encadena la siguiente repetición sin perder el ritmo.']::text[], 'principiante', 'Combina sentadilla y press para trabajar piernas, glúteos y hombros en un gesto global de cuerpo entero.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2970'),
('626737ad-33e1-52c9-bdd3-95e223872b55', 'Patada de tríceps con banda', ARRAY['Pisa la banda y sujeta el extremo con una mano, tronco inclinado y codo pegado al costado.', 'Estira el codo llevando la mano hacia atrás hasta que el brazo quede recto.', 'Aprieta el tríceps arriba y vuelve despacio sin mover el codo del sitio.', 'Evita balancear el tronco o subir el hombro para completar el recorrido.']::text[], 'principiante', 'Aísla el tríceps para tonificar la parte posterior del brazo, con apoyo de hombro y antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4143'),
('a30879c1-3670-502b-a760-959c9bfbb541', 'Giro con banda', ARRAY['Ancla la banda a un punto fijo a la altura del pecho y sujétala con ambas manos.', 'Con los brazos estirados, gira el tronco hacia un lado resistiendo la banda.', 'Vuelve al centro controlando y repite hacia el otro lado.', 'Mantén las caderas estables y evita tirar solo con los brazos.']::text[], 'principiante', 'Activa abdominales y oblicuos para mejorar la rotación del tronco y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3591'),
('07fe1bd1-735c-54ec-aa23-a1f3abb0854b', 'Press sobre la cabeza con giro con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.', 'Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.', 'Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.', 'Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.', 'Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.', 'Repite el empuje y el giro hacia el lado opuesto.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el deltoides y el tríceps con un press que añade rotación para el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1012'),
('7d8e8439-b7cb-50ef-ac66-06f78c422746', 'Elevación de gemelos a dos piernas con banda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.', 'Sujeta los extremos de la banda con las manos para mantener el equilibrio.', 'Levanta los talones del suelo lo más alto posible, usando las pantorrillas.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los gemelos y la estabilidad del tobillo para mejorar el empuje y la propiocepción del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1369'),
('f2c40082-3de6-5d4e-a83b-ce6171a39f0e', 'Jalón supino con banda elástica', ARRAY['Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.', 'Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.', 'Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal ancho y los bíceps tirando de la banda; útil para fortalecer la espalda sin poleas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1013'),
('b6b05a67-fdca-57bc-a1ef-d71101679853', 'Bicicleta acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda anclada a un punto fijo y sujeta los extremos con las manos.', 'Eleva los hombros y las piernas del suelo manteniendo la zona lumbar pegada.', 'Pedalea alternando piernas mientras llevas las manos hacia delante con tensión.', 'Espira al acercar las manos y controla el retorno sin arquear la espalda.', 'Evita tirar del cuello y mantén el movimiento lento y controlado.']::text[], 'principiante', 'Activa el abdomen, los oblicuos y el core con un movimiento de pedaleo que mejora la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3778'),
('c161df03-72ea-5c51-b5ff-b993a92bd797', 'Dead bug con banda para tren superior', ARRAY['Túmbate boca arriba con la banda anclada detrás de la cabeza y sujeta los extremos.', 'Eleva brazos y piernas formando un ángulo recto con el suelo.', 'Extiende un brazo y la pierna contraria mientras mantienes la lumbar pegada.', 'Espira al extender y vuelve despacio a la posición inicial.', 'Evita que la espalda baja se despegue del suelo en ningún momento.']::text[], 'principiante', 'Refuerza el core y la coordinación entre brazos y piernas, mejorando la estabilidad lumbar en decúbito supino.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2938'),
('850630f1-7588-5584-9fe2-31c998d8881e', 'Abdominal superior con banda elástica', ARRAY['Túmbate boca arriba con la banda anclada a un punto bajo y sujeta los extremos junto al pecho.', 'Flexiona las rodillas y apoya los pies en el suelo.', 'Eleva los hombros del suelo acercando el esternón a la pelvis.', 'Espira al subir y baja controlando la tensión de la banda.', 'Evita tirar del cuello con las manos y no uses impulso.']::text[], 'principiante', 'Fortalece la parte alta del recto abdominal con resistencia extra, mejorando la flexión del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4083'),
('c5de1d84-6d60-5537-ad38-3081ce21d5b1', 'Remo al mentón con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta los extremos.', 'Con los brazos extendidos y el torso erguido, tira de la banda hacia el mentón.', 'Guía los codos hacia arriba y hacia fuera, sin subir los hombros.', 'Espira al tirar y baja despacio controlando la banda.', 'Evita encogerte o usar impulso con la espalda.']::text[], 'principiante', 'Trabaja los deltoides y el trapecio elevando la banda; mejora la fuerza del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0934'),
('d27b5c8b-e18d-5dab-9108-c10a935bef50', 'Rotación externa de hombro con remo al mentón y banda', ARRAY['Pisa la banda y sujeta los extremos con las palmas hacia delante.', 'Tira de la banda hacia el mentón llevando los codos arriba y afuera.', 'Al llegar arriba, rota los antebrazos hacia fuera sin mover los codos.', 'Espira al tirar y vuelve despacio a la posición inicial.', 'Evita subir los hombros o arquear la espalda durante el movimiento.']::text[], 'principiante', 'Combina remo y rotación externa para reforzar el manguito rotador y la parte posterior del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0935'),
('5ba889a6-8faa-5df2-9382-9ea878f924ab', 'V-up con banda elástica', ARRAY['Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.', 'Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con un movimiento en V que exige control y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1014'),
('983fbba8-0640-5e59-86ca-ccec32b370c7', 'Pallof press vertical con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.', 'Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.', 'Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.', 'Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.', 'Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.', 'Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Ejercicio isométrico que fortalece el core y los oblicuos resistiendo la rotación del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1015'),
('b940fbc2-76f1-5a52-9da2-b24d483abf02', 'Estiramiento de hombros de calentamiento con banda', ARRAY['Sujeta la banda con las dos manos a la anchura de los hombros.', 'Eleva los brazos por delante hasta la altura del pecho sin encoger los hombros.', 'Abre la banda separando las manos y vuelve despacio al centro.', 'Respira de forma fluida y mantén el torso erguido.', 'Evita arquear la espalda o subir los hombros hacia las orejas.']::text[], 'principiante', 'Prepara los hombros y el manguito rotador antes de entrenar, mejorando la movilidad y reduciendo el riesgo de lesión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4516'),
('ca03f5bd-a08f-5809-8483-266f718909d7', 'Curl de muñeca con banda elástica', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo.', 'Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.', 'Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los antebrazos y la muñeca, mejorando el agarre y la estabilidad en otros ejercicios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1016'),
('2b776f81-d470-54fe-8fd8-3d5fad8889b7', 'Elevación en Y con banda elástica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.', 'Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo.', 'Junta los omóplatos en la parte superior del movimiento.', 'Baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los deltoides y la parte alta de la espalda, mejorando la postura y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1017'),
('c0c633d2-fa68-556f-8d21-0f541fd31e9a', 'Elevación de glúteos e isquios con banda elástica', ARRAY['Túmbate boca abajo con la banda anclada delante y sujeta los extremos con los pies.', 'Mantén las caderas pegadas al suelo y las piernas extendidas.', 'Flexiona las rodillas acercando los talones a los glúteos contra la banda.', 'Espira al flexionar y baja despacio controlando la tensión.', 'Evita despegar las caderas del suelo o usar impulso.']::text[], 'principiante', 'Refuerza isquiotibiales y glúteos con resistencia, mejorando la fuerza posterior de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4849'),
('dfb4eecc-4a42-5835-80d1-905232cc9be8', 'Bicho muerto con banda para tren inferior', ARRAY['Túmbate boca arriba con la banda anclada delante y sujeta los extremos con los pies.', 'Eleva las piernas formando un ángulo recto y pega la lumbar al suelo.', 'Extiende una pierna hacia delante contra la banda y vuelve al centro.', 'Alterna las piernas espirando en cada extensión.', 'Evita arquear la espalda o despegar la lumbar del suelo.']::text[], 'principiante', 'Activa el abdomen y los flexores de cadera con resistencia en las piernas, mejorando el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4839'),
('ceac7407-e623-5b5b-a7f6-b3e919d3e556', 'Curl de bíceps con barra', ARRAY['De pie, sujeta la barra con las palmas hacia arriba y los codos pegados al torso.', 'Flexiona los codos subiendo la barra hasta la altura del pecho.', 'Espira al subir y baja despacio controlando el peso.', 'Mantén la espalda recta y evita balancear el torso.', 'No dejes que los codos se separen del cuerpo durante el movimiento.']::text[], 'intermedio', 'Trabaja el bíceps y el braquial con la barra, aumentando la fuerza y el volumen del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4721'),
('ed001e47-f912-50da-a710-db813d81123e', 'Peso muerto con barra', ARRAY['Colócate con los pies a la anchura de las caderas y la barra pegada a las espinillas.', 'Agarra la barra con las manos a la anchura de los hombros y la espalda recta.', 'Empuja el suelo con los pies y sube extendiendo caderas y rodillas a la vez.', 'Espira al subir y baja controlando el descenso con la espalda neutra.', 'Evita redondear la espalda o separar la barra del cuerpo.']::text[], 'intermedio', 'Ejercicio global que fortalece glúteos, isquios y espalda baja, mejorando la fuerza y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11093'),
('05776c05-6390-5d80-b83b-5479e781706b', 'Curl de bíceps alterno con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.', 'Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.', 'Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, alternando los brazos.']::text[], 'intermedio', 'Fortalece los bíceps y antebrazos con un movimiento alterno que permite cargar más peso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0023'),
('18036b5b-3e64-5fb0-9efa-cac3ea75ccdf', 'Sentadilla anderson con barra', ARRAY['Coloca la barra sobre los hombros por detrás del cuello y separa los pies a la anchura de los hombros.', 'Baja en sentadilla profunda hasta que la barra quede cerca de las corvas.', 'Empuja con los pies y sube extendiendo las piernas sin perder la espalda neutra.', 'Mantén el core apretado y evita redondear la zona lumbar al arrancar desde abajo.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos partiendo desde abajo, mejorando la fuerza en el punto más débil del recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5659'),
('2d637771-3938-5652-9436-06f4d44881ec', 'Encogimiento con agarre abierto tras la espalda y barra', ARRAY['Sujeta la barra por detrás de los muslos con las palmas hacia atrás y las manos bien separadas.', 'Mantén los brazos rectos y los hombros relajados al inicio.', 'Eleva los hombros hacia las orejas sin doblar los codos y aguanta un segundo arriba.', 'Baja controlado y evita encoger con impulso de piernas o balanceo.']::text[], 'intermedio', 'Trabaja los trapecios superiores con un rango amplio, útil para mejorar la postura y la fuerza del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5226'),
('76b6d332-cefd-5487-ab86-f29db665909a', 'Peso muerto asistido con banda elástica y barra', ARRAY['Ancla la banda al suelo y pásala por la barra para que ayude en la fase de subida.', 'Colócate con los pies a la anchura de las caderas y agarra la barra con la espalda recta.', 'Empuja el suelo con los pies y extiende caderas y rodillas a la vez hasta quedar de pie.', 'Baja la barra controlando el movimiento y evitando que la espalda se redondee.']::text[], 'intermedio', 'Refuerza glúteos e isquios con ayuda elástica, ideal para aprender el patrón y ganar fuerza en la subida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4841'),
('c068ee9d-d76b-5b43-85dd-adf79da84dc1', 'Sentadilla en banco con barra y banda elástica', ARRAY['Coloca la banda por debajo de los pies y sobre la barra apoyada en la espalda.', 'Siéntate hacia atrás hasta tocar el banco con los glúteos sin perder la curvatura lumbar.', 'Empuja con los pies y sube extendiendo caderas y rodillas contra la tensión de la banda.', 'Mantén las rodillas alineadas con los pies y evita que se metan hacia dentro.']::text[], 'intermedio', 'Activa glúteos y cuádriceps con resistencia extra, útil para mejorar la potencia en la fase de subida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4061'),
('1e0ed6ff-9ab4-59b6-bdda-46ca55bb0e03', 'Peso muerto rumano con barra y banda elástica', ARRAY['Pisa la banda y pásala por la barra, agarra con las manos a la anchura de los hombros.', 'Con las rodillas ligeramente flexionadas, lleva las caderas atrás bajando la barra pegada a las piernas.', 'Nota el estiramiento en los isquios y sube empujando las caderas hacia delante.', 'Evita redondear la espalda y no bajes más allá de donde controles el movimiento.']::text[], 'intermedio', 'Estira y fortalece isquios y glúteos con tensión añadida, mejorando la cadena posterior y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4173'),
('a7fc8688-5593-52d0-99a9-5dee73c7f8d6', 'Sentadilla con barra y bandas', ARRAY['Pisa la banda y colócala sobre la barra apoyada en la espalda alta.', 'Separa los pies a la anchura de los hombros y apunta las puntas ligeramente hacia fuera.', 'Baja flexionando caderas y rodillas manteniendo el pecho arriba y el core firme.', 'Sube empujando el suelo y evita que las rodillas se desplacen hacia dentro.']::text[], 'intermedio', 'Fortalece piernas y core con resistencia progresiva, mejorando la potencia al final del recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3530'),
('2b462670-0740-546f-9c25-0187c02779af', 'Peso muerto sumo con barra y banda elástica', ARRAY['Pisa la banda con los pies bien separados y pásala por la barra.', 'Agarra la barra con las manos dentro de las piernas y el pecho arriba.', 'Empuja el suelo separando las rodillas y extiende caderas hasta quedar de pie.', 'Baja controlando y mantén la espalda neutra sin redondear la zona lumbar.']::text[], 'intermedio', 'Trabaja glúteos y aductores con una postura amplia, mejorando la fuerza de la cadena posterior y la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4203'),
('59724f2c-ac3b-5c77-bc10-8e5370bdbe03', 'Press de banca con banda elástica y disco con barra', ARRAY['Fija la banda al banco y pásala por la barra, tumbado con los pies apoyados.', 'Agarra la barra algo más ancho que los hombros y baja el disco al pecho controlado.', 'Empuja hacia arriba extendiendo los codos sin perder la tensión de la banda.', 'Mantén los omóplatos retraídos y evita rebotar la barra en el pecho.']::text[], 'intermedio', 'Desarrolla pectorales y tríceps con tensión creciente, útil para mejorar la potencia en el press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9932'),
('41fadd39-b9cc-57b3-92ae-d2d531049b92', 'Peso muerto tras la espalda con barra', ARRAY['Coloca la barra detrás de los muslos y agárrala con las palmas hacia atrás.', 'Con los pies a la anchura de las caderas, mantén el pecho arriba y el core firme.', 'Empuja el suelo y extiende caderas y rodillas hasta quedar erguido.', 'Baja controlado pegando la barra a las piernas y sin redondear la espalda.']::text[], 'intermedio', 'Refuerza glúteos e isquios con la barra detrás, mejorando la postura y la fuerza de la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5663'),
('333421bc-0d74-51e8-b2da-041a627c5ae6', 'Push press tras nuca con barra', ARRAY['Apoya la barra detrás del cuello sobre los trapecios con las manos algo más anchas que los hombros.', 'Flexiona ligeramente las rodillas y extiéndelas para impulsar la barra hacia arriba.', 'Termina el press extendiendo los codos y manteniendo el core apretado.', 'Baja la barra controlada y evita arquear en exceso la zona lumbar.']::text[], 'intermedio', 'Fortalece hombros y tríceps con impulso de piernas, mejorando la potencia del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4857'),
('07775399-72da-5810-bb70-74b09c336b17', 'Encogimiento detrás de la espalda con barra', ARRAY['Sujeta la barra por detrás de los muslos con las palmas hacia atrás.', 'Mantén los brazos rectos y los hombros bajos al inicio.', 'Eleva los hombros hacia las orejas sin doblar los codos y aguanta arriba.', 'Baja despacio y evita usar impulso de piernas o balanceo del torso.']::text[], 'intermedio', 'Aísla los trapecios con la barra detrás, útil para mejorar la fuerza del cuello y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3730'),
('aabe7e78-c26c-5429-969e-6bee99120d6e', 'Sentadilla frontal en banco con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.', 'Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.', 'Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los cuádriceps y glúteos con una sentadilla que exige una postura erguida y estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0024'),
('9be29434-e0f8-55d6-a894-680b4fe4729d', 'Press de banca contra cadenas con barra', ARRAY['Coloca las cadenas sobre la barra y túmbate en el banco con los pies firmes.', 'Agarra la barra algo más ancho que los hombros y baja al pecho controlado.', 'Empuja hacia arriba extendiendo los codos mientras las cadenas ganan peso.', 'Mantén los omóplatos retraídos y evita rebotar la barra en el pecho.']::text[], 'intermedio', 'Trabaja pectorales y tríceps con resistencia creciente, mejorando la potencia en la fase final del press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4201'),
('9fe55406-8a05-5e4e-80b9-72cefa86b01a', 'Atrape de press de banca con barra', ARRAY['Túmbate en el banco con los pies apoyados y agarra la barra a la anchura de los hombros.', 'Baja la barra al pecho controlando el movimiento y manteniendo los omóplatos retraídos.', 'Empuja hacia arriba y, al final, recibe la barra con los codos ligeramente flexionados.', 'Evita bloquear los codos de golpe y mantén el core apretado durante todo el recorrido.']::text[], 'intermedio', 'Mejora la recepción y el control del press de banca, útil para ganar seguridad y estabilidad en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10560'),
('d67b9f52-c9f0-5ce0-85e7-88a34fadc716', 'Press de banca con dos tablas y barra', ARRAY['Túmbate en el banco con los pies firmes y coloca las dos tablas sobre el pecho.', 'Agarra la barra a la anchura de los hombros y sácala del soporte con control.', 'Baja la barra hasta tocar las tablas y haz una pausa breve sin rebotar.', 'Empuja hacia arriba exhalando y mantén los omóplatos retraídos durante todo el recorrido.', 'Evita levantar la cadera del banco o perder la tensión en la espalda alta.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps limitando el recorrido para ganar fuerza en la fase media del empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4069'),
('dc41f131-84ca-56ab-a34d-6932a97f38d5', 'Press de banca con tres tablas y barra', ARRAY['Colócate en el banco con los pies apoyados y las tres tablas sobre el torso.', 'Sujeta la barra con agarre medio y retira los seguros con ayuda si es necesario.', 'Desciende la barra de forma controlada hasta contactar con las tablas.', 'Empuja la barra hacia arriba exhalando sin bloquear bruscamente los codos.', 'No dejes que los codos se abran en exceso ni que la barra rebote sobre las tablas.']::text[], 'intermedio', 'Fortalece pectorales y tríceps con un recorrido parcial que refuerza el punto de máxima dificultad del press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4068'),
('c186a5bc-423b-5636-b6a2-219495714482', 'Press de banca con kettlebell colgante y barra', ARRAY['Cuelga la kettlebell de la banda y engánchala a la barra antes de tumbarte.', 'Túmbate con los pies firmes y saca la barra del soporte con control.', 'Baja la barra despacio manteniendo la kettlebell estable y el core apretado.', 'Empuja hacia arriba exhalando sin dejar que la kettlebell oscile.', 'Evita mover la cadera o perder la tensión abdominal para compensar el balanceo.']::text[], 'intermedio', 'Añade inestabilidad al press para exigir más al core y estabilizadores mientras trabajas pecho y tríceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4414'),
('0c0a4980-6e79-5239-9935-8772ae7eaa36', 'Sentadilla en banco con barra', ARRAY['Coloca una barra en un soporte de sentadillas a la altura del pecho.', 'Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.', 'Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos controlando la profundidad al sentarte en el banco, ideal para aprender el patrón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0026'),
('ddb5a7b9-3328-5bbc-80df-52cf4ec30d73', 'Sentadilla en banco con cadenas y barra', ARRAY['Coloca la barra en la espalda alta y las cadenas enganchadas a los extremos.', 'Separa los pies a la anchura de los hombros y baja controlado hasta tocar el banco.', 'Haz una pausa breve sin relajarte y empuja el suelo para subir exhalando.', 'Mantén el pecho alto y las rodillas alineadas con los pies durante todo el movimiento.', 'Evita dejarte caer sobre el banco o perder la tensión del core al bajar.']::text[], 'intermedio', 'Desarrolla fuerza en cuádriceps y glúteos con resistencia variable que aumenta al subir por la tensión de las cadenas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1509'),
('33bcc45b-3b8f-5a3b-8db1-6c063a6452b2', 'Pullover con brazos flexionados y barra', ARRAY['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.', 'Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.', 'Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira y trabaja el dorsal ancho y el pecho con un recorrido controlado por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1316'),
('3e5736cb-ea1e-5d52-b190-44488095d3e5', 'Remo inclinado con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.', 'Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.', 'Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps con un tirón horizontal que mejora la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0027'),
('6dbdf6fa-0d76-572e-a595-5d7a9074fdb2', 'Remo inclinado alterno con agarre abierto y barra', ARRAY['Inclina el torso con la espalda recta y sujeta la barra con agarre abierto.', 'Tira de la barra hacia un lado llevando el codo atrás mientras el otro brazo mantiene la posición.', 'Alterna los lados de forma controlada sin girar el tronco.', 'Exhala en cada tirón y mantén el core apretado para proteger la zona lumbar.', 'Evita balancear el cuerpo o encoger los hombros al tirar.']::text[], 'intermedio', 'Trabaja dorsales y espalda alta de forma alterna, mejorando el control y la simetría del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3991'),
('1ffe8cf6-cb81-52ee-9332-ecc5aa73a97f', 'Remo inclinado con agarre abierto y barra', ARRAY['Inclina el torso con la espalda neutra y sujeta la barra con las manos más abiertas que los hombros.', 'Tira de la barra hacia el abdomen bajo llevando los codos hacia fuera.', 'Junta las escápulas al final del tirón y haz una pausa breve.', 'Baja la barra de forma controlada exhalando durante el esfuerzo.', 'Evita redondear la espalda o usar impulso de cadera para subir el peso.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con un agarre amplio que enfatiza la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3721'),
('65de53fb-75c8-59cc-a4e6-b2989fd8863c', 'Remo inclinado con agarre abierto plus y barra', ARRAY['Coloca el torso inclinado con la espalda recta y agarra la barra con las manos anchas.', 'Tira de la barra hacia el pecho bajo llevando los codos hacia atrás y afuera.', 'Aprieta las escápulas al final y controla la bajada sin soltar la tensión.', 'Exhala al tirar e inhala al bajar la barra.', 'Evita encoger los hombros o balancear el tronco para completar la repetición.']::text[], 'intermedio', 'Trabaja dorsales y espalda alta con un tirón amplio que mejora la fuerza y el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3992'),
('049d6b6c-92dd-58b9-b5f2-a647c5c8b388', 'Sentadilla al cajón con barra', ARRAY['Coloca la barra en la espalda alta y sitúate delante del cajón con los pies a la anchura de los hombros.', 'Baja controlado llevando la cadera atrás hasta sentarte suavemente en el cajón.', 'Mantén la tensión y empuja el suelo para subir exhalando sin rebotar.', 'Conserva el pecho alto y las rodillas alineadas con los pies.', 'Evita dejarte caer o perder la curvatura neutra de la espalda al sentarte.']::text[], 'intermedio', 'Desarrolla glúteos y cuádriceps controlando la profundidad al sentarte en el cajón, mejorando la técnica y la potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4962'),
('e08a1974-de9d-5b4b-b659-ff73e59f1bce', 'Press Z mariposa con barra', ARRAY['Siéntate en el suelo con las piernas abiertas y la barra a la altura de los hombros.', 'Aprieta el core y empuja la barra hacia arriba exhalando.', 'Baja la barra de forma controlada hasta la altura del pecho.', 'Mantén el torso erguido y evita arquear la espalda baja.', 'No bloquees la respiración ni dejes que la barra se desplace hacia delante.']::text[], 'intermedio', 'Trabaja los hombros y el core sentado en el suelo, exigiendo estabilidad y fuerza en el empuje vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10049'),
('8ce231ba-e3c6-5ef8-b671-bf7aeea43ef5', 'Press California con barra', ARRAY['Túmbate en el banco y sujeta la barra con agarre medio sobre el pecho.', 'Baja la barra hacia el cuello flexionando los codos y manteniéndolos cerca del cuerpo.', 'Extiende los codos para llevar la barra hacia arriba sin mover los hombros.', 'Exhala al empujar y controla la bajada en cada repetición.', 'Evita abrir los codos en exceso o dejar caer la barra rápido hacia la cara.']::text[], 'intermedio', 'Combina press y extensión para trabajar pecho, tríceps y hombros con un recorrido que exige control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9930'),
('6335bbd2-3e6d-50f4-8cde-3869d9aec59a', 'Press de banca con barra para control de antebrazos', ARRAY['Túmbate en el banco con los pies firmes y agarra la barra con las muñecas rectas.', 'Saca la barra del soporte y bájala controlada hasta el pecho.', 'Mantén los antebrazos verticales y empuja hacia arriba exhalando.', 'Revisa que las muñecas no se doblen hacia atrás en ningún momento.', 'Evita rebotar en el pecho o perder la alineación de los codos.']::text[], 'intermedio', 'Refuerza pecho y tríceps prestando atención a la posición de muñecas y antebrazos para mejorar la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2336'),
('3787ceb7-cc01-5ecb-bfb2-29ebb170e2e8', 'Cargada y envión con barra', ARRAY['Coloca la barra sobre los muslos con agarre firme y la espalda recta.', 'Tira explosivo extendiendo caderas y rodillas para llevar la barra a los hombros.', 'Recibe la barra en posición de sentadilla frontal y ponte de pie con control.', 'Flexiona ligeramente las piernas y empuja la barra sobre la cabeza exhalando.', 'Evita tirar con los brazos antes de extender las piernas o perder la barra por delante.']::text[], 'avanzado', 'Movimiento olímpico que desarrolla potencia en trapecios, piernas y hombros con una coordinación exigente.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5122'),
('054a3878-b1af-5e3b-ad12-693b6a9f89e4', 'Cargada y press con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.', 'Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.', 'Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.', 'Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.', 'Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.', 'Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.', 'Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'avanzado', 'Ejercicio explosivo de cuerpo completo que potencia piernas, espalda y hombros, mejorando la fuerza y la coordinación.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0028'),
('74d8655f-2920-55df-b747-3e10a5249dd1', 'Peso muerto de cargada con barra', ARRAY['Coloca la barra sobre el medio del pie con las espinillas casi tocándola.', 'Agarra la barra con las manos justo fuera de las piernas y saca pecho.', 'Empuja el suelo con los pies y sube la barra pegada al cuerpo.', 'Extiende caderas y rodillas a la vez sin redondear la espalda.', 'Evita tirar con los brazos: estos solo cuelgan de la barra.']::text[], 'avanzado', 'Trabaja glúteos, isquiotibiales y espalda para ganar fuerza en el primer tirón de la cargada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1515'),
('8cbf0bba-5573-5528-b2f3-0d6617b656d5', 'Cargada desde bloques con barra', ARRAY['Coloca los bloques a la altura de la rodilla y apoya la barra encima.', 'Agarra la barra con las manos fuera de las piernas y la espalda recta.', 'Empuja con los pies y extiende caderas y rodillas de forma explosiva.', 'Encoge los hombros y guía la barra cerca del cuerpo al subir.', 'Evita halar con los brazos antes de extender las piernas.']::text[], 'avanzado', 'Desarrolla potencia de cadera y trapecio al iniciar el tirón desde una altura que refuerza la técnica.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1516'),
('bdea4ffe-fff9-5ac1-bc1e-c57c15287b14', 'Tirón alto de cargada con barra', ARRAY['Sitúate con la barra en el suelo y los pies a la anchura de las caderas.', 'Agarra la barra y mantén la espalda neutra con el pecho arriba.', 'Extiende caderas y rodillas con fuerza y tira la barra hacia arriba.', 'Encoge los hombros y lleva los codos altos al final del tirón.', 'Evita doblar los codos demasiado pronto: primero extiende el cuerpo.']::text[], 'avanzado', 'Potencia trapecios, glúteos y hombros con un tirón explosivo que mejora la fase de extensión de la cargada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5705'),
('6400b128-3f5e-56ef-84b0-d453ff31ea89', 'Jalón de cargada con barra', ARRAY['Coloca la barra en el suelo con los pies a la anchura de las caderas.', 'Agarra la barra con las manos fuera de las piernas y la espalda recta.', 'Empuja el suelo y extiende caderas y rodillas de forma explosiva.', 'Mantén los brazos rectos y encoge los hombros al final del tirón.', 'Evita redondear la espalda o tirar con los brazos antes de extender.']::text[], 'avanzado', 'Refuerza glúteos, isquiotibiales y trapecio en la fase de tirón, clave para la potencia de la cargada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1517'),
('a0fbf3bf-99ab-5e9c-b021-7d011e52f35f', 'Sentadilla frontal con agarre de cargada y barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.', 'Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.', 'Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con la barra al frente, mejorando la postura y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0029'),
('537b5420-ff4d-5cee-872f-4d0d832eabee', 'Curl de bíceps con agarre cerrado y barra', ARRAY['De pie, sujeta la barra con las palmas hacia arriba y las manos juntas.', 'Mantén los codos pegados al torso y la espalda recta.', 'Sube la barra flexionando los codos sin mover los hombros.', 'Baja despacio controlando el movimiento y sin balancear el cuerpo.', 'Evita usar impulso de cadera para subir el peso.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo con un agarre estrecho que aumenta la tensión en el pico del músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4981'),
('a4fa43ec-8f63-58b5-83c9-5cca5864a917', 'Press larsen con agarre cerrado y barra', ARRAY['Túmbate en el banco con los pies en el aire y la barra sobre el pecho.', 'Agarra la barra con las manos a la anchura de los hombros.', 'Baja la barra al pecho manteniendo el core firme y los glúteos apretados.', 'Empuja la barra hacia arriba sin arquear la zona lumbar.', 'Evita levantar la cadera del banco durante el empuje.']::text[], 'intermedio', 'Trabaja pecho y tríceps con los pies elevados, aumentando la tensión del core y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6271'),
('cd0152f5-a179-59c2-a694-55cd355f0f3e', 'Press de banca con agarre cerrado y barra', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el trabajo en tríceps y pecho con un agarre estrecho que reduce la implicación del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0030'),
('2956b26c-f54f-5b9f-ae01-38bde1a516c3', 'Complejo de peso muerto, cargada y paso con barra', ARRAY['Empieza de pie con la barra en el suelo y los pies a la anchura de las caderas.', 'Realiza un peso muerto con piernas rectas manteniendo la espalda neutra.', 'Sube la barra a los hombros con una cargada explosiva.', 'Da un paso adelante y vuelve, controlando el equilibrio.', 'Evita perder la tensión del core entre movimientos.']::text[], 'avanzado', 'Encadena varios movimientos para trabajar glúteos, espalda y hombros, mejorando la resistencia y la técnica.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '3328'),
('80ca62e3-cd5b-52a3-8d5e-89ac7ade29ee', 'Sentadilla core con barra', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros.', 'Aprieta el core y baja la cadera como si fueras a sentarte.', 'Mantén el pecho arriba y las rodillas alineadas con los pies.', 'Sube empujando el suelo con los talones y exhala al final.', 'Evita que las rodillas se metan hacia dentro al bajar.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core con una sentadilla que exige estabilidad y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10092'),
('a9d2a1d9-a0a3-5045-b7f6-b73a97f9b49c', 'Curl con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.', 'Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio clásico para bíceps y antebrazo que gana fuerza y volumen en los brazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0031'),
('36a07676-3671-59dc-a79b-49175b648a43', 'Curl, press y extensión con barra', ARRAY['De pie, sujeta la barra con las palmas hacia arriba y los codos pegados.', 'Sube la barra hasta los hombros flexionando los codos.', 'Empuja la barra por encima de la cabeza extendiendo los brazos.', 'Baja la barra a la nuca y extiende los codos con control.', 'Evita arquear la espalda al empujar la barra.']::text[], 'intermedio', 'Combina bíceps, hombros y tríceps en un solo movimiento para trabajar todo el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5883'),
('ff32f2e5-8c30-5d79-ba17-a3cab16d7997', 'Peso muerto contra cadenas con barra', ARRAY['Coloca la barra con cadenas en el suelo y sitúate con los pies a la anchura de las caderas.', 'Agarra la barra con las manos fuera de las piernas y la espalda recta.', 'Empuja el suelo y extiende caderas y rodillas subiendo la barra pegada al cuerpo.', 'Baja la barra controlando el movimiento y manteniendo el core firme.', 'Evita redondear la espalda al levantar el peso.']::text[], 'intermedio', 'Aumenta la carga en la parte alta del recorrido, potenciando glúteos y espalda con resistencia variable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4199'),
('f0fb6e6c-e6fa-5f19-9fe6-0b75ac8923f6', 'Peso muerto con barra desde bloques', ARRAY['Coloca la barra sobre bloques a la altura de la rodilla y sitúate con los pies a la anchura de las caderas.', 'Agarra la barra con las manos fuera de las piernas y baja las caderas manteniendo la espalda neutra.', 'Empuja el suelo con los pies y extiende caderas y rodillas hasta quedar erguido, apretando glúteos arriba.', 'Baja la barra de forma controlada hasta los bloques sin redondear la espalda.', 'Evita tirar con la espalda baja: inicia el movimiento empujando con las piernas.']::text[], 'intermedio', 'Trabaja glúteos e isquios con un rango parcial que permite mover más carga y reforzar la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6034'),
('80be3b92-e4c5-5819-8c4b-600c37b2f108', 'Peso muerto desde déficit con barra', ARRAY['Sube a una plataforma baja y coloca la barra en el suelo con los pies a la anchura de las caderas.', 'Agarra la barra, baja las caderas y mantén el pecho arriba y la espalda neutra.', 'Empuja el suelo con los pies y extiende caderas y rodillas hasta quedar de pie.', 'Baja la barra controlando el recorrido hasta el suelo sin perder la tensión.', 'No fuerces el rango si la espalda se redondea: reduce la altura del déficit.']::text[], 'intermedio', 'Aumenta el rango de recorrido para ganar fuerza en la salida y trabajar glúteos, isquios y espalda baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5702'),
('2081a81e-8ef2-5806-ad03-df1007986f2a', 'Remo con parada en el suelo desde rack con barra', ARRAY['Coloca la barra en el rack a una altura cómoda y sitúate frente a ella con los pies a la anchura de las caderas.', 'Inclínate con la espalda recta, agarra la barra y deja los brazos extendidos.', 'Tira de la barra hacia el abdomen llevando los codos atrás y junta las escápulas.', 'Baja la barra hasta apoyarla en el rack y haz una pausa breve antes de la siguiente repetición.', 'Evita balancear el tronco para tirar: mantén el core firme durante todo el recorrido.']::text[], 'intermedio', 'Refuerza la espalda alta y los dorsales con una pausa que elimina el rebote y exige control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4126'),
('e3954504-bfb5-56f3-9dec-f8de2a2b86d1', 'Zancada en banco declinado con barra', ARRAY['Coloca la barra sobre la espalda alta y apoya un pie en el banco declinado con el otro detrás.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido y el core activo.', 'Empuja con la pierna delantera para volver a la posición inicial sin bloquear la rodilla.', 'Mantén el pie delantero bien apoyado y evita que la rodilla se vaya hacia dentro.', 'Haz las repeticiones de forma controlada y cambia de pierna al terminar la serie.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un apoyo declinado que aumenta el rango y la demanda de estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1518'),
('97bb8e58-f031-5ada-b59b-0fcc53206a42', 'Pullover declinado con brazos flexionados y barra', ARRAY['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.', 'Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.', 'Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.', 'Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales y tríceps con los brazos flexionados, reduciendo la tensión en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0034'),
('3fb810ff-82fc-5e15-993e-eb41f47c54fe', 'Press declinado con agarre cerrado y barra', ARRAY['Túmbate en el banco declinado y agarra la barra con las manos a la anchura de los hombros.', 'Baja la barra hacia el pecho con los codos cerca del cuerpo y de forma controlada.', 'Empuja la barra hacia arriba extendiendo los codos sin bloquear de golpe.', 'Mantén las muñecas rectas y evita abrir los codos en exceso.', 'Respira al empujar y controla la bajada en cada repetición.']::text[], 'intermedio', 'Enfoca el trabajo en tríceps y pecho con un agarre cerrado que limita la participación del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10115'),
('f432c0e7-0e4c-5047-a7dc-28aeec660ca8', 'Press declinado con agarre cerrado a la frente y barra', ARRAY['Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.', 'Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.', 'Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps llevando la barra hacia la frente en un banco declinado con agarre cerrado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0035'),
('53c96a40-1a46-5938-b88d-42576ffe1b45', 'Pullover declinado con barra', ARRAY['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.', 'Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.', 'Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.', 'Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.', 'Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales y tríceps con un recorrido amplio que estira el pecho en el banco declinado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1255'),
('258046a4-6445-5c78-8cc8-4b39666dd33c', 'Press declinado con agarre abierto y barra', ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.', 'Baja la barra hacia el pecho, manteniendo los codos hacia los lados.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Prioriza el pectoral con un agarre amplio que aumenta el estiramiento y el recorrido en el banco declinado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0036'),
('97af8e6c-0c9a-58d6-a606-2deb2b688881', 'Pullover declinado con agarre abierto y barra', ARRAY['Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.', 'Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.', 'Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.', 'Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales y tríceps con un agarre amplio que amplía el recorrido en el banco declinado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0037'),
('03170dbc-5969-51c3-a9c6-136e088666ec', 'Curl de arrastre con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.', 'Deja que la barra cuelgue a la longitud del brazo frente a los muslos.', 'Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con un recorrido que mantiene la barra cerca del cuerpo y reduce la tensión en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0038'),
('cd5566a8-8100-5f5c-a4ec-e180988b1b02', 'Sentadilla con agarre de cargada y talones elevados con barra', ARRAY['Coloca la barra en los hombros con agarre de cargada y apoya los talones sobre una cuña.', 'Baja las caderas manteniendo el pecho arriba y las rodillas alineadas con los pies.', 'Desciende hasta donde puedas sin perder la espalda neutra y empuja con los pies para subir.', 'Mantén el core firme y evita que las rodillas se vayan hacia dentro.', 'Respira al bajar y controla la subida sin rebotar en el fondo.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con los talones elevados, favoreciendo una sentadilla más vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9516'),
('6ff77d71-4930-5898-969b-426094d5ee21', 'Sentadilla con talones elevados y barra', ARRAY['Coloca la barra sobre la espalda alta y apoya los talones sobre una cuña o disco.', 'Separa los pies a la anchura de los hombros y activa el core antes de bajar.', 'Baja las caderas manteniendo el tronco erguido y las rodillas alineadas con los pies.', 'Empuja con los pies para subir sin bloquear las rodillas de golpe.', 'Evita levantar los talones o perder la curvatura lumbar durante el recorrido.']::text[], 'intermedio', 'Enfoca el cuádriceps con una sentadilla más vertical gracias a la elevación de los talones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4178'),
('9dbfb033-e60e-5994-96e8-230d71495f33', 'Curl inverso con barra gruesa', ARRAY['Sujeta la barra gruesa con las palmas hacia abajo y los brazos extendidos.', 'Flexiona los codos llevando la barra hacia los hombros sin mover los hombros.', 'Baja la barra de forma controlada hasta extender los codos.', 'Mantén las muñecas firmes y evita balancear el tronco para subir.', 'Usa un peso que te permita controlar la bajada en cada repetición.']::text[], 'intermedio', 'Refuerza antebrazos y bíceps con un agarre prono que exige más a los músculos del antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10110'),
('040ee9e7-c63d-5d0e-ae69-0b67f2e9e385', 'Press de banca con pies planos y barra', ARRAY['Túmbate en el banco con los pies planos en el suelo y agarra la barra a la anchura de los hombros.', 'Baja la barra hacia el pecho con los codos a unos 45 grados y de forma controlada.', 'Empuja la barra hacia arriba hasta extender los brazos sin bloquear de golpe.', 'Mantén los glúteos y la espalda alta apoyados en el banco durante todo el movimiento.', 'Evita rebotar la barra en el pecho y respira al empujar.']::text[], 'intermedio', 'Trabaja pectorales y tríceps con los pies apoyados, mejorando la estabilidad y la técnica base del press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6584'),
('946718e1-9225-55e1-b5d2-07750d43cb61', 'Peso muerto en postura de rana con barra', ARRAY['Coloca los pies muy abiertos y las puntas hacia fuera, con la barra pegada a las espinillas.', 'Agarra la barra con las manos por dentro de las piernas y saca el pecho antes de tirar.', 'Empuja el suelo con los pies y extiende la cadera hasta quedar de pie, apretando glúteos arriba.', 'Baja controlando la barra pegada al cuerpo y evita redondear la espalda baja.']::text[], 'intermedio', 'Trabaja glúteos y aductores con una base ancha que aumenta el rango y la tensión en la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9696'),
('d6f7e807-d250-5417-be92-8b23751aaf36', 'Sentadilla frontal al pecho con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.', 'Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con la barra al pecho, lo que exige más control del core y la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0039'),
('868bc141-4ce4-5446-9653-93d138ac991f', 'Sentadilla frontal con barra y banda elástica', ARRAY['Pasa la banda por debajo de los pies y súbela hasta los muslos, con la barra apoyada al pecho.', 'Separa los pies a la anchura de los hombros y mantén los codos altos durante todo el recorrido.', 'Baja flexionando rodillas y cadera con el pecho erguido, sin que las rodillas se metan hacia dentro.', 'Empuja el suelo para subir y controla la bajada sin perder la tensión de la banda.']::text[], 'intermedio', 'Potencia cuádriceps y glúteos añadiendo tensión de banda para mejorar la estabilidad y la velocidad de subida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3871'),
('817df008-b671-5884-beec-0396b0656973', 'Zancada con barra en posición frontal', ARRAY['Sujeta la barra apoyada en los hombros delanteros con los codos altos y el core firme.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo manteniendo el torso vertical.', 'Empuja con el pie delantero para volver a la posición inicial sin inclinarte hacia delante.', 'Evita que la rodilla delantera se vaya hacia dentro y respira al subir.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos en unilateral, mejorando el equilibrio y la fuerza de cada pierna por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3399'),
('12bf8eb0-c24e-594f-9239-39f7d7dde739', 'Zancada hacia atrás con barra en posición frontal', ARRAY['Coloca la barra al pecho con los codos altos y los pies juntos.', 'Lleva un pie atrás y baja la rodilla hacia el suelo con el torso erguido.', 'Impulsa con la pierna delantera para volver a la posición inicial y alterna el lado.', 'Mantén el core apretado y no dejes que la rodilla delantera se desplace demasiado hacia delante.']::text[], 'intermedio', 'Enfoca el trabajo en glúteos y cuádriceps con un paso atrás que reduce la tensión en la rodilla delantera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4390'),
('15391111-831f-5bfb-b10a-deab4c515553', 'Sentadilla dividida con barra en posición frontal', ARRAY['Sujeta la barra al pecho con los codos altos y da un paso amplio hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso vertical y el peso repartido.', 'Empuja con el pie delantero para subir sin juntar los pies.', 'Evita inclinarte hacia delante y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos en posición dividida, mejorando la estabilidad de cadera y el control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4397'),
('13654c75-c4c4-5451-9425-937740ad67ef', 'Zancada caminando con barra en posición frontal', ARRAY['Coloca la barra al pecho con los codos altos y da un paso al frente.', 'Baja la rodilla trasera hacia el suelo y empuja para avanzar con la otra pierna.', 'Mantén el torso erguido y el core firme mientras caminas.', 'Evita pasos cortos y no dejes que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos de forma dinámica, mejorando la coordinación y la fuerza en cada paso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4409'),
('51a98869-226a-5e73-9bb6-5cf5c0b23a1d', 'Elevación frontal con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.', 'Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoides anterior para ganar fuerza y volumen en la parte delantera del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0041'),
('15a14754-5689-51e7-a521-391266ff2c65', 'Elevación frontal y pullover con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.', 'Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.', 'Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina hombro y pecho en un movimiento que trabaja la parte superior del torso y la movilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0040'),
('b24df725-7382-5674-b944-ad958d80bf75', 'Sentadilla frontal con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros.', 'Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con la barra al pecho, exigiendo más control del core y la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0042'),
('ccc44c3a-33de-5299-97fe-da783833157b', 'Subida frontal al cajón con barra', ARRAY['Coloca la barra al pecho con los codos altos y apoya un pie entero sobre el cajón.', 'Empuja con la pierna de arriba para subir, sin impulsarte con la de abajo.', 'Sube el cuerpo hasta extender la cadera y baja controlando el movimiento.', 'Evita que la rodilla de apoyo se vaya hacia dentro y mantén el torso erguido.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos de forma unilateral, mejorando la potencia y el equilibrio al subir al cajón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3728'),
('41a0c1ab-816f-5311-92f3-81efdc10bc89', 'Cargada completa con barra', ARRAY['Coloca la barra sobre el empeine con los pies a la anchura de la cadera y agarra con las manos fuera de las piernas.', 'Tira de la barra pegada al cuerpo extendiendo piernas y cadera de forma explosiva.', 'Cuando la barra llegue a la altura de la cadera, encoge los hombros y tira de los codos hacia arriba para recibirla en los hombros.', 'Baja en sentadilla para amortiguar y ponte de pie con la barra apoyada al pecho.', 'Evita tirar con los brazos y mantén la espalda neutra durante todo el movimiento.']::text[], 'avanzado', 'Movimiento de halterofilia que desarrolla potencia en piernas, espalda y hombros en un solo gesto explosivo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5287'),
('219b4e80-6a8a-5e59-9a23-991adb91bda6', 'Sentadilla con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.', 'Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.', 'Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.', 'Baja hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.', 'Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio básico que fortalece glúteos, cuádriceps y core, mejorando la fuerza global y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0043'),
('4f93e22e-d721-597f-89cd-d9e5dd01d1ca', 'Sentadilla completa con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.', 'Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.', 'Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.', 'Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.', 'Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps en un rango completo, desarrollando fuerza y control en la parte inferior del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1461'),
('4bcb2bb4-5ca5-5900-b055-ad7e278a8f5f', 'Sentadilla Zercher completa con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad.', 'Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.', 'Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con la barra en el pliegue de los codos, exigiendo mucho control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1545'),
('8545880f-cc2b-5fef-884c-32adbadd4301', 'Empuje de caderas con barra', ARRAY['Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.', 'Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.', 'Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa breve en la parte alta, apretando los glúteos.', 'Baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos e isquios elevando la cadera con carga, mejorando la extensión de cadera y la fuerza en el puente.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1409'),
('06103fa7-7e26-53fd-bd1b-17265638da8c', 'Puente de glúteos con barra y manos en la barra', ARRAY['Coloca la barra sobre la cadera y apoya los pies a la anchura de los hombros.', 'Agarra la barra con las manos para estabilizarla durante todo el recorrido.', 'Empuja con los talones y sube la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja controlando sin arquear la zona lumbar.', 'Evita empujar con la lumbar en lugar de los glúteos.']::text[], 'intermedio', 'Activa glúteos e isquios con la cadera elevada, estabilizando la barra con las manos para ganar control y potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2964'),
('38615f1e-127d-5547-8aab-c838812d2054', 'Puente de glúteos con barra y piernas en banco', ARRAY['Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.', 'Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.', 'Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa breve en la parte alta, apretando los glúteos.', 'Baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la cadera con los pies apoyados en un banco para aislar glúteos e isquios con mayor rango y tensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3562'),
('d947f42a-a1e2-53b7-8a12-b469972b2a3f', 'Good morning con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.', 'Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.', 'Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.', 'Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece isquios y espalda baja mediante la flexión de cadera con barra, mejorando el patrón de bisagra.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0044'),
('4aa3457c-0d9c-58a1-b02a-0baede8f579e', 'Press de banca guillotina con barra', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.', 'Haz una pausa breve cuando la barra esté justo encima del cuello.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de press que enfatiza el pecho con mayor apertura de codos, aumentando el estiramiento del pectoral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0045'),
('914f8fac-f007-5ebc-af4d-299bed546c90', 'Sentadilla hack con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.', 'Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con la barra tras las piernas, permitiendo una sentadilla profunda y estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0046'),
('b42d705b-c8d6-5667-a057-787e3c385150', 'Press de hombros con una rodilla en el suelo y barra', ARRAY['Colócate con una rodilla en el suelo y la barra a la altura de los hombros.', 'Agarra la barra con las manos algo más anchas que los hombros.', 'Empuja la barra hacia arriba hasta extender los brazos sin bloquear de golpe.', 'Baja controlando hasta la altura del pecho y mantén el core firme.', 'Evita arquear la espalda al empujar la carga.']::text[], 'intermedio', 'Fortalece hombros y core en posición de media rodilla, mejorando la estabilidad y el empuje vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9694'),
('cdef32f9-76b7-5529-ac9b-9192a6a8fd88', 'Levantamiento thor a media rodilla con barra', ARRAY['Colócate de rodillas con la barra sujeta delante del cuerpo.', 'Mantén el core activo y la espalda recta durante todo el movimiento.', 'Eleva y rota la barra de forma controlada hacia un lado.', 'Vuelve al centro y repite hacia el otro lado sin perder la postura.', 'Evita tirar con los brazos; el movimiento nace del tronco.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con control rotacional desde media rodilla, mejorando la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10195'),
('bf9e35d0-daf2-563a-a62e-f41e1e3d19f7', 'Cargada colgada con barra', ARRAY['Sujeta la barra con agarre prono a la anchura de los hombros, de pie.', 'Baja la barra hasta media muslo manteniendo la espalda recta.', 'Extiende con fuerza caderas y rodillas y encoge los hombros.', 'Recibe la barra en los hombros flexionando rodillas y codos.', 'Evita tirar solo con los brazos; usa la extensión de cadera.']::text[], 'avanzado', 'Movimiento de halterofilia que desarrolla potencia de glúteos y cadena posterior desde la posición colgada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1520'),
('312df15d-3dba-5863-9dea-52cb88f30b7d', 'Cargada colgada bajo las rodillas con barra', ARRAY['Sujeta la barra con agarre prono y colócala bajo las rodillas.', 'Mantén la espalda neutra y los hombros sobre la barra.', 'Extiende caderas y rodillas de forma explosiva.', 'Recibe la barra en los hombros con rodillas flexionadas.', 'Evita redondear la espalda al iniciar el tirón.']::text[], 'avanzado', 'Variante de cargada desde más abajo que exige mayor potencia de cadera y control de la cadena posterior.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1521'),
('04fa45db-a303-52c5-8c3e-d35d56fc4fe9', 'Tirón alto de cargada desde colgado con barra', ARRAY['Sujeta la barra con agarre prono a la anchura de los hombros.', 'Baja la barra hasta media muslo con la espalda recta.', 'Extiende caderas y rodillas explosivamente.', 'Tira de la barra hacia arriba con los codos altos y cerca del cuerpo.', 'Evita usar solo los brazos; la potencia viene de las piernas.']::text[], 'avanzado', 'Desarrolla trapecios y potencia de cadera con un tirón vertical explosivo desde la posición colgada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '10107'),
('d12b781c-64ab-5e07-8e7d-69571b9d7fe0', 'Cargada de potencia desde colgado con barra', ARRAY['Sujeta la barra con agarre prono y posiciónate de pie.', 'Baja la barra hasta media muslo manteniendo la espalda neutra.', 'Extiende caderas y rodillas con rapidez y encoge los hombros.', 'Recibe la barra en los hombros con una flexión ligera de rodillas.', 'Evita recibir la barra con la espalda redondeada.']::text[], 'avanzado', 'Ejercicio explosivo que potencia glúteos e isquios recibiendo la barra en posición alta de sentadilla.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5704'),
('4510040a-f291-58c3-9bd5-a555c4b8c186', 'Arrancada colgada con barra', ARRAY['Sujeta la barra con agarre amplio y posiciónate de pie.', 'Baja la barra hasta media muslo con la espalda recta.', 'Extiende caderas y rodillas explosivamente y encoge los hombros.', 'Recibe la barra sobre la cabeza con los brazos extendidos.', 'Evita bloquear los codos antes de estabilizar la barra.']::text[], 'avanzado', 'Movimiento olímpico que desarrolla potencia total de cadera y hombros elevando la barra sobre la cabeza.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1522'),
('548df03b-603c-5f03-8511-2eee1b3bbe5f', 'Arrancada colgada bajo las rodillas con barra', ARRAY['Sujeta la barra con agarre amplio y colócala bajo las rodillas.', 'Mantén la espalda neutra y los hombros sobre la barra.', 'Extiende caderas y rodillas de forma explosiva.', 'Recibe la barra sobre la cabeza con brazos extendidos.', 'Evita redondear la espalda al iniciar el tirón.']::text[], 'avanzado', 'Variante de arrancada desde más abajo que exige mayor potencia y control de la cadena posterior.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1523'),
('300ff562-09ac-5ce1-af7e-27829b0a51af', 'Balance de arrancada con empuje con barra', ARRAY['Coloca la barra sobre los hombros con agarre amplio.', 'Flexiona ligeramente las rodillas y empuja la barra hacia arriba.', 'Recibe la barra sobre la cabeza con los brazos extendidos.', 'Estabiliza la posición con el core firme antes de bajar.', 'Evita perder la barra hacia delante por falta de control.']::text[], 'avanzado', 'Ejercicio técnico que mejora la recepción de la arrancada y la estabilidad de hombros y core.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1524'),
('966850ad-344c-50c9-8d24-c091279c99b7', 'Tirón alto con barra', ARRAY['Colócate de pie con la barra a la altura de los muslos y los pies a la anchura de las caderas.', 'Extiende las caderas y las rodillas para impulsar la barra hacia arriba mientras la guías cerca del cuerpo.', 'Tira con los codos altos hasta llevar la barra a la altura del pecho y exhala en el tirón.', 'Baja la barra de forma controlada flexionando ligeramente las rodillas.', 'Evita encoger los hombros antes de tiempo y no uses un peso que te obligue a curvar la espalda.']::text[], 'avanzado', 'Trabaja trapecios y hombros con potencia de todo el cuerpo, útil para mejorar la explosividad y la coordinación en halterofilia.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '10106'),
('84ae6402-2d07-5aa7-bb0d-e71ea2091f2d', 'Empuje de cadera con barra', ARRAY['Apoya la parte alta de la espalda en un banco y coloca la barra sobre las caderas con una almohadilla.', 'Pon los pies a la anchura de los hombros y las rodillas flexionadas, con la barbilla ligeramente recogida.', 'Empuja con los talones y extiende las caderas hasta que el tronco quede paralelo al suelo, apretando los glúteos.', 'Baja de forma controlada sin dejar caer la cadera de golpe.', 'Evita arquear la zona lumbar en la parte alta del movimiento.']::text[], 'intermedio', 'Fortalece los glúteos y los isquiotibiales, mejorando la extensión de cadera y el rendimiento en sentadillas y carreras.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1060'),
('e4d62f00-cad6-53c6-9353-5a5241bbff4f', 'Empuje de cadera con barra y banda elástica', ARRAY['Coloca la banda por encima de las rodillas y la barra sobre las caderas con la espalda apoyada en un banco.', 'Separa ligeramente las rodillas contra la banda y apoya los pies firmes en el suelo.', 'Empuja con los talones y extiende las caderas apretando los glúteos en la parte alta.', 'Baja de forma controlada manteniendo la tensión de la banda.', 'Evita juntar las rodillas o perder la tensión elástica durante el recorrido.']::text[], 'intermedio', 'Añade tensión constante a los glúteos y aductores, mejorando la estabilidad de la cadera y la fuerza en la extensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3873'),
('e4f85317-20ee-5931-811f-098c8ffa1063', 'Peso muerto con agarre hook y barra', ARRAY['Coloca la barra sobre el suelo y sitúate con los pies a la anchura de las caderas y la barra pegada a las espinillas.', 'Agarra la barra con el pulgar atrapado bajo los dedos y baja las caderas manteniendo la espalda neutra.', 'Empuja el suelo con los pies y extiende caderas y rodillas a la vez, manteniendo la barra cerca del cuerpo.', 'Bloquea la cadera arriba sin hiperextender la espalda y exhala al terminar.', 'Evita redondear la zona lumbar o tirar con los brazos flexionados.']::text[], 'intermedio', 'Refuerza glúteos, isquiotibiales y espalda baja, además de mejorar la fuerza de agarre con la técnica del pulgar bloqueado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7237'),
('a8a8abc8-70b9-5323-882f-bafc748edf12', 'Press de banca inclinado con agarre cerrado y barra', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Túmbate en el banco con los pies planos sobre el suelo.', 'Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el trabajo en los tríceps y la parte superior del pecho, útil para ganar fuerza en empujes y mejorar el bloqueo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1719'),
('bd3186b4-0346-57e0-868e-09159d595e80', 'Elevación de deltoide posterior inclinado acostado con barra', ARRAY['Túmbate boca abajo en un banco inclinado con la barra colgando y las palmas mirando hacia dentro.', 'Con los codos ligeramente flexionados, eleva la barra hacia los lados hasta la altura de los hombros.', 'Aprieta los omóplatos arriba y exhala suavemente.', 'Baja la barra de forma controlada sin dejar caer los brazos.', 'Evita usar impulso con la espalda o encoger el cuello.']::text[], 'intermedio', 'Aísla el deltoide posterior y la espalda alta, corrigiendo desequilibrios y mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3722'),
('288c5d0f-cf51-5a7f-93d9-6b2e93f0e1bc', 'Remo inclinado para deltoide posterior con barra', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta la barra con las palmas hacia abajo.', 'Tira de la barra hacia el pecho abriendo los codos hacia los lados.', 'Aprieta los omóplatos al final del recorrido y exhala.', 'Baja la barra de forma controlada manteniendo la posición del tronco.', 'Evita redondear la espalda o tirar con los brazos en lugar de con la espalda.']::text[], 'intermedio', 'Trabaja el deltoide posterior y los romboides, mejorando la fuerza de tracción y la estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5853'),
('3338a522-bdb2-5fd1-802f-14acdab55dc7', 'Curl araña inclinado con agarre inverso y apoyo en el pecho con barra', ARRAY['Apoya el pecho en un banco inclinado y deja los brazos colgando con la barra sujeta en agarre inverso.', 'Flexiona los codos llevando la barra hacia los hombros sin mover el tronco.', 'Aprieta el antebrazo arriba y exhala suavemente.', 'Baja la barra de forma lenta y controlada hasta extender los codos.', 'Evita balancear el cuerpo o abrir los codos hacia los lados.']::text[], 'intermedio', 'Aísla los antebrazos y el braquial con el pecho apoyado, reduciendo el impulso y mejorando el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3988'),
('ea7a1e46-d81e-509f-b0cc-4e88de2528ed', 'Press inclinado con agarre inverso y barra', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros.', 'Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps y parte superior del pecho con un agarre que cambia el ángulo de empuje y reduce la tensión en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0048'),
('2890fdf3-4e69-53ce-a2e0-77b26a521d58', 'Elevación de hombros inclinada con barra', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.', 'Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.', 'Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.', 'Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el serrato anterior y los hombros, mejorando la estabilidad escapular y el control del omóplato en empujes.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0050'),
('c8f387dd-c329-5fc5-82ce-b4987e9ed748', 'Rompecráneos inclinado con barra', ARRAY['Túmbate en un banco inclinado con la barra sujeta por encima del pecho y los brazos extendidos.', 'Flexiona los codos llevando la barra hacia la frente sin mover los brazos.', 'Extiende los codos para volver a la posición inicial y exhala al empujar.', 'Mantén los codos apuntando al techo durante todo el recorrido.', 'Evita abrir los codos o usar impulso con los hombros.']::text[], 'intermedio', 'Aísla el tríceps en un banco inclinado, aumentando el estiramiento y la fuerza en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4344'),
('25cfb489-1ec9-5546-bf33-9f3bc50f585e', 'Press de banca inclinado con agarre abierto e inverso y barra', ARRAY['Túmbate en un banco inclinado y sujeta la barra con un agarre amplio y las palmas hacia ti.', 'Baja la barra de forma controlada hacia la parte alta del pecho con los codos abiertos.', 'Empuja la barra hacia arriba hasta extender los brazos y exhala al empujar.', 'Mantén los omóplatos retraídos y los pies firmes en el suelo.', 'Evita bajar la barra al cuello o perder el control por un peso excesivo.']::text[], 'intermedio', 'Enfatiza la parte superior del pecho y los hombros con un agarre amplio e inverso que cambia el estímulo del empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1173'),
('cdccd1cd-6645-58eb-b660-0e4e1b29b584', 'Curl de muñeca inclinado con apoyo en el pecho y barra', ARRAY['Apoya los antebrazos en un banco inclinado con las muñecas fuera del borde y sujeta la barra con las palmas hacia arriba.', 'Flexiona las muñecas llevando la barra hacia arriba sin mover los codos.', 'Aprieta suavemente arriba y exhala.', 'Baja la barra de forma lenta hasta estirar las muñecas.', 'Evita usar impulso con los brazos o levantar los antebrazos del banco.']::text[], 'intermedio', 'Fortalece los flexores de la muñeca y el agarre con el antebrazo apoyado, mejorando el rendimiento en tracciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3987'),
('8935c927-d812-5e5b-8980-4989395f054d', 'Curl jefferson con barra', ARRAY['Colócate de pie sobre una plataforma con la barra sujeta con las palmas hacia abajo y los pies separados.', 'Flexiona las rodillas y redondea la espalda lentamente para bajar la barra hacia los pies.', 'Respira de forma pausada y siente el estiramiento sin forzar.', 'Sube vértebra a vértebra apretando los glúteos al final.', 'Evita usar mucho peso o bajar de golpe sin control.']::text[], 'principiante', 'Mejora la movilidad de la columna y la flexibilidad de isquiotibiales y glúteos con una carga ligera y controlada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10857'),
('da819479-854b-5871-b770-25eb7174be89', 'Peso muerto jefferson con barra', ARRAY['Colócate de pie con la barra sujeta con las palmas hacia abajo y los pies a la anchura de las caderas.', 'Flexiona las rodillas y redondea la espalda de forma controlada para bajar la barra hacia los pies.', 'Mantén la barra cerca de las piernas y respira de forma pausada.', 'Sube extendiendo las caderas y apretando los glúteos al final.', 'Evita cargar demasiado peso o perder el control de la espalda.']::text[], 'intermedio', 'Combina fuerza de glúteos e isquiotibiales con movilidad de columna, mejorando la extensión de cadera y la flexibilidad posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5706'),
('3404c371-4164-5af7-8b6d-faabed7c7333', 'Sentadilla de preparación del envión', ARRAY['Coloca la barra sobre los deltoides traseros y separa los pies a la anchura de los hombros.', 'Flexiona las rodillas y baja el cuerpo unos centímetros manteniendo el torso vertical.', 'Empuja el suelo con los pies y extiende las piernas de forma explosiva sin despegar los talones.', 'Mantén la espalda neutra y evita que las rodillas se metan hacia dentro durante el descenso.']::text[], 'avanzado', 'Trabaja cuádriceps y glúteos con una flexión rápida que prepara el impulso del envión y mejora la potencia de piernas.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1525'),
('c0ff0a9f-8fdc-5e12-8206-45ab1bd33e6c', 'Press JM con barra', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de press que enfatiza el tríceps y la parte alta del pecho, útil para ganar fuerza en el bloqueo final.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0052'),
('293e7c8b-d6e2-5e43-a81f-86a636a34010', 'Puente de glúteos kas con barra', ARRAY['Siéntate en el suelo con la barra sobre la cadera y apoya la parte alta de la espalda en un banco.', 'Coloca los pies planos y separados a la anchura de la cadera, con las rodillas alineadas.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y muslos sin arquear la lumbar.', 'Aprieta el glúteo arriba un segundo y baja controlando el movimiento.', 'Evita empujar con la lumbar o hiperextender la espalda al final del recorrido.']::text[], 'intermedio', 'Aísla el glúteo con la cadera apoyada y rango corto, ideal para hipertrofia y control de la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5451'),
('f8a99f78-72f5-5cc8-8057-670b2e5a39d9', 'Subida al cajón con rodilla arriba', ARRAY['Coloca la barra sobre la espalda y apoya un pie completo sobre el cajón.', 'Empuja con la pierna de arriba y sube extendiendo la cadera mientras elevas la rodilla contraria.', 'Baja de forma controlada apoyando primero el pie libre en el suelo.', 'Mantén el torso erguido y evita impulsarte con la pierna de abajo.', 'Controla el descenso para no golpear el cajón ni perder el equilibrio.']::text[], 'intermedio', 'Ejercicio unilateral que trabaja glúteos y cuádriceps, mejora el equilibrio y la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4401'),
('c00ea417-cde0-59c3-a9e8-7c53645cf02f', 'Press larsen', ARRAY['Túmbate en el banco con los pies elevados y sin tocar el suelo.', 'Agarra la barra a la anchura de los hombros y sácala del soporte con control.', 'Baja la barra al pecho manteniendo el core firme y los glúteos en el banco.', 'Empuja hasta extender los brazos sin arquear la lumbar ni perder la posición.', 'Evita balancear las piernas o despegar la cadera del banco durante el recorrido.']::text[], 'intermedio', 'Press de banca sin apoyar los pies que activa el core y el pecho, mejorando la estabilidad y la fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6270'),
('3bdd1fab-767a-52d2-8878-f6b5e9324c76', 'Press con giro de piernas', ARRAY['Túmbate con la barra sobre el pecho y las rodillas flexionadas.', 'Empuja la barra hacia arriba mientras giras las piernas hacia un lado de forma controlada.', 'Vuelve al centro y repite el giro hacia el lado contrario.', 'Mantén los omóplatos apoyados y evita arquear la lumbar al empujar.', 'Controla la rotación para no perder la alineación de cadera y hombros.']::text[], 'intermedio', 'Movimiento de empuje con rotación de cadera que implica glúteos, oblicuos y core para ganar estabilidad y potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2811'),
('5446cd2e-6cc9-592a-a74e-f564ed9add27', 'Sentadilla con barra baja', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.', 'Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.', 'Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Sentadilla con la barra en la espalda baja que prioriza glúteos y cadena posterior, mejorando la fuerza general de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1435'),
('39847b92-57ee-5c76-adcd-42b83c74d61b', 'Sentadilla dividida baja', ARRAY['Coloca la barra sobre la espalda y da un paso amplio hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con el pie delantero para volver a la posición inicial sin mover los pies.', 'Mantén la rodilla delantera alineada con el pie y evita que se vaya hacia dentro.', 'Respira de forma constante y controla el descenso en cada repetición.']::text[], 'intermedio', 'Trabajo unilateral de cuádriceps y glúteos con zancada estática que mejora el equilibrio y la fuerza de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6329'),
('63c854a6-1d34-588a-ba36-6707db2c2312', 'Zancadas con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.', 'Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.', 'Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.', 'Empuja con el talón derecho para regresar a la posición inicial.', 'Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio unilateral que fortalece glúteos y cuádriceps, mejora el equilibrio y la coordinación al caminar con carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0054'),
('6b633acd-c77d-534b-bdcf-5209618f727e', 'Extensión de tríceps acostado por detrás de la cabeza', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con la barra llevada tras la cabeza, útil para trabajar la porción larga y ganar volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1720'),
('7a655636-9421-53ea-a45e-a2672f18af50', 'Remo acostado con agarre cerrado prono en rack', ARRAY['Colócate tumbado bajo la barra del rack y agárrala con las palmas hacia abajo y las manos juntas.', 'Con los pies en el suelo, tira de la barra hacia el pecho llevando los codos hacia atrás.', 'Junta las escápulas arriba y baja la barra de forma controlada.', 'Mantén el cuerpo recto y evita despegar la cadera o arquear la lumbar.', 'Respira al tirar y controla el descenso sin soltar la tensión.']::text[], 'intermedio', 'Trabaja la espalda alta y los dorsales tumbado bajo la barra, mejorando la retracción escapular y la fuerza de tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '4424'),
('ca892402-e8b6-51ee-8195-bf17827c86fa', 'Remo acostado con agarre cerrado supino en rack', ARRAY['Túmbate bajo la barra del rack y agárrala con las palmas hacia arriba y las manos juntas.', 'Tira de la barra hacia el pecho llevando los codos pegados al cuerpo.', 'Aprieta la espalda arriba y baja la barra controlando el movimiento.', 'Mantén el torso firme y evita balancearte o despegar la cadera.', 'Respira al tirar y no sueltes la tensión en la bajada.']::text[], 'intermedio', 'Variante de remo tumbado con agarre supino que enfatiza dorsales y bíceps, mejorando la fuerza de tracción horizontal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '4423'),
('353cdd83-c4e0-51c7-b570-c788bd59bd0f', 'Press acostado con agarre cerrado', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Press de banca con manos juntas que carga el tríceps y la parte interna del pecho, útil para fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0055'),
('0286ad3b-7dba-5e1f-ba24-29bbf6af140d', 'Extensión de tríceps acostado con agarre cerrado', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.', 'Extiende completamente los brazos, levantando la barra por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.', 'Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps tumbado con la barra y agarre cerrado, ideal para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0056'),
('551ab50d-4846-59c2-a81b-405057d0ed7a', 'Extensión acostado con barra', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio de aislamiento para el tríceps tumbado con barra, que mejora la fuerza y el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0057'),
('b8ce9a87-5ddd-52f3-be92-15e72568823e', 'Elevación frontal acostado con barra', ARRAY['Túmbate en un banco con la barra sujeta con agarre prono sobre los muslos.', 'Con los brazos casi rectos, eleva la barra hasta la vertical de los hombros.', 'Baja despacio controlando el movimiento y sin dejar caer la barra.', 'Evita arquear la zona lumbar y mantener los omóplatos pegados al banco.']::text[], 'intermedio', 'Trabaja el deltoides anterior y la parte alta del pecho, útil para ganar fuerza y control en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10588'),
('f10de9f9-2255-5c05-a561-31381011e052', 'Elevación acostado con barra en cadera', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas.', 'Sujeta la barra con un agarre pronado y colócala sobre las caderas.', 'Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa los glúteos y la cadena posterior para mejorar el empuje de cadera y la estabilidad pélvica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0058'),
('3bac5d23-0176-5c28-910e-a4bcf126f67c', 'Curl predicador acostado con barra', ARRAY['Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con el brazo apoyado, ideal para ganar volumen y control en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0059'),
('73b849bb-e821-5d9c-8805-da57b373e235', 'Remo acostado en rack con barra', ARRAY['Colócate boca abajo sobre un banco en el rack con la barra bajo las manos.', 'Agarra la barra con las palmas hacia abajo y los brazos extendidos.', 'Tira de la barra hacia el pecho juntando los omóplatos y sin encoger los hombros.', 'Baja la barra de forma controlada hasta estirar los brazos del todo.', 'Evita usar impulso del tronco y mantén el cuello en línea con la espalda.']::text[], 'intermedio', 'Fortalece la espalda alta y los dorsales, mejorando la postura y la tracción horizontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3654'),
('1dc5acaa-916d-5bed-bf73-c813eae2e998', 'Remo seal acostado con barra en rack', ARRAY['Túmbate boca abajo en un banco elevado en el rack con la barra a tu alcance.', 'Agarra la barra con agarre prono y deja los brazos colgando extendidos.', 'Tira de la barra hacia el pecho apretando los omóplatos y sin mover el tronco.', 'Baja la barra despacio hasta la extensión completa de los brazos.', 'Evita levantar el pecho del banco o encoger los hombros al tirar.']::text[], 'intermedio', 'Aísla la espalda alta y los romboides al eliminar el impulso, mejorando la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8798'),
('77c8f38b-ba07-5e14-bac7-f3ce42f00d2a', 'Extensión de tríceps acostado con barra', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.', 'Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps en aislamiento para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0061'),
('746740a3-21f1-5228-bede-4feda08e209c', 'Press francés acostado con barra', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.', 'Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con énfasis en la cabeza larga, mejorando la extensión del codo y el tamaño del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0060'),
('938d46a3-f603-54fc-84ca-ea108eac66ab', 'Press militar con barra con banda colgante', ARRAY['Coloca la barra a la altura de los hombros con las bandas colgando de forma simétrica.', 'Agarra la barra con las manos algo más anchas que los hombros y aprieta el core.', 'Empuja la barra hacia arriba hasta extender los brazos sin bloquear de golpe.', 'Baja la barra controlando la trayectoria hasta la altura de la barbilla.', 'Evita arquear la espalda o perder la tensión abdominal al empujar.']::text[], 'intermedio', 'Desarrolla los hombros y el core con una carga inestable que exige control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3186'),
('910f50f7-f986-58f7-8a00-d90eaa3c237c', 'Muscle clean con barra', ARRAY['Coloca la barra sobre los muslos con agarre prono y los pies a la anchura de las caderas.', 'Extiende las piernas y la cadera con fuerza mientras subes la barra pegada al cuerpo.', 'Recibe la barra a la altura de los hombros con los codos altos y las rodillas ligeramente flexionadas.', 'Baja la barra de forma controlada hasta la posición inicial.', 'Evita tirar con los brazos antes de completar la extensión de piernas y cadera.']::text[], 'avanzado', 'Movimiento de halterofilia que potencia la extensión de cadera y la fuerza de trapecios y piernas.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5075'),
('f1af560d-901a-562c-99ed-2f601dd9cc0e', 'Arrancada muscular con barra', ARRAY['Sujeta la barra en el suelo con agarre amplio y la espalda recta.', 'Extiende piernas y cadera con rapidez manteniendo la barra cerca del cuerpo.', 'Tira de la barra hacia arriba y recíbela por encima de la cabeza con los brazos extendidos.', 'Estabiliza la posición un instante y baja la barra controlando el descenso.', 'Evita encoger los hombros antes de tiempo o perder la tensión del core.']::text[], 'avanzado', 'Ejercicio explosivo de halterofilia que desarrolla potencia de piernas, trapecios y hombros.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1526'),
('70731210-89fa-55cd-853d-cb8b1eb0b636', 'Remo con agarre cerrado y barra', ARRAY['Inclina el tronco hacia delante con la espalda recta y la barra colgando con agarre cerrado.', 'Tira de la barra hacia el abdomen bajo juntando los omóplatos.', 'Mantén los codos cerca del cuerpo durante todo el recorrido.', 'Baja la barra despacio hasta estirar los brazos sin redondear la espalda.', 'Evita usar impulso de cadera o encoger los hombros al tirar.']::text[], 'intermedio', 'Fortalece dorsales y espalda media con un agarre estrecho que aumenta el recorrido de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0062'),
('954e6367-cdd7-5827-8101-dc641bdf36f3', 'Sentadilla con postura estrecha y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.', 'Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.', 'Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el trabajo en glúteos y cuádriceps con una base estrecha que aumenta la profundidad y el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0063'),
('2689f8b9-312b-5697-910a-b0b763de8ba1', 'Sentadilla olímpica con barra', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros.', 'Desciende flexionando rodillas y cadera manteniendo el pecho alto y la espalda recta.', 'Baja hasta donde tu movilidad permita sin perder la curvatura lumbar.', 'Empuja con los talones para subir extendiendo piernas y cadera a la vez.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Sentadilla profunda que desarrolla fuerza en cuádriceps, glúteos y core con gran movilidad de tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1527'),
('4d564e1e-c09f-5694-8c99-df532cad4494', 'Remo inclinado a un brazo con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.', 'Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.', 'Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.', 'Baja la barra de vuelta a la posición inicial de forma controlada.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja la espalda alta de forma unilateral, corrigiendo desequilibrios y mejorando la tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0064'),
('0c6ddc7f-2a36-56b9-85ca-a126bda9796e', 'Arrancada a un brazo con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.', 'Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.', 'Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.', 'Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.', 'Baja la barra de vuelta a la posición inicial de forma controlada.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'avanzado', 'Movimiento explosivo unilateral que desarrolla potencia de hombro, trapecio y core.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0067'),
('bb995a38-221a-5839-815d-112c7b8ee589', 'Empuje de cadera a una pierna con barra', ARRAY['Coloca la barra sobre la cadera y apoya la espalda alta en un banco, con un pie en el suelo y el otro elevado.', 'Empuja con el talón del pie apoyado para subir la cadera hasta alinear tronco y muslo.', 'Aprieta el glúteo arriba un segundo y baja controlando el movimiento.', 'Mantén el abdomen firme y evita arquear la zona lumbar en la subida.']::text[], 'intermedio', 'Trabaja glúteos e isquios de forma unilateral y mejora el control de la cadera y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1061'),
('83c795a1-ed3f-51c6-af38-76f5d1e7efef', 'Sentadilla a una pierna con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.', 'Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.', 'Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.', 'Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de rodilla y cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0068'),
('a22cda4f-d567-5292-9ccb-8185a2cef8dd', 'Acarreo sobre la cabeza con barra', ARRAY['Sube la barra por encima de la cabeza con los brazos extendidos y los omóplatos activos.', 'Camina con pasos cortos y controlados manteniendo el abdomen firme y la mirada al frente.', 'Respira de forma continua y evita bloquear la respiración durante el recorrido.', 'No arquees la zona lumbar ni dejes que la barra se vaya hacia delante.']::text[], 'intermedio', 'Refuerza hombros, core y espalda alta mientras caminas, mejorando la estabilidad overhead y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2914'),
('48b70716-8472-5ebd-afd1-67fcb53afa8c', 'Encogimiento sobre la cabeza con barra', ARRAY['Sujeta la barra por encima de la cabeza con los brazos extendidos y el core activo.', 'Eleva los hombros hacia las orejas sin doblar los codos.', 'Mantén un instante arriba y baja los hombros de forma controlada.', 'Evita arquear la espalda o encoger el cuello en lugar de los hombros.']::text[], 'intermedio', 'Trabaja los trapecios superiores y la espalda alta manteniendo la barra elevada, mejorando la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2928'),
('8e95d0b4-c3ad-5a7a-a0c1-e42a0ed0a5a0', 'Curl de muñeca con palmas abajo sobre banco y barra', ARRAY['Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.', 'Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.', 'Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los extensores del antebrazo y mejora la fuerza de agarre y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1411'),
('e105197f-5c99-5b47-9bb0-ecc28b672099', 'Curl de muñeca con palmas arriba sobre banco y barra', ARRAY['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.', 'Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.', 'Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.', 'Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los flexores del antebrazo y mejora la fuerza de agarre y la resistencia de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1412'),
('d38e5407-c45f-546c-b7a6-7ca8527181bc', 'Peso muerto con pausa y barra', ARRAY['Coloca la barra sobre el suelo y agárrala con las manos a la anchura de los hombros.', 'Empuja con las piernas y extiende la cadera hasta ponerte de pie con la espalda neutra.', 'Haz una pausa de uno o dos segundos justo al despegar la barra del suelo.', 'Baja la barra controlando el movimiento y evitando redondear la espalda.']::text[], 'intermedio', 'Refuerza glúteos, isquios y espalda baja, mejorando la técnica y el control en el punto de partida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5014'),
('0012f849-8675-54cc-af97-5f295b6f7367', 'Peso muerto sumo con pausa y barra', ARRAY['Abre los pies en posición sumo y agarra la barra con los brazos dentro de las piernas.', 'Empuja el suelo con los pies y extiende la cadera hasta quedar de pie.', 'Haz una pausa de uno o dos segundos justo al iniciar el tirón.', 'Mantén el pecho alto y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja glúteos, aductores e isquios con una pausa que mejora el control y la fuerza en el arranque.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5577'),
('a803c784-2a51-5259-8306-ed21e4ba4be9', 'Remo Pendlay con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.', 'Baja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con un tirón explosivo desde el suelo que mejora la potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3017'),
('53ce88f1-82be-5d46-96a0-d3066e1880e7', 'Press de banca con pines y agarre convencional con barra', ARRAY['Coloca los pines a la altura del pecho y túmbate con los pies firmes en el suelo.', 'Baja la barra de forma controlada hasta apoyarla suavemente en los topes.', 'Empuja la barra hacia arriba sin rebotar y manteniendo los omóplatos retraídos.', 'Evita levantar la cadera del banco o perder la tensión en el pecho.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps desde los topes, mejorando la fuerza en el punto bajo del press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7621'),
('5d17364c-a860-534b-9fd1-8f74c9117afc', 'Press de banca con agarre cerrado y topes con barra', ARRAY['Túmbate en el banco con un agarre más estrecho que la anchura de los hombros.', 'Baja la barra hasta los topes manteniendo los codos cerca del torso.', 'Empuja hacia arriba extendiendo los codos sin bloquear de golpe.', 'Evita abrir los codos en exceso o rebotar la barra en los pines.']::text[], 'intermedio', 'Enfoca el trabajo en tríceps y pecho con un agarre cerrado que limita el rango y protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4856'),
('7b0ec6da-7a4a-5b42-b808-a4aaf2c9cadd', 'Buenos días con topes y barra', ARRAY['Coloca la barra sobre la espalda alta y los pies a la anchura de la cadera.', 'Lleva la cadera hacia atrás inclinando el tronco hasta tocar los topes.', 'Mantén la espalda neutra y las rodillas ligeramente flexionadas.', 'Sube empujando la cadera hacia delante sin redondear la zona lumbar.']::text[], 'intermedio', 'Fortalece isquios, glúteos y espalda baja con un movimiento de bisagra controlado por los topes.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4851'),
('f97037b1-92b4-55b7-8aef-e345b264f6d8', 'Press desde soportes con barra', ARRAY['Coloca una barra en un rack de potencia a la altura del pecho.', 'Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps y hombros desde los topes, mejorando la fuerza en el rango parcial y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1751'),
('f5cf11c0-c97e-5ac3-b115-e46a5490c3db', 'Sentadilla con topes y barra', ARRAY['Coloca la barra sobre la espalda alta y ajusta los topes a la altura de tu sentadilla.', 'Baja controlando hasta tocar suavemente los topes sin rebotar.', 'Empuja con los pies y sube manteniendo el pecho alto y el core firme.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un rango controlado por los topes que mejora la técnica y la seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5701'),
('cc3f55cd-93ba-5ac8-b554-c6ab214859bb', 'Cargada de potencia desde bloques con barra', ARRAY['Coloca la barra sobre los bloques a la altura de la rodilla y agárrala con las manos fuera de las piernas.', 'Extiende la cadera y las rodillas de forma explosiva para tirar de la barra hacia arriba.', 'Recibe la barra en los hombros con los codos altos y las rodillas ligeramente flexionadas.', 'Evita tirar con los brazos o redondear la espalda durante el tirón.']::text[], 'avanzado', 'Desarrolla potencia y explosividad en glúteos, isquios y hombros con un movimiento olímpico desde bloques.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1528'),
('34bba2c7-3dd3-59b7-b447-ed758a0f7205', 'Envión de potencia con barra', ARRAY['Coloca la barra a la altura de los muslos con agarre firme y pies a la anchura de las caderas.', 'Flexiona ligeramente las rodillas y extiende con fuerza las caderas para impulsar la barra hacia arriba.', 'Recibe la barra con los brazos bloqueados sobre la cabeza y las rodillas algo flexionadas.', 'Estabiliza el core y respira con fuerza durante el impulso para evitar perder la posición.', 'Evita empujar la barra hacia delante: mantenla cerca del cuerpo en todo el recorrido.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que desarrolla potencia en hombros, piernas y core para transferir fuerza al deporte.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1529'),
('baebab14-0099-5900-b0d8-f3b0397d91f4', 'Encogimiento de potencia con barra', ARRAY['Sujeta la barra a la altura de los muslos con los brazos extendidos y el pecho alto.', 'Extiende las caderas y las rodillas de forma explosiva mientras elevas los hombros hacia las orejas.', 'Mantén los codos rectos y evita flexionarlos para no convertirlo en un remo.', 'Baja la barra de forma controlada y repite manteniendo el core activo.', 'No encorves la espalda ni des un tirón brusco con el cuello.']::text[], 'avanzado', 'Trabaja trapecios y espalda alta con un tirón explosivo que mejora la potencia del agarre y la estabilidad escapular.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5662'),
('72d97c86-e2c1-5bb6-812a-965476698f8a', 'Arrancada de potencia con barra', ARRAY['Agarra la barra en el suelo con las manos bien separadas y la espalda recta.', 'Tira de la barra pegada al cuerpo extendiendo caderas y rodillas de forma explosiva.', 'Recibe la barra sobre la cabeza con los brazos bloqueados y las rodillas ligeramente flexionadas.', 'Mantén el core firme y la mirada al frente durante todo el movimiento.', 'Evita recibir la barra con los brazos doblados o la espalda arqueada.']::text[], 'avanzado', 'Ejercicio olímpico que genera potencia en glúteos y piernas y mejora la coordinación de todo el cuerpo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1530'),
('26002d75-a9ff-5d6f-a949-6671c1f284f8', 'Arrancada de potencia desde bloques con barra', ARRAY['Coloca la barra sobre los bloques a la altura de la rodilla y agarra con las manos bien separadas.', 'Extiende caderas y rodillas con fuerza manteniendo la barra cerca del cuerpo.', 'Recibe la barra sobre la cabeza con los brazos bloqueados y las rodillas algo flexionadas.', 'Activa el core y respira con fuerza durante el tirón para estabilizar el tronco.', 'Evita tirar con los brazos antes de completar la extensión de piernas y cadera.']::text[], 'avanzado', 'Variante de la arrancada que enfatiza la potencia de glúteos y la extensión de cadera desde una posición elevada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1531'),
('260bcd6d-2aa7-5fe3-b13c-53b601993100', 'Abdominal con press de barra', ARRAY['Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.', 'Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina trabajo abdominal y empuje de hombros para reforzar el core y la parte superior del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0071'),
('21da1dbf-e89a-554d-be47-bd077bba7840', 'Curl inclinado boca abajo con barra', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.', 'Sujeta una barra con un agarre supino, separado a la altura de los hombros.', 'Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps en estiramiento para ganar fuerza y control en el rango completo del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0072'),
('5f4a2c61-9a69-54a0-86b3-f20f314770af', 'Pullover con barra', ARRAY['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.', 'Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja principalmente los dorsales y el pecho, ampliando la caja torácica y fortaleciendo la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0073'),
('04be010c-b500-5b94-b654-ac329819a869', 'Sostén de pullover con barra', ARRAY['Túmbate en un banco con la barra sujeta por encima del pecho y los brazos casi extendidos.', 'Lleva la barra hacia atrás hasta notar estiramiento en los dorsales y mantén la posición.', 'Aprieta el core y mantén las costillas abajo para no arquear la zona lumbar.', 'Respira de forma constante y evita aguantar la respiración durante el sostén.', 'No bajes más de lo que controlas: si pierdes la posición, reduce el recorrido.']::text[], 'intermedio', 'Isométrico que mantiene la tensión en dorsales y pecho para mejorar la estabilidad y la resistencia muscular.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1448'),
('e2f4d70a-9a53-5638-b813-61f8e2e66506', 'Pullover y press con barra', ARRAY['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.', 'Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina dorsales, tríceps y hombros en un movimiento completo que desarrolla fuerza y control en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0022'),
('37899713-3e0c-5743-9520-5606b3032286', 'Cuarto de sentadilla con barra', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros.', 'Desciende solo un cuarto del recorrido manteniendo el pecho alto y el core activo.', 'Empuja con los talones para subir y extiende las caderas sin bloquear las rodillas de golpe.', 'Mantén las rodillas alineadas con los pies y evita que se metan hacia dentro.', 'No cargues más peso del que puedes controlar en este recorrido corto.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un recorrido corto útil para reforzar la extensión de rodilla y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1514'),
('91eb6488-7450-5310-a4b1-8a755475d2c1', 'Peso muerto desde soportes', ARRAY['Coloca una barra en un soporte a la altura de la rodilla.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.', 'Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.', 'Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfocado en glúteos, isquios y zona lumbar, mejora la fuerza de la cadena posterior desde una altura controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0074'),
('21179b0b-9e65-5f87-b8a0-71497f239c08', 'Elevación de deltoide posterior con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoide posterior y los trapecios, equilibrando el desarrollo del hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0075'),
('3944c46e-f186-50dc-ac45-0ab5414ab260', 'Remo para deltoide posterior con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.', 'Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Tira de la barra hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el deltoide posterior, romboides y trapecios, corrigiendo desequilibrios y mejorando la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0076'),
('98e3260a-4470-549e-988d-633e3ba2e19d', 'Peso muerto reeves con barra', ARRAY['Coloca la barra en el suelo y sitúate con los pies más abiertos que la anchura de los hombros.', 'Agarra la barra por dentro de las piernas con la espalda recta y el pecho alto.', 'Empuja el suelo con los pies y extiende caderas y rodillas para levantar la barra.', 'Mantén la barra cerca del cuerpo y el core firme durante todo el recorrido.', 'Evita redondear la espalda o tirar con los brazos al iniciar el levantamiento.']::text[], 'intermedio', 'Variante de peso muerto que carga glúteos, isquios y aductores y mejora la fuerza de la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4116'),
('929221a3-e9d0-5823-8286-58ea8889d328', 'Press de banca inverso con banda elástica y barra', ARRAY['Ancla las bandas en la parte baja del rack y engánchalas a la barra por ambos lados.', 'Túmbate en el banco con los pies firmes y agarra la barra a la anchura de los hombros.', 'Baja la barra al pecho de forma controlada mientras las bandas se destensan.', 'Empuja con fuerza hasta bloquear los codos, donde la tensión de las bandas es mayor.', 'Evita rebotar en el pecho y mantén los omóplatos retraídos durante todo el press.']::text[], 'intermedio', 'Press de banca con bandas que reducen la carga en la parte baja y aumentan la tensión al bloquear, mejorando la potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1497'),
('f827f527-b31f-5b07-9182-13e88bf60236', 'Press de banca con agarre cerrado inverso y barra', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra esté justo encima del pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps con apoyo de pecho y hombros, ideal para ganar fuerza en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2187'),
('4038689a-179f-546b-82b6-fd5c792f66c7', 'Curl inverso con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.', 'Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el bíceps y los antebrazos con agarre prono, mejorando el control y la fuerza de prensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0080'),
('5304e686-d899-5857-82db-6a97d97c31ff', 'Remo inclinado con agarre inverso y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.', 'Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.', 'Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda alta con ayuda de bíceps y antebrazos, útil para mejorar la postura y la tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0118'),
('43fbac8d-2503-57dd-afc1-eaf79930c794', 'Press de banca declinado con agarre inverso y barra', ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Incide en el pecho con apoyo de tríceps y hombros, útil para variar el estímulo del empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1256'),
('1cbd4b24-50b5-5578-a474-24161d5b66d4', 'Press en el suelo con agarre inverso y barra', ARRAY['Túmbate en el suelo con las rodillas flexionadas y sujeta la barra con agarre inverso algo más estrecho que los hombros.', 'Baja la barra de forma controlada hasta que los tríceps toquen el suelo, sin rebotar.', 'Empuja la barra hacia arriba extendiendo los codos mientras sueltas el aire.', 'Mantén las muñecas firmes y evita abrir los codos en exceso para no cargar el hombro.']::text[], 'intermedio', 'Refuerza el tríceps con ayuda de pecho y hombros, limitando el rango para proteger el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3917'),
('58a30f87-b397-5074-8a79-892d61023fda', 'Press de banca inclinado con agarre inverso y barra', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Túmbate en el banco con los pies planos sobre el suelo.', 'Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el pecho superior con apoyo de tríceps y hombros, útil para ganar volumen en la parte alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1257'),
('42662a58-d68b-537e-bd87-a42dfbdf1083', 'Press francés con agarre inverso y barra', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.', 'Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.', 'Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.', 'Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con ayuda de los antebrazos, útil para trabajar la extensión del codo con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1721'),
('131f550d-9c8a-53f8-a26f-e58aa31afb1c', 'Curl predicador inverso con barra', ARRAY['Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.', 'Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps y los antebrazos con agarre prono, aislando el brazo y mejorando la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0081'),
('c920fcc5-5937-5d36-bba3-c31963daeada', 'Rodillo abdominal con barra', ARRAY['Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.', 'Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.', 'Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.', 'Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen con apoyo de la zona lumbar, útil para ganar estabilidad y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0084'),
('939763ad-84f0-5153-98fd-b44ca2615b16', 'Rodillo abdominal desde banco con barra', ARRAY['Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.', 'Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.', 'Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen con ayuda de hombros y tríceps, ideal para progresar en el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0083'),
('8b221ac5-873a-5109-bfec-f4e9e86e38a2', 'Peso muerto rumano desde déficit con barra', ARRAY['Colócate de pie sobre una superficie elevada con la barra frente a los muslos y los pies a la anchura de las caderas.', 'Lleva las caderas hacia atrás y baja la barra pegada a las piernas manteniendo la espalda recta.', 'Nota el estiramiento en los isquiotibiales y sube empujando las caderas hacia delante mientras sueltas el aire.', 'Evita redondear la espalda o bajar más de lo que te permita tu flexibilidad.']::text[], 'intermedio', 'Trabaja los isquiotibiales con apoyo de glúteos y espalda, útil para ganar fuerza y flexibilidad posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1532'),
('1135d45a-c627-5e1f-b816-2c58273f3efa', 'Press militar sentado por detrás de la cabeza con barra', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza.', 'Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.', 'Baja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los hombros con apoyo de tríceps y espalda alta, útil para ganar fuerza en el empuje vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0086'),
('ab57bf75-8a83-5083-971a-335bdc782466', 'Press Bradford sentado con barra', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.', 'Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.', 'Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estimula los hombros con ayuda de tríceps y espalda alta, útil para trabajar el empuje en distintos ángulos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0087'),
('b84f45ae-68ea-5730-8216-91807ec42698', 'Extensión de tríceps sentado por detrás de la nuca con agarre cerrado y barra', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.', 'Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con apoyo de los hombros, útil para trabajar la extensión del codo con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1718'),
('67729970-c9fb-58ef-8b29-9d5fa2922ef0', 'Curl concentrado sentado con agarre cerrado y barra', ARRAY['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.', 'Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.', 'Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.', 'Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con ayuda de los antebrazos, útil para trabajar el pico del brazo con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0089'),
('cf652073-13be-51cc-9009-7673d2a6cb2a', 'Buenos días sentado con barra', ARRAY['Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.', 'Mantén la espalda recta y el pecho elevado.', 'Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales con control lumbar, mejorando la bisagra de cadera sin cargar las rodillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0090'),
('afc1a042-becc-5058-bc5d-60244d2711a9', 'Elevación frontal alta sentado con barra', ARRAY['Siéntate con la espalda recta y la barra apoyada sobre los muslos, con agarre a la anchura de los hombros.', 'Sube la barra hacia delante y arriba hasta la altura de los ojos, con los codos ligeramente flexionados.', 'Baja despacio controlando el peso hasta la posición inicial y exhala al subir.', 'Evita arquear la espalda o usar impulso de cadera para lanzar la barra.']::text[], 'intermedio', 'Trabaja el deltoides anterior y la parte alta del pecho, ganando fuerza en el hombro para empujes por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4411'),
('ab726d40-050d-5f3e-9ad6-9dd83560c9b7', 'Press militar sentado con barra', ARRAY['Coloca el banco dentro de la jaula con los topes a la altura del pecho y siéntate con la espalda apoyada.', 'Agarra la barra un poco más ancha que los hombros y sácala de los soportes con los brazos extendidos.', 'Baja la barra hasta la barbilla y empuja hacia arriba hasta estirar los codos, exhalando al subir.', 'Mantén las costillas abajo y evita arquear la zona lumbar al empujar.']::text[], 'intermedio', 'Desarrolla fuerza en hombros y tríceps empujando por encima de la cabeza, con el core estabilizando el tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1045'),
('f5c4fa70-1ffe-5c71-9f08-417da39f5c37', 'Extensión de tríceps sobre la cabeza con barra', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.', 'Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.', 'Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en estiramiento, útil para ganar fuerza en la extensión del codo y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0092'),
('8f92aab9-a4f9-5da9-b749-98c40fe23189', 'Encogimientos sentado con barra', ARRAY['Siéntate en un banco con la barra sujeta a la altura de los muslos y las manos a la anchura de los hombros.', 'Mantén la espalda recta y los brazos extendidos, con la barra colgando delante de ti.', 'Sube los hombros hacia las orejas sin doblar los codos y mantén un segundo arriba.', 'Baja los hombros de forma controlada sin dejar caer la barra de golpe.', 'Evita encoger el cuello o usar impulso con las piernas durante el movimiento.']::text[], 'intermedio', 'Trabaja los trapecios superiores y el agarre, aumentando la fuerza y el volumen de la zona cervical y dorsal alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4016'),
('82ff5f73-f74b-5420-8e19-17115abed4b7', 'Giro sentado con barra', ARRAY['Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.', 'Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.', 'Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.', 'Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.', 'Repite el giro hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa abdominales y oblicuos con rotación controlada del tronco, mejorando la estabilidad y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0094'),
('ac9636a4-20a0-5d76-b48f-77bea0f3e9be', 'Remo al mentón con barra', ARRAY['De pie con la barra frente a los muslos y agarre a la anchura de los hombros.', 'Tira de la barra hacia el mentón llevando los codos por encima de las manos.', 'Baja despacio hasta estirar los brazos y exhala al subir.', 'Evita subir la barra por encima de la barbilla o encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Fortalece deltoides y trapecios tirando de la barra hacia arriba, mejorando la fuerza del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5632'),
('1b1a2ca8-da25-520e-a61e-1668415f834c', 'Encogimiento de hombros con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.', 'Mantén los brazos rectos y la espalda recta durante todo el ejercicio.', 'Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.', 'Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza los trapecios elevando los hombros, mejorando la fuerza del cuello y la estabilidad de la cintura escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0095'),
('f1a3f5c3-3682-5123-a240-f0327b9a7057', 'Flexión lateral con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite el movimiento hacia el lado izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja oblicuos y core inclinando el tronco con control, mejorando la fuerza lateral y la estabilidad de la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0096'),
('27973f66-c657-5a97-828e-590908979cd6', 'Sentadilla lateral con barra', ARRAY['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.', 'Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.', 'Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.', 'Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.', 'Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con desplazamiento lateral, mejorando la fuerza unilateral y la movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0098'),
('bfd427dc-fd7b-578c-bfe9-0c222631ec3b', 'Peso muerto a una pierna con barra', ARRAY['Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono.', 'Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio.', 'Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.', 'Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales sobre una sola pierna, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1756'),
('a86d82b1-23f6-5dad-b331-204545b2370b', 'Buenos días a una pierna con barra', ARRAY['Coloca la barra sobre los trapecios y apoya todo el peso en una pierna, con la otra ligeramente atrás.', 'Lleva la cadera hacia atrás inclinando el tronco con la espalda recta hasta notar estiramiento en el isquiotibial.', 'Vuelve a la posición inicial apretando el glúteo y exhala al subir.', 'Evita redondear la espalda o perder el equilibrio por bajar demasiado.']::text[], 'intermedio', 'Fortalece isquiotibiales y glúteos sobre una pierna, mejorando el equilibrio y el control de la bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4850'),
('eabc7ffb-a4c5-59a2-acc6-89148300780d', 'Sentadilla búlgara con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.', 'Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.', 'Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.', 'Continúa bajando hasta que el muslo delantero quede paralelo al suelo.', 'Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con una pierna elevada, mejorando la fuerza unilateral y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0099'),
('95eb5302-4caf-5757-9a13-ef5228c694ac', 'Elevación alterna de piernas sentado con barra', ARRAY['Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.', 'Coloca las manos a los lados del banco para apoyarte.', 'Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo.', 'Baja la pierna y repite con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa abdominales y flexores de cadera elevando las piernas alternas, mejorando el control del core sentado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2800'),
('5d8dcd4b-2ed3-59aa-bd1b-459679c6db0e', 'Giro de oblicuos sentado en el suelo con barra', ARRAY['Siéntate en el suelo con las piernas flexionadas y la barra apoyada sobre los hombros por detrás del cuello.', 'Gira el tronco hacia un lado y luego hacia el otro con movimiento lento y controlado.', 'Mantén la espalda recta y exhala al girar hacia cada lado.', 'Evita usar impulso o girar solo con los brazos en lugar del tronco.']::text[], 'intermedio', 'Trabaja oblicuos y core rotando el tronco sentado, mejorando la fuerza rotacional y la estabilidad de la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4854'),
('51352bb0-7c1d-5830-8296-744423eeef56', 'Arrancada con barra', ARRAY['Coloca los pies a la anchura de las caderas con la barra sobre el empeine y agarre amplio.', 'Empuja el suelo con las piernas y extiende la cadera mientras subes la barra pegada al cuerpo.', 'Cuando la barra pase la cadera, encógela y mete los codos bajo ella para recibirla arriba.', 'Recibe la barra con los brazos bloqueados y las rodillas ligeramente flexionadas.', 'Evita tirar con los brazos desde el inicio: la fuerza sale de piernas y cadera.']::text[], 'avanzado', 'Levantamiento olímpico que desarrolla potencia de glúteos y piernas, coordinando todo el cuerpo en un solo movimiento explosivo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1533'),
('1271b140-112d-5b93-bff5-afdf8357a9c5', 'Balance de arrancada con barra', ARRAY['Sujeta la barra sobre la espalda alta con agarre de arrancada y pies a la anchura de las caderas.', 'Flexiona ligeramente las rodillas y empuja la barra hacia arriba con un pequeño salto.', 'Recibe la barra con los brazos bloqueados y las rodillas flexionadas en sentadilla.', 'Estabiliza el core y mantén la barra alineada sobre la cabeza.', 'Evita recibir con los brazos doblados: bloquea los codos antes de frenar el descenso.']::text[], 'avanzado', 'Ejercicio técnico de halterofilia que mejora la recepción de la arrancada y la estabilidad sobre la cabeza.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1534'),
('0dddbd1f-ee03-519f-96e7-f2632ebff1a9', 'Peso muerto de arrancada con barra', ARRAY['Coloca la barra sobre el empeine con agarre amplio y pies a la anchura de las caderas.', 'Baja la cadera, saca pecho y mantén la espalda neutra antes de tirar.', 'Empuja el suelo con los pies y extiende piernas y cadera a la vez, con la barra pegada al cuerpo.', 'Termina de pie con la cadera extendida y los hombros atrás.', 'Evita redondear la espalda o tirar con los brazos: la barra sube por la extensión de piernas.']::text[], 'avanzado', 'Variante del peso muerto que refuerza glúteos, isquios y espalda alta en la posición inicial de la arrancada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1535'),
('3f968137-15cf-5009-9f60-c72df8ae00e5', 'Arrancada desde bloques con barra', ARRAY['Coloca la barra sobre los bloques a la altura de la rodilla con agarre de arrancada.', 'Adopta la posición inicial con la espalda neutra y los hombros sobre la barra.', 'Extiende piernas y cadera de forma explosiva manteniendo la barra cerca del cuerpo.', 'Recibe la barra arriba con los brazos bloqueados y las rodillas flexionadas.', 'Evita separar la barra del cuerpo: mantenla pegada durante todo el tirón.']::text[], 'avanzado', 'Variante de la arrancada que trabaja la potencia de glúteos y la fase final del tirón desde una altura controlada.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1536'),
('d3cc1c69-cbdc-552a-9641-f857ac9e6529', 'Sentadilla rápida con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.', 'Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla potencia y fuerza explosiva en glúteos y piernas, mejorando el rendimiento en movimientos rápidos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0101'),
('8114b4b9-dad9-516e-abc8-dfe412282bed', 'Curl araña con barra', ARRAY['Colócate boca abajo sobre un banco inclinado con la barra colgando y los brazos extendidos.', 'Agarra la barra con las palmas hacia arriba y los codos apuntando al suelo.', 'Flexiona los codos para subir la barra hacia los hombros sin mover los brazos del sitio.', 'Aprieta el bíceps arriba un instante y baja la barra de forma controlada.', 'Evita balancear el torso o usar impulso para levantar el peso.']::text[], 'intermedio', 'Aísla el bíceps y el braquial desde una posición inclinada, maximizando la tensión en el pico de contracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4338'),
('9dec6d15-98f3-50bf-b16c-6594d7224687', 'Cargada con tijera y barra', ARRAY['Coloca la barra sobre el empeine con agarre a la anchura de los hombros y espalda neutra.', 'Tira de forma explosiva extendiendo piernas y cadera, manteniendo la barra cerca.', 'Baja bajo la barra y recíbela en los hombros con una pierna adelantada y otra atrás.', 'Estabiliza el core y recupera la posición erguida juntando los pies.', 'Evita recibir con los codos bajos: súbelos rápido para que la barra quede sobre los hombros.']::text[], 'avanzado', 'Movimiento olímpico que desarrolla potencia de glúteos y coordinación para llevar la barra a los hombros en tijera.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1537'),
('1955efb9-6770-575b-abc0-200c77164fcc', 'Envión con tijera y barra', ARRAY['Sujeta la barra sobre los hombros con los codos delante y los pies a la anchura de las caderas.', 'Flexiona ligeramente las rodillas y empuja la barra hacia arriba con extensión explosiva.', 'Desplaza una pierna adelante y otra atrás para recibir la barra con los brazos bloqueados.', 'Estabiliza el core y mantén la barra alineada sobre la cabeza.', 'Evita bloquear los codos tarde: extiende los brazos mientras bajas bajo la barra.']::text[], 'avanzado', 'Ejercicio olímpico que potencia hombros, piernas y core al llevar la barra sobre la cabeza en posición de tijera.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1538'),
('992f6342-6eae-5a3d-ba76-964a9d6a5d69', 'Salto con tijera y barra', ARRAY['Coloca la barra sobre la espalda alta y adopta una posición de tijera con una pierna adelante.', 'Flexiona las rodillas y salta de forma explosiva extendiendo las piernas.', 'Cambia las piernas en el aire y aterriza suavemente en tijera con la rodilla flexionada.', 'Mantén el core firme y la barra estable durante todo el salto.', 'Evita aterrizar con las piernas rígidas: amortigua con las rodillas para proteger las articulaciones.']::text[], 'intermedio', 'Ejercicio pliométrico que mejora la potencia de piernas y la coordinación en posición de tijera con carga.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1539'),
('31f7bdef-cd7d-5d9e-9d11-13ccc1e235eb', 'Peso muerto rumano con piernas divididas y barra', ARRAY['Sujeta la barra delante de los muslos con una pierna adelantada y otra atrás.', 'Con la espalda neutra, lleva la cadera atrás y baja la barra pegada a la pierna delantera.', 'Nota el estiramiento en el isquio de la pierna delantera sin redondear la espalda.', 'Sube extendiendo la cadera y aprieta el glúteo al final del recorrido.', 'Evita perder el equilibrio: mantén el peso repartido y el core activo.']::text[], 'intermedio', 'Variante a una pierna que trabaja isquios y glúteos, mejorando el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10047'),
('32b76cf1-78d7-533f-95cc-8e3dcf804921', 'Sentadilla con pausa de 2 segundos y barra', ARRAY['Coloca la barra sobre la espalda alta y los pies a la anchura de los hombros.', 'Baja flexionando rodillas y cadera hasta que los muslos queden paralelos al suelo.', 'Mantén la posición de fondo durante dos segundos sin perder la espalda neutra.', 'Sube empujando el suelo con los pies y extendiendo piernas y cadera.', 'Evita que las rodillas se metan hacia dentro: mantenlas alineadas con los pies.']::text[], 'intermedio', 'Variante de sentadilla que mejora el control y la fuerza en el fondo, trabajando cuádriceps y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4362'),
('bf86cb78-7965-5909-8f06-d625219972c8', 'Sentadilla con barra, control de cadera', ARRAY['Coloca la barra sobre la espalda alta y los pies a la anchura de los hombros.', 'Baja controlando la cadera hacia atrás y manteniendo el pecho arriba.', 'Observa que la cadera no se desplace demasiado atrás ni la espalda se redondee.', 'Sube extendiendo piernas y cadera de forma coordinada.', 'Evita perder la curvatura lumbar: mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Ejercicio de control técnico que revisa la posición de la cadera para mejorar la sentadilla y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2361'),
('e80c4c22-257e-5861-80f9-46dbdc61cd20', 'Sentadilla con salto y zancada trasera con barra', ARRAY['Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas.', 'Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa.', 'Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.', 'Empuja con el talón delantero para volver a la posición inicial.', 'Repite la secuencia de salto y zancada con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico que combina salto y zancada para potenciar piernas y glúteos con carga.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '2798'),
('9cfd7b82-7da8-5f74-b1b4-069292652b0e', 'Sentadilla con barra, control de rodillas', ARRAY['Coloca la barra sobre la espalda alta y los pies a la anchura de los hombros.', 'Baja flexionando rodillas y cadera manteniendo el pecho arriba.', 'Comprueba que las rodillas siguen la línea de los pies sin meterse hacia dentro.', 'Sube empujando el suelo y extendiendo piernas y cadera.', 'Evita que los talones se levanten: mantén el peso repartido en todo el pie.']::text[], 'intermedio', 'Ejercicio de control técnico que revisa la alineación de las rodillas para mejorar la sentadilla y proteger las articulaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2359'),
('1f41d573-b397-5c86-a51a-27d10e50f0d0', 'Sentadilla a press de hombros con barra', ARRAY['Coloca la barra sobre los hombros con los codos delante y los pies a la anchura de los hombros.', 'Baja en sentadilla flexionando rodillas y cadera con la espalda neutra.', 'Sube extendiendo las piernas y, al llegar arriba, empuja la barra sobre la cabeza.', 'Bloquea los codos arriba y baja la barra a los hombros con control.', 'Evita arquear la espalda al press: aprieta el core y las nalgas durante el empuje.']::text[], 'intermedio', 'Ejercicio compuesto que trabaja cuádriceps y glúteos y encadena un press de hombros para todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1540'),
('026a4fca-7b6b-5555-b7de-8214956899f3', 'Sentadilla con remo al mentón', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Al subir, impulsa con las piernas y engancha un remo al mentón llevando la barra cerca del cuerpo.', 'Evita encoger los hombros hacia las orejas y controla la bajada de la barra.']::text[], 'intermedio', 'Combina sentadilla y tirón vertical para trabajar cuádriceps, glúteos y hombros en un solo movimiento global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1541'),
('4ac740f2-b5e8-52e3-a390-0399f67a6caa', 'Sentadilla con cadenas', ARRAY['Cuelga las cadenas de la barra y colócala sobre los trapecios con los pies a la anchura de los hombros.', 'Desciende controlando el movimiento hasta que los muslos queden paralelos al suelo.', 'Empuja con los talones para subir mientras el peso de las cadenas aumenta progresivamente.', 'Mantén el core firme y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Aumenta la carga a medida que subes, potenciando la fuerza en cuádriceps, glúteos y zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4064'),
('fbd67057-20f1-5acc-8db6-8a843b14b59b', 'Empuje de cadera con postura escalonada', ARRAY['Apoya la espalda alta en un banco y coloca la barra sobre la cadera con una pierna adelantada.', 'Empuja con los talones extendiendo la cadera hasta alinear el tronco con los muslos.', 'Aprieta el glúteo arriba y baja controlando sin perder la postura escalonada.', 'Evita arquear la zona lumbar en exceso; mantén las costillas abajo.']::text[], 'intermedio', 'Aísla el glúteo con una pierna adelantada, mejorando la fuerza y estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5476'),
('36b4a75c-2f1c-5638-81db-7f70b8d5748a', 'Peso muerto con piernas rígidas y postura escalonada', ARRAY['Sujeta la barra con las manos y coloca una pierna adelantada y otra atrás.', 'Con las rodillas ligeramente flexionadas, lleva la cadera atrás bajando la barra pegada a las piernas.', 'Nota el estiramiento en los isquiotibiales y sube extendiendo la cadera sin bloquear la espalda.', 'Evita redondear la zona lumbar; mantén el pecho alto durante todo el recorrido.']::text[], 'intermedio', 'Estira los isquiotibiales y fortalece la cadena posterior con una base más estable y unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11789'),
('5b9f7a0b-13b5-5866-96c6-c0dfa49de4a1', 'Rodillo abdominal de pie con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos.', 'Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos.', 'Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza.', 'Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el core y la estabilidad del tronco extendiendo la barra desde la posición erguida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0103'),
('7d391a20-eae4-5877-af92-fa8d3a7b97bb', 'Curl de muñeca de pie con agarre invertido', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.', 'Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo.', 'Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible.', 'Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y mejora el agarre con un movimiento controlado de muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0104'),
('9d0281ff-b058-51ad-b406-d5153ea9b342', 'Elevación de gemelos de pie con rodilla flexionada desde déficit', ARRAY['Coloca la punta de los pies en un escalón o disco y sujeta la barra sobre los trapecios.', 'Flexiona ligeramente las rodillas y mantén esa posición durante todo el ejercicio.', 'Sube los talones lo máximo posible y baja hasta sentir el estiramiento del sóleo.', 'Evita rebotar en la parte baja; controla el tempo en cada repetición.']::text[], 'intermedio', 'Enfoca el trabajo en el sóleo y la pantorrilla al mantener la rodilla doblada sobre una elevación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9410'),
('13b87fbd-e97f-5724-9514-c26c3eebdda5', 'Press Bradford de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono.', 'Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Baja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los hombros con un recorrido amplio que también activa tríceps y espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0105'),
('e108693a-fdbd-5610-9813-32a59e170076', 'Curl de pie con agarre cerrado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas.', 'Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.', 'Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con las manos juntas, aumentando la tensión y el control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0106'),
('41295a98-8f11-519f-94fa-09cd8203d665', 'Press militar de pie con agarre cerrado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros.', 'Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo.', 'Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Baja la barra de nuevo a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los hombros y tríceps con un agarre estrecho que aumenta el rango de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1456'),
('ed8b1169-7ab4-50ab-bda9-0a53775e10af', 'Curl concentrado de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba.', 'Apoya la otra mano sobre el muslo para mayor estabilidad.', 'Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente el peso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps con el codo fijo, maximizando la contracción y el control del peso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2414'),
('f4a67869-c85a-5749-a2a6-57b278e6e652', 'Elevación frontal sobre la cabeza', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono.', 'Mantén la espalda recta y activa el core.', 'Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.', 'Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la parte anterior del hombro elevando la barra por delante hasta encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0107'),
('cec69ff8-bfc8-572c-ac30-cee14fc23ce7', 'Press militar de pie', ARRAY['Sujeta la barra a la altura de los hombros con las manos algo más anchas que los hombros.', 'Aprieta el core y los glúteos para estabilizar el tronco antes de empujar.', 'Empuja la barra hacia arriba hasta bloquear los codos, pasando la cabeza ligeramente atrás.', 'Baja la barra controlando hasta la altura de la barbilla sin perder la tensión.']::text[], 'intermedio', 'Fortalece hombros, tríceps y core empujando la barra por encima de la cabeza de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1162'),
('4c31e39a-f758-5419-9403-8ad5da8c9ed7', 'Extensión de tríceps sobre la cabeza', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.', 'Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.', 'Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en estiramiento, mejorando la fuerza y el tamaño de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0109'),
('00cf64fc-6041-5ffb-a643-23d8750581bd', 'Curl de pie con agarre inverso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.', 'Mantén los codos cerca del torso y los brazos superiores quietos.', 'Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps y los extensores del antebrazo con un agarre prono que cambia el estímulo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0110'),
('fac8fb64-0511-5dbd-8f63-aa51e9c2c471', 'Elevación de gemelos de pie con balanceo de pierna y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.', 'Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies.', 'Baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y el equilibrio de la pierna de apoyo mientras el balanceo activa isquios y cuádriceps de forma dinámica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0111'),
('32030884-a14e-5d18-af89-0f41a32dad8b', 'Press de hombros de pie con topes y barra', ARRAY['Coloca la barra sobre los topes a la altura de la barbilla y agárrala algo más ancha que los hombros.', 'Aprieta glúteos y abdomen para mantener el tronco firme y los pies a la anchura de las caderas.', 'Empuja la barra hacia arriba hasta estirar los brazos, sin arquear la zona lumbar.', 'Baja la barra de forma controlada hasta que toque los topes y repite el movimiento.', 'Evita rebotar en los topes y exhala al empujar, inhalando al bajar.']::text[], 'intermedio', 'Trabaja los deltoides con un rango controlado por los topes, ganando fuerza en hombros, tríceps y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5668'),
('a601ddae-2795-5ccc-8df3-fdd62cca30a2', 'Press de hombros de pie con barra', ARRAY['Sujeta la barra a la altura de los hombros con las manos algo más anchas que estos y los codos bajo la barra.', 'Aprieta glúteos y abdomen, con los pies a la anchura de las caderas y la mirada al frente.', 'Empuja la barra verticalmente hasta estirar los brazos, pasando la cabeza ligeramente hacia delante al final.', 'Baja la barra con control hasta la altura de la barbilla sin dejar caer los codos.', 'Evita arquear la espalda baja; exhala al subir e inhala al bajar.']::text[], 'intermedio', 'Desarrolla la fuerza de los deltoides y el tríceps, exigiendo además estabilidad del core y de la parte alta de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5328'),
('041c2210-44a3-5f07-9737-93a8307b4ca2', 'Encogimientos de pie con agarre de arranque y barra', ARRAY['Agarra la barra con las manos muy separadas, como en un arranque, y cuélgala delante de los muslos.', 'Ponte erguido con los brazos estirados y el abdomen firme para no balancear el tronco.', 'Sube los hombros hacia las orejas sin doblar los codos ni encoger la cabeza.', 'Mantén un instante arriba y baja los hombros de forma controlada.', 'Evita dar tirones con la espalda; exhala al subir e inhala al bajar.']::text[], 'avanzado', 'Refuerza los trapecios y la parte alta de la espalda, mejorando el agarre y la postura con un rango de movimiento amplio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4862'),
('4f1ab50e-6a9a-58ae-8661-96d19138e74f', 'Giro de pie con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo.', 'Activa el core y mantén la espalda recta durante todo el ejercicio.', 'Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo.', 'Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.', 'Repite el giro hacia el lado izquierdo.', 'Continúa alternando los giros el número de repeticiones deseado.']::text[], 'intermedio', 'Activa los abdominales y oblicuos con rotación controlada, mejorando la estabilidad del tronco y la movilidad de la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0112'),
('a949a790-0ffb-5869-86b7-7cdf7b139d6f', 'Curl de bíceps de pie con agarre abierto y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros.', 'Mantén la espalda recta y los codos cerca del torso.', 'Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los bíceps con un agarre amplio que aumenta la tensión en la parte interna del brazo y en los antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1629'),
('004652b1-5486-5833-a59b-56824c67a080', 'Press militar de pie con agarre abierto y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra.', 'Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los hombros y el tríceps con un agarre amplio que reduce el recorrido y exige control de la parte alta de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1457'),
('be705fc5-1368-54bb-a898-068c8c66d622', 'Curl de pie con agarre abierto y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.', 'Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo.', 'Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los bíceps y antebrazos con un agarre amplio que cambia el ángulo de trabajo y mejora la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0113'),
('1dbf292a-611d-536f-a75a-0ee495a65c74', 'Curl de muñeca de pie con barra', ARRAY['Sujeta la barra con las palmas hacia arriba y los antebrazos apoyados o pegados al cuerpo.', 'Deja las muñecas relajadas y los codos ligeramente flexionados y fijos.', 'Sube la barra doblando solo las muñecas, sin mover los antebrazos.', 'Baja despacio hasta notar el estiramiento y repite sin rebotar.', 'Evita balancear el cuerpo; exhala al subir e inhala al bajar.']::text[], 'intermedio', 'Refuerza los flexores de la muñeca y el agarre, útil para prevenir molestias y mejorar la fuerza en ejercicios de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6262'),
('ff06f717-e93d-59f4-9bb0-b05bc9532c93', 'Curl de muñeca inverso de pie con barra', ARRAY['Agarra la barra con las palmas hacia abajo y los antebrazos pegados al cuerpo.', 'Mantén los codos fijos y las muñecas relajadas en posición neutra.', 'Sube la barra extendiendo las muñecas, sin mover los antebrazos.', 'Baja de forma controlada hasta notar el estiramiento y repite.', 'Evita usar impulso; exhala al subir e inhala al bajar.']::text[], 'intermedio', 'Fortalece los extensores de la muñeca y el agarre, equilibrando la musculatura del antebrazo y previniendo lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6263'),
('82673fc3-0ebd-5481-8b15-095c3fc025a2', 'Zancada estática con barra', ARRAY['Coloca la barra sobre la espalda alta y da un paso amplio hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido y el pie delantero plano.', 'Comprueba que la rodilla delantera no pase en exceso la punta del pie.', 'Empuja con el talón delantero para volver a la posición inicial sin mover los pies.', 'Respira de forma constante y evita inclinar el tronco hacia delante.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos en posición dividida, mejorando el equilibrio y la estabilidad de la pierna de apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10054'),
('6f301ad5-4e23-52e0-a29a-0696a5bc045e', 'Peso muerto con piernas rígidas en banco con barra', ARRAY['Coloca la barra sobre un banco bajo o elevación y ponte de pie frente a ella con los pies a la anchura de las caderas.', 'Agarra la barra con las palmas hacia abajo y los brazos estirados.', 'Lleva las caderas atrás bajando la barra con la espalda recta y las rodillas ligeramente flexionadas.', 'Nota el estiramiento en los isquios y sube empujando las caderas hacia delante.', 'Evita redondear la espalda; exhala al subir e inhala al bajar.']::text[], 'intermedio', 'Trabaja los isquios y glúteos con un rango amplio desde el banco, mejorando la fuerza del tren posterior y el agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1542'),
('bc603424-1c2f-5ff7-b1d8-c5fc3dd68b3f', 'Good morning con piernas semirrígidas y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios.', 'Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás.', 'Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.', 'Activa los glúteos y los isquiotibiales para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza glúteos, isquios y espalda baja con una flexión de cadera controlada que mejora la fuerza del tren posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0115'),
('a3c24647-57da-54d2-a423-965d37de6646', 'Peso muerto con piernas rígidas y barra', ARRAY['Ponte de pie con la barra delante de los muslos, agarrada con las palmas hacia abajo y los pies a la anchura de las caderas.', 'Mantén las rodillas ligeramente flexionadas y la espalda recta durante todo el recorrido.', 'Lleva las caderas hacia atrás bajando la barra pegada a las piernas hasta notar el estiramiento en los isquios.', 'Sube empujando las caderas hacia delante y apretando los glúteos al final.', 'Evita redondear la espalda o bajar más de lo que permite tu flexibilidad.']::text[], 'intermedio', 'Fortalece isquios y glúteos con un movimiento de bisagra de cadera que también trabaja la espalda baja y el agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1543'),
('b3db0f84-e09a-513c-b58b-daa49f9803b6', 'Peso muerto con piernas rectas y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.', 'Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.', 'Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Baja la barra hasta que sientas un estiramiento en los isquiotibiales.', 'Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los isquios y glúteos con las piernas casi extendidas, mejorando la fuerza del tren posterior y la movilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0116'),
('fc7bb95d-3d57-541f-96c8-089d124e43ed', 'Curl estricto con barra', ARRAY['Colócate de pie con la barra agarrada en supinación y los codos pegados al torso.', 'Sube la barra flexionando solo los codos hasta la altura del pecho.', 'Baja controlando el movimiento durante dos segundos sin dejar caer la barra.', 'Evita balancear la espalda o adelantar los codos para no restar tensión al bíceps.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo para ganar fuerza y volumen en el brazo sin balanceos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5669'),
('fbccd4cd-1f8e-5f89-a071-3d1f4b720f9a', 'Acarreo de maleta con barra', ARRAY['Sujeta la barra con una mano a un lado del cuerpo, como si fuera una maleta.', 'Mantén el torso erguido y los hombros nivelados durante todo el recorrido.', 'Camina con pasos cortos y controlados sin inclinarte hacia el lado de la carga.', 'Evita encoger el hombro o dejar que la barra se aleje del cuerpo.']::text[], 'intermedio', 'Fortalece el core, los glúteos y el agarre mientras caminas cargando la barra a un lado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2918'),
('f0112d0a-63b9-54c1-a831-c454c3913ace', 'Peso muerto sumo desde bloques con barra', ARRAY['Coloca la barra sobre bloques y sitúate con los pies anchos y las puntas hacia fuera.', 'Agarra la barra con los brazos rectos y el pecho arriba antes de tirar.', 'Empuja el suelo con los pies y extiende las caderas hasta quedar de pie.', 'Baja la barra controlando la espalda y evitando redondear la zona lumbar.']::text[], 'intermedio', 'Trabaja glúteos e isquios con un rango parcial que refuerza la fase inicial del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4107'),
('935504bb-3e60-5fb8-a800-a3d38f37ac3f', 'Peso muerto sumo desde déficit con barra', ARRAY['Sube sobre una plataforma baja y coloca los pies anchos con las puntas hacia fuera.', 'Agarra la barra con la espalda recta y el pecho alto antes de iniciar el tirón.', 'Empuja el suelo y extiende caderas y rodillas a la vez hasta quedar erguido.', 'Evita perder la curvatura lumbar al bajar la barra al suelo.']::text[], 'intermedio', 'Aumenta el rango de recorrido para potenciar glúteos, isquios y la fuerza de arranque desde el suelo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4864'),
('6c5ffd75-bd5f-50aa-9ed5-62ea7bf74aba', 'Peso muerto rumano sumo con barra', ARRAY['De pie con los pies anchos, sujeta la barra delante de los muslos con los brazos rectos.', 'Lleva las caderas hacia atrás bajando la barra pegada a las piernas.', 'Detente cuando notes tensión en los isquios y sube apretando los glúteos.', 'Evita flexionar en exceso las rodillas o redondear la espalda.']::text[], 'intermedio', 'Estira los isquios y glúteos con una variante de cadera que mejora la fuerza posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3731'),
('4a312c44-c868-55d5-908e-3dc4dd20514d', 'Thruster con barra', ARRAY['Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono.', 'Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza.', 'Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Combina sentadilla y press para elevar la frecuencia cardiaca y trabajar todo el cuerpo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '3305'),
('054bcd59-b379-56eb-a0ba-ce2d97f54f22', 'Activación de gemelos caminando con barra', ARRAY['Coloca la barra sobre la espalda alta y mantén el torso erguido.', 'Camina elevando los talones en cada paso para activar los gemelos.', 'Mantén el core firme y evita inclinarte hacia delante.', 'Da pasos cortos y controlados sin perder el equilibrio.']::text[], 'intermedio', 'Activa gemelos y sóleo con un caminar controlado que mejora la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2990'),
('4416ca44-56e5-5767-8202-ad2da4ee8c54', 'Zancada caminando con barra', ARRAY['Coloca la barra sobre la espalda alta y da un paso largo hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con el pie delantero para volver a la posición inicial y cambia de pierna.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5823'),
('83c9ff7d-fec6-579b-ab83-3a7f99329bf4', 'Press de banca con peso y barra', ARRAY['Túmbate en el banco con los pies firmes en el suelo y agarra la barra a la anchura de los hombros.', 'Baja la barra al pecho controlando el movimiento y manteniendo las escápulas retraídas.', 'Empuja la barra hacia arriba sin bloquear los codos de golpe.', 'Evita rebotar la barra en el pecho o despegar los glúteos del banco.']::text[], 'intermedio', 'Trabaja el pectoral, el tríceps y el hombro para ganar fuerza y masa en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3310'),
('51b51c32-6c53-5437-9c80-e0e199a84ce5', 'Peso muerto sumo con cadenas y barra', ARRAY['Coloca las cadenas en la barra y sitúate con los pies anchos y las puntas hacia fuera.', 'Agarra la barra con la espalda recta y el pecho alto antes de tirar.', 'Empuja el suelo y extiende las caderas hasta quedar de pie con la barra pegada.', 'Baja controlando el peso y evitando que las cadenas te desequilibren.']::text[], 'intermedio', 'Añade resistencia variable para potenciar glúteos y espalda en la fase final del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5912'),
('f4b24749-15df-5c99-9ec4-14a3db91804e', 'Peso muerto con peso y barra', ARRAY['Coloca los pies a la anchura de las caderas con la barra pegada a las espinillas.', 'Agarra la barra con los brazos rectos y el pecho arriba antes de tirar.', 'Empuja el suelo y extiende caderas y rodillas hasta quedar erguido.', 'Baja la barra controlando la espalda y evitando redondear la zona lumbar.']::text[], 'intermedio', 'Ejercicio global que fortalece glúteos, isquios y espalda baja, clave para la fuerza general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3308'),
('d31eea2e-6b94-5760-ae33-0295699e9826', 'Sentadilla frontal al pecho con peso y barra', ARRAY['Coloca la barra sobre los deltoides frontales con los codos altos.', 'Baja flexionando rodillas y caderas manteniendo el torso vertical.', 'Sube empujando el suelo con los pies y apretando el core.', 'Evita que los codos bajen o que el pecho se desplome hacia delante.']::text[], 'intermedio', 'Prioriza el cuádriceps y el core con una sentadilla que exige una postura muy erguida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3309'),
('3f91636c-1db6-5779-9f38-ff4eb82934bd', 'Complejo de halterofilia con barra', ARRAY['Elige una carga ligera y coloca la barra en posición de arranque.', 'Ejecuta cada movimiento del complejo con control y sin prisa.', 'Mantén la espalda recta y el core firme en todo el encadenado.', 'Evita perder la técnica por fatiga; si pasa, reduce la carga.']::text[], 'intermedio', 'Encadena varios movimientos olímpicos para mejorar la potencia, la técnica y la resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3316'),
('2c4b8be3-bb74-5cce-a284-083239ac4d78', 'Press de banca abierto con barra', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera.', 'Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Con un agarre amplio, incide más en el pectoral externo y en la apertura del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0122'),
('7046d6e7-a78a-5630-811a-a556a523253f', 'Curl drag con agarre abierto y barra', ARRAY['Sujeta la barra con las palmas hacia arriba y un agarre más ancho que los hombros, de pie y con el torso firme.', 'Sube la barra deslizándola cerca del abdomen y el pecho, llevando los codos hacia atrás.', 'Aprieta el bíceps arriba un instante y baja controlando el movimiento.', 'Evita balancear el tronco o encoger los hombros para no perder tensión en el bíceps.']::text[], 'intermedio', 'Trabaja el bíceps y el braquial con un recorrido que sube la barra pegada al cuerpo, ganando tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2413'),
('f0a294e9-dba2-5fec-b984-42100cc92a10', 'Pullover con agarre abierto y barra', ARRAY['Túmbate en un banco con la barra sujeta por encima del pecho y las manos bien separadas.', 'Lleva la barra hacia atrás en arco, por detrás de la cabeza, manteniendo los codos ligeramente flexionados.', 'Inspira al bajar y espira al devolver la barra al pecho.', 'No arquees en exceso la zona lumbar ni bajes más allá de donde controlas el peso.']::text[], 'intermedio', 'Estira y fortalece el dorsal y el pectoral llevando la barra por detrás de la cabeza con los brazos casi rectos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4340'),
('b322a896-a2e8-5bf8-b3e4-274db590c621', 'Press de banca con agarre inverso y abierto', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas.', 'Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante del press que enfatiza la parte superior del pectoral y el tríceps con un agarre invertido y amplio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1258'),
('0103f12a-439e-53fe-9139-7ac7d00185a5', 'Encogimientos con agarre abierto y barra', ARRAY['De pie, sujeta la barra con las palmas hacia abajo y un agarre más ancho que los hombros.', 'Eleva los hombros hacia las orejas sin doblar los codos ni mover la barra con los brazos.', 'Aprieta arriba un segundo y baja despacio hasta estirar el trapecio.', 'Evita encoger el cuello o dar tirones con el tronco para no cargar la zona cervical.']::text[], 'intermedio', 'Fortalece el trapecio superior y la fuerza de agarre elevando los hombros con la barra sujeta al frente.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5224'),
('81857ec5-742f-51af-b386-1869b393d6ea', 'Sentadilla con piernas abiertas y barra', ARRAY['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.', 'Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.', 'Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el cuádriceps y los glúteos con una base amplia que aumenta la estabilidad y la implicación del aductor.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0124'),
('e1ddc063-a860-5415-bc63-a0a727684a0e', 'Peso muerto con piernas rígidas y postura amplia', ARRAY['Coloca los pies más anchos que los hombros y sujeta la barra frente a los muslos con la espalda recta.', 'Empuja la cadera hacia atrás y baja la barra pegada a las piernas, con las rodillas ligeramente flexionadas.', 'Nota el estiramiento en los isquiotibiales y sube apretando los glúteos al espirar.', 'No redondees la espalda ni bajes más de lo que permite tu flexibilidad.']::text[], 'intermedio', 'Estira y fortalece los isquiotibiales y glúteos con las piernas abiertas y casi rectas durante todo el recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1544'),
('e0353935-8640-565f-8894-44c6a8d67361', 'Remo al mentón con agarre abierto y barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros.', 'Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos.', 'Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos.', 'Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla el deltoides y el trapecio tirando de la barra hacia el mentón con los codos altos y abiertos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0123'),
('c5833ee9-072e-5c4b-9f2a-69d598b074bb', 'Curl de muñeca con barra', ARRAY['Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino.', 'Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas.', 'Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los flexores del antebrazo y mejora el agarre flexionando las muñecas con la barra en las manos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0126'),
('1098f8e1-3f63-540d-9fb1-641e36b14abb', 'Extensión de espalda zercher con barra', ARRAY['Coloca la barra en el pliegue de los codos y sujétala con las manos, con los pies firmes y el torso inclinado.', 'Extiende la cadera y la espalda hasta quedar erguido, apretando glúteos al final.', 'Baja controlando el movimiento sin perder la curva natural de la espalda.', 'Evita hiperextender la zona lumbar al subir o soltar la barra lejos del cuerpo.']::text[], 'intermedio', 'Refuerza la cadena posterior y la musculatura de la columna sosteniendo la barra en el hueco de los codos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8991'),
('387fa893-6ee6-5307-a6de-2429864982d9', 'Sentadilla búlgara zercher con barra', ARRAY['Sujeta la barra en el pliegue de los codos y apoya el empeine del pie trasero en un banco.', 'Baja flexionando la pierna delantera hasta que el muslo quede cerca de la horizontal.', 'Empuja con el talón delantero para subir manteniendo el torso erguido y el core firme.', 'No dejes que la rodilla delantera se vaya hacia dentro ni que el tronco se desplome.']::text[], 'intermedio', 'Trabaja el cuádriceps y el glúteo de una pierna con la barra en los codos, exigiendo mucho al core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7552'),
('1868a654-bf93-53c2-8521-d8bbb015d00e', 'Acarreo zercher con barra', ARRAY['Sujeta la barra en el pliegue de los codos con las manos entrelazadas y el torso erguido.', 'Camina con pasos cortos y firmes, manteniendo el core apretado y los hombros atrás.', 'Respira de forma constante sin aguantar la respiración durante el recorrido.', 'Evita inclinarte hacia atrás o dejar caer los codos para no sobrecargar la lumbar.']::text[], 'intermedio', 'Mejora la fuerza de agarre, el core y la resistencia de piernas caminando con la barra sujeta en los codos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2915'),
('e45ed081-e447-55e5-9c3e-a5b2f8065848', 'Peso muerto zercher con barra', ARRAY['Con la barra en el suelo, agáchate y colócala en el pliegue de los codos con la espalda recta.', 'Empuja con las piernas y extiende la cadera para levantarte manteniendo la barra pegada al torso.', 'Espira al subir y controla la bajada flexionando rodillas y cadera.', 'No redondees la espalda ni levantes con los brazos en vez de con las piernas.']::text[], 'intermedio', 'Levanta la barra desde el suelo sujetándola en los codos, trabajando glúteos, isquiotibiales y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5670'),
('a1ad7674-e6bf-5406-bf4f-715c91736374', 'Sentadilla Zercher con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad.', 'Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.', 'Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.', 'Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Sentadilla con la barra en los codos que implica glúteos, cuádriceps y core por la posición frontal de la carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0127'),
('aca52a88-f638-5424-b439-b4640f94fe9b', 'Sostén de sentadilla zercher con barra', ARRAY['Sujeta la barra en el pliegue de los codos y baja hasta una sentadilla cómoda con el torso erguido.', 'Mantén la posición con los pies firmes, el core apretado y la mirada al frente.', 'Respira con normalidad sin aguantar el aire durante todo el sostén.', 'Sal de la posición subiendo despacio y evitando que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Isométrico que mantiene el cuádriceps y el core bajo tensión con la barra sujeta en los codos en posición baja.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1446'),
('0f1b36d5-9cfc-54eb-aa1c-af001cc301bc', 'Patada de burro cruzada', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Extiende una pierna hacia atrás y crúzala ligeramente hacia el lado contrario sin girar la cadera.', 'Aprieta el glúteo arriba y vuelve despacio sin apoyar del todo la rodilla.', 'Evita arquear la lumbar o balancear el tronco para no perder el control.']::text[], 'intermedio', 'Activa el glúteo y el core llevando una pierna extendida hacia atrás y en diagonal desde cuadrupedia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6316'),
('899e5191-afb9-5f4c-b0ab-b44cedbad80c', 'Toque de pies básico', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza glúteos e isquiotibiales y activa la cadena posterior, mejorando la flexibilidad y la coordinación en un gesto sencillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3212'),
('ae0d829d-861f-5f5a-adca-1ff46acfa8aa', 'Salto con tiro de baloncesto', ARRAY['Colócate de pie con los pies a la anchura de los hombros y los brazos flexionados como si sostuvieras un balón.', 'Flexiona las rodillas y baja la cadera mientras llevas los brazos atrás para cargar el salto.', 'Empuja con fuerza el suelo y salta extendiendo piernas y brazos hacia arriba como en un tiro.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto sin dejar caer los talones de golpe.', 'Evita bloquear las rodillas en el aire y mantén el abdomen activo durante todo el movimiento.']::text[], 'intermedio', 'Trabaja cuádriceps y gemelos con un salto explosivo que mejora la potencia de piernas y la coordinación del tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4709'),
('74acf46f-4a20-5892-b416-757e147e4abe', 'Jalón con cuerda de batalla', ARRAY['Sujeta un extremo de la cuerda en cada mano y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Tira de las cuerdas hacia ti de forma explosiva, llevando los codos hacia atrás y juntando las escápulas.', 'Vuelve a extender los brazos de forma controlada sin perder la tensión en el tronco.', 'Mantén el abdomen firme y evita encorvar la espalda o tirar solo con los brazos.', 'Respira de forma rítmica y mantén un tempo constante durante toda la serie.']::text[], 'intermedio', 'Fortalece dorsales y agarre con un tirón potente que también activa el core y los glúteos en posición estable.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '8703'),
('1e7608bc-8214-5b4a-90e7-3fd56e62df21', 'Cuerdas de batalla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí.', 'Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.', 'Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo.', 'Continúa durante el tiempo o el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja hombros y antebrazos con ondas continuas que también exigen estabilidad del core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0128'),
('55c15129-5e99-51e3-a7ae-8b041d10a4ca', 'Sentadilla con salto y cuerdas de batalla con brazos alternados', ARRAY['Sujeta las cuerdas con una mano en cada extremo y colócate de pie con los pies a la anchura de los hombros.', 'Flexiona las rodillas y salta extendiendo las piernas mientras mueves los brazos alternando ondas.', 'Aterriza suavemente con las rodillas flexionadas y continúa las ondas sin detener el movimiento.', 'Mantén el pecho alto y el abdomen activo para evitar que la espalda se curve.', 'Ajusta el ritmo de las ondas a tu respiración y evita saltar con las piernas rígidas.']::text[], 'intermedio', 'Combina salto y ondas de cuerda para elevar el pulso y trabajar piernas, hombros y core de forma intensa.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3370'),
('c81a40b6-cc53-5d36-a900-3157253c3686', 'Zancada lateral con cuerdas de batalla y brazos alternados', ARRAY['Sujeta las cuerdas con una mano en cada extremo y da un paso lateral amplio flexionando la rodilla de ese lado.', 'Mantén la otra pierna extendida y baja la cadera hacia atrás mientras mueves los brazos alternando ondas.', 'Empuja con la pierna flexionada para volver al centro y repite hacia el otro lado.', 'Mantén el tronco erguido y evita que la rodilla de la pierna flexionada pase por delante de los dedos del pie.', 'Controla la respiración y no bloquees las caderas durante el cambio de lado.']::text[], 'intermedio', 'Activa glúteos, cuádriceps y aductores mientras las ondas de cuerda elevan el pulso y trabajan hombros y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3372'),
('20d319b4-9c94-5486-8eb4-5b9143bb5951', 'Sentadilla con cuerdas de batalla y brazos alternados', ARRAY['Sujeta las cuerdas con una mano en cada extremo y colócate de pie con los pies a la anchura de los hombros.', 'Baja en sentadilla llevando la cadera atrás y flexionando las rodillas mientras mueves los brazos alternando ondas.', 'Sube empujando con los talones y mantén las ondas de cuerda sin parar.', 'Mantén el pecho alto y evita que las rodillas se metan hacia dentro al bajar.', 'Respira de forma constante y ajusta la profundidad de la sentadilla a tu control.']::text[], 'intermedio', 'Trabaja piernas y glúteos en sentadilla mientras las ondas de cuerda elevan el pulso y activan hombros y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3369'),
('23dcdadc-b433-57cd-b13f-4047bc55e98e', 'Ondas alternas con cuerdas de batalla y levantada de rodillas', ARRAY['Arrodíllate con una rodilla en el suelo y sujeta las cuerdas con una mano en cada extremo.', 'Mueve los brazos alternando ondas mientras mantienes el tronco erguido y el abdomen activo.', 'Levántate del suelo empujando con la pierna delantera y vuelve a arrodillarte con control.', 'Evita apoyar todo el peso en la rodilla y mantén la cadera alineada con los hombros.', 'Respira de forma rítmica y no dejes que la espalda se curve al levantarte.']::text[], 'intermedio', 'Combina ondas de cuerda con un cambio de rodillas que exige core, hombros y piernas para elevar el pulso.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4131'),
('e02612ed-1cb2-5a88-878b-816fbbc28a77', 'Apertura con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Abre los brazos hacia los lados de forma controlada, llevando las cuerdas hacia fuera.', 'Vuelve al centro sin dejar que los brazos caigan y mantén la tensión en los hombros.', 'Mantén el pecho alto y evita encorvar la espalda o encoger los hombros hacia las orejas.', 'Respira de forma constante y controla el ritmo de apertura y cierre.']::text[], 'intermedio', 'Trabaja hombros y espalda alta con un movimiento de apertura que también activa el core y los deltoides posteriores.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3375'),
('6632c283-3162-5966-b810-e051746c652d', 'Cuerdas de batalla de rodillas con una pierna', ARRAY['Arrodíllate con una rodilla en el suelo y la otra pierna flexionada por delante, sujetando las cuerdas con una mano en cada extremo.', 'Mueve los brazos alternando ondas manteniendo el tronco erguido y el abdomen activo.', 'Evita apoyar todo el peso en la rodilla y mantén la cadera alineada con los hombros.', 'Respira de forma rítmica y no dejes que la espalda se curve durante las ondas.', 'Cambia de pierna a mitad de la serie para trabajar ambos lados por igual.']::text[], 'intermedio', 'Trabaja hombros, core y agarre en una posición de media rodilla que exige estabilidad y eleva el pulso.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4052'),
('01adddf3-68a7-525b-9e94-0fbe37277145', 'Olas altas con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Levanta los brazos hasta la altura de los hombros y mueve las cuerdas formando olas amplias y rápidas.', 'Mantén el pecho alto y el abdomen activo para evitar que la espalda se curve.', 'Evita encoger los hombros hacia las orejas y controla la respiración durante toda la serie.', 'Ajusta la altura de las olas a tu resistencia y no pierdas el ritmo.']::text[], 'intermedio', 'Eleva el pulso con ondas amplias que trabajan hombros, espalda alta, core y antebrazos de forma intensa.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3379');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('04a96a87-6156-5395-b169-9dc3fb27f47f', 'Círculo hacia dentro con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Dibuja círculos hacia dentro con las cuerdas, moviendo los brazos de forma coordinada y controlada.', 'Mantén el pecho alto y el abdomen activo para evitar que la espalda se curve.', 'Evita encoger los hombros y mantén un ritmo constante sin perder la tensión.', 'Respira de forma rítmica y ajusta el tamaño de los círculos a tu control.']::text[], 'intermedio', 'Trabaja hombros, espalda alta y core con movimientos circulares que elevan el pulso y exigen coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3373'),
('1d675f94-a32c-589c-9abc-825d42219d0b', 'Jumping jack con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y colócate de pie con los pies juntos.', 'Salta abriendo las piernas a la anchura de los hombros mientras mueves los brazos alternando ondas.', 'Vuelve a juntar los pies con un salto suave y continúa las ondas sin parar.', 'Aterriza con las rodillas ligeramente flexionadas y evita saltar con las piernas rígidas.', 'Mantén el abdomen activo y respira de forma constante durante toda la serie.']::text[], 'intermedio', 'Combina saltos y ondas de cuerda para elevar el pulso y trabajar hombros, gemelos, cuádriceps y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3376'),
('4b29d15e-706c-515a-822f-c3c3e76425b0', 'Olas bajas con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Mantén los brazos bajos y mueve las cuerdas formando olas cortas y rápidas cerca del suelo.', 'Mantén el pecho alto y el abdomen activo para evitar que la espalda se curve.', 'Evita encoger los hombros y controla la respiración durante toda la serie.', 'Ajusta la velocidad de las olas a tu resistencia y no pierdas el ritmo.']::text[], 'intermedio', 'Eleva el pulso con ondas cortas y rápidas que trabajan hombros, core, antebrazos y glúteos en posición estable.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3380'),
('b87b6262-51ef-5ac7-b59a-07aec4018a69', 'Círculo hacia fuera con cuerdas de batalla', ARRAY['Sujeta las cuerdas con una mano en cada extremo y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Dibuja círculos hacia fuera con las cuerdas, moviendo los brazos de forma coordinada y controlada.', 'Mantén el pecho alto y el abdomen activo para evitar que la espalda se curve.', 'Evita encoger los hombros y mantén un ritmo constante sin perder la tensión.', 'Respira de forma rítmica y ajusta el tamaño de los círculos a tu control.']::text[], 'intermedio', 'Trabaja hombros, espalda alta y core con movimientos circulares hacia fuera que elevan el pulso y exigen coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3374'),
('27f94aee-1e02-5969-bd1a-ec16e84de716', 'Golpe de poder con cuerdas de batalla', ARRAY['Colócate frente a las cuerdas con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.', 'Agarra un extremo en cada mano y levanta ambos brazos por encima de la cabeza con fuerza.', 'Golpea el suelo con las cuerdas de forma explosiva y vuelve a subirlas sin parar.', 'Mantén el core firme y la espalda recta, respirando de forma rítmica.', 'Evita encorvar la espalda o bloquear las rodillas durante el movimiento.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja hombros, core y espalda en un gesto explosivo de cuerpo completo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3384'),
('7d913239-6114-50e8-bd6f-2e06c83ab3cc', 'Giro ruso con cuerdas de batalla', ARRAY['Siéntate o ponte de rodillas frente a las cuerdas y agarra un extremo en cada mano.', 'Lleva las cuerdas a un lado a la altura de la cadera girando el tronco.', 'Cambia de lado de forma continua y controlada, sin mover solo los brazos.', 'Mantén el abdomen apretado y respira de forma constante.', 'Evita tirar solo con los brazos o redondear la espalda.']::text[], 'intermedio', 'Activa oblicuos y abdomen con un giro controlado que también exige estabilidad de hombros y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3377'),
('8c0e2c5f-b09a-5d9f-b564-4aa9696ad204', 'Cuerdas de batalla sentado', ARRAY['Siéntate frente a las cuerdas con la espalda recta y los pies apoyados.', 'Agarra un extremo en cada mano y levanta los brazos a la altura del pecho.', 'Mueve las cuerdas arriba y abajo de forma rápida y continua.', 'Mantén el core activo y respira con ritmo constante.', 'Evita encorvar la espalda o perder el control del movimiento.']::text[], 'intermedio', 'Alternativa de bajo impacto para elevar el pulso y trabajar hombros, core y espalda alta.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4112'),
('72579499-da88-5d6a-bc38-1ba198d59db3', 'Elevación lateral con cuerdas de batalla', ARRAY['Colócate de pie frente a las cuerdas con los pies a la anchura de los hombros.', 'Agarra un extremo en cada mano con los brazos junto al cuerpo.', 'Eleva los brazos lateralmente hasta la altura de los hombros y baja con control.', 'Mantén el core firme y evita balancear el tronco.', 'No subas los hombros hacia las orejas ni uses impulso.']::text[], 'intermedio', 'Trabaja el deltoides con elevaciones laterales que también activan espalda alta y antebrazos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2828'),
('5f52c5f2-ff13-5311-8f71-43e8cd2e2b8e', 'Cuerdas de batalla de lado a lado', ARRAY['Ponte frente a las cuerdas con las rodillas ligeramente flexionadas y el core activo.', 'Agarra un extremo en cada mano y lleva las cuerdas a un lado.', 'Cambia rápidamente al otro lado manteniendo el ritmo.', 'Respira de forma constante y mantén la espalda recta.', 'Evita girar solo los brazos sin acompañar con el tronco.']::text[], 'intermedio', 'Ejercicio cardiovascular que implica hombros, core y oblicuos con un movimiento lateral continuo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3371'),
('25d823ca-0b2a-5d8f-8d0f-cd6bee12f618', 'Salto dividido con cuerdas de batalla', ARRAY['Colócate frente a las cuerdas con un pie adelantado y otro atrás.', 'Agarra un extremo en cada mano y mueve las cuerdas de forma continua.', 'Salta cambiando la posición de las piernas sin parar el movimiento de brazos.', 'Aterriza con las rodillas ligeramente flexionadas y el core firme.', 'Evita aterrizar con las piernas rígidas o perder el ritmo de las cuerdas.']::text[], 'intermedio', 'Movimiento pliométrico que eleva el pulso y trabaja piernas, glúteos y hombros de forma explosiva.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3378'),
('83a4f69f-ad5a-5548-a85e-b64dc07833a7', 'Caminata del oso', ARRAY['Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.', 'Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.', 'Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.', 'Continúa avanzando a gatas, alternando los movimientos de manos y pies.', 'Mantén un ritmo constante y el core firme durante todo el ejercicio.', 'Continúa durante la distancia o el tiempo deseado.']::text[], 'intermedio', 'Desplazamiento cuadrúpedo que eleva el pulso y fortalece core, hombros y tríceps.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3360'),
('bd95ffb6-0505-5adc-b85a-85109fdd8a51', 'Caminata de oso con cadera baja', ARRAY['Apóyate en manos y pies con las rodillas flexionadas y la cadera baja.', 'Avanza una mano y el pie contrario de forma coordinada.', 'Mantén la espalda recta y el abdomen apretado durante todo el recorrido.', 'Respira de forma constante y da pasos cortos y controlados.', 'Evita elevar la cadera o dejar caer la cabeza.']::text[], 'intermedio', 'Variante que eleva el pulso y exige más a hombros, cuádriceps y core al mantener la cadera baja.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6599'),
('00fb312e-b3fb-5a45-b9ab-20acb8e13834', 'Plancha de oso', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Levanta las rodillas unos centímetros del suelo manteniendo la espalda recta.', 'Aprieta el abdomen y mantén la posición el tiempo indicado.', 'Respira de forma constante sin aguantar la respiración.', 'Evita elevar la cadera o hundir la zona lumbar.']::text[], 'intermedio', 'Isométrico que refuerza el abdomen y el core mientras exige estabilidad a hombros y cuádriceps.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4170'),
('17657eab-61e9-522b-98a6-7d5dc31122fe', 'Patada hacia atrás en plancha de oso', ARRAY['Colócate en plancha de oso con las rodillas levantadas del suelo.', 'Extiende una pierna hacia atrás sin mover la cadera.', 'Vuelve a la posición inicial y alterna con la otra pierna.', 'Mantén el abdomen apretado y la espalda recta.', 'Evita arquear la zona lumbar o girar la cadera.']::text[], 'intermedio', 'Activa glúteos e isquios desde una plancha de oso que también exige estabilidad de core y hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6442'),
('d4bd43b6-f688-5441-bda8-d104931f06dd', 'Estiramiento de pecho por detrás de la cabeza', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera.', 'Junta lentamente los omóplatos y empuja el pecho hacia adelante.', 'Mantén el estiramiento durante 15-30 segundos.', 'Suelta el estiramiento y repite cuantas veces lo desees.']::text[], 'principiante', 'Estira pectorales y hombros para mejorar la movilidad del tren superior y aliviar tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1259'),
('e81b1f33-002c-57b3-8720-f89c9b21adc5', 'Fondos en banco con control de técnica', ARRAY['Siéntate en el banco con las manos a los lados y desliza la cadera hacia delante.', 'Flexiona los codos hasta unos 90 grados manteniendo la espalda cerca del banco.', 'Empuja con las manos para volver arriba sin bloquear los codos.', 'Mantén los hombros abajo y el core firme durante todo el movimiento.', 'Evita bajar demasiado o encorvar los hombros hacia las orejas.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombros con un movimiento controlado que cuida la técnica y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2346'),
('3188a889-0ab8-55bc-a225-9cfde9217a24', 'Fondos en banco en el suelo', ARRAY['Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.', 'Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Versión en el suelo que trabaja tríceps, pecho y hombros con un rango de movimiento más seguro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1399'),
('af0b3e84-f7e7-5d16-b817-3715a31a30ac', 'Fondos en banco con piernas en el banco', ARRAY['Siéntate en el banco con las manos a los lados y apoya los talones en otro banco.', 'Desliza la cadera hacia delante y flexiona los codos hasta unos 90 grados.', 'Empuja con las manos para subir sin bloquear los codos.', 'Mantén el core firme y los hombros lejos de las orejas.', 'Evita bajar demasiado o perder la alineación de la espalda.']::text[], 'intermedio', 'Variante más exigente que intensifica el trabajo de tríceps, hombros y pecho al elevar las piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4360'),
('7d11917b-ada2-516d-8742-5086fa8202cf', 'Sentadilla completa en banco', ARRAY['Colócate de pie frente al banco con los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás hasta tocar el banco con control.', 'Empuja con los talones para volver a la posición inicial.', 'Mantén el pecho arriba y las rodillas alineadas con los pies.', 'Evita dejar caer el peso o levantar los talones del suelo.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos e isquios con una sentadilla completa que también exige estabilidad de core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2560'),
('60abcf3c-3cdc-5f5d-b73f-466185b4c9b4', 'Extensión de cadera en banco', ARRAY['Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo.', 'Coloca las manos sobre el banco para apoyarte.', 'Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos e isquios trabajando la extensión de cadera, clave para empujar y estabilizar la pelvis.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0130'),
('67220a4c-31f5-5cba-9d88-84129b888c87', 'Dominadas en banco', ARRAY['Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho.', 'Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros.', 'Cuélgate con los brazos completamente extendidos y el cuerpo recto.', 'Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos.', 'Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie.', 'Baja de nuevo a la posición inicial con control.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsal y bíceps tirando del propio peso, mejorando fuerza de tracción y control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3019'),
('4b7add74-cd4e-5d47-ad08-7574653dbdc5', 'Estiramiento de hombro con brazo flexionado', ARRAY['Lleva un brazo cruzado sobre el pecho con el codo flexionado.', 'Con la otra mano, presiona suavemente el codo hacia ti sin forzar.', 'Mantén la espalda recta y los hombros bajos, sin encogerlos.', 'Respira despacio y aguanta entre veinte y treinta segundos por lado.', 'Evita tirar del codo con brusquedad o arquear la espalda.']::text[], 'principiante', 'Relaja deltoides y tríceps tras el entrenamiento, mejorando la movilidad del hombro y liberando tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1981'),
('83e724b8-e6dd-5fe0-aa7f-6efc6b87de4e', 'Dominada supina con brazos flexionados', ARRAY['Cuélgate de la barra con agarre supino y los codos ya flexionados.', 'Mantén el pecho alto y los omóplatos activos durante todo el ejercicio.', 'Sube hasta que la barbilla pase la barra sin balancearte.', 'Baja controlando el movimiento hasta estirar casi del todo los brazos.', 'Evita encoger los hombros o usar impulso de piernas.']::text[], 'intermedio', 'Trabaja dorsal, bíceps y core manteniendo la flexión de codos, mejorando fuerza y control en el rango alto.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5236'),
('865198fa-d9eb-5d74-9f5c-38187d13d80a', 'Patada atrás y lateral con rodilla flexionada', ARRAY['Colócate a cuatro apoyos con la espalda neutra y el core activado.', 'Lleva una pierna atrás con la rodilla flexionada sin arquear la lumbar.', 'Devuélvela al centro y llévala después hacia el lado, controlando el movimiento.', 'Mantén la cadera estable y evita girar el tronco.', 'Respira de forma constante y no balancees la pierna con impulso.']::text[], 'intermedio', 'Activa glúteos y core con patadas controladas, mejorando estabilidad de cadera y fuerza del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4692'),
('930733e4-e8f7-5757-b4e7-53aabe0f8665', 'Estiramiento de gemelos con rodilla flexionada', ARRAY['Apoya las manos en una pared y da un paso atrás con una pierna.', 'Flexiona la rodilla de la pierna trasera manteniendo el pie apoyado.', 'Empuja la cadera hacia delante hasta notar el estiramiento en la pantorrilla.', 'Mantén el talón en el suelo y respira durante veinte o treinta segundos.', 'Evita levantar el talón o girar el pie hacia fuera.']::text[], 'principiante', 'Estira sóleo y gemelos, mejorando la flexibilidad del tobillo y aliviando tensión tras correr o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11649'),
('b4a014ad-f7ce-5c96-ad48-0debeb627a83', 'Giro acostado con rodillas flexionadas', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Extiende los brazos hacia los lados, perpendiculares al cuerpo.', 'Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.', 'Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.', 'Repite el movimiento hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza la columna y la cadera tumbado, liberando tensión lumbar y mejorando la rotación del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3639'),
('8a028133-e90a-5df1-a1e3-7e477536ee5b', 'Plancha lateral con rodilla flexionada', ARRAY['Túmbate de lado y apóyate en el antebrazo con el codo bajo el hombro.', 'Flexiona las rodillas y apoya la cadera en el suelo para empezar.', 'Eleva la cadera hasta formar una línea recta entre hombro y rodilla.', 'Mantén la posición respirando con normalidad entre veinte y cuarenta segundos.', 'Evita dejar caer la cadera o adelantar el hombro.']::text[], 'intermedio', 'Refuerza oblicuos y core en isométrico, mejorando la estabilidad lateral del tronco con menor exigencia.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0133'),
('ffe723d7-570d-5d90-aba2-5582ee568985', 'Círculo de pierna flexionada de rodillas', ARRAY['Colócate a cuatro apoyos con la espalda neutra y el core activo.', 'Eleva una pierna con la rodilla flexionada a la altura de la cadera.', 'Dibuja círculos pequeños y lentos sin mover el tronco.', 'Cambia de sentido tras varias repeticiones y luego de pierna.', 'Evita arquear la lumbar o balancear la cadera.']::text[], 'intermedio', 'Activa glúteos y oblicuos con círculos controlados, mejorando movilidad de cadera y control del core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2570'),
('9441b20b-ee48-5e09-b9f4-bec2070cb7a0', 'Patada trasera con rodilla flexionada de rodillas', ARRAY['Colócate a cuatro apoyos con manos bajo hombros y rodillas bajo caderas.', 'Activa el core y mantén la espalda neutra durante todo el movimiento.', 'Lleva una pierna atrás con la rodilla flexionada hasta alinear el muslo con el tronco.', 'Baja controlando sin dejar caer la pierna y repite.', 'Evita arquear la lumbar o girar la cadera al subir.']::text[], 'intermedio', 'Aísla el glúteo con extensiones de cadera controladas, reforzando también isquios y zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3034'),
('23cf7756-3969-53a8-9b97-336c26e079d9', 'Patada lateral con rodilla flexionada de rodillas', ARRAY['Colócate a cuatro apoyos con la espalda neutra y el core activado.', 'Eleva una pierna hacia el lado con la rodilla flexionada, sin rotar la cadera.', 'Sube hasta donde controles y baja lentamente.', 'Mantén los hombros estables y evita inclinar el tronco.', 'No balancees la pierna ni fuerces más allá de tu rango.']::text[], 'intermedio', 'Trabaja abductores y glúteo medio con elevaciones laterales, mejorando estabilidad y fuerza de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3035'),
('205dbbd3-595a-554b-97c7-d8a4849196ce', 'Aducción escapular en extensión de espalda inclinado', ARRAY['Inclina el tronco hacia delante con la espalda recta y las rodillas algo flexionadas.', 'Deja los brazos colgando y junta los omóplatos llevando los codos atrás.', 'Mantén la posición un instante sintiendo la espalda alta.', 'Vuelve despacio a la posición inicial sin redondear la espalda.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'intermedio', 'Fortalece la espalda alta juntando omóplatos, mejorando postura y control escapular junto a glúteos e isquios.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8896'),
('122f36c1-a829-5f98-8847-8c83b2d7b04f', 'Elevación de brazos inclinado de espalda a lateral a frontal', ARRAY['Inclina el tronco hacia delante con la espalda recta y el core activo.', 'Eleva los brazos hacia atrás juntando omóplatos y vuelve al centro.', 'Llévalos después hacia los lados y luego hacia delante, sin subir los hombros.', 'Realiza el recorrido lento y controlado respirando con normalidad.', 'Evita arquear la lumbar o usar impulso para subir los brazos.']::text[], 'principiante', 'Moviliza hombros y espalda alta con elevaciones en distintos planos, mejorando control y movilidad del deltoides.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11798'),
('1b80151d-16c7-531e-81cf-67880e65be1a', 'Remo inclinado, espalda (control de técnica)', ARRAY['Sujeta la barra con las manos algo más anchas que los hombros.', 'Inclina el tronco hacia delante con la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la barra hacia el abdomen juntando los omóplatos.', 'Baja la barra controlando el movimiento sin redondear la espalda.', 'Evita usar impulso del tronco o encoger los hombros.']::text[], 'intermedio', 'Fortalece dorsal y espalda alta con tracción horizontal, mejorando fuerza de tirón y postura con control técnico.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2343'),
('b186323e-e319-5d00-a4e5-638b15790753', 'Remo inclinado con toalla', ARRAY['Pasa una toalla por un punto fijo y sujeta un extremo con cada mano.', 'Inclina el tronco hacia atrás con la espalda recta y las rodillas algo flexionadas.', 'Tira de la toalla hacia el pecho juntando los omóplatos.', 'Vuelve despacio estirando los brazos sin perder la postura.', 'Evita tirar con la espalda redondeada o usar impulso del cuerpo.']::text[], 'intermedio', 'Trabaja dorsal y bíceps con tracción usando una toalla, mejorando fuerza de espalda sin material de gimnasio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3828'),
('c7711aea-fab0-5260-bdc2-f2a4298e53b6', 'Péndulo de hombro inclinado', ARRAY['Inclina el tronco hacia delante con la espalda recta y apoya una mano en un apoyo estable.', 'Deja colgar el otro brazo relajado y dibuja círculos pequeños con el hombro.', 'Aumenta poco a poco el tamaño de los círculos sin mover el tronco.', 'Respira de forma continua y evita encoger el cuello o forzar el rango.']::text[], 'principiante', 'Moviliza el hombro y activa el manguito rotador para calentar antes de empujar o tirar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6438'),
('3975c500-abf5-51d4-8e6b-522b2b8a6ccb', 'Giro inclinado', ARRAY['Separa los pies a la anchura de los hombros y flexiona ligeramente las rodillas.', 'Inclina el tronco hacia delante manteniendo la espalda recta y el pecho abierto.', 'Gira el tronco hacia un lado y hacia el otro de forma lenta y controlada.', 'Evita redondear la espalda o girar solo con los brazos; acompaña con la respiración.']::text[], 'principiante', 'Mejora la movilidad de la columna y la cadera, implicando oblicuos y lumbares con control.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3391'),
('f49d2600-7880-5764-9455-def5a1f8738c', 'Flexión lateral con rodilla flexionada', ARRAY['Coloca las manos algo más anchas que los hombros y apoya las rodillas en el suelo.', 'Baja el pecho hacia el suelo manteniendo el cuerpo alineado de cabeza a rodillas.', 'Empuja con las manos para volver arriba sin bloquear los codos.', 'Evita que la cadera se hunda o que los codos se abran en exceso.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps desde una variante más accesible que la flexión estándar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0134'),
('3be88860-be13-5a4d-b22c-8ad6467342d3', 'Curl de bíceps con mancuerna', ARRAY['De pie con una mancuerna en cada mano y los brazos pegados al cuerpo.', 'Flexiona los codos subiendo las mancuernas sin mover los hombros hacia delante.', 'Baja despacio controlando el movimiento hasta estirar casi del todo el brazo.', 'Evita balancear el tronco o usar impulso para subir el peso.']::text[], 'intermedio', 'Fortalece bíceps y antebrazo con un control técnico que evita balanceos y compensaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2352'),
('d7e3912d-fd64-567f-a65c-1c781364f221', 'Curl de bíceps con paso al frente', ARRAY['De pie con los brazos flexionados y los codos pegados al cuerpo.', 'Da un paso al frente mientras mantienes la tensión en los bíceps.', 'Vuelve a la posición inicial y alterna las piernas con ritmo controlado.', 'Evita arquear la espalda o perder la postura al dar el paso.']::text[], 'intermedio', 'Combina fuerza de bíceps con un paso dinámico que activa piernas y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5623'),
('f36d72e6-32bc-5268-bc1f-73bd925a7f3e', 'Curl de bíceps bajo la mesa', ARRAY['Agárrate al borde de una mesa firme con las palmas hacia arriba.', 'Mantén el cuerpo recto y los codos pegados al torso.', 'Tira del cuerpo hacia arriba flexionando los codos y baja despacio.', 'Evita mover los hombros o usar impulso con las piernas.']::text[], 'intermedio', 'Fortalece bíceps y antebrazo usando el propio peso corporal como resistencia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8274'),
('3ecbfdc6-4a82-55d0-8890-5354d03a447e', 'Curl de bíceps con sábana', ARRAY['Pasa una sábana por debajo de un pie y sujeta los extremos con las manos.', 'Mantén los codos pegados al cuerpo y la espalda recta.', 'Flexiona los codos tirando de la sábana y baja controlando la tensión.', 'Evita inclinarte hacia atrás o tirar con los hombros.']::text[], 'intermedio', 'Entrena bíceps y antebrazo en casa usando una sábana como resistencia improvisada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3748'),
('3f6aa470-de78-5b0b-bdb8-76e4ccb72e90', 'Curl concentrado de bíceps', ARRAY['Siéntate en un banco con las piernas separadas y los pies planos en el suelo.', 'Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla.', 'Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto.', 'Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo apoyando el codo en la pierna, mejorando el pico y la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1770'),
('a20608b5-4390-5337-9f3a-b95c8324d639', 'Dominadas para bíceps con agarre cerrado', ARRAY['Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.', 'Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Potencia el bíceps y el antebrazo con un agarre estrecho que aumenta el rango y la tensión en los brazos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0139'),
('1cac8617-e844-5ab4-a8e2-6f9c7666496b', 'Dominada para bíceps', ARRAY['Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.', 'Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.', 'Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece bíceps, antebrazos y hombros mediante tracción vertical, mejorando la fuerza relativa del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0140'),
('efa3e786-93fd-5cc0-8149-baa4788c3626', 'Estiramiento de bíceps detrás de la espalda', ARRAY['Lleva un brazo detrás de la espalda con la palma hacia fuera.', 'Con la otra mano, sujeta suavemente la muñeca y estira sin forzar.', 'Mantén la posición unos segundos respirando de forma relajada.', 'Evita tirar con brusquedad o encoger el hombro.']::text[], 'principiante', 'Relaja el bíceps y la parte anterior del hombro tras entrenar tirón o empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1480'),
('0d08fb3b-e36e-556b-9657-dd804ddb8f9e', 'Bicicleta', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas elevadas.', 'Lleva una rodilla hacia el pecho mientras giras el tronco hacia ella.', 'Alterna las piernas con un ritmo constante y controlado.', 'Evita tirar del cuello o arquear la zona lumbar.']::text[], 'intermedio', 'Activa el core y los oblicuos con un movimiento coordinado de piernas y tronco.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2838'),
('93a6cb12-b40b-5cfa-8bdf-1d211e043da4', 'Abdominal bicicleta', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas flexionadas.', 'Eleva los hombros y lleva un codo hacia la rodilla contraria.', 'Alterna los lados sin apoyar la cabeza ni tirar del cuello.', 'Mantén la zona lumbar pegada al suelo y respira con ritmo.']::text[], 'intermedio', 'Fortalece abdominales y oblicuos con un movimiento alterno que exige coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6211'),
('6f993c3d-3137-513e-9440-6e280ee6f74f', 'Caminata en bicicleta reclinada', ARRAY['Siéntate en la bicicleta reclinada y ajusta el asiento a tu longitud de pierna.', 'Pedalea a un ritmo cómodo manteniendo la espalda apoyada.', 'Aumenta la resistencia o la velocidad de forma progresiva.', 'Evita bloquear las rodillas o pedalear con el tronco balanceándose.']::text[], 'principiante', 'Trabaja el sistema cardiovascular con bajo impacto en rodillas y espalda.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2193'),
('089c9ffd-7094-58ae-926a-98c819b30efe', 'Estiramiento de espalda con gran giro', ARRAY['Siéntate con las piernas cruzadas y la espalda recta, con las manos apoyadas en las rodillas.', 'Gira el tronco despacio hacia un lado mientras llevas la mano contraria a la rodilla opuesta.', 'Mantén el giro entre quince y treinta segundos respirando con calma y sin forzar.', 'Vuelve al centro de forma controlada y repite hacia el otro lado.', 'Evita arquear la zona lumbar: gira desde la parte alta de la espalda.']::text[], 'principiante', 'Moviliza la columna y estira oblicuos y dorsales, mejorando la rotación torácica y aliviando la rigidez tras estar sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6540'),
('f154e011-8669-5d5b-b00c-2680f2702a85', 'Bird dog', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Extiende a la vez un brazo y la pierna contraria hasta alinearlos con el tronco.', 'Mantén la posición dos segundos sin dejar caer la cadera ni arquear la espalda.', 'Recoge lentamente y alterna con el otro lado manteniendo la respiración fluida.', 'Evita levantar demasiado la pierna: la clave es la estabilidad, no la altura.']::text[], 'intermedio', 'Fortalece la cadena posterior y el core estabilizando la columna, útil para prevenir dolor lumbar y mejorar el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1241'),
('c28e64cf-ffc0-560c-b547-079fd0e78a00', 'Plancha bird dog', ARRAY['Parte de una plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Levanta un brazo y la pierna contraria sin mover la cadera.', 'Aprieta el abdomen y los glúteos para evitar que la pelvis se balancee.', 'Aguanta dos segundos y cambia de lado manteniendo la respiración.', 'No dejes caer la cadera ni subas el culo: mantén una línea recta.']::text[], 'intermedio', 'Trabaja el abdomen y el core en isométrico mientras exige estabilidad de glúteos y hombros en posición de plancha.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9002'),
('1f471f17-ddc6-5f06-a125-600f0baa7a23', 'Postura del ave del paraíso', ARRAY['Desde la postura de la montaña, cruza un brazo por delante del pecho y engancha el otro por detrás.', 'Flexiona una rodilla y cruza esa pierna por detrás de la otra, apoyando el pie si hace falta.', 'Baja la cadera y endereza la pierna de apoyo sin perder el equilibrio.', 'Mantén varias respiraciones y repite hacia el otro lado.', 'No fuerces el hombro: si no engancha, usa una correa o mantén las manos más cerca.']::text[], 'intermedio', 'Estira isquiotibiales y aductores mientras abre hombros y caderas, mejorando el equilibrio y la movilidad general.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6296'),
('2140ed8c-2bd9-5642-8a5c-ed942b570ab0', 'Estiramiento de barco', ARRAY['Túmbate boca abajo con las manos apoyadas bajo los hombros.', 'Empuja el suelo y eleva el pecho mientras llevas la cadera hacia delante.', 'Mantén el estiramiento entre quince y treinta segundos respirando despacio.', 'Baja con control y relaja los hombros lejos de las orejas.', 'Evita echar la cabeza atrás: mira al frente y no comprimas la lumbar.']::text[], 'principiante', 'Estira el abdomen y los flexores de cadera contrarrestando la postura sentada, y alivia la tensión de la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4279'),
('450aaa04-8139-5b54-a336-407a3f753ba5', 'Postura del bote', ARRAY['Siéntate con las rodillas flexionadas y las plantas de los pies en el suelo.', 'Inclina el tronco hacia atrás manteniendo la espalda recta y eleva los pies.', 'Extiende las piernas formando una V si puedes, con los brazos paralelos al suelo.', 'Respira con calma y mantén entre veinte y treinta segundos.', 'No redondees la espalda: si cuesta, deja las rodillas algo flexionadas.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera en equilibrio, mejorando la postura y la estabilidad del tronco.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0136'),
('6b64eacb-8647-5cc1-8f17-f2ac49186f6a', 'Extensión de cuerpo', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Aprieta los cuádriceps y eleva ligeramente los talones y la cabeza del suelo.', 'Mantén el abdomen activo sin arquear la zona lumbar.', 'Aguanta unos segundos y baja despacio controlando el movimiento.', 'Evita tirar del cuello: la mirada al techo y los hombros relajados.']::text[], 'intermedio', 'Activa cuádriceps y abdomen bajo en un movimiento de extensión que mejora el control postural y la fuerza del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4560'),
('f53c0030-7b99-5977-98f2-56239b6eb262', 'Body-up en banco', ARRAY['Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.', 'Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.', 'Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.', 'Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros usando el propio peso corporal en un banco, ideal para fondos accesibles.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0137'),
('234cc97a-e55e-564f-b9a0-8dc5aedb9028', 'Buenos días con postura b y peso corporal', ARRAY['De pie con los pies a la anchura de las caderas y las manos en la nuca.', 'Lleva la cadera hacia atrás mientras inclinas el tronco con la espalda recta.', 'Baja hasta notar el estiramiento en los isquiotibiales sin redondear la espalda.', 'Sube empujando la cadera hacia delante y apretando los glúteos.', 'Evita flexionar las rodillas en exceso: el movimiento sale de la cadera.']::text[], 'intermedio', 'Fortalece isquiotibiales, glúteos y lumbar mediante una bisagra de cadera que mejora el patrón de flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5672'),
('b3505036-cbf1-5cf9-a938-bd05e0c209c5', 'Sentadilla en banco con peso corporal', ARRAY['Colócate de pie delante de un banco con los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás hasta rozar el banco con los glúteos.', 'Mantén el pecho alto y las rodillas alineadas con los pies.', 'Empuja con los talones para subir apretando los glúteos.', 'No dejes caer el peso de golpe: controla la bajada.']::text[], 'intermedio', 'Refuerza cuádriceps, glúteos e isquiotibiales con una sentadilla guiada por el banco que enseña el patrón correcto.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6541'),
('86ed0883-6fca-571c-98d8-8f3520f51a38', 'Sentadilla al cajón con peso corporal', ARRAY['De pie frente a un cajón o banco, con los pies a la anchura de los hombros.', 'Lleva la cadera atrás y baja hasta sentarte suavemente en el cajón.', 'Mantén las rodillas alineadas y el pecho erguido durante todo el descenso.', 'Levántate empujando con los pies y apretando los glúteos arriba.', 'Evita desplomarte al sentarte: toca el cajón con control.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con una sentadilla al cajón que controla la profundidad y mejora la técnica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10168'),
('8f323727-f059-51b5-8102-db383185d803', 'Sentadilla con salto en profundidad y peso corporal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos.', 'Mientras estás en el aire, junta rápidamente los pies.', 'Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia glúteos y piernas mejorando la potencia y la capacidad de salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3543'),
('5329abf2-97f8-5040-98a4-6442534a5017', 'Sentadilla frontal con talones elevados y peso corporal', ARRAY['Coloca una superficie fina bajo los talones y los pies a la anchura de los hombros.', 'Lleva las manos al pecho o frente para mantener el tronco erguido.', 'Baja la cadera manteniendo el pecho alto y las rodillas hacia delante.', 'Sube empujando con los talones sin perder la verticalidad del tronco.', 'Evita inclinarte hacia delante: el peso debe quedar sobre el mediopié.']::text[], 'intermedio', 'Enfoca el cuádriceps con una sentadilla frontal y talones elevados que mejora la movilidad de tobillo y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9691'),
('903e4be6-32a6-5dde-83a8-221261a3132f', 'Sentadilla con talones elevados y peso corporal', ARRAY['Pon una superficie fina bajo los talones y separa los pies a la anchura de los hombros.', 'Baja la cadera como en una sentadilla manteniendo el pecho erguido.', 'Deja que las rodillas avancen sobre los pies sin levantarlos del suelo.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'No pierdas el equilibrio: si cuesta, sujétate a una pared.']::text[], 'intermedio', 'Incide en el cuádriceps elevando los talones, lo que mejora la movilidad de tobillo y la profundidad de la sentadilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4561'),
('28df7efe-e532-5e21-9c78-9e9ffd576cea', 'Zancada frontal con peso corporal', ARRAY['De pie con los pies juntos y las manos en la cintura.', 'Da un paso al frente y baja la cadera llevando la rodilla trasera hacia el suelo.', 'Mantén el tronco erguido y la rodilla delantera sobre el pie.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se meta hacia dentro: mantenla alineada.']::text[], 'intermedio', 'Fortalece glúteos y piernas con una zancada que mejora el equilibrio y la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4949'),
('4ba0ae44-46de-5bbd-a3e9-12bd962697cb', 'Empuje de cadera de rana', ARRAY['Túmbate boca arriba con las plantas de los pies juntas y las rodillas abiertas hacia los lados.', 'Apoya los talones cerca de los glúteos y mete ligeramente la pelvis para evitar arquear la zona lumbar.', 'Empuja con los talones y aprieta los glúteos hasta subir la cadera, manteniendo las rodillas abiertas.', 'Baja despacio sin apoyar del todo y repite el movimiento con un ritmo controlado.', 'Evita empujar con la zona lumbar: el movimiento debe salir de los glúteos.']::text[], 'intermedio', 'Activa glúteos y aductores con un empuje de cadera que mejora la extensión de cadera y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6464'),
('59d660fc-a78d-50a3-9dd8-a86a36639e9d', 'Bombeo de rana', ARRAY['Túmbate boca arriba con las plantas de los pies juntas y las rodillas hacia fuera.', 'Coloca los talones cerca de los glúteos y apoya bien la espalda en el suelo.', 'Sube y baja la cadera en un rango corto y rápido, apretando los glúteos en cada repetición.', 'Mantén las rodillas abiertas durante todo el movimiento y respira de forma continua.', 'No dejes que la zona lumbar se arquee ni que las rodillas se junten.']::text[], 'intermedio', 'Trabaja el glúteo medio y mayor con un movimiento corto y repetido que mejora la activación y el control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3181'),
('77a522ed-6be8-578c-9ee0-82de69197e74', 'Plancha frontal a perro boca abajo', ARRAY['Colócate en plancha frontal con manos bajo los hombros y cuerpo alineado.', 'Mantén la plancha apretando el abdomen y sin hundir la cadera.', 'Lleva la cadera hacia atrás y arriba hasta la postura de perro boca abajo, estirando la espalda.', 'Vuelve despacio a la plancha y repite el ciclo con una respiración fluida.', 'Evita perder la alineación de la espalda o bloquear los codos con fuerza.']::text[], 'principiante', 'Combina isometría de core con movilidad de hombros y cadena posterior para mejorar el control postural y la flexibilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4500'),
('d45bc99f-0638-5d57-920c-66aeea38ee7a', 'Sentadilla completa con press sobre la cabeza', ARRAY['De pie con los pies a la anchura de los hombros y los brazos a los lados.', 'Baja en sentadilla completa manteniendo el pecho alto y los talones apoyados.', 'Al subir, empuja los brazos por encima de la cabeza hasta estirarlos.', 'Baja los brazos mientras vuelves a la posición inicial y repite con ritmo controlado.', 'Evita arquear la espalda al levantar los brazos: mantén el abdomen activo.']::text[], 'intermedio', 'Ejercicio global que trabaja piernas, hombros y core, mejorando la coordinación y la potencia de todo el cuerpo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4499'),
('191ff68b-8a48-5c12-99a3-fd1884472c11', 'Subida al banco con foco en glúteo', ARRAY['Coloca un pie completo sobre el banco y el otro en el suelo.', 'Inclina ligeramente el tronco hacia delante y empuja con la pierna del banco para subir.', 'Aprieta el glúteo de la pierna que sube y evita impulsarte con la pierna de abajo.', 'Baja despacio controlando el movimiento y repite con la otra pierna.', 'No dejes que la rodilla de apoyo se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece glúteos y piernas con un patrón unilateral que mejora el equilibrio y la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5277'),
('bdf257df-4a64-5f19-a84f-353fbcb07d3c', 'Buenos días con peso corporal', ARRAY['De pie con los pies a la anchura de la cadera y las manos en la nuca o cruzadas al pecho.', 'Con las rodillas ligeramente flexionadas, lleva la cadera hacia atrás inclinando el tronco.', 'Baja hasta notar estiramiento en los isquios sin redondear la espalda.', 'Vuelve a la posición inicial empujando la cadera hacia delante y apretando los glúteos.', 'Evita curvar la zona lumbar: mantén la espalda neutra durante todo el recorrido.']::text[], 'principiante', 'Moviliza la cadena posterior y enseña a bisagra de cadera, mejorando la flexibilidad de isquios y el control lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5555'),
('914294cf-fd2d-51e5-ad1d-b26c086c28a4', 'Sostén de media sentadilla dividida', ARRAY['Da un paso amplio hacia delante y baja la rodilla trasera hacia el suelo.', 'Mantén el tronco erguido y la rodilla delantera alineada con el pie.', 'Sostén la posición sintiendo el estiramiento en la pierna trasera y la cadera.', 'Respira de forma profunda y relajada durante el tiempo indicado.', 'Evita que la rodilla delantera pase por delante de los dedos del pie.']::text[], 'principiante', 'Estira isquios y flexores de cadera mientras fortalece piernas y mejora la estabilidad en posición dividida.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10907'),
('bc88bca2-89bf-5efe-bf69-88e0ba1b9ed2', 'Sentadilla búlgara con talón elevado', ARRAY['Coloca el pie trasero sobre un apoyo elevado y el delantero con el talón sobre una superficie elevada.', 'Baja flexionando la rodilla delantera manteniendo el tronco erguido.', 'Empuja con el talón delantero para subir y aprieta el glúteo al final.', 'Mantén la rodilla delantera alineada con el pie y evita que se vaya hacia dentro.', 'Baja de forma controlada sin dejar caer el peso de golpe.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un patrón unilateral exigente que mejora el equilibrio y la fuerza de piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7551'),
('3eb18fed-3e8c-506a-8c9b-991d71549ebf', 'Sentadilla con talones elevados', ARRAY['Coloca los talones sobre una superficie elevada y los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Baja hasta donde puedas sin perder la espalda neutra.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita levantarte los talones o dejar que las rodillas se junten.']::text[], 'intermedio', 'Enfatiza el cuádriceps y mejora la movilidad de tobillo con una sentadilla que mantiene el tronco más erguido.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7577'),
('c7955bd7-dda7-5e2b-a577-f2c1b459636f', 'Plancha lateral inclinada', ARRAY['Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.', 'Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.', 'Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.', 'Mantén esta posición durante el tiempo deseado.', 'Baja las caderas de nuevo al suelo y repite hacia el otro lado.']::text[], 'intermedio', 'Refuerza el core y los oblicuos en isométrico, mejorando la estabilidad lateral y la resistencia postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3544'),
('5b34ce48-c544-568f-9815-0f989fce9efe', 'Curl jefferson', ARRAY['De pie con los pies separados y las rodillas ligeramente flexionadas.', 'Baja la cabeza y el tronco despacio, redondeando la columna vértebra a vértebra.', 'Deja que los brazos cuelguen y baja hasta donde puedas sin dolor.', 'Sube lentamente deshaciendo el redondeo y apilando la columna.', 'Evita forzar el rango o hacer el movimiento rápido: prioriza el control.']::text[], 'principiante', 'Moviliza la columna y la cadena posterior con un movimiento lento que mejora la flexibilidad y la conciencia corporal.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10752'),
('b149cdfe-1d14-520f-9a21-3b2d3be44d4f', 'De rodillas a de pie', ARRAY['Colócate de rodillas con el tronco erguido y los brazos al frente o cruzados.', 'Empuja la cadera hacia delante y aprieta los glúteos para iniciar la subida.', 'Lleva un pie adelante y empuja para ponerte de pie sin usar las manos.', 'Controla la bajada volviendo a la posición de rodillas.', 'Evita arquear la espalda o impulsarte con las manos.']::text[], 'intermedio', 'Fortalece glúteos y piernas con un patrón funcional que mejora la estabilidad y la fuerza para levantarse del suelo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5152'),
('f3fd2a44-c685-553e-b1fb-862f32c39f89', 'Flexión con remo de rodillas', ARRAY['Colócate de rodillas con las manos en el suelo bajo los hombros.', 'Baja el pecho flexionando los codos hasta acercarte al suelo.', 'Empuja para subir y, al llegar arriba, lleva un codo hacia atrás en remo.', 'Alterna el remo con cada brazo manteniendo el core activo.', 'Evita que la cadera se hunda o que la espalda se arquee.']::text[], 'intermedio', 'Combina empuje y tracción para trabajar pecho, espalda y core, mejorando la fuerza del tren superior de forma global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3906'),
('23cc9190-e31e-5d15-b6c3-a5468cf2f526', 'Sentadilla sissy de rodillas', ARRAY['Colócate de rodillas con el cuerpo erguido y las manos en la cadera o al frente.', 'Inclina el tronco hacia atrás manteniendo la cadera alineada con las rodillas.', 'Baja de forma controlada hasta notar tensión en el cuádriceps.', 'Vuelve a la posición inicial empujando con las piernas.', 'Evita forzar la rodilla o perder la alineación del tronco.']::text[], 'intermedio', 'Aísla el cuádriceps con un movimiento controlado que mejora la fuerza y el control de la rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4722'),
('221571fa-3df2-5548-a25a-9cdba6d19d3d', 'Extensión de tríceps de rodillas', ARRAY['Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.', 'Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.', 'Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.', 'Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps y los hombros con el peso corporal, ideal para progresar hacia fondos completos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1771'),
('21a08378-4790-5600-b1ea-c4d3bc543f31', 'Sentadilla dividida baja con peso corporal', ARRAY['Coloca un pie delante y otro detrás, con el torso erguido y el core activo.', 'Baja la rodilla trasera hacia el suelo controlando el descenso.', 'Empuja con la pierna delantera para volver arriba sin perder la verticalidad.', 'Evita que la rodilla delantera se vaya hacia dentro y mantén la respiración.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una pierna adelantada, mejorando el equilibrio y la estabilidad de rodilla y cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6327'),
('f90225ea-b35b-50cb-ad4c-ee4d081c0332', 'Curl de piernas alterno tumbado', ARRAY['Túmbate boca abajo con las piernas estiradas y el core apretado.', 'Flexiona una rodilla llevando el talón hacia el glúteo sin mover la cadera.', 'Baja despacio hasta estirar la pierna y alterna con la otra.', 'Evita arquear la zona lumbar y controla el tempo en cada repetición.']::text[], 'intermedio', 'Activa los isquiosurales de forma unilateral, útil para corregir desequilibrios y reforzar la parte posterior del muslo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7129'),
('bc4637e3-67ba-5080-9e65-3f3291eaa0eb', 'Curl de piernas tumbado', ARRAY['Túmbate boca abajo con las piernas estiradas y la frente apoyada.', 'Flexiona ambas rodillas llevando los talones hacia los glúteos.', 'Aprieta los isquios arriba y baja de forma controlada.', 'Mantén la cadera pegada al suelo y evita balancearte.']::text[], 'intermedio', 'Trabaja los isquiosurales con el peso corporal, reforzando la flexión de rodilla y la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6108'),
('7384bb21-bb45-561b-9cc7-cd0c2e53d3e8', 'Y boca abajo', ARRAY['Túmbate boca abajo con los brazos formando una Y por encima de la cabeza.', 'Eleva los brazos del suelo juntando las escápulas sin encoger el cuello.', 'Mantén un segundo arriba y baja despacio.', 'Evita levantar la cabeza y no fuerces la zona lumbar.']::text[], 'intermedio', 'Refuerza la espalda alta y los romboides, mejorando la postura y la salud escapular en estudiantes con muchas horas sentados.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5800'),
('18f8ed2e-ab6f-597f-b4cf-1a1ff85a6dbb', 'Rotación externa de hombro tumbado', ARRAY['Túmbate de lado con el codo pegado al cuerpo y flexionado a 90 grados.', 'Rota el antebrazo hacia arriba manteniendo el codo fijo en el costado.', 'Vuelve despacio a la posición inicial sin perder la alineación.', 'Evita despegar el codo del cuerpo y usa un rango cómodo.']::text[], 'principiante', 'Fortalece el manguito rotador y los deltoides posteriores, ayudando a prevenir molestias de hombro en el día a día.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '6754'),
('845024b2-7d16-5a02-9b51-ffc44f003619', 'Muscle-up', ARRAY['Cuélgate de la barra con agarre prono y activa el core.', 'Tira fuerte llevando el pecho hacia la barra en fase de dominada.', 'Gira los codos y empuja para pasar por encima de la barra.', 'Baja de forma controlada evitando caer de golpe.']::text[], 'avanzado', 'Ejercicio avanzado de dominada y fondo que desarrolla dorsal, bíceps y tríceps con gran demanda de fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5194'),
('3ba7807f-1ed1-5507-8dd8-0207bec8626d', 'Zancada con sentadilla estrecha', ARRAY['Da un paso al frente y junta los pies en posición estrecha.', 'Baja en sentadilla manteniendo el torso erguido y las rodillas alineadas.', 'Empuja con el talón para subir y vuelve a la posición inicial.', 'Evita que las rodillas se junten hacia dentro durante el descenso.']::text[], 'intermedio', 'Combina zancada y sentadilla con pies juntos para trabajar cuádriceps y glúteos con mayor control y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10051'),
('662fee75-8235-56e5-ad50-0d948f38f240', 'Sentadilla con pies juntos', ARRAY['Coloca los pies juntos con las puntas ligeramente hacia fuera.', 'Baja la cadera como si te sentaras, manteniendo el pecho alto.', 'Empuja con los talones para volver arriba apretando glúteos.', 'Evita perder la curvatura lumbar y no dejes que las rodillas colapsen.']::text[], 'intermedio', 'Variante estrecha que enfatiza cuádriceps y aductores, mejorando la fuerza y el control en rangos de rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5630'),
('ce166ce3-f0c8-52fc-b4e7-0aa74a377848', 'Zancada frontal con brazos arriba', ARRAY['De pie con los brazos extendidos por encima de la cabeza.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo.', 'Mantén los brazos arriba y el core firme durante todo el movimiento.', 'Empuja con la pierna delantera para volver y alterna lados.']::text[], 'intermedio', 'Añade demanda de hombros y core a la zancada, mejorando la estabilidad global y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9611'),
('a380a585-4f93-51a2-b7b3-7274cc9f251a', 'Sentadilla con brazos arriba', ARRAY['De pie con los brazos extendidos por encima de la cabeza.', 'Baja en sentadilla manteniendo el pecho alto y los brazos activos.', 'Llega hasta donde puedas sin perder la curvatura lumbar.', 'Empuja con los talones para subir y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Exige movilidad de hombros y tobillos mientras fortalece cuádriceps, glúteos y core en una sentadilla completa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4294'),
('f8c25cc2-bf59-5fdb-8b26-92a9fa259221', 'Extensión de tríceps sobre la cabeza con peso corporal', ARRAY['Coloca las manos detrás de la cabeza con los codos apuntando arriba.', 'Extiende los codos empujando las manos hacia el techo.', 'Baja despacio controlando el retorno a la posición inicial.', 'Evita abrir los codos en exceso y mantén el core activo.']::text[], 'intermedio', 'Trabaja el tríceps en estiramiento con el peso corporal, útil para reforzar la extensión del codo y la estabilidad del hombro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4667'),
('4bcfd6db-b346-5bca-a399-1cb22a5c7ef6', 'Paso Patrick', ARRAY['Apoya un pie en el suelo y eleva el otro ligeramente.', 'Flexiona la rodilla de apoyo llevando la cadera atrás con control.', 'Empuja con el pie de apoyo para volver arriba sin perder el equilibrio.', 'Evita que la rodilla se vaya hacia dentro y mantén el torso erguido.']::text[], 'intermedio', 'Ejercicio de control de rodilla que activa cuádriceps y glúteos, útil para readaptación y estabilidad de la pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9601'),
('34fa0bcf-b2d3-5c4f-b640-8a2473d3b965', 'Paso Patrick desde cajón', ARRAY['Coloca un pie sobre el cajón y el otro en el suelo.', 'Baja la cadera flexionando la rodilla de apoyo con control.', 'Empuja con el pie del cajón para volver arriba.', 'Evita que la rodilla se desplace hacia dentro y mantén el equilibrio.']::text[], 'intermedio', 'Variante sobre cajón que aumenta el rango y la demanda de control de rodilla, reforzando cuádriceps y glúteos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9602'),
('be4c84d7-c68b-5ba2-b5a5-1b7d5bf6eb03', 'Paso Peterson desde cajón', ARRAY['Apoya un pie en el cajón con el talón cerca del borde.', 'Baja la cadera llevando la rodilla hacia delante con control.', 'Empuja con el talón para extender la pierna por completo.', 'Evita que la rodilla se vaya hacia dentro y no bloquees de golpe.']::text[], 'intermedio', 'Trabaja el cuádriceps en extensión completa sobre cajón, mejorando el control de rodilla y la fuerza del vasto medial.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9605'),
('35985684-5d0d-578a-877a-585f808e3f00', 'Paso Poliquin', ARRAY['Coloca el pie de apoyo sobre una superficie elevada y el otro en el suelo.', 'Baja la cadera manteniendo la rodilla alineada con el pie.', 'Empuja con el talón para volver arriba con control.', 'Evita que la rodilla colapse hacia dentro y mantén el core activo.']::text[], 'intermedio', 'Variante de control de rodilla que enfatiza el cuádriceps y la estabilidad, útil para readaptación y prevención de molestias.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9603'),
('11b09898-a11f-53f0-b73f-1bf3e6960960', 'Paso poliquin desde cajón', ARRAY['Coloca un pie sobre el cajón con la rodilla alineada con el pie.', 'Empuja con la pierna de arriba para subir el cuerpo sin impulso.', 'Baja despacio controlando la rodilla y sin dejarla caer hacia dentro.', 'Mantén el torso erguido y respira al subir.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un paso elevado que mejora fuerza unilateral y estabilidad de rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9604'),
('4969e4cc-ebbd-5f6d-8ed4-74bac305fcf9', 'Sentadilla goblet con pulsos', ARRAY['Separa los pies a la anchura de los hombros y baja en sentadilla.', 'Mantén la posición baja y haz pulsos cortos sin subir del todo.', 'Aprieta el core y evita que las rodillas se junten.', 'Respira de forma continua y controla el ritmo.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core con pulsos cortos que aumentan el tiempo bajo tensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9702'),
('ff55ee51-2aca-51e6-91f4-40d50bff50cb', 'Sentadilla con pulsos', ARRAY['Baja hasta media sentadilla con la espalda recta.', 'Haz pulsos cortos sin perder la posición de las rodillas.', 'Mantén el peso en los talones y el core firme.', 'Evita rebotar y respira con ritmo constante.']::text[], 'intermedio', 'Activa cuádriceps y glúteos con pulsos en la parte baja que incrementan la resistencia muscular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3535'),
('63a9c892-c8da-5ea4-bb42-9a6a17b7000e', 'Cuarto de sentadilla', ARRAY['Ponte de pie con los pies a la anchura de los hombros.', 'Baja solo un cuarto del recorrido manteniendo el torso erguido.', 'Empuja con los talones para volver arriba sin bloquear las rodillas.', 'Evita inclinarte hacia delante y respira al subir.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un rango parcial útil para aprender el patrón y calentar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10914'),
('2bb3ca13-9983-53c6-b68f-c8067904e72e', 'Zancada trasera', ARRAY['Da un paso largo hacia atrás y baja la rodilla hacia el suelo.', 'Mantén el torso erguido y la rodilla delantera sobre el pie.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla trasera golpee el suelo y respira al subir.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con un paso atrás que mejora el equilibrio y la fuerza unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1581'),
('debd2bc8-f8ba-5f90-ae04-529092fa66e5', 'Zancada hacia atrás con alcance sobre la cabeza', ARRAY['Da un paso atrás y baja en zancada mientras elevas los brazos.', 'Lleva los brazos por encima de la cabeza sin arquear la espalda.', 'Mantén el core activo y la rodilla delantera alineada.', 'Vuelve al centro controlando el movimiento y respira.']::text[], 'intermedio', 'Combina fuerza de piernas y core con un alcance que mejora la movilidad y la estabilidad global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6551'),
('6be59841-85ff-5138-b0b7-f65844def370', 'Remo invertido en cuerda', ARRAY['Sujeta la cuerda y colócate con el cuerpo inclinado hacia atrás.', 'Tira de la cuerda llevando el pecho hacia las manos.', 'Junta las escápulas y evita encoger los hombros.', 'Baja despacio y respira al tirar.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps con un tirón horizontal que mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11715'),
('64e678b2-ac26-517a-90a9-73d78b9a1738', 'Dominada en cuerda', ARRAY['Agarra la cuerda con firmeza y cuelga con los brazos extendidos.', 'Tira del cuerpo hacia arriba llevando el pecho a la cuerda.', 'Evita balancearte y mantén el core activo.', 'Baja controlado y respira al subir.']::text[], 'intermedio', 'Desarrolla dorsales y agarre con un tirón vertical que exige control y fuerza de espalda.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11714'),
('63213a44-d764-526f-afa6-b91fbd6785b9', 'Remo en el marco de una puerta', ARRAY['Agarra el marco de la puerta y inclina el cuerpo hacia atrás.', 'Tira del cuerpo hacia el marco juntando las escápulas.', 'Mantén el cuerpo recto y evita encoger los hombros.', 'Baja despacio y respira al tirar.']::text[], 'intermedio', 'Trabaja la espalda alta y los bíceps con un remo horizontal usando el marco como apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3506'),
('23b82f43-e118-5197-8598-e9c9a2da0b36', 'Encogimientos de hombros', ARRAY['Ponte de pie con los brazos relajados a los lados.', 'Eleva los hombros hacia las orejas sin doblar los codos.', 'Mantén un segundo arriba y baja controlado.', 'Evita girar los hombros y respira al subir.']::text[], 'intermedio', 'Activa los trapecios con un movimiento de elevación que mejora la estabilidad del cuello y hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4361'),
('ecfd3011-7b83-572c-9314-a503871a5a41', 'Rotación externa de hombro tumbado de lado', ARRAY['Túmbate de lado con el codo pegado al cuerpo y a 90 grados.', 'Rota el antebrazo hacia arriba sin separar el codo del torso.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita compensar con la espalda y respira con calma.']::text[], 'principiante', 'Fortalece el manguito rotador y la espalda alta para prevenir lesiones y mejorar la estabilidad del hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10934'),
('e3ba69f9-f2e8-557b-a130-4a33d4fc8b89', 'Peso muerto a una pierna', ARRAY['Apoya una pierna y lleva el peso al pie de apoyo.', 'Inclina el torso hacia delante mientras la otra pierna se eleva.', 'Mantén la espalda recta y el core activo.', 'Vuelve despacio sin perder el equilibrio y respira.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3928'),
('c5324124-8c09-5ffe-90b4-a5a0e74224db', 'Peso muerto a una pierna contra balón', ARRAY['Coloca el pie libre contra el balón y apoya el otro en el suelo.', 'Inclina el torso mientras ruedas el balón hacia atrás.', 'Mantén la espalda recta y el core firme.', 'Vuelve controlando el balón y respira.']::text[], 'intermedio', 'Fortalece isquiotibiales y glúteos con apoyo en balón que mejora el control y la propiocepción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10862'),
('dd085160-f127-541e-994e-466ff6c1eccb', 'Sostén de peso muerto a una pierna', ARRAY['Inclínate sobre una pierna hasta que el torso quede paralelo al suelo.', 'Mantén la posición con la espalda recta y el core activo.', 'Aguanta el tiempo indicado sin perder el equilibrio.', 'Respira de forma constante y evita arquear la espalda.']::text[], 'intermedio', 'Isométrico que activa isquiotibiales y glúteos para mejorar la estabilidad y la resistencia muscular.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10915'),
('00a98c9c-e1a6-5e58-af8b-ccf9d2389729', 'Peso muerto a una pierna con toque de pie', ARRAY['Apoya una pierna y lleva el peso al pie de apoyo.', 'Inclínate y toca el suelo con la mano contraria al pie levantado.', 'Mantén la espalda recta y el core activo.', 'Vuelve despacio sin perder el equilibrio y respira.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos con un toque que añade control y movilidad al patrón unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10916'),
('2ae625b7-61d1-5831-81c9-cf16c7daa83f', 'Puente de glúteo a una pierna', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado, la otra pierna extendida o elevada.', 'Empuja con el talón y sube la cadera hasta alinear rodilla, cadera y hombro.', 'Aprieta el glúteo arriba un segundo y baja controlando sin tocar el suelo.', 'Mantén el core firme y evita arquear la zona lumbar en la subida.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales y mejora la estabilidad de cadera y core sobre una sola pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5671'),
('249d20bf-3e9b-5b6c-bb58-ac185c95a378', 'Peso muerto rumano a una pierna', ARRAY['De pie sobre una pierna con la rodilla ligeramente flexionada y la espalda recta.', 'Lleva la cadera hacia atrás y baja el tronco mientras la otra pierna se eleva estirada.', 'Baja hasta notar el estiramiento en el isquiotibial sin redondear la espalda.', 'Sube empujando la cadera hacia delante y mantén la mirada al frente.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos mientras entrena el equilibrio y el control del core en apoyo unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4971'),
('010ae221-d2ec-59f7-9a41-3664a736f03e', 'Sentadilla a una pierna', ARRAY['De pie sobre una pierna con la otra ligeramente adelantada y los brazos al frente para equilibrarte.', 'Baja llevando la cadera atrás y flexionando la rodilla de apoyo sin que pase de la punta del pie.', 'Desciende todo lo que controles y empuja con el pie para subir.', 'Evita que la rodilla se meta hacia dentro y mantén el core activo.']::text[], 'intermedio', 'Ejercicio unilateral exigente para cuádriceps y glúteos que mejora fuerza, equilibrio y control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7560'),
('fd7b1efb-6bcb-5f52-943d-588bccd84255', 'Sentadilla a una pierna con apoyo', ARRAY['Colócate de pie sobre una pierna junto a una pared o soporte y apóyate ligeramente con una mano.', 'Baja flexionando la rodilla de apoyo mientras la otra pierna se adelanta.', 'Usa el apoyo solo para equilibrarte, no para tirar de ti hacia arriba.', 'Sube empujando con el talón y mantén la rodilla alineada con el pie.']::text[], 'intermedio', 'Versión asistida del ejercicio unilateral que desarrolla cuádriceps y glúteos con mayor seguridad y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7561'),
('02accec8-a21f-51d3-b906-ab3c07069f1e', 'Sentadilla en pared a una pierna', ARRAY['Apoya la espalda en la pared y coloca una pierna adelantada con el pie en el suelo.', 'Desliza la espalda hacia abajo hasta flexionar la rodilla de apoyo unos 90 grados.', 'Mantén la posición con el core firme y respira con normalidad.', 'Evita que la rodilla se desplace hacia dentro y sube controladamente al terminar.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos en isométrico unilateral, mejorando resistencia y estabilidad de rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4072'),
('c7e5c51d-8fdc-593f-b451-b0d55ea77f39', 'Saltos de comba', ARRAY['Sujeta la comba con los codos cerca del cuerpo y las muñecas relajadas.', 'Gira la comba con las muñecas y salta con ambos pies a la vez.', 'Salta bajo, con rodillas ligeramente flexionadas y aterrizaje suave en la punta del pie.', 'Mantén un ritmo constante y evita saltar demasiado alto o con los brazos abiertos.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y la coordinación, con trabajo de gemelos y flexores de cadera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6100'),
('80883069-8c27-5f1f-be0b-d89833026096', 'Sentadilla lenta y explosiva', ARRAY['De pie con los pies a la anchura de los hombros y el core activo.', 'Baja despacio controlando la sentadilla hasta donde puedas sin perder la espalda recta.', 'Sube de forma explosiva extendiendo las caderas y las rodillas.', 'Aterriza o vuelve a bajar con control y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Combina fuerza y potencia en cuádriceps y glúteos, mejorando la capacidad de salto y la explosividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6336'),
('0aba26b8-9acf-5ed0-bbc5-71682e8b07ea', 'Sostén de sentadilla dividida', ARRAY['Coloca una pierna adelantada con la rodilla flexionada y la otra atrás con la rodilla en el suelo.', 'Baja la cadera hasta notar el estiramiento en la parte delantera de la pierna trasera.', 'Mantén el torso erguido y el core activo durante el tiempo indicado.', 'Respira de forma profunda y evita arquear la zona lumbar.']::text[], 'principiante', 'Estiramiento activo que abre flexores de cadera y cuádriceps mientras fortalece glúteos y mejora la estabilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10906'),
('4cc7b78d-72fd-5228-a6a7-c1dfeb4d0a5b', 'Remo en sentadilla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos.', 'Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.', 'Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con tracción horizontal, mejorando la postura y la fuerza de tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3168'),
('e47f2d08-2e63-53c7-a3b0-1bb745c54fee', 'Remo en sentadilla con toalla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda alta y los bíceps usando una toalla como agarre, aumentando la dificultad y el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3167'),
('82b857c3-70a7-5453-b990-d21b93638d72', 'Alrededor del mundo de pie en la pared', ARRAY['Apoya la espalda en la pared con los brazos extendidos y las palmas hacia delante.', 'Dibuja un círculo amplio con los brazos manteniéndolos en contacto con la pared.', 'Mueve despacio y controla el recorrido sin despegar la espalda.', 'Evita encoger los hombros y respira de forma constante.']::text[], 'principiante', 'Movilidad de hombro que activa deltoides y manguito rotador, mejorando el rango y la estabilidad articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4612'),
('ce1e6cdf-26aa-512d-98ae-8033862c83ef', 'Estiramiento de espalda de pie', ARRAY['De pie con los pies a la anchura de las caderas y las rodillas ligeramente flexionadas.', 'Entrelaza las manos y extiende los brazos hacia delante mientras redondeas la espalda.', 'Mantén el estiramiento sin forzar y respira profundamente.', 'Evita bloquear las rodillas o rebotar durante el estiramiento.']::text[], 'principiante', 'Alivia la tensión de la columna y los dorsales, mejorando la movilidad y la relajación de la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4875'),
('c07c39c8-75d6-5c56-bc4d-1c146507ae59', 'Curl de bíceps de pie', ARRAY['De pie con los brazos extendidos y las palmas hacia arriba, agarrando una toalla o barra imaginaria.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los codos.', 'Aprieta el bíceps arriba y baja controlando el movimiento.', 'Evita balancear el torso o encoger los hombros para subir el peso.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos con el propio peso, mejorando la fuerza de tracción y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2922'),
('9a5a2124-6a20-5349-94e8-028114291362', 'Elevación de gemelos de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.', 'Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.', 'Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y la zona del tobillo, mejorando el equilibrio y la estabilidad en la marcha y la carrera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1373'),
('633557da-92b4-52e3-9b29-e4d436bf61a2', 'Remo a un brazo con agarre cerrado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja la espalda alta y el bíceps, ayudando a mejorar la postura y la fuerza de tracción unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3156'),
('2c90ce33-f248-5819-8e49-f88eb225c44e', 'Remo con agarre cerrado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.', 'Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado.', 'Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.', 'Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa la espalda alta y los brazos, útil para reforzar la musculatura de tracción y la postura diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3158'),
('702b3c50-a424-5ece-8c8a-2a467690b249', 'Apertura de pie con peso corporal', ARRAY['Colócate de pie con los pies a la anchura de los hombros y los brazos extendidos al frente.', 'Junta ligeramente las manos y abre los brazos hacia atrás apretando el pecho, sin arquear la espalda.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Mantén el abdomen firme y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Trabaja el pecho y la parte anterior del hombro, útil para activar el torso sin material y mejorar el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5173'),
('4a5f625a-f8a0-5930-bada-351694bd7ca0', 'Giro de oblicuos de pie', ARRAY['Separa los pies a la anchura de los hombros y flexiona un poco las rodillas.', 'Gira el tronco hacia un lado llevando los brazos sueltos, sin forzar la zona lumbar.', 'Vuelve al centro y repite hacia el otro lado con ritmo controlado.', 'Respira de forma fluida y evita mover solo los brazos sin girar el torso.']::text[], 'principiante', 'Moviliza la columna y activa los oblicuos, ayudando a calentar el core y mejorar la rotación del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4855'),
('5d674427-3860-5454-bd9c-19a0b65145b4', 'Remo a un brazo', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido.', 'Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.', 'Junta los omóplatos en la parte superior del movimiento.', 'Baja la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece la espalda alta y el bíceps de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3162'),
('08f4d527-479e-55b0-8311-20176d998609', 'Remo a un brazo con toalla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Tira de la toalla hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja la espalda alta y el agarre con una toalla, mejorando la fuerza de tracción y la resistencia de antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3161'),
('05a5df37-e030-580f-9863-9fc4a226517d', 'Encogimiento de hombros sobre la cabeza', ARRAY['De pie, eleva los brazos por encima de la cabeza con los codos ligeramente flexionados.', 'Sube los hombros hacia las orejas sin doblar los codos ni arquear la espalda.', 'Baja los hombros despacio hasta la posición inicial.', 'Mantén el cuello relajado y evita encogerlo junto con los hombros.']::text[], 'principiante', 'Activa los trapecios superiores y mejora la movilidad del hombro, útil para tomar conciencia de la elevación escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11288'),
('3bcb63aa-20fc-56e7-85e8-d3e86d2e47d2', 'Pulso de elevación de gemelos', ARRAY['Colócate de pie con los pies juntos y el peso sobre las puntas.', 'Eleva los talones y haz pequeños rebotes sin bajar del todo.', 'Mantén el equilibrio con el abdomen firme y la mirada al frente.', 'Evita rebotar de forma brusca o perder el control del tobillo.']::text[], 'intermedio', 'Trabaja los gemelos y el sóleo con pequeños rebotes, mejorando la resistencia y el control del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3534'),
('9752747e-e3eb-5f0b-a5f0-ad96a1033a28', 'Remo de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo.', 'Mantén la espalda recta y el core activado.', 'Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento.', 'Suelta lentamente y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los hombros, contribuyendo a una mejor postura y a la fuerza de tracción general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3166'),
('0e262724-4d57-557c-911d-28b54003cf41', 'Remo de pie con toalla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Tira de la toalla hacia el pecho, juntando los omóplatos.', 'Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa la espalda alta y el agarre usando una toalla, útil para fortalecer la tracción y los antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3165'),
('69247fea-90b2-5ca5-b3f3-65d86551f19e', 'Remo escapular de pie', ARRAY['De pie con los brazos extendidos al frente, junta ligeramente las escápulas sin doblar los codos.', 'Mantén el movimiento pequeño y controlado, sintiendo cómo se acercan los omóplatos.', 'Suelta despacio hasta la posición inicial.', 'Evita encoger los hombros o usar los brazos para tirar.']::text[], 'intermedio', 'Activa la musculatura de la espalda alta y los romboides, mejorando la retracción escapular y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6137'),
('fbfbb07d-0338-5b51-b14c-6f795c61f2fa', 'Rotación escapular externa de pie', ARRAY['De pie, flexiona los codos a 90 grados con los brazos pegados al cuerpo.', 'Gira los antebrazos hacia fuera sin separar los codos del torso.', 'Vuelve despacio a la posición inicial manteniendo el control.', 'Evita arquear la espalda o encoger los hombros durante el giro.']::text[], 'principiante', 'Fortalece el manguito rotador y los deltoides posteriores, ayudando a estabilizar el hombro y prevenir molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8342'),
('7afcbf6a-bdee-5f8c-a3df-ab822e9e444c', 'Sentadilla sissy', ARRAY['De pie, apoya las puntas de los pies y lleva las rodillas hacia delante inclinando el torso atrás.', 'Baja de forma controlada manteniendo el cuerpo alineado y el abdomen firme.', 'Sube empujando con los cuádriceps sin perder el equilibrio.', 'Evita bajar más de lo que controlas o dejar caer la cadera.']::text[], 'intermedio', 'Aísla el cuádriceps y mejora la movilidad de rodilla, útil para reforzar la parte anterior del muslo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4723'),
('7f1841df-ea59-5bdc-87ec-929d360fdba1', 'Press de columna torácica en T', ARRAY['De pie con los brazos en cruz y las palmas hacia delante.', 'Lleva el pecho hacia arriba y presiona suavemente hacia atrás sin arquear la lumbar.', 'Mantén la respiración fluida y el abdomen activo.', 'Evita forzar el cuello o compensar con la zona baja de la espalda.']::text[], 'principiante', 'Moviliza la columna torácica y abre el pecho, mejorando la extensión y la postura en la parte alta de la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8343'),
('4c012907-08f2-5e90-aec7-2b7b89d5951d', 'Subida al cajón', ARRAY['Colócate frente al cajón con un pie apoyado encima.', 'Empuja con la pierna de arriba para subir el cuerpo sin impulsarte con la de abajo.', 'Baja de forma controlada hasta el suelo y cambia de pierna.', 'Evita apoyar toda la rodilla o dejar caer el peso de golpe.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con un patrón funcional, mejorando la fuerza de piernas y el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4579'),
('e079145b-544c-5bff-8720-a79cdddbe197', 'Sentadilla con apoyo', ARRAY['De pie frente a un apoyo, agárrate suavemente con las manos.', 'Baja la cadera hacia atrás flexionando las rodillas, manteniendo el pecho alto.', 'Sube empujando con los talones hasta la posición inicial.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con ayuda para el equilibrio, ideal para aprender el patrón de sentadilla con seguridad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6600'),
('ac67cb21-2455-56ce-8fb7-d7383899a878', 'Swing con peso corporal', ARRAY['Colócate de pie con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.', 'Lleva la cadera hacia atrás mientras bajas el tronco con la espalda recta y los brazos relajados.', 'Empuja la cadera hacia delante de forma explosiva para volver a la posición erguida.', 'Exhala al extender la cadera e inhala al bajarla, manteniendo el abdomen firme.', 'Evita redondear la espalda o usar los brazos para impulsarte.']::text[], 'intermedio', 'Activa glúteos e isquios con un gesto explosivo de cadera que mejora la potencia y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5864'),
('576800b4-bf71-57b9-9804-61dcb5837d25', 'Elevación de tibial con apoyo en pared', ARRAY['Apóyate con las manos en la pared y separa los pies unos centímetros de ella.', 'Mantén los talones en el suelo y eleva las puntas de los pies lo máximo posible.', 'Baja las puntas de forma controlada hasta el suelo sin dejar caer el peso.', 'Exhala al subir e inhala al bajar, con un ritmo lento y constante.', 'Evita balancear el cuerpo o despegar los talones del suelo.']::text[], 'intermedio', 'Fortalece la parte delantera de la espinilla y el tobillo, mejorando la estabilidad y previniendo molestias en la carrera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8536'),
('35b3b9de-c986-546b-913e-1acfe684cece', 'Extensión de tríceps en plancha', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Flexiona los codos hacia atrás manteniéndolos pegados al torso hasta apoyar los antebrazos.', 'Empuja con las palmas para volver a extender los codos y recuperar la plancha.', 'Exhala al empujar e inhala al bajar, sin perder la línea del cuerpo.', 'Evita que la cadera suba o baje y no abras los codos hacia los lados.']::text[], 'intermedio', 'Trabaja el tríceps y los hombros desde una posición isométrica que también exige estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6423'),
('370a8aca-49bc-51c6-b326-a8ec75225870', 'Zancada baja caminando', ARRAY['Da un paso largo hacia delante y baja la rodilla trasera hasta acercarla al suelo.', 'Mantén el tronco erguido y la rodilla delantera alineada con el pie.', 'Empuja con la pierna delantera para avanzar y repetir con la otra pierna.', 'Exhala al bajar e inhala al empujar, con un ritmo controlado.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con un paso amplio que también mejora el equilibrio y la movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9700'),
('c999a5c5-cebe-5ba5-ae7f-2623b0b4fb66', 'Sentadilla con leñador', ARRAY['De pie con los pies a la anchura de los hombros, junta las manos delante del pecho.', 'Baja en sentadilla mientras llevas las manos hacia un lado de la cadera.', 'Al subir, rota el tronco y lleva las manos en diagonal hacia el lado contrario.', 'Exhala al rotar e inhala al bajar, manteniendo el abdomen firme.', 'Evita rotar solo con los brazos o perder la alineación de las rodillas.']::text[], 'intermedio', 'Combina sentadilla y rotación para trabajar abdomen, oblicuos y glúteos, mejorando la coordinación y la fuerza funcional.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5882'),
('1c9bf23b-59c8-5298-b4af-dca743f3231f', 'Boomerang', ARRAY['Siéntate con las piernas estiradas y el tronco erguido, brazos a los lados.', 'Inclina el tronco ligeramente hacia atrás y eleva las piernas manteniendo la espalda recta.', 'Cruza los brazos delante y baja las piernas y el tronco de forma controlada.', 'Vuelve a subir lentamente y exhala durante el esfuerzo.', 'Evita redondear la espalda o usar impulso para subir.']::text[], 'intermedio', 'Ejercicio de pilates que fortalece el abdomen y la zona lumbar mientras mejora el control postural y la flexibilidad.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2876'),
('91a995c8-da43-55d5-aacb-c1808d0c40b3', 'Sentadilla de patinador con contrapeso en bosu', ARRAY['Colócate sobre el bosu apoyando una pierna y lleva la otra hacia atrás.', 'Extiende los brazos al frente como contrapeso para mantener el equilibrio.', 'Baja flexionando la rodilla de apoyo con el tronco ligeramente inclinado.', 'Empuja con el pie para subir y exhala durante el ascenso.', 'Evita que la rodilla se vaya hacia dentro o perder el control del bosu.']::text[], 'intermedio', 'Mejora la fuerza unilateral de cuádriceps y glúteos y el equilibrio sobre superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8479'),
('8b317139-e99d-5818-8b5f-0415f036c7be', 'Sentadilla a una pierna en bosu', ARRAY['Súbete al bosu y apoya todo el peso sobre una pierna con la otra ligeramente adelantada.', 'Extiende los brazos al frente y mantén la mirada al horizonte.', 'Baja despacio flexionando la rodilla de apoyo sin perder el equilibrio.', 'Empuja para subir y exhala durante el ascenso.', 'Evita bajar demasiado rápido o dejar que la rodilla se desplace hacia dentro.']::text[], 'intermedio', 'Exige fuerza y control unilateral de cuádriceps, glúteos y core sobre una base inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10869'),
('7b6103a6-3307-5743-9d58-264cb8f928d0', 'Sentadilla en bosu', ARRAY['Colócate de pie sobre el bosu con los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás flexionando rodillas y caderas con el pecho arriba.', 'Empuja con los pies para volver a la posición inicial de forma controlada.', 'Exhala al subir e inhala al bajar, manteniendo el abdomen firme.', 'Evita que las rodillas se junten o que el bosu se mueva bruscamente.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core mientras el bosu añade un reto de equilibrio y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10868'),
('dcd3db54-9903-561a-a97e-46d0004a38df', 'Curl martillo con botella', ARRAY['De pie con una botella en cada mano y las palmas mirándose entre sí.', 'Mantén los codos pegados al torso y flexiona hasta llevar las botellas a los hombros.', 'Baja de forma controlada sin balancear el cuerpo.', 'Exhala al subir e inhala al bajar, con un ritmo constante.', 'Evita mover los hombros o usar impulso de la espalda.']::text[], 'intermedio', 'Trabaja bíceps y antebrazo con un agarre neutro que también fortalece la musculatura del braquial.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3554'),
('ea945c71-ef57-570b-9ccd-79358fbaab81', 'Curl de bíceps alternado con botella', ARRAY['De pie con una botella en cada mano y las palmas hacia delante.', 'Flexiona un codo llevando la botella al hombro mientras el otro brazo queda abajo.', 'Baja lentamente y repite con el brazo contrario.', 'Exhala al subir e inhala al bajar, sin mover los codos del torso.', 'Evita balancear el tronco o girar los hombros para subir la botella.']::text[], 'intermedio', 'Fortalece el bíceps y el antebrazo trabajando cada brazo por separado para mejorar el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6068'),
('a64304f8-9096-5f28-b7bd-62a1a66a55e9', 'Elevación frontal alternada con botella', ARRAY['De pie con una botella en cada mano y los brazos extendidos delante de los muslos.', 'Eleva un brazo al frente hasta la altura del hombro con el codo ligeramente flexionado.', 'Baja de forma controlada y repite con el otro brazo.', 'Exhala al subir e inhala al bajar, manteniendo el abdomen firme.', 'Evita arquear la espalda o subir el brazo por encima del hombro.']::text[], 'intermedio', 'Trabaja el deltoides anterior y la parte alta del pecho, mejorando la fuerza y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6075'),
('c968a557-671a-55ec-aa48-74083f820c31', 'Curl martillo alternado con botella', ARRAY['De pie con una botella en cada mano y las palmas mirándose entre sí.', 'Flexiona un codo llevando la botella al hombro sin mover el brazo contrario.', 'Baja lentamente y repite con el otro brazo.', 'Exhala al subir e inhala al bajar, con los codos pegados al torso.', 'Evita balancear el cuerpo o encoger los hombros.']::text[], 'intermedio', 'Fortalece bíceps y antebrazo con agarre neutro, trabajando cada brazo de forma independiente.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6069'),
('2faa3957-1066-533c-aa3f-049f743cbbec', 'Remo a la axila con botella', ARRAY['Inclina el tronco hacia delante con la espalda recta y una botella en cada mano.', 'Tira de los codos hacia atrás y arriba, llevando las botellas hacia las axilas.', 'Aprieta los omóplatos y baja de forma controlada.', 'Exhala al tirar e inhala al bajar, sin redondear la espalda.', 'Evita encoger los hombros hacia las orejas o usar impulso.']::text[], 'intermedio', 'Fortalece deltoides posterior, trapecio y espalda alta, mejorando la postura y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6072'),
('8c09fc98-0735-519e-83bb-00bef7866815', 'Apertura invertida inclinado con botella', ARRAY['Inclina el tronco hacia delante con la espalda recta y una botella en cada mano.', 'Con los codos ligeramente flexionados, abre los brazos hacia los lados hasta la altura de los hombros.', 'Aprieta los omóplatos y baja lentamente.', 'Exhala al abrir e inhala al bajar, manteniendo el cuello relajado.', 'Evita subir los hombros o arquear la espalda.']::text[], 'intermedio', 'Trabaja deltoides posterior y espalda alta, corrigiendo la postura y equilibrando la fuerza del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6061'),
('c5544c39-4177-542d-a391-7f390da6edb9', 'Remo inclinado con botella', ARRAY['Colócate con el torso inclinado hacia delante y la espalda recta, sujetando la botella con una mano.', 'Tira de la botella hacia la cadera llevando el codo pegado al cuerpo.', 'Aprieta la escápula arriba y baja controlando el movimiento.', 'Evita redondear la espalda o tirar con impulso del tronco.']::text[], 'intermedio', 'Fortalece la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción para el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6059'),
('2f335715-deb7-5aab-9217-7b0007c164cb', 'Curl concentrado con botella', ARRAY['Siéntate y apoya el codo en la cara interna del muslo con la botella en la mano.', 'Sube la botella flexionando el codo sin mover el brazo del apoyo.', 'Baja despacio hasta estirar casi del todo y repite.', 'No balancees el tronco ni sueltes el codo del muslo.']::text[], 'intermedio', 'Aísla el bíceps para ganar volumen y fuerza en el brazo, con apoyo que evita compensaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6063'),
('a1712782-8881-5eea-9fc9-e32b8ccb61ad', 'Peso muerto con botella', ARRAY['Con la botella delante de los muslos, separa los pies a la anchura de las caderas.', 'Lleva la cadera atrás bajando la botella con la espalda recta.', 'Empuja con los talones y extiende la cadera para subir apretando glúteos.', 'Evita curvar la espalda o bloquear las rodillas al final.']::text[], 'intermedio', 'Trabaja glúteos e isquios en cadena posterior, clave para levantar peso con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5988'),
('c9b27c72-0d5b-5f1a-baca-2d46b5c242fe', 'Zancada frontal con botella', ARRAY['De pie con la botella a la altura del pecho, da un paso largo hacia delante.', 'Baja flexionando ambas rodillas hasta que la trasera casi toque el suelo.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el tronco erguido y evita que la rodilla delantera pase mucho del pie.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos mejorando el equilibrio y la estabilidad de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6047'),
('f0c10325-4384-52a0-bb38-f6e9bce22ab0', 'Abdominal de rana con botella', ARRAY['Túmbate boca arriba con las plantas de los pies juntas y las rodillas abiertas.', 'Sujeta la botella sobre el pecho y eleva ligeramente los hombros del suelo.', 'Acerca las costillas a la pelvis contrayendo el abdomen y baja despacio.', 'No tires del cuello ni uses impulso con los brazos.']::text[], 'intermedio', 'Activa el abdomen bajo y los flexores de cadera con un rango corto y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6053'),
('1ad1c142-43fd-5b15-b6bc-e330aada7379', 'Sentadilla frontal con botella', ARRAY['Sujeta la botella a la altura del pecho con los codos altos y los pies a la anchura de hombros.', 'Baja la cadera flexionando las rodillas manteniendo el pecho erguido.', 'Sube empujando con los talones y aprieta glúteos arriba.', 'Evita inclinarte hacia delante o dejar caer los codos.']::text[], 'intermedio', 'Potencia cuádriceps y core al mantener la carga delante, exigiendo control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6044'),
('437f24f9-4c5c-5236-b26b-31461b99a0f9', 'Puente de glúteos con botella', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la botella sobre la cadera.', 'Empuja con los talones elevando la pelvis hasta alinear cadera y hombros.', 'Aprieta los glúteos arriba y baja controlando el movimiento.', 'No arquees la zona lumbar ni empujes con las puntas de los pies.']::text[], 'intermedio', 'Activa glúteos e isquios sin cargar la espalda, ideal para fortalecer la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6050'),
('1c19f064-b229-5bbe-83ba-50613bbb041f', 'Remo gorila con botella', ARRAY['Con los pies a la anchura de hombros, inclina el torso y sujeta la botella con ambas manos.', 'Tira de la botella hacia el abdomen llevando los codos atrás.', 'Junta las escápulas arriba y baja controlando el movimiento.', 'Mantén la espalda recta y evita tirar con la zona lumbar.']::text[], 'intermedio', 'Fortalece la espalda y los dorsales con un remo bilateral que mejora la tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7276'),
('80a14fdf-316f-54e5-b827-1255fc51426b', 'Patada de tríceps con botella', ARRAY['Inclina el torso hacia delante con la espalda recta y el codo pegado al costado.', 'Extiende el brazo hacia atrás hasta estirar del todo, sujetando la botella.', 'Vuelve despacio sin mover el codo de su sitio.', 'Evita balancear el tronco o subir el hombro al extender.']::text[], 'intermedio', 'Aísla el tríceps para tonificar la parte posterior del brazo y mejorar la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6065'),
('71c26ae5-c6c4-57b1-90c2-9199741a58ac', 'Sentadilla de rodillas con botella', ARRAY['Arrodíllate con la botella sujeta delante del pecho y el torso erguido.', 'Siéntate hacia atrás llevando la cadera a los talones manteniendo el control.', 'Sube apretando glúteos y extendiendo la cadera.', 'No dejes caer el peso de golpe ni redondees la espalda.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps desde una posición estable, útil para aprender el patrón de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6051'),
('c2b2d232-8476-5ade-993d-885d9320fa6f', 'Press de pecho acostado con botella', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la botella sobre el pecho.', 'Empuja la botella hacia arriba extendiendo los brazos sin bloquear del todo.', 'Baja controlando hasta la altura del pecho y repite.', 'Evita arquear la lumbar o abrir los codos en exceso.']::text[], 'intermedio', 'Fortalece pectorales y tríceps con un empuje horizontal que mejora la fuerza del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6057'),
('81f8c384-729a-5eb0-ab2a-fdee4739eea8', 'Abdominal sobre la cabeza con botella', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la botella sobre la cabeza.', 'Eleva los hombros del suelo acercando las costillas a la pelvis.', 'Baja despacio manteniendo la botella estable arriba.', 'No tires del cuello ni dejes caer los brazos hacia atrás.']::text[], 'intermedio', 'Refuerza el abdomen y los oblicuos con la carga elevada, aumentando la exigencia del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6052'),
('fef83c97-a51c-5d70-82d4-edd559e41402', 'Extensión de tríceps sobre la cabeza con botella', ARRAY['De pie o sentado, sujeta la botella con ambas manos por encima de la cabeza.', 'Baja la botella detrás de la cabeza flexionando solo los codos.', 'Extiende los brazos para volver arriba apretando el tríceps.', 'Mantén los codos cerca de la cabeza y evita arquear la espalda.']::text[], 'intermedio', 'Trabaja el tríceps en estiramiento, mejorando la fuerza y el tono del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6067'),
('be61ac8f-6599-5eb9-bf38-3835f92f8f3e', 'Pullover con botella', ARRAY['Túmbate boca arriba con la botella sujeta con ambas manos sobre el pecho.', 'Lleva la botella hacia atrás por encima de la cabeza con los brazos casi estirados.', 'Vuelve despacio a la posición inicial sin bloquear los codos.', 'Evita arquear la lumbar o bajar demasiado si notas tensión en el hombro.']::text[], 'intermedio', 'Estira y fortalece dorsales y pectorales, mejorando la movilidad del hombro y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6060'),
('fa149602-f930-51c3-a4f7-efc7778cbe10', 'Zancada hacia atrás con botella', ARRAY['De pie con la botella a la altura del pecho, da un paso largo hacia atrás.', 'Baja flexionando ambas rodillas hasta que la trasera casi toque el suelo.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el tronco erguido y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con un paso atrás que reduce la carga en la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6048'),
('bb6bc07a-d3a5-5166-ac54-518c297bc60e', 'Curl concentrado con agarre inverso y botella', ARRAY['Siéntate y apoya el codo en la cara interna del muslo con la botella sujeta en agarre inverso.', 'Sube la botella flexionando solo el codo, manteniendo la muñeca firme y neutra.', 'Baja despacio controlando el movimiento durante dos o tres segundos.', 'Evita balancear el tronco o usar el hombro para ayudar a subir el peso.']::text[], 'intermedio', 'Aísla los antebrazos y flexores de la muñeca para mejorar el agarre y la fuerza de prensión en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6064'),
('9fbe3713-064f-51f1-89fb-53b97981c0cf', 'Peso muerto rumano con botella', ARRAY['De pie con los pies a la anchura de las caderas y la botella frente a los muslos.', 'Empuja la cadera hacia atrás bajando la botella pegada a las piernas con la espalda recta.', 'Baja hasta notar estiramiento en los isquiotibiales sin redondear la zona lumbar.', 'Sube apretando glúteos y exhala al final del recorrido.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos, mejorando la bisagra de cadera y la salud lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6041'),
('ad28a968-a69d-53c7-a599-36ff995b828f', 'Flexión lateral con botella', ARRAY['De pie con la botella en una mano y el brazo relajado junto al cuerpo.', 'Inclina el tronco hacia el lado de la botella sin rotar ni flexionar la cadera.', 'Vuelve despacio al centro apretando el oblicuo del lado contrario.', 'Evita tirar del cuello o inclinarte hacia delante durante el recorrido.']::text[], 'intermedio', 'Trabaja los oblicuos y la estabilidad del tronco para mejorar el control postural en movimientos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6054'),
('56d8bb94-b1aa-55a1-b611-6ddb29939717', 'Peso muerto rumano a una pierna con botella', ARRAY['De pie sobre una pierna con la botella en la mano contraria al pie de apoyo.', 'Lleva la cadera atrás y baja la botella mientras la otra pierna se eleva estirada.', 'Mantén la espalda recta y la cadera nivelada durante todo el descenso.', 'Sube apretando el glúteo de la pierna de apoyo sin perder el equilibrio.']::text[], 'intermedio', 'Desarrolla fuerza unilateral en isquiotibiales y glúteos, además de equilibrio y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6042'),
('4009da5c-a7df-5b7f-a5c7-0a1090010d68', 'Sentadilla dividida con botella', ARRAY['Coloca un pie delante y otro detrás en posición cómoda con la botella pegada al pecho.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el talón delantero para volver arriba sin bloquear la rodilla.', 'Evita que la rodilla delantera se vaya hacia dentro durante el descenso.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6046'),
('446eb000-814b-5f4b-9be7-5346546874c7', 'Ondas alternas en sentadilla con botella', ARRAY['De pie con la botella sujeta con ambas manos frente al pecho.', 'Baja en sentadilla mientras llevas la botella a un lado con un movimiento fluido.', 'Sube extendiendo las piernas y alterna el lado de la botella en cada repetición.', 'Mantén el core firme y evita que las rodillas se junten al bajar.']::text[], 'intermedio', 'Combina fuerza de piernas con coordinación y potencia de hombros en un movimiento dinámico y global.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '6056'),
('79b9e346-be21-55f2-927a-733b300863ac', 'Peso muerto con piernas rectas y botella', ARRAY['De pie con las piernas casi estiradas y la botella frente a los muslos.', 'Baja la botella deslizándola por las piernas con la espalda recta y el pecho arriba.', 'Detente cuando notes tensión en la parte posterior del muslo.', 'Sube apretando glúteos sin hiperextender la espalda al final.']::text[], 'intermedio', 'Estira y fortalece los isquiotibiales con una bisagra de cadera controlada, útil para prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6049'),
('cc68aa69-a07d-59a6-9857-8050331330ec', 'Sentadilla sumo con botella', ARRAY['Separa los pies más allá de la anchura de los hombros con las puntas hacia fuera.', 'Sujeta la botella con ambas manos delante del pecho.', 'Baja la cadera entre las piernas manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Empuja con los talones para subir y aprieta los glúteos arriba.']::text[], 'intermedio', 'Activa glúteos y aductores con una sentadilla amplia que mejora la fuerza de la cadera y las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6045'),
('b5a4a749-b945-53ae-a771-e92ad8da8ef5', 'Balanceo con botella', ARRAY['De pie con los pies a la anchura de los hombros y la botella sujeta con ambas manos.', 'Lleva la cadera atrás y balancea la botella entre las piernas con la espalda recta.', 'Extiende la cadera con fuerza para llevar la botella hasta la altura del pecho.', 'Deja que el peso baje de nuevo controlando el movimiento sin redondear la espalda.']::text[], 'intermedio', 'Genera potencia de cadera y glúteos con un movimiento balístico que también activa el core y los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6043'),
('858ae3fa-be52-513f-9c23-9900d41bd25e', 'Patada de tríceps a dos brazos con botella', ARRAY['Inclina el tronco hacia delante con la espalda recta y la botella sujeta con ambas manos.', 'Pega los codos al cuerpo y extiende los brazos hacia atrás hasta estirarlos.', 'Aprieta el tríceps arriba un instante y baja despacio.', 'Evita mover los codos o arquear la espalda durante el recorrido.']::text[], 'intermedio', 'Aísla el tríceps para tonificar la parte posterior del brazo y mejorar la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6066'),
('3cf1f4fb-e4e2-5515-b96b-721836c7e8f9', 'Remo al mentón con botella', ARRAY['De pie con la botella sujeta con ambas manos frente a los muslos.', 'Sube la botella pegada al cuerpo hasta la altura del pecho guiando con los codos.', 'Baja despacio sin dejar caer el peso de golpe.', 'Evita encoger los hombros o subir la botella por encima de la barbilla.']::text[], 'intermedio', 'Trabaja deltoides y trapecios para mejorar la fuerza de hombros y la postura en la parte superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6071'),
('d01f5352-88b6-5837-8d14-fec4ee0cc6fc', 'Bottoms-up', ARRAY['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.', 'Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.', 'Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos con un ejercicio de calistenia que exige control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0138'),
('d6cc8055-1ec0-51ba-ad84-8c2584bfe8ad', 'Postura del arco', ARRAY['Túmbate boca abajo con los brazos estirados junto al cuerpo y las piernas juntas.', 'Flexiona las rodillas y agarra los tobillos por detrás.', 'Eleva el pecho y las piernas del suelo arqueando la espalda de forma progresiva.', 'Respira con normalidad y evita forzar el cuello mirando al frente.']::text[], 'intermedio', 'Estira el pecho y los flexores de cadera mientras fortalece la espalda y los cuádriceps en extensión.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1481'),
('e2cbb49c-fda2-5289-b8a4-61aeaaa7f402', 'Dominadas asistidas con cajón', ARRAY['Coloca el cajón bajo la barra y apoya un pie para regular la ayuda.', 'Agarra la barra con las palmas hacia delante y los brazos estirados.', 'Tira del cuerpo hacia arriba ayudándote lo justo con la pierna del cajón.', 'Baja controlando hasta estirar los brazos sin soltar la barra de golpe.']::text[], 'intermedio', 'Permite progresar hacia la dominada trabajando dorsales y bíceps con ayuda del pie en el cajón.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9511'),
('96f5164e-92c6-5129-ab93-ae46c44b3ef0', 'Caída desde cajón con aterrizaje a dos pies', ARRAY['Súbete al cajón con los pies a la anchura de las caderas.', 'Da un paso al vacío y cae buscando aterrizar con ambos pies a la vez.', 'Flexiona rodillas y cadera al tocar el suelo para amortiguar el impacto.', 'Mantén las rodillas alineadas con los pies y evita aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Mejora la potencia y la absorción de impactos en piernas, entrenando la estabilidad al aterrizar.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9068'),
('e5f3349d-4a75-5abc-b2b1-415481758897', 'Salto en profundidad desde cajón', ARRAY['Sube al cajón y colócate en el borde con los pies a la anchura de las caderas.', 'Da un paso al vacío y cae con las rodillas ligeramente flexionadas y el torso erguido.', 'Amortigua la caída y salta de inmediato hacia arriba lo más alto posible.', 'Aterriza suave con las rodillas alineadas con los pies y exhala al saltar.', 'Evita caer con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Trabaja la potencia de cuádriceps y glúteos con un salto reactivo tras caer del cajón, mejorando la explosividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9606'),
('7d88db41-93ae-519b-a31f-4d533b424341', 'Bajada de cajón con estabilización a una pierna', ARRAY['Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde.', 'Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo.', 'Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio.', 'Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial.', 'Repite el ejercicio con la otra pierna.']::text[], 'intermedio', 'Mejora el control y la fuerza de gemelos y cuádriceps al aterrizar y mantener el equilibrio sobre una sola pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1374'),
('9248b4e2-6eb4-5684-8079-e2b05873264f', 'Salto al cajón con balanceo de brazos', ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas y los brazos atrás.', 'Flexiona rodillas y caderas mientras llevas los brazos hacia atrás para cargar el salto.', 'Balancea los brazos hacia delante y salta impulsándote con fuerza para subir al cajón.', 'Aterriza con ambos pies planos y las rodillas flexionadas, absorbiendo el impacto.', 'Evita saltar con el cajón demasiado alto o aterrizar con las piernas estiradas.']::text[], 'intermedio', 'Desarrolla la potencia de piernas y la coordinación del tren superior al impulsarse con los brazos hacia el cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10738'),
('2b5f81fe-008f-5692-95e1-d5cec154f6d9', 'Dominada asistida con cajón a una pierna', ARRAY['Coloca el cajón bajo la barra y apoya un pie en él con la rodilla flexionada.', 'Agarra la barra con las palmas hacia delante y los brazos extendidos.', 'Tira de los codos hacia abajo y hacia atrás ayudándote con la pierna del cajón.', 'Sube hasta que la barbilla pase la barra y baja controlando el descenso.', 'Evita balancearte o empujar en exceso con la pierna de apoyo.']::text[], 'intermedio', 'Refuerza dorsales y bíceps permitiendo subir con ayuda de una pierna apoyada en el cajón.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9512'),
('85c986f8-5195-52e9-9dce-552e326a8349', 'Shuffle de boxeador', ARRAY['Adopta una postura atlética con las rodillas ligeramente flexionadas y el peso en la parte delantera.', 'Desplázate dando pasos cortos y rápidos alternando los pies sin cruzar las piernas.', 'Mantén los brazos en guardia y el torso erguido durante todo el movimiento.', 'Respira de forma constante y mantén un ritmo ágil sin rigidez.', 'Evita dar zancadas largas o arrastrar los pies.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y mejora la coordinación y agilidad de piernas con un desplazamiento rápido y ligero.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3532'),
('854cb70f-ccfe-509d-8f7e-f60f07581089', 'Bloqueo de boxeo', ARRAY['Colócate en guardia con los puños a la altura de las mejillas y los codos pegados al torso.', 'Sube ligeramente los hombros y aprieta los puños para activar la defensa.', 'Mantén la posición con la barbilla baja y la mirada al frente.', 'Respira con normalidad sin relajar los brazos durante el tiempo indicado.', 'Evita separar los codos del cuerpo o bajar las manos.']::text[], 'intermedio', 'Fortalece hombros y antebrazos al mantener la guardia alta para proteger la cara de los golpes.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4581'),
('f81e8335-7fd2-5055-8af3-34b97d28de12', 'Jab de boxeo', ARRAY['Ponte en guardia con el pie adelantado y las manos altas.', 'Extiende el brazo delantero hacia delante girando ligeramente el puño.', 'Recoge la mano rápidamente a la guardia mientras exhalas en el golpe.', 'Mantén la barbilla baja y el hombro relajado al extender.', 'Evita bajar la mano contraria o bloquear el codo por completo.']::text[], 'intermedio', 'Entrena la velocidad y extensión del hombro con el golpe recto de la mano adelantada.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2272'),
('93fb3603-d698-5076-843e-af6a7391d703', 'Uppercut izquierdo de boxeo', ARRAY['Adopta la guardia con las rodillas ligeramente flexionadas.', 'Baja ligeramente el hombro izquierdo y flexiona el codo para cargar el golpe.', 'Impulsa el puño hacia arriba en arco corto girando el torso.', 'Exhala al golpear y vuelve rápido a la guardia.', 'Evita echar el brazo atrás o golpear solo con el brazo sin girar el tronco.']::text[], 'intermedio', 'Trabaja la potencia ascendente de hombros y bíceps con el golpe corto desde abajo.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2275'),
('7df14481-a697-5de9-84eb-859b10eccd56', 'Cruzado derecho de boxeo', ARRAY['Colócate en guardia con el pie derecho atrás y las manos altas.', 'Gira la cadera y el pie trasero mientras extiendes el brazo derecho hacia delante.', 'Exhala al impactar y recoge la mano a la guardia.', 'Mantén la barbilla baja y la mirada al frente.', 'Evita dejar caer la mano delantera o extender el codo sin girar la cadera.']::text[], 'intermedio', 'Desarrolla la potencia del hombro y el tríceps con el golpe recto de la mano trasera.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2273'),
('4c9a37dc-b151-535d-9f88-4b35c4e6f979', 'Gancho derecho de boxeo', ARRAY['Ponte en guardia con los codos altos y las manos junto a la cara.', 'Gira el torso y la cadera hacia la izquierda llevando el codo derecho en arco.', 'Impacta con el puño horizontal y exhala durante el golpe.', 'Vuelve rápidamente a la guardia manteniendo el equilibrio.', 'Evita abrir demasiado el brazo o golpear sin rotar el tronco.']::text[], 'intermedio', 'Fortalece hombros y oblicuos con el golpe lateral en arco que implica rotación del tronco.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '3171'),
('d93d6aa3-489a-5afe-a50e-542429942167', 'Uppercut derecho de boxeo', ARRAY['Adopta la guardia con el peso repartido y las rodillas flexionadas.', 'Flexiona el codo derecho y baja ligeramente el hombro para cargar.', 'Impulsa el puño hacia arriba girando la cadera y el torso.', 'Exhala al golpear y regresa a la guardia con control.', 'Evita golpear con el brazo estirado o perder la posición de los pies.']::text[], 'intermedio', 'Refuerza hombros y bíceps con el golpe ascendente de la mano trasera desde la guardia.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2274'),
('be2bbed3-206e-5e59-92d1-e4986b74f3d3', 'Puente sobre rodillas', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva la cadera hasta formar una línea recta entre hombros, cadera y rodillas.', 'Aprieta los glúteos y el abdomen manteniendo la posición.', 'Respira de forma constante sin dejar caer la cadera.', 'Evita arquear la zona lumbar o empujar con las puntas de los pies.']::text[], 'intermedio', 'Activa el core y los glúteos manteniendo la cadera elevada en isométrico para estabilizar la zona lumbar.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0142'),
('e1bceb6a-b308-5dab-a872-9849999680c4', 'Puente con escaladores cruzados', ARRAY['Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo.', 'Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho.', 'Continúa alternando los lados, moviéndote a un ritmo controlado.', 'Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo.', 'Mantén un patrón de respiración constante durante todo el ejercicio.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina la activación de glúteos y core con el trabajo dinámico de escaladores cruzados.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2466'),
('d2c1fd75-e68a-5f7f-89db-bb70f48a2afd', 'Abducción de cadera en puente', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva la cadera hasta alinear hombros, cadera y rodillas.', 'Abre las rodillas hacia los lados sin mover los pies ni bajar la cadera.', 'Junta las rodillas de nuevo controlando el movimiento y respirando.', 'Evita dejar caer la cadera o abrir las rodillas de golpe.']::text[], 'intermedio', 'Fortalece los abductores y glúteos abriendo las rodillas mientras mantienes la cadera elevada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4881'),
('5bdfd002-3fff-5e7a-992e-bfc6b4496690', 'Postura del puente', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies paralelos cerca de los glúteos.', 'Apoya los brazos a los lados y eleva la cadera empujando con los pies.', 'Entrelaza las manos bajo la espalda y mantén los hombros apoyados.', 'Respira profundo y mantén la postura sin forzar el cuello.', 'Evita girar la cabeza o arquear en exceso la zona lumbar.']::text[], 'intermedio', 'Estiramiento de yoga que abre el pecho y fortalece glúteos e isquiotibiales mientras moviliza la columna.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4511'),
('64ed4f80-4109-59bf-892b-e25596f3c32e', 'Estiramiento de yoga en postura del puente', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados a la anchura de las caderas.', 'Presiona los pies contra el suelo y eleva la pelvis hasta formar una línea recta con el torso.', 'Junta las escápulas y respira despacio manteniendo la postura varias respiraciones.', 'Evita arquear en exceso la zona lumbar: sube desde los glúteos, no desde la espalda.']::text[], 'intermedio', 'Estira la columna y abre el pecho mientras activa glúteos e isquios, mejorando la movilidad y la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3565'),
('0ee5e86b-bc17-52cb-95f7-c3758bfffc69', 'Caminar a paso ligero', ARRAY['Camina erguido con los hombros relajados y la mirada al frente.', 'Aumenta el ritmo hasta que notes la respiración algo acelerada pero puedas hablar.', 'Balancea los brazos de forma natural y apoya el pie de talón a punta.', 'Evita encorvarte o dar zancadas exageradas que frenen el ritmo.']::text[], 'intermedio', 'Actividad cardiovascular suave que activa piernas y glúteos, mejora la resistencia y ayuda a quemar calorías.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3004'),
('7c4756e9-be08-59c0-8bd5-e2d68c17d734', 'Salto de longitud a salto vertical', ARRAY['Colócate de pie con los pies a la anchura de las caderas y flexiona ligeramente las rodillas.', 'Salta hacia delante con los dos pies y aterriza con las rodillas alineadas con los pies.', 'Aprovecha la recepción para saltar de inmediato hacia arriba lo más alto posible.', 'Amortigua cada aterrizaje con las rodillas flexionadas y evita caer con las piernas rígidas.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia cuádriceps y glúteos, mejorando la explosividad y la coordinación del salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4242'),
('2613544d-7943-5768-b1df-8026696e0628', 'Sentadilla búlgara con salto', ARRAY['Coloca el empeine del pie trasero sobre una superficie elevada y el pie delantero bien apoyado.', 'Baja flexionando la rodilla delantera hasta que el muslo quede casi paralelo al suelo.', 'Impulsa con la pierna delantera para saltar y cambia de pierna en el aire o aterriza con control.', 'Amortigua la caída y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Variante pliométrica unilateral que trabaja cuádriceps y glúteos, desarrollando potencia y estabilidad en cada pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3863'),
('90363751-9378-54b2-bbec-8192455eda2f', 'Sentadilla búlgara con silla', ARRAY['Apoya el empeine del pie trasero sobre una silla y da un paso al frente con el otro pie.', 'Mantén el torso erguido y baja flexionando la rodilla delantera hacia el suelo.', 'Empuja con el pie delantero para volver a la posición inicial sin perder el equilibrio.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Ejercicio unilateral de calistenia que fortalece cuádriceps, glúteos y aductores, mejorando el equilibrio y la fuerza de piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3743'),
('08ad8a16-f199-57f8-bfb5-6dc7b21310eb', 'Burpee', ARRAY['Comienza de pie con los pies separados a la altura de los hombros.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti.', 'Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos.', 'Realiza una flexión de brazos, manteniendo el cuerpo en línea recta.', 'Salta con los pies de vuelta a la posición de sentadilla.', 'Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.', 'Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que implica todo el cuerpo, mejorando la resistencia, la coordinación y la potencia.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '1160'),
('2013ed87-cd5d-57db-aeb2-d3c1d5060709', 'Burpee con salto al cajón', ARRAY['Desde de pie, baja a apoyar las manos y lleva los pies atrás hasta la posición de plancha.', 'Realiza una flexión si lo deseas y recoge los pies hacia las manos.', 'Salta con los dos pies sobre el cajón y aterriza con las rodillas flexionadas.', 'Baja del cajón con control y evita saltar con el cajón demasiado alto para tu nivel.']::text[], 'intermedio', 'Ejercicio explosivo que combina cardio y fuerza, trabajando piernas, pecho y core para mejorar la potencia y la resistencia.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '8704'),
('b64337c0-06cc-5612-884c-f1ccc3732839', 'Burpee con salto largo y flexión', ARRAY['Desde de pie, baja las manos al suelo y lleva los pies atrás a la posición de plancha.', 'Haz una flexión con el cuerpo alineado y el core apretado.', 'Recoge los pies y salta hacia delante lo más lejos posible con los dos pies.', 'Amortigua el aterrizaje y evita que la cadera se hunda durante la flexión.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que activa pecho, tríceps y piernas, mejorando la resistencia y la potencia del tren inferior.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5187'),
('c1953e6a-b61c-5882-a3e0-5ac4f82cc34f', 'Burpee sobre la mancuerna', ARRAY['Coloca la mancuerna en el suelo a un lado y colócate de pie frente a ella.', 'Baja a la posición de plancha, haz una flexión y recoge los pies.', 'Salta lateralmente por encima de la mancuerna y aterriza con las rodillas flexionadas.', 'Evita golpear la mancuerna con los pies y mantén el core firme en la plancha.']::text[], 'intermedio', 'Variante con mancuerna que suma intensidad cardiovascular y trabaja piernas, pecho y core con un salto lateral.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10182'),
('3b3f4612-b30f-50d0-b141-6792b9adf0a8', 'Burpee con empuje de trineo', ARRAY['Realiza un burpee completo bajando a plancha y recogiendo los pies.', 'Colócate tras el trineo con los brazos extendidos y el torso inclinado hacia delante.', 'Empuja el trineo con pasos cortos y firmes manteniendo la espalda recta.', 'Evita bloquear los codos o encorvar la espalda durante el empuje.']::text[], 'intermedio', 'Combinación de cardio y fuerza que trabaja piernas, pecho y hombros, mejorando la potencia y la resistencia muscular.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10193'),
('da729c2b-eb75-535a-8598-d54296af74ac', 'Complejo de burpee, flexión y escalador', ARRAY['Desde de pie, baja a plancha y realiza una flexión con el cuerpo alineado.', 'Sin levantar la cadera, lleva una rodilla al pecho y alterna como un escalador.', 'Recoge los pies y salta hacia arriba con los brazos extendidos.', 'Mantén el core apretado y evita que la cadera suba durante el escalador.']::text[], 'intermedio', 'Circuito cardiovascular exigente que activa pecho, tríceps, core y piernas, mejorando la resistencia y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5337'),
('4b5ceb01-4101-56cc-b321-992265eb279d', 'Burpee con sentadilla', ARRAY['Desde de pie, baja a la posición de plancha y recoge los pies.', 'Al incorporarte, realiza una sentadilla profunda con el pecho erguido.', 'Sube de la sentadilla y salta hacia arriba con los brazos extendidos.', 'Evita que las rodillas se vayan hacia dentro al hacer la sentadilla.']::text[], 'intermedio', 'Ejercicio explosivo que combina cardio y fuerza, trabajando piernas, glúteos y core para mejorar la resistencia y la potencia.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4548'),
('b50e3dc2-8a2b-5b19-ad2f-6d5fbc488705', 'Burpee con giro', ARRAY['Realiza un burpee bajando a plancha y recogiendo los pies.', 'Al incorporarte, gira el torso llevando los brazos hacia un lado.', 'Alterna el giro a cada lado en cada repetición.', 'Evita girar solo con los brazos: rota desde el tronco y mantén el core activo.']::text[], 'intermedio', 'Variante con rotación que trabaja oblicuos, core y piernas, mejorando la resistencia y la movilidad del tronco.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5968'),
('f0956a73-fbe7-5e51-948d-e675083fc3cb', 'Burpee con flexión', ARRAY['Desde de pie, baja las manos al suelo y lleva los pies atrás a la posición de plancha.', 'Realiza una flexión con los codos cerca del cuerpo y el core apretado.', 'Recoge los pies hacia las manos y salta hacia arriba con los brazos extendidos.', 'Evita hundir la cadera o adelantar la cabeza durante la flexión.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que suma trabajo de pecho y tríceps, mejorando la fuerza y la resistencia general.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3457'),
('eaed088d-a2a3-5cec-88a2-81b1c3af6670', 'Talones al glúteo', ARRAY['Corre en el sitio con el torso erguido y los brazos relajados.', 'Lleva los talones hacia los glúteos de forma rápida y alterna las piernas.', 'Mantén un ritmo constante y apoya la punta del pie en cada zancada.', 'Evita inclinarte hacia delante o dar zancadas demasiado largas.']::text[], 'intermedio', 'Ejercicio cardiovascular de carrera que activa isquios y gemelos, mejorando la coordinación y la frecuencia de zancada.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3037'),
('bec85aeb-1461-5bb1-96ad-0616ac8b0e32', 'Caminata sobre glúteos', ARRAY['Siéntate en el suelo con las piernas estiradas y el torso erguido.', 'Apoya las manos detrás o cruza los brazos y desplázate hacia atrás contrayendo un glúteo cada vez.', 'Avanza y retrocede alternando lados sin usar las piernas para impulsarte.', 'Mantén el abdomen firme y evita arquear la espalda baja.']::text[], 'principiante', 'Activa glúteos y core desplazándote sentado, mejorando movilidad de cadera y estabilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11571'),
('de76282c-2568-5051-beca-f7adfb67ce6d', 'Elevación de glúteos', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos a los lados, con las palmas hacia abajo.', 'Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.', 'En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen elevando la pelvis desde el suelo con control, sumando flexores de cadera y zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0870'),
('17a81bd2-058a-5339-bc11-94ee43f35650', 'Balanceo hacia atrás en mariposa', ARRAY['Siéntate con las plantas de los pies juntas y sujeta los pies con las manos.', 'Redondea la espalda y balancéate suavemente hacia atrás y hacia delante.', 'Respira de forma pausada y evita forzar la zona lumbar.', 'Vuelve despacio al centro y mantén la posición unos segundos.']::text[], 'principiante', 'Estira la columna y la cadena posterior meciéndote en mariposa, aliviando tensión en espalda y glúteos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10194'),
('96d852cc-3322-526f-8629-4ba0739bd0b2', 'Aleteo de mariposa en yoga', ARRAY['Siéntate con las plantas de los pies juntas y las rodillas hacia los lados.', 'Sujeta los pies y mueve las rodillas arriba y abajo con pequeños rebotes.', 'Mantén la espalda larga y respira con calma durante el movimiento.', 'Evita rebotes bruscos y no fuerces la apertura de cadera.']::text[], 'intermedio', 'Moviliza aductores y caderas con pequeños rebotes en mariposa, preparando la zona para estiramientos más profundos.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4867'),
('e1420c00-d88d-51f9-b6a0-fc7dd248b123', 'Postura de mariposa', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.', 'Sujétate los tobillos o los pies con las manos.', 'Siéntate erguido y alarga la columna.', 'Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.', 'Mantén esta posición durante unas cuantas respiraciones.', 'Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.']::text[], 'intermedio', 'Estira aductores y cara interna de los muslos, mejorando la apertura de cadera y la relajación.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1494'),
('a1614257-459e-59b3-91f4-e61b790aac76', 'Apertura invertida a 45 grados en polea', ARRAY['Colócate frente a la polea con las asas a la altura del pecho y los brazos cruzados.', 'Abre los brazos hacia atrás y afuera en diagonal, apretando los omóplatos.', 'Controla el retorno sin dejar que el peso tire de ti.', 'Evita encoger los hombros y mantener el torso quieto.']::text[], 'principiante', 'Refuerza deltoides posterior y espalda alta abriendo los brazos en polea, mejorando postura y estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8878'),
('b37263e1-e1d5-5745-bfd1-0e1b35684056', 'Apertura invertida a 45 grados con agarre inverso en polea', ARRAY['Sujeta las asas con agarre inverso y brazos cruzados frente al pecho.', 'Abre los brazos en diagonal hacia atrás apretando los omóplatos.', 'Vuelve despacio manteniendo el control del peso.', 'No balancees el torso ni subas los hombros.']::text[], 'principiante', 'Trabaja deltoides posterior y romboides con agarre inverso, reforzando la espalda alta y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9867'),
('2eac9468-8f0c-5fed-8c5f-6403dcceb197', 'Apertura invertida a 45 grados a un brazo en polea', ARRAY['Colócate de lado a la polea y sujeta el asa con la mano contraria al peso.', 'Abre el brazo hacia atrás en diagonal sin mover el torso.', 'Aprieta el omóplato al final y vuelve con control.', 'Evita girar el tronco o encoger el hombro.']::text[], 'principiante', 'Aísla el deltoides posterior de un lado abriendo el brazo en polea, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9868'),
('cff373b2-a427-5e7c-b79e-993f1b3a4075', 'Apertura invertida a 45 grados a un brazo con agarre inverso en polea', ARRAY['Sujeta el asa con agarre inverso y colócate de lado a la polea.', 'Abre el brazo hacia atrás en diagonal apretando el omóplato.', 'Regresa despacio sin perder la tensión.', 'Mantén el torso estable y el hombro bajo.']::text[], 'principiante', 'Refuerza deltoides posterior y espalda alta de forma unilateral con agarre inverso, mejorando control y postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9869'),
('6c946e0e-69eb-5be6-86d4-e6ac3bdf7f1c', 'Atrape de rotación interna a 90 grados en polea', ARRAY['Coloca el codo a 90 grados pegado al cuerpo y sujeta el asa.', 'Rota el antebrazo hacia dentro del cuerpo con control.', 'Vuelve despacio a la posición inicial sin soltar la tensión.', 'Evita separar el codo del torso o usar impulso.']::text[], 'principiante', 'Fortalece el manguito rotador con rotación interna controlada, mejorando estabilidad del hombro y prevención de lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10597'),
('3060340e-3b19-595c-8803-1d2f30a3b6af', 'Press de hombros alternado en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono.', 'Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante.', 'Mantén el core activado y la espalda recta.', 'Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.', 'Repite con el otro brazo.', 'Alterna entre los brazos el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece deltoides y tríceps empujando de forma alterna en polea, mejorando estabilidad y control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0148'),
('a323d5f7-15fb-5cba-8b4f-2cbc2a9bd8e0', 'Curl femoral inverso asistido en polea', ARRAY['Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja.', 'Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos.', 'Sujétate de las agarraderas del banco para mantener la estabilidad.', 'Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.', 'Inhala y baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja isquiotibiales y glúteos con flexión de rodilla asistida, reforzando la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3235'),
('7c11353c-c2c8-5577-acbb-73fc8d001185', 'Extensión de tríceps sobre la cabeza con barra en polea alta', ARRAY['Colócate de espaldas a la polea con la barra sujeta por encima de la cabeza.', 'Mantén los codos altos y cerca de la cabeza.', 'Extiende los brazos hacia delante y arriba hasta estirar del todo.', 'Vuelve despacio sin abrir los codos ni arquear la espalda.']::text[], 'principiante', 'Aísla el tríceps extendiendo los codos por encima de la cabeza, mejorando fuerza y tono del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3040'),
('c943adc2-4c65-5d3b-a0ce-da43da96e9ca', 'Jalón al pecho en polea', ARRAY['Ajusta la polea del cable a una posición alta y coloca una barra recta.', 'Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar.', 'Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos.', 'Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece dorsales y bíceps tirando de la barra al pecho, mejorando la amplitud y la postura de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0150'),
('edfe8ddc-27a9-5879-8305-e2e5c31e398b', 'Press de banca en polea', ARRAY['Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.', 'Coloca los pies firmemente en el suelo y activa el core.', 'Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.', 'Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.', 'Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja pectorales y tríceps empujando en polea, con tensión constante y menor carga sobre el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0151'),
('141c8186-70bf-53df-bf0b-7a7db6d72587', 'Patada de tríceps inclinado con cuerda en polea', ARRAY['Colócate inclinado hacia delante con el torso firme y una ligera flexión de rodillas.', 'Sujeta la cuerda con agarre neutro y lleva los codos junto al cuerpo.', 'Extiende los codos hacia atrás hasta estirar del todo sin mover los hombros.', 'Controla la vuelta en dos o tres segundos y evita balancear el tronco.']::text[], 'principiante', 'Aísla el tríceps en su porción lateral y refuerza la extensión del codo, útil para definir la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4578'),
('bc163eff-7a13-54ad-b9f0-ab00fafe70d2', 'Remo inclinado con agarre inverso en polea', ARRAY['Agarra la barra con las palmas hacia arriba y el torso inclinado y estable.', 'Tira de la barra hacia el abdomen bajo llevando los codos cerca del cuerpo.', 'Junta las escápulas al final del recorrido y mantén un instante.', 'Baja controlando el peso sin redondear la espalda ni perder la postura.']::text[], 'principiante', 'Trabaja la espalda y el dorsal con un agarre que activa más el bíceps, mejorando la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4367'),
('2094d84d-e124-5b35-87d5-08e91d3ca034', 'Remo inclinado en polea', ARRAY['Colócate con el torso inclinado, rodillas ligeramente flexionadas y espalda neutra.', 'Sujeta el maneral y tira hacia el pecho llevando los codos atrás.', 'Aprieta las escápulas al final y exhala durante el esfuerzo.', 'Evita tirar con los brazos o encorvar la espalda al bajar el peso.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides, mejorando la postura y la estabilidad de la cintura escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3859'),
('65c075de-32c5-5871-bcd5-972543c12e1d', 'Remo inclinado con barra en polea', ARRAY['Agarra la barra con las palmas hacia abajo y el torso inclinado y firme.', 'Tira de la barra hacia la parte baja del pecho sin mover el tronco.', 'Mantén los codos cerca del cuerpo y aprieta la espalda al final.', 'Controla la bajada y evita usar impulso de cadera o lumbares.']::text[], 'principiante', 'Desarrolla el dorsal y la espalda media con un movimiento de tracción horizontal que gana fuerza y volumen.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4011'),
('c552402d-ee48-54e4-8502-75e2d2e4f08b', 'Remo inclinado con cuerda en polea', ARRAY['Sujeta la cuerda con agarre neutro y el torso inclinado y estable.', 'Tira hacia el abdomen separando ligeramente las manos al final.', 'Junta las escápulas y mantén un segundo de contracción.', 'Vuelve despacio sin perder la curvatura natural de la espalda.']::text[], 'principiante', 'Activa la espalda alta y los romboides con un agarre neutro que permite mayor recorrido y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4368'),
('27f3798b-b285-5566-8734-4fb30e4cb84f', 'Patada de tríceps a un brazo inclinado en polea', ARRAY['Inclínate con una mano apoyada y sujeta el maneral con la otra.', 'Fija el codo junto al costado y extiende el brazo hacia atrás.', 'Estira del todo sin elevar el hombro ni girar el tronco.', 'Regresa despacio y mantén el abdomen firme durante todo el recorrido.']::text[], 'principiante', 'Aísla el tríceps de un brazo y exige control del core para mantener la postura inclinada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4545'),
('0dd62ec6-adc2-5de6-90be-d12305aa9b4d', 'Patada de tríceps a un brazo con cuerda en polea', ARRAY['Colócate inclinado y sujeta la cuerda con una sola mano.', 'Lleva el codo junto al cuerpo y extiende el brazo hacia atrás.', 'Aprieta el tríceps al final sin mover el hombro.', 'Controla la vuelta y evita balancear el torso para coger impulso.']::text[], 'principiante', 'Trabaja el tríceps de forma unilateral con agarre neutro, mejorando el control y la simetría del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4567'),
('33bfaf54-717b-5982-854d-de42cafc17c4', 'Remo a un brazo inclinado en polea', ARRAY['Inclínate con apoyo y agarra el maneral con una mano.', 'Tira del codo hacia atrás y hacia la cadera sin girar el tronco.', 'Aprieta el dorsal al final del recorrido y exhala.', 'Baja controlando el peso y mantén la espalda neutra.']::text[], 'principiante', 'Fortalece el dorsal de forma unilateral, corrigiendo desequilibrios y mejorando la conexión mente-músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11269'),
('1e20e381-640d-5c50-8dde-6aa70c010674', 'Curl de bíceps en polea con barra Z', ARRAY['Sujeta la barra Z con las palmas hacia arriba y los codos pegados al cuerpo.', 'Flexiona los codos hasta subir la barra sin mover los hombros.', 'Aprieta el bíceps arriba y baja despacio controlando el peso.', 'Evita balancear el tronco o adelantar los codos para subir más.']::text[], 'principiante', 'Aísla el bíceps con tensión constante y un agarre que reduce la carga en las muñecas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1607'),
('e4fe9bfa-98e5-56d2-bc80-89506bf776e7', 'Jalón al pecho con agarre cerrado en polea', ARRAY['Siéntate con el torso erguido y agarra el maneral con las palmas hacia delante.', 'Tira hacia la parte alta del pecho llevando los codos abajo y atrás.', 'Junta las escápulas y evita echar el tronco muy atrás.', 'Sube el peso despacio hasta estirar los brazos sin soltar la tensión.']::text[], 'principiante', 'Desarrolla el dorsal y la espalda alta con un agarre cerrado que aumenta el recorrido y la activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1047'),
('1327ee47-c534-5841-adc3-7026a71eef03', 'Curl concentrado en polea', ARRAY['Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo.', 'Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Aísla el bíceps con el codo fijo, buscando máxima contracción y control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1631'),
('b046409a-e1a9-5369-85d2-02422930c283', 'Extensión concentrada de tríceps en polea', ARRAY['Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo.', 'Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha.', 'Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla.', 'Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Aísla el tríceps con el codo apoyado, mejorando la extensión y la definición del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0152'),
('ccae3457-31bb-5015-be31-cdf14324a527', 'Jalón lateral cruzado en polea', ARRAY['Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros.', 'Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros.', 'Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables.', 'Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos.', 'Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal con un recorrido cruzado que enfatiza la porción baja y la conexión con la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0153'),
('6f4b4f28-bf57-5026-a91d-f5e7ae2e608a', 'Apertura invertida cruzada en polea', ARRAY['Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado.', 'Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado.', 'Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa.', 'Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el deltoides posterior y los romboides, equilibrando el hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0154'),
('3f16ad5f-a67a-5d30-9254-ec4de726d243', 'Cruce de poleas', ARRAY['Ajusta las poleas del cable a la altura del pecho.', 'Ponte de pie en el centro de la máquina de cable con un pie delante del otro.', 'Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados.', 'Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados.', 'Con una ligera flexión en los codos, junta las manos frente al pecho.', 'Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el pectoral con un movimiento de aducción que busca máxima contracción en el centro del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0155'),
('fb4281aa-000e-51de-a563-c2875cd8476e', 'Curl en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el accesorio del cable con agarre supino, palmas hacia arriba.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps con tensión constante para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0868'),
('c9f22715-d907-5de3-9c8b-548b4670c305', 'Peso muerto en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.', 'Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.', 'Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.', 'Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja glúteos y cadena posterior con un patrón de bisagra que fortalece la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0157'),
('e69c306f-ccd1-5a48-95dc-cb6d01a0ec62', 'Press declinado a un brazo en polea', ARRAY['Ajusta la máquina de cable a una posición declinada.', 'Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano.', 'Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti.', 'Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto.', 'Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Activa el pectoral desde un ángulo descendente y añade trabajo unilateral para corregir desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1260'),
('b4daf00e-8ddb-5efd-aa3c-36cb143447bb', 'Remo sentado declinado con agarre abierto en polea', ARRAY['Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés.', 'Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo.', 'Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.', 'Tira del cable hacia la parte inferior del pecho, juntando los omóplatos.', 'Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la espalda alta con un tirón horizontal que mejora la postura y la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0159'),
('3e5ede7c-410c-51b2-b48a-0cc180c1f122', 'Patada diagonal de burro en polea', ARRAY['Colócate frente a la polea con la tobillera puesta y las manos apoyadas en el soporte.', 'Lleva la pierna hacia atrás y en diagonal, extendiendo la cadera sin arquear la lumbar.', 'Aprieta el glúteo arriba un segundo y baja controlando el retorno.', 'Mantén el abdomen firme y evita girar la pelvis durante el recorrido.']::text[], 'principiante', 'Aísla el glúteo con una trayectoria diagonal que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6742'),
('c41c5ce2-5338-546a-b277-29a10bc827ed', 'Patada de burro en polea', ARRAY['Sujétate al soporte con la tobillera colocada y el torso ligeramente inclinado.', 'Empuja la pierna hacia atrás manteniendo la rodilla algo flexionada.', 'Extiende la cadera sin balancear el tronco ni curvar la espalda.', 'Sube con control, aprieta el glúteo y vuelve despacio a la posición inicial.']::text[], 'principiante', 'Ejercicio de aislamiento para glúteo que mejora la extensión de cadera y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4421'),
('64b6d559-565a-5e29-a3d9-eeb80ff7beec', 'Remo elevado en polea', ARRAY['Siéntate o colócate con el agarre a la altura del pecho y la espalda recta.', 'Tira de la polea llevando los codos atrás y juntando las escápulas.', 'Evita encoger los hombros y no uses impulso del tronco.', 'Vuelve despacio controlando la fase excéntrica y respirando de forma fluida.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides con un tirón que mejora la postura diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1046'),
('8c19ce8b-ada8-52e8-874d-3bc00d11c680', 'Face pull con rotación externa en polea', ARRAY['Coloca la polea a la altura de la cara y agarra la cuerda con las palmas hacia dentro.', 'Tira hacia la frente separando las manos y abriendo los codos.', 'Añade rotación externa llevando las manos hacia atrás sin subir los hombros.', 'Trabaja con poco peso y evita arquear la espalda o encoger el cuello.']::text[], 'principiante', 'Refuerza deltoides posterior y manguito rotador para proteger el hombro y mejorar la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11060'),
('de74c6c8-9258-5601-8525-8d2d56e9647f', 'Remo sentado en el suelo con agarre abierto en polea', ARRAY['Siéntate en el suelo con las piernas extendidas y la espalda recta.', 'Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti.', 'Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.', 'Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.', 'Tira de la agarradera hacia la cintura, juntando los omóplatos.', 'Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta desde el suelo con un tirón amplio que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0160'),
('c1893c95-4d1f-583b-b36f-16953f1fbbd5', 'Pronación de antebrazo en polea', ARRAY['Siéntate con el antebrazo apoyado y la muñeca fuera del borde, sujetando el mango.', 'Gira la muñeca hacia dentro contra la resistencia de la polea.', 'Mantén el codo fijo y el movimiento lento y controlado.', 'Evita compensar con el hombro y vuelve despacio a la posición neutra.']::text[], 'principiante', 'Fortalece los rotadores del antebrazo y la muñeca para mejorar el agarre y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8881'),
('3505e7ce-ac08-5c8f-b885-64c1377ad19f', 'Zancada hacia delante en polea', ARRAY['Colócate de espaldas a la polea con la tobillera y da un paso al frente.', 'Baja flexionando la rodilla delantera sin que pase la punta del pie.', 'Empuja con el talón para volver a la posición inicial manteniendo el tronco erguido.', 'Evita que la rodilla se vaya hacia dentro y controla el descenso.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3356'),
('1626c08a-f778-5066-9432-cf7740ad9e02', 'Elevación frontal en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.', 'Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el deltoides anterior para ganar fuerza y definición en la parte frontal del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0161'),
('5788a2b1-b5aa-5d51-829e-1b790d896a4d', 'Remo frontal sentado en polea', ARRAY['Siéntate frente a la polea con los pies apoyados y la espalda recta.', 'Tira del agarre hacia el abdomen llevando los codos atrás.', 'Junta las escápulas al final del recorrido sin encoger los hombros.', 'Vuelve despacio y evita balancear el tronco para usar impulso.']::text[], 'principiante', 'Refuerza la espalda alta y los dorsales con un tirón horizontal que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0163'),
('92a2e46b-9181-563e-9aef-d3d1651b00d6', 'Sentadilla frontal en polea', ARRAY['Sujeta el agarre de la polea a la altura del pecho con los codos altos.', 'Baja flexionando rodillas y caderas manteniendo el torso vertical.', 'Empuja con los talones para subir sin perder la posición del pecho.', 'Evita que las rodillas se junten hacia dentro y controla la bajada.']::text[], 'principiante', 'Trabaja cuádriceps y core con una sentadilla que exige tronco erguido y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3349'),
('bd11eb7b-9542-5e26-ad7e-5268b7d13d86', 'Subida al banco enfocada en glúteos en polea', ARRAY['Coloca la tobillera y apoya un pie sobre el banco con la rodilla alineada.', 'Empuja con el talón para subir extendiendo la cadera del lado de trabajo.', 'Mantén el tronco erguido y evita impulsarte con la pierna de abajo.', 'Baja despacio controlando el movimiento y repite sin perder el equilibrio.']::text[], 'principiante', 'Fortalece glúteos y cuádriceps con un patrón unilateral que mejora el equilibrio y la fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5315'),
('9b61b2ce-e2c4-52fb-89d0-a78f6656eedf', 'Sentadilla goblet en polea', ARRAY['Coloca el agarre a la altura del pecho y sujétalo con ambas manos pegadas al esternón.', 'Separa los pies a la anchura de los hombros y baja flexionando rodillas y caderas con el pecho alto.', 'Desciende hasta que los muslos queden cerca de la horizontal sin perder la curvatura lumbar.', 'Empuja el suelo con los talones y sube exhalando mientras aprietas los glúteos.', 'Evita que las rodillas se metan hacia dentro o que los talones se despeguen del suelo.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos mientras el core estabiliza el tronco, ideal para aprender el patrón de sentadilla con carga controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6544'),
('b4795140-9b4d-5cd0-9795-dac19817f0b4', 'Press pallof de aductores a media rodilla en polea', ARRAY['Arrodíllate sobre la rodilla interior con el cable a un lado y el cuerpo de perfil a la polea.', 'Sujeta el mango con ambas manos frente al pecho y activa el glúteo de la pierna apoyada.', 'Extiende los brazos al frente sin dejar que el cable te gire hacia la polea.', 'Mantén dos segundos y vuelve despacio al pecho respirando de forma constante.', 'Evita arquear la zona lumbar o girar las caderas para compensar la tensión.']::text[], 'principiante', 'Trabaja el core y los aductores resistiendo la rotación del cable, mejorando la estabilidad del tronco y la fuerza en el plano frontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4196'),
('93930586-7874-501f-be9a-d27df101d0f3', 'Rotación externa a media rodilla en polea', ARRAY['Arrodíllate de perfil a la polea con el codo pegado al costado y flexionado a 90 grados.', 'Sujeta el mango con la mano exterior y mantén el antebrazo paralelo al suelo.', 'Gira el antebrazo hacia fuera sin separar el codo del cuerpo ni mover el tronco.', 'Vuelve despacio a la posición inicial controlando la resistencia en todo el recorrido.', 'Evita encoger el hombro o usar impulso del torso para completar la rotación.']::text[], 'principiante', 'Refuerza el manguito rotador y la parte posterior del hombro, clave para estabilizar la articulación y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4194'),
('fe5cd724-449a-548a-91da-3dd143ecead8', 'Press con rotación externa a media rodilla en polea', ARRAY['Arrodíllate de perfil a la polea con el codo flexionado y la mano cerca del hombro.', 'Empuja el mango hacia delante mientras giras el antebrazo hacia fuera.', 'Extiende el brazo sin bloquear del todo el codo y mantén el core firme.', 'Regresa despacio invirtiendo el giro hasta la posición inicial.', 'Evita elevar el hombro hacia la oreja o perder la alineación del tronco.']::text[], 'principiante', 'Combina empuje y rotación para fortalecer deltoides y manguito rotador, mejorando el control escapular y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8879'),
('af8e30f9-6f22-5bfc-a746-ea03b1629711', 'Press pallof a media rodilla en polea', ARRAY['Arrodíllate de perfil a la polea con el mango sujeto a la altura del esternón.', 'Activa glúteos y abdomen para mantener la cadera y las costillas alineadas.', 'Extiende los brazos al frente sin permitir que el cable te rote.', 'Aguanta un instante y regresa despacio al pecho sin perder la tensión.', 'Evita girar el torso o adelantar el hombro para resistir el tirón del cable.']::text[], 'principiante', 'Entrena la antirotación del core y los oblicuos, mejorando la estabilidad del tronco y la transferencia de fuerza en gestos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4193'),
('a3168b35-aff0-5e41-bdbe-9344b2f3e270', 'Empuje y tirón a media rodilla en polea', ARRAY['Arrodíllate de perfil a la polea con el mango sujeto con ambas manos frente al pecho.', 'Empuja el mango hacia delante extendiendo los brazos sin dejar que el cuerpo rote.', 'Recoge el mango hacia el pecho juntando las escápulas y manteniendo el abdomen firme.', 'Alterna empuje y tirón con ritmo controlado y respiración constante.', 'Evita balancear el tronco o encoger los hombros durante el movimiento.']::text[], 'principiante', 'Trabaja el core, oblicuos y espalda alta alternando empuje y tracción, mejorando la estabilidad y el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4228'),
('78fb3f89-cd0e-541c-a967-ad3cb15db0c3', 'Remo a un brazo a media rodilla en polea', ARRAY['Arrodíllate frente a la polea con una mano apoyada en el muslo y la otra sujetando el mango.', 'Lleva el codo hacia atrás pegándolo al costado mientras juntas la escápula.', 'Mantén el tronco estable y el abdomen activo sin girar hacia la polea.', 'Extiende el brazo despacio hasta la posición inicial controlando la resistencia.', 'Evita tirar con el bíceps o rotar el torso para completar el recorrido.']::text[], 'principiante', 'Fortalece dorsales y espalda alta con un brazo, trabajando también el core para evitar la rotación del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8299'),
('7c66c324-580d-58eb-be58-15f5e5830b84', 'Curl martillo en polea', ARRAY['Colócate frente a la polea baja con los codos pegados al costado y las palmas enfrentadas.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Aprieta el bíceps arriba y baja despacio controlando la resistencia.', 'Mantén las muñecas neutras y la espalda recta durante todo el recorrido.', 'Evita balancear el tronco o adelantar los codos para levantar más peso.']::text[], 'principiante', 'Aísla bíceps y braquial con agarre neutro, aumentando la fuerza del brazo y el grosor del antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0166'),
('a2d9289a-e349-5008-908e-81941aa18dcd', 'Curl martillo en polea con cuerda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.', 'Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el bíceps y el antebrazo con un agarre neutro, ganando fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0165'),
('1a552dea-6827-583b-b62d-d865772239e6', 'Jalón alto en polea con cuerda', ARRAY['Sujeta la cuerda con ambas manos y da un paso atrás con los pies a la anchura de los hombros.', 'Tira de la cuerda hacia arriba y hacia fuera llevando los codos por encima de los hombros.', 'Junta las escápulas al final del recorrido sin encoger el cuello.', 'Baja la cuerda despacio hasta la altura del pecho controlando la tensión.', 'Evita usar impulso de piernas o encorvar la espalda para subir más peso.']::text[], 'principiante', 'Trabaja deltoides posteriores, espalda alta y trapecios con un tirón vertical, mejorando la fuerza y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6648'),
('6f12d592-87e1-5a8c-8b71-401a55543ea5', 'Extensión de tríceps sobre la cabeza en polea alta', ARRAY['Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina.', 'Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza.', 'Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil.', 'Baja lentamente la cuerda detrás de la cabeza flexionando los codos.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps en estiramiento, útil para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1722'),
('38f9342f-b517-51fd-b3f9-81c884be37f8', 'Extensión de tríceps sobre la cabeza con barra recta en polea alta', ARRAY['Colócate de espaldas a la polea alta con la barra sujeta por encima de la cabeza.', 'Mantén los codos apuntando al frente y pegados junto a las orejas.', 'Extiende los codos llevando la barra hacia delante sin mover los brazos.', 'Vuelve despacio a la posición inicial sintiendo el estiramiento del tríceps.', 'Evita abrir los codos o arquear la zona lumbar durante el movimiento.']::text[], 'principiante', 'Aísla el tríceps en posición estirada, trabajando las tres porciones y mejorando la fuerza en extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5874'),
('affc3ef8-7861-5599-b8f7-a66b004b5cb5', 'Remo alto en polea de rodillas', ARRAY['Sujeta una barra recta a una máquina de cable a la altura del pecho.', 'Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros.', 'Siéntate sobre los talones, manteniendo la espalda recta y el core activado.', 'Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los hombros, mejorando la postura y la fuerza de tracción desde una posición estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0167'),
('1caf15fb-8e6f-5df0-bfdc-5a8efe3f4db0', 'Remo alto con apoyo de pecho en polea', ARRAY['Apoya el pecho en el soporte y sujeta los mangos con los brazos extendidos.', 'Tira de los codos hacia atrás juntando las escápulas sin despegar el pecho.', 'Mantén el cuello alineado y el abdomen activo durante el tirón.', 'Regresa despacio a la posición inicial controlando la resistencia.', 'Evita encoger los hombros o usar impulso para completar el recorrido.']::text[], 'principiante', 'Fortalece espalda alta, romboides y deltoides posteriores con apoyo que reduce la carga lumbar y mejora la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7597'),
('e926dc62-ad58-54b4-babb-b668ded9e8e8', 'Abducción de cadera en polea con pie hacia dentro', ARRAY['Coloca la tobillera en el pie exterior y sujétate a la polea para mantener el equilibrio.', 'Gira ligeramente la punta del pie hacia dentro y mantén la pierna recta.', 'Separa la pierna del cuerpo hacia fuera sin inclinar el tronco.', 'Vuelve despacio a la posición inicial controlando la resistencia.', 'Evita balancear el cuerpo o compensar con la cadera contraria.']::text[], 'principiante', 'Fortalece abductores y glúteo medio, mejorando la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2756'),
('70c9443b-b3c0-5375-b86f-e78960944db8', 'Aducción de cadera en polea', ARRAY['Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable.', 'Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.', 'Coloca las manos sobre la máquina para apoyarte.', 'Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los aductores y estabiliza la cadera, útil para mejorar la fuerza en movimientos laterales y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0168'),
('bb4d561d-3f1a-5a43-a6d4-5183cc47924e', 'Press pallof horizontal en polea', ARRAY['Colócate de lado a la polea con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta el maneral con ambas manos a la altura del pecho y extiende los brazos al frente sin dejar que el torso gire.', 'Mantén la posición de 20 a 40 segundos respirando con normalidad y sin bloquear el aire.', 'Evita arquear la zona lumbar o encoger los hombros; mantén las costillas abajo y el abdomen firme.']::text[], 'principiante', 'Ejercicio isométrico que fortalece el core y los oblicuos resistiendo la rotación, clave para estabilidad lumbar y rendimiento.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1202'),
('5dbb740f-8ab4-5e81-8484-e65b7c514a20', 'Press de banca inclinado en polea', ARRAY['Coloca un banco inclinado frente a la polea baja y sujeta los manerales con las palmas hacia delante.', 'Empuja los mangos hacia arriba y adelante hasta extender los brazos sin bloquear del todo los codos.', 'Baja de forma controlada hasta notar estiramiento en el pecho, controlando unos dos segundos la fase excéntrica.', 'Evita sacar los hombros hacia delante o rebotar al final del recorrido; mantén la espalda apoyada en el banco.']::text[], 'principiante', 'Fortalece el pectoral superior y los tríceps con tensión constante, ideal para ganar volumen en la parte alta del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11264'),
('bd874765-5efb-58f0-b40b-0475323e2ea3', 'Remo inclinado en banco con polea', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja.', 'Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti.', 'Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado.', 'Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos.', 'Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción en la vida diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1318'),
('098357b1-5949-5fa0-ba95-4764fa6d526d', 'Curl de bíceps inclinado en polea', ARRAY['Siéntate en un banco inclinado frente a la polea baja y sujeta la barra con las palmas hacia arriba.', 'Flexiona los codos llevando la barra hacia los hombros sin mover los brazos del sitio.', 'Baja despacio controlando la polea hasta estirar casi del todo el codo, sin dejar caer el peso de golpe.', 'Evita balancear el torso o adelantar los hombros para subir más carga.']::text[], 'principiante', 'Aísla el bíceps en estiramiento con tensión constante, útil para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5703'),
('e8add6ba-9c84-5446-9352-499df27966b6', 'Curl inclinado con agarre cerrado en polea', ARRAY['Colócate en un banco inclinado frente a la polea baja y agarra la barra con las manos juntas y palmas arriba.', 'Sube la barra flexionando los codos sin separarlos del torso ni mover los hombros.', 'Aprieta un segundo arriba y baja de forma lenta hasta estirar el codo sin soltar la tensión.', 'Evita encoger los hombros o usar impulso del cuerpo para completar la repetición.']::text[], 'principiante', 'Trabaja el bíceps y el braquial con un agarre que aumenta la tensión, ayudando a engrosar el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4345'),
('87a02bb6-7eba-5659-bb57-3e2e2a4245f2', 'Press de hombros inclinado con agarre cerrado y barra V en polea', ARRAY['Siéntate en un banco inclinado frente a la polea baja y agarra la barra V con las palmas enfrentadas.', 'Empuja la barra hacia arriba y adelante hasta extender los brazos sin bloquear los codos del todo.', 'Baja controlando la polea hasta la altura del pecho, manteniendo las muñecas firmes.', 'Evita arquear la espalda o subir los hombros hacia las orejas durante el empuje.']::text[], 'principiante', 'Fortalece los hombros y tríceps con un agarre cerrado que enfatiza la parte alta del pecho y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8662'),
('bdf305d7-e781-5cba-9366-da7868b31434', 'Apertura posterior cruzada inclinado en polea', ARRAY['Colócate inclinado frente a la polea con los brazos cruzados y sujeta los manerales opuestos.', 'Abre los brazos hacia los lados y atrás con los codos ligeramente flexionados, buscando juntar las escápulas.', 'Vuelve despacio al centro manteniendo la tensión y sin dejar que los hombros se vayan hacia delante.', 'Evita usar impulso del tronco o encoger el cuello al abrir los brazos.']::text[], 'principiante', 'Refuerza los deltoides posteriores y la espalda alta, equilibrando el desarrollo del hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4012'),
('397b2062-3326-5851-9fb2-231d1d6a840a', 'Apertura inclinada en polea', ARRAY['Ajusta la máquina de cable a una posición baja y sujeta las agarraderas.', 'Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.', 'Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti.', 'Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado.', 'Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el pectoral con un recorrido amplio y tensión continua, ayudando a definir y estirar la musculatura del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0171'),
('b22963dd-2403-5c88-b28a-088f65575789', 'Extensión de tríceps inclinado en polea', ARRAY['Sujeta una barra recta a una máquina de cable con polea alta.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Inclínate ligeramente hacia adelante y mantén la espalda recta.', 'Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos.', 'Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el tríceps y la espalda en un patrón de empuje, útil para mejorar la extensión del codo y la fuerza general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0172'),
('c88ecbb5-ccbd-58f8-aa7b-51f8aca70e28', 'Apertura posterior inclinada con apoyo de espalda en polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada y sujeta los manerales de la polea con los brazos cruzados.', 'Abre los brazos hacia los lados y atrás con los codos algo flexionados, apretando las escápulas.', 'Regresa despacio al centro sin perder la tensión ni dejar caer los hombros.', 'Evita despegar la espalda del banco o encoger el cuello durante el movimiento.']::text[], 'principiante', 'Fortalece los deltoides posteriores y la espalda alta con apoyo lumbar, ideal para mejorar la postura y el equilibrio del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7592'),
('aab2c4b0-6044-5d49-9710-c2c72ac34c0a', 'Elevación en Y inclinada a un brazo con apoyo de espalda en polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada y sujeta un maneral con una mano.', 'Eleva el brazo en diagonal formando una Y, con el pulgar hacia arriba y el codo casi extendido.', 'Baja despacio controlando la polea hasta la posición inicial sin perder la tensión.', 'Evita encoger el hombro o usar impulso del tronco para subir el brazo.']::text[], 'principiante', 'Activa los deltoides y el manguito rotador en un patrón en Y, mejorando la estabilidad y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9870'),
('7847ba44-9847-5677-bf01-6eeb9ae30550', 'Elevación en Y inclinada a un brazo con muñequeras y apoyo de espalda en polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada y colócate las muñequeras antes de agarrar el maneral.', 'Eleva un brazo en diagonal formando una Y, con el pulgar hacia arriba y el codo casi extendido.', 'Baja de forma lenta y controlada hasta la posición inicial manteniendo la tensión en la polea.', 'Evita tirar con el cuello o despegar la espalda del banco durante la elevación.']::text[], 'principiante', 'Refuerza deltoides y manguito rotador con un patrón en Y, usando muñequeras para mejorar el agarre y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9871'),
('f63fffea-fa5d-523c-85d7-ed8e2ec529df', 'Rompecráneos inclinado en polea', ARRAY['Siéntate en un banco inclinado frente a la polea baja y sujeta la barra con las palmas hacia abajo.', 'Flexiona los codos llevando la barra hacia la frente, manteniendo los brazos quietos y apuntando al techo.', 'Extiende los codos para volver arriba sin bloquear del todo la articulación y controlando la polea.', 'Evita mover los hombros o abrir los codos hacia los lados durante el recorrido.']::text[], 'principiante', 'Aísla el tríceps en estiramiento con tensión constante, útil para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4351'),
('1fb92e2e-bf36-51a4-9c7e-b0c3dd779fd0', 'Elevación en Y inclinado con apoyo de espalda en polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada y sujeta los manerales con ambas manos.', 'Eleva los brazos en diagonal formando una Y, con los pulgares hacia arriba y los codos casi extendidos.', 'Baja despacio controlando la polea hasta la posición inicial sin perder la tensión.', 'Evita encoger los hombros o despegar la espalda del banco durante la elevación.']::text[], 'principiante', 'Trabaja los deltoides y la espalda alta en un patrón en Y, mejorando la estabilidad escapular y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8661'),
('362237b2-4a9b-5239-83ea-11b6ccfe6537', 'Elevación en Y inclinado en polea con correas', ARRAY['Colócate inclinado hacia delante con la espalda apoyada y las correas en las muñecas.', 'Sube los brazos en forma de Y hasta la altura de los hombros sin encogerlos.', 'Controla la bajada durante dos segundos y evita tirar con la espalda baja.']::text[], 'principiante', 'Trabaja el deltoides posterior y la parte alta de la espalda, mejorando la postura y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8663'),
('03f971f5-aa76-53f6-a022-c664bdc18a21', 'Subida al banco con glúteo en polea', ARRAY['Coloca la polea baja y engancha el tobillo con la pierna que sube al banco.', 'Apoya el pie completo en el banco y empuja con el talón para subir.', 'Mantén el tronco erguido y evita impulsarte con la pierna de abajo.', 'Baja controlando el movimiento sin dejar caer la cadera.']::text[], 'principiante', 'Fortalece el glúteo y el cuádriceps de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7586'),
('8ecab0e5-42d0-5e52-9fc1-b9a53b5f896c', 'Giro de judo en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo.', 'Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo.', 'Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural.', 'Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro.', 'Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro.', 'Repite el movimiento en el lado opuesto.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa el recto abdominal y los oblicuos con un movimiento rotacional controlado que mejora la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0174'),
('cbe0af35-0f97-5f4e-a182-6d157f054e04', 'Patada de tríceps en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.', 'Extiende el antebrazo hacia atrás, enderezando el brazo por completo.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Aísla el tríceps en extensión de codo, útil para definir la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0860'),
('28c26d54-2cc1-557a-a055-d57a69315908', 'Abdominal de rodillas en polea', ARRAY['Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina.', 'Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados.', 'Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el recto abdominal con flexión de tronco resistida, aumentando la fuerza y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0175'),
('169460ec-be3b-580e-9195-548b07c5d5a0', 'Patada de glúteo de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea baja con el tobillo enganchado y las manos apoyadas en el suelo.', 'Mantén el core activo y la espalda neutra mientras empujas la pierna hacia atrás y arriba.', 'Aprieta el glúteo al final del recorrido y evita arquear la zona lumbar.', 'Baja la pierna de forma controlada sin dejar que el peso tire de ti.', 'Respira exhalando al empujar y evita balancear el tronco para ganar impulso.']::text[], 'principiante', 'Aísla el glúteo y los isquios, ayudando a tonificar y fortalecer la zona posterior de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7589'),
('7b50251d-1ab5-5329-9e14-433ae198e150', 'Corte antirrotación de rodillas en polea', ARRAY['Colócate de rodillas con la polea alta a un lado del cuerpo.', 'Sujeta el mango con ambas manos y mantén los brazos extendidos.', 'Lleva el mango de arriba abajo sin girar el tronco.', 'Aprieta el abdomen y evita que la cadera rote.']::text[], 'principiante', 'Entrena el core para resistir la rotación, mejorando la estabilidad del tronco y la protección lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7584'),
('eb442ab7-5522-51ec-bf03-28a7d140b377', 'Apertura de rodillas en polea de alto a bajo', ARRAY['Colócate de rodillas entre las poleas con los brazos abiertos.', 'Junta las manos delante del pecho describiendo un arco descendente.', 'Aprieta el pecho al final y controla la vuelta.', 'Evita arquear la espalda o encoger los hombros.']::text[], 'principiante', 'Trabaja el pectoral con un movimiento de aducción descendente, mejorando la fuerza y la definición del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6542'),
('f4cf8793-ad86-58d6-88f6-3118010f8e70', 'Abducción de cadera de rodillas en polea', ARRAY['Colócate de rodillas con la polea baja enganchada al tobillo.', 'Separa la pierna hacia fuera sin inclinar el tronco.', 'Mantén el abdomen activo y evita compensar con la cadera.', 'Vuelve despacio a la posición inicial.']::text[], 'principiante', 'Fortalece los abductores y el glúteo medio, mejorando la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6739'),
('04f639ec-7d57-5ad1-b949-bd0c86b70cff', 'Remo a un brazo inclinado de rodillas en polea', ARRAY['Colócate de rodillas e inclina el tronco hacia delante con la espalda recta.', 'Tira del mango hacia la cadera llevando el codo atrás.', 'Junta la escápula al final del recorrido y controla la vuelta.', 'Evita girar el tronco o encoger el hombro.']::text[], 'principiante', 'Fortalece el dorsal y la espalda alta de forma unilateral, mejorando la tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5518'),
('cdbfe90c-0134-55fd-bcca-0402e89afc5b', 'Press militar de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea baja con los mangos a la altura de los hombros.', 'Empuja hacia arriba hasta extender los brazos sin bloquear de golpe.', 'Mantén el abdomen apretado y evita arquear la espalda.', 'Baja controlando el movimiento hasta la altura inicial.']::text[], 'principiante', 'Desarrolla la fuerza del hombro y el tríceps en un press vertical que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11260'),
('7589b650-e06a-5496-955d-0d75e75f1d88', 'Jalón dorsal a un brazo de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea alta y sujeta el mango con una mano.', 'Tira hacia abajo llevando el codo hacia la cadera.', 'Aprieta el dorsal al final y controla la subida.', 'Evita inclinarte o girar el tronco para tirar.']::text[], 'principiante', 'Trabaja el dorsal de forma unilateral, mejorando la fuerza de tracción y la conexión mente-músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4948');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('6c848f5f-90f5-5a81-9c12-72a4760b6879', 'Remo a un brazo de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea baja y sujeta el mango con una mano.', 'Tira del mango hacia la cadera manteniendo el tronco estable.', 'Junta la escápula al final y baja controlando.', 'Evita rotar el tronco o encoger el hombro.']::text[], 'principiante', 'Fortalece el dorsal y la espalda media de forma unilateral, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5369'),
('45672a03-8084-5712-ad2a-e9707d364d7b', 'Curl predicador de rodillas en polea', ARRAY['Colócate de rodillas con el brazo apoyado y la polea baja.', 'Flexiona el codo llevando la mano hacia el hombro.', 'Aprieta el bíceps arriba y baja despacio.', 'Evita mover el hombro o balancear el tronco.']::text[], 'principiante', 'Aísla el bíceps con el brazo apoyado, mejorando la fuerza y el control en flexión de codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5297'),
('21cc345f-e903-50d6-84a4-8e544a2b10bc', 'Pull through de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea baja con la cuerda entre las piernas.', 'Lleva la cadera atrás y luego extiéndela hacia delante apretando el glúteo.', 'Mantén la espalda neutra y el abdomen activo.', 'Evita arquear la lumbar al final del movimiento.']::text[], 'principiante', 'Activa el glúteo y los isquiotibiales en extensión de cadera, mejorando la fuerza del tren posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3352'),
('36c139e2-4bcd-52bf-89af-b151911a74fe', 'Jalón de rodillas en polea', ARRAY['Colócate de rodillas frente a la polea alta y agarra el maneral con los brazos estirados.', 'Tira del cable hacia el pecho llevando los codos hacia abajo y atrás.', 'Controla la subida del peso durante dos segundos sin dejar que te arrastre.', 'Evita encoger los hombros o balancear el tronco para completar la repetición.']::text[], 'principiante', 'Fortalece la espalda y los bíceps tirando del cable hacia el pecho, mejorando la tracción vertical sin cargar la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11253'),
('603e0ebf-e44d-538e-b592-7d3a2507bcf8', 'Remo para deltoide posterior de rodillas en polea con cuerda', ARRAY['Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina.', 'Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti.', 'Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos.', 'Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa.', 'Libera lentamente la tensión y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla la parte trasera del hombro y la espalda alta, útil para equilibrar el empuje y mejorar la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3697'),
('d3e394e3-d84e-5615-949d-e04f993ddd34', 'Press con rotación externa de hombro a 90 grados de rodillas en polea', ARRAY['Colócate de rodillas con el codo a 90 grados y el brazo en línea con el hombro.', 'Empuja el cable hacia delante mientras giras el antebrazo hacia arriba.', 'Mantén el codo fijo y el core activo durante todo el recorrido.', 'Vuelve despacio a la posición inicial sin perder la rotación controlada.']::text[], 'principiante', 'Trabaja el hombro y el manguito rotador combinando empuje y rotación, mejorando la estabilidad y la salud articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5821'),
('3e2dd7c5-296f-509b-b275-f7468ae96d1b', 'Rotación externa de hombro de rodillas en polea', ARRAY['Colócate de rodillas con el codo pegado al costado y flexionado a 90 grados.', 'Gira el antebrazo hacia fuera sin separar el codo del cuerpo.', 'Aguanta un segundo arriba y vuelve despacio a la posición inicial.', 'Evita arquear la espalda o usar impulso para girar.']::text[], 'principiante', 'Refuerza el manguito rotador y la parte posterior del hombro, previniendo lesiones en movimientos de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6755'),
('3df123be-0f36-5f59-9e96-2a758c452ee9', 'Rotación interna de hombro de rodillas en polea', ARRAY['Colócate de rodillas con el codo pegado al costado y flexionado a 90 grados.', 'Gira el antebrazo hacia dentro del cuerpo de forma controlada.', 'Mantén el tronco firme y el codo sin moverse del costado.', 'Vuelve lentamente a la posición inicial sin soltar la tensión.']::text[], 'principiante', 'Fortalece el manguito rotador en rotación interna, complementando el trabajo de estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6756'),
('a4d97824-6f2a-513e-a269-69eb9afbf6ce', 'Abdominal lateral de rodillas en polea', ARRAY['Colócate de rodillas de lado a la polea con el cable por encima de la cabeza.', 'Flexiona el tronco hacia el lado de la polea llevando el codo hacia la cadera.', 'Sube controlando el movimiento sin tirar con los brazos.', 'Evita girar el tronco o usar impulso para completar la repetición.']::text[], 'principiante', 'Trabaja los oblicuos y el core con flexión lateral, mejorando la fuerza rotacional y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6693'),
('62236be6-e9fc-53ef-bd16-280777c4f064', 'Remo horizontal de rodillas a un brazo en polea', ARRAY['Colócate de rodillas frente a la polea y agarra el maneral con una mano.', 'Tira del cable hacia la cadera llevando el codo hacia atrás.', 'Mantén el tronco estable y evita girar el cuerpo al tirar.', 'Vuelve despacio estirando el brazo sin perder la posición.']::text[], 'principiante', 'Fortalece la espalda y el dorsal de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10667'),
('c13bbaf1-40c3-55f6-85cb-9d4c2ddc51b5', 'Extensión de tríceps de rodillas en polea', ARRAY['Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable.', 'Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza.', 'Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.', 'Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps en extensión vertical, útil para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0176'),
('a89fcf10-a9c7-5f71-9284-d04c3538aed0', 'Giro de rodillas en polea', ARRAY['Colócate de rodillas de lado a la polea con los brazos extendidos.', 'Gira el tronco llevando las manos hacia el lado contrario de la polea.', 'Mantén las caderas quietas y gira solo desde la cintura.', 'Vuelve despacio sin dejar que el peso te arrastre.']::text[], 'principiante', 'Trabaja los oblicuos y el core con rotación controlada, mejorando la fuerza rotacional y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6760'),
('aad7c427-7e85-530d-adac-62f96147222f', 'Leñador de rodillas en polea', ARRAY['Colócate de rodillas de lado a la polea alta con las manos juntas.', 'Tira del cable en diagonal hacia la cadera contraria.', 'Gira el tronco de forma controlada manteniendo los brazos estirados.', 'Vuelve despacio a la posición inicial sin usar impulso.']::text[], 'principiante', 'Trabaja oblicuos y core con un movimiento diagonal, mejorando la fuerza rotacional y la coordinación del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11251'),
('c55be4c5-9d26-5776-b527-fd72c293d1fc', 'Zancada lateral en polea', ARRAY['Colócate de pie con el cable sujeto a la altura de la cadera.', 'Da un paso lateral amplio y flexiona la rodilla de esa pierna.', 'Empuja con el pie para volver al centro manteniendo el tronco erguido.', 'Evita que la rodilla pase por delante de la punta del pie.']::text[], 'principiante', 'Fortalece glúteos y aductores con desplazamiento lateral, mejorando la fuerza y estabilidad en el plano frontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3350'),
('8dadc222-5537-5cea-b429-b4d953eaa1eb', 'Jalón lateral en polea con cuerda', ARRAY['Sujeta un accesorio de cuerda a la máquina de cable en una posición alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.', 'Mantén la espalda recta e inclínate ligeramente hacia atrás.', 'Jala la cuerda hacia los costados, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte baja del movimiento.', 'Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal con tracción lateral, mejorando la amplitud de la espalda y la fuerza de los bíceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0177'),
('400f5fe4-22f6-53fb-bc22-f9576002e4db', 'Jalón lateral en polea con agarre mag', ARRAY['Colócate de pie frente a la polea alta y agarra el maneral mag.', 'Tira del cable hacia el pecho llevando los codos hacia abajo.', 'Mantén el pecho alto y evita encoger los hombros.', 'Controla la subida del peso durante dos segundos.']::text[], 'principiante', 'Fortalece el dorsal con un agarre que mejora la activación, útil para ganar amplitud y fuerza en la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6392'),
('c24a2ec5-4a2b-58dc-aa3d-31923af0850a', 'Jalón lateral con barra V en polea', ARRAY['Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono.', 'Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella.', 'Mantén la espalda recta e inclínate ligeramente hacia atrás.', 'Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo.', 'Aprieta los músculos de la espalda en la parte baja del movimiento.', 'Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal y los bíceps con un agarre neutro, mejorando la fuerza de tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2616'),
('8ce2dabe-deda-5941-bc4b-42ab900aa011', 'Elevación lateral en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.', 'Mantén los brazos rectos y el core activado.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el deltoide medio con tensión constante, útil para ganar anchura y mejorar la estética del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0178'),
('ca7b3d26-f5da-5fd2-b863-c71c4e6a25c9', 'Subida lateral al cajón en polea', ARRAY['Colócate de lado al cajón con la polea anclada baja y el mango en la mano contraria a la pierna que sube.', 'Apoya el pie de fuera sobre el cajón y empuja con el talón para subir, manteniendo el torso erguido.', 'Controla la bajada hasta rozar el suelo con el pie libre sin dejarlo caer.', 'Evita empujar con la pierna de abajo o inclinarte hacia el lado de la polea.']::text[], 'principiante', 'Trabaja glúteos y cuádriceps con apoyo de isquios y core, mejorando fuerza y estabilidad en una sola pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10119'),
('e19870d6-84f6-5f1b-be67-ee7999e1ee50', 'Elevación lateral inclinado en polea', ARRAY['Sujeta el mango de la polea baja con la mano contraria y apóyate en una estructura para inclinar el torso.', 'Con el brazo casi recto, eleva el mango hacia el lado hasta la altura del hombro.', 'Baja despacio controlando la polea sin dejar que tire de ti.', 'Evita encoger el hombro o usar impulso del tronco para subir el peso.']::text[], 'principiante', 'Aísla el deltoides medio con el torso inclinado, ganando rango y tensión constante en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3880'),
('dadeda4b-5290-5f7f-bde4-aa5b89874508', 'Press de pecho bajo en polea', ARRAY['Coloca la polea a la altura de la cadera y sujeta los mangos con los codos pegados al cuerpo.', 'Empuja hacia delante y arriba hasta juntar las manos delante del pecho.', 'Vuelve despacio hasta notar estiramiento en el pecho sin perder la postura.', 'Evita arquear la espalda o bloquear los codos de golpe al final.']::text[], 'principiante', 'Empuja el pectoral desde abajo con tensión continua, útil para trabajar la porción superior del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5814'),
('c53702fc-47ff-5773-85e7-c22d6825d1d6', 'Apertura baja en polea', ARRAY['Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado.', 'Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.', 'Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos.', 'Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo.', 'Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho.', 'Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Abre los brazos desde abajo para aislar el pectoral y estirar la fibra con tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0179'),
('1a67e588-7f65-5dcb-951f-7f70e22d1514', 'Remo bajo con cuerda en polea', ARRAY['Siéntate con los pies apoyados y sujeta la cuerda con los brazos estirados.', 'Tira de la cuerda hacia el abdomen llevando los codos atrás y juntando las escápulas.', 'Aguanta un instante arriba y vuelve despacio sin redondear la espalda.', 'Evita tirar con los brazos o balancear el tronco para mover el peso.']::text[], 'principiante', 'Fortalece la espalda media y los dorsales con agarre neutro, mejorando la postura y la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4391'),
('9859f499-a433-5b1c-91bc-2828772eebd8', 'Remo sentado bajo en polea', ARRAY['Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.', 'Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los bíceps con un tirón horizontal, base para una postura fuerte.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0180'),
('2779189f-66b8-5b1b-b524-b7567f90dfb3', 'Remo bajo sentado en polea con barra V', ARRAY['Siéntate con los pies en la plataforma y sujeta la barra V con los brazos estirados.', 'Tira hacia el abdomen llevando los codos cerca del cuerpo y juntando las escápulas.', 'Vuelve despacio hasta estirar los brazos sin perder la espalda neutra.', 'Evita encorvarte o tirar con impulso del tronco.']::text[], 'principiante', 'Refuerza espalda media y dorsales con agarre neutro, mejorando fuerza de tracción y control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6032'),
('3c964db8-c128-54ee-9d1f-61868e5b834f', 'Zancada en polea', ARRAY['Sujeta el mango de la polea baja y da un paso atrás con una pierna.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se vaya hacia dentro o que el tronco se incline.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos en patrón unilateral, mejorando equilibrio y fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3351'),
('75f6577c-3ab9-5179-82ef-895928d3e4cb', 'Navaja alterna con rodilla flexionada en polea', ARRAY['Túmbate boca arriba con la polea baja sujeta a los pies o tobillos.', 'Flexiona una rodilla y lleva la otra pierna hacia el pecho alternando el movimiento.', 'Sube el tronco ligeramente contrayendo el abdomen en cada repetición.', 'Evita tirar con el cuello o arquear la zona lumbar al subir.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con control, reforzando el core de forma dinámica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11262'),
('1114721b-03ae-573d-8b1e-fb6df715f369', 'Elevación lateral cruzada acostado en banco en polea', ARRAY['Túmbate de lado en el banco con la polea baja sujeta con la mano de arriba.', 'Con el brazo casi recto, eleva el mango cruzando por delante del cuerpo.', 'Baja despacio hasta notar estiramiento sin perder la posición del hombro.', 'Evita encoger el hombro o girar el tronco para subir el peso.']::text[], 'principiante', 'Aísla el deltoides con el torso tumbado, logrando tensión constante y buen rango en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9872'),
('4e7b7667-227a-501c-bda3-70fde37b5eaf', 'Elevación lateral cruzada a un brazo acostado en banco en polea', ARRAY['Túmbate de lado en el banco con la polea baja sujeta con una sola mano.', 'Eleva el brazo casi recto cruzando por delante del cuerpo hasta la altura del hombro.', 'Baja despacio controlando la tensión de la polea.', 'Evita compensar con el tronco o encoger el hombro al subir.']::text[], 'principiante', 'Trabaja el deltoides de forma unilateral tumbado, ganando control y rango en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9873'),
('117b2f51-aa72-5c9a-bd64-1b88b62955ec', 'Curl de bíceps acostado en polea', ARRAY['Túmbate boca arriba con la polea baja sujeta con las manos y los brazos estirados.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Baja despacio hasta estirar del todo el bíceps.', 'Evita despegar los codos del cuerpo o usar impulso del tronco.']::text[], 'principiante', 'Aísla el bíceps tumbado con tensión constante, útil para controlar el rango y evitar balanceos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2396'),
('7d70bb0e-ceea-5d70-8f28-70e0941a959b', 'Curl acostado con agarre cerrado en polea', ARRAY['Túmbate boca arriba con la polea baja sujeta con agarre cerrado y brazos estirados.', 'Flexiona los codos llevando las manos hacia el pecho sin separar los codos.', 'Baja despacio hasta estirar el bíceps por completo.', 'Evita mover los hombros o tirar con la espalda para subir el peso.']::text[], 'principiante', 'Trabaja el bíceps y el braquial con agarre cerrado, aumentando control y tensión en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0181'),
('ffb1dac7-3592-5120-9238-d799cc445739', 'Press con agarre cerrado acostado en polea', ARRAY['Túmbate boca arriba con la polea baja sujeta con agarre cerrado y codos pegados al cuerpo.', 'Empuja hacia arriba estirando los codos sin separarlos del torso.', 'Baja despacio hasta que las manos queden cerca del pecho.', 'Evita abrir los codos o arquear la espalda al empujar.']::text[], 'principiante', 'Fortalece el tríceps tumbado con agarre cerrado, con apoyo secundario de pecho y hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3362'),
('183a9122-47ab-5f12-a2c1-3e27b6d98e70', 'Curl acostado en polea', ARRAY['Túmbate boca arriba con la polea baja sujeta con las manos y los brazos estirados.', 'Flexiona los codos llevando las manos hacia los hombros manteniendo los brazos fijos.', 'Baja despacio hasta estirar el bíceps sin soltar la tensión.', 'Evita despegar los codos o usar impulso del tronco para subir.']::text[], 'principiante', 'Aísla el bíceps tumbado con tensión continua, ideal para controlar el recorrido y la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0183'),
('3ddc1778-b4e9-5a9c-9a73-6c2fd929f6de', 'Pullover con extensión en polea con cuerda', ARRAY['Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta.', 'Túmbate en un banco con la cabeza orientada hacia la máquina de cable.', 'Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control.', 'Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales y tríceps con un recorrido largo que estira la espalda y fortalece el empuje del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0184'),
('137593cb-c3fc-5cd7-a44d-1a20272085bc', 'Face pull acostado en polea', ARRAY['Túmbate boca arriba con la polea baja y agarra la cuerda con las palmas enfrentadas.', 'Lleva los codos hacia atrás y tira de la cuerda hacia la cara separando las manos.', 'Aprieta los omóplatos al final del recorrido y aguanta un segundo.', 'Vuelve despacio controlando la polea sin perder la tensión.', 'Evita encoger los hombros hacia las orejas durante todo el movimiento.']::text[], 'principiante', 'Refuerza deltoides posterior, romboides y manguito rotador para mejorar la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7591'),
('56768c87-cc9b-555d-9235-e734e4a29e08', 'Elevación frontal acostado en polea', ARRAY['Túmbate en el suelo con la polea baja detrás de la cabeza y agarra el maneral.', 'Con el brazo casi recto, eleva la mano hacia el techo hasta la vertical.', 'Sube en dos segundos y baja en tres, sin bloquear la respiración.', 'Mantén la muñeca neutra y el hombro pegado al suelo.', 'Evita arquear la zona lumbar o usar impulso del tronco.']::text[], 'principiante', 'Aísla el deltoides anterior y el pecho superior, útil para ganar fuerza en el hombro con apoyo estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9705'),
('5840a833-e198-562a-aacb-5591a58c2dba', 'Apertura acostado en polea', ARRAY['Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo.', 'Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho.', 'Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el pectoral con un estiramiento controlado que mejora la amplitud y la conexión en el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0185'),
('56851c51-9530-5ca0-81d5-c309f0afd29a', 'Flexión de cadera en polea', ARRAY['Túmbate boca arriba con la polea baja y engancha el pie en el maneral.', 'Lleva la rodilla hacia el pecho manteniendo la espalda apoyada.', 'Empuja con el pie para volver a la posición inicial de forma lenta.', 'Mantén el core firme y evita que la lumbar se despegue del suelo.', 'No uses impulso con la otra pierna ni con los brazos.']::text[], 'principiante', 'Trabaja cuádriceps y flexores de cadera con una sentadilla invertida que mejora el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8876'),
('4651dee6-6f2d-5d6e-ac9e-5972ccc588a3', 'Elevación lateral de pierna en polea', ARRAY['Colócate de lado en una superficie inclinada con la polea baja en el tobillo externo.', 'Eleva la pierna hacia arriba manteniéndola recta y el pie en flexión neutra.', 'Sube en dos segundos y baja controlando sin dejar caer la pierna.', 'Mantén el tronco alineado y el core activo para no rotar.', 'Evita compensar inclinando la cadera o usando impulso.']::text[], 'principiante', 'Activa glúteo medio y abductores para estabilizar la cadera y prevenir lesiones en la carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9927'),
('0e4085e7-91c9-5bf0-af92-335b4eaa4964', 'Patada de pierna a una pierna en polea', ARRAY['Colócate inclinado hacia delante con la polea baja enganchada al tobillo.', 'Lleva la pierna hacia atrás con la rodilla ligeramente flexionada.', 'Aprieta el glúteo al final y aguanta un segundo sin arquear la lumbar.', 'Vuelve despacio manteniendo la tensión en la polea.', 'Evita balancear el tronco o girar la cadera al empujar.']::text[], 'principiante', 'Aísla el glúteo mayor y los isquios con un gesto que mejora la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9928'),
('8db626be-e8f2-5da1-a3b3-45c742c6e911', 'Press pallof acostado en polea', ARRAY['Túmbate boca arriba con la polea a un lado y agarra el maneral con ambas manos.', 'Extiende los brazos hacia el techo manteniendo la polea en tensión.', 'Resiste la rotación del tronco y mantén la cadera y los hombros alineados.', 'Respira con normalidad y aguanta la posición el tiempo indicado.', 'Evita girar la cadera o dejar que la polea te lleve hacia un lado.']::text[], 'principiante', 'Entrena la antirotación del core y los oblicuos para ganar estabilidad en el tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4224'),
('fefe0638-cb81-5e49-a430-f13aa68c57b5', 'Curl acostado con agarre normal en polea', ARRAY['Túmbate boca arriba con la polea baja y agarra el maneral con las palmas hacia arriba.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Sube en dos segundos y baja en tres controlando la polea.', 'Mantén las muñecas neutras y los codos pegados al cuerpo.', 'Evita arquear la espalda o usar impulso del tronco.']::text[], 'principiante', 'Aísla el bíceps y el braquial con un apoyo que reduce el impulso y mejora la conexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4350'),
('96746724-a0ba-549a-a971-fe1b74fb01f2', 'Encogimientos acostado en polea', ARRAY['Túmbate boca arriba con la polea baja y agarra el maneral con ambas manos.', 'Eleva los hombros hacia las orejas sin doblar los codos.', 'Aprieta el trapecio arriba un segundo y baja despacio.', 'Mantén el cuello relajado y la mirada al techo.', 'Evita tirar con los brazos o encoger el cuello en exceso.']::text[], 'principiante', 'Fortalece el trapecio superior y la espalda alta para mejorar la estabilidad del cuello y los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4226'),
('fe2e7016-19f2-5190-af4d-2d6c01d4cf08', 'Elevación lateral cruzada a un brazo en polea', ARRAY['Túmbate boca arriba con la polea baja a un lado y agarra el maneral con una mano.', 'Eleva el brazo en diagonal por delante del cuerpo hasta la altura del hombro.', 'Controla el descenso sin dejar que la polea tire del brazo.', 'Mantén el hombro bajo y el core activo para no rotar.', 'Evita encoger el cuello o usar impulso del tronco.']::text[], 'principiante', 'Trabaja el deltoides lateral y posterior con un cruce que mejora el control y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9874'),
('c0fe264a-16fd-59c2-b14a-8dedacf8fb71', 'Flexión de cadera a una pierna en polea', ARRAY['Túmbate boca arriba con la polea baja enganchada a un tobillo.', 'Lleva la rodilla hacia el pecho manteniendo la espalda apoyada.', 'Empuja con el pie para volver despacio a la posición inicial.', 'Mantén el core firme y evita que la lumbar se despegue.', 'No uses impulso con la otra pierna ni con los brazos.']::text[], 'principiante', 'Fortalece cuádriceps y flexores de cadera con un gesto unilateral que mejora el control pélvico.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8875'),
('44d0a8d1-a4db-5d54-b805-fc886e20f856', 'Extensión de tríceps acostado en polea', ARRAY['Túmbate boca arriba con la polea baja y agarra la cuerda con ambas manos.', 'Con los codos fijos, extiende los brazos hacia el techo sin mover los hombros.', 'Baja la cuerda hacia la frente controlando la polea.', 'Mantén las muñecas neutras y los codos apuntando al techo.', 'Evita abrir los codos o arquear la espalda al empujar.']::text[], 'principiante', 'Aísla el tríceps con un recorrido completo que mejora la fuerza del brazo y la estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5243'),
('0042c817-c0cf-50df-a676-3d3fd22ef5d2', 'Remo al mentón acostado en polea', ARRAY['Túmbate boca arriba con la polea baja y agarra el maneral con las palmas hacia abajo.', 'Tira del maneral hacia el mentón llevando los codos hacia arriba y afuera.', 'Sube hasta la altura del pecho sin encoger el cuello.', 'Baja despacio controlando la polea y manteniendo la tensión.', 'Evita usar impulso del tronco o subir los hombros hacia las orejas.']::text[], 'principiante', 'Trabaja deltoides y trapecio con un tirón vertical que mejora la fuerza del hombro y la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4225'),
('4752af21-c9ee-5190-aefb-975c2167402e', 'Patada trasera para glúteo medio en polea', ARRAY['Colócate de lado a la polea con el tobillo en la tobillera y sujétate para mantener el equilibrio.', 'Lleva la pierna hacia atrás y ligeramente en diagonal manteniendo el tronco firme.', 'Controla la vuelta sin dejar que el peso tire de ti y evita arquear la zona lumbar.', 'Respira exhalando al empujar y mantén el abdomen activo en todo el recorrido.']::text[], 'principiante', 'Trabaja el glúteo medio y estabilizadores de cadera para mejorar la abducción y la estabilidad de la pelvis al caminar o correr.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5470'),
('033ccb1d-7602-5e9a-b97c-2313d182e240', 'Levantarse de silla en polea con agarre cerrado', ARRAY['Siéntate en la silla frente a la polea baja y agarra el manejador con las dos manos.', 'Empuja con los pies y extiende las piernas para ponerte de pie manteniendo la espalda recta.', 'Baja controlando el movimiento hasta rozar la silla sin dejarte caer.', 'Evita juntar las rodillas hacia dentro y exhala al subir.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos imitando el gesto de sentarse y levantarse, útil para la vida diaria y la estabilidad de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2835'),
('d0fa66b6-3a1b-5017-8ae8-b0941299ec89', 'Patada atrás con agarre neutro en polea', ARRAY['Inclínate ligeramente hacia delante con el codo pegado al costado y agarre neutro.', 'Extiende el antebrazo hacia atrás hasta estirar el codo sin mover el hombro.', 'Vuelve despacio controlando el peso y evita balancear el tronco.', 'Exhala al extender y mantén el codo fijo durante todo el recorrido.']::text[], 'principiante', 'Aísla el tríceps para ganar fuerza en la extensión del codo, con apoyo de hombro y antebrazo en el gesto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4566'),
('b9276e57-f1b6-5af4-9b6b-6b0799146e13', 'Jalón al pecho con agarre neutro en polea', ARRAY['Siéntate con los muslos bajo el soporte y agarra la barra con las palmas enfrentadas.', 'Baja la barra hacia el pecho llevando los codos hacia abajo y atrás.', 'Controla la subida sin dejar que los hombros se eleven hacia las orejas.', 'Exhala al tirar y evita echar el tronco muy atrás para hacer fuerza.']::text[], 'principiante', 'Desarrolla la espalda y los dorsales con un agarre que respeta el hombro, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7583'),
('e04408a6-e3eb-56b1-a9ee-2d8309857518', 'Jalón al pecho abierto con agarre neutro en polea', ARRAY['Siéntate con la espalda recta y agarra la barra con las palmas enfrentadas y las manos separadas.', 'Tira de la barra hacia la parte alta del pecho abriendo los codos hacia los lados.', 'Sube despacio manteniendo el control y sin encoger los hombros.', 'Exhala al bajar la barra y evita arquear la zona lumbar.']::text[], 'principiante', 'Trabaja dorsales y espalda alta con un agarre amplio que enfatiza la apertura del pecho y la amplitud de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9304'),
('e7e8c728-e46e-5f5f-b0d3-d1e4f66dacd6', 'Curl de bíceps a un brazo en polea', ARRAY['Colócate frente a la polea baja con el codo pegado al costado y la palma hacia arriba.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo.', 'Baja controlando el peso hasta estirar casi del todo el codo.', 'Exhala al subir y evita balancear el tronco para ayudar.']::text[], 'principiante', 'Aísla el bíceps de un brazo para corregir desequilibrios y ganar fuerza en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2656'),
('38edb779-ba8a-5746-8072-ba8c1b92dc77', 'Curl a un brazo en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.', 'Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el bíceps y el antebrazo de forma unilateral, ayudando a equilibrar la fuerza entre ambos brazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0190'),
('343e0936-41ac-57a9-86b2-970bcf6b303d', 'Elevación frontal a un brazo en polea', ARRAY['Colócate de espaldas a la polea con el manejador en la mano y el brazo extendido.', 'Eleva el brazo hacia delante hasta la altura del hombro sin bloquear la espalda.', 'Baja despacio controlando el peso y sin dejar que el hombro se encoja.', 'Exhala al subir y evita usar impulso del tronco.']::text[], 'principiante', 'Trabaja el deltoides anterior y la parte alta del pecho para mejorar la fuerza al elevar el brazo por delante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2689'),
('df6ca41d-db1f-5af8-8acd-d7711f4f6133', 'Extensión de tríceps a un brazo sobre la cabeza en polea alta', ARRAY['Colócate de espaldas a la polea alta con el codo apuntando hacia arriba junto a la cabeza.', 'Extiende el antebrazo hacia delante hasta estirar el codo sin mover el hombro.', 'Vuelve despacio dejando que el codo se flexione detrás de la cabeza.', 'Exhala al extender y evita arquear la zona lumbar.']::text[], 'principiante', 'Estira el tríceps en posición alargada para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3353'),
('13f35c5a-6b1d-5ecf-8760-9cd004f520fa', 'Press inclinado a un brazo en polea', ARRAY['Ajusta la máquina de cable a una posición de polea baja.', 'Siéntate en un banco inclinado de espaldas a la máquina de cable.', 'Sujeta la agarradera con una mano y llévala hasta la altura del hombro.', 'Coloca los pies firmemente en el suelo y mantén una posición estable.', 'Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Trabaja el pecho en un ángulo inclinado de forma unilateral, mejorando la fuerza de empuje y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1265'),
('914bdeb2-bbbd-54b9-8aca-37ccbf0ac1cd', 'Press inclinado a un brazo en balón de estabilidad (polea)', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.', 'Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado.', 'Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'principiante', 'Combina el empuje de pecho con el control del core sobre el balón, mejorando el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1266'),
('3ac0b961-7294-5e17-af86-76e9eaf615d7', 'Curl de bíceps interno a un brazo en polea', ARRAY['Colócate frente a la polea baja con el codo pegado al costado y la palma girada hacia dentro.', 'Flexiona el codo girando la muñeca hacia arriba al final del recorrido.', 'Baja controlando el peso hasta estirar el codo casi por completo.', 'Exhala al subir y evita mover el hombro o el tronco.']::text[], 'principiante', 'Enfatiza el bíceps y el braquial con una rotación que mejora la fuerza en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1203'),
('3fc249c8-80cd-5b8a-8426-8f8a80555dad', 'Jalón al pecho a un brazo en polea', ARRAY['Siéntate o colócate de pie frente a la polea alta y agarra el manejador con una mano.', 'Tira hacia el costado del pecho llevando el codo hacia abajo y atrás.', 'Sube despacio controlando el peso sin encoger el hombro.', 'Exhala al tirar y evita girar el tronco para ayudar.']::text[], 'principiante', 'Trabaja el dorsal de forma unilateral para corregir diferencias de fuerza y mejorar la tracción de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1204'),
('397e6f2c-753e-5562-8e06-03feb6456897', 'Elevación lateral a un brazo inclinado en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable.', 'Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.', 'Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo.', 'Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Trabaja el deltoides y la parte alta del pecho con el tronco inclinado, mejorando la fuerza en la apertura del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0191'),
('10faa7b1-96f0-58e9-82fd-3b29be80645e', 'Elevación lateral a un brazo en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.', 'Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.', 'Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Aísla el deltoides lateral para ganar amplitud de hombro y mejorar la estética de la parte superior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0192'),
('7188e366-faa4-5bfd-bf67-9b729838f266', 'Press a un brazo en balón de estabilidad en polea', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado.', 'Coloca la otra mano en la cadera para mantener el equilibrio.', 'Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Trabaja el pectoral con apoyo de hombro y tríceps, mejorando la estabilidad del core sobre superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1267'),
('cce87b04-2d52-5204-8797-3e26fd1803ca', 'Jalón a un brazo en polea', ARRAY['Sujeta una agarradera individual a una máquina de cable con polea alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la agarradera con un agarre prono y extiende el brazo por completo.', 'Mantén la espalda recta y el core activado.', 'Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo.', 'Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal.', 'Suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de lado y repite el ejercicio con el otro brazo.']::text[], 'avanzado', 'Aísla el dorsal trabajando también bíceps y antebrazo, útil para corregir desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3563'),
('fb65b629-564a-58d9-a64b-9967f1676130', 'Apertura invertida a un brazo en polea', ARRAY['Colócate de pie frente a la polea con el brazo extendido y el codo ligeramente flexionado.', 'Lleva el brazo hacia atrás en arco, abriendo el pecho, sin encoger el hombro.', 'Controla el retorno durante dos segundos y evita usar impulso del tronco.', 'Mantén el core activo y respira exhalando al abrir el brazo.']::text[], 'principiante', 'Fortalece el deltoides posterior y la espalda alta, clave para la postura y el equilibrio de hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4122'),
('827771fd-03bc-5dfc-8352-48ac4d15e5c7', 'Curl predicador inverso a un brazo en polea', ARRAY['Ajusta la máquina de cable de modo que la polea quede en la posición más baja.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla.', 'Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.', 'Baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de brazo y repite el ejercicio.']::text[], 'principiante', 'Trabaja el bíceps y el antebrazo con agarre prono, reforzando la muñeca y el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1635'),
('27cf8e08-f57a-5e31-b63a-eb1927e06056', 'Extensión lateral de tríceps a un brazo en polea', ARRAY['Sitúate de lado a la polea con el codo pegado al costado y flexionado.', 'Extiende el codo hacia abajo hasta estirar el brazo por completo.', 'Vuelve despacio sin dejar que el codo se separe del torso.', 'Evita balancear el hombro y exhala al extender.']::text[], 'principiante', 'Aísla el tríceps desde un ángulo lateral, mejorando el tono y la extensión completa del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1609'),
('a872b2b3-7b58-5233-b794-41f4b59ab323', 'Remo alto a un brazo con espalda recta en polea de rodillas', ARRAY['Sujeta una agarradera a una máquina de cable a la altura de la cintura.', 'Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano.', 'Mantén la espalda recta y el core activado.', 'Jala la agarradera hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta del movimiento.', 'Suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de lado y repite el ejercicio con el otro brazo.']::text[], 'principiante', 'Trabaja la espalda alta y el bíceps desde una posición estable, favoreciendo la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0193'),
('03110fa0-8a98-57d5-819e-b507c3cf19c7', 'Remo sentado con giro a un brazo en polea', ARRAY['Siéntate con la espalda recta y agarra el maneral con un brazo extendido.', 'Tira del codo hacia atrás mientras giras suavemente el tronco hacia ese lado.', 'Vuelve al centro controlando el retorno y sin redondear la espalda.', 'Mantén el core firme y exhala durante la tracción.']::text[], 'principiante', 'Fortalece la espalda alta y los oblicuos combinando tracción y rotación controlada del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1205'),
('46fa3708-0845-5285-a4f6-4f45196635cb', 'Curl de muñeca a un brazo en polea', ARRAY['Apoya el antebrazo en el muslo con la muñeca fuera de la rodilla y la palma hacia arriba.', 'Flexiona la muñeca llevando la mano hacia ti sin mover el antebrazo.', 'Baja despacio hasta la extensión completa y controla el peso.', 'Evita usar el codo o el hombro y respira de forma constante.']::text[], 'principiante', 'Refuerza los flexores de la muñeca y la fuerza de agarre, útil para prevenir molestias en el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4163'),
('fdd7e879-9be4-54bd-bc41-ef98cf78035f', 'Curl sobre la cabeza en polea', ARRAY['Sujeta una barra recta a una máquina de cable con polea alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil.', 'Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.', 'Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el bíceps desde un ángulo elevado, estirando el músculo y mejorando el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1636'),
('166cab34-0c10-5218-ba8f-44ba74796006', 'Curl sobre la cabeza en balón de estabilidad en polea', ARRAY['Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino.', 'Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas.', 'Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil.', 'Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Combina curl de bíceps con inestabilidad del balón, activando el core y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1637'),
('9e21981b-4b8d-5726-a8ef-34b5c7c2b205', 'Extensión de tríceps sobre la cabeza a un brazo en polea con cuerda', ARRAY['De espaldas a la polea, sujeta la cuerda con una mano detrás de la cabeza y el codo apuntando arriba.', 'Extiende el codo hacia delante hasta estirar el brazo sin mover el hombro.', 'Vuelve despacio manteniendo el codo fijo y cerca de la cabeza.', 'Activa el core y evita arquear la zona lumbar.']::text[], 'principiante', 'Aísla el tríceps en estiramiento con apoyo del core, mejorando la extensión completa del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4958'),
('9c460e98-437b-5288-9e29-b152d352962e', 'Sentadilla con brazos sobre la cabeza en polea', ARRAY['Colócate de frente a la polea con los brazos extendidos sobre la cabeza y los pies a la anchura de hombros.', 'Baja en sentadilla llevando la cadera atrás y manteniendo el pecho alto.', 'Empuja con los talones para subir sin perder la posición de los brazos.', 'Evita que las rodillas se metan hacia dentro y respira exhalando al subir.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos con demanda de hombros y core, mejorando la sentadilla profunda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11252'),
('b51c81e3-b403-5a35-bde4-c329243fa194', 'Extensión de tríceps sobre la cabeza con barra recta en polea', ARRAY['De espaldas a la polea, agarra la barra con las manos y llévala detrás de la cabeza con los codos altos.', 'Extiende los codos hasta estirar los brazos delante de la cabeza.', 'Vuelve despacio sin abrir los codos ni mover los hombros.', 'Mantén el abdomen firme y exhala al extender.']::text[], 'principiante', 'Aísla el tríceps en estiramiento con barra, reforzando la extensión del codo y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4115'),
('45a4464e-db8a-583d-bc6e-2918921c7746', 'Extensión de tríceps sobre la cabeza en polea con cuerda', ARRAY['Sujeta una cuerda a una máquina de cable en una posición alta.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza.', 'Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante.', 'Baja lentamente la cuerda detrás de la cabeza flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el tríceps en posición de estiramiento, mejorando la fuerza y el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0194'),
('7ff59c26-7e3c-5fc4-af8e-2e5fe4e98746', 'Press pallof con puente de glúteos en polea', ARRAY['Túmbate boca arriba con la polea a un lado y sujeta el maneral con ambas manos sobre el pecho.', 'Eleva la cadera en puente de glúteos manteniendo las costillas abajo.', 'Empuja el maneral hacia delante sin dejar que el tronco rote.', 'Aguanta un segundo, vuelve al pecho y baja la cadera con control.']::text[], 'principiante', 'Combina antirrotación del core con activación de glúteos, mejorando estabilidad y control lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4197'),
('84d9ea43-eac7-507a-a630-8516050a91a8', 'Remo con rotación de palma en polea', ARRAY['Sujeta una agarradera a una máquina de cable a la altura de la cintura.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la agarradera con un agarre prono, con las palmas hacia abajo.', 'Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces.', 'Aprieta los omóplatos al final del movimiento.', 'Suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides, mejorando la postura y la estabilidad escapular en el tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1319'),
('3716a369-ff16-594f-b89e-a453c4497248', 'Jalón al pecho con agarre paralelo en polea', ARRAY['Siéntate frente a la polea con el agarre paralelo y los brazos estirados.', 'Tira del agarre hacia el pecho llevando los codos hacia abajo y atrás.', 'Junta las escápulas al final del recorrido y controla la vuelta.', 'Evita balancear el tronco o encoger los hombros al tirar.']::text[], 'principiante', 'Trabaja los dorsales y la espalda alta, aumentando la amplitud del tirón vertical y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3358'),
('44ddf72f-cdbb-5134-8d51-0a5d39138ed3', 'Press en balón de estabilidad en polea', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados.', 'Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados.', 'Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa el pectoral y los hombros mientras el balón exige estabilidad constante del core y la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1268'),
('92929d4d-f896-58e5-b9d5-cd5ae40d3042', 'Curl de pierna a una pierna boca abajo en polea', ARRAY['Túmbate boca abajo con el tobillo enganchado a la polea y la pierna estirada.', 'Flexiona la rodilla llevando el talón hacia el glúteo sin mover la cadera.', 'Aprieta el isquiotibial arriba y baja controlando el movimiento.', 'Evita arquear la zona lumbar o dar tirones con la cadera.']::text[], 'principiante', 'Aísla los isquiotibiales y glúteos, mejorando la fuerza y el control de la flexión de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11276'),
('35bc090e-877d-56b9-99ed-b48d17ff48ec', 'Pull through en polea', ARRAY['Colócate de espaldas a la polea con la cuerda entre las piernas y los pies al ancho de hombros.', 'Lleva la cadera atrás con la espalda recta hasta sentir el estiramiento en los isquiotibiales.', 'Empuja la cadera adelante y aprieta los glúteos para volver de pie.', 'Evita redondear la espalda o tirar con los brazos en lugar de la cadera.']::text[], 'principiante', 'Trabaja glúteos e isquiotibiales con un patrón de bisagra de cadera que refuerza la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1206'),
('df30523d-dbdd-55da-9f9a-7902e6cc3eec', 'Jalón en polea', ARRAY['Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada.', 'Siéntate con la espalda recta y los pies apoyados planos en el suelo.', 'Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros.', 'Inclínate ligeramente hacia atrás y activa el core.', 'Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Desarrolla los dorsales y la fuerza de tracción vertical, con apoyo de bíceps y antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0198'),
('fb46c591-1d43-50ac-a982-32ff5ae51e78', 'Curl de bíceps con jalón en polea', ARRAY['Sujeta una barra recta a la máquina de cable en el ajuste más alto.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas.', 'Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.', 'Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps con tensión constante de la polea, favoreciendo el control y la congestión del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1638'),
('c012369f-26a6-5212-a442-300c4dffd9fd', 'Extensión de tríceps en polea', ARRAY['Sujeta una barra recta a una máquina de cable con polea alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.', 'Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos.', 'Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con tensión continua, útil para ganar fuerza y definición en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0201'),
('dc39ed20-90fa-5505-8b0d-f17232ee8a6c', 'Extensión de tríceps con brazos rectos en polea', ARRAY['Sujeta una barra recta a una máquina de cable con polea alta.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.', 'Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.', 'Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos.', 'Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales y tríceps con los brazos estirados, reforzando la extensión de hombro y la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0199'),
('7ba23120-1fc3-54fa-b1ba-82ebdfb2f4ef', 'Jalón de tríceps en polea con cuerda', ARRAY['Sujeta un accesorio de cuerda a una polea alta en una máquina de cable.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.', 'Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra.', 'Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.', 'Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con la cuerda, permitiendo un recorrido cómodo y una buena contracción final.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0200'),
('ae705fed-852c-5bc5-9e27-de7432b10072', 'Remo para deltoide posterior en polea', ARRAY['Agarra la barra paralela con los brazos estirados y el tronco ligeramente inclinado.', 'Tira de los codos hacia atrás y afuera, llevando la barra hacia el pecho.', 'Aprieta los omóplatos al final y vuelve controlando el movimiento.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'principiante', 'Enfoca el deltoide posterior y la espalda alta, equilibrando el hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6035'),
('01d3894c-8e85-53e9-aa8c-88a8542cdb28', 'Zancada trasera desde cajón en polea', ARRAY['Colócate de pie sobre el cajón con la polea enganchada a la cadera o al tobillo.', 'Da un paso atrás y baja la rodilla hacia el suelo manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se vaya hacia dentro o que el tronco se incline.']::text[], 'principiante', 'Fortalece glúteos y cuádriceps con un patrón unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2837'),
('16a2b5cc-03bd-5d77-8357-7aea0de9cca5', 'Jalón posterior en polea', ARRAY['Ajusta la máquina de cable de modo que la polea quede en la posición más alta.', 'Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado.', 'Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales y deltoides posteriores con un tirón hacia atrás que mejora la espalda y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0205'),
('635f5369-13a9-5833-9653-5d1cadfa9ddb', 'Abdominal reverso en polea', ARRAY['Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete.', 'Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo.', 'Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho.', 'Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa el recto abdominal y los flexores de cadera, reforzando el core con una flexión controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0873'),
('1ff60e30-4974-570d-9483-6ffea1937985', 'Curl inverso en polea', ARRAY['Coloca una barra recta en una máquina de cable con polea baja.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.', 'Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece bíceps y antebrazos con agarre prono, mejorando la fuerza de prensión y el equilibrio del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0206'),
('6123c1ec-3592-50e9-950a-da924c5e9e6e', 'Jalón al pecho con agarre inverso en polea', ARRAY['Colócate frente a la polea con las rodillas fijas bajo el soporte y agarra la barra con las palmas hacia ti.', 'Baja la barra hacia el pecho llevando los codos hacia abajo y atrás, sin balancear el torso.', 'Aprieta la espalda un segundo abajo y sube controlando el retorno.', 'Evita encoger los hombros o tirar con los brazos antes que con la espalda.']::text[], 'principiante', 'Trabaja el dorsal ancho y la espalda alta, mejorando la fuerza de tracción y la amplitud de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5123'),
('a8c83cd3-6b13-58cf-ac0f-2bdbb858ce12', 'Extensión de tríceps en polea con agarre inverso y barra SZ', ARRAY['Sujeta la barra SZ con las palmas hacia abajo y los codos pegados al cuerpo.', 'Extiende los codos empujando la barra hacia abajo hasta estirar del todo los brazos.', 'Controla la subida sin dejar que los codos se separen del torso.', 'Evita usar el peso del cuerpo o balancearte para completar la repetición.']::text[], 'principiante', 'Aísla el tríceps con un agarre que activa también los antebrazos, útil para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1606'),
('b1005f6d-0d9a-5de5-a731-a36f2df50ca2', 'Jalón al pecho con agarre inverso estrecho en polea', ARRAY['Agarra el maneral estrecho con las palmas hacia ti y siéntate con el torso erguido.', 'Tira del maneral hacia el pecho llevando los codos pegados al cuerpo.', 'Aprieta la espalda abajo y sube despacio controlando la fase excéntrica.', 'Evita inclinarte demasiado atrás o tirar con los brazos sin activar la espalda.']::text[], 'principiante', 'Enfoca el dorsal ancho y la espalda alta con mayor recorrido, reforzando también bíceps y antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10503'),
('0297d3f8-fcd2-551f-9707-001da597b4fb', 'Curl inverso a un brazo en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo.', 'Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el bíceps y el antebrazo con agarre prono, mejorando el equilibrio y la fuerza de flexión unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1413'),
('7ce78739-66dd-5b31-9781-14798e84298d', 'Curl predicador inverso en polea', ARRAY['Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.', 'Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos.', 'Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros.', 'Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps y el antebrazo con agarre inverso, ganando fuerza y control en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0209'),
('4da475cb-c373-5b58-a2ea-f9fad3b9ce69', 'Leñador inverso en polea', ARRAY['Colócate de lado a la polea con los pies firmes y agarra el maneral con ambas manos.', 'Rota el tronco llevando el maneral en diagonal hacia arriba, manteniendo los brazos extendidos.', 'Controla el retorno resistiendo la rotación y sin mover las caderas.', 'Evita tirar solo con los brazos o girar la cadera en lugar del tronco.']::text[], 'principiante', 'Trabaja el core y los oblicuos con rotación controlada, mejorando la estabilidad y la fuerza funcional del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8193'),
('9f019502-8431-5dcd-bf53-3a18ab4a08c3', 'Curl de muñeca inverso en polea', ARRAY['Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable.', 'Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo.', 'Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.', 'Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.', 'Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los extensores del antebrazo y la muñeca, mejorando el agarre y previniendo desequilibrios en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0210'),
('a295bf48-d148-5f54-a69a-b16846402bd4', 'Remo alto sentado a polea con agarre inverso', ARRAY['Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo.', 'Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.', 'Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.', 'Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los bíceps con un tirón horizontal que mejora la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0208'),
('87d50d15-ad0c-59d8-a081-ef566971cf40', 'Peso muerto rumano en polea', ARRAY['De pie frente a la polea baja, agarra el maneral con las palmas hacia ti y rodillas ligeramente flexionadas.', 'Lleva las caderas hacia atrás bajando el torso con la espalda recta hasta notar estiramiento en los isquios.', 'Empuja las caderas hacia delante para volver arriba apretando los glúteos.', 'Evita redondear la espalda o bajar más allá de tu movilidad.']::text[], 'principiante', 'Fortalece isquiotibiales y glúteos con un patrón de bisagra de cadera, mejorando la cadena posterior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6552'),
('f2bdef53-58b1-5701-88c0-217b370b5be3', 'Remo sentado cruzado con cuerda en polea', ARRAY['Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.', 'Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.', 'Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa la espalda alta y los bíceps con un recorrido cruzado que incide en romboides y dorsales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1320'),
('eee0bd78-f334-5dbd-a43a-91174bc40777', 'Remo sentado elevado con cuerda en polea', ARRAY['Siéntate en el asiento elevado frente a la máquina de cable.', 'Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra.', 'Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas.', 'Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda.', 'Haz una pausa por un momento en la posición de contracción completa.', 'Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la espalda alta y los bíceps con un tirón alto que trabaja trapecio y romboides.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1321'),
('dd7a04c4-458d-59f4-af7f-ef7b1a6d0798', 'Remo inclinado en banco con cuerda en polea', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja.', 'Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina.', 'Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta.', 'Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo.', 'Aprieta los omóplatos al final del movimiento.', 'Libera lentamente la tensión y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los hombros desde una posición inclinada que aísla el tirón y estabiliza el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1322'),
('7790858f-632a-5aaf-94d8-7eff391e01d8', 'Extensión de tríceps sobre la cabeza con cuerda en polea alta', ARRAY['Sujeta una cuerda a una polea alta y ajusta el peso según corresponda.', 'Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza.', 'Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo.', 'Baja lentamente la cuerda detrás de la cabeza flexionando los codos.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps en estiramiento, potenciando la fuerza y el volumen de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1724'),
('bbf6e261-e7d6-532a-b6ad-c8cec751cfe2', 'Extensión de tríceps tumbado con cuerda en polea', ARRAY['Sujeta una cuerda a una máquina de cable y colócala en la posición más baja.', 'Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable.', 'Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo.', 'Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el tríceps desde el suelo con tensión constante, útil para ganar fuerza y control en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1726'),
('8d5ef07c-1225-5392-9b95-d2b171a9e318', 'Curl predicador martillo a un brazo con cuerda en polea', ARRAY['Sujeta una agarradera de cuerda a una máquina de cable con polea baja.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba.', 'Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil.', 'Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Aísla el bíceps y el braquial con agarre neutro, ganando grosor en el brazo y fuerza en la flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1640'),
('5be04288-dc62-533a-84e7-999c2e5123f5', 'Remo sentado en polea con cuerda', ARRAY['Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos.', 'Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides, mejorando la postura y el control escapular en el tirón horizontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1323'),
('9b209042-1f65-5040-8e89-15c66912a8b3', 'Giro ruso en polea sobre balón', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.', 'Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.', 'Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha.', 'Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda.', 'Continúa alternando los giros el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el core y los oblicuos con rotación controlada, mejorando la estabilidad del tronco sobre superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0211'),
('4d70ea33-8f02-5a48-9e4b-f1cc574ea2cd', 'Press de pecho sentado en polea', ARRAY['Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda.', 'Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo.', 'Sujeta las agarraderas del cable con un agarre prono a la altura del hombro.', 'Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo.', 'Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Empuja el pectoral con tensión constante, implicando hombro y tríceps para ganar fuerza y volumen en el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2144'),
('b7529df8-a5b6-5007-baa0-f77c0c815dbf', 'Giro sentado con brazos cruzados en polea', ARRAY['Siéntate de lado a la polea con las rodillas flexionadas y los pies bien apoyados.', 'Cruza los brazos sobre el pecho y sujeta el asa con las manos cerca de los hombros.', 'Gira el tronco alejándote de la polea sin mover la cadera ni tirar con los brazos.', 'Vuelve despacio controlando la tensión y evita arquear la espalda o usar impulso.']::text[], 'principiante', 'Activa oblicuos y core con rotación controlada del tronco, útil para estabilidad y fuerza en movimientos rotacionales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4042'),
('d406a04e-66da-5f36-a6e9-aa25767f2442', 'Abdominal sentado en polea', ARRAY['Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas.', 'Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza.', 'Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.', 'Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Flexiona el tronco contra resistencia para trabajar el recto abdominal con carga progresiva y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0212'),
('65b635c4-2a60-5e04-b52d-86ecac7a3264', 'Curl sentado en polea', ARRAY['Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps con tensión continua de la polea, favoreciendo el control y la congestión del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1641'),
('5adf3eb7-92b0-5844-af70-5cde0721375b', 'Face pull sentado en polea con cuerda', ARRAY['Siéntate frente a la polea con la cuerda a la altura de la cara y los codos altos.', 'Tira de la cuerda hacia la frente separando las manos y llevando los codos hacia atrás.', 'Aprieta los omóplatos al final del recorrido y mantén un segundo.', 'Vuelve despacio sin dejar que los hombros se vayan hacia delante ni encoger el cuello.']::text[], 'principiante', 'Refuerza deltoides posterior y manguito rotador, equilibrando el hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5658'),
('5ef65637-80fc-5122-a149-cc5dc9b5a902', 'Curl concentrado a un brazo sentado en el suelo con polea', ARRAY['Siéntate en el suelo con las piernas abiertas y apoya el codo del brazo que trabaja en la cara interna del muslo.', 'Sujeta el asa con la palma hacia arriba y mantén el brazo extendido sin bloquear.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el tronco.', 'Baja controlando la polea y evita balancear el cuerpo o despegar el codo del muslo.']::text[], 'principiante', 'Aísla el bíceps y el braquial con el codo fijo, maximizando la contracción en el pico del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3925'),
('158d4209-abfa-596e-9d8c-862c42ebe689', 'Eversión de pie sentado en polea', ARRAY['Siéntate con la pierna extendida y coloca la banda o el asa en el borde externo del pie.', 'Mantén la rodilla estable y gira el pie hacia fuera contra la resistencia.', 'Aguanta un segundo arriba y vuelve despacio a la posición neutra.', 'Evita mover la pierna o compensar con la cadera durante el recorrido.']::text[], 'principiante', 'Fortalece los peroneos y la musculatura del tobillo, mejorando la estabilidad lateral del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6745'),
('3c4f0b21-d5a8-524a-a6ed-8a54c5c13308', 'Inversión de pie sentado en polea', ARRAY['Siéntate con la pierna extendida y engancha el asa en el borde interno del pie.', 'Gira el pie hacia dentro contra la resistencia manteniendo la rodilla quieta.', 'Aprieta un instante al final y vuelve controlando el movimiento.', 'No gires la cadera ni tires con la pierna para hacer más fuerza.']::text[], 'principiante', 'Trabaja la musculatura interna del tobillo y el pie, mejorando el control y la propiocepción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6746'),
('778ece24-6992-5efe-8cbd-af4031fb48ee', 'Remo alto sentado en polea con barra V', ARRAY['Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.', 'Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda.', 'Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfoca el dorsal y la espalda alta con un tirón horizontal, mejorando fuerza y control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0213'),
('62bc64a8-17dd-5bf7-bb31-b1e9e66d2642', 'Encogimientos horizontales sentado en polea', ARRAY['Siéntate frente a la polea con los brazos extendidos y las palmas enfrentadas.', 'Lleva los omóplatos hacia atrás y hacia abajo sin doblar los codos.', 'Aprieta un segundo al final del recorrido y mantén el cuello relajado.', 'Vuelve despacio sin encoger los hombros hacia las orejas ni usar impulso.']::text[], 'principiante', 'Trabaja el trapecio y la espalda alta con retracción escapular, mejorando la postura y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4111'),
('d5f713ff-0913-5f32-beb4-b951dacb5952', 'Curl inclinado sentado en polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada y los brazos colgando hacia atrás.', 'Sujeta el asa con las palmas hacia arriba y los codos ligeramente flexionados.', 'Flexiona los codos sin mover los hombros y aprieta arriba.', 'Baja despacio hasta notar el estiramiento y evita balancear el tronco.']::text[], 'principiante', 'Estira el bíceps en posición inclinada para trabajar la porción larga y ganar rango de movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11763'),
('29df4c94-882e-5f80-bf01-988ad3e26db8', 'Remo sentado enfocado en dorsales en polea', ARRAY['Siéntate con los pies apoyados y sujeta el asa con los brazos extendidos.', 'Inicia el movimiento llevando los codos hacia atrás y pegados al cuerpo.', 'Lleva el asa hacia el abdomen bajo apretando los dorsales.', 'Vuelve controlando la polea sin redondear la espalda ni tirar con los brazos.']::text[], 'principiante', 'Prioriza el dorsal en el tirón horizontal, mejorando la amplitud de la espalda y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5553'),
('fa81af8c-8991-512f-8f4a-ec52952939d2', 'Extensión de pierna sentado en polea', ARRAY['Siéntate con la espalda apoyada y el tobillo enganchado al accesorio de la polea baja.', 'Extiende la rodilla de forma controlada hasta estirar la pierna sin bloquear la articulación.', 'Baja despacio aguantando la tensión y evitando que el peso choque al final.', 'Mantén el tronco quieto y no balancees la cadera para ayudar al movimiento.']::text[], 'principiante', 'Aísla el cuádriceps para ganar fuerza y tono en la parte frontal del muslo, útil como complemento de sentadillas y prensa.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5664'),
('335faa64-2fe9-507a-88c3-d2e340f878a0', 'Extensión de cuello sentado en polea con arnés', ARRAY['Coloca el arnés en la cabeza y siéntate con la espalda recta frente a la polea baja.', 'Lleva la barbilla hacia el pecho flexionando el cuello lentamente.', 'Vuelve a la posición neutra sin echar la cabeza atrás de golpe.', 'Usa un peso ligero y evita tirones bruscos para proteger las vértebras cervicales.']::text[], 'principiante', 'Fortalece la musculatura posterior del cuello y la parte alta de la espalda, mejorando la estabilidad cervical y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2411'),
('95371e80-7021-5794-96fc-11f814dcb97f', 'Flexión de cuello sentado en polea con arnés', ARRAY['Ajusta el arnés y siéntate erguido con la polea por delante de la cara.', 'Baja la barbilla hacia el pecho de forma lenta y controlada.', 'Regresa despacio a la posición inicial sin dejar caer la cabeza atrás.', 'Mantén los hombros relajados y evita encogerlos durante el recorrido.']::text[], 'principiante', 'Trabaja los flexores profundos del cuello y la zona cervical anterior, ayudando a estabilizar la cabeza y prevenir molestias posturales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2412'),
('c48333bb-3b42-57be-874a-2c80084f3af7', 'Remo sentado en el suelo con cuerda en polea', ARRAY['Siéntate en el suelo frente a la polea baja con las piernas ligeramente flexionadas.', 'Agarra la cuerda y tira de ella hacia el abdomen juntando las escápulas.', 'Vuelve despacio estirando los brazos sin redondear la espalda.', 'Evita tirar con los brazos; inicia el movimiento desde la espalda.']::text[], 'principiante', 'Refuerza la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción en la vida diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3357'),
('db7ddd9c-618e-5174-8afb-94d051b28916', 'Remo sentado alternado a un brazo en polea', ARRAY['Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti.', 'Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado.', 'Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda.', 'Suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite con el otro brazo.', 'Alterna entre los brazos el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta de forma unilateral, corrigiendo desequilibrios entre lados y mejorando la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0214'),
('f749d0bf-b52a-59d9-8aaa-ec36d2218625', 'Curl concentrado sentado a un brazo en polea', ARRAY['Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla.', 'Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Aísla el bíceps de un brazo para ganar fuerza y volumen, controlando mejor la técnica y la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1642'),
('ef161ccc-8c4b-544e-9dae-9fdba831b3f2', 'Curl sobre la cabeza sentado en polea con barra SZ', ARRAY['Siéntate frente a la polea baja con la barra SZ agarrada en supinación.', 'Coloca los codos altos y fijos, y sube la barra hacia la frente.', 'Baja despacio hasta notar estiramiento en el bíceps sin mover los hombros.', 'Evita abrir los codos o arquear la espalda para completar la repetición.']::text[], 'principiante', 'Trabaja el bíceps en estiramiento junto con el braquial y los antebrazos, favoreciendo el desarrollo del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6266'),
('8b94dcda-ce49-5b23-9bcc-5929428afc04', 'Pullover sentado en polea', ARRAY['Siéntate de espaldas a la polea alta y agarra la barra con los brazos extendidos.', 'Lleva la barra hacia los muslos manteniendo los codos casi rectos.', 'Vuelve despacio hasta notar estiramiento en los dorsales sin arquear la espalda.', 'Mantén el abdomen activo y evita balancear el tronco.']::text[], 'principiante', 'Trabaja los dorsales en estiramiento junto con el pecho y el core, mejorando la amplitud y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4180'),
('9eb5e90b-3d2f-5312-8018-e184e6f6adcc', 'Apertura posterior sentado en polea con apoyo en el pecho', ARRAY['Siéntate con el pecho apoyado y agarra los manerales cruzados frente a ti.', 'Abre los brazos hacia atrás juntando las escápulas sin subir los hombros.', 'Vuelve despacio controlando la tensión en la parte posterior del hombro.', 'Usa un peso ligero y evita encoger el cuello durante el movimiento.']::text[], 'principiante', 'Fortalece el deltoides posterior y la espalda alta, equilibrando el hombro y mejorando la postura frente al ordenador.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3943'),
('ac721f41-daf4-580f-87dd-6003dff7d172', 'Elevación lateral posterior sentado en polea', ARRAY['Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.', 'Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti.', 'Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el deltoides posterior y los trapecios, ayudando a equilibrar el hombro y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0215'),
('c79e574d-e1e5-5318-a7b3-a9b4a2f095f0', 'Encogimientos inversos sentado en polea', ARRAY['Siéntate frente a la polea baja con los brazos extendidos y los hombros relajados.', 'Baja los hombros llevando las escápulas hacia abajo sin doblar los codos.', 'Mantén un segundo abajo y vuelve despacio a la posición inicial.', 'Evita encoger el cuello o usar impulso del tronco.']::text[], 'principiante', 'Trabaja el trapecio inferior y los romboides, mejorando la estabilidad escapular y la postura de la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7155'),
('47b3283e-2bcb-5609-bd7b-29e2507fbbfa', 'Remo sentado en polea', ARRAY['Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados.', 'Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los bíceps, mejorando la postura y la capacidad de tracción en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0861'),
('9c09b3b2-1c1b-5fb6-b5bd-e3a30c394bdf', 'Remo sentado en polea con barra V', ARRAY['Siéntate con los pies apoyados y agarra la barra V con los brazos extendidos.', 'Tira de la barra hacia el abdomen juntando las escápulas y manteniendo el pecho alto.', 'Vuelve despacio estirando los brazos sin redondear la espalda.', 'Evita tirar con los brazos o balancear el tronco hacia atrás.']::text[], 'principiante', 'Trabaja dorsales y espalda alta con un agarre neutro que mejora la tracción y el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2661'),
('bea69847-81b9-5a71-bd5d-ddc8a889a337', 'Retracción escapular sentado en polea', ARRAY['Siéntate frente a la polea baja con los brazos extendidos y el pecho alto.', 'Junta las escápulas hacia atrás sin doblar los codos.', 'Mantén un segundo la contracción y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'principiante', 'Activa la espalda alta y los romboides para mejorar la estabilidad de las escápulas y corregir la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11057'),
('a589ff13-7378-5f0e-b3e4-14f1877e8cbe', 'Rotación interna de hombro sentado en polea', ARRAY['Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo.', 'Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo.', 'Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo.', 'Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Fortalece el manguito rotador y la rotación interna del hombro, mejorando la estabilidad y la salud articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0216'),
('03da735a-8986-5332-b267-3cd2461ec6a2', 'Remo sentado a un brazo en polea', ARRAY['Siéntate frente a la polea con el torso erguido y sujeta el maneral con una mano.', 'Tira del codo hacia atrás pegándolo al costado sin rotar el tronco.', 'Aprieta el dorsal al final del recorrido y controla la vuelta.', 'Evita encoger el hombro o usar impulso del cuerpo.']::text[], 'principiante', 'Trabaja el dorsal de forma unilateral y mejora la estabilidad del core y la conexión mente-músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10112'),
('c886b8ef-076b-5d8c-84f4-114cda5756f8', 'Curl de bíceps a un brazo sentado en polea', ARRAY['Siéntate con la espalda recta y el codo apoyado junto al cuerpo.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo.', 'Baja despacio controlando la polea hasta extender casi del todo.', 'Evita balancear el tronco o adelantar el codo.']::text[], 'principiante', 'Aísla el bíceps de un brazo y mejora el control del movimiento con tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7922'),
('98d82ddd-5038-500c-828f-7b42fe26e95c', 'Remo sentado con agarre supino en polea', ARRAY['Siéntate con los pies apoyados y sujeta el maneral con las palmas hacia arriba.', 'Tira de los codos hacia atrás llevando el pecho ligeramente hacia delante.', 'Junta las escápulas al final y vuelve controlando el peso.', 'Evita redondear la espalda o tirar con los brazos sin activar la espalda.']::text[], 'principiante', 'Refuerza dorsales y espalda alta con mayor implicación del bíceps por el agarre supino.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3233'),
('a34ddc97-9d31-5c9a-a30d-c674b6323ca3', 'Giro sentado en polea', ARRAY['Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.', 'Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo.', 'Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la musculatura abdominal y oblicua con rotación controlada contra resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2399'),
('374bdc2e-5193-515c-9db2-bbdfd2932f76', 'Giro sentado en el suelo en polea', ARRAY['Siéntate en el suelo con las piernas flexionadas y sujeta la polea con ambas manos.', 'Mantén el pecho alto y rota el tronco hacia un lado sin mover las caderas.', 'Vuelve al centro controlando la tensión y repite hacia el otro lado.', 'Evita tirar solo con los brazos o arquear la espalda.']::text[], 'principiante', 'Fortalece el core y los oblicuos con rotación controlada desde el suelo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2434'),
('1eb76ddc-6050-5f48-a25d-5393266ac7df', 'Curl de bíceps unilateral sentado en polea', ARRAY['Siéntate con la espalda apoyada y el codo pegado al costado.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo.', 'Baja despacio hasta extender casi por completo el codo.', 'Evita balancear el tronco o encoger el hombro.']::text[], 'principiante', 'Aísla el bíceps de un brazo con tensión constante y mejora la simetría entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7921'),
('ec017773-b2b0-5552-9e92-2b00b433b085', 'Remo sentado con agarre abierto en polea', ARRAY['Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.', 'Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto más alto de la contracción.', 'Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfatiza la espalda alta y los romboides con un agarre amplio que abre los codos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0218'),
('4e416379-9ed6-532b-b148-67762b35bd49', 'Press con agarre cerrado sentado en polea', ARRAY['Siéntate frente a la polea con los codos pegados al cuerpo y las manos juntas.', 'Empuja hacia delante extendiendo los codos sin mover los hombros.', 'Vuelve despacio controlando la resistencia hasta la posición inicial.', 'Evita abrir los codos o arquear la espalda.']::text[], 'principiante', 'Trabaja el tríceps y el pecho con un empuje controlado que protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3364'),
('960bb0b2-0e18-566c-a92e-6bc0dc1d9967', 'Rotación externa de hombro a 90 grados en polea', ARRAY['Colócate de lado a la polea con el codo a 90 grados y el antebrazo al frente.', 'Rota el antebrazo hacia fuera sin mover el codo del costado.', 'Vuelve despacio controlando la tensión hasta la posición inicial.', 'Evita usar peso excesivo o girar el tronco.']::text[], 'principiante', 'Fortalece el manguito rotador y estabiliza el hombro en posición de 90 grados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5087'),
('7db2505f-8a49-5fdc-b699-eb222f856e62', 'Rotación interna de hombro a 90 grados en polea', ARRAY['Colócate de lado a la polea con el codo a 90 grados y el antebrazo hacia fuera.', 'Rota el antebrazo hacia dentro sin mover el codo del costado.', 'Vuelve despacio controlando la tensión hasta la posición inicial.', 'Evita compensar con el tronco o usar demasiado peso.']::text[], 'principiante', 'Refuerza el manguito rotador y el control interno del hombro con resistencia ligera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5089'),
('08433e2f-2e3e-5855-9668-245367ab2a19', 'Press de hombros en polea', ARRAY['Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera.', 'Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Desarrolla los deltoides y el tríceps con un empuje vertical guiado por la polea.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0219'),
('e8dfd93f-e3a6-5a0d-8c37-8bf399b4a14a', 'Encogimientos de hombros en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti.', 'Manteniendo los brazos rectos, encoge los hombros hacia las orejas.', 'Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los trapecios superiores y mejora la estabilidad de cuello y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0220'),
('e0ee6395-f71d-53bf-be77-727fb3bed66b', 'Flexión lateral en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano.', 'Mantén la espalda recta y el core activado.', 'Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite del otro lado.', 'Alterna los lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los oblicuos y la musculatura lateral del core con flexión controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0222'),
('8ca69c28-7c25-5d8c-b0ff-69c966e58a48', 'Abdominal con flexión lateral en polea sobre bosu', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano.', 'Coloca la otra mano en la cadera.', 'Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta.', 'Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Combina flexión abdominal y lateral para trabajar core y oblicuos con inestabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0221'),
('6355935a-a95d-55ea-90eb-349fa3fdb9e4', 'Abdominal lateral en polea', ARRAY['Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina.', 'Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera.', 'Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.', 'Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Enfatiza los oblicuos y la flexión lateral del tronco contra la resistencia de la polea.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0223'),
('36f69895-db63-58d2-b8fb-517213621da9', 'Patada lateral hacia atrás en polea', ARRAY['Colócate de pie frente a la polea con el tobillo enganchado y sujétate para mantener el equilibrio.', 'Lleva la pierna hacia atrás y afuera en un arco controlado, sin balancear el tronco.', 'Aprieta el glúteo al final del recorrido y vuelve despacio a la posición inicial.', 'Evita arquear la espalda o girar la cadera para compensar el movimiento.']::text[], 'principiante', 'Trabaja los abductores y glúteos para mejorar la estabilidad de la cadera y la fuerza en movimientos laterales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10860'),
('6f695b21-5221-55b6-9b91-e8858164acb1', 'Patada de pierna acostado de lado en polea', ARRAY['Túmbate de lado con el tobillo enganchado a la polea y el cuerpo alineado.', 'Extiende la pierna hacia atrás manteniendo la cadera estable y el abdomen activo.', 'Aprieta el glúteo arriba y regresa la pierna sin dejar que el peso tire de ti.', 'Evita rotar el tronco o levantar la cadera del suelo durante el recorrido.']::text[], 'principiante', 'Aísla el glúteo y los isquiotibiales para fortalecer la extensión de cadera con control y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9863'),
('fadf3ba0-0b4a-52c1-83da-c6749915e175', 'Elevación lateral acostado de lado en polea', ARRAY['Túmbate de lado con la polea alineada y el brazo inferior apoyado para estabilizarte.', 'Eleva el brazo superior hasta la altura del hombro con el codo ligeramente flexionado.', 'Baja despacio controlando el peso y sin dejar que caiga de golpe.', 'Evita encoger el hombro o usar impulso del tronco para subir el brazo.']::text[], 'principiante', 'Fortalece el deltoides lateral y el manguito rotador para mejorar la estabilidad del hombro en abducción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2924'),
('079a2dbf-2cf1-5082-95f4-4f03937c3905', 'Elevación lateral a un brazo acostado de lado en polea', ARRAY['Túmbate de lado con el brazo libre enganchado a la polea y el cuerpo alineado.', 'Sube el brazo hasta la altura del hombro manteniendo el codo suave y el core activo.', 'Controla el descenso sin dejar que la polea arrastre el brazo.', 'Evita girar el torso o elevar el hombro hacia la oreja durante el movimiento.']::text[], 'principiante', 'Trabaja el deltoides y el manguito rotador de forma unilateral para corregir desequilibrios y ganar estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9491'),
('e499a335-ffa6-5039-b044-442c6b04bc77', 'Remo en plancha lateral en polea', ARRAY['Colócate en plancha lateral con el brazo de apoyo firme y la mano libre agarrando la polea.', 'Tira del cable hacia el costado manteniendo la cadera elevada y el cuerpo alineado.', 'Extiende el brazo despacio sin dejar caer la cadera ni rotar el tronco.', 'Evita arquear la zona lumbar o perder la línea del cuerpo al tirar.']::text[], 'principiante', 'Combina antirotación y tracción para fortalecer oblicuos, dorsales y espalda alta con estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11275'),
('e494ad04-f7ab-5808-8dc8-e73e397a56be', 'Apertura de oso a un brazo en polea', ARRAY['Adopta posición de oso con rodillas despegadas y una mano agarrando la polea.', 'Lleva el brazo hacia delante y cruza ligeramente el cuerpo manteniendo la cadera estable.', 'Vuelve despacio resistiendo el cable sin perder la postura.', 'Evita hundir la cadera o bloquear el codo durante el recorrido.']::text[], 'principiante', 'Trabaja el pectoral y la parte superior del pecho con un patrón de empuje unilateral que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10095'),
('bc4d8a42-4c70-511c-9c4b-b882461ddb3b', 'Remo alto a un brazo en polea', ARRAY['Colócate de pie con la polea alta y agarra el maneral con una mano.', 'Tira del cable hacia el costado llevando el codo atrás y abajo, sin encoger el hombro.', 'Controla el retorno extendiendo el brazo despacio.', 'Evita girar el tronco o usar impulso para completar la tracción.']::text[], 'principiante', 'Fortalece la espalda alta, dorsales y deltoides posterior para mejorar la postura y la tracción unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6510'),
('ad5d673d-eb97-5949-8722-06fd44dd3cd7', 'Remo alto a un brazo con apoyo de pecho en polea', ARRAY['Apoya el pecho en el banco y agarra el maneral con una mano.', 'Tira del cable llevando el codo hacia atrás y abajo manteniendo el hombro lejos de la oreja.', 'Extiende el brazo despacio sin despegar el pecho del apoyo.', 'Evita encoger el hombro o tirar con el bíceps en lugar de la espalda.']::text[], 'principiante', 'Aísla la espalda alta y los romboides con apoyo que reduce la compensación lumbar y mejora la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7587'),
('01e498f0-56c4-561d-83e8-30b6d984ea27', 'Remo escapular alto a un brazo en polea', ARRAY['Colócate frente a la polea alta con el brazo extendido y el hombro relajado.', 'Retrae la escápula llevando el hombro hacia atrás sin flexionar el codo.', 'Mantén un instante y vuelve despacio a la posición inicial.', 'Evita encoger el hombro hacia la oreja o usar el tronco para ayudar.']::text[], 'principiante', 'Activa la espalda alta y los romboides con un rango corto para mejorar el control escapular y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6511'),
('b09a7ded-c41f-5d85-93b4-8ad7d6e88e49', 'Remo bajo a un brazo en polea con cuerda', ARRAY['Colócate frente a la polea baja con la cuerda agarrada con una mano y las rodillas ligeramente flexionadas.', 'Tira del cable hacia la cadera llevando el codo pegado al cuerpo.', 'Aprieta la espalda al final y extiende el brazo despacio.', 'Evita redondear la espalda o girar el tronco al tirar.']::text[], 'principiante', 'Trabaja dorsales y espalda alta de forma unilateral para ganar fuerza y corregir desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10437'),
('c5d714f6-5d97-5dca-9d9c-ee376fa94cad', 'Remo escapular bajo a un brazo en polea', ARRAY['Colócate frente a la polea baja con el brazo extendido y el codo casi recto.', 'Lleva la escápula hacia atrás sin doblar el codo, como si juntaras los omóplatos.', 'Mantén un segundo y suelta despacio sin perder la postura.', 'Evita encoger el hombro o tirar con el brazo en lugar de la escápula.']::text[], 'principiante', 'Mejora la retracción escapular y la estabilidad de la espalda alta con un movimiento corto y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6512'),
('ea898c84-46e9-5408-bbb7-be8e58272621', 'Elevación frontal a un brazo con agarre neutro en polea', ARRAY['Colócate de pie frente a la polea baja con agarre neutro y el brazo extendido.', 'Eleva el brazo hacia delante hasta la altura del hombro sin balancear el tronco.', 'Baja despacio resistiendo el cable y manteniendo el abdomen activo.', 'Evita arquear la espalda o usar impulso para subir el brazo.']::text[], 'principiante', 'Fortalece el deltoides anterior y la parte superior del pecho con un patrón unilateral que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5943'),
('5a923b28-bb88-5f6a-96ed-777268283dd7', 'Remo a un brazo con rotación en polea', ARRAY['Colócate frente a la polea con una mano agarrando el maneral y las rodillas suaves.', 'Tira del cable hacia la cadera y rota el tronco hacia el lado de la tracción.', 'Vuelve despacio a la posición inicial controlando la rotación.', 'Evita redondear la espalda o rotar solo con los brazos sin activar el core.']::text[], 'principiante', 'Trabaja dorsales y oblicuos combinando tracción y rotación para ganar fuerza funcional y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11263'),
('0390012d-673d-519f-bdf8-cbd063242b85', 'Extensión de tríceps a un brazo en polea con cuerda', ARRAY['Colócate frente a la polea alta con la cuerda agarrada con una mano y el codo pegado al cuerpo.', 'Extiende el codo hacia abajo separando ligeramente la cuerda al final.', 'Vuelve despacio sin dejar que el codo se separe del torso.', 'Evita usar el hombro o el tronco para empujar el cable.']::text[], 'principiante', 'Aísla el tríceps y el antebrazo para mejorar la extensión del codo y la definición del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5033'),
('f24f76d9-5b4f-5fe9-ba21-bf9c96e3f433', 'Remo con giro a un brazo sentado en banco en polea', ARRAY['Siéntate en el banco frente a la polea con una mano agarrando el maneral y la espalda recta.', 'Tira del cable hacia la cadera y rota el tronco hacia el lado de la tracción.', 'Vuelve despacio extendiendo el brazo y controlando la rotación.', 'Evita redondear la espalda o girar solo con el brazo sin acompañar con el tronco.']::text[], 'principiante', 'Fortalece dorsales y espalda alta con rotación que implica oblicuos y core para un patrón más funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9875'),
('48cfeb03-7a16-5668-ad2f-0b7d0f6b2437', 'Press pallof horizontal en polea con piernas en tijera', ARRAY['Colócate de lado a la polea con las piernas en tijera y el cable a la altura del pecho.', 'Sujeta el asa con las dos manos delante del esternón y aprieta el abdomen.', 'Empuja el asa hacia delante sin dejar que el torso gire hacia la polea.', 'Mantén dos segundos y vuelve despacio, respirando de forma controlada.', 'Evita arquear la espalda o encoger los hombros durante el recorrido.']::text[], 'principiante', 'Trabaja el core y los oblicuos resistiendo la rotación para ganar estabilidad y proteger la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4106'),
('f59daeb3-b279-54f4-b9d6-75bc07c6b7fe', 'Remo a un brazo en polea con piernas en tijera', ARRAY['Coloca una pierna delante y otra detrás, con el cable a la altura de la cadera.', 'Agarra el asa con una mano y lleva el hombro hacia atrás, con el pecho alto.', 'Tira del codo hacia la cadera sin girar el tronco.', 'Aguanta un segundo arriba y baja el brazo controlando el movimiento.', 'Evita encorvar la espalda o tirar con el bíceps en lugar de la espalda.']::text[], 'principiante', 'Fortalece dorsales y espalda alta, mejorando la postura y la fuerza de tracción de cada lado por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7564'),
('c1748876-4b86-5ea0-853b-634a90433f8d', 'Remo en sentadilla con cuerda en polea', ARRAY['Sujeta una cuerda a una máquina de cable a la altura de la cintura.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros.', 'Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí.', 'Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho.', 'Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Combina sentadilla y tirón para trabajar dorsales, bíceps y espalda alta con estabilidad de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1717'),
('d6089433-823e-565a-8352-1794f97cf04c', 'Sentadilla en polea', ARRAY['Sujeta el asa o la cuerda a la altura del pecho y da un paso atrás para tensar el cable.', 'Separa los pies a la anchura de los hombros y apunta las puntas ligeramente hacia fuera.', 'Baja flexionando caderas y rodillas como si te sentaras en una silla.', 'Empuja con los talones para subir, manteniendo el pecho alto y el abdomen firme.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'principiante', 'Refuerza cuádriceps y glúteos con resistencia constante, útil para aprender el patrón de sentadilla con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11268'),
('b384c5ed-19e1-558d-9b5f-ee0f047fdf3b', 'Curl en sentadilla en polea', ARRAY['Coloca un mango de cable en el ajuste más bajo de una máquina de cable.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.', 'Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.', 'Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados.', 'Haz una pausa breve en la parte alta del movimiento, apretando los bíceps.', 'Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los bíceps y antebrazos manteniendo una posición baja que exige estabilidad de piernas y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1644'),
('f671736a-769e-5887-a6c0-82df2ce69fd2', 'Levantarse en polea', ARRAY['Siéntate en un banco de espaldas a la polea con el cable tenso y el asa al pecho.', 'Apoya bien los pies y mantén el pecho alto y el abdomen apretado.', 'Empuja con los talones y extiende las caderas para ponerte de pie.', 'Aprieta los glúteos arriba un segundo y baja controlando el movimiento.', 'Evita tirar del cable con los brazos o redondear la espalda al subir.']::text[], 'principiante', 'Activa glúteos y piernas al pasar de sentado a de pie, un gesto útil para la fuerza funcional diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2758'),
('731e4796-1166-544e-8636-fe2ae10a8189', 'Apertura baja alterna de pie en polea', ARRAY['Colócate de pie entre dos poleas bajas con un asa en cada mano.', 'Abre los brazos con una ligera flexión de codos y el pecho alto.', 'Junta una mano hacia delante y arriba, cruzando ligeramente la línea del cuerpo.', 'Vuelve despacio y alterna con el otro brazo, respirando de forma fluida.', 'Evita balancear el tronco o encoger los hombros al juntar las manos.']::text[], 'principiante', 'Trabaja el pectoral desde abajo con un brazo cada vez, mejorando el control y la simetría del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4374'),
('4f12c164-2548-5757-8d1a-4ceeb66a52b4', 'Press de pecho diagonal alterno de pie en polea', ARRAY['Sitúate de pie entre dos poleas bajas con un asa en cada mano a la altura del pecho.', 'Empuja una mano hacia delante y arriba en diagonal, extendiendo el brazo sin bloquear el codo.', 'Vuelve controlando el movimiento y repite con el otro brazo.', 'Mantén el abdomen firme y el tronco estable durante todo el recorrido.', 'Evita girar el torso o echar el peso hacia atrás al empujar.']::text[], 'principiante', 'Fortalece el pectoral superior y los hombros con empuje diagonal, sumando trabajo de core por la postura de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11274'),
('99f526ab-e676-5639-bbc6-99511bd14726', 'Curl de muñeca de pie en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo.', 'Mantén los brazos rectos y los codos cerca de los costados.', 'Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza los flexores del antebrazo y la muñeca, mejorando el agarre y la resistencia en tirones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0224'),
('8b4163b6-2673-5583-92ad-39f8a8abbace', 'Curl de bíceps de pie en polea con cuerda', ARRAY['Colócate de pie frente a la polea baja y agarra la cuerda con las palmas hacia arriba.', 'Pega los codos al costado y mantén los hombros relajados.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Baja despacio hasta estirar casi del todo, controlando la bajada.', 'Evita balancear el cuerpo o adelantar los codos para subir más peso.']::text[], 'principiante', 'Aísla el bíceps con tensión constante, ayudando a ganar volumen y control en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11261'),
('25fe94c0-14f1-5a8b-8872-e3ee4b1d1dc1', 'Curl de bíceps a press Arnold en polea', ARRAY['De pie frente a la polea baja, agarra las asas con las palmas hacia arriba y los codos pegados.', 'Haz un curl hasta el pecho y, desde ahí, gira las palmas y empuja hacia arriba.', 'Extiende los brazos por encima de la cabeza sin arquear la espalda.', 'Baja invirtiendo el recorrido hasta la posición inicial con control.', 'Evita usar impulso de piernas o encoger los hombros al press.']::text[], 'principiante', 'Combina curl y press para trabajar bíceps y hombros en un solo movimiento, mejorando la coordinación y la fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11272'),
('91e48b8e-827f-5543-a316-d437280b5950', 'Elevación de gemelos de pie en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos.', 'Levanta los talones del suelo extendiendo los tobillos lo más alto posible.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los gemelos y sóleo con tensión constante, mejorando la fuerza y el equilibrio del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1375'),
('e339a09e-da97-562e-9e57-289d198d9ef0', 'Remo de pie con agarre cerrado en polea', ARRAY['Colócate de pie frente a la polea con el agarre cerrado a la altura del pecho.', 'Da un paso atrás para tensar el cable y flexiona ligeramente las rodillas.', 'Tira del agarre hacia el abdomen llevando los codos atrás y juntando las escápulas.', 'Aguanta un segundo y vuelve despacio sin perder la postura.', 'Evita encorvar la espalda o tirar con los brazos en lugar de la espalda.']::text[], 'principiante', 'Fortalece dorsales y espalda media con un tirón horizontal, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5179'),
('e9724f49-1063-5f1f-85e8-aaf79ce417be', 'Press con agarre cerrado de pie en polea', ARRAY['Sujeta el agarre cerrado a la altura del pecho con los codos pegados al cuerpo.', 'Da un paso atrás para tensar el cable y mantén el abdomen firme.', 'Empuja hacia delante extendiendo los codos sin bloquear del todo.', 'Vuelve despacio controlando el movimiento y sin abrir los codos.', 'Evita arquear la espalda o echar el peso hacia atrás al empujar.']::text[], 'principiante', 'Trabaja el tríceps y el pecho con un empuje controlado, reforzando la extensión del codo de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3363'),
('c99e8685-e0a7-5301-a4d4-2f9218475386', 'Cruce de pie en polea', ARRAY['Colócate de pie entre dos poleas altas con un asa en cada mano y un pie adelantado.', 'Inclina ligeramente el tronco y abre los brazos con los codos algo flexionados.', 'Junta las manos delante del pecho cruzando ligeramente una sobre otra.', 'Aprieta el pecho un segundo y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o usar impulso del tronco para juntar las manos.']::text[], 'principiante', 'Aísla el pectoral con un cruce de brazos, ayudando a definir el pecho y mejorar la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8141'),
('89320023-e240-52ae-8642-7c07b29c8a43', 'Extensión de tríceps sobre la cabeza cruzada en polea', ARRAY['Colócate de pie de espaldas a la polea con el mango agarrado por encima de la cabeza.', 'Lleva el codo flexionado detrás de la nuca y extiende el brazo hacia delante y arriba.', 'Controla la bajada en dos o tres segundos sin mover el hombro.', 'Mantén el codo apuntando al frente y evita arquear la espalda.']::text[], 'principiante', 'Aísla el tríceps en estiramiento para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5528'),
('a43d38c4-67d8-544d-86bf-9114426a2a77', 'Abdominal de pie en polea', ARRAY['Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina.', 'Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos.', 'Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el recto abdominal con resistencia constante para fortalecer el core sin cargar la lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0226'),
('d385a5cf-2d40-5019-85e3-ebf6e7dcd671', 'Face pull en polea con cuerda', ARRAY['Ajusta la polea a la altura de la cara y agarra la cuerda con las palmas hacia dentro.', 'Tira de la cuerda hacia la frente separando las manos y llevando los codos atrás.', 'Aprieta los omóplatos al final y vuelve despacio.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'principiante', 'Refuerza deltoides posterior y manguito rotador para mejorar la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5656'),
('3be674e7-0a49-5ab4-8421-e9f4a1766ee7', 'Aperturas de pie en polea', ARRAY['Coloca los mangos en los cables a la altura del pecho.', 'Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable.', 'Agarra los mangos con un agarre prono, con las palmas hacia adelante.', 'Da un paso adelante para crear tensión en los cables.', 'Mantén el core activado y la espalda recta durante todo el ejercicio.', 'Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho.', 'Aprieta los músculos del pecho en el punto máximo del movimiento.', 'Invierte lentamente el movimiento, regresando los brazos a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el pectoral con tensión continua para trabajar la apertura del pecho y la parte interna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0227'),
('68ee01bc-af67-5691-8da2-dc664e9e4cb9', 'Elevación frontal de pie en polea', ARRAY['Sitúate de espaldas a la polea baja con el mango delante de los muslos.', 'Sube el brazo estirado hasta la altura del hombro sin balancear el cuerpo.', 'Baja controlando el movimiento y mantén el core firme.', 'No eleves por encima del hombro ni uses inercia de la cadera.']::text[], 'principiante', 'Fortalece la porción anterior del deltoides para mejorar el empuje y la estética del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11277'),
('8419842d-9086-5784-82d8-17a17658fa28', 'Extensión de tríceps cruzada alta con agarre neutro en polea', ARRAY['Coloca la polea alta y agarra el mango con la palma hacia dentro.', 'Lleva el codo pegado al cuerpo y extiende el brazo cruzando ligeramente hacia el lado contrario.', 'Estira del todo abajo y vuelve despacio sin separar el codo del torso.', 'Evita mover el hombro o encogerlo durante la extensión.']::text[], 'principiante', 'Aísla el tríceps con el brazo cruzado para enfatizar la cabeza lateral y mejorar el tono.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11051'),
('a106018e-c5ae-52c2-8727-c45bfa122349', 'Extensión de tríceps cruzada alta en polea', ARRAY['Ajusta la polea arriba y agarra el mango con la mano contraria al lado de trabajo.', 'Fija el codo junto al costado y extiende el antebrazo cruzando hacia el otro lado.', 'Aprieta el tríceps abajo y regresa controlando el recorrido.', 'No balances el tronco ni dejes que el codo se abra.']::text[], 'principiante', 'Trabaja el tríceps en polea alta con cruce para aislar el brazo y ganar definición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3719'),
('e846219e-7bb8-59ac-a73f-1e0b1f50f3fe', 'Abducción de cadera en polea', ARRAY['Coloca el tobillo en la cincha de la polea baja y sujétate a la estructura.', 'Separa la pierna hacia fuera manteniéndola estirada y el tronco recto.', 'Sube hasta donde controles y baja despacio sin dejar caer la pierna.', 'Evita inclinarte hacia el lado contrario o girar la cadera.']::text[], 'principiante', 'Fortalece glúteo medio y abductores para estabilizar la cadera y prevenir lesiones al correr.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11266'),
('7a5975a5-85f5-54b0-a627-6f35121c8870', 'Aducción de cadera de pie en polea', ARRAY['Engancha el tobillo a la polea baja y colócate de lado con apoyo.', 'Lleva la pierna estirada hacia dentro cruzando delante de la otra.', 'Controla el retorno sin dejar que la polea tire de golpe.', 'Mantén el tronco erguido y evita rotar la pelvis.']::text[], 'principiante', 'Refuerza los aductores y la cara interna del muslo para mejorar la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11267'),
('bb230039-5de8-55bd-ac76-71660ec852fd', 'Extensión de cadera en polea', ARRAY['Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina.', 'Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros.', 'Mantén el core activado y la espalda recta durante todo el ejercicio.', 'Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de lado y repite con la otra pierna.']::text[], 'principiante', 'Activa el glúteo y los isquios en cadena posterior para mejorar la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0228'),
('76c4107f-2426-5c11-b236-4f0089dcccd6', 'Flexión de cadera de pie en polea', ARRAY['Engancha el tobillo a la polea baja y sujétate para mantener el equilibrio.', 'Sube la rodilla hacia el pecho manteniendo el tronco recto.', 'Baja la pierna despacio sin dejar que la polea tire de golpe.', 'Evita arquear la lumbar o balancear el cuerpo para subir más.']::text[], 'principiante', 'Trabaja el psoas y la parte alta del cuádriceps para ganar fuerza en la elevación de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8191'),
('62df934b-c651-597d-a949-bad5b4bfd3f6', 'Empuje de cadera en polea', ARRAY['Coloca la cincha en la cadera y sitúate de espaldas a la polea baja.', 'Da un paso al frente y empuja la cadera hacia delante apretando el glúteo.', 'Mantén las rodillas ligeramente flexionadas y el core activo.', 'Evita arquear la lumbar en exceso o tirar con la espalda.']::text[], 'principiante', 'Fortalece glúteo e isquios con empuje de cadera para potenciar la extensión y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2744'),
('5c1c8f9c-5a40-539a-85f0-9704aa484920', 'Curl interno en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Agarra el mango del cable con un agarre supino, con las palmas hacia arriba.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente el mango del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps con agarre interno para trabajar el pico del brazo y la fuerza de flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0229'),
('900e5244-0fc7-5441-9bd0-7e27e7662855', 'Jab en polea', ARRAY['Colócate de lado a la polea con el mango a la altura del pecho.', 'Extiende el brazo hacia delante como un golpe recto girando el torso.', 'Recoge el brazo despacio y repite manteniendo la guardia.', 'Evita bloquear el codo de golpe o perder la postura del tronco.']::text[], 'principiante', 'Entrena la extensión explosiva del pectoral y el core para mejorar la potencia del empuje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '8880'),
('60e3bd41-0200-5e05-b428-3d0c7c67b44a', 'Jalón de dorsales de pie en polea con cuerda', ARRAY['Ajusta la polea alta y agarra la cuerda con los brazos estirados.', 'Tira de la cuerda hacia los muslos llevando los codos hacia abajo y atrás.', 'Aprieta el dorsal abajo y vuelve controlando la subida.', 'Evita encoger los hombros o flexionar los codos como en un curl.']::text[], 'principiante', 'Activa el dorsal ancho con un tirón vertical para mejorar la amplitud de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1229'),
('781c0671-080a-555e-b70a-99c4cb3628fa', 'Curl de pierna de pie en polea', ARRAY['Coloca el tobillo en la tobillera de la polea baja y sujétate a la estructura para mantener el equilibrio.', 'Flexiona la rodilla llevando el talón hacia el glúteo sin mover la cadera ni arquear la espalda.', 'Controla la bajada durante dos o tres segundos para trabajar bien el isquiotibial.', 'Evita balancear el tronco o tirar con la cadera para completar la repetición.']::text[], 'principiante', 'Aísla los isquiotibiales y mejora la flexión de rodilla, útil para equilibrar el tren inferior y prevenir descompensaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1547'),
('629ad0db-d96f-5d62-9933-ee02e97409ab', 'Elevación de pie en polea', ARRAY['Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura.', 'Activa el core y mantén la espalda recta durante todo el ejercicio.', 'Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso.', 'Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Activa el abdomen y los oblicuos con un movimiento controlado que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0230'),
('3068bb0a-9db3-5e98-9d85-ed9145aecf45', 'Apertura de pie con agarre neutro en polea', ARRAY['Colócate de pie entre las poleas con los mangos a la altura del pecho y un pie adelantado para estabilidad.', 'Junta las manos delante del pecho con los codos ligeramente flexionados y el agarre neutro.', 'Abre los brazos hacia atrás de forma controlada hasta notar el estiramiento del pectoral.', 'Cierra llevando las manos al centro y evita encoger los hombros o bloquear los codos.']::text[], 'principiante', 'Trabaja el pectoral con un recorrido controlado y tensión constante, ideal para dar volumen al pecho sin cargar demasiado las articulaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7416'),
('6834af39-fd58-5fdc-b6f5-fc2fddb34373', 'Extensión de tríceps sobre la cabeza de pie con agarre neutro en polea', ARRAY['Sujeta la cuerda con agarre neutro y da la espalda a la polea baja con un pie adelantado.', 'Lleva las manos por encima de la cabeza con los codos apuntando al frente y pegados a las orejas.', 'Extiende los codos hasta estirar los brazos sin mover los hombros ni arquear la zona lumbar.', 'Vuelve despacio a la posición inicial manteniendo los codos fijos y el core activo.']::text[], 'principiante', 'Estira y fortalece la porción larga del tríceps, mejorando la extensión del codo y el aspecto del brazo por detrás.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11436'),
('67c75731-7815-5cee-b883-7f18076d0d4b', 'Curl martillo a un brazo de pie en polea', ARRAY['Engancha la cuerda a la polea baja y sujétala con una mano en agarre neutro, codo pegado al costado.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el brazo ni el tronco.', 'Aprieta arriba un instante y baja controlando el movimiento hasta estirar el brazo.', 'Evita balancear el cuerpo o encoger el hombro para subir más peso.']::text[], 'principiante', 'Fortalece el bíceps y el braquial con agarre neutro, mejorando la fuerza de agarre y el grosor del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5370'),
('02fc3b40-9f04-5850-8c54-ff72eab39233', 'Extensión de tríceps a un brazo en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.', 'Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo.', 'Mantén el codo quieto y cerca del cuerpo.', 'Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza.', 'Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.']::text[], 'principiante', 'Aísla el tríceps de forma unilateral, corrigiendo desequilibrios y mejorando la definición del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0231'),
('787be8f7-9022-521f-a2f4-395d8652f976', 'Jalón de pie con cuerda en polea', ARRAY['Sujeta una cuerda a la máquina de cable en el ajuste más alto.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Agarra la cuerda con un agarre prono, con las palmas hacia abajo.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps.', 'Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja bíceps y antebrazos con un tirón vertical que también implica hombros y espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0232'),
('6c29ace4-6eec-560e-a1c2-255f76545e93', 'Empuje y jalón de pie en polea', ARRAY['Colócate de pie frente a la polea con los mangos a la altura del pecho y los pies a la anchura de las caderas.', 'Empuja la polea hacia delante extendiendo los brazos mientras activas el core y mantienes la espalda recta.', 'Recoge tirando de los mangos hacia el pecho juntando las escápulas sin encoger los hombros.', 'Mantén un ritmo constante y evita arquear la zona lumbar o bloquear la respiración.']::text[], 'principiante', 'Combina empuje y tracción para trabajar espalda, pecho y core, mejorando la coordinación y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11258'),
('8b0e82b7-f60f-5c17-8b16-2c5fa5937e44', 'Remo horizontal de deltoide posterior de pie en polea con cuerda', ARRAY['Sujeta la cuerda con las palmas enfrentadas y da un paso atrás para crear tensión en la polea.', 'Con los codos ligeramente flexionados, tira de la cuerda hacia el pecho abriendo los codos hacia fuera.', 'Junta las escápulas al final del recorrido y mantén los hombros lejos de las orejas.', 'Vuelve despacio sin dejar que el peso te arrastre y evita usar el impulso del tronco.']::text[], 'principiante', 'Refuerza el deltoide posterior y la espalda alta, corrigiendo la postura encorvada y equilibrando el trabajo de hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3232'),
('fc27efaf-bc5d-59f0-b511-8b7ddbe19475', 'Tirón a la cara con cuerda en polea', ARRAY['Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable.', 'Mantén la espalda recta y el core activado.', 'Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza el deltoides posterior y la espalda alta, mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0233'),
('afdbb89c-1552-5d12-9e71-337bcac064e9', 'Curl inverso de pie en polea con barra sz', ARRAY['Engancha la barra sz a la polea baja y sujétala con las palmas hacia abajo, codos pegados al cuerpo.', 'Flexiona los codos llevando la barra hacia el pecho sin mover los hombros ni el tronco.', 'Baja controlando el movimiento hasta estirar los brazos del todo.', 'Evita balancear el cuerpo o doblar las muñecas para completar la repetición.']::text[], 'principiante', 'Trabaja el antebrazo y el braquial con agarre prono, mejorando la fuerza de agarre y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1608'),
('c9c6a9be-3b5a-54d8-9d13-f4cc538b0306', 'Apertura invertida de pie en polea', ARRAY['Colócate de pie entre las poleas con los mangos cruzados delante del cuerpo y los codos algo flexionados.', 'Abre los brazos hacia los lados y atrás hasta la altura de los hombros, juntando las escápulas.', 'Vuelve despacio al centro sin dejar que el peso te lleve y mantén el core activo.', 'Evita encoger los hombros o usar impulso del tronco para abrir más.']::text[], 'principiante', 'Aísla el deltoide posterior y los romboides, mejorando la postura y la salud del hombro en movimientos de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11254'),
('39975319-44b3-5b76-9402-26c9baf434d2', 'Curl de pie con agarre inverso en polea con barra recta', ARRAY['Engancha la barra recta a la polea baja y sujétala con las palmas hacia abajo, codos junto al torso.', 'Flexiona los codos llevando la barra hacia el pecho manteniendo las muñecas firmes.', 'Baja controlando el movimiento hasta estirar los brazos sin soltar la tensión.', 'Evita doblar las muñecas hacia atrás o balancear el cuerpo para subir el peso.']::text[], 'principiante', 'Fortalece los extensores de la muñeca y el antebrazo con agarre prono, útil para mejorar el agarre y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2954'),
('b9c94ff0-c946-5cec-947c-1363f519cc57', 'Extensión de tríceps sobre la cabeza a un brazo en polea con agarre inverso', ARRAY['Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza.', 'Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo.', 'Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'principiante', 'Aísla el tríceps en estiramiento para ganar fuerza y control en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1727'),
('108c307a-6983-5dad-b15c-9d92968e30ee', 'Remo de pie en polea', ARRAY['Sujeta el mango de la polea baja con una mano o ambas y da un paso atrás con la espalda recta.', 'Tira del mango hacia la cadera llevando el codo hacia atrás y juntando la escápula.', 'Vuelve despacio estirando el brazo sin perder la posición del tronco.', 'Evita encorvar la espalda o tirar con el bíceps en lugar de la espalda.']::text[], 'principiante', 'Trabaja la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción con tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5090'),
('579a223d-876f-5d95-a65f-f7c6ff91878b', 'Rotación externa de hombro de pie en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo.', 'Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás.', 'Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el manguito rotador y estabiliza el hombro, ayudando a prevenir lesiones en presses y movimientos por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0235'),
('7d18eb78-055e-54c5-98cb-8f1f0c8103d2', 'Inclinación lateral de pie en polea', ARRAY['Colócate de lado a la polea con los pies a la anchura de las caderas y agarra el asa con la mano más cercana.', 'Mantén el brazo pegado al cuerpo y el torso erguido mientras inclinas el tronco hacia el lado contrario a la polea.', 'Vuelve despacio a la posición inicial controlando la resistencia y sin dejar que el peso te arrastre.', 'Evita balancear el cuerpo o tirar con el brazo: el movimiento debe salir de la cintura.']::text[], 'principiante', 'Trabaja los oblicuos y la estabilidad del core, útil para controlar la inclinación del tronco y mejorar la fuerza lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11278'),
('4e472e57-e0a2-5011-b3a9-a70ce8333429', 'Apertura a un brazo en polea', ARRAY['Sitúate de pie de lado a la polea con un pie adelantado y agarra el asa con la mano más alejada.', 'Con el brazo ligeramente flexionado, lleva la mano hacia delante y hacia el centro del pecho en un arco amplio.', 'Aprieta el pectoral al final del recorrido y vuelve despacio sin dejar que el peso te lleve atrás.', 'Mantén el core firme y evita girar el tronco para no perder tensión en el pecho.']::text[], 'principiante', 'Aísla el pectoral en un rango amplio, mejorando la apertura del pecho y la conexión con la parte interna del músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6219'),
('1715dd13-7cff-530b-946b-4688a6bd02b6', 'Extensión horizontal de tríceps a un brazo de pie en polea', ARRAY['Colócate de pie frente a la polea con el codo pegado al costado y flexionado unos 90 grados.', 'Extiende el antebrazo hacia delante hasta estirar el codo sin mover el brazo del costado.', 'Aprieta el tríceps al final y vuelve despacio controlando la resistencia.', 'Evita abrir el codo hacia fuera o balancear el hombro para no restar tensión al tríceps.']::text[], 'principiante', 'Trabaja el tríceps en extensión horizontal, reforzando la fuerza de empuje y el control del codo en movimientos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8614'),
('cc5aa75c-3964-5629-8488-c33e36e71076', 'Extensión de tríceps sobre la cabeza a un brazo en polea', ARRAY['De espaldas a la polea, agarra el asa con una mano y sube el codo junto a la oreja con el antebrazo flexionado.', 'Extiende el codo hacia arriba hasta estirar el brazo sin mover el hombro.', 'Baja despacio hasta la posición inicial manteniendo el codo apuntando al techo.', 'Evita arquear la espalda o abrir el codo: mantén el core activo y el brazo alineado.']::text[], 'principiante', 'Estira el tríceps en posición elevada, trabajando la porción larga y mejorando la fuerza en movimientos por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11279'),
('0092e802-330d-5925-9674-ade3a411ca36', 'Press de pecho a un brazo con agarre supino en polea', ARRAY['Colócate de pie de lado a la polea con un pie adelantado y agarra el asa con la palma hacia arriba.', 'Empuja la mano hacia delante a la altura del pecho extendiendo el brazo sin bloquear el codo.', 'Vuelve despacio controlando la resistencia y manteniendo el tronco estable.', 'Evita girar el torso o encoger el hombro: el movimiento debe salir del pecho y el brazo.']::text[], 'principiante', 'Trabaja el pectoral con un empuje horizontal que también implica tríceps y hombro, mejorando la fuerza de empuje unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11764'),
('f4a8825a-e723-55b3-b441-5e7fb0a01480', 'Remo para deltoide a un brazo en polea', ARRAY['De pie frente a la polea, agarra el asa con una mano y flexiona ligeramente las rodillas.', 'Tira del asa hacia el costado llevando el codo hacia atrás y hacia arriba, por encima de la línea del hombro.', 'Aprieta el deltoide posterior al final y vuelve despacio sin perder la posición del tronco.', 'Evita encoger el hombro o tirar con la espalda baja: mantén el core firme y el codo guiando el movimiento.']::text[], 'principiante', 'Refuerza el deltoide posterior y la espalda alta, equilibrando el hombro y mejorando la postura en el trabajo de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6776'),
('145b9588-dbe2-5603-b408-4ac2183012b2', 'Face pull supino en polea con cuerda', ARRAY['Coloca la polea a la altura de la cara y agarra la cuerda con las palmas hacia arriba.', 'Tira de la cuerda hacia la frente separando las manos y llevando los codos hacia atrás.', 'Aprieta la espalda alta al final y vuelve despacio controlando la resistencia.', 'Evita arquear la espalda o encoger los hombros: mantén el pecho alto y el core activo.']::text[], 'principiante', 'Trabaja el deltoide posterior y el manguito rotador, mejorando la salud del hombro y la postura frente al trabajo de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7744'),
('28c6862f-1aa2-51b8-97db-bb78bd2d261d', 'Giro de torso en polea', ARRAY['Colócate de pie de lado a la polea con los pies a la anchura de las caderas y agarra el asa con ambas manos.', 'Con los brazos extendidos, gira el tronco hacia el lado contrario a la polea sin mover las caderas.', 'Vuelve despacio a la posición inicial controlando la resistencia y sin dejar que el peso te arrastre.', 'Evita tirar con los brazos o balancear el cuerpo: el giro debe salir del core.']::text[], 'principiante', 'Trabaja los oblicuos y la rotación del core, mejorando la estabilidad y la fuerza en movimientos de giro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11271'),
('c4ad81e0-8b74-56d5-9c15-58a329c15bf1', 'Remo con giro en polea con barra V', ARRAY['Coloca un accesorio en V en una máquina de cable a la altura del pecho.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo.', 'Da un paso atrás para crear tensión en el cable.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos.', 'Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda.', 'Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso.', 'Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición.']::text[], 'principiante', 'Combina tracción de espalda alta con rotación del tronco, mejorando la fuerza y el control en movimientos de tirar y girar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0236'),
('13f03c3f-d896-54b8-aad8-e5794897ae80', 'Cruces de poleas de pie hacia arriba', ARRAY['Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros.', 'Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados.', 'Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra.', 'Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la parte superior del pectoral con un recorrido ascendente, mejorando la definición y la fuerza en el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1269'),
('a77badc6-4264-5a78-8a4f-a732192ba8d5', 'Curl de muñeca en polea', ARRAY['De pie frente a la polea, agarra la barra con las palmas hacia arriba y los antebrazos apoyados en los muslos.', 'Flexiona las muñecas hacia arriba todo lo que puedas sin mover los antebrazos.', 'Baja despacio hasta la posición inicial controlando la resistencia.', 'Evita balancear el cuerpo o usar los hombros: el movimiento debe salir solo de la muñeca.']::text[], 'principiante', 'Fortalece los flexores de la muñeca y el agarre, mejorando la fuerza en la mano y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6360'),
('4703c552-702f-5eb4-9bca-def490754b2f', 'Curl de muñeca inverso de pie en polea', ARRAY['De pie frente a la polea, agarra la barra con las palmas hacia abajo y los antebrazos apoyados en los muslos.', 'Extiende las muñecas hacia arriba todo lo que puedas sin mover los antebrazos.', 'Baja despacio hasta la posición inicial controlando la resistencia.', 'Evita balancear el cuerpo o encoger los hombros: el movimiento debe salir solo de la muñeca.']::text[], 'principiante', 'Trabaja los extensores de la muñeca y el agarre, equilibrando la fuerza del antebrazo y previniendo molestias en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6363'),
('013953b2-662b-5a6b-9433-c03b029d44c2', 'Enrollado de muñeca en polea', ARRAY['De pie frente a la polea, agarra la barra con las palmas hacia abajo y los brazos extendidos.', 'Enrolla la muñeca hacia dentro y hacia fuera de forma controlada, sin mover el codo.', 'Mantén el antebrazo estable y respira de forma constante durante todo el recorrido.', 'Evita usar el hombro o el tronco para ayudar: el movimiento debe salir solo de la muñeca.']::text[], 'principiante', 'Trabaja flexores y extensores del antebrazo con un movimiento de enrollado, mejorando el agarre y la resistencia de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6269'),
('334ba748-c119-509d-8d24-426f47f8b082', 'Elevación en Y en polea', ARRAY['De pie frente a la polea, agarra el asa con una mano y coloca el brazo delante del cuerpo.', 'Eleva el brazo en diagonal hacia arriba formando una Y, con el pulgar apuntando hacia arriba.', 'Baja despacio controlando la resistencia y manteniendo el hombro lejos de la oreja.', 'Evita encoger el hombro o arquear la espalda: mantén el core activo y el movimiento controlado.']::text[], 'principiante', 'Refuerza el deltoide y la espalda alta en un patrón en Y, mejorando la estabilidad del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8899'),
('e825a8b7-4d68-5633-9f8e-8245f0961871', 'Subida al cajón en polea', ARRAY['Colócate de pie frente al cajón con la polea baja y el mango agarrado a un lado.', 'Apoya un pie entero sobre el cajón y empuja con la pierna de apoyo para subir.', 'Sube controlando el movimiento y baja despacio sin dejarte caer.', 'Mantén el torso erguido y evita empujar con la pierna de abajo.', 'Respira al subir y no bloquees la rodilla arriba.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos para ganar fuerza y estabilidad en una sola pierna, útil en gestos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10048'),
('d36bd536-c577-56cd-a7de-a3a9b8027f0c', 'Peso muerto con piernas rectas desde cajón en polea', ARRAY['Sube al cajón y agarra el mango de la polea baja con las piernas casi rectas.', 'Lleva la cadera atrás bajando el torso con la espalda neutra.', 'Nota el estiramiento en los isquiotibiales sin redondear la espalda.', 'Empuja la cadera adelante para volver a la posición inicial.', 'Evita flexionar demasiado las rodillas o curvar la zona lumbar.']::text[], 'principiante', 'Fortalece isquiotibiales y glúteos con un patrón de bisagra de cadera que mejora la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2836'),
('e595fac1-b363-506b-bfe0-45815ca37c73', 'Jalón con brazos rectos en polea', ARRAY['Coloca una barra recta en la polea alta de una máquina de cable.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo.', 'Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento.', 'Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el dorsal ancho con brazos rectos, ideal para sentir la espalda y mejorar la técnica del jalón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0238'),
('2d91cd4f-29d4-585f-be73-f4b08b0520c2', 'Remo sentado con espalda recta en polea', ARRAY['Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas.', 'Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la espalda alta y los bíceps con un remo controlado que mejora la postura y la tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0239'),
('690c970e-7213-5afd-80da-5d51441dfc3b', 'Patada diagonal con pierna recta en polea', ARRAY['Coloca la polea baja y sujeta el mango con el pie o el tobillo.', 'Inclínate ligeramente hacia delante apoyándote en el soporte.', 'Lleva la pierna recta hacia atrás y en diagonal sin arquear la lumbar.', 'Vuelve despacio controlando el retorno y sin balancear el tronco.', 'Evita girar la cadera o usar impulso para subir la pierna.']::text[], 'principiante', 'Activa el glúteo con una extensión diagonal de cadera que también exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8083'),
('9db525e7-4e6d-5256-9e8c-2d678ee22422', 'Pull through con piernas rectas en polea', ARRAY['Colócate de espaldas a la polea con la cuerda entre las piernas.', 'Da un paso adelante y flexiona ligeramente las rodillas.', 'Lleva la cadera atrás bajando el torso con la espalda recta.', 'Empuja la cadera adelante y aprieta los glúteos al final.', 'Evita tirar con los brazos o redondear la espalda.']::text[], 'principiante', 'Trabaja glúteos e isquiotibiales con una bisagra de cadera que enseña a empujar con la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2324'),
('85783a20-be99-559d-bcb7-4adb34dcb783', 'Apertura invertida boca arriba en polea', ARRAY['Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano.', 'Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti.', 'Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los deltoides posteriores y la espalda alta, equilibrando el trabajo de empuje del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0240'),
('d2752b74-b464-5c3a-8680-4d8291d38a47', 'Estiramiento de espalda en suspensión en polea', ARRAY['Ajusta la polea alta y agarra el mango con ambas manos.', 'Siéntate o arrodíllate dejando que el peso estire los brazos.', 'Inclina el torso atrás y deja que la espalda se alargue sin forzar.', 'Respira profundo y mantén el estiramiento sin rebotes.', 'Evita encoger los hombros o tirar con fuerza del mango.']::text[], 'principiante', 'Descomprime la espalda y estira dorsales y hombros, útil tras sesiones de tracción o mucho tiempo sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1800'),
('d25884c7-3666-5774-bdf1-21282135a6fe', 'Extensión de tríceps en polea con barra V', ARRAY['Coloca un accesorio en V en la máquina de cable en el ajuste más alto.', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.', 'Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.', 'Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.', 'Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.', 'Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con una extensión en polea que permite trabajar con carga constante y controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0241'),
('1b555dba-99ba-5cb6-88d6-6330ed4bcbe1', 'Abdominal reverso encogido en polea', ARRAY['Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla.', 'Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho.', 'Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho.', 'Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo.', 'Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen bajo con un encogimiento controlado que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0242'),
('06c1446e-ec65-5f5d-b689-33b92117aec9', 'Giro en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.', 'Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.', 'Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo.', 'Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos.', 'Regresa lentamente a la posición inicial, resistiendo la tracción del cable.', 'Repite el movimiento hacia el lado izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa abdominales y oblicuos con una rotación controlada que mejora la fuerza rotacional del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0243'),
('58040a6c-b873-54ad-b6ab-d19c490a48a9', 'Press sobre la cabeza con giro en polea', ARRAY['Colócate de pie con la polea baja y el mango a la altura del hombro.', 'Empuja el mango hacia arriba mientras giras el torso ligeramente.', 'Extiende el brazo sin arquear la espalda ni encoger el hombro.', 'Vuelve despacio a la posición inicial controlando la rotación.', 'Evita usar impulso de piernas o girar solo con los brazos.']::text[], 'principiante', 'Fortalece hombros y tríceps añadiendo una rotación que implica oblicuos y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1209'),
('caaea071-dbd4-532a-92db-0bdc9665afd8', 'Jalón con giro en polea', ARRAY['Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina.', 'Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo.', 'Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo.', 'Aprieta los músculos de la espalda al final del movimiento.', 'Regresa lentamente a la posición inicial, manteniendo la tensión en el cable.', 'Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha.']::text[], 'principiante', 'Trabaja dorsales y bíceps con una tracción rotatoria que suma control del core y la cintura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0244'),
('96ce9a96-985b-5e42-809a-6aa23b112e97', 'Remo alto de pie con giro en polea', ARRAY['Colócate de pie frente a la polea baja con el mango agarrado.', 'Tira del mango hacia el pecho llevando los codos atrás.', 'Añade un giro suave del torso al final del recorrido.', 'Vuelve despacio sin dejar caer el peso de golpe.', 'Evita encoger los hombros o tirar con la espalda arqueada.']::text[], 'principiante', 'Refuerza espalda alta y deltoides posteriores con una tracción rotatoria que exige estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1210'),
('eb3f9f34-6e53-5922-b77d-6ec98b0f6c77', 'Press de pecho de pie con giro a un brazo en polea', ARRAY['Colócate de pie de lado a la polea con el mango a la altura del pecho.', 'Empuja el mango hacia delante mientras giras el torso hacia el lado contrario.', 'Mantén el abdomen firme y evita que la cadera se mueva.', 'Vuelve despacio controlando el retorno del brazo.', 'Evita arquear la espalda o bloquear el hombro al empujar.']::text[], 'principiante', 'Trabaja pectoral y tríceps con un empuje a un brazo que reta al core a resistir la rotación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1211'),
('aa69c9e8-bc8a-5aa5-bd09-a708a5ada8c5', 'Remo de pie con giro en polea', ARRAY['Colócate de pie frente a la polea con los pies a la anchura de las caderas y las rodillas ligeramente flexionadas.', 'Agarra el manejador con una mano y tira llevando el codo hacia atrás mientras giras el tronco.', 'Controla el giro desde el core y evita mover la cadera para no compensar con la zona lumbar.', 'Vuelve despacio a la posición inicial y exhala al tirar, inhala al regresar.', 'Mantén el hombro lejos de la oreja y no tires con el brazo estirado.']::text[], 'principiante', 'Trabaja la espalda alta y los oblicuos, mejorando la fuerza de tracción y la rotación controlada del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1212'),
('3db89fbe-270d-5e02-a8d0-469a31fb62a4', 'Curl a dos brazos en banco inclinado con polea', ARRAY['Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.', 'Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los bíceps en estiramiento y fortalece antebrazos, útil para ganar volumen y control en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1645'),
('e14d98c9-6fe1-504d-af26-b68fd3883251', 'Patada de tríceps a dos brazos en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.', 'Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el tríceps en extensión completa y estabiliza el hombro, ayudando a definir la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1728'),
('ea3efc76-309e-5d54-9468-d3233fd02ef2', 'Jalón supino en polea', ARRAY['Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.', 'Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta e inclínate ligeramente hacia atrás.', 'Jala la barra hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfoca los dorsales con agarre supino y suma bíceps y antebrazos, mejorando la fuerza de tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0245'),
('8ece91e8-ebf5-5923-9628-5942a6613286', 'Subida unilateral al cajón en polea', ARRAY['Coloca un cajón estable frente a la polea y sujeta el manejador con la mano contraria a la pierna que sube.', 'Apoya todo el pie sobre el cajón y empuja con la pierna de apoyo sin impulsarte con la de abajo.', 'Sube controlando el tronco erguido y mantén la rodilla alineada con el pie.', 'Baja despacio hasta tocar el suelo con la punta del pie y repite sin dejar caer el peso.', 'Evita empujar con la pierna de abajo o inclinarte hacia delante para no perder el equilibrio.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10120'),
('90b9644f-ec2e-5452-8864-c9bd82714bdf', 'Remo al mentón en polea', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos.', 'Haz una pausa breve en la parte alta, apretando los omóplatos entre sí.', 'Baja lentamente el accesorio del cable de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa deltoides y trapecios para mejorar la fuerza del hombro y la postura en la parte alta de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0246'),
('ecb1cec9-b8aa-556a-91cc-9faac4921b6c', 'Press pallof vertical en polea', ARRAY['Colócate de lado a la polea con los pies a la anchura de los hombros y el manejador a la altura del pecho.', 'Sujeta el manejador con las dos manos y extiende los brazos al frente sin dejar que el cuerpo gire.', 'Mantén la posición de 20 a 40 segundos respirando de forma constante y sin bloquear el aire.', 'Aprieta glúteos y abdomen para no arquear la zona lumbar.', 'Evita girar el tronco o tirar del cable con los brazos.']::text[], 'principiante', 'Ejercicio isométrico que entrena el core y los oblicuos para resistir la rotación y estabilizar el tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1213'),
('d0dfa287-a7a7-56b9-a8b2-ddc2ead00df7', 'Jalón al pecho con agarre abierto en polea', ARRAY['Siéntate con los muslos bajo el soporte y agarra la barra con las manos más anchas que los hombros.', 'Tira de la barra hacia el pecho llevando los codos hacia abajo y atrás, sin balancear el tronco.', 'Junta las escápulas al final del recorrido y controla la subida en 2 o 3 segundos.', 'Exhala al tirar e inhala al subir, manteniendo el pecho alto.', 'Evita llevar la barra por detrás de la nuca o tirar con los brazos flexionados de más.']::text[], 'principiante', 'Desarrolla la amplitud de los dorsales y la espalda alta, mejorando la fuerza de tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2291'),
('7173e047-268c-5466-88da-ade0f8a6baa1', 'Jalón posterior tras nuca con agarre abierto en polea', ARRAY['Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza.', 'Siéntate y agarra la barra de jalón con un agarre prono amplio.', 'Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás.', 'Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales y deltoides posteriores con un recorrido amplio, aunque exige buena movilidad de hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1325'),
('55952b4f-a554-54b1-a882-5696d05e1020', 'Jalón con agarre neutro abierto en polea', ARRAY['Siéntate con los muslos fijados y agarra el manejador neutro con las manos separadas.', 'Tira llevando los codos hacia las costillas y acerca el manejador al pecho sin encoger los hombros.', 'Mantén el tronco ligeramente inclinado atrás y las escápulas juntas al final.', 'Sube despacio controlando el peso y sin soltar la tensión.', 'Evita tirar con los brazos o balancear el cuerpo para no perder el control.']::text[], 'principiante', 'Fortalece dorsales y espalda alta con un agarre cómodo para el hombro, mejorando la tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4217'),
('c9e59967-3ca1-5f98-8de3-08158d0e6106', 'Sentadilla zercher en polea', ARRAY['Sujeta el manejador o la barra en el pliegue de los codos, con los pies a la anchura de los hombros.', 'Baja flexionando caderas y rodillas con el pecho alto y la espalda recta.', 'Desciende hasta donde controles sin que la zona lumbar se redondee.', 'Empuja con los talones para subir y exhala al ascender.', 'Evita inclinarte hacia delante o dejar que los codos se separen del cuerpo.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos con el peso al frente, exigiendo core y espalda baja para mantener la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9878'),
('520aa297-1e6a-5cee-9edd-c3d15acd9580', 'Salto de gemelos hacia adelante', ARRAY['Colócate de pie con los pies a la anchura de las caderas y las rodillas ligeramente flexionadas.', 'Salta hacia delante impulsándote con los tobillos y aterriza con la punta de los pies.', 'Amortigua el impacto flexionando ligeramente las rodillas y vuelve a saltar.', 'Mantén el tronco erguido y respira de forma constante.', 'Evita aterrizar con las piernas rígidas o con los talones para no castigar los tobillos.']::text[], 'intermedio', 'Mejora la potencia y elasticidad de gemelos y sóleo, útil para saltos y cambios de dirección.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10756'),
('4c702f93-ee1b-5a66-9c8d-a74f1f05c218', 'Salto de gemelos', ARRAY['Ponte de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta hacia arriba impulsándote con los tobillos y mantén el cuerpo alineado.', 'Aterriza con la punta de los pies y amortigua con una flexión suave de rodillas.', 'Realiza saltos seguidos y controlados, respirando de forma constante.', 'Evita saltar con las piernas rígidas o aterrizar con los talones.']::text[], 'intermedio', 'Desarrolla la potencia y resistencia de los gemelos mediante saltos verticales, mejorando el rendimiento en carrera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10751'),
('d668795a-50a7-5eb0-86f4-cb6674fa96f6', 'Elevación de gemelos desde déficit con apoyo en silla', ARRAY['Coloca la punta de los pies en un escalón o déficit y sujétate a una silla para mantener el equilibrio.', 'Baja los talones por debajo del nivel del escalón hasta notar estiramiento en los gemelos.', 'Sube elevando los talones lo máximo posible y aprieta arriba un segundo.', 'Realiza el movimiento lento y controlado, sin rebotar.', 'Evita inclinar el cuerpo hacia delante o apoyarte demasiado en la silla.']::text[], 'intermedio', 'Fortalece gemelos y sóleo con mayor recorrido, mejorando la fuerza del tobillo y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3390'),
('2703ed76-c3d2-5809-9c2b-51f362a87785', 'Automasaje de gemelos con barra', ARRAY['Coloca la barra en el suelo y siéntate con un gemelo encima, apoyando las manos detrás.', 'Rueda despacio la barra desde el tobillo hasta la parte alta del gemelo, buscando puntos tensos.', 'Detente en los puntos dolorosos y mantén la presión unos segundos mientras respiras.', 'Evita rodar directamente sobre el tendón de Aquiles o el hueso de la tibia.']::text[], 'principiante', 'Libera tensión en gemelos y sóleo rodando la barra, mejorando la movilidad del tobillo y aliviando sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2992'),
('51d240b2-2312-59d0-844d-eae9a346bd06', 'Salto de gemelos de lado a lado', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta de lado a lado cayendo sobre la punta de los pies.', 'Amortigua cada aterrizaje con el tobillo y vuelve a saltar sin parar.', 'Mantén el torso erguido y evita aterrizar con el pie plano.']::text[], 'intermedio', 'Trabaja la potencia y reactividad de gemelos y tobillos con saltos laterales, mejorando la estabilidad y el impulso.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10757'),
('d8b856d5-cdbf-50e9-8301-5de1faff8e2a', 'Estiramiento de gemelos con cuerda', ARRAY['Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas.', 'Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho.', 'Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta.', 'Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos, luego suelta.', 'Repite con la otra pierna.']::text[], 'principiante', 'Estira gemelos y sóleo usando una cuerda para tirar del pie, mejorando la flexibilidad del tobillo y la cadena posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1378'),
('929a5ccb-ee43-53f1-8415-1b64e4c8c208', 'Estiramiento de gemelos', ARRAY['Apoya las manos en una pared y da un paso atrás con una pierna.', 'Mantén la pierna trasera estirada con el talón pegado al suelo.', 'Inclina el cuerpo hacia delante hasta notar el estiramiento en el gemelo.', 'Aguanta sin rebotar y evita levantar el talón del suelo.']::text[], 'principiante', 'Estira gemelos y sóleo para ganar flexibilidad en el tobillo y prevenir molestias en la parte baja de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4510'),
('22d08b2c-ec47-57bf-8311-0d211f221c87', 'Estiramiento estático de gemelos', ARRAY['Coloca el pie de la pierna a estirar sobre un escalón o superficie elevada.', 'Lleva el talón hacia el suelo manteniendo la rodilla estirada.', 'Inclínate ligeramente hacia delante hasta notar tensión en el gemelo.', 'Mantén la posición sin rebotar y respira de forma pausada.']::text[], 'principiante', 'Mantiene un estiramiento sostenido de gemelos y sóleo para mejorar la flexibilidad y relajar la pierna tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1848'),
('5ee05865-105e-582f-aa4d-1229cf7d8bbd', 'Remo acostado con barra curva', ARRAY['Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde.', 'Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros.', 'Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos.', 'Tira de la barra hacia el pecho, juntando los omóplatos.', 'Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los brazos tumbado boca abajo, trabajando la retracción escapular con un recorrido cómodo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0248'),
('d5d90e77-080c-5cdb-bd25-b6ad404ab1f3', 'Postura del camello', ARRAY['Arrodíllate con las rodillas a la anchura de las caderas y las manos en la espalda baja.', 'Empuja las caderas hacia delante y lleva el pecho hacia arriba.', 'Lleva las manos a los talones si puedes sin forzar el cuello.', 'Mantén el core activo y evita echar la cabeza hacia atrás.']::text[], 'intermedio', 'Abre el pecho y los flexores de cadera mientras activa el core, mejorando la extensión de la columna y la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3505'),
('5825be32-9a82-5dae-978e-e17792a31d4c', 'Postura del camello ustrasana', ARRAY['Arrodíllate con las rodillas separadas a la anchura de las caderas.', 'Coloca las manos en la espalda baja y empuja las caderas hacia delante.', 'Lleva el pecho hacia arriba y, si puedes, agarra los talones.', 'Mantén la mirada al frente y evita comprimir la zona lumbar.']::text[], 'intermedio', 'Estira cuádriceps y flexores de cadera abriendo el pecho, mejorando la extensión de la columna y la movilidad torácica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6303'),
('3a57e9a0-7dc0-5f1b-b5f3-9b44c242e5ff', 'Elevación de piernas en silla romana', ARRAY['Apoya los antebrazos en la silla romana y deja el cuerpo colgando.', 'Sube las rodillas hacia el pecho sin balancear el tronco.', 'Baja las piernas despacio controlando el movimiento.', 'Evita arquear la espalda baja y no uses impulso.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera colgado en la silla romana, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5107'),
('41aafa3b-19f4-5e99-94bf-28c5f0095a92', 'Elevación de piernas rectas en silla romana', ARRAY['Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas.', 'Mantén la parte superior del cuerpo estable y la espalda recta.', 'Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.', 'Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con las piernas estiradas, aumentando la dificultad del control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2963'),
('8ab29c6b-a069-5fb0-9195-a6c2e2691f8b', 'Zancada cardio', ARRAY['Colócate de pie con los pies juntos y el torso erguido.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo.', 'Impulsa con la pierna delantera y salta cambiando de pierna.', 'Mantén un ritmo constante y evita que la rodilla delantera pase de la punta del pie.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca con zancadas dinámicas que además trabajan piernas y glúteos de forma continua.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3708'),
('b03f510b-3dbf-5ddf-86d6-7069f4971d97', 'Estiramiento gato-vaca', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Redondea la espalda hacia arriba mientras exhalas y metes la barbilla.', 'Arquea la espalda hacia abajo mientras inhalas y miras al frente.', 'Mueve la columna vértebra a vértebra sin forzar el cuello.']::text[], 'intermedio', 'Moviliza la columna alternando flexión y extensión, aliviando tensión en la espalda y mejorando la coordinación respiratoria.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4580'),
('205bf04b-5a9d-52be-ba85-6ce2b9ba55ac', 'Postura del gato', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Redondea la espalda hacia el techo mientras exhalas.', 'Mete la barbilla hacia el pecho y empuja el suelo con las manos.', 'Mantén la posición unos segundos y evita bloquear los codos.']::text[], 'intermedio', 'Flexiona y redondea la columna para estirar la espalda y relajar la zona dorsal y los hombros.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0942'),
('76f8b3ac-fff4-55d6-ab21-aa25dc4b3b85', 'Estiramiento del gato', ARRAY['Colócate a cuatro patas con la espalda neutra.', 'Redondea la espalda hacia arriba llevando el ombligo hacia dentro.', 'Mete la barbilla y empuja el suelo con las manos.', 'Respira despacio y evita forzar el cuello hacia abajo.']::text[], 'principiante', 'Estira la columna y la espalda alta redondeando el torso, aliviando tensión y mejorando la movilidad vertebral.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1051'),
('18bb65f7-1c9b-552e-83fc-7b80921639ad', 'Estiramiento mirando al techo', ARRAY['Siéntate o ponte de pie con la espalda recta y los hombros relajados.', 'Lleva la barbilla hacia arriba y mira al techo sin forzar.', 'Coloca una mano suave en la cabeza para acompañar el estiramiento.', 'Mantén unos segundos y evita echar la cabeza hacia atrás de golpe.']::text[], 'principiante', 'Estira el elevador de la escápula y el cuello mirando hacia arriba, aliviando tensión en la zona cervical y dorsal.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0250'),
('7b718d41-e00d-5dea-a5ee-1dc50c9ea480', 'Rodillazos de celebración', ARRAY['Colócate de pie con el torso erguido y los pies a la anchura de las caderas.', 'Lleva una rodilla hacia el pecho mientras el brazo contrario sube con impulso.', 'Alterna las piernas a un ritmo vivo y controlado, sin perder el equilibrio.', 'Respira de forma rítmica y evita arquear la espalda baja al subir la rodilla.']::text[], 'intermedio', 'Eleva las rodillas con energía para activar cuádriceps y glúteos, mejorando la potencia y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6010'),
('a74daf8c-30be-5bd4-a2b2-3eb22ffb2046', 'Estiramiento de pierna extendida en silla', ARRAY['Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo.', 'Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.', 'Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps.', 'Mantén esta posición durante 20-30 segundos.', 'Cambia de pierna y repite el estiramiento.']::text[], 'principiante', 'Estira el cuádriceps y la parte posterior del muslo, aliviando la tensión tras estar sentado mucho tiempo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1548'),
('b515e11b-441f-5be9-8d6f-e916259c700c', 'Postura de la silla', ARRAY['Ponte de pie con los pies juntos y los brazos extendidos hacia arriba.', 'Flexiona las rodillas y lleva las caderas hacia atrás como si fueras a sentarte.', 'Mantén el pecho abierto y la espalda recta sin dejar caer la cabeza.', 'Respira con calma y evita que las rodillas se vayan hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core mientras mejora el equilibrio y la postura en una sentadilla isométrica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0944'),
('8ac95c73-3b8b-5ae6-960e-b207e08ed757', 'Chaturanga dandasana', ARRAY['Parte de una plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Flexiona los codos hacia atrás pegados al torso y baja el pecho a media altura.', 'Mantén el core firme y los glúteos activos para no hundir la cadera.', 'Evita que los codos se abran hacia fuera y sube con control al inspirar.']::text[], 'intermedio', 'Trabaja tríceps, pecho y core en una flexión de brazos controlada que refuerza la estabilidad del torso.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6290'),
('ab615ab9-3d79-5140-8a1a-76b97b40cb36', 'Postura chaturanga', ARRAY['Colócate en plancha alta con las manos alineadas bajo los hombros.', 'Baja el cuerpo flexionando los codos hacia atrás, cerca de las costillas.', 'Detente cuando los brazos formen unos noventa grados y mantén la posición.', 'Aprieta el core y los glúteos, y evita que la cadera caiga hacia el suelo.']::text[], 'intermedio', 'Refuerza tríceps, hombros y pecho con una flexión isométrica que exige control y estabilidad del core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5888'),
('3ed43cf5-0257-5489-bd14-c4d97414ddbf', 'Curl con impulso', ARRAY['Sujeta la barra con las palmas hacia arriba y los pies a la anchura de los hombros.', 'Da un pequeño impulso con las caderas para iniciar la subida de la barra.', 'Controla la bajada de forma lenta y sin balancearte para proteger la espalda.', 'Evita arquear la zona lumbar en exceso y mantén el core activado.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos usando un ligero balanceo para mover más peso en la fase concéntrica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5696'),
('bcac9af6-6131-5ef5-a3ab-952849d08c0e', 'Press de banca con control de brazos', ARRAY['Túmbate en el banco con los pies firmes y la barra a la altura del pecho.', 'Baja la barra controlando que los antebrazos queden verticales.', 'Empuja hacia arriba sin bloquear los codos de golpe y mantén las muñecas rectas.', 'Evita abrir los codos en exceso y respira al empujar.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros revisando la trayectoria de los brazos para una técnica segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2341'),
('f09f870e-ef46-558d-8810-0df1efb84f21', 'Press de banca con control de glúteos', ARRAY['Apoya la espalda en el banco con los pies planos en el suelo.', 'Mantén los glúteos pegados al banco durante todo el recorrido.', 'Baja la barra al pecho y empuja sin despegar la cadera.', 'Evita levantar los glúteos para no arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps manteniendo los glúteos apoyados para estabilizar la pelvis y proteger la lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2338'),
('e4db0a03-edcc-5eff-9438-454f42a8d464', 'Press de banca con control de codos', ARRAY['Colócate en el banco con la barra sujeta a la anchura de los hombros.', 'Baja la barra manteniendo los codos a unos cuarenta y cinco grados del torso.', 'Empuja hacia arriba sin dejar que los codos se abran en exceso.', 'Controla la bajada y evita rebotar la barra en el pecho.']::text[], 'intermedio', 'Trabaja pectorales y tríceps cuidando la posición de los codos para reducir el riesgo de lesión en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2342'),
('11abdbab-5cef-534e-a04d-41caf9297860', 'Press de banca con control del agarre', ARRAY['Agarra la barra con las manos algo más anchas que los hombros.', 'Comprueba que las muñecas quedan rectas y alineadas con los antebrazos.', 'Baja la barra al pecho y empuja manteniendo ese agarre estable.', 'Evita un agarre demasiado estrecho o abierto que cargue las muñecas.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps ajustando la anchura del agarre para una trayectoria más eficiente y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2339'),
('c97dda98-85ca-5e51-8fb9-17e88c53641a', 'Press de banca con control de hombros', ARRAY['Túmbate con los omóplatos retraídos y pegados al banco.', 'Baja la barra al pecho sin perder la retracción escapular.', 'Empuja hacia arriba manteniendo los hombros estables y lejos de las orejas.', 'Evita encoger los hombros o despegarlos del banco al empujar.']::text[], 'intermedio', 'Trabaja pectorales y tríceps cuidando la posición de los hombros para proteger la articulación durante el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2340'),
('30db4c63-22c1-57e9-b4c5-47fb3749b373', 'Fondos para pecho', ARRAY['Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto.', 'Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con el peso corporal, mejorando la fuerza de empuje del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0251'),
('8a66f6a5-e7d4-5be0-b28b-2f3d2ab0af8c', 'Fondos para pecho en barra recta', ARRAY['Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos.', 'Flexiona las rodillas y cruza los tobillos.', 'Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps en barra recta, exigiendo más control y estabilidad que en paralelas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2462'),
('eb7bb2b7-89f1-51d4-b2de-dbea450ee916', 'Estiramiento de pecho con manos atrás', ARRAY['De pie, entrelaza las manos detrás de la espalda con los brazos rectos.', 'Abre el pecho y lleva los omóplatos hacia atrás sin arquear la lumbar.', 'Mantén la posición respirando profundo durante veinte o treinta segundos.', 'Evita encoger los hombros o forzar la apertura si notas molestia.']::text[], 'principiante', 'Abre el pecho y los hombros para contrarrestar la postura encorvada y mejorar la movilidad torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4945'),
('0808aed6-e70d-58e6-be8b-1e2fbfb7d57f', 'Estiramiento de pecho con balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.', 'Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti.', 'Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho.', 'Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira pectorales y hombros usando el balón como apoyo para abrir el pecho y mejorar la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1272'),
('98482668-5205-5497-aa02-78bd666d644a', 'Flexión con toque al pecho', ARRAY['Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Mientras te bajas, toca tu pecho con la mano derecha.', 'Empújate de vuelta hacia arriba hasta la posición inicial.', 'Repite el movimiento, esta vez tocando tu pecho con la mano izquierda.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros; mejora la estabilidad del core y la coordinación al tocar el pecho en cada repetición.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3216'),
('1131714d-8cd6-5234-b380-6d704eb4f6e1', 'Postura de niño a cobra', ARRAY['Colócate en cuadrupedia con las rodillas bajo las caderas y las manos bajo los hombros.', 'Lleva las caderas hacia atrás y estira los brazos para entrar en postura de niño, respirando profundo.', 'Desliza el cuerpo hacia delante y eleva el pecho para entrar en cobra, sin forzar la zona lumbar.', 'Vuelve a la postura de niño con un movimiento lento y controlado, sincronizando la respiración.', 'Evita arquear en exceso el cuello: mantén la mirada al frente y los hombros lejos de las orejas.']::text[], 'intermedio', 'Moviliza la columna y abre el pecho, activando core, hombros y glúteos para mejorar la flexibilidad y la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4558'),
('7c17827e-1816-537e-8801-dc0effddd5ce', 'Estiramiento de barbilla al pecho', ARRAY['Siéntate o ponte de pie con la espalda recta y los hombros relajados.', 'Baja la barbilla hacia el pecho lentamente hasta notar un estiramiento suave en la nuca.', 'Mantén la posición entre 20 y 30 segundos respirando de forma pausada.', 'Evita tirar de la cabeza con las manos o forzar el cuello hacia abajo.', 'Sube despacio y repite el estiramiento dos o tres veces.']::text[], 'principiante', 'Estira el elevador de la escápula y el trapecio superior, aliviando la tensión cervical y mejorando la movilidad del cuello.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4509'),
('3dc00216-c045-52c1-9a2d-3550b42043e1', 'Dominada supina en posición de sentadilla', ARRAY['Agarra la barra con las palmas hacia ti y colócate en cuclillas con los pies en el suelo.', 'Tira de la barra flexionando los codos mientras las piernas empujan ligeramente para ayudarte.', 'Sube hasta que la barbilla supere la barra y controla la bajada.', 'Mantén el core activo y evita encoger los hombros hacia las orejas.', 'Respira al subir y baja de forma lenta y controlada.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con ayuda de las piernas, ideal para progresar hacia dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4724'),
('fe3d5064-bdc8-5b67-ba84-416c319cab9d', 'Dominada supina alrededor de la barra', ARRAY['Cuélgate de la barra con agarre supino y los brazos extendidos.', 'Tira de ti mismo hacia arriba mientras desplazas el cuerpo en círculo alrededor de la barra.', 'Controla el movimiento sin balancearte ni usar impulso.', 'Mantén el core firme y los hombros activos durante todo el recorrido.', 'Baja de forma lenta y repite el círculo en el sentido contrario.']::text[], 'intermedio', 'Trabaja dorsales, bíceps y espalda alta con un recorrido circular que añade control y estabilidad al tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4207'),
('a20c65c8-d573-57ab-a75d-b38a5293958a', 'Dominadas supinas', ARRAY['Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.', 'Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales, bíceps y antebrazos, mejorando la fuerza de tracción y el agarre del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1326'),
('45483c4a-9e08-5ef8-9fb3-ac936a42a9c2', 'Plancha china', ARRAY['Colócate boca abajo apoyando antebrazos y puntas de los pies.', 'Alinea la cabeza, la espalda y las caderas en una línea recta.', 'Activa glúteos y abdomen para evitar que la cadera se hunda o se eleve.', 'Mantén la posición respirando de forma constante durante el tiempo indicado.', 'Evita aguantar la respiración o dejar caer la cabeza.']::text[], 'intermedio', 'Isométrico que trabaja abdomen, oblicuos y glúteos, mejorando la estabilidad del core y la resistencia postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '8610'),
('86d2e66a-3720-573f-a606-9ac81fe87d35', 'Estiramiento de rodillas con círculos', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.', 'Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies.', 'Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario.', 'Realiza el movimiento el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza gemelos, isquiotibiales y cuádriceps mediante círculos suaves que preparan las piernas para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0257'),
('46caf3ae-65dc-5c64-ba6c-59732269762f', 'Flexiones con palmada', ARRAY['Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.', 'Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo.', 'Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico que trabaja pectorales, tríceps y hombros, desarrollando potencia y explosividad en el tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1273'),
('dadfdfc7-4c92-5ee9-8f18-1daba2fb9e1a', 'Trepar barras de mono', ARRAY['Agarra la primera barra con las dos manos y cuélgate con los brazos extendidos.', 'Balancea el cuerpo y suelta una mano para agarrar la siguiente barra.', 'Avanza alternando las manos sin perder el control del balanceo.', 'Mantén el core activo y evita soltar ambas manos a la vez.', 'Baja con cuidado al final del recorrido y descansa entre series.']::text[], 'intermedio', 'Fortalece dorsales, antebrazos y agarre, mejorando la coordinación y la fuerza de tracción en suspensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4216'),
('508030f1-bb08-53fb-8103-d2f330c7f05e', 'Sentadilla goblet reloj', ARRAY['Sujeta una mancuerna a la altura del pecho con ambas manos y los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Al subir, desplaza ligeramente el peso hacia un lado como si marcaras las horas de un reloj.', 'Alterna las direcciones en cada repetición manteniendo el core activo.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y core con una mancuerna al pecho, mejorando la fuerza y el control en distintas direcciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10191'),
('3523f773-978c-5de8-b735-508008007da5', 'Flexión de reloj', ARRAY['Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado.', 'Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro.', 'Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado.', 'Continúa alternando lados en cada repetición.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con un recorrido circular que añade control y estabilidad al core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0258'),
('4f7a9701-1510-5215-aa8d-5c98a6c88f14', 'Dominada supina con agarre cerrado', ARRAY['Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales, bíceps y antebrazos con un agarre estrecho que aumenta el recorrido y la intensidad del ejercicio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1327'),
('7b53e5b2-e00d-5ee0-bcca-68fdb29bd911', 'Dominada con agarre cerrado', ARRAY['Agarra la barra con las palmas hacia fuera y las manos más juntas que la anchura de los hombros.', 'Cuélgate con los brazos extendidos y el core activo.', 'Tira de la barra llevando los codos hacia abajo hasta que la barbilla supere la barra.', 'Evita balancearte o encoger los hombros durante la subida.', 'Baja de forma controlada hasta la extensión completa de los brazos.']::text[], 'intermedio', 'Trabaja dorsales, bíceps y espalda alta con un agarre estrecho que incrementa la activación del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5479'),
('98af5e89-ee82-5764-a3b8-42c14b20821b', 'Flexiones con agarre cerrado', ARRAY['Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros.', 'Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfocadas en tríceps, pecho y hombros, mejoran la fuerza de empuje y la estabilidad del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0259');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('4e5aa4e0-ba53-55a8-a893-fd030e2a1343', 'Cargada de fuerza desde el suelo', ARRAY['Coloca los pies a la anchura de las caderas con la barra pegada a las espinillas.', 'Agarra la barra y empuja el suelo con las piernas manteniendo la espalda recta.', 'Extiende caderas y rodillas a la vez y sube la barra cerca del cuerpo.', 'Evita redondear la zona lumbar o tirar solo con los brazos.']::text[], 'avanzado', 'Trabaja cuádriceps, glúteos y hombros para ganar potencia y coordinación en el levantamiento.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5192'),
('a98baea8-f8c1-532e-ae3e-a5602fa2dec5', 'Flexión cobra', ARRAY['Túmbate boca abajo con las manos bajo los hombros y los codos pegados.', 'Empuja el suelo para subir el pecho mientras extiendes los brazos.', 'Baja con control hasta rozar el suelo con el pecho.', 'No dejes caer la cadera ni bloquees la respiración.']::text[], 'intermedio', 'Fortalece el pecho y los tríceps mientras moviliza la columna y activa el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3488'),
('2d2721cd-0623-5d1e-a924-667848d7d37e', 'Capullos', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexiona y extiende el tronco para trabajar el abdomen y los flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0260'),
('09c91524-49ea-5605-b1ed-f6b87d18294f', 'Curl concentrado', ARRAY['Siéntate y apoya el codo en la cara interna del muslo con la mancuerna colgando.', 'Sube la mancuerna flexionando el codo sin mover el hombro.', 'Baja despacio controlando el recorrido completo.', 'Evita balancear el torso o usar impulso para subir.']::text[], 'intermedio', 'Aísla el bíceps y el braquial para ganar fuerza y control en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2353'),
('7b507f5e-3a1d-5353-bc2d-8fe632b3d35c', 'Circuito con conos', ARRAY['Coloca varios conos en línea recta separados un metro.', 'Esquiva cada cono en zigzag a ritmo rápido.', 'Mantén las rodillas ligeramente flexionadas y el tronco erguido.', 'No cruces los pies ni frenes de golpe al girar.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la agilidad con cambios de dirección rápidos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5986'),
('c4f2d3a6-5174-5d55-b206-a97a1ee3aae4', 'Control de balance', ARRAY['Túmbate boca arriba con las piernas elevadas y los brazos estirados.', 'Despega la zona lumbar del suelo activando el abdomen.', 'Mantén la posición respirando de forma pausada.', 'Evita arquear la espalda o aguantar la respiración.']::text[], 'intermedio', 'Refuerza el core y la estabilidad del tronco mejorando el control postural.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2840'),
('b1c429ff-6b3e-537b-a216-3772181252f6', 'Sacacorchos', ARRAY['Túmbate boca arriba con las piernas juntas y elevadas.', 'Dibuja círculos lentos con las piernas sin tocar el suelo.', 'Mantén la zona lumbar pegada al suelo durante todo el recorrido.', 'No uses impulso ni dejes caer las piernas de golpe.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con rotación controlada del tronco y las piernas.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2841'),
('809170f0-1a60-50db-873f-c335180a12f7', 'Flexión sacacorchos', ARRAY['Colócate en posición de flexión con las manos bajo los hombros.', 'Baja el pecho y al subir gira el tronco llevando un brazo al techo.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita hundir la cadera o girar solo el brazo sin el tronco.']::text[], 'intermedio', 'Combina empuje de pecho y rotación para trabajar pectoral, tríceps y oblicuos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0261'),
('9621f7b8-8e35-5b6d-90e3-f1f57f2da83d', 'Postura del cadáver', ARRAY['Túmbate boca arriba con las piernas ligeramente separadas y los brazos junto al cuerpo.', 'Cierra los ojos y suelta el peso de hombros y caderas.', 'Respira lento y profundo por la nariz durante varios minutos.', 'No tenses el cuello ni te quedes con la mente acelerada.']::text[], 'intermedio', 'Relaja la columna y todo el cuerpo para favorecer la recuperación y calmar la respiración.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5889'),
('ff9b933f-a10a-51b9-9631-ed4a6d15a54f', 'Sentadilla cosaco', ARRAY['Separa los pies ampliamente con las puntas ligeramente hacia fuera.', 'Desplaza el peso a una pierna y flexiona esa rodilla bajando la cadera.', 'Mantén la otra pierna estirada con el pie apoyado.', 'Evita que la rodilla se vaya hacia dentro o levantar el talón.']::text[], 'intermedio', 'Fortalece glúteos y aductores mejorando la movilidad de cadera y el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2569'),
('15fdc00a-b21a-5e7d-8964-e0284036ac8e', 'Estiramiento de sofá', ARRAY['Arrodíllate con una pierna adelantada y el pie trasero apoyado en una superficie.', 'Mantén el tronco erguido y lleva la cadera hacia delante.', 'Nota el estiramiento en la parte delantera del muslo y aguanta.', 'No arquees la lumbar ni fuerces si sientes dolor en la rodilla.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera para aliviar la tensión de la zona anterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4557'),
('cb088178-8de6-5a83-b963-f6f663a9ad95', 'Sentadilla patinador con contrapeso', ARRAY['Sujeta un apoyo ligero delante con ambas manos para equilibrarte.', 'Apoya una pierna y lleva la otra hacia atrás con la rodilla flexionada.', 'Baja flexionando la pierna de apoyo manteniendo el tronco erguido.', 'Evita que la rodilla pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos sobre una pierna mejorando fuerza y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4363'),
('18d2d19d-67f3-5c65-8b31-b63f4ebf0276', 'Salto con contramovimiento y manos en la cadera', ARRAY['Coloca las manos en la cadera y los pies a la anchura de los hombros.', 'Flexiona rodillas y caderas rápidamente para cargar el salto.', 'Salta lo más alto posible y aterriza con las rodillas flexionadas.', 'Evita aterrizar con las piernas rígidas o perder el equilibrio.']::text[], 'intermedio', 'Desarrolla potencia de piernas y salto vertical con un gesto explosivo controlado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9514'),
('433a5652-c0bf-5707-b910-44e932dd376b', 'Salto con contramovimiento y balanceo de brazos', ARRAY['Ponte de pie con los pies a la anchura de los hombros y los brazos relajados.', 'Balancea los brazos atrás mientras flexionas rodillas y caderas.', 'Lanza los brazos arriba y salta con fuerza.', 'Aterriza suave con las rodillas flexionadas y evita caer con las piernas rectas.']::text[], 'intermedio', 'Mejora la potencia del tren inferior coordinando el impulso de brazos con el salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9513'),
('fe4eb507-f304-5e27-8f13-f78eb531935e', 'Postura de la cara de vaca', ARRAY['Siéntate con las piernas cruzadas y una rodilla sobre la otra.', 'Sube un brazo por detrás de la cabeza y el otro por la espalda baja.', 'Intenta enlazar las manos sin forzar y mantén la espalda erguida.', 'No fuerces el cuello ni aguantes la respiración.']::text[], 'intermedio', 'Estira tríceps, hombros y caderas mejorando la movilidad y la postura general.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6902'),
('cb0af411-3441-50db-9f00-92f26f5d138a', 'Postura de yoga de la vaca bitilasana', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Inhala mientras arqueas la espalda, elevas el pecho y miras ligeramente hacia arriba.', 'Exhala para volver a la posición neutra sin hundir la zona lumbar.', 'Evita forzar el cuello: el movimiento nace de la columna, no de la cabeza.']::text[], 'intermedio', 'Moviliza la columna y abre el pecho, ideal para calentar la espalda y aliviar la rigidez tras horas sentado.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6901'),
('25c7dd1e-bebd-5086-9a3d-e722be1a1fca', 'Postura del cangrejo', ARRAY['Siéntate con las rodillas flexionadas y las manos apoyadas detrás de la cadera.', 'Empuja con las manos y eleva la cadera hasta formar una línea con el tronco.', 'Abre el pecho y deja caer la cabeza suavemente hacia atrás.', 'Evita bloquear los codos o cargar demasiado peso en las muñecas.']::text[], 'principiante', 'Estira el pecho, los hombros y la cadera mientras abre la caja torácica y mejora la movilidad de la muñeca.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5054'),
('318c4372-e636-5000-bbe9-d1402fce30c6', 'Toque de pies con giro en cangrejo', ARRAY['Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo.', 'Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo.', 'Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie.', 'Regresa a la posición inicial y repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un giro controlado que también activa la cadera y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1468'),
('e5b3a964-a0f6-5369-afc7-049cf87569df', 'Caminata del cangrejo', ARRAY['Siéntate y apoya las manos detrás, eleva la cadera con los pies firmes en el suelo.', 'Desplázate hacia atrás alternando mano y pie sin dejar caer la cadera.', 'Mantén el abdomen firme y respira de forma constante durante el recorrido.', 'Evita encoger los hombros o bloquear los codos en exceso.']::text[], 'intermedio', 'Fortalece glúteos, tríceps y hombros mientras mejora la coordinación y la estabilidad del core en movimiento.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5881'),
('6b00c2aa-d3e2-52db-bdf4-198892e2dfc7', 'Postura de la grulla', ARRAY['Colócate en cuclillas con las manos apoyadas en el suelo, dedos abiertos.', 'Apoya las rodillas en la parte alta de los tríceps, cerca de las axilas.', 'Inclina el peso hacia delante y eleva los pies poco a poco del suelo.', 'Mantén la mirada al frente y evita apoyar la cabeza en el suelo.']::text[], 'intermedio', 'Equilibrio avanzado que fortalece antebrazos, core y hombros mientras exige concentración y control corporal.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0946'),
('8dda505f-ece7-5d9e-b03e-a78f9c9ddd43', 'Arrastre a cangrejo', ARRAY['Siéntate con las manos detrás y eleva la cadera formando la postura del cangrejo.', 'Desplázate hacia delante alternando mano y pie con movimientos cortos.', 'Mantén la cadera alta y el abdomen activo durante todo el recorrido.', 'Evita girar la cadera o apoyar las rodillas en el suelo.']::text[], 'intermedio', 'Combina desplazamiento y fuerza para activar abdomen, hombros y glúteos, mejorando control y resistencia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3950'),
('10f50086-f44c-56cd-8c38-d8d0501a6c08', 'Postura de la luna creciente', ARRAY['De rodillas o de pie, eleva un brazo por encima de la cabeza.', 'Inclínate hacia el lado contrario formando una curva suave con el tronco.', 'Mantén la cadera estable y respira profundo durante el estiramiento.', 'Evita rotar el tronco o forzar la zona lumbar.']::text[], 'intermedio', 'Estiramiento lateral que trabaja abdomen y oblicuos, mejora la flexibilidad de la columna y abre el costado.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0947'),
('db60c3dd-ae5a-5187-ace4-ef53b67c8c89', 'Salto de tijera cruzado', ARRAY['Empieza de pie con los pies juntos y los brazos a los lados.', 'Salta abriendo piernas y cruzando los brazos delante del pecho.', 'Aterriza con las rodillas ligeramente flexionadas y de forma suave.', 'Evita caer con las piernas rígidas o perder el ritmo respiratorio.']::text[], 'intermedio', 'Ejercicio cardiovascular que eleva las pulsaciones y activa piernas y hombros con un cruce coordinado.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4711'),
('17cfb152-0e67-58b8-9baf-cfb3fc115e97', 'Elevaciones de piernas cruzadas', ARRAY['Túmbate boca arriba con las manos bajo la zona lumbar y las piernas estiradas.', 'Eleva las piernas y crúzalas alternando una sobre otra sin tocar el suelo.', 'Baja despacio manteniendo el abdomen firme y la zona lumbar pegada.', 'Evita arquear la espalda o usar impulso para subir las piernas.']::text[], 'intermedio', 'Fortalece el abdomen bajo y los oblicuos con un cruce controlado que también activa los aductores.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4020'),
('51cee746-2395-5c20-adf4-19d4b3b192cf', 'Saltitos cruzados con paso atrás', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas.', 'Da un paso atrás y salta cruzando la pierna hacia el otro lado.', 'Aterriza suave con la rodilla flexionada y recupera el equilibrio.', 'Evita saltar demasiado alto si pierdes el control del aterrizaje.']::text[], 'intermedio', 'Trabajo pliométrico que potencia cuádriceps y glúteos, mejorando la reactividad y la estabilidad al aterrizar.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7194'),
('d650eb84-7f28-580f-aa79-4d6724320355', 'Salto encogido cruzado', ARRAY['Empieza de pie con los pies a la anchura de las caderas.', 'Salta llevando las rodillas al pecho y cruzándolas ligeramente.', 'Aterriza con las rodillas flexionadas y el abdomen activo.', 'Evita caer con las piernas estiradas o perder la verticalidad.']::text[], 'intermedio', 'Ejercicio explosivo que eleva la frecuencia cardíaca y activa piernas y core con un salto coordinado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '11283'),
('9c9f6422-f031-5695-a27d-cc470cfe737e', 'Postura del cocodrilo', ARRAY['Túmbate boca abajo con las manos bajo los hombros y los codos pegados al cuerpo.', 'Activa el abdomen y eleva el tronco manteniendo el cuerpo alineado.', 'Mantén la posición respirando de forma pausada y sin hundir la cadera.', 'Evita encoger los hombros o dejar caer la cabeza.']::text[], 'intermedio', 'Variante de plancha que fortalece abdomen, hombros y tríceps mientras mejora la estabilidad del core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4372'),
('3016ca42-71ad-5308-9e58-24a08802f21c', 'Abdominal cruzado', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un movimiento de rotación que mejora la fuerza del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0262'),
('48793018-4361-5300-a56e-98749d43288e', 'Puñetazo cruzado en sentadilla', ARRAY['Adopta una sentadilla con las rodillas flexionadas y el abdomen firme.', 'Lanza un puñetazo cruzado girando el tronco y la cadera.', 'Vuelve al centro y alterna el brazo manteniendo la sentadilla.', 'Evita extender del todo las piernas o girar solo con los brazos.']::text[], 'intermedio', 'Combina fuerza de piernas y rotación del tronco, mejorando potencia, coordinación y estabilidad del core.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '5233'),
('8ed12f78-64fc-560f-8dbc-172149a94046', 'Flexión cruzada', ARRAY['Colócate en posición de flexión con las manos bajo los hombros.', 'Baja el pecho y lleva una rodilla hacia el codo contrario.', 'Empuja para subir y alterna el lado en cada repetición.', 'Evita hundir la cadera o perder la alineación del tronco.']::text[], 'intermedio', 'Variante de flexión que suma rotación para trabajar pecho, tríceps y core con mayor control y estabilidad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3979'),
('2f85a361-6bd9-5991-9023-d75fa1c38d5f', 'Abdominal cruzado con giro', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos detrás de la cabeza sin tirar del cuello.', 'Eleva los hombros y lleva el codo derecho hacia la rodilla izquierda mientras extiendes la pierna contraria.', 'Alterna los lados con un ritmo controlado y espira en cada giro.', 'Evita tirar de la nuca y mantener la zona lumbar despegada del suelo.']::text[], 'intermedio', 'Trabaja recto abdominal y oblicuos, mejorando la estabilidad del core y la rotación controlada del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0263'),
('b5f5f93e-e377-560a-8944-08bf1e52a7bc', 'Jacks cruzados', ARRAY['Empieza de pie con los pies juntos y los brazos a los lados.', 'Salta abriendo las piernas y cruza los brazos delante del pecho.', 'Vuelve a la posición inicial y repite alternando el cruce de brazos.', 'Aterriza con las rodillas ligeramente flexionadas para amortiguar el impacto.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca con un ejercicio cardiovascular completo que activa piernas, glúteos y hombros.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0264'),
('5991d52c-ae4e-5803-88f7-4f4aa36d043e', 'Salto de tijera cruzado con salto', ARRAY['Colócate de pie con los pies juntos y los brazos pegados al cuerpo.', 'Salta abriendo piernas y brazos mientras cruzas una pierna por delante de la otra.', 'Cambia el cruce en cada salto manteniendo un ritmo constante.', 'Aterriza suave con las rodillas flexionadas y evita bloquear las piernas.']::text[], 'intermedio', 'Ejercicio pliométrico que mejora la potencia de piernas y eleva las pulsaciones con un patrón cruzado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5105'),
('6debd3e9-7522-5785-9a03-ab527c513aec', 'Estiramiento de hombro cruzado', ARRAY['Lleva un brazo cruzado delante del pecho a la altura del hombro.', 'Sujeta el codo con la mano contraria y acércalo suavemente al pecho.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita elevar el hombro o forzar el cuello durante el estiramiento.']::text[], 'principiante', 'Estira el deltoides y la zona posterior del hombro, aliviando tensión tras entrenamientos de empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1793'),
('c69aa1e0-d85b-57d3-80e3-0ba1300f464b', 'Abdominal cruzado de pie', ARRAY['De pie con los pies a la anchura de las caderas y las manos detrás de la cabeza.', 'Contrae el abdomen y lleva el codo derecho hacia la rodilla izquierda al elevar la pierna.', 'Alterna los lados con un movimiento controlado y espira en cada repetición.', 'Evita arquear la espalda o tirar del cuello con las manos.']::text[], 'intermedio', 'Activa recto abdominal y oblicuos en posición vertical, útil para trabajar el core sin tumbarse.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5846'),
('da841242-a177-5466-98c9-dee322f949c4', 'Abdominal con giro cruzado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos en la nuca.', 'Sube el tronco y gira llevando el codo derecho hacia la rodilla izquierda.', 'Baja de forma controlada y repite hacia el lado contrario.', 'Mantén el abdomen contraído y evita tirar de la cabeza.']::text[], 'intermedio', 'Combina flexión y rotación del tronco para reforzar recto abdominal y oblicuos con mayor control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5334'),
('4eee2e7a-044f-5e36-adc5-f0ea83f837ae', 'Patada frontal con brazos cruzados', ARRAY['De pie con los brazos cruzados delante del pecho y el abdomen activo.', 'Eleva una pierna extendiendo la rodilla en una patada frontal controlada.', 'Baja la pierna y alterna manteniendo el equilibrio sobre el pie de apoyo.', 'Evita inclinar el tronco hacia atrás al lanzar la patada.']::text[], 'intermedio', 'Mejora la potencia de cuádriceps y la estabilidad del core con una patada frontal explosiva.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5684'),
('bd0d589a-07e5-5cce-ab14-87ab26f828c4', 'Estiramiento cruzado de flexores de cadera', ARRAY['Arrodíllate con una pierna adelantada y la rodilla trasera apoyada en el suelo.', 'Lleva el brazo contrario a la pierna adelantada por encima de la cabeza e inclínate.', 'Avanza ligeramente la cadera hasta notar el estiramiento en la parte delantera.', 'Mantén veinte o treinta segundos y cambia de lado sin forzar la lumbar.']::text[], 'principiante', 'Libera tensión en flexores de cadera y cuádriceps, mejorando la movilidad de la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4296'),
('e2be66e4-da5e-51b8-aabb-8c9732770ca3', 'Zancada inversa cruzada', ARRAY['De pie con los pies juntos y las manos en la cintura.', 'Da un paso atrás cruzando la pierna por detrás de la otra y flexiona ambas rodillas.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Alterna los lados manteniendo el tronco erguido y la rodilla alineada con el pie.']::text[], 'intermedio', 'Fortalece glúteos y piernas con un patrón cruzado que exige estabilidad y control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1510'),
('e8ef3520-0119-5a45-b0bc-995c102a04b7', 'Estiramiento de aquiles en cuclillas', ARRAY['Colócate en cuclillas con las manos en el suelo para mantener el equilibrio.', 'Apoya un pie con el talón en el suelo y el otro ligeramente adelantado.', 'Desplaza el peso hacia atrás hasta notar el estiramiento en el tendón.', 'Mantén la posición sin levantar el talón y cambia de lado.']::text[], 'principiante', 'Estira el tendón de Aquiles y el sóleo, mejorando la flexibilidad del tobillo y la pisada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1890'),
('5407a547-98cd-5fd1-9f0c-350ca9fbcf19', 'Abdominal con brazos en el pecho', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los brazos cruzados sobre el pecho.', 'Eleva los hombros del suelo contrayendo el abdomen y espirando.', 'Baja lentamente sin apoyar del todo la cabeza.', 'Evita impulsarte con el cuello o despegar la zona lumbar.']::text[], 'intermedio', 'Trabaja el recto abdominal con un rango controlado, reduciendo la tensión en el cuello.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4727'),
('8f374c3c-3c6e-5bc6-9751-637b1a6a7843', 'Abdominal contra la pared', ARRAY['Siéntate frente a la pared con las rodillas flexionadas y los pies apoyados.', 'Apoya la espalda y desliza el tronco hacia abajo hasta una ligera flexión.', 'Contrae el abdomen y sube los hombros separándolos de la pared.', 'Mantén el movimiento corto y evita tirar del cuello.']::text[], 'intermedio', 'Versión guiada del abdominal que ayuda a controlar el rango y activar el core con apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7414'),
('d1462d5d-b77f-55fb-8f60-f98fec45b455', 'Abdominal con control de técnica', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los brazos extendidos.', 'Activa el abdomen y eleva los hombros manteniendo la lumbar apoyada.', 'Sube y baja de forma lenta controlando cada fase del movimiento.', 'Evita arquear la espalda o usar el impulso de los brazos.']::text[], 'intermedio', 'Refuerza el abdomen priorizando la técnica y la estabilidad de la espalda en cada repetición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2344'),
('053bbbe3-de50-52ee-b8ac-df99d2b675fc', 'Abdominal en el suelo', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas.', 'Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el recto abdominal y los flexores de cadera para mejorar el control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0274'),
('1dda7485-f292-5951-8beb-200e087a464b', 'Abdominal mantenido', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos en la nuca.', 'Eleva los hombros y mantén la posición con el abdomen contraído.', 'Respira de forma constante sin aguantar la respiración.', 'Evita tirar del cuello y baja de forma controlada al terminar.']::text[], 'intermedio', 'Isométrico que mantiene la tensión en el abdomen, mejorando la resistencia del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4332'),
('728d123d-25c2-5a8c-ad56-d9c65349b357', 'Abdominal con elevación de una pierna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva una pierna manteniendo la rodilla doblada y el abdomen activado.', 'Sube la parte alta de la espalda despegando los omóplatos del suelo mientras espiras.', 'Baja despacio sin apoyar del todo la cabeza y cambia de pierna.', 'Evita tirar del cuello con las manos y no arquees la zona lumbar.']::text[], 'intermedio', 'Trabaja el recto abdominal y los flexores de cadera, mejorando el control del core y la estabilidad lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4331'),
('171d56db-a6c9-59d6-a48f-2483801e7244', 'Abdominal con elevación de piernas', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Eleva las piernas hasta unos 45 grados manteniendo la lumbar pegada al suelo.', 'Sube la parte alta de la espalda mientras espiras y activas el abdomen.', 'Baja las piernas y el tronco de forma controlada sin tocar el suelo.', 'Evita arquear la espalda baja o usar impulso para subir.']::text[], 'intermedio', 'Refuerza el abdomen y la zona baja del core, mejorando la estabilidad y el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4095'),
('998ad044-c89b-5ecb-bb0f-9376716a4e97', 'Abdominal corto', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el recto abdominal con un recorrido corto, ideal para trabajar el core sin cargar la lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3016'),
('da53e2b3-cbfc-56ff-b21e-7860cce41528', 'Sentadilla curtsy', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.', 'Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.', 'Mantén el torso erguido y el peso sobre el pie delantero.', 'Empuja con el pie delantero para regresar a la posición inicial.', 'Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con un patrón cruzado que añade control y estabilidad al tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3769'),
('ad325672-e463-5564-af1d-3776ffa955c6', 'Bicicleta elíptica', ARRAY['Ajusta la altura del asiento y colócate en la bicicleta elíptica.', 'Coloca los pies en los pedales y sujeta el manillar.', 'Comienza a pedalear con un movimiento suave y controlado.', 'Mantén un ritmo constante y aumenta la resistencia si lo deseas.', 'Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.']::text[], 'principiante', 'Ejercicio cardiovascular de bajo impacto que activa piernas y glúteos mientras mejora la resistencia.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2331'),
('69d0fa31-af33-5981-b828-d5693cf012df', 'Postura del bailarín', ARRAY['De pie, flexiona una rodilla y sujeta el pie por detrás con la mano del mismo lado.', 'Extiende el otro brazo hacia delante o arriba para mantener el equilibrio.', 'Inclina el tronco ligeramente hacia delante mientras empujas el pie hacia el glúteo.', 'Respira de forma profunda y mantén la postura sin forzar la lumbar.', 'Evita abrir la cadera hacia fuera o perder la alineación de la rodilla.']::text[], 'intermedio', 'Estiramiento de yoga que abre el pecho y los flexores de cadera mientras fortalece glúteos y equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6304'),
('52122295-9a45-5d33-a880-e4b6c6dfa8d1', 'Bicho muerto', ARRAY['Túmbate boca arriba con los brazos extendidos hacia el techo.', 'Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.', 'Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.', 'Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite el movimiento con el brazo izquierdo y la pierna derecha.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el core profundo y la zona lumbar, enseñando a mantener la estabilidad mientras se mueven brazos y piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0276'),
('fd6cf77d-a2be-50f1-a759-e994ecb5a21b', 'Bicho muerto con balón medicinal', ARRAY['Túmbate boca arriba con el balón sujeto con las manos sobre el pecho.', 'Eleva brazos y piernas hasta formar un ángulo recto con el suelo.', 'Extiende un brazo con el balón y la pierna contraria a la vez, sin despegar la lumbar.', 'Vuelve al centro y alterna el lado contrario manteniendo el abdomen activo.', 'Evita arquear la espalda o soltar el balón de forma descontrolada.']::text[], 'intermedio', 'Añade carga al core para mejorar la estabilidad y la coordinación entre brazos y piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '4124'),
('7f973c53-2acb-500a-903e-6c0966dfae7e', 'Estiramiento colgado', ARRAY['Agárrate a una barra con las palmas hacia delante y los brazos estirados.', 'Deja que el cuerpo cuelgue relajando los hombros y separándolos de las orejas.', 'Respira despacio y mantén la posición sin balancearte.', 'Baja con cuidado apoyando los pies antes de soltar la barra.', 'Evita soltarte de golpe o forzar si notas dolor en los hombros.']::text[], 'principiante', 'Descomprime la columna y estira dorsales y hombros, aliviando la tensión acumulada en la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5055'),
('d2794359-5dd8-59c5-b1f2-5eddc17b3aa7', 'Peso muerto con control de espalda', ARRAY['Colócate con la barra pegada a las espinillas y los pies a la anchura de las caderas.', 'Agarra la barra y saca pecho manteniendo la espalda recta y los omóplatos juntos.', 'Empuja el suelo con los pies y sube extendiendo caderas y rodillas a la vez.', 'Baja la barra controlando el movimiento y manteniendo la espalda neutra.', 'Evita redondear la espalda o tirar con los brazos en lugar de con las piernas.']::text[], 'intermedio', 'Enseña a mantener la espalda neutra en el peso muerto, protegiendo la lumbar y activando glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2354'),
('8ffc437e-91e8-55d6-93e6-dfaacc940b16', 'Peso muerto con control de cadera', ARRAY['De pie con la barra frente a ti y los pies a la anchura de las caderas.', 'Lleva las caderas hacia atrás mientras bajas la barra pegada a las piernas.', 'Mantén la espalda recta y las rodillas ligeramente flexionadas durante el descenso.', 'Empuja las caderas hacia delante para subir apretando los glúteos al final.', 'Evita flexionar demasiado las rodillas o redondear la zona lumbar.']::text[], 'intermedio', 'Refuerza el patrón de bisagra de cadera, trabajando glúteos e isquios con una técnica segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2357'),
('84d7fbbb-3b38-5779-8a43-fbb30eee42f7', 'Abdominal reverso declinado con piernas flexionadas', ARRAY['Túmbate en un banco declinado con la cabeza más baja y sujétate por detrás.', 'Flexiona las rodillas y eleva las piernas hacia el pecho.', 'Despega la cadera del banco contrayendo el abdomen bajo mientras espiras.', 'Baja las piernas de forma controlada sin dejar caer la cadera.', 'Evita usar impulso o balancear las piernas para subir.']::text[], 'intermedio', 'Incide en la zona baja del abdomen con mayor recorrido gracias a la inclinación del banco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1845'),
('0f5c2058-f5dd-5f7a-84e7-3213470f9b62', 'Abdominal declinado', ARRAY['Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados.', 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aumenta el recorrido del abdominal clásico para trabajar el recto abdominal con mayor intensidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0277'),
('8c9c1e7e-084e-51eb-bf03-51b296dadc07', 'Flexión diamante declinada', ARRAY['Coloca las manos juntas formando un diamante bajo el pecho y los pies elevados.', 'Mantén el cuerpo alineado y el core activado durante todo el movimiento.', 'Baja el pecho hacia las manos flexionando los codos cerca del torso.', 'Empuja el suelo para subir sin bloquear del todo los codos.', 'Evita abrir los codos hacia fuera o dejar caer la cadera.']::text[], 'intermedio', 'Potencia tríceps y pecho con una variante declinada que incrementa la carga sobre los brazos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5866'),
('0e55aa13-5573-5d35-9e53-8f64f304aa4b', 'Elevación de rodillas declinada', ARRAY['Cuélgate de una barra o colócate en un banco declinado con sujeción firme.', 'Eleva las rodillas hacia el pecho contrayendo el abdomen mientras espiras.', 'Baja las piernas despacio sin balancear el cuerpo.', 'Mantén el core activo y evita arquear la lumbar.', 'No uses impulso ni dejes caer las piernas de golpe.']::text[], 'intermedio', 'Trabaja el abdomen bajo y los flexores de cadera con un rango mayor gracias a la inclinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6548'),
('6388c6c3-f464-56d3-aff9-00e9af4365fe', 'Flexión declinada de rodillas en cajón', ARRAY['Coloca las rodillas en el suelo y las manos sobre el cajón, a la anchura de los hombros.', 'Baja el pecho hacia el cajón manteniendo el cuerpo alineado desde las rodillas a la cabeza.', 'Empuja con fuerza hasta estirar los brazos sin bloquear los codos.', 'Evita que la cadera se hunda o suba demasiado durante el recorrido.']::text[], 'intermedio', 'Trabaja el pecho con apoyo elevado y rodillas en el suelo, ideal para progresar hacia flexiones completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3490'),
('ebee99b4-5137-502b-8727-f6ab9a69b789', 'Press pike declinado entre bancos', ARRAY['Apoya las manos en el suelo entre dos bancos y eleva los pies sobre uno de ellos.', 'Forma una V invertida con la cadera alta y la cabeza entre los brazos.', 'Baja la cabeza hacia el suelo flexionando los codos y vuelve a empujar.', 'Mantén el core firme y evita arquear la espalda baja.']::text[], 'intermedio', 'Fortalece los hombros con el peso corporal en posición de pike, útil para ganar fuerza hacia el press vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3915'),
('a3496416-e1f5-5ce4-b301-0aa61150a6e4', 'Flexión declinada de rodillas', ARRAY['Apoya las rodillas en el suelo y los pies elevados sobre una superficie estable.', 'Coloca las manos algo más anchas que los hombros y el cuerpo alineado.', 'Desciende el pecho controlando el movimiento y empuja para subir.', 'No dejes caer la cadera ni adelantes la cabeza al bajar.']::text[], 'intermedio', 'Variante de flexión con pies elevados que aumenta la carga en el pecho y los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3935'),
('c3463aa5-c60f-5538-b731-432fd1dd308c', 'Flexión declinada contra la pared', ARRAY['Apoya las manos en la pared a la altura del pecho y da un paso atrás.', 'Mantén el cuerpo recto desde la cabeza hasta los talones.', 'Flexiona los codos acercando el pecho a la pared y empuja para volver.', 'Evita sacar la cadera o doblar la espalda durante el movimiento.']::text[], 'intermedio', 'Versión suave de flexión con inclinación que reduce la carga y sirve para iniciarse.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3491'),
('7c5af893-44df-50ee-a226-9b650fcdb076', 'Flexiones declinadas', ARRAY['Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.', 'Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.', 'Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión con pies elevados que intensifica el trabajo del pecho superior y los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0279'),
('0a9cab4d-b434-5b0f-bc2e-193d7ff59710', 'Toque de hombro declinado', ARRAY['Coloca los pies elevados y las manos en el suelo en posición de plancha.', 'Levanta una mano y toca el hombro contrario sin mover la cadera.', 'Alterna los lados manteniendo el abdomen apretado y la respiración constante.', 'Evita girar el tronco o hundir la zona lumbar.']::text[], 'intermedio', 'Ejercicio de core y hombros en plancha inclinada que mejora la estabilidad y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3823'),
('9fa21e46-5e34-5809-808a-30185142c1b6', 'Abdominal declinado con giro ruso', ARRAY['Túmbate con los pies sujetos y el tronco declinado hacia atrás.', 'Sube flexionando el abdomen y gira el tronco hacia un lado.', 'Baja controlando y repite hacia el otro lado.', 'No tires del cuello con las manos ni uses impulso para subir.']::text[], 'intermedio', 'Combina flexión de tronco y rotación para trabajar rectos y oblicuos con mayor rango.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4972'),
('e2c71952-2593-5734-97b4-dae2709b6da9', 'Abdominal completo declinado', ARRAY['Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.', 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión de tronco en banco declinado que trabaja el abdomen con mayor recorrido.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0282'),
('472d2c30-e6d5-5f54-a5fe-ecdd149f5513', 'Abdominal declinado con giro', ARRAY['Túmbate en el banco declinado con los pies sujetos y las manos en el pecho.', 'Sube flexionando el abdomen y gira el tronco hacia un lado arriba.', 'Desciende controlando y alterna el giro en cada repetición.', 'Evita tirar del cuello o balancear el cuerpo para ganar impulso.']::text[], 'intermedio', 'Añade rotación al abdominal declinado para implicar oblicuos y mejorar el control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2523'),
('f819ac0f-1bc4-555e-afb5-5cc2c3bca9f3', 'Sentadilla profunda', ARRAY['Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja la cadera llevando el peso a los talones y el pecho erguido.', 'Desciende todo lo que tu movilidad permita sin curvar la espalda.', 'Empuja con los pies para subir y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Sentadilla con gran recorrido que trabaja cuádriceps y glúteos y mejora la movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8220'),
('d67514a9-c822-5fcd-8fc6-dc36aa330f05', 'Zancada profunda a estiramiento de isquiotibiales', ARRAY['Da un paso largo y baja la rodilla trasera hacia el suelo.', 'Lleva el peso atrás y estira la pierna delantera con la punta del pie hacia arriba.', 'Mantén la espalda recta y siente el estiramiento en la parte posterior del muslo.', 'Respira de forma pausada y evita rebotar en la posición.']::text[], 'principiante', 'Estiramiento dinámico que abre cadera y flexores y alarga la parte posterior del muslo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8162'),
('c55fc5ff-f055-512f-b4ad-a6100735666a', 'Flexiones profundas', ARRAY['Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.', 'Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión con mayor recorrido usando mancuernas como apoyo para trabajar el pecho en amplitud.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '1274'),
('69b8abe1-057e-54d2-b9f6-902e523955c8', 'Flexión profunda en barras paralelas', ARRAY['Sujeta las barras paralelas y colócate en posición de plancha con los brazos estirados.', 'Baja el pecho entre las barras controlando el descenso.', 'Empuja para volver arriba sin bloquear bruscamente los codos.', 'Mantén el cuerpo alineado y evita hundir la cadera.']::text[], 'intermedio', 'Flexión en barras que permite un descenso amplio y trabaja pecho, hombros y tríceps.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6910'),
('736a0cce-5ea1-5745-aafa-b1d12a77a9f5', 'Postura base', ARRAY['Colócate de pie con los pies juntos o a la anchura de la cadera.', 'Alarga la columna, relaja los hombros y activa ligeramente el abdomen.', 'Respira de forma profunda y mantén la mirada al frente.', 'Evita bloquear las rodillas o sacar la cadera hacia delante.']::text[], 'intermedio', 'Postura neutra de pie que alinea la columna y activa el core para iniciar la práctica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0948'),
('145ab3a2-81b6-59cf-a2d6-e1424f81840d', 'Estiramiento en depresión en barras paralelas', ARRAY['Sujeta las barras paralelas con los brazos estirados y el cuerpo relajado.', 'Deja caer el pecho entre los hombros sin forzar la zona lumbar.', 'Mantén la posición respirando de forma lenta y controlada.', 'Evita rebotar o hundirte más de lo que tu movilidad permite.']::text[], 'principiante', 'Estiramiento de dorsales y pecho apoyado en barras que mejora la movilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1989'),
('878f2271-da68-5bfc-8715-7c0dad0e893a', 'Salto en profundidad', ARRAY['Sube a una plataforma baja y colócate en el borde con los pies a la anchura de las caderas.', 'Déjate caer y, al tocar el suelo, amortigua con las rodillas ligeramente flexionadas.', 'Salta hacia arriba lo más alto posible en cuanto los pies contacten el suelo.', 'Aterriza suave con las rodillas alineadas y evita que se metan hacia dentro.', 'Mantén el tronco firme y no bloquees las rodillas en ningún momento.']::text[], 'intermedio', 'Trabaja la potencia de cuádriceps y glúteos con un salto reactivo tras caer desde una altura, mejorando la explosividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4844'),
('34392159-c8d5-508e-b252-bf8ce3e150f3', 'Salto en profundidad a salto largo', ARRAY['Colócate en el borde de una plataforma baja con los pies a la anchura de las caderas.', 'Déjate caer y amortigua el impacto con una flexión ligera de rodillas.', 'En cuanto toques el suelo, salta hacia delante lo más lejos que puedas.', 'Aterriza con ambos pies a la vez y flexiona las rodillas para absorber el golpe.', 'Evita quedarte parado antes de saltar: el contacto debe ser rápido y reactivo.']::text[], 'intermedio', 'Combina caída y salto horizontal para desarrollar potencia de piernas y capacidad reactiva en cuádriceps y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4843'),
('a4b4ee3f-604a-561c-8954-5524f112aa3d', 'Salto en profundidad a salto de valla', ARRAY['Sitúate en el borde de una plataforma baja frente a una valla pequeña.', 'Déjate caer y amortigua con las rodillas ligeramente flexionadas.', 'Salta por encima de la valla en cuanto los pies toquen el suelo.', 'Aterriza suave con los pies paralelos y las rodillas alineadas.', 'Ajusta la altura de la valla para que el aterrizaje sea seguro y controlado.']::text[], 'intermedio', 'Entrena la reactividad y la potencia vertical de las piernas saltando una valla tras una caída controlada.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4198'),
('13644718-1b30-572a-8401-932673a5e74f', 'Isométrico de flexión diagonal', ARRAY['De pie con los pies a la anchura de las caderas, cruza los brazos por encima de la cabeza.', 'Inclínate despacio hacia un lado manteniendo la cadera estable y el tronco largo.', 'Mantén la posición entre quince y treinta segundos respirando con calma.', 'Evita arquear la espalda o girar el tronco: el movimiento es solo lateral.', 'Cambia de lado y repite el mismo tiempo para equilibrar.']::text[], 'principiante', 'Estiramiento activo que alarga la cadena posterior y los costados, aliviando tensión en espalda y caderas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6762'),
('2575c57d-b87f-521b-8450-408895184bf5', 'Estiramiento de cuello con flexión diagonal', ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Inclina la cabeza en diagonal hacia un hombro sin levantarlo.', 'Ayúdate con la mano del mismo lado apoyándola suavemente sobre la cabeza.', 'Mantén de quince a treinta segundos respirando despacio y sin tirar fuerte.', 'Evita girar la cabeza o forzar el cuello; cambia de lado con suavidad.']::text[], 'principiante', 'Alivia la tensión del elevador de la escápula y el trapecio, mejorando la movilidad cervical tras horas de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1832'),
('553ff159-2914-5843-9c54-04a4a0306a82', 'Zancada diagonal', ARRAY['De pie con los pies juntos y las manos en la cintura.', 'Da un paso en diagonal hacia delante y flexiona la rodilla delantera.', 'Mantén la rodilla trasera cerca del suelo sin que choque con fuerza.', 'Impulsa con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se meta hacia dentro: mantenla alineada con el pie.']::text[], 'intermedio', 'Zancada dinámica que activa cuádriceps, glúteos y aductores, mejorando estabilidad y coordinación en el tren inferior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4552'),
('7a7c5313-6556-5d2c-9535-f1710a28158d', 'Puñetazo diagonal', ARRAY['De pie con las piernas ligeramente flexionadas y los puños junto al mentón.', 'Lanza un puñetazo en diagonal hacia delante girando el tronco y la cadera.', 'Recoge el brazo rápido y alterna con el otro lado.', 'Mantén el abdomen firme y respira de forma continua durante el gesto.', 'Evita bloquear el codo al extender el brazo del todo.']::text[], 'intermedio', 'Movimiento explosivo que activa hombros y core, mejorando la coordinación y la potencia del tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4824'),
('5f8d3963-6dc6-500b-a677-750f5b396f4f', 'Alcance diagonal en silla', ARRAY['Siéntate en el borde de una silla con la espalda recta y los pies apoyados.', 'Extiende un brazo en diagonal hacia arriba y hacia el lado contrario.', 'Acompaña el movimiento con una ligera inclinación del tronco sin encorvarte.', 'Mantén unos segundos y vuelve despacio al centro respirando con calma.', 'Evita tirar del cuello o redondear la espalda durante el alcance.']::text[], 'principiante', 'Ejercicio de movilidad y control del core que estira la espalda y los costados desde una posición sentada segura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6632'),
('c9801bab-93a9-523c-ba0f-d5b43e0f46c1', 'Flexión diamante de rodillas', ARRAY['Apóyate sobre las rodillas con las manos juntas formando un diamante bajo el pecho.', 'Mantén el cuerpo alineado desde la cabeza hasta las rodillas.', 'Baja el pecho hacia el suelo flexionando los codos cerca del tronco.', 'Empuja para volver arriba sin bloquear los codos del todo.', 'Evita abrir los codos hacia fuera o dejar caer la cadera.']::text[], 'intermedio', 'Variante de flexión que concentra el trabajo en tríceps y pecho, ideal para progresar con menos carga.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1174'),
('9e13ea01-b636-5e95-9710-cef800179309', 'Flexiones diamante', ARRAY['Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.', 'Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.', 'Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión con manos juntas que enfatiza tríceps y pecho, aumentando la fuerza del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0283'),
('06de7b9c-0af1-5186-be86-f52486c41a08', 'Sostén en fondos', ARRAY['Colócate en posición de fondo con las manos en una superficie estable y los brazos extendidos.', 'Baja el cuerpo flexionando los codos hasta unos noventa grados.', 'Mantén la posición con el tronco erguido y los hombros lejos de las orejas.', 'Respira con normalidad y aguanta entre diez y treinta segundos.', 'Evita hundir los hombros o dejar caer la cadera durante el sostén.']::text[], 'intermedio', 'Isométrico que fortalece tríceps, pecho y hombros manteniendo la posición baja del fondo para ganar resistencia.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1442'),
('08d485bd-f66d-5b24-9798-1398fc499059', 'Fondos entre sillas', ARRAY['Coloca dos sillas estables separadas a la anchura de los hombros.', 'Apoya las manos en los bordes y extiende los brazos con los pies en el suelo.', 'Baja el cuerpo flexionando los codos hasta que los brazos formen unos noventa grados.', 'Empuja con los tríceps para volver arriba sin bloquear los codos.', 'Evita encoger los hombros o separar las sillas durante el movimiento.']::text[], 'intermedio', 'Ejercicio de calistenia que trabaja tríceps, pecho y hombros usando dos sillas como soporte.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3387'),
('87621134-bd9e-52ed-aab4-7661f511a2bd', 'Mantenimiento dish', ARRAY['Túmbate boca arriba con las piernas extendidas y los brazos a los lados.', 'Eleva ligeramente piernas, brazos y cabeza formando una forma de cuenco.', 'Mantén la zona lumbar pegada al suelo y el abdomen firme.', 'Aguanta entre quince y treinta segundos respirando de forma controlada.', 'Evita arquear la espalda o aguantar la respiración durante el sostén.']::text[], 'intermedio', 'Isométrico de core que activa abdomen y flexores de cadera, mejorando la estabilidad del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9486'),
('6f041130-b5ff-5fe1-be68-4c0d6ac812bf', 'Postura del delfín', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Apoya los antebrazos en el suelo con los codos a la anchura de los hombros.', 'Eleva las caderas hacia arriba formando una V invertida con la espalda larga.', 'Mantén la posición respirando despacio y sin hundir los hombros.', 'Evita bloquear las rodillas o cargar el peso en el cuello.']::text[], 'intermedio', 'Postura de yoga que fortalece hombros y espalda alta mientras estira isquiotibiales y gemelos.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6288'),
('d6e875b4-720f-5ca9-b9a5-80ff6739a537', 'Elevación de gemelos burro', ARRAY['Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.', 'Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.', 'Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Elevación de talones que trabaja los gemelos y sóleo, mejorando la fuerza y resistencia del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0284'),
('2502ff78-fe7f-5ff3-8a9a-0604dd4b39e8', 'Estiramiento de pecho en el marco de una puerta', ARRAY['Coloca el antebrazo en el marco de la puerta con el codo a la altura del hombro.', 'Da un paso adelante hasta notar tensión en el pecho, sin dolor.', 'Mantén la posición entre veinte y treinta segundos respirando despacio.', 'Evita arquear la espalda o sacar el hombro hacia delante.', 'Cambia de lado y repite el mismo tiempo.']::text[], 'principiante', 'Abre el pecho y los hombros tras horas de estudio o de empuje, aliviando la tensión acumulada en la zona anterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7553'),
('8058fc56-073e-59c2-ae57-9d5274b929d8', 'Ejercicio de puntos', ARRAY['Dibuja o imagina una cuadrícula de cuatro puntos en el suelo.', 'Salta con los dos pies de punto en punto lo más rápido que puedas.', 'Aterriza con la parte delantera del pie y las rodillas ligeramente flexionadas.', 'Mantén el tronco firme y la mirada al frente durante todo el recorrido.', 'Evita saltar con los talones para no perder elasticidad.']::text[], 'intermedio', 'Mejora la coordinación y la reactividad de tobillos y gemelos con saltos rápidos sobre una cuadrícula.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5969'),
('d23b2c05-4032-5dae-9342-d7f5ae0014db', 'Doble salto de cuerda', ARRAY['Sujeta la cuerda a la altura de las caderas con los codos cerca del cuerpo.', 'Gira las muñecas rápido para que la cuerda pase dos veces en un solo salto.', 'Salta bajo, con las rodillas ligeramente flexionadas y aterrizando de puntillas.', 'Mantén la respiración constante y evita encoger los hombros.', 'Si pierdes el ritmo, vuelve al salto simple antes de reintentar.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y la coordinación haciendo pasar la cuerda dos veces por cada salto.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5038'),
('b9ceca0c-ddbb-5dea-90ca-146cc6b54f6a', 'Doble sentadilla con salto', ARRAY['Separa los pies a la anchura de los hombros con los brazos al frente.', 'Baja en sentadilla hasta que los muslos queden paralelos al suelo.', 'Empuja con fuerza y salta lo más alto posible.', 'Aterriza con las rodillas flexionadas y el pecho erguido, sin dejarlas caer hacia dentro.', 'Respira al saltar y evita encadenar saltos si pierdes la técnica.']::text[], 'intermedio', 'Potencia piernas y glúteos con un salto explosivo que también exige control del core al aterrizar.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3704'),
('ffa03f84-03cb-5f8c-9d49-60d53f881cac', 'Estiramiento de espinilla de rodillas', ARRAY['Arrodíllate en el suelo con los empeines apoyados y el cuerpo erguido.', 'Siéntate suavemente sobre los talones sin forzar las rodillas.', 'Mantén la posición veinte o treinta segundos respirando con calma.', 'Evita inclinar el tronco hacia delante para no perder el estiramiento.', 'Sal despacio apoyando las manos si notas molestias.']::text[], 'principiante', 'Estira la parte delantera de la espinilla y el empeine, útil tras correr o caminar mucho.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1960'),
('b347e06c-5e02-55e1-9e38-3f068567376f', 'Estiramiento de cuádriceps inclinado hacia atrás', ARRAY['Arrodíllate con una pierna adelantada y el pie apoyado.', 'Lleva la cadera hacia delante y el tronco ligeramente hacia atrás.', 'Sujeta el tobillo de la pierna trasera si necesitas más tensión.', 'Mantén veinte o treinta segundos sin arquear la zona lumbar.', 'Cambia de pierna y repite el mismo tiempo.']::text[], 'principiante', 'Alarga la parte anterior del muslo y los flexores de cadera tras sesiones de carrera o sentadillas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1956'),
('cc9f005b-c47d-5a68-a7ab-d2fd2efabd9e', 'Patada al glúteo', ARRAY['Colócate de pie con el tronco erguido y los brazos relajados.', 'Lleva un talón hacia el glúteo de forma rápida y alterna las piernas.', 'Mantén las rodillas apuntando al suelo y el core activo.', 'Respira de forma constante y evita inclinarte hacia atrás.', 'Baja el ritmo si pierdes el equilibrio.']::text[], 'intermedio', 'Activa isquiotibiales y eleva las pulsaciones con un movimiento dinámico de talones al glúteo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1549'),
('da447a28-2ba4-52a8-a073-1ebccaa13cc8', 'Estiramiento de doble pierna', ARRAY['Túmbate boca arriba con las rodillas hacia el pecho y los brazos estirados.', 'Estira brazos y piernas a la vez sin tocar el suelo con la espalda baja.', 'Mantén la zona lumbar pegada al suelo durante todo el movimiento.', 'Vuelve a la posición inicial respirando al recoger.', 'Evita arquear la espalda o tirar del cuello.']::text[], 'intermedio', 'Fortalece el abdomen profundo y mejora el control del core con un movimiento lento y controlado.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2843'),
('610cd36b-69d4-5e2f-9bd1-b2d88ff32117', 'Postura de la doble paloma', ARRAY['Siéntate con una pierna flexionada delante y la otra cruzada encima.', 'Acerca los tobillos hacia el cuerpo hasta notar tensión en glúteos.', 'Mantén la espalda erguida y respira profundo durante treinta segundos.', 'Evita forzar las rodillas o inclinarte hacia delante con dolor.', 'Cambia el cruce de piernas y repite.']::text[], 'intermedio', 'Abre caderas y glúteos en una postura de yoga intensa que también libera la zona lumbar.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5890'),
('67a2253a-16a2-59eb-9a03-0c94987c818f', 'Jack doble en plancha a escalador de cuatro tiempos', ARRAY['Colócate en plancha alta con las manos bajo los hombros.', 'Abre y cierra las piernas con un salto manteniendo la cadera estable.', 'Lleva cuatro veces las rodillas al pecho alternando piernas.', 'Mantén el core firme y evita que la cadera suba o baje.', 'Respira de forma constante y reduce el ritmo si pierdes la postura.']::text[], 'intermedio', 'Combina cardio y core en plancha con saltos de piernas y rodillas al pecho para elevar pulsaciones.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7499'),
('9b13eb4e-a4fd-5c94-8e69-c86c9e48d814', 'Flexión de perro boca abajo contra la pared', ARRAY['Apoya las manos en la pared a la altura de los hombros y camina hacia atrás.', 'Lleva la cadera hacia arriba formando una V invertida con el cuerpo.', 'Flexiona los codos acercando el pecho a la pared y empuja para volver.', 'Mantén el core activo y evita hundir la zona lumbar.', 'Respira al empujar y controla la bajada.']::text[], 'intermedio', 'Refuerza hombros y tríceps con una flexión en pared que también estira la cadena posterior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6986'),
('08abe2df-7fb2-5b06-984a-c09805809653', 'Perro boca abajo', ARRAY['Colócate a cuatro patas con las manos bajo los hombros.', 'Empuja la cadera hacia arriba y estira las piernas formando una V invertida.', 'Presiona las manos contra el suelo y relaja el cuello.', 'Mantén las rodillas ligeramente flexionadas si los isquiotibiales tiran.', 'Respira profundo y aguanta entre treinta y sesenta segundos.']::text[], 'intermedio', 'Estira isquiotibiales, gemelos y espalda en una postura clásica de yoga que también abre hombros.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3469'),
('45ebfd71-21f9-5fbb-aecb-cde8523a499e', 'Perro boca abajo adho mukha svanasana', ARRAY['Parte de a cuatro patas con las manos bien apoyadas.', 'Eleva la cadera y estira las piernas sin bloquear las rodillas.', 'Alarga la columna y lleva el pecho hacia los muslos.', 'Mantén la respiración lenta y evita encoger los hombros.', 'Aguanta medio minuto y sal doblando las rodillas.']::text[], 'intermedio', 'Postura de yoga que alarga isquiotibiales, gemelos y espalda mientras fortalece hombros y core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0949'),
('94328eb7-a1cc-5386-a1f5-8f330e35291d', 'Movilidad de columna en perro boca abajo', ARRAY['Entra en perro boca abajo con las manos firmes en el suelo.', 'Lleva el pecho hacia los muslos y redondea suavemente la espalda.', 'Balancea la cadera hacia delante y atrás sin perder el apoyo.', 'Coordina el movimiento con la respiración y evita forzar el cuello.', 'Repite de forma lenta durante medio minuto.']::text[], 'intermedio', 'Mejora la movilidad de la columna y estira isquiotibiales y hombros con un balanceo controlado.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3528'),
('5cc774db-5466-5667-b764-028bc9bf00cb', 'Perro boca abajo con toque de pie', ARRAY['Colócate en perro boca abajo con las piernas estiradas.', 'Levanta una mano del suelo y llévala hacia el pie contrario.', 'Mantén la cadera alta y el core activo durante el toque.', 'Vuelve a apoyar la mano y alterna el lado.', 'Evita redondear la espalda o perder el equilibrio.']::text[], 'intermedio', 'Estira isquiotibiales y gemelos mientras el core trabaja para llevar una mano al pie.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3527'),
('1760d667-efce-57f3-8cbe-9f91e86bb4e5', 'Postura de la libélula', ARRAY['Coloca las manos en el suelo y abre las rodillas hacia los lados con los pies apoyados.', 'Desplaza el peso hacia un lado y extiende la pierna contraria hacia atrás manteniendo la cadera elevada.', 'Respira de forma constante y mantén la postura sin forzar la cadera.', 'Evita arquear la zona lumbar: activa el core y alarga la columna.']::text[], 'intermedio', 'Estira aductores y flexores de cadera mientras fortalece el core y los hombros, mejorando la movilidad y el equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6299'),
('8480b451-632c-578d-96f2-4c6ab9a118f6', 'Flexión con caída', ARRAY['Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros.', 'Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.', 'Una vez que tu pecho esté justo por encima del suelo, baja rápidamente las rodillas al suelo.', 'Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho con un componente pliométrico que mejora la potencia y la capacidad de absorción de impacto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1275'),
('0254b50b-92ae-5cba-ad3e-7650260d03d8', 'Caminata de pato', ARRAY['Baja en cuclillas hasta que los muslos queden cerca de la horizontal.', 'Da pasos cortos hacia delante sin enderezar del todo las piernas.', 'Mantén el pecho alto y el core activo durante todo el recorrido.', 'Evita juntar las rodillas hacia dentro: empújalas ligeramente hacia fuera.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón de sentadilla baja que también exige estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3867'),
('3dec07b5-de50-5d26-b707-9d207eafa4e4', 'Curl 21 con mancuernas', ARRAY['De pie, sujeta las mancuernas con las palmas hacia delante y los codos pegados al torso.', 'Haz siete repeticiones desde abajo hasta media altura.', 'Continúa con siete desde media altura hasta arriba.', 'Termina con siete repeticiones completas controlando la bajada.', 'Evita balancear el tronco para no perder la tensión en el bíceps.']::text[], 'intermedio', 'Aumenta el tiempo bajo tensión del bíceps combinando medias repeticiones bajas, altas y completas en una serie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5469'),
('36eb3c19-5612-5422-8252-6ed8db1aaf09', 'Elevación lateral en 4 direcciones con mancuernas', ARRAY['De pie con mancuernas a los lados, activa el core y mantén los hombros bajos.', 'Eleva los brazos al frente, luego a los lados, después en diagonal y por último atrás.', 'Controla la bajada en cada dirección sin usar impulso.', 'Evita encoger los hombros hacia las orejas durante las elevaciones.']::text[], 'intermedio', 'Refuerza los deltoides en varios planos para mejorar la estabilidad del hombro y la amplitud del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4211'),
('a2a00153-b55a-53b5-80eb-b9786714ec30', 'Elevación en 6 direcciones con mancuernas', ARRAY['De pie con mancuernas a los lados y codos ligeramente flexionados.', 'Realiza elevaciones al frente, a los lados, en diagonal, atrás y en los planos restantes.', 'Mantén el core firme y evita arquear la espalda.', 'Baja las mancuernas de forma controlada en cada repetición.', 'Usa un peso ligero para no perder la técnica en los últimos planos.']::text[], 'intermedio', 'Trabaja el deltoides completo en seis planos, mejorando fuerza, control y salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4871'),
('c2940009-66d6-5d32-b60b-939c56368d71', 'Press Arnold alternado con mancuernas', ARRAY['Siéntate con la espalda apoyada y las mancuernas a la altura del mentón con palmas hacia ti.', 'Empuja una mancuerna hacia arriba mientras giras la palma hacia fuera.', 'Baja controlando el retorno a la posición inicial y repite con el otro brazo.', 'Evita arquear la lumbar: mantén el core activo y las costillas abajo.']::text[], 'intermedio', 'Fortalece los deltoides con rotación, implicando también tríceps y porción superior del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4067'),
('dbc22449-dba5-5760-ad5e-9ed2cefe2fcb', 'Press de banca alternado con mancuernas desde arriba', ARRAY['Túmbate en el banco con las mancuernas extendidas sobre el pecho.', 'Baja una mancuerna hacia el pecho mientras la otra permanece arriba.', 'Empuja de vuelta y alterna con el otro brazo.', 'Mantén los omóplatos retraídos y evita abrir demasiado los codos.']::text[], 'intermedio', 'Trabaja el pecho de forma unilateral, mejorando el equilibrio entre lados y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3695'),
('c161c785-fa6a-5554-b732-a1f1205a00df', 'Curl de bíceps alternado con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, alternando los brazos.']::text[], 'intermedio', 'Aísla el bíceps de forma unilateral, favoreciendo la concentración y corrigiendo desequilibrios entre brazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0285'),
('c45ff36e-d51c-59be-aa10-d7e6e3c33fc4', 'Press de pecho alterno en balón con mancuernas', ARRAY['Siéntate en el balón y rueda hasta apoyar la espalda alta y la cabeza.', 'Sujeta las mancuernas a la altura del pecho con los codos abiertos.', 'Empuja una mancuerna hacia arriba y baja controlando, alternando brazos.', 'Mantén la cadera elevada y el core activo para no hundirte en el balón.']::text[], 'intermedio', 'Fortalece el pecho y el core al entrenar sobre superficie inestable, mejorando el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4834'),
('33c73d7e-21a3-5898-ab09-16051783658e', 'Elevación frontal alterna con mancuernas', ARRAY['De pie con mancuernas delante de los muslos y palmas hacia el cuerpo.', 'Eleva un brazo al frente hasta la altura del hombro sin balancearte.', 'Baja despacio y alterna con el otro brazo.', 'Evita usar impulso de cadera y mantener los hombros relajados.']::text[], 'intermedio', 'Trabaja la porción anterior del deltoides y la parte superior del pecho, mejorando la fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4341'),
('5c974832-d2a6-5f25-bfa7-a7ec2cf17f3f', 'Curl predicador martillo alternado con mancuernas', ARRAY['Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos.', 'Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones recomendado.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con agarre neutro, reduciendo la tensión en muñeca y antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1646'),
('726ac92c-6140-5dc6-8481-6864d17ff372', 'Elevación lateral alterna con mancuernas', ARRAY['De pie con mancuernas a los lados y codos ligeramente flexionados.', 'Eleva un brazo hacia el lado hasta la altura del hombro.', 'Baja controlando y alterna con el otro brazo.', 'Evita encoger el hombro o usar impulso del tronco.']::text[], 'intermedio', 'Fortalece el deltoides medio de forma unilateral, mejorando la amplitud del hombro y su estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4852'),
('1a51c4ae-14e4-50a8-b5c5-1688bfad0b06', 'Curl predicador alternado con mancuernas', ARRAY['Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba.', 'Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente.', 'Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps.', 'Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el movimiento con el brazo izquierdo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con el brazo apoyado, eliminando el impulso y mejorando la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1647'),
('152bca89-06f6-5db8-b4f9-be3cc000108c', 'Press de hombros alternado con mancuernas', ARRAY['Siéntate con la espalda apoyada y las mancuernas a la altura de los hombros.', 'Empuja una mancuerna hacia arriba sin bloquear del todo el codo.', 'Baja controlando hasta la altura del hombro y alterna con el otro brazo.', 'Evita arquear la lumbar y mantener el core activo durante todo el movimiento.']::text[], 'intermedio', 'Fortalece los deltoides y el tríceps de forma unilateral, mejorando la estabilidad del hombro y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3972'),
('8049182c-85b1-5be6-89e5-344e01da015d', 'Press lateral alternado con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.', 'Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro.', 'Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los deltoides laterales y mejora la estabilidad del hombro y el control del core al elevar un brazo cada vez.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0286'),
('cd907b5c-9ea2-5fee-a827-ce3a9ea91fc2', 'Thruster alternado a un brazo con mancuernas', ARRAY['Colócate de pie con los pies a la anchura de los hombros y una mancuerna a la altura del hombro.', 'Baja en sentadilla manteniendo el torso erguido y el core activo.', 'Al subir, empuja la mancuerna por encima de la cabeza con el brazo extendido.', 'Baja la mancuerna al hombro mientras desciendes de nuevo, alternando brazos.', 'Evita arquear la zona lumbar al extender el brazo arriba.']::text[], 'intermedio', 'Combina sentadilla y press para trabajar cuádriceps, glúteos y hombros, elevando la frecuencia cardiaca y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9693'),
('0cd4523c-0e69-5b46-a6ed-c5fbd99da8e3', 'Curl de bíceps alternado con pierna elevada en balón', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.', 'Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio.', 'Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto.', 'Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los bíceps y antebrazos mientras trabajas el equilibrio y la estabilidad del core sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1649'),
('c94012b5-6eb9-5e74-a998-35c74f3f69b8', 'Curl de bíceps alternado sentado en balón', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite la flexión con el otro brazo.', 'Continúa alternando flexiones el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los bíceps y antebrazos sentado sobre un balón, activando el core para mantener el equilibrio durante el movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1650'),
('ee2411a4-3685-5eb3-842d-6dc9afe238fd', 'Arquero con mancuernas', ARRAY['De pie, sujeta una mancuerna con ambas manos a la altura del pecho.', 'Extiende un brazo hacia un lado como si tensaras un arco, mientras el otro se flexiona.', 'Mantén el core firme y el torso estable sin girar en exceso.', 'Vuelve al centro y repite hacia el lado contrario de forma controlada.', 'Evita encoger los hombros o bloquear la respiración durante el movimiento.']::text[], 'avanzado', 'Trabaja hombros, tríceps y espalda alta con un movimiento de tracción y empuje que también exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3783'),
('32ebf20b-34be-5997-bfdb-16dcb922f73e', 'Press Arnold con mancuernas', ARRAY['Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura del hombro, con las palmas hacia tu cuerpo y los codos flexionados.', 'Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos y las palmas miren hacia adelante.', 'Rota las muñecas mientras levantas, de modo que las palmas miren hacia adelante en la parte alta del movimiento.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los deltoides en varios ángulos junto con tríceps y pecho superior, mejorando la fuerza y movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2137'),
('c4e1b516-9a71-5c58-8a9b-031245f84cd1', 'Pullover circular con mancuerna', ARRAY['Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.', 'Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco.', 'Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho, tríceps y dorsal con un recorrido circular que mejora la movilidad del hombro y la conexión torácica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0288'),
('0ef7f661-5fba-5fa0-ac7a-92bfa9a53d10', 'Sentadilla búlgara asistida con mancuernas', ARRAY['Coloca el pie trasero sobre un banco y sujeta una mancuerna en cada mano.', 'Apóyate ligeramente en una pared o soporte para mantener el equilibrio.', 'Baja flexionando la rodilla delantera hasta que el muslo quede casi paralelo al suelo.', 'Empuja con el talón delantero para subir manteniendo el torso erguido.', 'Evita que la rodilla delantera se desplace demasiado hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquiotibiales en una sola pierna, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4443'),
('e4db0056-8d2f-599e-9b05-233ed2ade562', 'Press de banca con banda elástica y mancuernas', ARRAY['Túmbate en el banco con una mancuerna en cada mano y la banda pasada por debajo del banco.', 'Sujeta los extremos de la banda junto con las mancuernas a la altura del pecho.', 'Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos.', 'Baja de forma controlada hasta que los codos queden a la altura del torso.', 'Evita arquear la espalda o rebotar en la parte baja del movimiento.']::text[], 'intermedio', 'Trabaja el pecho, tríceps y hombros con resistencia creciente de la banda, mejorando la fuerza en el rango final del empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4184'),
('9d8782cb-f855-5d46-b5f2-279eca210f24', 'Hip thrust con banda y mancuerna', ARRAY['Siéntate en el suelo con la espalda alta apoyada en un banco y la banda sobre las caderas.', 'Coloca una mancuerna sobre la banda, encima de la pelvis, y sujétala con las manos.', 'Empuja con los talones para elevar la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja de forma controlada sin apoyar del todo.', 'Evita arquear la zona lumbar en la parte alta del movimiento.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales con énfasis en la extensión de cadera, mejorando la fuerza y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6735'),
('be8fe615-8a43-5771-b57f-7feeffbf0069', 'Sentadilla isométrica en pared con banda y mancuerna', ARRAY['Apoya la espalda contra la pared y desliza hasta que los muslos queden paralelos al suelo.', 'Coloca la banda sobre los muslos y sujeta una mancuerna sobre la pelvis.', 'Mantén la posición con las rodillas alineadas con los pies y el core activo.', 'Respira de forma constante y aguanta el tiempo indicado sin bajar la cadera.', 'Evita que las rodillas se junten hacia dentro durante la isometría.']::text[], 'intermedio', 'Mantiene la fuerza isométrica de cuádriceps y glúteos con una postura estática que también activa el core y los aductores.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6558'),
('94ec9b6c-b51b-5439-a37b-80e147f29237', 'Sentadilla sumo con mancuerna agarrada por la barra', ARRAY['Separa los pies más allá de la anchura de los hombros con las puntas hacia fuera.', 'Sujeta una mancuerna con ambas manos entre las piernas, con el torso erguido.', 'Baja flexionando las rodillas y llevando la cadera atrás, manteniendo el pecho alto.', 'Empuja con los talones para subir y aprieta los glúteos arriba.', 'Evita que las rodillas se metan hacia dentro al bajar.']::text[], 'intermedio', 'Trabaja glúteos, aductores y cuádriceps con una postura amplia que mejora la fuerza de la cadera y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4030'),
('821fbdba-1963-5377-bf6d-af8963ae5928', 'Remo alterno en plancha de oso con mancuerna', ARRAY['Colócate en plancha de oso con las rodillas ligeramente separadas del suelo y una mancuerna bajo una mano.', 'Mantén la espalda plana y el core activo sin mover la cadera.', 'Tira de la mancuerna hacia la cadera flexionando el codo y llevando el omóplato atrás.', 'Baja la mancuerna de forma controlada y alterna con el otro brazo.', 'Evita girar la cadera o perder la posición de la espalda al remar.']::text[], 'intermedio', 'Trabaja el core, la espalda y los hombros con un remo desde plancha que exige estabilidad y control antirotación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10185'),
('33bc8edf-a8cd-53d5-a6c9-73e70201cdef', 'Curl de dedos detrás de la espalda con mancuernas', ARRAY['De pie, sujeta una mancuerna por detrás de la espalda con los dedos, no con la palma.', 'Mantén los brazos extendidos y los hombros relajados.', 'Flexiona los dedos para elevar la mancuerna lo máximo posible.', 'Baja de forma lenta y controlada hasta abrir los dedos sin soltar el peso.', 'Evita balancear el cuerpo o usar impulso para subir la mancuerna.']::text[], 'intermedio', 'Fortalece antebrazos, muñecas y agarre con un movimiento de flexión de dedos que mejora la fuerza de prensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1611'),
('a79efa1f-c4db-507f-8d83-e78ab736d766', 'Fondos en banco con mancuerna', ARRAY['Siéntate en el borde de un banco con las manos a los lados y una mancuerna sobre los muslos.', 'Desliza la cadera fuera del banco con los codos ligeramente flexionados.', 'Baja el cuerpo flexionando los codos hasta unos 90 grados, cerca del banco.', 'Empuja con las manos para subir extendiendo los codos sin bloquearlos del todo.', 'Evita encoger los hombros o bajar demasiado para no forzar el hombro.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con un movimiento de empuje que también fortalece antebrazos y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4728'),
('b700bea2-ba4e-5cb9-8205-3c2df4cdd33c', 'Fondos en banco con piernas elevadas y mancuerna', ARRAY['Coloca las manos en el borde del banco y los pies elevados sobre otro apoyo, con una mancuerna sujeta entre los muslos.', 'Baja el cuerpo flexionando los codos hasta que los brazos formen unos 90 grados, manteniendo la espalda cerca del banco.', 'Empuja con los tríceps para volver a la posición inicial sin bloquear los codos del todo.', 'Evita encoger los hombros hacia las orejas y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con gran exigencia; mejora la fuerza de empuje y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4729'),
('1c09cc25-105e-5536-aabd-14bd707356ab', 'Sentadilla a una pierna en banco con mancuernas', ARRAY['Siéntate en el borde del banco con una mancuerna en cada mano y apoya un pie en el suelo.', 'Levántate empujando con la pierna apoyada mientras la otra se mantiene ligeramente elevada.', 'Baja controlando el movimiento hasta rozar el banco con los glúteos y repite sin balancearte.', 'Evita que la rodilla se meta hacia dentro y mantén el torso erguido durante todo el recorrido.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral; mejora el equilibrio y corrige desequilibrios entre piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1550'),
('544ca687-57b0-564d-8aca-65e464bbe9c9', 'Press sentado en banco con mancuernas', ARRAY['Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.', 'Reclínate hacia atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia adelante.', 'Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los deltoides y refuerza tríceps y pecho superior; mejora la fuerza de empuje por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0290'),
('4b17de01-83c4-51a0-8d29-298a5b6b4067', 'Sentadilla en banco con mancuernas', ARRAY['Coloca una mancuerna en el suelo frente a un banco.', 'Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta.', 'Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos y cuádriceps con un rango controlado; útil para aprender el patrón de sentadilla con carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0291'),
('7b736998-4483-5064-a59b-e4fb60a5803d', 'Rotación externa con apoyo en banco y mancuerna', ARRAY['Apoya una rodilla y una mano en el banco con la espalda recta y el codo flexionado a 90 grados.', 'Sujeta la mancuerna con la mano libre y gira el antebrazo hacia arriba manteniendo el codo pegado al cuerpo.', 'Vuelve despacio a la posición inicial controlando el movimiento en todo momento.', 'Evita rotar el tronco o despegar el codo del costado para aislar el hombro.']::text[], 'intermedio', 'Refuerza el manguito rotador y la parte posterior del hombro; previene lesiones y mejora la estabilidad articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3693'),
('ca19e20e-13ac-5eba-9a44-b43c53982b16', 'Sostén isométrico con brazos flexionados y mancuernas', ARRAY['De pie, sujeta una mancuerna en cada mano con las palmas hacia arriba.', 'Flexiona los codos hasta unos 90 grados y mantén la posición sin mover los brazos.', 'Aprieta el core y respira de forma constante durante todo el sostén.', 'Evita balancear el tronco o subir los hombros para compensar la fatiga.']::text[], 'intermedio', 'Mantiene la tensión en bíceps y antebrazos; mejora la resistencia muscular y la estabilidad del codo.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4910'),
('cc6857f9-9079-57f7-9964-824f2c6ee3a7', 'Elevación lateral con brazos flexionados y mancuernas', ARRAY['De pie, sujeta una mancuerna en cada mano con los codos flexionados a unos 90 grados.', 'Eleva los brazos hacia los lados hasta la altura de los hombros manteniendo el ángulo del codo.', 'Baja las mancuernas despacio controlando el descenso sin dejar caer los brazos.', 'Evita encoger los hombros o usar impulso del tronco para subir el peso.']::text[], 'intermedio', 'Aísla el deltoides medio con los codos flexionados; mejora la amplitud del hombro con menos tensión articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5635'),
('0f9dab7b-f26e-513d-911b-20e2083e9440', 'Pullover con brazos flexionados y mancuerna', ARRAY['Túmbate en un banco con la espalda apoyada y sujeta una mancuerna con ambas manos sobre el pecho.', 'Con los codos ligeramente flexionados, lleva la mancuerna hacia atrás por encima de la cabeza.', 'Vuelve a la posición inicial controlando el recorrido y sin arquear en exceso la zona lumbar.', 'Evita abrir los codos en exceso o bajar demasiado si notas tensión en el hombro.']::text[], 'intermedio', 'Trabaja el pecho y los dorsales con los codos flexionados; amplía la caja torácica y mejora la movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4326'),
('35f55d65-9a43-5d39-9ce0-79456ac0b3fd', 'Sostén de pullover con brazos flexionados y mancuerna', ARRAY['Túmbate en un banco con una mancuerna sujeta con ambas manos por encima del pecho.', 'Baja la mancuerna hacia atrás hasta notar estiramiento en el pecho y mantén la posición.', 'Aprieta el core y respira con normalidad sin dejar caer los brazos.', 'Evita arquear la zona lumbar o bloquear la respiración durante el sostén.']::text[], 'intermedio', 'Mantiene la tensión en pecho y dorsales de forma isométrica; mejora la resistencia y el control postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1444'),
('1afde3e6-95f4-53f0-a300-12b8091cdba9', 'Pullover con brazos flexionados y rodillas flexionadas con mancuerna', ARRAY['Túmbate en el suelo con las rodillas flexionadas y sujeta una mancuerna con ambas manos sobre el pecho.', 'Lleva la mancuerna hacia atrás por encima de la cabeza manteniendo los codos ligeramente flexionados.', 'Vuelve a la posición inicial controlando el recorrido y manteniendo la zona lumbar pegada al suelo.', 'Evita despegar la espalda baja o bajar el peso más allá de tu movilidad cómoda.']::text[], 'intermedio', 'Activa pecho y dorsales con las rodillas flexionadas; reduce la tensión lumbar y mejora el control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2566'),
('a3157617-d5a4-53db-8f12-d92c5057e756', 'Apertura de deltoide posterior inclinado alternada con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta una mancuerna en cada mano.', 'Eleva un brazo hacia el lado con el codo ligeramente flexionado hasta la altura del hombro.', 'Baja despacio y repite con el otro brazo alternando el movimiento.', 'Evita redondear la espalda o usar impulso para elevar las mancuernas.']::text[], 'intermedio', 'Fortalece el deltoides posterior y la espalda alta; mejora la postura y equilibra el desarrollo del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3696'),
('c604aedb-e180-5e55-96ba-70b2f6f9ddae', 'Elevación de brazos inclinado de espalda a lateral a frontal con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta una mancuerna en cada mano.', 'Eleva los brazos hacia atrás, luego hacia los lados y finalmente hacia delante en un recorrido continuo.', 'Mantén los codos ligeramente flexionados y controla cada fase del movimiento.', 'Evita balancear el tronco o encoger los hombros para completar el recorrido.']::text[], 'intermedio', 'Recorre los tres haces del deltoides en un solo movimiento; mejora la fuerza y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11799'),
('6c90c6d2-2d9b-5fa2-b548-01dc6b63bc86', 'Curl inclinado con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y deja colgar los brazos con una mancuerna en cada mano.', 'Flexiona los codos llevando las mancuernas hacia los hombros sin mover los brazos del costado.', 'Baja despacio controlando el descenso hasta la extensión completa.', 'Evita balancear el tronco o adelantar los codos para subir el peso.']::text[], 'intermedio', 'Aísla el bíceps en estiramiento con el tronco inclinado; mejora el pico del bíceps y la fuerza de flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7625'),
('7e555e68-da3f-57b1-9025-c92159bb220a', 'Face pull inclinado con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta una mancuerna en cada mano.', 'Tira de las mancuernas hacia la cara separando los codos y juntando las escápulas.', 'Vuelve despacio a la posición inicial manteniendo el control del movimiento.', 'Evita encoger los hombros o usar impulso del tronco para tirar del peso.']::text[], 'intermedio', 'Refuerza el deltoides posterior y el manguito rotador; mejora la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5665'),
('9ab76553-4731-5f6f-85d8-5c932e07c2f7', 'Remo inverso inclinado con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta una mancuerna en cada mano con las palmas hacia delante.', 'Tira de las mancuernas hacia el abdomen juntando las escápulas y manteniendo los codos cerca del cuerpo.', 'Baja despacio controlando el descenso hasta la extensión completa de los brazos.', 'Evita redondear la espalda o usar impulso del tronco para completar la repetición.']::text[], 'intermedio', 'Trabaja la espalda alta y los dorsales con un agarre invertido; mejora la fuerza de tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3799'),
('37f69d1d-5b4a-50e1-8a93-9676a98d18f9', 'Remo inclinado con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Deja que los brazos cuelguen rectos hacia el suelo, con los codos ligeramente flexionados.', 'Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción en la vida diaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0293'),
('b507f917-e1f6-5cb1-b48b-944e5b9ca9cf', 'Remo inclinado contra la pared con mancuernas', ARRAY['Apoya la frente o el pecho en la pared y separa los pies para inclinar el tronco.', 'Sujeta las mancuernas con los brazos extendidos y la espalda recta.', 'Tira de los codos hacia atrás pegándolos al cuerpo hasta llevar las mancuernas a las costillas.', 'Baja las mancuernas despacio controlando el movimiento sin perder la postura.', 'Evita encoger los hombros y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja los dorsales y la espalda alta con apoyo en pared, ideal para aprender el patrón de tracción con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6146'),
('5a3ad328-f3b2-52cf-8857-41d54f8d8edc', 'Remo inclinado con apoyo en el pecho y mancuernas', ARRAY['Coloca el pecho apoyado en un banco inclinado y sujeta una mancuerna en cada mano.', 'Deja los brazos colgando con la espalda recta y el cuello en línea.', 'Tira de los codos hacia atrás llevando las mancuernas hacia las costillas.', 'Aprieta la espalda arriba y baja las mancuernas de forma controlada.', 'Evita arquear la zona lumbar o tirar con impulso del tronco.']::text[], 'intermedio', 'Aísla la espalda alta y los dorsales con apoyo en banco, reduciendo la carga lumbar y mejorando la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5661'),
('7daf7f3f-7cd0-5a8d-bd62-73a60fe9d30c', 'Remo escapular inclinado con mancuernas', ARRAY['Inclina el tronco con la espalda recta y sujeta las mancuernas con los brazos extendidos.', 'Sin doblar los codos, junta las escápulas llevando los hombros hacia atrás.', 'Mantén un segundo la contracción y vuelve a la posición inicial despacio.', 'Evita encoger los hombros hacia las orejas o mover los codos.', 'Respira de forma constante y mantén el abdomen firme.']::text[], 'intermedio', 'Activa la espalda alta y los romboides con un recorrido corto, útil para mejorar el control escapular y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6136'),
('21868d8d-5375-5f43-bbb4-67a3d1610abd', 'Remo inclinado a un brazo con mancuerna', ARRAY['Apoya una mano y una rodilla en un banco con la espalda recta y paralela al suelo.', 'Sujeta la mancuerna con la otra mano y deja el brazo colgando.', 'Tira del codo hacia atrás llevando la mancuerna hacia la cadera.', 'Baja la mancuerna despacio sin girar el tronco.', 'Evita rotar la cadera o tirar con impulso del cuerpo.']::text[], 'intermedio', 'Fortalece dorsales y espalda alta de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4730'),
('8430c229-7c03-5c0c-ac80-36eec038bb6a', 'Elevación en Y inclinado con mancuernas', ARRAY['Inclina el tronco con la espalda recta y sujeta las mancuernas con los brazos colgando.', 'Con los codos casi rectos, eleva los brazos en forma de Y hasta la altura de los hombros.', 'Aprieta la espalda alta arriba y baja las mancuernas despacio.', 'Evita encoger el cuello o usar impulso del tronco.', 'Usa un peso ligero y controla la respiración durante todo el recorrido.']::text[], 'intermedio', 'Refuerza los deltoides posteriores y los trapecios, mejorando la salud del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7995'),
('27a55bc2-b6e5-530d-90b9-842da52d10d3', 'Curl de bíceps en zancada con movimiento de boliche', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.', 'Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada.', 'Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.', 'En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche.', 'Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo.', 'Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Combina bíceps y piernas en un ejercicio dinámico que mejora la coordinación y la fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1651'),
('53f6a918-919a-5a07-83d9-aaca8dc58f7e', 'Curl de bíceps en balón de estabilidad con pierna elevada', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.', 'Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados.', 'Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Trabaja los bíceps sobre superficie inestable, añadiendo demanda de core y equilibrio al movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1652'),
('89437362-95d7-53ad-a9d6-ae02f5334688', 'Curl de bíceps en postura de cigüeña', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.', 'Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Fortalece los bíceps en equilibrio a una pierna, mejorando la estabilidad y la coordinación del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1653'),
('91f0b1f4-0bd5-5515-a386-cef1129f1c33', 'Curl de bíceps con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los bíceps y los antebrazos, aumentando la fuerza de flexión del codo y el volumen del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0294'),
('9c476f5e-285f-5d70-b603-72227a2a1467', 'Curl de bíceps en sentadilla con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.', 'Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina sentadilla y curl para trabajar piernas y bíceps a la vez, mejorando la coordinación global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1655'),
('77e5c5d3-b78c-5aac-b042-a401c5cff3fe', 'Curl de bíceps en V sentado en bosu', ARRAY['Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los bíceps sentado en superficie inestable, añadiendo demanda de core y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1656'),
('91bbea14-223c-5663-8a6d-33ed4a08a71a', 'Curl de bíceps con extensión sobre la cabeza en balón de estabilidad', ARRAY['Siéntate en el balón con la espalda recta y sujeta una mancuerna en cada mano.', 'Haz un curl llevando las mancuernas a los hombros con los codos pegados al cuerpo.', 'Desde ahí, extiende los brazos sobre la cabeza y vuelve a la posición de curl.', 'Controla el movimiento sin perder el equilibrio ni arquear la espalda.', 'Evita usar impulso y mantén el abdomen activo durante todo el ejercicio.']::text[], 'intermedio', 'Combina bíceps y tríceps sobre balón, trabajando brazos y core con demanda de equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5239'),
('7cbbeb92-6117-5d56-bf97-0614169cbad4', 'Press de banca en puente con mancuernas', ARRAY['Túmbate boca arriba con las rodillas dobladas y sujeta las mancuernas a la altura del pecho.', 'Eleva la cadera formando un puente y aprieta los glúteos.', 'Empuja las mancuernas hacia arriba hasta extender los brazos sin bloquear los codos.', 'Baja las mancuernas despacio al pecho manteniendo el puente.', 'Evita arquear la zona lumbar o dejar caer la cadera durante el movimiento.']::text[], 'intermedio', 'Trabaja pectorales y tríceps en puente de glúteo, sumando fuerza de core y glúteos al empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4731'),
('59bf713c-8f14-545e-bf89-d9933443228d', 'Sentadilla búlgara desde déficit con mancuernas', ARRAY['Coloca el pie trasero sobre un banco y el delantero sobre una superficie elevada, con una mancuerna en cada mano.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el pie delantero para subir controlando el movimiento.', 'Mantén la rodilla delantera alineada con el pie y evita que se meta hacia dentro.', 'Baja de forma lenta y evita rebotar en la posición baja.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral con mayor rango, mejorando fuerza y equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7550'),
('3ec1813d-29c2-5a3d-9f4d-3218de89a9ec', 'Burpee con mancuernas', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y una mancuerna en cada mano.', 'Baja el cuerpo a una posición de sentadilla, colocando las mancuernas en el suelo frente a ti.', 'Lleva los pies hacia atrás a una posición de flexión de brazos, manteniendo el cuerpo en línea recta.', 'Realiza una flexión de brazos, flexionando los codos y bajando el pecho hacia el suelo.', 'Salta con los pies hacia tus manos, aterrizando en una posición de sentadilla.', 'Ponte de pie de forma explosiva, levantando las mancuernas del suelo y llevándolas a los hombros.', 'Empuja las mancuernas por encima de la cabeza, extendiendo completamente los brazos.', 'Baja las mancuernas de vuelta a los hombros y repite toda la secuencia el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio cardiovascular de cuerpo completo que eleva las pulsaciones y mejora la resistencia mientras trabaja piernas, hombros y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '1201'),
('d348b7a6-929a-5009-857b-22003f252528', 'Apertura de pecho con mancuernas', ARRAY['Túmbate en un banco o en el suelo con una mancuerna en cada mano sobre el pecho.', 'Abre los brazos en arco con los codos ligeramente flexionados hasta notar estiramiento en el pecho.', 'Junta las mancuernas arriba sin bloquear del todo los codos y espira al subir.', 'Baja despacio controlando el movimiento, sin dejar que los codos se extiendan por completo.', 'Evita arquear la zona lumbar o abrir más de lo que controlas para no forzar el hombro.']::text[], 'intermedio', 'Aísla el pectoral abriendo los brazos con codos ligeramente flexionados, útil para ganar amplitud y controlar la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2337'),
('180050ea-50c6-5409-b1cb-5a47847dbe7c', 'Remo con apoyo de pecho y mancuernas', ARRAY['Apoya el pecho en un banco inclinado con una mancuerna en cada mano colgando.', 'Tira de las mancuernas hacia el abdomen llevando los codos atrás y juntando las escápulas.', 'Espira al tirar y controla la bajada durante dos segundos.', 'Mantén el cuello en línea con la espalda y evita encoger los hombros hacia las orejas.', 'No uses impulso del torso: el movimiento sale solo de los brazos y la espalda.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con el torso apoyado, reduciendo la carga lumbar y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9698'),
('45e9192d-3be4-5081-9d60-f0fd68dcda7d', 'Cargada con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.', 'Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo.', 'Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo.', 'Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba.', 'Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que potencia glúteos y piernas, mejorando la fuerza y la coordinación del tren inferior.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0295'),
('2c342686-b2b4-5a38-b6af-74aa344735a7', 'Cargada y press con mancuernas', ARRAY['Coloca las mancuernas a los lados con las caderas atrás y la espalda recta.', 'Extiende piernas y caderas con fuerza para llevar las mancuernas a los hombros.', 'Desde ahí empuja las mancuernas por encima de la cabeza sin arquear la lumbar.', 'Baja las mancuernas con control a los hombros y después al suelo.', 'Evita redondear la espalda o usar solo los brazos en la cargada.']::text[], 'avanzado', 'Ejercicio global que combina potencia de piernas y empuje de hombros, ideal para fuerza funcional y coordinación.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '3400'),
('b4195731-73ad-5d31-84f4-dc6e5850f858', 'Curl con agarre cerrado y mancuernas', ARRAY['De pie con una mancuerna en cada mano y las palmas enfrentadas, pegadas al centro.', 'Flexiona los codos subiendo las mancuernas hacia el pecho sin mover los hombros.', 'Espira al subir y baja despacio controlando el peso.', 'Mantén los codos pegados al torso y evita balancear el cuerpo.', 'No bloquees la respiración ni subas más de lo que controlas.']::text[], 'intermedio', 'Trabaja el bíceps y el braquial con las manos juntas, aumentando el grosor del brazo y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4152'),
('49fa3948-639c-526b-a70f-162c3ae26b5a', 'Press con agarre cerrado y mancuernas', ARRAY['Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.', 'Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.', 'Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.', 'Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.', 'Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas.', 'Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito.']::text[], 'intermedio', 'Variante de press que enfatiza el tríceps y el pecho, útil para ganar fuerza en el empuje y estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1731'),
('52213d59-00d4-5741-8f44-709ce2b72dc6', 'Press de hombros con agarre cerrado y abdominal con mancuernas', ARRAY['Siéntate con las rodillas flexionadas y una mancuerna a la altura del pecho.', 'Túmbate mientras empujas la mancuerna hacia arriba con agarre cerrado.', 'Sube el torso usando el abdomen y lleva la mancuerna al pecho.', 'Espira al subir y controla la bajada sin tirar del cuello.', 'Evita impulsarte con las piernas o arquear la espalda al tumbarte.']::text[], 'intermedio', 'Combina empuje de hombros y trabajo abdominal en un mismo movimiento, mejorando la fuerza del core y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4621'),
('f9c9eb22-ed8d-550b-ab58-cd7521acf958', 'Complejo con mancuernas: flexión, remo, cargada y press', ARRAY['Con una mancuerna en cada mano, haz una flexión apoyando el pecho en el suelo.', 'Desde ahí realiza un remo llevando los codos atrás y juntando escápulas.', 'Pasa a la cargada extendiendo caderas y piernas para subir las mancuernas.', 'Termina con un press por encima de la cabeza y baja con control.', 'Mantén la espalda recta y evita encadenar movimientos con prisa perdiendo técnica.']::text[], 'intermedio', 'Circuito de cuerpo completo que encadena varios movimientos para elevar pulsaciones y trabajar fuerza y resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3886'),
('8a8e4c01-7839-5205-909b-aa1b620cb92f', 'Curl concentrado con mancuerna', ARRAY['Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo.', 'Extiende completamente el brazo y sujeta la mancuerna con un agarre supino.', 'Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps con el codo apoyado, maximizando la contracción y el control del movimiento en cada repetición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0297'),
('78b9db7b-ac81-5ec6-b829-32da72b97239', 'Zancada hacia adelante contralateral con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado.', 'Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo.', 'Empuja con el talón derecho para regresar a la posición inicial.', 'Repite con la pierna izquierda.', 'Alterna las piernas el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y piernas con una zancada que reta el equilibrio y la estabilidad del core al cargar el peso a un lado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3635'),
('99f452e0-0b9b-5c84-89ec-a1c3edc1603f', 'Sentadilla búlgara contralateral con énfasis en glúteo y mancuernas', ARRAY['Coloca el pie trasero sobre un banco y sujeta una mancuerna en la mano contraria a la pierna delantera.', 'Baja la rodilla trasera hacia el suelo inclinando ligeramente el torso adelante.', 'Empuja con el talón delantero para subir apretando el glúteo.', 'Espira al subir y mantén el core firme para no perder el equilibrio.', 'Evita que la rodilla delantera se vaya hacia dentro o que el torso se hunda.']::text[], 'intermedio', 'Variante unilateral que carga el glúteo de la pierna delantera y mejora el equilibrio y la fuerza de cada pierna por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7598'),
('df3b09a9-fe05-594f-91d4-7f341e98e341', 'Sentadilla cosaca con mancuernas', ARRAY['De pie con los pies bien separados y una mancuerna sujeta delante del pecho.', 'Desplaza el peso a una pierna flexionando esa rodilla mientras la otra se estira.', 'Baja todo lo que controles manteniendo el talón apoyado y el pecho alto.', 'Empuja con la pierna flexionada para volver al centro y cambia de lado.', 'Evita levantar el talón o redondear la espalda al bajar.']::text[], 'intermedio', 'Sentadilla lateral que abre las caderas y fortalece glúteos, aductores y cuádriceps, mejorando la movilidad y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4732'),
('42723b31-1f95-5717-9f88-fe5cc2ad4dfa', 'Sentadillas cosacas con mancuernas', ARRAY['Separa bien los pies y sujeta una mancuerna delante del pecho con ambas manos.', 'Flexiona una rodilla llevando la cadera atrás y hacia ese lado.', 'Mantén la otra pierna estirada con el pie apoyado y el pecho erguido.', 'Vuelve al centro empujando con el talón y repite hacia el otro lado.', 'No dejes que la rodilla flexionada se meta hacia dentro ni que el talón se levante.']::text[], 'intermedio', 'Movimiento lateral que fortalece cuádriceps, glúteos y aductores, mejorando la movilidad de cadera y el control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4562'),
('c4b72f7d-7182-574e-b305-4397e6d4fda6', 'Curl martillo cruzado con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Mantén los codos cerca del torso y los brazos superiores quietos.', 'Exhala y flexiona los brazos contrayendo los bíceps, llevando las mancuernas a través del cuerpo hacia el hombro opuesto.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Curl que cruza el cuerpo para trabajar bíceps y braquial desde otro ángulo, mejorando el grosor y la fuerza del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0298'),
('5315dc01-c95b-50d5-9dd7-254a7780f1d2', 'Peso muerto rumano cruzado con mancuernas', ARRAY['Colócate de pie con una mancuerna en cada mano y los pies a la anchura de las caderas.', 'Cruza una mancuerna por delante del muslo contrario para mantener las cargas cerca del cuerpo.', 'Lleva las caderas hacia atrás bajando el torso con la espalda recta hasta notar tensión en los isquios.', 'Sube empujando las caderas hacia delante y aprieta los glúteos al final del recorrido.', 'Evita redondear la espalda o bajar más de lo que permite tu flexibilidad.']::text[], 'intermedio', 'Fortalece isquiosurales y glúteos con un patrón de cadera que mejora la fuerza posterior y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10199'),
('b05b77c0-047e-5857-bad0-0fb5cc697ab6', 'Abdominal con mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna sobre el pecho.', 'Contrae el abdomen elevando la parte alta de la espalda sin tirar del cuello.', 'Exhala al subir y controla la bajada en dos segundos.', 'Evita impulsarte con las piernas o balancear la mancuerna.']::text[], 'intermedio', 'Trabaja el recto abdominal con carga adicional, aumentando la intensidad del crunch y la resistencia del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4624'),
('b52d8ddd-71c6-5045-805d-58392fed484d', 'Press cubano con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.', 'Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.', 'Gira las muñecas de modo que las palmas queden mirando hacia adelante.', 'Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza deltoides y manguito rotador, mejorando la salud del hombro y la estabilidad en press verticales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0299'),
('450ab916-3fe5-5cf3-905b-4f1cbfcdb3d1', 'Curl, press y extensión con mancuernas', ARRAY['De pie con una mancuerna en cada mano, realiza un curl de bíceps hasta los hombros.', 'Desde ahí empuja las mancuernas por encima de la cabeza sin arquear la espalda.', 'Baja las mancuernas a la altura de la nuca y extiende los codos para trabajar el tríceps.', 'Regresa al punto de partida controlando el descenso y evitando balanceos.']::text[], 'intermedio', 'Combina bíceps, hombros y tríceps en un solo movimiento para ganar eficiencia y coordinación en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5884'),
('52f5b2a4-bdc4-5ad1-8d40-55782093dbb8', 'Curl a press con mancuernas', ARRAY['De pie con una mancuerna en cada mano y los codos pegados al torso.', 'Sube las mancuernas con un curl hasta la altura de los hombros.', 'Gira las palmas hacia delante y empuja por encima de la cabeza sin arquear la espalda.', 'Baja las mancuernas al pecho y luego a los muslos controlando el movimiento.']::text[], 'intermedio', 'Encadena bíceps y hombros en un movimiento fluido que mejora la coordinación y la fuerza funcional del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3347'),
('51207260-f7c5-5595-9fcf-b8df41e73f20', 'Zancada cruzada con mancuernas', ARRAY['De pie con una mancuerna en cada mano a los lados del cuerpo.', 'Da un paso cruzando una pierna por detrás de la otra y baja la rodilla trasera hacia el suelo.', 'Mantén el torso erguido y la rodilla delantera alineada con el pie.', 'Empuja con la pierna delantera para volver a la posición inicial y alterna lados.', 'Evita que la rodilla delantera se vaya hacia dentro al bajar.']::text[], 'intermedio', 'Activa glúteos y aductores con un patrón cruzado que mejora el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0881'),
('e75ceb33-2b22-5e42-a7d6-27f0c1eda852', 'Peso muerto con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.', 'Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo.', 'Flexiona las caderas y las rodillas, bajando las mancuernas hacia el suelo mientras mantienes la espalda recta.', 'Empuja con los talones y extiende las caderas y las rodillas, levantando las mancuernas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos e isquiosurales con un patrón de bisagra de cadera que mejora la fuerza posterior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0300'),
('37626c95-938c-5261-ae4e-8551c195c4db', 'Peso muerto y remo inclinado con mancuernas', ARRAY['De pie con una mancuerna en cada mano, baja con las caderas hacia atrás hasta quedar inclinado con la espalda recta.', 'Desde esa posición, tira de las mancuernas hacia el abdomen juntando las escápulas.', 'Baja las mancuernas controlando el movimiento y vuelve a subir extendiendo las caderas.', 'Mantén el core activo y evita redondear la espalda en todo el recorrido.']::text[], 'intermedio', 'Combina cadena posterior y espalda en un movimiento compuesto que mejora la fuerza global y la estabilidad del torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5232'),
('8da42239-6104-583b-b35e-8d921cca297f', 'Zancada en banco declinado con mancuernas', ARRAY['Coloca un pie sobre el banco declinado y sujeta una mancuerna en cada mano.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con la pierna delantera para subir sin bloquear la rodilla.', 'Controla la bajada y evita que la rodilla delantera pase de la punta del pie.']::text[], 'intermedio', 'Incrementa la carga en cuádriceps y glúteos con un rango mayor, mejorando fuerza y control en desnivel.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1551'),
('de35a6fd-5f99-5e02-8d1b-4f802f914c89', 'Apertura declinada con mancuernas', ARRAY['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.', 'Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.', 'Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el pectoral en un ángulo declinado, incidiendo en la porción inferior del pecho y mejorando la apertura torácica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0302'),
('6748da7d-489b-5b72-be40-e6adcc549361', 'Curl femoral declinado acostado con mancuerna', ARRAY['Túmbate boca abajo en un banco declinado con una mancuerna sujeta entre los pies.', 'Flexiona las rodillas llevando la mancuerna hacia los glúteos sin mover la cadera.', 'Sube controlando y baja lentamente hasta extender casi por completo las piernas.', 'Evita arquear la zona lumbar o dar tirones con la mancuerna.']::text[], 'intermedio', 'Fortalece los isquiosurales en un ángulo declinado, mejorando la fuerza posterior y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4733'),
('3f00b678-82b5-5c6c-92d8-694764b8399f', 'Press martillo declinado a un brazo con mancuerna', ARRAY['Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.', 'Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado.', 'Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo.', 'Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Trabaja tríceps y pecho con un press unilateral en banco declinado que mejora la estabilidad y corrige desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1617'),
('b6c71220-39c0-5bc6-9463-e84ed575ce9b', 'Abdominal declinado sobre la cabeza con mancuerna', ARRAY['Túmbate en un banco declinado con los pies sujetos y una mancuerna sobre el pecho o la cabeza.', 'Sube el torso contrayendo el abdomen sin tirar del cuello.', 'Baja controlando el movimiento hasta rozar el banco con la espalda.', 'Evita impulsarte con las piernas o balancear la mancuerna.']::text[], 'intermedio', 'Refuerza el recto abdominal y los flexores de cadera con un sit up cargado que aumenta la intensidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4734'),
('2e88240d-c67b-57d0-801b-35a7ad9a944d', 'Encogimientos declinados con mancuernas', ARRAY['Ajusta un banco declinado a un ángulo de 45 grados.', 'Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.', 'Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el suelo.', 'Manteniendo los brazos rectos, levanta los hombros hacia las orejas lo más alto posible.', 'Mantén la contracción por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los trapecios superiores en un ángulo declinado, mejorando la fuerza y el volumen de la zona cervical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0305'),
('92cbd3e7-3eb9-5b7e-9ce6-7f7c35c2c347', 'Extensión de tríceps declinada con mancuernas', ARRAY['Túmbate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.', 'Baja lentamente las mancuernas detrás de la cabeza, flexionando los codos.', 'Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en banco declinado, aumentando la tensión en el brazo y mejorando la definición posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0306'),
('393ff502-c8fb-5802-af12-295ba9a559d5', 'Devils press con mancuernas', ARRAY['Coloca los pies a la anchura de las caderas con las mancuernas en el suelo frente a ti.', 'Baja en peso muerto, agarra las mancuernas y llévalas a los hombros con un tirón explosivo.', 'Haz un press sobre la cabeza y devuélvelas al suelo con control.', 'Mantén la espalda neutra y evita redondearla al recoger el peso.']::text[], 'intermedio', 'Combina peso muerto, remo y press para trabajar todo el cuerpo y elevar la frecuencia cardíaca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4164'),
('f58cc2fb-594d-533a-adb8-9faeb6d11877', 'Curl de bíceps arrastrado con mancuernas', ARRAY['De pie, sujeta las mancuernas con las palmas hacia delante y los brazos extendidos.', 'Sube las mancuernas arrastrándolas cerca del cuerpo hasta la altura del pecho.', 'Aprieta el bíceps arriba y baja despacio controlando el movimiento.', 'Evita balancear el tronco para no perder tensión en el brazo.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con un recorrido que arrastra la mancuerna cerca del torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3687'),
('0ab8b5fd-e848-5543-a9d1-5d06f7363bba', 'Sentadilla frontal con talones elevados y mancuernas', ARRAY['Coloca una pequeña elevación bajo los talones y sujeta las mancuernas a la altura de los hombros.', 'Baja flexionando las rodillas con el pecho erguido y los codos altos.', 'Desciende hasta donde puedas mantener la espalda neutra y sube empujando con los pies.', 'Evita que las rodillas se metan hacia dentro durante el descenso.']::text[], 'intermedio', 'Enfatiza el cuádriceps con una sentadilla frontal que mejora la profundidad y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9690'),
('13712db2-48a3-50f3-b5d5-5c7f735fd37c', 'Empty can con mancuernas', ARRAY['De pie, eleva los brazos a 45 grados con los pulgares apuntando hacia abajo.', 'Sube las mancuernas hasta la altura de los hombros sin encogerlos.', 'Baja lentamente manteniendo el control en todo el recorrido.', 'Usa poco peso y evita arquear la espalda o subir más allá del hombro.']::text[], 'intermedio', 'Refuerza el manguito rotador y el deltoides con un movimiento de abducción en rotación interna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5819'),
('2dc924db-d74b-5a41-af3e-2c44dd0b736d', 'Rotación externa con mancuerna', ARRAY['Colócate de lado con el codo pegado al cuerpo flexionado a 90 grados.', 'Gira el antebrazo hacia fuera manteniendo el codo fijo junto al torso.', 'Vuelve despacio a la posición inicial sin mover el hombro.', 'Evita usar impulso o separar el codo del cuerpo.']::text[], 'intermedio', 'Fortalece el manguito rotador y estabiliza el hombro para prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3684'),
('ec583d49-42aa-50e0-9134-0ddf994e223f', 'Press de hombros boca abajo con mancuernas', ARRAY['Túmbate boca abajo en un banco con las mancuernas a la altura de los hombros.', 'Empuja las mancuernas hacia arriba extendiendo los brazos sin bloquear del todo.', 'Baja con control hasta la posición inicial manteniendo el cuello neutro.', 'Evita arquear la zona lumbar o encoger los hombros al empujar.']::text[], 'intermedio', 'Trabaja el deltoides y la espalda alta desde una posición tumbado que reduce la carga lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4125'),
('95d365d5-091c-5f1b-995c-9184a5f8ab34', 'Curl de dedos con mancuerna', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba.', 'Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba.', 'Repite el número de repeticiones deseado, luego cambia a la otra mano.']::text[], 'intermedio', 'Refuerza los flexores de la muñeca y la fuerza de agarre, útil para deportes y escalada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1437'),
('251c4e60-2f9f-538b-aac8-aaf80c8155e0', 'Alrededor del mundo plano con mancuernas', ARRAY['Túmbate en un banco con las mancuernas juntas sobre el pecho y los brazos extendidos.', 'Dibuja un círculo amplio llevando los brazos hacia los lados y hacia abajo.', 'Vuelve a juntar las mancuernas arriba completando el círculo.', 'Usa poco peso y evita bloquear los codos o perder el control.']::text[], 'intermedio', 'Activa el deltoides y el pecho con un círculo amplio que mejora la movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3968'),
('6277a78c-0e11-5c55-bd6b-399e3f3903a0', 'Sostén de apertura plana con mancuernas', ARRAY['Túmbate en un banco con las mancuernas abiertas a la altura del pecho.', 'Mantén los brazos semiflexionados y las palmas enfrentadas.', 'Aprieta el pecho y aguanta la posición respirando con normalidad.', 'Evita bajar demasiado los brazos o perder la tensión en los hombros.']::text[], 'intermedio', 'Mantiene la tensión isométrica en el pecho y los hombros para mejorar la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1450'),
('bc9aff89-f303-5fcd-9916-70de67442fac', 'Apertura en el suelo con mancuernas', ARRAY['Túmbate en el suelo con las mancuernas sobre el pecho y los codos semiflexionados.', 'Abre los brazos hacia los lados hasta que los codos rocen el suelo.', 'Junta las mancuernas arriba apretando el pecho.', 'Evita arquear la espalda o dejar caer los brazos sin control.']::text[], 'intermedio', 'Trabaja el pectoral con un recorrido limitado por el suelo que protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4149'),
('f87a7696-42f3-5b7e-8cb9-c3060e3cae78', 'Limpiaparabrisas en el suelo con mancuerna', ARRAY['Túmbate boca arriba con la mancuerna sujeta con ambas manos sobre el pecho.', 'Eleva las piernas y gira las caderas de lado a lado como un limpiaparabrisas.', 'Mantén la zona lumbar pegada al suelo durante todo el recorrido.', 'Evita usar impulso o despegar los hombros del suelo.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos con un movimiento de rotación controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4737'),
('828ac1ff-2318-5861-b8ce-ce7d438a6e7d', 'Aperturas con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.', 'Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el pectoral con un movimiento de apertura que estira y trabaja el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0308'),
('cc080487-4a2f-565c-aea2-b8f1c91c46d5', 'Apertura con mancuernas con rodillas a 90 grados', ARRAY['Túmbate en un banco con las rodillas flexionadas a 90 grados y las mancuernas sobre el pecho.', 'Abre los brazos hacia los lados con los codos semiflexionados.', 'Junta las mancuernas arriba apretando el pecho sin arquear la espalda.', 'Mantén las rodillas a 90 grados y evita bajar los pies durante el ejercicio.']::text[], 'intermedio', 'Trabaja el pectoral y el core con las piernas elevadas, aumentando la exigencia estabilizadora.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3175'),
('b60700c3-37bf-5428-8ab0-82ee03ffae8d', 'Apertura con mancuernas en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano.', 'Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí.', 'Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el pectoral sobre una superficie inestable que activa el core y los estabilizadores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1277'),
('bcc40487-b42b-59ca-99a8-1d07e7b14fc0', 'Zancada con inclinación hacia delante con mancuernas', ARRAY['De pie con las mancuernas a los lados, da un paso al frente inclinando ligeramente el tronco.', 'Baja flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.', 'Empuja con el pie delantero para volver a la posición inicial.', 'Evita que la rodilla delantera pase demasiado la punta del pie o que el tronco se redondee.']::text[], 'intermedio', 'Enfatiza el glúteo con una zancada inclinada que también trabaja cuádriceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1175'),
('0a763968-7d46-5bc3-84f1-4252280200ba', 'Zancada con extensión de tríceps con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Mantén la espalda recta y el pecho elevado.', 'Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas.', 'Baja las mancuernas detrás de la cabeza flexionando los codos.', 'Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial.', 'Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite.']::text[], 'intermedio', 'Combina el trabajo de piernas con la extensión de tríceps, mejorando la coordinación y la fuerza global del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1732'),
('5705a55a-c3b7-5677-8a7b-eb828d317085', 'Hip thrust de rana con mancuerna', ARRAY['Coloca la mancuerna sobre la cadera y apoya la espalda alta en un banco, con las plantas de los pies juntas y las rodillas abiertas.', 'Empuja con los talones y sube la cadera hasta alinear tronco y muslos, apretando los glúteos arriba.', 'Baja la cadera de forma controlada sin apoyarla del todo y repite el movimiento.', 'Evita arquear la zona lumbar en la subida; mantén las costillas abajo y el core activo.']::text[], 'intermedio', 'Activa los glúteos y aductores con un empuje de cadera que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6160'),
('ad4f97b3-dbb5-5485-a573-1799e461c865', 'Zancada con mancuernas en posición frontal', ARRAY['Sujeta las mancuernas a la altura de los hombros con los codos altos y da un paso al frente.', 'Baja flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.', 'Empuja con el pie delantero para volver a la posición inicial y alterna las piernas.', 'Mantén el tronco erguido y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con las mancuernas a la altura de los hombros, exigiendo más al core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3398'),
('04f9da81-f686-5447-b787-c4484fd4e315', 'Elevación frontal con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.', 'Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoides anterior para ganar fuerza y definición en la parte delantera del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0310'),
('fd660ff1-898c-5aec-9c2a-1f6dd15950c4', 'Sentadilla frontal con mancuernas', ARRAY['Sujeta las mancuernas a la altura de los hombros con los codos altos y los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás y abajo manteniendo el pecho alto y la espalda recta.', 'Sube empujando con los talones y aprieta los glúteos arriba sin bloquear las rodillas.', 'Evita que los codos bajen o que el tronco se incline demasiado hacia delante.']::text[], 'intermedio', 'Enfoca el trabajo en los cuádriceps con una carga frontal que también fortalece el core y los glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2966'),
('8ac5ce1d-7c29-5a17-af3d-b176c125648f', 'Elevación lateral full can con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.', 'Mantén la espalda recta y activa el core.', 'Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el deltoides lateral y el manguito rotador con un recorrido que protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0311'),
('2e041866-3c31-578c-a15a-0373fffef713', 'Atrape de elevación frontal con mancuerna', ARRAY['De pie con una mancuerna en cada mano frente a los muslos y el core activo.', 'Eleva los brazos al frente hasta la altura de los hombros con un movimiento controlado.', 'Deja caer ligeramente las mancuernas y atrápalas de nuevo con un pequeño impulso de cadera.', 'Evita balancear el tronco en exceso; el impulso debe ser mínimo y seguro.']::text[], 'intermedio', 'Trabaja el deltoides anterior y el pecho superior con un gesto explosivo que implica al core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10559'),
('7bd27206-bd2e-5119-aada-9efc2899ad42', 'Balanceo completo con mancuerna', ARRAY['Sujeta la mancuerna con ambas manos frente al cuerpo, pies a la anchura de los hombros y rodillas ligeramente flexionadas.', 'Lleva la cadera atrás mientras la mancuerna baja entre las piernas, con la espalda recta.', 'Extiende la cadera con fuerza para impulsar la mancuerna hasta la altura del pecho.', 'Evita redondear la espalda o usar los brazos para levantar el peso; el impulso nace de la cadera.']::text[], 'intermedio', 'Movimiento balístico que activa glúteos, isquios y core, mejorando la potencia y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3397'),
('2fb0acd4-cd43-5d98-ab7e-f534b1124249', 'Puente de glúteos con mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas, los pies apoyados y la mancuerna sobre la cadera.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba un segundo y baja de forma controlada.', 'Evita arquear la zona lumbar; mantén las costillas abajo y el core activo.']::text[], 'intermedio', 'Activa los glúteos y los isquios en un movimiento de empuje de cadera que también estabiliza el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3335'),
('a5e97bc9-8d6e-550e-a9ad-bc78f69d3778', 'Press de pecho en puente de glúteos con mancuernas', ARRAY['Túmbate con la espalda alta apoyada y las mancuernas a la altura del pecho, pies firmes en el suelo.', 'Eleva la cadera formando un puente y mantén la posición durante todo el ejercicio.', 'Empuja las mancuernas hacia arriba hasta extender los codos y bájalas de forma controlada.', 'Evita que la cadera caiga o que la zona lumbar se arquee mientras presionas.']::text[], 'intermedio', 'Combina el empuje de pecho con la extensión de cadera, trabajando pectoral, tríceps y glúteos a la vez.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7994'),
('67856364-3838-55e7-842c-3527ec4eb7e3', 'Sentadilla búlgara con énfasis en glúteo y mancuernas', ARRAY['Coloca el pie trasero sobre un banco y sujeta las mancuernas a los lados con el pie delantero firme.', 'Inclina ligeramente el tronco hacia delante y baja flexionando la rodilla delantera.', 'Empuja con el talón delantero para subir apretando el glúteo y repite.', 'Evita que la rodilla delantera se vaya hacia dentro o que el tronco se hunda.']::text[], 'intermedio', 'Trabaja glúteos e isquios de forma unilateral con el pie trasero elevado, mejorando el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7590'),
('7826056c-3e75-58de-9aa8-9eaacf21b754', 'Subida al banco enfocada en glúteos con mancuernas', ARRAY['Coloca un pie entero sobre el banco y sujeta las mancuernas a los lados.', 'Empuja con el talón del pie apoyado para subir, inclinando ligeramente el tronco hacia delante.', 'Sube hasta extender la cadera y baja de forma controlada sin dejarte caer.', 'Evita impulsarte con la pierna de abajo; el trabajo debe hacerlo la pierna de arriba.']::text[], 'intermedio', 'Ejercicio unilateral que activa glúteos y cuádriceps, mejorando la fuerza y el equilibrio de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5314'),
('a5127f30-6522-50b4-9b36-2059ae525025', 'Sentadilla goblet con pausa de 2 segundos y mancuerna', ARRAY['Sujeta la mancuerna a la altura del pecho con ambas manos y los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo el pecho alto y la espalda recta.', 'Haz una pausa de dos segundos en la posición baja sin perder la tensión.', 'Sube empujando con los talones y evita que las rodillas se junten hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una pausa isométrica que mejora el control y la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4816'),
('699a631f-db19-5a17-9548-3bedc4d129cd', 'Sentadilla goblet al cajón con mancuerna', ARRAY['Sujeta la mancuerna al pecho y colócate delante de un cajón con los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás hasta tocar el cajón con los glúteos, manteniendo el pecho alto.', 'Haz una breve pausa y sube empujando con los talones.', 'Evita dejarte caer sobre el cajón; controla la bajada en todo momento.']::text[], 'intermedio', 'Enseña el patrón de sentadilla con un cajón que marca la profundidad y activa glúteos y cuádriceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3692'),
('9afb97de-6e2b-545a-a121-365bbec16284', 'Sentadilla búlgara goblet con mancuerna', ARRAY['Sujeta la mancuerna al pecho y coloca el pie trasero sobre un banco con el delantero firme.', 'Baja flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.', 'Empuja con el talón delantero para subir manteniendo el tronco erguido.', 'Evita que la rodilla delantera pase muy por delante de los dedos del pie o se vaya hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos de forma unilateral con la mancuerna al pecho, mejorando el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7549'),
('f6c02c1f-b685-5cdf-b7a1-3c50476e73cc', 'Sentadilla dividida goblet con mancuerna', ARRAY['Sujeta la mancuerna a la altura del pecho y coloca un pie delante y otro detrás en zancada.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido y la rodilla delantera alineada con el pie.', 'Empuja con el pie delantero para subir sin perder el equilibrio.', 'Evita que la rodilla delantera se vaya hacia dentro y respira al bajar.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con apoyo unilateral, mejorando fuerza, equilibrio y estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3691'),
('6a7fd227-2dbe-5248-86de-70f9c19363b8', 'Sentadilla dividida goblet con pie delantero elevado', ARRAY['Coloca el pie delantero sobre un step y el trasero detrás, con la mancuerna pegada al pecho.', 'Desciende controlando hasta que la rodilla trasera casi toque el suelo.', 'Sube empujando con el talón del pie elevado sin balancearte.', 'Mantén el torso erguido y evita que la rodilla delantera pase muy por delante del pie.']::text[], 'intermedio', 'Aumenta la exigencia sobre el cuádriceps y el glúteo al elevar el pie delantero, ganando fuerza y control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2956'),
('16751346-ef2b-5469-b855-22f2aa09c6be', 'Sentadilla goblet con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos.', 'Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core con una sentadilla frontal que mejora la postura y la profundidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1760'),
('3757cb63-c9f9-5aa9-b760-5377fe6efa99', 'Sentadilla goblet con curl de bíceps', ARRAY['Sujeta la mancuerna con las dos manos a la altura del pecho y separa los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Al subir, realiza un curl de bíceps llevando la mancuerna hacia el pecho.', 'Controla la bajada del curl y evita arquear la espalda al subir.']::text[], 'intermedio', 'Combina fuerza de piernas y bíceps en un movimiento compuesto que eleva la frecuencia cardiaca y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4738'),
('8933f119-669b-5d9d-aadb-06ceaebd00c1', 'Sentadilla goblet con elevación de gemelos', ARRAY['Sujeta la mancuerna al pecho y coloca los pies a la anchura de los hombros.', 'Baja en sentadilla con el torso erguido y las rodillas alineadas.', 'Al subir, elévate sobre las puntas de los pies y aguanta un instante arriba.', 'Baja los talones con control y evita perder el equilibrio o redondear la espalda.']::text[], 'intermedio', 'Trabaja piernas y gemelos en un solo movimiento, mejorando fuerza, equilibrio y estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7469'),
('7fbb627f-39b2-508d-9e9a-0720ec6c26a4', 'Sentadilla sumo goblet con mancuerna', ARRAY['Separa los pies más allá de la anchura de los hombros con las puntas hacia fuera y sujeta la mancuerna al pecho.', 'Baja llevando la cadera atrás y las rodillas hacia fuera, siguiendo la línea de los pies.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita que las rodillas se metan hacia dentro y mantén el pecho alto.']::text[], 'intermedio', 'Enfatiza glúteos y aductores con una postura amplia, mejorando fuerza de cadera y movilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7547'),
('f4fdbe56-b9d9-5fdc-afc9-7b644152e7d5', 'Sentadilla isométrica en pared goblet con mancuerna', ARRAY['Apoya la espalda en la pared y desliza hasta que muslos y rodillas formen unos noventa grados.', 'Sujeta la mancuerna al pecho con los codos pegados al cuerpo.', 'Mantén la posición con la espalda apoyada y la respiración controlada.', 'Evita aguantar la respiración y no dejes que las rodillas se junten.']::text[], 'intermedio', 'Fortalece cuádriceps y core manteniendo una contracción estática que mejora la resistencia muscular.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '7559'),
('f8bc1756-8658-5b44-a9d2-a49fb571ba7a', 'Buenos días con mancuerna', ARRAY['De pie con los pies a la anchura de los hombros, sujeta la mancuerna pegada al pecho o detrás de la nuca.', 'Con las rodillas ligeramente flexionadas, lleva la cadera atrás bajando el torso.', 'Baja hasta notar el estiramiento en los isquiotibiales y vuelve subiendo con la cadera.', 'Evita redondear la espalda y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Refuerza isquiotibiales, glúteos y espalda baja con una bisagra de cadera que mejora el patrón de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6424'),
('bbcaceb6-4a04-516a-ad7e-186c18aca79d', 'Sentadilla buenos días con mancuerna', ARRAY['De pie con la mancuerna al pecho y los pies a la anchura de los hombros.', 'Baja en sentadilla llevando la cadera atrás y manteniendo el pecho alto.', 'Al subir, extiende la cadera apretando los glúteos sin arquear la espalda.', 'Evita juntar las rodillas y controla el descenso en todo momento.']::text[], 'intermedio', 'Combina sentadilla y bisagra de cadera para trabajar glúteos, isquiotibiales y cuádriceps con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5313'),
('ba6afd69-711c-5291-9fb7-a7caee95bd25', 'Sentadilla hack con mancuernas', ARRAY['Sujeta una mancuerna en cada mano a los lados y coloca los pies a la anchura de los hombros.', 'Baja llevando la cadera atrás y las rodillas hacia delante, manteniendo el torso erguido.', 'Desciende hasta donde controles y sube empujando con los talones.', 'Evita levantar los talones y no dejes que la espalda se redondee.']::text[], 'intermedio', 'Aísla el cuádriceps con una sentadilla guiada por el movimiento de cadera, mejorando fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7566'),
('a0d4679d-0ab0-5bf7-b98b-6be79b52440b', 'Cargada y press a media rodilla a un brazo', ARRAY['Colócate en media rodilla con la mancuerna en el suelo junto al pie delantero.', 'Lleva la mancuerna al hombro con un tirón controlado y el core activo.', 'Empuja la mancuerna por encima de la cabeza extendiendo el brazo.', 'Baja con control al hombro y evita arquear la espalda al press.']::text[], 'intermedio', 'Desarrolla hombros y core con un movimiento explosivo que mejora la coordinación y la estabilidad unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10117'),
('3747c437-347d-554a-8333-96241cb0438a', 'Press de hombros a media rodilla a un brazo', ARRAY['Arrodíllate sobre una rodilla con la mancuerna a la altura del hombro.', 'Activa el core y el glúteo para mantener la cadera estable.', 'Empuja la mancuerna por encima de la cabeza sin bloquear la respiración.', 'Baja con control y evita inclinarte hacia un lado al press.']::text[], 'intermedio', 'Fortalece hombros y tríceps en posición de media rodilla, mejorando estabilidad del core y control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11016'),
('23ac4340-de94-59d6-8202-e85b2aae880c', 'Levantamiento thor a media rodilla con mancuerna', ARRAY['En media rodilla, sujeta la mancuerna con las dos manos delante del pecho.', 'Gira el torso llevando la mancuerna hacia un lado con control.', 'Vuelve al centro y repite hacia el otro lado manteniendo la cadera estable.', 'Evita tirar con los brazos y no bloquees la respiración.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con un patrón de rotación controlada que mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10093'),
('765cf5a2-ad30-55ec-aa1f-92668f633741', 'Curl martillo en balón de estabilidad', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.', 'Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos sobre una superficie inestable, mejorando el control y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1659'),
('f5d453f5-8cff-5f26-b934-4a1ab0c24ae8', 'Remo inclinado a dos brazos con agarre martillo', ARRAY['Apoya el pecho en un banco inclinado con una mancuerna en cada mano y agarre neutro.', 'Tira de las mancuernas hacia la cadera juntando las escápulas.', 'Baja con control hasta estirar los brazos sin perder la postura.', 'Evita encoger los hombros y no uses impulso para subir el peso.']::text[], 'intermedio', 'Refuerza la espalda alta y los dorsales con un remo apoyado que mejora la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3320'),
('e4aa837a-75e9-574c-9702-e172109f85eb', 'Cargada colgado con mancuernas', ARRAY['Colócate de pie con una mancuerna en cada mano y las palmas hacia los muslos.', 'Baja ligeramente las caderas llevando el pecho arriba y mantén la espalda neutra.', 'Extiende las caderas y las rodillas de forma explosiva y encoge los hombros para subir las mancuernas.', 'Gira los codos para recibirlas a la altura de los hombros con las rodillas algo flexionadas.', 'Evita tirar con los brazos antes de extender las caderas.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que activa glúteos e isquios y mejora la potencia de todo el cuerpo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4449'),
('50deea52-5c3e-5f67-b0d3-5be98d42a377', 'Cargada colgado y envión con mancuernas', ARRAY['Empieza de pie con las mancuernas junto a los muslos y el core activado.', 'Realiza una cargada explosiva llevando las mancuernas a los hombros con las rodillas flexionadas.', 'Flexiona ligeramente las rodillas y empuja las mancuernas por encima de la cabeza.', 'Bloquea los codos arriba y baja las mancuernas de forma controlada.', 'Evita arquear la zona lumbar al recibir la carga.']::text[], 'avanzado', 'Ejercicio explosivo completo que trabaja glúteos, piernas y hombros y mejora la coordinación y la potencia.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4377'),
('f138b9b7-e995-5fe1-b7f0-23d8773b2ec2', 'Cargada de potencia desde colgado con mancuernas', ARRAY['Sitúate de pie con las mancuernas a la altura de los muslos y los pies a la anchura de las caderas.', 'Haz una pequeña flexión de caderas y rodillas manteniendo el pecho alto.', 'Extiende caderas y rodillas con fuerza y sube las mancuernas hasta los hombros.', 'Recibe la carga con los codos adelantados y las rodillas ligeramente dobladas.', 'No redondees la espalda en la fase de descenso.']::text[], 'avanzado', 'Variante explosiva que recluta glúteos, isquios y trapecios para ganar potencia y velocidad de extensión.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4739'),
('0aa0aa92-7cfe-5506-a1cc-c8d249836064', 'Cargada de potencia desde colgado y envión con mancuernas', ARRAY['Coge una mancuerna en cada mano y colócate de pie con el core firme.', 'Ejecuta una cargada explosiva llevando las mancuernas a los hombros.', 'Aprovecha un pequeño impulso de piernas para empujar las mancuernas sobre la cabeza.', 'Estabiliza arriba con los codos extendidos y baja de forma controlada.', 'Evita empujar con la espalda en lugar de con las piernas.']::text[], 'avanzado', 'Ejercicio de potencia que combina cargada y envión para trabajar glúteos, hombros y tríceps de forma global.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4740'),
('ea2e7a05-dadc-55df-a314-aebf648ad76f', 'Arranque desde colgado con mancuerna', ARRAY['Sujeta una mancuerna con una mano delante de los muslos y los pies a la anchura de las caderas.', 'Flexiona ligeramente caderas y rodillas manteniendo la espalda neutra.', 'Extiende caderas y rodillas con fuerza y tira de la mancuerna hacia arriba pegada al cuerpo.', 'Recibe la mancuerna por encima de la cabeza con el brazo extendido y las rodillas algo flexionadas.', 'Evita balancear el tronco hacia atrás al bloquear arriba.']::text[], 'avanzado', 'Movimiento explosivo que activa glúteos, isquios y hombros y desarrolla potencia y coordinación general.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '10044'),
('95e0024c-0f2a-56b9-80df-e9dca00eae5b', 'Remo con la cabeza apoyada y mancuernas', ARRAY['Apoya la frente en un banco inclinado y sujeta una mancuerna en cada mano.', 'Deja los brazos colgando con la espalda recta y el core activado.', 'Tira de las mancuernas hacia las costillas juntando las escápulas.', 'Baja de forma controlada sin perder la posición del tronco.', 'Evita encoger los hombros hacia las orejas durante el tirón.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides y mejora la postura y la estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4741'),
('7a6788f7-b17c-5079-882b-62fc41e1f8ca', 'Acarreo alto y bajo con mancuernas', ARRAY['Coge una mancuerna en cada mano y camina con el pecho alto y el core firme.', 'Alterna tramos con las mancuernas a la altura de los hombros y tramos con los brazos colgando.', 'Da pasos cortos y controlados manteniendo la mirada al frente.', 'Respira de forma constante y evita inclinarte hacia los lados.', 'No dejes caer los hombros ni bloquees la respiración.']::text[], 'intermedio', 'Trabaja glúteos, core y agarre mientras caminas cargando peso en posiciones alta y baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2911'),
('d07cb5e7-6f11-5cfe-b977-b4e08ccc77ea', 'Tirón alto con mancuernas', ARRAY['Colócate de pie con las mancuernas delante de los muslos y los pies a la anchura de las caderas.', 'Flexiona ligeramente caderas y rodillas con el pecho alto.', 'Extiende las caderas con fuerza y tira de las mancuernas hacia arriba pegadas al cuerpo.', 'Guía los codos por encima de las muñecas hasta la altura del pecho.', 'Evita tirar con los brazos sin usar la extensión de piernas.']::text[], 'intermedio', 'Ejercicio explosivo que trabaja deltoides y trapecios y mejora la potencia del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5666'),
('e00593a4-c7e8-5799-8538-69c2ec66fd1f', 'Peso muerto rumano con cadera apoyada y mancuernas', ARRAY['Apoya las caderas en un banco y sujeta una mancuerna en cada mano.', 'Con las rodillas ligeramente flexionadas, lleva las caderas hacia atrás bajando las mancuernas.', 'Baja hasta notar el estiramiento en los isquios sin redondear la espalda.', 'Sube extendiendo las caderas y aprieta los glúteos arriba.', 'Evita flexionar demasiado las rodillas y convertirlo en una sentadilla.']::text[], 'intermedio', 'Fortalece isquios y glúteos con un patrón de bisagra de cadera que mejora la fuerza posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11058'),
('aa2ef7f2-d469-5c40-8792-e8a91a990ff9', 'Empuje de cadera con mancuerna', ARRAY['Siéntate en el suelo con la espalda alta apoyada en un banco y una mancuerna sobre las caderas.', 'Apoya los pies a la anchura de las caderas y las rodillas flexionadas.', 'Empuja con los talones y extiende las caderas hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba y baja de forma controlada.', 'Evita arquear la zona lumbar en la posición alta.']::text[], 'intermedio', 'Activa glúteos e isquios y mejora la extensión de cadera con una carga cómoda y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4742'),
('1e4c1882-d18a-59ce-a234-cf6657e6db46', 'Hiperextensión con mancuerna', ARRAY['Colócate en el banco de hiperextensión con una mancuerna pegada al pecho.', 'Con las caderas apoyadas, baja el tronco de forma controlada manteniendo la espalda neutra.', 'Sube extendiendo la cadera hasta alinear el cuerpo sin forzar la lumbar.', 'Aprieta glúteos arriba y respira de forma constante.', 'Evita hiperextender la espalda más allá de la línea del cuerpo.']::text[], 'intermedio', 'Refuerza la musculatura lumbar, glúteos e isquios y mejora la estabilidad de la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7328'),
('aae17efa-8518-5887-8668-7380e4b66581', 'Sostén de apertura inclinada a 30 grados con mancuernas', ARRAY['Túmbate en un banco inclinado a 30 grados con una mancuerna en cada mano.', 'Abre los brazos con los codos ligeramente flexionados hasta notar estiramiento en el pecho.', 'Mantén la posición con los omóplatos juntos y el core activado.', 'Respira de forma constante durante todo el sostén.', 'Evita bajar los brazos por debajo de la línea de los hombros.']::text[], 'intermedio', 'Isométrico que mantiene la tensión en el pecho y los hombros y mejora la resistencia muscular.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1449'),
('33019e2a-4b53-57c3-adeb-c252df5a66c4', 'Alrededor del mundo inclinado con mancuernas', ARRAY['Túmbate en un banco inclinado con una mancuerna en cada mano y los brazos extendidos.', 'Dibuja un círculo amplio llevando las mancuernas hacia los lados y hacia abajo.', 'Mantén los codos ligeramente flexionados y los omóplatos juntos.', 'Controla el recorrido y evita balancear los brazos.', 'No dejes que las mancuernas choquen entre sí.']::text[], 'intermedio', 'Trabaja deltoides y pecho superior con un movimiento circular que mejora el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3967'),
('35d72473-0600-5fe1-97e2-a1ee9b3baf34', 'Press de banca inclinado con mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco.', 'Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros.', 'Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.', 'Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el pecho superior, los hombros y los tríceps con un empuje estable y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0314'),
('d65526a0-cbf0-5901-9b13-4fe297d73541', 'Curl de bíceps inclinado con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps y los antebrazos con un estiramiento mayor gracias a la inclinación del banco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0315'),
('7650773b-1180-5915-992e-c01394bd2cc2', 'Press inclinado con mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.', 'Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante.', 'Comienza con los brazos completamente extendidos, perpendiculares al suelo.', 'Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.', 'Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la porción superior del pecho y refuerza hombros y tríceps en empuje inclinado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0316'),
('70007f99-df10-5db8-a6c5-aacbb7429b5c', 'Press inclinado con agarre cerrado y mancuernas', ARRAY['Túmbate en un banco inclinado con una mancuerna en cada mano y las palmas mirándose.', 'Coloca los codos cerca del torso y baja las mancuernas a la altura del pecho.', 'Empuja hacia arriba hasta casi estirar los brazos sin bloquear los codos.', 'Evita abrir los codos hacia los lados para no cargar el hombro.']::text[], 'intermedio', 'Trabaja el tríceps con apoyo del pecho superior y los hombros, útil para ganar fuerza en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4015'),
('664b01d1-b2ba-51c6-b451-d7d806bf581a', 'Aperturas inclinadas con mancuernas', ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho.', 'Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el pectoral superior con un recorrido amplio que estira el pecho y activa el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0319'),
('1a13f5dc-2f2e-5655-bda4-5402ff1b3fb0', 'Apertura inclinada con mancuernas en balón', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el banco inclinado.', 'Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.', 'Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Haz una pausa por un momento, luego contrae los músculos del pecho para llevar las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el pectoral superior añadiendo inestabilidad para trabajar el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1278'),
('770968ce-12b9-5c72-9920-7523458c2810', 'Elevación frontal inclinada con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano frente a los muslos.', 'Sube los brazos estirados hacia delante hasta la altura de los hombros.', 'Baja despacio controlando el movimiento sin dejar caer el peso.', 'No balancees el tronco ni uses impulso para subir.']::text[], 'intermedio', 'Aísla el deltoides anterior y el pecho superior, mejorando la fuerza y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1176'),
('f0d1993c-e249-5f85-83ba-6d0f6a084ff6', 'Elevación frontal inclinada con apoyo en el pecho y mancuernas', ARRAY['Apoya el pecho en un banco inclinado y sujeta una mancuerna en cada mano.', 'Con los brazos casi estirados, elévalos hacia delante hasta la altura del hombro.', 'Baja lentamente sin dejar que el peso tire de ti.', 'Mantén el cuello neutro y evita encoger los hombros.']::text[], 'intermedio', 'Trabaja el deltoides anterior con el pecho apoyado, reduciendo trampas y aislando el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3980'),
('11a07eaf-fb84-5d01-b074-7249e5b475b7', 'Curl martillo inclinado con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos.', 'Mantén la espalda contra el banco y los pies apoyados en el suelo.', 'Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece bíceps y antebrazo con el brazo estirado, mejorando el agarre y la masa muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0320'),
('4592de36-b7c9-5efb-b8a8-f83e3b42c0c7', 'Press martillo inclinado con mancuernas', ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos.', 'Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí.', 'Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Empuje inclinado con agarre neutro que carga pecho, hombro y tríceps de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0321'),
('94db9540-a474-5c07-b696-1bd1210a3a7d', 'Press martillo inclinado en balón con mancuernas', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.', 'Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí.', 'Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento.', 'Baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombro sobre superficie inestable para ganar control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1618'),
('d512ee53-ed7c-588c-943a-1f31591cf2e5', 'Remo inclinado con la cabeza apoyada y mancuernas', ARRAY['Apoya la frente en un banco inclinado y sujeta una mancuerna en cada mano.', 'Tira de los codos hacia atrás llevando las mancuernas junto al torso.', 'Junta las escápulas arriba y baja controlando el peso.', 'Evita tirar con los brazos sin mover la espalda.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con apoyo que protege la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4744'),
('02b7faeb-9be6-56f7-87ff-a23b1213f68d', 'Curl interno de bíceps inclinado con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el bíceps con rotación interna para potenciar el pico y la fuerza de flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0322'),
('ef651d88-f410-5dc6-bbdd-659d1204b788', 'Apertura inclinada a un brazo con mancuerna en balón', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en una mano.', 'Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sostén la mancuerna con el brazo extendido recto hacia arriba sobre el pecho, con la palma hacia adentro.', 'Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.', 'Haz una pausa por un momento cuando el brazo esté paralelo al suelo.', 'Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla un lado del pectoral superior sobre balón, exigiendo control y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1280'),
('a0852c2c-8341-5e2c-8490-cf5b2c0842c8', 'Elevación frontal inclinada a un brazo con apoyo en el pecho y mancuerna', ARRAY['Apoya el pecho en un banco inclinado y sujeta una mancuerna con una mano.', 'Eleva el brazo estirado hacia delante hasta la altura del hombro.', 'Baja despacio sin dejar caer el peso de golpe.', 'Mantén el torso pegado al banco y no gires el tronco.']::text[], 'intermedio', 'Aísla el deltoides anterior de un lado con el pecho apoyado, mejorando el control y la simetría.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4071'),
('f4335856-3b00-5b2e-993c-a5a032de21ea', 'Press martillo inclinado a un brazo con mancuerna', ARRAY['Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.', 'Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros.', 'Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo.', 'Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Empuje unilateral que carga tríceps, hombro y pecho, corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1619'),
('21b15a52-c04d-5d0c-8a2b-5c1eddbca045', 'Press martillo inclinado a un brazo en balón con mancuerna', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en una mano.', 'Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.', 'Empuja la mancuerna hacia el techo, estirando el brazo.', 'Baja la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Trabaja tríceps y hombro de forma unilateral sobre balón, mejorando equilibrio y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1620'),
('0f238a02-a531-5d00-b94a-6995b68dcd07', 'Elevación lateral inclinada a un brazo con mancuerna', ARRAY['Siéntate en un banco inclinado con una mancuerna en una mano, apoyándola sobre el muslo.', 'Inclínate hacia adelante y coloca el brazo superior contra la parte interna del muslo.', 'Levanta la mancuerna hacia el lado, manteniendo el brazo ligeramente flexionado y la palma hacia abajo.', 'Continúa levantando hasta que el brazo quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja el deltoides lateral para ganar amplitud y forma del hombro, con apoyo inclinado que aísla el movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0323'),
('fce0bb80-5f49-5665-ba3a-9f99c96d30d5', 'Press inclinado a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo.', 'Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sostén la mancuerna a la altura del hombro con la palma hacia adelante.', 'Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Fortalece el pectoral superior y estabilizadores del hombro, añadiendo inestabilidad que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1282'),
('26e0aa9c-7e78-52aa-aa4b-09942573daa8', 'Press inclinado con palmas hacia dentro y mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Planta los pies firmemente en el suelo y mantén la espalda recta contra el banco.', 'Comienza con las mancuernas a la altura de los hombros, con los codos flexionados y las palmas enfrentadas entre sí.', 'Empuja las mancuernas hacia arriba y alejándolas del cuerpo, extendiendo completamente los brazos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el pectoral superior con agarre neutro, reduciendo tensión en el hombro y mejorando la estabilidad articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0324'),
('202fc986-183f-5649-aee7-7d8134d52639', 'Elevación Powell inclinada con mancuerna', ARRAY['Colócate boca abajo sobre un banco inclinado con una mancuerna en la mano y el brazo colgando.', 'Sube el codo hacia atrás manteniéndolo flexionado y eleva la mancuerna hasta la altura del hombro.', 'Gira ligeramente la muñeca hacia arriba al final del recorrido para activar el deltoides posterior.', 'Baja la mancuerna con control sin dejar caer el brazo de golpe.', 'Evita encoger el hombro o usar impulso del tronco durante la subida.']::text[], 'intermedio', 'Trabaja el deltoides posterior y el manguito rotador, mejorando la salud del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7252'),
('d00a24f9-e674-5284-86c0-e78956800da4', 'Apertura posterior inclinada con mancuernas', ARRAY['Túmbate boca abajo en un banco inclinado con una mancuerna en cada mano y los brazos colgando.', 'Abre los brazos hacia los lados con los codos ligeramente flexionados hasta la altura de los hombros.', 'Junta las escápulas al final del recorrido sin encoger el cuello.', 'Baja las mancuernas despacio controlando el movimiento.', 'Evita balancear el tronco o usar demasiado peso para no perder la técnica.']::text[], 'intermedio', 'Refuerza el deltoides posterior y la espalda alta, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2500'),
('92e34cdc-6641-5af1-94e4-de25dcb38701', 'Elevación lateral posterior inclinada con mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano.', 'Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí.', 'Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoides posterior y los romboides para equilibrar el hombro y mejorar la estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0326'),
('7d29b133-19c0-5178-a6b0-8781db5f34fd', 'Press de banca inclinado a 30 grados con agarre inverso y mancuernas', ARRAY['Túmbate en un banco inclinado a 30 grados con una mancuerna en cada mano y agarre supino.', 'Baja las mancuernas hacia el pecho con los codos cerca del cuerpo y control.', 'Empuja hacia arriba hasta extender los brazos sin bloquear del todo los codos.', 'Mantén las muñecas firmes y alineadas durante todo el recorrido.', 'Evita abrir demasiado los codos o usar un peso que te haga perder el control.']::text[], 'intermedio', 'Enfatiza el pectoral superior y la porción clavicular con agarre supino, aumentando la activación del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1214'),
('19063634-bd3d-5d70-b4f3-eb11f5e5629e', 'Elevación de hombros inclinada con mancuernas', ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia abajo.', 'Apoya las mancuernas sobre los muslos y recuéstate en el banco.', 'Usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia adelante.', 'Exhala y levanta lentamente las mancuernas por encima de la cabeza, manteniendo una ligera flexión en los codos.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el serrato anterior y los hombros para mejorar la movilidad escapular y la estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0328'),
('06e851d1-72e4-5797-8d74-50e475306c1e', 'Press de hombros inclinado con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano a la altura de los hombros.', 'Empuja las mancuernas hacia arriba hasta casi extender los brazos.', 'Baja con control hasta la altura de los hombros sin dejar caer el peso.', 'Mantén el core activo y la espalda apoyada durante todo el movimiento.', 'Evita arquear la zona lumbar o bloquear los codos con fuerza al final.']::text[], 'intermedio', 'Fortalece los deltoides y el tríceps con un ángulo inclinado que también implica el pectoral superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5261'),
('6542c3c7-6a90-5d5c-839a-04c21b777b5e', 'Encogimientos inclinados con mancuernas', ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano.', 'Coloca los pies planos sobre el suelo y deja que los brazos cuelguen rectos hacia abajo con las palmas hacia el cuerpo.', 'Manteniendo los brazos rectos, encoge los hombros hacia las orejas lo más alto posible.', 'Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el trapecio superior para mejorar la fuerza del cuello y la estabilidad de los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0329'),
('def86516-e109-5bac-846f-caae390fb97c', 'Extensión de tríceps inclinada con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro.', 'Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.', 'Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos.', 'Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en un ángulo inclinado que estira el músculo y favorece la hipertrofia del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0330'),
('ba2e73d2-65b8-5151-8571-eb7b4b887eab', 'Patada de tríceps inclinado con mancuerna', ARRAY['Apóyate en un banco inclinado con una mancuerna en la mano y el codo pegado al torso.', 'Extiende el brazo hacia atrás hasta que quede recto sin mover el codo.', 'Aprieta el tríceps al final del recorrido y mantén un segundo.', 'Baja la mancuerna con control hasta flexionar el codo unos 90 grados.', 'Evita balancear el brazo o despegar el codo del costado.']::text[], 'intermedio', 'Aísla el tríceps con el brazo apoyado, mejorando la definición y la fuerza en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7879'),
('48871a6e-2c22-5867-95e2-fb36b57000c4', 'Press inclinado con giro y mancuernas', ARRAY['Túmbate en un banco inclinado con una mancuerna en cada mano y agarre neutro.', 'Empuja las mancuernas hacia arriba mientras giras las palmas hacia delante.', 'Extiende los brazos sin bloquear los codos y mantén el control.', 'Baja girando las muñecas de nuevo a agarre neutro hasta el pecho.', 'Evita girar con impulso o perder la alineación de las muñecas.']::text[], 'intermedio', 'Combina press y rotación para trabajar el pectoral superior con mayor rango y activación del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6218'),
('5271f9d3-ed49-5e26-a5c8-31475ee6b9f7', 'Aperturas inclinadas con giro y mancuernas', ARRAY['Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Recuéstate en el banco y empuja las mancuernas hacia arriba hasta la posición inicial, directamente por encima del pecho, con los brazos extendidos.', 'Baja las mancuernas hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho.', 'Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden mirando hacia adelante en la parte inferior del movimiento.', 'Invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial, contrayendo los músculos del pecho en la parte superior.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira y activa el pectoral superior con rotación final que aumenta la tensión en el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0331'),
('e307d8ab-6565-516b-bc2d-f1f879c3c908', 'Extensión inclinada a dos brazos con mancuernas', ARRAY['Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.', 'Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho.', 'Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps con ambos brazos en un ángulo inclinado que estira el músculo y mejora la fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1733'),
('7698ccb2-ee35-5da6-8c64-d020744ca9f9', 'Elevación frontal inclinada con mancuernas y apoyo en el pecho', ARRAY['Apoya el pecho en un banco inclinado y sujeta una mancuerna en cada mano con los brazos colgando.', 'Eleva los brazos hacia delante hasta la altura de los hombros sin balancear el tronco.', 'Baja las mancuernas de forma controlada en dos o tres segundos.', 'Evita encoger los hombros hacia las orejas y mantén el cuello relajado.']::text[], 'intermedio', 'Fortalece la parte anterior del hombro y el pecho superior, mejorando la estabilidad y el control del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4236'),
('d43882d2-b6a2-5c09-a164-989e415ac67e', 'Peso muerto a una pierna con mancuerna', ARRAY['Sujeta una mancuerna con la mano del mismo lado que la pierna de apoyo.', 'Inclina el tronco hacia delante mientras la otra pierna se eleva hacia atrás, manteniendo la espalda recta.', 'Baja hasta notar el estiramiento en el isquiotibial y vuelve a subir apretando el glúteo.', 'Evita redondear la espalda y mantén la mirada al frente.']::text[], 'intermedio', 'Trabaja los isquiotibiales y glúteos mientras mejora el equilibrio y la estabilidad del core en apoyo unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7648'),
('e5f927c2-6c76-51ae-88a5-8ac2b55ae303', 'Sentadilla dividida ipsilateral con mancuerna', ARRAY['Coloca una pierna delante y otra detrás, con la mancuerna en la mano del lado de la pierna delantera.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el pie delantero para volver a la posición inicial.', 'Evita que la rodilla delantera se desplace demasiado hacia dentro o hacia delante.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4048'),
('f3d4cb45-3b61-52bd-a009-5c3f1a01d13a', 'Cruz de hierro con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo.', 'Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el deltoides y el pecho con un movimiento de apertura que mejora el control escapular y la fuerza del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0332'),
('aa8f56c0-ad99-5e13-9777-fea755393004', 'Curl jefferson con mancuerna', ARRAY['Sujeta una mancuerna con ambas manos delante de los muslos y separa los pies a la anchura de las caderas.', 'Redondea la columna vértebra a vértebra mientras bajas la mancuerna hacia el suelo.', 'Sube despacio desenrollando la columna desde la base hasta la cabeza.', 'Evita forzar el rango y no bloquees la respiración durante el descenso.']::text[], 'principiante', 'Movilidad de la columna que estira isquiotibiales y glúteos, mejorando la flexión vertebral y la conciencia postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '7329'),
('83a66c00-b8ed-5df3-9486-0044be1bc6c7', 'Salto al cajón con mancuernas', ARRAY['Sujeta una mancuerna en cada mano y colócate frente a un cajón estable.', 'Flexiona las rodillas y salta hacia el cajón aterrizando con ambos pies a la vez.', 'Amortigua la caída con las rodillas flexionadas y el tronco ligeramente inclinado.', 'Evita saltar si el cajón es demasiado alto o si aterrizas con las rodillas hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia de piernas y explosividad en cuádriceps y glúteos, mejorando la capacidad de salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10987'),
('39d5068f-5723-549b-a266-1efe582613d6', 'Sentadilla con salto y mancuernas', ARRAY['Sujeta una mancuerna en cada mano a los lados del cuerpo con los pies a la anchura de los hombros.', 'Baja en sentadilla y salta con fuerza hacia arriba extendiendo las caderas.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto.', 'Evita aterrizar con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Mejora la potencia y la explosividad del tren inferior, implicando cuádriceps, glúteos y gemelos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1552'),
('2322d94e-989f-5606-a63e-552807a0e4c1', 'Puente de glúteos kas con mancuernas', ARRAY['Túmbate boca arriba con una mancuerna apoyada sobre la cadera y los pies en el suelo.', 'Empuja con los talones y eleva la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta el glúteo arriba y baja de forma controlada sin apoyar del todo.', 'Evita arquear la zona lumbar en exceso o empujar con la punta de los pies.']::text[], 'intermedio', 'Aísla el glúteo con una elevación de cadera controlada que también activa isquiotibiales y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5554'),
('d5372b7b-9898-5d50-b830-331a9d70cb4d', 'Patada de tríceps con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados.', 'Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.', 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en extensión de codo, mejorando el tono y la fuerza de la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0333'),
('1c9d2935-6a34-54fa-b304-a3bb31da6831', 'Patadas de tríceps en balón de estabilidad con mancuernas', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.', 'Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.', 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps sobre una superficie inestable, añadiendo demanda de core y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1734'),
('1764b155-cd2c-5823-8189-8ec8bb7a05bb', 'Press arnold de rodillas con mancuernas', ARRAY['Arrodíllate con el tronco erguido y sujeta una mancuerna en cada mano a la altura del pecho con las palmas hacia ti.', 'Empuja las mancuernas hacia arriba girando las palmas hacia fuera al extender los brazos.', 'Baja invirtiendo el giro hasta la posición inicial de forma controlada.', 'Evita arquear la espalda o perder la posición neutra de la pelvis.']::text[], 'intermedio', 'Fortalece el hombro con rotación completa, implicando tríceps y core por la posición de rodillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4745'),
('b0f9e27b-888f-5a42-bd57-910460a30fda', 'Rotación de rodillas alrededor de la cabeza con mancuerna', ARRAY['Arrodíllate y sujeta una mancuerna ligera con una mano a la altura del hombro.', 'Dibuja un círculo amplio alrededor de la cabeza con el brazo extendido, sin forzar.', 'Realiza el recorrido lento y controlado en ambos sentidos.', 'Evita compensar con el tronco o elevar el hombro durante el movimiento.']::text[], 'principiante', 'Movilidad de hombro que mejora el control rotacional escapular y la estabilidad del manguito rotador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10200'),
('bc268519-eace-5a2d-97b6-67a115ad4ffd', 'Curl de bíceps de rodillas en balón de estabilidad con mancuernas', ARRAY['Arrodíllate en el suelo con un balón de estabilidad frente a ti.', 'Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba.', 'Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el bíceps y los antebrazos sobre una base inestable que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1660'),
('92825ac7-4f82-5b79-8556-c68da4ce43cd', 'Sostén de rodillas a de pie con mancuernas, agarre de cargada', ARRAY['Arrodíllate con una mancuerna en cada mano en agarre de cargada a la altura de los hombros.', 'Empuja con los pies para levantarte manteniendo el tronco erguido y el core activo.', 'Controla el descenso hasta volver a las rodillas sin dejarte caer.', 'Evita redondear la espalda o perder el equilibrio al subir.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con un patrón de levantamiento que mejora la fuerza funcional y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5064'),
('0e3f5531-28d5-5e68-9f09-88bcecce8f2b', 'Press de hombros contrario de rodillas con mancuerna', ARRAY['Arrodíllate con una mancuerna en una mano a la altura del hombro.', 'Empuja la mancuerna hacia arriba extendiendo el brazo sin inclinar el tronco.', 'Baja de forma controlada hasta la altura del hombro.', 'Evita rotar el tronco o compensar con la cadera al empujar.']::text[], 'intermedio', 'Fortalece el hombro de forma unilateral, mejorando la estabilidad del core y corrigiendo desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8502');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('6996a7a6-7239-5e82-ad86-a04984b88101', 'Press de hombros a un brazo de rodillas con mancuerna', ARRAY['Colócate de rodillas con la espalda recta y la mancuerna a la altura del hombro.', 'Aprieta glúteos y abdomen para no arquear la zona lumbar.', 'Empuja la mancuerna hacia arriba hasta estirar el brazo sin bloquear del todo el codo.', 'Baja controlando el peso hasta la altura del hombro mientras inspiras.', 'Evita girar el tronco o inclinarte hacia un lado para compensar.']::text[], 'intermedio', 'Fortalece el hombro y el tríceps mientras el core y los glúteos estabilizan el cuerpo en posición de rodillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11017'),
('5e7f2d76-7229-53ae-ab14-30eeea131556', 'Salto al cajón desde rodillas con mancuernas', ARRAY['Colócate de rodillas frente al cajón con una mancuerna en cada mano.', 'Impulsa con los glúteos y los brazos para saltar y caer de pie sobre el cajón.', 'Aterriza con las rodillas flexionadas y el peso repartido en todo el pie.', 'Baja del cajón con control y vuelve a la posición de rodillas.', 'Evita saltar con el cajón demasiado alto o aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Trabajo pliométrico que potencia glúteos y piernas y mejora la capacidad de salto y la estabilidad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10988'),
('157d82df-bc88-527f-afda-6e96168301d6', 'Patada de tríceps de rodillas con mancuerna', ARRAY['Colócate de rodillas con el tronco inclinado y una mano apoyada para estabilizarte.', 'Sujeta la mancuerna con el codo pegado al costado y flexionado unos 90 grados.', 'Extiende el brazo hacia atrás hasta estirar el codo sin mover el hombro.', 'Vuelve despacio a la posición inicial controlando el peso.', 'Evita balancear el tronco o abrir el codo hacia fuera.']::text[], 'intermedio', 'Aísla el tríceps y mejora la extensión del codo, con el core activo para mantener la postura estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7880'),
('3f74b3a5-c98c-564a-8ec7-47fd0042ce5a', 'Elevación con giro de abajo a arriba de rodillas con mancuerna', ARRAY['Colócate de rodillas con la mancuerna sujeta con ambas manos delante del pecho.', 'Baja el peso hacia un lado con un giro controlado del tronco.', 'Sube la mancuerna hacia el lado contrario describiendo un arco.', 'Mantén el abdomen apretado y la espalda recta durante todo el recorrido.', 'Evita girar solo con los brazos o perder la postura de las caderas.']::text[], 'intermedio', 'Activa abdomen y oblicuos con un movimiento de rotación que también implica hombros y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8505'),
('65d6f2f2-d5b7-5a62-9de6-5450f61ed430', 'Remo kroc con mancuerna', ARRAY['Apoya una mano y una rodilla en un banco con la espalda paralela al suelo.', 'Sujeta la mancuerna con el brazo estirado y el hombro relajado.', 'Tira del peso hacia la cadera llevando el codo pegado al cuerpo.', 'Baja la mancuerna controlando el movimiento sin dejar caer el hombro.', 'Evita usar impulso del tronco o redondear la espalda.']::text[], 'intermedio', 'Ejercicio de espalda que desarrolla dorsal y trapecio, además de mejorar el agarre y la fuerza del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10329'),
('c77bdd40-2e84-5001-a079-a6f956922690', 'Press larsen con mancuernas', ARRAY['Túmbate en el banco con los pies en el aire y las mancuernas a la altura del pecho.', 'Aprieta el abdomen y los glúteos para mantener la zona lumbar estable.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos.', 'Baja el peso despacio hasta la altura del pecho sin perder la tensión.', 'Evita arquear la espalda o apoyar los pies para ganar impulso.']::text[], 'intermedio', 'Variante de press que trabaja el pecho y el tríceps sin apoyar los pies, exigiendo más al core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6272'),
('b107d991-3599-5303-a049-93930d1a4114', 'Zancada lateral con mancuernas', ARRAY['De pie con una mancuerna en cada mano y los pies juntos.', 'Da un paso amplio hacia un lado y flexiona esa rodilla llevando la cadera atrás.', 'Mantén la otra pierna estirada y el pie apoyado en el suelo.', 'Empuja con la pierna flexionada para volver al centro.', 'Evita que la rodilla se vaya hacia dentro o que el tronco se incline en exceso.']::text[], 'intermedio', 'Fortalece glúteos y aductores y mejora la movilidad lateral de cadera y la estabilidad de las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4853'),
('2588f975-6e35-5498-9a46-6d3484357fff', 'Zancada lateral con curl de bíceps y mancuernas', ARRAY['De pie con una mancuerna en cada mano y los brazos estirados.', 'Da un paso lateral amplio y flexiona la rodilla mientras bajas la cadera.', 'Al volver al centro, flexiona los codos y sube las mancuernas hacia los hombros.', 'Baja las mancuernas controlando el movimiento antes del siguiente paso.', 'Evita balancear el tronco o usar impulso para subir el peso.']::text[], 'intermedio', 'Combina el trabajo de piernas y glúteos con un curl que refuerza bíceps y coordinación general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1553'),
('bb85c5f4-745c-594f-ac83-e8bf2ccd9bdd', 'Elevaciones laterales con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Mantén la espalda recta y activa el core.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoides medio para dar amplitud al hombro y mejorar la estética de la parte superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0334'),
('d2f73f6d-a71a-5fd7-8e59-b89eb8938288', 'Plancha con elevación lateral y mancuernas', ARRAY['Colócate en plancha sobre antebrazos con una mancuerna al lado de una mano.', 'Mantén el cuerpo alineado y el abdomen apretado.', 'Sujeta la mancuerna y elévala hacia un lado sin girar el tronco.', 'Baja el peso con control y repite o cambia de lado.', 'Evita hundir la cadera o perder la alineación de la cabeza y los pies.']::text[], 'intermedio', 'Refuerza el core y los hombros manteniendo la plancha mientras se eleva el peso lateralmente.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8221'),
('8a7489a8-54f3-5592-b3ed-ba2e4dcdb86b', 'Subida lateral al banco con mancuernas', ARRAY['Colócate de lado al banco con una mancuerna en cada mano.', 'Apoya un pie sobre el banco y empuja con esa pierna para subir.', 'Mantén el tronco erguido y la rodilla alineada con el pie.', 'Baja despacio hasta el suelo controlando el movimiento.', 'Evita impulsarte con la pierna de abajo o dejar caer el peso.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un patrón de subida que mejora la fuerza unilateral y el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2468'),
('82ced353-be66-56fc-9419-fb5ca54bcac1', 'Sentadilla dividida baja con mancuernas', ARRAY['Coloca un pie delante y otro detrás en posición de zancada.', 'Sujeta una mancuerna en cada mano a los lados del cuerpo.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a subir.', 'Evita que la rodilla delantera pase demasiado la punta del pie o que el tronco se incline.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sentadilla unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6328'),
('4c568988-e6b6-5d92-b567-4f082ac1707b', 'Elevación lu con mancuernas', ARRAY['De pie con una mancuerna en cada mano delante de los muslos.', 'Eleva los brazos hacia delante y luego ábrelos hacia los lados en un arco.', 'Sube hasta la altura de los hombros sin encoger el cuello.', 'Baja el peso por el mismo camino con control.', 'Evita usar impulso o elevar los hombros hacia las orejas.']::text[], 'intermedio', 'Trabaja el deltoides y la parte alta de la espalda con un recorrido que también implica el manguito rotador.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10858'),
('251575c3-b97b-53fc-ace4-ca253c072eb3', 'Zancadas con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo.', 'Empuja con el talón derecho para regresar a la posición inicial.', 'Repite con la pierna izquierda.', 'Alterna las piernas el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio básico de piernas que activa glúteos, cuádriceps y femoral y mejora el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0336'),
('78d7ab85-3399-5581-ba6d-be8fe712784f', 'Extensión alternada acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.', 'Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido.', 'Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite con el otro brazo, alternando lados el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps tumbado en el banco, alternando brazos para mantener la tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1729'),
('3f57716b-7b3f-508b-bfc6-80205f6970cf', 'Remo acostado con agarre cerrado en rack con mancuernas', ARRAY['Colócate tumbado boca abajo sobre un banco o rack con una mancuerna en cada mano y los codos pegados al cuerpo.', 'Tira de las mancuernas hacia el pecho juntando las escápulas sin encoger los hombros.', 'Baja despacio controlando el movimiento hasta estirar los brazos.', 'Evita arquear la espalda o usar impulso para subir el peso.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps tirando desde una posición estable, ideal para ganar fuerza y control en el dorsal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4425'),
('857e92ef-1ce9-5d82-b95b-627fc2f7db19', 'Press de codos acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.', 'Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos.', 'Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con un movimiento de extensión de codos tumbado, útil para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0338'),
('d7aac10d-d923-54f6-ac25-32d9b67b3711', 'Extensión acostado con mancuernas cruzando la cara', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí.', 'Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo.', 'Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps en un rango controlado cruzando la mancuerna, mejorando la fuerza y estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0337'),
('de208837-7c8e-5bca-ae77-338cf0708b81', 'Rotación externa de hombro acostado con mancuerna', ARRAY['Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados.', 'Sostén una mancuerna en la mano con la palma hacia abajo.', 'Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Fortalece el manguito rotador y estabiliza el hombro, útil en readaptación para prevenir molestias y lesiones.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 2.3, 'rehab', '0863'),
('55240f65-a4d9-5da7-a430-ccaaed6e3fec', 'Curl femoral acostado con mancuerna', ARRAY['Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo.', 'Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los isquiotibiales flexionando la rodilla tumbado, mejorando la fuerza y el control de la parte posterior del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0339'),
('c21dc46c-dee9-5583-83c5-42e12cf82026', 'Rompecráneos acostado en el suelo con mancuernas', ARRAY['Túmbate boca arriba con una mancuerna en cada mano y los brazos extendidos hacia el techo.', 'Flexiona los codos llevando las mancuernas hacia la frente sin mover los hombros.', 'Extiende los codos para volver a la posición inicial controlando el movimiento.', 'Mantén los codos apuntando al techo y evita abrirlos hacia los lados.']::text[], 'intermedio', 'Aísla el tríceps con extensión de codos tumbado en el suelo, ganando fuerza y control en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4151'),
('dca4af1f-7668-593c-9f1d-5e987e809f1d', 'Press de apretón acostado en el suelo con mancuernas', ARRAY['Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho y los codos cerca del torso.', 'Aprieta las mancuernas entre sí y empuja hacia arriba hasta extender los brazos.', 'Baja despacio hasta que los brazos toquen el suelo sin relajar la tensión.', 'Mantén los omóplatos retraídos y evita arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja el pecho con un press que aprieta las mancuernas, mejorando la fuerza y la activación del pectoral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10042'),
('9a2c1494-768e-5d29-8861-e8a888791877', 'Press martillo acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba.', 'Baja las mancuernas a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.', 'Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho con agarre neutro, reduciendo la tensión en el hombro y fortaleciendo también el tríceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0340'),
('db70788b-4001-5bc2-a690-dd4db7361a35', 'Curl de pierna acostado con mancuerna', ARRAY['Túmbate boca abajo con una mancuerna sujeta entre los pies.', 'Flexiona las rodillas llevando la mancuerna hacia los glúteos sin mover la cadera.', 'Baja despacio controlando el movimiento hasta estirar las piernas.', 'Evita arquear la espalda y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Fortalece los isquiotibiales flexionando la rodilla tumbado, mejorando la estabilidad y la fuerza del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4292'),
('ad58ec31-3099-5aee-9602-e8ee8d8ffeba', 'Curl de piernas acostado con mancuerna', ARRAY['Túmbate boca abajo con la mancuerna sujeta entre los pies y las piernas estiradas.', 'Flexiona las rodillas acercando la mancuerna a los glúteos sin despegar la cadera.', 'Baja lentamente hasta estirar las piernas del todo.', 'Mantén el core activo y evita balancear el peso con impulso.']::text[], 'intermedio', 'Trabaja los isquiotibiales con flexión de rodilla tumbado, ganando fuerza y control en la parte posterior del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6161'),
('75d48fe5-194a-5ecc-8536-6fc7182785a3', 'V-up oblicuo acostado con mancuerna', ARRAY['Túmbate boca arriba con una mancuerna sujeta con ambas manos y las piernas estiradas.', 'Eleva el torso y las piernas a la vez llevando la mancuerna hacia un lado.', 'Baja controlando el movimiento y repite hacia el otro lado.', 'Evita tirar del cuello y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un movimiento de flexión y rotación, mejorando la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6799'),
('68bf2eaf-a984-5a1b-a8b7-6c5026bf71fc', 'Press de pecho acostado en el suelo con mancuernas', ARRAY['Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho y los codos a unos 45 grados.', 'Empuja las mancuernas hacia arriba hasta extender los brazos sin bloquear del todo.', 'Baja despacio hasta que los brazos toquen el suelo.', 'Mantén los omóplatos retraídos y evita arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja el pecho con un press en el suelo que limita el rango y protege el hombro, ganando fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3668'),
('5e6d740b-6cd7-5c7b-811b-30684cd3005e', 'Press martillo acostado en el suelo con mancuernas', ARRAY['Túmbate en el suelo con una mancuerna en cada mano y las palmas mirándose entre sí.', 'Empuja hacia arriba hasta extender los brazos manteniendo el agarre neutro.', 'Baja despacio hasta que los codos toquen el suelo.', 'Mantén los hombros estables y evita abrir los codos en exceso.']::text[], 'intermedio', 'Trabaja el pecho con agarre neutro en el suelo, reduciendo la tensión en el hombro y fortaleciendo el tríceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3319'),
('40ed2243-1ae1-5f05-9b36-eb224c6592bc', 'Press acostado a un brazo con mancuerna', ARRAY['Túmbate boca arriba en un banco con la espalda apoyada y los pies planos sobre el suelo.', 'Sostén una mancuerna en una mano con la palma hacia los pies.', 'Extiende el brazo recto hacia el techo, manteniendo el codo ligeramente flexionado.', 'Baja lentamente la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.', 'Haz una pausa por un momento en la parte inferior, luego empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja el pecho de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad del hombro y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0342'),
('2d716076-56b4-55b5-a7a1-7b152a9af137', 'Extensión de tríceps acostado a un brazo con agarre prono y mancuerna', ARRAY['Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.', 'Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro.', 'Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.', 'Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps de forma unilateral con agarre prono, mejorando la fuerza y corrigiendo diferencias entre brazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0344'),
('deacf84f-d30e-58cb-b943-3d8f24513aeb', 'Elevación lateral posterior acostado a un brazo con mancuerna', ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo.', 'Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Aísla el deltoide posterior y los romboides, mejorando la postura y el equilibrio muscular del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0345'),
('fa9ec8aa-e02e-57de-90ec-738537684339', 'Extensión de tríceps acostado a un brazo con agarre supino y mancuerna', ARRAY['Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.', 'Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro.', 'Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.', 'Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Trabaja el tríceps en aislamiento con agarre supino, reforzando también el antebrazo y la estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0346'),
('ab09e9de-33e4-5420-921e-e92f08ecea6c', 'Sostén maltés acostado con agarre prono y mancuernas', ARRAY['Túmbate boca arriba con una mancuerna en cada mano y los brazos extendidos sobre el pecho.', 'Abre los brazos hacia los lados manteniéndolos rectos hasta formar una T, con las palmas hacia abajo.', 'Aguanta la posición sin bajar los brazos entre 15 y 30 segundos respirando de forma controlada.', 'Evita arquear la zona lumbar: mantén las costillas abajo y el core activo.', 'Baja las mancuernas despacio al terminar, sin dejarlas caer de golpe.']::text[], 'intermedio', 'Isométrico exigente para deltoides, pecho superior y core, que refuerza la estabilidad del hombro y la resistencia muscular.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1443'),
('8c3a27c1-7a00-5d74-9777-b718b2d63d6f', 'Pronación acostado con mancuerna', ARRAY['Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano.', 'Gira las palmas de modo que queden mirando hacia arriba.', 'Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo.', 'Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los rotadores del antebrazo y mejora el control de la muñeca, útil para prevenir molestias en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0347'),
('707f8e80-8c11-5ec4-8cb8-6595af49deec', 'Remo para deltoide posterior acostado con mancuernas', ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas hacia adentro.', 'Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.', 'Activando los músculos de la espalda, levanta las mancuernas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y el deltoide posterior, corrigiendo desequilibrios y mejorando la postura en el escritorio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1328'),
('365c0007-e980-5737-99e3-e7aaa8389d75', 'Elevación lateral posterior acostado con mancuernas', ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.', 'Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoide posterior y los trapecios, clave para un hombro equilibrado y una postura más erguida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0348'),
('93d6b101-7b27-565e-af14-41a8c52fc39b', 'Remo acostado sobre rack con mancuernas', ARRAY['Colócate boca abajo sobre un rack o banco inclinado con una mancuerna en cada mano.', 'Deja los brazos colgando y agarra las mancuernas con las palmas enfrentadas.', 'Tira de los codos hacia atrás pegándolos al torso hasta llevar las mancuernas a la altura del pecho.', 'Junta las escápulas arriba y baja las mancuernas de forma controlada sin perder la posición.', 'Evita tirar con los brazos: inicia el movimiento desde la espalda y mantén el cuello neutro.']::text[], 'intermedio', 'Trabaja la espalda alta y los dorsales con apoyo, reduciendo la carga lumbar y mejorando la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5697'),
('76f83e17-885c-57e2-8b98-1070a8ea4e5a', 'Extensión acostado a un brazo con mancuerna', ARRAY['Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho.', 'Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto.', 'Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps de un brazo tumbado, mejorando la fuerza y la simetría entre ambos lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1735'),
('c2724a79-9eff-562f-af4d-1e11887c3d3a', 'Press a un brazo recto acostado en el suelo con mancuerna', ARRAY['Túmbate boca arriba en el suelo con una mancuerna en una mano y el brazo extendido sobre el pecho.', 'Flexiona ligeramente el codo y baja la mancuerna hacia el lado hasta que el brazo toque el suelo.', 'Empuja hacia arriba hasta extender el brazo sin bloquear el codo del todo.', 'Mantén el core firme y evita que la cadera gire o se despegue del suelo.', 'Respira al empujar y controla la bajada en dos o tres segundos.']::text[], 'intermedio', 'Trabaja el pecho y el tríceps con un brazo, sumando demanda de core y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11800'),
('3a1dce5f-6548-5260-9c17-63e4367248a7', 'Press con brazos rectos acostado en el suelo con mancuernas', ARRAY['Túmbate boca arriba con una mancuerna en cada mano y los brazos extendidos sobre el pecho.', 'Baja las mancuernas hacia los lados con los codos ligeramente flexionados hasta tocar el suelo.', 'Empuja hacia arriba hasta juntar las mancuernas sin bloquear los codos con brusquedad.', 'Mantén los omóplatos retraídos y la zona lumbar pegada al suelo durante todo el movimiento.', 'Evita abrir demasiado los brazos: no bajes más allá de la línea de los hombros.']::text[], 'intermedio', 'Fortalece el pecho, el tríceps y el core con un press de recorrido corto y controlado en el suelo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9213'),
('5718a12c-ab9c-50f1-b681-9a7097176089', 'Supinación acostado con mancuerna', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo.', 'Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza los rotadores del antebrazo y la muñeca, ayudando a prevenir lesiones en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0349'),
('e61b97c1-2005-55d5-aff2-ea7939febe7e', 'Supinación acostado en el suelo con mancuerna', ARRAY['Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano.', 'Gira las palmas hacia arriba, manteniendo los codos cerca de los costados.', 'Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la rotación del antebrazo con apoyo en el suelo, mejorando el control de la muñeca y el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2706'),
('51871bf4-bc4d-5785-8f98-5368fb06f9be', 'Curl de bíceps boca arriba acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.', 'Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps tumbado, reduciendo el impulso del cuerpo y mejorando la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1661'),
('6b324170-070a-5928-9bb0-7be8bbc0db38', 'Curl boca arriba acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el bíceps y el antebrazo en posición tumbada, evitando balanceos y controlando el recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0350'),
('cb69da1f-d3cd-500c-8123-90e87dade9d4', 'Extensión de tríceps acostado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo.', 'Baja las mancuernas hacia la frente, flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps tumbado, ganando fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0351'),
('8066d6a2-f05c-54f5-a9d7-dddb65374712', 'Extensión de tríceps tumbado con mancuernas', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna con ambas manos sobre el pecho.', 'Lleva los brazos hacia arriba extendidos y baja la mancuerna hacia la frente doblando solo los codos.', 'Mantén los codos apuntando al techo y pegados, sin abrirlos hacia los lados.', 'Sube controlando el movimiento y exhala al extender los brazos.', 'Evita arquear la zona lumbar: mantén las costillas abajo y el core activo.']::text[], 'intermedio', 'Aísla el tríceps para ganar fuerza y volumen en la parte posterior del brazo, con apoyo en el suelo que protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2738'),
('ee6b35f5-5e2e-5c49-8905-dec38d88cad8', 'Curl abierto tumbado con mancuernas', ARRAY['Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps con un agarre amplio que incide en la porción corta y mejora el control del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1662'),
('0f105d76-b6bd-551c-b55b-beee2b4b3013', 'Remo tumbado con agarre abierto en rack con mancuernas', ARRAY['Colócate tumbado boca abajo sobre un banco o rack con una mancuerna en cada mano y los brazos colgando.', 'Agarra las mancuernas con las palmas hacia delante y una separación amplia.', 'Tira de los codos hacia atrás y arriba juntando las escápulas, sin encoger el cuello.', 'Baja las mancuernas controlando el movimiento hasta estirar los brazos.', 'Evita usar impulso del tronco: el movimiento nace de la espalda, no de la cadera.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con un tirón horizontal que mejora la postura y la estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4426'),
('5e035c3d-f345-5f14-ae85-3f1a1b905fc5', 'Leñador tumbado con mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna con ambas manos junto a una cadera.', 'Sube la mancuerna en diagonal hacia el hombro contrario manteniendo los brazos casi extendidos.', 'Gira el tronco desde el abdomen, no desde los hombros, y exhala al subir.', 'Baja controlando hasta la cadera de inicio sin dejar caer el peso de golpe.', 'Evita despegar la zona lumbar del suelo durante todo el recorrido.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con un patrón de rotación que mejora la estabilidad del core y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4747'),
('d97cd3a4-92d6-5bc3-ae84-4952b63e6bae', 'Press militar con giro ruso y piernas en el aire con mancuernas', ARRAY['Siéntate con las rodillas flexionadas y las piernas levantadas del suelo, sujetando una mancuerna a la altura del pecho.', 'Empuja la mancuerna por encima de la cabeza extendiendo los brazos sin arquear la espalda.', 'Baja la mancuerna al pecho y gira el tronco hacia un lado y otro con control.', 'Mantén el pecho alto y el abdomen apretado durante todo el ejercicio.', 'Evita balancear el tronco o dejar caer las piernas: si pierdes la postura, apóyalas.']::text[], 'intermedio', 'Combina empuje de hombros y rotación de core para trabajar abdomen, oblicuos y estabilidad con piernas elevadas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6806'),
('9035adc5-8855-5036-9079-9f500cfe1195', 'Zancada con sentadilla estrecha con mancuernas', ARRAY['De pie con los pies juntos y una mancuerna en cada mano a los lados del cuerpo.', 'Da un paso al frente y baja flexionando ambas rodillas hasta que la trasera casi toque el suelo.', 'Mantén la rodilla delantera alineada con el pie y el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial y alterna el lado.', 'Evita que la rodilla delantera se vaya hacia dentro: contrólala durante todo el descenso.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y aductores con un patrón de piernas estrecho que exige control y equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10055'),
('9bee76c0-f357-50e7-a336-575169f418d5', 'Sentadilla con postura estrecha y mancuernas', ARRAY['De pie con los pies juntos o muy cerca y una mancuerna en cada mano a los lados.', 'Baja la cadera hacia atrás y abajo manteniendo el pecho alto y la espalda recta.', 'Desciende hasta donde controles sin que los talones se levanten del suelo.', 'Empuja con los pies para subir y exhala al final del recorrido.', 'Evita juntar las rodillas hacia dentro: mantenlas alineadas con los pies.']::text[], 'intermedio', 'Enfoca el cuádriceps y los aductores con una base estrecha que aumenta la profundidad y el control del descenso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5634'),
('242eabfd-0d88-59ad-9c85-7a13aa1c98b1', 'Press de banca con agarre neutro y mancuernas', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sostén una mancuerna en cada mano con agarre neutro (palmas enfrentadas entre sí) y los brazos extendidos rectos hacia arriba sobre el pecho.', 'Baja lentamente las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece tríceps y pecho con un agarre neutro que reduce la tensión en el hombro y mejora el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0352'),
('01f58754-08e4-574d-b761-4ab08378e2b1', 'Remo a una mano con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Deja que la mancuerna cuelgue recta hacia el suelo, con el brazo completamente extendido.', 'Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja la espalda alta y el bíceps de forma unilateral, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0292'),
('13788ed1-e790-5807-868d-353424cafb90', 'Apertura de pecho a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.', 'Camina con los pies hacia adelante, haciendo rodar el balón hasta que la parte superior de la espalda quede apoyada en el balón y la cabeza, el cuello y los hombros queden fuera de él.', 'Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.', 'Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.', 'Haz una pausa por un momento cuando el brazo esté paralelo al suelo.', 'Activa los músculos del pecho para llevar la mancuerna de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el pectoral con un rango amplio sobre balón, sumando trabajo de estabilidad y control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1286'),
('5c89bf42-8533-5610-acc5-63a43ac8499f', 'Curl concentrado a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo.', 'Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo y repite.']::text[], 'intermedio', 'Aísla el bíceps con apoyo en balón, aumentando la concentración muscular y el control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0353'),
('589671ca-9236-59cf-9462-a442bf45ff1b', 'Press de pecho declinado a un brazo con mancuerna', ARRAY['Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.', 'Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco.', 'Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja el pectoral inferior y el tríceps con un empuje unilateral que exige estabilidad y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1287'),
('bed74d23-1bfa-5d43-bcd3-ff89e7984b05', 'Apertura a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en una mano y los pies apoyados en el suelo.', 'Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la parte superior de la espalda quede apoyada sobre el balón de estabilidad.', 'Extiende el brazo con la mancuerna recto hacia arriba sobre el pecho, con la palma hacia adentro.', 'Baja lentamente la mancuerna hacia el lado, manteniendo una ligera flexión en el codo.', 'Haz una pausa por un momento, luego contrae los músculos del pecho para llevar la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el pectoral con un movimiento de apertura unilateral sobre balón, mejorando el control y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1288'),
('8994f7ea-281a-506a-a0fa-62e1094a34c2', 'Press francés a un brazo en balón de estabilidad', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados.', 'Extiende el brazo recto hacia el techo, manteniendo el codo quieto.', 'Baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps con extensión unilateral sobre balón, sumando demanda de estabilidad al trabajo del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1736'),
('e35b05aa-0074-52d4-be5d-646b9adc5bc6', 'Press martillo a un brazo en balón de estabilidad', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.', 'Coloca la otra mano en la cadera para mantener el equilibrio.', 'Empuja la mancuerna hacia arriba, extendiendo completamente el brazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Fortalece tríceps y hombro con un empuje unilateral sobre balón que exige control y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1621'),
('742af4ed-3951-5f67-a127-87489b93b70c', 'Press inclinado a un brazo con mancuerna', ARRAY['Ajusta el banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.', 'Sostén una mancuerna en una mano con agarre prono, apoyándola sobre el hombro.', 'Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja la parte superior del pecho con apoyo unilateral, mejorando fuerza y control de cada lado por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1289'),
('188490ca-1223-546c-b618-21365ef3c1ee', 'Elevación lateral a un brazo con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.', 'Mantén la espalda recta y el core activado durante todo el ejercicio.', 'Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.', 'Continúa levantando hasta que el brazo quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Aísla el deltoides medio para ganar amplitud y forma del hombro, con trabajo unilateral que corrige desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0355'),
('587ac8f8-92c7-52df-b98c-32a73ecc8511', 'Elevación lateral a un brazo con apoyo y mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo.', 'Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte.', 'Mantén la espalda recta y activa el core.', 'Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.', 'Continúa levantando hasta que el brazo quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece el deltoides medio con apoyo para estabilizar el tronco y concentrarte en la elevación del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0356'),
('5ef4c13a-c824-52fc-bb48-8c1ba0ae8909', 'Apertura baja a un brazo con mancuerna', ARRAY['Túmbate en un banco con una mancuerna en la mano y el brazo extendido sobre el pecho.', 'Abre el brazo hacia el lado con el codo ligeramente flexionado hasta notar estiramiento en el pecho.', 'Junta de nuevo la mancuerna sobre el pecho controlando el movimiento y sin bloquear el codo.', 'Inspira al bajar y espira al subir, manteniendo el hombro estable y sin arquear la espalda.']::text[], 'intermedio', 'Trabaja el pecho desde un ángulo bajo, incidiendo en la porción superior y mejorando el control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4150'),
('09262fa8-3534-55e8-9b7b-faffc33c36eb', 'Zancada a un brazo con mancuerna', ARRAY['Colócate de pie con una mancuerna en una mano y el tronco erguido.', 'Da un paso largo hacia delante y baja la rodilla trasera hacia el suelo con control.', 'Empuja con el pie delantero para volver a la posición inicial sin perder el equilibrio.', 'Mantén el core activo y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con carga unilateral, mejorando equilibrio y estabilidad del core al avanzar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3339'),
('5b40ef98-c4cd-5ba2-82ea-805c66237321', 'Press a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate en el balón y apoya la espalda alta, con los pies firmes en el suelo.', 'Sujeta la mancuerna a la altura del pecho con el codo flexionado.', 'Empuja la mancuerna hacia arriba hasta extender el brazo sin bloquear el codo.', 'Baja controlando el movimiento y evita que el balón ruede o la cadera caiga.']::text[], 'intermedio', 'Trabaja el pecho con inestabilidad, activando el core y los estabilizadores del hombro en cada repetición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0357'),
('dad2147a-5ef9-5c1d-886b-ce83f895c060', 'Curl boca abajo a un brazo con mancuerna', ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo.', 'Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo.', 'Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps desde una posición inclinada que elimina impulso y aumenta la tensión en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1665'),
('ed7558ef-97e4-50c8-8327-82e960ca2d11', 'Curl martillo boca abajo a un brazo con mancuerna', ARRAY['Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido.', 'Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Trabaja bíceps y antebrazo con agarre neutro en posición inclinada, ganando fuerza y grosor del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1666'),
('6d139e93-d5ca-593d-bfa0-5035d22adf89', 'Pullover a un brazo con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho.', 'Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'avanzado', 'Estira y fortalece pecho y dorsal sobre el balón, mejorando movilidad del hombro y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1291'),
('a50253ab-1799-5b6e-ad12-2342a74ef80a', 'Apertura invertida a un brazo con apoyo y mancuerna', ARRAY['Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con la palma hacia adentro.', 'Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte.', 'Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Refuerza la parte posterior del hombro y la espalda alta, equilibrando el trabajo del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0359'),
('cf2fea87-d2f7-5bb5-ba87-213181b97167', 'Press a un brazo con agarre inverso y mancuerna', ARRAY['Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo.', 'Coloca los pies planos sobre el suelo y mantén la espalda recta.', 'Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo.', 'Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja el pecho con agarre supino, incidiendo en la porción superior y en la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1622'),
('0e557045-d09f-5656-a1fe-c678140a3eba', 'Curl araña inverso a un brazo con mancuerna', ARRAY['Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido.', 'Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo con agarre prono, mejorando fuerza y control en la flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1667'),
('6a9172bb-ab8a-5992-b443-49dc55fd9bbd', 'Curl de muñeca inverso a un brazo con mancuerna', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo.', 'Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo.', 'Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde.', 'Baja lentamente la mancuerna hacia el suelo flexionando la muñeca.', 'Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Fortalece los extensores de la muñeca y el antebrazo, previniendo molestias y mejorando el agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0358'),
('4d63b3fe-cfe8-5927-b187-ee70ffdfe134', 'Remo a un brazo con mancuerna en rack', ARRAY['Apoya una mano en el rack y lleva el tronco hacia delante con la espalda recta.', 'Sujeta la mancuerna con el brazo colgando y el codo extendido.', 'Tira de la mancuerna hacia la cadera llevando el codo atrás y pegado al cuerpo.', 'Baja controlando el movimiento sin dejar caer el hombro ni redondear la espalda.']::text[], 'intermedio', 'Trabaja dorsal y espalda alta con apoyo en el rack, mejorando fuerza y control unilateral del tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1236'),
('a450d9e6-1d02-56f2-b8ee-64a8847652d6', 'Curl de bíceps sentado a un brazo en balón de estabilidad con mancuerna', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.', 'Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aisla el bíceps y el antebrazo trabajando un brazo a la vez sobre superficie inestable, lo que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1668'),
('a4d136c5-b382-5295-8d32-c0f66774a6b7', 'Curl martillo sentado a un brazo con mancuerna', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí).', 'Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Fortalece bíceps y braquial con agarre neutro, mejorando la fuerza del antebrazo y el grosor del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1669'),
('7397c357-8d55-5052-9fba-d1b3088e4356', 'Curl de muñeca neutro sentado a un brazo con mancuerna', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.', 'Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde.', 'Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia a la otra mano.']::text[], 'intermedio', 'Trabaja los flexores del antebrazo con agarre neutro, útil para mejorar la fuerza de prensión y la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1415'),
('2438dc4d-2514-5be9-99f2-ebea8b4cfb2c', 'Press de hombros a un brazo con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano a la altura del hombro, con la palma hacia adelante.', 'Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Desarrolla el deltoides y el tríceps empujando por encima de la cabeza, con trabajo extra de estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0361'),
('05e2c26c-b5a6-54de-b2bc-0f3a11230a3e', 'Press de banca de lado a un brazo con mancuerna', ARRAY['Túmbate de lado en el banco con la mancuerna a la altura del pecho y el codo flexionado.', 'Empuja la mancuerna hacia arriba hasta extender el brazo sin bloquear el codo.', 'Baja controlando el movimiento hasta notar estiramiento en el pecho.', 'Mantén el core activo y el torso estable durante todo el recorrido.', 'Evita arquear la espalda o dejar caer la mancuerna rápido al bajar.']::text[], 'intermedio', 'Trabaja el pectoral de forma unilateral tumbado de lado, con implicación de tríceps, hombro y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5816'),
('b029cc81-e27e-5ab7-a61f-c8fdd7334863', 'Arrancada a un brazo con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo.', 'Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta.', 'Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo.', 'Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas.', 'Baja la mancuerna de nuevo a la posición inicial de manera controlada.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que activa glúteos, isquios y cuádriceps, mejorando potencia y coordinación.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '3888'),
('70c2a980-e27e-50ab-82e7-8db1221d5644', 'Thruster a un brazo con mancuerna', ARRAY['Coloca la mancuerna a la altura del hombro con el codo flexionado.', 'Baja en sentadilla manteniendo el pecho alto y los talones apoyados.', 'Sube con impulso de piernas y empuja la mancuerna por encima de la cabeza.', 'Baja la mancuerna al hombro mientras desciendes de nuevo en sentadilla.', 'Evita redondear la espalda o perder el control del peso al empujar.']::text[], 'intermedio', 'Combina sentadilla y press para trabajar piernas, hombros y core en un gesto global de alta demanda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4540'),
('9ca1afd5-56fe-5432-b408-a71be5f4d12a', 'Extensión de tríceps a un brazo con mancuerna', ARRAY['Sujeta la mancuerna con una mano y lleva el brazo por encima de la cabeza.', 'Mantén el codo apuntando al frente y el brazo superior quieto.', 'Extiende el codo hasta estirar el brazo sin bloquearlo con fuerza.', 'Baja la mancuerna controlando hasta flexionar el codo de nuevo.', 'Evita abrir el codo hacia fuera o mover el hombro durante el recorrido.']::text[], 'intermedio', 'Aísla el tríceps extendiendo el codo con una mancuerna, ayudando a tonificar y dar forma a la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4343'),
('a56a32e3-8250-546b-a271-98bede74f26a', 'Extensión de tríceps a un brazo en balón de estabilidad con mancuerna', ARRAY['Siéntate o túmbate sobre el balón con la mancuerna en una mano.', 'Lleva el brazo por encima de la cabeza con el codo flexionado.', 'Extiende el codo hasta estirar el brazo manteniendo el hombro estable.', 'Baja controlando el movimiento sin perder el equilibrio sobre el balón.', 'Evita arquear la espalda o dejar que el codo se abra hacia fuera.']::text[], 'intermedio', 'Trabaja el tríceps de forma unilateral sobre superficie inestable, sumando demanda de estabilidad al core y al hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4054'),
('5010b8e8-5b98-5924-8714-d279b80e41b2', 'Curl de muñeca a un brazo con mancuerna', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo.', 'Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo.', 'Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos.', 'Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.', 'Repite el número de repeticiones deseado, luego cambia a la otra mano.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y la muñeca, mejorando el agarre y la resistencia en tareas de fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0364'),
('1a294901-6440-5812-ac2d-acc179e616e0', 'Elevación en Y a un brazo con mancuerna', ARRAY['Colócate con el torso inclinado o tumbado boca abajo con la mancuerna en una mano.', 'Lleva el brazo hacia arriba y afuera formando una Y con el cuerpo.', 'Sube hasta la altura del hombro sin encoger el cuello.', 'Baja lentamente controlando el movimiento.', 'Evita usar impulso o elevar el hombro hacia la oreja.']::text[], 'intermedio', 'Activa el deltoides y la musculatura estabilizadora del hombro, mejorando control escapular y postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5002'),
('033012e8-274b-5d75-8d15-a7c80b543e4f', 'Curl predicador Zottman a un brazo con mancuerna', ARRAY['Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino.', 'Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente.', 'Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.', 'En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba.', 'Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Combina curl con agarre supino y prono para trabajar bíceps y antebrazo, mejorando fuerza y control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1672'),
('228d3a46-8d79-5129-9dc4-eb090dcd95d1', 'Apertura a una pierna con mancuerna en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.', 'Coloca un pie en el suelo y extiende la otra pierna recta hacia adelante.', 'Inclínate ligeramente hacia adelante y lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.', 'Baja lentamente las mancuernas hacia abajo y hacia los lados, sintiendo un estiramiento en el pecho.', 'Haz una pausa por un momento en la parte inferior, luego contrae los músculos del pecho para llevar las mancuernas de nuevo hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Trabaja el pectoral con apertura unilateral sobre balón, sumando inestabilidad y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1292'),
('f5eb82d9-3fa6-5b64-9c07-6b17af872c5f', 'Sentadilla a una pierna con mancuerna', ARRAY['Sujeta la mancuerna y apoya un pie en el suelo con la otra pierna ligeramente elevada.', 'Baja flexionando la rodilla de apoyo manteniendo el pecho alto.', 'Desciende hasta donde controles sin perder el equilibrio.', 'Empuja con el talón para subir extendiendo la pierna.', 'Evita que la rodilla se vaya hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core de forma unilateral, mejorando equilibrio y estabilidad de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0882'),
('cae4e76f-44a9-528a-8bd8-3acf4afae043', 'Curl de muñeca neutro sobre banco con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.', 'Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.', 'Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja bíceps y antebrazo con agarre neutro apoyado en banco, aislando la flexión de muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0365'),
('d2eeff1b-38a6-5d5b-95d6-b32bb5c699f9', 'Curl de muñeca neutro a un brazo sobre banco con mancuerna', ARRAY['Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba.', 'Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Fortalece el bíceps y los antebrazos con el agarre neutro, mejorando la fuerza de prensión y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0366'),
('c6a5bbc9-4247-5764-8b1a-65545e313275', 'Curl de muñeca inverso a un brazo sobre banco con mancuerna', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.', 'Apoya el antebrazo en el banco con la muñeca colgando del borde.', 'Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja los extensores del antebrazo y el braquial, equilibrando la musculatura del brazo y previniendo molestias en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1441'),
('3ace15c8-24b9-59d6-aae4-02018f7a70e0', 'Curl de muñeca a un brazo sobre banco con mancuerna', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.', 'Apoya el antebrazo en el banco con la muñeca colgando del borde.', 'Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Aísla los flexores del antebrazo para ganar fuerza de agarre y resistencia, útil en remos, dominadas y peso muerto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0367'),
('801a7875-2010-54bf-93c0-ac544e65b084', 'Curl de muñeca inverso sobre banco con esterilla y mancuerna', ARRAY['Apoya el antebrazo sobre el banco con la muñeca fuera del borde y sujeta la mancuerna con agarre prono.', 'Sube la muñeca extendiendo la mano hacia arriba sin mover el antebrazo del banco.', 'Baja despacio controlando el movimiento hasta notar estiramiento en el antebrazo.', 'Mantén el codo fijo y evita balancear el brazo o usar impulso del hombro.', 'Respira soltando el aire al subir y cogiéndolo al bajar.']::text[], 'intermedio', 'Refuerza los extensores de la muñeca y el agarre, ayudando a prevenir lesiones en el codo y mejorar el rendimiento en tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4908'),
('6a340493-f5fb-550e-9367-2cfd9c19fa5e', 'Curl de muñeca sobre banco con mancuernas', ARRAY['Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano.', 'Deja que tus muñecas cuelguen del borde del banco.', 'Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.', 'Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y el agarre, mejorando la sujeción en ejercicios de tracción y la salud de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0369'),
('6b42ab5a-1401-5390-a53b-d37088d9d17d', 'Abducción acostado con mancuerna sobre el pecho', ARRAY['Túmbate de lado con las rodillas flexionadas y la mancuerna apoyada sobre el pecho con una mano.', 'Eleva la rodilla de arriba abriendo la cadera sin mover la pelvis ni el tronco.', 'Baja la rodilla despacio hasta juntarla con la de abajo sin dejar caer el peso.', 'Mantén el abdomen firme y evita girar la cadera hacia atrás para compensar.', 'Respira soltando el aire al abrir la cadera y cogiéndolo al cerrar.']::text[], 'intermedio', 'Activa los abductores y glúteos desde el suelo, mejorando la estabilidad de la cadera y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11077'),
('f8a1d1a3-5f45-590f-969e-89d8915e2859', 'Acarreo sobre la cabeza con mancuerna', ARRAY['Sujeta la mancuerna con una mano y llévala por encima de la cabeza con el brazo extendido.', 'Activa el abdomen y camina con pasos cortos manteniendo el tronco erguido.', 'Mantén el hombro activo y el brazo cerca de la oreja sin arquear la espalda.', 'Evita inclinarte hacia el lado contrario; compensa con el core, no con la lumbar.', 'Respira de forma constante y baja la mancuerna con control al terminar.']::text[], 'intermedio', 'Refuerza hombros, core y espalda alta mientras caminas, mejorando la estabilidad del tren superior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2913'),
('fe900da9-f963-53b3-8867-b17ab97e8c51', 'Zancada sobre la cabeza con mancuernas', ARRAY['Coloca las mancuernas por encima de la cabeza con los brazos extendidos y los pies juntos.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo manteniendo el tronco recto.', 'Empuja con la pierna delantera para volver a la posición inicial con control.', 'Mantén los brazos firmes sobre la cabeza y evita que la espalda se arquee.', 'Respira soltando el aire al bajar y cogiéndolo al subir.']::text[], 'intermedio', 'Combina fuerza de piernas y estabilidad de hombros y core, mejorando el equilibrio y la coordinación en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5076'),
('f13ec763-6632-50fa-a2f6-75602b1a3c35', 'Zancada lateral con mancuerna sobre la cabeza', ARRAY['Sujeta las mancuernas sobre la cabeza con los brazos extendidos y los pies separados.', 'Da un paso amplio hacia un lado y flexiona esa rodilla llevando la cadera atrás.', 'Mantén la otra pierna estirada y el pie apoyado, sin levantar el talón.', 'Empuja con la pierna flexionada para volver al centro con control.', 'Evita inclinar el tronco hacia el lado; mantén el pecho alto y el core activo.']::text[], 'intermedio', 'Trabaja glúteos, aductores y cuádriceps mientras exige estabilidad de hombros y core en el plano lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1694'),
('ae1fb324-cd27-5016-9fde-db0d0118f2be', 'Abdominal con mancuerna sobre la cabeza y piernas en banco', ARRAY['Túmbate con las piernas apoyadas en el banco y sujeta la mancuerna con ambas manos sobre el pecho.', 'Sube el tronco llevando la mancuerna por encima de la cabeza sin arquear la lumbar.', 'Baja despacio hasta apoyar la espalda controlando el peso en todo momento.', 'Mantén el abdomen activo y evita tirar del cuello o usar impulso de brazos.', 'Respira soltando el aire al subir y cogiéndolo al bajar.']::text[], 'intermedio', 'Fortalece el recto abdominal y los flexores de cadera con carga sobre la cabeza, exigiendo control del core y los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6809'),
('18ce44ca-059c-5f2f-b715-25a6cd54927e', 'Sentadilla sobre la cabeza con mancuernas', ARRAY['Sujeta las mancuernas sobre la cabeza con los brazos extendidos y los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás flexionando rodillas y tobillos manteniendo el pecho alto.', 'Mantén los brazos firmes sobre la cabeza y evita que la espalda se arquee.', 'Empuja con los talones para subir controlando el peso en todo el recorrido.', 'Respira soltando el aire al subir y cogiéndolo al bajar.']::text[], 'intermedio', 'Desarrolla fuerza de piernas y movilidad de hombros, exigiendo un core muy estable para mantener el peso arriba.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3709'),
('7d8215e7-ad8c-543e-96fb-1234e264040b', 'Zancada caminando sobre la cabeza con mancuernas', ARRAY['Coloca las mancuernas sobre la cabeza con los brazos extendidos y los pies juntos.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo con el tronco recto.', 'Empuja con la pierna delantera y avanza con la otra pierna sin parar el movimiento.', 'Mantén los brazos firmes sobre la cabeza y el abdomen activo durante todo el recorrido.', 'Evita arquear la espalda o inclinarte; respira de forma constante.']::text[], 'intermedio', 'Combina fuerza de piernas con estabilidad de hombros y core, mejorando el equilibrio y la resistencia en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4865'),
('62021e95-714b-5742-8550-101906a8bff9', 'Remo inclinado con rotación de palma y mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Deja que los brazos cuelguen rectos hacia abajo, con las palmas hacia tu cuerpo.', 'Activa el core y tira de las mancuernas hacia tu pecho, manteniendo los codos cerca del cuerpo.', 'Mientras subes las mancuernas, gira las palmas para que queden mirando hacia afuera, alejadas de tu cuerpo.', 'Junta los omóplatos en la parte superior del movimiento.', 'Baja lentamente las mancuernas hasta la posición inicial, girando las palmas de vuelta a su posición original.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps con rotación del antebrazo, mejorando el control escapular y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1329'),
('c147d66e-a95e-55f2-b405-a76e275c6fa3', 'Press de banca inclinado con palmas hacia dentro y mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos en el suelo.', 'Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia adentro.', 'Extiende los brazos rectos hacia arriba, por encima del pecho, manteniendo una ligera flexión en los codos.', 'Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo.', 'Haz una pausa por un momento en la posición más baja y luego presiona las mancuernas de vuelta hacia arriba, hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el trabajo en tríceps, pecho y hombros con agarre neutro, reduciendo tensión en el hombro y ganando fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1623'),
('1a5ccce3-9e66-5377-9b4c-2efc49e266a2', 'Elevación lateral parcial con mancuernas', ARRAY['De pie con las mancuernas a los lados y los codos ligeramente flexionados.', 'Eleva los brazos hacia los lados hasta la altura del hombro sin subir más.', 'Haz repeticiones cortas en la parte baja del recorrido manteniendo la tensión.', 'Evita encoger los hombros o usar impulso del tronco para subir el peso.', 'Respira de forma constante y controla la bajada en cada repetición.']::text[], 'intermedio', 'Aísla el deltoides lateral con recorrido corto, útil para ganar volumen y resistencia en el hombro sin cargar el trapecio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4191'),
('141675d3-846c-5e0c-9238-f53fd3741656', 'Curl martillo en banco predicador con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.', 'Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.', 'Esta será tu posición inicial.', 'Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones recomendado.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos con un agarre neutro que reduce la tensión en la muñeca y gana grosor en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0370'),
('a873a380-32bb-5a2a-820c-ce45d312873e', 'Sentadilla pliométrica con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo.', 'Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante.', 'Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies.', 'Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y piernas con un salto explosivo que mejora la potencia y la capacidad de reacción del tren inferior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '0371'),
('2edc5bc1-eff7-5d5c-aab6-4b227e217ded', 'Elevación Powell con mancuerna', ARRAY['Colócate con el torso inclinado y apoya una mano para estabilizarte, con la mancuerna colgando frente a ti.', 'Sube el brazo en arco hacia el lateral, llevando la mancuerna a la altura del hombro.', 'Controla la bajada durante dos segundos sin dejar caer el peso de golpe.', 'Evita encoger el hombro o usar impulso del tronco para subir la mancuerna.']::text[], 'intermedio', 'Activa el deltoides posterior y la espalda alta, mejorando la postura y el equilibrio muscular del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10330'),
('50e7da38-7d94-528e-89e6-e271d89126c8', 'Cargada de potencia con mancuerna', ARRAY['Empieza de pie con la mancuerna entre los pies y el pecho arriba, espalda recta.', 'Baja en bisagra de cadera y agarra la mancuerna con el brazo extendido.', 'Extiende con fuerza caderas y rodillas y encoge los hombros para acelerar la mancuerna.', 'Recibe el peso a la altura del hombro con los codos abajo y las rodillas ligeramente flexionadas.', 'Evita redondear la espalda o tirar con los brazos antes de extender las caderas.']::text[], 'avanzado', 'Movimiento explosivo que recluta glúteos, isquios y espalda para ganar potencia y coordinación en el tren inferior.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4889'),
('ed11f858-82b8-526b-9348-e8c1c2dcc69c', 'Cargada de potencia y envión con mancuernas', ARRAY['Colócate de pie con las mancuernas a los lados y el core activado.', 'Baja en bisagra de cadera y extiende con fuerza para llevar las mancuernas al hombro.', 'Flexiona ligeramente las rodillas y empuja las mancuernas por encima de la cabeza.', 'Bloquea los codos arriba con el core firme y baja el peso de forma controlada.', 'Evita arquear la zona lumbar al recibir o al empujar el peso por encima de la cabeza.']::text[], 'avanzado', 'Ejercicio explosivo completo que desarrolla potencia de piernas, hombros y core en un solo movimiento coordinado.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4439'),
('0994458f-ec36-5a9e-bdfb-0ef85c03b446', 'Curl predicador con mancuernas', ARRAY['Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella.', 'Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con el brazo apoyado, lo que reduce el impulso y aumenta la tensión en el músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0372'),
('5d69ab71-1456-579b-9d9f-baefb19f4637', 'Curl predicador con torso girado y mancuerna', ARRAY['Siéntate en el banco predicador con el brazo apoyado y el torso ligeramente girado.', 'Sube la mancuerna flexionando el codo sin mover el hombro ni el tronco.', 'Aprieta el bíceps arriba un segundo y baja despacio hasta extender casi del todo.', 'Evita girar más el torso o balancearte para completar la repetición.']::text[], 'intermedio', 'Trabaja el bíceps y el braquial desde un ángulo girado que cambia la tensión y mejora el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5298'),
('77cb860f-1d51-5ca6-9f4f-34fd7529453a', 'Curl predicador sobre balón de estabilidad con mancuernas', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad.', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.', 'Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps sobre una superficie inestable, añadiendo trabajo de core y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1673'),
('e97831e0-94fb-5957-b33c-1e515c3bed0d', 'Curl predicador con balanceo y mancuernas', ARRAY['Colócate con el brazo apoyado y la mancuerna sujeta con agarre neutro.', 'Sube la mancuerna flexionando el codo y acompaña con un ligero balanceo del tronco.', 'Controla el retorno sin dejar que el peso caiga y mantén el hombro estable.', 'Evita usar demasiado impulso o perder la posición del brazo apoyado.']::text[], 'intermedio', 'Combina curl y balanceo para trabajar bíceps, braquial y hombros con un componente de control dinámico.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8613'),
('9f4a6931-7e1d-5b35-a5d1-aa67762eb7fe', 'Press con mancuernas en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.', 'Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados.', 'Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.', 'Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece pecho, hombros y tríceps mientras el core estabiliza el cuerpo sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1293'),
('e71fa5fc-4077-5da0-ba0c-2f4e33eb504c', 'Press y sentadilla con mancuernas', ARRAY['De pie con las mancuernas a la altura de los hombros y los pies a la anchura de las caderas.', 'Baja en sentadilla manteniendo el pecho arriba y las rodillas alineadas con los pies.', 'Al subir, empuja las mancuernas por encima de la cabeza hasta bloquear los codos.', 'Baja el peso al hombro y repite con control, evitando arquear la espalda.']::text[], 'intermedio', 'Ejercicio global que combina sentadilla y press para trabajar piernas, hombros y core en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3707'),
('45d1386d-302b-5366-ba04-75303d9e42e6', 'Extensión de tríceps con agarre prono y mancuernas', ARRAY['Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.', 'Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza.', 'Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con un agarre prono que enfatiza la cabeza lateral y mejora la definición del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0373'),
('efb83d4e-665e-5272-9c4a-39b2b7b6a808', 'Remo con mancuernas y agarre prono', ARRAY['Inclina el torso con la espalda recta y apoya una mano para estabilizarte.', 'Tira de la mancuerna hacia la cadera con el codo pegado al cuerpo.', 'Aprieta la escápula arriba y baja el peso de forma controlada.', 'Evita redondear la espalda o tirar con impulso del tronco.']::text[], 'intermedio', 'Fortalece dorsales y espalda alta con un agarre prono que activa más el deltoides posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2326'),
('ee678e52-0ff6-575e-8a22-6af08447aa60', 'Remo con mancuernas de agarre prono a neutro', ARRAY['Colócate inclinado con la espalda recta y la mancuerna colgando con agarre prono.', 'Tira del peso hacia la cadera girando la muñeca a agarre neutro al subir.', 'Aprieta la escápula y baja controlando el retorno al agarre inicial.', 'Evita balancear el tronco o perder la posición neutra de la columna.']::text[], 'intermedio', 'Trabaja dorsales y espalda alta cambiando el agarre durante el recorrido para mayor activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2325'),
('85d97b0a-a5cc-5de4-9591-b7d0e795d38f', 'Curl martillo alternado boca abajo con mancuernas', ARRAY['Túmbate boca abajo en un banco con los brazos colgando y las mancuernas en agarre neutro.', 'Flexiona un codo llevando la mancuerna hacia el hombro sin mover el brazo.', 'Baja despacio y alterna con el otro brazo manteniendo el core activo.', 'Evita levantar el pecho del banco o usar impulso para completar la repetición.']::text[], 'intermedio', 'Refuerza antebrazos y braquial desde una posición tumbado que limita el impulso y mejora el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6264'),
('8aa59de8-9359-5135-9e34-ada83eca5392', 'Elevación full can boca abajo con mancuernas', ARRAY['Túmbate boca abajo en un banco inclinado con una mancuerna en cada mano y los brazos colgando.', 'Sube los brazos hacia los lados con los codos ligeramente flexionados y los pulgares hacia arriba.', 'Aprieta los omóplatos arriba y baja controlando el movimiento sin dejar caer el peso.', 'Evita encoger los hombros hacia las orejas y mantén el cuello relajado.']::text[], 'intermedio', 'Trabaja el deltoides posterior y el manguito rotador para mejorar la estabilidad y salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5820'),
('c8333d63-c621-5cea-b23d-2eb7e6bbbccd', 'Curl inclinado boca abajo con mancuernas', ARRAY['Ajusta el banco a una inclinación de 45 grados.', 'Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.', 'Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps desde un ángulo estirado para ganar fuerza y volumen en la parte frontal del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0374'),
('31593ea1-d574-5781-98ca-03e7eccfe584', 'Curl martillo inclinado boca abajo con mancuernas', ARRAY['Ajusta el banco a una inclinación de 45 grados.', 'Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí.', 'Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece bíceps y antebrazo con agarre neutro, mejorando la fuerza de prensión y el grosor del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1674'),
('cd8ddf8d-0439-5562-ae1f-88cc1787a201', 'Balanceo posterior para deltoide posterior boca abajo con mancuernas', ARRAY['Túmbate boca abajo en un banco inclinado con una mancuerna en cada mano.', 'Balancea los brazos hacia atrás y hacia los lados con un movimiento controlado.', 'Aprieta la espalda alta al final y frena el retorno para no perder tensión.', 'Evita usar impulso de la cadera y mantén el torso pegado al banco.']::text[], 'intermedio', 'Activa el deltoides posterior y la espalda alta con un movimiento dinámico que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5606'),
('a7718f96-9764-586b-bee0-e6350b4936ad', 'Elevación en W boca abajo con mancuernas', ARRAY['Túmbate boca abajo en un banco inclinado con una mancuerna en cada mano.', 'Flexiona los codos formando una W y sube los brazos apretando los omóplatos.', 'Mantén los pulgares hacia arriba y baja despacio sin perder la posición.', 'Evita arquear la zona lumbar y no encorves los hombros.']::text[], 'intermedio', 'Refuerza el deltoides posterior, romboides y manguito rotador para estabilizar el hombro y corregir la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7747'),
('58438aff-11d1-5e50-bf5b-9b26a39cf0df', 'Pullover con mancuerna', ARRAY['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.', 'Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira y trabaja el pectoral y el dorsal, ampliando la movilidad del hombro y la caja torácica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0375'),
('9b222f05-7d46-5ec5-b58f-c692b56a65aa', 'Pullover con extensión de cadera en balón', ARRAY['Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos.', 'Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.', 'Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.', 'Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core.', 'Baja las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina pectoral y extensión de cadera para trabajar el core y la estabilidad sobre superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1294'),
('de3f8d55-cfc5-5ace-8c20-c5f4d130f3f5', 'Pullover con mancuerna en balón', ARRAY['Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos.', 'Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectoral y dorsal con mayor rango y demanda de estabilidad sobre el balón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1295'),
('71aada65-f0a1-5160-8992-a8d8566a8159', 'Pullover con mancuerna en el suelo', ARRAY['Túmbate en el suelo con las rodillas flexionadas y sujeta una mancuerna con ambas manos sobre el pecho.', 'Lleva la mancuerna hacia atrás por encima de la cabeza hasta donde llegues sin dolor.', 'Vuelve a la posición inicial apretando el dorsal y manteniendo las costillas abajo.', 'Evita arquear la lumbar y no fuerces el hombro más allá de tu movilidad.']::text[], 'intermedio', 'Trabaja dorsal y pectoral con apoyo seguro en el suelo, ideal para controlar el rango del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4318'),
('4e57fb8a-852b-536a-a7bb-cb7440233244', 'Pullover a press en puente con mancuerna', ARRAY['Túmbate boca arriba con los pies apoyados y eleva la cadera en puente.', 'Sujeta la mancuerna sobre el pecho y llévala atrás en pullover controlado.', 'Devuélvela al pecho y empuja en press manteniendo el puente activo.', 'Aprieta el glúteo durante todo el movimiento y evita que la cadera caiga.']::text[], 'intermedio', 'Combina glúteo, pectoral y core en un movimiento global que mejora fuerza y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10186'),
('26df9ba9-8850-58a0-93d0-16600465f8c0', 'Empuje y envión con mancuernas', ARRAY['Sujeta las mancuernas a la altura de los hombros con los codos hacia delante.', 'Flexiona ligeramente las rodillas y empuja el suelo para lanzar las mancuernas arriba.', 'Recibe el peso con los brazos extendidos y las rodillas algo flexionadas.', 'Baja las mancuernas con control y evita bloquear la espalda arqueándola.']::text[], 'avanzado', 'Ejercicio explosivo de hombro y piernas que desarrolla potencia y coordinación en todo el cuerpo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4389'),
('33e78588-3061-5cf6-ae5f-6bd62dc0dc31', 'Flexión con elevación frontal y mancuernas', ARRAY['Coloca las manos con mancuernas en el suelo y adopta la posición de flexión.', 'Baja el pecho con el cuerpo alineado y empuja para subir.', 'Al extender los brazos, eleva una mancuerna al frente y vuelve a apoyarla.', 'Alterna lados sin girar la cadera y mantén el abdomen firme.']::text[], 'intermedio', 'Combina pectoral, tríceps y hombro en un ejercicio global que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3993'),
('754ba30f-9e8a-572d-a2f9-93ff45f1e870', 'Elevación con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Mantén la espalda recta y activa el core.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el deltoides y los trapecios para ganar fuerza y estabilidad en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0376'),
('464eef34-877c-5b7b-b4ff-b6a04295b6da', 'Peso muerto rumano y remo inclinado con mancuernas', ARRAY['De pie con mancuernas, flexiona la cadera llevando el peso hacia abajo con la espalda recta.', 'Sube apretando el glúteo hasta quedar erguido.', 'Con el torso inclinado, rema las mancuernas hacia el abdomen y baja controlado.', 'Evita redondear la espalda y no uses impulso de la cadera en el remo.']::text[], 'intermedio', 'Encadena isquios, glúteo y espalda en un ejercicio completo de cadena posterior y tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4749'),
('bcdfaca4-6c63-5ac8-8df5-c3947a189274', 'Marcha de la muerte con peso muerto rumano y mancuernas', ARRAY['De pie con mancuernas, inclina el torso y eleva una rodilla al frente.', 'Mantén la espalda recta y las mancuernas cerca de las piernas.', 'Baja el pie con control y alterna el lado sin perder la posición.', 'Evita arquear la lumbar y no bloquees la rodilla de apoyo.']::text[], 'intermedio', 'Trabaja isquios, glúteo y core con control unilateral, mejorando equilibrio y estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3651'),
('c7104501-c305-5572-bd16-35cdba4e67f2', 'Estiramiento de peso muerto rumano con mancuernas', ARRAY['Sujeta una mancuerna con ambas manos frente a los muslos y coloca los pies a la anchura de las caderas.', 'Con las rodillas ligeramente flexionadas, empuja la cadera hacia atrás y baja la mancuerna por delante de las piernas.', 'Detente cuando notes tensión en los isquiotibiales, sin redondear la espalda.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita curvar la zona lumbar; si aparece dolor, reduce el rango.']::text[], 'intermedio', 'Estira isométricamente los isquiotibiales y glúteos, mejorando la flexibilidad posterior y la movilidad de la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1445'),
('3459ff54-b956-5f4c-b272-23af0382b446', 'Peso muerto rumano a encogimiento con salto y mancuernas', ARRAY['Con una mancuerna en cada mano, separa los pies a la anchura de las caderas y flexiona ligeramente las rodillas.', 'Baja las mancuernas con la cadera hacia atrás manteniendo la espalda recta hasta media espinilla.', 'Sube extendiendo la cadera y, al llegar arriba, encoge los hombros con un salto corto y explosivo.', 'Aterriza con las rodillas suaves y absorbe el impacto antes de la siguiente repetición.', 'Evita saltar con la espalda redondeada o aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Combina cadena posterior y potencia de salto para desarrollar glúteos, isquiotibiales y trapecios de forma explosiva.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '4822'),
('aeeec051-8318-5d87-950e-42c5e3ea3343', 'Apertura posterior con mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta una mancuerna en cada mano con las palmas enfrentadas.', 'Con los codos ligeramente flexionados, abre los brazos hacia los lados hasta la altura de los hombros.', 'Controla el descenso durante dos segundos sin dejar caer las mancuernas.', 'Evita encoger los hombros o usar impulso del tronco para subir el peso.']::text[], 'intermedio', 'Aísla el deltoide posterior y la zona alta de la espalda, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2487'),
('548b8c3c-292f-5562-ae2b-35ba66f70276', 'Elevación de deltoide posterior con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el deltoide posterior y los romboides para equilibrar el hombro y estabilizar la escápula.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2292'),
('365b91b2-64df-590c-891d-fe323cff5808', 'Remo para deltoide posterior con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.', 'Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos.', 'Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el deltoide posterior y los trapecios medios, mejorando la retracción escapular y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0377'),
('10043f49-f6b0-5d21-bcbe-1f99a52a9d92', 'Apertura invertida con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí.', 'Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el deltoide posterior y los romboides para compensar el trabajo de pecho y prevenir lesiones de hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0378'),
('a059f4a8-7352-55b7-8c46-7ab4d862b82c', 'Elevación lateral posterior con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoide posterior y los trapecios, mejorando la estabilidad del hombro y la postura erguida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0380'),
('1a77d8b5-9366-58bd-922f-8052a0121772', 'Elevación lateral posterior con apoyo de cabeza y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el deltoide posterior con apoyo cervical, reduciendo tensión en el cuello y mejorando el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0379'),
('e4c1c0f6-86f5-505c-b25c-fff75d84cae4', 'Zancada hacia atrás con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada.', 'Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.', 'Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial.', 'Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.']::text[], 'intermedio', 'Fortalece glúteos, cuádriceps e isquiotibiales con un patrón unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0381'),
('d8afba15-3f45-5370-97e2-6edfd63494e7', 'Zancada trasera desde escalón con mancuernas', ARRAY['Colócate de pie sobre un escalón bajo con una mancuerna en cada mano y los brazos relajados.', 'Da un paso largo hacia atrás y baja la rodilla trasera hacia el suelo con el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial sin perder el equilibrio.', 'Mantén el pie delantero completamente apoyado y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Incrementa la activación del cuádriceps y glúteo con mayor rango de movimiento, mejorando fuerza y equilibrio unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2367'),
('3321ac77-94ec-5b37-bd50-318c831aa6b4', 'Zancada hacia atrás con elevación frontal y mancuernas', ARRAY['De pie con una mancuerna en cada mano a los lados, da un paso atrás y baja la rodilla hacia el suelo.', 'Al volver a la posición inicial, eleva las mancuernas al frente hasta la altura de los hombros.', 'Baja las mancuernas de forma controlada mientras preparas la siguiente zancada.', 'Evita balancear el tronco o usar impulso para subir los brazos.']::text[], 'intermedio', 'Combina trabajo de glúteos y cuádriceps con hombros, mejorando la coordinación y la fuerza global del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4161'),
('29052a3e-59ba-5cda-a61a-ad0f00cb9163', 'Zancada hacia atrás con press de hombros a un brazo y mancuerna', ARRAY['Sujeta una mancuerna a la altura del hombro y da un paso atrás bajando la rodilla hacia el suelo.', 'Al subir, empuja la mancuerna por encima de la cabeza extendiendo el brazo.', 'Baja la mancuerna al hombro mientras preparas la siguiente repetición.', 'Mantén el core firme y evita arquear la zona lumbar al presionar.']::text[], 'intermedio', 'Integra piernas, hombros y core en un ejercicio unilateral que mejora fuerza, equilibrio y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10096'),
('845bcd4d-8ec7-5236-9fc2-9767d224a443', 'Remo renegado con mancuernas', ARRAY['Colócate en plancha alta con una mancuerna en cada mano y los pies más anchos que las caderas.', 'Remo una mancuerna hacia la cadera manteniendo el tronco estable y las caderas niveladas.', 'Baja la mancuerna con control y repite con el otro brazo.', 'Evita rotar la cadera o encoger el hombro al tirar del peso.']::text[], 'intermedio', 'Fortalece dorsal, espalda alta y core en posición de plancha, mejorando la estabilidad y la fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2980'),
('c7ef880f-3ed7-5640-9d88-a05133620251', 'Remo renegado en balón de estabilidad con mancuernas', ARRAY['Apoya las manos con las mancuernas sobre el balón y extiende las piernas en plancha.', 'Remo una mancuerna hacia la cadera manteniendo el balón quieto y el tronco firme.', 'Baja con control y alterna los brazos sin perder la posición.', 'Evita que el balón ruede o que la cadera se hunda durante el movimiento.']::text[], 'intermedio', 'Trabaja core, dorsal y hombros sobre superficie inestable, mejorando el control postural y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8223'),
('0f4cfe74-a708-52b3-8fc2-ee91539df967', 'Remo renegado a sentadilla con mancuernas', ARRAY['En plancha alta con mancuernas, realiza un remo con cada brazo manteniendo el tronco estable.', 'Salta o sube los pies hacia las manos y colócate en cuclillas con las mancuernas.', 'Levántate extendiendo la cadera y vuelve a bajar a la posición de plancha.', 'Evita redondear la espalda al pasar de plancha a sentadilla.']::text[], 'intermedio', 'Combina dorsal, core y piernas en un ejercicio funcional que mejora fuerza global y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4629'),
('276bee79-94e1-50da-bb90-9efe8672263a', 'Caminata de remo renegado con mancuernas', ARRAY['Colócate en plancha alta con una mancuerna en cada mano y los pies algo abiertos.', 'Remo una mancuerna hacia la cadera manteniendo el tronco estable y sin girar la pelvis.', 'Baja la mancuerna con control y repite con el otro brazo.', 'Da un paso corto hacia delante con mano y pie del mismo lado y continúa alternando.', 'Evita balancear las caderas o arquear la zona lumbar durante el movimiento.']::text[], 'intermedio', 'Trabaja abdomen, dorsales y hombros mientras avanzas en plancha, mejorando estabilidad y fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8225'),
('7470e385-5a7b-52e4-ac2b-1b06d42e7ffa', 'Curl de bíceps con agarre inverso y mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos con un agarre que enfatiza el braquial y mejora la fuerza de prensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0382'),
('875a78a9-5d2f-5e1c-80e5-1dfc077749cd', 'Remo inclinado a un brazo con agarre inverso en banco y mancuerna', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Coloca una mancuerna en el suelo junto al banco.', 'Ponte de pie frente al banco con los pies separados a la altura de los hombros.', 'Inclínate desde la cintura y coloca la rodilla izquierda y la mano izquierda sobre el banco para apoyarte.', 'Toma la mancuerna con la mano derecha usando un agarre inverso (con la palma hacia abajo).', 'Mantén la espalda recta y el core activado.', 'Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo.', 'Aprieta los músculos de la espalda en la parte superior del movimiento.', 'Baja la mancuerna de nuevo a la posición inicial de manera controlada.', 'Repite el número de repeticiones deseado.', 'Cambia de lado y repite el ejercicio con el brazo izquierdo.']::text[], 'intermedio', 'Trabaja la espalda alta y el bíceps con un apoyo que aísla el lado y mejora el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1330'),
('db106b04-2f58-5000-aee9-a68f1d6d3d95', 'Remo inclinado a dos brazos con agarre inverso en banco y mancuernas', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con el pecho apoyado en el respaldo y los pies planos en el suelo.', 'Sujeta una mancuerna en cada mano con agarre supino.', 'Inclínate hacia adelante y deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos.', 'Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los antebrazos con un tirón bilateral que mejora la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1331'),
('8cc83172-365c-5603-bfde-6dab0ce97f8e', 'Remo inclinado con agarre inverso y mancuernas', ARRAY['Inclina el tronco hacia delante con la espalda recta y las mancuernas colgando con agarre inverso.', 'Tira de las mancuernas hacia la cadera llevando los codos cerca del cuerpo.', 'Junta las escápulas arriba y baja con control sin perder la curvatura lumbar.', 'Inspira al bajar y espira al tirar, manteniendo el cuello en línea con la columna.', 'Evita redondear la espalda o usar impulso de cadera para subir el peso.']::text[], 'intermedio', 'Activa dorsales y espalda alta con un tirón que también exige bíceps y romboides para estabilizar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2511'),
('4622e502-a498-5698-8ec0-76d9c0af7c9a', 'Remo con agarre inverso y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tu cuerpo.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.', 'Deja que tus brazos cuelguen rectos hacia abajo, completamente extendidos, con una ligera flexión en los codos.', 'Tira de las mancuernas hacia arriba, hacia el pecho, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los antebrazos con un tirón que mejora la postura y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2327'),
('3a1efc15-f14d-5e64-805e-94b9711dc41c', 'Press de banca con agarre inverso y apretando mancuernas', ARRAY['Túmbate en el banco con una mancuerna en cada mano y agarre inverso, palmas hacia ti.', 'Aprieta las mancuernas entre sí y baja hasta la altura del pecho con los codos cerca del cuerpo.', 'Empuja hacia arriba extendiendo los codos sin bloquear de golpe.', 'Mantén los omóplatos retraídos y los pies firmes en el suelo.', 'Evita abrir los codos en exceso o perder la presión entre las mancuernas.']::text[], 'intermedio', 'Enfoca el tríceps y el pecho con un press que exige apretar las mancuernas para mantener el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4836'),
('e2a231ae-d0a9-5b2b-aa42-febc83565682', 'Hiperextensión inversa en banco con mancuerna', ARRAY['Túmbate boca abajo en el banco con el torso apoyado y las piernas colgando.', 'Sujeta la mancuerna entre los pies o con las manos según tu posición y activa el core.', 'Eleva las piernas hasta alinear el cuerpo sin arquear la lumbar en exceso.', 'Baja con control y repite manteniendo el movimiento fluido.', 'Evita usar impulso o hiperextender la espalda al subir.']::text[], 'intermedio', 'Trabaja glúteos e isquios elevando las piernas en el banco, con apoyo lumbar y control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6145'),
('4d59d2ea-d518-5d94-9bbb-7053dfd1f8d3', 'Zancada hacia atrás desde déficit con mancuernas', ARRAY['Colócate de pie sobre una superficie elevada con una mancuerna en cada mano.', 'Da un paso largo hacia atrás y baja la rodilla trasera hacia el suelo con control.', 'Empuja con el pie delantero para volver a la posición inicial.', 'Mantén el tronco erguido y la rodilla delantera alineada con el pie.', 'Evita dar pasos cortos o inclinar el torso hacia delante.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con una zancada que amplía el rango y mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7326'),
('e03512f7-4a5d-5ef8-9f40-e3f4691ea2da', 'Flexión inversa con mancuernas', ARRAY['Sujeta una mancuerna en cada mano y colócate en posición de flexión con agarre firme.', 'Baja el pecho hacia el suelo manteniendo el cuerpo en línea recta.', 'Empuja hacia arriba extendiendo los codos sin bloquear de golpe.', 'Mantén el core activo y evita que la cadera se hunda.', 'No dejes que los codos se abran demasiado hacia los lados.']::text[], 'intermedio', 'Trabaja tríceps y hombros con un empuje invertido que también exige core y control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6151'),
('e4a4af32-8974-54f3-b7eb-e5857651db16', 'Curl de muñeca inverso con mancuernas', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo.', 'Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo.', 'Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.', 'Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza antebrazos y extensores de la muñeca, mejorando la fuerza de agarre y la estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0385'),
('0aacce3e-dcc6-54a2-976b-e9e0ecd754cf', 'Rodillo abdominal con mancuernas', ARRAY['Arrodíllate y sujeta una mancuerna con ambas manos frente a ti.', 'Rueda la mancuerna hacia delante manteniendo el core activo y la espalda neutra.', 'Avanza solo hasta donde puedas controlar sin arquear la lumbar.', 'Vuelve tirando del abdomen y de los brazos con control.', 'Evita dejar caer la cadera o perder la tensión abdominal.']::text[], 'intermedio', 'Trabaja el abdomen y el core con un desplazamiento controlado que también exige hombros y dorsales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6215'),
('38a522e7-0cae-52fa-916a-1b156227aae0', 'Peso muerto rumano con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente.', 'Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos e isquios con un movimiento de bisagra que también trabaja la espalda baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1459'),
('65f77810-5c6a-571d-8eed-837074b8b157', 'Peso muerto rumano a sentadilla con mancuernas', ARRAY['De pie con una mancuerna en cada mano, baja el tronco con la espalda recta hasta notar el estiramiento en isquios.', 'Sube extendiendo la cadera y, al llegar arriba, flexiona rodillas y cadera para hacer una sentadilla.', 'Mantén el pecho alto y las rodillas alineadas con los pies durante la sentadilla.', 'Respira de forma coordinada y evita redondear la espalda en la bisagra.', 'No uses impulso ni bloquees las rodillas al subir.']::text[], 'intermedio', 'Combina bisagra y sentadilla para trabajar glúteos, isquios y cuádriceps en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9484'),
('84a55879-934f-517f-8dc4-7091c19280ce', 'Apertura invertida con rotación y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.', 'Gira los brazos de modo que las palmas queden mirando hacia abajo.', 'Baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja deltoides posteriores y romboides con una apertura que incluye rotación para mejorar el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0386'),
('971c859d-f198-5c82-b164-f69653a03f44', 'Press de banca con agarre rotatorio y mancuernas', ARRAY['Túmbate en el banco con una mancuerna en cada mano a la altura del pecho y las palmas mirándose.', 'Empuja hacia arriba mientras giras las muñecas hasta que las palmas queden mirando hacia los pies.', 'Baja controlando el giro inverso hasta la posición inicial sin dejar caer las mancuernas.', 'Exhala al empujar e inhala al bajar, manteniendo los omóplatos retraídos.', 'Evita arquear la zona lumbar o rebotar la mancuerna contra el pecho.']::text[], 'intermedio', 'Trabaja el pecho con un giro que activa más fibras y suma tríceps y hombro para un empuje completo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4835'),
('be6b17c4-36d1-5a32-8fcc-180e13e5722b', 'Giro ruso con press de hombros y abdominal', ARRAY['Siéntate con las rodillas flexionadas y sujeta una mancuerna con ambas manos a la altura del pecho.', 'Inclina el tronco hacia atrás manteniendo la espalda recta y gira el torso a un lado y a otro.', 'Tras el giro, empuja la mancuerna por encima de la cabeza con agarre cerrado.', 'Exhala en cada giro y en el press, e inhala al volver al centro.', 'Evita tirar del cuello o redondear la espalda durante el movimiento.']::text[], 'intermedio', 'Combina core, oblicuos y empuje de hombro en un ejercicio global que mejora estabilidad y fuerza del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4625'),
('bda02574-19ca-5262-9ffa-62b07874567e', 'Giro ruso con mancuerna y piernas elevadas', ARRAY['Siéntate con las piernas elevadas y flexionadas, sujetando una mancuerna con ambas manos.', 'Inclina ligeramente el tronco hacia atrás y mantén el equilibrio sobre los glúteos.', 'Gira el torso hacia un lado y hacia el otro llevando la mancuerna junto a la cadera.', 'Exhala en cada rotación e inhala al volver al centro, sin bloquear la respiración.', 'Evita balancear los brazos o perder la curvatura neutra de la espalda.']::text[], 'intermedio', 'Intensifica el trabajo de abdominales y oblicuos al mantener las piernas en el aire y añadir rotación con carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4750'),
('9b9ec6cf-1dd4-5c93-8949-ddac1899b8f6', 'Press Scott con mancuernas', ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.', 'Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.', 'Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el deltoide con un recorrido guiado que también implica tríceps y parte alta del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2397'),
('49416c6d-f432-57a4-ae0d-b7b4fa94d7a4', 'Curl de bíceps sentado alternado con mancuernas', ARRAY['Siéntate con la espalda apoyada y una mancuerna en cada mano con las palmas hacia delante.', 'Flexiona un codo llevando la mancuerna hacia el hombro sin mover el brazo.', 'Baja despacio hasta extender el codo y repite con el otro brazo.', 'Exhala al subir e inhala al bajar, manteniendo el tempo controlado.', 'Evita balancear el tronco o usar impulso para levantar el peso.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con un trabajo alterno que mejora el control y la simetría de cada brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3761'),
('154b0fc6-21fc-592a-8dcc-daedc4e3ff67', 'Elevación frontal alternada sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados.', 'Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite con el otro brazo.', 'Alterna entre los brazos el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la porción anterior del deltoide y el trapecio, mejorando la fuerza de elevación del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0387'),
('66596599-d404-5eff-ae86-3f9f8200d9bd', 'Curl martillo alternado sentado en balón de estabilidad', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.', 'Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el movimiento con el brazo contrario.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza bíceps y antebrazo con agarre neutro mientras el balón exige estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1676'),
('60b958e4-1635-5bc7-a74e-1c307794fc7a', 'Extensión de tríceps sobre la cabeza alternada sentado con mancuernas', ARRAY['Siéntate con la espalda recta y sujeta una mancuerna por encima de la cabeza con ambas manos.', 'Baja la mancuerna detrás de la cabeza flexionando solo los codos.', 'Extiende un brazo de forma alterna hasta la posición inicial sin mover los hombros.', 'Exhala al extender e inhala al bajar, manteniendo los codos cerca de la cabeza.', 'Evita abrir los codos o arquear la espalda al empujar.']::text[], 'intermedio', 'Aísla el tríceps en estiramiento y suma hombro y core para mantener la posición estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6148'),
('5fb4d75b-e17e-5467-8d18-d8d1549040c1', 'Press de hombros alternado sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna en cada mano, con las palmas hacia adentro, y levántalas a la altura de los hombros.', 'Presiona una mancuerna hacia arriba, por encima de la cabeza, mientras mantienes la otra mancuerna a la altura de los hombros.', 'Baja la mancuerna levantada de vuelta a la altura de los hombros mientras presionas simultáneamente la otra mancuerna por encima de la cabeza.', 'Continúa alternando entre los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla el deltoide y el tríceps con un empuje alterno que mejora la coordinación y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3546'),
('84a80a29-8e55-574e-be49-575a120b6e1c', 'Elevación lateral alternada sentado con mancuernas', ARRAY['Siéntate con la espalda recta y una mancuerna en cada mano a los lados del cuerpo.', 'Eleva un brazo hacia el lado hasta la altura del hombro con el codo ligeramente flexionado.', 'Baja despacio y repite con el otro brazo sin balancear el tronco.', 'Exhala al elevar e inhala al bajar, manteniendo el movimiento controlado.', 'Evita encoger los hombros o subir el peso por encima de la línea del hombro.']::text[], 'intermedio', 'Fortalece el deltoide medio y el manguito rotador, mejorando la forma y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9933'),
('a93174f3-4e33-54dd-aee8-f08e31b958a3', 'Extensión sentado en banco con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.', 'Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.', 'Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps en posición sentada, con apoyo que reduce la tensión en hombros y espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0389'),
('4f178c57-3540-5caa-aa55-df403490fd38', 'Elevación lateral sentado con brazos flexionados (mancuernas)', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados.', 'Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el deltoide medio con los codos flexionados, reduciendo la palanca y protegiendo el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2317'),
('bfe7ca7f-90cc-5e51-8424-ce85fd6fc730', 'Patada alternada sentado inclinado con mancuernas', ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.', 'Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido.', 'Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en su porción posterior con un movimiento de extensión controlado y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1730'),
('34c84fe9-6c26-5353-856d-792a08e68392', 'Apertura posterior alterna sentado e inclinado con mancuernas', ARRAY['Siéntate en el banco inclinando el tronco hacia delante con la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas enfrentadas y los codos ligeramente flexionados.', 'Abre un brazo hacia el lado hasta la altura del hombro y vuelve al centro.', 'Exhala al abrir e inhala al volver, alternando los brazos sin balancear el tronco.', 'Evita encoger los hombros o usar impulso para elevar el peso.']::text[], 'intermedio', 'Refuerza el deltoide posterior y la espalda alta, equilibrando el desarrollo del hombro y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4066'),
('5edfbb4b-7804-5a37-af4b-32547034637a', 'Remo para deltoide posterior sentado e inclinado con mancuernas', ARRAY['Siéntate inclinando el tronco hacia delante con la espalda recta y una mancuerna en cada mano.', 'Tira de los codos hacia atrás llevando las mancuernas junto al torso.', 'Aprieta los omóplatos arriba y baja despacio hasta extender los brazos.', 'Exhala al tirar e inhala al bajar, manteniendo el cuello relajado.', 'Evita redondear la espalda o tirar con los brazos en lugar de con la espalda.']::text[], 'intermedio', 'Trabaja el deltoide posterior y la espalda alta con un remo que mejora la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4235'),
('77b1dfb3-b470-565b-9d2b-a9207c5e035f', 'Extensión de tríceps sentado inclinado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y la cabeza erguida.', 'Extiende los brazos rectos hacia atrás, manteniendo los codos cerca de la cabeza.', 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en posición inclinada para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1737'),
('6116d41e-eb8a-5f72-832a-1315e2d535d1', 'Curl de bíceps sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.', 'Mantén la espalda recta y los codos cerca del torso.', 'Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps y los antebrazos sentado, controlando el movimiento para aislar el brazo sin balanceo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1677'),
('ce812859-c3e4-50dd-aa2c-15456ae4348c', 'Curl a press de hombros sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros.', 'Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante.', 'Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos.', 'Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina curl de bíceps y press de hombros para trabajar brazos y deltoides en un solo movimiento global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3547'),
('0a1c0290-e6ed-5c91-b126-3698df93afd8', 'Elevación de gemelos sentado con mancuernas', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.', 'Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde.', 'Sujétate de la mancuerna para mantener la estabilidad.', 'Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y la parte posterior de la pierna con un rango controlado desde la posición sentada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1379'),
('93a224ea-8d03-50fb-b307-9fd8bc802623', 'Curl sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, con las palmas hacia adelante.', 'Mantén la espalda recta y los codos cerca del torso.', 'Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio clásico para bíceps y antebrazos que aísla el brazo al eliminar el impulso del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0391'),
('93661eff-1c0c-596e-ad44-97f47ccfa70f', 'Curl concentrado doble sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y sujeta una mancuerna en cada mano con las palmas hacia arriba.', 'Apoya los codos en la cara interna de los muslos y deja los brazos extendidos hacia abajo.', 'Sube las mancuernas flexionando los codos sin mover los hombros y aprieta el bíceps arriba.', 'Baja despacio controlando el movimiento y evita balancear el torso para coger impulso.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con las dos manos a la vez, buscando máxima contracción en cada repetición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6150'),
('fda8fc59-1614-537c-ab8a-28eee8361da9', 'Rotación externa sentado con mancuerna', ARRAY['Siéntate con la espalda recta y sujeta una mancuerna con el codo pegado al costado y flexionado a 90 grados.', 'Mantén el antebrazo apuntando hacia delante y el codo fijo junto al cuerpo.', 'Gira el antebrazo hacia fuera sin separar el codo del torso y aguanta un segundo arriba.', 'Vuelve despacio a la posición inicial y evita usar peso excesivo o girar el tronco.']::text[], 'intermedio', 'Refuerza el manguito rotador y la parte posterior del hombro para mejorar la estabilidad y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6140'),
('424a1b8e-f92d-534d-97f4-383fff489531', 'Rotación externa de hombro sentado con mancuerna', ARRAY['Siéntate erguido con una mancuerna en la mano y el codo flexionado a 90 grados pegado al costado.', 'Coloca el antebrazo hacia delante y mantén el hombro relajado y bajo.', 'Rota el brazo hacia fuera lentamente hasta donde te permita el hombro, sin mover el codo.', 'Regresa al punto de partida con control y evita compensar girando el tronco.']::text[], 'intermedio', 'Trabaja el manguito rotador y el deltoides posterior para estabilizar el hombro y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5001'),
('9482c305-7739-5053-b599-0a3b33562941', 'Press Tate sentado con mancuernas', ARRAY['Siéntate con la espalda apoyada y sujeta una mancuerna en cada mano con los codos flexionados y pegados al cuerpo.', 'Coloca las mancuernas a la altura del pecho con las palmas mirando hacia delante.', 'Extiende los codos empujando las mancuernas hacia delante y arriba hasta estirar los brazos.', 'Flexiona los codos para volver al inicio controlando el peso y sin abrir los codos hacia los lados.']::text[], 'intermedio', 'Aísla el tríceps con un movimiento de extensión que también implica pecho y hombros de forma secundaria.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4157'),
('00c2e957-eeae-532b-ae30-ccf6fa7a16d3', 'Elevación frontal sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.', 'Mantén la espalda recta y el core activado.', 'Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el deltoides anterior y los trapecios para mejorar la fuerza y el aspecto de los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0392'),
('7ac0fde8-88e5-5570-8a4b-cf67fa3d04ae', 'Encogimientos Gittleson sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y sujeta una mancuerna en cada mano a los lados.', 'Deja los brazos extendidos y los hombros relajados hacia abajo.', 'Sube los hombros hacia las orejas sin doblar los codos y aprieta los trapecios arriba.', 'Baja despacio hasta estirar los hombros y evita encoger el cuello o dar tirones.']::text[], 'intermedio', 'Trabaja los trapecios y la parte alta de la espalda con un encogimiento que también exige agarre y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4053'),
('23b8329b-b1df-54e5-a163-b8370f27d163', 'Curl interno de bíceps sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.', 'Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.', 'Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps y los antebrazos con un agarre que enfatiza la parte interna del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0393'),
('d67092d0-95f3-543f-bdfc-89327af0dd67', 'Patada de tríceps sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados.', 'Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.', 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con una extensión de codo que busca la contracción máxima en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0394'),
('82d5e05e-843c-5bff-b313-52e5ffc27fad', 'Elevación lateral sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.', 'Mantén la espalda recta y el core activado.', 'Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el deltoides medio y los trapecios para dar anchura y estabilidad a los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0396'),
('0de41fa2-bfc5-5da3-a213-996f7b6c5735', 'Elevación lateral sentado en balón de estabilidad con mancuernas', ARRAY['Siéntate sobre el balón con los pies apoyados y separados a la anchura de las caderas.', 'Sujeta una mancuerna en cada mano a los lados con los codos ligeramente flexionados.', 'Eleva los brazos hacia los lados hasta la altura de los hombros sin encogerlos.', 'Baja despacio manteniendo el tronco estable y evita balancearte o perder el equilibrio.']::text[], 'intermedio', 'Trabaja el deltoides medio y el core al mantener el equilibrio sobre el balón durante la elevación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4055'),
('d013d34f-8953-5ed4-bf82-acf8133045ba', 'Elevación lateral a frontal sentado con mancuernas', ARRAY['Siéntate con la espalda recta y una mancuerna en cada mano a los lados.', 'Sube los brazos lateralmente hasta la altura de los hombros con los codos ligeramente flexionados.', 'Continúa el movimiento hacia delante hasta juntar las manos frente a ti.', 'Baja controlando el recorrido por el mismo camino y exhala al elevar.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'intermedio', 'Trabaja los deltoides en sus porciones media y anterior, mejorando la estabilidad del hombro y la fuerza en elevación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4238'),
('0089a406-8895-5944-ab45-c9f01c3fb93f', 'Curl de muñeca neutro sentado con mancuernas', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí.', 'Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.', 'Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los flexores y extensores del antebrazo con agarre neutro, útil para mejorar el agarre y prevenir molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0397'),
('60ba1215-0131-5f64-9617-375a638bcd61', 'Press de hombros sentado en balón con mancuernas', ARRAY['Siéntate sobre el balón con los pies apoyados y la espalda erguida.', 'Sujeta las mancuernas a la altura de los hombros con las palmas al frente.', 'Empuja hacia arriba hasta estirar los brazos sin bloquear del todo los codos.', 'Baja controlando hasta la altura de los hombros y exhala al empujar.', 'Evita arquear la zona lumbar o perder el equilibrio sobre el balón.']::text[], 'intermedio', 'Desarrolla la fuerza de los deltoides y el tríceps mientras el core estabiliza el balón, mejorando el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3690'),
('1c248dea-639c-5f10-8b78-22b03fc5764e', 'Press arnold a un brazo sentado con mancuerna', ARRAY['Siéntate con la espalda apoyada y la mancuerna frente al hombro con la palma hacia ti.', 'Rota la muñeca mientras empujas hacia arriba hasta que la palma mire al frente.', 'Estira el brazo sin bloquear el codo y mantén el core activo.', 'Baja invirtiendo la rotación hasta la posición inicial y exhala al subir.', 'Evita balancear el tronco o encoger el hombro al empujar.']::text[], 'intermedio', 'Trabaja el deltoides en todo su recorrido con rotación, sumando tríceps y pecho superior en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4120'),
('e17a73ef-8a5c-5171-bf26-7f0066166448', 'Curl de bíceps a un brazo sentado en balón con pierna elevada', ARRAY['Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.', 'Coloca la otra mano en la cadera para mantener el equilibrio.', 'Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.', 'Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.', 'Baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de brazo y repite el ejercicio.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo mientras el core trabaja para mantener el equilibrio con una pierna levantada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1679'),
('e6678d62-97c9-5241-a150-f8c069c120f5', 'Elevación frontal a un brazo sentado con mancuerna', ARRAY['Siéntate erguido con la mancuerna apoyada en el muslo y la palma hacia abajo.', 'Eleva el brazo estirado hacia delante hasta la altura del hombro.', 'Mantén un segundo arriba sin encoger el cuello.', 'Baja despacio controlando el peso y exhala al elevar.', 'Evita usar impulso del tronco o subir por encima de la línea del hombro.']::text[], 'intermedio', 'Refuerza el deltoides anterior y el pecho superior, mejorando la fuerza en movimientos de empuje por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3689'),
('6bc91f33-aac6-51c4-86c0-77d56deadd3c', 'Patada de tríceps a un brazo sentado con mancuerna', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano.', 'Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.', 'Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps en extensión de codo, ayudando a tonificar la parte posterior del brazo con poco material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0398'),
('1928bbc6-c8dc-5ee2-ad0d-358b1f5a91c2', 'Rotación a un brazo sentado con mancuerna', ARRAY['Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo.', 'Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo.', 'Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo.', 'Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja los rotadores del antebrazo y la muñeca, mejorando el control y la estabilidad en agarres y giros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0399'),
('1e4c9bd4-469d-5c71-8946-bcbc52c189e1', 'Press de hombros a un brazo sentado con mancuerna', ARRAY['Siéntate con la espalda recta y la mancuerna a la altura del hombro.', 'Activa el abdomen para no inclinarte hacia el lado del peso.', 'Empuja la mancuerna hacia arriba hasta estirar el brazo sin bloquear el codo.', 'Baja controlando hasta el hombro y exhala al empujar.', 'Evita arquear la espalda o rotar el tronco durante el movimiento.']::text[], 'intermedio', 'Fortalece el deltoides y el tríceps de forma unilateral, exigiendo al core para evitar compensaciones laterales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1231'),
('9a704ddd-1889-5d59-9b71-e2005a0f5df8', 'Elevación de gemelos a una pierna sentado con mancuerna', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho.', 'Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado.', 'Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso.', 'Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Fortalece los gemelos y sóleo de forma unilateral, mejorando la estabilidad del tobillo y la fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0400'),
('fcaa64bf-7c2e-5baf-9a78-e7812db4e271', 'Elevación de gemelos a una pierna sentado con agarre martillo', ARRAY['Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.', 'Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde.', 'Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra.', 'Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia a la otra pierna.']::text[], 'intermedio', 'Trabaja el sóleo y los gemelos con agarre neutro, reforzando tobillos y pantorrillas de manera equilibrada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1380'),
('58b11a14-50fd-55a2-a9a5-b44435f60f87', 'Elevación de gemelos a una pierna sentado con palma arriba', ARRAY['Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.', 'Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba.', 'Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada.', 'Eleva el talón lo más alto posible empujando con la punta del pie.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Estimula la pantorrilla con un agarre que cambia la tensión del antebrazo, útil para variar el estímulo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1381'),
('a8f18a9e-3324-578c-a013-b3f3ae75534d', 'Curl de muñeca sentado con palmas arriba', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.', 'Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.', 'Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.', 'Haz una pausa por un momento y luego baja las muñecas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y la muñeca, mejorando el agarre y la resistencia en tareas diarias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0401'),
('af93535f-fed5-5721-a385-37f5e68c7cbd', 'Curl predicador sentado con mancuernas', ARRAY['Siéntate en un banco scott con los pies apoyados en el suelo.', 'Sujeta una mancuerna con una mano con agarre supino, apoyando la parte superior del brazo en la almohadilla del banco scott.', 'Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps con el brazo apoyado, reduciendo el impulso y aumentando la tensión en la parte baja del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0402'),
('6f9504db-4f91-54d7-8178-8d509688b120', 'Press arnold inverso sentado con mancuernas', ARRAY['Siéntate con la espalda apoyada y las mancuernas a la altura de los hombros con las palmas al frente.', 'Empuja hacia arriba mientras rotas las muñecas hasta que las palmas miren hacia ti.', 'Estira los brazos sin bloquear los codos y mantén el core activo.', 'Baja invirtiendo la rotación hasta la posición inicial y exhala al subir.', 'Evita encoger los hombros o perder la rotación controlada en la bajada.']::text[], 'intermedio', 'Trabaja los deltoides con rotación inversa, sumando tríceps y manguito rotador para hombros más estables.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6142'),
('9199bc7f-41bb-5618-884a-20955a2b44b0', 'Curl de bíceps sentado con agarre inverso y mancuernas', ARRAY['Siéntate con la espalda recta y los pies apoyados, sujetando las mancuernas con las palmas hacia abajo.', 'Flexiona los codos llevando las mancuernas hacia los hombros sin mover los brazos del torso.', 'Baja despacio controlando el movimiento y mantén las muñecas firmes durante todo el recorrido.', 'Evita balancear el cuerpo o encoger los hombros para subir el peso.']::text[], 'intermedio', 'Fortalece antebrazos y bíceps con un agarre que exige control y mejora la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3688'),
('d8f3f05a-9f59-5e14-b732-af77387d35d7', 'Extensión de tríceps sobre la cabeza a un brazo con agarre inverso', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza.', 'Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.', 'Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps en un rango largo, útil para ganar fuerza y control en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1738'),
('10e07b46-03de-5e8e-ba4f-4578ebb9dfa0', 'Press de hombros sentado con mancuernas', ARRAY['Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.', 'Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.', 'Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la fuerza de los hombros y la estabilidad del tren superior empujando el peso por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0405'),
('cad70b94-bbb1-50db-9a01-23988e96f389', 'Press de hombros sentado con agarre paralelo', ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.', 'Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.', 'Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los deltoides con un agarre neutro que reduce la tensión en el hombro y mejora la comodidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0404'),
('69288e4f-2aa5-5e51-a74a-416f3c88130f', 'Extensión de tríceps sobre la cabeza a un brazo sentado', ARRAY['Siéntate con la espalda recta y sujeta la mancuerna con una mano por encima de la cabeza.', 'Flexiona el codo bajando el peso detrás de la cabeza sin mover el brazo superior.', 'Extiende el codo para volver arriba controlando el movimiento y respirando con normalidad.', 'Evita arquear la espalda o abrir el codo hacia fuera durante el recorrido.']::text[], 'intermedio', 'Aísla el tríceps en un rango amplio y exige estabilidad del core para no compensar con el torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6158'),
('a540d65a-fe80-5162-aa58-4a53640dca99', 'Extensión de tríceps sentado con mancuerna', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.', 'Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.', 'Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el tríceps con un movimiento de extensión que mejora la fuerza y el tono del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2188'),
('30655b06-047f-5aca-a031-aee73f745911', 'Abdominal encogido sentado con mancuerna', ARRAY['Siéntate en el suelo con las rodillas flexionadas y sujeta la mancuerna con las dos manos.', 'Encoge el abdomen llevando el pecho hacia las rodillas sin tirar del cuello.', 'Mantén la posición un instante y vuelve despacio controlando el descenso.', 'Evita usar impulso o redondear la espalda en exceso.']::text[], 'intermedio', 'Trabaja la zona abdominal y los flexores de cadera con un encogimiento controlado que exige estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4626'),
('a6df9f6a-bbae-55f5-8720-c63fe11d3a76', 'Abdominal encogido con giro sentado con mancuerna', ARRAY['Siéntate en el suelo con las rodillas flexionadas y la mancuerna sujeta con las dos manos.', 'Encoge el abdomen y gira el tronco hacia un lado llevando el peso junto a la cadera.', 'Vuelve al centro y repite hacia el otro lado con un movimiento controlado.', 'Evita tirar del cuello o girar solo con los brazos.']::text[], 'intermedio', 'Activa abdominales y oblicuos con un encogimiento rotado que mejora el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4628'),
('1c92468e-918f-54e0-8ef8-0be6eda74944', 'Press con apretón alternado sentado', ARRAY['Siéntate erguido con las mancuernas a la altura del pecho y los codos cerca del cuerpo.', 'Aprieta las mancuernas entre sí mientras empujas una hacia arriba de forma alterna.', 'Baja controlando el peso y alterna los brazos sin perder la tensión en el pecho.', 'Evita bloquear los codos de golpe o separar las mancuernas durante el empuje.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps con un press que suma tensión interna y estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3946'),
('d7d13378-fe1d-51c4-b7e1-fb35f8d53d07', 'Curl zottman sentado con mancuernas', ARRAY['Siéntate con la espalda recta y las mancuernas con las palmas hacia arriba.', 'Flexiona los codos hasta los hombros manteniendo los brazos pegados al torso.', 'Gira las muñecas para bajar el peso con las palmas hacia abajo de forma controlada.', 'Evita balancear el cuerpo o perder el control en la rotación de la muñeca.']::text[], 'intermedio', 'Combina flexión y rotación para trabajar bíceps, antebrazo y braquial en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4110'),
('b612488f-e8ba-5da2-89d5-7d97e09293a2', 'Rotación interna de hombro a 90 grados con mancuerna', ARRAY['Coloca el brazo a 90 grados de abducción con el codo flexionado y la mancuerna ligera.', 'Rota el antebrazo hacia abajo manteniendo el codo fijo y el hombro estable.', 'Vuelve despacio a la posición inicial sin forzar el rango.', 'Evita usar peso excesivo o mover el codo durante la rotación.']::text[], 'principiante', 'Fortalece el manguito rotador y mejora la estabilidad del hombro en un rango controlado y seguro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 2.3, 'rehab', '5065'),
('9a67a550-4dbb-5aae-b485-cfbac3ddb30f', 'Complejo de hombros con mancuernas', ARRAY['De pie con las mancuernas a los lados, realiza una elevación lateral controlada.', 'Continúa con un press de hombros y luego un remo alto sin soltar el peso.', 'Mantén el core activo y respira de forma constante durante toda la secuencia.', 'Evita usar impulso o perder la postura cuando aparezca la fatiga.']::text[], 'intermedio', 'Encadena varios movimientos de hombro para ganar resistencia, coordinación y fuerza global del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10196'),
('c88dda33-4832-5d54-ac3a-1fe4d27289c3', 'Encogimientos de hombros con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.', 'Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados.', 'Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos.', 'Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los trapecios superiores y mejora la estabilidad de la cintura escapular con un movimiento sencillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0406'),
('d3430293-8784-5bd3-9de4-190fcbea65c3', 'Sentadilla lateral en banco con mancuernas', ARRAY['Colócate de pie junto a un banco con las mancuernas a los lados y los pies separados.', 'Da un paso lateral y baja flexionando la rodilla de la pierna de apoyo como en una sentadilla.', 'Empuja con el pie para volver al centro y repite hacia el otro lado.', 'Evita que la rodilla se vaya hacia dentro o cargar el peso sobre la punta del pie.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y aductores con un desplazamiento lateral que mejora la fuerza y el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4752'),
('abb1176a-7643-541e-a158-8b727d9368a5', 'Flexión lateral con mancuerna', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado.', 'Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado y repite.']::text[], 'intermedio', 'Trabaja los oblicuos y la estabilidad del core, útil para fortalecer la cintura y mejorar el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0407'),
('6d712087-79ce-5557-b85f-a3c1065d4a95', 'Puente lateral con pierna flexionada y mancuerna', ARRAY['Colócate de lado apoyando el antebrazo y la rodilla flexionada, con la mancuerna sujeta cerca del pecho.', 'Eleva la cadera hasta formar una línea recta entre hombro, cadera y rodilla.', 'Mantén la posición apretando el core y respirando de forma controlada.', 'Evita que la cadera caiga o rote; baja con control al terminar.']::text[], 'intermedio', 'Fortalece oblicuos, glúteos y hombros en isométrico, mejorando la estabilidad lateral del core y la resistencia postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4457'),
('0798ea6a-235b-596b-9332-c6cc5e405c72', 'Zancada lateral con press de hombros y mancuernas', ARRAY['De pie con una mancuerna en cada mano a la altura de los hombros.', 'Da un paso amplio hacia un lado flexionando esa rodilla y llevando la cadera atrás.', 'Al volver al centro, empuja las mancuernas por encima de la cabeza.', 'Baja las mancuernas con control y alterna el lado.', 'Evita que la rodilla pase por delante del pie en la zancada.']::text[], 'intermedio', 'Combina trabajo de glúteos, cuádriceps y hombros, mejorando la coordinación y la fuerza funcional de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4753'),
('3cd34ffa-ea1b-5066-875c-5435c8f5f51b', 'Rotación externa acostado de lado con mancuerna', ARRAY['Túmbate de lado en el banco con el codo pegado al cuerpo flexionado a 90 grados.', 'Sujeta la mancuerna ligera con la mano de arriba y el antebrazo apuntando al frente.', 'Rota el antebrazo hacia arriba sin separar el codo del costado.', 'Baja lentamente controlando el movimiento y repite.', 'Evita usar demasiado peso o girar el tronco.']::text[], 'principiante', 'Refuerza el manguito rotador y el deltoides posterior, ideal para readaptación y prevención de lesiones de hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 2.3, 'rehab', '5817'),
('ef4a2452-d553-50ae-bad9-f8add9376326', 'Elevación de lado acostado a una mano con mancuerna', ARRAY['Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.', 'Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo.', 'Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Aísla el deltoides y activa trapecio y romboides, útil para ganar fuerza y control en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0408'),
('168fce87-39fa-5f50-8e1b-5c7510e6a7e9', 'Plancha lateral con apertura posterior y mancuerna', ARRAY['Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.', 'Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados.', 'Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo.', 'Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones.', 'Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí.', 'Baja la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja la espalda alta y el core en isométrico, mejorando la estabilidad del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3664'),
('9667c48e-eac1-54c9-ba16-f1234df82629', 'Sentadilla lateral con mancuernas', ARRAY['De pie con los pies más anchos que los hombros y una mancuerna en cada mano.', 'Desplaza la cadera hacia un lado flexionando esa rodilla mientras la otra pierna se estira.', 'Mantén el pecho alto y la espalda recta durante el descenso.', 'Empuja con la pierna flexionada para volver al centro y alterna.', 'Evita redondear la espalda o levantar los talones.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y aductores, mejorando la movilidad lateral y la fuerza de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4754'),
('b788f3e6-3966-58b1-ac76-df74ab4bb392', 'Press de banca declinado alterno a un brazo con mancuerna', ARRAY['Túmbate en el banco declinado con una mancuerna en cada mano a la altura del pecho.', 'Empuja una mancuerna hacia arriba mientras la otra permanece abajo.', 'Baja con control y alterna el brazo, manteniendo el core firme.', 'Evita arquear en exceso la zona lumbar o perder el control del descenso.']::text[], 'intermedio', 'Trabaja el pectoral de forma unilateral, con apoyo de tríceps y core para estabilizar el movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5097'),
('ce5b92e6-97b6-5158-a25c-53cb104793a4', 'Remo con apoyo de pecho a un brazo con mancuerna', ARRAY['Apoya el pecho en el banco con una mancuerna colgando en una mano.', 'Tira de la mancuerna hacia la cadera llevando el codo atrás.', 'Aprieta la escápula arriba y baja con control.', 'Evita balancear el tronco o encoger el hombro.']::text[], 'intermedio', 'Fortalece dorsal, espalda alta y bíceps con apoyo que reduce la carga lumbar y mejora la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9699'),
('a12b9893-dd56-5046-82f2-151ac87ff0ab', 'Curl a un brazo con mancuerna y sostén isométrico', ARRAY['De pie con una mancuerna en una mano y el codo pegado al costado.', 'Flexiona el codo subiendo la mancuerna hasta la altura del hombro.', 'Mantén la posición arriba unos segundos apretando el bíceps.', 'Baja lentamente y repite sin balancear el tronco.']::text[], 'intermedio', 'Aísla el bíceps y el braquial, con una pausa isométrica que aumenta la tensión y el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11864'),
('f6281e88-f85c-5028-9ee4-f188868904ac', 'Elevación frontal a un brazo con agarre neutro y mancuerna', ARRAY['De pie con una mancuerna en una mano y agarre neutro frente al muslo.', 'Eleva el brazo estirado hasta la altura del hombro sin balancear.', 'Baja con control manteniendo el core activo.', 'Evita usar impulso del tronco o subir por encima del hombro.']::text[], 'intermedio', 'Trabaja el deltoides anterior y el pectoral superior, mejorando la fuerza y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5944'),
('8127e6f9-8d67-57e5-9785-b58fbe189a70', 'Transporte sobre la cabeza a un brazo con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.', 'Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.', 'Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza.', 'Continúa caminando durante la distancia o el tiempo deseado.', 'Cambia de mano y repite el ejercicio.']::text[], 'intermedio', 'Fortalece hombros, trapecios y core, mejorando la estabilidad y la resistencia postural en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3548'),
('66f3710a-7fe3-5e46-ab22-b78dc99080d1', 'Zancada sobre la cabeza a un brazo con mancuerna', ARRAY['De pie con una mancuerna sujeta por encima de la cabeza con un brazo estirado.', 'Da un paso al frente y baja flexionando la rodilla trasera.', 'Mantén el brazo firme y el core apretado durante la zancada.', 'Empuja con la pierna delantera para volver y alterna.', 'Evita perder la verticalidad del brazo o inclinar el tronco.']::text[], 'intermedio', 'Combina piernas, hombros y core, mejorando la coordinación y la fuerza funcional en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5095'),
('621f1c99-07cf-5ff1-ae86-1fa2be406361', 'Curl predicador a un brazo con mancuerna', ARRAY['Apoya el brazo sobre el soporte del predicador con la mancuerna en la mano.', 'Flexiona el codo subiendo la mancuerna con control.', 'Aprieta el bíceps arriba y baja lentamente sin extender del todo.', 'Evita despegar el brazo del soporte o usar impulso.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con apoyo del brazo, reduciendo el impulso y mejorando la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3084'),
('3713c934-3aa6-5474-9455-3f127872ed47', 'Encogimiento a un brazo con mancuerna', ARRAY['De pie con una mancuerna en una mano a lo largo del cuerpo.', 'Eleva el hombro hacia la oreja sin doblar el codo.', 'Aprieta arriba un instante y baja con control.', 'Evita rotar el tronco o encoger el cuello.']::text[], 'intermedio', 'Trabaja el trapecio y la espalda alta, mejorando la fuerza del cuello y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10901'),
('87b3d3a2-807e-5003-9cf2-46693eab8319', 'Elevación frontal a un brazo con agarre supino y mancuerna', ARRAY['Colócate de pie con la mancuerna sujeta con agarre supino y el brazo extendido delante del muslo.', 'Sube el brazo recto hasta la altura del hombro sin balancear el tronco.', 'Baja despacio controlando el movimiento y mantén el abdomen activo.', 'Evita encoger el hombro o usar impulso de la espalda.']::text[], 'intermedio', 'Trabaja la parte anterior del hombro y el pecho superior, mejorando la fuerza y el control del hombro de forma unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5092'),
('c97a0472-d3c4-521a-8c8d-40426ca5e1f8', 'Press Z a un brazo con mancuerna', ARRAY['Siéntate en el suelo con las piernas abiertas y la espalda recta.', 'Sujeta la mancuerna a la altura del hombro con el codo flexionado.', 'Empuja hacia arriba hasta extender el brazo sin arquear la espalda.', 'Baja controlando hasta el hombro y mantén el core firme en todo momento.', 'Evita inclinarte hacia atrás para completar el empuje.']::text[], 'intermedio', 'Fortalece hombros, tríceps y core desde una posición sentada en el suelo que exige estabilidad y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10043'),
('dac8cb08-b4e0-5303-8cd2-136d74d090d6', 'Elevación de gemelos a una pierna con mancuerna', ARRAY['Ponte de pie en el borde de un escalón o plataforma, con los talones colgando y la punta de los pies sobre el escalón.', 'Sujeta una mancuerna con una mano y coloca la otra mano sobre una pared o barandilla para apoyarte.', 'Eleva el talón lo más alto posible, levantando el cuerpo sobre la punta de los pies.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón por debajo del nivel del escalón.', 'Repite el número de repeticiones deseado, luego cambia a la otra pierna.']::text[], 'intermedio', 'Aísla el gemelo y el sóleo para ganar fuerza y estabilidad en el tobillo, mejorando el equilibrio sobre una pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0409'),
('0f7480a5-9b7c-54a6-94b8-12d3934eba66', 'Peso muerto a una pierna con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.', 'Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo.', 'Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo.', 'Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda.', 'Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo.', 'Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja glúteos e isquios mientras mejora el equilibrio y la estabilidad de la cadera en apoyo monopodal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1757'),
('91f3e514-da08-594c-8a77-e1c2925ca2fa', 'Peso muerto a una pierna con apoyo en cajón y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.', 'Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti.', 'Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo.', 'Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón.', 'Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Refuerza glúteos e isquios con apoyo que facilita el equilibrio, ideal para progresar en el control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2805'),
('382beb6a-9a72-5ef6-be49-4662b60f4c6a', 'Peso muerto a una pierna con apoyo en la pared y mancuerna', ARRAY['Apóyate con una mano en la pared y sujeta la mancuerna con la otra.', 'Inclínate hacia delante llevando la cadera atrás mientras la pierna libre se eleva.', 'Mantén la espalda recta y baja hasta notar el estiramiento del isquio.', 'Sube apretando el glúteo y evita redondear la espalda.']::text[], 'intermedio', 'Fortalece isquios y glúteos mejorando el equilibrio y la estabilidad de la cadera con ayuda del apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2750'),
('7f1efc25-84a3-5a27-9ec8-374bafd02815', 'Puente de glúteos a una pierna con mancuerna', ARRAY['Túmbate boca arriba con una pierna flexionada y la mancuerna sobre la cadera.', 'Eleva la cadera apretando el glúteo hasta alinear tronco y muslo.', 'Mantén la otra pierna extendida o elevada sin forzar la lumbar.', 'Baja controlando y evita arquear la espalda al subir.']::text[], 'intermedio', 'Activa el glúteo de forma unilateral y refuerza isquios y core, útil para estabilidad de cadera y lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4291'),
('33a0d113-8da7-53fe-abea-cd5e8dbf1d60', 'Empuje de cadera a una pierna con mancuerna', ARRAY['Apoya la espalda alta en un banco con una pierna flexionada y la mancuerna sobre la cadera.', 'Empuja la cadera hacia arriba hasta alinear tronco y muslo.', 'Aprieta el glúteo arriba y mantén el abdomen firme.', 'Baja despacio sin dejar caer la cadera y evita hiperextender la lumbar.']::text[], 'intermedio', 'Potencia el glúteo con extensión de cadera unilateral, mejorando fuerza, estabilidad y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4755'),
('374e7e57-d4af-502f-86c0-e5c7112208a9', 'Peso muerto rumano a una pierna en banco con mancuerna', ARRAY['Apoya un pie en el banco y sujeta la mancuerna con la mano contraria.', 'Inclínate llevando la cadera atrás mientras la pierna libre se eleva.', 'Mantén la espalda recta y baja hasta notar el estiramiento del isquio.', 'Sube apretando el glúteo y evita redondear la espalda.']::text[], 'intermedio', 'Estira y fortalece isquios y glúteos con control unilateral, mejorando equilibrio y estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10865'),
('8ee179b9-966d-5c43-b4ab-3a76373b2f88', 'Sentadilla a una pierna con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio.', 'Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.', 'Mantén el pecho arriba y la espalda recta.', 'Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Desarrolla fuerza y equilibrio en glúteos y cuádriceps trabajando una pierna a la vez con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0411'),
('bf675191-df0a-5e14-ac49-46602176aec6', 'Subida al cajón a una pierna con mancuernas', ARRAY['Colócate frente al cajón con una mancuerna en cada mano.', 'Apoya un pie entero sobre el cajón y empuja con esa pierna para subir.', 'Extiende la cadera arriba sin impulsarte con la pierna de abajo.', 'Baja controlando y evita dejarte caer o apoyar la rodilla.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora potencia, equilibrio y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2925'),
('c944cca5-bb98-56fb-ba77-96074848d8ec', 'Subida al banco a una pierna con mancuernas', ARRAY['Sitúate frente al banco con una mancuerna en cada mano.', 'Apoya el pie completo en el banco y empuja para subir.', 'Mantén el tronco erguido y extiende la cadera arriba.', 'Baja despacio y evita empujarte con la pierna del suelo.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un paso unilateral que mejora fuerza, equilibrio y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4821'),
('2f96ae6f-aabe-58df-98cd-4a71f4c624b6', 'Cargada de potencia con una mancuerna', ARRAY['Coloca la mancuerna entre los pies con la espalda recta y el pecho arriba.', 'Extiende con fuerza caderas y rodillas para acelerar la mancuerna.', 'Recibe la mancuerna a la altura del hombro con los codos abajo.', 'Evita tirar con los brazos antes de extender las caderas.']::text[], 'avanzado', 'Movimiento explosivo que desarrolla potencia de glúteos, isquios y trapecios, mejorando la coordinación global.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5101'),
('821bfee0-c31d-558a-816b-d5cdc42f0460', 'Curl araña a un brazo con apoyo en el pecho y mancuerna', ARRAY['Apoya el pecho en un banco inclinado y deja colgar el brazo con la mancuerna.', 'Flexiona el codo subiendo la mancuerna sin mover el hombro.', 'Aprieta el bíceps arriba y baja controlando el movimiento.', 'Evita balancear el cuerpo o usar impulso para subir.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con el pecho apoyado, evitando impulso y mejorando el control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3963'),
('72b79e0f-2bb4-5fc7-8cb5-4aaedac0c613', 'Peso muerto a una pierna con piernas rectas y mancuerna', ARRAY['De pie con la mancuerna en una mano y las piernas casi extendidas.', 'Inclínate llevando la cadera atrás mientras elevas la pierna libre.', 'Mantén la espalda recta y baja hasta notar el estiramiento del isquio.', 'Sube apretando el glúteo y evita redondear la espalda.']::text[], 'intermedio', 'Estira y fortalece isquios y glúteos con pierna casi recta, mejorando equilibrio y control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3338'),
('85adfbc2-7f39-558a-b1d1-589d9f86038d', 'Abdominal completo con mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta la mancuerna con ambas manos junto al pecho.', 'Contrae el abdomen y eleva el tronco hasta acercar el pecho a las rodillas.', 'Baja de forma controlada sin apoyar del todo la espalda y repite.', 'Evita tirar del cuello con las manos y mantén la barbilla separada del pecho.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos, mejorando la fuerza del core y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4756'),
('7d4bc121-4fa3-5196-b321-6c80a24fb3f1', 'Buenos días sentado con mancuernas', ARRAY['Siéntate en un banco con la espalda recta y la mancuerna apoyada sobre los trapecios.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda neutra.', 'Baja hasta notar el estiramiento de los isquios y vuelve a subir.', 'Evita redondear la espalda y controla el descenso sin dejarte caer.']::text[], 'intermedio', 'Fortalece la cadena posterior y los erectores espinales, mejorando la estabilidad y la postura del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9515'),
('7fcbff07-27b7-5b9c-8c86-64ce86748f63', 'Salto con tijera y mancuernas', ARRAY['Colócate en zancada con una mancuerna en cada mano y el tronco erguido.', 'Salta y cambia de pierna en el aire, aterrizando con la rodilla delantera alineada con el pie.', 'Amortigua el aterrizaje flexionando ligeramente las rodillas antes del siguiente salto.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Desarrolla la potencia de piernas y glúteos con un gesto explosivo que mejora la coordinación y el equilibrio.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1554'),
('459a89eb-ed0a-5aa8-9308-b00041848602', 'Sentadilla dividida con pie delantero elevado y mancuernas', ARRAY['Apoya el pie delantero sobre un step y el trasero detrás, con una mancuerna en cada mano.', 'Desciende flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.', 'Empuja con el pie delantero para volver a subir sin perder el equilibrio.', 'Mantén el tronco erguido y evita que la rodilla trasera golpee el suelo.']::text[], 'intermedio', 'Aumenta la fuerza del cuádriceps y el glúteo con mayor rango de movimiento y control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2957'),
('7864f72e-8d19-5ec6-ab36-24b07e2a0e28', 'Sentadilla dividida con pie delantero elevado en bosu y mancuernas', ARRAY['Coloca el pie delantero sobre el bosu y el trasero detrás, con una mancuerna en cada mano.', 'Baja de forma lenta flexionando la rodilla delantera mientras mantienes el equilibrio.', 'Empuja con el pie delantero para subir controlando la superficie inestable.', 'Evita mirar al suelo y fija la vista al frente para no perder la estabilidad.']::text[], 'intermedio', 'Mejora la fuerza unilateral y el equilibrio del cuádriceps sobre una superficie inestable que exige control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3710'),
('6893cad1-bb2e-50bc-81f6-e7cdea094c80', 'Sentadilla con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.', 'Manteniendo el pecho arriba y el core activado, baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos, cuádriceps e isquios, mejorando la fuerza y la estabilidad de todo el tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0413'),
('e79f79de-5767-549d-bd28-7419723c66fd', 'Elevación de gemelos en sentadilla mantenida con mancuernas', ARRAY['Colócate en sentadilla con los muslos paralelos al suelo y una mancuerna en cada mano.', 'Mantén la posición y eleva los talones hasta ponerte de puntillas.', 'Baja los talones de forma controlada sin perder la postura de la sentadilla.', 'Evita rebotar en el descenso y mantén el peso repartido en todo el pie.']::text[], 'intermedio', 'Trabaja los gemelos y el sóleo manteniendo una isometría de cuádriceps y glúteos que exige estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4563'),
('9004363a-05fd-58d6-b5cb-69da67f4a39f', 'Complejo de sentadilla, zancada y salto con mancuernas', ARRAY['Con una mancuerna en cada mano, haz una sentadilla completa y vuelve a subir.', 'Pasa a zancada alternando piernas manteniendo el tronco erguido.', 'Termina con un salto vertical amortiguando bien el aterrizaje.', 'Evita perder la espalda neutra y descansa si la técnica se deteriora.']::text[], 'intermedio', 'Combina fuerza y pliometría para mejorar la potencia, la resistencia y la coordinación del tren inferior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '4564'),
('333f4c84-14b7-5951-ba3f-eb2c8dbecbd1', 'Sentadilla a press sobre la cabeza con mancuernas', ARRAY['Sujeta una mancuerna en cada mano a la altura de los hombros con los pies a la anchura de las caderas.', 'Haz una sentadilla bajando las caderas hacia atrás y manteniendo el pecho alto.', 'Al subir, empuja las mancuernas por encima de la cabeza hasta estirar los brazos.', 'Evita arquear la zona lumbar al press y baja las mancuernas con control.']::text[], 'intermedio', 'Ejercicio global que trabaja piernas, hombros y core, mejorando la fuerza y la coordinación de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5066'),
('03d9f29b-2be5-5c19-9f41-8f4b0a8c0e35', 'Press de banca con mancuernas apretadas', ARRAY['Túmbate en el banco con una mancuerna en cada mano y los pies apoyados en el suelo.', 'Baja las mancuernas al pecho manteniéndolas juntas y con los codos cerca del cuerpo.', 'Empuja hacia arriba apretando las mancuernas entre sí durante todo el recorrido.', 'Evita abrir los codos en exceso y no rebotes en el pecho.']::text[], 'intermedio', 'Trabaja el pectoral con mayor activación interna al juntar las mancuernas, implicando también tríceps y hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3681'),
('e7735973-926b-5c1c-89dc-5bf656f2d4a5', 'Peso muerto rumano con postura escalonada y mancuernas', ARRAY['Coloca un pie delante y otro detrás con una mancuerna en cada mano frente a los muslos.', 'Lleva las caderas hacia atrás bajando las mancuernas por las piernas con la espalda recta.', 'Nota el estiramiento de los isquios y sube empujando las caderas hacia delante.', 'Evita redondear la espalda y mantén el peso repartido entre ambos pies.']::text[], 'intermedio', 'Fortalece isquios y glúteos con una base escalonada que mejora el equilibrio y la conciencia de la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4757'),
('1a529756-a3fc-5cda-a423-fdf686d87cc1', 'Press arnold alternado de pie con mancuernas', ARRAY['De pie, sujeta las mancuernas frente a los hombros con las palmas hacia ti.', 'Empuja una mancuerna hacia arriba girando la muñeca hasta que la palma mire al frente.', 'Baja de forma controlada invirtiendo la rotación y alterna con el otro brazo.', 'Evita arquear la espalda y mantén el abdomen activo durante todo el movimiento.']::text[], 'intermedio', 'Trabaja el deltoides en todo su rango con rotación, mejorando la fuerza y la movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4065'),
('df8341d1-7ee8-55c1-a0e5-4964f148a530', 'Curl martillo y press alternado de pie con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Mantén los codos cerca del torso y la espalda recta.', 'Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el curl con la mano izquierda.', 'Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza.', 'Extiende completamente el brazo y mantén la posición por un momento en la parte superior.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el press con la mano izquierda.', 'Continúa alternando entre curls y press durante el número de repeticiones deseado.']::text[], 'intermedio', 'Combina el trabajo de bíceps y antebrazo con un press de hombro, ganando fuerza y eficiencia en un solo ejercicio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3560'),
('12c79eb5-4eaa-5056-9c3a-62a0a7cb640a', 'Press sobre la cabeza alternado de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.', 'Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo.', 'Baja la mancuerna de vuelta a la altura de los hombros.', 'Repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los hombros y el tríceps de forma unilateral, exigiendo estabilidad del core al mantenerte de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0414'),
('85e4d976-cf6c-5436-a5d8-56028fefb9a8', 'Elevación alternada de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.', 'Mantén la espalda recta y el core activado.', 'Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.', 'Continúa levantando hasta que el brazo quede paralelo al suelo.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite con el otro brazo.', 'Alterna entre los brazos el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el deltoides con elevaciones controladas que mejoran la fuerza y el control del hombro de forma unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0415'),
('14646ba4-63c1-5eaa-8b58-6ec0e855973a', 'Curl inverso alternado de pie con mancuernas', ARRAY['Colócate de pie con una mancuerna en cada mano y las palmas hacia abajo.', 'Sube una mancuerna flexionando el codo sin mover el hombro ni la muñeca.', 'Baja despacio controlando el movimiento y alterna con el otro brazo.', 'Evita balancear el torso o usar impulso para subir el peso.']::text[], 'intermedio', 'Fortalece los antebrazos y los extensores de la muñeca, mejorando el agarre y la estabilidad en movimientos de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6265'),
('17beb5cd-21b6-5a8e-81e1-be86193d52cf', 'Elevaciones frontales alternadas de pie con mancuernas', ARRAY['De pie, con una mancuerna en cada mano delante de los muslos y las palmas hacia el cuerpo.', 'Sube un brazo estirado hasta la altura de los ojos sin encoger el hombro.', 'Baja despacio y repite con el otro brazo de forma alterna.', 'Mantén el abdomen firme y evita arquear la espalda al levantar.']::text[], 'intermedio', 'Trabaja la parte delantera del hombro y el pecho superior, ayudando a ganar fuerza en empujes por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1230'),
('b60a286a-aec4-57d0-8a9c-8536d1d6c8f7', 'Elevación cruzada alterna de pie con mancuernas', ARRAY['De pie, con una mancuerna en cada mano y los brazos junto al cuerpo.', 'Sube un brazo en diagonal hasta cruzar delante del pecho.', 'Baja controlando y alterna con el otro brazo.', 'No gires el tronco ni uses impulso para completar la subida.']::text[], 'intermedio', 'Activa el deltoides y la parte alta del pecho, con implicación de oblicuos por el cruce del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10040'),
('b3d9bebe-3b9a-52cd-bd7b-cf650fa3d2c7', 'Patada de tríceps alternada de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite con el otro brazo, alternando lados en cada repetición.']::text[], 'intermedio', 'Aísla el tríceps para tonificar la parte posterior del brazo y mejorar la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1739'),
('8ebf1968-8783-598a-8cbd-a8d3a45f8b2f', 'Rotación de brazos de pie con mancuernas', ARRAY['De pie, con una mancuerna en cada mano y los codos pegados al cuerpo.', 'Gira las muñecas hacia dentro y hacia fuera de forma lenta y controlada.', 'Mantén los codos fijos y el peso ligero para no forzar la articulación.', 'Respira con normalidad y evita movimientos bruscos.']::text[], 'intermedio', 'Refuerza antebrazos y muñecas mediante rotaciones controladas, mejorando el agarre y la movilidad articular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6267'),
('4ccbabe1-87f5-52fd-b994-44069c2e45d9', 'Press Arnold de pie con mancuernas', ARRAY['De pie, con mancuernas a la altura de los hombros y palmas hacia ti.', 'Empuja hacia arriba girando las palmas hacia fuera al extender los brazos.', 'Baja invirtiendo el giro hasta la posición inicial.', 'Mantén el abdomen firme y evita arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja el deltoides en varios ángulos con participación de tríceps y trapecio, ganando fuerza en el empuje vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4108'),
('b329ea7d-2192-5208-b891-93fe0113317a', 'Círculo mundial de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo.', 'Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza.', 'Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Moviliza y fortalece el hombro en todo su rango con un círculo amplio, mejorando control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2143'),
('28c76aff-1d12-52db-a430-a0e95093d17f', 'Curl de muñeca por detrás de pie con mancuernas', ARRAY['De pie, sujeta las mancuernas detrás de la espalda con las palmas hacia atrás.', 'Flexiona las muñecas hacia arriba sin mover los codos.', 'Baja despacio hasta la posición inicial.', 'Usa un peso ligero y evita balancear el cuerpo.']::text[], 'intermedio', 'Fortalece los flexores de la muñeca y el agarre, útil para mejorar el rendimiento en ejercicios de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6366'),
('382436cb-850d-5f3f-b227-c063b8581873', 'Elevación lateral de pie con brazos flexionados y mancuernas', ARRAY['De pie, con mancuernas a los lados y los codos flexionados unos 90 grados.', 'Sube los brazos hacia los lados hasta la altura de los hombros.', 'Baja controlando sin dejar caer el peso.', 'Evita encoger los hombros o usar impulso del tronco.']::text[], 'intermedio', 'Incide en el deltoides medio con los codos flexionados, reduciendo tensión en el hombro y mejorando la forma.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5631'),
('06933fc9-24a2-5bf1-9cd5-a983351cb893', 'Extensión de tríceps a un brazo inclinado con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.', 'Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.', 'Baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el tríceps en posición inclinada, trabajando la extensión del codo con apoyo del hombro y la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1740'),
('d22f17d1-0582-55c5-a9e3-2ae33d26e9e7', 'Extensión de tríceps a dos brazos inclinado con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.', 'Baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps con ambos brazos en posición inclinada, mejorando la fuerza en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1741'),
('0e783ee2-c178-543a-a825-184b2292a178', 'Curl de bíceps de pie con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el bíceps y los antebrazos, mejorando la flexión del codo y el volumen del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0416'),
('2de38895-88c2-524a-92a8-215591199fb4', 'Curl de bíceps a press de hombros con mancuernas', ARRAY['De pie, con mancuernas a los lados y palmas hacia delante.', 'Flexiona los codos hasta llevar las mancuernas a los hombros.', 'Desde ahí empuja hacia arriba hasta extender los brazos.', 'Baja invirtiendo el recorrido y mantén el abdomen firme.']::text[], 'intermedio', 'Combina bíceps y hombros en un movimiento completo que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4574'),
('a65c4da3-1d49-562b-9ca4-3a2e6546f015', 'Elevación de gemelos de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.', 'Levanta los talones del suelo lo más alto posible, usando las pantorrillas.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y el tobillo, mejorando la estabilidad y la fuerza en la extensión del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0417'),
('4da41ddc-4ebd-564d-8902-34717064224a', 'Curl concentrado de pie con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro.', 'Apoya la otra mano sobre el muslo para mayor estabilidad.', 'Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Aísla el bíceps con el codo fijo, buscando máxima contracción y control en la flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0418'),
('2efce617-145d-5043-8489-6e8c5598133c', 'Cargada cruzada de pie con mancuerna', ARRAY['Colócate de pie con los pies a la anchura de las caderas y una mancuerna en una mano junto al muslo.', 'Flexiona ligeramente las rodillas y lleva la cadera atrás mientras bajas la mancuerna hacia la rodilla contraria.', 'Sube la mancuerna en diagonal hasta el hombro opuesto con un movimiento rápido y controlado, girando la muñeca.', 'Baja despacio por el mismo camino y repite sin perder la espalda neutra.', 'Evita encorvar la espalda o usar impulso excesivo de la zona lumbar.']::text[], 'intermedio', 'Trabaja los hombros y el trapecio con un gesto explosivo que también activa glúteos, isquios y core para ganar potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10094'),
('894b9e28-6b5d-5f6e-a4ac-bceb4807bc95', 'Curl de arrastre de pie con mancuernas', ARRAY['De pie, sujeta una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos extendidos.', 'Sube las mancuernas deslizándolas cerca del torso, llevando los codos hacia atrás y arriba.', 'Aprieta el bíceps arriba un instante y baja controlando el movimiento.', 'Mantén los hombros bajos y evita balancear el tronco para subir el peso.']::text[], 'intermedio', 'Aísla el bíceps y el braquial con un recorrido corto que mantiene tensión constante y respeta el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5449'),
('0ab82b26-bc29-51d7-8f7c-79a92f280f56', 'Driver de pie con mancuerna', ARRAY['De pie con los pies a la anchura de los hombros, sujeta una mancuerna a la altura del hombro con el codo flexionado.', 'Extiende el brazo hacia arriba mientras giras la palma hacia delante.', 'Baja la mancuerna controlando el recorrido hasta la posición inicial.', 'Mantén el abdomen firme y evita arquear la espalda al empujar.']::text[], 'intermedio', 'Ejercicio de hombro y tríceps que exige estabilidad del core mientras elevas y rotas la mancuerna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6141'),
('334d7a7f-db94-54e0-9ca3-57007a7bd90b', 'Press francés de pie con mancuerna', ARRAY['De pie, sujeta una mancuerna con ambas manos por encima de la cabeza y los codos apuntando al frente.', 'Baja la mancuerna detrás de la cabeza flexionando solo los codos.', 'Extiende los codos para volver arriba sin mover los brazos.', 'Mantén el core apretado y evita abrir los codos hacia los lados.']::text[], 'intermedio', 'Fortalece el tríceps en posición vertical, con demanda adicional de hombros y core para mantener la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6221'),
('dfec6ab8-97f0-5db1-b609-6a6e0a87ed62', 'Elevación frontal y lateral de pie con mancuernas', ARRAY['De pie con una mancuerna en cada mano y los brazos junto al cuerpo.', 'Eleva una mancuerna al frente hasta la altura del hombro y bájala con control.', 'Eleva la otra mancuerna hacia el lado hasta la altura del hombro y bájala.', 'Alterna ambos movimientos sin balancear el tronco ni encoger los hombros.']::text[], 'intermedio', 'Combina elevaciones frontales y laterales para trabajar las tres porciones del deltoides y mejorar la estética del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7449'),
('7879e125-9063-57fd-a1e0-807cfee7940a', 'Elevación frontal de pie sobre la cabeza con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva las mancuernas por encima de la cabeza para trabajar la porción anterior del deltoides y el trapecio superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0419'),
('514181f3-22e9-5e2a-be50-05f00e3a929e', 'Elevación frontal de pie con giro y mancuernas', ARRAY['De pie con los pies a la anchura de los hombros y una mancuerna en cada mano frente a los muslos.', 'Eleva una mancuerna al frente hasta la altura del hombro mientras giras el tronco hacia ese lado.', 'Vuelve al centro bajando la mancuerna con control.', 'Alterna lados manteniendo el abdomen apretado y evitando tirar con la espalda.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con una elevación frontal que añade rotación para activar el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10183'),
('ba3320c4-f959-5590-9180-9e3426e41c76', 'Torsión de manos de pie con mancuerna', ARRAY['De pie, sujeta una mancuerna por un extremo con una mano y el brazo extendido junto al cuerpo.', 'Gira la muñeca hacia dentro y hacia fuera de forma lenta y controlada.', 'Mantén el codo pegado al torso y el hombro relajado.', 'Evita movimientos bruscos y usa un peso ligero para no forzar la muñeca.']::text[], 'intermedio', 'Refuerza antebrazos y muñecas con un gesto de torsión que mejora el agarre y la estabilidad de la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7054'),
('7949a242-b3a6-50b0-9255-dd57a2751fca', 'Molino alto de pie con mancuerna', ARRAY['De pie con los pies más anchos que las caderas y una mancuerna en una mano extendida por encima de la cabeza.', 'Inclina el tronco hacia el lado contrario mientras la mancuerna libre baja hacia el pie.', 'Mantén la mirada en la mancuerna elevada y las piernas ligeramente flexionadas.', 'Vuelve al centro apretando el oblicuo y repite sin perder la espalda neutra.']::text[], 'intermedio', 'Ejercicio de core y oblicuos que también moviliza hombros e isquios, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4888'),
('10185d71-7163-5c4b-8c4b-05876e9ba680', 'Curl interno de bíceps de pie con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.', 'Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.', 'Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps.', 'Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas.', 'Repite el número de repeticiones recomendado.']::text[], 'intermedio', 'Curl con agarre interno que enfatiza el bíceps y el antebrazo, útil para ganar volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2321'),
('33b527b3-c637-5191-aa0f-a98d1fbdd6b3', 'Patada de tríceps de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.', 'Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps con la extensión del codo, trabajando también el hombro para mantener la posición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0420'),
('7cc94f78-fb10-5260-914b-f21a7a3045ff', 'Elevación lateral de pie con mancuernas', ARRAY['De pie con una mancuerna en cada mano y los brazos ligeramente flexionados junto al cuerpo.', 'Eleva los brazos hacia los lados hasta la altura de los hombros, con los codos ligeramente doblados.', 'Baja las mancuernas despacio controlando el movimiento.', 'Evita encoger los hombros o usar impulso del tronco para subir el peso.']::text[], 'intermedio', 'Trabaja la porción lateral del deltoides para dar anchura al hombro y mejorar la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2234'),
('d6521d8d-236b-510f-b377-a1c58fc09f9d', 'Curl concentrado de pie a un brazo con mancuerna', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba.', 'Coloca la mano libre sobre el muslo para apoyarte.', 'Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Curl aislado a una mano que concentra la tensión en el bíceps y el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0421'),
('b597acc7-c604-5d1d-aa41-9c426cfd6643', 'Curl de pie a un brazo con mancuerna sobre banco inclinado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante.', 'Coloca la otra mano sobre un banco inclinado para apoyarte.', 'Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.', 'Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo.']::text[], 'intermedio', 'Curl a una mano apoyado en un banco inclinado que aísla el bíceps y el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0422'),
('4050f3e0-4364-5393-a3c6-f1689ceaa7ec', 'Press de pie a un brazo con palma hacia dentro y mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro.', 'Activa el core y mantén la espalda recta.', 'Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Press vertical a una mano que trabaja el hombro y el tríceps con apoyo del core para estabilizar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0424'),
('5b30dd82-d0a3-5143-a2d8-381a8f3c9b8a', 'Press de hombros de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.', 'Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los deltoides y el tren superior, mejorando la estabilidad del hombro y la fuerza al empujar por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0426'),
('9cabff40-6124-5ba2-a08a-961ba6ee1db9', 'Curl predicador de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.', 'Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con el brazo fijo, aumentando el pico del músculo y controlando el rango de movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0428');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('b2d975c4-02b9-5194-adf9-550b51a004b6', 'Curl inverso con rotación de pie con mancuernas', ARRAY['Sujeta las mancuernas con las palmas hacia abajo y los brazos extendidos junto al cuerpo.', 'Flexiona los codos llevando las mancuernas hacia los hombros sin mover los brazos.', 'Al subir, gira las muñecas hasta dejar las palmas hacia arriba y controla la bajada.', 'Baja despacio hasta la posición inicial y evita balancear el tronco para coger impulso.']::text[], 'intermedio', 'Trabaja los extensores de la muñeca y el antebrazo, mejorando el agarre y la estabilidad del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7056'),
('9bdc879c-8158-5a1c-9bf3-6f6e829743b9', 'Rotación escapular externa de pie con mancuerna', ARRAY['Colócate de pie con una mancuerna en la mano y el codo flexionado a 90 grados pegado al cuerpo.', 'Mantén el codo fijo y gira el antebrazo hacia fuera, separando la mano del abdomen.', 'Aprieta la escápula al final del recorrido y aguanta un segundo.', 'Vuelve despacio a la posición inicial sin despegar el codo del costado.']::text[], 'intermedio', 'Refuerza la parte alta de la espalda y el manguito rotador, mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7234'),
('dd77e4b2-0f66-5643-a4d4-14193a7208bf', 'Press Arnold a un brazo de pie con mancuerna', ARRAY['De pie, sujeta la mancuerna a la altura del hombro con la palma hacia ti y el codo flexionado.', 'Activa el abdomen y presiona la mancuerna hacia arriba girando la muñeca hasta la palma al frente.', 'Extiende el brazo sin bloquear del todo el codo y sin arquear la espalda.', 'Baja controlando el giro inverso hasta la posición inicial y repite sin balancearte.']::text[], 'intermedio', 'Trabaja el deltoides en varios ángulos y el core, mejorando la fuerza y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4833'),
('8cc37c7e-4ca6-547a-9cfd-c9e9ea7fe4e2', 'Curl de bíceps a un brazo de pie con mancuerna', ARRAY['De pie, sujeta la mancuerna con la palma hacia arriba y el brazo extendido junto al cuerpo.', 'Flexiona el codo llevando la mancuerna hacia el hombro sin mover el brazo del costado.', 'Aprieta el bíceps arriba y baja despacio controlando el movimiento.', 'Evita balancear el tronco o usar impulso para subir el peso.']::text[], 'intermedio', 'Aísla el bíceps de un brazo, corrigiendo desequilibrios y mejorando la fuerza y el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6757'),
('ea69d12c-4559-5cf4-aa15-4c105e3d24a1', 'Elevación cruzada a un brazo de pie con mancuerna', ARRAY['De pie, sujeta la mancuerna con la palma hacia dentro y el brazo ligeramente flexionado.', 'Eleva el brazo en diagonal cruzando el cuerpo hasta la altura del hombro contrario.', 'Controla la subida sin encoger el hombro ni arquear la espalda.', 'Baja despacio hasta la posición inicial y mantén el abdomen activo.']::text[], 'intermedio', 'Trabaja el pectoral y la parte anterior del hombro, mejorando la fuerza y el control en el plano cruzado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5458'),
('112ef48d-2715-55da-9006-6d764039db80', 'Curl araña a un brazo de pie con mancuerna', ARRAY['Inclínate ligeramente hacia delante con la espalda recta y deja colgar el brazo con la mancuerna.', 'Flexiona el codo llevando la mancuerna hacia el hombro sin mover el brazo.', 'Aprieta el bíceps arriba y baja despacio hasta extender el codo.', 'Evita balancear el tronco o encoger el hombro durante el recorrido.']::text[], 'intermedio', 'Aísla el bíceps con el brazo colgando, aumentando la tensión en la parte baja del músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4017'),
('c66bc48b-6bb9-59e7-ba22-5a38f0bb568e', 'Press de columna torácica en T de pie con mancuernas', ARRAY['De pie, sujeta una mancuerna en cada mano a la altura del pecho con los codos abiertos.', 'Extiende los brazos hacia delante y arriba formando una T, sin arquear la espalda.', 'Aprieta la escápula al final del movimiento y aguanta un segundo.', 'Vuelve despacio al pecho y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Mejora la movilidad y fuerza de la espalda alta, favoreciendo una postura erguida y hombros estables.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6964'),
('6dcdca6f-3b8e-503f-ab2b-3dc04137269e', 'Extensión de tríceps de pie con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.', 'Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto.', 'Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo.', 'Extiende el brazo de vuelta hacia arriba, hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el tríceps y mejora la extensión del codo, útil para empujar y estabilizar el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0430'),
('7703e5ec-bbaa-5185-bac3-abe99d54711d', 'Molino de pie con mancuerna', ARRAY['De pie con los pies separados, sujeta la mancuerna con un brazo extendido por encima de la cabeza.', 'Inclina el tronco hacia un lado llevando la mano libre hacia el pie contrario.', 'Mantén la mirada en la mancuerna y la espalda recta durante el descenso.', 'Sube despacio activando el abdomen y evita redondear la espalda.']::text[], 'intermedio', 'Trabaja el core y los oblicuos con movilidad de cadera y hombro, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4901'),
('1e34270f-363e-5cec-85df-528366032595', 'Curl de muñeca de pie con mancuernas', ARRAY['De pie, sujeta las mancuernas con las palmas hacia arriba y los brazos extendidos.', 'Flexiona solo las muñecas llevando las mancuernas hacia arriba sin mover los codos.', 'Aprieta el antebrazo arriba y baja despacio controlando el movimiento.', 'Evita balancear los brazos o usar impulso para subir el peso.']::text[], 'intermedio', 'Fortalece los flexores de la muñeca y el agarre, mejorando la fuerza en la mano y el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6359'),
('c138e500-bf2b-5f8c-9683-21b8dfd0e0ec', 'Curl de muñeca inverso de pie con mancuernas', ARRAY['De pie, sujeta las mancuernas con las palmas hacia abajo y los brazos extendidos.', 'Extiende las muñecas hacia arriba sin mover los codos ni los hombros.', 'Aprieta el antebrazo arriba y baja despacio hasta la posición inicial.', 'Evita balancear los brazos o encoger los hombros durante el movimiento.']::text[], 'intermedio', 'Trabaja los extensores de la muñeca y el agarre, equilibrando la fuerza del antebrazo y previniendo molestias.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6362'),
('4b7b32f1-6227-5186-b446-e51919145a52', 'Curl predicador Zottman de pie con mancuernas', ARRAY['Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.', 'Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados.', 'Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.', 'En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo.', 'Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina flexión y extensión de muñeca para trabajar bíceps y antebrazo, mejorando fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2293'),
('4deab614-5d92-5238-9b23-f77469adc995', 'Zancada estática con mancuernas', ARRAY['De pie con una mancuerna en cada mano y un pie adelantado, el otro atrás.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el talón delantero para volver a la posición inicial.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mejorando el equilibrio y la estabilidad de piernas y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4290'),
('f4ea9c43-2583-5d2c-83ef-9b4f7c3f3fb3', 'Zancada atrás con remo y mancuernas', ARRAY['De pie con una mancuerna en cada mano, da un paso atrás y baja la rodilla hacia el suelo.', 'Desde esa posición inclina el tronco y lleva las mancuernas hacia la cadera juntando las escápulas.', 'Baja las mancuernas con control y empuja con la pierna delantera para volver de pie.', 'Mantén la espalda recta y evita redondearla al remar.']::text[], 'intermedio', 'Combina piernas y espalda en un solo movimiento para ganar fuerza global y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4758'),
('b1d01497-a0c5-5de0-adde-9a6c9a902b9c', 'Paso lateral sobre cajón con mancuernas', ARRAY['Colócate de pie junto al cajón con una mancuerna en cada mano.', 'Sube un pie sobre el cajón y empuja para pasar por encima hasta el otro lado.', 'Apoya el pie libre con suavidad y controla la bajada sin dejarte caer.', 'Mantén el tronco erguido y evita girar la rodilla hacia dentro.']::text[], 'intermedio', 'Trabaja piernas y glúteos con un patrón lateral que mejora la estabilidad y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9612'),
('0143353e-887a-570f-b90d-0655800e2f53', 'Zancada con subida al cajón y mancuernas', ARRAY['Con una mancuerna en cada mano, da un paso atrás y baja la rodilla.', 'Impulsa con la pierna delantera y sube ese pie al cajón.', 'Extiende la cadera arriba y baja con control al suelo.', 'Mantén la rodilla alineada con el pie y no dejes que se meta hacia dentro.']::text[], 'intermedio', 'Encadena zancada y subida para trabajar cuádriceps y glúteos con gran demanda de equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2795'),
('8a9d540b-a2ab-5a9f-a2f7-a11b64089caf', 'Subida al cajón a una pierna con curl de bíceps', ARRAY['Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie.', 'Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho.', 'En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros.', 'Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo.', 'Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Suma un curl al equilibrio sobre una pierna para trabajar bíceps y estabilidad de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1684'),
('f67a0443-b96e-5d65-80da-bf4d1640774f', 'Subida al banco con mancuernas', ARRAY['Colócate de pie frente al banco con una mancuerna en cada mano.', 'Apoya un pie entero sobre el banco y empuja con esa pierna para subir.', 'Extiende la cadera arriba sin arquear la espalda y baja con control.', 'Evita impulsarte con la pierna de abajo o dar un salto.']::text[], 'intermedio', 'Ejercicio unilateral que fortalece cuádriceps y glúteos y mejora el equilibrio y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4986'),
('fc174089-379f-5dd2-be86-a74322b969ad', 'Subida al cajón con rodilla arriba y mancuernas', ARRAY['De pie frente al cajón con una mancuerna en cada mano.', 'Sube un pie al cajón y empuja para extender la cadera.', 'Arriba, eleva la rodilla contraria hacia el pecho sin perder el equilibrio.', 'Baja la pierna y el cuerpo con control, sin dejarte caer.']::text[], 'intermedio', 'Trabaja glúteos y core con una subida que añade elevación de rodilla y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4565'),
('a5595d29-867c-5c97-99ad-ac75104c0906', 'Sentadilla búlgara con subida al cajón y mancuernas', ARRAY['Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.', 'Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.', 'Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo.', 'Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho.', 'Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón.', 'Repite el movimiento con el pie izquierdo sobre el banco o escalón.', 'Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado.']::text[], 'intermedio', 'Combina sentadilla dividida y subida para exigir cuádriceps y glúteos con gran control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2812'),
('b1f8c855-eff8-5b27-964f-08ec413f912a', 'Peso muerto semirrígido con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas.', 'Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos e isquios con una bisagra de cadera que también cuida la espalda baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0432'),
('1f7f07b9-c7b8-5cb0-8b85-655fe743b166', 'Peso muerto rígido sobre banco con mancuernas', ARRAY['Colócate de pie sobre el banco con una mancuerna en cada mano.', 'Con las piernas casi rectas, lleva la cadera atrás y baja las mancuernas por delante de las piernas.', 'Nota el estiramiento en los isquios y sube apretando glúteos sin hiperextender la espalda.', 'Mantén las rodillas ligeramente flexionadas y evita redondear la zona lumbar.']::text[], 'intermedio', 'Aísla isquios y glúteos con un rango mayor al elevar el apoyo y mejora la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1556'),
('e0e4222e-46b4-52b4-85b6-c473b84f00b6', 'Balanceo de bíceps con brazos rectos y mancuernas', ARRAY['De pie con una mancuerna en cada mano y los brazos extendidos junto al cuerpo.', 'Balancea los brazos hacia delante y atrás manteniéndolos rectos.', 'Controla el rango y no uses impulso de la espalda para mover el peso.', 'Mantén el core activo y la mirada al frente durante todo el movimiento.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos con un movimiento dinámico que también activa hombros y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10949'),
('8a210dce-e75b-584d-a503-15f715de9446', 'Abdominal con brazos rectos y mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna con los brazos rectos sobre el pecho.', 'Eleva el tronco llevando las manos hacia las rodillas mientras espiras.', 'Baja con control sin dejar caer la espalda de golpe.', 'Evita tirar del cuello o usar impulso con los brazos.']::text[], 'intermedio', 'Refuerza el recto abdominal con brazos extendidos, aumentando la palanca y la exigencia del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4248'),
('2d427333-8551-56a0-b094-432e840e63a5', 'Pullover con brazos rectos y mancuerna', ARRAY['Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.', 'Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco.', 'Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira y fortalece pectoral y dorsal con un movimiento de hombro que amplía la movilidad torácica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0433'),
('31161d57-216b-59e5-9350-32a8ff715589', 'Abdominal con giro y brazos rectos con mancuerna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta una mancuerna con los brazos rectos.', 'Sube el tronco y gira el torso hacia un lado llevando la mancuerna junto a la cadera.', 'Vuelve al centro y repite hacia el otro lado con control.', 'Mantén el movimiento en el tronco y evita tirar del cuello.']::text[], 'intermedio', 'Trabaja recto abdominal y oblicuos con un giro que mejora la rotación y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4251'),
('fd00c39a-cf58-5e4e-b7b5-8aa016df0507', 'Peso muerto con piernas rectas y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante.', 'Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas.', 'Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos e isquios con una bisagra de cadera que también trabaja la espalda baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0434'),
('094fec1c-4b3e-575c-a74c-044d86d3334f', 'Giro ruso con piernas rectas y mancuerna', ARRAY['Siéntate en el suelo con las piernas extendidas y sujeta una mancuerna con ambas manos.', 'Inclina ligeramente el tronco atrás manteniendo la espalda recta.', 'Gira el torso a un lado y a otro llevando la mancuerna junto a la cadera.', 'Evita redondear la espalda y controla el ritmo sin balancearte.']::text[], 'intermedio', 'Activa oblicuos y core con una rotación sentado que mejora la estabilidad y la fuerza del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4249'),
('321f99fe-7e9b-5ce0-a555-66acaf621e56', 'Acarreo de maleta con mancuerna', ARRAY['Coge una mancuerna con una mano y colócala junto al muslo, como si llevaras una maleta.', 'Camina erguido con los hombros nivelados y el abdomen firme, sin inclinarte hacia el peso.', 'Respira con normalidad y mantén el paso controlado durante el recorrido.', 'Evita encoger el hombro o dejar caer el tronco hacia un lado para compensar.']::text[], 'intermedio', 'Fortalece glúteos, oblicuos y agarre mientras caminas cargando el peso a un lado, mejorando estabilidad y postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2910'),
('f5daec8f-8daf-5e48-8237-e229b8731a3d', 'Peso muerto sumo con mancuerna', ARRAY['Separa los pies más allá del ancho de los hombros y apunta las puntas hacia fuera.', 'Sujeta la mancuerna con ambas manos delante del cuerpo y baja la cadera con la espalda recta.', 'Empuja el suelo con los talones y extiende las caderas hasta quedar de pie apretando glúteos.', 'Evita redondear la espalda o tirar con los brazos en lugar de con las piernas.']::text[], 'intermedio', 'Trabaja glúteos y piernas con un movimiento de cadera que también refuerza lumbares y aductores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8192'),
('c64ce681-9ab4-5cd2-8ba7-abb445d5dff4', 'Pull through sumo con mancuerna', ARRAY['Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera.', 'Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos.', 'Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.', 'Baja la mancuerna entre las piernas, manteniendo los brazos rectos.', 'Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo.', 'Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos e isquios con un empuje de cadera que también exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2808'),
('5daeb679-df22-5df9-959f-4ac886287b05', 'Sentadilla sumo con mancuernas con balón en la pared', ARRAY['Apoya la espalda en el balón contra la pared y sujeta una mancuerna delante del pecho.', 'Separa los pies con las puntas hacia fuera y baja flexionando rodillas y caderas.', 'Empuja con los talones para subir mientras el balón rueda por la pared.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Refuerza cuádriceps y aductores con apoyo en el balón, ideal para aprender el patrón de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0435'),
('2afbb913-cea8-517f-9afb-6c50e7ded26c', 'Sentadilla sumo entre bancos con mancuerna', ARRAY['Colócate entre dos bancos con un pie en cada uno y sujeta la mancuerna delante del pecho.', 'Baja la cadera entre los bancos con el pecho alto y las puntas de los pies hacia fuera.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita bajar más de lo que controlas o perder la espalda neutra.']::text[], 'intermedio', 'Potencia glúteos y aductores con un rango profundo controlado entre dos apoyos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2431'),
('67cc7f4d-ca43-50c3-8c8f-8e1f89edb10d', 'Superman con mancuernas', ARRAY['Túmbate boca abajo con una mancuerna ligera en cada mano y los brazos estirados al frente.', 'Eleva a la vez brazos, pecho y piernas del suelo sin forzar el cuello.', 'Mantén uno o dos segundos arriba y baja con control respirando.', 'Evita arquear en exceso el cuello o levantar demasiado las piernas.']::text[], 'intermedio', 'Fortalece la musculatura de la espalda y los glúteos tumbado boca abajo, mejorando la extensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3454'),
('1cb99dad-cc03-5737-8ab2-ec910b998b2d', 'Sentadilla con apoyo y mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.', 'Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con ayuda de un apoyo para mantener el equilibrio y la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2803'),
('11999673-8d1b-58b7-9afc-be4969e6a0cd', 'Balanceo con mancuerna', ARRAY['De pie con los pies a la anchura de los hombros, sujeta la mancuerna con ambas manos delante.', 'Lleva la cadera atrás con la espalda recta y deja que la mancuerna baje entre las piernas.', 'Extiende la cadera con fuerza para impulsar la mancuerna hasta la altura del pecho.', 'Evita hacer el movimiento con los brazos o redondear la espalda.']::text[], 'intermedio', 'Genera potencia de cadera con glúteos e isquios, sumando trabajo de core y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3368'),
('d7d72774-9f56-5b3c-93ed-492f511c6142', 'Press Tate con mancuernas', ARRAY['Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí.', 'Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera.', 'Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros.', 'Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps tumbado con un movimiento de codos que también involucra los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0436'),
('e9e4ec79-ded7-5852-83a5-6feafc490ec8', 'Thruster con mancuernas', ARRAY['Sujeta una mancuerna en cada hombro con los codos altos y los pies a la anchura de los hombros.', 'Baja en sentadilla con el pecho alto y la espalda recta.', 'Sube con fuerza y empuja las mancuernas por encima de la cabeza al extender las piernas.', 'Evita perder la espalda neutra o bloquear los codos de golpe.']::text[], 'intermedio', 'Combina sentadilla y press para trabajar piernas, hombros y core en un gesto explosivo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2968'),
('43ef3a22-9886-5f52-bd1b-ab64ad2f9504', 'Patada de tríceps en postura de cigüeña con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.', 'Extiende el brazo derecho recto hacia atrás, apretando el tríceps.', 'Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Aísla el tríceps en equilibrio sobre una pierna, añadiendo control y estabilidad al gesto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1742'),
('e4b84973-a270-5be4-970e-4467c6dcf400', 'Apertura con giro y mancuernas', ARRAY['Túmbate con una mancuerna en cada mano y los brazos extendidos sobre el pecho.', 'Abre los brazos con los codos ligeramente flexionados hasta notar estiramiento en el pecho.', 'Al cerrar, gira las palmas hacia dentro juntando las mancuernas arriba.', 'Evita bajar demasiado los brazos o perder el control de la rotación.']::text[], 'intermedio', 'Trabaja el pecho con una apertura que suma rotación, implicando hombros y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4342'),
('f6902a9a-c5c0-509e-974a-92f74ea1dd2d', 'Press de banca con giro y mancuernas', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti.', 'Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.', 'Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento.', 'Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial.', 'Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza tríceps y pecho con un press que añade rotación para mayor control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1743'),
('99b39309-048b-5149-b251-27eb46a98687', 'Curl martillo sentado en balón con mancuernas', ARRAY['Siéntate en el balón con los pies firmes en el suelo y una mancuerna en cada mano.', 'Con las palmas mirándose, flexiona los codos llevando las mancuernas hacia los hombros.', 'Baja despacio controlando el movimiento y mantén el tronco erguido.', 'Evita balancear el cuerpo o mover los codos hacia delante.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos sentado en el balón, sumando trabajo de core por el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1681'),
('50d1f54f-34e3-5309-a729-0d7e577f455b', 'Elevación frontal con agarre supino y mancuernas', ARRAY['De pie con una mancuerna en cada mano y las palmas hacia arriba, brazos delante de los muslos.', 'Eleva los brazos estirados hasta la altura de los hombros sin balancear el tronco.', 'Baja con control respirando y mantén el abdomen firme.', 'Evita usar impulso de cadera o subir por encima de los hombros.']::text[], 'intermedio', 'Trabaja el deltoides frontal con un agarre que también implica pecho superior y bíceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11014'),
('7ad25126-ba69-560d-bec2-63f4675e1bf0', 'Remo renegado con agarre inverso y mancuernas', ARRAY['Colócate en plancha alta con una mancuerna en cada mano y los pies más abiertos que los hombros.', 'Mantén el tronco firme y tira de una mancuerna hacia la cadera con el codo pegado al cuerpo.', 'Baja la mancuerna con control y repite con el otro brazo sin balancear las caderas.', 'Evita rotar la cadera o arquear la zona lumbar durante el movimiento.']::text[], 'intermedio', 'Fortalece el core y la espalda mientras trabajas estabilidad y coordinación en posición de plancha con apoyo de mancuernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8222'),
('9bef3375-7af3-5f70-9487-aee75f866140', 'Elevación escapular unilateral con mancuerna', ARRAY['De pie con una mancuerna en una mano y el brazo relajado junto al cuerpo.', 'Eleva el hombro hacia la oreja sin doblar el codo ni encoger el cuello.', 'Mantén un segundo arriba y baja el hombro lentamente hasta la posición inicial.', 'Evita ayudarte con el torso o girar el tronco durante la elevación.']::text[], 'intermedio', 'Activa los trapecios y la parte alta de la espalda para mejorar el control y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6123'),
('063f2447-c408-5e2f-ad3d-92dece64dfac', 'Remo al mentón con mancuernas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.', 'Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos.', 'Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los deltoides y los trapecios para ganar fuerza y volumen en la parte superior del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0437'),
('7f7f57fc-6400-579a-aedb-04e312558ccd', 'Rotación externa de hombro de pie con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.', 'Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados.', 'Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición.', 'Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el manguito rotador y estabiliza el hombro para prevenir lesiones en empujes y presses.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0864'),
('0b4421d3-ad8f-5b75-b131-34458d92cc91', 'V up con mancuerna', ARRAY['Túmbate boca arriba con las piernas estiradas y una mancuerna sujeta con ambas manos.', 'Eleva a la vez el tronco y las piernas formando una V, con los brazos hacia delante.', 'Baja con control sin dejar caer la espalda de golpe y mantén el abdomen activo.', 'Evita tirar del cuello o usar impulso para subir.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con un gesto dinámico que mejora la coordinación y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3336'),
('42643168-6311-5a61-9fac-7b925829f183', 'Press en W con mancuernas', ARRAY['Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.', 'Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.', 'Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Baja las mancuernas de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los deltoides y el tríceps con un recorrido que también implica al pecho superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0438'),
('922324db-a06e-5a70-9ccb-8d08aa195f2e', 'Elevación de gemelos caminando con mancuernas', ARRAY['De pie con una mancuerna en cada mano y los pies a la anchura de las caderas.', 'Eleva los talones y camina unos pasos sobre las puntas sin perder el equilibrio.', 'Baja el talón con control en cada paso y mantén el abdomen activo.', 'Evita inclinarte hacia delante o dar pasos demasiado largos.']::text[], 'intermedio', 'Trabaja los gemelos y el sóleo con un gesto funcional que mejora la fuerza y el equilibrio en la marcha.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5698'),
('0d9d816b-3edf-5851-a11e-8afb2d9d2a93', 'Zancada caminando con mancuernas', ARRAY['De pie con una mancuerna en cada mano y el tronco erguido.', 'Da un paso largo y baja la rodilla trasera hasta rozar el suelo con control.', 'Empuja con la pierna delantera para avanzar y repite con la otra pierna.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón de marcha que mejora el equilibrio y la estabilidad de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4295'),
('14dd1683-28de-595b-9b34-ab6937154598', 'Sentadilla en la pared con mancuernas', ARRAY['Apoya la espalda en la pared y coloca una mancuerna sobre los muslos o sujétala con ambas manos.', 'Desliza la espalda hacia abajo hasta que los muslos queden paralelos al suelo.', 'Mantén la posición con la respiración controlada y los pies bien apoyados.', 'Evita que las rodillas se junten o que los talones se levanten.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos en isométrico, mejorando la resistencia muscular y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1558'),
('20f33075-1118-5657-9b32-13d5f3975997', 'Rotación de muñeca con mancuerna', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la mano sujetando una mancuerna.', 'Gira la muñeca hacia dentro y hacia fuera con un recorrido corto y controlado.', 'Mantén el codo fijo y respira de forma constante durante las repeticiones.', 'Evita usar un peso excesivo que obligue a mover el antebrazo.']::text[], 'intermedio', 'Fortalece los antebrazos y la muñeca para mejorar el agarre y prevenir molestias en movimientos de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10817'),
('96f91a52-2646-57e8-8033-1db98a8b4df8', 'Supinación de muñeca con mancuerna', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la mancuerna en la mano.', 'Gira la palma hacia arriba y hacia abajo de forma lenta y controlada.', 'Mantén el codo pegado al cuerpo y la muñeca alineada con el antebrazo.', 'Evita compensar con el hombro o hacer movimientos bruscos.']::text[], 'intermedio', 'Trabaja los rotadores del antebrazo y la muñeca para mejorar el control y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10038'),
('a37245a2-56c4-55df-be08-b61b80867b2b', 'Press z con mancuernas', ARRAY['Siéntate en el suelo con las piernas cruzadas y una mancuerna en cada mano a la altura de los hombros.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos sin bloquear del todo los codos.', 'Baja con control hasta la altura de los hombros manteniendo el tronco erguido.', 'Evita arquear la espalda o perder la posición de las piernas.']::text[], 'intermedio', 'Fortalece los hombros y el core en posición sentada, mejorando la estabilidad y la fuerza del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5667'),
('285398cb-0439-5ae7-8039-4e7a9f1cb777', 'Curl predicador Zottman con mancuernas', ARRAY['Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla.', 'Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba.', 'En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo.', 'Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps y los antebrazos con un giro que combina flexión y rotación para ganar fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2294'),
('83e42462-3e6a-5881-ab56-8eea415d9f1b', 'Puente de glúteos con mancuernas', ARRAY['Túmbate boca arriba con las rodillas dobladas y una mancuerna apoyada sobre la cadera.', 'Empuja con los talones y eleva la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja con control sin apoyar del todo la cadera.', 'Evita arquear la zona lumbar o empujar con los brazos.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales para mejorar la extensión de cadera y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4887'),
('a2e522c3-8c6a-5633-801f-56535e74ca5d', 'Pullover con brazos rectos y mancuernas', ARRAY['Túmbate en un banco o en el suelo con una mancuerna sujeta con ambas manos sobre el pecho.', 'Lleva los brazos estirados hacia atrás hasta notar el estiramiento del dorsal.', 'Vuelve a la posición inicial con control sin doblar los codos.', 'Evita arquear la espalda o bajar demasiado si notas molestia en el hombro.']::text[], 'intermedio', 'Trabaja el dorsal ancho y el pecho con un recorrido que mejora la movilidad del hombro y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2365'),
('f720ba80-6f7c-595e-a1db-6e90441c23b9', 'Estiramiento dinámico de espalda', ARRAY['Colócate de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Lleva los brazos hacia delante y cruza uno sobre otro mientras redondeas la espalda.', 'Abre después los brazos hacia atrás buscando juntar las escápulas sin forzar.', 'Acompaña el movimiento con una respiración lenta y evita arquear la zona lumbar.']::text[], 'principiante', 'Activa dorsales, zona alta de la espalda y oblicuos para preparar el tren superior antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4671'),
('2230c2d0-b5ad-51d3-8bc7-c1eae56f545a', 'Estiramiento dinámico de pecho', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Extiende los brazos hacia los lados, paralelos al suelo.', 'Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo.', 'Siente el estiramiento en los músculos del pecho.', 'Mantén el estiramiento durante 10-30 segundos.', 'Vuelve a la posición inicial y repite el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza pecho, hombro y tríceps antes de entrenar, mejorando amplitud y preparación articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1167'),
('a72f200b-ced9-5240-b590-f9d6c833ee7a', 'Postura del águila', ARRAY['Ponte de pie y cruza un muslo sobre el otro enganchando el pie por detrás de la pantorrilla.', 'Entrelaza los brazos delante del pecho con los codos flexionados y las palmas juntas.', 'Baja ligeramente las caderas como si fueras a sentarte y mantén la espalda larga.', 'Respira despacio y evita bloquear la rodilla de apoyo para no perder el equilibrio.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps mientras mejora el equilibrio y la movilidad de hombros y tobillos.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6301'),
('4494c2eb-4759-5c80-9094-c6286dc1a90a', 'Dominada excéntrica a un brazo', ARRAY['Agárrate a la barra con una mano y colócate arriba con ayuda de la otra o de un salto.', 'Suelta la mano de apoyo y baja el cuerpo de forma lenta y controlada.', 'Mantén el core firme y el hombro activo para no colgarte de golpe.', 'Evita dejarte caer sin control; si pierdes la técnica, vuelve a usar las dos manos.']::text[], 'intermedio', 'Trabaja dorsales y agarre con una bajada controlada a un solo brazo para ganar fuerza.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10902'),
('f2abc9e8-3d35-5049-bc14-dae7e7e5d44b', 'Salto de puntas en cama elástica', ARRAY['Colócate en el centro de la cama elástica con los pies juntos y el cuerpo erguido.', 'Impúlsate solo con los tobillos haciendo saltos bajos y rápidos.', 'Aterriza con la planta del pie y mantén las rodillas ligeramente flexionadas.', 'Evita saltar demasiado alto o perder el centro para no caerte.']::text[], 'intermedio', 'Activa gemelos y sóleo con saltos cortos que mejoran la reactividad y la elasticidad del tobillo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10890'),
('72a72e24-f426-584b-adb5-055ac8a0fe8f', 'Círculos de brazos con codos', ARRAY['Ponte de pie con los brazos extendidos a los lados a la altura de los hombros.', 'Flexiona ligeramente los codos y dibuja círculos pequeños hacia delante.', 'Ve ampliando el círculo poco a poco sin subir los hombros hacia las orejas.', 'Cambia el sentido de giro y evita movimientos bruscos o dolorosos.']::text[], 'principiante', 'Moviliza hombros y manguito rotador para calentar el tren superior antes de cargar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0256'),
('39a64d1a-3adf-552e-8cf4-177d46aad39e', 'Fondos de codos', ARRAY['Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.', 'Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo.', 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.', 'Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombro con el peso corporal en un patrón de empuje básico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3287'),
('931c915c-78c0-5f14-bb0e-a49fbf88c590', 'Extensión de codo', ARRAY['Siéntate o ponte de pie con el brazo pegado al cuerpo y el codo flexionado.', 'Extiende el codo despacio hasta estirar el brazo del todo sin bloquear.', 'Vuelve a flexionar de forma controlada y repite sin balancear el hombro.', 'Evita forzar si notas pinchazo en el codo o en el tendón.']::text[], 'principiante', 'Moviliza el tríceps y el antebrazo para recuperar rango en el codo tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2763'),
('7742fcf8-3526-50da-b161-c1c9f28c5680', 'Estiramiento de antebrazo con supinación y pronación', ARRAY['Extiende un brazo al frente con el codo recto y la palma hacia arriba.', 'Con la otra mano lleva la muñeca hacia abajo hasta notar el estiramiento.', 'Gira la palma hacia abajo y repite el estiramiento manteniendo el codo estirado.', 'Respira con calma y evita tirar con fuerza brusca de la muñeca.']::text[], 'principiante', 'Estira flexores y extensores de muñeca y alivia la tensión acumulada en el antebrazo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1821'),
('0c8c97f4-78d8-585a-80ea-7159e9fcfa90', 'Estiramiento de extensores del codo y ancóneo', ARRAY['Levanta un brazo y flexiona el codo llevando la mano hacia la nuca.', 'Con la otra mano empuja suavemente el codo hacia abajo sin forzar.', 'Mantén el hombro relajado y respira de forma pausada durante el estiramiento.', 'Evita arquear la espalda o tirar del codo con rebotes.']::text[], 'principiante', 'Relaja el tríceps y la zona del ancóneo para descargar el codo después de empujar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1830'),
('4ae07805-75f4-5712-9fa1-fa57e2fed095', 'Flexión de codo', ARRAY['Ponte de pie con los brazos relajados a los lados y las palmas hacia delante.', 'Flexiona los codos llevando las manos hacia los hombros de forma lenta.', 'Aprieta ligeramente el bíceps arriba y baja controlando el movimiento.', 'Evita balancear el tronco o subir los hombros para completar la flexión.']::text[], 'principiante', 'Moviliza bíceps y braquial para mantener el rango articular del codo sin carga.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2764'),
('8c239267-32ac-5467-bff7-6070270ec0ca', 'Estiramiento de flexores del codo', ARRAY['Extiende un brazo hacia atrás con la palma mirando hacia delante.', 'Gira el hombro hacia dentro y mantén el codo recto sin bloquearlo.', 'Nota el estiramiento en la parte delantera del brazo y respira despacio.', 'Evita forzar el hombro o encogerlo durante el estiramiento.']::text[], 'principiante', 'Estira bíceps y braquial para aliviar la tensión del codo y del hombro tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1814'),
('a35c4fab-7062-5d30-8125-424a9e74511b', 'Elevación de codos en flexión inversa', ARRAY['Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros.', 'Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados.', 'Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta.', 'Baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los tríceps con un empuje invertido que mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1772'),
('90e74b7b-6295-53ee-80ff-67561d43d95b', 'Estiramiento de rotadores con codo hacia fuera', ARRAY['Lleva un brazo cruzado delante del pecho con el codo flexionado.', 'Con la otra mano tira suavemente del codo hacia el hombro contrario.', 'Mantén el hombro bajo y la espalda recta mientras respiras despacio.', 'Evita girar el tronco o tirar con fuerza excesiva del codo.']::text[], 'principiante', 'Estira el hombro y el manguito rotador para mejorar la movilidad y prevenir molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1985'),
('7905d549-d0eb-5f3b-8158-f138546c9ee9', 'Planche de codos', ARRAY['Colócate en cuadrupedia con los antebrazos apoyados y los codos bajo los hombros.', 'Inclina el peso hacia delante poco a poco mientras aprietas el core y los glúteos.', 'Mantén la posición sin hundir la zona lumbar y respirando de forma controlada.', 'Evita cargar demasiado las muñecas; si duelen, reduce la inclinación.']::text[], 'avanzado', 'Isométrico avanzado que carga hombros, core y tríceps para progresar hacia la planche.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10665'),
('8f3f9303-16a7-591e-b397-0f0a5997964b', 'Flexión sobre codos', ARRAY['Colócate boca abajo apoyando antebrazos y puntas de los pies.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Aprieta el abdomen y los glúteos sin hundir la cadera.', 'Respira con normalidad evitando aguantar la respiración.', 'No dejes caer la cabeza ni eleves el culo por encima de la línea.']::text[], 'intermedio', 'Trabaja el abdomen y el core estabilizando la cadera mientras apoyas los antebrazos, ideal para ganar control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3266'),
('70edd2e0-6f66-59d5-9939-8d384706d1a9', 'Plancha lateral con codo a rodilla', ARRAY['Apóyate de lado sobre un antebrazo con los pies apilados.', 'Eleva la cadera hasta formar una línea recta con el cuerpo.', 'Lleva la rodilla de arriba hacia el codo del apoyo.', 'Vuelve a estirar la pierna sin perder la alineación.', 'Evita rotar el tronco hacia atrás durante el movimiento.']::text[], 'intermedio', 'Activa oblicuos y abdomen en plancha lateral llevando el codo hacia la rodilla, mejorando estabilidad y control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3503'),
('04a66b16-8f31-597b-8eaa-e44d3c7568a3', 'Abdominal con codo a rodilla', ARRAY['Túmbate boca arriba con las rodillas flexionadas y manos en la nuca.', 'Eleva el tronco llevando el codo derecho hacia la rodilla izquierda.', 'Baja despacio y repite hacia el lado contrario.', 'Exhala al subir e inhala al bajar.', 'No tires del cuello con las manos ni uses impulso.']::text[], 'intermedio', 'Flexiona el tronco llevando el codo a la rodilla contraria para trabajar abdomen y oblicuos con control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3484'),
('a4747930-036c-5d75-9bd1-b896bf3341cb', 'Giros de codo a rodilla', ARRAY['De pie, eleva una rodilla mientras llevas el codo contrario hacia ella.', 'Alterna los lados a un ritmo constante y controlado.', 'Mantén el abdomen apretado y la espalda recta.', 'Respira de forma rítmica sin bloquear el aire.', 'Evita encorvar la espalda o tirar del cuello.']::text[], 'intermedio', 'Ejercicio dinámico que activa abdomen y oblicuos con rotación, útil como calentamiento o trabajo cardiovascular ligero.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3086'),
('0ecb14a6-54df-57de-97d6-2ffe5e7d3b50', 'Plancha dinámica subiendo y bajando de codos', ARRAY['Comienza en plancha alta con manos bajo los hombros.', 'Baja un codo y luego el otro hasta apoyar los antebrazos.', 'Vuelve a subir a plancha alta empujando con las manos.', 'Mantén la cadera estable sin balancearte.', 'Evita hundir la zona lumbar durante el cambio.']::text[], 'intermedio', 'Alterna entre plancha alta y baja para reforzar abdomen, hombros y tríceps mejorando la estabilidad general.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2978'),
('f30c4e0a-7b6b-5ea1-8577-cfca1697e1ca', 'Codo a rodilla', ARRAY['Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.', 'Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial.', 'Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Movimiento de flexión y rotación que activa abdomen y oblicuos, sencillo para trabajar el core en cualquier lugar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0443'),
('d55fcd5d-fe2d-551f-9c42-05ac3a4725a8', 'Estiramiento de codos hacia atrás', ARRAY['De pie, entrelaza las manos detrás de la espalda.', 'Estira los brazos y lleva los codos hacia atrás.', 'Abre el pecho y mantén la postura sin arquear la lumbar.', 'Respira profundo y sostén entre veinte y treinta segundos.', 'Evita encoger los hombros hacia las orejas.']::text[], 'principiante', 'Abre el pecho y los hombros llevando los codos atrás, aliviando tensión tras entrenar empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4672'),
('35aeb45c-5f01-525a-adab-e3d297108d69', 'Remo invertido elevado entre tres sillas', ARRAY['Coloca tres sillas estables y sujeta el borde con las manos.', 'Cuélgate con el cuerpo recto y los talones en el suelo.', 'Tira del pecho hacia las manos apretando la espalda.', 'Baja despacio controlando el movimiento.', 'Evita encoger los hombros o usar impulso de cadera.']::text[], 'intermedio', 'Tira del cuerpo desde una barra improvisada para fortalecer espalda alta, dorsales y bíceps con control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3536'),
('7b5f1e58-a031-5db9-ab64-210632be9b10', 'Remo invertido elevado con agarre supino entre tres sillas', ARRAY['Sujeta el borde de las sillas con las palmas mirando hacia ti.', 'Mantén el cuerpo recto y los pies apoyados.', 'Tira del pecho hacia las manos juntando las escápulas.', 'Baja de forma lenta y controlada.', 'No dejes caer la cadera ni bloquees la respiración.']::text[], 'intermedio', 'Variante con palmas hacia arriba que enfatiza dorsales y bíceps, mejorando fuerza de tracción horizontal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3537'),
('e5566ea5-38af-5c3d-b11e-7cf2b2970e52', 'Flexión elevada', ARRAY['Apoya las manos en una superficie elevada y estable.', 'Coloca el cuerpo en línea recta con los pies atrás.', 'Baja el pecho hacia la superficie flexionando los codos.', 'Empuja para volver arriba sin bloquear los codos.', 'Evita que la cadera se hunda o se eleve demasiado.']::text[], 'intermedio', 'Flexión con manos en altura que reduce la carga y permite trabajar pecho, tríceps y hombros con buena técnica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3812'),
('cfd7697a-b867-55da-8d9a-1a205fe54d69', 'Elevación de gemelos sentado sobre elevación', ARRAY['Siéntate con los pies sobre una superficie elevada y estable.', 'Deja los talones al aire y las puntas apoyadas.', 'Eleva los talones lo máximo posible apretando los gemelos.', 'Baja despacio hasta estirar bien la pantorrilla.', 'Evita rebotar o hacer el movimiento con prisa.']::text[], 'intermedio', 'Fortalece gemelos y sóleo elevando los talones sentado, útil para resistencia y estabilidad del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4900'),
('07b756a4-95d0-55e8-a266-381fea71d224', 'Zancada lateral elevada', ARRAY['Coloca un pie sobre una superficie elevada y estable.', 'Da un paso lateral amplio con la otra pierna.', 'Flexiona la rodilla de la pierna elevada llevando la cadera atrás.', 'Empuja con el talón para volver al centro.', 'Evita que la rodilla pase por delante de la punta del pie.']::text[], 'intermedio', 'Desplaza el peso a un lado sobre una superficie elevada para trabajar glúteos, cuádriceps y aductores.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5310'),
('15db5843-1fea-55b6-ab1d-2864bf5f7c97', 'Puente a una pierna elevado', ARRAY['Túmbate con la espalda apoyada y un pie sobre una superficie elevada.', 'Extiende la otra pierna en el aire.', 'Empuja con el talón para elevar la cadera.', 'Aprieta el glúteo arriba y baja despacio.', 'Evita arquear la lumbar o rotar la cadera.']::text[], 'intermedio', 'Extiende la cadera con una sola pierna sobre altura para activar glúteos, isquios y estabilidad lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10549'),
('0f50d265-8cd1-5452-adf4-a01110f83307', 'Empuje de cadera a una pierna elevado', ARRAY['Apoya la espalda alta en una superficie elevada y estable.', 'Coloca un pie en el suelo y extiende la otra pierna.', 'Empuja con el talón elevando la cadera hasta alinear el cuerpo.', 'Baja controlando sin dejar caer la pelvis.', 'Evita hiperextender la espalda al subir.']::text[], 'intermedio', 'Empuje de cadera con una pierna sobre altura que refuerza glúteos e isquios y mejora el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4902'),
('cc6ae4e7-5ead-509e-90d5-ce68877732c4', 'Sentadilla a una pierna elevada', ARRAY['Coloca un pie sobre una superficie elevada y estable.', 'Baja flexionando la rodilla llevando la cadera atrás.', 'Mantén la rodilla alineada con el pie.', 'Empuja con el talón para subir controlando el equilibrio.', 'Evita que la rodilla se hunda hacia dentro.']::text[], 'intermedio', 'Sentadilla unilateral con pie elevado que exige fuerza de cuádriceps, glúteos y equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4892'),
('179231ba-3db3-5af8-ab4c-8c79caf5f6e5', 'Zancada búlgara', ARRAY['Coloca el empeine del pie trasero sobre un banco o superficie elevada y da un paso al frente con el otro pie.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido y la rodilla delantera alineada con el pie.', 'Empuja con la pierna delantera para volver a la posición inicial sin bloquear la rodilla.', 'Inspira al bajar y espira al subir, controlando el descenso.', 'Evita que la rodilla delantera se vaya hacia dentro o que el torso se incline en exceso.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una pierna elevada, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9315'),
('6fe185c3-d206-5573-8f74-055833bfe332', 'Elevación de gemelos de pie sobre elevación', ARRAY['Colócate de pie con la punta de los pies sobre un escalón y los talones en el aire.', 'Sube los talones lo máximo posible manteniendo las rodillas ligeramente flexionadas.', 'Baja lentamente hasta sentir el estiramiento en la pantorrilla sin rebotar.', 'Espira al subir e inspira al bajar, con un tempo controlado.', 'Evita balancear el cuerpo o usar impulso para subir.']::text[], 'intermedio', 'Tonifica los gemelos y el sóleo, mejorando la fuerza del tobillo y la estabilidad en la marcha y la carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4760'),
('040eb490-ed35-51ac-a0fe-372d63f56f49', 'Elevación de gemelos a una pierna', ARRAY['Apóyate en una pared o superficie estable y coloca la punta de un pie sobre un escalón.', 'Eleva el talón lo máximo posible manteniendo la rodilla ligeramente flexionada.', 'Baja despacio hasta notar el estiramiento en la pantorrilla sin perder el equilibrio.', 'Espira al subir e inspira al bajar, manteniendo el core activo.', 'Evita girar la cadera o apoyar el pie libre para ayudarte.']::text[], 'intermedio', 'Aumenta la fuerza y el control de gemelos y sóleo con una sola pierna, corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4761'),
('3b528a03-e3d7-53dc-8a43-796d106cd439', 'Hip thrust elevado', ARRAY['Apoya la parte alta de la espalda en un banco o superficie elevada y flexiona las rodillas con los pies en el suelo.', 'Empuja con los talones para elevar la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja de forma controlada sin apoyar del todo la cadera.', 'Espira al subir e inspira al bajar, manteniendo el core activo.', 'Evita arquear la zona lumbar en exceso o empujar con la punta de los pies.']::text[], 'intermedio', 'Activa glúteos e isquios con un empuje de cadera desde una superficie elevada, mejorando la extensión de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7413'),
('5f7dc45e-c539-517d-9971-86f61413ac78', 'Elevador', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Coloca las manos sobre las caderas o crúzalas frente al pecho.', 'Manteniendo la espalda recta, inclínate lentamente hacia adelante desde la cintura, bajando la parte superior del cuerpo hacia el suelo.', 'Haz una pausa por un momento en la posición más baja, luego sube lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda alta y los trapecios con un movimiento de retracción escapular, mejorando la postura y la estabilidad del hombro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3292'),
('1df1d8c2-105e-5520-b8f8-5dd0acfc1196', 'Esquí en elíptica', ARRAY['Súbete a la elíptica y agarra las asas móviles con un agarre cómodo.', 'Empuja y tira de las asas coordinando el movimiento con las piernas, como si esquiaras.', 'Mantén el torso erguido y el core activo durante todo el recorrido.', 'Respira de forma rítmica y constante, ajustando la resistencia a tu nivel.', 'Evita encorvar la espalda o bloquear las rodillas en la extensión.']::text[], 'principiante', 'Mejora la resistencia cardiovascular con un movimiento de esquí que implica glúteos, cuádriceps e isquios.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2658'),
('8d0462f9-a678-571e-b493-12998f46829b', 'Caminata en elíptica', ARRAY['Súbete a la elíptica y coloca los pies en las plataformas con las asas a mano.', 'Camina con un movimiento fluido, empujando con los talones y manteniendo el torso erguido.', 'Ajusta la resistencia y la inclinación para mantener una intensidad constante.', 'Respira de forma rítmica y relajada durante todo el ejercicio.', 'Evita apoyarte en las asas o encorvar los hombros.']::text[], 'principiante', 'Activa el sistema cardiovascular con un movimiento de marcha que implica cuádriceps, glúteos e isquios.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2192'),
('c9598306-4d5a-5fb6-9b5b-ddf34efc61f4', 'Elevaciones alternas de brazos en balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas hacia adentro y los brazos extendidos hacia abajo a los lados.', 'Activa el core y levanta lentamente un brazo hacia el hombro, manteniendo el codo ligeramente flexionado.', 'Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.', 'Repite el movimiento con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece dorsales y hombros mientras el core estabiliza el cuerpo sobre el balón, mejorando el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1332'),
('5df289e9-d98a-5658-92e0-4c3a33be3c7c', 'Extensión de espalda con brazos extendidos en balón', ARRAY['Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.', 'Extiende los brazos rectos hacia adelante, con las palmas hacia abajo.', 'Activa el core y levanta lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta y el cuello alineado con la columna.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la musculatura de la columna y los glúteos, mejorando la extensión y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1333'),
('79ffe273-0b9c-53bc-8ac6-74416865295d', 'Extensión de espalda con manos en la nuca en balón', ARRAY['Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él con las caderas apoyadas en el balón.', 'Coloca los pies contra una pared u otra superficie estable para apoyarte.', 'Cruza los brazos detrás de la cabeza, con las manos tocando la parte de atrás de la cabeza.', 'Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta las caderas.', 'Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda y los glúteos con las manos en la nuca, aumentando la extensión y el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1334'),
('85ed84cf-c989-5c03-9f6c-df20b0c007cd', 'Extensión de espalda con rodillas elevadas en balón', ARRAY['Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad.', 'Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Incrementa la exigencia sobre la columna y los glúteos al separar las rodillas del suelo, mejorando la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1335'),
('05606308-2663-5aa2-887d-d974545b71ab', 'Extensión de espalda con rotación en balón', ARRAY['Comienza tumbado boca abajo sobre el balón de estabilidad, con las caderas apoyadas en el balón y los pies firmemente apoyados en el suelo.', 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.', 'Haz una pausa por un momento en la parte superior, luego gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables.', 'Vuelve al centro y repite el giro hacia el otro lado.', 'Baja la parte superior del cuerpo de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'principiante', 'Combina extensión y rotación del tronco para trabajar la columna, los glúteos y la musculatura estabilizadora.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1336'),
('c55c8af9-dfe1-5fdb-96b1-ad76c017b133', 'Estiramiento de espalda en balón', ARRAY['Siéntate sobre el balón y camina hacia delante hasta apoyar la espalda y los hombros.', 'Extiende los brazos hacia atrás y deja que el pecho se abra, sintiendo el estiramiento.', 'Mantén la postura entre 20 y 30 segundos respirando de forma profunda y relajada.', 'Sal despacio apoyando las manos en el suelo para volver a sentarte.', 'Evita forzar la zona lumbar o aguantar la respiración.']::text[], 'principiante', 'Relaja dorsales y zona lumbar, aliviando la tensión acumulada y mejorando la movilidad de la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1337'),
('9c7e4a70-e654-517f-b47d-50401ca0a888', 'Fondos en balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante.', 'Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos.', 'Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece tríceps y pecho con un movimiento de fondos sobre el balón, mejorando la estabilidad del hombro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1744'),
('00abf552-5c76-57a0-865b-653413290270', 'Abdominal de rana en balón', ARRAY['Apoya la espalda baja sobre el balón y coloca las manos detrás de la cabeza.', 'Junta las plantas de los pies y deja caer las rodillas hacia los lados, como una rana.', 'Encoge el torso hacia delante acercando las costillas a la pelvis.', 'Espira al encoger e inspira al volver, con un movimiento lento y controlado.', 'Evita tirar del cuello con las manos o usar impulso.']::text[], 'principiante', 'Trabaja el abdomen y la zona baja con un encogimiento en balón, mejorando la fuerza y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2469'),
('918e9545-29c1-57a9-865e-107eadc15f58', 'Estiramiento de flexor de cadera en balón', ARRAY['Coloca el balón de estabilidad en el suelo y arrodíllate frente a él.', 'Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados.', 'Extiende la pierna izquierda hacia atrás, manteniéndola recta.', 'Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha.', 'Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.']::text[], 'principiante', 'Estira la cadera y el psoas para aliviar la tensión de estar sentado y mejorar la extensión de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1559'),
('aab715a3-bbee-5620-bd74-c69292bf4c58', 'Abrazo de balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta.', 'Sujeta el balón de estabilidad con ambas manos, abrazándolo cerca del pecho.', 'Activa los músculos del core y reclínate lentamente hacia atrás, manteniendo la espalda recta y los pies apoyados en el suelo.', 'Continúa reclinándote hacia atrás hasta sentir un estiramiento en los músculos de la espalda.', 'Mantén la posición durante unos segundos, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Relaja la columna y abre la espalda alta y el pecho, útil para descargar la zona dorsal tras el estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1338'),
('eff1db13-1700-57d3-b721-4bd58a8b71e9', 'Estiramiento de dorsales en balón', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.', 'Sujeta una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.', 'Inclínate lentamente hacia el lado opuesto, sintiendo un estiramiento en el músculo dorsal.', 'Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.', 'Repite del otro lado.']::text[], 'principiante', 'Alarga los dorsales y los hombros para ganar amplitud en los brazos por encima de la cabeza.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1339'),
('8b7d0d05-253a-5761-aa0c-727c34674dc7', 'Curl femoral con balón', ARRAY['Túmbate boca arriba con los talones apoyados encima del balón y los brazos junto al cuerpo.', 'Eleva la cadera del suelo apretando los glúteos para formar una línea recta.', 'Flexiona las rodillas acercando el balón hacia los glúteos sin dejar caer la cadera.', 'Estira las piernas despacio hasta la posición inicial controlando el movimiento.', 'Evita arquear la zona lumbar: mantén el abdomen firme durante todo el recorrido.']::text[], 'principiante', 'Fortalece los isquiotibiales y glúteos mientras el core estabiliza la cadera sobre la pelota.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5036'),
('26dc9106-3b2c-52a9-b567-27fb8b6fdf80', 'Estiramiento de espalda baja boca abajo en balón', ARRAY['Coloca el abdomen sobre el balón con los pies apoyados en el suelo para estabilizarte.', 'Deja caer el tronco hacia delante abrazando el balón con los brazos.', 'Relaja los hombros y respira profundo dejando que la espalda se alargue.', 'Mantén la postura entre veinte y treinta segundos sin forzar la lumbar.', 'Evita levantar la cabeza: deja el cuello en línea con la columna.']::text[], 'principiante', 'Descomprime la columna y relaja la musculatura lumbar y dorsal tras sesiones de carga.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1340'),
('950ea3b3-2e56-5b35-9e14-f0be6d7c21b4', 'Estiramiento lumbar en pirámide sobre balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Camina lentamente hacia adelante con los pies, haciendo rodar el balón por tu espalda hasta que tu zona lumbar quede apoyada sobre el balón.', 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, permitiendo que tu zona lumbar se estire sobre el balón.', 'Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira la espalda baja, los glúteos y los isquiotibiales, ayudando a descargar la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1341'),
('1153602c-2472-554b-89f7-e223ae4b46f8', 'Estiramiento de abductores tumbado en balón', ARRAY['Túmbate de lado con la cadera apoyada sobre el balón y el pie de abajo en el suelo.', 'Deja caer la pierna superior hacia el suelo buscando el estiramiento sin rebotes.', 'Mantén la pelvis estable y respira de forma pausada durante la posición.', 'Sostén entre veinte y treinta segundos y cambia de lado.', 'Evita girar el tronco hacia atrás para no perder el estiramiento.']::text[], 'principiante', 'Relaja la cara interna del muslo y los glúteos, mejorando la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1883'),
('df53b55f-5448-5e60-8af9-328a958a77d2', 'Estiramiento lateral de dorsales tumbado en balón', ARRAY['Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el balón de estabilidad.', 'Coloca el brazo de arriba sobre el balón para mantener la estabilidad.', 'Extiende el brazo de arriba por encima de la cabeza y permite que tu torso gire ligeramente.', 'Siente el estiramiento en los músculos dorsales del costado de tu cuerpo.', 'Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.']::text[], 'principiante', 'Abre el costado y el dorsal para mejorar la movilidad del hombro y descargar la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1342'),
('5de61a35-b285-5b0a-99c4-e03c70f533b3', 'Elevación de gemelos en balón contra la pared', ARRAY['Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.', 'Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante.', 'Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.', 'Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y mejora el equilibrio del tobillo, útil para correr y subir escaleras.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1382'),
('af4e0cd0-ecc3-5e00-b534-3badc3900d0f', 'Elevación de gemelos en balón contra la pared con pelota entre tobillos', ARRAY['Ponte de pie frente a una pared con los pies separados a la altura de los hombros.', 'Coloca un balón de ejercicio entre la pared y tu zona lumbar.', 'Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.', 'Coloca una pelota de tenis entre los tobillos.', 'Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza los gemelos con mayor control del tobillo al mantener la pelota entre las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3241'),
('8e253ac6-e9fc-50d7-86df-ffaaec1c18e1', 'Rotación de tren inferior a una pierna boca abajo en balón', ARRAY['Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.', 'Coloca las manos en el suelo frente a ti para mayor apoyo.', 'Activa los glúteos y el abdomen para estabilizar el cuerpo.', 'Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso.', 'Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables.', 'Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial.', 'Repite la rotación con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja glúteos y core con control del equilibrio sobre el balón, mejorando la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1416'),
('b2215b05-dd6f-5b2a-b74e-1318b3e93d23', 'Curl femoral con patada diagonal a una pierna en balón', ARRAY['Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad.', 'Coloca los brazos a los lados del cuerpo para mantener el equilibrio.', 'Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones.', 'Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión.', 'Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales.', 'Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio.', 'Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa glúteos e isquiotibiales con una patada diagonal que exige control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1417'),
('0e9d21e9-2353-5576-844a-8e3d00079313', 'Elevación de piernas boca abajo en balón', ARRAY['Túmbate boca abajo sobre una esterilla con las piernas extendidas y los dedos de los pies apoyados sobre el balón de estabilidad.', 'Coloca las manos en el suelo, separadas a la altura de los hombros, y activa el abdomen.', 'Manteniendo las piernas rectas, levántalas lentamente del suelo, usando la zona lumbar y los glúteos para elevarlas tan alto como sea posible.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda baja y los glúteos, mejorando la extensión de cadera y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1343'),
('19a8a27c-bcdf-5d92-9f60-7f6ff7bfe3ec', 'Estiramiento de isquiotibiales sentado en balón', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti.', 'Coloca las manos en las caderas para mayor apoyo.', 'Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado.', 'Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos.', 'Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Alarga los isquiotibiales y descarga la espalda baja, ideal después de entrenar o estudiar sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1560'),
('46d5a32d-b52e-5829-b72d-1a539cdcf26c', 'Estiramiento de cuádriceps sentado en balón', ARRAY['Siéntate en el balón con la espalda recta y los pies apoyados en el suelo.', 'Lleva un tobillo hacia el glúteo sujetándolo con la mano del mismo lado.', 'Mantén las rodillas juntas y empuja suavemente la cadera hacia delante.', 'Respira despacio y aguanta entre veinte y treinta segundos por pierna.', 'Evita arquear la lumbar: mantén el abdomen activo durante el estiramiento.']::text[], 'principiante', 'Alarga la parte anterior del muslo y el flexor de cadera, aliviando tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1561'),
('23c3e1dc-de58-5d65-838b-26da163d7584', 'Estiramiento de tríceps sentado en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.', 'Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.', 'Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja.', 'Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.', 'Repite con el otro brazo.']::text[], 'principiante', 'Estira el tríceps y la parte posterior del hombro, alivia tensión tras empujes y mejora la movilidad del codo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1745'),
('ec2f0d8a-69f7-5921-a26e-2310ab0a52c4', 'Deslizamiento de serrato en la pared con balón', ARRAY['Coloca el balón contra la pared a la altura del pecho y apoya las manos sobre él con los codos ligeramente flexionados.', 'Desliza el balón hacia arriba mientras extiendes los brazos, manteniendo el core activo y sin arquear la espalda.', 'Haz una pausa arriba y vuelve despacio a la posición inicial controlando el movimiento.', 'Respira exhalando al subir y evita encoger los hombros hacia las orejas.']::text[], 'principiante', 'Activa el serrato anterior y la escápula para mejorar la estabilidad del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5311'),
('b0525cd4-bfa4-5d4f-93f0-7a990536ad10', 'Extensión de tríceps boca arriba en balón', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo.', 'Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.', 'Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el tríceps en posición supina sobre superficie inestable, mejorando control y estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1746'),
('76cf3d5f-7492-5d2e-9370-f345b4ec7bd1', 'Plancha dinámica explosiva', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Impulsa el cuerpo hacia arriba de forma explosiva separando las manos del suelo un instante.', 'Aterriza con los codos ligeramente flexionados para amortiguar el impacto y mantener el core firme.', 'Evita que la cadera se hunda o suba demasiado durante el movimiento.', 'Respira de forma controlada y reduce la intensidad si pierdes la alineación.']::text[], 'intermedio', 'Trabaja el core y los hombros con un gesto explosivo que mejora la potencia y la estabilidad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7859'),
('5cd37ddd-eeee-5a52-8a4c-3440bdb35b0f', 'Dedos explosivos', ARRAY['Apoya la palma de la mano en una superficie plana con los dedos extendidos.', 'Presiona las yemas contra la superficie y extiende los dedos de forma rápida y explosiva.', 'Mantén la muñeca neutra y evita mover el antebrazo durante el gesto.', 'Haz series cortas y descansa para no sobrecargar tendones de la mano.']::text[], 'principiante', 'Mejora la fuerza y la movilidad de dedos, muñeca y agarre, útil para escalada y deportes de raqueta.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11783'),
('b4c1a813-1185-54e4-97c5-79bc0cc4a61b', 'Sentadilla colgado explosiva', ARRAY['Baja a una sentadilla con los pies a la anchura de los hombros y el pecho alto.', 'Impulsa el suelo con fuerza y salta de forma explosiva extendiendo caderas y rodillas.', 'Aterriza con las rodillas alineadas con los pies y flexionando para amortiguar.', 'Evita que las rodillas se metan hacia dentro y mantén el core activo en todo momento.']::text[], 'intermedio', 'Desarrolla potencia en cuádriceps y glúteos con un salto desde sentadilla que mejora el rendimiento.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '11784'),
('2353f454-f12b-537d-bb41-038f649bc073', 'Flexión explosiva', ARRAY['Colócate en posición de flexión con manos algo más anchas que los hombros y cuerpo alineado.', 'Baja el pecho de forma controlada hasta cerca del suelo.', 'Empuja con fuerza para despegar las manos del suelo y vuelve a caer con codos ligeramente flexionados.', 'Amortigua la caída y evita arquear la zona lumbar en ningún momento.']::text[], 'intermedio', 'Trabaja el pecho con potencia y activa tríceps, hombros y core para ganar fuerza explosiva y velocidad de empuje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5460'),
('64b9e8ec-2f51-5842-a120-000142130b5c', 'Postura de ángulo lateral extendido', ARRAY['Desde una zancada amplia, gira el pie trasero hacia fuera y apoya la mano del mismo lado en el suelo o en la pierna.', 'Extiende el brazo contrario hacia arriba formando una línea con el torso.', 'Abre el pecho y mira hacia la mano elevada sin forzar el cuello.', 'Respira profundo y evita bloquear la rodilla delantera.']::text[], 'intermedio', 'Estira aductores e isquiotibiales y abre la cadera, mejorando la movilidad lateral y la estabilidad del tronco.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5220'),
('d6481b3f-9478-5ed8-b43c-dc2d10717bc4', 'Movilización de hombros con empuje externo', ARRAY['Coloca el brazo flexionado a la altura del hombro con el codo pegado al cuerpo.', 'Empuja suavemente la mano contraria contra el antebrazo para resistir el movimiento.', 'Mantén la tensión unos segundos sin mover el codo del sitio.', 'Evita encoger el hombro o girar el tronco durante el empuje.']::text[], 'principiante', 'Mejora la movilidad del hombro y activa el manguito rotador para preparar la articulación antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11793'),
('a6e4ce51-1ad0-5368-ac66-81aa1012ac57', 'Movilización de hombros con rotación externa', ARRAY['Pega el codo al costado con el antebrazo a 90 grados.', 'Rota el brazo hacia fuera sin separar el codo del cuerpo.', 'Haz el recorrido lento y controlado, notando el estiramiento en la parte delantera.', 'Evita compensar girando el tronco o subiendo el hombro.']::text[], 'principiante', 'Activa el manguito rotador y gana rango de rotación externa para proteger el hombro en presses y jalones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11796'),
('346d8bc0-c538-5b0f-924d-65fb3663fa20', 'Estiramiento de rotación externa del hombro', ARRAY['Lleva el brazo estirado hacia atrás con la palma hacia fuera.', 'Gira suavemente el hombro hacia dentro hasta notar tensión en la parte delantera.', 'Mantén la posición respirando de forma relajada.', 'No fuerces el cuello ni eleves el hombro estirado.']::text[], 'principiante', 'Estira la parte delantera del hombro y el pecho, liberando tensión tras sesiones de empuje o trabajo de escritorio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1990'),
('dc5dd3f1-4fc8-5b8f-8c30-414a549afc81', 'Abdominal con declinación extra', ARRAY['Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.', 'Sube el tronco enrollando la columna sin tirar del cuello.', 'Baja de forma controlada hasta notar el estiramiento abdominal.', 'Evita impulsarte con las piernas o arquear la lumbar al bajar.']::text[], 'intermedio', 'Refuerza el recto abdominal y los flexores de cadera con mayor recorrido para un core más fuerte y estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1864'),
('7629319a-ca7f-5649-b7ec-d6eb3061eed9', 'Rompecráneos california con barra EZ', ARRAY['Túmbate en el banco con la barra EZ sujeta por encima del pecho y brazos extendidos.', 'Lleva la barra hacia atrás de la cabeza flexionando solo los codos.', 'Extiende los codos para volver a la posición inicial sin mover los brazos.', 'Mantén los codos apuntando al techo y evita abrirlos hacia fuera.']::text[], 'intermedio', 'Aísla el tríceps con un recorrido amplio que también implica hombros y antebrazos para ganar fuerza y volumen.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4130'),
('d5dd895b-b247-59f7-bac5-3124d5fce0f0', 'Curl de bíceps arrastrado con barra EZ', ARRAY['De pie, sujeta la barra EZ con las palmas hacia arriba y los brazos extendidos.', 'Sube la barra arrastrándola cerca del cuerpo hasta la altura del pecho.', 'Aprieta el bíceps arriba y baja despacio controlando el peso.', 'Evita balancear el tronco o adelantar los codos en exceso.']::text[], 'intermedio', 'Trabaja el bíceps y el braquial con un arrastre que mantiene tensión constante y refuerza antebrazos y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4422'),
('c24c2a1d-cfe7-593d-b896-334564b91632', 'Press francés con barra EZ en balón', ARRAY['Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono.', 'Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza.', 'Baja lentamente la barra detrás de la cabeza doblando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el tríceps sobre superficie inestable, mejorando el control y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1747'),
('5aca4be8-8d47-5e94-93dd-659f146fdba8', 'Elevación frontal con giro y barra EZ', ARRAY['Sujeta la barra EZ con agarre prono frente a los muslos y mantén el core activo.', 'Eleva la barra hasta la altura de los hombros mientras giras las muñecas hacia arriba.', 'Baja controlando el movimiento y exhala al subir.', 'Evita balancear el torso o usar impulso para levantar el peso.']::text[], 'intermedio', 'Trabaja el deltoides anterior y el core, mejorando la fuerza y estabilidad del hombro en movimientos de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3986'),
('ca0e5896-9dbc-58b2-8f7e-e25980fbb562', 'Abdominal con piernas al lado y barra EZ', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta la barra EZ con ambas manos.', 'Sube el tronco y lleva la barra hacia un lado de las piernas con control.', 'Baja lentamente y repite hacia el otro lado alternando.', 'Exhala al subir y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Fortalece el recto abdominal y los oblicuos, mejorando el control del tronco y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4187'),
('f0b9ac0a-140f-5758-8974-c44e1ee39c19', 'Pullover acostado con brazos flexionados y barra EZ', ARRAY['Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.', 'Sostén la barra EZ con agarre prono (palmas hacia afuera) y las manos separadas a la altura de los hombros.', 'Extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.', 'Baja la barra describiendo un arco detrás de la cabeza, manteniendo la ligera flexión en los codos.', 'Haz una pausa breve, luego regresa la barra a la posición inicial invirtiendo el movimiento del arco.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira y trabaja el dorsal ancho y el pecho, favoreciendo la movilidad del hombro y la expansión torácica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3010'),
('83927bf4-30cb-5214-89f3-44ad7633060d', 'Extensión de tríceps acostado por detrás de la cabeza con barra EZ', ARRAY['Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.', 'Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho.', 'Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.', 'Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en su porción larga, aumentando la fuerza y el volumen del brazo tras el entrenamiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1748'),
('f35f092c-bdb7-5818-bc86-043e4d96e29f', 'Estiramiento de brazos en banco predicador con barra EZ', ARRAY['Coloca los brazos sobre el banco predicador con la barra EZ sujeta en agarre supino.', 'Extiende los codos lentamente hasta notar el estiramiento en el bíceps.', 'Mantén la posición de 20 a 30 segundos respirando con calma.', 'Evita forzar la extensión o rebotar para no sobrecargar el codo.']::text[], 'principiante', 'Estira el bíceps y el braquial, mejorando la flexibilidad del brazo y aliviando la tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1820'),
('4aafe721-be50-51e4-9fc5-636145809e79', 'Abdominal reverso con barra EZ', ARRAY['Túmbate boca arriba con la barra EZ sujeta con ambas manos junto a la cadera.', 'Eleva las piernas y lleva las rodillas hacia el pecho despegando la pelvis.', 'Baja las piernas con control sin arquear la zona lumbar.', 'Exhala al subir y evita usar impulso con las piernas.']::text[], 'intermedio', 'Activa la parte baja del abdomen y los flexores de cadera, mejorando el control pélvico y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4188'),
('67aef15c-587d-53f9-9960-dc20df4db461', 'Remo inclinado con agarre inverso y barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.', 'Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.', 'Tira de la barra EZ hacia la parte baja del pecho, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte superior, luego baja lentamente la barra EZ a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1344'),
('b2261c5d-d3d9-52df-92f0-3a5f8d0d8eb4', 'Abdominal con giro ruso y barra EZ', ARRAY['Siéntate con las rodillas flexionadas y sujeta la barra EZ frente al pecho.', 'Inclina ligeramente el tronco hacia atrás manteniendo la espalda recta.', 'Gira el tronco hacia un lado y luego hacia el otro con control.', 'Exhala en cada giro y evita mover solo los brazos sin rotar el torso.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos, mejorando la rotación del tronco y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5308'),
('de4e7071-9327-5bef-9978-f81e310bfbae', 'Curl concentrado sentado con agarre cerrado y barra EZ', ARRAY['Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino.', 'Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.', 'Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil.', 'Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo, aumentando el pico del brazo y la fuerza en flexión de codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1682'),
('d7e7c8aa-0dee-5ae1-ac40-92d426405cd1', 'Curl de muñeca sentado con barra EZ', ARRAY['Siéntate con los antebrazos apoyados en los muslos y sujeta la barra EZ en agarre supino.', 'Deja las muñecas colgando al borde de las rodillas.', 'Flexiona las muñecas hacia arriba y baja lentamente con control.', 'Evita mover los antebrazos o usar impulso para subir la barra.']::text[], 'intermedio', 'Fortalece los flexores de muñeca y la fuerza de agarre, mejorando el rendimiento en tracciones y levantamientos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5579'),
('98f01f0e-649c-5b4d-9d1b-9e9393d09820', 'Abdominal con press de hombros y barra EZ', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la barra EZ sujeta frente al pecho.', 'Sube el tronco mientras empujas la barra por encima de la cabeza.', 'Baja la barra y el tronco de forma controlada hasta la posición inicial.', 'Exhala al empujar y evita arquear la zona lumbar al subir.']::text[], 'intermedio', 'Combina el trabajo abdominal con el empuje de hombros, mejorando la fuerza global del core y el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5309'),
('2ec57690-a612-527a-936a-41e9f9c905e9', 'Press francés de pie con barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono.', 'Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en su porción larga, mejorando la fuerza y el volumen del brazo en extensión de codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1749'),
('31357590-b011-523d-9622-8058fa0f79e2', 'Giro arriba y abajo con barra EZ', ARRAY['De pie con los pies a la anchura de los hombros, sujeta la barra EZ frente al pecho.', 'Gira el tronco hacia un lado llevando la barra arriba y luego abajo con control.', 'Vuelve al centro y repite hacia el otro lado alternando.', 'Exhala en cada giro y evita mover solo los brazos sin rotar el torso.']::text[], 'intermedio', 'Trabaja el core y los oblicuos con rotación controlada, mejorando la estabilidad y la coordinación del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4190'),
('3ebb3cc6-650a-5b43-963f-941c6ec59585', 'Press anti gravedad con barra EZ', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono.', 'Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante.', 'Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los hombros y el tríceps con un empuje controlado, mejorando la estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0445'),
('cc240f8a-208e-51a9-8a7a-6799e5274f96', 'Curl predicador con agarre cerrado y barra EZ', ARRAY['Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino.', 'Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta.', 'Sube lentamente la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Baja la barra a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo en el banco predicador, aumentando la fuerza y el volumen del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1627'),
('4e50cf8e-aa4b-5c09-8768-b3d99f80a46d', 'Curl con barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.', 'Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.', 'Exhala mientras subes la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo para ganar fuerza y volumen en el brazo con un agarre más cómodo para las muñecas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0447'),
('c5611843-a2ee-5448-973a-6cff8dd32a6e', 'Press declinado a la cara con agarre cerrado y barra EZ', ARRAY['Túmbate en un banco declinado con la cabeza más baja que los pies.', 'Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra.', 'Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo.', 'Baja la barra hacia la frente doblando los codos.', 'Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros desde un ángulo declinado, útil para reforzar la extensión del codo y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0448'),
('be4a3671-92d2-5408-8754-ae2d4c91e61e', 'Extensión de tríceps declinada con barra EZ', ARRAY['Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados.', 'Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.', 'Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.', 'Baja la barra lentamente hacia la frente, doblando los codos.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el tríceps en un banco declinado, aumentando el rango de estiramiento y el trabajo del hombro en la extensión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2186'),
('89e292c5-3a0e-5726-b23c-32c101b88085', 'Extensión de tríceps inclinada con barra EZ', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Siéntate en el banco con la espalda apoyada en el respaldo y sostén la barra EZ con agarre prono.', 'Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.', 'Baja la barra detrás de la cabeza doblando los codos, manteniendo los brazos superiores inmóviles.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tríceps en un banco inclinado, con mayor estiramiento del brazo y apoyo de los hombros para ganar fuerza en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0449'),
('39c24e36-20d0-53f4-b0af-f4eabfb1dffb', 'Extensión de tríceps acostado con barra EZ', ARRAY['Túmbate en el banco con los pies apoyados y sujeta la barra EZ con agarre estrecho sobre el pecho.', 'Lleva los brazos hacia arriba extendiendo los codos sin mover los hombros del banco.', 'Baja la barra hacia la frente flexionando solo los codos y controlando el movimiento.', 'Empuja de nuevo hacia arriba mientras exhalas, sin abrir los codos hacia los lados.', 'Evita arquear la espalda o usar impulso; mantén los codos apuntando al techo.']::text[], 'intermedio', 'Aísla el tríceps tumbado en el banco, con apoyo de hombros y antebrazos, ideal para ganar fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5873'),
('ff118d88-dfb7-5312-aeb2-bd15d958e569', 'Curl con agarre inverso y barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino.', 'Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio.', 'Sube la barra contrayendo los bíceps, mientras exhalas.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Comienza a regresar la barra lentamente a la posición inicial mientras inhalas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza bíceps y antebrazos con un agarre prono que también trabaja los extensores de la muñeca y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0451'),
('b42f029a-6a02-58f2-a84c-46ab047f8b97', 'Curl sentado con barra EZ', ARRAY['Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.', 'Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.', 'Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti.', 'Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la barra EZ a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps sentado, reduciendo el impulso del cuerpo y permitiendo un trabajo controlado del brazo y el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1458'),
('157cbe68-4d59-5d12-b6fd-b24436566eec', 'Curl de muñeca inverso sentado con barra EZ', ARRAY['Siéntate con los antebrazos apoyados en los muslos y las muñecas al borde de las rodillas.', 'Sujeta la barra EZ con agarre prono, palmas hacia abajo y muñecas relajadas.', 'Sube las muñecas extendiéndolas hacia arriba sin mover los antebrazos.', 'Baja despacio hasta la posición inicial controlando el peso en todo momento.', 'Evita balancear los brazos o usar demasiado peso; el movimiento sale solo de la muñeca.']::text[], 'intermedio', 'Fortalece los extensores de la muñeca y el agarre desde una posición sentada, útil para equilibrar la fuerza del antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6364'),
('7e66cd02-4611-5f57-bf40-55da95f34fbc', 'Curl araña con barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.', 'Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.', 'Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con el brazo colgando en vertical, aumentando el estiramiento y evitando el impulso del resto del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0454'),
('308e13ef-5f01-500e-a0f4-b08d4cfa3466', 'Curl de muñeca por detrás de pie con barra EZ', ARRAY['De pie, sujeta la barra EZ por detrás de la espalda con agarre prono y brazos extendidos.', 'Mantén los codos pegados al cuerpo y los hombros relajados durante todo el ejercicio.', 'Flexiona las muñecas llevando la barra hacia arriba sin mover los brazos.', 'Baja la barra despacio hasta la posición inicial controlando el peso.', 'Evita encoger los hombros o balancear el torso; el movimiento sale solo de la muñeca.']::text[], 'intermedio', 'Trabaja los flexores de la muñeca y el agarre con la barra detrás del cuerpo, útil para reforzar el antebrazo de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6365'),
('1aec1c33-24b4-5527-a465-22da0ed7b27e', 'Press sobre la cabeza de pie con barra EZ', ARRAY['De pie, sujeta la barra EZ a la altura de los hombros con las palmas hacia delante.', 'Aprieta el abdomen y los glúteos para mantener el torso firme y la espalda neutra.', 'Empuja la barra hacia arriba extendiendo los brazos mientras exhalas.', 'Baja la barra despacio hasta la altura de los hombros controlando el movimiento.', 'Evita arquear la espalda o bloquear las rodillas; mantén el core activo en todo momento.']::text[], 'intermedio', 'Fortalece hombros, tríceps y core empujando la barra por encima de la cabeza, mejorando la estabilidad y la fuerza vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1226'),
('5786d3d5-6ead-5be5-b007-afe80d3ef9d2', 'Curl predicador de pie con barra EZ', ARRAY['Colócate de pie detrás del soporte y apoya la parte posterior de los brazos sobre el almohadillado.', 'Sujeta la barra EZ con agarre supino y los codos alineados con los hombros.', 'Flexiona los codos subiendo la barra sin despegar los brazos del soporte.', 'Baja la barra despacio hasta extender casi por completo los codos.', 'Evita balancear el torso o soltar los brazos del apoyo para no perder tensión.']::text[], 'intermedio', 'Aísla el bíceps con el brazo apoyado, trabajando también el braquial y el antebrazo sin impulso del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2900'),
('c4703222-595f-5b81-ad65-ccd8b152f386', 'Curl de muñeca neutro a un brazo de pie con barra EZ', ARRAY['De pie, sujeta un extremo de la barra EZ con una mano en agarre neutro y el brazo pegado al cuerpo.', 'Mantén el codo fijo y la muñeca alineada con el antebrazo.', 'Flexiona la muñeca llevando la barra hacia arriba sin mover el brazo.', 'Baja despacio hasta la posición inicial controlando el peso.', 'Evita girar el torso o usar impulso; el movimiento sale solo de la muñeca.']::text[], 'intermedio', 'Fortalece flexores de la muñeca y agarre con un solo brazo, corrigiendo desequilibrios y mejorando la fuerza del antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6268'),
('982cba2f-3cf9-5566-8de0-afa15d84a688', 'Remo al mentón de pie con barra EZ', ARRAY['De pie, sujeta la barra EZ frente a los muslos con agarre prono y manos al ancho de los hombros.', 'Mantén el abdomen activo y la espalda recta durante todo el movimiento.', 'Tira de la barra hacia el mentón llevando los codos hacia arriba y hacia fuera.', 'Baja la barra despacio hasta la posición inicial controlando el peso.', 'Evita encoger los hombros en exceso o usar impulso del torso para subir la barra.']::text[], 'intermedio', 'Trabaja hombros, trapecio y espalda alta tirando de la barra hacia el mentón, mejorando la fuerza y la postura del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7114'),
('e1a05c0e-7401-584d-80db-6c46eca925d4', 'Curl de muñeca de pie con barra EZ', ARRAY['De pie, sujeta la barra EZ con agarre supino y los brazos extendidos frente a los muslos.', 'Mantén los codos pegados al cuerpo y los hombros relajados.', 'Flexiona las muñecas llevando la barra hacia arriba sin mover los brazos.', 'Baja la barra despacio hasta la posición inicial controlando el peso.', 'Evita balancear el torso o soltar los codos del cuerpo durante el movimiento.']::text[], 'intermedio', 'Fortalece los flexores de la muñeca y el agarre de pie, mejorando la fuerza del antebrazo y la resistencia en la mano.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6358'),
('8e308308-b5b7-5374-b942-072bd867f6b0', 'Curl de muñeca inverso de pie con barra EZ', ARRAY['Sujeta la barra EZ con las palmas hacia abajo y los brazos extendidos junto al cuerpo.', 'Deja que las muñecas bajen despacio sin mover los codos.', 'Sube las muñecas hasta la extensión completa apretando el antebrazo.', 'Controla el descenso durante dos segundos y evita balancear el torso.']::text[], 'intermedio', 'Fortalece los extensores de la muñeca y el agarre, útil para equilibrar el antebrazo y prevenir molestias en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6361'),
('9c07f6fd-630d-5ec1-80c6-bf2b7e47ef73', 'Press de banca con agarre cerrado y barra EZ', ARRAY['Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.', 'Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante.', 'Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.', 'Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el tríceps en un press de banca que también solicita pecho y hombros para empujes más potentes.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2432'),
('1fbb7794-e639-5f63-9e44-b34ae086046e', 'Curl de bíceps de pie con agarre abierto y barra EZ', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros.', 'Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.', 'Sube la barra hacia los hombros contrayendo los bíceps.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el bíceps con un agarre amplio que enfatiza la cabeza corta y suma tensión en los antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2741'),
('5ab650f9-9c61-5bd6-90e2-b178f902311d', 'Prueba de Faber', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Junta las plantas de los pies y deja caer las rodillas hacia los lados.', 'Observa si una rodilla queda mucho más alta que la otra.', 'No fuerces la posición ni empujes con las manos para igualarlas.']::text[], 'principiante', 'Evalúa la movilidad de la cadera y los aductores, detectando acortamientos que afectan a la sentadilla y al equilibrio pélvico.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6786'),
('95f81dfb-a07c-5102-9326-d6a59eb2837b', 'Caminata del granjero', ARRAY['Ponte de pie con una mancuerna en cada mano, palmas hacia los costados.', 'Mantén la espalda recta y los hombros hacia atrás.', 'Da pasos pequeños y controlados hacia adelante, manteniendo una postura erguida.', 'Continúa caminando durante la distancia o el tiempo deseado.', 'Para terminar, deja de caminar y baja con cuidado las mancuernas a los costados.']::text[], 'intermedio', 'Fortalece piernas, agarre y core caminando con carga, mejorando la resistencia y la estabilidad global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2133'),
('98296094-4aa3-54c0-be0a-935bb6e4fdf7', 'Estiramiento con rotación de pies y tobillos', ARRAY['Siéntate o apóyate y levanta un pie del suelo.', 'Dibuja círculos lentos con el tobillo en ambos sentidos.', 'Haz diez rotaciones por lado sin mover la rodilla.', 'Evita forzar el rango si notas pinchazos en el tobillo.']::text[], 'principiante', 'Mejora la movilidad del tobillo y activa la circulación en pies y gemelos antes o después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4283'),
('c2374d84-e397-5c9c-b005-7e6b8b4471cc', 'Estiramiento de pies y tobillos de lado a lado', ARRAY['Apoya el pie en el suelo y mantén la pierna relajada.', 'Inclina el pie hacia dentro y hacia fuera alternando el apoyo.', 'Mantén cada posición dos segundos sin levantar el talón.', 'No cargues todo el peso sobre el borde del pie.']::text[], 'principiante', 'Moviliza tobillos y gemelos de forma lateral, preparando la articulación para correr o caminar con seguridad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3245'),
('76758111-6a84-5a55-ac70-48a0b66fd1fc', 'Estiramiento de pies y tobillos', ARRAY['Apoya las manos en una pared y da un paso atrás con una pierna.', 'Mantén el talón de atrás pegado al suelo y la rodilla estirada.', 'Inclina el cuerpo hacia delante hasta notar tensión en el gemelo.', 'Respira despacio y evita rebotar durante el estiramiento.']::text[], 'principiante', 'Relaja gemelos, sóleo y la fascia del pie, aliviando tensión tras estar muchas horas de pie o caminando.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4282'),
('c2125ca6-701b-52fe-bdc0-c43fecfc17ae', 'Carrera en figura', ARRAY['Coloca varios conos formando un recorrido en zigzag.', 'Corre en curva alrededor de cada cono sin frenar en seco.', 'Mantén el tronco ligeramente inclinado y los pasos cortos.', 'Baja el ritmo si pierdes el control de la trayectoria.']::text[], 'intermedio', 'Mejora la coordinación, la agilidad y la capacidad cardiovascular mediante cambios de dirección rápidos y controlados.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5989'),
('2e899497-1787-59c2-840d-315e80dafcff', 'Curl de dedos', ARRAY['Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.', 'Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.', 'Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza.', 'Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza antebrazos y flexores de la muñeca para mejorar la fuerza de agarre en dominadas y peso muerto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0455'),
('ea124f10-7859-5131-9370-f302c68c643c', 'Estiramiento de extensión de dedos', ARRAY['Extiende una mano con la palma hacia arriba.', 'Con la otra mano, lleva los dedos suavemente hacia abajo.', 'Mantén la posición veinte segundos sin dolor.', 'Evita tirar de la punta de los dedos con fuerza.']::text[], 'principiante', 'Estira los flexores de los dedos y el antebrazo, aliviando la tensión acumulada por escribir o usar el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2095'),
('570e0cdc-2c24-5efd-b783-0d72274bffbb', 'Estiramiento de extensores de los dedos', ARRAY['Apoya la palma de la mano sobre una mesa con los dedos juntos.', 'Presiona suavemente el dorso de los dedos hacia la mesa.', 'Mantén la tensión veinte segundos respirando con calma.', 'No cargues el peso del cuerpo sobre la mano.']::text[], 'principiante', 'Relaja los extensores de la mano y el antebrazo, útil tras sesiones de agarre o de teclado prolongado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1827'),
('44e45e7b-86e8-5a52-bca0-425d00a2d2e4', 'Flexión de dedos con extensión del pulgar', ARRAY['Abre la mano con los dedos extendidos.', 'Flexiona los dedos hacia la palma dejando el pulgar estirado.', 'Vuelve a abrir despacio y repite el movimiento.', 'Evita apretar con fuerza ni bloquear las articulaciones.']::text[], 'principiante', 'Moviliza dedos y pulgar para mejorar la coordinación fina y la flexibilidad de la mano y el antebrazo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10031'),
('db39d900-e4c7-5329-8809-2feae21373a7', 'Estiramiento de dedos', ARRAY['Entrelaza los dedos de ambas manos delante del pecho.', 'Gira las palmas hacia fuera y estira los brazos.', 'Mantén la posición quince segundos sin encoger los hombros.', 'Suelta despacio y sacude las manos para relajarlas.']::text[], 'principiante', 'Relaja manos y antebrazos, reduciendo la rigidez de los dedos después de estudiar o de entrenar agarre.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2089'),
('92a3201a-39cf-5fd1-aae6-7bb4f70873e7', 'Postura del pez', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Arquea ligeramente la espalda y apoya la coronilla en el suelo.', 'Abre el pecho y respira profundo manteniendo la postura.', 'Evita forzar el cuello si notas molestias en la nuca.']::text[], 'intermedio', 'Abre el pecho y los flexores de la cadera, corrigiendo la postura encorvada y mejorando la respiración.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0950'),
('8cf42f87-244a-5c79-9c3a-aa67d2138669', 'Estiramiento de espalda en barra fija', ARRAY['Agárrate a la barra con las palmas hacia delante y los brazos estirados.', 'Deja que el cuerpo cuelgue relajando los hombros y separando las escápulas.', 'Respira despacio y mantén el estiramiento entre veinte y treinta segundos.', 'Evita balancearte o soltar de golpe; baja con control al terminar.']::text[], 'principiante', 'Estira dorsales y espalda alta colgándote de la barra, alivia tensión y mejora la movilidad de hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1052'),
('285568f4-e8d6-5b12-a5a3-3b24f407c5b6', 'Bandera', ARRAY['Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos.', 'Activa el core y levanta las piernas del suelo, manteniéndolas rectas.', 'Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo.', 'Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Isométrico avanzado que trabaja abdomen, oblicuos y hombros manteniendo el cuerpo rígido y alineado en horizontal.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3303'),
('181c0c9b-24be-5ca4-8b56-b4ca12debe83', 'Estiramiento de cadera con flexión y extensión', ARRAY['Colócate en cuadrupedia con las manos bajo los hombros y las rodillas bajo las caderas.', 'Lleva una rodilla hacia el pecho y después extiende esa pierna hacia atrás sin arquear la zona lumbar.', 'Alterna el movimiento de forma lenta y controlada, respirando con normalidad.', 'Evita girar la cadera o compensar con la espalda baja.']::text[], 'principiante', 'Moviliza glúteos y flexores de cadera alternando flexión y extensión para ganar rango y aliviar tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3396'),
('6d1aee40-e416-5316-9263-f49fe2bc1b23', 'Estiramiento de flexión de dedos', ARRAY['Extiende un brazo al frente con la palma hacia arriba.', 'Con la otra mano, tira suavemente de los dedos hacia abajo hasta notar el estiramiento.', 'Mantén entre quince y treinta segundos sin forzar y respira con calma.', 'Evita rebotes y cambia de mano al terminar.']::text[], 'principiante', 'Estira antebrazos y flexores de la mano, útil tras escribir o usar el móvil para prevenir tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2096'),
('3dfacc99-4d05-5b97-bbd6-51b738d1fe2d', 'Abdominal con rodillas flexionadas', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho.', 'Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el recto abdominal con las rodillas dobladas, reduce tensión lumbar y fortalece el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0456'),
('895fe888-64ba-57e7-87ef-0edc0b5cf2da', 'Abdominal en el suelo con pies en banco', ARRAY['Túmbate boca arriba con los pies apoyados en el banco y las rodillas flexionadas.', 'Coloca las manos en las sienes sin tirar del cuello.', 'Eleva la parte alta de la espalda contrayendo el abdomen y exhala al subir.', 'Baja despacio sin apoyar del todo y evita arquear la lumbar.']::text[], 'intermedio', 'Encoge el tronco con los pies apoyados en un banco para aislar el abdomen y proteger la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3279'),
('9d50f8ef-334f-589a-9d3f-30b72114e73e', 'Apertura en el suelo con barra', ARRAY['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.', 'Sostén una barra con agarre prono, brazos extendidos rectos por encima del pecho.', 'Baja lentamente la barra hacia los lados, manteniendo una ligera flexión en los codos.', 'Baja la barra hasta que los brazos queden paralelos al suelo, sintiendo un estiramiento en el pecho.', 'Haz una pausa breve, luego contrae los músculos del pecho para llevar la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Abre los pectorales tumbado con barra, trabajando también hombros y tríceps con control del rango.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0458'),
('9d005005-74fa-5059-834c-602225181797', 'Apertura en el suelo con toallas', ARRAY['Túmbate boca arriba con las rodillas flexionadas y una toalla bajo cada mano.', 'Extiende los brazos hacia los lados con los codos ligeramente flexionados.', 'Desliza las manos juntándolas sobre el pecho y vuelve despacio a la posición inicial.', 'Mantén el core activo y evita arquear la espalda baja.']::text[], 'intermedio', 'Abre pectorales deslizando las manos sobre toallas, activando hombros, core y tríceps sin material extra.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3924'),
('71931cdf-1505-5816-a35d-6d30b5359ccf', 'Hiperextensión en el suelo', ARRAY['Túmbate boca abajo con los brazos estirados al frente y la frente apoyada.', 'Aprieta los glúteos y eleva las piernas del suelo sin arquear en exceso la lumbar.', 'Mantén un segundo arriba y baja con control, respirando de forma constante.', 'Evita levantar la cabeza o usar impulso para subir.']::text[], 'intermedio', 'Fortalece glúteos, lumbares e isquios elevando las piernas tumbado, mejora la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2394'),
('e5cc6ab5-757d-5bcb-a630-40de1883a2bb', 'Elevación en T en el suelo', ARRAY['Túmbate boca abajo con los brazos abiertos formando una T y las palmas hacia el suelo.', 'Aprieta las escápulas y eleva los brazos unos centímetros sin despegar la frente.', 'Mantén la posición un segundo y baja despacio, respirando con normalidad.', 'Evita encoger los hombros hacia las orejas o arquear la lumbar.']::text[], 'intermedio', 'Refuerza espalda alta y deltoides posteriores tumbado boca abajo, mejora la postura y estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3225'),
('8cb8efb3-8ee0-5c02-bc3e-c733c0078ff8', 'Abdominal con giro en el suelo con pies en banco', ARRAY['Túmbate boca arriba con los pies apoyados en el banco y las manos en las sienes.', 'Eleva la parte alta de la espalda y gira el tronco hacia un lado contrayendo el oblicuo.', 'Vuelve al centro y alterna hacia el otro lado con movimiento controlado.', 'Exhala en cada giro y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Encoge y gira el tronco con los pies en banco para trabajar abdomen y oblicuos con apoyo estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3280'),
('ea487d5f-5694-5fcd-9e96-f6064ebf80dc', 'Elevación en W en el suelo', ARRAY['Túmbate boca abajo con los codos flexionados y los brazos formando una W.', 'Aprieta las escápulas y eleva los codos y las manos del suelo.', 'Mantén un segundo arriba y baja con control sin perder la tensión.', 'Evita levantar la cabeza o encoger los hombros.']::text[], 'intermedio', 'Activa espalda alta, romboides y deltoides posteriores con los brazos en forma de W, mejorando la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11648'),
('15b96f36-274a-56c1-9a5a-11aaa8c79346', 'Pataleo', ARRAY['Túmbate boca arriba con las piernas extendidas y las manos a los costados.', 'Activa el core y levanta las piernas del suelo unos 15 centímetros.', 'Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.', 'Continúa este movimiento de aleteo durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos, flexores y abdomen inferior con patadas alternas que también mejoran la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0459'),
('1816089c-b127-5644-ae8e-b7fb7711f18a', 'Patadas de aleteo con manos bajo las caderas', ARRAY['Túmbate boca arriba con las manos bajo las caderas y la cabeza ligeramente elevada.', 'Eleva las piernas unos centímetros y alterna patadas cortas y rápidas.', 'Mantén la zona lumbar pegada al suelo y respira de forma constante.', 'Evita arquear la espalda o subir demasiado las piernas.']::text[], 'intermedio', 'Activa abdomen inferior y flexores de cadera con patadas alternas, manteniendo la lumbar protegida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2891'),
('12821a6a-adf5-5768-90ed-c8d2bb36b40a', 'Apertura contra cadenas', ARRAY['Túmbate en un banco con una mancuerna en cada mano y los brazos abiertos.', 'Con los codos ligeramente flexionados, junta las mancuernas sobre el pecho.', 'Controla la bajada notando la tensión de las cadenas y exhala al subir.', 'Evita bloquear los codos o bajar más de lo que controlas.']::text[], 'intermedio', 'Abre pectorales con mancuernas y resistencia de cadenas, sumando tensión a hombros y bíceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4200'),
('b0036f0d-2545-5301-afcd-776d49df66a1', 'Postura del lagarto volador', ARRAY['Coloca las manos en el suelo con los codos bajo los hombros y las piernas abiertas.', 'Desliza el pie derecho hacia delante hasta apoyar el antebrazo en el suelo junto al muslo.', 'Baja la cadera y alarga la pierna trasera mientras mantienes el pecho abierto.', 'Respira despacio y evita colapsar la zona lumbar; activa el core para sostenerte.']::text[], 'intermedio', 'Estira aductores y flexores de cadera mientras fortalece el core y los glúteos en equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '7624'),
('9bbf5073-8280-5734-b1c9-7036ab278711', 'Deslizamiento de serrato en la pared con rodillo', ARRAY['Apoya el rodillo en la pared a la altura del pecho y coloca las manos sobre él.', 'Mantén los codos ligeramente flexionados y los omóplatos separados.', 'Desliza el rodillo hacia arriba mientras estiras los brazos sin perder la presión.', 'Vuelve despacio controlando el movimiento y evita encoger los hombros.']::text[], 'principiante', 'Activa el serrato anterior y mejora la movilidad escapular para estabilizar el hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5027'),
('d1772654-e83d-51f2-ab5a-db7ddc82e6fb', 'Pronación de antebrazo', ARRAY['Siéntate con el codo flexionado a noventa grados y el antebrazo apoyado.', 'Gira la palma hacia abajo sin mover el codo de su sitio.', 'Aguanta un segundo al final del recorrido y vuelve despacio.', 'Evita compensar con el hombro; el movimiento sale solo de la muñeca.']::text[], 'principiante', 'Moviliza la rotación del antebrazo y fortalece los músculos que giran la muñeca.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2765'),
('2914f21f-985a-5608-827b-2285c8fe3a99', 'Estiramiento de pronadores del antebrazo', ARRAY['Extiende el brazo hacia delante con la palma mirando al suelo.', 'Con la otra mano agarra el dorso y gira la muñeca hacia dentro.', 'Mantén el estiramiento sin dolor durante veinte o treinta segundos.', 'Respira con calma y evita tirar del codo o forzar la articulación.']::text[], 'principiante', 'Relaja los pronadores y flexores de la muñeca tras esfuerzos de agarre o teclado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1815'),
('fe158f46-3755-5825-a371-8f0806534050', 'Supinación de antebrazo', ARRAY['Siéntate con el codo pegado al cuerpo y flexionado a noventa grados.', 'Gira la palma hacia arriba manteniendo el codo quieto.', 'Sostén un instante arriba y regresa de forma controlada.', 'No rotes el hombro ni muevas el brazo para ganar recorrido.']::text[], 'principiante', 'Mejora la rotación externa del antebrazo y la movilidad de la muñeca y el codo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2766'),
('aef70a74-2dc0-5639-9989-64ab819cae63', 'Deslizamiento de antebrazos en la pared', ARRAY['Apoya los antebrazos en la pared con los codos a la altura de los hombros.', 'Desliza los antebrazos hacia arriba manteniendo el contacto con la pared.', 'Separa ligeramente los omóplatos al subir y vuelve despacio.', 'Evita arquear la espalda o encoger los hombros durante el recorrido.']::text[], 'principiante', 'Trabaja el serrato y la movilidad del hombro para mejorar la estabilidad escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2941'),
('e69c36d3-7884-57ac-88d8-f519b5a75aac', 'Postura de la parada de antebrazos', ARRAY['Coloca los antebrazos en el suelo con los codos bajo los hombros y forma un triángulo.', 'Apoya la coronilla ligeramente delante de las manos y activa el core.', 'Sube las piernas con control hasta quedar invertido sin arquear la lumbar.', 'Respira de forma constante y evita cargar el peso en la cabeza.']::text[], 'intermedio', 'Fortalece hombros, core y espalda alta mientras mejoras el equilibrio invertido.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6880'),
('6ad51966-7f56-5c0d-8d15-664d29b1144f', 'Caminata de cangrejo hacia delante y atrás', ARRAY['Siéntate en el suelo y apoya las manos detrás con los dedos hacia los pies.', 'Eleva la cadera hasta formar una línea recta entre hombros y rodillas.', 'Avanza con pasos cortos alternando mano y pie sin hundir la cadera.', 'Retrocede igual y evita bloquear los codos o dejar caer la pelvis.']::text[], 'intermedio', 'Refuerza el core, tríceps y glúteos con un patrón de desplazamiento en cuadrupedia invertida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10995'),
('f140c151-12af-542b-99fe-ca2d873b06c6', 'Salto adelante y atrás', ARRAY['Colócate de pie con los pies a la anchura de las caderas y rodillas ligeramente flexionadas.', 'Salta hacia delante cayendo con la parte delantera del pie.', 'Salta de inmediato hacia atrás amortiguando la caída.', 'Mantén el tronco erguido y evita aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Mejora la potencia y elasticidad de los gemelos con saltos cortos en ambas direcciones.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7543'),
('7215ff4c-19c3-57d1-a6ab-a60f63d7871e', 'Desplazamiento adelante y atrás', ARRAY['Adopta una postura atlética con rodillas ligeramente flexionadas.', 'Da pasos rápidos y cortos hacia delante moviendo los brazos.', 'Cambia de dirección y retrocede con la misma cadencia.', 'Mantén el peso en la parte delantera del pie y evita cruzar las piernas.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y glúteos con pasos rápidos y cortos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9248'),
('4e36c9fe-f466-59cc-96e9-eb5551a7387f', 'Estiramiento de espalda con flexión hacia delante', ARRAY['De pie con los pies juntos, flexiona las rodillas ligeramente.', 'Baja el tronco hacia las piernas dejando caer la cabeza y los brazos.', 'Respira profundo y relaja la espalda sin forzar el rango.', 'Sube despacio vértebra a vértebra y evita rebotar en la posición.']::text[], 'principiante', 'Alarga la cadena posterior y descomprime la columna tras estar sentado o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6764'),
('c81dd6ac-6425-5309-a6b2-e96f9dd0f218', 'Saltitos hacia delante', ARRAY['De pie con los pies juntos y el cuerpo erguido.', 'Salta hacia delante con un impulso rápido de tobillos y rodillas.', 'Aterriza suavemente con la parte delantera del pie y repite.', 'Evita saltos largos y mantén el core activo en cada caída.']::text[], 'intermedio', 'Desarrolla la potencia de cuádriceps y gemelos con saltos cortos y reactivos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1698'),
('a61f5c39-bcf8-51fe-9d8e-588bdc9a47d1', 'Salto hacia adelante', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.', 'Balancea los brazos hacia atrás para generar impulso.', 'Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos.', 'Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Potencia cuádriceps, glúteos y gemelos con un salto explosivo y aterrizaje controlado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1472'),
('6fd75be0-c9dc-5be1-89d1-208ed8af5173', 'Zancada hacia adelante', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.', 'Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo.', 'Empuja con el pie derecho y vuelve a la posición inicial.', 'Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps mejorando el equilibrio y la estabilidad de la pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3470'),
('13b48dcc-5b6f-5e1d-8c48-76c428e531bd', 'Movilización de hombros con empuje hacia delante', ARRAY['De pie, entrelaza las manos delante del pecho con los codos altos.', 'Empuja las manos hacia delante separando los omóplatos.', 'Mantén el cuello relajado y respira al extender.', 'Vuelve despacio y evita encoger los hombros hacia las orejas.']::text[], 'principiante', 'Gana movilidad en el hombro y activa el deltoides antes de empujar o entrenar pecho.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11797'),
('c488da57-ed80-54db-b1ed-090331a09c00', 'Zancada con pulso y manos arriba', ARRAY['Colócate de pie con los brazos extendidos por encima de la cabeza.', 'Da un paso al frente y baja hasta que la rodilla trasera quede cerca del suelo.', 'Mantén la posición baja y haz pequeños pulsos sin subir del todo.', 'Aprieta el abdomen y evita que la rodilla delantera pase de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras activa hombros y core, mejorando el equilibrio y la estabilidad en posición unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3702'),
('9334d5e6-3f3e-5762-93d0-882e3ed40ba9', 'Plancha frontal con paso adelante', ARRAY['Apoya antebrazos y puntas de pies con el cuerpo en línea recta.', 'Aprieta glúteos y abdomen para no hundir la cadera.', 'Lleva un pie hacia delante junto a la mano y vuelve a la posición inicial.', 'Alterna los pies sin perder la alineación ni aguantar la respiración.']::text[], 'intermedio', 'Trabaja el abdomen y el core en isométrico mientras el paso adelante añade demanda de estabilidad y control lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3959'),
('00e714ac-d4e4-5916-af6b-6080a62cb9d6', 'Zancada adelante, lateral y atrás', ARRAY['De pie, da un paso al frente y baja flexionando ambas rodillas.', 'Vuelve al centro y da un paso lateral, empujando la cadera hacia atrás.', 'Regresa y da un paso atrás, controlando el descenso.', 'Mantén el tronco erguido y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Combina patrones de zancada para trabajar cuádriceps, glúteos y aductores, mejorando fuerza y control en varias direcciones.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3961'),
('dd696f25-5a31-5651-affb-5730e196a067', 'Postura del bastón de cuatro apoyos', ARRAY['Siéntate con las piernas estiradas y las palmas apoyadas detrás de la cadera.', 'Empuja el suelo con las manos y eleva la cadera hasta formar una línea recta.', 'Aprieta glúteos y abdomen, y mantén los hombros lejos de las orejas.', 'Respira con calma y evita bloquear los codos o dejar caer la cadera.']::text[], 'intermedio', 'Postura de yoga que fortalece tríceps, pecho y hombros, y mejora la estabilidad del core en apoyo invertido.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5914'),
('29d82f3c-44dd-5234-b676-021fffcfa3ee', 'Sentadilla Frankenstein con barra', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos.', 'Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de sentadilla con barra que enfatiza glúteos y control postural, útil para mejorar la técnica y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3194'),
('a69fb6cd-78fc-5619-a1bb-8af5a518b24e', 'Abdominal rana', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio de abdomen que suma flexión de cadera para trabajar la zona baja del recto abdominal y los flexores.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2429'),
('67638831-c78b-565b-ad75-701e82e40186', 'Saltos de rana', ARRAY['En cuclillas, con los pies algo abiertos y los brazos atrás.', 'Salta hacia delante extendiendo caderas y rodillas.', 'Aterriza suavemente con las rodillas alineadas con los pies.', 'Amortigua la caída y evita aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Ejercicio pliométrico que desarrolla potencia en cuádriceps y glúteos, con demanda de coordinación y aterrizaje seguro.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3088'),
('6ccf2e27-eb52-551f-8ec7-a44a0602248b', 'Postura de la rana mandukasana', ARRAY['Colócate a cuatro apoyos con las rodillas separadas hacia los lados.', 'Abre los pies hacia fuera y baja la cadera hacia el suelo.', 'Apoya antebrazos y mantén la espalda larga sin forzar.', 'Respira profundo y evita rebotar o forzar la apertura de cadera.']::text[], 'intermedio', 'Postura de yoga que abre aductores y caderas, mejorando la movilidad de la zona interna del muslo y la ingle.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6292'),
('693f1966-c03e-5034-bbdc-e8cd6e5dcadb', 'Hiperextensión inversa de rana en banco', ARRAY['Túmbate boca abajo en el banco con la cadera en el borde.', 'Junta las plantas de los pies y abre las rodillas.', 'Eleva las piernas apretando glúteos hasta alinear con el tronco.', 'Baja controlando y evita hiperextender la lumbar al subir.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales elevando las piernas en banco, con trabajo adicional de la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3870'),
('c837cba8-9dd6-5743-a4a7-9c52c844e65a', 'Abdominal de rana', ARRAY['Túmbate boca arriba con las plantas juntas y rodillas abiertas.', 'Coloca las manos detrás de la cabeza sin tirar del cuello.', 'Eleva el tronco acercando costillas a la pelvis.', 'Baja despacio y evita impulsarte con las piernas o el cuello.']::text[], 'intermedio', 'Encogimiento con piernas en rana que trabaja el abdomen y los oblicuos, añadiendo control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3889'),
('b87a061d-2a5c-53c4-a60a-62f58495f6e6', 'Sentadilla de rana', ARRAY['De pie, con los pies algo más anchos que la cadera y punteras hacia fuera.', 'Baja en cuclillas manteniendo el pecho alto y las rodillas alineadas.', 'Salta extendiendo piernas y cadera, y aterriza suave.', 'Amortigua con las rodillas y evita que se metan hacia dentro.']::text[], 'intermedio', 'Sentadilla pliométrica que potencia cuádriceps y glúteos, con trabajo de aductores y tobillos en el salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0461'),
('49ee2a38-9712-5384-9629-6c906c5f6b29', 'Frogger', ARRAY['En cuclillas, apoya las manos en el suelo delante de ti.', 'Salta hacia delante llevando los pies hacia las manos.', 'Vuelve a la posición de cuclillas y repite el salto.', 'Mantén el ritmo y evita redondear la espalda al saltar.']::text[], 'intermedio', 'Ejercicio cardiovascular que combina saltos y desplazamiento, elevando la frecuencia cardíaca y trabajando piernas y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3703'),
('3c66b7df-43ce-5ead-b7b6-4cf7e55953e7', 'Elevaciones de pierna adelante y atrás', ARRAY['De pie, apóyate en una pared o silla para mantener el equilibrio.', 'Eleva una pierna hacia delante sin mover el tronco.', 'Llévala hacia atrás controlando el movimiento.', 'Mantén el abdomen activo y evita arquear la lumbar.']::text[], 'principiante', 'Ejercicio de movilidad que activa glúteos y flexores de cadera, mejorando el control y la estabilidad pélvica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1563'),
('4cb0dea3-6484-580c-9ea3-5cab30598c97', 'Estiramiento de espinilla cruzando al frente', ARRAY['De pie, cruza una pierna por delante de la otra.', 'Apoya el empeine del pie cruzado en el suelo.', 'Lleva la cadera hacia delante hasta notar tensión en la espinilla.', 'Mantén sin rebotar y respira de forma relajada.']::text[], 'principiante', 'Estiramiento que relaja la espinilla y el tobillo, útil tras correr o caminar para mejorar la movilidad del pie.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2101'),
('fe8ea074-de91-5924-9b85-f5c661100a29', 'Patada frontal a la ingle', ARRAY['Colócate de pie con los pies a la anchura de los hombros y las manos en guardia.', 'Eleva la rodilla hacia delante y extiende la pierna con un movimiento rápido y controlado.', 'Golpea con el empeine o la espinilla, no con los dedos, y vuelve a la posición inicial.', 'Mantén el abdomen apretado y exhala al golpear para no perder el equilibrio.', 'Evita bloquear la rodilla al extender la pierna para proteger la articulación.']::text[], 'intermedio', 'Trabaja cuádriceps y cadera para golpear rápido y bajo, mejorando potencia y control en defensa personal.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2303'),
('d31b7752-0c4f-53e6-8829-380a103ed3e5', 'Patada frontal a la ingle en kickboxing con saco', ARRAY['Sitúate frente al saco a distancia de patada, con las manos en guardia y el peso en la pierna de apoyo.', 'Eleva la rodilla y extiende la pierna hacia el saco con un movimiento explosivo.', 'Impacta con el empeine o la espinilla y recupera la pierna rápidamente a la guardia.', 'Exhala en el golpe y mantén el core firme para no perder el equilibrio.', 'Evita golpear con los dedos del pie y no bloquees la rodilla al extender.']::text[], 'intermedio', 'Desarrolla potencia de pierna y cadera golpeando el saco, mejorando precisión y resistencia en combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4585'),
('46806d52-4f0c-5728-a70e-3d69074ab03d', 'Estiramiento frontal de isquiotibiales', ARRAY['Siéntate en el suelo con una pierna extendida y la otra flexionada con la planta apoyada.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Lleva las manos hacia el pie de la pierna extendida hasta notar un estiramiento suave.', 'Respira despacio y mantén la posición sin rebotar durante veinte o treinta segundos.', 'Evita curvar la espalda o forzar hasta el dolor para no sobrecargar la zona lumbar.']::text[], 'principiante', 'Estira la parte posterior del muslo y la zona lumbar para mejorar flexibilidad y aliviar tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3468'),
('6e1d4f07-ef3c-5e65-ac52-dc98b36454cf', 'Patada frontal de kickboxing con saco', ARRAY['Colócate frente al saco con las manos en guardia y el peso repartido.', 'Eleva la rodilla y extiende la pierna hacia el saco con control y velocidad.', 'Impacta con el empeine y vuelve a la guardia sin bajar la pierna de forma descontrolada.', 'Exhala al golpear y mantén el abdomen apretado para estabilizar el tronco.', 'Evita girar el cuerpo en exceso o golpear con los dedos del pie.']::text[], 'intermedio', 'Entrena potencia y técnica de patada frontal contra el saco, activando piernas, cadera y core.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4586'),
('78c66316-4905-5d0f-992e-638a6eaa01da', 'Rodillazo frontal de kickboxing con compañero', ARRAY['Colócate frente a tu compañero a distancia corta, con las manos en guardia.', 'Sujeta suavemente su hombro o guante para mantener el equilibrio.', 'Eleva la rodilla hacia delante de forma controlada y sin impactar con fuerza.', 'Exhala al subir la rodilla y mantén el core firme para no inclinarte atrás.', 'Evita golpear con fuerza real y coordina el ritmo con tu compañero.']::text[], 'intermedio', 'Fortalece cuádriceps, cadera y abdomen mediante rodillazos controlados, mejorando potencia y técnica de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4595'),
('401a4003-e94c-57e1-8f2a-aeab41d0f9ee', 'Patada de gancho delantera', ARRAY['Colócate de pie con las manos en guardia y el peso sobre la pierna de apoyo.', 'Eleva la pierna y dibuja un arco lateral con el pie, como un gancho.', 'Gira la cadera para acompañar el movimiento y vuelve a la posición inicial.', 'Mantén el abdomen apretado y exhala al ejecutar el gancho.', 'Evita perder el equilibrio inclinando el tronco demasiado hacia un lado.']::text[], 'intermedio', 'Trabaja glúteos y cadera con un movimiento circular de pierna, mejorando coordinación y potencia de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2302'),
('0262ebd5-2262-56c0-b9dc-28accdf17811', 'Elevación de pierna frontal con toque bajo la rodilla', ARRAY['De pie, con los pies juntos y los brazos relajados a los lados.', 'Eleva una rodilla hacia delante y toca por debajo con la mano contraria.', 'Baja la pierna con control y alterna el lado a un ritmo constante.', 'Mantén el tronco erguido y exhala en cada elevación.', 'Evita arquear la espalda o encorvarte para llegar con la mano.']::text[], 'intermedio', 'Activa abdomen y flexores de cadera con elevaciones rápidas, mejorando coordinación y control del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6094'),
('2b7ffdca-adf0-5f6c-8783-dde0beaa5180', 'Plancha frontal', ARRAY['Apoya antebrazos y puntas de los pies en el suelo, con codos bajo los hombros.', 'Alinea cabeza, espalda y piernas formando una línea recta.', 'Aprieta glúteos y abdomen para mantener la cadera sin caer ni subir.', 'Respira con normalidad y mantén la posición el tiempo indicado.', 'Evita hundir la zona lumbar o levantar la cadera en exceso.']::text[], 'intermedio', 'Fortalece abdomen, core y hombros en isométrico, mejorando la estabilidad del tronco y la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0463'),
('5653bb5e-09e4-582f-8f6c-2fc284093ae1', 'Plancha frontal con control de glúteos', ARRAY['Colócate en plancha sobre antebrazos con los codos bajo los hombros.', 'Aprieta los glúteos y el abdomen para alinear la cadera con el tronco.', 'Mantén la mirada al suelo y el cuello en posición neutra.', 'Respira de forma constante sin aguantar la respiración.', 'Evita que la cadera suba o baje; revisa la línea del cuerpo.']::text[], 'intermedio', 'Refuerza abdomen y glúteos en isométrico, corrigiendo la técnica y la estabilidad de la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2347'),
('62015db2-cb65-51f6-b94d-1058da2d28c4', 'Salto lateral en plancha frontal', ARRAY['Comienza en plancha alta con las manos bajo los hombros y los pies juntos.', 'Salta con los pies hacia un lado manteniendo el tronco estable.', 'Vuelve al centro y salta hacia el otro lado con ritmo controlado.', 'Exhala en cada salto y mantén el abdomen apretado.', 'Evita que la cadera se hunda o que los hombros se adelanten.']::text[], 'intermedio', 'Trabaja abdomen, oblicuos y hombros con saltos laterales, mejorando potencia y estabilidad del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3750'),
('1df93332-f8b6-5a8a-8a8b-dfda44523d8f', 'Plancha frontal a flexión', ARRAY['Empieza en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho hacia el suelo flexionando los codos cerca del torso.', 'Empuja para volver a la plancha alta manteniendo el abdomen firme.', 'Exhala al empujar y evita que la cadera se hunda.', 'No adelantes la cabeza ni bloquees los codos al extender.']::text[], 'intermedio', 'Combina isométrico y empuje para trabajar pecho, tríceps y core, mejorando fuerza y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2890'),
('acca329c-e2b1-5b85-ba85-380dbe97d5d0', 'Plancha frontal con toque de pies', ARRAY['Colócate en plancha alta con los pies a la anchura de la cadera.', 'Levanta un pie del suelo y tócalo con la mano contraria sin girar la cadera.', 'Vuelve a la posición inicial y alterna el lado con control.', 'Mantén el abdomen apretado y exhala en cada toque.', 'Evita balancear la cadera o encorvar la espalda.']::text[], 'intermedio', 'Activa abdomen, oblicuos y hombros con toques de pie, mejorando control y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4023'),
('98fa9ec2-9ece-566d-9e3e-f75e7d669037', 'Plancha frontal con toque de pie', ARRAY['Adopta una plancha alta con manos bajo los hombros y cuerpo alineado.', 'Levanta un pie y tócalo con la mano del mismo lado sin mover la cadera.', 'Regresa el pie al suelo y repite con el otro lado.', 'Mantén la respiración fluida y el abdomen apretado.', 'Evita girar el tronco o levantar la cadera al tocar el pie.']::text[], 'intermedio', 'Fortalece abdomen, oblicuos y glúteos en isométrico, mejorando el equilibrio y la estabilidad del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3814'),
('e10a9517-de7b-57e2-ae7a-c326150a2887', 'Caminata hacia delante en plancha', ARRAY['Comienza de pie y baja a la plancha alta apoyando las manos en el suelo.', 'Camina con las manos hacia delante manteniendo el cuerpo alineado.', 'Vuelve a caminar con las manos hacia atrás hasta ponerte de pie.', 'Mantén el abdomen firme y exhala durante el movimiento.', 'Evita que la cadera se hunda o que los pies se levanten del suelo.']::text[], 'intermedio', 'Trabaja abdomen, hombros y core con desplazamientos en plancha, mejorando fuerza y control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3854'),
('bc16fea7-64cb-5417-a811-8eb33953a45f', 'Plancha frontal con elevación de brazo', ARRAY['Colócate en plancha alta con las manos bajo los hombros y los pies juntos.', 'Levanta un brazo hacia delante sin girar la cadera ni el tronco.', 'Mantén la posición un instante y baja el brazo con control.', 'Alterna los brazos y respira de forma constante.', 'Evita balancear el cuerpo o hundir la zona lumbar al elevar el brazo.']::text[], 'intermedio', 'Refuerza abdomen, hombros y glúteos en isométrico, mejorando estabilidad y control del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2894'),
('57d6a990-e238-5f2b-b045-77856de6a493', 'Plancha frontal con giro', ARRAY['Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.', 'Activa el core y los glúteos para mantener una posición estable.', 'Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo.', 'Mantén las caderas y las piernas estables mientras giras.', 'Mantén la posición por un momento, luego regresa a la posición inicial.', 'Repite el giro hacia el lado izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos mientras mantienes el cuerpo estable, mejorando el control del core y la fuerza antirotación.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0464'),
('84c7fe2c-6ce5-5ec5-9e3f-7495c74af7a1', 'Patada frontal rápida', ARRAY['Colócate de pie con los pies a la anchura de los hombros y las manos en guardia.', 'Eleva la rodilla hacia el pecho y extiende la pierna hacia delante de forma rápida y controlada.', 'Recoge la pierna por el mismo camino y vuelve a la posición inicial sin bajar el talón de golpe.', 'Exhala en la extensión y evita bloquear la rodilla o perder el equilibrio del tronco.']::text[], 'intermedio', 'Potencia los cuádriceps y los flexores de cadera con un gesto explosivo que mejora la velocidad de pierna y la estabilidad del core.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2305'),
('0d199c67-5a84-565a-87aa-c6a948b30ac2', 'Patada frontal rápida de kickboxing en saco', ARRAY['Sitúate frente al saco en guardia, con el peso repartido y las manos protegiendo la cara.', 'Eleva la rodilla y extiende la pierna golpeando el saco con la parte delantera del pie.', 'Recoge la pierna rápidamente y vuelve a la guardia sin perder la postura.', 'Exhala en cada golpe y evita golpear con los dedos o bloquear la rodilla en la extensión.']::text[], 'intermedio', 'Desarrolla potencia de pierna y cadera golpeando el saco, mejorando la técnica de patada y la resistencia específica de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4587'),
('4972bd1b-a6f5-5c69-b6e3-20dbc0e15654', 'Plancha frontal a lateral', ARRAY['Apóyate en antebrazos y puntas de pies con el cuerpo alineado y el abdomen activo.', 'Gira el tronco hacia un lado llevando el peso a un antebrazo y abre el brazo libre hacia arriba.', 'Mantén la cadera alta y el cuerpo en línea recta durante la transición.', 'Vuelve al centro y repite hacia el otro lado, respirando de forma constante y sin hundir la cadera.']::text[], 'intermedio', 'Refuerza el abdomen, los oblicuos y los hombros alternando posiciones de plancha, mejorando la estabilidad y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3954'),
('f0073c35-1cde-5504-9f7c-4881fc44b68e', 'Toque de punta de pie', ARRAY['De pie con las piernas juntas, alarga la columna y activa ligeramente el abdomen.', 'Baja el tronco llevando las manos hacia las puntas de los pies sin redondear en exceso la espalda.', 'Mantén las rodillas ligeramente flexionadas y respira de forma pausada en la posición baja.', 'Sube de forma controlada y evita rebotar o forzar más allá de tu rango cómodo.']::text[], 'principiante', 'Mejora la flexibilidad de isquiotibiales y zona lumbar mientras activa el abdomen, útil para movilidad y control postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3248'),
('f2bffde9-269f-556c-82bc-b75faed87515', 'Postura del loto completo', ARRAY['Siéntate en el suelo con la espalda erguida y las piernas extendidas.', 'Cruza un pie sobre el muslo opuesto y después coloca el otro pie sobre el muslo contrario.', 'Mantén la columna alargada y las rodillas lo más cerca posible del suelo sin forzar.', 'Respira de forma lenta y evita tirar de las rodillas hacia abajo si sientes dolor en la rodilla.']::text[], 'intermedio', 'Abre caderas, ingles y tobillos en una postura de yoga sentada que favorece la relajación y la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1483'),
('8b26cae0-abcd-516c-bdf9-dd9c7f5d27ac', 'Maltesa completa', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados.', 'Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo.', 'Activa el core y mantén esta posición durante unos segundos.', 'Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio isométrico avanzado que exige fuerza de abdomen, hombros y pecho para mantener el cuerpo horizontal y estable.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3315'),
('8c4dbbdc-f354-5205-8014-946b8b80d240', 'Flexión en planche completa', ARRAY['Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.', 'Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.', 'Mientras te bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos.', 'Continúa bajando el cuerpo hasta que el pecho quede justo por encima del suelo.', 'Empuja con las manos y extiende los brazos para volver a subir el cuerpo a la posición inicial.', 'Mantén una línea recta desde la cabeza hasta los talones durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Trabaja pecho, hombros, tríceps y core con una flexión avanzada que exige gran control y fuerza en posición horizontal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3327'),
('246a6777-579c-5364-b6b3-77b0eaa0cdbe', 'Postura de la guirnalda', ARRAY['Ponte en cuclillas con los pies algo más anchos que las caderas y los talones apoyados.', 'Junta las palmas de las manos a la altura del pecho y usa los codos para abrir suavemente las rodillas.', 'Alarga la columna y lleva el peso hacia los talones sin levantar los pies.', 'Respira de forma profunda y evita redondear la espalda o forzar los tobillos.']::text[], 'intermedio', 'Estiramiento de yoga que abre caderas, ingles y tobillos, alivia la zona lumbar y mejora la movilidad para sentadillas profundas.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0951'),
('f7748672-e851-5df9-bcd0-cb6799070f85', 'Dominada Gironda al esternón', ARRAY['Ponte de pie frente a una barra alta con los pies separados a la altura de los hombros.', 'Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los dorsales y los bíceps para llevar el pecho hacia la barra, guiando con el esternón.', 'Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales, bíceps y romboides con un tirón que lleva el esternón hacia la barra, mejorando fuerza y control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0466'),
('9f8d9255-da8a-5391-a6b9-7652052eded5', 'Puente de glúteos con marcha', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.', 'Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho.', 'Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna.', 'Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales mientras estabilizas la cadera, mejorando el control del core y la fuerza del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3561'),
('bf544f07-6914-5700-b92b-82b45d8f0ad2', 'Puente de glúteos a una pierna en banco', ARRAY['Apoya un pie en el banco con la rodilla flexionada y extiende la otra pierna en el aire.', 'Empuja con el talón del pie apoyado para elevar la cadera hasta alinear tronco y muslo.', 'Aprieta el glúteo arriba y baja de forma controlada sin dejar caer la cadera.', 'Evita arquear la zona lumbar y mantén el abdomen activo durante todo el movimiento.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales de forma unilateral, mejorando la estabilidad de cadera y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2473'),
('6c9a852a-ed1f-504a-b647-4cc0fd8d34d6', 'Puente de glúteos a una pierna', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado, y la otra pierna extendida.', 'Empuja con el talón para elevar la cadera hasta formar una línea con el tronco y el muslo.', 'Aprieta el glúteo arriba y baja lentamente sin apoyar del todo la cadera.', 'Mantén el abdomen activo y evita arquear la espalda o girar la cadera.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales de forma unilateral en el suelo, mejorando la estabilidad de cadera y el control lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2475'),
('3015e933-5b32-5fb6-9907-bf96bf786658', 'Puente de glúteos con piernas en banco', ARRAY['Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo.', 'Coloca las manos en el banco junto a las caderas para mayor apoyo.', 'Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales con los pies elevados, aumentando el rango y mejorando la fuerza y el control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3523'),
('fbf18538-df5f-5faa-8087-05b0cae1684e', 'Puente de glúteos con dos piernas en el suelo', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados a la anchura de las caderas.', 'Empuja con los talones para elevar la cadera hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba y baja de forma controlada sin apoyar del todo.', 'Evita arquear la zona lumbar y mantén el abdomen activo durante todo el movimiento.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales y estabiliza la zona lumbar, mejorando la extensión de cadera y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2471'),
('cff916db-9fc1-5e4e-864d-c0c4336dd98c', 'Caminata en puente de glúteos', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados a la anchura de las caderas.', 'Eleva la pelvis hasta formar una línea recta entre rodillas, caderas y hombros.', 'Sin bajar la cadera, da pasos cortos hacia delante alternando los pies.', 'Mantén el abdomen apretado y respira de forma constante durante todo el recorrido.', 'Evita arquear la zona lumbar: si la notas, baja un poco la pelvis.']::text[], 'intermedio', 'Activa glúteos e isquios con el core estable, ideal para calentar y mejorar la estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6570'),
('59e95e91-ce2d-5a4b-be6c-aaba864d5c07', 'Abdominal completo en banco GHD', ARRAY['Colócate en el banco con los muslos apoyados y los pies fijados en los rodillos.', 'Cruza los brazos sobre el pecho y mantén la espalda neutra al inicio.', 'Sube el tronco flexionando el abdomen hasta quedar sentado, sin tirar del cuello.', 'Baja de forma lenta y controlada hasta la posición inicial.', 'Evita dejarte caer en la bajada para proteger la zona lumbar.']::text[], 'principiante', 'Trabaja el recto abdominal y los flexores de cadera con un recorrido amplio que exige control y fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10639'),
('4b59c1cb-af09-5eca-af5e-d464a59a8ffc', 'Extensión de cadera en banco de glúteos e isquios', ARRAY['Apoya el torso en el banco con las caderas en el borde y los pies fijados.', 'Mantén la espalda neutra y el abdomen activo antes de empezar.', 'Extiende las caderas elevando las piernas hasta alinear el cuerpo.', 'Aprieta los glúteos arriba un instante y baja despacio.', 'Evita hiperextender la lumbar al final del movimiento.']::text[], 'principiante', 'Aísla los glúteos y los isquios con extensión de cadera, útil para fortalecer la cadena posterior y la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4762'),
('fbd4a458-fadd-5e08-b19d-d3d2c03ec780', 'Abdominal y giro ruso en banco de glúteos e isquios', ARRAY['Siéntate en el banco con los pies fijados y el torso erguido.', 'Sube el tronco flexionando el abdomen hasta quedar incorporado.', 'Gira el torso a un lado y al otro de forma controlada.', 'Mantén el abdomen apretado y respira en cada giro.', 'Evita girar solo con los brazos: la rotación nace del tronco.']::text[], 'principiante', 'Combina flexión de tronco y rotación para trabajar recto abdominal y oblicuos, mejorando la fuerza rotacional del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4763'),
('b306948f-9c98-5ae8-92af-28b2ec07d422', 'Abdominal con brazos rectos en banco GHD', ARRAY['Colócate en el banco con los muslos apoyados y los pies fijados.', 'Extiende los brazos por encima de la cabeza con las manos juntas.', 'Sube el tronco flexionando el abdomen hasta quedar sentado.', 'Baja despacio manteniendo los brazos rectos y el abdomen activo.', 'Evita arquear la espalda al bajar: controla el recorrido.']::text[], 'intermedio', 'Refuerza el recto abdominal y el core con los brazos extendidos, aumentando la palanca y la exigencia del movimiento.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11282'),
('6d1bc7b9-a7e6-5443-8d09-ae7c32f8fd63', 'Hiperextensión con giro en banco de glúteos e isquios', ARRAY['Apoya el torso en el banco con las caderas en el borde y los pies fijados.', 'Baja el tronco de forma controlada manteniendo la espalda neutra.', 'Sube extendiendo la columna y añade un giro suave hacia un lado.', 'Alterna el giro en cada repetición sin forzar la lumbar.', 'Evita rotar con brusquedad: el movimiento debe ser fluido.']::text[], 'principiante', 'Fortalece la musculatura espinal y los oblicuos con extensión y rotación, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4764'),
('98ff28bd-fd7d-5edf-90e2-92bcea0816b2', 'Elevación de glúteos e isquios', ARRAY['Arrodíllate con los tobillos fijados y el cuerpo erguido.', 'Mantén caderas, tronco y cabeza alineados.', 'Baja el tronco hacia delante controlando con isquios y glúteos.', 'Sube apretando glúteos sin arquear la lumbar.', 'Evita impulsarte con las manos o perder la alineación.']::text[], 'intermedio', 'Ejercicio de cadena posterior que trabaja isquios y glúteos con el peso corporal, mejorando fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4456'),
('d9266479-2eae-5037-83b3-16777912da98', 'Elevación de glúteos e isquios con brazos extendidos', ARRAY['Colócate en la máquina con los tobillos fijados y el torso erguido.', 'Extiende los brazos al frente para mantener el equilibrio.', 'Baja el tronco controlando con isquios y glúteos.', 'Sube apretando glúteos sin perder la alineación.', 'Evita arquear la espalda al final del recorrido.']::text[], 'principiante', 'Variante que aísla isquios y glúteos con brazos extendidos, aumentando la exigencia de control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4890'),
('858f90b0-5018-538d-8c50-d346085210a6', 'Hiperextensión a una pierna en banco de glúteos e isquios', ARRAY['Apoya el torso en el banco con una pierna fijada y la otra libre.', 'Mantén la espalda neutra y el abdomen activo.', 'Extiende la cadera elevando la pierna libre hasta alinear el cuerpo.', 'Aprieta el glúteo arriba y baja despacio.', 'Evita rotar la pelvis: mantén las caderas niveladas.']::text[], 'principiante', 'Trabaja glúteos e isquios de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4765'),
('070882da-a7e0-5fd9-ad92-7f9ef3d221e3', 'Abdominal en máquina glúteo-isquio', ARRAY['Siéntate en la máquina con los pies fijados y la espalda apoyada.', 'Cruza los brazos sobre el pecho y activa el abdomen.', 'Sube el tronco flexionando el abdomen sin tirar del cuello.', 'Baja de forma lenta y controlada hasta la posición inicial.', 'Evita usar impulso: el movimiento nace del abdomen.']::text[], 'principiante', 'Fortalece el recto abdominal y los flexores de cadera con recorrido guiado, ideal para ganar fuerza de core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6554'),
('3b202461-1e4c-5b61-b195-73c2015fcdd1', 'Marcha de glúteos', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva la pelvis hasta formar una línea recta con el cuerpo.', 'Sin bajar la cadera, levanta un pie del suelo y vuelve a apoyarlo.', 'Alterna las piernas manteniendo el abdomen apretado.', 'Evita que la cadera caiga o se balancee durante la marcha.']::text[], 'intermedio', 'Activa glúteos y core en posición tumbada, perfecto para calentar y mejorar la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3394'),
('8c7064d8-8467-57d8-ab40-53d747f6a695', 'Sentadilla good morning', ARRAY['De pie con los pies a la anchura de las caderas y las manos en la nuca.', 'Haz una sentadilla parcial manteniendo el pecho alto.', 'Desde abajo, inclina el tronco hacia delante llevando la cadera atrás.', 'Vuelve a subir extendiendo caderas y rodillas a la vez.', 'Evita redondear la espalda: mantén la curvatura neutra.']::text[], 'intermedio', 'Combina sentadilla y bisagra de cadera para trabajar glúteos, isquios y cuádriceps, mejorando la fuerza global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4547'),
('b352a4e4-3091-5d0a-8865-53cc93620ce7', 'Dominada gorila', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera.', 'Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina dominada y elevación de rodillas para trabajar core, agarre y bíceps en un solo movimiento.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0467'),
('9e659373-7a6d-5b8c-912e-e42295a57ab0', 'Flexión saltamontes', ARRAY['Colócate en posición de flexión con las manos bajo los hombros.', 'Lleva una rodilla hacia el codo del mismo lado sin tocar el suelo.', 'Baja el pecho flexionando los codos de forma controlada.', 'Empuja para subir y alterna la rodilla en cada repetición.', 'Evita que la cadera suba o baje: mantén el cuerpo alineado.']::text[], 'intermedio', 'Variante de flexión que trabaja pectorales y tríceps con el core y los flexores de cadera en tensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0468'),
('17c38895-4cf0-55e4-af46-ccd8bb124f7c', 'Abdominal para aductores', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen junto con aductores y flexores de cadera para un core fuerte y una cadera estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0469'),
('4c2292a1-f87a-53b9-a82d-9b06199ded5e', 'Elevación de gemelos a una pierna en hack', ARRAY['Ajusta la máquina de trineo a un peso adecuado.', 'Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo.', 'Sujétate de las asas para mantener el equilibrio.', 'Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.', 'Cambia de pierna y repite el ejercicio.']::text[], 'intermedio', 'Aísla el gemelo a una pierna en máquina hack, sumando trabajo de isquios y glúteos para estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1384'),
('5454eaae-c4eb-589d-84d2-2716ef4c0ae8', 'Postura de media barca', ARRAY['Siéntate con las rodillas flexionadas y las plantas de los pies apoyadas en el suelo.', 'Inclina el tronco hacia atrás y eleva los pies hasta formar una V con el cuerpo.', 'Estira los brazos hacia delante paralelos al suelo y mantén la espalda recta.', 'Respira con normalidad y evita curvar la zona lumbar o encoger los hombros.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejorando el equilibrio y la estabilidad del core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6300'),
('cb5d9e3e-d714-5fcc-a7ea-c93369274702', 'Postura de media rana', ARRAY['Túmbate boca abajo con los codos apoyados bajo los hombros.', 'Flexiona una rodilla y sujeta el pie con la mano del mismo lado.', 'Acerca el talón al glúteo sin forzar la rodilla ni girar la cadera.', 'Mantén la respiración lenta y evita arquear en exceso la zona lumbar.']::text[], 'intermedio', 'Abre la cadera y estira los cuádriceps, aliviando tensión en la parte frontal del muslo.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6294'),
('1a8a702f-d4d4-55d2-9348-a3ea774477be', 'Media sentadilla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla.', 'Mantén el pecho elevado y el peso en los talones.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja piernas y glúteos con un rango parcial, útil para iniciar el patrón de sentadilla y elevar la frecuencia cardiaca.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3221'),
('afbc5886-342a-571d-aed8-d1294b2a8ead', 'Estiramiento de isquiotibiales a media rodilla', ARRAY['Arrodíllate sobre una rodilla con la otra pierna estirada hacia delante.', 'Coloca las manos en la cadera y mantén la espalda recta.', 'Inclina el tronco hacia delante desde la cadera hasta notar el estiramiento.', 'Respira despacio y evita redondear la espalda o bloquear la rodilla.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla, mejorando la flexibilidad de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10592'),
('0ddd168c-b06e-594f-9347-9004125ad218', 'Estiramiento de movilización de pectoral a media rodilla', ARRAY['Arrodíllate sobre una rodilla y sujeta el tubo con ambas manos frente al pecho.', 'Lleva los brazos hacia delante y abre el pecho sin arquear la lumbar.', 'Desliza el tubo hacia arriba y abajo con control, buscando amplitud.', 'Respira de forma constante y evita encoger los hombros hacia las orejas.']::text[], 'principiante', 'Moviliza el pecho y los hombros, mejorando la apertura torácica y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2935'),
('b6aedd31-4e1e-5d31-92b8-7382075e3c1b', 'Zancada lateral a media rodilla', ARRAY['Arrodíllate sobre una rodilla con la otra pierna extendida hacia el lado.', 'Apoya las manos en la cadera y mantén el tronco erguido.', 'Desplaza la cadera hacia el lado de la pierna estirada sin levantar el pie.', 'Respira con calma y evita girar el pie o forzar más allá de tu rango.']::text[], 'principiante', 'Moviliza aductores y cadera, ganando amplitud para sentadillas y desplazamientos laterales.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8987'),
('cd917602-dfe2-523e-8260-f4fdf7161e14', 'Giro de torso a media rodilla', ARRAY['Arrodíllate sobre una rodilla con la otra pierna apoyada delante.', 'Coloca las manos en la nuca o cruzadas sobre el pecho.', 'Gira el tronco lentamente hacia un lado y luego hacia el otro.', 'Respira de forma fluida y evita mover la cadera o tirar del cuello.']::text[], 'principiante', 'Moviliza la columna y los oblicuos, mejorando la rotación del tronco y la estabilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10566'),
('ee3f2d26-b9db-52b7-9716-2efdc432553d', 'Postura de la media luna', ARRAY['Parte de una postura de guerrero y apoya la mano delantera en el suelo.', 'Eleva la pierna trasera hasta alinearla con el tronco y abre la cadera.', 'Extiende el brazo superior hacia el techo y mira hacia arriba.', 'Respira con calma y evita bloquear la rodilla de apoyo o perder el equilibrio.']::text[], 'intermedio', 'Trabaja glúteos y equilibrio, fortaleciendo el core y abriendo la cadera en lateral.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0952'),
('53b648a4-6c6d-5d0a-9a2c-7175333a72eb', 'Estiramiento de cadera de media paloma', ARRAY['Desde a cuatro patas, adelanta una rodilla hacia la muñeca del mismo lado.', 'Extiende la pierna trasera hacia atrás y baja la cadera.', 'Inclina el tronco hacia delante sobre la pierna flexionada.', 'Respira despacio y evita forzar la rodilla o girar la cadera.']::text[], 'principiante', 'Libera tensión en glúteos y cadera, mejorando la rotación externa y el confort lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6761'),
('f6d2ac41-d225-5ea6-a1a5-291b77146571', 'Círculo de pierna medio sentado', ARRAY['Siéntate en el suelo con una pierna flexionada y la otra extendida.', 'Apoya las manos detrás del cuerpo para estabilizar el tronco.', 'Dibuja círculos lentos con la pierna extendida en ambos sentidos.', 'Respira con normalidad y evita arquear la lumbar o mover el tronco.']::text[], 'principiante', 'Moviliza la cadera y el glúteo, mejorando la coordinación y la amplitud articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6443'),
('f23a7c8f-abe4-5b50-8f29-5f2bbc05b5f7', 'Medio abdominal', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa la zona media y los flexores de cadera con un recorrido corto, ideal para aprender a controlar el abdomen.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3202'),
('437137a6-3aed-5456-b3b4-bf35ba38b1b0', 'Medio saludo al sol', ARRAY['De pie, inhala y eleva los brazos hacia el techo.', 'Exhala y baja el tronco hacia las piernas con la espalda larga.', 'Inhala para alargar la columna y exhala para profundizar el estiramiento.', 'Respira de forma fluida y evita bloquear las rodillas o forzar la lumbar.']::text[], 'intermedio', 'Moviliza la columna y estira isquiotibiales y hombros, activando el cuerpo de forma suave.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5982'),
('027a980d-40d2-54e1-ab68-8dc32bf3b010', 'Medio limpiaparabrisas', ARRAY['Túmbate boca arriba con las piernas flexionadas y elevadas.', 'Mantén los brazos extendidos a los lados para estabilizar el tronco.', 'Baja las rodillas hacia un lado y luego hacia el otro con control.', 'Respira de forma constante y evita despegar la lumbar del suelo.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos, mejorando el control del core y la rotación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1248'),
('eefcb2a7-a022-5deb-bb69-3bd142e187be', 'Dominada con agarre martillo', ARRAY['Cuélgate de la barra con las palmas enfrentadas y los brazos extendidos.', 'Activa los hombros y tira del cuerpo hacia arriba acercando el pecho a la barra.', 'Baja de forma controlada hasta extender los brazos sin balancearte.', 'Respira al subir y evita encoger los hombros o usar impulso.']::text[], 'intermedio', 'Fortalece dorsales y bíceps, mejorando la fuerza de tracción y el agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1865'),
('93965c60-d113-57e1-ba21-9b13fb4333b4', 'Puente de isquiotibiales', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados a la anchura de las caderas.', 'Aprieta los glúteos y empuja con los talones para elevar la cadera hasta formar una línea recta con el tronco.', 'Mantén dos segundos arriba mientras espiras y baja controlando sin dejar caer la cadera de golpe.', 'Evita arquear la zona lumbar en exceso: sube hasta donde puedas mantener las costillas abajo.']::text[], 'intermedio', 'Fortalece isquiotibiales y glúteos elevando la cadera desde el suelo, mejorando la extensión de cadera y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8358'),
('f75cf5b1-0710-5742-bba0-816911b7a827', 'Puente de isquiotibiales con patada', ARRAY['Colócate boca arriba con rodillas flexionadas y pies apoyados a la anchura de las caderas.', 'Eleva la cadera apretando glúteos hasta alinear tronco y muslos.', 'Estira una pierna sin mover la cadera y vuelve a flexionarla con control.', 'Alterna las piernas manteniendo la pelvis estable y sin rotar.', 'Baja la cadera al final evitando que la zona lumbar se arquee.']::text[], 'intermedio', 'Añade una extensión de rodilla al puente para exigir más a isquiotibiales y glúteos, ganando control y estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10905'),
('fe7f9c76-0b9e-53d9-a62e-1c2ab49ac596', 'Estiramiento de isquiotibiales tumbado', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Sujeta el muslo o la pantorrilla de la pierna flexionada y estírala hacia el techo.', 'Lleva suavemente la pierna hacia ti hasta notar tensión sin dolor.', 'Respira profundo y mantén la posición sin rebotar.', 'Evita levantar la cadera del suelo o bloquear la rodilla con fuerza.']::text[], 'principiante', 'Relaja la parte posterior del muslo tumbado, ideal tras entrenar o para ganar flexibilidad sin cargar la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1406'),
('11a97e8b-5772-5fa7-99c5-58ad28589ef1', 'Estiramiento de isquiotibiales', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha.', 'Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos.', 'Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.', 'Repite del otro lado.']::text[], 'principiante', 'Alarga la parte posterior del muslo y glúteos, mejorando la flexibilidad y reduciendo tensión tras el ejercicio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1511'),
('41e1b551-272b-5cde-b9c9-f3ba95b3aa3f', 'Abdominal con mano a rodilla opuesta', ARRAY['Túmbate boca arriba con rodillas flexionadas y manos suavemente detrás de la cabeza.', 'Eleva los hombros del suelo y lleva una mano hacia la rodilla opuesta.', 'Vuelve al centro y alterna el otro lado con control.', 'Espira al cruzar y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Trabaja recto abdominal y oblicuos cruzando el tronco, mejorando la estabilidad del core y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0470'),
('a55761e7-64de-510a-9da4-c80a3c00acf9', 'Colgado en handboard con medio crimp', ARRAY['Agarra el handboard con los dedos en medio crimp, sin hiperextender las articulaciones.', 'Cuelga con los brazos estirados y los hombros activos, sin encogerlos.', 'Mantén la posición el tiempo indicado respirando de forma constante.', 'Baja despacio y evita soltar de golpe o colgarte con los hombros relajados.']::text[], 'intermedio', 'Refuerza antebrazos y agarre en posición de medio crimp, clave para escalada y fuerza de dedos.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3834'),
('30efe063-8794-5b8d-aba9-9b0dba73d9f9', 'Colgado en handboard con codos a 135 grados', ARRAY['Agarra el handboard con firmeza y colócate con los codos flexionados a unos 135 grados.', 'Activa los hombros y mantén el cuerpo estable sin balancearte.', 'Sostén la posición el tiempo indicado respirando con normalidad.', 'Baja con control y evita perder el ángulo de los codos durante el tiempo.']::text[], 'intermedio', 'Isométrico que carga antebrazos, bíceps y dorsales manteniendo los codos a 135 grados, mejorando fuerza de agarre.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3836'),
('4a42a113-14e8-5c3a-b65f-f4b5951fe783', 'Colgado en handboard con codos a 90 grados', ARRAY['Agarra el handboard y flexiona los codos hasta unos 90 grados.', 'Mantén los hombros activos y el tronco estable sin columpiarte.', 'Sostén la posición el tiempo indicado con respiración constante.', 'Baja despacio y evita dejar caer los codos o perder la tensión.']::text[], 'intermedio', 'Isométrico exigente para antebrazos, bíceps y dorsales que mejora la fuerza de agarre y la resistencia en flexión.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3835'),
('fa6e1831-bd94-537b-9cf9-fe725e474203', 'Colgado en handboard con agarre abierto', ARRAY['Coloca los dedos en el handboard con agarre abierto, sin cerrar el pulgar en exceso.', 'Cuelga con los brazos estirados y los hombros activos.', 'Mantén la posición el tiempo indicado respirando de forma relajada.', 'Suelta con control y evita colgarte con los hombros caídos.']::text[], 'intermedio', 'Fortalece antebrazos y manos con agarre abierto, base para la fuerza de dedos y la prevención de lesiones.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3833'),
('57aeeae1-392a-564d-9b06-a81ed4b74096', 'Colgado en handboard con inclinación', ARRAY['Agarra el handboard inclinado con los dedos bien colocados.', 'Cuelga con los brazos estirados y los hombros activos.', 'Mantén la posición el tiempo indicado sin balancearte.', 'Baja despacio y evita perder el agarre por falta de tensión.']::text[], 'intermedio', 'Trabaja antebrazos y agarre en una superficie inclinada, aumentando la demanda sobre dedos y hombros.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3832'),
('32f32763-0043-5515-85c4-f297fedc643d', 'Bicicleta de brazos', ARRAY['Ajusta la altura del asiento y la posición del manillar a un nivel cómodo.', 'Siéntate en el ergómetro con la espalda recta y los pies sobre los pedales.', 'Sujeta las asas con las manos y coloca los brazos en un ángulo de 90 grados.', 'Comienza a pedalear con las manos, empujando y tirando de las asas con un movimiento controlado.', 'Continúa pedaleando durante el tiempo o el número de repeticiones deseado.']::text[], 'intermedio', 'Cardio de tren superior que activa pecho, hombros y tríceps, útil para trabajar el corazón sin cargar las piernas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2139'),
('7b3e8864-96c5-5fc0-ba00-48e053770af5', 'Toque de pies en círculo con manos entrelazadas', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Movilidad de cadena posterior y cadera que mejora la flexibilidad de isquiotibiales, glúteos y cuádriceps.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3218'),
('145d0a00-ffff-5529-b6d9-e04958d41454', 'Flexión con liberación de manos', ARRAY['Colócate en posición de flexión con manos bajo los hombros y cuerpo alineado.', 'Baja el pecho hasta cerca del suelo manteniendo el core firme.', 'Empuja para subir y, al llegar arriba, despega brevemente las manos del suelo.', 'Vuelve a apoyarlas con control y repite sin perder la alineación.', 'Evita hundir la cadera o adelantar la cabeza durante el movimiento.']::text[], 'intermedio', 'Variante de flexión que suma una fase de despegue de manos, trabajando pecho, tríceps y core con más control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3947'),
('45f69b80-5b4c-5788-8e6c-e348568a9817', 'Toque de pies en círculo con manos entrelazadas al revés', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Extiende las manos hacia abajo y entrelázalas detrás de las piernas.', 'Sube lentamente las manos en un movimiento circular por encima de la cabeza, manteniendo las piernas rectas.', 'Continúa el movimiento circular hasta que las manos toquen los dedos de los pies.', 'Invierte el movimiento y regresa las manos a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Movilidad que estira isquiotibiales, glúteos y cuádriceps con las manos entrelazadas en posición invertida.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3215'),
('992f94f2-fecd-513b-9adb-bfa67d441743', 'Postura de manos a los pies', ARRAY['Ponte de pie con los pies juntos y la espalda recta.', 'Inclínate hacia delante desde la cadera y lleva las manos hacia los pies.', 'Relaja el cuello y mantén las rodillas ligeramente flexionadas si lo necesitas.', 'Respira profundo y mantén la posición sin forzar ni rebotar.', 'Evita curvar la espalda en exceso o bloquear las rodillas con dolor.']::text[], 'principiante', 'Estiramiento de isquiotibiales y espalda baja que mejora la flexibilidad posterior y la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0953'),
('fe1e00a2-8eb9-5fa5-90fe-1265000d2b18', 'Parada de manos isométrica en la pared', ARRAY['Coloca las manos en el suelo a la anchura de los hombros y apoya los pies en la pared para subir.', 'Sube hasta quedar completamente invertido con el cuerpo alineado y los talones tocando la pared.', 'Aprieta el core y los glúteos para mantener la línea recta sin arquear la espalda.', 'Respira de forma controlada y mantén la posición el tiempo indicado antes de bajar con cuidado.', 'Evita encoger los hombros: empuja el suelo para alejar las orejas de los brazos.']::text[], 'avanzado', 'Fortalece hombros, tríceps y core mientras aprendes a mantener el equilibrio invertido con apoyo seguro en la pared.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6545'),
('6ba1279c-6c77-5ab3-96c6-973df0003ec8', 'Press de hombros en parada de manos con pared', ARRAY['Sube a la parada de manos con los talones apoyados en la pared y el cuerpo alineado.', 'Baja lentamente la cabeza hacia el suelo flexionando los codos sin perder la línea del tronco.', 'Empuja con fuerza para volver a extender los brazos y recuperar la posición inicial.', 'Mantén el core apretado y evita arquear la zona lumbar durante todo el recorrido.', 'Controla el tempo: baja en dos segundos y sube en uno para ganar fuerza.']::text[], 'avanzado', 'Trabaja hombros, tríceps y core con un press invertido que exige control y fuerza de empuje vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3916'),
('03a519a4-2a7c-505d-a82a-3f23279ee5d1', 'Estiramiento colgado en barra hacia atrás', ARRAY['Agárrate a la barra con las palmas hacia delante y los brazos extendidos.', 'Deja que el cuerpo cuelgue y empuja ligeramente la cadera hacia atrás para abrir los dorsales.', 'Relaja los hombros y respira profundo manteniendo el estiramiento sin rebotes.', 'Evita soltar de golpe: baja los pies con control al terminar.']::text[], 'principiante', 'Estira dorsales y hombros colgándote de la barra, aliviando tensión y mejorando la movilidad del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5146');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('42b5d3a2-3467-5734-9545-c3accfa51960', 'Front lever agrupado avanzado colgado', ARRAY['Cuélgate de la barra con agarre prono y los brazos completamente extendidos.', 'Recoge las rodillas hacia el pecho y eleva la cadera hasta llevar el tronco paralelo al suelo.', 'Aprieta el core y los dorsales para mantener la posición sin perder la horizontal.', 'Respira de forma corta y controlada durante el isométrico.', 'Evita encoger los hombros o perder la retracción escapular.']::text[], 'avanzado', 'Isométrico avanzado que exige gran tensión de abdominales, dorsales y core para mantener el cuerpo horizontal.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9044'),
('65318d41-87f1-5e43-b621-446078662cb5', 'Elevación alterna de rodillas colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y el cuerpo estable.', 'Eleva una rodilla hacia el pecho de forma controlada sin balancearte.', 'Baja la pierna lentamente y repite con la otra, alternando el ritmo.', 'Mantén el core apretado y evita usar impulso para subir las piernas.']::text[], 'intermedio', 'Activa abdominales y flexores de cadera con un movimiento alterno que también fortalece el agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10735'),
('240cc890-387f-50a6-993b-6ae643cc2f54', 'Bicho muerto colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y las piernas juntas.', 'Extiende una pierna hacia delante mientras la otra se mantiene recogida, imitando el bicho muerto.', 'Alterna las piernas de forma lenta y controlada sin balancear el cuerpo.', 'Aprieta el core y evita arquear la espalda o perder el control del tronco.']::text[], 'intermedio', 'Mejora el control abdominal y la coordinación colgado de la barra, trabajando core y flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4373'),
('d43c27b1-c2d5-55ac-be96-38777b0e703d', 'Patada de aleteo colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y las piernas rectas.', 'Eleva ligeramente las piernas y realiza patadas alternas pequeñas y rápidas.', 'Mantén el core apretado y evita balancear el tronco.', 'Controla la respiración y detén el movimiento si pierdes la postura.']::text[], 'intermedio', 'Trabaja la zona baja del abdomen y los flexores de cadera con un movimiento continuo y controlado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4766'),
('e1e27e60-af04-5cca-aa73-390306e03497', 'Front lever colgado', ARRAY['Cuélgate de la barra con agarre prono y brazos extendidos.', 'Eleva el cuerpo hasta quedar horizontal con las piernas rectas y juntas.', 'Aprieta el core, los glúteos y los dorsales para mantener la línea.', 'Respira de forma controlada y evita perder la horizontal o encoger los hombros.']::text[], 'avanzado', 'Isométrico exigente que fortalece abdominales, dorsales y hombros manteniendo el cuerpo horizontal.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9045'),
('59af4bbe-96bc-5521-aa16-729029c902b8', 'Elevación de front lever colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y el core activado.', 'Eleva las piernas rectas y la cadera hasta acercarte a la posición horizontal.', 'Mantén la tensión en dorsales y abdominales sin balancearte.', 'Baja con control y evita usar impulso para subir.']::text[], 'avanzado', 'Desarrolla fuerza abdominal y de dorsales elevando el cuerpo hacia la posición horizontal colgado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7251'),
('b9f79cc9-2250-50cd-9858-3b9c68614f68', 'Hollow colgado', ARRAY['Cuélgate de la barra con los brazos extendidos.', 'Recoge ligeramente las piernas y redondea la zona lumbar para crear la posición hueca.', 'Aprieta el abdomen y mantén la tensión sin balancearte.', 'Respira de forma controlada y evita perder la curvatura del tronco.']::text[], 'intermedio', 'Refuerza el core y la zona baja del abdomen manteniendo la posición hueca colgado de la barra.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6547'),
('db469298-5e00-57ae-a859-3ac915f3b6d2', 'Elevación de rodillas con círculo colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y el cuerpo estable.', 'Eleva las rodillas hacia el pecho y dibuja un círculo controlado con las piernas.', 'Mantén el core apretado y evita balancear el tronco.', 'Realiza el círculo en ambos sentidos de forma lenta y controlada.']::text[], 'intermedio', 'Trabaja abdominales y oblicuos con un movimiento circular que exige control y estabilidad colgado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4767'),
('193699e5-f166-5329-ae03-4b6aa2ea306a', 'Elevación de rodillas colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y las piernas juntas.', 'Eleva las rodillas hacia el pecho de forma controlada sin balancearte.', 'Aprieta el abdomen en la parte alta y baja las piernas lentamente.', 'Evita usar impulso y mantén los hombros activos.']::text[], 'intermedio', 'Fortalece abdominales, zona baja y flexores de cadera con un movimiento básico y efectivo colgado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9819'),
('91403354-46cf-53b0-83c3-09396e4cfdc7', 'Rodillas a los codos colgado', ARRAY['Cuélgate de la barra con los brazos extendidos y el core activado.', 'Eleva las rodillas hacia los codos llevando la cadera hacia arriba.', 'Aprieta el abdomen en la parte alta y baja con control.', 'Evita balancearte o usar impulso para subir las piernas.']::text[], 'intermedio', 'Ejercicio intenso para abdominales y oblicuos que exige fuerza de agarre y control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3890'),
('4dd37706-afd8-5c9b-802e-3771d3be92de', 'L-sit colgado', ARRAY['Cuélgate de la barra con los brazos extendidos.', 'Eleva las piernas rectas hasta formar un ángulo de 90 grados con el tronco.', 'Aprieta el core y mantén las piernas juntas y paralelas al suelo.', 'Respira de forma controlada y evita balancearte o perder la L.']::text[], 'intermedio', 'Isométrico que fortalece abdominales, flexores de cadera y antebrazos manteniendo las piernas en L.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '11877'),
('ed2a2306-5854-5da2-8d0d-57fac520edef', 'Elevación de piernas colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.', 'Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja abdominales y flexores de cadera elevando las piernas rectas colgado de la barra.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0472'),
('b3134675-077d-54b4-ab74-e94d8ed7e3cd', 'Elevación de rodillas oblicua colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite hacia el otro lado, girando el torso en la dirección opuesta.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos colgado de una barra, mejorando el control del core y la fuerza de agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1761'),
('5b9724f5-9b4a-5917-807f-28661ba45935', 'Pike colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas.', 'Continúa levantando hasta que el cuerpo forme una ''V'', con las piernas paralelas al suelo.', 'Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con las piernas rectas, exigiendo control del core y movilidad de isquios.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0473'),
('d8a7dce1-26b1-5f14-bb05-42735c7f39c1', 'Encogimiento escapular colgado', ARRAY['Cuélgate de la barra con los brazos estirados y los hombros relajados.', 'Sin doblar los codos, eleva los hombros hacia las orejas apretando los omóplatos.', 'Mantén un segundo arriba y baja despacio hasta la posición inicial.', 'Evita balancearte o encoger los codos para no perder tensión.']::text[], 'intermedio', 'Fortalece los trapecios y la espalda alta colgado de la barra, mejorando la estabilidad escapular y el agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4177'),
('21ba42a7-53f6-5c92-a032-1f77e75efa18', 'Inclinación lateral colgado', ARRAY['Cuélgate de la barra con los brazos estirados y el cuerpo recto.', 'Inclina las piernas juntas hacia un lado sin balancearte.', 'Vuelve al centro y repite hacia el otro lado de forma controlada.', 'Evita usar impulso y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Solicita los oblicuos y el abdomen inclinando el cuerpo colgado, mejorando el control lateral del core y el agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9489'),
('ccfa5640-23a2-5605-b587-97279bcd4ce4', 'Elevación de cadera con piernas rectas colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera elevando la cadera con las piernas rectas, ganando fuerza en el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0474'),
('7a300a86-1479-5816-8296-9811402b368a', 'Elevación de piernas rectas colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.', 'Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera subiendo las piernas rectas, mejorando el control del core colgado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0475'),
('3ae1bb74-ec35-5fba-9e7e-58b335f56b86', 'Elevación de cadera con piernas rectas y giro colgado', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas.', 'Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas.', 'Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Involucra abdomen y oblicuos elevando la cadera con giro, mejorando la fuerza rotacional del core y el agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0476'),
('cb27a058-a6b0-56cb-a306-db84fe5cf6e7', 'Isométrico de front lever agrupado colgado', ARRAY['Cuélgate de la barra y lleva las rodillas al pecho agrupándolas.', 'Inclina el torso hacia atrás hasta que la espalda quede paralela al suelo.', 'Aprieta el abdomen y los dorsales manteniendo la posición el tiempo indicado.', 'Evita perder la retroversión de pelvis o dejar caer las caderas.']::text[], 'avanzado', 'Mantiene el core y los dorsales en tensión con las rodillas agrupadas, base para progresar hacia el front lever.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9043'),
('5b7c0c5d-7e23-5d66-8eba-4ae00e2dee85', 'Sentadilla hawaiana', ARRAY['Colócate de pie con los pies juntos y el peso sobre las puntas.', 'Baja despacio llevando las rodillas hacia delante y el pecho erguido.', 'Mantén los talones elevados y el abdomen activo durante el descenso.', 'Sube empujando con los cuádriceps sin perder el equilibrio.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y aductores con una sentadilla profunda sobre las puntas, exigiendo movilidad y equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3365'),
('319a7999-07d1-5278-8aca-6a085ecc51ab', 'Headbanger', ARRAY['Colócate en cuadrupedia con las manos bajo los hombros.', 'Redondea la espalda llevando la barbilla al pecho y aprieta los glúteos.', 'Extiende la columna mirando al frente sin arquear en exceso el lumbar.', 'Realiza el movimiento lento y coordinado con la respiración.']::text[], 'principiante', 'Moviliza la columna y la espalda alta con control, activando glúteos e isquios para mejorar la extensión vertebral.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10736'),
('9ea747ac-49cb-5570-8558-30e14a230f31', 'Caída de talones', ARRAY['Colócate de pie sobre la punta de los pies en un escalón.', 'Déjate caer suavemente hasta que los talones bajen por debajo del nivel.', 'Recupera la posición elevando los talones de forma controlada.', 'Evita rebotes bruscos y mantén el equilibrio agarrado a un apoyo.']::text[], 'principiante', 'Moviliza tobillos y gemelos dejando caer los talones, mejorando la elasticidad del tendón de Aquiles y la propiocepción.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3872'),
('19ae2dbf-94aa-5806-bd95-90d3fc96e2b2', 'Puente de glúteos con talones', ARRAY['Túmbate boca arriba con las rodillas dobladas y los talones apoyados.', 'Empuja con los talones y eleva la cadera hasta alinear rodillas y hombros.', 'Aprieta los glúteos arriba y mantén un segundo antes de bajar.', 'Evita arquear el lumbar en exceso y no dejes caer la cadera de golpe.']::text[], 'intermedio', 'Activa glúteos e isquios apoyando los talones, mejorando la extensión de cadera y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6435'),
('944e1c7b-458b-56f1-aa0e-3cfab8fe9bb9', 'Presión de talón', ARRAY['Apoya el talón en el suelo con la punta del pie elevada.', 'Inclina el cuerpo hacia delante manteniendo la rodilla estirada.', 'Presiona el talón contra el suelo y mantén el estiramiento sin dolor.', 'Respira despacio y evita rebotar durante la posición.']::text[], 'principiante', 'Estira gemelos y sóleo presionando el talón contra el suelo, mejorando la movilidad del tobillo y la flexibilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5059'),
('7f95874a-a855-5f55-b375-f366ea2f5559', 'Patada de empuje con el talón', ARRAY['Colócate de pie con las manos en guardia y el abdomen activo.', 'Eleva la rodilla y extiende la pierna empujando con el talón al frente.', 'Recoge la pierna rápido y vuelve a la posición inicial.', 'Evita bloquear la rodilla de golpe y mantén el equilibrio.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con una patada de empuje, mejorando la potencia de piernas y el equilibrio del core.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2309'),
('366df135-b308-5fe9-bdb1-9fc05f684db1', 'Caminata talón punta', ARRAY['Colócate de pie y da un paso apoyando primero el talón.', 'Rueda el pie hasta la punta y empuja para dar el siguiente paso.', 'Mantén el torso erguido y el abdomen activo durante la caminata.', 'Camina despacio y evita mirar al suelo para no perder el equilibrio.']::text[], 'principiante', 'Moviliza tobillos, pies y gemelos caminando talón-punta, mejorando la propiocepción y la estabilidad del tren inferior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5970'),
('0e940a42-6c9f-57d7-9581-76df6fba9a05', 'Caminata sobre talones', ARRAY['Ponte de pie y apoya solo los talones en el suelo con las puntas levantadas.', 'Camina dando pasos cortos manteniendo el peso sobre los talones.', 'Mantén el torso erguido y la mirada al frente durante todo el recorrido.', 'Evita bloquear las rodillas o inclinarte hacia delante para no perder el equilibrio.']::text[], 'principiante', 'Activa gemelos y tibiales para mejorar el equilibrio y la fuerza del tobillo, útil como calentamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10294'),
('02cdf777-5bc3-5102-abc7-2e2c2f1d1729', 'Sentadilla deslizada en la pared', ARRAY['Apoya la espalda en la pared y separa los pies un paso hacia delante.', 'Desliza la espalda hacia abajo flexionando rodillas hasta unos 90 grados.', 'Empuja con los talones para subir controlando el movimiento.', 'No dejes que las rodillas se metan hacia dentro ni que los talones se levanten.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con apoyo en la pared, ideal para aprender el patrón de sentadilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8956'),
('98491ed0-9cb4-5ac1-94dc-6ae159e3b7c4', 'Postura del héroe', ARRAY['Arrodíllate con las rodillas juntas y siéntate sobre los talones.', 'Si te cuesta, coloca una manta o cojín bajo los glúteos.', 'Mantén la espalda recta y respira despacio durante varias respiraciones.', 'Evita forzar si sientes dolor agudo en rodillas o tobillos.']::text[], 'intermedio', 'Estira cuádriceps y flexores de cadera mientras abre tobillos, útil tras entrenar piernas o correr.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0954'),
('e704b571-6c04-5176-8689-f93f0d1f3c7c', 'Flexión inclinada en barra alta', ARRAY['Apoya las manos en una barra alta a la altura de la cadera y da un paso atrás.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Baja el pecho hacia la barra flexionando los codos y vuelve a subir.', 'No dejes caer la cadera ni bloquees los codos al final del recorrido.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros con una versión más accesible de la flexión, ideal para principiantes.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9312'),
('051262a0-2b26-5681-9701-1a863e814be6', 'Remo invertido en barra alta', ARRAY['Colócate bajo una barra alta y agárrala con las manos algo más abiertas que los hombros.', 'Cuelga con el cuerpo recto y los talones apoyados en el suelo.', 'Tira del pecho hacia la barra juntando las escápulas y baja controlando.', 'Evita encoger los hombros o arquear la zona lumbar durante el movimiento.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps con el peso corporal, mejorando la postura y la tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4917'),
('474d1e3b-1afc-5ea5-b9a8-c93e360b8f45', 'Subida a cajón alto', ARRAY['Colócate frente a un cajón estable con los pies a la anchura de la cadera.', 'Apoya un pie entero sobre el cajón y empuja con ese talón para subir.', 'Extiende la cadera arriba y baja controlando el mismo pie.', 'Evita impulsarte con la pierna de abajo o dejar caer el peso de golpe.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la potencia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10864'),
('db7d0166-b2ae-58e8-a12b-72e20ac720f0', 'Salto de valla y sprint con cambio de dirección', ARRAY['Colócate frente a una valla baja con los pies a la anchura de la cadera.', 'Salta la valla con ambos pies y aterriza con las rodillas ligeramente flexionadas.', 'Sprinta unos metros y cambia de dirección de forma controlada.', 'Evita aterrizar con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia de piernas y agilidad con un gesto explosivo útil en deportes de equipo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5990'),
('00371099-0c86-5d7b-a329-e7c983bf68a9', 'Salto de cuerda alto', ARRAY['Sujeta la cuerda con los codos cerca del cuerpo y las muñecas relajadas.', 'Salta más alto de lo normal manteniendo el torso erguido.', 'Gira la cuerda con las muñecas y aterriza suavemente con las rodillas flexionadas.', 'Evita saltar con los pies planos o encoger los hombros.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y la coordinación con un salto más alto que el habitual.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3678'),
('d39266ca-3774-57ae-b726-2ede70a060c4', 'Rodillas altas contra la pared', ARRAY['Ponte de pie frente a una pared con los pies separados a la altura de las caderas.', 'Coloca las manos en la pared para mayor apoyo.', 'Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo.', 'Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo.', 'Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible.', 'Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio.', 'Repite durante la duración o el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardiaca y activa piernas y glúteos, mejorando la coordinación y la postura en carrera.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3636'),
('e8029eb1-fdff-53b8-bbcd-ffa7fd2e72e3', 'Salto de cuerda con rodillas altas', ARRAY['Sujeta la cuerda y salta llevando las rodillas hacia el pecho de forma alterna.', 'Mantén el torso erguido y los codos cerca del cuerpo.', 'Gira la cuerda con las muñecas y aterriza con la parte delantera del pie.', 'Evita inclinarte hacia atrás o saltar demasiado alto.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa flexores de cadera y gemelos con un trabajo cardiovascular intenso.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3677'),
('d8f27290-a0c1-5d0b-a4f0-6d35eaeef2e9', 'Zancada con rodilla alta en bosu', ARRAY['Coloca el bosu con la cúpula hacia arriba y apoya un pie en el centro.', 'Sube llevando la rodilla contraria hacia el pecho.', 'Baja controlando el movimiento y repite cambiando de pierna.', 'Evita apoyar solo la punta del pie o perder el equilibrio por mirar al suelo.']::text[], 'intermedio', 'Mejora el equilibrio y la potencia unilateral trabajando cuádriceps y glúteos sobre superficie inestable.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5478'),
('010bafd9-a37f-58ce-b602-367b6c42c8e8', 'Carrera con rodillas altas', ARRAY['Corre en el sitio llevando las rodillas hacia la cadera de forma alterna.', 'Mantén el torso erguido y los brazos acompañando el movimiento.', 'Apoya la parte delantera del pie y mantén un ritmo constante.', 'Evita inclinarte hacia atrás o golpear el suelo con los talones.']::text[], 'intermedio', 'Aumenta la frecuencia cardíaca y activa flexores de cadera y core con un gesto de carrera exagerado.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3556'),
('651a5213-6cd3-53a7-b4dd-07b16833a1ce', 'Saltitos con rodillas altas', ARRAY['Realiza pequeños saltos alternando las rodillas hacia el pecho.', 'Mantén el torso erguido y los brazos en movimiento.', 'Aterriza suavemente con la parte delantera del pie.', 'Evita saltar demasiado alto o perder el ritmo.']::text[], 'intermedio', 'Trabajo cardiovascular y coordinativo que activa flexores de cadera y gemelos con bajo impacto.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3091'),
('29eea88a-3109-573a-a8e0-d049ed40ebad', 'Sprints con rodillas altas', ARRAY['Corre en el sitio a máxima velocidad llevando las rodillas bien altas.', 'Mantén el torso erguido y los brazos a 90 grados.', 'Apoya la parte delantera del pie y mantén un ritmo rápido y constante.', 'Evita inclinarte hacia atrás o encoger los hombros.']::text[], 'intermedio', 'Mejora la potencia y la resistencia anaeróbica con un gesto explosivo de carrera en el sitio.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3701'),
('4bdb0779-a9b8-5a13-b4b3-d69fafccc2f2', 'Sentadilla con rodillas altas', ARRAY['Ponte de pie con los pies a la anchura de la cadera.', 'Baja en sentadilla flexionando rodillas y cadera.', 'Al subir, lleva una rodilla hacia el pecho y alterna.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Combina fuerza de piernas y trabajo cardiovascular, activando cuádriceps, glúteos y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3092'),
('be5c2c2b-6270-5294-9d5e-13d7b1e33832', 'Subida al cajón con rodilla alta', ARRAY['Coloca un pie entero sobre el cajón con la rodilla alineada con el pie.', 'Empuja con la pierna de arriba y sube llevando la rodilla contraria a la altura de la cadera.', 'Baja controlando el movimiento hasta apoyar el pie en el suelo.', 'Evita impulsarte con la pierna de abajo y mantén el tronco erguido.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras mejora el equilibrio y la estabilidad de la cadera en cada subida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0479'),
('2f5f61c1-048d-5497-bace-de1dfe1a9ec8', 'Toque de rodilla alta', ARRAY['Ponte de pie con los pies a la anchura de las caderas.', 'Sube una rodilla hacia el pecho y toca con la mano contraria.', 'Alterna las piernas a un ritmo constante sin perder el equilibrio.', 'Mantén el abdomen activo y evita inclinar el tronco hacia atrás.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa el core y los flexores de cadera con un gesto rápido y controlado.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5537'),
('eae1b548-884c-58f7-8122-351d26bce2f4', 'Rodillas altas a talones al glúteo', ARRAY['Comienza de pie con una postura erguida y mirada al frente.', 'Lleva una rodilla al pecho y después el talón contrario al glúteo.', 'Alterna ambos gestos de forma fluida y rítmica.', 'Apoya con la parte delantera del pie y evita arquear la espalda.']::text[], 'intermedio', 'Trabajo cardiovascular que activa cuádriceps, isquios y gemelos alternando rodillas altas y talones al glúteo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4634'),
('caf711eb-6949-57ff-9171-a3062d0c3fc7', 'Giro con rodilla alta', ARRAY['De pie, con los brazos flexionados a la altura del pecho.', 'Sube una rodilla y gira el tronco hacia el lado contrario.', 'Alterna lados manteniendo un ritmo constante.', 'Gira desde el tronco, no desde la cadera, y evita forzar la zona lumbar.']::text[], 'intermedio', 'Ejercicio cardiovascular que suma rotación de tronco para activar oblicuos y mejorar la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0480'),
('2b747a22-9404-5ff0-a37a-f4856f390bcb', 'Caminata con rodillas altas', ARRAY['Camina despacio manteniendo el tronco erguido.', 'En cada paso, sube la rodilla hasta la altura de la cadera.', 'Apoya con cuidado y mantén el abdomen activo.', 'Evita inclinarte hacia atrás y no bloquees la rodilla de apoyo.']::text[], 'principiante', 'Movilidad dinámica que activa cuádriceps y flexores de cadera mientras mejora la coordinación al caminar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10759'),
('0fc8f777-9edc-504a-9889-365ad28cfb77', 'Rodillas altas y talones al glúteo', ARRAY['Empieza de pie con los brazos relajados.', 'Realiza varias repeticiones de rodillas altas al pecho.', 'Cambia a talones al glúteo durante el mismo tiempo.', 'Alterna los bloques sin parar y mantén la respiración constante.']::text[], 'intermedio', 'Combinación cardiovascular que activa isquios, cuádriceps y gemelos para elevar pulsaciones y mejorar la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0481'),
('fe541898-83c5-57e8-9f71-98626c83a715', 'Zancada con rodillas altas', ARRAY['Da un paso al frente y baja en zancada con la rodilla trasera cerca del suelo.', 'Al subir, eleva la rodilla de la pierna de atrás hacia el pecho.', 'Alterna las piernas manteniendo el tronco erguido.', 'Evita que la rodilla delantera pase por delante de la punta del pie.']::text[], 'intermedio', 'Ejercicio cardiovascular y de piernas que combina zancada y elevación de rodilla para activar glúteos y cuádriceps.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3952'),
('fec5bc5b-124a-5145-9b65-e02b5e16c337', 'Zancada alta', ARRAY['Desde de pie, da un paso largo atrás y baja la rodilla hacia el suelo.', 'Mantén la rodilla delantera alineada sobre el tobillo.', 'Alarga los brazos hacia arriba y abre el pecho.', 'Respira profundo y evita arquear la zona lumbar.']::text[], 'intermedio', 'Postura de yoga que estira flexores de cadera y fortalece cuádriceps y glúteos mientras mejora el equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5891'),
('dc9b8153-f64f-5b7a-9758-e498315d7ca4', 'Abducción de cadera', ARRAY['Ponte de pie o tumbado de lado con el cuerpo alineado.', 'Separa la pierna del cuerpo de forma controlada.', 'Mantén la pelvis estable y evita rotar el tronco.', 'Baja despacio y repite sin dejar caer la pierna.']::text[], 'principiante', 'Movilidad que activa los abductores y glúteos para mejorar la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2767'),
('aff8a1a4-8400-5be2-a5a3-168a8da295f6', 'Estiramiento de abducción de cadera con flexión al frente', ARRAY['Siéntate con las piernas abiertas y la espalda recta.', 'Flexiona el tronco hacia delante manteniendo la columna alargada.', 'Respira profundo y relaja los músculos de la cadera.', 'Evita rebotar y no fuerces más allá de una molestia leve.']::text[], 'principiante', 'Estiramiento que relaja abductores y glúteos, mejorando la movilidad de la cadera y la flexibilidad de la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1903'),
('58e19110-0f74-5f7d-aada-ce3c5410f865', 'Aducción de cadera', ARRAY['De pie o tumbado de lado, con la pelvis neutra.', 'Lleva la pierna hacia el centro del cuerpo de forma controlada.', 'Mantén el tronco estable y evita balancearte.', 'Vuelve despacio a la posición inicial y repite.']::text[], 'principiante', 'Movilidad que activa los aductores y la cara interna del muslo para mejorar el control y la estabilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2768'),
('ee3060a6-3356-572e-9ba7-be9c96185e99', 'Estiramiento en cuclillas con flexión de cadera y rodilla', ARRAY['Ponte en cuclillas con los pies algo más anchos que las caderas.', 'Baja la cadera y mantén los talones en el suelo.', 'Apoya los codos dentro de las rodillas y abre el pecho.', 'Respira profundo y evita levantar los talones o curvar la espalda.']::text[], 'principiante', 'Estiramiento que relaja glúteos, aductores y cuádriceps, mejorando la movilidad de cadera y rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1931'),
('002f2f88-8e05-5b00-acb9-3c1dd332a306', 'Estiramiento con círculos de cadera', ARRAY['Ponte de pie con las manos en la cintura.', 'Dibuja círculos amplios con la cadera en un sentido.', 'Cambia de sentido tras varias repeticiones.', 'Mantén las rodillas ligeramente flexionadas y evita mover el tronco.']::text[], 'principiante', 'Movilidad que relaja glúteos y flexores de cadera mientras mejora la circulación y la amplitud articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4286'),
('a2b4fd6e-0dad-5c80-a372-476276deac23', 'Almeja de cadera', ARRAY['Túmbate de lado con las rodillas flexionadas y los pies juntos.', 'Abre la rodilla de arriba sin mover la pelvis.', 'Mantén el abdomen activo y evita rotar el tronco hacia atrás.', 'Baja despacio y repite antes de cambiar de lado.']::text[], 'intermedio', 'Fortalece abductores y glúteos para estabilizar la cadera y prevenir molestias en la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4870'),
('4d340bf6-fff7-57d1-8f9f-3852a839ab9d', 'Abdominal de cadera con rodillas flexionadas', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva la cadera del suelo acercando las rodillas al pecho.', 'Contrae el abdomen y evita impulsarte con las piernas.', 'Baja despacio sin arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja la zona abdominal baja y los oblicuos para mejorar la estabilidad del core y el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0482'),
('952d182d-d6a4-533d-b56e-8b31ec2f2e49', 'Extensión de cadera', ARRAY['Túmbate boca abajo con las piernas estiradas y la frente apoyada en las manos.', 'Aprieta el glúteo y eleva una pierna recta sin arquear la zona lumbar.', 'Sube despacio contando dos segundos y baja controlando otros dos.', 'Evita girar la pelvis o compensar con la espalda baja.', 'Respira de forma continua y alterna las piernas.']::text[], 'principiante', 'Activa glúteos y femorales para mejorar la movilidad y estabilidad de la cadera en posición tumbada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2769'),
('90b6d814-cd33-58d5-ae74-6dc24c14cf24', 'Extensión de cadera de rodillas', ARRAY['Colócate en cuadrupedia con manos bajo hombros y rodillas bajo caderas.', 'Mantén la espalda neutra y activa el abdomen antes de moverte.', 'Lleva una rodilla flexionada hacia atrás apretando el glúteo, sin arquear la lumbar.', 'Vuelve despacio y alterna el lado.', 'Evita balancear el tronco o perder la posición de la pelvis.']::text[], 'principiante', 'Trabaja glúteos y core desde cuadrupedia, mejorando el control de la cadera y la estabilidad lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2115'),
('3fa8cb3f-063a-5a28-8a1b-7620749ef5eb', 'Estiramiento de extensión de cadera', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Lleva una rodilla al pecho y sujétala con las manos sin forzar.', 'Mantén el estiramiento entre veinte y treinta segundos respirando despacio.', 'Evita levantar la cabeza o arquear la zona lumbar.', 'Cambia de pierna y repite el mismo tiempo.']::text[], 'principiante', 'Estira glúteos y flexores de cadera para aliviar tensión y ganar rango en la extensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4673'),
('5d7a0a92-6e21-54cd-9041-9f340e14952f', 'Extensión de cadera con apoyo en la espalda', ARRAY['Túmbate boca arriba con los pies apoyados y las rodillas flexionadas.', 'Apoya bien la espalda y activa el abdomen antes de empezar.', 'Empuja con los talones y eleva la cadera apretando el glúteo arriba.', 'Baja controlando el movimiento sin dejar caer la pelvis de golpe.', 'Evita arquear la lumbar en el punto más alto.']::text[], 'principiante', 'Fortalece glúteos y femorales con apoyo dorsal, mejorando la estabilidad de la cadera y el core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2112'),
('407ea55c-fcdb-51b1-9657-b9d1a2b29461', 'Prueba de rotación externa de cadera', ARRAY['Siéntate en el suelo con las piernas estiradas y la espalda recta.', 'Gira una pierna hacia fuera manteniendo el muslo apoyado.', 'Observa hasta dónde llega sin compensar con la pelvis.', 'No fuerces el rango ni busques dolor en ningún momento.', 'Compara ambos lados y anota la diferencia.']::text[], 'principiante', 'Evalúa el rango de rotación externa de la cadera para detectar restricciones y orientar la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6787'),
('66a4b615-35c1-508f-bc4a-f3a9e636576e', 'Estiramiento de rotadores externos de cadera', ARRAY['Siéntate con una pierna estirada y la otra cruzada por encima.', 'Gira el tronco hacia el lado de la pierna cruzada apoyando el codo.', 'Mantén la posición veinte o treinta segundos respirando con calma.', 'Evita tirar del cuello o forzar la zona lumbar.', 'Cambia de lado y repite el estiramiento.']::text[], 'principiante', 'Relaja los rotadores externos y glúteos para mejorar la movilidad y reducir tensión en la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1944'),
('b5ca1e35-4e5b-5d4b-9fce-8ec9f24fcf59', 'Flexión de cadera', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Lleva una rodilla hacia el pecho sin despegar la lumbar del suelo.', 'Sube despacio y baja controlando el movimiento.', 'Evita impulsarte con la espalda o balancear la pierna.', 'Alterna las piernas manteniendo la respiración fluida.']::text[], 'principiante', 'Moviliza cuádriceps y flexores de cadera, mejorando el rango y el control del abdomen bajo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2770'),
('40323b92-986d-5e26-a4f0-9ee71f70fc43', 'Estiramiento de flexores de cadera con pie trasero elevado', ARRAY['Coloca el pie de atrás elevado sobre una superficie estable y da un paso al frente.', 'Baja la cadera y lleva la pelvis hacia delante sin arquear la lumbar.', 'Mantén el estiramiento veinte o treinta segundos respirando despacio.', 'Evita girar el tronco o forzar la rodilla trasera.', 'Cambia de pierna y repite el mismo tiempo.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera para contrarrestar el acortamiento por estar sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4674'),
('d2b60b0d-83ac-526e-b8ff-2cb89e91241e', 'Prueba de rotación interna de cadera', ARRAY['Siéntate en el suelo con las piernas estiradas y la espalda recta.', 'Gira una pierna hacia dentro manteniendo el muslo apoyado.', 'Observa el rango sin compensar con la pelvis ni el tronco.', 'No fuerces ni busques dolor durante la prueba.', 'Compara ambos lados y anota la diferencia.']::text[], 'principiante', 'Mide el rango de rotación interna de la cadera para detectar limitaciones y ajustar el trabajo de movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6788'),
('ad074b53-c538-5153-8485-8e46ac385e27', 'Rotación lateral de cadera', ARRAY['Siéntate con las piernas flexionadas y los pies apoyados en el suelo.', 'Abre una rodilla hacia fuera manteniendo el pie apoyado.', 'Controla el movimiento sin despegar la pelvis del suelo.', 'Vuelve despacio y alterna el lado.', 'Evita compensar girando el tronco o forzando la rodilla.']::text[], 'principiante', 'Mejora la rotación externa de cadera activando glúteos y aductores para un movimiento más libre.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2771'),
('43f80409-48a1-5cbc-8b1f-1c09176ccaea', 'Elevación de cadera con espalda baja despegada del suelo', ARRAY['Túmbate boca arriba con las piernas flexionadas y los brazos a los lados.', 'Aprieta el abdomen y despega la espalda baja del suelo elevando la cadera.', 'Mantén la posición un segundo y baja controlando el movimiento.', 'Evita arquear la lumbar o impulsarte con las piernas.', 'Respira de forma continua sin bloquear el aire.']::text[], 'intermedio', 'Trabaja el abdomen bajo y los flexores de cadera elevando la pelvis con control lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11010'),
('91565b3d-27c4-5891-b413-d3f2a90df23d', 'Rotación medial de cadera', ARRAY['Siéntate con las piernas flexionadas y los pies apoyados.', 'Lleva una rodilla hacia dentro manteniendo el pie en el suelo.', 'Controla el movimiento sin despegar la pelvis ni girar el tronco.', 'Vuelve despacio y alterna el lado.', 'Evita forzar la rodilla o buscar dolor en el rango final.']::text[], 'principiante', 'Moviliza la rotación interna de cadera activando aductores y glúteos para ganar rango funcional.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2772'),
('4ee39503-e330-5759-b46c-1c4cee13ee39', 'Elevación de cadera con rodillas flexionadas', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos a los lados, con las palmas hacia abajo.', 'Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece abdomen, glúteos y femorales con un movimiento controlado de elevación de pelvis.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0484'),
('3f45cfbb-695a-5c5e-9998-cd9cc93023b6', 'Puente con elevación de cadera', ARRAY['Túmbate boca arriba con los pies apoyados y las rodillas flexionadas.', 'Empuja con los talones y eleva la cadera apretando el glúteo.', 'Mantén la línea entre rodillas, cadera y hombros sin arquear la lumbar.', 'Baja controlando el movimiento hasta rozar el suelo.', 'Evita empujar con la espalda o juntar las rodillas.']::text[], 'intermedio', 'Activa glúteos y core elevando la pelvis para mejorar la estabilidad y la fuerza posterior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0486'),
('831ff540-22e9-54a0-a73e-0e4a12440d24', 'Abdominal con elevación de cadera', ARRAY['Túmbate boca arriba con las piernas flexionadas y las manos en la nuca.', 'Eleva la cadera despegando la lumbar mientras subes ligeramente el tronco.', 'Aprieta el abdomen arriba y baja controlando el movimiento.', 'Evita tirar del cuello o impulsarte con las piernas.', 'Respira exhalando al subir y alterna el ritmo.']::text[], 'intermedio', 'Combina crunch y elevación de pelvis para trabajar abdomen bajo, oblicuos y flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0487'),
('86626fdc-15d8-5dd6-a092-f985bf93cb9a', 'Plancha con balanceo de cadera', ARRAY['Colócate en plancha sobre antebrazos con codos bajo los hombros y cuerpo alineado.', 'Aprieta glúteos y abdomen para mantener la cadera neutra.', 'Balancea la cadera hacia un lado y luego hacia el otro sin tocar el suelo.', 'Evita hundir la zona lumbar o dejar caer la cadera al girar.']::text[], 'intermedio', 'Trabaja el core y los oblicuos mientras mantienes la estabilidad del tronco en apoyo isométrico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4385'),
('f80f2845-ab8b-5b56-8114-66d2d9a30786', 'Remolinos de cadera', ARRAY['Apoya las manos en la cadera y separa los pies a la anchura de los hombros.', 'Dibuja círculos amplios con la cadera hacia un lado y luego hacia el otro.', 'Mantén las rodillas ligeramente flexionadas y el abdomen activo.', 'Evita arquear la espalda o mover solo la cintura sin control.']::text[], 'principiante', 'Moviliza la cadera y activa glúteos y oblicuos para mejorar la rotación y la estabilidad pélvica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4615'),
('fad5433f-a681-541e-99f2-bca99062680f', 'Hip thrust', ARRAY['Túmbate boca arriba con rodillas flexionadas y pies apoyados a la anchura de la cadera.', 'Empuja con los talones y eleva la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja controlando el movimiento.', 'Evita arquear la zona lumbar en la parte alta del recorrido.']::text[], 'intermedio', 'Fortalece glúteos e isquios con extensión de cadera, mejorando la potencia y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2072'),
('009344b7-f5d2-5f88-bd0b-07da2dbbebea', 'Sentadilla isométrica', ARRAY['Separa los pies a la anchura de los hombros y baja la cadera como en sentadilla.', 'Detente cuando los muslos queden paralelos al suelo y mantén la posición.', 'Aprieta el abdomen y respira de forma constante sin aguantar el aire.', 'Evita que las rodillas se vayan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Mantiene la tensión en cuádriceps y glúteos para mejorar la resistencia muscular y la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6344'),
('b315dd2e-5259-5a6d-b0cd-c9b33f365f7e', 'Hollow rock', ARRAY['Túmbate boca arriba y eleva hombros y piernas formando una curva en la espalda.', 'Pega la zona lumbar al suelo y extiende los brazos por encima de la cabeza.', 'Balancea el cuerpo hacia delante y atrás manteniendo la forma.', 'Evita arquear la lumbar o perder la tensión abdominal al balancearte.']::text[], 'intermedio', 'Activa el abdomen profundo y los flexores de cadera con balanceo controlado sobre la espalda.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5649'),
('e809323f-68f4-5879-bc29-27e162726ffd', 'Patada de gancho de kickboxing', ARRAY['Colócate frente al saco en guardia con las manos arriba.', 'Gira la cadera y el pie de apoyo mientras lanzas la pierna en arco.', 'Impacta con el talón o el borde del pie y recupera la guardia.', 'Evita bloquear la rodilla o perder el equilibrio al girar.']::text[], 'intermedio', 'Desarrolla potencia de glúteos y rotación de tronco con un gesto técnico de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '4588'),
('a3bb2532-c761-5e5b-a4dd-05befa31f69a', 'Toque con rodillas altas a saltitos', ARRAY['Colócate de pie con el abdomen activo y los brazos preparados.', 'Salta ligeramente y sube una rodilla a la vez hacia el pecho.', 'Toca la rodilla con la mano contraria y alterna con ritmo.', 'Evita caer con las rodillas rígidas o inclinar el tronco hacia atrás.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa flexores de cadera y gemelos con un trabajo pliométrico.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9679'),
('7b63ff93-da27-57c3-8416-b50743eb17f1', 'Péndulo con saltos', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas.', 'Salta de un lado a otro como un péndulo, aterrizando suave.', 'Amortigua cada caída con las rodillas y mantén el tronco estable.', 'Evita aterrizar con las piernas rígidas o perder la alineación de rodillas.']::text[], 'intermedio', 'Mejora la potencia de cuádriceps y gemelos con saltos laterales que exigen control y equilibrio.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7341'),
('32e65554-a761-5f7b-b599-83e4c1975d09', 'Abrazo de rodillas al pecho', ARRAY['Comienza de pie con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.', 'Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos.', 'Mantén esta posición por un momento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira glúteos, isquios y zona lumbar para aliviar tensión tras el entrenamiento o la jornada sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1418'),
('cd2d3244-fbaf-56ca-b1ad-91403875b00f', 'Postura del guerrero humilde', ARRAY['Da un paso amplio hacia delante y flexiona la rodilla delantera.', 'Gira el torso hacia la pierna delantera y entrelaza las manos detrás de la espalda.', 'Inclina el tronco sobre la pierna delantera y relaja los hombros.', 'Evita forzar la rodilla delantera más allá del pie o curvar la espalda.']::text[], 'intermedio', 'Estira isquios y cuádriceps mientras abre el pecho y los hombros en una postura de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6341'),
('7141a090-c82e-503d-a683-5b6e83ad9eff', 'El cien', ARRAY['Túmbate boca arriba y eleva las piernas formando una mesa.', 'Sube la cabeza y los hombros y extiende los brazos junto al cuerpo.', 'Bombea los brazos arriba y abajo mientras respiras en cinco tiempos.', 'Evita tirar del cuello o despegar la zona lumbar del suelo.']::text[], 'intermedio', 'Activa el abdomen profundo con respiración rítmica y bombeo de brazos en posición de pilates.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2846'),
('8c8c1e8e-44af-5dd2-95cc-6e2599002a61', 'Caminata en el sitio en hidroterapia', ARRAY['Colócate erguido con el agua a la altura de la cintura o el pecho.', 'Levanta las rodillas alternativamente como si caminaras en el sitio.', 'Mantén el abdomen activo y los brazos relajados.', 'Evita movimientos bruscos o perder el equilibrio por el agua.']::text[], 'principiante', 'Activa la circulación y la musculatura de las piernas con un trabajo suave de readaptación.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '11656'),
('9f7c0006-e5a3-5375-b004-703c384f731e', 'Hiperextensión', ARRAY['Ajusta el banco de hiperextensiones para que la parte superior de los muslos quede apoyada en la almohadilla y los pies queden asegurados.', 'Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.', 'Baja la parte superior del cuerpo hacia el suelo manteniendo la espalda recta.', 'Haz una pausa breve en la parte baja, luego eleva la parte superior del cuerpo hasta que quede alineada con las piernas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la musculatura lumbar, glúteos e isquiotibiales, ayudando a mantener una espalda sana y estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0489'),
('9a058cc4-3a92-5247-9510-57cb5ee250bb', 'Fondos imposibles', ARRAY['Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.', 'Flexiona las rodillas y cruza los tobillos.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con un fondo exigente que requiere control y fuerza.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3289'),
('afe8fe9a-ec32-5f44-80c6-dcc506863c54', 'Gusano', ARRAY['Comienza de pie con los pies separados a la altura de las caderas.', 'Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.', 'Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.', 'Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.', 'Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el core y los hombros mientras estira la cadena posterior con un desplazamiento controlado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1471'),
('b60dcbb9-8972-5614-b44a-f7d79f8f1266', 'Gusano y escaladores', ARRAY['Desde de pie, flexiona el tronco y apoya las manos en el suelo con las piernas lo más rectas posible.', 'Camina con las manos hacia delante hasta quedar en plancha alta con el core firme.', 'Lleva una rodilla al pecho y alterna rápido como si corrieras en el sitio sin levantar la cadera.', 'Camina con las manos hacia atrás y vuelve a ponerte de pie para repetir.', 'Evita que la cadera se hunda o suba demasiado durante los escaladores.']::text[], 'intermedio', 'Combina desplazamiento y escaladores para elevar las pulsaciones y activar todo el cuerpo con tu propio peso.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5598'),
('8105f500-680e-5176-ab89-e922b203a31d', 'Patadas de aleteo alternas inclinadas', ARRAY['Túmbate boca arriba en el banco inclinado y agárrate por detrás de la cabeza o los lados.', 'Eleva las piernas estiradas unos centímetros del banco y mantén la zona lumbar pegada.', 'Alterna subir y bajar cada pierna con patadas cortas y rápidas sin tocar el banco.', 'Respira de forma continua y evita arquear la espalda baja.']::text[], 'intermedio', 'Trabaja la zona abdominal baja y los flexores de cadera con un movimiento continuo y controlado sobre una superficie inclinada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4768'),
('c88ec361-d44c-5644-9337-f8f07e8da649', 'Flexión inclinada con agarre cerrado con silla contra la pared', ARRAY['Coloca una silla firme contra la pared y apoya las manos en el borde con agarre cerrado.', 'Retrasa los pies hasta formar una línea recta desde la cabeza a los talones.', 'Baja el pecho hacia la silla manteniendo los codos pegados al cuerpo.', 'Empuja para volver arriba sin bloquear del todo los codos.', 'Evita que la cadera se hunda o que los codos se abran hacia fuera.']::text[], 'intermedio', 'Fortalece tríceps y pecho con una flexión facilitada por la inclinación, ideal para progresar hacia variantes más duras.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11315'),
('d97b80e3-aaeb-5565-8e0a-dd37a80afd43', 'Flexiones inclinadas con agarre cerrado', ARRAY['Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.', 'Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones.', 'Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados.', 'Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante accesible de la flexión que carga tríceps y pecho con menos peso corporal y buena técnica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0490'),
('f6a201f9-b812-5acd-bd62-b0157be9f2b4', 'Elevación de cadera inclinada', ARRAY['Túmbate boca arriba en el banco inclinado y sujétate por detrás de la cabeza.', 'Eleva las piernas y la cadera juntas hasta formar un ángulo recto con el tronco.', 'Baja despacio sin dejar que la zona lumbar se despegue del banco.', 'Exhala al subir y controla la bajada para no balancearte.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera elevando la pelvis de forma controlada sobre una superficie inclinada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9049'),
('3797bc5a-7b21-5797-aecc-88c1cfb07dd5', 'Plancha inclinada con jacks', ARRAY['Apoya las manos en un banco o superficie elevada y extiende el cuerpo en plancha.', 'Abre y cierra las piernas con un salto ligero manteniendo la cadera estable.', 'Mantén el core firme y la mirada al suelo durante todo el movimiento.', 'Evita que la cadera suba o baje al ritmo de los saltos.']::text[], 'intermedio', 'Combina plancha y saltos de piernas para trabajar core y elevar las pulsaciones con poco material.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10593'),
('0c31af3e-26b4-5321-988b-5dd562dab2ec', 'Elevación de cadera y piernas inclinada con piernas rectas', ARRAY['Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti.', 'Coloca las manos a los lados del banco para apoyarte.', 'Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera elevando piernas y pelvis rectas sobre un banco inclinado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0491'),
('481c5ae4-a8bf-5607-95fe-187c6467da0b', 'Push press inclinado', ARRAY['Coloca la barra a la altura del pecho con las manos algo más anchas que los hombros.', 'Flexiona ligeramente las rodillas y el tronco para cargar el impulso.', 'Extiende piernas y brazos a la vez para empujar la barra hacia delante y arriba.', 'Controla la vuelta de la barra al pecho sin dejarla caer.', 'Evita arquear la espalda o empujar solo con los brazos sin usar las piernas.']::text[], 'intermedio', 'Empuje explosivo con barra que involucra pecho, hombros y piernas para ganar potencia y fuerza general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1851'),
('567d89fe-332f-55b0-a761-8e9c302a1dfb', 'Flexiones inclinadas en banco', ARRAY['Apoya las manos en el borde de un banco, algo más anchas que los hombros.', 'Extiende las piernas hacia atrás formando una línea recta con el cuerpo.', 'Baja el pecho hacia el banco flexionando los codos unos 45 grados.', 'Empuja para volver arriba manteniendo el core activo.', 'Evita que la cadera se hunda o que la cabeza se adelante.']::text[], 'intermedio', 'Versión más sencilla de la flexión que trabaja pecho, tríceps y hombros con menor carga corporal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5637'),
('77979fb6-98ae-56b5-93bc-5b54186cad99', 'Flexiones inclinadas con salto en profundidad', ARRAY['Busca una superficie elevada, como un banco o un escalón, y coloca las manos separadas a la altura de los hombros en el borde.', 'Da un paso hacia atrás con los pies, manteniendo el cuerpo en línea recta desde la cabeza hasta los talones.', 'Baja el pecho hacia el borde de la superficie, doblando los codos y manteniendo el cuerpo alineado.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Salta desde el borde de la superficie, aterrizando suavemente con las rodillas ligeramente flexionadas.', 'Repite la flexión de brazos y el salto en profundidad durante el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico que desarrolla potencia de pecho y tríceps con un salto explosivo tras la flexión.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0492'),
('4ffdce4e-cfba-52dc-9535-f17bdc5f41a4', 'Flexión inclinada en barra smith', ARRAY['Coloca la barra del Smith a una altura cómoda y apoya las manos en ella.', 'Retrasa los pies hasta quedar en línea recta con el cuerpo.', 'Baja el pecho hacia la barra con los codos cerca del torso.', 'Empuja para volver arriba sin perder la alineación.', 'Evita apoyarte demasiado en la barra o dejar caer la cadera.']::text[], 'intermedio', 'Flexión apoyada en la barra guiada que permite ajustar la altura y trabajar pecho y tríceps con seguridad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6550'),
('30cbd097-7508-5d89-8842-6e144c80c398', 'Flexiones inclinadas con agarre inverso', ARRAY['Coloca las manos en el borde de un banco o una superficie elevada, ligeramente más separadas que la altura de los hombros.', 'Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.', 'Baja el pecho hacia el banco doblando los codos, manteniéndolos cerca de los costados.', 'Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de flexión con agarre invertido que enfatiza la parte superior del pecho y los tríceps.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0494'),
('eab0327a-cb89-5028-a0f4-cde65db16661', 'Hiperextensión inversa inclinada', ARRAY['Túmbate boca abajo en el banco inclinado sujetándote con las manos.', 'Con las piernas rectas, elévalas hasta alinear el cuerpo con el tronco.', 'Aprieta los glúteos arriba y baja despacio sin arquear la lumbar.', 'Evita usar impulso o subir más de la cuenta.']::text[], 'intermedio', 'Fortalece glúteos, isquios y zona lumbar elevando las piernas en un banco inclinado con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3180'),
('8684fc47-31c0-5f89-a5c5-874c48ee6c25', 'Flexión escapular inclinada', ARRAY['Coloca un banco inclinado a un ángulo de 45 grados.', 'Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.', 'Coloca los pies en el suelo, separados a la altura de las caderas.', 'Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.', 'Mientras bajas, retrae los omóplatos, apretándolos entre sí.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el serrato anterior y los estabilizadores del hombro con un movimiento corto de escápulas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3011'),
('cc7b7794-8b68-594d-a487-e00e6bcce83a', 'Toque de hombro inclinado', ARRAY['Apoya las manos en un banco y extiende el cuerpo en plancha alta.', 'Levanta una mano y toca el hombro contrario sin mover la cadera.', 'Vuelve a apoyar y alterna con el otro brazo a ritmo controlado.', 'Mantén el core firme y evita girar el tronco al tocar.']::text[], 'intermedio', 'Mejora la estabilidad del core y los hombros alternando toques en plancha inclinada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3348'),
('b5f9eae4-bbf1-5b9b-a475-075285b3a95d', 'Abdominal inclinado con giro', ARRAY['Túmbate en un banco inclinado con los pies fijados y las manos cerca de las sienes.', 'Sube el tronco mientras giras el torso hacia un lado, llevando el codo hacia la rodilla contraria.', 'Baja controlando el movimiento y alterna el giro en cada repetición.', 'Evita tirar del cuello con las manos y espira al subir.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos, mejorando la fuerza del core y la rotación del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1190'),
('98a89f9d-9a20-5ebe-ab42-802afadf38c6', 'Patinaje en línea', ARRAY['Colócate los patines y las protecciones antes de empezar.', 'Adopta una postura baja con las rodillas flexionadas y el tronco ligeramente inclinado.', 'Impulsa alternando las piernas y mantén un ritmo constante y controlado.', 'Evita bloquear las rodillas y frena siempre de forma progresiva.']::text[], 'intermedio', 'Ejercicio cardiovascular que activa piernas y glúteos mientras mejora el equilibrio y la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '7175'),
('5a684da1-8b50-5b15-b84b-085695382a21', 'Estiramiento de flexor de cadera y cuádriceps', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Sujétate de un objeto estable para mayor apoyo.', 'Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha.', 'Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta el estiramiento y repite en el lado izquierdo.']::text[], 'principiante', 'Estira la parte anterior del muslo y la cadera, aliviando tensión tras el entrenamiento o las horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1564'),
('87b0007f-1518-5642-b6af-7a69d0802eee', 'Movilización de hombros con rotación interna', ARRAY['Coloca el brazo a la altura del hombro con el codo flexionado a 90 grados.', 'Gira el antebrazo hacia dentro sin mover el codo de su sitio.', 'Mantén la posición unos segundos y vuelve despacio al inicio.', 'Evita compensar con el tronco o forzar el rango de movimiento.']::text[], 'principiante', 'Mejora la movilidad del hombro y la rotación interna, preparando la articulación para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11785'),
('8859723a-49d2-51ca-bde7-da1f97c33ecf', 'Estiramiento de rotación interna del hombro', ARRAY['Lleva el brazo por detrás de la espalda con el codo flexionado.', 'Tira suavemente del codo hacia el lado contrario sin dolor.', 'Mantén el estiramiento respirando de forma relajada.', 'Evita encoger el hombro o forzar más allá de lo cómodo.']::text[], 'principiante', 'Estira la parte posterior del hombro y la rotación interna, mejorando la flexibilidad de la articulación.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1991'),
('4ecb4596-b3fa-50f0-a0f0-5f5ec2c7c8ad', 'Curl femoral inverso con apoyo en banco', ARRAY['Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti.', 'Sujétate del banco para mayor apoyo.', 'Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos.', 'Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos usando el peso corporal, mejorando la fuerza posterior de la pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0496'),
('6573836f-271e-5ea9-ad54-7ae89ed538a9', 'Curl femoral inverso con almohadillas de banco', ARRAY['Colócate con los talones sobre las almohadillas y el cuerpo alineado.', 'Sube la cadera contrayendo glúteos e isquiotibiales hasta formar una línea recta.', 'Baja controlando el movimiento sin dejar caer la cadera.', 'Evita arquear la zona lumbar y mantén el abdomen activo.']::text[], 'intermedio', 'Trabaja los isquiotibiales y glúteos con el peso corporal, reforzando la cadena posterior y el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4988'),
('c22251f8-8f53-538d-9f30-961be08af841', 'Curl invertido de mentón entre sillas', ARRAY['Colócate entre dos sillas agarrando el borde con las palmas hacia ti.', 'Con las rodillas flexionadas, tira del cuerpo hacia arriba acercando el pecho.', 'Baja despacio controlando el movimiento hasta estirar los brazos.', 'Evita balancearte y mantén el core firme durante todo el recorrido.']::text[], 'intermedio', 'Fortalece bíceps y espalda usando el peso corporal, mejorando la fuerza de tracción en casa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3486'),
('0d8446cb-811a-5990-9bdd-bb6d12d111d5', 'Remo invertido', ARRAY['Coloca una barra a la altura de la cintura o usa un entrenador de suspensión.', 'Ponte de pie frente a la barra o al entrenador de suspensión, con los pies separados a la altura de los hombros.', 'Agarra la barra o las asas con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.', 'Tira del pecho hacia la barra o las asas, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con el peso corporal, mejorando la postura y la tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0499'),
('4cb78f0e-7695-5eb8-a19c-0ce2a709d7d7', 'Remo invertido con rodillas flexionadas bajo una mesa', ARRAY['Túmbate bajo una mesa firme y agarra el borde con las manos.', 'Con las rodillas flexionadas, tira del pecho hacia la mesa apretando la espalda.', 'Baja despacio hasta estirar los brazos sin perder la alineación.', 'Evita encoger los hombros y mantén el cuerpo recto.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps con el peso corporal, reforzando la tracción y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3382'),
('39cf4ec1-3388-5a90-9623-d15459d0e535', 'Remo invertido con rodillas flexionadas', ARRAY['Coloca una barra a la altura de la cintura y túmbate debajo de ella.', 'Agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Coloca el cuerpo de manera que los talones queden en el suelo y el cuerpo esté recto.', 'Tira del pecho hacia arriba en dirección a la barra apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con el peso corporal, mejorando la fuerza de tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2300'),
('b22c174d-78d5-5626-9afb-9c1bc08829fb', 'Remo invertido entre sillas', ARRAY['Coloca dos sillas estables y agarra sus bordes con las manos.', 'Con el cuerpo recto y los talones apoyados, tira del pecho hacia arriba.', 'Junta las escápulas en la subida y baja controlando el movimiento.', 'Evita dejar caer la cadera y mantén el abdomen activo.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps con el peso corporal, reforzando la tracción y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3388'),
('99275ac2-dc8e-5718-8691-c3e5852f24de', 'Remo invertido en banco', ARRAY['Coloca un banco a una altura que permita que el cuerpo cuelgue libremente debajo de él.', 'Túmbate boca arriba en el suelo con la cabeza hacia el banco.', 'Estira los brazos hacia arriba y agarra el banco con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Coloca el cuerpo de manera que los talones queden en el suelo y los brazos completamente extendidos.', 'Activa el core y aprieta los omóplatos entre sí mientras tiras del pecho hacia el banco.', 'Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con el peso corporal, mejorando la postura y la tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2298'),
('1cba45b9-b181-5357-aa82-7dd4e1e46279', 'Remo invertido deslizante', ARRAY['Colócate en posición de remo invertido con los brazos estirados.', 'Desliza el cuerpo hacia atrás mientras tiras del pecho hacia las manos.', 'Controla el deslizamiento de vuelta manteniendo el cuerpo alineado.', 'Evita arquear la espalda y mantén el core firme.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps con deslizamiento, mejorando la fuerza de tracción y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4769'),
('91f7fb7a-78f7-566c-ae5a-3c9e3c5d8831', 'Remo invertido deslizante en el suelo', ARRAY['Túmbate en el suelo y agarra un punto fijo con las manos.', 'Desliza el cuerpo hacia atrás mientras tiras del pecho hacia arriba.', 'Vuelve despacio controlando el movimiento y sin perder la alineación.', 'Evita encoger los hombros y mantén el abdomen activo.']::text[], 'intermedio', 'Fortalece la espalda y los bíceps deslizando el cuerpo, mejorando la tracción y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4974'),
('5dbd6ca6-9dc3-5182-9534-599bf80d8975', 'Remo invertido bajo una mesa', ARRAY['Túmbate bajo una mesa robusta y agarra el borde con las manos a la anchura de los hombros.', 'Mantén el cuerpo recto desde la cabeza hasta los talones y aprieta el abdomen.', 'Tira del pecho hacia el borde exhalando y baja controlando la inspiración.', 'Evita encoger los hombros hacia las orejas: junta las escápulas al subir.']::text[], 'intermedio', 'Fortalece dorsales y espalda alta tirando del borde de la mesa; mejora la postura y compensa el trabajo de empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3381'),
('7ddaf072-859a-5f6d-b7ed-0cbf07abf9e9', 'Remo invertido con sábana', ARRAY['Ata la sábana a un punto fijo resistente a la altura del pecho y sujeta ambos extremos.', 'Colócate inclinado hacia atrás con el cuerpo recto y los talones como apoyo.', 'Tira de la sábana llevando el pecho hacia las manos y aprieta las escápulas.', 'Baja despacio sin perder la línea del cuerpo y evita tirar con los brazos doblados de más.']::text[], 'intermedio', 'Trabaja dorsales y romboides con una sábana anudada; útil para entrenar espalda en casa sin material.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3749'),
('3e155af5-4bea-5a5a-86f3-3dbaeb2181c3', 'Remo invertido entre sillas con rodillas flexionadas', ARRAY['Coloca dos sillas estables enfrentadas y apoya una barra o palo entre ellas.', 'Siéntate debajo con las rodillas flexionadas y agarra el palo con las manos.', 'Tira del pecho hacia el palo exhalando y mantén el tronco firme.', 'Baja controlando el movimiento sin dejar caer los hombros hacia delante.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps usando dos sillas; versión accesible para principiantes.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3485'),
('1b2160a5-3afc-558e-bfa6-8be3f3a05b7d', 'Remo invertido con correas', ARRAY['Coloca un entrenador de suspensión o correas a la altura del pecho.', 'Ponte de pie frente al punto de anclaje y agarra las asas con agarre prono.', 'Camina con los pies hacia adelante, inclinándote hacia atrás hasta que el cuerpo quede en ángulo.', 'Mantén el cuerpo recto y activa el core.', 'Tira del pecho hacia las asas, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con correas de suspensión; mejora el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0498'),
('965ff64b-b095-5828-bcfd-b16ac005a6d9', 'Encogimiento invertido', ARRAY['Cuélgate boca abajo de una barra o mesa con los brazos extendidos y el cuerpo recto.', 'Sin doblar los codos, eleva los hombros hacia las orejas apretando los trapecios.', 'Mantén un segundo arriba y baja los hombros con control.', 'Evita balancear el cuerpo o usar impulso para subir.']::text[], 'intermedio', 'Activa los trapecios y la espalda alta colgado boca abajo; mejora la estabilidad de los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4049'),
('94776a62-a466-5de0-9bf3-65623aafaa67', 'Remo invertido supino entre sillas', ARRAY['Coloca dos sillas estables y apoya un palo entre ellas a la altura adecuada.', 'Túmbate debajo y agarra el palo con las palmas hacia ti, a la anchura de los hombros.', 'Tira del pecho hacia el palo flexionando los codos y aprieta las escápulas.', 'Baja despacio manteniendo el cuerpo recto y sin encoger los hombros.']::text[], 'intermedio', 'Trabaja dorsales y bíceps con agarre supino; potencia la flexión del codo y la espalda.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3538'),
('2f3538b4-5357-5730-a53a-f196fae9e86f', 'Remo invertido con agarre abierto', ARRAY['Agarra una barra o borde fijo con las manos más separadas que los hombros.', 'Mantén el cuerpo recto y los talones apoyados, con el abdomen activo.', 'Tira del pecho hacia la barra llevando los codos hacia fuera.', 'Evita subir los hombros o arquear la zona lumbar durante el tirón.']::text[], 'intermedio', 'Enfatiza la espalda alta y los deltoides posteriores con un agarre amplio; mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4770'),
('253d9b4d-4999-5301-b752-b1ad9d69a745', 'Remo invertido de abierto a cerrado', ARRAY['Sujeta las asas del entrenador de suspensión con los brazos extendidos y el cuerpo inclinado.', 'Realiza un tirón con agarre amplio llevando el pecho hacia las manos.', 'En la siguiente repetición junta las asas para un agarre cerrado y repite.', 'Mantén el cuerpo recto y evita balancearte para completar el movimiento.']::text[], 'intermedio', 'Combina agarre amplio y cerrado para trabajar toda la espalda y mejorar la coordinación escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4911'),
('38603ebf-d52e-50dc-a9d1-e0bced1ec718', 'Plancha cruz de hierro', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo recto.', 'Abre los pies y desplaza el peso alternando el apoyo de una mano.', 'Mantén la posición apretando el abdomen y respirando con normalidad.', 'Evita hundir la cadera o levantar los glúteos durante el tiempo de trabajo.']::text[], 'intermedio', 'Isométrico exigente para el core y los hombros; mejora la estabilidad y la fuerza del abdomen.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1193'),
('12cf6e05-dca2-5ba9-baf2-d47dda9e2317', 'Estiramiento cruz de hierro', ARRAY['Túmbate boca arriba con los brazos extendidos hacia los lados.', 'Levanta las piernas hacia el techo, manteniéndolas rectas.', 'Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies.', 'Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial.', 'Repite el estiramiento en el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Estira glúteos y zona posterior de la pierna; alivia tensión tras el entrenamiento o el estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1419'),
('9dda957c-6c10-5207-9191-f2c698840c94', 'Apretón isométrico de pecho', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra.', 'Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos.', 'Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho.', 'Suelta la contracción y relaja los músculos del pecho.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa pectorales y tríceps juntando las palmas; útil para calentar o reforzar el empuje.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1297'),
('e782bb72-3f91-5e48-bc20-8463b3b7dd33', 'Dominada supina cerrada isométrica', ARRAY['Cuélgate de la barra con las palmas hacia ti y las manos juntas.', 'Sube hasta la mitad o arriba del recorrido y mantén la posición.', 'Aprieta los dorsales y el abdomen sin balancear el cuerpo.', 'Baja con control al terminar el tiempo y evita soltarte de golpe.']::text[], 'intermedio', 'Mantiene la tensión en dorsales y bíceps con agarre cerrado; mejora la fuerza de tracción.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9320'),
('66987338-d249-5d20-b433-d26ab2d1761e', 'Flexión con pausa isométrica', ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo recto.', 'Baja hasta que los codos formen unos 90 grados y mantén la posición.', 'Aprieta el abdomen y los glúteos para no hundir la cadera.', 'Sube con control al acabar la pausa sin perder la alineación.']::text[], 'intermedio', 'Refuerza pecho, tríceps y core manteniendo la posición baja; mejora el control del empuje.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9325'),
('9d0453aa-63a6-5274-8c9a-45f366c6b853', 'Flexión abierta isométrica', ARRAY['Coloca las manos más anchas que los hombros y extiende el cuerpo en plancha.', 'Baja hasta la mitad del recorrido y mantén la posición sin tocar el suelo.', 'Mantén los codos hacia fuera y el core firme durante la pausa.', 'Evita dejar caer la cadera o adelantar la cabeza.']::text[], 'intermedio', 'Trabaja pectorales y hombros con manos separadas y pausa; mejora la estabilidad del empuje.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9311'),
('295ddf17-7277-58bc-ac85-f49e45e046e1', 'Tirón isométrico a media altura del muslo', ARRAY['Coloca la barra a la altura de la mitad del muslo y agarra con las manos firmes.', 'Adopta la posición de peso muerto con la espalda recta y el pecho arriba.', 'Tira de la barra sin moverla manteniendo la tensión en glúteos e isquios.', 'Evita redondear la espalda o contener la respiración durante el esfuerzo.']::text[], 'intermedio', 'Activa glúteos, isquios y espalda manteniendo la barra a media altura; mejora la fuerza del peso muerto.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9607'),
('302bdd70-de8c-5c8f-baee-cb4a99243f1e', 'Limpiaparabrisas isométrico', ARRAY['Comienza acostado boca arriba en una esterilla o un banco.', 'Extiende los brazos hacia los lados, perpendiculares al cuerpo.', 'Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas.', 'Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control.', 'Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial.', 'Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho y los hombros manteniendo el cuerpo estático en tensión, mejorando la estabilidad y la fuerza en el rango medio.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0500'),
('e46c4d58-eecd-57ce-9890-31d7e1c5260d', 'Extensión isométrica de muñeca', ARRAY['Coloca el antebrazo sobre el muslo con la mano fuera de la rodilla y la palma hacia abajo.', 'Extiende la muñeca hacia arriba y sujétala con la otra mano para crear resistencia.', 'Mantén la tensión entre quince y treinta segundos sin mover la articulación.', 'Respira con normalidad y evita encoger el hombro o girar el tronco.']::text[], 'intermedio', 'Fortalece los extensores de la muñeca y el antebrazo manteniendo la posición sin movimiento, útil para prevenir molestias en el codo.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9995'),
('7fd6f34d-aa79-5e0e-8c80-cc8575b08721', 'Burpee con tijeras', ARRAY['Comienza de pie con los pies separados a la altura de los hombros.', 'Baja el cuerpo a una posición de sentadilla, colocando las manos en el suelo frente a ti.', 'Lanza los pies hacia atrás, aterrizando en posición de flexión de brazos.', 'Realiza una flexión de brazos, bajando el pecho hacia el suelo y luego empujando de nuevo hacia arriba.', 'Salta con los pies hacia adelante, aterrizando en posición de sentadilla.', 'Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza.', 'Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca combinando sentadilla, plancha y salto, mejorando la resistencia y la coordinación de todo el cuerpo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0501'),
('d81fd747-491f-5c62-8d3c-412a98811242', 'Burpee con salto de tijera y flexión', ARRAY['Desde de pie, baja a la plancha y realiza una flexión con el pecho cerca del suelo.', 'Recoge los pies hacia las manos y salta abriendo y cerrando piernas y brazos.', 'Aterriza con las rodillas ligeramente flexionadas y el tronco erguido.', 'Mantén un ritmo constante y evita arquear la zona lumbar en la plancha.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que suma una flexión al burpee, implicando pecho, tríceps y piernas en un esfuerzo intenso.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3970'),
('dc62380f-8885-5ecb-a62a-7f8213e7b295', 'Jumping jack', ARRAY['Ponte de pie con los pies juntos y los brazos a los costados.', 'Salta, separando los pies y levantando los brazos por encima de la cabeza.', 'Al aterrizar, salta rápidamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Actividad cardiovascular clásica que activa piernas y brazos, elevando el pulso y mejorando la coordinación y la resistencia.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3224'),
('69396ec9-a69b-5a66-b4cb-1f511d0b8121', 'Navaja en el suelo', ARRAY['Túmbate boca arriba con brazos extendidos por encima de la cabeza y piernas estiradas.', 'Eleva a la vez el tronco y las piernas hasta tocar los pies con las manos.', 'Baja de forma controlada sin dejar caer los pies de golpe al suelo.', 'Exhala al subir e inhala al bajar, evitando tirar del cuello.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera elevando tronco y piernas a la vez, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0502'),
('14cb6f92-f1a9-5dfd-a237-250055dc625b', 'Navaja en balón', ARRAY['Coloca la espalda sobre el balón con los pies apoyados y los brazos extendidos.', 'Eleva el tronco y las piernas a la vez formando una V con el cuerpo.', 'Sujeta el balón con los pies o las manos según tu variante y controla la bajada.', 'Mantén el abdomen apretado y evita arquear la espalda al extenderte.']::text[], 'principiante', 'Con el balón bajo la espalda, trabaja el abdomen y los flexores de cadera con mayor rango y control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0503'),
('ef3c67f3-29ff-508a-86d2-b6b9496b5dce', 'Plancha jack', ARRAY['Colócate en plancha alta con manos bajo los hombros y cuerpo alineado.', 'Salta abriendo y cerrando las piernas sin mover el tronco.', 'Mantén la cadera baja y el abdomen apretado durante todo el ejercicio.', 'Respira de forma constante y evita hundir la zona lumbar.']::text[], 'intermedio', 'Plancha dinámica que suma saltos de piernas, trabajando abdomen, hombros y core con un extra cardiovascular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1478'),
('752b23d1-8e08-59b7-81f2-68550552d067', 'Plancha jack sobre balón medicinal', ARRAY['Apoya las manos sobre el balón medicinal y extiende el cuerpo en plancha.', 'Salta abriendo y cerrando las piernas manteniendo el tronco firme.', 'Aprieta el abdomen y evita que el balón ruede hacia delante.', 'Respira con ritmo y baja la intensidad si pierdes la alineación.']::text[], 'intermedio', 'Variante inestable que exige más al core y los hombros mientras las piernas saltan, mejorando el equilibrio y la fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2564'),
('50e1cb7c-55f4-5280-b0ed-a9392a8e97f3', 'Press jack', ARRAY['De pie con una mancuerna en cada mano a la altura de los hombros.', 'Salta abriendo piernas mientras empujas las mancuernas por encima de la cabeza.', 'Vuelve a la posición inicial cerrando piernas y bajando los brazos.', 'Mantén el abdomen firme y evita arquear la espalda al press.']::text[], 'intermedio', 'Combina saltos de tijera con press de hombros, elevando el pulso y trabajando hombros, tríceps y piernas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0504'),
('21c440bf-5341-5ae2-b2be-bea224d2e5ed', 'Abdominales jack con piernas abiertas', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas flexionadas.', 'Eleva el tronco mientras abres las piernas hacia los lados.', 'Vuelve al centro y baja el tronco de forma controlada.', 'Evita tirar del cuello y exhala al subir.']::text[], 'intermedio', 'Encogimiento dinámico que suma apertura de piernas, trabajando abdomen, oblicuos y flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0505'),
('6940c346-78ee-564a-ac57-63da1893db0d', 'Paso de tijera', ARRAY['De pie, da un paso lateral amplio y flexiona la rodilla de ese lado.', 'Impulsa con la pierna para volver al centro y repite hacia el otro lado.', 'Mantén el tronco erguido y los brazos acompañando el movimiento.', 'Aterriza con suavidad y evita juntar demasiado las rodillas.']::text[], 'intermedio', 'Paso lateral con salto que activa piernas y glúteos, mejorando la coordinación y elevando la frecuencia cardíaca.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4438'),
('88a82485-3756-56e8-8fac-f6d831f001f6', 'Navaja', ARRAY['Túmbate boca arriba con brazos extendidos y piernas estiradas.', 'Eleva tronco y piernas a la vez buscando formar una V.', 'Sujeta un instante arriba y baja con control sin apoyar del todo.', 'Exhala al subir e inhala al bajar, manteniendo el abdomen activo.']::text[], 'intermedio', 'Ejercicio de pilates que flexiona el cuerpo en V, fortaleciendo el abdomen profundo y los flexores de cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '6103'),
('d32c312e-dcf2-50a9-9cf5-2c302a7beadd', 'Abdominal Janda', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Encogimiento con pies juntos que activa el abdomen y la zona lumbar, mejorando la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0508'),
('19499db4-4398-5271-83d6-1c8a6c6e3254', 'Salto sobre cajón', ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas.', 'Flexiona rodillas y caderas y salta con fuerza para subir al cajón.', 'Aterriza con las rodillas alineadas y el tronco ligeramente inclinado.', 'Baja con control y evita saltar con las rodillas hacia dentro.']::text[], 'intermedio', 'Ejercicio pliométrico que desarrolla potencia en cuádriceps y glúteos, mejorando la explosividad y el control del aterrizaje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3887'),
('34e3ad0c-0ac8-560a-b3d9-29606bef038b', 'Salto desde sentado', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados.', 'Impulsa con los brazos y las piernas para saltar hacia arriba con fuerza.', 'Aterriza con las rodillas alineadas y amortigua el impacto.', 'Evita bloquear las rodillas o caer con las piernas rígidas.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un impulso explosivo que mejora la potencia de piernas y la reactividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10053'),
('f9f2d2a2-7d1b-544a-91ba-f8357bd4215d', 'Zancada con salto a jack', ARRAY['Parte en zancada con una pierna delante y otra detrás.', 'Salta y cambia a posición de jack abriendo piernas y brazos.', 'Vuelve a la zancada alternando la pierna adelantada.', 'Mantén el torso erguido y evita que la rodilla delantera pase la punta del pie.']::text[], 'intermedio', 'Combina zancada y salto abriendo piernas para elevar las pulsaciones y trabajar piernas y hombros.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0510'),
('4f5d2739-d583-5cf7-bf9e-ac40b77e2b50', 'Sentadilla pistol con salto sobre cajón', ARRAY['Colócate sobre una pierna frente al cajón con la otra extendida al frente.', 'Baja en sentadilla pistol controlando el equilibrio.', 'Impulsa con fuerza y salta sobre el cajón.', 'Aterriza con la rodilla flexionada y amortigua sin dejarla caer hacia dentro.']::text[], 'avanzado', 'Ejercicio explosivo unilateral que potencia cuádriceps y glúteos y mejora el control en el aterrizaje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4168'),
('8c17c147-0c80-5e84-bedd-b11513ab8770', 'Saltar la cuerda', ARRAY['Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies.', 'Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar.', 'Continúa saltando durante el tiempo o el número de repeticiones deseado.']::text[], 'intermedio', 'Cardio clásico que eleva las pulsaciones y trabaja pantorrillas, cuádriceps y glúteos con bajo impacto articular.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2612'),
('61649fb2-b16f-504b-bca1-3bbaa65d3f67', 'Encogimiento con salto', ARRAY['Sujeta la barra con las manos a la altura de los muslos y la espalda recta.', 'Flexiona ligeramente las rodillas y encoge los hombros con fuerza.', 'Extiende las piernas y salta impulsándote con la cadera.', 'Aterriza con las rodillas flexionadas y evita redondear la espalda.']::text[], 'avanzado', 'Movimiento explosivo con barra que activa glúteos y trapecios para mejorar la potencia de cadera y hombros.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4964'),
('70db334a-9125-5630-83db-2522f97ca64d', 'Salto de cuerda', ARRAY['Sujeta la cuerda con los codos cerca del cuerpo y las muñecas relajadas.', 'Gira la cuerda con las muñecas y salta con los pies juntos.', 'Mantén saltos bajos y un ritmo constante respirando de forma regular.', 'Evita saltar demasiado alto o encorvar los hombros.']::text[], 'intermedio', 'Trabajo cardiovascular con cuerda que activa pantorrillas, hombros y antebrazos y mejora la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4829'),
('c52ac320-b01f-5852-be7c-d1f2de2dc6c2', 'Salto con zancada', ARRAY['Parte en zancada con el torso erguido y los brazos a los lados.', 'Salta hacia arriba y cambia de pierna en el aire.', 'Aterriza suavemente en zancada con las rodillas alineadas.', 'Evita que la rodilla delantera pase la punta del pie al aterrizar.']::text[], 'intermedio', 'Pliometría unilateral que fortalece cuádriceps y glúteos y mejora la potencia y el equilibrio en el salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1166'),
('072dfdd0-f1d8-5770-91e7-ff2b75ba9336', 'Salto con zancada y manos en la cadera', ARRAY['Coloca las manos en la cadera y adopta posición de zancada.', 'Salta y cambia de pierna en el aire manteniendo el torso firme.', 'Aterriza con control y las rodillas alineadas con los pies.', 'Evita inclinarte hacia delante o perder el equilibrio al caer.']::text[], 'intermedio', 'Variante de zancada con salto que trabaja cuádriceps, glúteos y core manteniendo el equilibrio sin ayuda de brazos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4771'),
('71d7aaa7-e8f3-55d9-a980-03f1e3431d36', 'Salto, paso y salto', ARRAY['Da un paso al frente y realiza un salto vertical.', 'Aterriza suavemente y da otro paso antes del siguiente salto.', 'Mantén un ritmo constante y los brazos en movimiento.', 'Evita aterrizar con las piernas rígidas o el torso inclinado.']::text[], 'intermedio', 'Secuencia cardiovascular que combina saltos y pasos para elevar las pulsaciones y activar piernas y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4706'),
('0266a498-5a7c-599f-8380-ab9cf82cfa02', 'Subida con salto al cajón', ARRAY['Colócate frente al cajón con los pies a la anchura de las caderas.', 'Flexiona las rodillas y salta para subir al cajón.', 'Aterriza con el pie completo y las rodillas alineadas.', 'Baja con control y evita saltar con el torso inclinado hacia delante.']::text[], 'intermedio', 'Ejercicio explosivo que eleva las pulsaciones y fortalece cuádriceps, glúteos y pantorrillas al subir al cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3765'),
('b38bff0f-b1d5-57be-89a5-0ac89e8383ec', 'Salto con giro', ARRAY['Parte de pie con las rodillas ligeramente flexionadas.', 'Salta girando el cuerpo hacia un lado en el aire.', 'Aterriza suavemente con las rodillas flexionadas y alineadas.', 'Evita girar solo con la cadera o aterrizar con los pies rígidos.']::text[], 'intermedio', 'Salto con rotación que trabaja cuádriceps, glúteos y oblicuos y mejora la potencia y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5966'),
('73679397-27a3-5c63-8106-b7d198fea3c7', 'Salto lateral con impulso', ARRAY['Parte de pie con las rodillas ligeramente flexionadas.', 'Impúlsate hacia un lado con fuerza y salta lateralmente.', 'Aterriza con el pie completo y amortigua el impacto.', 'Evita que la rodilla se vaya hacia dentro al caer.']::text[], 'intermedio', 'Pliometría lateral que fortalece cuádriceps, glúteos y core y mejora la agilidad y el control del aterrizaje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10187'),
('58961814-69cb-5484-be16-6eade0c31678', 'Salto de tijera (jumping jack)', ARRAY['Parte de pie con los brazos a los lados y los pies juntos.', 'Salta abriendo piernas y subiendo los brazos por encima de la cabeza.', 'Vuelve a la posición inicial con un salto suave.', 'Mantén un ritmo constante y evita aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Cardio clásico que eleva las pulsaciones y activa pantorrillas, hombros y glúteos con un movimiento coordinado.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3094'),
('336b3623-0896-5557-83f1-c717b59d61ed', 'Jumping jack con rodillas altas', ARRAY['Parte de pie con los brazos a los lados.', 'Salta abriendo piernas y subiendo los brazos mientras elevas una rodilla.', 'Alterna las rodillas manteniendo un ritmo constante.', 'Evita inclinar el torso hacia atrás al subir la rodilla.']::text[], 'intermedio', 'Variante cardiovascular que combina jumping jack y rodillas altas para trabajar piernas, core y hombros.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '7555'),
('0bf3f227-4f95-5ffe-8aac-6a5154c6cc3a', 'Sentadilla pistol con salto', ARRAY['Colócate sobre una pierna con la otra extendida al frente.', 'Baja en sentadilla pistol controlando el equilibrio.', 'Impulsa con fuerza y salta hacia arriba.', 'Aterriza con la rodilla flexionada y alineada con el pie.']::text[], 'avanzado', 'Ejercicio explosivo unilateral que potencia cuádriceps y glúteos y mejora el equilibrio y la reactividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4169'),
('b37f140c-07a2-5176-ad82-244d492c2f84', 'Dominada con salto', ARRAY['Colócate bajo la barra con las manos a la anchura de los hombros y los brazos estirados.', 'Flexiona las rodillas y salta para impulsarte hasta que la barbilla supere la barra.', 'Controla el descenso durante dos o tres segundos hasta la posición inicial.', 'Evita balancear el cuerpo o encoger los hombros al subir.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con impulso de piernas, ideal para progresar hacia dominadas estrictas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1198'),
('02dfbbc0-28f6-5423-bfa9-daf686a88128', 'Zancada con salto a una pierna', ARRAY['Parte de pie con una pierna adelantada y el tronco erguido.', 'Desciende flexionando ambas rodillas hasta que la trasera casi toque el suelo.', 'Impúlsate con fuerza para saltar y cambiar de pierna en el aire.', 'Aterriza con la rodilla alineada con el pie y amortigua el impacto.', 'Evita que la rodilla delantera se vaya hacia dentro al caer.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia cuádriceps y glúteos, mejorando la explosividad y el equilibrio unilateral.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5148'),
('c510bf83-c75f-5556-8466-4354fb0629c4', 'Molino avanzado con kettlebell', ARRAY['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.', 'Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante.', 'Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda.', 'Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo.', 'Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.', 'Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente.', 'Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo.', 'Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja oblicuos, abdomen y hombros, mejorando la estabilidad del tronco y la movilidad de cadera bajo carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0517'),
('c3d78223-3780-53b3-b759-2ea310f96f18', 'Thruster alternado a un brazo con kettlebell', ARRAY['Sujeta la kettlebell a la altura del hombro con el codo flexionado.', 'Baja en sentadilla manteniendo el tronco erguido y el core activo.', 'Al subir, empuja la kettlebell por encima de la cabeza hasta estirar el brazo.', 'Baja la pesa al hombro y repite alternando los brazos.', 'Evita arquear la espalda al extender el brazo arriba.']::text[], 'intermedio', 'Combina sentadilla y press unilateral para trabajar piernas, hombros y core en un solo movimiento global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9692'),
('0cc8e4e9-4669-57ff-9fca-6b0be6388fa0', 'Cargada alternada desde colgado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos.', 'En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros.', 'Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos.', 'Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'avanzado', 'Desarrolla antebrazos, trapecios y hombros, mejorando la potencia y la coordinación en el tirón desde el suelo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0518'),
('9fec0016-8e60-598b-bff6-acc47fde62d5', 'Press alternado en el suelo con kettlebell', ARRAY['Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.', 'Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo.', 'Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba.', 'Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro.', 'Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece pectorales, hombros y tríceps desde el suelo, con menor tensión en el hombro y buen control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0519'),
('ddecb2a9-2dca-595f-a3f4-90a11a48af61', 'Remo renegado alternado con kettlebell', ARRAY['Comienza en posición de plancha alta con las manos sujetando las pesas rusas y los pies separados a la altura de las caderas.', 'Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo.', 'Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja espalda alta, core y hombros en posición de plancha, mejorando fuerza y estabilidad global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0521'),
('0e3c4802-f836-58a3-aa87-a92053bf5937', 'Remo alternado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Tira de una pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y apretando los omóplatos entre sí.', 'Baja la pesa rusa de nuevo a la posición inicial y repite con el otro brazo.', 'Continúa alternando los brazos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta, bíceps y antebrazos, mejorando la postura y la fuerza de tracción de forma unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0522'),
('0bac095e-5d40-5791-928c-a08e06230260', 'Press en ángulo con kettlebell', ARRAY['Siéntate o colócate con la kettlebell a la altura del hombro y el codo flexionado.', 'Empuja la pesa hacia arriba y ligeramente hacia delante en diagonal.', 'Extiende el brazo sin bloquear del todo y controla la bajada.', 'Mantén el core firme para no arquear la zona lumbar.', 'Evita girar el tronco al empujar la kettlebell.']::text[], 'intermedio', 'Trabaja deltoides y tríceps desde un ángulo que también activa el pecho superior y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2942'),
('f5dd4259-b8be-57fa-adf2-97a9dd0dca37', 'Press Arnold con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti.', 'Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos.', 'Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla deltoides, tríceps y espalda alta con rotación, ganando fuerza y movilidad en el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0523'),
('14643493-b587-5362-8d07-bc17b43cb402', 'Rotación de kettlebell alrededor de la cabeza', ARRAY['Sujeta la kettlebell con ambas manos cerca del pecho.', 'Dibuja un círculo alrededor de la cabeza pasándola cerca de las orejas.', 'Mantén los codos altos y el core activado durante todo el recorrido.', 'Cambia el sentido de giro en cada serie.', 'Evita encoger los hombros o mover el tronco para compensar.']::text[], 'principiante', 'Movilidad de hombros y muñecas que activa el core y la espalda alta con control circular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2939'),
('0d3f8539-2cb6-50a8-b5c4-ff72141c9604', 'Sentadilla búlgara asistida con kettlebell', ARRAY['Apoya el pie trasero en un banco y sujeta la kettlebell junto al pecho.', 'Desciende flexionando la rodilla delantera hasta que el muslo quede paralelo.', 'Empuja con el talón delantero para volver a subir.', 'Mantén el tronco erguido y la rodilla alineada con el pie.', 'Evita cargar el peso en la pierna trasera o perder el equilibrio.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4444'),
('6f0540c2-81cb-56c7-ac72-34dc7223980d', 'Sentadilla trasera con kettlebell', ARRAY['Sujeta la kettlebell con ambas manos detrás de la cabeza o a la espalda.', 'Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando caderas y rodillas manteniendo el pecho alto.', 'Empuja con los talones para subir exhalando al final del recorrido.', 'Evita que las rodillas se metan hacia dentro o que la espalda se curve.']::text[], 'intermedio', 'Ejercicio básico de fuerza para piernas y glúteos que también exige estabilidad del core y la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10674'),
('b6b7ec46-9371-51bb-a528-1d6ab76f1a5a', 'Balanceo con kettlebell y banda elástica', ARRAY['Coloca la banda alrededor de la cadera y ancla el otro extremo delante de ti.', 'Sujeta la kettlebell con ambas manos y adopta una ligera flexión de rodillas.', 'Lleva la cadera atrás y proyecta la pesa entre las piernas.', 'Extiende la cadera con fuerza para llevar la kettlebell a la altura del pecho.', 'Evita tirar con los brazos o redondear la espalda.']::text[], 'intermedio', 'Potencia glúteos e isquios con un swing guiado por banda que mejora la técnica y la activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4167'),
('67914be0-c31f-5440-b982-41b469764f27', 'Pullover con brazos flexionados y rodillas flexionadas con kettlebell', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Sujeta la kettlebell con ambas manos sobre el pecho y los codos flexionados.', 'Lleva la pesa hacia atrás por encima de la cabeza sin arquear la lumbar.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita separar la zona lumbar del suelo durante el recorrido.']::text[], 'intermedio', 'Estira y fortalece dorsales y pecho desde tumbado, con apoyo de rodillas para proteger la lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4538'),
('9fca0101-958c-5f69-a1f5-ced63510f1c2', 'Remo inclinado con giro alterno y kettlebell', ARRAY['Coloca los pies a la anchura de las caderas y lleva la kettlebell a una mano.', 'Inclina el tronco hacia delante manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la kettlebell hacia la cadera y gira el tronco hacia ese lado al final del recorrido.', 'Vuelve al centro con control y repite alternando los lados.', 'Evita redondear la espalda o girar solo con los brazos; el giro nace del tronco.']::text[], 'intermedio', 'Fortalece la espalda alta y los oblicuos, mejorando la estabilidad del core y la coordinación en cada tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5867'),
('1e70c7c4-b0d8-596e-8119-b546975fba6e', 'Remo inclinado con kettlebell', ARRAY['Sujeta la kettlebell con una mano y apoya la otra en el muslo o la rodilla.', 'Inclina el tronco con la espalda recta y el pecho hacia delante.', 'Tira de la kettlebell hacia la cadera llevando el codo pegado al cuerpo.', 'Baja con control sin dejar caer el peso de golpe.', 'Evita encoger el hombro o balancear el tronco para subir el peso.']::text[], 'intermedio', 'Trabaja los dorsales y la espalda alta, mejorando la fuerza de tracción y la postura en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6156'),
('ece67f4d-793c-5b1c-879b-c863bc06b31b', 'Press inclinado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.', 'Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado.', 'Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo.', 'Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza.', 'Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado.', 'Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante.', 'Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Desarrolla la fuerza del core y los oblicuos mientras estabilizas el hombro y el tríceps en un press unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0524'),
('a2a6c1df-b46a-5378-9170-5754217622d9', 'Curl de bíceps con kettlebell', ARRAY['De pie, sujeta la kettlebell por el asa con la palma hacia delante.', 'Mantén los codos pegados al torso y los hombros relajados.', 'Flexiona el codo subiendo la kettlebell sin mover el tronco.', 'Baja despacio controlando el peso hasta estirar el brazo.', 'Evita balancear el cuerpo o adelantar el codo para completar la repetición.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo, ganando fuerza de agarre y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5857'),
('b56ce9a3-8872-5aa2-ab40-8a18dfb72434', 'Press de banca a un brazo bottoms-up con kettlebell', ARRAY['Túmbate en el banco con la kettlebell en una mano y el asa hacia arriba.', 'Coloca el codo a unos 45 grados del torso y mantén la muñeca firme.', 'Empuja la kettlebell hacia arriba sin dejar que se incline.', 'Baja despacio hasta la altura del pecho manteniendo el control.', 'Evita bloquear la respiración o dejar que la campana se vuelque hacia un lado.']::text[], 'intermedio', 'Refuerza el pecho y el hombro con gran demanda de estabilidad y agarre, mejorando el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3739'),
('b6ecff8c-0339-5a17-895b-6f765888a448', 'Cargada bottoms-up desde colgado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido.', 'En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro.', 'Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba.', 'Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba.', 'Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'avanzado', 'Mejora la fuerza de bíceps y antebrazo con una carga inestable que exige control y precisión.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0525'),
('c949aff2-6af4-5d04-abc6-52c6a289a02e', 'Paseo con kettlebell bottoms-up sobre la cabeza a un brazo', ARRAY['Sube la kettlebell sobre la cabeza con el asa hacia arriba y el brazo estirado.', 'Mantén el hombro activo y la mirada al frente.', 'Camina con pasos cortos y controlados sin dejar que la campana se incline.', 'Respira de forma constante y evita arquear la zona lumbar.', 'Si pierdes el equilibrio, baja la kettlebell antes de continuar.']::text[], 'intermedio', 'Fortalece el hombro y el manguito rotador mientras el core estabiliza el cuerpo en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9697'),
('64f02ba4-e510-5871-b217-091c45220521', 'Levantamiento turco bottoms-up a la rodilla con kettlebell', ARRAY['Túmbate con la kettlebell en una mano y el asa hacia arriba, brazo estirado.', 'Flexiona la rodilla del mismo lado y apoya el pie en el suelo.', 'Empuja con el pie y el codo libre para incorporarte hasta la rodilla.', 'Mantén la kettlebell estable sobre la mano durante todo el movimiento.', 'Vuelve al suelo con control y evita perder la verticalidad de la campana.']::text[], 'intermedio', 'Activa el core y los glúteos con un patrón de suelo que mejora la estabilidad y la movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4230'),
('38c54f4b-4045-50b5-81a9-c63bc064ca33', 'Sentadilla al cajón con kettlebell', ARRAY['Sujeta la kettlebell al pecho y colócate delante de un cajón o banco.', 'Separa los pies a la anchura de los hombros y activa el core.', 'Baja sentándote hacia atrás hasta tocar el cajón con los glúteos.', 'Empuja con los talones para subir manteniendo el pecho alto.', 'Evita dejarte caer sobre el cajón o perder la curvatura lumbar.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps controlando la profundidad, ideal para mejorar la técnica de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4963'),
('504980d7-b236-5fab-b02d-03521d19bdd7', 'Burpee con kettlebell', ARRAY['Coloca la kettlebell en el suelo delante de ti y ponte de pie.', 'Baja a apoyar las manos y lleva los pies atrás a la posición de plancha.', 'Vuelve a traer los pies y coge la kettlebell para incorporarte.', 'Sube la kettlebell al pecho o sobre la cabeza y repite.', 'Evita hundir la cadera en la plancha o redondear la espalda al coger el peso.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja todo el cuerpo, mejorando la resistencia y la potencia.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3864'),
('a8d5be24-9cb8-5143-acc5-32d56951fc6e', 'Elevación de gemelos y sentadilla frontal con kettlebell', ARRAY['Sujeta la kettlebell a la altura de los hombros con los codos altos.', 'Sube los talones elevando los gemelos y baja despacio.', 'Desde ahí, baja en sentadilla manteniendo el pecho alto.', 'Sube empujando con los talones y repite la secuencia.', 'Evita inclinar el tronco hacia delante o levantar los talones en la sentadilla.']::text[], 'intermedio', 'Combina fuerza de cuádriceps y gemelos, mejorando el control del tobillo y la estabilidad en la sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5880'),
('44814d2e-bdfc-5f23-a8e1-0cf21ed5c59a', 'Cargada y envión con kettlebell', ARRAY['Coloca la kettlebell entre los pies y agárrala con una mano.', 'Haz una cargada llevándola al hombro con un tirón de cadera.', 'Flexiona ligeramente las rodillas y empuja la kettlebell sobre la cabeza.', 'Recibe el peso con el brazo estirado y el core firme.', 'Evita usar solo los brazos o perder el control en la recepción.']::text[], 'avanzado', 'Movimiento explosivo que trabaja hombros, piernas y core, mejorando la potencia y la coordinación.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4542'),
('db6fe18e-64f0-5ab5-b751-a0262b0d160a', 'Cargada y press con kettlebell', ARRAY['Coge la kettlebell del suelo con una mano y llévala al hombro con la cadera.', 'Mantén el codo pegado y el core activo en la posición de cargada.', 'Empuja la kettlebell sobre la cabeza estirando el brazo.', 'Baja al hombro con control y repite.', 'Evita arquear la espalda al press o golpear el antebrazo en la cargada.']::text[], 'intermedio', 'Trabaja hombros y tríceps junto con piernas y core, mejorando la fuerza global y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5855'),
('87d85b0f-b9e4-5ae7-a5e5-548574ae32b5', 'Curl concentrado con kettlebell', ARRAY['Siéntate y apoya el codo del brazo que trabaja en la cara interna del muslo.', 'Sujeta la kettlebell con la palma hacia arriba.', 'Flexiona el codo subiendo la kettlebell hacia el hombro.', 'Baja despacio hasta estirar el brazo por completo.', 'Evita mover el tronco o ayudar con el hombro para subir el peso.']::text[], 'intermedio', 'Aísla el bíceps con apoyo, maximizando la tensión y controlando el movimiento en cada repetición.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5856'),
('d579786f-5b11-5a60-a7ce-17d3b61f1358', 'Zancada hacia atrás contralateral con kettlebell', ARRAY['Sujeta la kettlebell en una mano y ponte de pie con los pies juntos.', 'Da un paso atrás con la pierna contraria a la mano que lleva el peso.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera se vaya hacia dentro o que el tronco se incline.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con un patrón unilateral que mejora el equilibrio y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7581'),
('4238be9f-5185-59d6-bdc3-25da9053de0f', 'Sentadilla cosaca con kettlebell', ARRAY['Coloca los pies muy abiertos con las puntas hacia fuera y sujeta la kettlebell con las dos manos delante del pecho.', 'Desplaza el peso hacia una pierna flexionando esa rodilla mientras la otra se estira con el pie apoyado.', 'Baja hasta donde controles sin redondear la espalda y mantén el pecho alto.', 'Empuja con el talón de la pierna flexionada para volver al centro y cambia de lado.', 'Evita que la rodilla flexionada se vaya hacia dentro y respira de forma constante.']::text[], 'intermedio', 'Trabaja aductores y glúteos mejorando la movilidad de cadera y la estabilidad unilateral de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6193'),
('ddaab0d3-856f-53b7-a901-4fbf621146ce', 'Bicho muerto con kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sujeta con las dos manos sobre el pecho y las rodillas flexionadas.', 'Pega la lumbar al suelo y extiende un brazo por encima de la cabeza mientras estiras la pierna contraria.', 'Vuelve al centro con control y repite con el lado opuesto sin arquear la espalda.', 'Exhala al extender y evita que la kettlebell se aleje del pecho.']::text[], 'intermedio', 'Refuerza el core y la zona abdominal baja enseñando a mantener la lumbar estable mientras se mueven brazos y piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4047'),
('1dafc09f-99d4-5b41-a5ce-a7ffa6eb2133', 'Cargada muerta con kettlebell', ARRAY['Coloca la kettlebell entre los pies y agárrala con una mano, con la espalda recta y el pecho alto.', 'Empuja el suelo con los talones y extiende la cadera para llevar la pesa hasta el hombro.', 'Recibe la kettlebell pegada al cuerpo con el codo abajo y la muñeca neutra.', 'Baja la pesa controlando el descenso entre las piernas y repite.', 'Evita tirar con la espalda: la fuerza sale de las piernas y la cadera.']::text[], 'avanzado', 'Potencia glúteos y cadena posterior con un gesto explosivo que también exige agarre y control del tronco.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1565'),
('1abee33e-54c9-5084-9928-27ad26c027b4', 'Peso muerto con kettlebell', ARRAY['Pisa con los pies a la anchura de las caderas y sujeta la kettlebell con las dos manos delante.', 'Lleva la cadera atrás con la espalda recta y las rodillas ligeramente flexionadas.', 'Baja la pesa hasta media espinilla sin redondear la zona lumbar.', 'Empuja el suelo con los talones y aprieta los glúteos al subir.', 'Evita hiperextender la espalda al final del movimiento.']::text[], 'intermedio', 'Fortalece glúteos e isquios con un patrón de bisagra de cadera básico para la espalda y el agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3322'),
('4b3f4de4-d960-5680-b3e6-503f45f0b971', 'Sentadilla deck con kettlebell', ARRAY['Sujeta la kettlebell con las dos manos delante del pecho y separa los pies a la anchura de los hombros.', 'Baja en sentadilla profunda manteniendo el pecho alto y los talones apoyados.', 'Desde abajo, inclina el tronco y rueda suavemente sobre la espalda para pasar por detrás.', 'Vuelve a subir apoyando los pies y empujando con las piernas hasta la posición inicial.', 'Evita rodar sobre el cuello y controla el ritmo en todo el recorrido.']::text[], 'intermedio', 'Combina fuerza de cuádriceps y control del core con un movimiento que exige equilibrio y movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3579'),
('7e687db3-7999-56a4-8de3-7151fad2c7a6', 'Flexión profunda con kettlebell', ARRAY['Coloca la kettlebell en el suelo y apoya las manos sobre el asa con el cuerpo en plancha.', 'Baja el pecho entre las manos manteniendo el core activo y los codos cerca del torso.', 'Empuja con fuerza para volver arriba sin perder la línea del cuerpo.', 'Evita que la cadera se hunda o suba demasiado durante el movimiento.']::text[], 'intermedio', 'Trabaja pectorales y tríceps con mayor rango de movimiento al apoyar las manos sobre la pesa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '3580'),
('4cf31c09-0bb9-5a6d-81c0-159e3de1f593', 'Cargada alternada doble desde colgado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Deja que las pesas rusas cuelguen rectas frente a tu cuerpo.', 'En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros.', 'Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados.', 'Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante.', 'Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'avanzado', 'Desarrolla bíceps, antebrazos y hombros con un gesto de halterofilia que exige coordinación y potencia.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0526'),
('d158638f-9a72-547d-bc8a-099e9c99feaa', 'Push press doble con kettlebell', ARRAY['Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro.', 'Flexiona ligeramente las rodillas y activa el core.', 'Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza.', 'Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos.', 'Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Fortalece deltoides y tríceps usando el impulso de piernas para mover las pesas por encima de la cabeza.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0528'),
('ec39dc69-9847-581f-8482-c4fe2acca711', 'Molino doble con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.', 'Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa.', 'Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha.', 'Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza.', 'Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo.', 'Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja oblicuos y core con estabilidad de hombro y flexibilidad de isquios en un movimiento técnico.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0530'),
('161ff552-a66b-5855-97af-ef9695071f33', 'Sentadilla sumo desde cajón con kettlebell y mancuerna', ARRAY['Sube a un cajón o step con los pies anchos y las puntas hacia fuera, sujetando la kettlebell y la mancuerna.', 'Baja la cadera hacia atrás y abajo manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Desciende hasta donde controles sin perder la curvatura lumbar.', 'Empuja con los talones y aprieta los glúteos al subir.', 'Evita que las rodillas se junten hacia dentro durante el descenso.']::text[], 'intermedio', 'Activa glúteos y aductores con una sentadilla amplia que mejora la fuerza y la movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2751'),
('c29ebef4-fca2-5080-ad79-6af6943a1189', 'Sentadilla goblet elevada con kettlebell', ARRAY['Coloca los talones sobre una superficie elevada y sujeta la kettlebell pegada al pecho.', 'Separa los pies a la anchura de los hombros y activa el core.', 'Baja en sentadilla manteniendo el torso erguido y las rodillas alineadas.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita inclinarte demasiado hacia delante o levantar los talones de la superficie.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con mayor rango al elevar los talones, mejorando la profundidad de la sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5496'),
('16d9dfda-4dfb-548f-8633-096927dcb162', 'Press a un brazo con rango extendido en el suelo', ARRAY['Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.', 'Sujeta una pesa rusa con una mano, con la palma hacia los pies.', 'Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta.', 'Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Trabaja pectoral y tríceps con un press unilateral que amplía el rango y exige control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0531'),
('6aab5ee7-8b94-5df2-8327-9e5d1dabe8a0', 'Paseo del granjero con kettlebell', ARRAY['Sujeta una kettlebell en cada mano y ponte erguido con los hombros atrás.', 'Camina con pasos cortos y controlados manteniendo el core activo.', 'Evita inclinarte hacia los lados y mantén la mirada al frente.', 'Respira con normalidad y suelta las pesas con control al terminar.']::text[], 'intermedio', 'Fortalece antebrazos, agarre y core mientras se camina cargado, mejorando la estabilidad global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3576'),
('ebb2c8fb-e3f6-56b2-b7ed-afcbf8def3e1', 'Caminata del granjero con kettlebell', ARRAY['Coge una kettlebell en cada mano y adopta una postura erguida con el pecho alto.', 'Da pasos firmes y regulares manteniendo los hombros bajos y el core apretado.', 'Evita encoger los hombros o balancear el cuerpo al caminar.', 'Controla la respiración y deja las pesas en el suelo con la espalda recta al acabar.']::text[], 'intermedio', 'Mejora el agarre, los trapecios y la resistencia del core caminando con carga en cada mano.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4528'),
('74462a08-0113-5683-9d98-25194dfe3002', 'Figura 8 con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas.', 'Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas.', 'Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho.', 'Mantén un ritmo constante y activa el core durante todo el ejercicio.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja abdominales y oblicuos con un movimiento dinámico que también implica hombros y antebrazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0532'),
('bcb72674-5de8-5789-a09d-1297aeb68c85', 'Apertura en el suelo con kettlebell', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la kettlebell sujeta con ambas manos sobre el pecho.', 'Baja la kettlebell hacia un lado con el codo ligeramente flexionado hasta notar estiramiento en el pecho.', 'Sube controlando el movimiento y aprieta el pecho arriba sin bloquear del todo el codo.', 'Inspira al bajar y espira al subir, manteniendo los omóplatos pegados al suelo.', 'Evita abrir demasiado el codo ni dejar caer la kettlebell de golpe.']::text[], 'intermedio', 'Trabaja el pectoral y la parte delantera del hombro, mejorando la fuerza y el control en el rango final del press.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5858'),
('a8c0b360-e6d0-5501-8dec-d01a0e6ec766', 'Zancada hacia delante con kettlebell', ARRAY['Sujeta la kettlebell en posición goblet contra el pecho y colócate de pie con los pies a la anchura de las caderas.', 'Da un paso largo hacia delante y baja la rodilla trasera hacia el suelo con el torso erguido.', 'Empuja con el pie delantero para volver a la posición inicial y alterna las piernas.', 'Mantén el core activo y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3574'),
('135791c4-a187-56e8-a71e-f481c2b37d81', 'Zancada con press con kettlebell', ARRAY['Sujeta la kettlebell a la altura del hombro con una mano y da un paso hacia delante bajando en zancada.', 'Al subir, empuja la kettlebell por encima de la cabeza hasta estirar el brazo.', 'Baja la kettlebell al hombro mientras vuelves a la posición inicial y cambia de pierna.', 'Mantén el abdomen firme para no arquear la espalda al presionar.', 'Evita encoger el hombro o bloquear la respiración durante el press.']::text[], 'intermedio', 'Combina fuerza de piernas y hombros en un patrón global que exige coordinación y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4533'),
('52f21d7d-2989-5da3-ae75-6329d69ea1d8', 'Zancada caminando con kettlebell en posición frontal', ARRAY['Coloca la kettlebell en posición frontal contra el pecho con los codos altos.', 'Da un paso largo hacia delante y baja la rodilla trasera cerca del suelo.', 'Empuja con la pierna delantera y avanza con la otra pierna sin perder la verticalidad.', 'Mantén el torso erguido y el core apretado durante todo el recorrido.', 'Evita inclinarte hacia delante o dejar caer los codos.']::text[], 'intermedio', 'Trabaja piernas y core con carga frontal, mejorando la postura y la resistencia en desplazamiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4441'),
('eef054c4-cb59-52a9-a47d-a9174f3e3096', 'Elevación frontal con kettlebell', ARRAY['De pie, sujeta la kettlebell con ambas manos delante de los muslos.', 'Eleva la kettlebell hacia delante hasta la altura de los hombros con los codos casi rectos.', 'Baja despacio controlando el descenso sin balancear el cuerpo.', 'Espira al subir e inspira al bajar, manteniendo el core activo.', 'Evita usar impulso de cadera o encoger los hombros.']::text[], 'intermedio', 'Aísla la parte delantera del hombro para ganar fuerza y control en movimientos de empuje por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5859'),
('5f9e4f6f-ca65-5265-9706-c692f5fca017', 'Sentadilla frontal con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo.', 'Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps con carga frontal, mejorando la postura y la profundidad de la sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0533'),
('42009de6-3837-5499-b452-0ad305f79694', 'Sentadilla completa desde déficit con kettlebell', ARRAY['Colócate de pie sobre una superficie elevada y estable con la kettlebell en posición goblet.', 'Baja en sentadilla profunda dejando que la cadera descienda por debajo de las rodillas.', 'Mantén los talones apoyados y el pecho erguido durante todo el descenso.', 'Empuja con los pies para subir controlando el movimiento y sin perder la tensión del core.', 'Evita que las rodillas se junten hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Mejora la profundidad y la fuerza de cuádriceps y glúteos trabajando un rango mayor de movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5301'),
('3fab87aa-60c2-529e-a819-ab2723e6d515', 'Acarreo goblet con kettlebell', ARRAY['Sujeta la kettlebell en posición goblet contra el pecho con los codos apretados.', 'Camina con pasos cortos y firmes manteniendo el torso erguido.', 'Aprieta el abdomen y los glúteos para no balancearte de un lado a otro.', 'Respira de forma constante y evita encoger los hombros.']::text[], 'intermedio', 'Refuerza el core, la espalda alta y el agarre mientras caminas con carga, mejorando la estabilidad global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2916'),
('61076be0-9841-5ec7-a68f-205a42933213', 'Zancada cruzada goblet con kettlebell', ARRAY['Sujeta la kettlebell en posición goblet y colócate de pie con los pies juntos.', 'Cruza una pierna por detrás y por fuera de la otra, bajando en zancada.', 'Mantén el torso erguido y la rodilla delantera alineada con el pie.', 'Empuja para volver a la posición inicial y alterna las piernas.', 'Evita girar la cadera o perder el equilibrio por falta de control.']::text[], 'intermedio', 'Trabaja glúteo y aductores con un patrón cruzado que mejora la estabilidad y la fuerza de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3732'),
('5201ef0e-1248-56d1-8899-7f1cc1deaac2', 'Salto de sentadilla goblet con kettlebell', ARRAY['Sujeta la kettlebell en posición goblet y baja en sentadilla con el pecho erguido.', 'Empuja con fuerza y salta extendiendo las piernas, manteniendo la kettlebell pegada al pecho.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto.', 'Evita aterrizar con las piernas rígidas o dejar que las rodillas se junten hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia de piernas y capacidad explosiva, mejorando la fuerza rápida de cuádriceps y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '3187'),
('af4951cc-7a53-5fc3-a553-dd4314eb98c5', 'Buenos días con kettlebell', ARRAY['De pie con la kettlebell sujeta contra el pecho o en la espalda alta, según tu comodidad.', 'Con las rodillas ligeramente flexionadas, lleva la cadera hacia atrás bajando el torso.', 'Mantén la espalda recta y siente el estiramiento en los isquiotibiales.', 'Vuelve a la posición inicial apretando glúteos y sin arquear la espalda.', 'Evita redondear la zona lumbar o bajar más de lo que controlas.']::text[], 'intermedio', 'Fortalece isquiotibiales, glúteos y espalda baja, mejorando el patrón de bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4817'),
('108b56f2-a804-563c-b80a-6a7c4f751cfc', 'Remo gorila con kettlebell', ARRAY['Coloca la kettlebell en el suelo entre los pies y adopta una posición de bisagra con la espalda recta.', 'Agarra la kettlebell con ambas manos y tira de ella hacia el abdomen apretando los omóplatos.', 'Baja la kettlebell controlando el movimiento hasta el suelo sin perder la postura.', 'Mantén el core firme y evita redondear la espalda al recoger la carga.']::text[], 'intermedio', 'Trabaja la espalda y el agarre con un remo bilateral que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7230'),
('37bd18d1-9f79-55b5-b077-c08d2fc18ab5', 'Halo en media rodilla con kettlebell', ARRAY['Arrodíllate sobre una rodilla con la kettlebell sujeta por el asa con ambas manos.', 'Lleva la kettlebell en un círculo alrededor de la cabeza, cerca del cráneo.', 'Mantén el torso erguido y el core apretado para no mover la cadera.', 'Haz el recorrido en ambos sentidos de forma lenta y controlada.', 'Evita encoger los hombros o mover la cabeza para seguir la kettlebell.']::text[], 'principiante', 'Mejora la movilidad del hombro y la estabilidad del core con un círculo controlado alrededor de la cabeza.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8331'),
('2395b4f4-ee01-5445-9109-0d317ef781e3', 'Press bottoms-up a un brazo de media rodilla con kettlebell', ARRAY['Arrodíllate sobre una rodilla y sujeta la kettlebell invertida con el asa hacia abajo a la altura del hombro.', 'Presiona la kettlebell hacia arriba manteniendo la base del asa apuntando al techo.', 'Baja despacio controlando el equilibrio y sin perder la verticalidad.', 'Mantén el core apretado y evita inclinarte hacia un lado.', 'Si la kettlebell se tambalea, reduce la carga o el rango.']::text[], 'intermedio', 'Refuerza el hombro, el agarre y la estabilidad del core con la kettlebell invertida en un press unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4446'),
('8a896739-8a5a-585d-aacb-a6995e46e249', 'Zancada lateral a media rodilla con kettlebell', ARRAY['Arrodíllate sobre una rodilla con la kettlebell sujeta contra el pecho.', 'Extiende una pierna hacia el lado y baja la cadera hacia ese lado buscando estiramiento en el aductor.', 'Vuelve al centro controlando el movimiento y alterna los lados.', 'Mantén el torso erguido y evita forzar más allá de lo que controlas.']::text[], 'principiante', 'Mejora la movilidad de aductores y cadera con un desplazamiento lateral controlado desde media rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11286'),
('82809215-1b69-5001-aa63-53babca37dd6', 'Media levantada turca con kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sujeta con una mano y el brazo extendido hacia el techo.', 'Flexiona la rodilla del mismo lado y apoya el pie, manteniendo la muñeca firme y el codo bloqueado.', 'Empuja con el pie y el codo libre para incorporarte hasta quedar apoyado sobre una rodilla.', 'Mantén la mirada al frente y evita arquear la zona lumbar en ningún momento.', 'Respira de forma constante y controla el descenso hasta volver a la posición inicial.']::text[], 'intermedio', 'Trabaja el core, los hombros y los glúteos, mejorando la estabilidad y la coordinación en posición tumbada y de rodillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3323'),
('12fd9dfb-5977-5ea8-9d0c-b0b3ea5f263a', 'Cargada desde colgado con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas.', 'Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.', 'Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo.', 'Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado.']::text[], 'avanzado', 'Potencia la cadena posterior y la extensión de cadera, desarrollando fuerza explosiva en isquios, glúteos y cuádriceps.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0535'),
('14e0f11b-ed62-5e0f-aa97-d24450cada92', 'Apertura inclinada con kettlebell', ARRAY['Colócate inclinado hacia delante con la espalda recta y las kettlebells a la altura del pecho.', 'Abre los brazos en arco con los codos ligeramente flexionados, sin subir los hombros.', 'Baja despacio hasta notar el estiramiento en el pecho y evita bajar más de lo que controlas.', 'Junta las kettlebells al subir apretando el pecho y espira en la fase de esfuerzo.', 'Mantén el core activo para no arquear la espalda durante todo el recorrido.']::text[], 'intermedio', 'Aísla el pectoral y la porción superior del pecho, mejorando la apertura y el control del hombro en un ángulo inclinado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6820'),
('b453eced-dd90-52f0-a940-fc05a9d4d06c', 'Zancada hacia atrás ipsilateral con kettlebell', ARRAY['Sujeta la kettlebell en la mano del mismo lado de la pierna que va a retroceder.', 'Da un paso atrás y baja la rodilla hacia el suelo manteniendo el tronco erguido.', 'Apoya el peso en la pierna delantera y empuja para volver a la posición inicial.', 'Evita que la rodilla delantera se vaya hacia dentro y mantén el pie bien apoyado.', 'Respira al bajar y controla el retorno sin dar un tirón.']::text[], 'intermedio', 'Fortalece el glúteo y el cuádriceps de forma unilateral, mejorando el equilibrio y la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7582'),
('38f7667b-8ed2-5c0a-b11a-83890de28e8c', 'Zancada hacia atrás ipsilateral con rodilla alta y kettlebell', ARRAY['Sujeta la kettlebell en la mano del mismo lado de la pierna que retrocede.', 'Da un paso atrás y baja hasta que la rodilla trasera casi toque el suelo.', 'Empuja con la pierna delantera para volver y eleva la rodilla de la pierna trasera al frente.', 'Mantén el tronco firme y evita balancearte al subir la rodilla.', 'Controla el tempo y respira de forma constante en cada repetición.']::text[], 'intermedio', 'Combina fuerza de glúteo y cuádriceps con control del core, añadiendo una elevación de rodilla que exige equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10562'),
('d0f65506-1548-5d6d-afd9-39d678035ac4', 'Peso muerto a una pierna con apoyo trasero y kettlebell', ARRAY['Coloca una pierna ligeramente atrás con la punta del pie apoyada como soporte.', 'Sujeta la kettlebell con la mano contraria a la pierna de apoyo y mantén la espalda recta.', 'Inclínate hacia delante llevando la cadera atrás mientras la kettlebell baja por la pierna.', 'Empuja con el glúteo para volver arriba sin arquear la zona lumbar.', 'Evita redondear la espalda y mantén la mirada al frente durante todo el movimiento.']::text[], 'intermedio', 'Trabaja el glúteo y los isquios de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3734'),
('4dd56109-c750-56ea-9266-1bd6c1791d0b', 'Press bottoms-up a un brazo de rodillas con kettlebell', ARRAY['Arrodíllate con la espalda recta y sujeta la kettlebell con la base hacia arriba.', 'Lleva la kettlebell a la altura del hombro con el codo pegado al cuerpo.', 'Empuja hacia arriba manteniendo la muñeca firme y la base apuntando al techo.', 'Baja despacio controlando el equilibrio y evita inclinar el tronco hacia atrás.', 'Respira al subir y mantén el core activo durante todo el press.']::text[], 'intermedio', 'Refuerza el deltoides y el manguito rotador, mejorando la estabilidad del hombro y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2927'),
('8ba4d483-6bd9-530b-baef-4b9411ea6628', 'Press de hombros a un brazo de rodillas con kettlebell', ARRAY['Arrodíllate con la espalda recta y la kettlebell a la altura del hombro.', 'Empuja la kettlebell hacia arriba hasta extender el brazo sin bloquear de golpe.', 'Baja despacio hasta la altura del hombro manteniendo el codo cerca del cuerpo.', 'Evita arquear la espalda o inclinarte hacia atrás al empujar.', 'Respira al subir y mantén el core firme durante todo el recorrido.']::text[], 'intermedio', 'Desarrolla la fuerza del deltoides y el tríceps, con el core estabilizando el tronco en posición de rodillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2932'),
('0946301b-380f-5e16-9880-6956cb0fe16e', 'Zancada lateral con kettlebell', ARRAY['De pie con la kettlebell sujeta al pecho y los pies separados a la anchura de las caderas.', 'Da un paso amplio hacia un lado y flexiona la rodilla de esa pierna llevando la cadera atrás.', 'Mantén la otra pierna estirada y el pie bien apoyado en el suelo.', 'Empuja con la pierna flexionada para volver al centro sin perder el equilibrio.', 'Evita que la rodilla se vaya hacia dentro y respira al bajar.']::text[], 'intermedio', 'Fortalece el cuádriceps y los aductores, mejorando la movilidad lateral y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4045'),
('8e83543f-199e-535a-9aea-564e4f5df98a', 'Zancada, cargada y press con kettlebell', ARRAY['Sujeta la kettlebell en posición de colgado frente al cuerpo.', 'Da un paso adelante y baja en zancada manteniendo el tronco erguido.', 'Al volver, carga la kettlebell al hombro y empuja hacia arriba hasta extender el brazo.', 'Baja la kettlebell y repite la secuencia controlando cada fase.', 'Evita arquear la espalda al press y respira de forma constante.']::text[], 'intermedio', 'Combina fuerza de piernas y hombros en un movimiento completo que exige coordinación y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3577'),
('16cca78c-9216-524a-b1ca-c9424efc6c18', 'Zancada con paso por debajo y kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.', 'Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.', 'Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda.', 'Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo.', 'Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo.', 'Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con un gesto dinámico que mejora la coordinación y la estabilidad unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0536'),
('8abe5e60-193b-5e33-8d86-648d0ea7b720', 'Zancada con giro y kettlebell', ARRAY['De pie con la kettlebell sujeta al pecho y los pies a la anchura de las caderas.', 'Da un paso adelante y baja en zancada manteniendo el tronco erguido.', 'Gira el tronco hacia el lado de la pierna delantera sin mover la cadera.', 'Vuelve al centro y empuja para regresar a la posición inicial.', 'Evita girar con la espalda redondeada y respira al rotar.']::text[], 'intermedio', 'Refuerza el core y los oblicuos junto con glúteos y cuádriceps, mejorando la rotación controlada del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5069'),
('a2fdeb99-43cc-57b9-b59e-9c6dbf624101', 'Press de pecho bottoms-up a un brazo acostado en el suelo con kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sujeta con la base hacia arriba y el codo flexionado.', 'Empuja la kettlebell hacia el techo hasta extender el brazo manteniendo la muñeca firme.', 'Baja despacio hasta que el codo toque el suelo sin perder el equilibrio de la base.', 'Evita arquear la zona lumbar y mantén el core activo.', 'Respira al empujar y controla el descenso en cada repetición.']::text[], 'intermedio', 'Trabaja el pectoral y el tríceps con inestabilidad, mejorando el control del hombro y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4846'),
('1f09ff2c-f591-5746-9b7a-8ee39b72a26e', 'Press francés acostado con kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sujeta con ambas manos sobre el pecho.', 'Flexiona los codos llevando la kettlebell hacia la frente sin mover los brazos.', 'Extiende los codos para volver a la posición inicial apretando el tríceps.', 'Evita abrir los codos hacia los lados y mantén los hombros estables.', 'Respira al extender y controla el descenso sin dejar caer la kettlebell.']::text[], 'intermedio', 'Aísla el tríceps y mejora la extensión del codo, con los hombros y antebrazos estabilizando el movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5861'),
('a8222961-ab38-51c7-b09b-2f0c6a068d02', 'Press de banca a un brazo con kettlebell', ARRAY['Túmbate en el banco con la kettlebell sujeta a la altura del pecho y el codo flexionado.', 'Empuja la kettlebell hacia arriba hasta extender el brazo sin bloquear de golpe.', 'Baja despacio hasta la altura del pecho manteniendo el codo cerca del cuerpo.', 'Evita arquear la zona lumbar y mantén los pies bien apoyados en el suelo.', 'Respira al empujar y controla el descenso en cada repetición.']::text[], 'intermedio', 'Desarrolla la fuerza del pectoral y el tríceps de forma unilateral, con el core estabilizando el tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3738'),
('2281a647-0a2d-54c0-9fd8-6097857692ad', 'Cargada a un brazo con kettlebell', ARRAY['Coloca la kettlebell entre los pies y agarra el asa con una mano, espalda recta y pecho arriba.', 'Empuja el suelo con los talones y extiende la cadera para llevar la pesa hacia el hombro.', 'Gira la muñeca para que la pesa quede apoyada en el antebrazo y el codo pegado al cuerpo.', 'Evita tirar con el brazo: la fuerza sale de las piernas y la cadera.', 'Respira al extender la cadera y controla la bajada hasta el suelo.']::text[], 'avanzado', 'Movimiento explosivo de cadera y glúteo que sube la pesa al hombro y mejora la potencia y la coordinación.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4543'),
('98d2ce2d-d5f6-5d05-81a0-6c4218e357bd', 'Envión a un brazo con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.', 'Flexiona ligeramente las rodillas y activa el core.', 'Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo.', 'Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso.', 'Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas.', 'Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza.', 'Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza.', 'Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado.']::text[], 'avanzado', 'Potencia hombros, tríceps y core con un movimiento explosivo, mejorando la coordinación y la transferencia de fuerza.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0538'),
('b3343212-04be-5f4a-a611-fbab702528d2', 'Press militar lateral a un brazo con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.', 'Activa el core y mantén la espalda recta.', 'Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo.', 'Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece deltoides, tríceps y core de forma unilateral, mejorando la estabilidad del hombro y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0539'),
('1a6e7ef5-ff79-55aa-9407-153b4598ec47', 'Sentadilla sobre la cabeza a un brazo con kettlebell', ARRAY['Sujeta la kettlebell sobre la cabeza con el brazo extendido y los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás y abajo manteniendo el pecho alto y el brazo vertical.', 'Empuja con los talones para subir y aprieta el glúteo arriba sin perder la posición del brazo.', 'Mantén el core firme y evita que la pesa se vaya hacia delante.', 'Respira al bajar y sube controlando el movimiento.']::text[], 'intermedio', 'Sentadilla profunda con la pesa fija sobre la cabeza que exige movilidad de hombro y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1566'),
('9d5cad09-4ee4-560e-8cba-c9f836cea599', 'Remo a un brazo con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Tira de la pesa rusa hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.', 'Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.']::text[], 'intermedio', 'Trabaja espalda alta, bíceps y antebrazos de forma unilateral, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0541'),
('976825a0-2816-5090-91b4-02aa50642ea6', 'Swing a un brazo con kettlebell', ARRAY['Con la kettlebell delante, pies a la anchura de los hombros y rodillas ligeramente flexionadas.', 'Lleva la cadera atrás y deja que la pesa pase entre las piernas con la espalda recta.', 'Extiende la cadera con fuerza para que la pesa suba hasta la altura del pecho.', 'No eleves con los brazos ni redondees la espalda: el impulso viene de la cadera.', 'Respira al subir y controla el descenso entre las piernas.']::text[], 'intermedio', 'Balanceo explosivo de cadera que activa glúteos e isquios y entrena potencia y resistencia del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1568'),
('b5b074ed-8def-5b59-8b47-5f27de19f0ee', 'Thruster a un brazo con kettlebell', ARRAY['Sujeta la kettlebell a la altura del hombro con el codo pegado al cuerpo.', 'Baja en sentadilla manteniendo el pecho alto y el peso en los talones.', 'Al subir, empuja la pesa sobre la cabeza aprovechando el impulso de las piernas.', 'Baja la pesa al hombro y encadena la siguiente repetición sin perder el core firme.', 'Evita arquear la espalda al press y respira al empujar hacia arriba.']::text[], 'intermedio', 'Combina sentadilla y press para trabajar piernas, hombros y core en un gesto global de cuerpo entero.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4541'),
('7305105b-40c4-5d8b-b06d-1ab78a1a72bb', 'Peso muerto a una pierna con kettlebell', ARRAY['Sujeta la kettlebell con una mano y apoya el peso en la pierna contraria con la rodilla algo flexionada.', 'Inclina el tronco hacia delante mientras la pierna libre se eleva hacia atrás, espalda recta.', 'Baja hasta notar el estiramiento del isquio y vuelve subiendo con la cadera.', 'Evita redondear la espalda o girar la cadera: mantén la pelvis cuadrada.', 'Respira al bajar y aprieta el glúteo al subir.']::text[], 'intermedio', 'Trabaja isquios y glúteos con apoyo a una pierna y mejora el equilibrio y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1569'),
('47bd7b97-9cc5-5d39-a092-660ecf63cc44', 'Cargada con palma abierta y kettlebell', ARRAY['Agarra la kettlebell con la palma abierta y los pies a la anchura de los hombros.', 'Lleva la cadera atrás y extiéndela con fuerza para elevar la pesa cerca del cuerpo.', 'Gira la mano para recibir la pesa en el hombro con el codo bajo y pegado.', 'Evita tirar solo con el brazo: el impulso nace de piernas y cadera.', 'Respira al extender la cadera y controla la bajada.']::text[], 'avanzado', 'Cargada explosiva que sube la pesa al hombro y desarrolla potencia de cadera, espalda y agarre.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '1567'),
('b0a91746-c4d9-5ae0-b1e3-714b35919988', 'Balanceo con agarre por encima con kettlebell', ARRAY['Sujeta la kettlebell con el agarre por encima y los pies a la anchura de los hombros.', 'Lleva la cadera atrás y deja que la pesa pase entre las piernas con la espalda recta.', 'Extiende la cadera con fuerza para que la pesa suba hasta la altura del pecho.', 'No eleves con los brazos ni redondees la espalda: el impulso viene de la cadera.', 'Respira al subir y controla el descenso entre las piernas.']::text[], 'intermedio', 'Swing con agarre prono que refuerza glúteos, isquios y espalda baja, además de la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3680'),
('54ce83d7-3321-585a-81bc-22ccfafa9fe7', 'Caminata con kettlebell sobre la cabeza', ARRAY['Sube la kettlebell sobre la cabeza con el brazo extendido y el codo cerca de la oreja.', 'Camina con pasos cortos manteniendo el core firme y la mirada al frente.', 'Evita arquear la espalda o inclinarte hacia el lado contrario: mantén el tronco recto.', 'Respira de forma constante y controla el ritmo del paseo.', 'Baja la pesa con control al terminar el recorrido.']::text[], 'intermedio', 'Paseo con la pesa sobre la cabeza que fortalece hombros, core y oblicuos y mejora la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4244'),
('a817a3da-e073-55d3-80d0-1f50019d7769', 'Extensión de tríceps sobre la cabeza con kettlebell', ARRAY['Sujeta la kettlebell con ambas manos sobre la cabeza y los codos apuntando al frente.', 'Baja la pesa detrás de la cabeza flexionando solo los codos.', 'Extiende los codos para subir la pesa sin mover los brazos del sitio.', 'Evita abrir los codos o arquear la espalda: mantén el core firme.', 'Respira al subir y controla la bajada.']::text[], 'intermedio', 'Aísla el tríceps con la pesa sobre la cabeza y mejora la fuerza y el control del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5860'),
('1a2bfe9b-3939-59cf-ac26-77b59b3c5160', 'Pirata de piernas con kettlebell sentado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo.', 'Extiende el brazo por completo por encima de la cabeza, enderezando el codo.', 'Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Trabaja los hombros y fortalece brazos y antebrazos manteniendo el core activo en posición sentada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0543'),
('1b44d518-7215-5238-8f45-51bd820d6e7c', 'Sentadilla pistol con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.', 'Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo.', 'Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida.', 'Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'avanzado', 'Ejercicio unilateral que potencia glúteos y cuádriceps, mejorando el equilibrio y la estabilidad de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0544'),
('051607ea-c999-5529-8c48-9028817fe52a', 'Paso de kettlebell por debajo en plancha', ARRAY['Colócate en plancha alta con la kettlebell a un lado y los pies algo abiertos.', 'Con una mano, pasa la pesa por debajo del cuerpo hacia el otro lado sin mover la cadera.', 'Recógela con la otra mano y repite el movimiento alternando lados.', 'Evita que la cadera suba o gire: mantén el cuerpo en línea recta.', 'Respira de forma constante y controla el ritmo.']::text[], 'intermedio', 'Plancha con paso de la pesa que activa el abdomen y los oblicuos y mejora la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7229'),
('c0483e61-2a97-5622-a773-9d66b46cda4a', 'Flexión pliométrica con kettlebell', ARRAY['Comienza en una posición de plancha alta con las manos sobre las pesas rusas, separadas a la altura de los hombros.', 'Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.', 'Empuja con las manos de forma explosiva, levantándolas de las pesas rusas y extendiendo los brazos por completo.', 'Aterriza suavemente sobre las pesas rusas y baja el pecho de inmediato para la siguiente repetición.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pecho con potencia explosiva y mejora la capacidad de salto y la estabilidad del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '0545'),
('f3238a78-dbde-53d4-b683-292aed086023', 'Flexión con kettlebell', ARRAY['Coloca la kettlebell en el suelo y apoya las manos en el asa con los pies atrás en plancha.', 'Baja el pecho de forma controlada manteniendo el cuerpo alineado y el core apretado.', 'Empuja con fuerza para subir sin que la cadera se hunda ni se eleve.', 'Exhala al empujar e inhala al bajar, evitando perder la posición de la muñeca.']::text[], 'intermedio', 'Fortalece pecho, tríceps y hombros mientras el core estabiliza el cuerpo sobre la pesa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '4521'),
('11456cd7-47df-522d-812f-ebd63cc5ca04', 'Pullover con kettlebell tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta la kettlebell con ambas manos sobre el pecho.', 'Lleva la pesa hacia atrás por encima de la cabeza con los codos ligeramente flexionados.', 'Baja hasta notar estiramiento en dorsales sin arquear la zona lumbar.', 'Vuelve al pecho controlando el movimiento y evitando rebotes.']::text[], 'intermedio', 'Estira y fortalece los dorsales y el pecho, mejorando la movilidad del hombro y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3735'),
('bc8ecaeb-e36a-5113-a76b-18097cac37f6', 'Dead bug con pullover de kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sobre el pecho y las rodillas en el aire a 90 grados.', 'Estira una pierna y el brazo con la pesa hacia atrás sin despegar la lumbar del suelo.', 'Vuelve al centro y alterna el lado contrario manteniendo el abdomen apretado.', 'Respira de forma pausada y evita que la espalda se arquee en ningún momento.']::text[], 'intermedio', 'Refuerza el abdomen profundo y la coordinación entre core y dorsales manteniendo la lumbar estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9518'),
('2d84b608-7311-5c82-828a-112d35246d0f', 'Remo para deltoide posterior con kettlebell', ARRAY['Inclina el tronco hacia delante con la espalda recta y la kettlebell colgando en una mano.', 'Tira del codo hacia atrás y arriba llevando la pesa hacia la cadera.', 'Aprieta el omóplato al final del recorrido y baja controlando el descenso.', 'Evita rotar el tronco o encoger el hombro durante el movimiento.']::text[], 'intermedio', 'Activa la parte trasera del hombro y la espalda alta para mejorar la postura y el equilibrio muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4536'),
('6146d43c-9d5c-54c4-9aa1-8fbab96e6a2e', 'Sentadilla completa desde déficit con banda elástica', ARRAY['Colócate de pie sobre una superficie elevada con la banda en los muslos y la kettlebell al pecho.', 'Baja despacio buscando profundidad máxima sin perder la curvatura lumbar.', 'Empuja con los talones para subir manteniendo las rodillas alineadas con los pies.', 'Evita que las rodillas se metan hacia dentro y controla la bajada.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos en rango completo, mejorando fuerza y movilidad de tobillo y cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2753'),
('52b630cf-6483-5774-8d2e-7e762b58bbab', 'Peso muerto rumano con kettlebell', ARRAY['De pie con la kettlebell frente a los muslos y las rodillas ligeramente flexionadas.', 'Lleva la cadera atrás bajando la pesa pegada a las piernas con la espalda recta.', 'Baja hasta notar estiramiento en isquiotibiales sin redondear la lumbar.', 'Sube empujando la cadera adelante y apretando glúteos al final.']::text[], 'intermedio', 'Fortalece isquiotibiales y glúteos con un patrón de bisagra que mejora la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4861'),
('e76b500b-28da-5448-bfd8-6da33ef97dae', 'Peso muerto rumano a sentadilla con kettlebell', ARRAY['De pie con la kettlebell al pecho y los pies a la anchura de los hombros.', 'Haz una bisagra de cadera bajando la pesa con la espalda recta.', 'Al subir enlaza con una sentadilla bajando la cadera entre los talones.', 'Mantén el core apretado y evita curvar la espalda en la transición.']::text[], 'intermedio', 'Combina bisagra y sentadilla para trabajar glúteos, isquiotibiales y cuádriceps en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9485'),
('1118aa68-0308-57da-8a28-1bb22e54e59a', 'Peso muerto rotacional con kettlebell', ARRAY['Coloca la kettlebell en el suelo a un lado y adopta una postura de bisagra de cadera.', 'Coge la pesa y levántala rotando el tronco hacia el lado contrario.', 'Controla la rotación desde el core sin forzar la lumbar.', 'Baja la pesa con el mismo control y alterna los lados.']::text[], 'intermedio', 'Trabaja glúteos y oblicuos añadiendo rotación controlada para mejorar la fuerza funcional del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5886'),
('09dc95f0-45ac-55c6-918b-73665b5ff94a', 'Giro ruso con kettlebell', ARRAY['Siéntate con las rodillas flexionadas y el tronco ligeramente inclinado atrás sujetando la kettlebell.', 'Gira el tronco llevando la pesa hacia un lado y luego al otro.', 'Mantén el pecho alto y el abdomen apretado durante todo el recorrido.', 'Evita tirar solo con los brazos: la rotación nace del core.']::text[], 'intermedio', 'Fortalece oblicuos y abdomen con un movimiento rotacional que mejora la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4393'),
('d0640369-ba72-5e2f-95df-a32f567af6ca', 'Elevación lateral sentado con kettlebell', ARRAY['Siéntate con la espalda recta y la kettlebell en una mano junto a la cadera.', 'Eleva el brazo lateralmente hasta la altura del hombro con el codo ligeramente flexionado.', 'Baja despacio controlando el descenso sin dejar caer la pesa.', 'Evita encoger el hombro o usar impulso del tronco.']::text[], 'intermedio', 'Aísla el deltoide medio para ganar amplitud y estabilidad en el hombro sin cargar la lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6833'),
('7ed064cf-728e-54e4-8e55-ca5384c8d987', 'Press militar a un brazo sentado con kettlebell', ARRAY['Siéntate con la espalda recta y la kettlebell en posición de rack a la altura del hombro.', 'Empuja la pesa hacia arriba hasta estirar el brazo sin bloquear de golpe.', 'Baja controlando hasta el hombro manteniendo el core apretado.', 'Evita arquear la espalda o inclinarte hacia el lado contrario.']::text[], 'intermedio', 'Desarrolla fuerza de hombro y tríceps con trabajo unilateral que exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3737'),
('2f0dca4e-5f21-5791-ab15-358cbd7cad0a', 'Press militar a dos brazos sentado con kettlebell', ARRAY['Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.', 'Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.', 'Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo.', 'Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece hombros y tríceps con un press vertical estable que también activa la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1438'),
('9f2de160-534a-5ccd-a3f9-26e0a33ac14c', 'Press balancín con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.', 'Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro.', 'Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza.', 'Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja hombros y tríceps alternando brazos, mejorando la coordinación y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0547'),
('08ed9cd2-aa10-553c-86b6-1a0388602be5', 'Encogimientos con kettlebell', ARRAY['De pie con la kettlebell en cada mano a los lados y los brazos estirados.', 'Eleva los hombros hacia las orejas sin flexionar los codos.', 'Aprieta arriba un instante y baja controlando el movimiento.', 'Evita rotar los hombros o usar impulso de piernas.']::text[], 'intermedio', 'Fortalece trapecios y espalda alta, mejorando la postura y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6194'),
('8f3f30eb-7968-5415-98fd-99bea86f4b06', 'Flexión lateral con kettlebell', ARRAY['De pie con los pies a la anchura de los hombros, sujeta la kettlebell con una mano a un lado del cuerpo.', 'Inclina el tronco hacia el lado de la pesa flexionando solo la cintura, sin rotar.', 'Vuelve despacio al centro apretando los oblicuos y repite.', 'Evita balancear el brazo o usar inercia; el movimiento debe ser lento y controlado.']::text[], 'intermedio', 'Trabaja los oblicuos y el core para ganar estabilidad y control del tronco en el plano lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4396'),
('26ef38fe-cc83-596b-a0d7-183f8d3a6a83', 'Plancha lateral con kettlebell', ARRAY['Túmbate de lado y apoya el antebrazo en el suelo con el codo bajo el hombro.', 'Sujeta la kettlebell con la mano libre y extiende el brazo hacia arriba.', 'Eleva la cadera hasta formar una línea recta desde la cabeza a los pies.', 'Mantén la posición respirando con normalidad y sin dejar caer la cadera.']::text[], 'intermedio', 'Fortalece el core y los oblicuos en isométrico, mejorando la estabilidad lateral y la resistencia postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '5879'),
('c37b10af-7f8c-54a1-a660-238abf5b5339', 'Paso lateral en sentadilla con kettlebell', ARRAY['De pie con la kettlebell sujeta al pecho, da un paso amplio hacia un lado.', 'Flexiona la rodilla de la pierna que recibe el peso y baja la cadera hacia atrás.', 'Empuja con el pie para volver al centro y alterna de lado.', 'Mantén las rodillas alineadas con los pies y evita que se hundan hacia dentro.']::text[], 'intermedio', 'Activa cuádriceps y glúteos con un desplazamiento lateral que también trabaja aductores y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4524'),
('1a8cc8bb-361e-5988-9160-7d06e3e38f96', 'Swing lateral con kettlebell', ARRAY['De pie con la kettlebell en una mano, pies algo más anchos que los hombros.', 'Lleva la pesa entre las piernas y empuja la cadera hacia atrás.', 'Extiende la cadera con fuerza para balancear la kettlebell hacia el lado.', 'Controla el descenso y evita arquear la espalda o usar solo los brazos.']::text[], 'intermedio', 'Potencia la cadena posterior y el core con un movimiento explosivo de cadera en el plano lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10192'),
('1c3264c5-5421-5fa7-9356-492fa2775003', 'Apertura alterna a un brazo con kettlebell', ARRAY['Túmbate en el suelo con la kettlebell en una mano y el brazo extendido sobre el pecho.', 'Abre el brazo hacia el lado con el codo ligeramente flexionado.', 'Vuelve al centro controlando el movimiento y alterna de brazo.', 'Evita bajar demasiado el brazo para no forzar el hombro.']::text[], 'intermedio', 'Trabaja el pectoral y la estabilidad del hombro con una apertura unilateral que exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11284'),
('a2c8d6d2-82c1-5568-8bca-eb62052184a9', 'Cargada y press a un brazo con kettlebell', ARRAY['Con la kettlebell en una mano, flexiona ligeramente las rodillas y lleva la pesa al hombro.', 'Desde ahí empuja la kettlebell por encima de la cabeza extendiendo el brazo.', 'Baja la pesa al hombro y luego al suelo con control.', 'Evita arquear la espalda al empujar y mantén el core firme.']::text[], 'intermedio', 'Combina potencia de cadera y empuje vertical para trabajar hombros, tríceps y core de forma global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4531'),
('1f3a17da-f88d-5ef5-aa39-fa5f7c62cdf8', 'Zancada con kettlebell sobre la cabeza', ARRAY['Sujeta la kettlebell por encima de la cabeza con un brazo extendido.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el brazo firme y evita que la cadera se balancee.']::text[], 'intermedio', 'Desafía cuádriceps, glúteos y hombros con una zancada que exige estabilidad del core y del brazo elevado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5071'),
('7019c131-9d3a-5ad0-ba73-c6c7d3aa6d6f', 'Abdominal a un brazo con kettlebell', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la kettlebell en una mano sobre el pecho.', 'Eleva el tronco hasta sentarte manteniendo la pesa cerca del cuerpo.', 'Baja despacio controlando el abdomen y alterna de brazo.', 'Evita tirar del cuello o usar impulso para subir.']::text[], 'intermedio', 'Refuerza el recto abdominal y los flexores de cadera con una carga unilateral que añade control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4535'),
('946554a6-477e-546a-ad1d-905e4e2f4e57', 'Balanceo a un brazo con kettlebell', ARRAY['De pie con la kettlebell en una mano y los pies a la anchura de los hombros.', 'Lleva la pesa entre las piernas empujando la cadera hacia atrás.', 'Extiende la cadera con fuerza para balancear la kettlebell hasta la altura del pecho.', 'Controla el descenso y evita redondear la espalda.']::text[], 'intermedio', 'Trabaja glúteos y cadena posterior con un swing unilateral que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4527'),
('072fe6c9-13d6-5232-b004-7931a759eadd', 'Sentadilla frontal a una pierna con kettlebell', ARRAY['Sujeta la kettlebell al pecho y apoya un pie en el suelo.', 'Flexiona la rodilla y baja la cadera manteniendo el tronco erguido.', 'Empuja con el pie para volver arriba y alterna de pierna.', 'Evita que la rodilla se desplace hacia dentro y mantén el core activo.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sentadilla unilateral que mejora el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4123'),
('47d0776c-ac5c-512d-8e36-2fc90cfb5403', 'Peso muerto a una pierna con pase de kettlebell', ARRAY['De pie con la kettlebell en una mano y el peso sobre una pierna.', 'Inclina el tronco hacia delante y eleva la pierna libre hacia atrás.', 'Pasa la kettlebell a la otra mano por debajo del cuerpo.', 'Vuelve arriba controlando el movimiento y alterna de pierna.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos con un peso muerto unilateral que también mejora el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10561'),
('9c442b53-09e8-5caa-a27b-292190092aac', 'Pullover con puente de glúteos a una pierna', ARRAY['Túmbate boca arriba con un pie apoyado y la kettlebell sujeta con ambas manos sobre el pecho.', 'Eleva la cadera formando un puente con una pierna extendida.', 'Lleva la kettlebell por encima de la cabeza y vuelve al pecho.', 'Mantén la cadera alta y evita arquear la zona lumbar.']::text[], 'intermedio', 'Combina glúteos y dorsal en un ejercicio que exige estabilidad de cadera y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3522'),
('329aefd9-eab8-568f-a40d-6a62cc98fa07', 'Subida al cajón a una pierna con kettlebell', ARRAY['Coloca un pie sobre el cajón y sujeta la kettlebell al pecho.', 'Empuja con la pierna de arriba para subir el cuerpo.', 'Baja despacio controlando la pierna y alterna.', 'Evita impulsarte con la pierna de abajo o dejar caer el peso.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora la fuerza y el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4134'),
('185de39e-d996-52e8-9eb0-2dd5516989d2', 'Abdominal con kettlebell', ARRAY['Túmbate boca arriba con las rodillas flexionadas y la kettlebell sujeta al pecho.', 'Eleva el tronco hasta sentarte manteniendo la pesa pegada al cuerpo.', 'Baja despacio controlando el abdomen.', 'Evita tirar del cuello o usar impulso para subir.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera con una carga que aumenta la exigencia del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1187'),
('6117e40b-8ebc-5888-a589-6cf156e6e3b3', 'Press de tibial sentado con kettlebell', ARRAY['Siéntate en una silla con la kettlebell apoyada sobre el empeine del pie.', 'Eleva la punta del pie contra la pesa sin mover la rodilla.', 'Baja despacio controlando el movimiento y repite.', 'Evita balancear la pierna o usar demasiado peso.']::text[], 'intermedio', 'Fortalece la tibia y el tobillo para mejorar la estabilidad y prevenir molestias en la parte delantera de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10367'),
('2a81d117-8d73-59f0-bce3-37cbe7341fea', 'Slingshot con kettlebell', ARRAY['Colócate de pie con los pies a la anchura de los hombros y sujeta la kettlebell con una mano delante de la cadera.', 'Pasa la pesa alrededor de la cabeza por detrás del cuello y recógela con la otra mano.', 'Continúa el círculo bajando por la espalda hasta la cadera y repite el recorrido sin parar.', 'Mantén el abdomen firme y la mirada al frente para evitar que el tronco gire en exceso.', 'Evita encoger los hombros: deja que el movimiento salga de los brazos y del core.']::text[], 'intermedio', 'Trabaja hombros, core y antebrazos pasando la pesa alrededor del cuerpo; mejora la estabilidad y la coordinación del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3578'),
('69f10a39-5867-5f30-8cfd-0c3b72de5b4b', 'Arrancada con kettlebell', ARRAY['Coloca la kettlebell entre los pies y agárrala con una mano, con la espalda recta y las caderas atrás.', 'Empuja el suelo con las piernas y extiende la cadera de forma explosiva para lanzar la pesa hacia arriba.', 'Cuando la pesa llegue a la altura del pecho, mete la mano por debajo y fíjala por encima de la cabeza con el brazo estirado.', 'Acompaña la bajada controlando la pesa hasta el suelo y cambia de mano.', 'Evita tirar solo con el brazo: la fuerza nace de las piernas y la cadera.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que potencia glúteos, isquios y hombros; mejora la potencia y la coordinación global.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4532'),
('9005f10f-a169-5568-89da-1a97c23dca55', 'Press sots con kettlebell', ARRAY['Sujeta la kettlebell a la altura del hombro y baja en sentadilla profunda manteniendo el pecho alto.', 'Desde esa posición, empuja la pesa por encima de la cabeza hasta estirar el brazo.', 'Baja la pesa de forma controlada al hombro sin perder la sentadilla.', 'Mantén el abdomen apretado y la espalda neutra durante todo el recorrido.', 'Evita arquear la zona lumbar al press: si pierdes la posición, reduce la profundidad.']::text[], 'intermedio', 'Press de hombros desde sentadilla profunda que exige movilidad y estabilidad; refuerza hombros, cuádriceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3573'),
('218bebd5-1039-53d0-8ecc-442662be7e88', 'Arrancada dividida con kettlebell', ARRAY['Parte con la kettlebell entre los pies, agárrala con una mano y prepara la espalda recta.', 'Extiende cadera y rodillas de forma explosiva para lanzar la pesa hacia arriba.', 'Al recibirla, da un paso adelante y baja en zancada con la pesa fijada sobre la cabeza.', 'Vuelve a la posición inicial con control y cambia de pierna y de mano.', 'Evita bloquear la rodilla trasera en el aire: aterriza con la zancada ya formada.']::text[], 'avanzado', 'Variante de arrancada que trabaja glúteos, hombros y piernas; desarrolla potencia y estabilidad en posición dividida.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4210'),
('a5e6cc07-2e46-5df4-b538-0f1f9a165631', 'Sentadilla dividida con kettlebell', ARRAY['Sujeta la kettlebell contra el pecho y coloca un pie delante y otro detrás en zancada.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con la pierna delantera para volver a subir sin mover los pies.', 'Mantén el peso repartido y evita que la rodilla delantera se vaya hacia dentro.', 'Respira al bajar y aprieta el glúteo al subir.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y aductores con una pierna adelantada; mejora el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4059'),
('b1321152-efdd-5ae3-b6a6-bb033fedab5d', 'Sentadilla con kettlebell', ARRAY['Sujeta la kettlebell a la altura del pecho con ambas manos y los pies a la anchura de los hombros.', 'Baja las caderas hacia atrás y abajo manteniendo el pecho alto y la espalda recta.', 'Llega hasta donde puedas sin perder la curvatura lumbar y empuja con los talones para subir.', 'Aprieta glúteos al final y evita que las rodillas se metan hacia dentro.', 'Respira al bajar y suelta el aire al subir.']::text[], 'intermedio', 'Ejercicio básico de piernas que trabaja cuádriceps, glúteos y core; mejora la fuerza y la técnica de sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10673'),
('0b35692e-37ae-5100-bac3-7e1e8144088d', 'Peso muerto con postura escalonada y kettlebell', ARRAY['Coloca un pie adelantado y otro atrás, con la kettlebell en el suelo entre ambos.', 'Agárrala con las dos manos y lleva las caderas atrás manteniendo la espalda recta.', 'Baja hasta notar el estiramiento en los isquios y sube empujando con los talones.', 'Mantén el torso firme y evita redondear la espalda al recoger la pesa.', 'Cambia la pierna adelantada al terminar la serie.']::text[], 'intermedio', 'Trabaja isquios, glúteos y espalda baja con una pierna adelantada; mejora la fuerza y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8892'),
('8b365a32-2e33-5d97-a379-4c1c4b349674', 'Peso muerto rumano con kettlebell detrás de la espalda', ARRAY['Sujeta la kettlebell con las dos manos por detrás de la espalda, a la altura de los glúteos.', 'Con las piernas casi rectas, lleva las caderas atrás y baja la pesa por detrás de las piernas.', 'Detente cuando notes el estiramiento en los isquios y vuelve a subir apretando glúteos.', 'Mantén el pecho alto y la espalda neutra durante todo el recorrido.', 'Evita flexionar las rodillas en exceso: el movimiento sale de la cadera.']::text[], 'intermedio', 'Trabaja isquios y glúteos con la pesa detrás del cuerpo; mejora la fuerza del tren posterior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11287'),
('90a5a375-6a1a-5d0b-936f-a05afd78b9ee', 'Press de hombros a un brazo bottoms-up con kettlebell', ARRAY['Sujeta la kettlebell por el mango con la base hacia arriba y el codo pegado al cuerpo.', 'Empuja la pesa lentamente por encima de la cabeza manteniendo la base arriba.', 'Baja de forma controlada hasta el hombro sin perder el equilibrio de la pesa.', 'Mantén el abdomen firme y la muñeca recta durante todo el movimiento.', 'Evita compensar con la espalda: si la pesa se inclina, usa menos peso.']::text[], 'intermedio', 'Press de hombros con la pesa invertida que exige estabilidad; refuerza deltoides, antebrazos y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3736'),
('4043e722-d54f-53be-84ce-24047389210c', 'Extensión de pie a un brazo con kettlebell', ARRAY['Sujeta la kettlebell con una mano por encima de la cabeza y el brazo estirado.', 'Baja la pesa por detrás de la cabeza flexionando solo el codo.', 'Extiende el brazo de nuevo sin mover el hombro ni el tronco.', 'Mantén el codo apuntando al frente y el abdomen apretado.', 'Evita abrir el codo hacia fuera: mantenlo cerca de la cabeza.']::text[], 'intermedio', 'Aísla el tríceps desde de pie con una pesa; mejora la fuerza y el control del brazo en posición vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5863'),
('ed65cdd4-d231-57e1-8bdf-5c830a42af33', 'Slingshot de pie con kettlebell', ARRAY['De pie con los pies a la anchura de los hombros, sujeta la kettlebell con una mano a la altura de la cadera.', 'Pasa la pesa por delante del cuerpo hacia la otra mano en un movimiento circular.', 'Continúa el círculo por detrás de la espalda y recógela de nuevo delante.', 'Mantén las rodillas ligeramente flexionadas y el core activo para no girar el tronco.', 'Evita usar impulso de la espalda: el movimiento sale de los brazos y los hombros.']::text[], 'intermedio', 'Paso de la pesa alrededor del cuerpo que trabaja hombros, core y oblicuos; mejora la coordinación y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4534'),
('904fd3e0-e906-55e9-99e5-e7b90a527317', 'Slingshots con kettlebell de pie (avanzado)', ARRAY['Colócate de pie con la kettlebell en una mano y el abdomen bien apretado.', 'Pasa la pesa alrededor de la cintura con un ritmo constante y sin girar el tronco.', 'Recíbela con la otra mano y continúa el círculo por detrás de la espalda.', 'Mantén la mirada al frente y los hombros bajos durante todo el recorrido.', 'Evita arquear la espalda o encoger los hombros cuando la pesa pase por detrás.']::text[], 'intermedio', 'Versión avanzada del paso de pesa que exige más control; refuerza abdomen, oblicuos y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '12018'),
('78e28e15-d2fa-5ffd-9916-d1dfa11f22de', 'Peso muerto con piernas rectas y kettlebell', ARRAY['Sujeta la kettlebell con las dos manos delante de los muslos y los pies a la anchura de las caderas.', 'Con las rodillas ligeramente flexionadas, lleva las caderas atrás y baja la pesa por delante de las piernas.', 'Detente cuando notes el estiramiento en los isquios y sube apretando glúteos.', 'Mantén la espalda recta y el pecho alto durante todo el recorrido.', 'Evita redondear la espalda: si pasa, reduce el rango de bajada.']::text[], 'intermedio', 'Trabaja isquios, glúteos y espalda baja con las piernas casi extendidas; mejora la fuerza del tren posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3733'),
('dd2ab7ba-c221-570b-a7dc-10016e7d00ab', 'Giro ruso fuerte con kettlebell', ARRAY['Siéntate con las rodillas flexionadas y sujeta la kettlebell con las dos manos delante del pecho.', 'Inclina ligeramente el torso atrás manteniendo la espalda recta.', 'Gira el tronco hacia un lado y lleva la pesa junto a la cadera, luego hacia el otro lado.', 'Mantén el movimiento controlado y evita tirar solo con los brazos.', 'Respira de forma constante y no bloquees el aire en cada giro.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con rotación controlada; mejora la fuerza del core y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10327'),
('511ad66d-de81-5836-8dba-9616c9d0504d', 'Peso muerto maleta con kettlebell', ARRAY['Coloca la kettlebell en el suelo junto a un pie y agáchate con la espalda recta para agarrarla.', 'Empuja con las piernas y extiende la cadera para ponerte de pie con la pesa a un lado.', 'Mantén el tronco recto y evita inclinarte hacia el lado de la pesa.', 'Baja la pesa de forma controlada hasta el suelo y repite.', 'Cambia de mano al terminar la serie para trabajar ambos lados.']::text[], 'intermedio', 'Trabaja glúteos, isquios y oblicuos con la pesa a un lado; mejora la fuerza y la estabilidad lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4133'),
('845e49ca-6f69-57e3-9a4c-e45f1d8d8176', 'Peso muerto sumo con kettlebell', ARRAY['Coloca los pies más anchos que los hombros con las puntas hacia fuera y la kettlebell entre ellos.', 'Agarra el asa con ambas manos, saca pecho y mantén la espalda recta.', 'Empuja el suelo con los talones y extiende las caderas hasta quedar de pie apretando los glúteos.', 'Baja controlando el movimiento con la cadera hacia atrás, sin redondear la espalda.', 'Evita tirar con los brazos: son solo un enlace entre la kettlebell y tu cadera.']::text[], 'intermedio', 'Trabaja glúteos, isquiotibiales y aductores; mejora la fuerza de la cadena posterior y la técnica de bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4046'),
('d0d60f15-c522-54c0-84d8-38599f841677', 'Peso muerto sumo con tirón alto y kettlebell', ARRAY['Separa los pies y coloca la kettlebell entre ellos con el pecho alto y la espalda neutra.', 'Realiza el peso muerto empujando con los talones y extendiendo las caderas.', 'Al llegar arriba, tira del asa hacia el pecho con los codos altos y guiando con los hombros.', 'Baja la kettlebell controlando el descenso y vuelve a la posición inicial.', 'Evita encoger los hombros hacia las orejas durante el tirón.']::text[], 'intermedio', 'Combina fuerza de glúteos e isquiotibiales con un tirón explosivo que activa trapecios y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4132'),
('d921466b-ce5d-58d6-987e-e37543308857', 'Jalón alto sumo con kettlebell', ARRAY['Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.', 'Sujeta una pesa rusa con ambas manos frente al cuerpo, con los brazos extendidos hacia abajo.', 'Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.', 'Empuja con los talones y extiende explosivamente las caderas y las rodillas, tirando de la pesa rusa hacia la barbilla.', 'Mientras tiras de la pesa rusa hacia arriba, mantén los codos altos y abiertos, y junta los omóplatos.', 'Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio explosivo que trabaja trapecios y hombros con ayuda de glúteos e isquiotibiales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0548');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('9f47f911-4276-51d1-baa8-153d908d09fa', 'Sentadilla sumo con kettlebell', ARRAY['Sujeta la kettlebell con ambas manos delante del pecho y abre los pies más allá de los hombros.', 'Apunta las puntas hacia fuera y baja la cadera llevando las rodillas en la misma dirección que los pies.', 'Desciende hasta donde puedas mantener el pecho alto y la espalda recta.', 'Empuja con los talones para subir apretando los glúteos al final.', 'Evita que las rodillas se metan hacia dentro durante el descenso.']::text[], 'intermedio', 'Fortalece glúteos, cuádriceps y aductores con una sentadilla amplia que mejora la movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4089'),
('b14fbcdd-57a0-5489-a733-4282f3838a8c', 'Balanceo con kettlebell y sentadilla frontal con agarre de cargada', ARRAY['Haz un swing con la kettlebell impulsando desde la cadera y no desde los brazos.', 'Al terminar el swing, recógela en posición de cargada con el codo pegado al cuerpo.', 'Baja en sentadilla frontal manteniendo el pecho alto y los codos hacia delante.', 'Sube empujando con los talones y vuelve a la posición de cargada.', 'Evita perder la tensión del core al pasar del swing a la sentadilla.']::text[], 'intermedio', 'Encadena un swing y una sentadilla frontal para trabajar glúteos, cuádriceps y core en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7563'),
('80e0439a-8322-5f7e-9bb2-075fab7bc69d', 'Swing, cargada, sentadilla frontal y press sobre la cabeza con kettlebell', ARRAY['Realiza un swing impulsando con la cadera y frena la kettlebell en la posición de cargada.', 'Desde la cargada, baja en sentadilla frontal con el pecho alto y los codos delante.', 'Sube y, sin perder la tensión, empuja la kettlebell sobre la cabeza extendiendo el brazo.', 'Baja la kettlebell a la cargada y encadena el siguiente swing con control.', 'Evita arquear la zona lumbar al hacer el press sobre la cabeza.']::text[], 'intermedio', 'Secuencia completa que trabaja glúteos, piernas, hombros y core con fuerza y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5335'),
('b83db2d4-96a4-521d-96cd-dfa9af9ddbce', 'Balanceo con kettlebell a sentadilla goblet', ARRAY['Haz un swing con la kettlebell impulsando desde la cadera y manteniendo la espalda neutra.', 'Al frenar el swing, recoge la kettlebell con ambas manos delante del pecho.', 'Baja en sentadilla goblet con los codos dentro de las rodillas y el pecho alto.', 'Sube empujando con los talones y vuelve a iniciar el swing.', 'Evita redondear la espalda al recoger la kettlebell tras el swing.']::text[], 'intermedio', 'Combina potencia de cadera y fuerza de piernas, trabajando glúteos, cuádriceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7548'),
('563ca44c-71d5-587c-afd1-4733b10d7028', 'Levantamiento turco con kettlebell (estilo sentadilla)', ARRAY['Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro.', 'Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida.', 'Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente.', 'Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo.', 'Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo.', 'Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas.', 'Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza.', 'Invierte el movimiento para volver a la posición inicial.', 'Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda.']::text[], 'intermedio', 'Ejercicio global que trabaja glúteos, piernas y core mejorando estabilidad y control corporal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0551'),
('53658ae2-5d0f-5d2b-a9a1-833aaac23c11', 'Levantamiento turco a la mano con kettlebell', ARRAY['Túmbate con la kettlebell extendida sobre el hombro y la rodilla del mismo lado flexionada.', 'Rueda sobre el codo y luego apoya la mano para incorporarte manteniendo el brazo vertical.', 'Levanta la cadera y pasa la pierna por debajo hasta quedar en posición de zancada.', 'Ponte de pie con control y deshaz el camino en orden inverso.', 'Evita perder la verticalidad del brazo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja hombros, core y glúteos mejorando la estabilidad y el control del cuerpo en el suelo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4057'),
('b15c2c02-d578-5a72-95b7-0679d93cfb3a', 'Remo a dos brazos con kettlebell', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sostén una pesa rusa en cada mano con las palmas hacia el cuerpo.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.', 'Tira de las pesas rusas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1345'),
('701fa658-9d41-56d6-a653-4043d785f42d', 'Paseo del granjero unilateral con kettlebell', ARRAY['Coge la kettlebell con una mano y mantén los hombros nivelados y el core activo.', 'Camina con pasos cortos y controlados sin inclinarte hacia el lado de la carga.', 'Mantén la mirada al frente y respira con normalidad durante el recorrido.', 'Cambia de mano al terminar la distancia o el tiempo.', 'Evita encoger el hombro que sujeta la kettlebell.']::text[], 'intermedio', 'Mejora el agarre y la estabilidad del core caminando con carga en un solo lado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5099'),
('f2fa87cc-1ff1-5501-8b24-55c01f8d361f', 'Leñador con kettlebell', ARRAY['Sujeta la kettlebell con ambas manos a un lado de la cadera y abre los pies a la anchura de los hombros.', 'Lleva la kettlebell en diagonal hacia el hombro contrario girando el tronco y pivotando el pie.', 'Controla el retorno a la posición inicial sin dejar caer la carga.', 'Mantén el core activo y evita tirar solo con los brazos.', 'No gires en exceso la zona lumbar: el movimiento sale del tronco y la cadera.']::text[], 'intermedio', 'Trabaja abdominales y oblicuos con un movimiento diagonal que también activa hombros y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8025'),
('51542c90-0857-5988-bb77-83c11d01a729', 'Curl de muñeca con kettlebell', ARRAY['Siéntate y apoya el antebrazo en el muslo con la muñeca fuera de la rodilla.', 'Sujeta la kettlebell con la palma hacia arriba y deja caer la muñeca lentamente.', 'Sube la muñeca flexionando solo la mano, sin mover el antebrazo.', 'Baja con control y repite sin balancear el brazo.', 'Evita usar impulso del codo para subir la carga.']::text[], 'intermedio', 'Fortalece antebrazos y flexores de la muñeca, mejorando el agarre y la fuerza de la mano.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5862'),
('09ad7ed8-3573-5b5b-85d7-a98bf86f36b3', 'Press z con kettlebell', ARRAY['Siéntate en el suelo con las piernas extendidas en forma de V y la espalda recta.', 'Sujeta la kettlebell a la altura del hombro con el codo flexionado.', 'Empuja la kettlebell sobre la cabeza extendiendo el brazo sin arquear la espalda.', 'Baja con control hasta el hombro y repite manteniendo el core activo.', 'Evita inclinarte hacia atrás para compensar la falta de fuerza.']::text[], 'intermedio', 'Trabaja hombros, tríceps y core sentado en el suelo, exigiendo estabilidad y fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9703'),
('4c3ea9a6-dcee-5fbb-9192-976283e5b867', 'Peso muerto sumo con kettlebells', ARRAY['Coloca dos kettlebells entre los pies abiertos y agarra un asa de cada una.', 'Saca pecho y mantén la espalda recta mientras bajas la cadera.', 'Empuja con los talones y extiende las caderas hasta quedar de pie apretando los glúteos.', 'Baja controlando el movimiento con la cadera hacia atrás.', 'Evita redondear la espalda o tirar con los brazos durante el levantamiento.']::text[], 'intermedio', 'Fortalece glúteos, isquiotibiales y aductores con una bisagra de cadera estable y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4403'),
('2cd55a72-3307-5540-a6e6-56784651cf6c', 'Patada de piernas sentado', ARRAY['Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo.', 'Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante.', 'Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos con un gesto controlado que mejora la extensión de cadera y la estabilidad del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0555'),
('b4f5c87d-2d4e-5e68-a67c-59d8e2ec9e4b', 'Salto con patada lateral', ARRAY['Colócate de pie con los pies a la anchura de las caderas y las rodillas ligeramente flexionadas.', 'Salta hacia un lado mientras extiendes la pierna contraria en una patada lateral controlada.', 'Aterriza suavemente con la rodilla flexionada y absorbe el impacto antes de repetir al otro lado.', 'Mantén el core activo y evita bloquear las rodillas en el aterrizaje.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y potencia la explosividad de piernas y core con un salto lateral que exige coordinación y aterrizaje seguro.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4898'),
('eecc940a-6c8a-5cb1-8b68-14ab4de8f4de', 'Flexión con patada pasante', ARRAY['Adopta la posición de plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho flexionando los codos y mantén el core firme sin hundir la cadera.', 'Empuja para subir y lleva una rodilla hacia el pecho pasando la pierna por debajo del cuerpo.', 'Vuelve a la plancha y alterna el lado en cada repetición, evitando arquear la zona lumbar.']::text[], 'intermedio', 'Combina empuje de pecho y tríceps con una patada que activa el core y mejora la coordinación en posición de plancha.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4159'),
('55c0fa46-27b9-5344-a909-807733735c87', 'Patada de glúteo con pierna flexionada', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Mantén la rodilla flexionada y empuja el pie hacia el techo sin mover la cadera.', 'Aprieta el glúteo arriba un instante y baja la pierna con control sin apoyar del todo.', 'Evita arquear la lumbar y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Aísla el glúteo mayor y los isquiotibiales con una patada controlada que también estabiliza el core y la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5810'),
('efa5db17-55ae-5cfa-aa55-00960b7c5e06', 'Muscle up con kipping', ARRAY['Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Activa el core y usa un movimiento de balanceo para generar impulso.', 'Mientras te balanceas hacia adelante, tira del pecho hacia la barra, usando los dorsales y los bíceps para iniciar el movimiento.', 'Continúa el movimiento ascendente hasta que el pecho llegue a la barra, luego pasa a una posición de fondos empujando hacia abajo en la barra y extendiendo los brazos.', 'Bájate de vuelta a la posición inicial flexionando los brazos y controlando el descenso.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Ejercicio avanzado de tracción y empuje que desarrolla dorsal, bíceps y hombros con un impulso explosivo en barra.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0558'),
('1073853f-b852-5c6a-ba50-cabefaf05dbd', 'Extensión de rodilla', ARRAY['Siéntate en una silla con la espalda recta y los pies apoyados en el suelo.', 'Extiende una pierna hasta estirar la rodilla sin bloquearla bruscamente.', 'Mantén la posición un par de segundos y baja el pie con control.', 'Evita balancear la pierna o compensar con la cadera durante el movimiento.']::text[], 'principiante', 'Moviliza la articulación de la rodilla y activa el cuádriceps para mejorar el rango de movimiento y la salud articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2773'),
('b97c3e23-59b7-535b-9a82-47c8015246e2', 'Flexión de rodilla', ARRAY['Túmbate boca abajo con las piernas estiradas y la cadera pegada al suelo.', 'Flexiona una rodilla llevando el talón hacia el glúteo sin despegar la cadera.', 'Mantén unos segundos arriba y baja la pierna lentamente.', 'Evita arquear la lumbar o tirar con fuerza brusca al flexionar.']::text[], 'principiante', 'Mejora la movilidad de la rodilla y activa isquiotibiales y gemelos para un tren inferior más funcional.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2774'),
('7b79d67a-63e0-5c3e-8d86-bb76787244e5', 'Flexión con rodillas y retroceso de pecho', ARRAY['Apoya las rodillas en el suelo y coloca las manos algo más anchas que los hombros.', 'Baja el pecho flexionando los codos y mantén el cuerpo alineado desde la cabeza a las rodillas.', 'Empuja para subir y lleva el pecho ligeramente hacia atrás al final para activar la espalda.', 'Evita dejar caer la cadera o adelantar la cabeza durante el descenso.']::text[], 'intermedio', 'Trabaja el pecho y los tríceps desde una posición más accesible, reforzando el control escapular y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6231'),
('3eb6d8c8-3a99-5e4a-9c21-75255ac1af92', 'Elevación de rodilla', ARRAY['Colócate de pie con la espalda recta y el abdomen activo.', 'Eleva una rodilla hacia la cadera manteniendo el equilibrio sobre la otra pierna.', 'Baja el pie con control y alterna el lado sin perder la postura.', 'Evita inclinarte hacia atrás o encoger los hombros al subir la rodilla.']::text[], 'principiante', 'Activa el cuádriceps y los flexores de cadera, mejora el equilibrio y refuerza el core en apoyo monopodal.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4287'),
('a5519550-438e-599b-885c-c22b9e08973f', 'Estiramiento de gemelos con rodilla al cajón', ARRAY['Coloca una caja o escalón delante y apoya la punta del pie con el talón en el suelo.', 'Lleva la rodilla hacia la caja manteniendo el talón apoyado y la pierna estirada.', 'Mantén el estiramiento entre veinte y treinta segundos sin rebotar.', 'Evita girar el pie hacia fuera o levantar el talón durante el estiramiento.']::text[], 'principiante', 'Estira gemelos y sóleo, mejora la flexibilidad del tobillo y alivia la tensión tras correr o entrenar piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10563'),
('bce2160a-b409-5c5e-ad4b-d781be441c19', 'Estiramiento de rodilla al pecho', ARRAY['Túmbate boca arriba con las piernas estiradas y la espalda relajada.', 'Lleva una rodilla hacia el pecho con las manos y mantén la otra pierna estirada.', 'Respira despacio y mantén el estiramiento entre veinte y treinta segundos.', 'Evita tirar con fuerza brusca o despegar la cabeza y los hombros del suelo.']::text[], 'principiante', 'Libera tensión en glúteos y zona lumbar y mejora la movilidad de la cadera tras sesiones de fuerza o carrera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0559'),
('e12d9734-67fa-5659-b318-39ed0ab4216f', 'Abdominal con toque de rodilla', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda.', 'Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el recto abdominal y los flexores de cadera con un gesto corto que mejora el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3640'),
('38f1c2dd-14f6-586b-adc0-7c691aedf14e', 'Salto con rodillas al pecho', ARRAY['Colócate de pie con los pies a la anchura de las caderas y el abdomen activo.', 'Salta hacia arriba y lleva ambas rodillas hacia el pecho en el aire.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto.', 'Evita aterrizar con las piernas rígidas o perder la alineación de rodillas y pies.']::text[], 'intermedio', 'Desarrolla potencia de piernas y core con un salto explosivo que mejora la coordinación y la capacidad cardiovascular.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1570'),
('2607d889-7f3a-5dc8-be56-dc773f7856c4', 'Flexión con rodillas al pecho', ARRAY['Adopta la posición de plancha alta con las manos bajo los hombros.', 'Baja el pecho flexionando los codos y mantén el cuerpo alineado.', 'Al subir, lleva ambas rodillas hacia el pecho y vuelve a la plancha.', 'Evita hundir la cadera o adelantar la cabeza durante el movimiento.']::text[], 'intermedio', 'Combina empuje de pecho y tríceps con una recogida de rodillas que exige control del core y coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8894'),
('b7d90ecd-65a3-585f-8160-bcf211b5473e', 'Estiramiento abdominal de rodillas', ARRAY['Arrodíllate con las rodillas separadas y las manos apoyadas en el suelo.', 'Desliza las manos hacia delante y baja el pecho mientras llevas la cadera hacia atrás.', 'Mantén el estiramiento entre veinte y treinta segundos respirando despacio.', 'Evita forzar la lumbar o levantar los glúteos de los talones.']::text[], 'principiante', 'Estira el recto abdominal y los flexores de cadera, alivia la tensión lumbar y mejora la extensión de la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2109'),
('1f94c128-3ce8-5208-a207-50421983b328', 'Dominada supina asistida deslizante de rodillas', ARRAY['Colócate de rodillas frente a la barra con las palmas mirando hacia ti.', 'Agarra la barra a la anchura de los hombros y deja que las rodillas se deslicen hacia delante al subir.', 'Tira del pecho hacia la barra mientras sueltas aire y aprieta los omóplatos.', 'Baja controlando el movimiento sin dejar caer el cuerpo de golpe.', 'Evita encoger los hombros hacia las orejas durante el ascenso.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con ayuda del deslizamiento, ideal para progresar hacia la dominada completa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4919'),
('40cb5c8a-ab55-52bd-82e5-1c7bf16e90aa', 'Rotación de espalda de rodillas', ARRAY['Arrodíllate con la espalda recta y las manos en la nuca.', 'Gira el tronco lentamente hacia un lado manteniendo las caderas fijas.', 'Vuelve al centro y repite hacia el otro lado con control.', 'Respira de forma fluida y evita forzar el rango de movimiento.']::text[], 'principiante', 'Moviliza la columna y activa oblicuos y core, mejorando la rotación torácica y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5029'),
('baf161c4-eb16-5022-a892-c0358bd3720a', 'Estiramiento de rotación de espalda de rodillas', ARRAY['Siéntate sobre los talones con la espalda erguida.', 'Coloca una mano en el suelo y gira el tronco hacia ese lado.', 'Mantén la posición entre veinte y treinta segundos respirando despacio.', 'Cambia de lado sin rebotar ni forzar la zona lumbar.']::text[], 'principiante', 'Relaja la columna y la zona lumbar, aliviando tensiones tras estar muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1812'),
('4068e811-e98a-53e5-9ced-8e7f90009165', 'Cuerdas de batalla de rodillas', ARRAY['Arrodíllate frente a las cuerdas y agarra un extremo en cada mano.', 'Mueve los brazos arriba y abajo de forma alterna y rápida.', 'Mantén el core firme y la espalda recta durante todo el ejercicio.', 'Respira de forma constante y evita bloquear los hombros.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja hombros y core con un cardio intenso de bajo impacto.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2929'),
('6c2e0c1d-da59-5fb3-af7c-7872e0e18ab3', 'Flexión de rodilla de rodillas con apoyo en silla', ARRAY['Arrodíllate con una mano apoyada en la silla para mantener el equilibrio.', 'Desliza una rodilla hacia delante sin levantar el pie del suelo.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita que la rodilla se vaya hacia dentro durante el recorrido.']::text[], 'principiante', 'Mejora la movilidad de rodilla y cadera y activa cuádriceps con apoyo para mayor seguridad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10543'),
('dd076d0e-a7a0-552a-bede-2624b11d9176', 'Estiramiento de pecho de rodillas', ARRAY['Arrodíllate con las manos entrelazadas detrás de la espalda.', 'Lleva los brazos hacia atrás y eleva el pecho sin arquear la lumbar.', 'Mantén la posición veinte segundos respirando profundo.', 'Evita encoger los hombros o tirar del cuello.']::text[], 'principiante', 'Abre el pecho y los hombros, compensando la postura encorvada de estudiar o usar el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1785'),
('86523b06-624d-5ae9-b086-157a12853df1', 'Flexión cobra de rodillas', ARRAY['Arrodíllate con las manos en el suelo a la anchura de los hombros.', 'Baja el pecho hacia el suelo flexionando los codos.', 'Empuja hacia arriba mientras extiendes la columna como una cobra.', 'Mantén el core activo y evita hundir la zona lumbar.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros con una variante de flexión que también moviliza la columna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3489'),
('e8666638-254d-540e-ac08-ce0f15e17ade', 'Estiramiento de aductores de rodillas boca abajo', ARRAY['Colócate boca abajo con las rodillas flexionadas y separadas.', 'Junta las plantas de los pies y deja caer las rodillas hacia los lados.', 'Mantén la posición sin forzar y respirando de forma relajada.', 'Evita rebotar o presionar la zona lumbar contra el suelo.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, mejorando la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1901'),
('e89e1b5d-7c84-5d81-9c40-f6c89677b319', 'Círculos de cadera hacia adelante de rodillas', ARRAY['Arrodíllate con las manos en la cintura y el core activo.', 'Dibuja círculos amplios con la cadera hacia delante.', 'Mantén el movimiento lento y controlado sin mover los hombros.', 'Cambia de sentido al terminar las repeticiones.']::text[], 'principiante', 'Moviliza la cadera y activa glúteos y core, preparando la articulación para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5057'),
('aa94d8b3-3470-52bc-855d-a7b4c9e06076', 'Press de glúteos de rodillas', ARRAY['Colócate a cuatro patas con las manos bajo los hombros.', 'Empuja un talón hacia el techo manteniendo la rodilla flexionada.', 'Aprieta el glúteo arriba y baja despacio sin arquear la lumbar.', 'Evita girar la cadera hacia un lado durante el movimiento.']::text[], 'intermedio', 'Activa y fortalece glúteos e isquios con un gesto de extensión de cadera controlado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6747'),
('b8c486c9-4387-56b9-b0cd-c17b43847eaa', 'Media extensión de tríceps de rodillas', ARRAY['Arrodíllate frente a la polea y agarra la cuerda con los codos pegados al cuerpo.', 'Extiende los antebrazos hacia abajo hasta la media extensión.', 'Vuelve despacio sin separar los codos del torso.', 'Evita mover los hombros o usar impulso del tronco.']::text[], 'principiante', 'Aísla el tríceps con polea en un rango parcial, útil para ganar fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4893'),
('c743f883-d350-5221-b08c-ce1f57d0232a', 'Estiramiento de aquiles de rodillas con talón abajo', ARRAY['Arrodíllate con un pie adelantado y el talón trasero apoyado en el suelo.', 'Lleva el peso del cuerpo hacia delante sin levantar el talón.', 'Mantén el estiramiento veinte segundos respirando despacio.', 'Evita forzar el tobillo o rebotar sobre el talón.']::text[], 'principiante', 'Estira el tendón de Aquiles y el sóleo, previniendo molestias en tobillos y pantorrillas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1892'),
('fcbee8ac-a5cf-5bb3-aad2-b5ae673ee3d1', 'Estiramiento de flexor de cadera de rodillas', ARRAY['Arrodíllate con una pierna adelantada y la rodilla trasera en el suelo.', 'Lleva la cadera hacia delante y aprieta el glúteo de la pierna retrasada.', 'Mantén la posición sin arquear la zona lumbar.', 'Respira profundo y cambia de lado.']::text[], 'principiante', 'Libera la parte delantera de la cadera y el cuádriceps, aliviando la rigidez por estar sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0560'),
('8b004fe8-8df2-5382-ac2d-5d6a48467ce9', 'Empuje de cadera de rodillas', ARRAY['Arrodíllate con la espalda recta y las manos en la cintura.', 'Empuja la cadera hacia delante apretando los glúteos.', 'Mantén un segundo arriba y vuelve despacio al inicio.', 'Evita arquear la lumbar o adelantar la cabeza.']::text[], 'intermedio', 'Fortalece glúteos e isquios con una extensión de cadera que también estabiliza el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4669'),
('a8cb8c38-9d51-59d6-ad13-2bca26c660c4', 'Estiramiento del iliopsoas de rodillas', ARRAY['Colócate de rodillas con una pierna adelantada y el torso erguido.', 'Empuja la cadera hacia delante y ligeramente hacia arriba.', 'Mantén el estiramiento treinta segundos sin arquear la lumbar.', 'Cambia de lado respirando de forma relajada.']::text[], 'principiante', 'Estira el psoas y el flexor profundo de la cadera, mejorando la postura y la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6771'),
('2432644e-a89d-5900-80a0-8abde962a739', 'Sostén isométrico de bíceps de rodillas', ARRAY['Colócate de rodillas con la espalda recta y los codos pegados al cuerpo.', 'Flexiona los codos hasta unos 90 grados y mantén la posición sin moverte.', 'Aprieta el bíceps y respira de forma pausada durante todo el sostén.', 'Evita encoger los hombros o arquear la espalda para no cargar el cuello.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos manteniendo la tensión sin moverte, útil para ganar resistencia y control en la flexión.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '11792'),
('eaf34655-8f26-5018-952e-6c46e6327354', 'Sentadilla con salto desde rodillas', ARRAY['Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante.', 'Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.', 'Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas.', 'Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas.', 'Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto.', 'Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con potencia explosiva, mejorando la capacidad de salto y la fuerza reactiva de las piernas.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1420'),
('505524f3-eac4-5969-a235-b1f7bb3443a0', 'Estiramiento de dorsales de rodillas', ARRAY['Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás.', 'Extiende los brazos por encima de la cabeza y entrelaza los dedos.', 'Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo.', 'Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.', 'Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Estira dorsales y hombros para aliviar tensión acumulada y mejorar la movilidad del tren superior tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1346'),
('f7ba99e2-ff99-54b5-9e8e-083e913c7745', 'Estiramiento de dorsal de rodillas en banco', ARRAY['Apoya las manos en el borde del banco y colócate de rodillas frente a él.', 'Baja el pecho hacia el suelo mientras llevas la cadera atrás.', 'Mantén los brazos estirados y respira profundo durante el estiramiento.', 'Evita forzar el cuello; deja que la cabeza siga la línea de la espalda.']::text[], 'principiante', 'Estira dorsales y hombros apoyándote en un banco, ideal para descargar la espalda tras tirar o empujar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4559'),
('16f2a66d-a9f4-55e3-beea-f5ce55fa0717', 'Medio círculo de pierna de rodillas', ARRAY['Colócate a cuatro apoyos con las manos bajo los hombros.', 'Levanta una pierna y dibuja un semicírculo lento hacia un lado y luego al otro.', 'Mantén el abdomen firme y la espalda estable sin balancear la cadera.', 'Evita arquear la zona lumbar mientras mueves la pierna.']::text[], 'intermedio', 'Activa glúteos y core dibujando un semicírculo con la pierna, mejorando control y movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4693'),
('859b0c41-dafa-53b6-95db-e06f69e69b42', 'Estiramiento de aductores de rodillas con pierna hacia fuera', ARRAY['Colócate de rodillas y extiende una pierna hacia el lado con el pie apoyado.', 'Desplaza la cadera hacia atrás manteniendo la espalda recta.', 'Nota el estiramiento en la cara interna del muslo y respira despacio.', 'Evita rebotar o forzar más de lo que permite la cadera.']::text[], 'principiante', 'Estira aductores e ingle abriendo la pierna hacia fuera, útil para mejorar la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1898'),
('8c19e59a-9294-5e24-8ccb-168e8eba47b8', 'Estiramiento de cuello de rodillas', ARRAY['Colócate de rodillas con la espalda recta y los hombros relajados.', 'Inclina la cabeza hacia un lado llevando la oreja al hombro.', 'Ayúdate con la mano del mismo lado sin tirar con fuerza.', 'Mantén la respiración tranquila y evita girar la cabeza durante el estiramiento.']::text[], 'principiante', 'Relaja elevador de la escápula y trapecio, aliviando la tensión cervical típica de estudiar muchas horas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5058'),
('294fcf67-04aa-5214-be11-88ae8dcd0a5b', 'Estiramiento de hombro cruzando el brazo de rodillas', ARRAY['Colócate de rodillas con el torso erguido.', 'Pasa un brazo por delante del pecho y sujétalo con la mano contraria.', 'Lleva el brazo hacia ti sin elevar el hombro y mantén la posición.', 'Evita encoger el hombro o girar el tronco para forzar más.']::text[], 'principiante', 'Estira deltoides y zona alta de la espalda cruzando un brazo, ideal para descargar hombros tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1988'),
('a3b078c3-e8f4-5ab9-9367-53cbc20e39b6', 'Alcance con un brazo, rodar y elevar de rodillas', ARRAY['Colócate a cuatro apoyos con la espalda neutra.', 'Extiende un brazo hacia delante y rota el tronco abriendo el pecho.', 'Vuelve al centro y repite el movimiento de forma controlada.', 'Mantén el abdomen firme y evita hundir la zona lumbar.']::text[], 'principiante', 'Moviliza la zona alta de la espalda y el core alternando alcance y rotación, mejorando control postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3417'),
('90a87393-b4f5-5606-9148-213f2b4a5f78', 'Plancha de rodillas con toque al hombro', ARRAY['Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros.', 'Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha.', 'Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto.', 'Devuelve la mano al suelo y repite con la otra mano.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el core y los hombros mientras trabajas la estabilidad antirotación, útil para mejorar el control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3239'),
('ed9dbd95-0990-5642-808b-2e2592bb8090', 'Flexión pliométrica de rodillas', ARRAY['Colócate de rodillas con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho de forma controlada hasta cerca del suelo.', 'Empuja con fuerza para despegar las manos un instante del suelo.', 'Amortigua la caída con los codos ligeramente flexionados y evita bloquear los codos.']::text[], 'intermedio', 'Desarrolla potencia de pecho y tríceps con un empuje explosivo, mejorando la fuerza rápida del tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10882'),
('7e842c9f-43b3-5bb3-9154-34d800cda6fb', 'Pulso de glúteo de rodillas', ARRAY['Colócate a cuatro apoyos con las manos bajo los hombros.', 'Levanta una pierna flexionada manteniendo el pie en el aire.', 'Haz pulsos cortos hacia arriba sin bajar del todo la pierna.', 'Aprieta el glúteo y evita arquear la espalda o girar la cadera.']::text[], 'intermedio', 'Activa glúteos y femorales con pequeños pulsos, útil para sentir la contracción y ganar resistencia local.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5170'),
('fbdaa981-053b-5577-ade8-f911cb4cebc2', 'Flexión a postura del niño de rodillas', ARRAY['Colócate de rodillas con las manos bajo los hombros.', 'Baja el pecho flexionando los codos hasta cerca del suelo.', 'Empuja para volver arriba y lleva la cadera atrás hacia la postura del niño.', 'Estira los brazos al frente y respira antes de repetir.']::text[], 'intermedio', 'Combina empuje de pecho y tríceps con una relajación de espalda, mejorando fuerza y movilidad en un solo movimiento.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3265'),
('1b24c052-d3f8-5366-978c-c669a188658f', 'Flexiones de rodillas', ARRAY['Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante.', 'Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones.', 'Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece pectorales, tríceps y hombros con una versión más accesible que permite progresar hacia las flexiones completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3211'),
('db4ba646-63d8-551f-b8fe-3c753b835cde', 'Rotación de torso de rodillas con apertura y paso por debajo', ARRAY['Colócate a cuatro apoyos con la espalda neutra.', 'Abre un brazo hacia el techo rotando el tronco y mirando la mano.', 'Pasa ese brazo por debajo del cuerpo y lleva el hombro hacia el suelo.', 'Mantén la cadera estable y evita hundir la zona lumbar.']::text[], 'principiante', 'Moviliza la zona alta de la espalda y los oblicuos alternando apertura y paso del brazo, mejorando rotación torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '7895'),
('44a7f4a6-d52d-5945-9d67-8f18561a562e', 'Flexión rotacional de rodillas', ARRAY['Colócate en cuadrupedia con las rodillas apoyadas y las manos bajo los hombros.', 'Baja el pecho flexionando los codos hasta acercarte al suelo.', 'Al subir, gira el tronco y lleva un brazo hacia el techo.', 'Vuelve al centro y alterna el lado en cada repetición.', 'Evita hundir la zona lumbar manteniendo el abdomen firme.']::text[], 'intermedio', 'Trabaja el pecho con rotación de tronco, sumando oblicuos y core para un empuje más completo y estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3492'),
('15ce8254-288b-56fb-a550-72cee61bc123', 'Estiramiento del sartorio de rodillas', ARRAY['Arrodíllate con una pierna adelantada y el pie apoyado.', 'Lleva la cadera hacia delante sin arquear la zona lumbar.', 'Mantén la posición entre veinte y treinta segundos respirando despacio.', 'Cambia de pierna y repite el estiramiento.', 'Evita forzar si notas pinchazo en la rodilla delantera.']::text[], 'principiante', 'Estira la parte frontal del muslo y la cadera, aliviando tensión tras entrenamientos de pierna o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6770'),
('c14c7e3a-968a-53cc-8489-e8eef567a868', 'Flexión escapular de rodillas', ARRAY['Apóyate en cuadrupedia con rodillas y manos alineadas bajo los hombros.', 'Sin doblar los codos, deja caer el pecho juntando las escápulas.', 'Empuja el suelo separando las escápulas y redondeando ligeramente la espalda.', 'Realiza el movimiento lento y controlado, sin mover la cadera.', 'Evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Activa el serratus anterior y la escápula, mejorando la estabilidad del hombro y la calidad del empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4117'),
('6a722967-8351-5c64-b0d5-4fe381a047c1', 'Toque de hombro de rodillas', ARRAY['Colócate en cuadrupedia con rodillas apoyadas y manos bajo los hombros.', 'Levanta una mano y toca el hombro contrario sin mover la cadera.', 'Vuelve a apoyar y alterna el lado.', 'Mantén el abdomen apretado y la espalda recta.', 'Evita balancear el cuerpo o girar la cadera al levantar la mano.']::text[], 'intermedio', 'Refuerza el core y los oblicuos mientras estabilizas el tronco, útil para mejorar el control en planchas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4506'),
('eda6e5f5-3d8c-56d7-81cf-045404976f35', 'Flexión con toque al hombro de rodillas', ARRAY['Empieza en cuadrupedia con rodillas apoyadas y manos bajo los hombros.', 'Baja el pecho flexionando los codos y vuelve a subir.', 'Al terminar, toca el hombro contrario con una mano.', 'Alterna el toque en cada repetición manteniendo la cadera quieta.', 'Evita perder la alineación de la espalda al tocar el hombro.']::text[], 'intermedio', 'Combina empuje de pecho y control del core, mejorando fuerza y estabilidad en un solo movimiento.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4658'),
('eb56e709-b14e-5031-82b8-0a425f31647e', 'Patada lateral de rodillas', ARRAY['Colócate en cuadrupedia con rodillas apoyadas y manos bajo los hombros.', 'Levanta una pierna hacia el lado manteniendo la rodilla flexionada.', 'Sube hasta donde controles sin girar la cadera.', 'Baja despacio y repite antes de cambiar de lado.', 'Evita arquear la espalda o balancear el tronco.']::text[], 'intermedio', 'Activa glúteo medio y oblicuos, mejorando la estabilidad de cadera y el control lateral de la pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4691'),
('be0fceed-a4c1-5d9f-a86d-95d1a2cfead7', 'Curl femoral a una pierna de rodillas', ARRAY['Arrodíllate con el tronco recto y las manos en la cintura.', 'Inclínate ligeramente hacia delante manteniendo el abdomen firme.', 'Flexiona una rodilla llevando el talón hacia el glúteo.', 'Baja despacio y repite antes de cambiar de pierna.', 'Evita compensar arqueando la zona lumbar.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos con control, útil para prevenir desequilibrios entre piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6748'),
('9501acea-8857-579b-a943-3a0a456c21e0', 'Flexión escalonada de rodillas', ARRAY['Colócate en cuadrupedia con rodillas apoyadas y una mano algo adelantada.', 'Baja el pecho flexionando los codos sin perder la línea del tronco.', 'Empuja el suelo para volver arriba de forma controlada.', 'Cambia la mano adelantada al terminar la serie.', 'Evita que la cadera se hunda o se eleve demasiado.']::text[], 'intermedio', 'Trabaja el pecho con una mano adelantada, aumentando la dificultad y el control del empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5278'),
('6d1f695c-9163-5d3a-b69b-ac7740f25165', 'Patada trasera con pierna recta de rodillas', ARRAY['En cuadrupedia con rodillas apoyadas, mantén la espalda recta.', 'Extiende una pierna hacia atrás sin subirla por encima de la cadera.', 'Aprieta el glúteo arriba y baja despacio.', 'Alterna las piernas manteniendo el abdomen firme.', 'Evita arquear la lumbar al levantar la pierna.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales, mejorando la extensión de cadera y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4772'),
('8e701fa1-074b-5a6d-b97b-ac65ab6f273a', 'Patada lateral con pierna recta de rodillas', ARRAY['Colócate en cuadrupedia con rodillas apoyadas y manos bajo los hombros.', 'Extiende una pierna hacia el lado manteniéndola recta.', 'Sube hasta donde controles sin inclinar el tronco.', 'Baja despacio y repite antes de cambiar de lado.', 'Evita girar la cadera o apoyar el peso en un solo brazo.']::text[], 'intermedio', 'Fortalece abductores y glúteo medio, mejorando la estabilidad lateral de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4896'),
('cb09bd44-ab7a-55e8-9ed9-449c749c9c0c', 'Movilidad de columna torácica de rodillas', ARRAY['Arrodíllate y apoya una mano en el suelo.', 'Coloca la otra mano detrás de la cabeza.', 'Gira el codo hacia el techo abriendo el pecho.', 'Vuelve despacio y repite antes de cambiar de lado.', 'Evita mover la cadera; la rotación sale de la espalda alta.']::text[], 'principiante', 'Mejora la rotación de la espalda alta, aliviando rigidez y preparando el torso para entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3526'),
('9061379c-56f0-528a-b253-2b3c7edb6cea', 'Estiramiento de movilidad de columna torácica de rodillas', ARRAY['Arrodíllate con una mano apoyada en el suelo.', 'Lleva la otra mano detrás de la cabeza y abre el codo.', 'Mantén el estiramiento unos segundos respirando profundo.', 'Vuelve al centro y cambia de lado.', 'Evita forzar la rotación si notas molestia en la lumbar.']::text[], 'principiante', 'Gana rotación y flexibilidad en la espalda alta, reduciendo tensión en cuello y hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3540'),
('d3e14d24-7d29-58ec-bac2-c5ab74f37e07', 'Rotación torácica de rodillas', ARRAY['En cuadrupedia con rodillas apoyadas, coloca una mano en la nuca.', 'Gira el codo hacia el techo sin mover la cadera.', 'Baja el codo hacia el suelo buscando el brazo contrario.', 'Repite de forma lenta y alterna los lados.', 'Evita compensar girando la pelvis o encogiendo el hombro.']::text[], 'principiante', 'Moviliza la columna dorsal y los oblicuos, mejorando la rotación del tronco para gestos deportivos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8052'),
('95214b46-f67a-577b-85a2-fb01ccef6f5d', 'Salto al cajón desde rodillas', ARRAY['Arrodíllate frente a un cajón bajo y coloca los brazos atrás.', 'Impulsa con las caderas y los brazos para saltar hacia delante.', 'Aterriza sobre el cajón con las rodillas flexionadas.', 'Baja con control y prepara la siguiente repetición.', 'Evita saltar si el cajón es demasiado alto o inestable.']::text[], 'intermedio', 'Potencia piernas y glúteos con un salto explosivo, mejorando la fuerza y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10743'),
('4b191a29-0784-53fa-a7de-1c9c1c4b821f', 'Sentadilla de rodillas a de pie', ARRAY['Arrodíllate con el torso erguido y los pies apoyados por el empeine.', 'Lleva el peso a un pie y empuja con la pierna para ponerte de pie.', 'Mantén el pecho alto y el abdomen activo durante todo el movimiento.', 'Baja de forma controlada hasta la posición de rodillas.', 'Evita lanzar el cuerpo hacia delante; usa la fuerza de la pierna.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y core, y mejora la fuerza para levantarte del suelo con control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8533'),
('ea89d544-8440-5fe7-aaf9-7eb4781470a1', 'Estiramiento de flexores de muñeca de rodillas', ARRAY['Colócate de rodillas con las palmas en el suelo y los dedos hacia las rodillas.', 'Mantén los codos rectos y lleva el peso suavemente hacia atrás.', 'Nota el estiramiento en el antebrazo sin dolor agudo.', 'Respira despacio y mantén la posición entre veinte y treinta segundos.', 'Evita cargar demasiado peso sobre las muñecas si notas molestia.']::text[], 'principiante', 'Estira los flexores del antebrazo y la muñeca, aliviando tensión tras el trabajo de agarre.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0561'),
('6656c400-c2a3-5e99-b19e-45e70bb17447', 'Flexión sobre nudillos', ARRAY['Apoya los nudillos en el suelo con las muñecas alineadas y el cuerpo recto.', 'Baja el pecho flexionando los codos cerca del torso.', 'Empuja para volver arriba manteniendo el core activo.', 'Respira al subir y evita que la cadera se hunda.', 'No dejes que los codos se abran en exceso hacia los lados.']::text[], 'intermedio', 'Fortalece pectorales, tríceps y muñecas, y mejora la estabilidad del puño en el apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4192'),
('136fc8e3-4a0c-56e7-8cc9-3f1ce3f0cd4d', 'Fondos coreanos', ARRAY['Colócate entre dos barras paralelas con los brazos extendidos sosteniendo el peso de tu cuerpo.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con un rango amplio que exige gran control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3288'),
('f656eb79-213b-507f-a8d5-8a22356bb0f0', 'Ejercicio en L', ARRAY['Coloca cuatro marcas formando una L en el suelo.', 'Corre hacia la primera marca y toca el suelo con la mano.', 'Gira y desplázate a la siguiente marca manteniendo el ritmo.', 'Mantén las rodillas ligeramente flexionadas y el torso estable.', 'Evita cruzar los pies de forma descuidada para no tropezar.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la coordinación con cambios rápidos de dirección y apoyo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5971'),
('12913214-4c1a-532b-b3e3-e398037f4282', 'L-sit', ARRAY['Siéntate con las manos apoyadas y empuja para elevar la cadera.', 'Extiende las piernas formando una L con el torso.', 'Mantén los hombros bajos y el abdomen apretado.', 'Respira de forma constante sin perder la posición.', 'Evita encoger los hombros o redondear la espalda.']::text[], 'intermedio', 'Isométrico que fortalece el abdomen, los flexores de cadera y los tríceps manteniendo las piernas elevadas.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1402'),
('2a6de3cf-9abb-5c1f-b190-28c4809f5f31', 'Elevación de piernas en L-sit', ARRAY['Adopta la posición de L-sit con los brazos extendidos.', 'Baja las piernas de forma controlada sin tocar el suelo.', 'Vuelve a subirlas manteniendo el core activo.', 'Respira al elevar y evita balancear el torso.', 'No dejes caer los hombros hacia las orejas.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera elevando las piernas desde una posición de L-sit.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10951'),
('a58bc126-acce-5ab4-88b9-f02ecd4ed5ed', 'Trepa de cuerda en L-sit', ARRAY['Sujeta la cuerda con las manos y eleva las piernas en L.', 'Tira con un brazo mientras el otro sube el agarre.', 'Mantén el abdomen apretado y las piernas extendidas.', 'Sube de forma alterna y controlada sin balancearte.', 'Evita perder la posición de L al tirar con fuerza.']::text[], 'intermedio', 'Trabaja dorsales, bíceps y antebrazos mientras el core mantiene las piernas en L durante la subida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10731'),
('855b8626-aaa5-54e8-9d67-c8f9788b5075', 'Ejercicio de escalera', ARRAY['Coloca la escalera en el suelo y sitúate al inicio.', 'Pisa cada hueco con un pie de forma rápida y ligera.', 'Mantén las rodillas flexionadas y el torso erguido.', 'Coordina los brazos con el ritmo de los pies.', 'Evita mirar solo al suelo; mantén la cabeza alta.']::text[], 'intermedio', 'Mejora la coordinación, la velocidad de pies y la capacidad cardiovascular con pasos rápidos en escalera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5972'),
('c1062362-7a85-57b6-837e-cd3d93e7c399', 'Landmine 180', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho.', 'Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha.', 'Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo.', 'Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con rotación controlada usando una barra anclada en landmine.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0562'),
('fa6bf746-a8f8-589e-bd36-4607b1d4638d', 'Press landmine con banda elástica', ARRAY['Sujeta la barra con una mano y coloca la banda para resistir el empuje.', 'Empuja la barra hacia delante y arriba extendiendo el brazo.', 'Mantén el core activo y evita rotar el torso.', 'Vuelve de forma controlada a la posición inicial.', 'No bloquees la respiración durante el empuje.']::text[], 'intermedio', 'Fortalece hombros, tríceps y core con un empuje diagonal que añade tensión de banda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10056'),
('1c8dfb58-5be9-5201-8b69-7e57241f96e8', 'Sentadilla cosaca en landmine', ARRAY['Sujeta la barra con ambas manos frente al pecho.', 'Da un paso amplio hacia un lado y flexiona esa rodilla.', 'Mantén la otra pierna extendida y el pie apoyado.', 'Empuja para volver al centro con control.', 'Evita que la rodilla flexionada se vaya hacia dentro.']::text[], 'intermedio', 'Trabaja glúteos, cuádriceps y aductores con una sentadilla lateral que mejora la movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10052'),
('e60341f8-a1c9-52b4-a30b-97bf72be371a', 'Peso muerto con landmine', ARRAY['Sujeta la barra con ambas manos y los pies a la anchura de la cadera.', 'Lleva la cadera atrás manteniendo la espalda recta.', 'Baja la barra hasta media espinilla sin redondear la espalda.', 'Empuja con los talones y extiende la cadera para subir.', 'Evita tirar con la espalda en lugar de con las piernas.']::text[], 'intermedio', 'Fortalece glúteos, isquiotibiales y espalda baja con un patrón de bisagra seguro y guiado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7883'),
('cc71738b-78de-54e7-9ca1-1021d06c3dc8', 'Sentadilla hack en landmine', ARRAY['Sujeta la barra con ambas manos y colócala frente al pecho.', 'Baja flexionando las rodillas con el torso erguido.', 'Mantén los talones apoyados y el core activo.', 'Empuja para subir sin perder la alineación de rodillas.', 'Evita levantar los talones o inclinarte demasiado.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con una sentadilla guiada que permite gran profundidad y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5628'),
('069ca712-455c-5ff6-848b-2174568db49d', 'Press de hombros con una rodilla en el suelo en landmine', ARRAY['Colócate con una rodilla en el suelo y sujeta la barra con una mano.', 'Empuja la barra hacia arriba y ligeramente adelante.', 'Mantén el core activo y evita arquear la espalda.', 'Baja la barra de forma controlada hasta el hombro.', 'No rotes el torso al empujar.']::text[], 'intermedio', 'Fortalece hombros, tríceps y core con un empuje unilateral que exige estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9695'),
('14986c66-e8ef-53f6-a051-d915487876b4', 'Landmine 180 de rodillas', ARRAY['Colócate de rodillas frente al landmine con el extremo de la barra sujeto con ambas manos.', 'Gira el torso llevando la barra hacia un lado manteniendo los brazos casi rectos.', 'Controla el movimiento de vuelta al centro y repite hacia el otro lado.', 'Evita arquear la zona lumbar y acompaña la rotación con la cadera.']::text[], 'intermedio', 'Trabaja el core y los oblicuos con rotación controlada, mejorando la estabilidad y la fuerza rotacional del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11092'),
('ad1a053d-3fb5-502b-a773-2fd9d94b7d47', 'Press de hombros a un brazo de rodillas con landmine', ARRAY['Arrodíllate de lado al landmine y sujeta la barra con una mano a la altura del hombro.', 'Empuja la barra hacia arriba y ligeramente adelante hasta extender el brazo.', 'Baja controlando el movimiento sin dejar caer la barra.', 'Mantén el abdomen firme y evita inclinarte hacia el lado contrario.']::text[], 'intermedio', 'Fortalece el hombro y el tríceps de forma unilateral, exigiendo al core mantener el tronco estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3525'),
('db14a47a-ae71-5c26-8b5a-76e0b4bf47ff', 'Thruster de rodillas en landmine', ARRAY['Arrodíllate frente al landmine sujetando la barra a la altura del pecho.', 'Baja la cadera hacia los talones y luego extiende con impulso.', 'Aprovecha ese impulso para empujar la barra por encima de la cabeza.', 'Controla la bajada y evita perder la alineación del tronco.']::text[], 'intermedio', 'Combina empuje de hombros y extensión de cadera para un trabajo global de fuerza y potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5282'),
('1fc00ec0-78d2-5db8-bec3-24e1f4e0b3b8', 'Remo inclinado a un brazo en banco con landmine', ARRAY['Apoya una mano y una rodilla en el banco con el torso paralelo al suelo.', 'Sujeta la barra con la mano libre y tira de ella hacia la cadera.', 'Junta la escápula al final del recorrido y baja controlando.', 'Evita rotar el tronco o tirar con el bíceps en exceso.']::text[], 'intermedio', 'Trabaja la espalda y el dorsal de forma unilateral con apoyo, reduciendo la carga lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4039'),
('ab1cbf28-48ae-5818-b4ab-fa38b06a2490', 'Remo inclinado a un brazo con landmine', ARRAY['Con los pies separados, inclina el torso y sujeta la barra con una mano.', 'Tira de la barra hacia la cadera llevando el codo atrás.', 'Aprieta la escápula arriba y baja de forma controlada.', 'Mantén la espalda neutra y evita redondearla o girar el tronco.']::text[], 'intermedio', 'Fortalece dorsal y espalda alta de forma unilateral, implicando también el core para estabilizar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4038'),
('e696b351-50bc-5dd9-9986-17ecdad984e8', 'Peso muerto rumano a una pierna en landmine', ARRAY['Sujeta la barra con una mano y apoya el peso en la pierna contraria.', 'Inclina el torso llevando la pierna libre atrás mientras bajas la barra.', 'Baja hasta notar el estiramiento en el isquiotibial y vuelve arriba.', 'Mantén la cadera nivelada y evita redondear la espalda.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos a una pierna, mejorando el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5307'),
('23875607-fa9e-55e4-b955-1d7de8ad335d', 'Zancada atrás con landmine sobre la cabeza', ARRAY['Sujeta la barra con ambas manos por encima de la cabeza con los brazos extendidos.', 'Da un paso atrás y baja la rodilla hacia el suelo con control.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén la barra estable arriba y evita arquear la zona lumbar.']::text[], 'intermedio', 'Combina fuerza de piernas y estabilidad de hombros con la barra elevada, exigiendo mucho al core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7627'),
('0b75d218-ac48-586e-bb44-bbdaeda4feee', 'Press de hombros a un brazo con landmine y banda elástica', ARRAY['Coloca la banda en el landmine y sujeta el extremo junto con la barra.', 'Empuja la barra hacia arriba hasta extender el brazo.', 'Baja controlando la tensión de la banda.', 'Mantén el core firme y evita compensar con la espalda.']::text[], 'intermedio', 'Añade resistencia variable al press unilateral, aumentando la tensión en la parte alta del recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4202'),
('5cb96571-217c-55e1-b3a5-ff9c1ffc49bd', 'Peso muerto rumano con landmine', ARRAY['Sujeta la barra con ambas manos frente a los muslos.', 'Empuja la cadera atrás bajando la barra pegada a las piernas.', 'Baja hasta notar el estiramiento y vuelve extendiendo la cadera.', 'Mantén la espalda neutra y evita flexionar las rodillas en exceso.']::text[], 'intermedio', 'Fortalece isquiotibiales, glúteos y espalda baja con un patrón de bisagra de cadera seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4113'),
('fd7754ad-8adb-531d-9735-446e1a11fcfb', 'Push press a un brazo en landmine', ARRAY['Sujeta la barra con una mano a la altura del hombro.', 'Flexiona ligeramente las rodillas y extiende con impulso.', 'Empuja la barra por encima de la cabeza hasta extender el brazo.', 'Controla la bajada y evita arquear la espalda al empujar.']::text[], 'intermedio', 'Desarrolla potencia de hombros y tríceps usando un pequeño impulso de piernas y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10190'),
('37d6687f-79a7-5f06-9428-3d5b01eed97b', 'Hip thrust a una pierna con landmine', ARRAY['Apoya la espalda alta en un banco y coloca la barra sobre la cadera.', 'Apoya un pie en el suelo y eleva la cadera hasta alinear el cuerpo.', 'Aprieta el glúteo arriba y baja controlando el movimiento.', 'Evita hiperextender la lumbar y mantén la pelvis nivelada.']::text[], 'intermedio', 'Aísla el glúteo de forma unilateral, mejorando fuerza y estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6546'),
('6e689666-a9c4-5be6-bd8b-94279ffb8ed3', 'Peso muerto rumano a una pierna con landmine', ARRAY['Sujeta la barra con una mano y apoya el peso en la pierna contraria.', 'Inclina el torso y lleva la pierna libre atrás mientras bajas la barra.', 'Baja hasta notar el estiramiento y vuelve arriba con control.', 'Mantén la cadera nivelada y evita redondear la espalda.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos a una pierna, mejorando equilibrio y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3918'),
('73218767-35ae-5e69-985a-27bd70f56c21', 'Sentadilla con landmine', ARRAY['Sujeta la barra a la altura del pecho con ambas manos.', 'Baja la cadera flexionando rodillas y cadera con el torso erguido.', 'Baja hasta donde controles sin perder la espalda neutra.', 'Empuja con los talones para subir y evita que las rodillas se junten.']::text[], 'intermedio', 'Fortalece piernas y glúteos con una sentadilla frontal que exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7626'),
('4c0adf6e-cfe0-560d-ac21-679e2c737a17', 'Salto de sentadilla en landmine', ARRAY['Sujeta la barra a la altura del pecho y adopta una postura atlética.', 'Baja en sentadilla y salta de forma explosiva.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto.', 'Evita aterrizar con las piernas rígidas o perder el control del tronco.']::text[], 'intermedio', 'Ejercicio pliométrico que desarrolla potencia de piernas y explosividad con carga ligera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10675'),
('7997a723-462d-5c4b-9e1c-1378a88cf183', 'Levantarse con rodilla alta en landmine', ARRAY['Arrodíllate frente al landmine sujetando la barra con ambas manos.', 'Apoya un pie adelante y empuja para levantarte.', 'Sube llevando la rodilla contraria alta y mantén el control.', 'Baja de forma controlada y evita perder el equilibrio del tronco.']::text[], 'intermedio', 'Trabaja piernas y core en un patrón de levantarse unilateral con control y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3529'),
('2985b2bd-81ad-5290-8ef0-8bde227ec2ca', 'Sentadilla sumo con landmine', ARRAY['Coloca el extremo de la barra en el landmine y sujétala con ambas manos a la altura del pecho.', 'Abre los pies más allá del ancho de los hombros con las puntas hacia fuera y saca pecho.', 'Baja flexionando rodillas y caderas manteniendo la espalda recta y las rodillas alineadas con los pies.', 'Empuja con los talones para subir y exhala al final del recorrido.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Trabaja glúteos, cuádriceps y aductores; mejora la fuerza de piernas y la estabilidad del core en posición abierta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4090'),
('38d71c0d-c28c-5b4b-8ed8-a0277eee4e48', 'Flexión lateral de rodillas', ARRAY['Arrodíllate con las rodillas a la anchura de las caderas y la espalda recta.', 'Eleva un brazo por encima de la cabeza y llévalo hacia el lado contrario inclinando el tronco.', 'Mantén la cadera estable y siente el estiramiento en el costado sin rebotar.', 'Respira profundo y aguanta entre veinte y treinta segundos antes de cambiar de lado.', 'Evita girar el tronco o forzar la inclinación más allá de lo cómodo.']::text[], 'principiante', 'Estira la cadena lateral del tronco y la espalda, aliviando tensión en oblicuos y dorsales tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2124'),
('0f906415-8046-5926-8980-6e3d700be7db', 'Salto lateral', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y el peso en una pierna.', 'Impúlsate lateralmente y aterriza sobre la pierna contraria con la rodilla blanda.', 'Absorbe el impacto flexionando la cadera y mantén el tronco estable.', 'Realiza saltos continuos controlando la dirección y la respiración.', 'Evita aterrizar con la rodilla rígida o que se meta hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia en glúteos y mejora la estabilidad de rodilla y tobillo en desplazamientos laterales.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3095'),
('4b86efb1-0c83-5723-8dee-9242bfd770b8', 'Salto lateral al cajón', ARRAY['Sitúate de pie junto al cajón con los pies a la anchura de las caderas.', 'Flexiona rodillas y caderas y salta lateralmente para subir al cajón.', 'Aterriza con ambos pies y las rodillas alineadas, absorbiendo el impacto.', 'Baja con control y repite el salto hacia el otro lado.', 'Evita saltar si no dominas la altura o aterrizar con la espalda curvada.']::text[], 'intermedio', 'Mejora la potencia de cuádriceps y glúteos con un salto lateral explosivo sobre una superficie elevada.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0564'),
('72182667-16c7-59e2-8be4-e650bc52bbd8', 'Salto lateral de valla', ARRAY['Colócate de pie junto a la valla con las rodillas ligeramente flexionadas.', 'Salta lateralmente por encima de la valla con un impulso rápido de tobillos y caderas.', 'Aterriza suavemente con ambos pies y las rodillas alineadas.', 'Encadena los saltos manteniendo un ritmo constante y el core activo.', 'Evita golpear la valla o aterrizar con los pies juntos y rígidos.']::text[], 'intermedio', 'Entrena la potencia y la reactividad de piernas con saltos laterales sobre una valla baja.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6958'),
('bfede3ea-860a-5cfd-bc1f-c4b050dcd8a2', 'Ejercicio lateral de escalera', ARRAY['Coloca la escalera en el suelo y sitúate a un extremo con las rodillas ligeramente flexionadas.', 'Desplázate lateralmente pisando cada hueco con un pie y luego con el otro.', 'Mantén el pecho alto y los brazos acompañando el movimiento.', 'Aumenta la velocidad progresivamente sin perder el control.', 'Evita cruzar los pies o mirar al suelo durante el recorrido.']::text[], 'intermedio', 'Activa abductores y mejora la coordinación y agilidad en desplazamientos laterales rápidos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5973'),
('a79ac63c-56e8-507c-aac0-2094106817f4', 'Elevación lateral de brazos', ARRAY['De pie con una mancuerna en cada mano y los brazos junto al cuerpo.', 'Eleva los brazos lateralmente hasta la altura de los hombros con los codos ligeramente flexionados.', 'Controla el descenso en dos o tres segundos y exhala al subir.', 'Mantén los hombros bajos y evita encogerlos hacia las orejas.', 'No balancees el tronco ni uses impulso para subir el peso.']::text[], 'intermedio', 'Fortalece el deltoides medio y mejora la técnica de elevación para hombros más estables y definidos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4967'),
('96618241-2612-5db0-9d60-89722a85bfcd', 'Paso lateral rápido', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y el peso en la parte delantera del pie.', 'Da pasos laterales rápidos manteniendo los pies a la anchura de las caderas.', 'Mantén el tronco erguido y los brazos en movimiento.', 'Aumenta la velocidad sin perder el control del aterrizaje.', 'Evita cruzar los pies o arrastrarlos por el suelo.']::text[], 'intermedio', 'Mejora la reactividad de tobillos y pantorrillas con desplazamientos laterales rápidos y controlados.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0565'),
('ec370cf1-f54e-5650-9b45-8c463525b052', 'Estiramiento lateral tumbado', ARRAY['Túmbate de lado con las piernas ligeramente flexionadas y el brazo inferior extendido.', 'Eleva el brazo superior por encima de la cabeza y alárgalo hacia el lado contrario.', 'Siente el estiramiento en el costado sin levantar la cadera del suelo.', 'Respira lento y mantén entre veinte y treinta segundos por lado.', 'Evita arquear la espalda o forzar el estiramiento hasta sentir dolor.']::text[], 'principiante', 'Relaja la musculatura lateral del tronco y la espalda, mejorando la movilidad de oblicuos y dorsales.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2125'),
('76c2e92c-a928-5b8a-b9fd-922e93606eab', 'Salto lateral al cajón con giro', ARRAY['Sitúate de pie junto al cajón con las rodillas ligeramente flexionadas.', 'Salta lateralmente girando el tronco para aterrizar de frente sobre el cajón.', 'Aterriza con ambos pies y las rodillas alineadas, absorbiendo el impacto.', 'Baja con control y repite el salto hacia el lado contrario.', 'Evita girar solo con la espalda o aterrizar con los pies desalineados.']::text[], 'intermedio', 'Aumenta la potencia de piernas y la rotación del core con un salto lateral con giro sobre el cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0567'),
('f25fba02-61ae-5b98-81f8-fe9d5b6444d5', 'Flexión con desplazamiento lateral', ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho flexionando los codos y empuja para subir.', 'Desplázate lateralmente con una mano y luego con la otra manteniendo el core activo.', 'Realiza otra flexión y continúa el desplazamiento alternando lados.', 'Evita que la cadera se hunda o que los codos se abran en exceso.']::text[], 'intermedio', 'Fortalece pecho, tríceps y core mientras trabajas la estabilidad en desplazamientos laterales.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4858'),
('08d3a6c9-2817-509a-a441-c6fad03eb92c', 'Flexión desde el suelo', ARRAY['Túmbate boca abajo con las manos bajo los hombros y las piernas extendidas.', 'Empuja el suelo para elevar el cuerpo manteniendo una línea recta de cabeza a talones.', 'Baja el pecho flexionando los codos hasta casi tocar el suelo.', 'Empuja de nuevo exhalando y manteniendo el core activo.', 'Evita que la cadera se hunda o que la cabeza caiga hacia delante.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros mejorando la fuerza del tren superior y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5997'),
('7a86192c-bb20-592b-a283-9b425d847297', 'Estiramiento inclinado hacia adelante', ARRAY['De pie con los pies a la anchura de las caderas, flexiona ligeramente las rodillas.', 'Inclina el tronco hacia delante manteniendo la espalda recta y los brazos relajados.', 'Baja hasta sentir el estiramiento en glúteos e isquiotibiales sin rebotar.', 'Respira profundo y mantén entre veinte y treinta segundos.', 'Evita redondear la espalda o forzar la bajada más allá de lo cómodo.']::text[], 'principiante', 'Estira glúteos, isquiotibiales y zona lumbar, aliviando tensión tras sesiones de fuerza o carrera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5695'),
('4b303f6b-51ee-5bf1-8398-fccf94df4305', 'Planche inclinada', ARRAY['Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto.', 'Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos.', 'Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante.', 'Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Isométrico que fortalece core, hombros y pecho mientras prepara el camino hacia la planche completa.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3300'),
('3068fd8f-c129-5233-b2e9-2ecc163b297c', 'Estiramiento de abductores inclinado', ARRAY['De pie, apoya una mano en una pared o superficie estable para mantener el equilibrio.', 'Cruza una pierna por delante de la otra y flexiona ligeramente la rodilla de apoyo.', 'Inclina el tronco hacia el lado contrario hasta sentir el estiramiento en la cadera.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita girar el tronco o forzar la cadera más allá de lo cómodo.']::text[], 'principiante', 'Estira abductores y glúteos mejorando la movilidad de cadera y aliviando tensión en la zona lateral.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1880'),
('a39b5a91-1c61-5d28-bc9c-0959a356c5cc', 'Estiramiento de aquiles inclinado con talón atrás', ARRAY['Apoya las manos en una pared y coloca un pie delante y otro detrás con el talón apoyado en el suelo.', 'Inclina el cuerpo hacia delante flexionando la rodilla delantera sin despegar el talón trasero.', 'Mantén la rodilla trasera estirada y nota el estiramiento en el gemelo durante 20 o 30 segundos.', 'Respira de forma pausada y evita rebotar o forzar el tobillo más allá de lo cómodo.']::text[], 'principiante', 'Estira el gemelo y el sóleo para mejorar la flexibilidad del tobillo y prevenir molestias en la parte baja de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2104'),
('30d851eb-f573-5073-8348-0ca2d06b272e', 'Gancho de izquierda', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla.', 'Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe.', 'Gira el torso y activa los músculos del core para generar potencia en el golpe.', 'Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la potencia del hombro y la coordinación del tren superior mediante un golpe de boxeo con rotación de cadera.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2271'),
('2f4ad0d6-523f-551c-9129-b4719bf8a85f', 'Dominada en anillas asistida con piernas', ARRAY['Cuelga de las anillas con agarre prono y apoya las puntas de los pies en el suelo o en un apoyo estable.', 'Tira del cuerpo hacia arriba ayudándote lo justo con las piernas hasta acercar el pecho a las anillas.', 'Baja de forma controlada hasta estirar los brazos del todo sin dejarte caer.', 'Evita encoger los hombros y mantén el abdomen activo durante todo el recorrido.']::text[], 'intermedio', 'Fortalece la espalda y los brazos con ayuda de las piernas, ideal para progresar hacia dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4920'),
('2f64559d-6018-5fe9-a243-b3c4cdb6f1b3', 'Puente lateral con pierna en banco', ARRAY['Colócate de lado con el codo apoyado bajo el hombro y la pierna de arriba sobre un banco.', 'Eleva la cadera hasta formar una línea recta entre hombro, cadera y pie de apoyo.', 'Mantén la posición apretando el abdomen y respirando con normalidad.', 'Evita dejar caer la cadera o adelantar el hombro para no perder la alineación.']::text[], 'intermedio', 'Trabaja la zona lateral del abdomen y estabiliza la cadera para mejorar la firmeza del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0568'),
('e4431990-48f4-5193-83e0-389bfb9a14cb', 'Curl de pierna en balón de estabilidad', ARRAY['Túmbate boca arriba con los talones apoyados sobre el balón y las piernas estiradas.', 'Eleva la cadera y acerca el balón hacia los glúteos flexionando las rodillas.', 'Estira las piernas de forma controlada sin dejar caer la cadera al suelo.', 'Mantén el abdomen apretado y evita arquear la zona lumbar durante el movimiento.']::text[], 'principiante', 'Refuerza los isquiotibiales y el control del core usando el balón para un movimiento más estable y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0569'),
('72f9abf5-eb0a-5214-ac0d-da90668c1511', 'Abdominal con extensión de piernas en balón', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas flexionadas sobre el balón.', 'Eleva ligeramente el tronco mientras estiras las piernas empujando el balón hacia delante.', 'Recoge las piernas y baja el tronco de forma controlada sin tirar del cuello.', 'Respira exhalando al estirar y evita despegar la zona lumbar del suelo.']::text[], 'principiante', 'Activa el abdomen y los flexores de cadera coordinando una extensión de piernas sobre el balón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3606'),
('9b18e5a3-0b0c-55e9-808a-972e74388732', 'Patada frontal de pierna', ARRAY['De pie con el abdomen activo, eleva una pierna estirada hacia delante hasta donde controles.', 'Mantén la espalda recta y el pie de apoyo firme sin bloquear la rodilla.', 'Baja la pierna despacio y alterna, exhalando al subir y controlando la bajada.', 'Evita arquear la zona lumbar o impulsarte con el tronco para subir más.']::text[], 'principiante', 'Mejora la movilidad de la cadera y la fuerza del abdomen al elevar la pierna de forma controlada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4616'),
('28039180-5135-57d8-8536-7bae4a06a4cb', 'Prueba de longitud de piernas', ARRAY['Túmbate boca arriba con las piernas estiradas y la pelvis neutra.', 'Lleva una rodilla al pecho sin despegar la zona lumbar del suelo.', 'Observa hasta dónde llega y compara con el otro lado sin forzar.', 'Evita compensar girando la cadera o levantando la espalda baja.']::text[], 'principiante', 'Valora la movilidad y simetría de cadera y glúteos para detectar diferencias entre ambos lados.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6789'),
('cc8b6af3-a5e6-56d5-ba22-a5fbf5e8bc06', 'Plancha frontal con rodilla al pecho', ARRAY['Colócate en plancha frontal con codos bajo los hombros y cuerpo alineado.', 'Lleva una rodilla hacia el pecho sin mover la cadera ni la espalda.', 'Vuelve a la posición inicial y alterna las piernas a ritmo controlado.', 'Mantén el abdomen apretado y evita hundir la zona lumbar o subir la cadera.']::text[], 'intermedio', 'Combina isometría y control dinámico del abdomen para ganar estabilidad y fuerza en el core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3982'),
('916863a0-17fa-55df-9d8b-44231dca9f12', 'Puente de glúteos con pierna sobre la rodilla', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado, y el otro tobillo sobre esa rodilla.', 'Empuja con el pie de apoyo y eleva la cadera hasta alinear tronco y muslo.', 'Aprieta el glúteo arriba y baja de forma controlada sin dejar caer la cadera.', 'Evita arquear la zona lumbar y mantén la pelvis nivelada durante todo el movimiento.']::text[], 'intermedio', 'Activa glúteos y core con un apoyo unilateral que exige más estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4690'),
('e8f1a11b-2ec3-54c8-beb0-cd636b3e2172', 'Leg pull', ARRAY['Siéntate con las piernas estiradas y las manos apoyadas detrás del cuerpo.', 'Eleva la cadera y las piernas formando una línea recta desde los hombros hasta los pies.', 'Mantén la posición apretando el abdomen y respirando de forma pausada.', 'Evita hundir la cadera o bloquear los codos en exceso.']::text[], 'intermedio', 'Ejercicio de pilates que fortalece el abdomen y los hombros mientras estabilizas la cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2849'),
('e2c41dd9-403e-5114-ac9b-d50bf276fda4', 'Leg pull frontal con apoyo', ARRAY['Colócate en plancha frontal con antebrazos o manos apoyados y cuerpo alineado.', 'Activa glúteos y abdomen para mantener la cadera estable.', 'Mantén la posición el tiempo indicado respirando con normalidad.', 'Evita subir la cadera o dejar caer la zona lumbar.']::text[], 'intermedio', 'Versión apoyada del leg pull que refuerza abdomen, hombros y glúteos con más control.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2874'),
('885af46a-c0e5-5b75-9429-9bd5abaec717', 'Jalón de piernas en banco plano', ARRAY['Siéntate en un banco plano con las piernas extendidas rectas hacia adelante.', 'Coloca las manos en el banco junto a las caderas para mayor apoyo.', 'Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera, mejorando el control del core y la estabilidad en posición tumbada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0570'),
('3650de74-99f5-5862-b137-47ad398a3adf', 'Leg pull lateral', ARRAY['Siéntate de lado con una mano apoyada y las piernas estiradas.', 'Eleva la cadera hasta formar una línea recta entre hombro, cadera y pies.', 'Mantén la posición apretando el costado y respirando de forma pausada.', 'Evita dejar caer la cadera o girar el tronco hacia el suelo.']::text[], 'intermedio', 'Trabaja la zona lateral del abdomen y la estabilidad de cadera con una variante lateral de pilates.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2848'),
('6e5e99a5-cb36-57c1-b11a-e6db404dd8f3', 'Elevación de pierna con rodilla flexionada', ARRAY['Túmbate boca arriba con las manos a los lados y las rodillas flexionadas.', 'Eleva las piernas hasta que los muslos queden perpendiculares al suelo.', 'Baja de forma controlada sin despegar la zona lumbar del suelo.', 'Exhala al subir y evita impulsarte o balancear las piernas.']::text[], 'intermedio', 'Fortalece el abdomen bajo y los flexores de cadera con un movimiento más seguro y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2850'),
('f21ec3f1-a716-5836-8cde-fc2849750a26', 'Bandera del dragón con elevación de piernas', ARRAY['Túmbate boca arriba y agarra un soporte fijo detrás de la cabeza con los brazos extendidos.', 'Eleva el cuerpo y las piernas hasta formar una línea recta apoyándote solo en los hombros.', 'Sube y baja las piernas juntas sin perder la tensión del abdomen.', 'Exhala al elevar las piernas e inhala al bajarlas con control.', 'Evita arquear la zona lumbar: mantén las costillas hacia abajo durante todo el recorrido.']::text[], 'avanzado', 'Trabaja el abdomen y el core en bloque, además de dorsales y flexores de cadera, mejorando el control corporal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4058'),
('390640e6-034b-5524-86bf-4d93456dd86b', 'Elevación de piernas con elevación de cadera', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Sube las piernas hasta la vertical manteniendo la zona lumbar pegada al suelo.', 'Eleva la cadera despegando la pelvis y aprieta los glúteos arriba.', 'Baja la cadera y luego las piernas con control, exhalando en el esfuerzo.', 'No dejes caer las piernas de golpe ni arquees la espalda al bajar.']::text[], 'intermedio', 'Activa el abdomen bajo y los flexores de cadera, sumando glúteos al elevar la pelvis para un core más fuerte.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1852'),
('4d7ab4e8-638d-5069-b711-92fe1bfd4855', 'Elevación de piernas con elevación de cadera y cabeza arriba', ARRAY['Túmbate boca arriba y eleva ligeramente la cabeza y los hombros del suelo.', 'Sube las piernas juntas hasta la vertical sin despegar la lumbar.', 'Eleva la pelvis apretando glúteos y abdomen en la parte alta.', 'Baja primero la cadera y después las piernas de forma controlada.', 'Evita tirar del cuello con las manos y mantén la barbilla separada del pecho.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera con la cabeza elevada, facilitando la respiración y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1855'),
('d47980a9-8f73-5c56-b482-9c31c689ae26', 'Elevación de piernas con rodillas ligeramente flexionadas', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos bajo los glúteos.', 'Flexiona ligeramente las rodillas y sube las piernas hasta la vertical.', 'Baja despacio hasta cerca del suelo sin tocarlo.', 'Exhala al subir e inhala al bajar manteniendo el abdomen activo.', 'Evita arquear la lumbar: si se despega, reduce el recorrido.']::text[], 'intermedio', 'Trabaja el abdomen bajo y los flexores de cadera con una variante más accesible que protege la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1854'),
('f3cfaf81-ab6a-5a71-ae84-b516144004a7', 'Pierna hacia el lado', ARRAY['Siéntate en el suelo con las piernas estiradas y la espalda recta.', 'Abre una pierna hacia el lado todo lo que puedas sin inclinar el tronco.', 'Inclínate suavemente hacia la pierna abierta hasta notar el estiramiento.', 'Respira profundo y mantén la posición sin rebotes.', 'No fuerces ni redondees la espalda: busca el rango cómodo.']::text[], 'principiante', 'Estira aductores e ingles, mejorando la movilidad de la cadera y aliviando tensiones en la cara interna del muslo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0955'),
('00867c32-93e2-510f-90c9-f15ccef51855', 'Estiramiento de isquiotibiales con pierna elevada', ARRAY['Túmbate boca arriba con las piernas extendidas.', 'Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla.', 'Endereza la pierna tanto como sea posible mientras la mantienes elevada.', 'Mantén el estiramiento durante 20-30 segundos.', 'Repite con la otra pierna.']::text[], 'principiante', 'Alarga la parte posterior del muslo y los glúteos, mejorando la flexibilidad y reduciendo la rigidez tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1576'),
('461553b1-c744-500e-ab3f-832b039d3286', 'Postura de piernas en la pared', ARRAY['Túmbate boca arriba cerca de una pared y apoya los glúteos contra ella.', 'Sube las piernas estiradas por la pared hasta formar un ángulo recto.', 'Deja los brazos a los lados y relaja los hombros y la mandíbula.', 'Respira lento y profundo manteniendo la postura entre uno y cinco minutos.', 'Evita forzar si notas hormigueo: separa un poco las piernas o acorta el tiempo.']::text[], 'intermedio', 'Estira isquiotibiales y gemelos y descarga la zona lumbar, favoreciendo la relajación y la circulación de las piernas.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4381'),
('ab08f418-ce69-58b9-94c1-e9d125bf3a91', 'Abdominal en máquina ab coaster', ARRAY['Ajusta el asiento y colócate con la espalda apoyada y los pies en las plataformas.', 'Agarra las asas y engancha las rodillas o los pies según la máquina.', 'Flexiona el tronco llevando las rodillas hacia el pecho con el abdomen.', 'Exhala al recoger e inhala al volver despacio a la posición inicial.', 'Evita tirar con los brazos o balancear el cuerpo para no perder la tensión abdominal.']::text[], 'principiante', 'Fortalece el abdomen y los oblicuos con recorrido guiado, ideal para trabajar el core con carga progresiva.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5583'),
('3c1955cb-5385-577a-a78c-c120d6cdb6cb', 'Balanceo abdominal en máquina', ARRAY['Siéntate en la máquina con la espalda apoyada y los pies bien fijados.', 'Agarra las asas y activa el abdomen antes de empezar.', 'Balancea el tronco hacia delante contrayendo el core sin usar impulso.', 'Vuelve despacio a la posición inicial controlando el retorno.', 'Evita balancearte con inercia: el movimiento debe salir del abdomen.']::text[], 'principiante', 'Trabaja el abdomen y los oblicuos con un movimiento guiado que mejora la fuerza del core y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6561'),
('5834f6a9-d8d8-5ee8-bd31-f1583f09fdfe', 'Elevación de pierna con abducción en máquina', ARRAY['Colócate en la máquina con la espalda apoyada y el pie en la plataforma.', 'Ajusta la resistencia y sujeta las asas para estabilizar el tronco.', 'Eleva la pierna hacia fuera abduciendo la cadera de forma controlada.', 'Baja despacio sin dejar que el peso choque al final del recorrido.', 'Evita inclinar el tronco o compensar con la lumbar para mover más carga.']::text[], 'principiante', 'Fortalece abductores y glúteos, mejorando la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5349'),
('bd9a8823-764d-5c18-a69f-4dd7a42507d6', 'Sentadilla con abducción en máquina', ARRAY['Colócate en la máquina con los pies en las plataformas y la espalda apoyada.', 'Ajusta la resistencia y sujeta las asas laterales.', 'Flexiona las rodillas y abre las piernas hacia fuera abduciendo la cadera.', 'Empuja con los talones para volver arriba apretando glúteos.', 'Evita juntar las rodillas hacia dentro o despegar la espalda del respaldo.']::text[], 'principiante', 'Activa abductores, glúteos y cuádriceps, reforzando la cadera y mejorando la estabilidad en la sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2746'),
('5d427b5b-0059-593e-82b2-450d9ec73f00', 'Empuje de aducción en máquina', ARRAY['Siéntate en la máquina con la espalda apoyada y las piernas en las almohadillas.', 'Ajusta la resistencia y agarra las asas para estabilizarte.', 'Junta las piernas empujando hacia dentro con los aductores.', 'Vuelve despacio a la posición abierta sin dejar caer el peso.', 'Evita abrir demasiado de golpe o usar impulso para no forzar la ingle.']::text[], 'principiante', 'Trabaja aductores e ingles con empuje guiado, mejorando la fuerza y estabilidad de la cara interna del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2747'),
('dfa40076-7ed4-5f75-b071-8aa8e3029d9f', 'Extensión de pierna alternada en máquina con discos', ARRAY['Siéntate en la máquina con la espalda apoyada y el rodillo sobre el empeine.', 'Ajusta la carga en los discos y sujeta las asas laterales.', 'Extiende una pierna hasta estirar la rodilla sin bloquearla del todo.', 'Baja despacio y alterna con la otra pierna manteniendo el ritmo.', 'Evita dar tirones o despegar la espalda del respaldo al empujar.']::text[], 'principiante', 'Aísla el cuádriceps de cada pierna, corrigiendo desequilibrios y mejorando la fuerza y el control de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1874'),
('90aa5b3d-1aa6-5fc2-912e-bb83149aa1be', 'Prensa de piernas alternada en máquina', ARRAY['Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies.', 'Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.', 'Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta.', 'Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial.', 'Repite con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece cuádriceps, isquiotibiales y glúteos pierna a pierna, mejorando la fuerza y corrigiendo asimetrías.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2287'),
('0b2b74a1-9516-56fd-b25f-a6832cd8bcec', 'Remo sentado alternado con agarre cerrado en máquina', ARRAY['Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.', 'Siéntate en la máquina con la espalda recta y los pies planos sobre la placa para los pies.', 'Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.', 'Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio.', 'Tira de una asa hacia el torso mientras mantienes la otra asa inmóvil.', 'Aprieta los omóplatos al final del movimiento.', 'Devuelve lentamente el asa a la posición inicial y repite con el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los bíceps con un jalón por brazo, mejorando la fuerza y el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0571'),
('9fc711e8-7ad2-56c0-9361-6b96114042e8', 'Prensa de piernas angulada en máquina', ARRAY['Apoya bien la espalda y los glúteos en el respaldo y coloca los pies en la plataforma a la anchura de los hombros.', 'Empuja la plataforma extendiendo las piernas sin bloquear del todo las rodillas.', 'Baja de forma controlada hasta que las rodillas formen unos 90 grados, sin despegar la zona lumbar.', 'Evita juntar las rodillas hacia dentro y no rebotes en la parte baja del recorrido.']::text[], 'principiante', 'Trabaja principalmente los cuádriceps con ayuda de glúteos, isquios y gemelos, ideal para ganar fuerza y volumen en las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8375'),
('d548256b-432f-51d8-bff4-81833fcaac96', 'Prensa de pierna angulada a una pierna en máquina', ARRAY['Coloca un pie centrado en la plataforma y mantén la espalda y los glúteos bien apoyados.', 'Empuja con esa pierna extendiendo la rodilla sin bloquearla del todo.', 'Baja despacio controlando el movimiento hasta unos 90 grados de flexión.', 'Mantén la rodilla alineada con el pie y evita que se vaya hacia dentro.']::text[], 'principiante', 'Fortalece el cuádriceps de forma unilateral, corrigiendo desequilibrios y sumando glúteo, isquios y aductores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9387'),
('eefe4751-e058-5488-8539-7b31d487acb1', 'Prensa de piernas asistida en máquina', ARRAY['Ajusta el asiento y apoya la espalda completa en el respaldo con los pies en la plataforma.', 'Empuja la plataforma de forma fluida extendiendo las piernas sin bloquear las rodillas.', 'Controla el descenso hasta notar el estiramiento sin despegar la lumbar.', 'Respira al empujar y evita levantar los talones de la plataforma.']::text[], 'principiante', 'Permite entrenar los cuádriceps con apoyo y control, útil para principiantes o para trabajar con más seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2749'),
('c552e897-fd5f-54b0-bc94-b76ec7ea3401', 'Extensión lumbar en máquina', ARRAY['Ajusta la máquina según el tamaño de tu cuerpo y tu rango de movimiento.', 'Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies asegurados.', 'Coloca las manos en las asas o en las barras de agarre.', 'Activa el core e inclínate lentamente hacia adelante, permitiendo que la espalda se redondee ligeramente.', 'Haz una pausa breve en la posición baja, sintiendo un estiramiento en la zona lumbar.', 'Usando los músculos de la espalda, levanta lentamente el torso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la musculatura de la columna con apoyo de glúteos e isquios, ayudando a prevenir molestias lumbares.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0573'),
('7e22f3ea-e145-54a7-8d86-e3a05b643347', 'Press de pecho con banda elástica en máquina', ARRAY['Ajusta el asiento para que las empuñaduras queden a la altura del pecho y coloca la banda en el anclaje indicado.', 'Empuja hacia delante extendiendo los brazos sin bloquear del todo los codos.', 'Vuelve despacio controlando la tensión de la banda hasta la posición inicial.', 'Mantén los omóplatos retraídos y evita arquear la espalda al empujar.']::text[], 'principiante', 'Trabaja el pectoral con tensión extra de la banda, implicando también tríceps y hombro para empujar con más potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4213'),
('508124bf-7188-53e3-8d00-d3446da0aaed', 'Sentadilla búlgara con cinturón en máquina', ARRAY['Coloca el pie delantero en la plataforma y el trasero apoyado atrás, con el cinturón bien ajustado.', 'Baja flexionando la rodilla delantera hasta que el muslo quede cerca de la horizontal.', 'Empuja con el talón delantero para subir manteniendo el tronco estable.', 'Evita que la rodilla delantera se vaya hacia dentro y no cargues el peso en la punta del pie.']::text[], 'principiante', 'Ejercicio unilateral exigente para cuádriceps y glúteo que también activa isquios, aductores y core para estabilizar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10328'),
('2e4b8f09-7f17-54d4-b133-b114866190c4', 'Peso muerto con cinturón en máquina', ARRAY['Colócate con los pies a la anchura de las caderas y agarra la barra con la espalda neutra.', 'Empuja el suelo con las piernas y extiende la cadera para levantar la barra pegada al cuerpo.', 'Baja controlando el movimiento hasta la posición inicial sin perder la curvatura lumbar.', 'Evita redondear la espalda y no tires con los brazos, solo sujeta la barra.']::text[], 'principiante', 'Movimiento global que trabaja glúteos e isquios junto a cuádriceps, espalda baja y agarre para ganar fuerza general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9866'),
('465b6d91-3bbd-5a75-b6ab-2629e3cc8926', 'Peso muerto rumano con cinturón en máquina', ARRAY['Sujeta la barra con los brazos extendidos y las rodillas ligeramente flexionadas.', 'Lleva la cadera hacia atrás bajando la barra pegada a las piernas hasta notar estiramiento en isquios.', 'Sube extendiendo la cadera y apretando glúteos sin hiperextender la espalda.', 'Mantén la espalda neutra y evita flexionar demasiado las rodillas.']::text[], 'principiante', 'Enfocado en isquios y glúteo, mejora la fuerza del tren posterior y la técnica de bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9494'),
('5a30097e-1a34-5ad4-bd40-3ff4d974c8c0', 'Peso muerto rumano a una pierna con cinturón en máquina', ARRAY['Apóyate en una pierna con la rodilla ligeramente flexionada y sujeta la barra.', 'Lleva la cadera atrás mientras la pierna libre se eleva, manteniendo la espalda recta.', 'Baja hasta notar estiramiento en el isquio y sube apretando el glúteo.', 'Evita girar la cadera y mantén la mirada al frente para no perder el equilibrio.']::text[], 'principiante', 'Trabaja isquios y glúteo de forma unilateral, mejorando equilibrio y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11529'),
('137a36da-f354-5024-bdab-379308e20e5b', 'Sentadilla con cinturón en máquina', ARRAY['Colócate en la máquina con el cinturón ajustado y los pies a la anchura de los hombros.', 'Baja flexionando rodillas y cadera manteniendo el tronco erguido.', 'Empuja con los talones para subir hasta la posición inicial sin bloquear las rodillas.', 'Evita que las rodillas se metan hacia dentro y no despeques los talones.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con gran estabilidad, permitiendo cargar más sin castigar la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2950'),
('6807540b-0f80-5e9c-9bc7-100a5e22b5b6', 'Peso muerto sumo con cinturón en máquina', ARRAY['Abre los pies más allá de la anchura de los hombros con las puntas hacia fuera y agarra la barra en V.', 'Empuja el suelo separando las rodillas y extendiendo la cadera para subir.', 'Mantén la barra cerca del cuerpo y la espalda neutra durante todo el recorrido.', 'Evita redondear la espalda y no bloquees las rodillas de golpe al final.']::text[], 'principiante', 'Variante de peso muerto que enfatiza glúteos y aductores, con trabajo de cuádriceps, isquios y espalda baja.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11055'),
('87a533af-0114-5d15-af25-0c3ec655f27f', 'Sentadilla sumo con cinturón en máquina', ARRAY['Coloca los pies anchos con las puntas hacia fuera y ajusta el cinturón.', 'Baja flexionando rodillas y cadera manteniendo el pecho alto.', 'Empuja con los talones y aprieta glúteos al subir.', 'Evita que las rodillas se vayan hacia dentro y no cargues el peso en la punta.']::text[], 'principiante', 'Con los pies abiertos activa más glúteo y aductores, sumando cuádriceps e isquios para piernas completas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9493'),
('f7ceb5e5-e23f-5ae0-8dc0-748cac8e75a3', 'Remo inclinado con agarre neutro en máquina con apoyo de pecho', ARRAY['Apoya el pecho en el soporte y agarra las empuñaduras con las palmas enfrentadas.', 'Tira de los codos hacia atrás juntando los omóplatos sin encoger los hombros.', 'Vuelve despacio controlando el movimiento hasta estirar los brazos.', 'Evita tirar con los brazos y no despeques el pecho del soporte.']::text[], 'principiante', 'Trabaja la espalda alta con apoyo que protege la lumbar, implicando dorsales, deltoides posterior y bíceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6514'),
('4f8142e2-e197-5f60-a26c-5ebd51dee4ce', 'Remo inclinado en máquina', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.', 'Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.', 'Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0574'),
('6fae3f48-8640-5f8d-a972-46eaada87f34', 'Remo inclinado a un brazo en máquina enfocado en dorsales', ARRAY['Apoya una mano o el pecho en la máquina y agarra la empuñadura con el otro brazo.', 'Tira del codo hacia atrás y abajo llevando la mano hacia la cadera.', 'Vuelve despacio estirando el brazo sin perder la posición del tronco.', 'Evita rotar el torso y no encojas el hombro al tirar.']::text[], 'principiante', 'Aísla el dorsal de un lado, con apoyo de romboides, bíceps y deltoides posterior para una espalda más fuerte.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10866'),
('e273111f-de49-5ca8-84b5-3b376022d5c2', 'Remo a un brazo en máquina con apoyo de pecho', ARRAY['Ajusta el asiento para que el pecho quede apoyado y el agarre a la altura del torso.', 'Agarra la empuñadura con la palma neutra y extiende el brazo sin perder el apoyo del pecho.', 'Tira del codo hacia atrás pegándolo al costado hasta llevar la mano a la cadera.', 'Controla la vuelta en dos o tres segundos sin dejar que el hombro se adelante.', 'Evita encoger el hombro hacia la oreja y mantén el cuello relajado durante todo el recorrido.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta de forma unilateral, corrigiendo desequilibrios y mejorando la retracción escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6515'),
('2c455239-93ba-59c8-8521-abb1367af227', 'Remo a un brazo en máquina con agarre abierto', ARRAY['Coloca el pecho firme contra el apoyo y regula la altura del asiento.', 'Sujeta la empuñadura con agarre abierto y el brazo estirado sin bloquear el codo.', 'Lleva el codo hacia fuera y atrás, juntando la escápula al final del movimiento.', 'Vuelve despacio controlando la carga y sin perder el contacto del pecho.', 'No balancees el tronco ni uses impulso para subir el peso.']::text[], 'principiante', 'Enfoca el trabajo en la espalda alta y los romboides, reforzando la postura y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6517'),
('84154c96-b856-55a1-92fd-6100ad6f6508', 'Remo en máquina con apoyo de pecho y agarre abierto', ARRAY['Ajusta el asiento para que el pecho quede bien apoyado y los brazos lleguen cómodos.', 'Agarra las empuñaduras con las palmas hacia abajo y los codos ligeramente abiertos.', 'Tira de los codos hacia atrás y hacia fuera hasta juntar las escápulas.', 'Regresa el peso de forma lenta manteniendo el pecho pegado al apoyo.', 'Evita tirar con los brazos y no arquees la espalda para completar la repetición.']::text[], 'principiante', 'Fortalece la espalda alta y los romboides con un gesto bilateral que mejora la postura y la salud escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6516'),
('90d088b4-ea72-5319-90f0-4c4724fa4890', 'Remo inclinado con barra V en máquina', ARRAY['Ajusta la altura del asiento y colócate frente a la máquina.', 'Sujeta la barra en V con un agarre prono, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la barra en V hacia el abdomen, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente el peso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los bíceps con un tirón horizontal guiado, ideal para ganar masa y postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3200'),
('8dbda7e5-4a1e-5136-b9b0-70c3d70d0a63', 'Jalón trasero en polea', ARRAY['Siéntate con los muslos fijados y agarra la barra con las manos algo más abiertas que los hombros.', 'Lleva la barra hacia la nuca o la parte alta del pecho sin echar la cabeza adelante.', 'Baja los codos hacia los costados y junta las escápulas al final del recorrido.', 'Sube el peso despacio controlando la fase excéntrica.', 'No tires con el cuello ni balancees el tronco para ganar impulso.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta con un tirón vertical que también implica bíceps y romboides.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1863'),
('5f2a06c9-a3a4-5b4d-b554-54a4578babd7', 'Press de hombros en polea con palanca', ARRAY['Ajusta el asiento para que las empuñaduras queden a la altura de los hombros.', 'Empuja hacia arriba extendiendo los codos sin bloquear del todo la articulación.', 'Baja el peso de forma controlada hasta la altura inicial.', 'Mantén el abdomen activo y la espalda apoyada en el respaldo.', 'Evita arquear la zona lumbar o encoger los hombros al empujar.']::text[], 'principiante', 'Desarrolla la fuerza de los deltoides y el tren superior con una trayectoria guiada y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1862'),
('fda70fcb-06c0-5ee6-bf30-31f9c6c431cb', 'Prensa de gemelos en máquina', ARRAY['Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca.', 'Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde.', 'Sujeta las asas o los soportes laterales para mayor estabilidad.', 'Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas.', 'Haz una pausa por un momento en la parte baja del movimiento.', 'Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los gemelos para desarrollar fuerza y volumen en la pantorrilla con una trayectoria guiada y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2289'),
('4982240b-939c-5e3c-ba13-2a6993e1c5ee', 'Elevación de gemelos en máquina', ARRAY['Coloca las puntas de los pies en la plataforma con los talones al aire.', 'Empuja con el metatarso y eleva los talones lo máximo posible.', 'Aguanta un segundo arriba apretando la pantorrilla.', 'Baja los talones despacio hasta notar el estiramiento sin rebotar.', 'Evita hacer rebotes rápidos y no bloquees las rodillas con fuerza.']::text[], 'principiante', 'Aísla el sóleo y el gemelo para mejorar la fuerza y el volumen de la pantorrilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1220'),
('f549cf89-e1cd-58fa-b2d2-5bc8fe2e790b', 'Estiramiento de gemelos en máquina', ARRAY['Coloca el pie en la plataforma con el talón fuera y la punta apoyada.', 'Empuja suavemente hacia delante hasta notar tensión en la pantorrilla.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Cambia de pierna y repite el mismo tiempo.', 'No fuerces hasta el dolor ni rebotes durante el estiramiento.']::text[], 'principiante', 'Mejora la flexibilidad de la pantorrilla y el tobillo, reduciendo tensión y riesgo de lesión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1447'),
('563d96d5-7d23-5cfb-a00b-163776d5cf7a', 'Sentadilla en silla en máquina', ARRAY['Apoya la espalda en el respaldo y coloca los pies en la plataforma a la anchura de los hombros.', 'Baja flexionando rodillas y caderas hasta unos noventa grados.', 'Empuja con los talones para subir sin bloquear las rodillas del todo.', 'Mantén el abdomen activo y la espalda pegada al respaldo.', 'Evita juntar las rodillas hacia dentro o despegar los talones.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con un patrón de sentadilla guiado, ideal para aprender la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1038'),
('fcb6c2d8-54d9-59b4-b50c-cde27ec0d30d', 'Jalón al pecho cruzado en máquina', ARRAY['Siéntate con los muslos fijados y agarra las empuñaduras cruzadas frente al pecho.', 'Tira de los codos hacia abajo y hacia el costado opuesto.', 'Junta las escápulas al final del recorrido sin encoger los hombros.', 'Vuelve despacio controlando la carga en todo momento.', 'No balancees el tronco ni tires con los brazos en lugar de con la espalda.']::text[], 'principiante', 'Trabaja el dorsal con un tirón cruzado que aumenta el rango y la activación de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6881'),
('9466109a-ee1f-5ed0-a881-a896124d35a0', 'Cruces en máquina', ARRAY['Ajusta la altura de las poleas y sujeta las empuñaduras con los codos ligeramente flexionados.', 'Lleva las manos hacia delante y hacia el centro hasta juntarlas.', 'Aprieta el pecho un instante al final del recorrido.', 'Abre los brazos despacio hasta notar el estiramiento sin forzar el hombro.', 'Evita bloquear los codos o usar impulso del tronco.']::text[], 'principiante', 'Aísla el pectoral con un movimiento de aducción que mejora la definición y la congestión del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3344'),
('04e90eff-5e86-5145-a526-12ce021cd846', 'Peso muerto en máquina', ARRAY['Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.', 'Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies.', 'Sujeta las asas o los lados del asiento para mayor estabilidad.', 'Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso.', 'Mantén la espalda recta y evita redondear los hombros.', 'Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos.', 'Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja glúteos, isquios y cuádriceps con un patrón de bisagra guiado, útil para aprender el gesto con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0578'),
('22ce9603-5f53-534b-ae89-aff65f4cd4d6', 'Press de pecho declinado en máquina', ARRAY['Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.', 'Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.', 'Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.', 'Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados.', 'Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfoca el trabajo en la porción inferior del pectoral con apoyo guiado, reduciendo la demanda de estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1300'),
('52efe9eb-7891-5f00-9986-587b54a07601', 'Abdominal declinado en máquina', ARRAY['Siéntate en el banco declinado y fija los pies en los apoyos.', 'Sube el tronco flexionando el abdomen sin tirar del cuello.', 'Baja de forma lenta hasta la posición inicial controlando el movimiento.', 'Espira al subir e inspira al bajar.', 'Evita usar impulso o tirar de la cabeza con las manos.']::text[], 'principiante', 'Refuerza el recto abdominal y los flexores de cadera con un rango controlado y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1858'),
('062f455f-acda-5b53-b793-6c298c153a71', 'Elevación de gemelos burro en máquina', ARRAY['Ajusta la máquina de palanca a la altura adecuada para tu cuerpo.', 'Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde.', 'Coloca las manos en las asas o en las barras de soporte para mayor estabilidad.', 'Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los gemelos con la cadera flexionada y estira también isquios y glúteos, mejorando la fuerza y el volumen de la pantorrilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1253'),
('74533bfd-b911-56ec-835a-e36158a63412', 'Jalón frontal en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Siéntate erguido con el pecho elevado y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.', 'Activa los dorsales y tira de las asas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal ancho y los romboides, reforzando la espalda y mejorando la postura y la fuerza de tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0579'),
('d79c3f19-3664-5ea8-a121-c195421db3ea', 'Sentadilla completa en máquina', ARRAY['Coloca los pies en la plataforma a la anchura de los hombros y apoya la espalda bien pegada al respaldo.', 'Desbloquea la máquina y desciende de forma controlada hasta que los muslos queden paralelos o algo más abajo.', 'Empuja con los talones para subir sin bloquear las rodillas del todo al final.', 'Inspira al bajar y espira al subir, manteniendo el core activo.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten durante el recorrido.']::text[], 'principiante', 'Fortalece cuádriceps, glúteos e isquios con un recorrido completo, mejorando la fuerza y la estabilidad de las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1039'),
('e46348a2-8a2a-5a8e-a881-3ef2dd248a62', 'Press de glúteos en máquina', ARRAY['Ajusta el respaldo y apoya la espalda y el pie en la plataforma según indique la máquina.', 'Empuja con el talón extendiendo la cadera sin arquear la zona lumbar.', 'Aprieta el glúteo arriba un segundo antes de volver de forma controlada.', 'Espira al empujar e inspira al regresar a la posición inicial.', 'Evita compensar con la lumbar o empujar con la punta del pie.']::text[], 'principiante', 'Empuja la cadera hacia atrás contra la resistencia para aislar el glúteo y reforzar isquios y cuádriceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6601'),
('2a832772-6d9b-5de8-b0ef-6bde9c7400ce', 'Buenos días en máquina hack squat', ARRAY['Colócate en la máquina con los hombros bajo las almohadillas y los pies a la anchura de la cadera.', 'Con las rodillas ligeramente flexionadas, lleva la cadera hacia atrás inclinando el torso con la espalda recta.', 'Baja hasta notar el estiramiento en los isquios y vuelve empujando la cadera hacia delante.', 'Mantén el core activo y espira al subir, inspirando al bajar.', 'Evita redondear la espalda o bajar más de lo que controlas.']::text[], 'principiante', 'Con la cadera hacia atrás y el torso inclinado, carga isquios, glúteos y zona lumbar baja mejorando la bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6733'),
('d7f65737-ada8-5ea0-96d1-032078f6bb9e', 'Encogimiento sin agarre en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina de palanca.', 'Sujeta las asas con las palmas hacia adentro y los brazos completamente extendidos.', 'Manteniendo la espalda recta, exhala y eleva los hombros tan alto como sea posible.', 'Mantén la contracción por un momento breve, luego inhala y baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Sube los hombros contra la resistencia para trabajar el trapecio superior sin depender de la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0580'),
('9d49beba-778d-554d-8e08-c9855a7c364f', 'Fortalecedor de agarre en máquina', ARRAY['Ajusta la altura del asiento y sujeta las asas de la máquina de palanca.', 'Mantén la espalda recta y los pies planos en el suelo.', 'Exhala y aprieta las asas, contrayendo los antebrazos.', 'Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Cierra las manos contra la resistencia para reforzar antebrazos y agarre, útil en dominadas y peso muerto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2288'),
('4856c43d-c2cb-5d37-8d9b-27d668e2b106', 'Sentadilla hack en máquina', ARRAY['Apoya la espalda y los hombros en el respaldo y coloca los pies en la plataforma a la anchura de los hombros.', 'Desbloquea la máquina y baja de forma controlada hasta que las rodillas lleguen a unos 90 grados.', 'Empuja con los talones para subir sin bloquear las rodillas al final.', 'Inspira al bajar y espira al subir, manteniendo la espalda pegada al respaldo.', 'Evita levantar los talones o dejar que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Guía el movimiento de sentadilla para cargar cuádriceps, glúteos y aductores con gran estabilidad y menos riesgo lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5516'),
('15ace9ba-a7bd-51a4-b1cd-dedddc8e66ca', 'Remo alto en máquina', ARRAY['Ajusta la altura del asiento y la plataforma para los pies a una posición cómoda.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la plataforma para los pies.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y activa el core.', 'Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Tira de la resistencia hacia el pecho para trabajar la espalda alta, los romboides y los deltoides posteriores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0581'),
('18d527e6-e894-5d55-85ec-50fbe53cf09f', 'Extensión de cadera en máquina', ARRAY['Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.', 'Coloca los pies en los apoyapiés y sujeta las asas para mayor estabilidad.', 'Activa los glúteos y los isquiotibiales, luego empuja contra los apoyapiés para extender las caderas y levantar las piernas hacia atrás.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Extiende la cadera contra la resistencia para aislar el glúteo y reforzar los isquios con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2286'),
('56bc6f25-2a2c-585b-84b7-347bed7872db', 'Hip thrust en máquina', ARRAY['Coloca la espalda alta apoyada en el respaldo y los pies a la anchura de la cadera.', 'Empuja con los talones extendiendo la cadera hasta alinear tronco y muslos.', 'Aprieta el glúteo arriba un segundo sin hiperextender la lumbar.', 'Espira al subir e inspira al bajar de forma controlada.', 'Evita empujar con la punta del pie o arquear la espalda al final.']::text[], 'principiante', 'Empuja la cadera hacia arriba contra la resistencia para cargar el glúteo con fuerza, implicando isquios y cuádriceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2146'),
('d239753b-38c5-59f7-b0a6-f0f6113938f9', 'Hip thrust en máquina con cajón', ARRAY['Coloca el cajón bajo la máquina y apoya la espalda alta en el respaldo con los pies firmes.', 'Empuja con los talones extendiendo la cadera hasta alinear tronco y muslos.', 'Aprieta el glúteo arriba y baja de forma controlada hasta el estiramiento.', 'Mantén el core activo y espira al empujar, inspirando al bajar.', 'Evita que la cadera suba más de la cuenta arqueando la lumbar.']::text[], 'principiante', 'Usa un cajón para ajustar la altura y empujar la cadera contra la resistencia, aislando el glúteo con más recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2742'),
('224d0fb2-c4ae-5a2a-81fe-c8a676f7cf41', 'Hip thrust en máquina con banda elástica', ARRAY['Coloca la banda por encima de las rodillas y apoya la espalda alta en el respaldo.', 'Empuja con los talones extendiendo la cadera mientras mantienes las rodillas alineadas con los pies.', 'Aprieta el glúteo arriba un segundo sin arquear la lumbar.', 'Espira al subir e inspira al bajar de forma controlada.', 'Evita que las rodillas se junten o se abran en exceso contra la banda.']::text[], 'principiante', 'Añade una banda para aumentar la tensión en la cadera y activar más el glúteo medio y los aductores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2147'),
('af2ab10e-db7c-5097-ae85-c281c561dca8', 'Prensa de piernas horizontal en máquina', ARRAY['Siéntate con la espalda y la cadera bien apoyadas y coloca los pies en la plataforma a la anchura de los hombros.', 'Desbloquea la máquina y baja la plataforma de forma controlada hasta unos 90 grados de rodilla.', 'Empuja con los talones sin bloquear las rodillas del todo al final.', 'Inspira al bajar y espira al empujar, manteniendo la lumbar pegada al respaldo.', 'Evita levantar la cadera o dejar que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Empuja la plataforma con las piernas para cargar cuádriceps, glúteos e isquios con gran estabilidad y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2951'),
('59e046dc-dcc8-51db-8285-b8291c94e7d5', 'Prensa horizontal a una pierna en máquina', ARRAY['Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.', 'Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.', 'Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo.', 'Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'principiante', 'Empuja con una sola pierna para trabajar glúteo y cuádriceps de forma unilateral, corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2611'),
('a7eba9b2-957b-58a8-953b-b3526fd188ee', 'Press de pecho inclinado en máquina', ARRAY['Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.', 'Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.', 'Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.', 'Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la parte superior del pectoral con apoyo de hombros y tríceps, ideal para ganar fuerza y volumen en el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1299'),
('8d8edd62-f6c8-56da-be03-ca829a6f6752', 'Apertura invertida inclinada con pecho apoyado en máquina', ARRAY['Coloca el pecho apoyado en el respaldo y ajusta los brazos a la altura de los hombros.', 'Agarra las asas con las palmas hacia dentro y mantén los codos ligeramente flexionados.', 'Abre los brazos hacia atrás de forma controlada hasta notar tensión en la parte posterior del hombro.', 'Vuelve despacio a la posición inicial sin dejar que el peso choque.', 'Evita encoger los hombros hacia las orejas durante todo el recorrido.']::text[], 'principiante', 'Aísla el deltoides posterior y la espalda alta, mejorando la postura y el equilibrio muscular del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11718'),
('58f7227a-aa8b-5ce4-9156-fb55a0a66541', 'Apertura inclinada en máquina', ARRAY['Siéntate con la espalda pegada al respaldo y los pies bien apoyados en el suelo.', 'Coloca los antebrazos o asas a la altura del pecho con los codos ligeramente flexionados.', 'Junta los brazos hacia delante apretando el pecho sin bloquear los codos.', 'Abre despacio controlando el retorno hasta sentir un estiramiento cómodo.', 'Evita arquear la espalda o usar impulso para mover el peso.']::text[], 'principiante', 'Aísla el pectoral superior con un movimiento de apertura guiado, útil para definir y estirar el pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5843'),
('d7b86920-d688-5514-b9f3-4fa63925331d', 'Press de pecho martillo inclinado en máquina', ARRAY['Ajusta el asiento para que las asas queden a la altura del pecho alto.', 'Agarra las asas con las palmas enfrentadas y la espalda apoyada en el respaldo.', 'Empuja hacia delante extendiendo los brazos sin bloquear del todo los codos.', 'Vuelve despacio hasta que las manos queden junto al pecho.', 'Evita despegar la espalda del respaldo o encoger los hombros al empujar.']::text[], 'principiante', 'Fortalece el pectoral superior con agarre neutro, implicando también tríceps y hombros en un empuje seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1195'),
('c226585a-b8c8-5c15-8882-0a8cb5d3e433', 'Press de pecho inclinado a un brazo en máquina', ARRAY['Siéntate con la espalda apoyada y coloca un solo brazo en el asa a la altura del pecho alto.', 'Mantén el tronco estable y el otro brazo relajado o apoyado.', 'Empuja el asa hacia delante extendiendo el codo sin bloquearlo.', 'Regresa despacio controlando el peso hasta la posición inicial.', 'Evita girar el tronco o inclinarte hacia el lado que empuja.']::text[], 'principiante', 'Trabaja el pectoral superior de forma unilateral, corrigiendo desequilibrios entre lados y mejorando el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4371'),
('e7e3b2f2-aa75-58ae-849f-f0edfe36dec0', 'Remo inclinado boca abajo con agarre neutro en máquina', ARRAY['Túmbate boca abajo con el pecho apoyado y agarra las asas con las palmas enfrentadas.', 'Mantén los codos cerca del cuerpo y la cabeza alineada con la columna.', 'Tira de las asas hacia el pecho juntando las escápulas.', 'Baja el peso despacio hasta estirar los brazos sin perder la postura.', 'Evita levantar el pecho del apoyo o encoger los hombros al tirar.']::text[], 'principiante', 'Refuerza la espalda alta y los romboides con agarre neutro, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10867'),
('1c6652cd-d554-5a11-ba8f-fd720e7041bc', 'Remo inclinado boca abajo en máquina', ARRAY['Túmbate boca abajo con el pecho apoyado y agarra las asas de la máquina.', 'Mantén la espalda neutra y los pies firmes en el apoyo.', 'Tira de las asas hacia el cuerpo llevando los codos hacia atrás.', 'Junta las escápulas arriba y baja el peso de forma controlada.', 'Evita usar impulso o despegar el pecho del respaldo.']::text[], 'principiante', 'Fortalece la espalda alta y los dorsales con tracción apoyada, útil para mejorar postura y fuerza de tirón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10646'),
('12915e68-4506-5129-8281-38ef223bff91', 'Sentadilla isométrica con abducción de cadera en máquina', ARRAY['Colócate en la máquina con las piernas en la posición de sentadilla indicada.', 'Mantén la espalda apoyada y los pies bien colocados en las plataformas.', 'Abre las piernas contra la resistencia mientras sostienes la postura isométrica.', 'Mantén la tensión respirando de forma constante sin aguantar el aire.', 'Evita bloquear la respiración o perder la alineación de rodillas y pies.']::text[], 'principiante', 'Activa los abductores y glúteos manteniendo una postura estática, mejorando estabilidad y fuerza de cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10113'),
('c0d13688-a1c2-56c7-9c38-b4e60c3fa0a4', 'Curl femoral de rodillas en máquina', ARRAY['Ajusta la máquina a tu cuerpo y selecciona el peso deseado.', 'Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies.', 'Sujeta las asas o los lados de la máquina para mayor estabilidad.', 'Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.', 'Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los isquiotibiales con flexión de rodilla, reforzando la parte posterior del muslo y protegiendo la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0582'),
('852c037a-16ca-56a4-a9bc-3dbe411bc4f4', 'Hiperextensión inversa de rodillas en máquina', ARRAY['Colócate en la máquina con el tronco apoyado y las rodillas bien fijadas.', 'Sujétate con firmeza y mantén la espalda neutra.', 'Eleva las piernas hacia atrás apretando los glúteos sin arquear la lumbar.', 'Baja las piernas despacio hasta la posición inicial.', 'Evita balancear el cuerpo o usar impulso para subir.']::text[], 'principiante', 'Fortalece glúteos e isquiotibiales elevando las piernas, ayudando a estabilizar la cadera y la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2748'),
('268a0bba-43ea-5467-b8cc-d6de97d723fc', 'Giro de rodillas en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante.', 'Sujeta las asas o los lados de la máquina para mayor estabilidad.', 'Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible.', 'Haz una pausa por un momento, luego regresa lentamente a la posición inicial.', 'Repite el giro hacia el lado opuesto.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los oblicuos con rotación controlada, mejorando la fuerza del core y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0583'),
('756500f2-8105-57a6-8bdb-c7622471ac59', 'Jalón lateral en máquina', ARRAY['Siéntate con los muslos fijados y agarra las asas por encima de la cabeza.', 'Mantén el pecho alto y la espalda ligeramente arqueada.', 'Tira de las asas hacia los lados y abajo llevando los codos hacia el cuerpo.', 'Sube el peso despacio controlando el retorno.', 'Evita encoger los hombros o tirar con impulso del tronco.']::text[], 'principiante', 'Desarrolla los dorsales con tracción lateral, ampliando la espalda y mejorando la fuerza de tirón vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1870'),
('138fbcbe-05af-5d5a-b2a4-befdca087da8', 'Elevación lateral en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.', 'Sujeta las asas con un agarre prono y mantén los brazos rectos.', 'Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo.', 'Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el deltoides medio con elevación guiada, ayudando a dar forma y anchura a los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0584'),
('b1cfcd96-7ace-51c2-b935-de7bc7ec5f3c', 'Jalón lateral abierto en máquina', ARRAY['Siéntate con los muslos sujetos y agarra las asas con las manos separadas.', 'Mantén el pecho arriba y los hombros bajos.', 'Tira de las asas hacia abajo y hacia los lados abriendo bien los codos.', 'Regresa despacio hasta estirar los brazos sin perder la postura.', 'Evita inclinarte hacia atrás o encoger los hombros al tirar.']::text[], 'principiante', 'Trabaja los dorsales con un agarre amplio, favoreciendo la amplitud de la espalda y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2665'),
('71f952b6-82e2-5ff9-ad53-3c2b0229b9fc', 'Extensión de piernas en máquina', ARRAY['Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies.', 'Sujeta las asas o las barras laterales para mayor estabilidad.', 'Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso.', 'Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el cuádriceps extendiendo la rodilla, útil para reforzar el muslo y mejorar la fuerza en la parte frontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0585'),
('295a1100-1caf-5ee3-b69a-9dcf299284e3', 'Extensión de pierna en máquina (con discos)', ARRAY['Ajusta el respaldo para que la rodilla quede alineada con el eje de la máquina.', 'Coloca los tobillos bajo el rodillo y agarra las asas para estabilizar el tronco.', 'Extiende las rodillas hasta arriba sin bloquear de golpe y baja controlando dos segundos.', 'Evita despegar la espalda del respaldo o dar tirones con impulso.']::text[], 'principiante', 'Aísla el cuádriceps y sirve para ganar fuerza y volumen en la parte frontal del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1873'),
('9d9c3a07-2b67-5d60-895b-092f7361f941', 'Sentadilla hack lineal en máquina', ARRAY['Apoya la espalda completa en el respaldo y coloca los pies en la plataforma a la anchura de los hombros.', 'Desbloquea las asas y baja flexionando rodillas y caderas hasta donde controles.', 'Empuja con los talones para subir sin bloquear las rodillas al final.', 'Mantén el core activo y evita que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Trabaja cuádriceps, glúteos y femorales con apoyo guiado, ideal para cargar sin comprometer el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6523'),
('c17c06bc-923a-52c4-82b5-16c458be6fe2', 'Remo bajo en máquina', ARRAY['Siéntate con el pecho apoyado y agarra las asas con los brazos extendidos.', 'Tira de los codos hacia atrás llevando las asas al abdomen sin encoger los hombros.', 'Aprieta la espalda un segundo y vuelve controlando el recorrido.', 'Evita tirar con la espalda baja arqueándola o usar impulso del tronco.']::text[], 'principiante', 'Refuerza la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4214'),
('1abd4a21-812e-5286-b58a-08deb3a1b77c', 'Remo en barra T acostado con banda', ARRAY['Túmbate boca abajo con el pecho apoyado y agarra las asas con la banda tensa.', 'Tira de los codos hacia el cuerpo llevando las manos al pecho.', 'Aprieta los omóplatos arriba y baja despacio resistiendo la banda.', 'No levantes el pecho del apoyo ni encojas el cuello durante la tracción.']::text[], 'principiante', 'Trabaja dorsales y espalda alta con tensión constante de la banda, útil para hipertrofia y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4062'),
('8b26cbc0-2219-5d1d-bfb2-c46cfba429cc', 'Press de pecho acostado en máquina (con discos)', ARRAY['Ajusta el asiento para que las asas queden a la altura del pecho.', 'Empuja hacia delante extendiendo los codos sin bloquear del todo.', 'Vuelve controlando hasta notar estiramiento en el pecho.', 'Mantén los omóplatos retraídos y evita arquear la zona lumbar.']::text[], 'principiante', 'Desarrolla pectorales, tríceps y hombros con un recorrido guiado y seguro para ganar fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1041'),
('032572ab-843b-5f1e-b0fc-f4e9c49a11b2', 'Abdominal en máquina', ARRAY['Siéntate y ajusta el apoyo para que el pecho quede fijo contra el rodillo.', 'Flexiona el tronco llevando las costillas hacia la pelvis sin tirar del cuello.', 'Exhala al contraer y vuelve despacio sin soltar la tensión.', 'Evita usar impulso de brazos o tirar con la cadera en lugar del abdomen.']::text[], 'principiante', 'Fortalece el recto abdominal y los oblicuos con carga progresiva y recorrido controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2276'),
('7589d42e-17f3-52b1-a8c2-7632882e70c4', 'Flexión de rodilla en máquina', ARRAY['Túmbate boca abajo con las rodillas alineadas con el eje de la máquina.', 'Coloca el rodillo sobre los tobillos y agarra las asas.', 'Flexiona las rodillas llevando los talones hacia los glúteos y baja controlando.', 'Evita despegar la cadera del banco o dar tirones con la espalda.']::text[], 'principiante', 'Aísla los isquiotibiales y mejora la fuerza y estabilidad posterior de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9676'),
('b1713ea7-e4a7-59f4-997b-6fe0c0e1e58a', 'Curl femoral tumbado en máquina', ARRAY['Ajusta la máquina a tu cuerpo y selecciona el peso deseado.', 'Túmbate boca abajo en la máquina con las piernas rectas y los talones contra la palanca acolchada.', 'Sujeta las asas o los lados de la máquina para mayor estabilidad.', 'Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba tanto como sea posible sin levantar las caderas de la almohadilla.', 'Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.', 'Inhala y baja lentamente la palanca de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los isquiotibiales para reforzar la parte posterior del muslo y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0586'),
('94950265-2666-509b-8ece-72f97e6433c9', 'Curl femoral con hiperextensión inversa', ARRAY['Colócate en la máquina con el rodillo en los tobillos y el tronco bien apoyado.', 'Flexiona las rodillas hacia los glúteos como en un curl normal.', 'Desde ahí extiende la cadera elevando las piernas sin arquear la lumbar.', 'Baja controlando el recorrido y evita balancear el cuerpo para ganar impulso.']::text[], 'principiante', 'Combina isquiotibiales y glúteos con extensión de cadera, fortaleciendo la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11567'),
('6e4dcc16-0034-5838-8832-bf5eca4f520b', 'Elevación de piernas en máquina', ARRAY['Siéntate o túmbate según la máquina y apoya la espalda firme en el respaldo.', 'Con las rodillas flexionadas, eleva las piernas contrayendo el abdomen.', 'Baja despacio sin dejar que la espalda se arquee.', 'Evita usar impulso o balancear el tronco para subir las piernas.']::text[], 'principiante', 'Trabaja el abdomen bajo y los flexores de cadera con recorrido guiado y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1856'),
('62bc04e6-6d9a-5806-91e6-bc1a0d3d8d0a', 'Remo en barra T tumbado en máquina', ARRAY['Túmbate boca abajo con el pecho apoyado y agarra las asas.', 'Tira de los codos hacia atrás llevando las manos al abdomen.', 'Junta los omóplatos arriba y vuelve controlando el movimiento.', 'No levantes el pecho del apoyo ni encojas los hombros al tirar.']::text[], 'principiante', 'Fortalece espalda alta y dorsales con tracción horizontal guiada, mejorando postura y fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1194'),
('b17bb865-b51d-53df-819f-8a9dba2d6088', 'Curl femoral a una pierna en máquina', ARRAY['Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.', 'Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos.', 'Sujeta las asas a los lados de la máquina para mayor apoyo.', 'Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos.', 'Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los isquiotibiales de forma unilateral para corregir desequilibrios entre piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3195'),
('a1aa3072-dcef-5e74-85f2-98912cb76f42', 'Press militar en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.', 'Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.', 'Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.', 'Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Desarrolla deltoides y tríceps empujando por encima de la cabeza con recorrido guiado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0587'),
('edf3c454-e569-59b6-b272-a82cd928ed5c', 'Jalón al pecho con cuerda', ARRAY['Siéntate y ajusta el rodillo para fijar los muslos, agarrando la cuerda.', 'Tira de los codos hacia abajo y atrás llevando la cuerda al pecho.', 'Aprieta los dorsales abajo y sube controlando sin perder tensión.', 'Evita echar el tronco atrás o tirar con los brazos sin activar la espalda.']::text[], 'principiante', 'Trabaja dorsales y espalda alta con agarre neutro, mejorando la fuerza de tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5326'),
('4f5f317e-bc0a-5343-8209-d4f3b7aa4d79', 'Remo sentado con agarre cerrado', ARRAY['Ajusta la altura del asiento y los apoyapiés para asegurar una postura correcta.', 'Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas.', 'Sujeta las asas con un agarre estrecho, con las palmas una frente a la otra.', 'Mantén la espalda recta e inclínate ligeramente hacia adelante.', 'Tira de las asas hacia el torso, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento.', 'Suelta lentamente las asas y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza espalda alta, bíceps y antebrazos con tracción horizontal de agarre estrecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0588'),
('0dddb787-6e6a-507c-921e-c8468acae589', 'Extensión de cuello en máquina', ARRAY['Ajusta el asiento y coloca la frente o la nuca en el soporte según la máquina.', 'Empieza con poco recorrido y extiende el cuello de forma lenta y controlada.', 'Exhala al extender y vuelve a la posición inicial sin dejar caer el peso.', 'Evita arquear la espalda o usar impulso; mantén el movimiento suave y corto.']::text[], 'principiante', 'Fortalece los elevadores de la escápula y el cuello, mejorando la estabilidad cervical y la postura de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2282'),
('bf81270c-60fa-5243-baab-0aa373c975ed', 'Flexión lateral de cuello en máquina', ARRAY['Siéntate con la espalda apoyada y coloca la cabeza en el soporte lateral.', 'Inclina el cuello hacia un lado lentamente contra la resistencia.', 'Exhala al inclinar y controla la vuelta sin dejar caer el peso.', 'Mantén los hombros relajados y evita girar la cabeza durante el movimiento.']::text[], 'principiante', 'Trabaja la inclinación lateral del cuello, reforzando la zona cervical y los músculos que estabilizan la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2283'),
('0a5c2bbb-fae2-5da6-b861-7ea13567c60e', 'Flexión lateral derecha de cuello en máquina (con discos)', ARRAY['Ajusta el soporte a la altura de la cabeza y siéntate con la espalda recta.', 'Inclina el cuello hacia el lado contrario con un movimiento lento y corto.', 'Exhala al inclinar y regresa controlando la resistencia.', 'No uses impulso ni gires la cabeza; mantén los hombros quietos.']::text[], 'principiante', 'Refuerza la musculatura lateral del cuello y los elevadores de la escápula, ayudando a estabilizar la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2284'),
('d3c1c95a-84b5-5403-965d-1ce1cbb9af5e', 'Remo inclinado a un brazo', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con agarre prono.', 'Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza erguida.', 'Deja que la barra cuelgue frente a ti con los brazos completamente extendidos.', 'Tira de la barra hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Junta los omóplatos en la parte superior del movimiento.', 'Baja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta y el bíceps de forma unilateral, corrigiendo desequilibrios y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0589'),
('48969da3-acfc-5e01-aef5-78bdb6861ace', 'Press de pecho a un brazo en máquina', ARRAY['Ajusta el asiento para que la empuñadura quede a la altura del pecho.', 'Empuja la palanca hacia delante sin bloquear del todo el codo.', 'Exhala al empujar y vuelve despacio controlando el peso.', 'Evita arquear la espalda o girar el tronco para empujar.']::text[], 'principiante', 'Trabaja el pectoral de forma unilateral, mejorando la fuerza y corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2974'),
('5bd86a9a-b0c3-59c0-b3f4-106e27156250', 'Remo alto lateral a un brazo en máquina', ARRAY['Ajusta la altura del asiento y colócate frente a la máquina.', 'Sujeta el asa con una mano y mantén la espalda recta.', 'Tira del asa hacia el cuerpo, manteniendo el codo cerca del costado.', 'Aprieta los músculos de la espalda en la parte superior del movimiento.', 'Suelta lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y el hombro con un tirón unilateral guiado, mejorando fuerza y control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1356'),
('821114ba-d0aa-5146-b2d8-fe82cb16f9e8', 'Jalón lateral abierto a un brazo en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.', 'Sujeta el asa con un agarre prono y extiende el brazo por completo, manteniendo una ligera flexión en el codo.', 'Tira del asa hacia abajo y a través del cuerpo en dirección a la cadera opuesta, apretando el dorsal en la parte baja del movimiento.', 'Devuelve lentamente el asa a la posición inicial, extendiendo el brazo por completo.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'principiante', 'Desarrolla dorsales y bíceps con un tirón vertical unilateral que amplía el rango y corrige asimetrías.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1347'),
('6e94b941-3f23-5f09-83a8-3b36554c78de', 'Remo bajo a un brazo en máquina', ARRAY['Siéntate con el pecho apoyado y agarra la empuñadura con un brazo.', 'Tira del peso hacia la cadera llevando el codo atrás y pegado al cuerpo.', 'Exhala al tirar y vuelve despacio sin perder la posición del tronco.', 'Evita encoger el hombro o usar impulso del cuerpo.']::text[], 'principiante', 'Fortalece el dorsal y la espalda alta de forma unilateral, mejorando la fuerza de tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4215'),
('5f5dc2af-0132-5466-82e5-55089ccfd2b1', 'Remo sentado a un brazo en máquina', ARRAY['Siéntate con la espalda recta y agarra la empuñadura con un brazo.', 'Tira hacia el abdomen llevando el codo atrás y sin girar el tronco.', 'Exhala al tirar y controla la vuelta hasta estirar el brazo.', 'Evita balancear el cuerpo o encoger el hombro al tirar.']::text[], 'principiante', 'Trabaja el dorsal y la espalda media de forma unilateral, reforzando la tracción y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1235'),
('3fd02bf3-975b-5819-8da1-2f3545dec59e', 'Press de hombros a un brazo en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.', 'Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados.', 'Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.', 'Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'principiante', 'Fortalece el deltoides y el tríceps de forma unilateral guiada, útil para equilibrar fuerzas entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0590'),
('3b14bf84-9d9f-5120-88e3-9ee111f2ca73', 'Press de pecho lateral a un brazo en máquina', ARRAY['Ajusta el asiento y coloca la empuñadura a la altura del pecho.', 'Empuja la palanca hacia delante sin bloquear el codo del todo.', 'Exhala al empujar y vuelve controlando la resistencia.', 'Mantén la espalda apoyada y evita girar el tronco.']::text[], 'principiante', 'Trabaja el pectoral de forma unilateral desde un ángulo lateral, mejorando fuerza y control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5815'),
('1aedc77c-e200-5bc4-9e5a-4b6c8f62bbba', 'Press de pecho sentado en máquina', ARRAY['Ajusta el asiento para que las empuñaduras queden a la altura del pecho.', 'Empuja hacia delante extendiendo los brazos sin bloquear los codos.', 'Exhala al empujar y vuelve despacio controlando el peso.', 'Evita arquear la espalda o separar los hombros del respaldo.']::text[], 'principiante', 'Fortalece el pectoral y los tríceps en posición sentada, ideal para trabajar el empuje de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6355'),
('64a558fe-acdc-5c74-bf26-15683d5ef004', 'Jalón al pecho sentado en máquina', ARRAY['Siéntate con la espalda apoyada y agarra la barra con las manos.', 'Tira hacia el pecho llevando los codos abajo y atrás.', 'Exhala al tirar y sube el peso controlando el movimiento.', 'Evita echar el tronco atrás o encoger los hombros.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta, mejorando la fuerza de tracción y la postura en posición sentada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6356'),
('1c7726b7-9f79-53fa-8f53-c243b1dd60eb', 'Prensa de piernas sentado para exteriores en máquina', ARRAY['Siéntate con la espalda apoyada y los pies en la plataforma a la anchura de los hombros.', 'Empuja la plataforma extendiendo las piernas sin bloquear las rodillas.', 'Exhala al empujar y vuelve despacio hasta unos 90 grados de rodilla.', 'Evita despegar la espalda o juntar las rodillas hacia dentro.']::text[], 'principiante', 'Fortalece cuádriceps, glúteos e isquios con un empuje guiado, útil para ganar fuerza en las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6354'),
('49c08d8b-5be8-510c-bdd9-8a57cc22879a', 'Fondos de tríceps con agarre prono en máquina', ARRAY['Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición.', 'Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos.', 'Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados.', 'Continúa bajando hasta que los brazos superiores queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps con un empuje guiado que también implica pecho y hombro, ideal para ganar fuerza y volumen.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0591'),
('3e99a95a-05ca-5c22-b1d9-7e43efebc019', 'Extensión de tríceps sobre la cabeza en máquina', ARRAY['Ajusta el asiento y coloca los codos apoyados en el soporte de la máquina.', 'Empuja la palanca hacia arriba extendiendo los codos sin mover los hombros.', 'Baja controlando el peso hasta notar estiramiento en el tríceps.', 'Evita arquear la espalda o despegar los codos del apoyo.']::text[], 'principiante', 'Aísla el tríceps en estiramiento para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7864'),
('2a25a00e-c096-5945-a0b7-151d932bf20d', 'Sentadilla péndulo en máquina', ARRAY['Colócate con la espalda apoyada y los pies en la plataforma.', 'Desbloquea la máquina y baja flexionando rodillas y caderas.', 'Empuja con los talones para subir sin bloquear las rodillas.', 'Mantén el core activo y evita que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Trabaja cuádriceps con gran carga y recorrido guiado, útil para fuerza y hipertrofia de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4951'),
('c60b898b-33e6-5e97-a1f2-0235a9d0bdff', 'Sentadilla pistol en máquina', ARRAY['Apoya un pie en la plataforma y sujétate a las asas de la máquina.', 'Baja flexionando la rodilla de la pierna de apoyo con control.', 'Empuja con el pie para volver arriba sin perder la alineación de la rodilla.', 'Evita dejar caer la cadera o cargar todo el peso en el asa.']::text[], 'avanzado', 'Fortalece cuádriceps y glúteo de forma unilateral con apoyo guiado para mejorar equilibrio y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1040'),
('bef655da-5c11-5deb-a58c-4319469abd5f', 'Curl predicador con torso girado en máquina', ARRAY['Siéntate con el pecho contra el soporte y el torso ligeramente girado.', 'Apoya los brazos en el pad y agarra las asas.', 'Flexiona los codos subiendo el peso sin despegar los brazos del apoyo.', 'Baja despacio controlando el retorno y evita balancear el torso.']::text[], 'principiante', 'Aísla el bíceps desde un ángulo que aumenta el estiramiento y la tensión en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5299'),
('6592c0c2-e6f4-5908-953d-f0f8a018f021', 'Remo sentado en máquina con agarre pronado', ARRAY['Siéntate con el pecho contra el pad y agarra las asas con las palmas hacia abajo.', 'Tira de las asas llevando los codos hacia atrás y juntando las escápulas.', 'Vuelve despacio sin perder la posición del pecho.', 'Evita encoger los hombros o tirar con los brazos sin activar la espalda.']::text[], 'principiante', 'Refuerza la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5447'),
('0dea4234-a31b-5b58-beb8-4f9de2c20a53', 'Encogimiento sentado en máquina con retracción escapular', ARRAY['Siéntate con el pecho apoyado y agarra las asas con agarre pronado.', 'Junta las escápulas llevando los hombros hacia atrás sin subirlos.', 'Mantén un segundo la contracción y vuelve controlando.', 'Evita encogerte hacia arriba o usar impulso del tronco.']::text[], 'principiante', 'Trabaja la musculatura interescapular y los trapecios para estabilizar y mejorar la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5448'),
('ea6b4f10-6919-5121-9308-b01e720a56e8', 'Pullover en máquina', ARRAY['Ajusta el asiento y las asas de la máquina de palanca a una posición cómoda.', 'Siéntate en la máquina con la espalda apoyada en la almohadilla y sujeta las asas con un agarre prono.', 'Mantén los brazos ligeramente flexionados y el core activado.', 'Tira lentamente de las asas hacia el pecho, apretando los dorsales.', 'Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los dorsales con un recorrido amplio que también implica tríceps y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2285'),
('b4c8dcea-3275-5d2a-aba0-b20b13ff37db', 'Flexión con toallas', ARRAY['Coloca las toallas en el suelo y apoya las manos sobre ellas en posición de plancha.', 'Baja el pecho flexionando los codos cerca del cuerpo.', 'Empuja para volver arriba manteniendo el cuerpo alineado.', 'Evita que la cadera caiga o que los codos se abran en exceso.']::text[], 'intermedio', 'Trabaja pecho, tríceps y core con el peso corporal, mejorando fuerza y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7884'),
('7c64f49c-5ef8-59b9-bffd-0388f6313bb9', 'Remo alto en máquina con agarre inverso', ARRAY['Siéntate con el pecho contra el pad y agarra las asas con las palmas hacia arriba.', 'Tira hacia ti llevando los codos abajo y atrás.', 'Junta las escápulas al final del recorrido y vuelve despacio.', 'Evita tirar con los brazos sin activar la espalda o encoger los hombros.']::text[], 'principiante', 'Enfoca dorsales y espalda alta con un ángulo alto que favorece la tracción vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4378'),
('68420f6d-e451-57c9-a5c8-c860d4fca7ff', 'Jalón lateral en máquina con agarre inverso', ARRAY['Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.', 'Tira de las asas hacia el pecho, liderando con los codos y juntando los omóplatos.', 'Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales y bíceps con un agarre que aumenta el recorrido y la activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2736'),
('8d8a316d-2da0-538a-b02a-0b9fc801b67c', 'Curl predicador en máquina con agarre inverso', ARRAY['Ajusta la altura del asiento y colócate en la máquina de palanca.', 'Sujeta las asas con un agarre supino, con las palmas hacia arriba.', 'Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos.', 'Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el bíceps y el antebrazo desde un ángulo que enfatiza el control del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1616'),
('9e4ddd18-2944-56ee-a82f-a1febf2f8343', 'Remo vertical en máquina con agarre inverso', ARRAY['Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.', 'Sujeta las asas con un agarre supino, con las palmas hacia arriba.', 'Mantén la espalda recta y activa el core.', 'Tira de las asas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la espalda alta y los bíceps con una tracción vertical guiada y estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1348'),
('427c6175-6f75-524a-b990-951d33e7c782', 'Hiperextensión inversa en máquina', ARRAY['Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies.', 'Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla.', 'Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.', 'Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece glúteos, isquios y zona lumbar, útil para estabilidad y salud de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0593'),
('42efe259-12fc-5441-830f-1fe292f2da61', 'Press de hombros inverso en máquina', ARRAY['Siéntate con la espalda apoyada y agarra las asas a la altura de los hombros.', 'Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos.', 'Baja controlando hasta la altura inicial.', 'Evita arquear la espalda o subir los hombros hacia las orejas.']::text[], 'principiante', 'Desarrolla deltoides y tríceps con un empuje guiado que también activa el pecho superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4174'),
('d16d1b6e-4bef-5f42-99d7-b335a9828a0e', 'Remo en T invertido en máquina', ARRAY['Ajusta la altura del asiento y la posición de la placa para los pies en la máquina de palanca.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y activa el core.', 'Tira de las asas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los bíceps con una tracción horizontal que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1349'),
('5bb6590f-1b9b-54e3-9960-0180d0f49f03', 'Sentadilla hack inversa en máquina', ARRAY['Colócate de espaldas al respaldo con los hombros bajo las almohadillas y los pies en la plataforma.', 'Baja flexionando rodillas y caderas hasta unos 90 grados sin despegar la espalda.', 'Empuja con los talones para subir controlando el movimiento y exhala al empujar.', 'Evita que las rodillas se metan hacia dentro y no bloquees del todo al final.']::text[], 'principiante', 'Trabaja cuádriceps con apoyo de glúteos y femorales, ideal para ganar fuerza y volumen en las piernas sin cargar la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5784'),
('7f82ce35-8fd0-5831-a680-eec39ef9badd', 'Peso muerto rumano en máquina', ARRAY['Ajusta la máquina y agarra las asas con los brazos extendidos y la espalda recta.', 'Lleva la cadera hacia atrás bajando el peso pegado a las piernas con rodillas ligeramente flexionadas.', 'Nota el estiramiento en los femorales y sube apretando glúteos mientras exhalas.', 'Evita redondear la espalda o bajar más de lo que tu flexibilidad permite.']::text[], 'principiante', 'Fortalece femorales y glúteos con un patrón de bisagra de cadera, mejorando la fuerza posterior y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8712'),
('d4a0e04d-4a84-52d1-8f9d-93686b020363', 'Gemelos rotativos en máquina', ARRAY['Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.', 'Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.', 'Sujeta las asas o los lados de la máquina para mayor estabilidad.', 'Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los gemelos y el sóleo con rotación del pie, mejorando fuerza y estabilidad del tobillo en distintos ángulos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2315'),
('b87e4af1-4291-5fc3-8424-b202a817b405', 'Remo en máquina', ARRAY['Siéntate con el pecho contra el apoyo y agarra las asas con los brazos extendidos.', 'Tira de los codos hacia atrás juntando las escápulas sin encoger los hombros.', 'Vuelve controlando el peso hasta estirar los brazos y exhala al tirar.', 'Evita usar impulso del tronco o tirar solo con los bíceps.']::text[], 'principiante', 'Desarrolla dorsales y espalda alta, mejorando la postura y la fuerza de tracción con apoyo estable del torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1237'),
('d0df7838-2c67-5de5-9e46-20edcdf51653', 'Apertura posterior inclinado en máquina', ARRAY['Siéntate inclinado con el pecho apoyado y agarra las asas con los codos algo flexionados.', 'Abre los brazos hacia los lados llevándolos a la altura de los hombros sin encogerlos.', 'Vuelve despacio controlando el peso y exhala al abrir.', 'Evita balancear el tronco o usar demasiado peso para no perder tensión.']::text[], 'principiante', 'Aísla el deltoides posterior y la espalda alta, corrigiendo desequilibrios y mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5527'),
('59beee66-63e8-5a7f-a7f9-d4d3955fc9b6', 'Elevación de gemelos sentado en máquina', ARRAY['Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.', 'Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.', 'Sujeta las asas o los lados del asiento para mayor estabilidad.', 'Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el sóleo y los gemelos desde una posición estable, mejorando la fuerza y resistencia del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0594'),
('a014eab5-17aa-5743-b6e1-711af5ecea10', 'Abdominal sentado en máquina', ARRAY['Siéntate en la máquina de palanca con la espalda apoyada en la almohadilla y los pies planos en el suelo.', 'Sujeta las asas o coloca las manos sobre las almohadillas laterales para mayor apoyo.', 'Activa el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla se mueva contigo.', 'Cuando la parte superior del cuerpo esté en un ángulo de 45 grados, contrae el abdomen y haz un crunch hacia adelante, llevando el pecho hacia las rodillas.', 'Haz una pausa breve en lo alto, luego suelta lentamente y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el recto abdominal y los oblicuos con un movimiento guiado, útil para ganar fuerza en el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1452'),
('beed17c9-d69d-5013-b347-ae863d94664d', 'Fondos sentado en máquina', ARRAY['Ajusta la altura del asiento de modo que tus pies queden planos en el suelo y tus rodillas formen un ángulo de 90 grados.', 'Agarra las asas de la máquina de palanca con las palmas hacia abajo y los brazos completamente extendidos.', 'Baja lentamente el cuerpo flexionando los codos hasta que tus brazos queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla tríceps con apoyo de pecho y hombros, ideal para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1451'),
('e0d982d9-a2c7-503b-8541-c2788b7d98dc', 'Abdominal completo sentado en máquina', ARRAY['Siéntate con la espalda apoyada y sujeta las asas o el soporte indicado.', 'Flexiona el tronco llevando el pecho hacia las rodillas sin tirar del cuello.', 'Sube controlando y exhala al contraer, volviendo despacio a la posición inicial.', 'Evita usar impulso o arquear la zona lumbar al bajar.']::text[], 'principiante', 'Trabaja el core completo con flexión de tronco y cadera, mejorando la fuerza abdominal y la estabilidad del centro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3881'),
('c981a149-f2c9-54ed-8d8b-3ec0af5bfbe5', 'Good morning sentado en máquina', ARRAY['Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés.', 'Sujeta las asas o los lados del asiento para mayor estabilidad.', 'Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo.', 'Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece glúteos y femorales con un patrón de bisagra guiado, mejorando la fuerza posterior y la estabilidad lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3759'),
('8f1e5f86-c02c-5d49-84c5-8e747961964f', 'Press de hombros sentado con agarre martillo en máquina', ARRAY['Siéntate con la espalda apoyada y agarra las asas con las palmas enfrentadas.', 'Empuja hacia arriba extendiendo los brazos sin bloquear del todo los codos.', 'Baja controlando hasta la altura de los hombros y exhala al empujar.', 'Evita arquear la espalda o encoger los hombros al subir.']::text[], 'principiante', 'Desarrolla deltoides con apoyo de tríceps y pecho superior, ganando fuerza y volumen en el hombro de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2962'),
('89457e67-f0a0-5e3d-accc-44288c7f1907', 'Abducción de cadera sentado en máquina', ARRAY['Ajusta la altura del asiento de modo que tus rodillas formen un ángulo de 90 grados.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.', 'Coloca las manos en las asas laterales para mayor estabilidad.', 'Activa los abductores y empuja lentamente las piernas hacia afuera, alejándolas de la línea media del cuerpo.', 'Haz una pausa al final del movimiento y luego junta lentamente las piernas de nuevo hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los abductores y glúteos, mejorando la estabilidad de la cadera y la fuerza en movimientos laterales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0597'),
('62119873-817d-548a-8fef-a80ac232756d', 'Aducción de cadera sentado en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.', 'Coloca los pies sobre los apoyapiés y agarra las asas para mayor estabilidad.', 'Activa los aductores y junta lentamente las piernas, apretando la parte interna de los muslos.', 'Haz una pausa breve en el punto máximo de contracción, luego vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los aductores con apoyo de glúteos y femorales, mejorando la estabilidad y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0598'),
('1ec76f65-0be4-54cd-acc6-2897e5131fe1', 'Prensa de piernas horizontal sentado en máquina', ARRAY['Siéntate con la espalda y la cadera bien apoyadas y los pies en la plataforma al ancho de hombros.', 'Empuja la plataforma extendiendo las piernas sin bloquear del todo las rodillas.', 'Baja controlando hasta unos 90 grados de flexión y exhala al empujar.', 'Evita despegar la zona lumbar o juntar las rodillas hacia dentro.']::text[], 'principiante', 'Trabaja cuádriceps con apoyo de glúteos y femorales, permitiendo cargar las piernas con menor estrés lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3768'),
('5097c11e-9266-5e9e-b655-feee5e7e95b2', 'Abdominal lateral sentado en máquina', ARRAY['Siéntate con la espalda apoyada y sujeta el soporte con el torso alineado.', 'Flexiona el tronco hacia un lado llevando el codo hacia la cadera sin girar.', 'Vuelve despacio controlando el movimiento y exhala al contraer.', 'Evita tirar con el cuello o usar impulso para no perder tensión.']::text[], 'principiante', 'Enfoca oblicuos y core con flexión lateral guiada, mejorando la fuerza y el control del tronco en rotaciones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3882'),
('d6c47f39-885d-55ac-b38c-f9f0af1091fa', 'Curl femoral sentado en máquina', ARRAY['Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.', 'Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos.', 'Sujeta las asas a los lados de la máquina para mayor apoyo.', 'Manteniendo la parte superior de las piernas inmóvil, exhala y flexiona las piernas hacia arriba todo lo que puedas.', 'Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales.', 'Inhala y baja lentamente la palanca de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los isquiotibiales en posición sentada y mejora la fuerza y el control de la flexión de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0599'),
('62a012d7-5130-50cb-ad8d-76a27bfb48ea', 'Curl femoral sentado en máquina con discos', ARRAY['Ajusta el respaldo y el rodillo para que la rodilla quede alineada con el eje de la máquina.', 'Coloca los discos en el soporte y apoya los tobillos sobre el rodillo acolchado.', 'Flexiona las rodillas llevando los talones hacia los glúteos mientras sueltas el aire.', 'Baja la carga de forma controlada en dos o tres segundos sin dejar caer el peso.', 'Evita despegar la espalda del respaldo o impulsarte con el tronco.']::text[], 'principiante', 'Trabaja los isquiotibiales con carga adicional y refuerza también glúteos y gemelos en la flexión de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8604'),
('6f3097a9-50c6-512a-8cd6-91c0ef4225d8', 'Extensión de piernas sentado en máquina', ARRAY['Siéntate con la espalda apoyada y ajusta el rodillo justo por encima de los tobillos.', 'Alinea la rodilla con el eje de giro de la máquina antes de empezar.', 'Extiende las piernas hasta casi bloquear la rodilla mientras sueltas el aire.', 'Baja el peso despacio, controlando el retorno, sin dejar que golpee la pila.', 'Evita balancear el tronco o usar impulso para subir la carga.']::text[], 'principiante', 'Aísla el cuádriceps y sirve para ganar fuerza y control en la extensión de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3386'),
('d029b07a-26af-588e-8456-54c6cb6f2a06', 'Abdominal con elevación de piernas sentado en máquina', ARRAY['Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.', 'Sujeta las asas o las barras laterales para mayor estabilidad.', 'Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con un movimiento guiado que mejora la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0600'),
('e8917dfb-e80d-5aa1-b6de-e9e3e5dc8923', 'Elevación de gemelos sentado a una pierna en máquina', ARRAY['Siéntate y coloca la almohadilla sobre el muslo, con la punta del pie en el borde de la plataforma.', 'Apoya solo una pierna y deja la otra fuera del soporte.', 'Eleva el talón lo máximo posible mientras sueltas el aire y mantén un segundo arriba.', 'Baja el talón despacio hasta notar el estiramiento del gemelo sin rebotar.', 'Evita girar el pie hacia fuera o hacer rebotes rápidos para ganar recorrido.']::text[], 'principiante', 'Fortalece el sóleo y los gemelos de forma unilateral, mejorando el equilibrio y la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1216'),
('20a541ac-ed1d-531a-807c-c1594ab41fcd', 'Sentadilla sentado a una pierna en máquina', ARRAY['Siéntate con la espalda apoyada y coloca un pie en la plataforma, alineado con la cadera.', 'Ajusta el recorrido para que la rodilla no pase de forma forzada al bajar.', 'Empuja con el pie extendiendo la pierna mientras sueltas el aire.', 'Baja de forma controlada hasta unos 90 grados de flexión de rodilla.', 'Evita bloquear la rodilla de golpe o dejar que la cadera se despegue del asiento.']::text[], 'principiante', 'Trabaja el cuádriceps de forma unilateral con apoyo de glúteos, isquios y gemelos en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1573'),
('dcd1a48a-27ca-57b2-9a99-b751025087e6', 'Sentadilla amplia sentado a una pierna en máquina', ARRAY['Siéntate con la espalda apoyada y coloca un pie en la plataforma con la punta ligeramente hacia fuera.', 'Separa un poco la rodilla de la línea del cuerpo para abrir la cadera.', 'Empuja extendiendo la pierna mientras sueltas el aire, sin bloquear la rodilla.', 'Baja despacio hasta notar el estiramiento del cuádriceps y el aductor.', 'Evita que la rodilla se vaya hacia dentro o que el pie pierda el apoyo.']::text[], 'principiante', 'Trabaja el cuádriceps con una postura más abierta que implica también aductores, glúteos e isquios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1572'),
('af101823-0c8b-5b84-b67f-a6500fccc2be', 'Apertura invertida sentado en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.', 'Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados.', 'Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.', 'Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Refuerza la parte posterior del hombro y la espalda alta, mejorando la postura y la salud escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0602'),
('3194808e-14c4-5d18-acc1-959dd7e07609', 'Abdominal lateral derecho sentado en máquina', ARRAY['Siéntate con la espalda apoyada y ajusta el soporte para que quede a la altura del hombro derecho.', 'Sujeta las asas y mantén el tronco estable antes de iniciar el movimiento.', 'Flexiona el tronco hacia la derecha mientras sueltas el aire, sin tirar con los brazos.', 'Vuelve despacio a la posición inicial controlando el retorno.', 'Evita girar el tronco o usar impulso de cadera para completar la repetición.']::text[], 'principiante', 'Trabaja el oblicuo y el core de forma unilateral, útil para la estabilidad y el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3883'),
('f42b8333-789c-5b65-aa0f-4dfc50bbdddc', 'Remo sentado en máquina', ARRAY['Ajusta la altura del asiento y los apoyapiés a una posición cómoda.', 'Siéntate en la máquina con el pecho apoyado en la almohadilla y los pies sobre los apoyapiés.', 'Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.', 'Mantén la espalda recta y el core activado.', 'Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte alta del movimiento.', 'Suelta lentamente las asas y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece la espalda alta y los bíceps, mejorando la postura y la fuerza de tracción horizontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1350'),
('167a9489-8607-55cd-afa4-8eedeb090cee', 'Retracción escapular sentado en máquina con discos', ARRAY['Siéntate con el pecho apoyado o la espalda recta y sujeta las asas con los brazos extendidos.', 'Coloca los discos en el soporte y ajusta la carga según tu nivel.', 'Junta las escápulas llevando los codos hacia atrás mientras sueltas el aire.', 'Mantén un segundo la retracción y vuelve despacio a la posición inicial.', 'Evita encoger los hombros hacia las orejas o arquear la zona lumbar.']::text[], 'principiante', 'Activa la espalda alta y los romboides para mejorar la postura y el control de las escápulas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11056'),
('ca03b829-38d4-55c1-a9cc-f19d915f9bc4', 'Prensa de gemelos a una pierna sentado en máquina', ARRAY['Siéntate y coloca la punta de un pie en la plataforma, con la almohadilla sobre el muslo.', 'Alinea la rodilla con el eje de la máquina y apoya bien el pie.', 'Empuja la plataforma extendiendo el tobillo mientras sueltas el aire.', 'Baja el talón despacio hasta notar el estiramiento del gemelo sin rebotar.', 'Evita girar el pie o hacer rebotes rápidos para ganar recorrido.']::text[], 'principiante', 'Trabaja el sóleo y el gemelo de forma unilateral, mejorando la fuerza y la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7177'),
('81b3fc17-1bba-5338-b105-c859b5e8838e', 'Curl de pierna sentado a una pierna en máquina con discos', ARRAY['Ajusta el respaldo y el rodillo para que la rodilla quede alineada con el eje de la máquina.', 'Coloca los discos en el soporte y apoya un tobillo sobre el rodillo acolchado.', 'Flexiona la rodilla llevando el talón hacia el glúteo mientras sueltas el aire.', 'Baja la carga de forma controlada en dos o tres segundos sin dejarla caer.', 'Evita despegar la espalda del respaldo o impulsarte con el tronco.']::text[], 'principiante', 'Aísla los isquiotibiales de una pierna con carga adicional, mejorando fuerza y control unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10763'),
('669e36aa-4eab-501f-8711-94d31beb32f0', 'Prensa de una pierna sentado en máquina', ARRAY['Siéntate con la espalda apoyada y coloca un pie en la plataforma a la anchura de la cadera.', 'Ajusta el asiento para que la rodilla no pase de forma forzada al bajar.', 'Empuja la plataforma extendiendo la pierna mientras sueltas el aire.', 'Baja de forma controlada hasta unos 90 grados de flexión de rodilla.', 'Evita bloquear la rodilla de golpe o dejar que la cadera se despegue del asiento.']::text[], 'principiante', 'Trabaja el cuádriceps de forma unilateral con apoyo de glúteos, isquios y gemelos en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7107'),
('ce92c149-a027-5516-98d4-a87f6489608c', 'Sentadilla sentado en máquina', ARRAY['Siéntate con la espalda apoyada y coloca los pies en la plataforma a la anchura de la cadera.', 'Ajusta el recorrido para que la rodilla no pase de forma forzada al bajar.', 'Empuja con los pies extendiendo las piernas mientras sueltas el aire.', 'Baja de forma controlada hasta unos 90 grados de flexión de rodilla.', 'Evita bloquear las rodillas de golpe o despegar la cadera del asiento.']::text[], 'principiante', 'Trabaja el cuádriceps con apoyo de glúteos, isquios y aductores en un movimiento guiado y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1232'),
('e1cc174e-4c23-5f3a-a815-610aca0679a9', 'Elevación de gemelos sentado en prensa', ARRAY['Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros.', 'Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde.', 'Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas.', 'Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas.', 'Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los gemelos para ganar fuerza y volumen en la pantorrilla, con apoyo estable en la máquina.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1385'),
('dd689a17-96aa-5b69-ad26-1f375eee2f89', 'Giro sentado en máquina', ARRAY['Siéntate con la espalda apoyada y los pies fijos en el suelo.', 'Agarra las asas y mantén el pecho alto durante todo el recorrido.', 'Gira el tronco hacia un lado de forma controlada y vuelve al centro.', 'Evita tirar con los brazos: el movimiento nace del abdomen.', 'Respira al girar y no bloquees la respiración en ningún momento.']::text[], 'principiante', 'Trabaja abdomen y oblicuos para ganar control rotacional y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1453'),
('97374f21-cee6-58cb-a214-85fbeaa1f5b0', 'Sentadilla amplia en máquina', ARRAY['Coloca los pies en la plataforma más anchos que los hombros, con las puntas ligeramente hacia fuera.', 'Apoya la espalda en el respaldo y sujeta las asas.', 'Baja flexionando las rodillas en línea con los pies, sin que se metan hacia dentro.', 'Empuja con los talones para subir y evita bloquear las rodillas arriba.', 'Respira al bajar y controla el ascenso sin rebotar.']::text[], 'principiante', 'Fortalece cuádriceps, glúteos y aductores con una sentadilla guiada de base ancha.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1574'),
('de58c932-e074-5af5-a22f-be5eb27cfa09', 'Press de hombros en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.', 'Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros.', 'Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.', 'Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Desarrolla la fuerza de los hombros y el tríceps con un recorrido guiado y seguro en máquina.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0603'),
('344d28f9-e5af-5210-b2d2-770d7aece717', 'Encogimientos en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina de palanca con la espalda apoyada en la almohadilla.', 'Sujeta las asas con un agarre prono y mantén los brazos rectos.', 'Manteniendo la espalda recta, eleva los hombros hacia las orejas tan alto como sea posible.', 'Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece los trapecios para mejorar la postura y la estabilidad de cuello y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0604'),
('02e8c3d0-4500-5ca5-941e-3c8cd2a59fe0', 'Abducción de cadera en máquina', ARRAY['Siéntate con la espalda apoyada y coloca las piernas en los soportes.', 'Abre las piernas hacia fuera de forma controlada hasta notar tensión en el glúteo.', 'Evita arquear la espalda o impulsarte con el tronco.', 'Aguanta un instante arriba y vuelve despacio sin dejar caer el peso.', 'Respira al abrir y controla el retorno en cada repetición.']::text[], 'principiante', 'Refuerza los abductores y glúteos para estabilizar la cadera y mejorar la alineación de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1034'),
('55edfcfc-1b63-5b9d-a69c-8ad81064b44b', 'Aducción de cadera en máquina', ARRAY['Siéntate con la espalda apoyada y las piernas abiertas en los soportes.', 'Junta las piernas de forma controlada hasta notar la contracción interna.', 'Mantén el tronco quieto y evita balancearte para ganar impulso.', 'Vuelve despacio a la posición inicial sin dejar caer el peso.', 'Respira al cerrar las piernas y controla la apertura.']::text[], 'principiante', 'Trabaja los aductores y la cara interna del muslo para mejorar la estabilidad y el cierre de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1035'),
('feec4323-3799-53c7-ac0a-68459d79b626', 'Apertura posterior a un brazo en máquina', ARRAY['Siéntate de lado con el pecho apoyado y el brazo en el soporte.', 'Empuja el brazo hacia atrás en arco, con el codo ligeramente flexionado.', 'Evita encoger el hombro o tirar con la espalda baja.', 'Vuelve despacio y controla el peso en todo el recorrido.', 'Respira al abrir y mantén el cuello relajado.']::text[], 'principiante', 'Aísla el deltoides posterior y la parte alta de la espalda para equilibrar el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8990'),
('aa458dcc-edb0-5392-a31c-a983a968eacc', 'Curl predicador a un brazo en máquina', ARRAY['Apoya el brazo sobre el soporte con la axila bien pegada al borde.', 'Sube el peso flexionando el codo sin despegar el brazo del apoyo.', 'Evita extender del todo el codo abajo para no forzar la articulación.', 'Baja despacio controlando el peso hasta casi la extensión completa.', 'Respira al subir y mantén la muñeca neutra.']::text[], 'principiante', 'Aísla el bíceps y el braquial con el brazo apoyado para evitar balanceos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9862'),
('e5bbd65a-3114-5e44-bb7e-6805f2d44f50', 'Jalón lateral a un brazo con agarre inverso', ARRAY['Siéntate con el pecho alto y agarra el asa con la palma hacia ti.', 'Tira del asa hacia la cadera llevando el codo pegado al costado.', 'Evita encoger el hombro o tirar con el tronco hacia atrás.', 'Vuelve despacio estirando el brazo sin soltar la tensión.', 'Respira al tirar y mantén el core activo.']::text[], 'principiante', 'Trabaja el dorsal y la espalda alta con un agarre que enfatiza el bíceps.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11309'),
('e39a1347-35a6-5520-a14d-b2f319d3e689', 'Extensión de pierna a una pierna en máquina', ARRAY['Siéntate con la espalda apoyada y el rodillo sobre el empeine.', 'Extiende la rodilla de forma controlada hasta casi bloquearla.', 'Evita dar tirones o usar impulso con la cadera.', 'Baja despacio sin dejar caer el peso de golpe.', 'Respira al extender y mantén el abdomen activo.']::text[], 'principiante', 'Aísla el cuádriceps de una pierna para corregir desequilibrios y ganar fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5178'),
('21e04bf8-9af0-5ea6-a9d0-da54edb7679d', 'Hip thrust a una pierna en máquina', ARRAY['Coloca la espalda alta apoyada y un pie en la plataforma.', 'Empuja con el talón para extender la cadera hasta alinear el tronco.', 'Evita arquear la lumbar en exceso: aprieta el glúteo arriba.', 'Baja despacio sin perder la alineación de la rodilla.', 'Respira al empujar y mantén el core firme.']::text[], 'principiante', 'Fortalece el glúteo de forma unilateral y mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2148'),
('84ef55b5-50f4-58a0-939c-3e9519fe0a3c', 'Elevación de puntas sentado en máquina', ARRAY['Siéntate con la espalda apoyada y los pies en la plataforma.', 'Eleva las puntas de los pies de forma controlada contra la resistencia.', 'Evita mover las rodillas o impulsarte con el tronco.', 'Baja despacio hasta notar el estiramiento en la pantorrilla.', 'Respira al elevar y controla el retorno.']::text[], 'principiante', 'Trabaja el sóleo y la zona del tobillo para mejorar la fuerza y estabilidad del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9509'),
('31a009e6-c1f4-5339-a27a-a8bd11d579ec', 'Sentadilla en máquina', ARRAY['Coloca los pies en la plataforma a la anchura de los hombros.', 'Apoya la espalda en el respaldo y sujeta las asas.', 'Baja flexionando las rodillas hasta donde controles sin perder la postura.', 'Empuja con los talones para subir sin bloquear las rodillas.', 'Respira al bajar y evita que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Fortalece cuádriceps, glúteos e isquios con un patrón de sentadilla guiado y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1875'),
('a4004e10-8a3c-5d17-a5c7-929098b04bf2', 'Press de pecho sentado en máquina de placas', ARRAY['Siéntate con la espalda apoyada y las asas a la altura del pecho.', 'Empuja hacia delante extendiendo los brazos sin bloquear los codos.', 'Evita encoger los hombros o sacar el pecho en exceso.', 'Vuelve despacio hasta notar el estiramiento del pectoral.', 'Respira al empujar y mantén las muñecas alineadas.']::text[], 'principiante', 'Trabaja el pectoral, el tríceps y el hombro para ganar fuerza de empuje de forma guiada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10671'),
('a89e0f47-1301-5f51-9cd2-7c4c84812517', 'Press inclinado en máquina', ARRAY['Ajusta el asiento para que los agarres queden a la altura del pecho alto.', 'Empuja las asas hacia delante sin bloquear del todo los codos.', 'Exhala al empujar e inhala al volver de forma controlada.', 'Evita arquear la espalda o sacar los hombros hacia delante.']::text[], 'principiante', 'Trabaja la parte superior del pecho y los tríceps, ideal para ganar fuerza y volumen en el torso de forma guiada y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10669'),
('dbf84556-7de2-51ee-99dc-d292e5c7e9f3', 'Press inclinado a un brazo en máquina', ARRAY['Siéntate con la espalda apoyada y agarra el asa con una mano.', 'Empuja hacia delante manteniendo el tronco firme y sin girar.', 'Controla la vuelta hasta notar estiramiento en el pecho.', 'Evita rotar el torso o despegar la espalda del respaldo.']::text[], 'principiante', 'Fortalece el pecho superior de forma unilateral, implicando también el core para mantener el tronco estable durante el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10670'),
('83f9f020-90f3-5b7c-98c9-80e6895e42c1', 'Press de pecho sentado a un brazo en máquina de placas', ARRAY['Ajusta el asiento y agarra el asa con una sola mano.', 'Empuja al frente sin dejar que el hombro se suba.', 'Vuelve despacio controlando el recorrido completo.', 'Mantén el abdomen activo para no girar el torso.']::text[], 'principiante', 'Trabaja el pectoral de forma unilateral y exige al core estabilizar el tronco, corrigiendo desequilibrios entre lados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10672'),
('a9e1af45-db89-5b69-99af-fe119cf965c4', 'Empuje de cadera con piernas escalonadas en máquina', ARRAY['Coloca un pie adelantado y otro atrás sobre la plataforma.', 'Apoya la espalda en el respaldo y empuja la cadera hacia delante.', 'Aprieta el glúteo arriba y baja controlando el movimiento.', 'Evita arquear la zona lumbar en exceso al empujar.']::text[], 'principiante', 'Activa glúteos y femorales con una pierna adelantada, mejorando la fuerza de cadera y la estabilidad en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11054');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('3456a775-041e-5283-878b-52a4bae471c7', 'Elevación de gemelos de pie en máquina', ARRAY['Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros.', 'Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad.', 'Eleva los talones tan alto como puedas extendiendo los tobillos.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los gemelos y el sóleo, mejorando la fuerza y el volumen de la pantorrilla con un recorrido guiado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0605'),
('30dc8bd3-8887-54f8-82dd-967d9917029b', 'Press de pecho de pie en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo.', 'Agarra las asas con un agarre prono y coloca las manos a la altura del pecho.', 'Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados.', 'Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el pectoral y los hombros desde una posición erguida, implicando el core para mantener el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3758'),
('8f4b4f4b-d88c-5778-9d6b-e2a842ad07e3', 'Extensión de cadera de pie en máquina', ARRAY['Colócate de pie con el muslo apoyado en la almohadilla.', 'Empuja la pierna hacia atrás apretando el glúteo.', 'Vuelve despacio sin dejar caer la pierna de golpe.', 'Evita arquear la espalda o balancear el tronco.']::text[], 'principiante', 'Fortalece el glúteo y los femorales llevando la pierna atrás, útil para potenciar la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1031'),
('648880ac-d632-58db-8cbf-e2c52af43c79', 'Elevación lateral de pie en máquina', ARRAY['Colócate de pie con el brazo apoyado en la palanca.', 'Eleva el brazo hacia el lado hasta la altura del hombro.', 'Baja controlando el movimiento sin dejar caer el peso.', 'Evita encoger el hombro o usar impulso del cuerpo.']::text[], 'principiante', 'Aísla el deltoides lateral para ganar anchura de hombros, con un recorrido guiado que reduce el riesgo de lesión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8847'),
('83d263ba-17fe-5c72-af6b-bf0063e29555', 'Curl de pierna de pie en máquina', ARRAY['Apoya el muslo en la almohadilla y coloca el tobillo en el rodillo.', 'Flexiona la rodilla llevando el talón hacia el glúteo.', 'Vuelve despacio controlando la bajada.', 'Evita mover la cadera o arquear la espalda.']::text[], 'principiante', 'Aísla los isquiotibiales flexionando la rodilla, mejorando la fuerza posterior del muslo y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4347'),
('ed45a931-8955-575c-bc7b-b7208f73e54f', 'Elevación de pierna de pie en máquina', ARRAY['Colócate de pie con la espalda apoyada en la máquina.', 'Eleva la rodilla hacia delante de forma controlada.', 'Baja despacio sin dejar caer la pierna.', 'Evita inclinar el tronco o usar impulso.']::text[], 'principiante', 'Trabaja el cuádriceps y los flexores de cadera elevando la rodilla, útil para la fuerza funcional de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1036'),
('c6208d0c-b122-5297-a306-573c58429a20', 'Apertura de pecho de pie en máquina', ARRAY['Colócate de pie con los antebrazos en las almohadillas.', 'Junta los brazos al frente apretando el pecho.', 'Vuelve despacio hasta notar estiramiento sin forzar.', 'Evita encoger los hombros o bloquear los codos.']::text[], 'principiante', 'Aísla el pectoral juntando los brazos, mejorando la definición y la fuerza del pecho con un recorrido guiado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9398'),
('9dda2a5a-a408-5b8d-be82-2b22604337e7', 'Patada trasera de pie en máquina', ARRAY['Apoya el torso en la máquina y coloca el pie en la palanca.', 'Empuja la pierna hacia atrás apretando el glúteo.', 'Vuelve despacio controlando el recorrido.', 'Evita arquear la lumbar o girar la cadera.']::text[], 'principiante', 'Aísla el glúteo llevando la pierna atrás, reforzando la extensión de cadera y el tono de la zona posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1037'),
('090d5846-1629-575b-845f-f8d196cc3757', 'Escaladora', ARRAY['Sube a la máquina y agarra las asas con suavidad.', 'Pisa alternando las piernas a un ritmo constante.', 'Mantén el tronco erguido sin apoyarte en las asas.', 'Regula la intensidad para poder mantener la respiración.']::text[], 'principiante', 'Mejora la resistencia cardiovascular y la fuerza de piernas simulando subir escaleras, con trabajo de glúteos y gemelos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0938'),
('1efe4918-a179-589b-a7e2-dbdc238a7e0a', 'Remo en barra T agarre cerrado', ARRAY['Apoya el pecho en el soporte y agarra las asas cerradas.', 'Tira hacia el abdomen juntando las escápulas.', 'Vuelve despacio controlando el estiramiento.', 'Evita tirar con los brazos o encoger los hombros.']::text[], 'principiante', 'Fortalece la espalda alta y los dorsales con un agarre cerrado, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11880'),
('889dbb00-aa5d-54ba-a99a-e2666367eb11', 'Peso muerto rumano en barra T', ARRAY['Agarra la barra con la espalda recta y rodillas ligeramente flexionadas.', 'Baja la barra llevando la cadera atrás sin curvar la espalda.', 'Sube empujando la cadera hacia delante y apretando glúteos.', 'Evita redondear la lumbar o bajar más de lo que controlas.']::text[], 'principiante', 'Trabaja los isquiotibiales y glúteos con un movimiento de bisagra de cadera, mejorando la fuerza posterior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5327'),
('ad4c6af2-6454-5855-8ff2-7b05c48eaa3f', 'Remo en T en máquina', ARRAY['Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y activa el core.', 'Tira de las asas hacia el torso, juntando los omóplatos.', 'Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la espalda alta y los bíceps para mejorar la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0606'),
('e5b960f6-6f27-58f8-9628-ff29605ced74', 'Remo en T con agarre inverso en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y activa el core.', 'Tira de las asas hacia el pecho, juntando los omóplatos.', 'Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Enfatiza la espalda alta y los bíceps con un agarre que aumenta el recorrido y la activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1351'),
('786cc95c-843d-5ffb-8d35-e7246d1e133c', 'Rotación de torso en máquina', ARRAY['Ajusta el asiento y la altura del pivote para que quede a la altura de tu pecho.', 'Siéntate con la espalda apoyada y sujeta los manerales con los brazos semiflexionados.', 'Gira el tronco de forma controlada hacia un lado sin mover las caderas.', 'Vuelve al centro y repite hacia el otro lado, exhalando en cada rotación.', 'Evita tirar con los brazos o usar impulso; el movimiento nace del core.']::text[], 'principiante', 'Trabaja abdominales y oblicuos rotando el tronco contra resistencia, mejorando la fuerza del core y la estabilidad de la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10065'),
('7a1bacea-fadb-5de4-95c7-eea75c68469d', 'Abdominal total en máquina', ARRAY['Ajusta el respaldo y el apoyo de pies según tu altura y siéntate con la espalda pegada.', 'Sujeta las asas y coloca los pies firmes bajo los rodillos.', 'Flexiona el tronco hacia delante contrayendo el abdomen y exhalando.', 'Vuelve despacio a la posición inicial sin dejar que el peso te arrastre.', 'Evita tirar con los brazos o el cuello; el movimiento debe salir del abdomen.']::text[], 'principiante', 'Fortalece el recto abdominal y los oblicuos con flexión de tronco guiada, útil para ganar fuerza en el core de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1857'),
('4728fee1-a70c-51f6-a0dc-60a87565bbb4', 'Fondos de tríceps en máquina', ARRAY['Ajusta el asiento para que las asas queden a la altura de tus caderas y siéntate erguido.', 'Sujeta las asas con los codos pegados al cuerpo y los antebrazos alineados.', 'Empuja hacia abajo extendiendo los codos mientras exhalas.', 'Sube controlando el peso hasta que los codos vuelvan a unos 90 grados.', 'Evita mover los hombros o separar los codos del torso durante el recorrido.']::text[], 'principiante', 'Aísla el tríceps con un empuje guiado, ideal para ganar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1871'),
('138c42b2-68ed-5d73-9e2c-24f9c627250d', 'Extensión de tríceps en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.', 'Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti.', 'Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos.', 'Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla el tríceps para ganar fuerza y tono en la parte posterior del brazo de forma controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0607'),
('2646c8e3-c152-5288-8bb2-a42b88a5f0f2', 'Giro en máquina', ARRAY['Colócate en la máquina con los pies firmes y el cuerpo alineado con el eje de giro.', 'Sujeta las asas o apoyos con los brazos relajados y el abdomen activo.', 'Gira el tronco lentamente hacia un lado sin mover las caderas.', 'Regresa al centro con control y repite hacia el otro lado.', 'Evita girar rápido o con impulso; mantén el movimiento lento y respirando.']::text[], 'principiante', 'Activa oblicuos y zona lumbar con un giro controlado del tronco, mejorando la estabilidad y la fuerza rotacional del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0608'),
('7f141fbe-51f3-50d6-98da-67e538074b95', 'Remo unilateral en máquina', ARRAY['Ajusta la altura del asiento y colócate frente a la máquina.', 'Agarra las asas con un agarre prono y mantén la espalda recta.', 'Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí.', 'Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Permite trabajar cada lado de la espalda alta de forma independiente, corrigiendo desequilibrios y mejorando la tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1313'),
('362b2850-1ba7-55e4-bbf5-b31f236105a2', 'Peso muerto a una pierna en máquina', ARRAY['Colócate en la máquina con una pierna apoyada y la otra ligeramente elevada.', 'Sujeta las asas y mantén la espalda recta con el abdomen activo.', 'Lleva la cadera hacia atrás bajando el torso mientras la pierna libre se extiende detrás.', 'Empuja con el glúteo para volver arriba exhalando y sin arquear la lumbar.', 'Evita redondear la espalda o perder el equilibrio; usa un peso ligero al principio.']::text[], 'principiante', 'Trabaja glúteos y femorales con un patrón a una pierna que mejora el equilibrio y la fuerza unilateral de la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8799'),
('a0d48bf4-fb80-57b0-9a30-f5254740cefa', 'Sentadilla a una pierna en máquina', ARRAY['Coloca un pie en la plataforma y el otro apoyado ligeramente detrás o elevado.', 'Ajusta la espalda contra el respaldo y sujeta las asas.', 'Baja flexionando la rodilla de la pierna de trabajo con control.', 'Empuja con el pie para subir exhalando sin bloquear la rodilla de golpe.', 'Evita que la rodilla se vaya hacia dentro; mantenla alineada con el pie.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad de rodilla y cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9929'),
('56c60cc5-2e7e-5e54-a702-ae5230935a0e', 'Empuje de cadera de pie en máquina', ARRAY['Colócate en la máquina con la espalda apoyada y el apoyo en la cadera o pelvis.', 'Ajusta los pies a la anchura de las caderas y activa el abdomen.', 'Empuja la cadera hacia delante contrayendo el glúteo y exhalando.', 'Vuelve despacio a la posición inicial sin perder la alineación.', 'Evita arquear la lumbar en el empuje; el movimiento debe salir del glúteo.']::text[], 'principiante', 'Activa glúteos y femorales con una extensión de cadera guiada, útil para potenciar la fuerza de la cadena posterior de pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9848'),
('52bb060f-9fc0-530b-b85e-0418bc96ddd7', 'Postura del lagarto', ARRAY['Desde una posición de zancada, baja la rodilla trasera al suelo.', 'Coloca las manos a ambos lados del pie delantero y avanza el pie hacia fuera.', 'Baja la cadera hacia el suelo manteniendo la espalda larga.', 'Respira profundo y mantén la postura entre 30 y 60 segundos.', 'Evita forzar la rodilla delantera hacia dentro; mantenla alineada con el pie.']::text[], 'intermedio', 'Estira aductores, flexores de cadera y femorales, mejorando la movilidad de la cadera y aliviando tensión en la zona lumbar.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5892'),
('a7ac0225-4f64-5782-847c-fbb863f9de5d', 'Postura de la langosta', ARRAY['Túmbate boca abajo con los brazos extendidos hacia delante y el cuello relajado.', 'Activa el abdomen y presiona el pubis contra el suelo.', 'Eleva brazos, pecho y piernas a la vez sin forzar el cuello.', 'Mantén la postura respirando y baja lentamente al suelo.', 'Evita arquear en exceso la lumbar; eleva solo hasta donde controles.']::text[], 'intermedio', 'Fortalece la musculatura de la espalda, glúteos y femorales, mejorando la extensión torácica y la postura en el suelo.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1484'),
('4c6831ec-54ae-5ff3-bbff-ed5093a869c8', 'Puente de Londres', ARRAY['Sujeta la cuerda a un punto de anclaje alto.', 'Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.', 'Agarra la cuerda con un agarre prono, con las palmas hacia abajo.', 'Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.', 'Tira de la cuerda hacia tu cuerpo, juntando las escápulas.', 'Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio con cuerda que fortalece la espalda alta y los hombros, mejorando la estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0609'),
('b48434a1-b233-5a6a-afbb-85ebc3689ce1', 'Abdominal con brazos largos', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Extiende los brazos por encima de la cabeza con las manos juntas.', 'Eleva el tronco despegando los omóplatos mientras exhalas.', 'Baja despacio controlando el movimiento sin tirar del cuello.', 'Evita usar impulso con los brazos; el abdomen debe iniciar la subida.']::text[], 'intermedio', 'Trabaja el recto abdominal con brazos extendidos, aumentando la palanca y la dificultad para ganar fuerza en el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4009'),
('7cfa64aa-1181-5b04-95f3-ec144adc4d1f', 'Zancada larga', ARRAY['Da un paso largo hacia delante y apoya el pie con toda la planta.', 'Baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con una zancada amplia que mejora fuerza, estabilidad y movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9701'),
('d1b345c7-45aa-5935-9784-9e47faf8e655', 'Abdominal declinado con palanca larga', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos por encima de la cabeza.', 'Contrae el abdomen y eleva el tronco llevando las manos hacia los pies.', 'Baja despacio controlando el movimiento sin dejarte caer.', 'Evita tirar del cuello o arquear la zona lumbar al subir.']::text[], 'intermedio', 'Fortalece el recto abdominal y los flexores de cadera con un recorrido amplio que exige control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4906'),
('0a979054-1e4f-5faf-9e51-ab8f1d6053f1', 'Extensión de espalda tumbado con palanca larga', ARRAY['Túmbate boca abajo con los brazos estirados por delante.', 'Eleva suavemente el pecho y los brazos del suelo contrayendo la espalda.', 'Mantén un instante arriba y baja de forma controlada.', 'Evita hiperextender el cuello mirando siempre al suelo.']::text[], 'intermedio', 'Refuerza la musculatura de la columna y los glúteos, mejorando la extensión y la postura de la espalda.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4924'),
('cb848daf-9eba-5593-b174-542307b9745f', 'Extensión de cadera de pie con palanca larga', ARRAY['Colócate de pie con el peso sobre una pierna y el torso erguido.', 'Lleva la otra pierna estirada hacia atrás sin arquear la lumbar.', 'Aprieta el glúteo arriba y vuelve despacio a la posición inicial.', 'Evita balancear el tronco o compensar con la espalda baja.']::text[], 'intermedio', 'Activa glúteos e isquios con una extensión de cadera de pie que también trabaja el core y la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9324'),
('c3f7555d-9b10-5800-bfb5-c3e105ebb0a8', 'Respiración en postura del loto', ARRAY['Siéntate con las piernas cruzadas en loto o medio loto.', 'Alarga la columna y apoya las manos sobre las rodillas.', 'Inhala profundo por la nariz y exhala lento por la boca.', 'Evita forzar las rodillas si notas molestia en las caderas.']::text[], 'intermedio', 'Mejora la capacidad respiratoria y la relajación mientras estira caderas y flexores en una postura estable.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5885'),
('0172ab12-c560-5306-9de3-3605c4c2c8b7', 'Postura del loto', ARRAY['Siéntate en el suelo y cruza las piernas colocando cada pie sobre el muslo opuesto.', 'Mantén la espalda erguida y los isquiones apoyados.', 'Respira con calma y relaja los hombros durante la postura.', 'Evita forzar las rodillas si no llegas a la posición completa.']::text[], 'intermedio', 'Abre caderas y tobillos y mejora la estabilidad sentada, con trabajo de glúteos y core en la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0956'),
('d9a69cc4-1f51-5b88-869b-a8a9ac017258', 'Puente de glúteos bajo en el suelo', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo.', 'Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Haz una pausa breve en la parte alta, apretando los glúteos.', 'Baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos e isquios y estabiliza el core con un movimiento suave y controlado desde el suelo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3013'),
('cbf4dafc-3631-5c9e-ac0a-d55a107602f9', 'Jacks bajos', ARRAY['Colócate de pie con los brazos pegados al cuerpo.', 'Abre un pie hacia el lado mientras elevas los brazos sin saltar.', 'Vuelve al centro y repite alternando los lados.', 'Mantén un ritmo constante y evita bloquear las rodillas.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca con un ejercicio cardiovascular de bajo impacto que activa piernas y glúteos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0610'),
('4e181e14-6b89-502b-9587-24af25a7c3af', 'Zancada baja', ARRAY['Arrodíllate con una pierna delante y la rodilla trasera apoyada.', 'Desplaza la cadera hacia delante hasta notar el estiramiento.', 'Mantén la posición respirando de forma relajada.', 'Evita arquear la lumbar en exceso durante el estiramiento.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera, aliviando la tensión de la zona y mejorando la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6007'),
('fbd0cf3a-f96e-5b85-b69e-c662892b1d71', 'Postura de zancada baja', ARRAY['Arrodíllate con una pierna delante y la rodilla trasera en el suelo.', 'Eleva los brazos y abre el pecho llevando la cadera hacia delante.', 'Mantén la postura respirando profundo y sin forzar.', 'Evita hundir la cadera o perder la verticalidad del tronco.']::text[], 'intermedio', 'Estira cuádriceps y flexores de cadera mientras abre el pecho y mejora el equilibrio en la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6618'),
('971280b1-39f5-5970-8a16-80a94e435811', 'Curl lumbar', ARRAY['Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.', 'Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Moviliza la columna y activa glúteos e isquios con un gesto suave que mejora la flexibilidad de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1352'),
('160d4f43-14a2-551f-abd2-62537c3e823e', 'Estiramiento de flexores del tronco inferior', ARRAY['Túmbate boca abajo con las manos bajo los hombros.', 'Empuja suavemente el tronco hacia arriba sin despegar la cadera.', 'Mantén el estiramiento respirando de forma pausada.', 'Evita forzar la lumbar si notas dolor en la espalda.']::text[], 'principiante', 'Estira el abdomen y los flexores de cadera, aliviando tensión y mejorando la movilidad de la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2105'),
('c02f29a4-20c5-5af6-af87-90495129284b', 'Zancada', ARRAY['Colócate de pie con los pies a la anchura de las caderas.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el torso erguido y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquios y mejora el equilibrio con un patrón básico de piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0612'),
('ade3605f-f9d2-556f-9986-df19b07a7938', 'Zancada con flexión', ARRAY['Desde de pie, da un paso atrás y baja a posición de zancada.', 'Apoya las manos en el suelo y lleva los pies atrás a plancha.', 'Haz una flexión controlada con el cuerpo alineado.', 'Vuelve a la zancada y empuja para ponerte de pie sin perder el equilibrio.']::text[], 'intermedio', 'Combina piernas y pecho en un ejercicio completo que trabaja fuerza, coordinación y estabilidad general.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0611'),
('b2ce7b1b-037d-57c6-8783-cb30fccbff62', 'Estiramiento en zancada', ARRAY['Arrodíllate con una pierna delante y la rodilla trasera apoyada.', 'Lleva la cadera hacia delante hasta notar tensión en la pierna trasera.', 'Mantén la posición sin rebotar y respirando con calma.', 'Evita arquear la espalda o forzar más de lo necesario.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera, mejorando la movilidad y reduciendo la tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4930'),
('20635369-1ece-5628-bd72-af91cd7bd9ef', 'Zancada para muslos', ARRAY['Colócate de pie con los pies a la anchura de las caderas y el tronco erguido.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo sin que la delantera pase la punta del pie.', 'Empuja con el talón delantero para volver a la posición inicial controlando el movimiento.', 'Mantén el abdomen activo y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps con apoyo de glúteos e isquios y sirve para ganar fuerza y control en el patrón de zancada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4959'),
('6eccc136-413b-553f-940b-d55209d4c16d', 'Zancada con elevación de pierna', ARRAY['De pie, da un paso al frente y baja en zancada hasta que ambas rodillas formen unos 90 grados.', 'Al subir, extiende la pierna trasera hacia atrás manteniendo el tronco recto.', 'Aprieta el glúteo de la pierna elevada un instante antes de volver a bajar.', 'Evita arquear la zona lumbar y mantén la mirada al frente.']::text[], 'intermedio', 'Activa glúteos e isquios mientras exige estabilidad de core y cadera en cada repetición.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3581'),
('05aeafa5-ec61-5a44-9bd1-874f9f6fd92a', 'Estiramiento de gemelos en zancada con pierna recta', ARRAY['Apoya las manos en la pared y coloca una pierna estirada atrás con el talón en el suelo.', 'Flexiona la rodilla delantera y lleva el peso hacia delante hasta notar tensión en el gemelo.', 'Mantén la pierna trasera recta y el talón pegado al suelo durante 20-30 segundos.', 'Respira con calma y evita rebotar para no forzar el tobillo.']::text[], 'principiante', 'Estira gemelos y sóleo, mejora la movilidad del tobillo y alivia la tensión tras correr o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1054'),
('902dd219-0f84-5acc-a9a4-6901fdd49ae3', 'Estiramiento abdominal boca abajo', ARRAY['Túmbate boca abajo con las manos apoyadas bajo los hombros.', 'Empuja el suelo con las manos y eleva suavemente el pecho sin despegar la pelvis.', 'Mantén la posición 20-30 segundos respirando de forma pausada.', 'Evita forzar la lumbar: sube solo hasta donde notes estiramiento cómodo.']::text[], 'principiante', 'Estira abdomen y flexores de cadera, y ayuda a descargar la zona lumbar después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1168'),
('d54805ea-efd6-582c-b48f-e3c69777f80b', 'Estiramiento de cuádriceps acostado de lado', ARRAY['Túmbate de lado con las piernas rectas.', 'Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano.', 'Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta el estiramiento y repite del otro lado.']::text[], 'principiante', 'Relaja y alarga la parte frontal del muslo, aliviando tensión tras el entrenamiento de piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0613'),
('b29595e5-2cd1-51e8-bfc7-af972ae73fa2', 'Abdominal con presión acostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Coloca las manos sobre los muslos y presiona hacia dentro mientras el abdomen se activa.', 'Eleva ligeramente la cabeza y los hombros manteniendo la lumbar pegada al suelo.', 'Aguanta dos segundos y baja despacio, evitando tirar del cuello.']::text[], 'intermedio', 'Refuerza el abdomen profundo y los oblicuos con una presión isométrica que mejora el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4459'),
('6f2f4f36-7893-5d44-b36d-24fdca91999c', 'Abdominal de tijeras acostado', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas elevadas.', 'Eleva los hombros y lleva el codo hacia la rodilla contraria de forma alterna.', 'Mantén la lumbar apoyada y el movimiento controlado, sin tirones.', 'Evita juntar las manos en la nuca para no cargar el cuello.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con un movimiento alterno que también implica a los flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9024'),
('958b0437-d52f-5f97-8fd9-c16b457127f4', 'Abducción acostado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva la pierna superior sin rotar la cadera ni el tronco.', 'Baja la pierna despacio hasta casi tocar la otra y repite.', 'Evita balancear el cuerpo o usar impulso para subir la pierna.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para estabilizar la cadera y prevenir molestias en rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11047'),
('899b107c-a666-5ade-8338-e60e1c3f9b8f', 'Estiramiento de abductores acostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Cruza un tobillo sobre la rodilla contraria formando una figura de cuatro.', 'Lleva suavemente la rodilla hacia el pecho hasta notar estiramiento en la cadera.', 'Mantén 20-30 segundos y cambia de lado sin forzar la rodilla.']::text[], 'principiante', 'Relaja abductores y glúteos, mejora la movilidad de cadera y alivia tensión en la cara externa del muslo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1882'),
('6d621dd3-f46e-594d-9f1c-aadae3e5b2c3', 'Ciclos en el aire acostado', ARRAY['Túmbate boca arriba con la lumbar pegada al suelo y las manos a los lados.', 'Eleva las piernas y pedalea en el aire con movimientos amplios y controlados.', 'Mantén el abdomen activo y respira de forma constante sin aguantar el aire.', 'Evita arquear la espalda: si la lumbar se despega, reduce la amplitud.']::text[], 'intermedio', 'Activa abdomen y flexores de cadera con un pedaleo continuo que mejora la resistencia del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4883'),
('2fdc7525-d87d-5bc9-a27f-b920292a7b22', 'Patada de rana alterna acostado', ARRAY['Túmbate boca abajo con las manos bajo la frente y las piernas estiradas.', 'Flexiona una rodilla y lleva el talón hacia el glúteo apretando el glúteo.', 'Baja la pierna despacio y alterna con la otra sin despegar la cadera del suelo.', 'Evita arquear la lumbar o levantar la pelvis al patear.']::text[], 'intermedio', 'Activa glúteos e isquios con un movimiento corto que también exige estabilidad de la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6024'),
('e2f1bc83-97a4-55de-b4d9-056e27e5d57f', 'Extensión de cadera alterna acostado', ARRAY['Túmbate boca abajo con las piernas estiradas y el abdomen activo.', 'Eleva una pierna recta hasta donde puedas sin arquear la lumbar.', 'Aprieta el glúteo arriba un segundo y baja despacio.', 'Alterna las piernas evitando usar impulso o girar la cadera.']::text[], 'intermedio', 'Fortalece glúteos e isquios y mejora la estabilidad lumbopélvica con una extensión controlada de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0614'),
('8f246bed-3a39-578a-b22e-8ce053b3d831', 'Toque alterno de punta acostado en el suelo', ARRAY['Túmbate boca arriba con las piernas elevadas y los brazos extendidos.', 'Eleva los hombros y lleva una mano hacia la punta del pie contrario.', 'Vuelve al centro y alterna el lado manteniendo la lumbar apoyada.', 'Evita tirar del cuello y controla el descenso en cada repetición.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con un movimiento cruzado que mejora la coordinación y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5050'),
('4aabc2bd-1ed4-56ce-bd25-ca0effa4ca9f', 'Alrededor del mundo acostado', ARRAY['Túmbate boca arriba con los brazos extendidos hacia el techo.', 'Dibuja círculos amplios con los brazos hacia atrás y luego hacia delante.', 'Mantén las costillas abajo y el abdomen activo durante todo el recorrido.', 'Evita arquear la lumbar o encoger los hombros al circular.']::text[], 'principiante', 'Moviliza hombros y escápulas, mejora la rotación y prepara la articulación para empujes y tirones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3826'),
('010fd178-23f7-53cf-9512-29fff3785faf', 'Extensión de espalda acostado', ARRAY['Túmbate boca abajo con las manos en la nuca o junto a la cabeza.', 'Eleva suavemente el pecho del suelo manteniendo el cuello alineado.', 'Aprieta glúteos y espalda arriba un segundo y baja despacio.', 'Evita hiperextender el cuello o subir más de lo que controlas.']::text[], 'intermedio', 'Refuerza la musculatura de la espalda y los glúteos, y mejora la extensión y estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3228'),
('26cbe3b6-6539-5b9a-808f-e0ce3bd82ee1', 'Extensión de espalda acostado con press', ARRAY['Túmbate boca abajo con los brazos extendidos al frente y las piernas estiradas.', 'Eleva ligeramente el pecho y los brazos del suelo mientras aprietas los glúteos.', 'Haz un pequeño press empujando las manos hacia delante sin despegar el pecho.', 'Baja con control y exhala al elevar; evita arquear en exceso el cuello.']::text[], 'intermedio', 'Fortalece la columna y la cadena posterior, mejorando la postura y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3229'),
('21e85978-3813-517e-a117-61801d83e399', 'Ocho con rodilla flexionada acostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Dibuja un ocho con la rodilla llevándola hacia dentro y hacia fuera con control.', 'Mantén la pelvis estable y respira de forma continua durante el recorrido.', 'Evita compensar con la lumbar; el movimiento nace de la cadera.']::text[], 'principiante', 'Moviliza la cadera y activa los glúteos, mejorando la coordinación y la flexibilidad de la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4932'),
('1a4ad0c2-6b2c-5be3-9748-b72e66138c68', 'Press de tibial acostado con rodilla flexionada', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Presiona con la parte delantera del pie hacia el suelo activando la tibia.', 'Mantén la presión dos segundos y relaja sin mover la rodilla.', 'Evita levantar los talones o compensar con los dedos.']::text[], 'intermedio', 'Refuerza la tibia y el tobillo, útil para prevenir lesiones y mejorar la estabilidad del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10540'),
('feb3768c-1ee2-5dc4-b3b2-b800c42616f5', 'Elevación de piernas flexionadas acostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos junto al cuerpo.', 'Eleva las piernas juntas hasta que los muslos queden perpendiculares al suelo.', 'Baja despacio sin despegar la lumbar del suelo y exhala al subir.', 'Evita arquear la espalda o usar impulso para completar la repetición.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera, ganando control y fuerza en la zona media.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5472'),
('456a4227-65c7-50a2-923a-c775ba0e3995', 'Curl de bíceps acostado con toalla', ARRAY['Túmbate boca arriba con una toalla bajo los pies y sujeta los extremos con las manos.', 'Flexiona los codos tirando de la toalla hacia el pecho sin mover los hombros.', 'Aprieta el bíceps arriba un segundo y baja con control.', 'Evita balancear el tronco o encoger los hombros durante el tirón.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo usando la toalla como resistencia, mejorando la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3558'),
('6e6ea1e8-193b-5f81-a415-4eb402a5d3c4', 'Estiramiento de gemelos acostado', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Lleva la punta del pie estirado hacia ti ayudándote con una toalla o la mano.', 'Mantén el estiramiento veinte segundos respirando despacio.', 'Evita forzar el tobillo o rebotar durante la posición.']::text[], 'principiante', 'Relaja los gemelos y el sóleo, aliviando la tensión y mejorando la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4929'),
('65598985-2451-5cd2-83f0-ef66fdcb0971', 'Piernas cruzadas acostado', ARRAY['Túmbate boca arriba con las manos detrás de la cabeza y las piernas elevadas.', 'Cruza una pierna sobre la otra mientras elevas ligeramente el tronco.', 'Alterna el cruce de piernas con un ritmo controlado y respira de forma continua.', 'Evita tirar del cuello con las manos o arquear la lumbar.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos, mejorando la coordinación y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4880'),
('ac049c7c-a82b-56f4-ba52-bc4d762c7b4b', 'Estiramiento acostado con rodilla cruzada tirando hacia abajo', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Cruza una pierna sobre la otra y lleva la rodilla hacia el pecho.', 'Tira suavemente de la rodilla hacia abajo acercándola al hombro contrario.', 'Mantén veinte segundos sin rebotar y cambia de lado.']::text[], 'principiante', 'Estira el glúteo y la zona lumbar, liberando tensión tras el entrenamiento o largos periodos sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1936'),
('c0256158-2ed9-5a5a-8927-58eef883af5a', 'Estiramiento acostado con rodilla cruzada tirando hacia arriba', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Cruza una pierna sobre la otra y sujeta la rodilla con las manos.', 'Tira de la rodilla hacia el pecho con suavidad y mantén la posición.', 'Respira despacio veinte segundos y evita levantar la cadera del suelo.']::text[], 'principiante', 'Estira el glúteo y la cadera, mejorando la flexibilidad y aliviando la tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1935'),
('48646d5d-5c87-54fa-84c6-f29a3fcca1f0', 'Estiramiento cruzado acostado', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos en cruz.', 'Cruza una pierna por encima de la otra llevando la rodilla al lado contrario.', 'Gira la cabeza al lado opuesto y mantén los hombros pegados al suelo.', 'Respira veinte segundos y cambia de lado sin forzar la lumbar.']::text[], 'principiante', 'Estira glúteos y zona lumbar, mejorando la movilidad de la cadera y aliviando tensiones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0615'),
('def18d67-7d81-59b0-ac58-25af404f00f4', 'Abdominal acostado con piernas rectas', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos detrás de la cabeza.', 'Eleva el tronco despegando los omóplatos del suelo sin tirar del cuello.', 'Aprieta el abdomen arriba y baja con control exhalando al subir.', 'Evita arquear la lumbar o usar impulso para incorporarte.']::text[], 'intermedio', 'Fortalece el recto abdominal y los oblicuos, mejorando la estabilidad del tronco y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6005'),
('2ca2dd81-c233-5ef3-b7c1-ea51f0f6e959', 'Patada doble de piernas acostado', ARRAY['Túmbate boca abajo con las manos bajo la frente y las piernas estiradas.', 'Flexiona las rodillas y da dos patadas suaves con los talones hacia los glúteos.', 'Mantén el abdomen activo y el pubis pegado al suelo durante el movimiento.', 'Evita arquear la lumbar o levantar el pecho del suelo.']::text[], 'intermedio', 'Trabaja la columna, glúteos e isquios, mejorando la extensión y el control postural al estilo pilates.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2851'),
('997c0a56-7d25-5338-9c3c-fe1657d8b54c', 'Curl de bíceps acostado con doble pierna y toalla', ARRAY['Túmbate boca arriba con la toalla bajo ambos pies y sujeta los extremos.', 'Flexiona los codos tirando de la toalla hacia el pecho con los hombros estables.', 'Aprieta el bíceps arriba y baja despacio controlando la tensión.', 'Evita despegar la lumbar o tirar con la espalda en lugar de los brazos.']::text[], 'intermedio', 'Refuerza bíceps y antebrazos con resistencia de toalla, implicando también isquios y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3752'),
('faf330d7-ccc4-503e-beec-473e38ca5d32', 'Curl martillo con ambas piernas acostado con toalla', ARRAY['Túmbate boca arriba con la toalla bajo los pies y agarra los extremos con las palmas enfrentadas.', 'Flexiona los codos manteniendo las muñecas neutras y los hombros relajados.', 'Aprieta arriba un segundo y baja con control sin soltar la toalla.', 'Evita girar las muñecas o balancear el tronco para completar el movimiento.']::text[], 'intermedio', 'Trabaja bíceps, braquial y agarre con la toalla, mejorando la fuerza del brazo y la muñeca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3830'),
('6bfd5a92-9385-5ea2-bf59-81564fa171ae', 'Codo a rodilla acostado', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.', 'Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera, mejorando la coordinación y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2312'),
('3bca4db4-e08a-56ab-b8d5-e7e3bca43200', 'Elevación de cadera acostado plano', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Presiona la zona lumbar contra el suelo y eleva las caderas unos centímetros.', 'Mantén el abdomen apretado y baja despacio sin arquear la espalda.', 'Evita impulsarte con las piernas: el movimiento nace del core.']::text[], 'intermedio', 'Trabaja el abdomen y la zona baja del core, mejorando el control pélvico y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4886'),
('29cf80ad-2919-5256-b25f-e7a694332a00', 'Isométrico a 15 centímetros del suelo', ARRAY['Túmbate boca arriba con las manos bajo los glúteos y las piernas estiradas.', 'Eleva los talones unos 15 centímetros y mantén la zona lumbar pegada al suelo.', 'Respira de forma continua sin aguantar la respiración.', 'Si la espalda se arquea, sube un poco las piernas o dobla las rodillas.']::text[], 'intermedio', 'Mantiene el abdomen en tensión constante para ganar resistencia en el core y estabilidad lumbar.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9451'),
('b477653d-f26e-52cc-bad5-6576eff4c84d', 'Aleteo horizontal tumbado', ARRAY['Túmbate boca arriba con las manos bajo los glúteos y las piernas estiradas.', 'Eleva los pies unos centímetros y alterna subidas y bajadas cortas y rápidas.', 'Mantén la zona lumbar apoyada y el abdomen apretado todo el tiempo.', 'Evita que los talones toquen el suelo para no perder la tensión.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un movimiento continuo que mejora la coordinación del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9321'),
('9d67423a-c1d6-5de9-bcf0-3575c53287a2', 'Hiperextensión tumbado en el suelo', ARRAY['Túmbate boca abajo con los brazos estirados hacia delante.', 'Aprieta glúteos y eleva ligeramente pecho y brazos del suelo.', 'Mantén el cuello alineado mirando al suelo y baja con control.', 'Evita arquear en exceso la lumbar: sube solo hasta donde controles.']::text[], 'intermedio', 'Refuerza la musculatura de la espalda, glúteos e isquios, ayudando a mantener una postura erguida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3827'),
('154c7b0b-a1c3-5a13-8445-c1332c8e8129', 'Hiperextensión tumbado con toalla', ARRAY['Túmbate boca abajo sujetando una toalla tensa entre las manos.', 'Aprieta glúteos y eleva el pecho llevando los brazos hacia delante.', 'Mantén la mirada al suelo y baja despacio sin relajar del todo.', 'No tires de la toalla con fuerza ni arquees el cuello hacia atrás.']::text[], 'intermedio', 'Fortalece espalda alta y baja, glúteos e isquios usando una toalla para ampliar la palanca.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3829'),
('6b30ef06-95b8-5595-8c25-4bd699b1e9ee', 'Dragon flag negativo acostado en el suelo', ARRAY['Túmbate y agárrate a un soporte fijo detrás de la cabeza.', 'Sube el cuerpo recto hasta quedar casi vertical sobre los hombros.', 'Baja lentamente manteniendo el cuerpo alineado y el abdomen apretado.', 'Evita doblarte por la cadera: si pierdes la línea, reduce el recorrido.']::text[], 'avanzado', 'Ejercicio avanzado de core que exige gran control para bajar el cuerpo recto sin perder la tensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9318'),
('b34d4f48-7a03-5ddf-8349-739cff052e7b', 'Medio dragon flag negativo', ARRAY['Túmbate y agárrate a un soporte fijo con las manos.', 'Eleva el cuerpo recto hasta la mitad del recorrido, sin llegar a vertical.', 'Baja despacio manteniendo abdomen y glúteos apretados.', 'No dejes caer las piernas de golpe: controla hasta el final.']::text[], 'avanzado', 'Versión más accesible del dragon flag que entrena el core con un recorrido parcial y controlado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9319'),
('6a21d7db-56c9-520b-b16c-c4af6c95770f', 'Remo tumbado con rodillas flexionadas', ARRAY['Túmbate boca abajo y agarra un soporte fijo con las rodillas dobladas.', 'Tira del cuerpo hacia arriba juntando las escápulas.', 'Baja despacio hasta estirar los brazos sin perder la tensión.', 'Evita encoger los hombros: lleva los codos hacia atrás y abajo.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps usando el propio peso corporal como resistencia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3495'),
('4b9acb3f-4e7b-51da-b3da-217efcb9e076', 'Dragon flag negativo a una pierna', ARRAY['Túmbate y agárrate a un soporte fijo detrás de la cabeza.', 'Sube el cuerpo recto con una pierna extendida y la otra recogida.', 'Baja lentamente sin doblar la cadera ni perder la alineación.', 'Si la lumbar se arquea, vuelve a subir y reduce el recorrido.']::text[], 'avanzado', 'Variante unilateral del dragon flag que aumenta la exigencia de control y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9322'),
('c8a7495d-bf94-5474-b18c-8d69afb27cb7', 'Deslizamiento tumbado en el suelo', ARRAY['Túmbate boca arriba con los brazos estirados hacia el techo.', 'Desliza los brazos hacia el suelo por encima de la cabeza sin despegar la lumbar.', 'Mantén las escápulas activas y respira de forma pausada.', 'Evita arquear la espalda: si no llegas, reduce el recorrido.']::text[], 'principiante', 'Movilidad para la espalda alta y los hombros que mejora el control escapular y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '7538'),
('9fe3e320-0914-5a21-aea4-2cef1635ce1c', 'Press svend tumbado con disco', ARRAY['Túmbate boca arriba sujetando un disco con las palmas enfrentadas.', 'Empuja el disco hacia el techo juntando las manos con fuerza.', 'Baja despacio hasta el pecho manteniendo la presión entre las palmas.', 'No bloquees los codos de golpe ni dejes caer el disco.']::text[], 'intermedio', 'Trabaja el pectoral con un movimiento de aproximación que activa la parte interna del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10550'),
('deca4f7d-0ae6-57df-b850-4a0471e059ce', 'Patada de rana tumbado', ARRAY['Túmbate boca abajo con las rodillas dobladas y los pies juntos.', 'Aprieta glúteos y eleva los talones hacia el techo sin mover la cadera.', 'Mantén el abdomen apretado y baja despacio.', 'Evita arquear la lumbar: el movimiento sale del glúteo, no de la espalda.']::text[], 'intermedio', 'Activa glúteos e isquios con un movimiento corto que mejora la fuerza y el control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6025'),
('fa94d608-2a3c-5097-912e-19504499649f', 'Elevación completa de piernas', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Sube las piernas rectas hasta quedar perpendiculares al suelo.', 'Baja despacio sin despegar la zona lumbar del suelo.', 'Si la espalda se arquea, dobla un poco las rodillas o reduce el recorrido.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con un recorrido amplio que exige control lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3263'),
('bc1dd2eb-2fc0-50df-b7e4-aa95c5293aad', 'Contracción de glúteos tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos relajados.', 'Aprieta los glúteos con fuerza como si juntaras los talones.', 'Mantén la contracción unos segundos respirando con normalidad.', 'Evita arquear la lumbar: el esfuerzo debe notarse en el glúteo.']::text[], 'intermedio', 'Activa glúteos e isquios de forma isométrica, útil para tomar conciencia y despertar la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3412'),
('163a6cdc-0e81-5b1a-a6ef-a87ce4884210', 'Estiramiento de glúteo tumbado', ARRAY['Túmbate boca arriba con una rodilla doblada y el pie apoyado.', 'Cruza el tobillo contrario sobre la rodilla y lleva la pierna hacia el pecho.', 'Sujeta el muslo y mantén el estiramiento sin rebotes.', 'Respira despacio y evita forzar si notas pinchazos en la rodilla.']::text[], 'principiante', 'Estira glúteos e isquios para aliviar tensión en la cadera y mejorar la movilidad de la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1056'),
('712b1c6d-db66-5fb2-9871-aafca8424630', 'Estiramiento de flexor de cadera tumbado', ARRAY['Túmbate boca arriba cerca del borde de una superficie firme.', 'Deja una pierna colgando y lleva la rodilla de la otra hacia el pecho.', 'Mantén la zona lumbar pegada al suelo sin arquear la espalda.', 'Respira despacio y aguanta entre veinte y treinta segundos por lado.', 'Evita tirar de la rodilla con fuerza y no rebotes.']::text[], 'principiante', 'Estira la parte delantera del muslo y la cadera, alivia tensión tras estar sentado y mejora la movilidad de la pelvis.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1577'),
('659c8a19-4f94-554d-8087-c46d5837343a', 'Estiramiento de flexor de cadera acostado', ARRAY['Colócate tumbado boca arriba con las piernas estiradas.', 'Lleva una rodilla al pecho y sujétala con las manos.', 'Empuja suavemente la cadera contraria hacia el suelo.', 'Mantén la posición sin levantar la espalda baja.', 'Respira de forma continua y cambia de lado sin prisa.']::text[], 'principiante', 'Relaja el psoas y la cadera tras sesiones de sentadilla o muchas horas sentado, ganando rango en la extensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0616'),
('49156463-7a65-5f46-8ec1-d55f7670614f', 'Elevación de pierna y cadera tumbado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva la pierna superior sin rotar la cadera hacia atrás.', 'Aprieta el glúteo arriba y baja con control.', 'Mantén el abdomen activo y evita arquear la zona lumbar.', 'Haz las repeticiones lentas y cambia de lado.']::text[], 'intermedio', 'Trabaja glúteo medio y abdominales laterales para estabilizar la cadera y prevenir molestias al caminar o correr.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0617'),
('c3c9c9a3-3e69-53a7-8bfa-b45897c69299', 'Elevación de cadera en balón de estabilidad', ARRAY['Apoya la espalda alta y los pies en el suelo con el balón bajo la zona lumbar.', 'Eleva la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y baja sin dejar caer el balón.', 'Mantén el abdomen firme para no arquear la espalda.', 'Controla el descenso y evita impulsarte con las piernas.']::text[], 'principiante', 'Fortalece glúteos e isquios mientras el core estabiliza el balón, útil para mejorar la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1065'),
('5efd3025-4caf-54e9-96fa-73c286ee8b51', 'Elevación de pierna recta tumbado', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Eleva la pierna recta hasta unos cuarenta y cinco grados.', 'Mantén la rodilla estirada y el abdomen activo.', 'Baja despacio sin que la zona lumbar se despegue del suelo.', 'Evita balancear la pierna para ganar impulso.']::text[], 'intermedio', 'Activa isquios y glúteos con la pierna estirada, mejorando el control de la cadera y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0619'),
('d7a611e1-9b71-5314-862d-3a8f9226c3ad', 'Isométrico de hiperextensión tumbado', ARRAY['Túmbate boca abajo con los brazos junto al cuerpo.', 'Eleva ligeramente el pecho y las piernas del suelo.', 'Mantén la posición sin forzar el cuello ni mirar arriba.', 'Respira con normalidad durante quince a treinta segundos.', 'Baja despacio y evita arquear en exceso la lumbar.']::text[], 'intermedio', 'Refuerza la musculatura de la espalda y los glúteos manteniendo la extensión, clave para una postura estable.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6019'),
('86a4ff2f-fde1-5a87-abb1-e2678e4ffdfd', 'Elevación de cadera en inclinación', ARRAY['Túmbate en una superficie inclinada con la cabeza más baja.', 'Sujétate para estabilizar el torso y eleva las piernas rectas.', 'Lleva las rodillas hacia el pecho sin despegar la lumbar.', 'Baja las piernas con control sin dejarlas caer.', 'Evita impulsarte con los brazos o balancear el cuerpo.']::text[], 'intermedio', 'Incide en el abdomen bajo y los flexores de cadera, ayudando a controlar la pelvis en movimientos diarios.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4885'),
('92f482ad-cec4-5aae-babe-58715f737106', 'Elevación de rodilla tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Lleva una rodilla hacia el pecho sin despegar la lumbar.', 'Aprieta el abdomen abajo y baja la pierna con control.', 'Alterna las piernas manteniendo un ritmo constante.', 'Evita arquear la espalda o tirar del cuello.']::text[], 'intermedio', 'Trabaja el abdomen bajo y los flexores de cadera con un movimiento sencillo que mejora el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8194'),
('6c385108-594a-59a0-b0ea-c3ae9bdcadca', 'Estiramiento de rodilla al pecho tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Lleva una rodilla al pecho y sujétala con las manos.', 'Mantén la otra pierna estirada o flexionada según tu comodidad.', 'Respira hondo y aguanta veinte a treinta segundos.', 'Evita tirar con fuerza y no levantes la cabeza del suelo.']::text[], 'principiante', 'Libera tensión en glúteos y zona lumbar, ideal después de estar sentado o tras entrenar piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1810'),
('7cb0cafe-ee56-5ead-81d3-ef4282d296aa', 'Jalón dorsal tumbado', ARRAY['Túmbate en un banco con la polea alta alineada sobre el pecho.', 'Agarra la barra con las manos algo más anchas que los hombros.', 'Tira de la barra hacia el pecho llevando los codos abajo.', 'Controla el retorno sin perder la tensión en los dorsales.', 'Evita encoger los hombros o tirar con impulso.']::text[], 'principiante', 'Fortalece dorsales y bíceps con polea, mejorando la tracción y la postura sin cargar la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4957'),
('dea2d315-86d1-5b2e-a763-f5c894fc040e', 'Estiramiento apoyado en la pared', ARRAY['Túmbate boca arriba junto a una pared.', 'Apoya una pierna estirada en la pared y deja la otra abierta.', 'Acerca suavemente la pierna abierta hacia el suelo.', 'Mantén la espalda relajada y respira despacio.', 'Evita forzar la apertura y no rebotes.']::text[], 'principiante', 'Estira aductores e isquios con apoyo estable, mejorando la apertura de cadera y la movilidad de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1905'),
('f4585304-d6ec-5a9a-af31-f7c75768686e', 'Ocho con las piernas tumbado', ARRAY['Túmbate boca arriba con las piernas elevadas y rodillas flexionadas.', 'Dibuja un ocho con las piernas sin tocar el suelo.', 'Mantén la lumbar pegada al suelo durante todo el recorrido.', 'Respira de forma constante y controla la velocidad.', 'Evita balancear el cuerpo o usar impulso.']::text[], 'intermedio', 'Coordina abdomen y oblicuos con un movimiento circular que mejora el control del core y la movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4987'),
('1a9705e6-56cd-5d52-8790-dfaa931fa9f0', 'Estiramiento de abductores con pierna colgando', ARRAY['Túmbate de lado cerca del borde de una superficie.', 'Deja la pierna superior colgando hacia el suelo.', 'Relaja la cadera y deja que la gravedad abra la pierna.', 'Mantén la posición sin forzar y respira despacio.', 'Evita girar el tronco y cambia de lado.']::text[], 'principiante', 'Relaja abductores y glúteos, aliviando tensión lateral de cadera y mejorando la apertura de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1884'),
('073e0aec-5337-53bc-a600-e67cd0121d1b', 'Elevación de piernas y cadera en el suelo', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Eleva las piernas rectas hasta unos cuarenta y cinco grados.', 'Aprieta el abdomen y baja sin tocar el suelo.', 'Mantén la lumbar pegada al suelo en todo momento.', 'Evita arquear la espalda o usar impulso.']::text[], 'intermedio', 'Refuerza el abdomen bajo y los flexores de cadera, mejorando la estabilidad del tronco en movimientos cotidianos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3393'),
('64c070a6-1da2-56af-9505-621f8da73015', 'Elevación lateral de pierna y cadera tumbado', ARRAY['Túmbate de lado con el cuerpo alineado y las piernas estiradas.', 'Eleva la pierna superior hacia el techo sin rotar la cadera.', 'Aprieta el costado y baja con control.', 'Mantén el abdomen activo y evita inclinarte atrás.', 'Haz el movimiento lento y cambia de lado.']::text[], 'intermedio', 'Trabaja oblicuos y aductores con control lateral, útil para estabilizar la cadera y mejorar la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4156'),
('de122eda-efb0-5f3e-aa51-3e28f879e1c0', 'Elevación lateral de pierna tumbado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva la pierna de arriba sin rotar la cadera ni el tronco.', 'Baja la pierna con control sin dejarla caer de golpe.', 'Evita arquear la espalda o balancear el cuerpo para subir más.']::text[], 'intermedio', 'Trabaja los abductores y glúteos para estabilizar la cadera y mejorar la fuerza en movimientos laterales.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2852'),
('a971a9f6-f0b2-5d90-bd7c-48baef31eb91', 'Elevación de piernas tumbado con sostén', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos a los lados.', 'Sube las piernas hasta unos 45 grados y mantén la posición.', 'Aprieta el abdomen y mantén la zona lumbar pegada al suelo.', 'Baja las piernas despacio sin que la espalda se despegue.']::text[], 'intermedio', 'Refuerza el abdomen y la zona baja del core, mejorando el control pélvico y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1245'),
('017dec03-522e-5cfa-a508-9d77e61f7acd', 'Elevación de piernas en banco plano', ARRAY['Túmbate en un banco plano con la espalda presionada contra él.', 'Coloca las manos debajo de los glúteos como apoyo.', 'Mantén las piernas rectas y juntas, y elévalas hacia el techo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejorando el control del core en posición tumbada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0620'),
('249d0c04-b883-52c5-b2fc-9146bbe77949', 'Elevación de pierna hacia el lado tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Eleva una pierna hacia el lado sin despegar la cadera del suelo.', 'Controla el descenso y alterna con la otra pierna.', 'Evita girar el tronco o usar impulso para subir la pierna.']::text[], 'intermedio', 'Activa oblicuos y abdomen para trabajar la fuerza lateral del core y la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3268'),
('e370ecea-3027-5a7a-bd5f-0f61619bc2d3', 'Estiramiento de cadera y espalda tumbado con pierna recogida', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Recoge una rodilla hacia el pecho y sujétala con las manos.', 'Mantén la otra pierna estirada y respira despacio.', 'Evita tirar con fuerza o levantar la cabeza del suelo.']::text[], 'principiante', 'Relaja glúteos, flexores de cadera y zona lumbar, aliviando tensión tras estar sentado mucho tiempo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3475'),
('169629a9-0a75-548c-ab30-4a26f9711789', 'Estiramiento de cadera tumbado con pierna recogida hacia la derecha', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Recoge la rodilla derecha hacia el pecho y sujétala con las manos.', 'Mantén la pierna izquierda estirada y respira con calma.', 'Evita forzar la cadera o despegar la zona lumbar del suelo.']::text[], 'principiante', 'Estira glúteos y zona lumbar del lado derecho, liberando tensión acumulada en la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3477'),
('945f25a8-4c3b-5561-967d-be506ee185a7', 'Estiramiento de cadera tumbado con pierna recogida', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Lleva una rodilla al pecho y sujétala con las manos.', 'Mantén la posición respirando de forma relajada.', 'Evita rebotar o tirar demasiado fuerte de la rodilla.']::text[], 'principiante', 'Alivia la tensión en glúteos y flexores de cadera, mejorando la movilidad de la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3472'),
('1449f458-ab6d-50ef-b3ed-79c2d95a3ea5', 'Estiramiento de cadera tumbado con pierna recogida y manos arriba', ARRAY['Túmbate boca arriba con los brazos estirados por encima de la cabeza.', 'Recoge una rodilla hacia el pecho y sujétala con las manos.', 'Mantén la otra pierna estirada y respira profundamente.', 'Evita arquear la zona lumbar o forzar el cuello.']::text[], 'principiante', 'Estira glúteos y cadena posterior mientras alarga la columna, mejorando la movilidad general.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3474'),
('e57858ee-a4d2-5904-97c3-0e6acbaa439c', 'Estiramiento de cadera con giro tumbado y pierna recogida', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Recoge una rodilla y llévala cruzada hacia el lado contrario.', 'Gira la cabeza al lado opuesto y relaja los hombros.', 'Evita forzar la rotación o levantar la cadera del suelo.']::text[], 'principiante', 'Estira glúteos y zona lumbar con rotación, mejorando la movilidad de la cadera y la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3476'),
('8df94587-c181-5f21-9b48-656889a1f73a', 'Estiramiento de cadera con giro tumbado y pierna recogida hacia la izquierda', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Recoge la rodilla izquierda y llévala cruzada hacia la derecha.', 'Gira la cabeza a la izquierda y relaja los hombros.', 'Evita forzar la rotación o despegar la cadera del suelo.']::text[], 'principiante', 'Estira glúteos y zona lumbar del lado izquierdo con rotación, liberando tensión en la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3478'),
('c70377dc-a9ff-5b25-87dc-9d1cad1e75e3', 'Elevación de piernas y cadera acostado', ARRAY['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.', 'Coloca las manos debajo de los glúteos como apoyo.', 'Activa el core y levanta las piernas del suelo, elevándolas hacia el techo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera, mejorando la fuerza del core y el control pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0865'),
('d9888d71-dcb7-5f7e-9105-d13de3d32b83', 'Estiramiento de zona lumbar tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas.', 'Recoge las rodillas hacia el pecho y abrázalas con los brazos.', 'Respira despacio y deja que la zona lumbar se relaje.', 'Evita tirar con fuerza o levantar la cabeza del suelo.']::text[], 'principiante', 'Relaja la musculatura lumbar y glútea, aliviando la tensión de la espalda baja tras el día.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3243'),
('e1bfade1-299e-565e-967c-c887a5cf118f', 'Extensión de cuello tumbado', ARRAY['Túmbate boca abajo con la frente apoyada y los brazos relajados.', 'Eleva ligeramente la cabeza y el cuello sin forzar.', 'Mantén unos segundos y baja con control.', 'Evita echar la cabeza muy atrás o hacer movimientos bruscos.']::text[], 'intermedio', 'Fortalece los extensores del cuello y la parte alta de la espalda, mejorando la postura cervical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10781'),
('931914b9-487d-5399-8615-c85a09ae22b1', 'Estiramiento de extensión de cuello tumbado', ARRAY['Túmbate boca arriba con los hombros relajados.', 'Lleva la barbilla hacia el pecho suavemente.', 'Mantén la posición respirando despacio.', 'Evita tirar de la cabeza con las manos o forzar el cuello.']::text[], 'principiante', 'Estira los extensores del cuello y la parte alta de la espalda, aliviando la tensión cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1842'),
('6d7bfe22-0ba0-58cd-a6c9-27cc9b538cd7', 'Estiramiento de extensores del cuello tumbado', ARRAY['Túmbate boca arriba con los brazos a los lados.', 'Inclina la cabeza hacia un lado hasta notar el estiramiento.', 'Mantén la posición respirando con calma.', 'Evita girar el tronco o forzar el cuello hacia atrás.']::text[], 'principiante', 'Relaja los extensores cervicales y la parte alta de la espalda, reduciendo la tensión del cuello.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1841'),
('c5449a82-70eb-57f6-b69a-78e81420dc3d', 'Flexión de cuello tumbado', ARRAY['Túmbate boca arriba con la cabeza apoyada y los hombros relajados.', 'Lleva la barbilla hacia el pecho despacio, sin levantar la cabeza del suelo.', 'Aguanta un segundo arriba y baja controlando el movimiento.', 'Evita tirar con las manos o encoger los hombros durante el recorrido.']::text[], 'intermedio', 'Trabaja el elevador de la escápula y el esternocleidomastoideo para mejorar el control y la movilidad de la zona cervical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10780'),
('6e55061b-d01e-51f3-8049-81c253a699d4', 'Tirón de cuello tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Eleva ligeramente la cabeza y los hombros mientras espiras.', 'Mantén el abdomen firme y el cuello largo, sin tirar de la cabeza.', 'Baja despacio inspirando y repite sin perder la tensión del core.']::text[], 'intermedio', 'Activa el core y los flexores de cadera con control respiratorio, útil para estabilidad y coordinación en Pilates.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2853'),
('2809ad90-d63b-5a4a-b41f-b864b8663e02', 'Relajación del suelo pélvico con respiración profunda', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los brazos a los lados.', 'Inspira por la nariz llevando el aire al abdomen y nota cómo se expande.', 'Espira despacio y deja que el suelo pélvico se relaje sin apretar.', 'Evita contener la respiración o forzar el abdomen durante el ejercicio.']::text[], 'principiante', 'Favorece la relajación del suelo pélvico y la respiración diafragmática para recuperar control y reducir tensión.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8146'),
('cc52fe85-282e-5016-890c-a6c42180b10d', 'Inclinación pélvica tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Aplana la zona lumbar contra el suelo basculando la pelvis hacia atrás.', 'Mantén unos segundos y vuelve a la posición neutra despacio.', 'Evita empujar con los pies o levantar los glúteos del suelo.']::text[], 'principiante', 'Moviliza la pelvis y la zona lumbar, mejorando la conciencia corporal y aliviando tensión en la espalda baja.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '7294'),
('52a34622-db67-5917-b9f0-33d48ef7abde', 'Estiramiento pretzel tumbado', ARRAY['Túmbate boca arriba y cruza una pierna por encima de la otra.', 'Gira la cadera hacia un lado hasta notar el estiramiento en el glúteo.', 'Respira profundo y mantén la posición sin forzar la zona lumbar.', 'Evita girar bruscamente o levantar el hombro del suelo.']::text[], 'principiante', 'Estira glúteos, flexores de cadera y cuádriceps, ayudando a liberar tensión tras sesiones de pierna o sedestación prolongada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11954'),
('23ec95ba-b4a4-5f8e-92c5-5d3a8ccd607d', 'A tumbado boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos formando una A.', 'Eleva ligeramente los brazos y el pecho sin arquear la lumbar.', 'Aprieta las escápulas y mantén un par de segundos arriba.', 'Baja controlando y evita encoger el cuello durante el movimiento.']::text[], 'intermedio', 'Refuerza la espalda alta y los romboides, mejorando la postura y la estabilidad escapular en posición prona.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5040'),
('2acdce6c-f42e-5da5-90b4-2bc2ec3b979e', 'T tumbado boca abajo', ARRAY['Túmbate boca abajo con los brazos abiertos formando una T.', 'Eleva los brazos hacia el techo juntando las escápulas.', 'Mantén la frente cerca del suelo y el cuello relajado.', 'Baja despacio sin dejar caer los brazos de golpe.']::text[], 'intermedio', 'Trabaja la espalda alta y los deltoides posteriores para mejorar la postura y la salud escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5041'),
('aaa0e77a-ec24-5051-9fb1-f416a1e4ab27', 'W tumbado boca abajo', ARRAY['Túmbate boca abajo con los codos flexionados formando una W.', 'Eleva los codos y las manos apretando las escápulas hacia abajo.', 'Mantén la barbilla recogida y evita arquear la zona lumbar.', 'Baja controlando el movimiento y repite sin perder la tensión.']::text[], 'intermedio', 'Activa la espalda alta y los rotadores externos, útil para corregir la postura y estabilizar los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5042'),
('95272459-b132-5a77-8b14-26c49cfdcade', 'De W a T tumbado boca abajo', ARRAY['Túmbate boca abajo con los codos flexionados en forma de W.', 'Eleva los brazos y extiéndelos hacia los lados hasta formar una T.', 'Mantén las escápulas activas y el cuello alineado con la columna.', 'Vuelve a la posición W despacio y evita perder la tensión.']::text[], 'intermedio', 'Moviliza y fortalece la espalda alta combinando rotación escapular para mejorar control y postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5043'),
('add3063b-5bfc-5389-8a32-a6b442a7ddc2', 'De W a Y tumbado boca abajo', ARRAY['Túmbate boca abajo con los codos flexionados en W.', 'Extiende los brazos hacia delante y arriba formando una Y.', 'Aprieta las escápulas y mantén la frente cerca del suelo.', 'Vuelve a la W controlando el movimiento y sin encoger el cuello.']::text[], 'intermedio', 'Fortalece la espalda alta y los trapecios inferiores, mejorando la estabilidad y la postura de los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5044'),
('d5611521-983e-516e-9699-7c1bd39c4ed8', 'Elevación en Y tumbado boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos hacia delante en Y.', 'Eleva los brazos y el pecho ligeramente sin arquear la lumbar.', 'Aprieta las escápulas y mantén un segundo arriba.', 'Baja despacio y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Refuerza la espalda alta y los deltoides posteriores, mejorando la postura y la estabilidad de los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6350'),
('77740bcf-2367-52be-b17f-b022d121d419', 'De Y a T a W tumbado boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos en Y.', 'Abre los brazos hacia los lados hasta formar una T.', 'Flexiona los codos y llévalos hacia el cuerpo formando una W.', 'Realiza la secuencia despacio y evita perder la tensión escapular.']::text[], 'principiante', 'Moviliza y activa la espalda alta mediante transiciones escapulares, mejorando control postural y movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8546'),
('bdfa4176-4b64-54f9-a403-a1622a07381d', 'Activación del recto abdominal tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos en el abdomen.', 'Eleva la cabeza y los hombros unos centímetros contrayendo el abdomen.', 'Espira al subir y mantén la barbilla ligeramente recogida.', 'Baja despacio y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Activa el recto abdominal y los oblicuos con un movimiento corto, útil para aprender a controlar el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6752'),
('561023ea-35d1-571a-bbe6-9d4c4fca4be7', 'Activación de los escalenos tumbado', ARRAY['Túmbate boca arriba con la cabeza apoyada y los hombros relajados.', 'Realiza una inspiración profunda notando cómo se eleva la parte alta del pecho.', 'Espira despacio manteniendo el cuello largo y sin tensión.', 'Evita levantar la cabeza o encoger los hombros durante el ejercicio.']::text[], 'principiante', 'Activa los escalenos y el elevador de la escápula para mejorar el control cervical y la respiración.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6753'),
('e994b56f-ba78-5549-bc05-1d6e2a122ad1', 'Abdominal tijera tumbado', ARRAY['Túmbate boca arriba con las piernas elevadas y las manos junto al cuerpo.', 'Sube ligeramente la cabeza y los hombros manteniendo el abdomen firme.', 'Alterna las piernas arriba y abajo sin tocar el suelo con los pies.', 'Evita arquear la lumbar y mantén la respiración constante.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con movimiento alterno de piernas, mejorando control y resistencia del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0621'),
('6b3a6c48-1731-5ead-a9f6-e4dae025b2f1', 'Patada tijera acostado', ARRAY['Túmbate boca arriba con las manos bajo los glúteos y la zona lumbar pegada al suelo.', 'Eleva las piernas estiradas unos centímetros y abre y cierra las piernas como unas tijeras.', 'Mantén el abdomen apretado y respira de forma continua sin aguantar el aire.', 'Evita arquear la espalda baja: si se despega, reduce la amplitud o sube menos las piernas.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con un movimiento alterno que mejora el control del core y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0622'),
('927fee76-d8bf-59ce-b595-888e5603d814', 'Tijeras cruzadas acostado', ARRAY['Túmbate boca arriba con las piernas elevadas y las manos apoyadas junto a la cadera.', 'Cruza una pierna sobre la otra y alterna el cruce de forma controlada.', 'Mantén la zona lumbar pegada al suelo y el abdomen activo durante todo el movimiento.', 'No dejes caer las piernas de golpe: controla el descenso y evita rebotar.']::text[], 'intermedio', 'Activa aductores y abdomen bajo con cruces de piernas que mejoran la estabilidad del core y la movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6214'),
('11b12be9-1099-5db5-a90c-38a1d1736040', 'Barrido de hombros acostado', ARRAY['Túmbate boca arriba con los brazos estirados a los lados y las palmas hacia arriba.', 'Lleva un brazo en arco por encima de la cabeza hasta el suelo, manteniéndolo estirado.', 'Vuelve despacio a la posición inicial y alterna con el otro brazo.', 'Evita despegar la espalda del suelo o forzar el hombro si notas dolor.']::text[], 'principiante', 'Moviliza el hombro y la cintura escapular, mejorando la rotación y la salud del manguito rotador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3413'),
('3e202746-0a8c-524e-b0cc-73190177bfd6', 'Rodillas de lado a lado acostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Deja caer las rodillas hacia un lado sin despegar los hombros del suelo.', 'Vuelve al centro y repite hacia el otro lado de forma lenta y controlada.', 'Respira profundo en cada rotación y evita forzar si notas tensión en la espalda.']::text[], 'principiante', 'Moviliza la columna y la cadera con rotaciones suaves que alivian la zona lumbar y activan los oblicuos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4609'),
('77c02b46-f55f-570d-9e2a-f2aec41c1330', 'Elevación de piernas alterna y simultánea acostado', ARRAY['Túmbate boca arriba con las manos bajo los glúteos y las piernas estiradas.', 'Eleva una pierna y luego la otra, alternando, y después sube las dos a la vez.', 'Mantén la zona lumbar pegada al suelo y el abdomen apretado en todo momento.', 'Baja las piernas despacio sin que toquen el suelo y evita arquear la espalda.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera combinando elevaciones alternas y simultáneas para un core más estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0623'),
('07f36978-caf6-5b14-9650-b93d447ba173', 'Elevación de piernas rectas alterna y simultánea acostado', ARRAY['Túmbate boca arriba con las piernas rectas y las manos bajo los glúteos.', 'Sube una pierna estirada, bájala y alterna, y después eleva las dos juntas.', 'Mantén las piernas rectas y la zona lumbar apoyada durante todo el ejercicio.', 'Evita balancear el cuerpo o usar impulso: controla el descenso en cada repetición.']::text[], 'intermedio', 'Refuerza el abdomen bajo y los flexores de cadera con piernas estiradas, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1180'),
('07bed3e3-bfba-5aed-a13c-8e2c1499c0db', 'Deslizamiento de un brazo de Y a T acostado', ARRAY['Túmbate boca abajo con un brazo estirado por encima de la cabeza formando una Y.', 'Desliza ese brazo hacia el lado hasta formar una T, manteniéndolo pegado al suelo.', 'Vuelve despacio a la posición de Y y repite antes de cambiar de brazo.', 'Evita levantar el hombro o arquear la espalda: mantén el cuello relajado.']::text[], 'principiante', 'Moviliza trapecios y deltoides posteriores, mejorando la movilidad escapular y la postura de los hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10742'),
('b4a54bac-9bbc-5b67-899a-b7fc578c2504', 'Estiramiento de tríceps a un brazo acostado', ARRAY['Túmbate boca arriba con un brazo flexionado y la mano detrás de la cabeza.', 'Con la otra mano, empuja suavemente el codo hacia abajo hasta notar el estiramiento.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita tirar del codo con fuerza o forzar el hombro si aparece dolor.']::text[], 'principiante', 'Estira el tríceps y la parte posterior del hombro, aliviando la tensión tras el trabajo de empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10739'),
('c30a7a22-01c5-5a4f-9edb-183d3971dcd6', 'Círculo a una pierna acostado', ARRAY['Túmbate boca arriba con una pierna estirada hacia el techo y la otra apoyada.', 'Dibuja círculos pequeños con la pierna elevada, manteniéndola recta.', 'Haz la mitad de las repeticiones en un sentido y luego en el contrario.', 'Evita mover la cadera o arquear la espalda: mantén el abdomen activo.']::text[], 'intermedio', 'Trabaja abductores y glúteos con círculos controlados que mejoran la estabilidad de la cadera y el core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2854'),
('9b15ea17-d74d-5890-96e6-d702579616de', 'Estiramiento de isquiotibiales a una pierna contra la pared', ARRAY['Túmbate boca arriba con una pierna apoyada en la pared y la otra estirada en el suelo.', 'Acerca el glúteo a la pared hasta notar el estiramiento en la parte posterior del muslo.', 'Mantén la pierna estirada y respira despacio durante veinte o treinta segundos.', 'Evita levantar la cadera o forzar la rodilla: flexiona ligeramente si molesta.']::text[], 'principiante', 'Estira los isquiotibiales y la parte posterior de la pierna, mejorando la flexibilidad y aliviando la tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7622'),
('0a4cea13-e074-55bc-96ef-3ba58333af71', 'Patada a una pierna acostado', ARRAY['Túmbate boca abajo con la frente apoyada en las manos y las piernas estiradas.', 'Eleva una pierna recta y dale dos patadas pequeñas hacia arriba sin tocar el suelo.', 'Baja la pierna despacio y alterna con la otra, manteniendo el abdomen activo.', 'Evita arquear la zona lumbar en exceso: el movimiento debe salir del glúteo.']::text[], 'intermedio', 'Moviliza la columna y activa glúteos e isquiotibiales con patadas controladas que mejoran la extensión de cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2855'),
('e3fbe1a3-d337-5fc6-ba34-034d9b5dc291', 'Movilización de cuádriceps a una pierna acostado', ARRAY['Túmbate boca abajo con las piernas estiradas y los brazos junto al cuerpo.', 'Flexiona una rodilla y lleva el talón hacia el glúteo de forma lenta.', 'Mantén unos segundos arriba y baja el pie con control antes de repetir.', 'Evita forzar la rodilla o despegar la cadera del suelo durante el movimiento.']::text[], 'principiante', 'Moviliza el cuádriceps y la cadera, mejorando la flexibilidad del muslo y la extensión de la rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11801'),
('99b80d8e-513b-5089-badc-a839ae4ed615', 'Elevación de pierna a una pierna acostado', ARRAY['Túmbate boca arriba con una pierna estirada en el suelo y la otra flexionada.', 'Eleva la pierna estirada hasta unos cuarenta y cinco grados manteniéndola recta.', 'Baja despacio sin que toque el suelo y repite antes de cambiar de pierna.', 'Evita arquear la espalda o usar impulso: aprieta el abdomen en cada repetición.']::text[], 'intermedio', 'Fortalece cuádriceps y flexores de cadera con elevaciones controladas que mejoran la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10913'),
('9b22d91b-1549-5c78-85ed-64a88d83fbcb', 'Curl de bíceps inverso a una pierna con toalla', ARRAY['Siéntate o túmbate con una pierna flexionada y sujeta la toalla con ambas manos por los extremos.', 'Pisa la toalla con el pie y tira de ella flexionando los codos con las palmas hacia abajo.', 'Sube apretando el antebrazo y baja despacio resistiendo la tensión de la toalla.', 'Evita encoger los hombros o tirar con la espalda: el movimiento sale del codo.']::text[], 'intermedio', 'Refuerza antebrazos y agarre con un curl inverso usando una toalla, mejorando la fuerza de prensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3831'),
('ac209b25-1519-534f-a646-8d971e0ce28e', 'Extensión de cadera a una pierna recta acostado', ARRAY['Túmbate boca abajo con las piernas estiradas y las manos bajo la frente.', 'Aprieta el glúteo y eleva una pierna recta hasta donde puedas sin arquear la espalda.', 'Mantén un segundo arriba y baja la pierna despacio antes de cambiar de lado.', 'Evita girar la cadera o subir demasiado: el movimiento debe ser corto y controlado.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales con una extensión de cadera que mejora la estabilidad lumbar y la fuerza posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1776'),
('673142b1-fa69-5b91-b25e-618f63904128', 'Marcha con piernas rectas tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y las lumbares pegadas al suelo.', 'Eleva una pierna recta hasta unos 45 grados sin arquear la espalda.', 'Bájala despacio alternando con la otra, como si marcharas en el aire.', 'Exhala al subir y evita que la zona lumbar se despegue del suelo.']::text[], 'intermedio', 'Activa el abdomen profundo y los flexores de cadera, mejorando el control del core sin cargar la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3496'),
('2bf4bd51-c9d7-5928-85bb-810f7aad7f2e', 'Elevación de piernas rectas tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos bajo los glúteos.', 'Sube ambas piernas juntas hasta la vertical manteniendo las lumbares apoyadas.', 'Baja lentamente sin llegar a tocar el suelo y sin arquear la espalda.', 'Exhala al subir y controla el descenso para evitar balanceos.']::text[], 'intermedio', 'Fortalece el abdomen bajo y los flexores de cadera, ganando control pélvico y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1181'),
('fdd65702-7c6c-5001-a045-f8499dbde91c', 'Respiración abdominal tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y una mano en el abdomen.', 'Inhala por la nariz llevando el aire al vientre, sin mover el pecho.', 'Exhala despacio por la boca notando cómo el abdomen baja.', 'Evita forzar el cuello y mantén los hombros relajados.']::text[], 'principiante', 'Reeduca el diafragma y relaja el core, útil para reducir tensión y mejorar la estabilidad profunda.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '9977'),
('fbd40ade-e2fb-570e-883d-4c5a62f73e73', 'Deslizamiento de talón tumbado', ARRAY['Túmbate boca arriba con las piernas estiradas y los talones apoyados.', 'Desliza un talón hacia el glúteo flexionando la rodilla sin despegar el pie.', 'Vuelve a estirar la pierna despacio controlando el movimiento.', 'Mantén la lumbar apoyada y evita que la rodilla se desvíe hacia dentro.']::text[], 'principiante', 'Activa isquiotibiales y cuádriceps de forma suave, ideal para recuperar control y movilidad de rodilla.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '9969'),
('dc5f83a3-2fbb-59d7-8b91-2757cf0a2dc4', 'Elevación de rodilla recta tumbado', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Bloquea la rodilla de la pierna estirada y elévala unos centímetros.', 'Mantén unos segundos y baja despacio sin perder la contracción.', 'Evita arquear la lumbar y no aguantes la respiración.']::text[], 'principiante', 'Trabaja el cuádriceps y los flexores de cadera con control, útil para readaptar la extensión de rodilla.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '9971'),
('b66a5d44-e0f8-5df7-b4fb-3df71456f960', 'Estiramiento de movilidad de columna torácica tumbado', ARRAY['Túmbate de lado con las rodillas flexionadas y los brazos estirados al frente.', 'Abre el brazo de arriba hacia atrás siguiendo la mirada, sin mover las caderas.', 'Mantén la posición unos segundos respirando profundo.', 'Vuelve despacio y evita forzar la zona lumbar para girar más.']::text[], 'principiante', 'Mejora la rotación y extensión de la columna dorsal, aliviando rigidez y favoreciendo una postura erguida.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3539'),
('d7dc206b-f34e-55f7-9e2f-120a18fd5cda', 'Extensiones torácicas sobre rodillo de espuma', ARRAY['Coloca el rodillo perpendicular bajo la zona dorsal y apoya la cabeza.', 'Con las manos tras la nuca, extiende la espalda hacia atrás sobre el rodillo.', 'Sube el rodillo poco a poco por la espalda repitiendo la extensión.', 'Evita arquear la lumbar y no fuerces si notas dolor en las vértebras.']::text[], 'principiante', 'Moviliza la columna dorsal y abre el pecho, corrigiendo la rigidez por posturas mantenidas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11572'),
('217c3f0b-3927-50ce-8b66-ff22aad02fe6', 'Toque de punta tumbado', ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas a 90 grados.', 'Baja un pie hasta tocar el suelo sin despegar la lumbar.', 'Vuelve a subir y alterna con la otra pierna a ritmo controlado.', 'Exhala al bajar y evita que la espalda se arquee.']::text[], 'intermedio', 'Activa el abdomen bajo y los flexores de cadera con un movimiento corto y controlado del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6002'),
('7baa5daa-d1ed-599c-8a17-3c2f3261e182', 'Abdominal encogido tumbado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos en el pecho.', 'Encoge el tronco despegando solo los omóplatos del suelo.', 'Aprieta el abdomen arriba y baja despacio sin relajarlo del todo.', 'Evita tirar del cuello y no aguantes la respiración.']::text[], 'intermedio', 'Fortalece el recto abdominal con un rango corto, mejorando la flexión de tronco de forma segura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5274'),
('25a0b7a1-d61c-5ffe-9951-3f2900e3d9eb', 'Rotación de la parte alta del cuerpo tumbado', ARRAY['Túmbate boca arriba con los brazos en cruz y las rodillas flexionadas.', 'Deja caer las rodillas hacia un lado mientras giras la cabeza al contrario.', 'Mantén la posición respirando y vuelve al centro.', 'Alterna lados sin despegar los hombros del suelo.']::text[], 'principiante', 'Gana movilidad rotacional en la columna dorsal y oblicuos, mejorando la libertad de movimiento del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3414'),
('1eb834d5-7e8f-5d8f-8190-cfd801549471', 'Estiramiento de cuerpo completo tumbado', ARRAY['Túmbate boca arriba con brazos y piernas estirados.', 'Alarga los brazos por encima de la cabeza y estira los talones.', 'Mantén el estiramiento respirando profundo sin arquear en exceso.', 'Relaja despacio y evita rebotes bruscos.']::text[], 'principiante', 'Estira dorsales, core y cadena posterior, liberando tensión y mejorando la amplitud de movimiento general.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1798'),
('77d00cf7-0b95-537d-82a9-617631b53520', 'Press de pecho interno en máquina', ARRAY['Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.', 'Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.', 'Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.', 'Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la porción interna del pectoral con recorrido guiado, útil para volumen y control del empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1301'),
('683fc6fa-2ec4-5c13-8f38-770d35c77a57', 'Sentadilla isométrica en la pared', ARRAY['Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas.', 'Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados.', 'Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho.', 'Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho.', 'Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y cuádriceps en isométrico, mejorando la resistencia muscular y la estabilidad de piernas.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0624'),
('703d606a-f44f-58df-a9f2-9991fc2dac25', 'Marcha en el sitio', ARRAY['Colócate de pie con la espalda recta y el abdomen activo.', 'Eleva una rodilla a la altura de la cadera y baja alternando.', 'Acompaña el movimiento con los brazos de forma natural.', 'Mantén un ritmo constante y evita encorvar los hombros.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y core, sirviendo como calentamiento o trabajo cardiovascular suave.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4420'),
('e003bd3e-b5c0-562d-acca-619a6a83951e', 'Lanzamiento de balón medicinal hacia atrás sobre la cabeza', ARRAY['De pie con el balón entre las manos y los pies a la anchura de los hombros.', 'Flexiona caderas y rodillas llevando el balón entre las piernas.', 'Extiende todo el cuerpo con fuerza y lanza el balón hacia atrás sobre la cabeza.', 'Evita arquear la lumbar en exceso y usa un balón ligero para aprender el gesto.']::text[], 'intermedio', 'Desarrolla potencia de glúteos y cadena posterior mediante un gesto explosivo de extensión de cadera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10109'),
('093764be-5f3f-510f-a7b5-de5b855c318a', 'Lanzamiento hacia atrás con balón medicinal', ARRAY['Colócate de espaldas a la pared con los pies a la anchura de las caderas y el balón a la altura de la cadera.', 'Flexiona ligeramente rodillas y cadera llevando el balón entre las piernas.', 'Extiende con fuerza cadera y rodillas y lanza el balón hacia atrás contra la pared.', 'Recoge el balón tras el bote y repite sin perder la postura neutra de la espalda.', 'Evita redondear la zona lumbar en la flexión inicial.']::text[], 'intermedio', 'Potencia glúteos e isquios con un gesto explosivo que mejora la extensión de cadera y la coordinación global.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '3439'),
('d46833fa-44f1-5ae9-9e44-046daeb0f5fe', 'Atrape y lanzamiento sobre la cabeza con balón medicinal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho.', 'Flexiona ligeramente las rodillas y activa el core.', 'Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba.', 'Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza.', 'Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando.', 'Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales y hombros con un gesto explosivo de tracción y empuje que mejora la potencia del tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1353'),
('f7f0703a-8b5f-5a60-b905-d895170575d5', 'Pase de pecho con balón medicinal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.', 'Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho.', 'Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante.', 'Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato.', 'Continúa durante el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la potencia de pectorales y tríceps con un empuje explosivo que transfiere fuerza al gesto deportivo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1302'),
('813a2385-1b94-58f7-98fd-5543cd71d217', 'Empuje de pecho con balón medicinal desde tres apoyos', ARRAY['Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo.', 'Extiende las piernas y coloca tu cuerpo en línea recta.', 'Baja el pecho hacia el suelo manteniendo la espalda recta.', 'Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo.', 'Vuelve a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa pectorales y tríceps en un empuje explosivo que exige estabilidad del core y control postural.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1303'),
('06810f01-f295-55dc-af96-9d72070ebdd0', 'Empujes de pecho con balón medicinal encadenados', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.', 'Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho.', 'Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Potencia pectorales y tríceps con empujes repetidos y rápidos que mejoran la capacidad reactiva del tren superior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1304'),
('bb903c28-5c27-57c0-8eb4-920827d7bf76', 'Empuje de pecho con balón medicinal y salida en carrera', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho.', 'Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos.', 'Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar.', 'Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo.', 'Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante.', 'Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado.']::text[], 'intermedio', 'Combina potencia de pectorales y tríceps con un arranque explosivo que entrena la transferencia al sprint.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1312'),
('95966cff-d930-5c96-b8c1-3b1da3bd479d', 'Flexiones con agarre cerrado sobre balón medicinal', ARRAY['Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza tríceps, pecho y hombros con un apoyo inestable que exige control y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '1701'),
('8c889a8f-932a-5877-9cd5-4dacffb119c2', 'Abdominal con balón medicinal en balón de estabilidad', ARRAY['Siéntate en el balón de estabilidad con los pies apoyados y el balón medicinal sujeto con las manos a la altura del pecho.', 'Recuéstate dejando que la zona lumbar se adapte al balón y mantén la barbilla ligeramente hacia el pecho.', 'Flexiona el tronco hacia delante elevando los hombros y espirando al subir.', 'Baja de forma controlada sin dejar caer la cabeza hacia atrás.', 'Evita tirar del cuello con las manos; el movimiento nace del abdomen.']::text[], 'intermedio', 'Trabaja el recto abdominal con mayor recorrido y control sobre una superficie inestable que activa todo el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9010'),
('06b26fcb-f900-5a8f-9b5e-61cf5308afe7', 'Abdominal con balón medicinal', ARRAY['Túmbate boca arriba con las rodillas flexionadas y el balón medicinal sujeto con las manos frente al pecho.', 'Pega la zona lumbar al suelo y mantén la barbilla separada del pecho.', 'Flexiona el tronco elevando los hombros y espirando al subir.', 'Baja despacio controlando el descenso sin relajar del todo el abdomen.', 'Evita impulsarte con los brazos o tirar del cuello.']::text[], 'intermedio', 'Fortalece el recto abdominal y el core con una carga ligera que aumenta la exigencia del gesto de flexión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4253'),
('96e46333-7e5e-5bf8-bc5c-e65c3fd63d61', 'Empuje de pecho de rodillas con balón medicinal', ARRAY['Arrodíllate sobre una rodilla con el torso erguido y el balón medicinal a la altura del pecho.', 'Alinea la rodilla trasera con la cadera y activa el abdomen para estabilizar el tronco.', 'Empuja el balón hacia delante de forma explosiva extendiendo los brazos.', 'Recoge el balón con los codos ligeramente flexionados y repite.', 'Evita arquear la espalda al empujar; mantén el core firme.']::text[], 'intermedio', 'Desarrolla potencia de pectorales y tríceps desde una base estable que permite concentrarse en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4099'),
('93737920-983f-5662-b56d-b96acad7bc9a', 'Golpe horizontal con balón medicinal', ARRAY['Colócate de pie de lado a una pared con los pies a la anchura de las caderas y el balón a la altura del pecho.', 'Gira ligeramente el tronco hacia el lado contrario al lanzamiento cargando el gesto.', 'Empuja el balón contra la pared con un movimiento horizontal y explosivo.', 'Recoge el balón tras el bote y repite manteniendo el abdomen activo.', 'Evita rotar solo con los brazos; el giro nace de cadera y tronco.']::text[], 'intermedio', 'Entrena la potencia rotacional de pecho, hombros y oblicuos con un gesto explosivo de empuje lateral.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10197'),
('81a79e3f-1d7c-5348-bb84-e19e38c92455', 'Atrape de press cerrado tumbado con balón medicinal', ARRAY['Túmbate boca arriba con las rodillas flexionadas y el balón medicinal sujeto con las manos sobre el pecho.', 'Activa el abdomen y pega la zona lumbar al suelo.', 'Empuja el balón hacia arriba de forma explosiva extendiendo los codos.', 'Atrápalo a la vuelta con los codos ligeramente flexionados y sin perder el control.', 'Evita abrir los codos en exceso; mantén un agarre cerrado y estable.']::text[], 'intermedio', 'Potencia pectorales y tríceps con un gesto explosivo de empuje y recepción que exige control y estabilidad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10598'),
('97154006-4668-5a66-a9e2-768ae0750dfa', 'Golpe sobre la cabeza con balón medicinal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza.', 'Activa el core y mantén la espalda recta.', 'Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti.', 'Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core.', 'Atrapa el balón al rebotar y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda alta y el core con un gesto explosivo de elevación y golpe que mejora la potencia global.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1354'),
('03646666-8e4f-5e81-ba09-90fd3115a432', 'Círculo y golpe sobre la cabeza con balón medicinal', ARRAY['De pie con los pies a la anchura de las caderas, sujeta el balón medicinal con las dos manos.', 'Eleva el balón por encima de la cabeza dibujando un círculo amplio con los brazos.', 'Golpea el balón contra el suelo con fuerza flexionando el tronco y las rodillas.', 'Recoge el balón y repite el círculo en el mismo sentido o alternando.', 'Evita redondear la espalda al golpear; flexiona desde la cadera.']::text[], 'intermedio', 'Activa abdomen, dorsales y hombros con un gesto circular explosivo que exige coordinación y control del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10118'),
('c4187621-10cc-5125-8620-7af1bc889bbe', 'Lanzamiento por encima de la cabeza con balón medicinal', ARRAY['Colócate de pie frente a la pared con los pies a la anchura de las caderas y el balón a la altura del pecho.', 'Flexiona ligeramente rodillas y cadera llevando el balón entre las piernas.', 'Extiende con fuerza todo el cuerpo y lanza el balón por encima de la cabeza contra la pared.', 'Recoge el balón tras el bote y repite manteniendo el abdomen activo.', 'Evita arquear la zona lumbar en la extensión; acompaña el gesto con la cadera.']::text[], 'intermedio', 'Potencia abdomen, hombros y glúteos con un lanzamiento explosivo que entrena la extensión completa del cuerpo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '4243'),
('494dd9cc-803f-5768-9f22-421bf6f04925', 'Lanzamiento de balón medicinal sobre la cabeza', ARRAY['Colócate de pie con los pies a la anchura de los hombros y el balón a la altura del pecho.', 'Baja ligeramente en sentadilla y lleva el balón detrás de la cabeza con los brazos extendidos.', 'Lanza el balón hacia arriba y adelante extendiendo caderas, rodillas y brazos de forma explosiva.', 'Exhala en el lanzamiento y evita arquear la zona lumbar en la fase final.']::text[], 'intermedio', 'Potencia el core y la cadena posterior con un gesto explosivo que mejora la transferencia de fuerza al salto y al sprint.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10108'),
('69defcfd-d6ca-5d62-bf4c-a77f637299ce', 'Atrape de pullover con balón medicinal', ARRAY['Túmbate boca arriba con las rodillas flexionadas y el balón sobre el pecho.', 'Lleva el balón por encima de la cabeza con los brazos casi extendidos.', 'Lánzalo hacia arriba y atrápalo con las manos, controlando el movimiento.', 'Mantén las costillas abajo y evita despegar la zona lumbar del suelo.']::text[], 'intermedio', 'Trabaja dorsales y core con un gesto de tracción que mejora la estabilidad del hombro y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10595'),
('ad9f5262-6d29-5fa5-b2ca-ed82b710f82e', 'Sentadilla con leñador inverso y balón medicinal', ARRAY['De pie con los pies a la anchura de los hombros, sujeta el balón arriba a un lado.', 'Baja en sentadilla mientras llevas el balón en diagonal hacia la cadera contraria.', 'Sube extendiendo piernas y devuelve el balón a la posición inicial con control.', 'Exhala en el descenso y evita girar solo con los brazos sin acompañar con el tronco.']::text[], 'intermedio', 'Combina sentadilla y rotación para fortalecer oblicuos, glúteos y cuádriceps mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1697'),
('d0ae9dfa-06d7-5b82-a5b1-48723c8c6004', 'Lanzamiento rotacional con balón medicinal', ARRAY['Colócate de pie de lado a una pared con el balón a la altura de la cadera.', 'Gira el tronco cargando el peso en la pierna trasera.', 'Lanza el balón contra la pared rotando caderas y tronco de forma explosiva.', 'Recoge el balón y repite evitando bloquear la respiración durante el giro.']::text[], 'intermedio', 'Desarrolla la potencia rotacional del core y la coordinación entre cadera y tronco para gestos deportivos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '1699'),
('efaa299a-0b2b-5925-ae15-8d07d3044b4f', 'Peso muerto a una pierna con balón medicinal', ARRAY['De pie sobre una pierna con el balón sujeto con ambas manos frente al muslo.', 'Inclina el tronco hacia delante mientras la otra pierna se eleva hacia atrás.', 'Baja el balón hacia el suelo manteniendo la espalda recta y la cadera nivelada.', 'Vuelve a la posición inicial apretando el glúteo y evita redondear la espalda.']::text[], 'intermedio', 'Fortalece isquiotibiales y glúteos mejorando el equilibrio y la estabilidad de la cadera en apoyo monopodal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1693'),
('ac98c26a-a8c4-5617-964d-97be8962db32', 'Leñador a una pierna con balón medicinal', ARRAY['De pie sobre una pierna con el balón arriba a un lado del cuerpo.', 'Lleva el balón en diagonal hacia la cadera contraria mientras flexionas ligeramente la rodilla.', 'Controla el movimiento y vuelve a subir el balón con el tronco estable.', 'Mantén la rodilla alineada con el pie y evita perder el equilibrio girando solo los brazos.']::text[], 'intermedio', 'Trabaja oblicuos y core en apoyo monopodal, mejorando el equilibrio y la estabilidad dinámica del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1704'),
('1bb5bb84-2d3d-5e32-bfba-cab515af8551', 'Abdominal con golpe de balón medicinal', ARRAY['Túmbate boca arriba con las rodillas flexionadas y el balón sobre el pecho.', 'Sube el tronco en abdominal y lanza el balón hacia delante con fuerza.', 'Recoge el balón y baja controlando la espalda hasta el suelo.', 'Exhala en el lanzamiento y evita tirar del cuello con las manos.']::text[], 'intermedio', 'Potencia la musculatura abdominal con un gesto explosivo que mejora la fuerza del core y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10558'),
('8fca51e9-902c-538d-99df-54bbade0bea5', 'Salto de patinador con balón medicinal', ARRAY['De pie con el balón sujeto frente al pecho y las rodillas ligeramente flexionadas.', 'Salta lateralmente hacia un lado aterrizando sobre una pierna.', 'Amortigua el aterrizaje flexionando la rodilla y manteniéndola alineada con el pie.', 'Salta de vuelta al otro lado y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Mejora la potencia lateral de glúteos y cuádriceps con un salto que entrena la estabilidad en apoyo monopodal.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10758'),
('c82a0f90-46f9-5ff9-9319-080c90b7c028', 'Giro de torso con piernas divididas y balón medicinal', ARRAY['Colócate en zancada dividida con el balón sujeto frente al pecho.', 'Gira el tronco hacia un lado manteniendo las caderas estables.', 'Vuelve al centro y gira hacia el otro lado con control.', 'Exhala en cada giro y evita mover las rodillas o los pies durante el movimiento.']::text[], 'intermedio', 'Fortalece oblicuos y core con una rotación controlada que mejora la estabilidad del tronco en posición dividida.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10552'),
('ac54400e-493c-5493-9029-98a6aa4137b2', 'Salto con sentadilla y balón medicinal', ARRAY['De pie con el balón sujeto frente al pecho y los pies a la anchura de los hombros.', 'Baja en sentadilla llevando las caderas atrás y el pecho arriba.', 'Salta extendiendo piernas y brazos de forma explosiva.', 'Aterriza con las rodillas flexionadas y evita que se vayan hacia dentro.']::text[], 'intermedio', 'Desarrolla la potencia de cuádriceps y glúteos con un salto explosivo que mejora la fuerza del tren inferior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '3877'),
('0e396d13-947d-5412-80ca-cbad5a7ca388', 'Lanzamiento sobre la cabeza de pie con balón medicinal', ARRAY['De pie frente a una pared con el balón a la altura del pecho.', 'Lleva el balón detrás de la cabeza flexionando ligeramente las rodillas.', 'Lanza el balón contra la pared extendiendo brazos y caderas con fuerza.', 'Recoge el balón y evita arquear la espalda en el lanzamiento.']::text[], 'intermedio', 'Potencia pectorales y hombros con un lanzamiento explosivo que mejora la fuerza del tren superior y el core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '3442'),
('1c5677f8-5e3a-5517-9026-c475d8d844d6', 'Lanzamiento rotacional con paso atrás y balón medicinal', ARRAY['De pie de lado a la pared con el balón a la altura de la cadera.', 'Da un paso atrás con la pierna trasera cargando el peso.', 'Lanza el balón contra la pared rotando caderas y tronco con fuerza.', 'Recoge el balón y repite evitando girar solo con los brazos.']::text[], 'intermedio', 'Entrena la potencia rotacional del core con un paso atrás que suma coordinación y fuerza de piernas.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '4383'),
('54447e22-b872-5cf3-9e37-d1fa0be14934', 'Meditación', ARRAY['Siéntate con la espalda recta y las manos sobre las rodillas.', 'Cierra los ojos y respira lento por la nariz.', 'Centra la atención en la respiración y deja pasar los pensamientos.', 'Evita forzar la postura y mantén los hombros relajados.']::text[], 'intermedio', 'Favorece la relajación y la conciencia corporal, mejorando la respiración y reduciendo el estrés.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5894'),
('b8000e8a-a109-5fba-9ed5-7a248f8dbe22', 'Postura de la sirena', ARRAY['Siéntate de lado con las piernas flexionadas y la mano apoyada en el suelo.', 'Eleva el brazo libre por encima de la cabeza y alarga el costado.', 'Inclínate lateralmente manteniendo las caderas estables.', 'Respira profundo y evita comprimir el cuello o forzar la curva.']::text[], 'intermedio', 'Estira la columna y los costados, mejorando la movilidad del tronco y la flexibilidad de oblicuos y dorsales.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2879'),
('c76ccce7-75f6-5234-a5e9-fce0ec2093c0', 'Elevaciones laterales en el aire con cambio de palmas', ARRAY['De pie con una mancuerna en cada mano y los brazos a los lados.', 'Eleva los brazos lateralmente hasta la altura de los hombros girando las palmas hacia arriba.', 'Baja controlando el movimiento y girando las palmas hacia abajo.', 'Evita encoger los hombros y mantener el core activo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja el deltoides lateral con un gesto controlado que mejora la estabilidad del hombro y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3825'),
('331683eb-39c2-5844-9a43-111c17d198cf', 'Apretón de codos en la espalda media', ARRAY['Colócate de pie o sentado con la espalda recta y los brazos flexionados a la altura del pecho.', 'Junta los omóplatos llevando los codos hacia atrás sin mover los hombros hacia arriba.', 'Aguanta el apretón dos segundos y suelta despacio, respirando con normalidad.', 'Evita encoger el cuello o arquear la zona lumbar al apretar.']::text[], 'intermedio', 'Activa la espalda alta y los romboides para mejorar la postura y contrarrestar las horas encorvado estudiando.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8585'),
('a529c848-970f-5b0c-9e50-7ade13bc0a85', 'Estiramiento de espalda media', ARRAY['Siéntate o ponte de pie y entrelaza los dedos delante del pecho.', 'Redondea la espalda empujando las manos hacia delante y separando los omóplatos.', 'Mantén la posición entre veinte y treinta segundos respirando despacio.', 'No fuerces el cuello hacia abajo ni aguantes la respiración.']::text[], 'principiante', 'Relaja la musculatura entre los omóplatos y alivia la tensión acumulada por malas posturas al estudiar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4288'),
('41fac7f9-6813-5a8d-92ad-b7c6c46b745f', 'Meditación de respiración consciente', ARRAY['Siéntate con la espalda erguida y las manos apoyadas sobre los muslos.', 'Cierra los ojos y dirige la atención a la entrada y salida del aire por la nariz.', 'Cuando la mente se distraiga, vuelve suavemente a la respiración sin juzgarte.', 'Respira de forma natural, sin forzar el ritmo ni la profundidad.']::text[], 'intermedio', 'Calma el sistema nervioso y mejora la concentración mediante la atención plena a la respiración.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5895'),
('db51e085-ce6a-55aa-996f-f62ecaec1560', 'Dominada supina con agarre mixto', ARRAY['Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con un agarre asimétrico que exige control y estabilidad en el tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0627'),
('b034bbd1-fc4a-5c50-928c-4e896587dfd4', 'Movilización de tobillo', ARRAY['Apoya la punta del pie sobre una superficie elevada con el talón en el suelo.', 'Lleva la rodilla hacia delante por encima de los dedos sin levantar el talón.', 'Mantén unos segundos al final del recorrido y vuelve despacio.', 'Evita que el pie se gire hacia fuera o que el talón se despegue.']::text[], 'principiante', 'Gana rango de movimiento en el tobillo para mejorar la sentadilla y prevenir molestias al caminar o correr.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1969'),
('903a1904-bc69-59ff-938b-26d3a34a35e3', 'Flexión hindú modificada', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas.', 'Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado.', 'Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.', 'Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pecho, hombros y tríceps con un recorrido fluido que también moviliza la columna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3217'),
('3d628315-0dab-5268-a064-652876465e9f', 'Flexión modificada a antebrazos', ARRAY['Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado.', 'Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros.', 'Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza antebrazos, tríceps y pecho con una variante de flexión que reduce la carga en muñecas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1421'),
('ae863bea-265b-588f-9fc5-cf71f51b4b6b', 'Caminata del monstruo', ARRAY['Coloca una banda elástica alrededor de los tobillos.', 'Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.', 'Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica.', 'Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Activa glúteos y piernas con pasos laterales que mejoran la estabilidad de cadera y rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0628'),
('c8c5956e-774f-52ba-9d8f-b967ce22aa39', 'Escalador con patada cruzada', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Lleva una rodilla hacia el codo contrario cruzando la cadera.', 'Vuelve a la posición inicial y alterna el otro lado a ritmo constante.', 'Mantén la cadera baja y evita que el culo suba al cambiar de pierna.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja el abdomen con una patada cruzada que activa los oblicuos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '9048'),
('6202bf91-268d-5f2f-8b50-b383c3794ba7', 'Escalador con salto', ARRAY['Parte de plancha alta con los hombros sobre las manos y el abdomen firme.', 'Salta llevando las dos rodillas al pecho a la vez y vuelve a extender las piernas.', 'Aterriza con suavidad sobre la punta de los pies y mantén el ritmo.', 'Evita hundir la zona lumbar o perder la alineación de la cabeza al saltar.']::text[], 'intermedio', 'Ejercicio pliométrico intenso que eleva las pulsaciones y trabaja core y piernas con explosividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4976'),
('c2c03653-4c62-583d-a7a9-a63327aa4c54', 'Escalador con zancada', ARRAY['Colócate en plancha alta con el core activo y la mirada al suelo.', 'Lleva un pie junto a la mano del mismo lado formando una zancada.', 'Vuelve a la plancha y alterna el otro lado sin perder la alineación.', 'No dejes caer la cadera ni bloquees la respiración durante el movimiento.']::text[], 'intermedio', 'Combina cardio y fuerza llevando una pierna a zancada frontal mientras mantienes la plancha.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0629'),
('a0503eb0-6f62-5e5f-8745-33aeb79e9798', 'Escalador deslizante con toalla', ARRAY['Coloca una toalla bajo los pies y adopta una plancha alta sobre las manos.', 'Desliza un pie hacia delante acercando la rodilla al pecho sin mover el tronco.', 'Vuelve a deslizar el pie atrás y alterna el otro lado con control.', 'Evita que la cadera se eleve o que los hombros se adelanten a las manos.']::text[], 'intermedio', 'Trabaja el abdomen con un deslizamiento controlado que exige estabilidad y coordinación en el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5156'),
('9ed91c63-ebfd-5e86-aa5d-a39d662f8e3a', 'Escalador', ARRAY['Adopta una plancha alta con las manos bajo los hombros y el cuerpo recto.', 'Lleva una rodilla al pecho y vuelve a extenderla mientras la otra avanza.', 'Alterna las piernas a un ritmo ágil pero controlado.', 'Mantén la cadera estable y evita rebotar o encorvar la espalda.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y fortalece el abdomen con un movimiento rápido y constante en plancha.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5213'),
('a1618fdf-4366-5763-b70c-c003ae0cd703', 'Postura de la montaña', ARRAY['Ponte de pie con los pies juntos o a la anchura de las caderas.', 'Reparte el peso por todo el pie y alarga la columna hacia el techo.', 'Relaja los hombros y deja los brazos caer junto al cuerpo con las palmas al frente.', 'Respira despacio y evita bloquear las rodillas o sacar las costillas.']::text[], 'intermedio', 'Postura base del yoga que alinea la columna y activa el core para mejorar la postura y el equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5896'),
('c6bf3d85-5dd6-511f-b436-372facdf702e', 'Postura del niño en movimiento', ARRAY['Arrodíllate y siéntate sobre los talones con los brazos estirados al frente.', 'Desliza las manos hacia un lado y luego hacia el otro manteniendo la cadera atrás.', 'Acompaña el movimiento con la respiración y mantén cada lado unos segundos.', 'Evita levantar la cadera o forzar los hombros al estirar.']::text[], 'principiante', 'Estira dorsales y zona lumbar con un balanceo suave que relaja la espalda tras el estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8130'),
('267acfdf-efcd-5c2b-8865-bf99cce228cc', 'Abdominal miotático en bosu', ARRAY['Colócate sentado sobre el bosu con los pies sujetos y el tronco ligeramente inclinado atrás.', 'Sube hasta la mitad y deja caer el tronco para aprovechar el rebote elástico del bosu.', 'Contrae el abdomen con fuerza para volver a subir y controla la bajada.', 'Exhala al subir e inhala al bajar, sin tirar del cuello.', 'Evita arquear la zona lumbar en exceso y no rebotes sin control.']::text[], 'intermedio', 'Trabaja el abdomen con rebote controlado en el bosu para ganar potencia y estabilidad en el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5228'),
('58b38c1b-1be0-5fa7-b328-f54bcf8d0c08', 'Postura de yoga namaskarasana', ARRAY['Siéntate con las piernas abiertas y la espalda erguida sobre la esterilla.', 'Junta las palmas de las manos frente al pecho en gesto de saludo.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda larga.', 'Respira profundo y mantén la postura sin forzar los aductores.', 'Evita redondear la espalda o rebotar para llegar más lejos.']::text[], 'intermedio', 'Estira aductores e ingles abriendo las piernas, mejora la movilidad de cadera y la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6138'),
('1cbcc219-78ad-534f-aa43-1f39e58915bc', 'Puente con piernas juntas en banco', ARRAY['Apoya la parte alta de la espalda en el banco y los pies en el suelo con las rodillas juntas.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba un segundo y baja controlando el movimiento.', 'Exhala al subir e inhala al bajar sin perder la tensión.', 'Evita arquear la lumbar en exceso o separar las rodillas.']::text[], 'intermedio', 'Activa glúteos e isquios con las piernas juntas para mejorar la extensión de cadera y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0632'),
('e02bb8ff-f383-51cc-82f3-1c569b3606cd', 'Flexiones cerradas en balón de estabilidad', ARRAY['Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros.', 'Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.', 'Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo.', 'Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el tríceps y el pecho con un apoyo inestable que exige control y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2328'),
('72b6c0f4-b067-5cf7-a218-091a8ada6bba', 'Dominada supina sentado con agarre cerrado', ARRAY['Cuelga de la barra con agarre supino y las manos juntas, brazos estirados.', 'Tira de los codos hacia abajo llevando el pecho hacia la barra.', 'Sube controlando y baja sin soltar la tensión de los dorsales.', 'Exhala al subir e inhala al bajar manteniendo el core activo.', 'Evita balancearte o encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con agarre supino cerrado, mejorando la fuerza de tracción y el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4773'),
('25b6f999-02c1-50fc-86ed-17fbb5e1a645', 'Sentadilla cerrada desde déficit', ARRAY['Colócate de pie sobre una superficie elevada con los pies juntos.', 'Baja flexionando rodillas y cadera manteniendo el pecho alto.', 'Empuja con los talones para subir controlando el movimiento.', 'Inhala al bajar y exhala al subir sin perder el equilibrio.', 'Evita que las rodillas se metan hacia dentro o levantar los talones.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con pies juntos y rango extra, mejorando fuerza y movilidad de tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3392'),
('02e9656f-6f0a-50dc-a382-988d0e457077', 'Dominada cerrada de media amplitud', ARRAY['Cuelga de la barra con agarre cerrado y los brazos casi estirados.', 'Tira de los codos hacia abajo llevando el pecho a la barra.', 'Mantén la parte alta un instante y baja controlando el rango corto.', 'Exhala al subir e inhala al bajar sin balancearte.', 'Evita encoger los hombros o usar impulso de piernas.']::text[], 'intermedio', 'Trabaja la parte alta de la tracción con agarre cerrado, reforzando dorsales y bíceps en rango corto.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4913'),
('a7031268-7fdc-5ea7-b34d-5de816b7735b', 'Puente de cuello boca abajo', ARRAY['Túmbate boca abajo con las manos apoyadas a la altura de los hombros.', 'Empuja el suelo y eleva el pecho arqueando suavemente la espalda.', 'Lleva la cabeza atrás con control sin forzar el cuello.', 'Respira de forma constante y mantén la posición unos segundos.', 'Evita cargar todo el peso en la cabeza o hacer movimientos bruscos.']::text[], 'intermedio', 'Fortalece la musculatura cervical posterior y escapular, mejorando la estabilidad del cuello y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0633'),
('d3f0c783-d37a-524c-b1be-28b1d163d6d9', 'Estiramiento de cuello en círculos', ARRAY['Siéntate o ponte de pie con la espalda recta y los hombros relajados.', 'Dibuja círculos lentos con la barbilla hacia el pecho.', 'Cambia de sentido tras varias repeticiones sin forzar el rango.', 'Respira de forma pausada y mantén los hombros bajos.', 'Evita hacer círculos completos hacia atrás o movimientos rápidos.']::text[], 'principiante', 'Moviliza el cuello y relaja la musculatura cervical, aliviando tensión y mejorando la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3994'),
('f3f3f6af-80b2-5f96-bbd6-f0da51470bff', 'Estiramiento de extensión de cuello', ARRAY['Siéntate con la espalda recta y los hombros relajados.', 'Lleva la barbilla hacia arriba y atrás con suavidad.', 'Mantén el estiramiento sin forzar y respira profundo.', 'Vuelve despacio a la posición neutra.', 'Evita echar la cabeza demasiado atrás o sentir dolor.']::text[], 'principiante', 'Estira la musculatura anterior del cuello, mejorando la movilidad cervical y aliviando tensión acumulada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1833'),
('7f063d2b-cb2d-56cc-8b61-54684defd9b4', 'Estiramiento de extensores del cuello', ARRAY['Siéntate con la espalda recta y los hombros bajos.', 'Baja la barbilla hacia el pecho lentamente.', 'Puedes apoyar suavemente la mano en la nuca sin tirar fuerte.', 'Respira profundo y mantén el estiramiento unos segundos.', 'Evita tirar con fuerza o rebotar en la posición.']::text[], 'principiante', 'Relaja la musculatura posterior del cuello, aliviando tensión y mejorando la flexibilidad cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1837'),
('b745fdd6-6b0f-5618-a450-25ecb173d9b1', 'Estiramiento de flexores del cuello', ARRAY['Siéntate con la espalda recta y los hombros relajados.', 'Lleva la barbilla hacia arriba y hacia un lado con suavidad.', 'Mantén el estiramiento sin forzar y respira pausado.', 'Cambia de lado tras unos segundos.', 'Evita mover la cabeza de forma brusca o sentir dolor.']::text[], 'principiante', 'Estira la musculatura anterior del cuello, mejorando la movilidad y reduciendo tensión en la zona cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1839'),
('6a1ed1ba-d014-5720-ada1-7802dabea045', 'Estiramiento de protracción de cuello', ARRAY['Siéntate con la espalda recta y los hombros bajos.', 'Lleva la cabeza hacia delante suavemente, como una tortuga.', 'Mantén la posición sin forzar y respira profundo.', 'Vuelve despacio a la posición neutra.', 'Evita encoger los hombros o hacer movimientos rápidos.']::text[], 'principiante', 'Estira la musculatura cervical y escapular, corrigiendo la postura adelantada y aliviando tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1834'),
('dc662179-4011-525e-81df-db1eaf51c0a5', 'Curl concentrado de bíceps en pierna negativo', ARRAY['Siéntate y apoya el codo en la cara interna del muslo con el brazo estirado.', 'Sube la mano hacia el hombro contrayendo el bíceps.', 'Baja muy despacio, controlando la fase negativa.', 'Exhala al subir e inhala al bajar sin balancear el tronco.', 'Evita mover el codo o usar impulso del cuerpo.']::text[], 'intermedio', 'Aísla el bíceps con el codo apoyado en la pierna, controlando la fase negativa para ganar fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8084'),
('162d7c2a-f481-5aff-8720-5ff22a7e72f9', 'Abdominal negativo', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el recto abdominal con énfasis en la fase excéntrica, mejorando el control y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0634'),
('014a0346-8a9e-53ce-85ac-46b31fa5b729', 'Elevación negativa de front lever', ARRAY['Cuélgate de la barra con los brazos estirados y el cuerpo en línea recta.', 'Sube hasta la posición de front lever con las caderas a la altura de los hombros.', 'Baja lentamente manteniendo el cuerpo rígido y sin arquear la espalda.', 'Controla la respiración y evita soltar de golpe al final del recorrido.']::text[], 'avanzado', 'Fortalece el abdomen y los dorsales con una bajada controlada que exige gran tensión en todo el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11090'),
('2ed73e2a-fb15-5d9a-89ef-b75a32e97189', 'Flexión negativa', ARRAY['Colócate en posición de plancha alta con las manos bajo los hombros.', 'Baja el pecho hacia el suelo de forma lenta y controlada.', 'Mantén el cuerpo alineado sin dejar caer la cadera.', 'Apoya las rodillas para volver arriba y evita rebotar en la bajada.']::text[], 'intermedio', 'Refuerza pectorales y tríceps controlando la bajada, ideal para progresar hacia flexiones completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5556'),
('651e3d8b-010c-5412-9ab2-f90c92746675', 'Enrollador de muñeca neutro', ARRAY['Sujeta el enrollador con las palmas enfrentadas y los brazos extendidos.', 'Enrolla la cuerda levantando el peso girando solo las muñecas.', 'Sube y baja el peso de forma controlada sin mover los codos.', 'Evita balancear el torso y mantén los hombros relajados.']::text[], 'intermedio', 'Desarrolla la fuerza de antebrazos y agarre mediante un movimiento de enrollado con muñeca en posición neutra.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8882'),
('ce8facf6-e277-5102-a257-1ed6bb80fcc5', 'Curl nórdico de isquiotibiales', ARRAY['Arrodíllate con las piernas fijas y el torso erguido.', 'Inclínate hacia delante resistiendo con los isquiotibiales todo lo posible.', 'Frena la caída con las manos y empuja para volver arriba.', 'Mantén la cadera extendida y evita doblarla durante el descenso.']::text[], 'avanzado', 'Fortalece los isquiotibiales con una contracción excéntrica intensa que mejora la prevención de lesiones.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7746'),
('07acb3b5-8e33-530c-927c-5c6744609c2b', 'Abdominal oblicuo', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.', 'Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa la musculatura oblicua y el recto abdominal para mejorar la estabilidad y rotación del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1495'),
('516ebe81-9489-5742-a8db-ac9c4f17ad20', 'Abdominales oblicuos en el suelo', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.', 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.', 'Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.', 'Repite hacia el otro lado, alternando los lados en cada repetición.']::text[], 'intermedio', 'Trabaja los oblicuos y el abdomen desde el suelo para ganar control y fuerza en la cintura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0635'),
('02787e22-cbdb-5d08-8ffd-1f3647eaf16c', 'Abdominal oblicuo con elevación de pierna flexionada', ARRAY['Túmbate boca arriba con las manos en la nuca y una rodilla flexionada.', 'Eleva el hombro hacia la rodilla contraria contrayendo el oblicuo.', 'Sube la pierna flexionada a la vez que realizas el crunch.', 'Baja de forma controlada sin tirar del cuello.']::text[], 'intermedio', 'Combina oblicuos y abdomen bajo elevando la rodilla, mejorando la coordinación y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3330'),
('072b15c8-42ec-55e3-8996-cf7ba11f8243', 'Abdominal oblicuo con elevación de pierna recta', ARRAY['Túmbate boca arriba con las manos en la nuca y las piernas estiradas.', 'Eleva una pierna recta mientras acercas el hombro contrario.', 'Contrae el oblicuo en la subida y controla la bajada.', 'Evita arquear la zona lumbar y no tires del cuello.']::text[], 'intermedio', 'Refuerza oblicuos y abdomen bajo con la pierna estirada, aumentando la exigencia sobre el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3331'),
('153f873e-a529-5038-903a-77561e319e4b', 'Curl martillo con barra olímpica', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono.', 'Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo.', 'Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.', 'Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.', 'Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.', 'Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos con agarre neutro, ganando fuerza y volumen en el brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0636'),
('a80089c9-b358-5f5b-9ff6-7f1c57125a9a', 'Extensión de tríceps con barra olímpica', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono.', 'Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.', 'Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.', 'Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps para desarrollar fuerza y volumen en la parte posterior del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0637'),
('816f9f4b-ce96-5524-aca1-9504fcd4f1f7', 'Un brazo contra la pared', ARRAY['Ponte de pie frente a una pared con los pies separados a la altura de los hombros.', 'Extiende un brazo recto hacia adelante y coloca la palma contra la pared.', 'Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana.', 'Empuja lentamente la pared con la palma, activando los dorsales.', 'Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo.']::text[], 'intermedio', 'Isométrico que activa dorsales y hombros empujando contra la pared para ganar estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1355'),
('a0637905-1127-5046-bb06-ff4f0ff3c3e0', 'Dominada supina a un brazo', ARRAY['Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.', 'Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo.', 'Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado.', 'Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de brazo y repite.']::text[], 'avanzado', 'Ejercicio avanzado que exige gran fuerza de dorsales y bíceps con un solo brazo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0638'),
('f9324ebe-05ae-5c8b-aa66-93cea7a96b2c', 'Fondos a un brazo', ARRAY['Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros.', 'Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo.', 'Extiende las piernas hacia adelante, manteniendo los talones en el suelo.', 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla.', 'Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con una exigencia extrema de fuerza y control unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0639'),
('0a1b1b3d-2498-5c2c-801e-645e4c9198aa', 'Estiramiento de dorsal a un brazo', ARRAY['Sujeta una barra o apoyo con una mano y da un paso atrás.', 'Inclina el torso y deja que el brazo se extienda para estirar el dorsal.', 'Mantén la posición sin rebotar y respira de forma profunda.', 'Evita forzar el hombro y cambia de lado con control.']::text[], 'principiante', 'Estira dorsales y hombros para mejorar la movilidad y aliviar tensión en la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1801'),
('739b04f0-9e9f-5045-a315-de057f32dc25', 'Estiramiento de flexores del hombro a un brazo', ARRAY['Coloca una mano en la pared o en el marco de una puerta a la altura del hombro.', 'Gira el torso hacia el lado contrario hasta notar un estiramiento suave en la parte delantera del hombro.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita arquear la zona lumbar o forzar el hombro hacia atrás.']::text[], 'principiante', 'Estira la parte delantera del hombro y el pecho, aliviando tensión tras entrenar press o pasar horas sentado estudiando.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1976'),
('a7e5b80f-3c33-5552-a7da-a935667bc75e', 'Golpe a un brazo con balón medicinal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura.', 'Flexiona ligeramente las rodillas y activa el core.', 'Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo.', 'Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia.', 'Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Potencia la fuerza del core y la coordinación al lanzar el balón con un solo brazo desde arriba.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '0640'),
('5db1d9c7-3ad9-5e40-93b0-2dbd07bc6598', 'Cargada y press con giro a un brazo', ARRAY['Sujeta la mancuerna con una mano a la altura de la cadera y flexiona ligeramente las rodillas.', 'Sube la mancuerna con un tirón rápido hasta el hombro girando la muñeca.', 'Empuja la mancuerna por encima de la cabeza mientras giras el torso ligeramente.', 'Baja con control hasta la posición inicial y evita arquear la espalda al press.']::text[], 'intermedio', 'Trabaja hombros, core y piernas en un movimiento explosivo que mejora la coordinación y la potencia global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2814'),
('7ab9c6b8-f7ab-5b2b-bcd5-a408ddc1aaeb', 'Colgado con una mano', ARRAY['Agarra la barra con una sola mano a la anchura del hombro.', 'Cuelga con el brazo estirado y el cuerpo relajado, sin balancearte.', 'Mantén el tiempo objetivo respirando de forma constante.', 'Baja con control antes de soltar y evita encoger el hombro hacia la oreja.']::text[], 'intermedio', 'Desarrolla fuerza de agarre y resistencia en antebrazos, fundamental para dominadas y ejercicios de suspensión.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1357'),
('f6675aa9-e2ee-57ef-8367-623f55c6d759', 'Elevación de gemelos a una pierna en el suelo', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio.', 'Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.', 'Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Fortalece gemelos y tobillos con el peso corporal, mejorando el equilibrio y la estabilidad del pie.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1387'),
('fd0908cc-5492-5622-92c6-666a13596491', 'Patada trasera a una pierna con apoyo en banco', ARRAY['Apoya las manos en un banco y coloca el torso inclinado hacia delante.', 'Eleva una pierna hacia atrás manteniendo la rodilla ligeramente flexionada.', 'Aprieta el glúteo arriba un segundo y baja con control.', 'Evita arquear la zona lumbar o girar la cadera al subir la pierna.']::text[], 'intermedio', 'Aísla el glúteo y activa los isquios, útil para mejorar la extensión de cadera y la estabilidad lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1049'),
('c3d8c88f-4d9a-5adb-a8bf-5a4f487e22a0', 'Cuarto de sentadilla a una pierna', ARRAY['De pie sobre una pierna, extiende la otra ligeramente hacia delante.', 'Baja flexionando la rodilla de apoyo solo un cuarto del recorrido.', 'Empuja con el pie de apoyo para volver arriba manteniendo el equilibrio.', 'Evita que la rodilla se vaya hacia dentro y controla el descenso.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un rango parcial, preparando la pierna para sentadillas completas a una pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1578'),
('14530b77-bf78-5340-a863-9a30c0ac8078', 'Equilibrio en estrella a una pierna', ARRAY['De pie sobre una pierna con el torso erguido y la mirada al frente.', 'Extiende la pierna libre y los brazos hacia fuera formando una estrella.', 'Mantén la posición el tiempo indicado sin perder la alineación de la rodilla.', 'Evita bloquear la rodilla de apoyo o inclinar el tronco hacia un lado.']::text[], 'intermedio', 'Mejora el equilibrio, la estabilidad del tobillo y la fuerza del glúteo medio sobre una sola pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4212'),
('2be01b8b-3c64-5559-8e8d-8860e0ff9fa8', 'Postura del arco hacia arriba a una pierna', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies en el suelo.', 'Empuja con manos y pies para elevar la cadera y el pecho del suelo.', 'Levanta una pierna hacia arriba manteniendo la cadera elevada y estable.', 'Respira con calma y evita comprimir la zona lumbar al subir.']::text[], 'intermedio', 'Extiende la columna y abre el pecho, fortaleciendo glúteos y hombros en una variante avanzada de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6298'),
('45e7eda4-649c-512d-be59-c8a98f44c4e5', 'Flexión arquero a un lado', ARRAY['Colócate en posición de flexión con las manos más anchas que los hombros.', 'Baja el pecho hacia un lado flexionando ese codo mientras el otro se estira.', 'Empuja para volver arriba y alterna el lado en la siguiente repetición.', 'Evita que la cadera se hunda o que el codo se abra en exceso.']::text[], 'avanzado', 'Variante de flexión que carga más un pectoral, aumentando la fuerza de empuje de forma unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4153'),
('eec255cd-dca3-5215-938b-4436a6a9c577', 'Estiramiento de libro abierto', ARRAY['Túmbate de lado con las rodillas flexionadas y los brazos estirados al frente.', 'Abre el brazo de arriba hacia el otro lado girando el pecho, como un libro.', 'Sigue la mano con la mirada y mantén la cadera estable.', 'Respira profundo y evita forzar el hombro contra el suelo.']::text[], 'principiante', 'Moviliza la columna torácica y abre el pecho, aliviando la rigidez por malas posturas al estudiar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4601'),
('3a1658da-6345-5beb-92a5-3553298f3b2c', 'Elevación de brazo y pierna opuestos contra la pared', ARRAY['Colócate de pie frente a la pared con las manos apoyadas a la altura de los hombros.', 'Eleva un brazo y la pierna contraria a la vez manteniendo el torso estable.', 'Aprieta el glúteo y el core arriba un segundo y baja con control.', 'Evita arquear la espalda o girar la cadera al elevar la pierna.']::text[], 'intermedio', 'Activa la cadena posterior y el core, mejorando la estabilidad de la columna y la coordinación cruzada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7216'),
('319a5293-7f77-5e4f-96a0-c62963e10689', 'Otis up', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio abdominal con carga que trabaja el recto abdominal y los flexores de cadera con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0641'),
('c81e11ae-68ec-5415-b29b-fa9dd0cdb20f', 'Flexión con patada de pierna hacia fuera', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.', 'Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos.', 'Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición.', 'Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado.']::text[], 'intermedio', 'Combina el empuje de pecho con una extensión de cadera que activa glúteos y piernas para ganar fuerza global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0642'),
('1f915c22-c72f-5778-982d-3730e47ef326', 'Estiramiento de brazos rectos sobre la cabeza', ARRAY['Colócate de pie con la espalda recta y los pies a la anchura de las caderas.', 'Entrelaza los dedos y sube los brazos estirados por encima de la cabeza.', 'Abre el pecho y lleva los brazos ligeramente hacia atrás sin arquear la zona lumbar.', 'Mantén la posición entre veinte y treinta segundos respirando de forma profunda y relajada.', 'Evita encoger los hombros hacia las orejas y no fuerces si notas pinchazos.']::text[], 'principiante', 'Abre el pecho y los hombros para mejorar la postura y aliviar la tensión acumulada por estudiar muchas horas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1788'),
('e077dfba-2191-5ba8-a712-039c9aae9b9f', 'Palmada sobre la cabeza', ARRAY['Ponte de pie con los pies a la anchura de los hombros y el abdomen firme.', 'Sube los brazos por los lados hasta juntar las palmas por encima de la cabeza.', 'Baja los brazos con control hasta la altura de los hombros sin perder la postura.', 'Realiza el movimiento de forma fluida y coordinada con la respiración.', 'Evita arquear la espalda o encoger el cuello al subir los brazos.']::text[], 'principiante', 'Moviliza hombros y escápulas y activa el core, útil para calentar antes de entrenar o tras horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4665'),
('ae00ef19-f6e2-59a2-ba80-e281200228b8', 'Abdominal con brazos sobre la cabeza y piernas en banco', ARRAY['Túmbate boca arriba con las piernas apoyadas en el banco y las rodillas flexionadas.', 'Coloca las manos detrás de la cabeza sin tirar del cuello.', 'Eleva el tronco despegando las escápulas del suelo mientras exhalas.', 'Baja despacio controlando el movimiento y sin dejar caer la cabeza.', 'Evita impulsarte con las piernas o tirar del cuello con las manos.']::text[], 'intermedio', 'Refuerza el recto abdominal y los flexores de cadera con un rango controlado que exige estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7417'),
('72c92613-c782-593c-882a-5a164536e708', 'Extensión de tríceps sobre la cabeza con sábana', ARRAY['Sujeta la sábana por los extremos y pásala por detrás de la cabeza con los codos apuntando al frente.', 'Mantén los codos cerca de la cabeza y el abdomen firme durante todo el movimiento.', 'Estira los brazos hacia arriba venciendo la resistencia de la sábana.', 'Baja con control hasta notar el estiramiento del tríceps y repite.', 'Evita abrir los codos hacia los lados o arquear la espalda.']::text[], 'intermedio', 'Trabaja el tríceps en estiramiento usando una sábana como resistencia, ideal para entrenar en casa.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3745'),
('13ceacbb-b69d-5028-adbc-7e719952a2e2', 'Estiramiento de tríceps sobre la cabeza', ARRAY['Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros.', 'Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta.', 'Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps.', 'Mantén el estiramiento durante 15-30 segundos, luego suelta.', 'Repite del otro lado.']::text[], 'principiante', 'Relaja la parte posterior del brazo y el hombro, muy útil después de empujes y fondos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0643'),
('75f438f6-69b9-5097-add7-11f97096407f', 'Estiramiento de antebrazo con palmas hacia fuera', ARRAY['Extiende un brazo al frente con la palma hacia arriba y los dedos apuntando al suelo.', 'Con la otra mano, tira suavemente de los dedos hacia ti hasta notar el estiramiento.', 'Mantén la posición entre veinte y treinta segundos sin bloquear el codo.', 'Cambia de brazo y repite el estiramiento.', 'Evita forzar la muñeca o hacer movimientos bruscos.']::text[], 'principiante', 'Alivia la tensión de muñecas y antebrazos acumulada por escribir o usar el móvil durante horas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2090'),
('d25eb2c4-11c1-5903-970f-ad09cc6dc080', 'Remo invertido con rodillas flexionadas en barras paralelas', ARRAY['Colócate bajo las barras paralelas y agárralas con las palmas mirando hacia fuera.', 'Apoya los pies en el suelo con las rodillas flexionadas y el cuerpo recto.', 'Tira del pecho hacia las barras juntando las escápulas mientras exhalas.', 'Baja con control hasta estirar los brazos sin perder la tensión.', 'Evita encoger los hombros o dejar caer la cadera durante el movimiento.']::text[], 'intermedio', 'Fortalece la espalda y los bíceps con el propio peso, mejorando la postura y la tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7554'),
('927ff3b2-89b2-5613-a7f3-9825132dcf65', 'Dominadas asistidas por compañero', ARRAY['Cuélgate de la barra con las palmas mirando hacia fuera y los brazos estirados.', 'Pide a tu compañero que te sujete suavemente por la cintura o las piernas.', 'Tira del cuerpo hacia arriba juntando las escápulas hasta pasar la barbilla por la barra.', 'Baja despacio controlando el descenso y sin soltarte de golpe.', 'Evita balancearte o dejar que el compañero haga todo el trabajo.']::text[], 'principiante', 'Permite progresar en dominadas con ayuda externa, trabajando dorsal y bíceps con seguridad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9510'),
('3fe7ed6a-ef0b-5f97-a4f7-50167495b427', 'Desplazamiento lateral en pareja', ARRAY['Colócate frente a tu compañero a un par de metros de distancia.', 'Desplázate lateralmente hacia un lado con pasos cortos y rodillas ligeramente flexionadas.', 'Mantén el tronco erguido y los brazos activos durante el movimiento.', 'Cambia de dirección al cruzarte con tu compañero sin chocar.', 'Evita cruzar los pies o perder el control de las rodillas.']::text[], 'intermedio', 'Mejora la agilidad y la fuerza de abductores y glúteos con desplazamientos rápidos en pareja.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5991'),
('bb760d45-c8f8-55f2-8eca-93566425c82f', 'Sentadilla con pausa', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros.', 'Baja flexionando caderas y rodillas hasta pasar la paralela manteniendo el pecho alto.', 'Haz una pausa de dos segundos en la posición baja sin perder la tensión.', 'Sube empujando el suelo con los pies y exhalando al final del recorrido.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'intermedio', 'Mejora la fuerza y el control en la parte baja de la sentadilla, reforzando cuádriceps y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5017'),
('0b5d7b45-0f7b-5a03-a290-fd91f93eacc9', 'Postura de yoga pavanamuktasana', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos a los lados.', 'Flexiona las rodillas y llévalas hacia el pecho abrazándolas con los brazos.', 'Acerca la frente a las rodillas si te resulta cómodo y respira profundo.', 'Mantén la postura entre treinta segundos y un minuto sin forzar el cuello.', 'Evita presionar la zona lumbar o levantar la cabeza con tensión.']::text[], 'intermedio', 'Libera la zona lumbar y los glúteos, aliviando la tensión tras largas horas sentado estudiando.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6120'),
('b4bc3a59-7820-542c-a4ec-ece97f69c4c2', 'Postura del pavo real mayurasana', ARRAY['Arrodíllate y apoya las palmas en el suelo con los dedos hacia los pies.', 'Junta los codos bajo el abdomen y apóyate sobre ellos con el cuerpo inclinado.', 'Estira las piernas hacia atrás y eleva el cuerpo manteniendo el equilibrio.', 'Respira de forma constante y mantén la postura solo el tiempo que controles.', 'Evita empezar sin calentar muñecas y antebrazos o perder la alineación del core.']::text[], 'intermedio', 'Postura avanzada de yoga que exige fuerza de core, antebrazos y muñecas para mantener el equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6293'),
('472f3c76-203f-5138-9107-ce70cc083bc4', 'Inclinación pélvica', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos a los lados del cuerpo.', 'Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.', 'Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.', 'Deshaz la inclinación y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza la pelvis y la zona lumbar, ayudando a tomar conciencia del core y a aliviar la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3147'),
('ea72a543-5c18-5659-9eff-38763b4497e5', 'Inclinación pélvica a puente', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.', 'Activa los glúteos y los músculos del core.', 'Inclina la pelvis hacia arriba, levantando las caderas del suelo.', 'Mantén la posición de puente durante unos segundos.', 'Baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa glúteos y core mediante una progresión suave que mejora la movilidad de la cadera y la estabilidad lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1422'),
('16c86be4-cd72-58e1-afcb-da803c13310c', 'Estiramiento de peroneos', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.', 'Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.', 'Mantén el estiramiento durante 15-30 segundos.', 'Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Alarga los músculos laterales de la pierna y el tobillo, ayudando a prevenir molestias y mejorar la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1388'),
('e96c01e6-6b49-5e15-86c5-8d3d8ccfc3f3', 'Postura de la paloma', ARRAY['Coloca una rodilla delante y la otra pierna extendida hacia atrás, con la espinilla delantera cruzada.', 'Baja la cadera poco a poco hasta notar el estiramiento en el glúteo de la pierna delantera.', 'Apoya las manos delante y mantén la espalda larga sin curvar la zona lumbar.', 'Respira profundo y mantén entre 30 y 60 segundos por lado.', 'Evita forzar la rodilla delantera: si molesta, acerca el pie hacia la cadera.']::text[], 'intermedio', 'Estira glúteos y flexores de cadera, mejora la movilidad de la cadera y alivia la tensión lumbar.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1943'),
('b7ee1fa4-84fa-5f4c-b6b0-0ed04840eb58', 'Press pike entre bancos', ARRAY['Apoya las manos en el borde de dos bancos separados y coloca los pies detrás.', 'Eleva la cadera hasta formar una V invertida con la espalda recta.', 'Baja la cabeza entre las manos flexionando los codos con control.', 'Empuja con los hombros para volver arriba sin perder la posición de pike.', 'Evita arquear la espalda o encoger el cuello durante el descenso.']::text[], 'intermedio', 'Trabaja hombros y tríceps con el peso corporal, ganando fuerza de empuje vertical y control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3904'),
('84ec021e-11a2-51c0-98c7-5d39d51ebcc2', 'Flexión pike', ARRAY['Desde plancha alta, camina los pies hacia las manos y eleva la cadera en V invertida.', 'Mantén las piernas lo más rectas posible y la mirada entre las manos.', 'Flexiona los codos y baja la coronilla hacia el suelo con control.', 'Empuja con los hombros para volver a la posición inicial sin perder la V.', 'Evita abrir los codos en exceso o dejar caer la cadera.']::text[], 'intermedio', 'Fortalece hombros y tríceps con el peso corporal, preparando el camino hacia el press vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2921'),
('eab247d7-4cce-5d59-a76e-ecc06fec0b42', 'Postura pike', ARRAY['Desde plancha alta, camina los pies hacia las manos hasta elevar la cadera.', 'Empuja el suelo con las manos y alarga la espalda formando una V invertida.', 'Mantén la mirada entre las manos y el cuello relajado.', 'Aguanta la posición respirando de forma constante entre 20 y 40 segundos.', 'Evita bloquear los codos con los hombros encogidos hacia las orejas.']::text[], 'principiante', 'Mejora la fuerza de hombros y el equilibrio invertido, estirando isquiotibiales y espalda alta.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '9488'),
('14df03d0-d9b3-5160-9f18-d5bed389bb68', 'Pike a cobra', ARRAY['Empieza en pike con la cadera alta y las manos en el suelo.', 'Baja la cadera hacia delante y extiende el pecho en posición de cobra.', 'Mantén los hombros lejos de las orejas y el cuello largo.', 'Vuelve al pike empujando con las manos y repite el movimiento con fluidez.', 'Evita hundir la lumbar en cobra: el movimiento sale del pecho.']::text[], 'principiante', 'Moviliza hombros y columna, alternando flexión y extensión para ganar rango y control postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3960'),
('dc8ed6c8-3490-5abe-a882-05e491b36781', 'Flexión pike a cobra', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.', 'Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.', 'Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho.', 'Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo.', 'Empuja con las manos para volver a la posición de V invertida.', 'Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina empuje de hombros y extensión de columna, trabajando glúteos, core y tríceps de forma dinámica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3662'),
('9f7f1dfe-01cc-5555-a9d1-dbc5a672945f', 'Círculo de brazos en máquina de pilates', ARRAY['Siéntate o túmbate en la máquina con la espalda apoyada y los brazos extendidos.', 'Dibuja círculos pequeños y controlados con los brazos sin mover el tronco.', 'Mantén el core activo y los hombros alejados de las orejas.', 'Respira de forma constante y cambia el sentido del círculo.', 'Evita arquear la lumbar o encoger el cuello durante el movimiento.']::text[], 'principiante', 'Activa hombros y espalda alta con control, mejorando la estabilidad escapular y la postura.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10854'),
('83be75f3-0590-5d40-8665-e1e03dae8505', 'Expansión de pecho en máquina de pilates', ARRAY['Siéntate en la máquina con la espalda recta y los brazos a la altura del pecho.', 'Abre los brazos hacia atrás juntando las escápulas sin forzar.', 'Mantén el core activo y la cabeza alineada con la columna.', 'Vuelve despacio a la posición inicial controlando el retorno.', 'Evita sacar las costillas o arquear la lumbar al abrir.']::text[], 'principiante', 'Abre el pecho y fortalece la espalda alta, corrigiendo la postura encorvada y mejorando la respiración.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10855'),
('979046b4-8d96-53ad-8d57-7475ca8ef107', 'The hundred en máquina de pilates', ARRAY['Túmbate en la máquina con las piernas en mesa y los brazos extendidos.', 'Eleva la cabeza y los hombros y bombea los brazos arriba y abajo.', 'Inhala en cinco bombeos y exhala en cinco, manteniendo el ritmo.', 'Mantén la lumbar apoyada y el core activo todo el tiempo.', 'Evita tirar del cuello: el movimiento nace del pecho.']::text[], 'principiante', 'Activa el core profundo y la respiración coordinada, mejorando la resistencia abdominal y la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10658'),
('d24121e5-26f2-535c-bcff-7f3543113192', 'Long spine en máquina de pilates', ARRAY['Siéntate en la máquina con la espalda recta y las piernas extendidas.', 'Enrolla la columna hacia abajo vértebra a vértebra con control.', 'Desenrolla despacio hacia arriba apilando la columna.', 'Coordina la respiración: exhala al bajar y inhala al subir.', 'Evita redondear de golpe o tirar de la lumbar sin control.']::text[], 'principiante', 'Moviliza la columna vértebra a vértebra, estirando isquiotibiales y fortaleciendo el core y los glúteos.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10853'),
('73f82a0c-2f2b-534a-84a1-cb8a7d08548c', 'Elevación de gemelos acostado en máquina de pilates', ARRAY['Túmbate en la máquina con los pies apoyados en la plataforma.', 'Empuja con la punta de los pies extendiendo los tobillos.', 'Sube despacio y baja controlando el movimiento.', 'Mantén las rodillas alineadas y el core activo.', 'Evita rebotar o bloquear las rodillas al empujar.']::text[], 'principiante', 'Fortalece gemelos y sóleo, mejorando la estabilidad del tobillo y la fuerza de empuje del pie.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10657'),
('810825e2-8292-56ff-a8f1-709bdc9dffc2', 'Rana y círculo de pierna acostado en máquina de pilates', ARRAY['Túmbate en la máquina con las piernas flexionadas y los pies juntos.', 'Abre las rodillas hacia fuera en posición de rana y ciérralas con control.', 'Dibuja círculos pequeños con las piernas manteniendo el core activo.', 'Mantén la lumbar apoyada y respira de forma constante.', 'Evita arquear la espalda o hacer movimientos bruscos.']::text[], 'principiante', 'Trabaja aductores y glúteos con movimientos controlados, mejorando la movilidad de la cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10847'),
('435e4fee-45f0-5f6d-9ca8-78787f1e3e70', 'Extensión de rodilla acostado en máquina de pilates', ARRAY['Túmbate en la máquina con las rodillas flexionadas y los pies apoyados.', 'Extiende las rodillas despacio hasta estirar las piernas.', 'Mantén el core activo y la lumbar apoyada.', 'Baja controlando el movimiento sin dejar caer el peso.', 'Evita bloquear las rodillas de golpe al extender.']::text[], 'principiante', 'Fortalece cuádriceps con control, mejorando la estabilidad de la rodilla y la fuerza del tren inferior.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10655'),
('c4d3a379-e062-50f7-a8e2-f5a21cf002b6', 'Extensión de rodilla acostado en máquina de pilates sobre talones', ARRAY['Túmbate en la máquina con los talones apoyados y las rodillas flexionadas.', 'Extiende las rodillas despacio empujando con los talones.', 'Mantén el core activo y la espalda apoyada en la máquina.', 'Baja controlando el retorno sin perder la alineación.', 'Evita bloquear las rodillas o levantar la cadera al empujar.']::text[], 'principiante', 'Fortalece cuádriceps e isquiotibiales con control, mejorando la estabilidad de la rodilla y el core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10656'),
('363235b7-6cb5-551e-9a37-88c1340ea564', 'Extensión de rodilla en máquina de pilates sobre puntas', ARRAY['Colócate tumbado en la máquina con las rodillas alineadas con el eje de giro.', 'Apoya las puntas de los pies en la plataforma y mantén los talones elevados.', 'Extiende las rodillas de forma lenta y controlada hasta estirar casi por completo.', 'Baja sin dejar caer el peso y evita bloquear las rodillas con un golpe seco.']::text[], 'principiante', 'Fortalece cuádriceps y activa gemelos y core, mejorando el control y la estabilidad de la rodilla.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10654'),
('f3fb9fac-6386-5151-a3d4-fcc4c2606713', 'Elevación pélvica en máquina de pilates', ARRAY['Túmbate en la máquina con la espalda apoyada y los pies bien colocados.', 'Empuja con los talones y eleva la pelvis contrayendo los glúteos.', 'Mantén arriba un instante sin arquear la zona lumbar.', 'Baja despacio y evita impulsarte con la espalda baja.']::text[], 'principiante', 'Activa glúteos e isquios y refuerza la zona lumbar, mejorando la estabilidad de la cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10849'),
('b67bcec4-7b29-5ed6-bec2-7d77d80f2c9a', 'Carrera en máquina de pilates', ARRAY['Túmbate en la máquina con los pies apoyados y el cuerpo alineado.', 'Alterna el empuje de una pierna y otra como si corrieras sin moverte.', 'Mantén el ritmo constante y el abdomen firme durante todo el movimiento.', 'Evita levantar la cadera o perder la alineación del tronco.']::text[], 'principiante', 'Trabaja gemelos y piernas con un patrón de carrera controlado que también activa el core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10848'),
('d6287958-6d74-5f1e-a38d-ac7f882ca81b', 'Overhead en máquina de pilates', ARRAY['Colócate en la máquina con la espalda apoyada y los brazos preparados.', 'Lleva los brazos por encima de la cabeza de forma controlada.', 'Mantén el abdomen activo y la zona lumbar pegada al apoyo.', 'Vuelve despacio y evita arquear la espalda al subir los brazos.']::text[], 'principiante', 'Fortalece el abdomen y los hombros con un movimiento de brazos por encima de la cabeza.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10856'),
('2084358b-10b2-55bd-91e1-28c9ee7a9509', 'Apertura rusa en máquina de pilates', ARRAY['Colócate en la máquina con los pies bien apoyados y las caderas alineadas.', 'Abre y cierra las piernas de forma lenta y controlada.', 'Mantén el abdomen firme para no balancear el tronco.', 'Evita abrir demasiado rápido y perder el control en el cierre.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos con un patrón de apertura que exige control y estabilidad.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10852'),
('34848b48-4f7f-56ba-a043-bef1a123ec07', 'Sentadilla rusa en máquina de pilates', ARRAY['Colócate en la máquina con los pies apoyados y la espalda alineada.', 'Empuja y flexiona las piernas como en una sentadilla controlada.', 'Mantén las rodillas alineadas con los pies durante todo el recorrido.', 'Evita bloquear las rodillas o cargar la espalda al empujar.']::text[], 'principiante', 'Refuerza cuádriceps y glúteos con una sentadilla guiada que mejora la fuerza y el control.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10851'),
('76c6f755-23f9-5877-8ad3-01fd0b928bd5', 'Apertura lateral en máquina de pilates', ARRAY['Colócate en la máquina con las piernas apoyadas y el tronco estable.', 'Abre las piernas hacia los lados de forma lenta y progresiva.', 'Mantén el abdomen activo y evita rebotar al abrir.', 'Cierra despacio controlando el retorno sin dejar caer el peso.']::text[], 'principiante', 'Estira y fortalece aductores e ingles, mejorando la movilidad y el control de la cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones', 'peso']::text[], false, true, 3.0, 'pilates', '10850'),
('26f2b18d-fd8f-5ed6-a855-098c0045ca46', 'Sentadilla pistol al cajón', ARRAY['Colócate de pie frente al cajón sobre una pierna y extiende la otra al frente.', 'Baja despacio llevando la cadera hacia atrás hasta rozar el cajón.', 'Mantén la rodilla alineada con el pie y el tronco firme.', 'Empuja con el talón para subir y evita dejarte caer sobre el cajón.']::text[], 'avanzado', 'Desarrolla fuerza y equilibrio en una pierna, trabajando cuádriceps, glúteos y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2984'),
('2e58de77-f504-5595-90bc-823661a051d3', 'Trote en el sitio', ARRAY['Colócate de pie con la espalda recta y los brazos relajados.', 'Trota en el sitio levantando ligeramente las rodillas.', 'Mantén un ritmo constante y respira de forma regular.', 'Evita golpear fuerte el suelo y mantener los hombros tensos.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y cadera, ideal como calentamiento o cardio suave.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '4004'),
('17acf845-2a77-58ac-91b3-10dd0260b014', 'Fondos planche en barras paralelas', ARRAY['Sujeta las barras paralelas con los brazos extendidos y el cuerpo inclinado.', 'Baja el pecho de forma controlada manteniendo la inclinación.', 'Empuja con los tríceps para volver arriba sin perder la postura.', 'Evita hundir los hombros o perder la tensión del abdomen.']::text[], 'avanzado', 'Fortalece tríceps y hombros con un fondo avanzado que exige gran control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7415'),
('3b2d47c2-6435-5bf0-a887-43f7bd4d638b', 'Press de planche', ARRAY['Coloca las manos en el suelo con los brazos preparados y el cuerpo inclinado.', 'Empuja el cuerpo hacia arriba manteniendo la tensión en hombros y abdomen.', 'Controla el descenso sin perder la alineación del tronco.', 'Evita arquear la espalda o cargar las muñecas en exceso.']::text[], 'avanzado', 'Trabaja hombros y core con un empuje avanzado que exige fuerza y control corporal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10664'),
('b929166a-5779-52e5-943b-8c04b109013f', 'Plancha golpeando el balón alternado', ARRAY['Colócate en plancha con las manos apoyadas y el balón cerca.', 'Golpea el balón alternando una mano y otra sin mover la cadera.', 'Mantén el abdomen firme y la respiración constante.', 'Evita girar el tronco o perder la línea del cuerpo.']::text[], 'intermedio', 'Refuerza el abdomen y los oblicuos con un movimiento alterno que también activa hombros.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10554'),
('d0001748-89d0-511a-83e5-4023e7d82b1d', 'Plancha con elevación de brazos', ARRAY['Colócate en plancha con los codos o manos apoyados y el cuerpo alineado.', 'Eleva un brazo despacio sin mover la cadera.', 'Mantén el abdomen activo y baja el brazo con control.', 'Evita balancear el tronco o hundir la zona lumbar.']::text[], 'intermedio', 'Fortalece el abdomen y la espalda alta mejorando la estabilidad y el control postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1440'),
('8d474662-cf21-5a36-a116-4e8ddd7e727b', 'Plancha con control de glúteos', ARRAY['Colócate en plancha con el cuerpo alineado de cabeza a talones.', 'Aprieta los glúteos y el abdomen para mantener la posición.', 'Respira de forma constante sin perder la tensión.', 'Evita elevar la cadera o hundir la zona lumbar.']::text[], 'intermedio', 'Trabaja el abdomen y el core con atención a la técnica, activando también glúteos y hombros.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2358'),
('9f48d2f1-43ef-565f-9e9a-f4d69f2e2082', 'Plancha con saltos', ARRAY['Colócate en plancha con las manos apoyadas y el cuerpo alineado.', 'Abre y cierra las piernas con pequeños saltos controlados.', 'Mantén el abdomen firme y la cadera estable.', 'Evita rebotar demasiado o perder la línea del tronco.']::text[], 'intermedio', 'Combina trabajo de abdomen y cardio con saltos que activan glúteos y flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3930'),
('72a08932-8a9c-53a3-abd4-d187828be98d', 'Salto de tijera en plancha sobre codos', ARRAY['Apoya antebrazos y puntas de los pies con el cuerpo alineado y el abdomen firme.', 'Abre y cierra las piernas con un salto corto manteniendo la cadera baja y estable.', 'Respira de forma rítmica y evita que la zona lumbar se hunda o suba.']::text[], 'intermedio', 'Activa el abdomen y los glúteos con impacto cardiovascular, mejorando la estabilidad del core y la resistencia.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5157'),
('c3611e67-60d6-5d1a-9089-7025877d228e', 'Salto de plancha', ARRAY['Colócate en plancha alta con manos bajo los hombros y cuerpo recto.', 'Salta separando y juntando los pies sin perder la alineación de la cadera.', 'Mantén el abdomen apretado y evita rebotar con la espalda arqueada.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca mientras fortalece core, hombros y cuádriceps con un gesto explosivo y controlado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '2792'),
('718cccea-2a34-5dab-9ac5-8112f81d926b', 'Salto de plancha a sentadilla', ARRAY['Empieza en plancha alta con los pies juntos y el core activo.', 'Salta llevando los pies hacia las manos y sube a sentadilla con el pecho alto.', 'Vuelve a la plancha con un salto controlado y evita que las caderas se hundan.']::text[], 'intermedio', 'Combina potencia de piernas y control del core en un movimiento global que eleva las pulsaciones.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10326'),
('b1db7223-d88f-5060-a98a-f616f458e80e', 'Plancha con toque de rodilla', ARRAY['Adopta una plancha alta con manos bajo los hombros y cuerpo alineado.', 'Lleva una rodilla hacia el codo del mismo lado sin girar la cadera.', 'Vuelve al centro y alterna lados manteniendo el abdomen firme y la respiración constante.']::text[], 'intermedio', 'Trabaja la estabilidad del abdomen y los oblicuos mientras exige control de hombros y cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9999'),
('4a4b43c9-67f5-53df-8584-39c731be7614', 'Elevación lateral en plancha', ARRAY['Colócate en plancha alta con los pies algo más abiertos para ganar estabilidad.', 'Levanta un brazo hacia el lateral sin rotar el tronco ni hundir la cadera.', 'Baja con control y alterna lados evitando arquear la zona lumbar.']::text[], 'intermedio', 'Refuerza el core y los oblicuos con una demanda extra de hombros y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3852'),
('a0863bc7-faa3-5719-b201-17700afdc017', 'Escalador con elevación de pierna en plancha', ARRAY['Empieza en plancha alta con el core activo y la mirada al suelo.', 'Lleva una rodilla al pecho y luego extiende la pierna hacia atrás sin tocar el suelo.', 'Alterna piernas a ritmo constante y evita que la cadera suba demasiado.']::text[], 'intermedio', 'Aumenta la intensidad cardiovascular y fortalece abdomen, oblicuos y flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9821'),
('a9cbabd9-c48a-5201-aa50-a6b1c311a853', 'Pica deslizante en plancha con toalla', ARRAY['Coloca los pies sobre una toalla en plancha alta con manos firmes.', 'Eleva la cadera hacia arriba deslizando los pies hacia las manos y vuelve despacio.', 'Mantén el abdomen apretado y evita perder la alineación de la espalda.']::text[], 'intermedio', 'Fortalece el abdomen y los hombros con un gesto deslizante que exige control y coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5165');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('89b1ea07-d529-5093-b9a6-6c36a0e04145', 'Remo con flexión desde plancha', ARRAY['Sujeta una mancuerna en cada mano en plancha alta con pies abiertos.', 'Haz una flexión controlada manteniendo el cuerpo alineado.', 'Remo una mancuerna hacia la cadera sin girar el tronco y alterna lados.']::text[], 'intermedio', 'Ejercicio global de espalda, pecho y core que mejora la fuerza y la estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2961'),
('62f1a560-88e9-5d95-8862-62534aaa5ca3', 'Salto lateral en plancha', ARRAY['Colócate en plancha alta con el abdomen firme y los pies juntos.', 'Salta llevando ambos pies hacia un lado y luego hacia el otro.', 'Mantén la cadera baja y evita que la espalda se arquee durante los saltos.']::text[], 'intermedio', 'Mejora la potencia lateral y la resistencia del core con un gesto explosivo que eleva el pulso.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9677'),
('e1e258fb-6e02-51c7-9990-f61e6d67d8fa', 'Plancha con subida y bajada', ARRAY['Empieza en plancha sobre antebrazos con codos bajo los hombros.', 'Sube a plancha alta apoyando una mano y luego la otra sin mover la cadera.', 'Baja de nuevo al antebrazo con control y alterna el orden de las manos.']::text[], 'intermedio', 'Fortalece abdomen, hombros y tríceps mientras mejora la estabilidad y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2793'),
('c7703de9-78af-5ad5-a948-e5a67922f908', 'Estiramiento de flexión plantar', ARRAY['Siéntate con una pierna extendida y la otra flexionada.', 'Lleva la punta del pie hacia abajo con ayuda de la mano hasta notar el estiramiento.', 'Mantén la posición sin dolor y respira de forma relajada.']::text[], 'principiante', 'Relaja gemelos y sóleo, mejora la movilidad del tobillo y alivia la tensión tras el ejercicio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1920'),
('50790ffa-64c7-5580-afe5-6b0e307487ae', 'Estiramiento de flexores plantares y eversores del pie', ARRAY['Siéntate con la pierna extendida y el pie relajado.', 'Lleva la punta del pie hacia abajo y hacia fuera con ayuda de la mano.', 'Sostén el estiramiento sin forzar y respira con calma.']::text[], 'principiante', 'Libera tensión en gemelos y cara externa del tobillo, mejorando la movilidad del pie.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1926'),
('fa0f4acb-a633-52d1-936c-47bdd1a71c29', 'Estiramiento de flexores plantares e inversores del pie', ARRAY['Siéntate con la pierna extendida y el pie sin tensión.', 'Lleva la punta del pie hacia abajo y hacia dentro con ayuda de la mano.', 'Mantén el estiramiento suave y evita rebotes bruscos.']::text[], 'principiante', 'Estira gemelos y cara interna del tobillo, favoreciendo la movilidad y previniendo molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1927'),
('023cddef-3739-5497-b9c9-2a55a9e61f19', 'Hiperextensión con disco', ARRAY['Sujeta un disco contra el pecho y colócate con la cadera apoyada.', 'Baja el tronco con control manteniendo la espalda neutra.', 'Sube hasta alinear el cuerpo sin hiperextender y evita usar impulso.']::text[], 'intermedio', 'Fortalece la musculatura lumbar, glúteos e isquios, mejorando la extensión y estabilidad de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1234'),
('2a79a214-bd66-5277-af1e-769ebe20468e', 'Empuje de disco', ARRAY['Sujeta un disco a la altura del pecho con los codos flexionados.', 'Empuja el disco hacia delante de forma explosiva y controlada.', 'Recoge el disco sin perder la postura y evita bloquear la espalda.']::text[], 'intermedio', 'Desarrolla potencia de pecho, hombros y tríceps con un gesto explosivo que también activa el core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '7882'),
('771b6060-2bdd-533b-8cc6-71bf12df1133', 'Postura del arado', ARRAY['Túmbate boca arriba con los brazos pegados al cuerpo y las piernas estiradas.', 'Sube las piernas juntas hacia el techo y llévalas por detrás de la cabeza hasta apoyar los pies en el suelo.', 'Mantén las piernas rectas y respira despacio durante veinte o treinta segundos.', 'Evita girar la cabeza para no forzar el cuello y sal despacio desenrollando la columna.']::text[], 'intermedio', 'Estira la espalda, los isquiotibiales y los hombros, y mejora la movilidad de la columna en flexión profunda.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1485'),
('085c2bd8-785d-58a0-9f13-f9f81cc23360', 'Jacks pliométricos', ARRAY['Empieza de pie con los pies juntos y los brazos a los lados.', 'Salta abriendo piernas y brazos a la vez y cae con las rodillas ligeramente flexionadas.', 'Vuelve a saltar cerrando piernas y brazos en un solo movimiento.', 'Aterriza con la punta de los pies y evita caer con las rodillas rígidas.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y hombros con un salto explosivo de cuerpo completo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3108'),
('850b1352-5076-5c3c-bdba-f8f15b7c153f', 'Estiramiento de zancada lateral pliométrica', ARRAY['Colócate de pie con los pies bien separados y el peso repartido.', 'Desplaza el peso hacia un lado flexionando esa rodilla mientras la otra pierna queda estirada.', 'Mantén la espalda recta y siente el estiramiento en la cara interna del muslo.', 'Vuelve al centro con un pequeño impulso y repite hacia el otro lado sin rebotar.']::text[], 'intermedio', 'Estira aductores y glúteos con un desplazamiento lateral dinámico que mejora la movilidad de la cadera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4675'),
('c6627d79-a73e-5686-af3a-b32ae15bbe10', 'Sentadilla pliométrica en la pared', ARRAY['Colócate de espaldas a la pared a un paso de distancia con los pies al ancho de cadera.', 'Baja en sentadilla y salta hacia arriba buscando tocar la pared con las manos.', 'Aterriza con las rodillas flexionadas y absorbe el impacto.', 'Evita caer con las piernas estiradas y mantén el pecho alto en todo momento.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un salto vertical controlado usando la pared como referencia.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0647'),
('17e8d74e-a521-51e1-83cd-ea4ba2e594a7', 'Sentadilla pliométrica', ARRAY['Ponte de pie con los pies al ancho de los hombros y los brazos relajados.', 'Baja en sentadilla llevando la cadera atrás y los brazos hacia delante.', 'Salta lo más alto posible extendiendo piernas y brazos.', 'Aterriza suave con las rodillas flexionadas y evita juntar las rodillas hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia en piernas y glúteos con un salto explosivo que mejora la fuerza reactiva.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5745'),
('77e653ad-3639-5a6f-baa1-8d87488c564a', 'Ejercicio pliométrico de agilidad', ARRAY['Coloca dos marcas en el suelo separadas un metro aproximadamente.', 'Salta de una marca a otra con los pies juntos y aterriza suave.', 'Aumenta la velocidad progresivamente manteniendo el control del tronco.', 'Evita mirar al suelo todo el rato y respira de forma constante.']::text[], 'intermedio', 'Mejora la coordinación, la reactividad y la capacidad cardiovascular con desplazamientos rápidos y saltos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5974'),
('e8322da2-655a-526d-97d8-6601215d2cb3', 'Salto pogo a dos pies', ARRAY['Ponte de pie con los pies juntos y las manos en la cintura.', 'Salta hacia arriba usando solo los tobillos, con las rodillas casi estiradas.', 'Aterriza con la punta de los pies y rebota de inmediato.', 'Evita flexionar demasiado las rodillas y mantén el tronco erguido.']::text[], 'intermedio', 'Refuerza gemelos y tobillos con saltos verticales cortos que mejoran la rigidez elástica del pie.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9070'),
('a1a2bd50-5dca-5317-8e0c-28c3da84ade8', 'Prueba de flexibilidad de la cadena posterior', ARRAY['Siéntate en el suelo con las piernas estiradas y los pies juntos.', 'Lleva los brazos hacia delante intentando alcanzar la punta de los pies.', 'Mantén las rodillas estiradas y la espalda lo más recta posible.', 'Anota hasta dónde llegas sin forzar ni rebotar para comparar tu progreso.']::text[], 'principiante', 'Valora la elasticidad de isquiotibiales, glúteos y zona lumbar para detectar acortamientos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6793'),
('19102068-a9b9-5e7a-a866-8d5c08dc1aaa', 'Paso hacia atrás con alcance sobre la cabeza', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo.', 'Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.', 'Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada.', 'Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza.', 'Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante.', 'Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa el core y la cadera mientras moviliza hombros y columna en un patrón completo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1687'),
('d120bd25-b140-5cb7-8ca1-2b937ecb52e1', 'Estiramiento del tibial posterior', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.', 'Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta la tensión de la cuerda y relaja el pie.', 'Repite el estiramiento en la otra pierna.']::text[], 'principiante', 'Alivia la tensión en la parte interna del tobillo y la pantorrilla tras correr o caminar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1389'),
('f5f146ae-b791-5246-9d4e-d0895dc688e8', 'Sentadilla profunda con apoyo', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Mejora la movilidad de cadera y tobillo y fortalece glúteos y cuádriceps en rango completo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3132'),
('960f9ebc-c963-54f0-9eb0-7a2f3f9cc7b7', 'Cargada de potencia', ARRAY['Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros.', 'Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros.', 'Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas.', 'Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados.', 'Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal.', 'Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas.', 'Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Ejercicio explosivo de halterofilia que desarrolla potencia en isquiotibiales, glúteos y cuádriceps.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0648'),
('4bd19664-c5fc-5743-bc4a-9f6396bb34be', 'Thruster de cargada de potencia', ARRAY['Sujeta la barra con las manos al ancho de los hombros y los pies al ancho de cadera.', 'Baja la barra hasta los muslos y explota extendiendo caderas y rodillas para cargarla a los hombros.', 'Desde los hombros, baja en sentadilla y empuja la barra sobre la cabeza al subir.', 'Aterriza con las rodillas flexionadas y evita arquear la espalda al recibir la barra.']::text[], 'avanzado', 'Combina cargada y press para trabajar piernas, hombros y core en un gesto potente y global.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5188'),
('6f012a7c-266f-58e5-b703-2f8c2fe42c9b', 'Plancha power point', ARRAY['Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.', 'Activa el core y aprieta los glúteos para mantener una posición estable.', 'Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies.', 'Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados.', 'Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el core de forma isométrica mientras activa hombros, tríceps y glúteos para estabilizar.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3665'),
('6688c37c-fd4d-594a-9e38-b1a91499aea0', 'Empujes de poder', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Empuja el suelo con las manos separando los omóplatos y redondeando ligeramente la espalda alta.', 'Mantén la posición dos o tres segundos apretando el core y los glúteos.', 'Vuelve al inicio sin hundir la cadera y evita bloquear los codos.']::text[], 'intermedio', 'Fortalece la espalda alta y los omóplatos con un empuje isométrico que mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3555'),
('fcdf0f06-5bda-50e8-93cc-895c55b9ad94', 'Caminata antirrotación hacia delante con trineo', ARRAY['Colócate de espaldas al trineo con el arnés o las asas a la altura de la cadera.', 'Camina hacia delante con pasos cortos manteniendo el tronco recto y las caderas alineadas.', 'Evita que el trineo te gire el torso: activa el core y respira de forma constante.', 'Da pasos firmes sin inclinarte hacia atrás ni encoger los hombros.']::text[], 'intermedio', 'Trabaja glúteos y core resistiendo la rotación del trineo, mejorando la estabilidad y la fuerza de empuje en carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2908'),
('9be1c44a-c120-5cd9-b415-ff413713c2d4', 'Empuje hacia atrás con trineo', ARRAY['Sujeta las asas del trineo de frente a él, con los codos ligeramente flexionados.', 'Da pasos hacia atrás manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Empuja con el talón y extiende la cadera en cada paso sin bloquear las rodillas.', 'Evita arquear la espalda o dar pasos demasiado largos que te desequilibren.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos al empujar el trineo hacia atrás, mejorando la potencia de piernas y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2907'),
('806abad7-2860-5605-9ede-0243f5bfd3bf', 'Curl de bíceps con trineo', ARRAY['Colócate de espaldas al trineo con las asas agarradas y los brazos extendidos.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los hombros.', 'Mantén los codos pegados al torso y baja de forma controlada.', 'Evita balancear el tronco o usar impulso para tirar del trineo.']::text[], 'intermedio', 'Aísla los bíceps y antebrazos al flexionar los codos contra la resistencia del trineo, ganando fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2901'),
('468f44b7-233d-592b-a034-9ef595aedeab', 'Arrastre de trineo de potencia', ARRAY['Engancha el arnés o las asas a la cintura y colócate de espaldas al trineo.', 'Camina hacia delante con pasos cortos manteniendo el tronco erguido.', 'Activa glúteos e isquiotibiales en cada paso y respira de forma rítmica.', 'Evita inclinarte hacia atrás o tirar con los brazos en lugar de con las piernas.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos al arrastrar el trineo, desarrollando fuerza de cadena posterior y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5143'),
('b836f378-043b-5257-b58e-f0850a1840f2', 'Tirón alto con trineo', ARRAY['Colócate de espaldas al trineo con las asas a la altura de la cintura.', 'Tira de las asas hacia arriba y hacia el pecho llevando los codos altos.', 'Mantén el core activo y evita encoger los hombros hacia las orejas.', 'Baja de forma controlada y repite sin balancear el tronco.']::text[], 'intermedio', 'Desarrolla hombros y espalda alta al tirar del trineo hacia arriba, mejorando la potencia de tracción y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2909'),
('d60a3f83-a6fe-5695-ab7a-bd7e9e0849c6', 'Remo con tirón de trineo de potencia', ARRAY['Colócate de frente al trineo con las asas agarradas y los brazos extendidos.', 'Tira de las asas hacia el torso llevando los codos hacia atrás y juntando las escápulas.', 'Mantén la espalda recta y el core activo durante todo el recorrido.', 'Evita encorvar la espalda o tirar solo con los brazos sin usar la espalda.']::text[], 'intermedio', 'Fortalece dorsales y espalda alta al remar contra la resistencia del trineo, mejorando la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2563'),
('ad09e30e-8bae-5036-ad68-04c0e9eae03c', 'Empuje de trineo de potencia', ARRAY['Coloca las manos en las asas del trineo con los brazos extendidos y el cuerpo inclinado.', 'Empuja con las piernas dando pasos cortos y firmes manteniendo el tronco alineado.', 'Mantén el core activo y respira de forma constante durante el empuje.', 'Evita levantar los talones o perder la alineación de la espalda.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y core al empujar el trineo, desarrollando potencia de piernas y acondicionamiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4428'),
('b490da6d-e9b0-5543-97a3-05c710610948', 'Batwing trasero con trineo', ARRAY['Engancha el arnés o las asas y colócate de espaldas al trineo.', 'Camina hacia atrás con pasos cortos manteniendo el pecho alto y los hombros atrás.', 'Activa glúteos e isquiotibiales y evita encorvar la espalda.', 'Respira de forma rítmica y mantén el core firme durante todo el recorrido.']::text[], 'intermedio', 'Trabaja isquiotibiales y glúteos con un arrastre que también activa la espalda alta y los deltoides posteriores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2904'),
('7ea43392-5926-5dfa-b11a-1af79225da53', 'Arrastre hacia atrás con trineo', ARRAY['Engancha el arnés o las asas y colócate de frente al trineo.', 'Camina hacia atrás con pasos cortos manteniendo el tronco erguido.', 'Empuja con los talones y activa glúteos y cuádriceps en cada paso.', 'Evita inclinarte hacia delante o dar pasos demasiado largos.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos al arrastrar el trineo hacia atrás, mejorando la fuerza de piernas y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2906'),
('592da22a-b1b1-59a5-ae39-ef3474e29882', 'Apertura posterior con trineo', ARRAY['Colócate de frente al trineo con las asas agarradas y los brazos extendidos.', 'Abre los brazos hacia atrás juntando las escápulas sin flexionar los codos.', 'Mantén el core activo y evita encoger los hombros hacia las orejas.', 'Vuelve de forma controlada y repite sin balancear el tronco.']::text[], 'intermedio', 'Trabaja deltoides posteriores y espalda alta al abrir los brazos contra la resistencia, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2905'),
('67dce26f-146b-5ecd-b60e-389470d7e709', 'Zancada trasera con trineo', ARRAY['Engancha el arnés o las asas y colócate de frente al trineo.', 'Da un paso atrás flexionando la rodilla y baja la cadera de forma controlada.', 'Empuja con el talón del pie delantero para volver a la posición inicial.', 'Evita que la rodilla delantera pase la punta del pie y mantén el tronco erguido.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con zancadas hacia atrás contra la resistencia, mejorando el equilibrio y la potencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2830'),
('23bb1fd6-3ba8-572d-a600-38ad944f18e7', 'Remo con zancada trasera y trineo', ARRAY['Colócate de frente al trineo con las asas agarradas y los brazos extendidos.', 'Da un paso atrás y, al mismo tiempo, tira de las asas hacia el torso.', 'Mantén la espalda recta y el core activo durante todo el movimiento.', 'Evita encorvar la espalda o tirar solo con los brazos sin usar las piernas.']::text[], 'intermedio', 'Combina zancada y remo para trabajar espalda, piernas y core, mejorando la coordinación y la fuerza global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2902'),
('6861e88d-702d-5363-b053-cadc3185c5d7', 'Extensión de tríceps en trineo de potencia', ARRAY['Colócate de espaldas al trineo con las asas agarradas y los codos flexionados.', 'Extiende los codos llevando las manos hacia delante sin mover los hombros.', 'Mantén los codos pegados al torso y vuelve de forma controlada.', 'Evita balancear el tronco o usar impulso para empujar el trineo.']::text[], 'intermedio', 'Aísla los tríceps al extender los codos contra la resistencia del trineo, mejorando la fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4119'),
('30c810cd-fbbd-5281-9488-ac4fd4daecab', 'Trote elevado', ARRAY['Colócate de pie con la espalda recta y los brazos relajados.', 'Trota en el sitio elevando las rodillas a la altura de la cadera.', 'Mantén el core activo y respira de forma constante.', 'Evita inclinarte hacia atrás o golpear el suelo con fuerza.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y core con un trote en el sitio que mejora la coordinación y la resistencia.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3197'),
('1630e5d8-fc2b-58e1-8741-5406610d59a9', 'Empuje de oración', ARRAY['Colócate de pie con las manos juntas frente al pecho y los codos flexionados.', 'Presiona las palmas entre sí y empuja ligeramente hacia delante.', 'Mantén la tensión isométrica y respira de forma constante.', 'Evita encoger los hombros o perder la alineación de la espalda.']::text[], 'intermedio', 'Trabaja hombros y tríceps con una presión isométrica que mejora la estabilidad y la fuerza de empuje.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4876'),
('3bbcc7f1-27b1-5201-9a56-39066a414cd1', 'Postura de la sentadilla de oración', ARRAY['Colócate de pie con los pies más anchos que las caderas y las puntas ligeramente hacia fuera.', 'Junta las palmas de las manos a la altura del pecho y baja las caderas flexionando las rodillas.', 'Mantén la espalda recta y los talones apoyados mientras respiras despacio.', 'Empuja suavemente las rodillas hacia fuera con los codos sin forzar.', 'Evita curvar la espalda o levantar los talones al bajar.']::text[], 'intermedio', 'Abre las caderas y estira aductores e ingles, mejorando la movilidad para sentadillas y posturas de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4387'),
('6aa992dc-c6f1-5439-bc46-20561951248a', 'Press under', ARRAY['Sujeta la barra a la altura de los hombros con las manos algo más anchas que los hombros.', 'Flexiona ligeramente las rodillas y baja el cuerpo para meterte bajo la barra.', 'Empuja la barra hacia arriba mientras extiendes las piernas y bloqueas los codos.', 'Mantén el core apretado y la mirada al frente durante todo el movimiento.', 'Evita arquear la espalda o empujar la barra por delante de la cabeza.']::text[], 'avanzado', 'Fortalece hombros y tríceps al empujar la barra desde debajo de la barbilla, mejorando la técnica de halterofilia.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '4966'),
('f62abdfa-f2c0-531c-b525-a47e27be93ab', 'Estiramiento pretzel', ARRAY['Siéntate en el suelo con las piernas extendidas y cruza una pierna sobre la otra.', 'Gira el torso hacia el lado de la pierna cruzada y apoya la mano contraria en la rodilla.', 'Mantén la posición mientras respiras profundamente y relajas los hombros.', 'Cambia de lado tras varias respiraciones sin forzar la rotación.', 'Evita tirar del cuello o forzar la columna más allá de lo cómodo.']::text[], 'principiante', 'Libera tensión en oblicuos, glúteos y zona lumbar, mejorando la rotación de la columna y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0649'),
('c93a8984-9fae-57cf-8214-a5aed3cf83c3', 'Levantada del prisionero', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Coloca las manos detrás de la cabeza sin tirar del cuello.', 'Empuja con los talones y activa los glúteos para incorporarte.', 'Mantén el core apretado y la espalda recta al subir.', 'Evita usar impulso de brazos o curvar la zona lumbar.']::text[], 'intermedio', 'Activa glúteos y cuádriceps al levantarte desde el suelo, mejorando la fuerza funcional y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4388'),
('c77edf04-966d-537a-bfb2-6a58a0ec3127', 'Medio abdominal con manos en la nuca', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la parte alta del abdomen y los flexores de cadera, mejorando la fuerza del core y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3203'),
('ec5f90ba-8e62-5c67-91e2-828bb88e9de5', 'Sentadilla con salto y manos en la nuca', ARRAY['Colócate de pie con los pies a la anchura de los hombros y las manos en la nuca.', 'Flexiona las rodillas y baja las caderas como en una sentadilla normal.', 'Salta hacia arriba extendiendo las piernas y aterriza suavemente con las rodillas flexionadas.', 'Mantén el core apretado y la espalda recta durante todo el movimiento.', 'Evita aterrizar con las piernas rígidas o dejar caer las rodillas hacia dentro.']::text[], 'intermedio', 'Mejora la potencia de piernas y la explosividad con un salto que activa cuádriceps, glúteos y gemelos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4118'),
('983d8ed5-fb5e-5b31-a579-d9dfa40b10a3', 'Sentadilla del prisionero', ARRAY['Colócate de pie con los pies a la anchura de los hombros y las manos detrás de la cabeza.', 'Baja las caderas flexionando las rodillas como si te sentaras en una silla.', 'Mantén el pecho arriba y la espalda recta mientras bajas.', 'Empuja con los talones para volver a la posición inicial.', 'Evita juntar las rodillas o inclinar el torso hacia delante.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con las manos en la nuca, mejorando la postura y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1580'),
('3bfafc66-8958-59ee-acfe-fe8f90a42d4c', 'Cobra boca abajo con manos entrelazadas', ARRAY['Túmbate boca abajo con las manos entrelazadas detrás de la espalda.', 'Activa los glúteos y eleva ligeramente el pecho y los brazos del suelo.', 'Mantén la posición mientras respiras de forma controlada.', 'Baja despacio sin dejar caer el cuerpo de golpe.', 'Evita levantar demasiado la cabeza o forzar la zona lumbar.']::text[], 'intermedio', 'Refuerza la musculatura de la espalda y los glúteos, mejorando la postura y la extensión torácica.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3230'),
('2be992f8-41e6-59c7-a243-e662ee9ed3f4', 'Cobra boca abajo con palmas bajo los muslos', ARRAY['Túmbate boca abajo con las palmas de las manos bajo los muslos.', 'Activa los glúteos y eleva el pecho del suelo sin forzar el cuello.', 'Mantén la posición mientras respiras de forma pausada.', 'Baja lentamente controlando el movimiento.', 'Evita arquear en exceso la zona lumbar o levantar la cabeza demasiado.']::text[], 'intermedio', 'Trabaja la extensión de la columna y la espalda alta, mejorando la postura y la estabilidad del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3226'),
('53c5eec4-9fd2-59bd-b764-cbe65949fff0', 'Cisne con press boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos hacia delante.', 'Activa los glúteos y eleva el pecho y los brazos del suelo.', 'Presiona las palmas hacia el suelo como si empujaras, manteniendo la elevación.', 'Mantén la posición mientras respiras de forma controlada.', 'Evita forzar el cuello o arquear demasiado la zona lumbar.']::text[], 'intermedio', 'Fortalece la espalda y los glúteos mientras estira el pecho, mejorando la postura y la extensión de la columna.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2878'),
('e9918924-17e6-5f17-be32-58959d9e94a4', 'Elevación de trapecio a un brazo boca abajo', ARRAY['Túmbate boca abajo con un brazo extendido hacia delante.', 'Activa los glúteos y eleva el brazo del suelo sin girar el torso.', 'Mantén la posición mientras respiras de forma controlada.', 'Baja lentamente y cambia de brazo.', 'Evita encoger el hombro o levantar la cabeza en exceso.']::text[], 'intermedio', 'Fortalece trapecios y espalda alta, mejorando la estabilidad escapular y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2940'),
('c1a0dceb-e83c-55bb-8349-6ac430248718', 'Giro boca abajo en balón de estabilidad', ARRAY['Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo.', 'Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta.', 'Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite la rotación hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'principiante', 'Activa abdominales, oblicuos y zona lumbar, mejorando el control del core y la estabilidad sobre superficie inestable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1707'),
('0e8f3a11-3154-58f1-97c2-e07deae16a1d', 'Elevación en Y boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos formando una Y.', 'Activa los glúteos y eleva los brazos del suelo sin forzar el cuello.', 'Mantén la posición mientras respiras de forma controlada.', 'Baja lentamente controlando el movimiento.', 'Evita encoger los hombros o levantar la cabeza demasiado.']::text[], 'intermedio', 'Refuerza la espalda alta y los hombros posteriores, mejorando la postura y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5822'),
('eda4c069-a8f0-5e96-8745-c3a454ce1616', 'Flexión pseudo planche', ARRAY['Colócate en posición de flexión con las manos más cerca de la cintura.', 'Inclina el cuerpo hacia delante para cargar más peso sobre los hombros.', 'Baja el pecho flexionando los codos y mantén el core apretado.', 'Empuja para volver a la posición inicial sin perder la inclinación.', 'Evita dejar caer las caderas o perder la alineación del cuerpo.']::text[], 'avanzado', 'Fortalece pectorales y hombros con una inclinación que aumenta la dificultad y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3824'),
('d88d2bd5-97c2-5a40-bbe0-c23cb13c300e', 'Dominada negativa', ARRAY['Sujeta la barra con las palmas hacia delante y cuélgate con los brazos extendidos.', 'Sube con ayuda hasta que la barbilla quede por encima de la barra.', 'Baja lentamente controlando el movimiento durante varios segundos.', 'Mantén el core apretado y los hombros activos al bajar.', 'Evita dejarte caer de golpe o balancear el cuerpo.']::text[], 'intermedio', 'Desarrolla dorsales y bíceps controlando la bajada, mejorando la fuerza para dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7385'),
('94c85063-a036-547a-b90b-e673973835c0', 'Dominadas con agarre neutro', ARRAY['Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos.', 'Activa el core y junta los omóplatos.', 'Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales y bíceps colgándote de la barra con las palmas enfrentadas, mejorando la fuerza de tracción vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0651'),
('366b1ea0-cfe4-5af5-adff-0806585fe6f4', 'Dominada con rodillas flexionadas entre sillas', ARRAY['Coloca dos sillas estables y agárrate a los respaldos con las palmas enfrentadas.', 'Cuelga con los brazos estirados y las rodillas flexionadas entre las sillas sin tocar el suelo.', 'Tira de los codos hacia abajo y hacia atrás hasta que la barbilla supere las manos.', 'Baja controlando el movimiento hasta estirar los brazos del todo.', 'Evita balancearte o encoger los hombros; mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps con el peso corporal, ideal para progresar hacia la dominada completa.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3487'),
('a7d46160-240f-5208-942d-3d3593d2079f', 'Jalón de rodillas en balón de estabilidad', ARRAY['Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados.', 'Coloca las manos a los lados del balón de estabilidad para mayor apoyo.', 'Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho.', 'Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el abdomen llevando las rodillas al pecho sobre el balón, mejorando el control del core y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0650'),
('39c8af1e-12f6-5ee3-8969-42231debc54d', 'Remo con pulso', ARRAY['Túmbate boca abajo o inclínate con el torso recto y los brazos colgando.', 'Tira de los codos hacia atrás juntando las escápulas hasta la posición alta del remo.', 'Haz pequeños pulsos cortos sin perder la retracción escapular.', 'Mantén el cuello neutro y evita encoger los hombros hacia las orejas.', 'Respira de forma constante y controla el tempo sin rebotar.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con un movimiento corto y controlado que mejora la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3822'),
('b9f27762-6797-5b93-9277-efe39a0f9839', 'Puñetazo con paso adelante', ARRAY['Colócate en guardia con los puños a la altura de la barbilla y las rodillas ligeramente flexionadas.', 'Da un paso adelante mientras extiendes el brazo contrario en un puñetazo recto.', 'Gira la cadera y el torso para sumar potencia al golpe.', 'Recoge el brazo y vuelve a la guardia antes del siguiente paso.', 'Evita bloquear el codo del todo y mantén el abdomen activo.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y coordina tren superior e inferior con un gesto explosivo de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '6027'),
('22bccb78-9387-5fbe-b015-0b3abe964cf7', 'Postura del cachorro', ARRAY['Colócate a cuatro patas con las rodillas bajo la cadera y las manos bajo los hombros.', 'Camina las manos hacia delante manteniendo la cadera sobre las rodillas.', 'Baja el pecho hacia el suelo y alarga los brazos sin forzar.', 'Respira profundo y mantén la postura entre veinte y treinta segundos.', 'Evita arquear la zona lumbar o levantar los hombros hacia las orejas.']::text[], 'intermedio', 'Estira la espalda, los dorsales y los hombros, aliviando la tensión acumulada por el estudio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5897'),
('98566eb0-fd57-5cd1-aefd-008ec1a408f4', 'Empuje y jalón con peso corporal', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta.', 'Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina movimientos de empuje y tracción para trabajar pecho, tríceps y hombros, desarrollando fuerza global sin material.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1689'),
('9648c6f2-04fc-5c5b-a32d-93c29cd1d1af', 'Push press', ARRAY['Sujeta la barra a la altura de los hombros con las muñecas firmes.', 'Flexiona ligeramente las rodillas y el torso para cargar el impulso.', 'Extiende las piernas con rapidez y empuja la barra por encima de la cabeza.', 'Bloquea los codos arriba y baja la barra controlando el descenso.', 'Evita arquear en exceso la lumbar o empujar con los brazos antes que con las piernas.']::text[], 'intermedio', 'Desarrolla potencia de hombros y tríceps usando el impulso de piernas para mover la barra.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1200'),
('9b832989-c45c-558c-89e4-2048fd30a51d', 'Alcance con empuje', ARRAY['Colócate a cuatro patas con la espalda recta y el core activo.', 'Lleva una mano hacia delante y empuja el suelo alejándolo del cuerpo.', 'Alarga el brazo y abre la escápula sin girar la cadera.', 'Vuelve despacio a la posición inicial y alterna lados.', 'Evita hundir la zona lumbar o rotar el torso durante el alcance.']::text[], 'principiante', 'Mejora la movilidad de la espalda alta y los hombros, favoreciendo una postura más erguida.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4556'),
('4b090bfb-3d2e-5a2e-9565-5130e564bdb0', 'Empuje a carrera', ARRAY['Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.', 'Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto.', 'Empuja con las manos para extender los brazos y volver a la posición inicial.', 'Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho.', 'Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma.', 'Continúa durante el tiempo o el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca alternando empujes y carrera, mejorando la resistencia y la potencia de piernas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3638'),
('9546641c-c4ae-5038-aff0-8ccddf241cde', 'Flexión con rodilla al pecho', ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho flexionando los codos hacia atrás.', 'Al subir, lleva una rodilla hacia el pecho sin perder la línea del torso.', 'Vuelve a apoyar el pie y repite con la otra pierna.', 'Evita que la cadera se hunda o se eleve demasiado durante el movimiento.']::text[], 'intermedio', 'Combina empuje de pecho y trabajo de core, mejorando la estabilidad y la coordinación global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0654'),
('7e1875e0-c9bc-5e27-a3b1-8ea0c632695c', 'Flexión y fondos de tríceps en paralelas', ARRAY['Sujétate en las paralelas con los brazos estirados y los hombros bajos.', 'Flexiona los codos para bajar el cuerpo controlando el descenso.', 'Empuja hasta estirar los brazos sin bloquear de golpe los codos.', 'Mantén el core activo y evita encoger los hombros hacia las orejas.', 'Combina flexiones y fondos según tu nivel sin perder la técnica.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros con dos patrones de empuje que refuerzan el tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4775'),
('ab24ac06-0755-5a0d-8c31-5a5b4c59229f', 'Flexión, posición final', ARRAY['Coloca las manos bajo los hombros y extiende los brazos con el cuerpo en línea.', 'Aprieta glúteos y abdomen para mantener la cadera neutra.', 'Mantén la mirada al suelo y el cuello relajado.', 'Respira con normalidad sin dejar caer la cadera.', 'Evita bloquear los codos con tensión o elevar los hombros hacia las orejas.']::text[], 'intermedio', 'Refuerza pecho, tríceps y core manteniendo una posición alta estable y bien alineada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2351'),
('5ab4a784-e756-5ba4-8b10-816ce52d6477', 'Flexión mano tras mano', ARRAY['Empieza en posición de flexión con las manos bajo los hombros.', 'Baja el pecho flexionando los codos y mantén el cuerpo alineado.', 'Al subir, desplaza una mano ligeramente hacia delante y luego la otra.', 'Mantén el core firme para evitar que la cadera se balancee.', 'Evita mover los pies o perder la línea del torso durante el cambio.']::text[], 'intermedio', 'Aumenta el control y la estabilidad del tren superior alternando el apoyo de las manos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3985'),
('b51cc51a-5c1f-5bd6-b686-5311a4187ef9', 'Flexiones sobre bosu', ARRAY['Coloca el bosu en el suelo con el lado plano hacia arriba.', 'Colócate en posición de flexión con las manos en los bordes exteriores del bosu.', 'Activa el core y baja el cuerpo hacia el bosu flexionando los codos.', 'Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros sobre superficie inestable, añadiendo demanda de core y equilibrio al empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1307'),
('c661bba0-6610-5ed9-9fd8-53af8736887f', 'Flexión pike con toque de pies', ARRAY['Coloca las manos en el suelo y eleva la cadera hasta formar una V invertida con el cuerpo.', 'Baja la cabeza hacia el suelo flexionando los codos sin perder la alineación.', 'Empuja para volver arriba y, al subir, lleva una mano hacia el pie contrario.', 'Alterna el toque de pies en cada repetición manteniendo el core firme.', 'Evita arquear la espalda baja: mantén la cadera alta durante todo el movimiento.']::text[], 'intermedio', 'Trabaja pecho, hombros y tríceps mientras activas el core en una posición de flexión elevada.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3984'),
('9e289eca-6465-5222-9100-1ae4ddf76b39', 'Flexión con jalón', ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho al suelo flexionando los codos y mantén el core apretado.', 'Al subir, lleva un codo hacia atrás como si hicieras un jalón, activando el dorsal.', 'Alterna el lado en cada repetición sin girar la cadera.', 'Evita que la cadera se hunda o suba demasiado durante el movimiento.']::text[], 'intermedio', 'Combina el empuje de pecho con una tracción que activa dorsales y espalda para un trabajo completo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6537'),
('da60a85f-ee5d-5759-bb1a-2264a19ce096', 'Flexión, posición inicial', ARRAY['Apoya las manos bajo los hombros con los dedos apuntando al frente.', 'Extiende las piernas y aprieta glúteos y abdomen para alinear el cuerpo.', 'Mantén la mirada al suelo y el cuello en línea con la columna.', 'Respira con normalidad y comprueba que la cadera no cae ni sube.', 'Evita adelantar la cabeza o bloquear los codos en exceso.']::text[], 'intermedio', 'Enseña a colocar el cuerpo correctamente antes de hacer flexiones para proteger hombros y zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2350'),
('154e92f8-9351-5d86-8db1-e75b83f4f35c', 'Flexión con toque de rodilla', ARRAY['Colócate en posición de flexión con el cuerpo alineado y el core activo.', 'Baja el pecho al suelo flexionando los codos de forma controlada.', 'Al empujar para subir, lleva una rodilla hacia el pecho sin perder la alineación.', 'Alterna la rodilla en cada repetición manteniendo la cadera estable.', 'Evita girar el torso o dejar caer la cadera al llevar la rodilla.']::text[], 'intermedio', 'Trabaja pecho y tríceps añadiendo una activación de core al llevar la rodilla al pecho.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4162'),
('f888efcf-3b02-5ebb-9727-042604c49e06', 'Flexión a plancha lateral', ARRAY['Empieza en posición de flexión con las manos bajo los hombros.', 'Baja el pecho al suelo y empuja para volver arriba.', 'Al subir, gira el cuerpo y apoya un pie para entrar en plancha lateral.', 'Mantén la cadera alta y el brazo libre extendido hacia el techo.', 'Evita que la cadera caiga o que el hombro de apoyo se adelante.']::text[], 'intermedio', 'Combina el empuje de pecho con una plancha lateral que refuerza oblicuos y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4859'),
('c3df06fd-50eb-5880-8e91-66d9abd8c9a7', 'Flexión con toque de pies', ARRAY['Colócate en posición de flexión con el cuerpo alineado y el core firme.', 'Baja el pecho al suelo flexionando los codos.', 'Al empujar para subir, lleva una mano hacia el pie del mismo lado.', 'Alterna el toque de pies en cada repetición sin perder la alineación.', 'Evita arquear la espalda o levantar demasiado la cadera.']::text[], 'intermedio', 'Ejercicio pliométrico que trabaja pecho y tríceps con una activación extra de core al tocar los pies.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3977'),
('00e7183c-5ceb-59fc-ae7a-988ae4f5c9fd', 'Flexión en w', ARRAY['Coloca las manos en el suelo formando una W con los codos hacia fuera.', 'Mantén el cuerpo alineado y el core apretado durante todo el movimiento.', 'Baja el pecho de forma controlada flexionando los codos.', 'Empuja para volver arriba sin bloquear los codos del todo.', 'Evita encoger los hombros o perder la alineación de la cadera.']::text[], 'intermedio', 'Variante de flexión que trabaja pecho y tríceps con los codos hacia fuera para mayor activación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0665'),
('ad273715-2503-52a9-a7dc-c81ffbb6366c', 'Empuje con silla', ARRAY['Apoya las manos en el borde de una silla estable con los pies en el suelo.', 'Inclina el cuerpo hacia delante manteniendo la alineación de la espalda.', 'Flexiona los codos para bajar el pecho hacia la silla de forma controlada.', 'Empuja para volver a la posición inicial sin bloquear los codos.', 'Evita que la silla se mueva o que la cadera se hunda.']::text[], 'intermedio', 'Flexión asistida que trabaja pecho y tríceps con apoyo en una silla para facilitar el movimiento.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4329'),
('5b48bdb4-0ba6-5cdd-9ba2-234cda0b2515', 'Flexiones', ARRAY['Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.', 'Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio básico de empuje que fortalece pecho, tríceps y hombros, con el core como estabilizador.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0662'),
('bd152f7f-ffea-50f5-93c1-d709186e8cea', 'Flexiones con agarre cerrado sobre mancuernas', ARRAY['Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros.', 'Sostén una mancuerna en cada mano, apoyándolas en el suelo.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de flexión con agarre estrecho que enfatiza el trabajo de tríceps y pecho.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '0660'),
('e262953c-3106-55f0-a31e-3601f970e376', 'Flexión con patada de pierna hacia dentro', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.', 'Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta.', 'Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna.', 'Continúa alternando las patadas de pierna en cada repetición de la flexión.']::text[], 'intermedio', 'Combina el empuje de pecho con una patada de pierna que activa glúteos y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0661'),
('d717420e-f3a8-5b23-9d83-0dee1586341e', 'Flexiones sobre balón medicinal', ARRAY['Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.', 'Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión inestable sobre balón que trabaja pecho y tríceps con mayor demanda de core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '0663'),
('db1578ae-8f8e-5a3c-b536-887984d0129e', 'Flexiones sobre antebrazos', ARRAY['Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros.', 'Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.', 'Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de flexión que enfatiza tríceps y pecho con un rango de movimiento más corto.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1467'),
('644778a1-2016-5d22-9011-c497ae5bae7d', 'Flexión plus', ARRAY['Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.', 'En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.', 'Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión con extensión final de la escápula que activa pecho y serrato para mayor control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3145'),
('6e7a292b-8e4b-5ac3-8ba9-67d06c8971b0', 'Rotación externa con pica', ARRAY['Coloca los codos pegados al cuerpo con los antebrazos hacia delante y sujeta la pica con las manos.', 'Gira los antebrazos hacia fuera manteniendo los codos fijos junto a las costillas.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita separar los codos del torso o encoger los hombros durante el recorrido.']::text[], 'principiante', 'Activa el manguito rotador y la parte posterior del hombro, mejorando la estabilidad y previniendo molestias en el hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4602'),
('c5595a41-ad51-52db-bc6d-fd5e3bf04c9b', 'Estiramiento de posición frontal con pica', ARRAY['Sujeta la pica con las manos a la anchura de los hombros y súbela frente al pecho.', 'Levanta los codos hacia arriba hasta que la pica quede cerca del cuello.', 'Mantén la posición y respira profundo sin forzar las muñecas.', 'Evita arquear la zona lumbar mientras subes los codos.']::text[], 'principiante', 'Abre dorsales, hombros y muñecas, útil para mejorar la posición de front rack en levantamientos y aliviar tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4603'),
('94d1d531-91a5-5fe7-abcd-99fe2ec4e325', 'Good morning con pica', ARRAY['Apoya la pica sobre la espalda alta con las manos y separa los pies a la anchura de las caderas.', 'Lleva la cadera hacia atrás inclinando el tronco con la espalda recta.', 'Baja hasta notar tensión en los isquios y vuelve empujando la cadera hacia delante.', 'Evita redondear la espalda o flexionar las rodillas en exceso.']::text[], 'principiante', 'Trabaja la cadena posterior y enseña a mantener la espalda neutra mientras la cadera se desplaza hacia atrás.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4604'),
('6a8e0ec6-ba71-59e1-b12e-def7db4a49a7', 'Bisagra de cadera con pica', ARRAY['Sujeta la pica pegada a la espalda tocando la cabeza, la espalda alta y el sacro.', 'Empuja la cadera hacia atrás manteniendo la pica en contacto con esos tres puntos.', 'Baja hasta donde puedas sin perder la espalda neutra y vuelve apretando glúteos.', 'Evita doblar el tronco hacia delante en lugar de mover la cadera.']::text[], 'principiante', 'Enseña el patrón de bisagra de cadera, base del peso muerto, activando glúteos e isquios con control.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4605'),
('4b1f52d6-7e7e-5cbb-b738-d8f8789d42f9', 'Sentadilla sobre la cabeza con pica', ARRAY['Sujeta la pica por encima de la cabeza con los brazos extendidos y los pies a la anchura de los hombros.', 'Baja en sentadilla manteniendo la pica alineada sobre el centro de los pies.', 'Desciende lo que te permita la movilidad sin perder la espalda neutra.', 'Evita que la pica se vaya hacia delante o que los talones se levanten.']::text[], 'principiante', 'Mejora la movilidad de tobillo, cadera y hombros mientras refuerza el control del core en posición profunda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4606'),
('60ae00d1-5f0f-5bd8-b59f-a1addf053b23', 'Pase por encima de la cabeza con pica', ARRAY['Sujeta la pica con las manos anchas frente a las caderas.', 'Sube la pica por delante hasta pasarla por encima de la cabeza y detrás.', 'Hazlo despacio y con los brazos casi rectos, sin forzar.', 'Evita arquear la espalda o encoger los hombros al pasar la pica.']::text[], 'principiante', 'Moviliza hombros y pectoral, mejora la rotación del manguito rotador y prepara la articulación para press.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4607'),
('d1dee830-980f-5844-b91d-3b7da3dc75a0', 'Postura de la pirámide', ARRAY['Desde de pie, da un paso atrás y apoya el pie trasero con la punta hacia fuera.', 'Inclina el tronco sobre la pierna delantera manteniendo la espalda larga.', 'Apoya las manos en el suelo o en la pierna delantera según tu flexibilidad.', 'Respira profundo y evita bloquear la rodilla delantera o redondear la espalda.']::text[], 'intermedio', 'Estira isquios, gemelos y espalda baja, aportando calma y mejorando la flexibilidad posterior de las piernas.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5898'),
('02bc158d-8de8-576d-9a27-6eeb7c402f47', 'Estiramiento de cuádriceps tumbado', ARRAY['Túmbate boca abajo y flexiona una rodilla llevando el talón hacia el glúteo.', 'Sujeta el tobillo con la mano del mismo lado sin forzar la rodilla.', 'Mantén la cadera pegada al suelo y respira durante el estiramiento.', 'Evita arquear la lumbar o tirar del pie con demasiada fuerza.']::text[], 'principiante', 'Estira el cuádriceps y el flexor de cadera en una posición segura que protege la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4299'),
('bb64c431-21e7-528f-9e0e-5f1f417b4afb', 'Estiramiento de cuádriceps', ARRAY['De pie, flexiona una rodilla y lleva el talón hacia el glúteo.', 'Sujeta el tobillo con la mano y mantén las rodillas juntas.', 'Aprieta el glúteo y mantén la cadera hacia delante sin arquear la espalda.', 'Evita inclinarte hacia delante o separar la rodilla del cuerpo.']::text[], 'principiante', 'Alarga el cuádriceps y el flexor de cadera de pie, ayudando a recuperar tras carrera o sentadillas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4300'),
('851e929a-6c81-5956-9112-91f57873037c', 'Estiramiento de cuádriceps en cajón', ARRAY['Apoya el empeine del pie trasero sobre un cajón bajo detrás de ti.', 'Lleva la cadera hacia delante y aprieta el glúteo del lado estirado.', 'Mantén el tronco erguido y respira durante el estiramiento.', 'Evita arquear la lumbar o forzar si notas pinchazo en la rodilla.']::text[], 'principiante', 'Estira cuádriceps y flexor de cadera con apoyo elevado, ideal para ganar rango en la extensión de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1954'),
('b99ce49e-6f6f-5500-b15a-dbb7bb9108c4', 'Curl femoral en cuadrupedia', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Mantén una rodilla apoyada y flexiona la otra llevando el talón hacia el glúteo.', 'Sube y baja despacio sin mover la cadera ni la espalda.', 'Evita arquear la lumbar o girar la pelvis durante el movimiento.']::text[], 'intermedio', 'Fortalece isquios y glúteos sin material, mejorando la flexión de rodilla y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4968'),
('1778f593-c2ca-53d4-9b57-af6516a623bb', 'Cuádriceps', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.', 'Mantén el pecho arriba y la espalda recta.', 'Baja hasta que los muslos queden paralelos al suelo.', 'Empuja con los talones para volver a ponerte de pie en la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio básico de piernas que trabaja cuádriceps, glúteos e isquios y mejora el patrón de sentadilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3533'),
('f8ed581d-6032-55f1-98e2-3b85fc8d87e9', 'Abdominal de un cuarto', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la parte alta del abdomen con un recorrido corto, útil para iniciarse en el fortalecimiento del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3201'),
('7c959cb9-a271-5879-956d-488d1d4ac5b8', 'Carrera rápida de pies dentro y fuera', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Da pasos rápidos abriendo y cerrando los pies alternando el apoyo.', 'Mantén el peso sobre la parte delantera del pie y los brazos activos.', 'Evita quedarte plano o perder el ritmo por ir demasiado rápido.']::text[], 'intermedio', 'Eleva la frecuencia cardiaca y mejora la coordinación y la agilidad de pies con cambios rápidos de apoyo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10747'),
('6983fab2-5c49-54dd-9ed9-fb3699d6168b', 'Carrera de pies rápidos', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y el tronco erguido.', 'Mueve los pies rápido en el sitio con pasos cortos y ligeros.', 'Mantén los brazos en movimiento y el peso sobre la parte delantera del pie.', 'Evita talonear fuerte o inclinar el tronco hacia delante.']::text[], 'intermedio', 'Mejora la frecuencia de zancada, la coordinación y la resistencia cardiovascular con un trabajo explosivo de pies.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3196'),
('42dfebb0-6e0e-5262-866f-369c74771b6a', 'Pies rápidos', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.', 'Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio.', 'Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies.', 'Continúa durante el tiempo o el número de repeticiones deseado.']::text[], 'intermedio', 'Aumenta la frecuencia cardíaca con pasos rápidos en el sitio, mejorando la coordinación y la resistencia de piernas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3552'),
('084186be-5464-538d-958e-1ca33e436add', 'Balanceo rápido de brazos en el sitio', ARRAY['Colócate de pie con los pies a la anchura de las caderas y los brazos relajados a los lados.', 'Balancea los brazos hacia delante y hacia atrás de forma rápida y controlada, sin mover el tronco.', 'Mantén el abdomen firme y respira de forma continua durante todo el movimiento.', 'Evita encoger los hombros o arquear la espalda; el balanceo debe salir del hombro, no de la lumbar.']::text[], 'principiante', 'Moviliza hombros y cintura escapular, activa el core y prepara la parte superior del cuerpo antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3588'),
('0a91d162-b898-5b39-91e8-a58f96980a91', 'Trote rápido en el sitio', ARRAY['Colócate de pie con la espalda recta y los brazos flexionados a la altura de la cintura.', 'Trotа en el sitio levantando los pies del suelo con pasos cortos y rápidos.', 'Apoya primero la punta del pie y mantén un ritmo constante respirando de forma acompasada.', 'Evita golpear el suelo con el talón o inclinar el tronco hacia delante.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y cadera, ideal como calentamiento o para sumar cardio sin material.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3589'),
('29d9093b-9faa-50c6-a23a-2c18520e92d8', 'Flexión levantando un brazo', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Extiende un brazo hacia el lado, paralelo al suelo.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.', 'Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo.', 'Repite con el otro brazo extendido.']::text[], 'intermedio', 'Refuerza pecho, tríceps y hombros con una variante que exige control del core para evitar rotaciones.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0666'),
('48bc55bc-1fb1-5ca2-abe0-195372d5e45c', 'Flexión a una pierna con elevación', ARRAY['Coloca las manos bajo los hombros y extiende el cuerpo en plancha con una pierna elevada del suelo.', 'Baja el pecho flexionando los codos cerca del torso hasta casi tocar el suelo.', 'Empuja con las manos para volver arriba manteniendo la cadera alineada y sin girar.', 'Aprieta el core y los glúteos para no hundir la lumbar; respira al subir.']::text[], 'intermedio', 'Trabaja pecho, tríceps y core con apoyo reducido, mejorando el equilibrio y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0667'),
('7f81d4af-04be-55ff-aeee-c958d5acb4f2', 'Estiramiento de flexores de rodilla con pierna elevada', ARRAY['Apoya un pie sobre una superficie elevada con la pierna casi extendida y la espalda recta.', 'Inclina el tronco hacia delante desde la cadera hasta notar tensión en la parte posterior del muslo.', 'Mantén la posición entre veinte y treinta segundos respirando de forma lenta y profunda.', 'Evita redondear la espalda o forzar la rodilla; baja el apoyo si notas dolor.']::text[], 'principiante', 'Alarga isquiotibiales y gemelos, alivia la tensión tras correr o entrenar piernas y mejora la flexibilidad posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1911'),
('9241c8fc-d59d-5c70-9c53-50a980585614', 'Estiramiento de espalda alta alcanzando hacia delante', ARRAY['Siéntate o ponte de pie con la espalda recta y los brazos extendidos hacia delante.', 'Entrelaza los dedos y empuja las manos hacia delante mientras redondeas ligeramente la espalda alta.', 'Mantén la posición veinte segundos respirando despacio y sintiendo cómo se separan los omóplatos.', 'Evita encoger el cuello o bloquear la respiración durante el estiramiento.']::text[], 'principiante', 'Relaja la musculatura de la espalda alta y los omóplatos, útil tras jornadas de estudio o trabajo sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1794'),
('52db4a31-0d58-5338-a599-62f6e5ab1f1e', 'Estiramiento de espalda alcanzando arriba', ARRAY['De pie o sentado, entrelaza los dedos y eleva los brazos por encima de la cabeza.', 'Empuja las manos hacia el techo y alarga todo el costado del cuerpo sin arquear la lumbar.', 'Mantén veinte segundos respirando de forma profunda y relajando los hombros.', 'Evita sacar las costillas hacia delante o encoger el cuello.']::text[], 'principiante', 'Estira dorsales y hombros, mejora la movilidad del tren superior y contrarresta posturas encorvadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1797'),
('2198431b-9808-5eb8-9a77-a2e898a17e7a', 'Estiramiento de tríceps alcanzando hacia abajo', ARRAY['Eleva un brazo y flexiona el codo para llevar la mano hacia la espalda alta.', 'Con la otra mano, presiona suavemente el codo hacia abajo sin forzar el hombro.', 'Mantén veinte segundos respirando despacio y cambia de brazo.', 'Evita arquear la espalda o tirar del codo con brusquedad.']::text[], 'principiante', 'Alarga el tríceps y el hombro, alivia la tensión del brazo tras empujes y mejora la movilidad del codo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1828'),
('56401505-2052-587d-ad00-20240c5cb4ab', 'Estiramiento de hombro alcanzando arriba', ARRAY['De pie, eleva un brazo hacia arriba y estíralo lo máximo posible.', 'Inclina ligeramente el tronco hacia el lado contrario para notar el estiramiento en el costado.', 'Mantén veinte segundos respirando de forma lenta y cambia de lado.', 'Evita encoger el hombro o perder la alineación de la cadera.']::text[], 'principiante', 'Moviliza el hombro y el dorsal, mejora la amplitud del brazo y prepara la articulación para empujes y tracciones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1983'),
('adb6660a-fda5-5b38-bebd-c13591430a21', 'Estiramiento de espalda alta alcanzando', ARRAY['Ponte de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Entrelaza los dedos y extiende los brazos hacia delante mientras redondeas la espalda alta.', 'Mantén la posición veinte segundos respirando despacio y sin encoger el cuello.', 'Evita forzar la lumbar o bloquear la respiración.']::text[], 'principiante', 'Relaja la espalda alta y los omóplatos, mejora la postura y alivia la rigidez acumulada del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1795'),
('b3382c03-b8c2-5ceb-a58f-5fd2232c5552', 'Patada de hacha trasera', ARRAY['Colócate de pie con los pies a la anchura de las caderas y el abdomen firme.', 'Lleva una pierna hacia atrás y arriba en un gesto rápido y controlado, como un hachazo.', 'Vuelve a la posición inicial con control y repite alternando o completando la serie.', 'Evita arquear la lumbar o perder el equilibrio; apoya la mirada al frente.']::text[], 'intermedio', 'Potencia glúteos e isquiotibiales con un gesto explosivo de pierna, mejorando la fuerza y la coordinación del tren inferior.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2304'),
('6861faac-5ea1-5625-8eb4-30a18cd0b3fd', 'Puente posterior declinado', ARRAY['Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas.', 'Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.', 'Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos, isquiotibiales y zona lumbar manteniendo la cadera elevada con los pies más altos que la cabeza.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0668'),
('981184b7-215a-5182-b706-60245a3e4178', 'Apertura de deltoide posterior con sábana', ARRAY['Sujeta una sábana por los extremos con las manos y estira los brazos al frente a la altura de los hombros.', 'Abre los brazos hacia los lados manteniendo los codos casi rectos y la sábana tensa.', 'Aprieta los omóplatos al final del recorrido y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o usar impulso; controla el movimiento en todo momento.']::text[], 'intermedio', 'Refuerza el deltoide posterior y la espalda alta, corrigiendo la postura encorvada y equilibrando el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3744'),
('841093b3-f012-53aa-a176-cb4b4d05765e', 'Remo de deltoide posterior con sábana', ARRAY['Sujeta la sábana por los extremos con los brazos extendidos al frente y el tronco recto.', 'Tira de la sábana hacia el pecho flexionando los codos y llevando los omóplatos hacia atrás.', 'Aprieta la espalda un instante y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o inclinar el tronco hacia atrás para hacer más fuerza.']::text[], 'intermedio', 'Fortalece espalda alta, romboides y deltoide posterior, mejorando la postura y la fuerza de tracción sin material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3746'),
('61c658fb-a46f-555a-988f-29a1eeff8039', 'Estiramiento de deltoides posterior', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho.', 'Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho.', 'Mantén el estiramiento durante 15-30 segundos, luego suelta.', 'Repite del otro lado.']::text[], 'principiante', 'Estira la parte trasera del hombro y la zona alta de la espalda, aliviando tensión tras entrenar pecho o empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0669'),
('6c0fb166-b726-5736-a506-96b346ab2108', 'Patada de gancho trasera', ARRAY['Colócate de pie con las manos en guardia y el peso sobre la pierna de apoyo.', 'Lleva la pierna trasera hacia atrás y dibuja un gancho con el talón a la altura de la cadera.', 'Gira el tronco y la cadera a la vez que golpeas, manteniendo el abdomen firme.', 'Recoge la pierna con control y vuelve a la posición inicial sin perder el equilibrio.', 'Evita bloquear la rodilla de apoyo y no lances la patada solo con la pierna.']::text[], 'intermedio', 'Trabaja glúteos y core con un gesto de combate que mejora potencia de cadera, equilibrio y coordinación dinámica.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2301'),
('d1076b1d-6201-548f-9db2-771ec9b18b0f', 'Zancada hacia atrás desde déficit', ARRAY['Sube a una superficie elevada estable con un pie y mantén el otro en el aire.', 'Da un paso largo hacia atrás y baja la rodilla trasera hacia el suelo con control.', 'Mantén el tronco erguido y empuja con la pierna delantera para volver arriba.', 'Respira al bajar y evita que la rodilla delantera se vaya hacia dentro.', 'No uses un déficit demasiado alto si pierdes el equilibrio o redondeas la espalda.']::text[], 'intermedio', 'Fortalece glúteos y piernas con mayor rango de movimiento, mejorando fuerza unilateral y control de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5312'),
('f182a753-70ee-51f6-8380-5347b7c032b2', 'Zancada trasera con cuerdas de batalla', ARRAY['Sujeta un extremo de la cuerda en cada mano con las rodillas ligeramente flexionadas.', 'Da un paso atrás y baja en zancada mientras agitas las cuerdas con ritmo constante.', 'Empuja con la pierna delantera para volver y alterna la pierna que retrocede.', 'Mantén el pecho alto y el abdomen activo durante todo el movimiento.', 'Evita encorvar la espalda o golpear las cuerdas sin control cuando suba la fatiga.']::text[], 'intermedio', 'Combina fuerza de piernas y cardio con trabajo de hombros y core, elevando pulsaciones y resistencia muscular.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2933'),
('d59bae9a-7987-5ef2-bea9-ca2dc288d1a0', 'Dominada por detrás', ARRAY['Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la espalda y los brazos con un agarre que enfatiza dorsales y mejora la fuerza de tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0670'),
('a2381173-2ee2-53f6-b796-d4095650ea21', 'Zancada con desplazamiento hacia atrás desde déficit', ARRAY['Coloca un pie sobre una superficie elevada estable y el otro en el suelo.', 'Da un paso atrás amplio y baja la rodilla trasera hacia el suelo con control.', 'Impulsa con la pierna delantera para volver a la posición inicial.', 'Mantén el tronco erguido y la rodilla delantera alineada con el pie.', 'Evita dar pasos cortos o inclinarte hacia delante para compensar.']::text[], 'intermedio', 'Mejora fuerza y estabilidad de piernas con un paso atrás amplio que exige control de cadera y rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5582'),
('cd50b1d3-9299-5297-af5a-54d57e2027ac', 'Postura reclinada del dedo gordo con cuerda', ARRAY['Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.', 'Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos.', 'Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado.', 'Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial.', 'Repite con la pierna izquierda.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'principiante', 'Estira isquiotibiales y gemelos tumbado, ideal para relajar la parte posterior de la pierna con ayuda de la cuerda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1582'),
('9d234abe-502b-537a-97e7-8bdfd0db234f', 'Estiramiento de extensores del tronco inferior recostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Lleva las rodillas hacia el pecho y abrázalas con las manos con suavidad.', 'Respira profundo y mantén la postura sin forzar la zona lumbar.', 'Baja las piernas lentamente y evita rebotar o tirar con brusquedad.']::text[], 'principiante', 'Alivia la tensión de la zona lumbar y los glúteos, favoreciendo la relajación de la espalda baja tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1808'),
('11921d57-2293-50d3-9143-2e2308911abb', 'Estiramiento de rotadores externos y extensores de cadera recostado', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies en el suelo.', 'Cruza un tobillo sobre la rodilla contraria formando una figura de cuatro.', 'Lleva suavemente la rodilla hacia el pecho hasta notar el estiramiento en el glúteo.', 'Respira de forma relajada y evita tirar del cuello o forzar la cadera.']::text[], 'principiante', 'Estira glúteos y cadera tumbado, mejorando movilidad y aliviando tensión en la zona lumbar y los flexores.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1939'),
('3d09fa84-c908-5045-ab30-a13a63fddf73', 'Estiramiento de flexores de rodilla recostado', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Sujeta el muslo de la pierna estirada y extiende la rodilla poco a poco.', 'Mantén la pierna contraria apoyada y la zona lumbar relajada en el suelo.', 'Respira profundo y evita bloquear la rodilla o tirar con demasiada fuerza.']::text[], 'principiante', 'Estira isquiotibiales y gemelos tumbado, ayudando a recuperar flexibilidad en la parte posterior de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1921'),
('31d17b00-c305-5906-8bdc-6c6c7438530f', 'Estiramiento de flexores de rodilla recostado con toalla', ARRAY['Túmbate boca arriba y pasa una toalla por la planta del pie de una pierna.', 'Sujeta los extremos y eleva la pierna estirada hasta notar tensión en la parte posterior.', 'Mantén la otra pierna apoyada y la espalda baja relajada en el suelo.', 'Respira de forma pausada y evita tirar fuerte o levantar la cadera.']::text[], 'principiante', 'Estira isquiotibiales y gemelos con ayuda de una toalla, permitiendo un estiramiento controlado y cómodo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1922'),
('ea5d04a6-05fa-587b-bc24-af40d32aa4ce', 'Saltitos repetidos', ARRAY['Colócate de pie con los pies a la anchura de la cadera y las rodillas ligeramente flexionadas.', 'Salta poco a poco manteniendo el contacto breve con el suelo y aterriza con las rodillas suaves.', 'Mantén el tronco erguido y los brazos relajados acompañando el ritmo.', 'Respira de forma constante y evita aterrizar con las piernas rígidas o los talones.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la reactividad de piernas con saltos cortos que activan gemelos y tobillos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9408'),
('ade91e0b-4b13-520c-93ee-f7cb92f0f03a', 'Extensión de cadera a 45 grados con banda elástica', ARRAY['Coloca la banda alrededor de los muslos o anclada al frente según tu montaje.', 'Inclínate ligeramente hacia delante con el tronco firme y las rodillas suaves.', 'Empuja la cadera hacia atrás y extiéndela contrayendo el glúteo al final.', 'Mantén el abdomen activo y evita arquear la zona lumbar al extender.']::text[], 'principiante', 'Fortalece glúteos e isquiotibiales con énfasis en el glúteo, mejorando la extensión de cadera y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7999'),
('207057bc-ff7d-5ec8-9a1a-98761b46944e', 'Hiperextensión a 45 grados con banda elástica', ARRAY['Coloca la banda en el banco a 45 grados y pásala por la espalda o los hombros.', 'Apoya las caderas en el soporte y baja el tronco con control.', 'Extiende la cadera para subir hasta alinear el cuerpo sin hiperextender la espalda.', 'Mantén el abdomen activo y evita subir con impulso o arquear en exceso.']::text[], 'principiante', 'Refuerza la espalda baja, glúteos e isquiotibiales con resistencia extra, mejorando la extensión de tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3875'),
('b2581a3d-b507-5ec9-b129-bc937dec784c', 'Sentadilla dividida con aducción y banda elástica', ARRAY['Coloca la banda alrededor de una pierna y fija el otro extremo para crear tensión hacia dentro.', 'Adopta una posición de sentadilla dividida con un pie delante y otro detrás.', 'Baja flexionando ambas rodillas mientras resistes la aducción de la banda.', 'Empuja con la pierna delantera para subir y mantén el tronco erguido.', 'Evita que la rodilla delantera se vaya hacia dentro o que la banda tire con brusquedad.']::text[], 'principiante', 'Trabaja aductores y piernas con una sentadilla dividida que mejora fuerza unilateral y control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4109'),
('746a9b1f-6463-5647-a781-f9f8032335a6', 'Bicicleta de aire con banda elástica', ARRAY['Túmbate boca arriba con la banda anclada y sujétala con las manos junto a la cabeza.', 'Eleva los hombros del suelo y extiende una pierna mientras acercas la rodilla contraria al pecho.', 'Alterna el movimiento de forma lenta y controlada sin arquear la zona lumbar.', 'Espira al acercar la rodilla y evita tirar del cuello con las manos.']::text[], 'principiante', 'Trabaja el abdomen y los oblicuos con movimiento alterno de piernas, mejorando la estabilidad del core y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2420'),
('8081b110-fade-54c8-b759-001b7d728411', 'Press pallof alterno con piernas divididas y banda elástica', ARRAY['Ancla la banda a la altura del pecho y colócate de lado con las piernas divididas.', 'Sujeta la banda con ambas manos frente al esternón y tensa el abdomen.', 'Extiende los brazos al frente sin dejar que el cuerpo rote hacia la banda.', 'Mantén unos segundos y vuelve despacio, respirando de forma constante.', 'Evita girar el tronco o encoger los hombros durante el movimiento.']::text[], 'principiante', 'Fortalece el core y los oblicuos resistiendo la rotación, mejorando la estabilidad del tronco en posiciones asimétricas.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10184'),
('65664ac9-ddf1-5cc2-a902-6038d7065889', 'Bicho muerto antirrotación con banda elástica', ARRAY['Túmbate boca arriba con la banda anclada a un lado y sujétala con una mano.', 'Eleva brazos y piernas formando un ángulo recto con el suelo.', 'Extiende lentamente el brazo y la pierna contraria sin que el tronco rote.', 'Vuelve al centro y alterna los lados manteniendo la zona lumbar pegada al suelo.', 'Evita arquear la espalda o dejar que la banda te gire el torso.']::text[], 'principiante', 'Refuerza el core profundo y los oblicuos controlando la rotación mientras coordinas brazos y piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3866'),
('9e83f7ff-98b1-5d2f-93ac-c5821aa028a5', 'Estiramiento de recepción frontal asistido con banda elástica', ARRAY['Coloca la banda en un punto fijo detrás de ti y pásala por la muñeca.', 'Arrodíllate con una pierna adelantada y el codo elevado en posición de recepción.', 'Lleva suavemente la cadera hacia delante hasta notar el estiramiento en la parte frontal.', 'Mantén la posición respirando profundo y sin forzar la muñeca.', 'Evita rebotar o arquear en exceso la zona lumbar.']::text[], 'principiante', 'Estira cuádriceps, flexores de cadera y muñecas, mejorando la movilidad para posiciones de recepción en halterofilia.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5147'),
('ca572203-62aa-5125-849d-d44b2a11ab96', 'Curl nórdico de isquios asistido con banda elástica', ARRAY['Arrodíllate con la banda anclada delante para que te ayude a controlar la bajada.', 'Sujeta la banda y mantén el cuerpo recto desde las rodillas hasta la cabeza.', 'Baja el tronco lentamente hacia delante controlando con los isquios.', 'Empuja con las manos en la banda para volver a la posición inicial.', 'Evita doblar la cadera o perder la línea del cuerpo durante el descenso.']::text[], 'avanzado', 'Fortalece los isquiotibiales con énfasis excéntrico, mejorando la fuerza y la prevención de lesiones en el tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4204'),
('dfc30c85-7c64-57c5-a707-b602a0f6c7c7', 'Dominada a un brazo asistida con banda elástica', ARRAY['Coloca la banda en la barra y pásala bajo el pie o la rodilla para asistirte.', 'Agarra la barra con una mano y cuelga con el brazo extendido.', 'Tira del cuerpo hacia arriba llevando el codo hacia la cadera.', 'Baja de forma controlada sin dejarte caer de golpe.', 'Evita balancearte o encoger los hombros al iniciar el tirón.']::text[], 'principiante', 'Trabaja la espalda y los bíceps con una dominada unilateral asistida, progresando hacia la dominada a un brazo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10660'),
('12a87b0d-40e9-5f8d-add5-1125a2cc2e29', 'Patada trasera con pierna flexionada de rodillas con banda elástica', ARRAY['Colócate a cuatro apoyos con la banda anclada delante y pasada por el pie.', 'Mantén la rodilla flexionada y el abdomen activo.', 'Empuja el pie hacia atrás y arriba apretando el glúteo.', 'Vuelve despacio sin dejar caer la rodilla al suelo.', 'Evita arquear la lumbar o girar la cadera durante la patada.']::text[], 'principiante', 'Aísla el glúteo mayor con extensión de cadera, mejorando la fuerza y el control de la musculatura posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2149'),
('45f74688-e7bf-56c7-8f7c-60f5c2ed60b5', 'Patada lateral con pierna flexionada de rodillas con banda elástica', ARRAY['Colócate a cuatro apoyos con la banda anclada a un lado y pasada por el pie.', 'Mantén la rodilla flexionada y el core activo.', 'Abre la pierna hacia el lado contra la resistencia de la banda.', 'Vuelve despacio sin dejar que la cadera se balancee.', 'Evita rotar el tronco o levantar demasiado la pelvis.']::text[], 'principiante', 'Activa el glúteo medio y estabilizadores de cadera, mejorando el control lateral y la estabilidad de la pelvis.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2418'),
('0cea0869-b828-5b04-a4df-f3fa79e49f12', 'Remo inclinado con agarre neutro y banda elástica', ARRAY['Ancla la banda a baja altura y sujétala con agarre neutro.', 'Inclina el tronco hacia delante manteniendo la espalda recta.', 'Tira de la banda hacia el abdomen llevando los codos atrás.', 'Aprieta la espalda arriba y baja de forma controlada.', 'Evita redondear la espalda o tirar con los brazos sin activar la espalda.']::text[], 'principiante', 'Fortalece la espalda y los bíceps con un tirón horizontal, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4570'),
('1ec814e2-d8a0-576c-9281-c810f18d44ec', 'Bird dog con banda elástica', ARRAY['Colócate a cuatro apoyos con la banda anclada delante y sujeta un extremo.', 'Extiende el brazo y la pierna contraria a la vez manteniendo el tronco estable.', 'Mantén unos segundos sin que la cadera rote.', 'Vuelve al centro y alterna los lados.', 'Evita arquear la lumbar o levantar demasiado la pierna.']::text[], 'principiante', 'Mejora la estabilidad de la columna y el control del core coordinando brazo y pierna contrarios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3511'),
('c87e4592-846f-5fa5-a58c-57e36f2cb2a0', 'Sentadilla en polea con banda elástica', ARRAY['Ancla la banda a un punto alto y sujétala frente al pecho.', 'Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando rodillas y cadera manteniendo el pecho alto.', 'Empuja con los talones para volver a subir.', 'Evita que las rodillas se metan hacia dentro o que la espalda se redondee.']::text[], 'principiante', 'Trabaja cuádriceps y glúteos con una sentadilla guiada por la banda, mejorando la fuerza y el control del descenso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3857'),
('5d6e2b31-063f-5e2f-9812-0e158e0085f2', 'Almeja con banda elástica', ARRAY['Túmbate de lado con la banda por encima de las rodillas y las piernas flexionadas.', 'Mantén los pies juntos y la cadera apilada.', 'Abre la rodilla superior contra la banda sin mover la pelvis.', 'Baja despacio y repite antes de cambiar de lado.', 'Evita rotar el tronco hacia atrás o separar los pies.']::text[], 'principiante', 'Fortalece el glúteo medio y los rotadores externos de cadera, mejorando la estabilidad de la pelvis.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2150'),
('ebf9e5a0-4d7a-5f6c-ac58-d004b78c873c', 'Curl drag con banda elástica', ARRAY['Pisa la banda o anótala abajo y sujeta los extremos con las palmas hacia arriba.', 'Mantén los codos pegados al cuerpo y los hombros atrás.', 'Sube las manos arrastrando la banda hacia el pecho.', 'Baja de forma controlada sin balancear el tronco.', 'Evita mover los codos hacia delante o usar impulso.']::text[], 'principiante', 'Aísla el bíceps con un recorrido que arrastra la banda hacia el cuerpo, mejorando el pico de contracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8327'),
('11a780c6-c85d-5147-abcd-eb25024e8d59', 'Caminata de pato con banda elástica', ARRAY['Coloca la banda por encima de las rodillas o los tobillos.', 'Adopta una posición de sentadilla baja con el pecho alto.', 'Camina hacia delante dando pasos cortos manteniendo la tensión.', 'Mantén las rodillas alineadas con los pies en todo momento.', 'Evita juntar las rodillas o enderezar demasiado el tronco.']::text[], 'principiante', 'Activa glúteos y cuádriceps con desplazamientos en sentadilla, mejorando la resistencia y la estabilidad del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2417'),
('b3051f88-5857-50f2-8bd1-c764f9e1bdd1', 'Puente de glúteos elevado con banda elástica', ARRAY['Apoya los pies elevados en un escalón con la banda por encima de las rodillas.', 'Túmbate boca arriba con la espalda apoyada y el abdomen activo.', 'Empuja con los talones y eleva la cadera apretando los glúteos.', 'Mantén arriba un instante y baja de forma controlada.', 'Evita arquear la lumbar o empujar con las puntas de los pies.']::text[], 'principiante', 'Fortalece glúteos e isquios con mayor rango de movimiento, mejorando la extensión de cadera y la estabilidad lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4447'),
('621b5583-5b60-5794-b142-ebdb2c6151c2', 'Flexión explosiva con banda elástica', ARRAY['Coloca la banda alrededor de la espalda y sujeta los extremos con las manos en el suelo, en posición de flexión.', 'Baja el pecho de forma controlada hasta rozar el suelo.', 'Empuja con fuerza para despegar las manos del suelo de forma explosiva.', 'Aterriza con los codos ligeramente flexionados para amortiguar el impacto.', 'Evita arquear la zona lumbar manteniendo el core activo durante todo el movimiento.']::text[], 'principiante', 'Trabaja el pecho con potencia y velocidad, mejorando la fuerza explosiva y la estabilidad del core en el empuje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10650'),
('0979028b-b036-5c05-97ef-ec75e18dbbe5', 'Rotación externa con banda elástica', ARRAY['Fija la banda a la altura del codo y colócate de lado con el codo pegado al cuerpo a 90 grados.', 'Gira el antebrazo hacia fuera manteniendo el codo fijo junto al torso.', 'Vuelve despacio a la posición inicial controlando la tensión.', 'Evita mover el hombro o el codo durante el recorrido.']::text[], 'principiante', 'Refuerza el manguito rotador y la parte posterior del hombro, ayudando a estabilizar la articulación y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2151'),
('b36d6019-694c-532f-8712-61c7260fe185', 'Extensión de dedos con banda elástica', ARRAY['Coloca la banda alrededor de los dedos con la palma hacia abajo sobre una superficie.', 'Abre los dedos contra la resistencia de la banda de forma lenta.', 'Mantén la apertura un segundo y vuelve a cerrar con control.', 'Evita compensar moviendo la muñeca o el antebrazo.']::text[], 'principiante', 'Fortalece los extensores de la mano y el antebrazo, útil para la readaptación de tendinitis y el equilibrio muscular.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8877'),
('7c8a8c70-e42a-53ce-8968-ab03b0a2f568', 'Hiperextensión en el suelo con banda elástica', ARRAY['Túmbate boca abajo con la banda sujeta por las manos y los brazos extendidos al frente.', 'Eleva el pecho y las piernas del suelo de forma simultánea y controlada.', 'Aprieta los glúteos arriba y mantén un segundo sin forzar la lumbar.', 'Baja despacio evitando dejarte caer de golpe.']::text[], 'principiante', 'Fortalece la musculatura de la espalda y los glúteos, mejorando la extensión de la columna y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2423'),
('5b4ba194-f8a5-519a-9e0f-0143086a5f62', 'Eversión del pie con banda elástica', ARRAY['Siéntate con la pierna extendida y la banda enganchada en el antepié.', 'Gira el pie hacia fuera contra la resistencia sin mover la rodilla.', 'Vuelve despacio a la posición neutra controlando el movimiento.', 'Evita compensar girando toda la pierna.']::text[], 'principiante', 'Fortalece los peroneos y la musculatura lateral del tobillo, mejorando la estabilidad y la readaptación de esguinces.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '3127'),
('e6e0f90b-dcdf-56d7-a251-75dcb0e8337b', 'Rotación externa del pie con banda elástica', ARRAY['Siéntate con la banda sujeta al antepié y la pierna relajada.', 'Rota el pie hacia fuera manteniendo el talón fijo en el suelo.', 'Aguanta un instante arriba y vuelve con control.', 'Evita mover la rodilla o la cadera durante la rotación.']::text[], 'principiante', 'Activa la musculatura rotadora del tobillo y el pie, útil para recuperar movilidad y estabilidad tras una lesión.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '3125'),
('32ddd892-a1e0-53d2-b88f-1b4c868945b3', 'Inversión del pie con banda elástica', ARRAY['Siéntate con la banda enganchada en el antepié y el talón apoyado.', 'Gira el pie hacia dentro contra la resistencia de forma lenta.', 'Vuelve a la posición neutra controlando la tensión.', 'Evita levantar el talón o girar la pierna entera.']::text[], 'principiante', 'Refuerza el tibial posterior y la musculatura interna del tobillo, mejorando la estabilidad y la propiocepción.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '3128'),
('ce51307c-e73a-5c12-91c3-2da2661d825e', 'Flexión plantar del pie con banda elástica', ARRAY['Siéntate con la banda en la planta del pie y sujeta los extremos con las manos.', 'Empuja el pie hacia abajo como si pisaras el acelerador.', 'Mantén la contracción un segundo y vuelve despacio.', 'Evita mover la rodilla o despegar el talón del apoyo.']::text[], 'principiante', 'Trabaja el sóleo y el gemelo para recuperar fuerza y movilidad del tobillo en procesos de readaptación.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '3126'),
('9478c1b9-e335-5f7b-9b06-aeadc43b17e5', 'Plancha frontal con patada y banda elástica', ARRAY['Coloca la banda alrededor de los tobillos y adopta la posición de plancha sobre antebrazos.', 'Eleva una pierna hacia atrás manteniendo la cadera estable.', 'Aprieta el glúteo arriba y vuelve a la posición inicial.', 'Alterna las piernas sin balancear la cadera ni hundir la lumbar.']::text[], 'principiante', 'Combina estabilidad del core con activación de glúteos, mejorando el control del tronco y la fuerza funcional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2152'),
('f2c19e0d-aae1-5279-b8bf-7436aec6740f', 'Sentadilla completa con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta los extremos a la altura de los hombros.', 'Baja flexionando caderas y rodillas hasta donde controles, con el pecho erguido.', 'Empuja el suelo con los talones para subir apretando los glúteos.', 'Evita que las rodillas se metan hacia dentro durante el descenso.']::text[], 'principiante', 'Fortalece piernas y glúteos con un patrón completo, mejorando la fuerza y la movilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2153'),
('792a1f41-cbfa-5664-8ea7-8b89be884a03', 'Puente de glúteos con banda elástica', ARRAY['Túmbate boca arriba con la banda sobre las caderas y los pies apoyados.', 'Empuja con los talones y eleva la cadera hasta alinear rodillas, cadera y hombros.', 'Aprieta los glúteos arriba y mantén un segundo.', 'Baja despacio sin apoyar del todo y evita arquear la lumbar.']::text[], 'principiante', 'Activa glúteos e isquios desde el suelo, mejorando la extensión de cadera y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2154'),
('7f92f101-470d-59dc-b3ae-ba8ca7375115', 'Abducción en puente de glúteos con banda elástica', ARRAY['Túmbate boca arriba con la banda alrededor de los muslos y los pies apoyados.', 'Eleva la cadera hasta formar una línea recta.', 'Separa las rodillas contra la banda manteniendo el puente.', 'Junta las rodillas y baja la cadera con control sin perder la tensión.']::text[], 'principiante', 'Refuerza el glúteo medio junto con el glúteo mayor, mejorando la estabilidad de la cadera y la pelvis.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7198'),
('29bf7303-29a3-5340-94f0-ad5908f492f7', 'Caminata de puente de glúteos con banda elástica', ARRAY['Túmbate boca arriba con la banda sobre las caderas y eleva la pelvis.', 'Da pasos cortos hacia un lado manteniendo la cadera alta.', 'Mantén las rodillas alineadas y el core activo durante el recorrido.', 'Evita que la cadera caiga o que las rodillas se junten.']::text[], 'principiante', 'Trabaja glúteos y core con desplazamiento lateral, mejorando la estabilidad de la pelvis en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10870'),
('fd9cb10b-d997-5166-88fc-82856376dcaf', 'Empuje de cadera con banda elástica', ARRAY['Apoya la espalda alta en un banco con la banda sobre las caderas y los pies en el suelo.', 'Empuja con los talones y eleva la cadera hasta alinear el tronco.', 'Aprieta los glúteos arriba y mantén un segundo.', 'Baja despacio sin perder la tensión de la banda.']::text[], 'principiante', 'Fortalece glúteos e isquios con extensión de cadera, mejorando la potencia y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2760'),
('5b5bd2d3-c590-5509-824d-357a61dafee3', 'Hip thrust de rodillas con banda elástica', ARRAY['Colócate de rodillas con la banda sobre las caderas y el tronco erguido.', 'Lleva la cadera hacia delante apretando los glúteos sin arquear la lumbar.', 'Mantén la contracción un segundo y vuelve despacio.', 'Evita balancear el tronco o tirar con la espalda baja.']::text[], 'principiante', 'Activa el glúteo desde una posición arrodillada, mejorando la extensión de cadera y el control lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7277'),
('eefb085c-e81c-55fa-8b5e-cef84171134c', 'Empuje de caderas de rodillas con banda elástica', ARRAY['Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados.', 'Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas.', 'Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio.', 'Activa los glúteos y los músculos del core.', 'Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo.', 'Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Aísla los glúteos empujando la cadera contra la banda con las rodillas apoyadas, ideal para activación y fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3236'),
('1ab72107-24e9-5234-a3b2-0ca74f3fdd05', 'Remo invertido con banda', ARRAY['Sujeta la banda a un punto fijo a la altura del pecho y agárrala con ambas manos.', 'Colócate de pie, inclina el torso hacia atrás y deja los brazos extendidos con el cuerpo en línea recta.', 'Tira de la banda llevando los codos hacia atrás y junta las escápulas sin encoger los hombros.', 'Vuelve despacio a la posición inicial controlando la banda.', 'Evita arquear la zona lumbar: mantén el abdomen firme durante todo el recorrido.']::text[], 'principiante', 'Fortalece la espalda alta y los bíceps tirando del cuerpo contra la banda, mejorando la postura y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4379'),
('dc77b07e-e7cd-5891-99c6-d93d757c3e77', 'Extensión isométrica de pulgar con banda', ARRAY['Coloca la banda alrededor del pulgar y sujétala con la otra mano para crear tensión.', 'Extiende el pulgar hacia fuera contra la resistencia hasta notar tensión cómoda.', 'Mantén la posición entre diez y veinte segundos sin bloquear la respiración.', 'Relaja despacio y repite el número de series indicado.', 'Evita mover la muñeca: el movimiento debe salir solo del pulgar.']::text[], 'principiante', 'Refuerza los extensores de la muñeca y la mano, útil para prevenir molestias por uso prolongado del teclado o el móvil.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9996'),
('0a5f5a76-c3eb-57b1-930c-d19ad6357b84', 'Sentadilla con salto y banda', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta los extremos a la altura de los hombros.', 'Baja en sentadilla llevando las caderas atrás y manteniendo el pecho alto.', 'Empuja con fuerza y salta hacia arriba extendiendo las piernas.', 'Aterriza con las rodillas ligeramente flexionadas y absorbiendo el impacto.', 'Evita aterrizar con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'principiante', 'Trabaja la potencia de piernas y glúteos con un gesto explosivo que también eleva la frecuencia cardíaca.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3878'),
('ab0810d0-cec5-519b-8308-0f1fef0d9259', 'Jumping jack con banda', ARRAY['Pasa la banda por la espalda y sujeta los extremos con las manos a la altura de la cintura.', 'Salta abriendo las piernas mientras elevas los brazos contra la resistencia de la banda.', 'Vuelve al centro con otro salto y mantén un ritmo constante.', 'Respira de forma acompasada y aterriza con las rodillas algo flexionadas.', 'Evita encoger los hombros o perder el control de la banda durante el movimiento.']::text[], 'principiante', 'Eleva la frecuencia cardíaca combinando saltos y apertura de brazos, con trabajo extra de hombros y glúteos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2465'),
('15446153-afd5-5368-9c2e-d10bfeb0c2c6', 'Patada hacia atrás de rodillas con banda', ARRAY['Coloca la banda en el tobillo y sujétala a un punto fijo bajo o písala con la rodilla contraria.', 'Apóyate en cuadrupedia con las manos bajo los hombros y la espalda recta.', 'Empuja el talón hacia atrás y arriba apretando el glúteo sin mover la cadera.', 'Vuelve despacio a la posición inicial sin dejar que la banda tire de la pierna.', 'Evita arquear la lumbar: mantén el abdomen activo y el movimiento pequeño y controlado.']::text[], 'principiante', 'Aísla el glúteo con una extensión de cadera controlada que también activa isquios y zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7208'),
('6b6ce616-9508-5bc1-9cd4-14400c63ad60', 'Medio círculo de pierna de rodillas con banda', ARRAY['Coloca la banda en el tobillo y fíjala a un punto bajo o písala con la rodilla de apoyo.', 'En cuadrupedia, eleva la pierna hacia un lado manteniendo la rodilla flexionada.', 'Dibuja medio círculo hacia atrás sin mover el tronco ni la cadera.', 'Vuelve por el mismo camino controlando la banda.', 'Evita girar la pelvis o compensar con la lumbar durante el recorrido.']::text[], 'principiante', 'Activa el glúteo medio y el core con un movimiento circular de cadera que mejora la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7209'),
('7e0542ac-fbbd-59da-a3f6-1d9e2b1fa4eb', 'Medio círculo de pierna de rodillas en banco con banda', ARRAY['Coloca la banda en el tobillo y fíjala a un punto bajo.', 'Apoya antebrazos y rodillas sobre el banco con la espalda alineada.', 'Eleva la pierna hacia un lado y dibuja medio círculo hacia atrás.', 'Mantén la cadera estable y vuelve despacio a la posición inicial.', 'Evita balancear el tronco o perder la alineación de la espalda.']::text[], 'principiante', 'Trabaja el glúteo y la estabilidad de cadera con apoyo en banco, reduciendo la carga sobre las muñecas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6741'),
('d6697e01-4714-502b-8649-dff899538953', 'Patada trasera de rodillas en banco con banda', ARRAY['Coloca la banda en el tobillo y fíjala a un punto bajo o písala.', 'Apoya rodillas y antebrazos en el banco con la espalda recta.', 'Empuja el talón hacia atrás y arriba apretando el glúteo.', 'Baja la pierna despacio sin dejar que la banda la arrastre.', 'Evita elevar la cadera o arquear la lumbar para ganar rango.']::text[], 'principiante', 'Aísla el glúteo con una extensión de cadera sobre banco que también exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11059'),
('086028a0-2ccc-5389-aca9-18e5781b506e', 'Plancha lateral de rodillas con banda', ARRAY['Coloca la banda por encima de las rodillas y túmbate de lado apoyando el antebrazo.', 'Flexiona las rodillas y eleva la cadera hasta formar una línea recta con el tronco.', 'Mantén la posición apretando glúteos y abdomen sin dejar caer la cadera.', 'Respira con normalidad durante el tiempo indicado y cambia de lado.', 'Evita hundir el hombro de apoyo o dejar que la cadera descienda.']::text[], 'principiante', 'Refuerza oblicuos, abdomen y hombros con un isométrico que mejora la estabilidad lateral del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2155'),
('5c583792-c71a-5b92-b537-e312d4f0a4c1', 'Sissy squat de rodillas con banda', ARRAY['Sujeta la banda a un punto fijo delante de ti y agárrala con ambas manos.', 'Colócate de rodillas con el cuerpo erguido y las caderas alineadas.', 'Inclina el tronco ligeramente hacia atrás y lleva las caderas adelante flexionando las rodillas.', 'Vuelve despacio a la posición inicial manteniendo el control.', 'Evita dejar caer el peso de golpe o perder la alineación de rodillas y pies.']::text[], 'principiante', 'Aísla el cuádriceps con una flexión de rodilla controlada que también reta el equilibrio y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9988'),
('31d5a352-06ab-5ca8-aa00-5037a65083d5', 'Leñador de rodillas con banda', ARRAY['Fija la banda a un punto alto y sujétala con ambas manos.', 'Colócate de rodillas con el tronco erguido y los brazos extendidos hacia arriba.', 'Tira de la banda en diagonal hacia la cadera contraria girando el tronco.', 'Vuelve despacio a la posición inicial controlando la banda.', 'Evita tirar solo con los brazos: el giro debe salir del tronco y el abdomen.']::text[], 'principiante', 'Trabaja abdomen y oblicuos con un giro diagonal que también implica hombros y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4776'),
('4b71d3d4-0370-5309-944b-3ea41633f0fc', 'Golpe lateral con banda', ARRAY['Fija la banda a un punto lateral a la altura del pecho y sujétala con una mano.', 'Colócate de pie de lado a la banda con los pies a la anchura de los hombros.', 'Empuja la mano hacia delante y en diagonal contra la resistencia.', 'Vuelve despacio a la posición inicial sin dejar que la banda te arrastre.', 'Evita girar el tronco o encoger el hombro durante el empuje.']::text[], 'principiante', 'Trabaja pectorales y hombros con un empuje lateral que también activa tríceps y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10594'),
('4592178d-15e1-56a0-8de8-65be42a1911d', 'Paso lateral y sentadilla con banda', ARRAY['Coloca la banda por encima de las rodillas o en los tobillos.', 'Da un paso lateral manteniendo la tensión de la banda y los pies paralelos.', 'Baja en sentadilla con el pecho alto y las rodillas alineadas con los pies.', 'Empuja para subir y repite el paso hacia el otro lado.', 'Evita juntar las rodillas hacia dentro o perder la tensión de la banda.']::text[], 'principiante', 'Combina desplazamiento lateral y sentadilla para activar glúteos, cuádriceps y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7206'),
('765bded4-8281-54d9-90e9-7e843a06d984', 'Curl de pierna con banda', ARRAY['Fija la banda a un punto bajo y engancha el otro extremo en el tobillo.', 'Túmbate boca abajo con las piernas extendidas y el abdomen firme.', 'Flexiona la rodilla llevando el talón hacia el glúteo contra la resistencia.', 'Baja despacio hasta extender la pierna sin perder la tensión.', 'Evita arquear la lumbar o levantar la cadera del suelo.']::text[], 'principiante', 'Fortalece los isquios con una flexión de rodilla que también activa glúteos y gemelos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4036'),
('b78434ab-4729-5188-8d7b-4e07b4e90fe2', 'Extensión de piernas con banda elástica', ARRAY['Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti.', 'Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'principiante', 'Fortalece el cuádriceps en aislamiento y ayuda a estabilizar la rodilla en movimientos cotidianos y deportivos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3007'),
('60307be9-b2ef-573e-a230-66594aa30f77', 'Patada hacia atrás con banda elástica', ARRAY['Coloca la banda en el tobillo y sujétala a un punto fijo bajo, con el torso erguido.', 'Lleva la pierna hacia atrás sin arquear la zona lumbar, apretando el glúteo.', 'Vuelve despacio controlando la banda y sin dejar que tire de ti.', 'Evita balancear el tronco o compensar con la espalda baja.']::text[], 'principiante', 'Trabaja el glúteo mayor y los isquios para mejorar la extensión de cadera y la estabilidad de la pelvis.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7281'),
('c8af165c-df3f-5fea-b8be-070fa48ecb82', 'Elevación de pierna con banda elástica', ARRAY['Túmbate de lado con la banda en los tobillos y el cuerpo alineado.', 'Eleva la pierna superior sin rotar la pelvis ni el tronco.', 'Baja con control hasta juntar los tobillos, manteniendo la tensión.', 'No dejes caer la cadera ni gires el pie hacia arriba.']::text[], 'principiante', 'Activa el glúteo medio y el mayor para ganar estabilidad lateral de cadera y prevenir molestias lumbares.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2419'),
('c3a07be6-9302-5859-8d11-84943ffc9af5', 'Salto de longitud con banda elástica', ARRAY['Coloca la banda en la cintura y sujétala por detrás a un punto fijo.', 'Flexiona rodillas y caderas y salta hacia delante con los brazos.', 'Aterriza con las rodillas alineadas y amortigua el impacto.', 'Evita caer con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'principiante', 'Mejora la potencia de piernas y la explosividad del salto, útil para deportes que exigen impulso y aterrizaje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3862'),
('8828446e-4fc7-5cc1-a1c7-31d0e31a62f5', 'Zancada con banda elástica', ARRAY['Pisa la banda con el pie delantero y sujeta los extremos a la altura de los hombros.', 'Da un paso atrás y baja la rodilla trasera hacia el suelo.', 'Empuja con el pie delantero para volver a la posición inicial.', 'Mantén el tronco erguido y evita que la rodilla delantera pase muy por delante del pie.']::text[], 'principiante', 'Refuerza cuádriceps y glúteos en patrón de zancada, mejorando el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2424'),
('1281b56e-0016-5f2b-948b-7c413065d103', 'Abducción acostado con banda elástica', ARRAY['Túmbate de lado con la banda en los tobillos y las piernas estiradas.', 'Separa la pierna superior manteniendo la pelvis estable.', 'Baja lentamente hasta juntar los tobillos sin perder la tensión.', 'Evita rotar el tronco hacia atrás para ganar rango.']::text[], 'principiante', 'Fortalece los abductores de cadera para estabilizar la pelvis y mejorar el control en carrera y sentadillas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10899'),
('2db58f83-9991-525d-9bae-c87b429a25ab', 'Abducción de cadera con rodilla flexionada acostado con banda elástica', ARRAY['Túmbate de lado con las rodillas flexionadas y la banda en los muslos.', 'Eleva la rodilla superior sin mover la pelvis ni el tronco.', 'Baja despacio manteniendo la banda en tensión constante.', 'No arquees la espalda ni gires el cuerpo para abrir más.']::text[], 'principiante', 'Trabaja abductores y glúteo con la rodilla doblada, útil para estabilizar la cadera y aliviar tensión lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7199'),
('1bb0df40-03aa-5fd5-b3e8-2fa25a784cb0', 'Press de pecho acostado en el suelo con banda elástica', ARRAY['Pasa la banda por la espalda y sujeta los extremos con las manos a la altura del pecho.', 'Empuja los brazos hacia arriba hasta estirarlos sin bloquear del todo.', 'Baja despacio hasta que los codos rocen el suelo.', 'Evita arquear la zona lumbar o abrir los codos en exceso.']::text[], 'principiante', 'Fortalece pectorales, hombros y tríceps en un press horizontal que también exige control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11285'),
('a614b4cd-68a0-5e11-bffb-b2d9978c6e3d', 'Abducción con hiperextensión acostado con banda elástica', ARRAY['Túmbate boca abajo con la banda en los tobillos y las piernas estiradas.', 'Eleva una pierna hacia arriba y hacia fuera sin forzar la lumbar.', 'Baja con control manteniendo el abdomen activo.', 'Evita arquear demasiado la espalda o levantar el tronco.']::text[], 'principiante', 'Combina abducción de cadera y extensión lumbar para reforzar glúteos y espalda baja de forma controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7211'),
('0e2962bc-055f-552c-b2f7-123eb4efcf44', 'Prensa de piernas acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda en los pies y sujétala con las manos.', 'Empuja los pies hacia delante hasta estirar las piernas sin bloquear.', 'Flexiona las rodillas despacio para volver al inicio.', 'No despeques la zona lumbar del suelo ni dejes que la banda tire sin control.']::text[], 'principiante', 'Refuerza cuádriceps, glúteos e isquios con un empuje horizontal que imita el gesto de la prensa.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8142'),
('6f4dec99-0082-509d-884a-d3888f1183be', 'Elevación de piernas acostado con banda elástica', ARRAY['Túmbate boca arriba con la banda en los tobillos y las piernas estiradas.', 'Eleva una pierna hacia el lado sin despegar la pelvis del suelo.', 'Baja despacio manteniendo la tensión de la banda.', 'Evita arquear la lumbar o girar el tronco para subir más.']::text[], 'principiante', 'Activa abductores, glúteos y core para mejorar la estabilidad de cadera y el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2157'),
('9af3f5c8-8281-51c3-8be2-09222ca42eac', 'Remo inclinado a un brazo con banda elástica', ARRAY['Sujeta la banda con una mano y ancla el otro extremo a un punto fijo bajo.', 'Inclina el tronco con la espalda recta y apoya la mano libre en la rodilla.', 'Tira del codo hacia atrás pegándolo al cuerpo y aprieta la escápula.', 'Evita redondear la espalda o girar el tronco al tirar.']::text[], 'principiante', 'Fortalece dorsales y espalda alta, corrigiendo desequilibrios y mejorando la postura en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4569'),
('1b371efe-f801-5fbd-8f52-8b1173f7a864', 'Puente de glúteos a una pierna con banda elástica', ARRAY['Túmbate boca arriba con la banda en los muslos y una pierna apoyada.', 'Eleva la cadera apretando el glúteo hasta alinear tronco y muslo.', 'Baja despacio sin dejar caer la pelvis de golpe.', 'Evita arquear la lumbar o empujar con la pierna contraria.']::text[], 'principiante', 'Refuerza glúteos e isquios de forma unilateral, mejorando la estabilidad de cadera y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2159'),
('7002aaa1-d5d8-5ded-b7bb-2971abb7798b', 'Puente de glúteos a una pierna con pierna recta y banda elástica', ARRAY['Túmbate boca arriba con la banda en los muslos y una pierna estirada en el aire.', 'Eleva la cadera con la pierna de apoyo hasta alinear el cuerpo.', 'Baja con control manteniendo la pierna libre recta.', 'No dejes que la cadera se caiga hacia un lado ni arquees la lumbar.']::text[], 'principiante', 'Trabaja glúteo e isquios con la pierna libre estirada, exigiendo más control y estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2158'),
('37c7da28-1bfc-5146-b7ba-1f083ed2e02a', 'Patada trasera a una pierna con banda elástica', ARRAY['Coloca la banda en el tobillo y ancla el otro extremo a un punto fijo bajo.', 'Inclina ligeramente el tronco y lleva la pierna hacia atrás apretando el glúteo.', 'Vuelve despacio sin dejar que la banda tire de la pierna.', 'Evita arquear la espalda o balancear el cuerpo para ganar impulso.']::text[], 'principiante', 'Aísla el glúteo mayor y los isquios para mejorar la extensión de cadera y la estabilidad al caminar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2161'),
('faaa45af-5f59-5d0a-9eb1-a571eb06482d', 'Patada atrás a una pierna con banda elástica', ARRAY['Coloca la banda en un punto bajo y engánchala al tobillo, con el torso inclinado y las manos apoyadas.', 'Mantén el core activo y la espalda neutra mientras llevas la pierna hacia atrás.', 'Empuja con el glúteo hasta extender la cadera sin arquear la zona lumbar.', 'Controla el retorno a la posición inicial en dos segundos y evita balancear el tronco.']::text[], 'principiante', 'Fortalece glúteos y femorales trabajando la extensión de cadera, útil para mejorar la estabilidad y la potencia en la carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3903'),
('81d361d6-d1de-57d6-93dd-9324f439a0ea', 'Golpe sobre la cabeza con banda elástica', ARRAY['Sujeta la banda por detrás de la espalda con ambas manos a la altura de los hombros.', 'Extiende los brazos hacia delante y arriba en diagonal, como si lanzaras un golpe.', 'Mantén el abdomen firme y no arquees la espalda al empujar.', 'Vuelve despacio a la posición inicial controlando la tensión de la banda.']::text[], 'principiante', 'Trabaja pectorales y hombros con un empuje diagonal que también activa el core y los dorsales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10553'),
('4ac5abb8-7227-5170-b7c2-4d7e470cb6e1', 'Press de hombros sobre la cabeza con banda elástica', ARRAY['Pisa la banda con los pies a la anchura de las caderas y sujeta los extremos a la altura de los hombros.', 'Empuja las manos hacia arriba hasta extender los brazos sin bloquear del todo los codos.', 'Mantén el core activo y evita arquear la zona lumbar durante el empuje.', 'Baja las manos de forma controlada hasta la altura de los hombros y repite.']::text[], 'principiante', 'Refuerza deltoides y tríceps con un empuje vertical que mejora la fuerza y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8364'),
('21f48b07-6346-5adb-9f8b-f91009b9e0f0', 'Sentadilla sobre la cabeza con banda elástica', ARRAY['Pisa la banda y sujeta los extremos con los brazos extendidos por encima de la cabeza.', 'Baja en sentadilla llevando las caderas atrás y manteniendo el pecho alto.', 'Empuja el suelo con los talones para subir mientras mantienes los brazos firmes arriba.', 'Evita que las rodillas se metan hacia dentro y no pierdas la curvatura neutra de la espalda.']::text[], 'principiante', 'Combina fuerza de cuádriceps y glúteos con estabilidad de hombros y core en un patrón global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4186'),
('e7df865e-9f34-5867-bb78-6959761eaee8', 'Pass through con banda elástica', ARRAY['Sujeta la banda con las manos separadas al ancho de los hombros frente al pecho.', 'Lleva los brazos extendidos por encima de la cabeza y pasa la banda por detrás.', 'Continúa el recorrido hasta la espalda baja y vuelve por delante sin doblar los codos.', 'Hazlo lento y sin dolor; si notas tirantez, reduce la tensión de la banda.']::text[], 'principiante', 'Moviliza hombros y manguito rotador, preparando la articulación para empujes y mejorando la amplitud.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8365'),
('f5c8216d-072f-5781-9aaa-661beb1d1b4e', 'Jack en plancha con banda elástica', ARRAY['Coloca la banda alrededor de los tobillos y adopta la posición de plancha sobre antebrazos.', 'Abre y cierra las piernas con un salto corto manteniendo la cadera estable.', 'Aprieta el abdomen y evita que la cadera suba o baje durante el movimiento.', 'Respira de forma constante y reduce el ritmo si pierdes la alineación.']::text[], 'principiante', 'Activa el abdomen y los oblicuos con un movimiento dinámico que también exige estabilidad de hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7210'),
('c6aa3c28-d5c4-592c-9a7d-13db32793310', 'Marcha en plancha con banda elástica', ARRAY['Coloca la banda alrededor de los pies y adopta la posición de plancha alta con las manos bajo los hombros.', 'Levanta una rodilla hacia el pecho sin mover la cadera ni el tronco.', 'Vuelve a apoyar el pie y alterna con la otra pierna a ritmo controlado.', 'Mantén el abdomen firme y evita que la zona lumbar se hunda.']::text[], 'principiante', 'Trabaja core y flexores de cadera con una plancha dinámica que mejora el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2162'),
('179bd556-201b-58f4-a183-b1d384aef44e', 'Apertura con banda elástica a 45 grados', ARRAY['Sujeta la banda frente al pecho con las manos separadas y los brazos ligeramente flexionados.', 'Abre los brazos en diagonal hacia arriba a 45 grados hasta estirar la banda.', 'Junta las escápulas sin encoger los hombros hacia las orejas.', 'Vuelve despacio al centro manteniendo la tensión y repite.']::text[], 'principiante', 'Refuerza deltoides posteriores y espalda alta, mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5317'),
('c74552c7-42cc-5422-8b8a-d1021d498671', 'Golpe con banda elástica', ARRAY['Ancla la banda a la altura del pecho y sujeta los extremos con las manos a los lados.', 'Extiende un brazo hacia delante como un golpe directo sin bloquear el codo.', 'Rota el tronco ligeramente y mantén el abdomen activo durante el empuje.', 'Vuelve controlando la banda y alterna los brazos sin perder la postura.']::text[], 'principiante', 'Trabaja pectorales y tríceps con un empuje horizontal que también activa el core y los hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3798'),
('0f13c9c8-ddc0-5ec6-91d3-2893afd26853', 'Apertura posterior con banda elástica', ARRAY['Sujeta la banda frente al cuerpo con los brazos extendidos y las palmas hacia dentro.', 'Abre los brazos hacia los lados hasta la altura de los hombros, juntando las escápulas.', 'Evita encoger los hombros y mantén los codos ligeramente flexionados.', 'Regresa despacio al centro sin dejar que la banda pierda tensión.']::text[], 'principiante', 'Fortalece deltoides posteriores y romboides, corrigiendo la postura y equilibrando el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3321'),
('23a6d6b6-bfb9-53af-b20d-6618ccdd30ee', 'Remo renegado con banda elástica', ARRAY['Coloca la banda bajo los pies y adopta la posición de plancha alta sujetando los extremos.', 'Tira de un extremo hacia la cadera manteniendo la cadera paralela al suelo.', 'Aprieta la escápula y evita rotar el tronco durante la tracción.', 'Baja el brazo con control y alterna lados sin perder la alineación.']::text[], 'principiante', 'Exige core y espalda en una plancha con remo que mejora la estabilidad y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8224'),
('b89eb366-ab07-5653-bf9f-8e7d5bc4199b', 'Hiperextensión inversa con banda elástica y balón en banco', ARRAY['Coloca el balón sobre el banco y túmbate boca abajo con la cadera en el borde.', 'Engancha la banda a un punto bajo y sujétala con los pies.', 'Eleva las piernas extendiendo la cadera sin arquear la espalda.', 'Baja las piernas despacio y mantén el abdomen activo durante todo el recorrido.']::text[], 'principiante', 'Fortalece glúteos y femorales con una extensión de cadera que también cuida la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6738'),
('a12b12ed-9f00-5a9e-b684-2313af2fd5c7', 'Hiperextensión inversa con banda elástica', ARRAY['Túmbate boca abajo con la cadera en el borde de un banco y sujétate con las manos.', 'Engancha la banda a un punto bajo y pásala por los tobillos.', 'Eleva las piernas juntas extendiendo la cadera sin levantar el tronco.', 'Baja con control y evita balancear las piernas o arquear la lumbar.']::text[], 'principiante', 'Activa glúteos y femorales con una extensión de cadera que refuerza la cadena posterior y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2163'),
('d163a93d-f18b-5f5a-960a-c7fe4b17f6ed', 'Abducción sentado con rodilla flexionada y banda elástica', ARRAY['Siéntate en una silla con la banda alrededor de los muslos por encima de las rodillas.', 'Separa las rodillas contra la resistencia manteniendo los pies apoyados.', 'Aprieta los glúteos al final del recorrido y evita inclinar el tronco.', 'Vuelve despacio a la posición inicial sin dejar que la banda se destense.']::text[], 'principiante', 'Trabaja abductores y glúteos medios, mejorando la estabilidad de la cadera y la alineación de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7200'),
('66f2abad-854a-5c1e-a52c-18fd223a3d1e', 'Abducción sentado con pies en el aire y banda elástica', ARRAY['Siéntate en una silla con la banda alrededor de los muslos y los pies separados del suelo.', 'Separa las rodillas contra la banda manteniendo el tronco erguido.', 'Aprieta el abdomen para no balancearte mientras abres las piernas.', 'Cierra las rodillas con control y evita dejar caer los pies.']::text[], 'principiante', 'Refuerza abductores y glúteos medios con mayor demanda de core al mantener los pies elevados.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11050'),
('35de8030-6ed3-5f25-bcce-261862b29d37', 'Curl de bíceps sentado con banda elástica', ARRAY['Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.', 'Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo.', 'Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente la banda elástica de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja los bíceps y los antebrazos, ideal para ganar fuerza en el tren superior con poco material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3123'),
('bfc230d1-5fcd-55e6-8a93-26b32ca4bc35', 'Estiramiento de gemelos sentado con banda elástica', ARRAY['Siéntate con la pierna estirada y pasa la banda por la planta del pie.', 'Sujeta los extremos y tira suavemente hacia ti hasta notar tensión en la pantorrilla.', 'Mantén la posición entre 20 y 30 segundos sin rebotar y respirando con calma.', 'Evita tirar con fuerza brusca: la sensación debe ser de estiramiento, no de dolor.']::text[], 'principiante', 'Estira gemelos y sóleo para mejorar la movilidad del tobillo y aliviar la tensión tras caminar o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5480'),
('42186e33-b824-5170-9c9c-1243e57c23e6', 'Press de pecho sentado con banda elástica', ARRAY['Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.', 'Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados.', 'Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho.', 'Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa pectorales, hombros y tríceps para empujar con fuerza y estabilidad en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3124'),
('905b9006-1006-5007-8f1d-424f10252901', 'Eversión de pie sentado con banda elástica', ARRAY['Siéntate y ancla la banda a un punto fijo a la altura del pie.', 'Coloca el lazo alrededor del pie y gira la planta hacia fuera contra la resistencia.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita compensar con la rodilla o la cadera: mueve solo el tobillo.']::text[], 'principiante', 'Refuerza la musculatura lateral del tobillo y la pantorrilla para readaptar esguinces y mejorar la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8611'),
('ebf515fa-ee34-5b49-abe5-b1aef796c9d7', 'Face pull sentado con banda elástica', ARRAY['Ancla la banda a la altura de la cara y siéntate con la espalda recta.', 'Sujeta los extremos con las palmas hacia abajo y los brazos estirados.', 'Tira de la banda hacia la cara separando las manos y juntando las escápulas.', 'Aguanta un segundo atrás y vuelve despacio sin perder la postura.', 'Evita encoger los hombros o arquear la espalda durante el tirón.']::text[], 'principiante', 'Fortalece deltoides posteriores, romboides y manguito rotador para mejorar la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4445'),
('517777bc-3153-5a4c-a44b-d877cf5eb6f1', 'Inversión de pie sentado con banda elástica', ARRAY['Siéntate y ancla la banda a un punto fijo a la altura del pie.', 'Coloca el lazo alrededor del pie y gira la planta hacia dentro contra la resistencia.', 'Vuelve despacio a la posición neutra manteniendo el control.', 'Evita mover la rodilla o la cadera: el giro debe salir solo del tobillo.']::text[], 'principiante', 'Trabaja la musculatura interna del tobillo y la pantorrilla para recuperar estabilidad tras una lesión.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8612'),
('83c16a43-f7a8-527c-9d20-0bf8e0cbfa19', 'Elevación de rodilla sentado con banda elástica', ARRAY['Siéntate en una silla y ancla la banda por debajo del asiento.', 'Coloca el lazo en el empeine y apoya bien la espalda en el respaldo.', 'Sube la rodilla hacia el pecho contra la resistencia sin mover el tronco.', 'Baja la pierna despacio y controla el retorno.', 'Evita arquear la espalda o tirar con el torso para subir la pierna.']::text[], 'principiante', 'Activa el abdomen y los flexores de cadera para ganar control del core desde una posición estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10753'),
('32a6902f-26a6-583b-baac-0974648756e1', 'Curl femoral sentado con banda elástica', ARRAY['Siéntate y ancla la banda a un punto fijo delante de ti, a ras de suelo.', 'Coloca el lazo en el tobillo y estira la pierna ligeramente hacia delante.', 'Flexiona la rodilla llevando el talón hacia el asiento contra la resistencia.', 'Vuelve despacio a la posición inicial sin soltar la tensión.', 'Evita mover el muslo o la cadera: el movimiento debe salir de la rodilla.']::text[], 'principiante', 'Fortalece los isquiotibiales y glúteos para proteger la rodilla y equilibrar la fuerza de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4903'),
('58036615-6c38-5f8a-9687-0b9607e5bff5', 'Press de hombros sentado con banda elástica', ARRAY['Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.', 'Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros.', 'Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja deltoides, tríceps y espalda alta para empujar por encima de la cabeza con fuerza y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3122'),
('1aa594bc-8dfe-5bb2-ab7f-4f444789c69e', 'Curl de pierna a una pierna sentado con banda elástica', ARRAY['Siéntate y ancla la banda a un punto fijo delante de ti, a ras de suelo.', 'Coloca el lazo en un tobillo y deja la otra pierna relajada.', 'Flexiona la rodilla llevando el talón hacia el asiento contra la resistencia.', 'Vuelve despacio y completa todas las repeticiones antes de cambiar de pierna.', 'Evita girar la cadera o compensar con la espalda al tirar.']::text[], 'principiante', 'Aísla los isquiotibiales de cada pierna para corregir desequilibrios y reforzar la parte posterior del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3508'),
('c5830117-8ad9-59ef-94f9-109b19af5496', 'Estiramiento de isquiotibiales sentado a una pierna con banda elástica', ARRAY['Siéntate con una pierna estirada y la otra flexionada.', 'Pasa la banda por la planta del pie estirado y sujeta los extremos.', 'Tira suavemente hacia ti hasta notar tensión detrás del muslo.', 'Mantén entre 20 y 30 segundos respirando con calma y sin rebotar.', 'Evita redondear la espalda en exceso: mantén el pecho abierto.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla para mejorar la flexibilidad y aliviar la rigidez.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10744'),
('45faa371-d28f-5f6b-a899-9ac0036f5820', 'Flexión de rodilla abrazada sentado a una pierna con banda elástica', ARRAY['Siéntate y ancla la banda a un punto fijo delante de ti, a ras de suelo.', 'Coloca el lazo en un tobillo y apoya la espalda en el respaldo.', 'Flexiona la rodilla llevando el talón hacia ti mientras abrazas la pierna con las manos.', 'Vuelve despacio a la posición inicial manteniendo la tensión.', 'Evita tirar con los brazos: el trabajo debe hacerlo la pierna.']::text[], 'principiante', 'Activa isquiotibiales y glúteos con un gesto de flexión controlado que mejora la fuerza y el control de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10591'),
('d49f821c-4349-58c9-98b6-d0371d2a5b9c', 'Extensión de rodilla sentado a una pierna con banda elástica', ARRAY['Siéntate y ancla la banda detrás de ti, a la altura del asiento.', 'Coloca el lazo en el tobillo y apoya la espalda en el respaldo.', 'Estira la rodilla contra la resistencia hasta que la pierna quede recta.', 'Aguanta un segundo arriba y baja despacio controlando el movimiento.', 'Evita bloquear la rodilla con un golpe seco o mover el muslo.']::text[], 'principiante', 'Refuerza el cuádriceps de forma aislada para estabilizar la rodilla y mejorar la extensión completa.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10746'),
('8b58bb51-7c6f-56d0-b0ea-4f1adadb20f4', 'Sostén de extensión de rodilla sentado a una pierna con banda elástica', ARRAY['Siéntate y ancla la banda detrás de ti, a la altura del asiento.', 'Coloca el lazo en el tobillo y estira la rodilla contra la resistencia.', 'Mantén la pierna recta y en tensión durante 15 a 30 segundos.', 'Respira con normalidad y baja despacio al terminar.', 'Evita aguantar la respiración o bloquear la rodilla con dolor.']::text[], 'principiante', 'Mantiene el cuádriceps en tensión isométrica para ganar resistencia y estabilidad en la rodilla.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10921'),
('68e875e8-73b1-5b52-8d46-97b6e746220a', 'Deslizamiento de serrato en la pared con banda elástica', ARRAY['Sujeta la banda con las manos y apoya los antebrazos en la pared.', 'Coloca los codos a la altura de los hombros y la espalda recta.', 'Desliza los antebrazos hacia arriba empujando la pared y separando las escápulas.', 'Vuelve despacio a la posición inicial sin perder la tensión.', 'Evita encoger los hombros o arquear la zona lumbar durante el deslizamiento.']::text[], 'principiante', 'Activa el serrato anterior y la escápula para mejorar la estabilidad del hombro y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5024'),
('5f277228-53f9-51d2-9387-40290ecdea2b', 'Deslizamiento de serrato en la pared con banda', ARRAY['Coloca la banda alrededor de las muñecas y apoya los antebrazos en la pared a la altura de los hombros.', 'Desliza los brazos hacia arriba manteniendo la banda tensa y los omóplatos pegados a la pared.', 'Baja despacio controlando el movimiento y sin perder la tensión de la banda.', 'Evita arquear la zona lumbar o encoger los hombros hacia las orejas.']::text[], 'principiante', 'Activa el serrato anterior y estabiliza la escápula, mejorando la movilidad y el control del hombro en empujes.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5026'),
('f46aaab1-32a2-518e-a8a4-f0e36f0d033c', 'Aducción de hombro con banda', ARRAY['Fija la banda a un punto alto y sujeta el extremo con el brazo estirado hacia fuera.', 'Lleva el brazo hacia el cuerpo cruzando por delante, manteniendo el codo casi recto.', 'Controla la vuelta a la posición inicial sin dejar que la banda tire de golpe.', 'Mantén el tronco firme y evita girar el torso para no compensar con la espalda.']::text[], 'principiante', 'Trabaja el dorsal ancho y los rotadores internos, útil para fortalecer la espalda y estabilizar el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6437'),
('28b56aba-f26f-5673-ac22-d652cd6d6e7e', 'Carrera de ida y vuelta con banda', ARRAY['Coloca la banda por encima de las rodillas o en los tobillos y adopta una ligera flexión de rodillas.', 'Da pasos laterales rápidos manteniendo la banda tensa y los pies paralelos.', 'Desplázate de ida y vuelta sin juntar del todo los pies en ningún momento.', 'Evita inclinar el tronco hacia los lados y mantén el abdomen activo.']::text[], 'principiante', 'Mejora la fuerza de abductores y glúteos con desplazamientos laterales, útil para la estabilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4241'),
('ba72bc38-51d0-5b1c-9aad-335c5d8ea3bd', 'Zancada lateral con banda', ARRAY['Coloca la banda por encima de las rodillas y separa los pies a la anchura de las caderas.', 'Da un paso amplio hacia un lado flexionando la rodilla y llevando la cadera atrás.', 'Empuja con la pierna de apoyo para volver al centro manteniendo la banda tensa.', 'Evita que la rodilla pase por delante de la punta del pie y no dejes caer el tronco.']::text[], 'principiante', 'Fortalece cuádriceps, glúteos y aductores, mejorando la estabilidad y la fuerza en movimientos laterales.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7202'),
('4e08e50b-ab5f-5024-b11c-24c61966e5c5', 'Abducción de cadera tumbado de lado con banda', ARRAY['Túmbate de lado con la banda por encima de las rodillas y las piernas ligeramente flexionadas.', 'Eleva la pierna superior sin rotar la cadera ni mover el tronco.', 'Baja despacio controlando la tensión de la banda hasta casi tocar la otra pierna.', 'Evita arquear la espalda o balancear la pierna para ganar impulso.']::text[], 'principiante', 'Aísla el glúteo medio y los abductores, clave para prevenir lesiones y estabilizar la cadera al caminar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11644'),
('789245a5-fbaf-572d-a70f-7298710267e4', 'Plancha lateral con banda', ARRAY['Coloca la banda por encima de las rodillas y apóyate de lado sobre el antebrazo.', 'Eleva la cadera hasta formar una línea recta entre hombros, cadera y pies.', 'Mantén la posición apretando la banda y respirando de forma constante.', 'Evita que la cadera caiga o que el hombro se hunda hacia el suelo.']::text[], 'principiante', 'Refuerza el core y los oblicuos con isometría, mejorando la estabilidad lateral del tronco y la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2164'),
('de91b19a-a18a-5603-b482-448332d77d5a', 'Elevación de glúteo en plancha lateral con banda', ARRAY['Coloca la banda por encima de las rodillas y adopta la posición de plancha lateral sobre el antebrazo.', 'Eleva la cadera y, desde ahí, abre la rodilla superior contra la banda.', 'Junta la rodilla despacio sin dejar caer la cadera en ningún momento.', 'Evita rotar el tronco hacia atrás o perder la línea recta del cuerpo.']::text[], 'principiante', 'Combina isometría lateral con abducción para trabajar glúteo medio, oblicuos y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6737'),
('d51ae75f-7d1e-5348-953e-cd17e27780f9', 'Sentadilla con paso lateral y banda', ARRAY['Coloca la banda por encima de las rodillas y baja en sentadilla hasta media profundidad.', 'Manteniendo la sentadilla, da pasos laterales cortos con la banda tensa.', 'Conserva las rodillas alineadas con los pies y el pecho erguido.', 'Evita juntar las rodillas hacia dentro o enderezar las piernas entre pasos.']::text[], 'principiante', 'Trabaja abductores, glúteos y cuádriceps en un patrón funcional que mejora la estabilidad de rodilla y cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6744'),
('59272238-2b4a-50d5-a855-0531337ede06', 'Press de hombro a un brazo con banda', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano del mismo lado a la altura del hombro.', 'Empuja el brazo hacia arriba hasta estirarlo del todo sin bloquear la respiración.', 'Baja despacio controlando la banda hasta la altura del hombro.', 'Evita arquear la espalda o inclinarte hacia el lado contrario al empujar.']::text[], 'principiante', 'Fortalece el deltoides y el tríceps con un patrón unilateral que exige control del core y estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5204'),
('4059c8fe-d14a-5be6-b1b3-9c815e974881', 'Dorsiflexión de tobillo sentado con banda', ARRAY['Siéntate en el suelo con la pierna estirada y pasa la banda por la punta del pie.', 'Sujeta la banda con las manos y lleva la punta del pie hacia ti contra la resistencia.', 'Mantén un segundo arriba y vuelve despacio a la posición neutra.', 'Evita mover la rodilla o compensar tirando con la cadera.']::text[], 'principiante', 'Fortalece la tibial anterior y mejora la movilidad del tobillo, útil en readaptación de esguinces y tendinopatías.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10003'),
('049bc129-73dc-506f-aabb-eb2230116fb1', 'Press de tibial sentado con banda', ARRAY['Siéntate en el suelo con la pierna estirada y ancla la banda en un punto fijo frente a ti.', 'Pasa la banda por el empeine y lleva la punta del pie hacia delante contra la resistencia.', 'Vuelve despacio a la posición inicial sin dejar que la banda tire de golpe.', 'Evita levantar el talón o mover la rodilla durante el recorrido.']::text[], 'principiante', 'Refuerza el tibial anterior y la musculatura de la espinilla, mejorando el control del tobillo y la pisada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10366'),
('1aed7cba-3edd-5b36-a1b7-364a0af9550a', 'Sentadilla en multipower con banda', ARRAY['Coloca la banda en los ganchos de la máquina y pásala por encima de las rodillas.', 'Apoya la barra en la espalda alta y separa los pies a la anchura de los hombros.', 'Baja controlando hasta que los muslos queden paralelos al suelo.', 'Empuja con los talones para subir evitando que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquios con trayectoria guiada, añadiendo tensión de banda para más control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3856'),
('652020ce-8484-5414-9f37-785f55f256e2', 'Paso rápido con banda', ARRAY['Coloca la banda en los tobillos y adopta una postura atlética con rodillas ligeramente flexionadas.', 'Da pasos cortos y rápidos hacia delante manteniendo la banda tensa.', 'Acompaña el movimiento con los brazos y mantén el pecho erguido.', 'Evita arrastrar los pies o perder la tensión de la banda entre pasos.']::text[], 'principiante', 'Mejora la potencia de glúteos y la coordinación con pasos rápidos, útil como calentamiento o trabajo cardiovascular.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '8874'),
('b9d66a91-6646-5b9e-86a5-3ae51528e721', 'Arrastre de araña con banda', ARRAY['Coloca la banda alrededor de las muñecas y adopta posición de flexión con rodillas despegadas.', 'Avanza una mano y el pie contrario a la vez manteniendo la banda tensa.', 'Mantén la cadera baja y el abdomen activo durante todo el recorrido.', 'Evita elevar demasiado la cadera o cruzar las manos por delante.']::text[], 'principiante', 'Trabaja pectorales, core y hombros en un patrón de suelo que mejora la fuerza y la coordinación global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2943'),
('6a36853f-52e6-50c0-bedb-15df2ac3d002', 'Salto en sentadilla con banda', ARRAY['Coloca la banda por encima de las rodillas y adopta una sentadilla a media profundidad.', 'Salta hacia arriba con fuerza extendiendo caderas y rodillas.', 'Aterriza con las rodillas flexionadas y alineadas con los pies, amortiguando el impacto.', 'Evita caer con las piernas rígidas o juntar las rodillas hacia dentro.']::text[], 'principiante', 'Desarrolla potencia de piernas y explosividad con un gesto pliométrico que implica cuádriceps, glúteos y core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7205'),
('e9ae6faf-8b9d-5e4b-8d2c-439214b4133f', 'Sentadilla con banda elástica de calentamiento', ARRAY['Pisa la banda con los pies a la anchura de los hombros y sujeta los extremos a la altura de los hombros.', 'Baja en sentadilla llevando la cadera atrás mientras mantienes el pecho alto y la banda tensa.', 'Sube empujando con los talones y controla la respiración durante todo el recorrido.', 'Evita que las rodillas se metan hacia dentro y no pierdas la tensión de la banda.']::text[], 'principiante', 'Activa hombros, espalda alta y piernas antes de entrenar, mejorando la movilidad y la preparación neuromuscular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4028'),
('81001d4e-6e3e-5664-8873-88baae101c31', 'Rotación externa de hombro a 90 grados con banda', ARRAY['Fija la banda a la altura del codo y colócate de pie con el brazo a 90 grados y el codo pegado al cuerpo.', 'Rota el antebrazo hacia fuera manteniendo el codo fijo y sin mover el tronco.', 'Vuelve despacio a la posición inicial controlando la banda.', 'Evita encoger el hombro o girar el cuerpo para completar el movimiento.']::text[], 'principiante', 'Fortalece el manguito rotador y los deltoides posteriores, mejorando la estabilidad del hombro y previniendo lesiones.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8363'),
('5ae6e549-9434-522a-91f9-e37a894047b8', 'Estiramiento de talón de Aquiles con banda', ARRAY['Pasa la banda por la planta del pie y sujeta los extremos con las manos.', 'Lleva la punta del pie hacia ti manteniendo la rodilla estirada.', 'Mantén el estiramiento sin rebotes y respira de forma lenta y profunda.', 'Evita tirar con demasiada fuerza y no bloquees la respiración.']::text[], 'principiante', 'Estira el tendón de Aquiles y el sóleo, mejorando la flexibilidad del tobillo y reduciendo tensión en la pantorrilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2999'),
('0f73b2ce-6cd2-5db0-a121-2e12e2d9b6e4', 'Calentamiento de espalda alta con banda', ARRAY['Sujeta la banda con ambas manos frente al pecho y mantén los codos ligeramente flexionados.', 'Lleva los omóplatos hacia atrás juntándolos sin encoger los hombros.', 'Vuelve despacio a la posición inicial manteniendo la tensión.', 'Evita arquear la zona lumbar o tirar con los brazos en lugar de con la espalda.']::text[], 'principiante', 'Activa la espalda alta, romboides y manguito rotador, preparando la cintura escapular para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4027'),
('c5a8806c-985d-5168-a974-4d5e0f108d55', 'Abducción de cadera con rodilla flexionada y banda', ARRAY['Coloca la banda alrededor de los muslos y apoya el peso sobre una pierna con la rodilla ligeramente flexionada.', 'Separa la pierna libre hacia el lado manteniendo la rodilla doblada y el tronco estable.', 'Vuelve despacio sin dejar que la banda te arrastre.', 'Evita inclinar el tronco o perder el equilibrio durante el movimiento.']::text[], 'principiante', 'Trabaja los abductores y glúteos mejorando el equilibrio y la estabilidad de la cadera sobre una pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10820'),
('d019bf1a-5f99-5cba-ae50-086f70e8d484', 'Patada de glúteo con banda en equilibrio', ARRAY['Fija la banda al tobillo y apóyate sobre una pierna con el tronco erguido.', 'Lleva la pierna hacia atrás extendiendo la cadera sin arquear la lumbar.', 'Aprieta el glúteo arriba y vuelve despacio a la posición inicial.', 'Evita balancear el tronco o usar impulso para completar la patada.']::text[], 'principiante', 'Activa el glúteo mayor y los isquiotibiales, mejorando la extensión de cadera y la estabilidad sobre una pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6798'),
('d3f297ba-a9e0-5014-9abc-d0a38adc2114', 'Abducción de cadera con banda en equilibrio', ARRAY['Coloca la banda por encima de los tobillos y apoya el peso sobre una pierna.', 'Eleva la pierna libre hacia el lado manteniendo el tronco recto y el pie alineado.', 'Baja despacio controlando la tensión de la banda.', 'Evita inclinarte hacia el lado contrario o dejar caer la cadera.']::text[], 'principiante', 'Refuerza abductores y glúteos mejorando la estabilidad de la cadera y el control postural sobre una pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8085'),
('63838d78-ac89-5d56-a874-9e1d0a8ff4e3', 'Calentamiento de hombros con banda hacia abajo', ARRAY['Sujeta la banda por encima de la cabeza con los brazos estirados.', 'Tira de la banda hacia abajo llevando los codos hacia los costados.', 'Vuelve despacio a la posición inicial manteniendo la tensión.', 'Evita encoger los hombros o arquear la espalda al tirar.']::text[], 'principiante', 'Moviliza hombros, dorsales y manguito rotador, preparando la articulación para empujes y tracciones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4025'),
('5a29fe07-48ab-53d3-acd6-78ee10f3e284', 'Rotación externa de hombro con banda', ARRAY['Fija la banda a la altura del codo y colócate de pie con el codo pegado al cuerpo a 90 grados.', 'Rota el antebrazo hacia fuera sin separar el codo del tronco.', 'Vuelve despacio controlando la banda en todo el recorrido.', 'Evita girar el cuerpo o encoger el hombro para completar la rotación.']::text[], 'principiante', 'Fortalece el manguito rotador y los deltoides posteriores, mejorando la estabilidad y la salud del hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '6441'),
('334e67e1-2f42-5e13-8a74-b480260ea703', 'Estiramiento de talón de Aquiles con banda hacia delante', ARRAY['Pasa la banda por la planta del pie y sujeta los extremos con las manos.', 'Lleva la punta del pie hacia ti manteniendo la rodilla estirada y el talón apoyado.', 'Mantén el estiramiento sin rebotes y respira de forma pausada.', 'Evita tirar con fuerza excesiva o bloquear la respiración.']::text[], 'principiante', 'Estira el tendón de Aquiles y la pantorrilla, mejorando la flexibilidad del tobillo y aliviando tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3000'),
('f91bd87d-2160-5afb-943d-8c5163d883a8', 'Calentamiento de hombros con banda hacia delante', ARRAY['Sujeta la banda frente al pecho con las manos a la anchura de los hombros.', 'Empuja la banda hacia delante extendiendo los brazos sin bloquear los codos.', 'Vuelve despacio a la posición inicial manteniendo la tensión.', 'Evita encoger los hombros o arquear la zona lumbar.']::text[], 'principiante', 'Activa deltoides, pectoral y espalda alta, preparando la cintura escapular para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4026'),
('0c63648b-fbb7-5495-a829-42c23d7f5306', 'Abducción de cadera con banda', ARRAY['Coloca la banda por encima de los tobillos y colócate de pie con el tronco erguido.', 'Separa una pierna hacia el lado manteniendo el pie alineado y la rodilla estirada.', 'Vuelve despacio controlando la banda sin dejar que te arrastre.', 'Evita inclinar el tronco o levantar la cadera durante el movimiento.']::text[], 'principiante', 'Trabaja abductores y glúteos, mejorando la estabilidad de la cadera y la fuerza en el plano lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3853'),
('9ed458bb-9d95-5b7f-b6bf-3136058f4e93', 'Calentamiento de hombros con banda por encima de la cabeza', ARRAY['Sujeta la banda frente al pecho con las manos a la anchura de los hombros.', 'Eleva los brazos por encima de la cabeza manteniendo la banda tensa.', 'Baja despacio a la posición inicial controlando el movimiento.', 'Evita arquear la espalda o encoger los hombros al elevar los brazos.']::text[], 'principiante', 'Moviliza hombros, espalda alta y tríceps, preparando la articulación para movimientos por encima de la cabeza.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4024'),
('c9853095-12f9-5350-8ee3-3afd9562396a', 'Elevación lateral de pierna con banda', ARRAY['Coloca la banda por encima de los tobillos y apóyate sobre una pierna.', 'Eleva la pierna libre hacia el lado manteniendo el tronco recto.', 'Baja despacio controlando la tensión de la banda.', 'Evita inclinarte o usar impulso para subir la pierna.']::text[], 'principiante', 'Fortalece abductores y glúteos, mejorando la estabilidad de la cadera y el control del equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11569'),
('096b451c-2076-52f2-a222-c20fffa7d5b4', 'Elevación lateral a un brazo con banda', ARRAY['Pisa la banda con un pie y sujeta el extremo con la mano contraria.', 'Eleva el brazo hacia el lado hasta la altura del hombro sin encogerlo.', 'Baja despacio controlando la banda en todo el recorrido.', 'Evita balancear el tronco o usar impulso para subir el brazo.']::text[], 'principiante', 'Aísla el deltoides lateral y el trapecio, mejorando la fuerza y la forma del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8362'),
('6f8e828a-e1e5-5e9a-a599-404c048bf026', 'Extensión lateral de hombro a un brazo con banda', ARRAY['Pisa la banda con el pie del lado contrario y sujeta el extremo con la mano libre.', 'Mantén el brazo recto y elévalo lateralmente hasta la altura del hombro.', 'Controla el descenso en dos o tres segundos sin dejar caer la banda.', 'Evita encoger el hombro o balancear el tronco para subir el brazo.']::text[], 'principiante', 'Trabaja el deltoides lateral y estabilizadores del hombro, mejorando la fuerza y el control en el plano lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6440'),
('64534e0d-8df5-5d0d-96ad-2fd740311a29', 'Flexión de hombro a un brazo con banda', ARRAY['Pisa la banda y agarra el extremo con la mano, palma hacia dentro.', 'Sube el brazo recto al frente hasta la altura del hombro.', 'Baja despacio manteniendo el codo ligeramente extendido.', 'No arquees la espalda ni uses impulso del tronco.']::text[], 'principiante', 'Fortalece el deltoides anterior y el control escapular, útil para elevar objetos y estabilizar el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6439'),
('3881a279-e5ca-5a96-b622-9d43a0796f67', 'Estiramiento de tríceps con banda', ARRAY['Sujeta la banda por encima de la cabeza con una mano y baja el codo detrás de la nuca.', 'Con la otra mano tira suavemente del extremo libre para aumentar la tensión.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'No fuerces el cuello ni arquees la zona lumbar.']::text[], 'principiante', 'Estira el tríceps y la parte posterior del hombro, aliviando tensión tras el trabajo de empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10741'),
('980c8210-03e9-5a28-a483-b84975d39c2b', 'Extensión de rodilla a una pierna con banda', ARRAY['Ancla la banda detrás de ti y colócala en el tobillo.', 'De pie, extiende la rodilla llevando el pie hacia delante sin mover el muslo.', 'Aprieta el cuádriceps arriba y baja controlando el retorno.', 'Evita bloquear la rodilla de golpe o balancear el cuerpo.']::text[], 'principiante', 'Refuerza el cuádriceps y la estabilidad de la rodilla, útil para prevenir molestias en la práctica deportiva.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10536'),
('fc300f96-fa46-5ace-9117-82d06e83260c', 'Sentadilla sumo con banda', ARRAY['Coloca la banda por encima de las rodillas y abre los pies más allá del ancho de hombros.', 'Baja la cadera llevando los glúteos atrás y empujando las rodillas hacia fuera.', 'Sube apretando glúteos y manteniendo el pecho alto.', 'No dejes que las rodillas se metan hacia dentro.']::text[], 'principiante', 'Activa glúteos y aductores con una sentadilla amplia, mejorando fuerza y movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8608'),
('df6114c9-81bf-59fe-9c94-fcbe24922846', 'Marcha en puente de glúteo con banda', ARRAY['Túmbate boca arriba con la banda sobre las rodillas y los pies apoyados.', 'Eleva la cadera formando una línea recta entre hombros y rodillas.', 'Levanta un pie unos centímetros sin mover la cadera y alterna.', 'Evita que la cadera caiga o rote durante el movimiento.']::text[], 'principiante', 'Trabaja glúteos y core en cadena posterior, mejorando la estabilidad de la cadera en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2166'),
('1807bcfd-3996-5ffa-a2d4-73e694cf06de', 'Caminata lateral sobre puntas con banda', ARRAY['Coloca la banda por encima de los tobillos y elévate sobre las puntas.', 'Da pasos laterales cortos manteniendo la tensión de la banda.', 'Mantén el tronco erguido y las rodillas ligeramente flexionadas.', 'No arrastres los pies ni pierdas el equilibrio.']::text[], 'principiante', 'Fortalece gemelos y tobillos mientras activa glúteos y cadera en desplazamiento lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10761'),
('e727ffb3-de93-529f-b68c-7a63be765919', 'Toque de pies con banda', ARRAY['Túmbate boca arriba con la banda sujeta con las manos y los pies elevados.', 'Eleva el tronco y lleva las manos hacia los pies sin tirar del cuello.', 'Baja controlando la espalda hasta el suelo.', 'Evita usar impulso o despegar la zona lumbar.']::text[], 'principiante', 'Trabaja el abdomen y los flexores de cadera con un gesto controlado que mejora la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2463'),
('2cdfb1eb-9d83-5388-b824-4ec2acbcffdc', 'Caminata sobre puntas con banda', ARRAY['Coloca la banda por encima de los tobillos y elévate sobre las puntas.', 'Camina hacia delante con pasos cortos manteniendo la tensión.', 'Mantén el tronco erguido y la mirada al frente.', 'No dejes caer los talones de golpe.']::text[], 'principiante', 'Refuerza gemelos, tibiales y tobillos, mejorando la estabilidad del pie en la marcha.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10760'),
('e2cb87fc-0eae-5a4d-9f1e-11c2cf737eed', 'Caminata con banda', ARRAY['Coloca la banda por encima de las rodillas o tobillos.', 'Da pasos laterales manteniendo las rodillas ligeramente flexionadas.', 'Mantén la tensión constante sin juntar del todo los pies.', 'Evita inclinar el tronco o arrastrar los pies.']::text[], 'principiante', 'Activa abductores y glúteos con desplazamientos laterales, mejorando la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7282'),
('20428b4a-767e-5a21-99ac-1b62496dde55', 'Curl con giro y pronación con banda', ARRAY['Pisa la banda y sujeta el extremo con la palma hacia arriba.', 'Flexiona el codo girando la muñeca hacia fuera al subir.', 'Baja controlando el giro hasta la posición inicial.', 'No balancees el tronco ni muevas el codo del costado.']::text[], 'principiante', 'Fortalece bíceps y antebrazo con rotación, útil para agarres y movimientos de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10331'),
('c57f3bed-35ea-5c6a-bc36-51cef8157c26', 'Corte antirrotación con postura abierta y banda', ARRAY['Ancla la banda a un lado y sujétala con ambas manos frente al pecho.', 'Separa los pies y mantén las rodillas ligeramente flexionadas.', 'Tira de la banda en diagonal sin dejar que el tronco rote.', 'Evita encoger los hombros o bloquear la respiración.']::text[], 'principiante', 'Trabaja el core y oblicuos resistiendo la rotación, mejorando la estabilidad en movimientos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8002'),
('3b062dc2-3ef7-51d1-b780-0ad528ed1eb8', 'Ciclismo aéreo inverso', ARRAY['Túmbate boca arriba con las manos en la zona lumbar y las piernas elevadas.', 'Pedalea en el aire llevando las rodillas hacia el pecho de forma alterna.', 'Mantén la zona lumbar pegada al suelo durante todo el movimiento.', 'No arquees la espalda ni aceleres perdiendo el control.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un movimiento controlado que mejora la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7850'),
('a7d89dd1-7613-59e3-8759-3214d22d9b7c', 'Extensión de espalda inversa en el suelo', ARRAY['Túmbate boca abajo con los brazos extendidos al frente.', 'Eleva ligeramente brazos y piernas del suelo apretando glúteos.', 'Mantén la posición un segundo y baja controlando.', 'Evita arquear en exceso el cuello o la zona lumbar.']::text[], 'intermedio', 'Fortalece glúteos y lumbares con un movimiento controlado que mejora la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4777'),
('89f94865-b75e-50ce-ae53-abf60c6b8baa', 'Estiramiento de pecho inverso', ARRAY['Entrelaza las manos detrás de la espalda con los brazos rectos.', 'Abre el pecho y lleva los hombros hacia atrás sin forzar.', 'Mantén entre veinte y treinta segundos respirando con calma.', 'No arquees la zona lumbar ni subas los hombros.']::text[], 'principiante', 'Abre el pecho y la parte anterior del hombro, aliviando la tensión por posturas encorvadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1782'),
('85883599-8e17-5852-913a-1d214e5a35b5', 'Encogimiento abdominal inverso', ARRAY['Túmbate boca arriba con los brazos extendidos a los lados del cuerpo.', 'Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo.', 'Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la zona baja del abdomen y los flexores de cadera, mejorando el control del core y la estabilidad lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0872'),
('38d9bd67-e9d5-5acc-81de-6b2f6db53f42', 'Encogimiento abdominal inverso con patada', ARRAY['Túmbate boca arriba con las piernas flexionadas y las manos apoyadas junto al cuerpo.', 'Eleva la pelvis despegando la zona lumbar del suelo mientras extiendes las piernas hacia delante.', 'Recoge las piernas y baja la pelvis con control, sin dejarte caer de golpe.', 'Exhala al encoger y subir las piernas, e inhala al bajar.', 'Evita arquear la espalda baja: mantén las costillas hacia abajo durante todo el recorrido.']::text[], 'intermedio', 'Activa el abdomen bajo y los flexores de cadera con extensión de piernas, reforzando el core y la coordinación del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4330'),
('76325829-588a-559d-a386-2373c3c28a69', 'Encogimiento abdominal inverso a bicho muerto', ARRAY['Túmbate boca arriba con brazos extendidos hacia el techo y rodillas flexionadas a 90 grados.', 'Encoge la pelvis despegando la zona lumbar y extiende un brazo y la pierna contraria sin tocar el suelo.', 'Vuelve al centro y repite con el lado opuesto manteniendo la espalda baja pegada al suelo.', 'Exhala al extender y inhala al recoger, con movimiento lento y controlado.', 'No dejes que la lumbar se arquee ni que el abdomen se hinche hacia fuera.']::text[], 'intermedio', 'Combina abdomen bajo y control del core para estabilizar la pelvis y mejorar la coordinación entre brazos y piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4097'),
('2e981902-8045-517f-9727-0c2ce5a85e5e', 'Fondos inversos', ARRAY['Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombros usando el peso corporal, ideal para ganar fuerza en el tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0672'),
('69dfadae-1283-550c-85ca-049c487b75ec', 'Aleteo inverso en el suelo', ARRAY['Túmbate boca arriba con una mano bajo la cabeza y la otra junto al cuerpo, piernas estiradas y elevadas.', 'Mantén la zona lumbar pegada al suelo y sube ligeramente las piernas.', 'Aletea las piernas arriba y abajo con movimientos cortos y alternos.', 'Respira de forma continua sin aguantar la respiración durante el aleteo.', 'Evita arquear la espalda o bajar demasiado las piernas para no cargar la lumbar.']::text[], 'intermedio', 'Trabaja el abdomen bajo y los flexores de cadera con un movimiento alterno de piernas que exige control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4779'),
('76ef3cd1-ef96-53cc-a187-1aef19c226bf', 'Jalón al pecho con agarre inverso', ARRAY['Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo.', 'Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros.', 'Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.', 'Tira de las asas hacia el pecho, juntando las escápulas.', 'Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja el dorsal ancho con agarre supino, sumando bíceps y antebrazos para tirar con más fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0673'),
('6b91e1cc-a93c-5449-a0a4-e4c3659540a9', 'Dominada con agarre inverso', ARRAY['Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla el dorsal ancho y los bíceps colgándote de la barra, mejorando la fuerza de tracción del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0674'),
('21844520-6367-5e0a-80d4-e7141a7546a8', 'Hiperextensión inversa en balón', ARRAY['Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.', 'Coloca las manos en el suelo frente a ti para mayor estabilidad.', 'Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Activa glúteos, isquios y zona lumbar para fortalecer la cadena posterior y estabilizar la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0675'),
('8fdfaefb-544c-575b-b421-140e920a41f2', 'Hiperextensión inversa en banco plano', ARRAY['Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco.', 'Sujétate del banco para mantener la estabilidad.', 'Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas.', 'Aprieta los glúteos en la parte alta del movimiento.', 'Baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza glúteos, isquios y lumbar elevando las piernas, mejorando la extensión de cadera y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1423'),
('7e29821f-9159-5e36-aec6-81692ba9f981', 'Hiperextensión inversa en banco', ARRAY['Túmbate boca abajo en el banco con la cadera en el borde y sujétate con las manos.', 'Aprieta el core y eleva las piernas juntas hasta alinear el cuerpo con el banco.', 'Baja las piernas con control sin balancearte ni usar impulso.', 'Exhala al subir y controla la bajada durante dos segundos.', 'Evita hiperextender la lumbar: sube solo hasta la línea del cuerpo.']::text[], 'intermedio', 'Trabaja glúteos, isquios y zona lumbar con elevación de piernas, fortaleciendo la cadena posterior y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5803'),
('d17b8dfb-3ad5-53cd-8c0a-fb8aa17b185b', 'Hiperextensión inversa en balón de estabilidad', ARRAY['Túmbate boca abajo sobre el balón con la cadera en el borde y las manos apoyadas en el suelo.', 'Aprieta el core y eleva las piernas juntas hasta alinear el cuerpo.', 'Baja las piernas lentamente manteniendo el equilibrio sobre el balón.', 'Exhala al subir y controla la bajada sin rebotar.', 'No arquees la lumbar ni dejes caer la cadera para evitar perder estabilidad.']::text[], 'principiante', 'Fortalece glúteos, isquios y lumbar sobre el balón, mejorando el equilibrio y la extensión de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9009'),
('0ad45f14-ad27-598c-82d4-575a2bad8a69', 'Extensión de pierna inversa', ARRAY['Colócate a cuatro apoyos con manos bajo los hombros y rodillas bajo la cadera.', 'Aprieta el core y extiende una pierna hacia atrás hasta alinear el cuerpo.', 'Baja la pierna con control sin tocar el suelo y repite las repeticiones.', 'Exhala al extender y evita girar la cadera hacia un lado.', 'No arquees la lumbar: sube solo hasta donde puedas mantener la espalda neutra.']::text[], 'intermedio', 'Activa glúteos, isquios y zona lumbar elevando la pierna hacia atrás, mejorando la extensión de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4916'),
('d766f431-d3d7-5f18-9a86-9ebd17206237', 'Zancada hacia atrás con patada', ARRAY['De pie, con los pies a la anchura de la cadera y las manos en la cintura.', 'Da un paso largo hacia atrás y baja la rodilla hasta rozar el suelo.', 'Empuja con la pierna delantera para volver de pie y lanza una patada al frente con la pierna trasera.', 'Exhala al subir y al patalear, manteniendo el core activo.', 'Evita que la rodilla delantera se vaya hacia dentro y no pierdas el equilibrio.']::text[], 'intermedio', 'Trabaja glúteos, cuádriceps e isquios con un paso atrás y patada final, mejorando fuerza y equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0676'),
('b2979afb-0455-57fa-9084-0c51941b1570', 'Zancada hacia atrás con giro y alcance de brazo', ARRAY['De pie, con los brazos extendidos al frente a la altura de los hombros.', 'Da un paso atrás y baja la rodilla mientras giras el torso y llevas un brazo hacia el lado contrario.', 'Vuelve al centro y regresa de pie, repitiendo con el otro lado.', 'Exhala al girar y mantén el movimiento lento y controlado.', 'No fuerces la torsión desde la lumbar: gira desde el pecho y mantén la rodilla alineada.']::text[], 'principiante', 'Mejora movilidad de cadera y torsión torácica, activando cuádriceps, glúteos y oblicuos en un gesto fluido.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11088'),
('ed398995-230b-5d45-afb5-7aa4fe8bc848', 'Zancada atrás con rodilla alta y zancada frontal', ARRAY['De pie, con los pies juntos y el core activado.', 'Da un paso atrás y baja la rodilla, luego sube llevando la rodilla trasera a la altura de la cadera.', 'Sin bajar el pie, avanza con una zancada frontal y vuelve a la posición inicial.', 'Exhala en cada subida y mantén el torso erguido durante todo el recorrido.', 'Evita que la rodilla delantera pase de la punta del pie y no pierdas el equilibrio.']::text[], 'intermedio', 'Combina fuerza y coordinación de cuádriceps, glúteos e isquios, mejorando el equilibrio y la estabilidad del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7412'),
('ac10e267-9713-5fbf-8830-692ec44f791d', 'Plancha inversa', ARRAY['Siéntate en el suelo con las piernas estiradas y las manos apoyadas detrás de la cadera.', 'Empuja con manos y talones para elevar la cadera hasta formar una línea recta de hombros a pies.', 'Aprieta los glúteos y mantén el abdomen firme sin dejar caer la cadera.', 'Respira de forma constante y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Fortalece glúteos, isquios y espalda baja mientras estabilizas el core y abres el pecho.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0867'),
('a0302f6f-04b8-54e7-976b-3ff551f3565f', 'Flexión inversa', ARRAY['Siéntate en el suelo con las rodillas flexionadas y las manos apoyadas detrás, dedos hacia delante.', 'Eleva la cadera y extiende los brazos para sostener el peso sobre manos y pies.', 'Flexiona los codos hacia atrás hasta bajar la cadera cerca del suelo.', 'Empuja con los tríceps para volver arriba sin bloquear los codos de golpe.', 'Evita abrir los codos hacia los lados y mantén el core activo.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con el propio peso, mejorando la fuerza de empuje y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3751'),
('665c6087-c1fc-5239-9f31-98acc9e1f4a9', 'Estiramiento de hombro inverso', ARRAY['Lleva un brazo estirado por delante del pecho a la altura del hombro.', 'Con la otra mano, sujeta el codo y llévalo suavemente hacia ti.', 'Mantén los hombros bajos y no gires el tronco para aumentar el estiramiento.', 'Respira profundo y sostén entre veinte y treinta segundos por lado.']::text[], 'principiante', 'Estira la parte anterior del hombro y el pecho, aliviando tensión tras entrenar empujes o pasar horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1971'),
('8554234f-e8d9-5ab2-b14a-884584dbf359', 'Curl femoral deslizante con toalla', ARRAY['Túmbate boca arriba con los talones sobre una toalla y las piernas estiradas.', 'Eleva la cadera apoyando los hombros y forma una línea recta con el cuerpo.', 'Desliza los talones hacia la cadera flexionando las rodillas sin bajar la pelvis.', 'Empuja de nuevo los pies hacia delante controlando el movimiento.', 'Evita arquear la espalda baja y mantén el abdomen apretado.']::text[], 'intermedio', 'Fortalece isquios y glúteos deslizando los talones sobre una toalla, mejorando la fuerza posterior de la pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4897'),
('7bcbf7fd-2d0b-550d-bbb3-852ad422937d', 'Postura del guerrero invertido', ARRAY['Desde una zancada amplia, flexiona la rodilla delantera y gira el pie trasero hacia fuera.', 'Eleva el brazo delantero y llévalo hacia atrás inclinando el tronco sobre la pierna trasera.', 'Apoya la mano trasera en la pierna de atrás y alarga el costado.', 'Mantén la mirada al frente y respira de forma pausada.', 'Evita hundir la cadera delantera y no fuerces la rodilla más allá del tobillo.']::text[], 'intermedio', 'Abre la cadera y estira el costado del cuerpo mientras fortalece cuádriceps y glúteos en una postura de yoga activa.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5913'),
('3dcd5e13-ba95-54ec-80e3-61c43f1b6577', 'Silla con giro', ARRAY['Junta los pies y flexiona las rodillas como si fueras a sentarte en una silla.', 'Lleva las manos al pecho y gira el tronco hacia un lado manteniendo la cadera al frente.', 'Alarga la columna y respira profundo durante la torsión.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita juntar las rodillas o perder el equilibrio por girar demasiado rápido.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras moviliza la columna y los oblicuos en una torsión de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5899'),
('b1789cc7-070e-58be-9bda-a2998fb43db8', 'Postura de cabeza a rodilla con giro', ARRAY['Siéntate con una pierna estirada y la otra flexionada con la planta en el muslo interno.', 'Gira el tronco hacia la pierna estirada y lleva la mano contraria al pie.', 'Alarga la columna y apoya la otra mano detrás para estabilizar la torsión.', 'Respira profundo y mantén la posición sin forzar la espalda.', 'Evita redondear la espalda y no tires del cuello.']::text[], 'intermedio', 'Estira isquios y espalda mientras moviliza la columna y los oblicuos con una torsión sentada.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5908'),
('bf981c60-ed36-5a5d-b77a-0e9fdf16c103', 'Postura de ángulo lateral con giro', ARRAY['Desde una zancada amplia, flexiona la rodilla delantera y apoya la mano contraria al pie delantero.', 'Gira el tronco y eleva el brazo libre hacia el techo.', 'Mantén la cadera baja y alarga el costado sin perder el equilibrio.', 'Respira de forma constante y mira hacia la mano elevada.', 'Evita colapsar la rodilla delantera hacia dentro.']::text[], 'intermedio', 'Fortalece piernas y oblicuos mientras abre la cadera y estira el costado en una torsión de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5900'),
('9e50caf7-bfbf-542e-8594-8a0f20dd66b8', 'Postura del ángulo lateral con giro', ARRAY['Abre las piernas en una zancada amplia y flexiona la rodilla delantera.', 'Gira el tronco y lleva la mano contraria al pie delantero.', 'Eleva el brazo libre y alarga el costado manteniendo la cadera estable.', 'Respira profundo y sostén la postura sin forzar la rodilla.', 'Evita perder el equilibrio por girar demasiado el tronco.']::text[], 'intermedio', 'Combina fuerza de piernas y movilidad de columna, trabajando oblicuos, glúteos y hombros en una torsión profunda.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0957'),
('54e3631f-6dcd-55aa-9835-9bed6d400f02', 'Postura del triángulo con giro', ARRAY['Coloca las piernas abiertas con el pie delantero apuntando al frente.', 'Gira el tronco y lleva la mano contraria al pie delantero.', 'Eleva el brazo libre y alarga la columna sin redondear la espalda.', 'Mantén las piernas firmes y respira de forma pausada.', 'Evita bloquear la rodilla delantera y no fuerces la torsión.']::text[], 'intermedio', 'Estira isquios y gemelos mientras fortalece oblicuos y glúteos con una torsión de pie.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5901'),
('53d726ff-f6f6-5020-a022-afcbced49884', 'Andar en bicicleta al aire libre', ARRAY['Ajusta el sillín a la altura de la cadera y comprueba frenos antes de salir.', 'Pedalea con cadencia constante manteniendo la espalda relajada y las manos firmes.', 'Cambia de marcha antes de las cuestas para no forzar las rodillas.', 'Respira de forma regular y mantén la mirada al frente.', 'Evita pedalear con el pie mal colocado o con el sillín demasiado bajo.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y fortalece piernas y glúteos pedaleando al aire libre.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5214'),
('6f989cd8-ba3b-537f-a7e2-8e1d2ca968df', 'Superman alterno en anillas', ARRAY['Sujeta las anillas y colócate en suspensión con el cuerpo alineado.', 'Eleva un brazo y la pierna contraria a la vez manteniendo el tronco estable.', 'Baja con control y alterna el lado sin balancearte.', 'Aprieta glúteos y abdomen durante todo el movimiento.', 'Evita arquear la espalda baja o perder la alineación del cuerpo.']::text[], 'intermedio', 'Fortalece la espalda baja y los glúteos mientras estabilizas el core suspendido en anillas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4977'),
('1c819f08-a994-59a8-8d4e-504b0d4c71d2', 'Dominada arquero en anillas', ARRAY['Cuélgate de las anillas con agarre neutro y el cuerpo alineado.', 'Tira hacia un lado flexionando ese codo mientras el otro brazo se mantiene más extendido.', 'Sube controlando el movimiento y sin balancearte.', 'Baja despacio y alterna el lado en la siguiente repetición.', 'Evita encoger los hombros o perder la tensión del core.']::text[], 'avanzado', 'Trabaja dorsal y bíceps con mayor exigencia unilateral, mejorando fuerza y control en suspensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7512'),
('191d0b88-e093-57ef-a72c-b48932326928', 'Curl de brazos en anillas', ARRAY['Sujeta las anillas con las palmas hacia ti y el cuerpo ligeramente inclinado hacia atrás.', 'Flexiona los codos para acercar el pecho a las manos manteniendo los hombros estables.', 'Baja despacio hasta extender los brazos sin perder la tensión.', 'Mantén el core firme y evita balancearte.', 'No encorves la espalda ni dejes caer los hombros.']::text[], 'intermedio', 'Aísla bíceps y antebrazos usando el propio peso en suspensión, mejorando fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6234'),
('5c1b26c4-0daf-5b59-8f4c-069f135d4228', 'Fondos en anillas', ARRAY['Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto.', 'Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Fortalece tríceps, pecho y hombros con el propio peso, mejorando la estabilidad y la fuerza de empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0677'),
('d43d906a-ce5a-5d26-9c7f-ea0d72e47e2d', 'Flexión pike elevada en anillas', ARRAY['Coloca los pies en el suelo y las manos en las anillas, con la cadera elevada y el cuerpo en forma de V invertida.', 'Baja la cabeza hacia el suelo flexionando los codos y manteniendo la cadera alta.', 'Empuja con fuerza hasta extender los brazos sin perder la posición de pike.', 'Inspira al bajar y espira al subir, controlando el tempo.', 'Evita arquear la espalda o adelantar la cabeza; mantén el core firme.']::text[], 'intermedio', 'Trabaja hombros y tríceps con gran demanda de control escapular y core, ideal para ganar fuerza en vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9316'),
('11287c20-dd7b-5db8-9819-3f2b0955f980', 'Remo en anillas con pies elevados', ARRAY['Agarra las anillas y apoya los pies en un cajón, con el cuerpo recto y en suspensión.', 'Tira del pecho hacia las manos juntando las escápulas.', 'Baja de forma controlada hasta extender los brazos sin perder la tensión.', 'Espira al tirar e inspira al bajar, manteniendo el core activo.', 'Evita encoger los hombros o dejar caer la cadera durante el movimiento.']::text[], 'intermedio', 'Fortalece la espalda alta y los bíceps con mayor carga al elevar los pies, mejorando la postura y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4818'),
('58f20827-4f82-5592-abc6-635bb1eb7fda', 'Face pull en anillas', ARRAY['Sujeta las anillas a la altura de los ojos y da un paso atrás con los brazos extendidos.', 'Tira de las anillas hacia la cara separando las manos y abriendo los codos.', 'Aprieta las escápulas al final y vuelve despacio a la posición inicial.', 'Espira al tirar e inspira al volver, sin balancear el cuerpo.', 'Evita usar impulso o encoger el cuello; mantén los hombros bajos.']::text[], 'intermedio', 'Refuerza los deltoides posteriores y la musculatura rotadora, clave para la salud del hombro y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6252'),
('036b9a11-bde1-5b12-89d2-fa62853d0276', 'Remo alto en anillas', ARRAY['Agarra las anillas a la altura del pecho y colócate en suspensión con el cuerpo recto.', 'Tira de las anillas hacia el esternón llevando los codos hacia fuera.', 'Junta las escápulas al final del recorrido y baja controlando.', 'Espira al tirar e inspira al bajar, sin perder la línea del cuerpo.', 'Evita adelantar los hombros o dejar caer la cadera.']::text[], 'intermedio', 'Activa la espalda alta y los deltoides posteriores, útil para equilibrar el tren superior y mejorar la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4921'),
('508bd268-c3da-5d1a-a335-1be55212f47f', 'Rodillo abdominal inverso con isométrico en anillas', ARRAY['Colócate en posición de plancha con las manos en las anillas y los pies en el suelo.', 'Lleva las rodillas hacia el pecho manteniendo la espalda neutra.', 'Sostén la posición unos segundos apretando el abdomen.', 'Vuelve despacio a la plancha sin arquear la lumbar.', 'Evita balancear el cuerpo o perder la alineación durante la pausa.']::text[], 'intermedio', 'Trabaja el abdomen y el core con una pausa isométrica que aumenta la tensión y el control.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9313'),
('98754feb-c15c-5038-ac9f-40e137888bbc', 'Rodillo abdominal de rodillas en anillas', ARRAY['Arrodíllate frente a las anillas y agárralas con los brazos extendidos.', 'Rueda hacia delante estirando el cuerpo sin arquear la espalda.', 'Vuelve tirando con el abdomen y los brazos hasta la posición inicial.', 'Inspira al rodar hacia delante y espira al volver.', 'Evita hundir la lumbar o perder el control en el recorrido.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con un movimiento controlado que exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4978'),
('d2627b8c-6d8a-5970-a8fa-baa6d9817894', 'Curl femoral en anillas', ARRAY['Túmbate boca arriba con los talones en las anillas y las piernas extendidas.', 'Eleva la cadera y flexiona las rodillas llevando los talones hacia los glúteos.', 'Extiende las piernas despacio sin dejar caer la cadera.', 'Espira al flexionar e inspira al extender, manteniendo el core firme.', 'Evita arquear la lumbar o usar impulso para subir.']::text[], 'intermedio', 'Aísla los isquiotibiales y glúteos con un movimiento de flexión de rodilla que mejora la fuerza posterior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4819'),
('5233dbba-5be6-5878-a875-9ecc67a11a2a', 'Sostén de flexión con brazos largos en anillas', ARRAY['Coloca las manos en las anillas y adopta una posición de plancha con brazos extendidos.', 'Aprieta el core y mantén el cuerpo recto sin dejar caer la cadera.', 'Sostén la posición respirando de forma controlada.', 'Evita bloquear la respiración o encoger los hombros hacia las orejas.', 'Sal si pierdes la alineación o sientes molestias en el hombro.']::text[], 'intermedio', 'Mejora la estabilidad escapular y la fuerza isométrica del pecho y hombros en posición de plancha.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10950');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('971e9ac3-f1af-560d-b91a-a6790348c665', 'Curl de bíceps a un brazo en anillas', ARRAY['Agarra una anilla con una mano y colócate con el cuerpo ligeramente inclinado.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el tronco.', 'Baja despacio hasta extender el brazo por completo.', 'Espira al subir e inspira al bajar, manteniendo el core activo.', 'Evita balancear el cuerpo o encoger el hombro durante el curl.']::text[], 'intermedio', 'Trabaja el bíceps y el antebrazo de forma unilateral, mejorando la fuerza y el control de cada brazo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6237'),
('7859875d-d444-5f14-bcef-585bcf0ef039', 'Dominada a un brazo en anillas', ARRAY['Agarra una anilla con una mano y cuelga con el brazo extendido y el cuerpo estable.', 'Tira del cuerpo hacia arriba llevando el codo hacia el costado.', 'Sube hasta que la barbilla supere la anilla y baja controlando.', 'Espira al subir e inspira al bajar, sin balancearte.', 'Evita usar impulso o perder la tensión escapular; si no controlas, usa asistencia.']::text[], 'avanzado', 'Ejercicio avanzado que exige gran fuerza de dorsal y bíceps, además de control del core y agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7517'),
('8d937d19-0b1a-593c-bd50-635555f7a24e', 'Dominada en anillas', ARRAY['Cuelga de las anillas con los brazos extendidos y los hombros activos.', 'Tira del cuerpo hacia arriba juntando las escápulas y llevando el pecho a las anillas.', 'Baja de forma controlada hasta extender los brazos.', 'Espira al subir e inspira al bajar, sin balancear las piernas.', 'Evita encoger los hombros o usar impulso para completar la repetición.']::text[], 'intermedio', 'Fortalece dorsales, bíceps y espalda alta, mejorando la fuerza de tracción y el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5522'),
('411a615a-7335-5f04-a41a-cfc43d421f37', 'Pullover en anillas', ARRAY['Colócate en suspensión con las manos en las anillas y el cuerpo recto.', 'Lleva los brazos hacia atrás extendiéndolos y abriendo el pecho.', 'Vuelve a la posición inicial tirando con los dorsales.', 'Inspira al abrir y espira al volver, manteniendo el core firme.', 'Evita arquear la espalda o perder la alineación del cuerpo.']::text[], 'intermedio', 'Trabaja dorsales y pecho con un recorrido amplio que también exige control del core y los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8750'),
('0e06a104-c35d-56ed-97ce-967d69a2e790', 'Dominada a un brazo en anillas asistida con banda', ARRAY['Coloca la banda en la anilla y apoya un pie o rodilla en ella para asistirte.', 'Agarra la anilla con una mano y cuelga con el brazo extendido.', 'Tira del cuerpo hacia arriba controlando el recorrido y baja despacio.', 'Espira al subir e inspira al bajar, sin balancearte.', 'Evita depender demasiado de la banda o perder la tensión escapular.']::text[], 'intermedio', 'Progresión hacia la dominada a un brazo que permite ganar fuerza de dorsal y bíceps con ayuda elástica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10661'),
('889d16e2-818b-57fe-ad09-7536f118cc31', 'Apertura invertida en anillas', ARRAY['Agarra las anillas con los brazos extendidos y el cuerpo inclinado hacia atrás.', 'Abre los brazos hacia los lados juntando las escápulas.', 'Vuelve despacio a la posición inicial sin perder la tensión.', 'Espira al abrir e inspira al volver, manteniendo el core activo.', 'Evita encoger los hombros o usar impulso para abrir los brazos.']::text[], 'intermedio', 'Refuerza los deltoides posteriores y la espalda alta, ayudando a equilibrar el hombro y mejorar la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4923'),
('7c4db953-4474-5a34-a032-16375a32341d', 'Dominada rocky con jalón en anillas', ARRAY['Cuelga de las anillas con los brazos extendidos y el cuerpo estable.', 'Tira del cuerpo hacia arriba como en una dominada y, al bajar, extiende los brazos hacia delante.', 'Controla el jalón llevando el pecho hacia las anillas y vuelve despacio.', 'Espira al tirar e inspira al extender, sin balancearte.', 'Evita perder la alineación del cuerpo o usar impulso en el recorrido.']::text[], 'intermedio', 'Combina tracción y jalón para trabajar dorsales y bíceps con un recorrido amplio y controlado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10662'),
('1241bf6e-ba0b-5de2-b679-460a3407637f', 'Rodillo abdominal en anillas', ARRAY['Colócate de rodillas frente a las anillas y agárralas con los brazos extendidos.', 'Mantén el cuerpo en línea recta desde las rodillas hasta la cabeza y activa el abdomen.', 'Desliza las anillas hacia delante de forma lenta hasta donde controles sin arquear la espalda.', 'Tira de las anillas para volver a la posición inicial exhalando al recoger.', 'Evita hundir la zona lumbar: si la espalda se arquea, reduce el recorrido.']::text[], 'intermedio', 'Fortalece el abdomen y el core profundo mientras estabilizas hombros y dorsales en un patrón de extensión controlada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4979'),
('f7d8edb3-df0b-5cb9-a69b-659f004110a9', 'Remo a un brazo para deltoide posterior en anillas', ARRAY['Sujeta una anilla con una mano y colócate inclinado hacia atrás con el cuerpo recto.', 'Deja el brazo extendido y el hombro relajado hacia delante como posición de partida.', 'Tira de la anilla llevando el codo hacia atrás y hacia fuera, apretando la escápula.', 'Baja controlando el movimiento sin dejar caer el hombro de golpe.', 'Evita girar el tronco: mantén la cadera y los hombros alineados durante todo el recorrido.']::text[], 'intermedio', 'Trabaja el deltoide posterior y la espalda alta de forma unilateral, mejorando el control escapular y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6259'),
('45614a19-dbb3-5afb-8956-ff9a4709d743', 'Skin the cat en anillas', ARRAY['Cuélgate de las anillas con agarre firme y brazos extendidos.', 'Eleva las rodillas hacia el pecho y pasa las piernas entre los brazos de forma controlada.', 'Continúa girando hasta quedar invertido con los hombros abiertos y el cuerpo relajado.', 'Vuelve por el mismo camino empujando con los brazos y controlando el descenso.', 'No fuerces el rango: detente antes de notar dolor en el hombro y calienta bien antes.']::text[], 'principiante', 'Movilidad avanzada de hombros y espalda alta que exige control del core y fuerza de tracción en todo el rango.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10663'),
('a5fc20ee-f1bb-55ec-b600-5b474c63e06b', 'Dominada agarre abierto en anillas', ARRAY['Cuélgate de las anillas con las manos más separadas que los hombros.', 'Activa el core y junta ligeramente las escápulas antes de tirar.', 'Tira de las anillas llevando el pecho hacia arriba hasta pasar la barbilla.', 'Baja de forma controlada hasta extender los brazos sin balancearte.', 'Evita encoger los hombros hacia las orejas: inicia el movimiento desde la espalda.']::text[], 'intermedio', 'Desarrolla la amplitud de los dorsales y la fuerza de tracción con un agarre amplio que exige más control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7228'),
('48335107-640d-5e47-9c2c-ea54efae3b95', 'Balancín con piernas abiertas', ARRAY['Siéntate con las piernas abiertas y las manos apoyadas detrás del cuerpo.', 'Eleva el pecho y alarga la columna antes de empezar.', 'Balancéate hacia atrás y hacia delante manteniendo el abdomen activo y la espalda redondeada al rodar.', 'Controla el impulso para no cargar el cuello ni la zona lumbar.', 'Respira de forma fluida y evita rodar sobre la cabeza.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un balanceo controlado que masajea la columna y mejora la coordinación.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2856'),
('b7a4a7c4-6277-5b21-a60f-1f82a5fb0b60', 'Salto cohete', ARRAY['Colócate de pie con los pies a la anchura de los hombros y rodillas ligeramente flexionadas.', 'Baja en una sentadilla corta llevando los brazos atrás.', 'Salta con fuerza hacia arriba extendiendo caderas y rodillas y llevando los brazos arriba.', 'Aterriza con las rodillas blandas y absorbiendo el impacto.', 'Evita aterrizar con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia la fuerza explosiva de cuádriceps y glúteos, útil para mejorar el salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1584'),
('77844e6a-be03-5660-b838-422d5b761222', 'Balanceo', ARRAY['Túmbate boca abajo con los brazos extendidos hacia delante.', 'Activa el abdomen y alarga la columna antes de empezar.', 'Balancéate suavemente hacia delante y hacia atrás desde las caderas.', 'Mantén el cuello alineado y evita forzar la zona lumbar.', 'Respira de forma pausada y controla la amplitud del balanceo.']::text[], 'intermedio', 'Moviliza la columna y activa glúteos y espalda alta mediante un balanceo suave que mejora la conciencia corporal.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2857'),
('bb03ed8f-79e6-59f8-ae2c-c747212a4f15', 'Estiramiento de tobillo con balanceo', ARRAY['Apoya las manos en el suelo o en una pared y coloca un pie delante.', 'Lleva la rodilla del pie delantero hacia delante sin levantar el talón.', 'Balancéate suavemente hacia delante y hacia atrás buscando el rango cómodo.', 'Mantén el talón pegado al suelo y la respiración relajada.', 'Evita forzar si notas pinchazos en la parte delantera del tobillo.']::text[], 'principiante', 'Mejora la movilidad del tobillo y estira gemelos y sóleo, favoreciendo una sentadilla más profunda y segura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2936'),
('0bceb1c3-f837-5ac4-a7e1-0f51477c0f35', 'Estiramiento de rana con balanceo', ARRAY['Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas.', 'Coloca las manos en el suelo frente a ti para mayor apoyo.', 'Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti.', 'Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo.', 'Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos.', 'Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira glúteos, isquiotibiales y cuádriceps con un balanceo suave que mejora la movilidad de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2571'),
('18237e07-b161-5098-8c6b-5ca5c94fb823', 'Jalón tipo Rocky en dominada', ARRAY['Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros.', 'Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales y bíceps con un jalón explosivo colgado de la barra, mejorando la potencia de tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0678'),
('78cd747b-2ffa-53ab-be4e-3a375e7d347d', 'Masaje con rodillo en el tibial anterior', ARRAY['Coloca el rodillo sobre el suelo y túmbate boca abajo con la espinilla apoyada encima.', 'Apoya los antebrazos para repartir el peso y controlar la presión.', 'Desliza la pierna hacia delante y hacia atrás sobre el rodillo lentamente.', 'Detente en los puntos más sensibles y respira de forma profunda.', 'Evita presionar directamente sobre el hueso de la tibia.']::text[], 'principiante', 'Libera la tensión de la parte delantera de la pierna y mejora la movilidad del tobillo tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2947'),
('b24e816b-64ac-559d-9782-2a0237c79887', 'Rodillo alrededor del mundo acostado en el suelo', ARRAY['Túmbate boca arriba con el rodillo colocado bajo la espalda alta, en horizontal.', 'Apoya los pies en el suelo y cruza los brazos o extiéndelos hacia el techo.', 'Desliza el rodillo hacia arriba y hacia abajo por la espalda alta con control.', 'Acompaña el movimiento llevando los brazos por encima de la cabeza si puedes.', 'Evita arquear la zona lumbar y no ruedes sobre el cuello.']::text[], 'principiante', 'Moviliza la espalda alta y los hombros, mejorando la extensión torácica y la libertad de movimiento del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5386'),
('70b357d3-cb03-576a-aa83-9eecdb33851a', 'Masaje con balón en los aductores', ARRAY['Coloca el balón en el suelo y túmbate boca abajo con una pierna abierta apoyada sobre él.', 'Apoya los antebrazos para controlar la presión sobre el aductor.', 'Desliza la pierna sobre el balón buscando los puntos de mayor tensión.', 'Mantén la presión unos segundos y respira profundamente.', 'Evita presionar sobre zonas con dolor agudo o venas visibles.']::text[], 'principiante', 'Libera la tensión de la cara interna del muslo y mejora la movilidad de la cadera en deportes con cambios de dirección.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4470'),
('b3541b60-8992-5f03-a046-1e2dda2caa34', 'Masaje con balón en la pantorrilla', ARRAY['Siéntate en el suelo con el balón bajo la pantorrilla y las manos apoyadas detrás.', 'Eleva ligeramente la cadera para cargar el peso sobre el balón.', 'Desliza la pierna hacia delante y hacia atrás y gira suavemente el pie.', 'Detente en los puntos sensibles y respira de forma pausada.', 'Evita presionar directamente sobre el tendón de Aquiles o zonas doloridas.']::text[], 'principiante', 'Alivia la tensión de gemelos y sóleo y mejora la movilidad del tobillo después de correr o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4465'),
('e0df4345-caa0-5a4d-88e7-129943d17640', 'Masaje con balón en el deltoides posterior', ARRAY['Coloca el balón entre la pared y la parte posterior del hombro.', 'Apoya el peso del cuerpo contra la pared y busca la zona más tensa.', 'Mueve el brazo lentamente en círculos y hacia delante y atrás sobre el balón.', 'Mantén la presión unos segundos y respira de forma relajada.', 'Evita presionar sobre la columna cervical o zonas con dolor agudo.']::text[], 'principiante', 'Libera la tensión del deltoide posterior y la roturación del hombro, útil tras entrenamientos de empuje o tracción.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4611'),
('aa000d99-904f-5aeb-ba0e-61da7df639f8', 'Masaje con balón en el diafragma', ARRAY['Coloca el rodillo en el suelo y túmbate boca abajo con la parte baja del abdomen sobre él.', 'Apoya los antebrazos y respira despacio mientras dejas que el peso del cuerpo presione la zona.', 'Desplázate lentamente hacia los lados para masajear el diafragma sin forzar.', 'Evita presionar sobre las costillas flotantes y detente si notas dolor agudo.']::text[], 'principiante', 'Libera la tensión del diafragma y la zona abdominal, mejorando la respiración y reduciendo la rigidez del core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4482'),
('462e5ab7-ce04-5052-8817-709ef8afc066', 'Masaje con balón en los erectores de la columna', ARRAY['Túmbate boca arriba con el rodillo bajo la zona lumbar, paralelo a la columna.', 'Flexiona las rodillas y apoya los pies para controlar la presión.', 'Rueda despacio arriba y abajo sin llegar a las vértebras directamente.', 'Mantén la respiración relajada y evita arquear en exceso la espalda.']::text[], 'principiante', 'Alivia la tensión de los erectores espinales y la zona lumbar, favoreciendo la movilidad y reduciendo el dolor de espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4480'),
('ddd879da-ef4d-580f-a54d-d0d62377cf51', 'Masaje con balón en el oblicuo externo', ARRAY['Túmbate de lado con el rodillo bajo la zona lateral del abdomen.', 'Apoya el antebrazo para regular la presión sobre el oblicuo.', 'Desliza el cuerpo lentamente hacia delante y atrás sobre el rodillo.', 'Evita presionar sobre las costillas y respira de forma constante.']::text[], 'principiante', 'Relaja el oblicuo externo y mejora la movilidad del tronco, útil para reducir tensiones laterales del core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4478'),
('56c88fc6-ba5a-51a7-8ef8-85d9b2165b3b', 'Masaje con balón en los flexores del antebrazo', ARRAY['Coloca el antebrazo sobre el rodillo con la palma hacia arriba.', 'Presiona suavemente y rueda desde la muñeca hasta el codo.', 'Abre y cierra la mano mientras masajeas para aumentar el efecto.', 'Evita presionar sobre el codo y detente si aparece hormigueo.']::text[], 'principiante', 'Libera la tensión de los flexores del antebrazo y la muñeca, mejorando la movilidad y previniendo molestias por uso repetitivo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4494'),
('880b1044-9092-5357-aaec-5c09841457e8', 'Masaje con balón en el pronador del antebrazo', ARRAY['Apoya el antebrazo sobre el rodillo con la palma hacia abajo.', 'Rueda despacio por la cara interna del antebrazo, cerca del codo.', 'Gira la muñeca lentamente mientras mantienes la presión.', 'Evita presionar sobre el nervio y reduce la fuerza si notas hormigueo.']::text[], 'principiante', 'Relaja el pronador redondo y mejora la movilidad de la muñeca, aliviando tensiones por gestos repetidos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4497'),
('d55d750f-b5f3-512e-a278-2c8077c8120a', 'Masaje con balón en el supinador del antebrazo', ARRAY['Coloca el antebrazo sobre el rodillo con el pulgar hacia arriba.', 'Rueda por la cara externa del antebrazo, cerca del codo.', 'Gira la palma hacia arriba y abajo mientras masajeas.', 'Evita presionar directamente sobre el hueso y mantén una presión suave.']::text[], 'principiante', 'Libera el supinador y mejora la rotación del antebrazo, reduciendo tensión en la cara externa del codo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4495'),
('92aaac89-dbc2-57ad-8678-1c6fab6a5178', 'Masaje con balón en el glúteo medio', ARRAY['Túmbate de lado con el rodillo bajo la cadera, en la zona lateral del glúteo.', 'Apoya el antebrazo y flexiona la pierna de arriba para controlar la presión.', 'Rueda lentamente sobre la zona sin llegar al hueso de la cadera.', 'Evita presionar sobre la cresta ilíaca y respira con calma.']::text[], 'principiante', 'Alivia la tensión del glúteo medio y mejora la movilidad de la cadera, útil para reducir molestias laterales.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4472'),
('6b0f6c69-849e-5fd6-887d-133fce8ced7f', 'Masaje con balón en el ilíaco', ARRAY['Túmbate boca abajo con el rodillo bajo la parte baja del abdomen.', 'Apoya los antebrazos y relaja el peso del cuerpo sobre la zona.', 'Desplázate lentamente hacia los lados sin presionar el hueso pélvico.', 'Evita forzar la respiración y detente si notas molestia aguda.']::text[], 'principiante', 'Relaja la zona del ilíaco y los flexores de la cadera, mejorando la movilidad abdominal y pélvica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4477'),
('4e5de4fe-21c3-5f5e-8c62-b271620924ba', 'Masaje con balón en el iliopsoas', ARRAY['Túmbate boca arriba con el rodillo bajo la zona abdominal baja, ligeramente lateral.', 'Flexiona las rodillas y apoya los pies para regular la presión.', 'Rueda despacio en pequeños desplazamientos sobre la zona.', 'Evita presionar el abdomen alto y respira de forma constante.']::text[], 'principiante', 'Libera el iliopsoas y los flexores profundos de la cadera, mejorando la movilidad y reduciendo tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4475'),
('3c5845df-9817-51c6-9eb9-c30050cc554a', 'Masaje con balón en el infraespinoso', ARRAY['Túmbate de lado con el rodillo bajo el omóplato, en la zona posterior del hombro.', 'Apoya el brazo para controlar la presión sobre el infraespinoso.', 'Rueda lentamente en círculos pequeños sobre la zona.', 'Evita presionar sobre la columna y detente si aparece dolor punzante.']::text[], 'principiante', 'Alivia la tensión del infraespinoso y la roturación externa del hombro, mejorando la movilidad escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4485'),
('086c606b-3299-5984-8ce8-07d4d81b5b11', 'Masaje con balón en el vasto lateral', ARRAY['Túmbate de lado con el rodillo bajo la cara externa del muslo.', 'Apoya el antebrazo y la pierna de abajo para regular la presión.', 'Rueda desde la rodilla hasta la cadera sin llegar a las articulaciones.', 'Evita presionar sobre la rodilla y mantén la respiración relajada.']::text[], 'principiante', 'Relaja el vasto lateral del cuádriceps y mejora la movilidad del muslo, reduciendo tensión en la cara externa.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4469'),
('5232be98-2e49-51fa-a6ae-ea61b3f3774e', 'Masaje con balón en el dorsal ancho', ARRAY['Túmbate de lado con el rodillo bajo la axila, en la zona lateral de la espalda.', 'Extiende el brazo por encima de la cabeza para estirar el dorsal.', 'Rueda despacio desde la axila hasta la parte media de la espalda.', 'Evita presionar sobre las costillas y respira profundamente.']::text[], 'principiante', 'Libera el dorsal ancho y mejora la movilidad del hombro, reduciendo tensión en la espalda y la zona escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4493'),
('6fe35997-1e41-593c-a258-df09beebaed2', 'Masaje con balón en la zona lumbar', ARRAY['Túmbate boca arriba con el rodillo bajo la zona lumbar.', 'Flexiona las rodillas y apoya los pies para controlar la presión.', 'Rueda lentamente arriba y abajo sin llegar a las vértebras.', 'Evita arquear la espalda y detente si notas dolor agudo.']::text[], 'principiante', 'Alivia la tensión de la zona lumbar y los glúteos, mejorando la movilidad y reduciendo rigidez de espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4600'),
('e892f4b8-5c07-57e0-80b9-468ab112e173', 'Masaje con balón en diagonal lumbar', ARRAY['Túmbate de lado con el rodillo bajo la zona lumbar, en diagonal.', 'Apoya el antebrazo para regular la presión sobre la zona.', 'Rueda lentamente siguiendo la dirección diagonal del músculo.', 'Evita presionar sobre la columna y respira con calma.']::text[], 'principiante', 'Relaja la musculatura lumbar en diagonal y los oblicuos, mejorando la movilidad de la espalda baja.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4481'),
('193b5fe0-f7c3-55bf-91e6-4f27028657fa', 'Activación del semiespinoso de la cabeza con rodillo', ARRAY['Túmbate boca arriba con el rodillo bajo la nuca, en la base del cráneo.', 'Apoya la cabeza y realiza pequeños movimientos de afirmación con el cuello.', 'Mantén la presión suave y rueda ligeramente hacia los lados.', 'Evita forzar el cuello y detente si aparece mareo o dolor.']::text[], 'principiante', 'Activa el semiespinoso de la cabeza y la zona cervical alta, mejorando el control postural y reduciendo tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6769'),
('48be08bc-f0e1-58fa-aca8-e29514aba02d', 'Masaje con balón en el pectoral mayor clavicular', ARRAY['Coloca el balón sobre el pectoral superior, cerca de la clavícula, y túmbate boca abajo o de lado.', 'Aplica presión gradual con el peso del cuerpo y rueda lento por la zona.', 'Respira profundo y mantén la presión unos segundos en los puntos más tensos.', 'Evita presionar directamente sobre la clavícula o el hueso.']::text[], 'principiante', 'Libera la porción superior del pecho y mejora la movilidad del hombro antes de empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4484'),
('c37326fc-c13a-555a-81c1-1bd91c5a181c', 'Masaje con balón en el peroneo', ARRAY['Siéntate y coloca el balón en la parte externa de la pierna, bajo la rodilla.', 'Presiona con el peso del cuerpo y rueda despacio arriba y abajo.', 'Detente en los puntos dolorosos y respira mientras cede la tensión.', 'Evita pasar el balón sobre el hueso de la rodilla o el tobillo.']::text[], 'principiante', 'Relaja la cara externa de la pierna y mejora la estabilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4463'),
('c4f2d77a-2cbb-5f30-8982-0d3daeb3d0c3', 'Masaje con balón en el piriforme', ARRAY['Siéntate sobre el balón con una pierna cruzada sobre la otra.', 'Inclina el peso hacia el lado de la nalga que quieres trabajar.', 'Rueda lento buscando los puntos tensos y mantén la presión.', 'Evita cargar todo el peso de golpe sobre el balón.']::text[], 'principiante', 'Alivia la tensión glútea profunda y mejora la rotación de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4473'),
('1542b754-9329-5e36-90b1-87d2f7e7829b', 'Liberación del piriforme con pelota', ARRAY['Túmbate boca arriba y coloca la pelota bajo la nalga.', 'Cruza el tobillo sobre la rodilla contraria para aumentar la presión.', 'Rueda despacio y mantén la posición en los puntos más sensibles.', 'Respira profundo y evita rebotar sobre la pelota.']::text[], 'principiante', 'Reduce la rigidez en la nalga y libera tensión que puede irradiar a la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3568'),
('95c9e1d7-d9a2-55ff-ab90-cee42dab3bec', 'Masaje con balón en el poplíteo', ARRAY['Siéntate y coloca el balón detrás de la rodilla, en el hueco poplíteo.', 'Aplica una presión suave y rueda muy despacio por la zona.', 'Mantén la presión ligera y respira de forma constante.', 'Evita presionar con fuerza sobre los vasos y nervios del hueco.']::text[], 'principiante', 'Libera la parte posterior de la rodilla y mejora la flexión de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4466'),
('78215481-d6a9-5ae4-8a56-a1b7b4700037', 'Masaje con balón en el tibial posterior', ARRAY['Túmbate de lado con el balón bajo la cara interna de la pierna.', 'Apoya el peso del cuerpo y rueda despacio por la zona interna.', 'Detente en los puntos tensos y respira mientras cede.', 'Evita presionar directamente sobre el hueso de la espinilla.']::text[], 'principiante', 'Relaja la parte interna de la pantorrilla y mejora la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6766'),
('2e2896cf-4222-5c27-89d7-806bb1493446', 'Masaje con balón en el psoas', ARRAY['Túmbate boca arriba y coloca el balón en la zona abdominal baja, junto al ombligo.', 'Presiona suavemente con la respiración y rueda muy despacio.', 'Mantén una presión ligera y exhala al soltar la tensión.', 'Evita presionar fuerte sobre el abdomen o después de comer.']::text[], 'principiante', 'Libera la zona abdominal profunda y mejora la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4476'),
('10b20618-a648-5d1c-b314-3f8a638956e3', 'Masaje con balón en el recto abdominal', ARRAY['Túmbate boca abajo o de lado con el balón bajo el abdomen.', 'Aplica una presión suave y rueda despacio por la zona.', 'Respira profundo y mantén la presión ligera en los puntos tensos.', 'Evita presionar con fuerza sobre el abdomen.']::text[], 'principiante', 'Relaja la musculatura abdominal y mejora la respiración diafragmática.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4479'),
('36036a57-3e8f-5d30-a534-46f965080d7c', 'Masaje con balón en el recto femoral', ARRAY['Túmbate boca abajo y coloca el balón bajo la parte frontal del muslo.', 'Apoya el peso del cuerpo y rueda despacio arriba y abajo.', 'Detente en los puntos tensos y respira mientras cede.', 'Evita pasar el balón sobre la rodilla o la cadera.']::text[], 'principiante', 'Libera la parte frontal del muslo y mejora la extensión de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4468'),
('499b1538-2fc3-5953-bed4-b33609b163c7', 'Masaje con balón en el romboides', ARRAY['Túmbate boca arriba con el balón bajo la zona entre los omóplatos.', 'Cruza los brazos o apoya las manos para controlar la presión.', 'Rueda despacio y mantén la presión en los puntos tensos.', 'Evita presionar directamente sobre la columna.']::text[], 'principiante', 'Libera la zona entre los omóplatos y mejora la movilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4489'),
('e4361725-9da8-570a-97c8-749ef51eb82c', 'Masaje con balón en el elevador de la escápula', ARRAY['Túmbate boca arriba con el balón bajo el ángulo interno del omóplato.', 'Gira la cabeza hacia el lado contrario para aumentar la presión.', 'Rueda muy despacio y mantén la presión en los puntos tensos.', 'Evita presionar sobre la columna o el cuello directamente.']::text[], 'principiante', 'Relaja la parte alta del cuello y mejora la movilidad cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4487'),
('dc1d65d6-9086-5400-8973-88b6c5a92966', 'Activación del pectíneo sentado con balón', ARRAY['Siéntate en una silla y coloca el balón entre las rodillas.', 'Aprieta el balón con las piernas y mantén unos segundos.', 'Relaja despacio y repite sin perder la postura erguida.', 'Evita apretar con rebote o aguantar la respiración.']::text[], 'principiante', 'Activa la cara interna del muslo y mejora la estabilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6812'),
('6d70c2ba-66ac-5020-8881-b36da3ca57de', 'Activación de los escalenos con balón de lado', ARRAY['Túmbate de lado con el balón bajo la zona lateral del cuello.', 'Aplica una presión muy suave y gira la cabeza despacio.', 'Respira profundo y mantén la presión ligera.', 'Evita presionar fuerte sobre el cuello o la tráquea.']::text[], 'principiante', 'Activa la musculatura lateral del cuello y mejora la movilidad cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6767'),
('475a36c4-67e2-5639-8c3b-51e11ba30d15', 'Masaje con balón en el tensor de la fascia lata', ARRAY['Túmbate de lado con el balón bajo la cadera, en la cara externa.', 'Apoya el peso del cuerpo y rueda despacio por la zona.', 'Detente en los puntos tensos y respira mientras cede.', 'Evita presionar directamente sobre el hueso de la cadera.']::text[], 'principiante', 'Libera la cara externa de la cadera y mejora la movilidad lateral.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4471'),
('2b144bff-e944-5c77-ae08-cb77e22baa93', 'Masaje con balón en el tibial anterior', ARRAY['Siéntate y coloca el balón en la parte frontal de la espinilla.', 'Presiona con la mano o el peso del cuerpo y rueda despacio.', 'Detente en los puntos tensos y respira mientras cede.', 'Evita presionar directamente sobre el hueso de la tibia.']::text[], 'principiante', 'Relaja la parte frontal de la espinilla y mejora la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4464'),
('17e77668-43de-5db9-9631-6686dc944e70', 'Masaje con rodillo en el trapecio inferior', ARRAY['Coloca el rodillo en horizontal sobre el suelo y túmbate boca arriba con la zona media de la espalda encima.', 'Cruza los brazos sobre el pecho y eleva ligeramente la cadera para cargar el peso sobre el rodillo.', 'Desplázate despacio arriba y abajo por la zona entre los omóplatos, deteniéndote donde notes tensión.', 'Respira profundo y evita arquear la zona lumbar en exceso durante el recorrido.']::text[], 'principiante', 'Libera tensión en la zona media de la espalda y mejora la movilidad escapular tras horas de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4491'),
('1d4133d6-68c6-5dce-b4a3-f614c3b20efa', 'Masaje con rodillo en el trapecio superior', ARRAY['Túmbate boca arriba con el rodillo bajo la parte alta de la espalda, cerca de los omóplatos.', 'Entrelaza las manos detrás de la cabeza para sostener el cuello sin tirar de él.', 'Rueda lentamente arriba y abajo y gira el tronco hacia cada lado para llegar al trapecio.', 'Evita presionar directamente sobre las vértebras cervicales y mantén la respiración relajada.']::text[], 'principiante', 'Alivia la rigidez del cuello y los hombros acumulada por malas posturas frente al ordenador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4490'),
('06dc4393-12b8-5834-a2f7-dedee7b3e887', 'Liberación del trapecio superior con pelota', ARRAY['Coloca la pelota sobre el trapecio superior, entre el cuello y el hombro, y apóyate contra una pared.', 'Presiona con el peso del cuerpo hasta notar una tensión tolerable, sin llegar al dolor agudo.', 'Mueve despacio el hombro y el brazo mientras mantienes la presión sobre el punto.', 'Respira de forma pausada y evita aplicar la pelota sobre la columna o el hueso del hombro.']::text[], 'principiante', 'Relaja los puntos gatillo del cuello y los hombros para reducir dolor de cabeza tensional.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3570'),
('5d7b641f-f28b-506d-a808-993b667013db', 'Rodillo para pecho acostado en el suelo', ARRAY['Túmbate boca abajo con el rodillo colocado bajo el pecho, en diagonal hacia el hombro.', 'Apoya el peso del cuerpo de forma progresiva y extiende el brazo hacia el lado del rodillo.', 'Rueda despacio sobre la zona pectoral girando ligeramente el tronco para abarcar más superficie.', 'Evita presionar sobre las costillas flotantes y mantén la respiración constante.']::text[], 'principiante', 'Abre la musculatura pectoral y mejora la extensión de hombros tras sesiones de press o apuntes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5377'),
('c044c50a-5c39-5e91-8ecb-4630605a1408', 'Rodillo para erectores espinales acostado en el suelo', ARRAY['Siéntate en el suelo con el rodillo detrás y túmbate apoyando la zona lumbar sobre él.', 'Cruza los brazos o apóyalos en el suelo y eleva la cadera lo justo para cargar el peso.', 'Rueda muy despacio arriba y abajo sin llegar a las vértebras cervicales ni a las lumbares más bajas.', 'Detente en los puntos tensos y respira profundo, evitando rodar rápido o con dolor.']::text[], 'principiante', 'Descarga la musculatura lumbar y mejora la sensación de movilidad en la espalda baja.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5387'),
('18e2564e-598f-53d5-b48a-850be7e99e7c', 'Rodillo para el pie', ARRAY['Siéntate en una silla y coloca el rodillo bajo la planta del pie.', 'Presiona con el pie y rueda desde el talón hasta la base de los dedos con presión moderada.', 'Detente en las zonas más sensibles y mantén la presión unos segundos mientras respiras.', 'Evita cargar todo el peso del cuerpo de golpe y no ruedes sobre el arco con dolor agudo.']::text[], 'principiante', 'Relaja la fascia plantar y los músculos del pie para mejorar el apoyo y prevenir molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5398'),
('2d0fbef2-71d7-5450-b3e5-0093bc8d90f7', 'Rodillo para hombro frontal y pecho acostado en el suelo', ARRAY['Túmbate boca abajo con el rodillo colocado bajo el hombro y la parte delantera del pecho.', 'Extiende el brazo hacia delante y apoya el peso de forma progresiva sobre la zona.', 'Rueda despacio en diagonal desde el pecho hacia el hombro con movimientos cortos.', 'Evita presionar sobre la clavícula y reduce la presión si notas hormigueo en el brazo.']::text[], 'principiante', 'Libera la parte anterior del hombro y el pectoral para recuperar amplitud en los movimientos de empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5378'),
('53fbc82b-b010-57a4-a8b1-4c184c2b12e3', 'Rodillo para giro de glúteos acostado en el suelo', ARRAY['Siéntate sobre el rodillo con una pierna flexionada y la otra cruzada sobre ella.', 'Inclina el tronco hacia atrás apoyando las manos y carga el peso sobre un lado del glúteo.', 'Gira el tronco y la cadera despacio para rodar sobre la zona glútea durante unos segundos.', 'Cambia de lado y evita presionar directamente sobre el hueso del isquion.']::text[], 'principiante', 'Relaja el glúteo y la cadera y mejora la rotación de la pelvis antes o después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5391'),
('9b1b3371-022d-5350-91b8-0aa3f432b217', 'Rodillo para glúteos sentado en el suelo', ARRAY['Siéntate sobre el rodillo con las rodillas flexionadas y los pies apoyados en el suelo.', 'Inclina el tronco hacia atrás con las manos detrás para repartir el peso.', 'Rueda despacio sobre un glúteo y luego sobre el otro, deteniéndote en los puntos tensos.', 'Evita cargar todo el peso sobre el coxis y mantén la respiración relajada.']::text[], 'principiante', 'Alivia la tensión glútea acumulada por estar sentado y mejora la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5390'),
('a285b3a3-4354-5f46-98a3-868818be321f', 'Rodillo para isquiotibiales y glúteos sentado en el suelo', ARRAY['Siéntate en el suelo con el rodillo bajo un muslo y las manos detrás para apoyarte.', 'Eleva ligeramente la cadera y rueda desde la parte baja del glúteo hasta encima de la rodilla.', 'Gira la pierna hacia dentro y hacia fuera para abarcar toda la parte posterior del muslo.', 'Evita rodar sobre el hueco de la rodilla y reduce la presión si aparece dolor.']::text[], 'principiante', 'Relaja la parte posterior del muslo y el glúteo para mejorar la flexibilidad y reducir sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5392'),
('fb7570ed-d898-5838-8576-1d521d562e75', 'Hip thrust con balón', ARRAY['Apoya la parte alta de la espalda en el balón y coloca los pies a la anchura de las caderas.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y muslos sin arquear la lumbar.', 'Aprieta los glúteos arriba un segundo y baja controlando el movimiento.', 'Evita empujar con la zona lumbar y mantén el abdomen activo durante todo el recorrido.']::text[], 'principiante', 'Fortalece glúteos e isquiotibiales y mejora la extensión de cadera con apoyo inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2200'),
('826fe220-d69a-55d4-bc37-1f6f3bf8ed23', 'Masaje del iliopsoas', ARRAY['Túmbate boca abajo con el rodillo colocado en la parte baja del abdomen, junto a la cadera.', 'Apoya el peso de forma progresiva y mantén una respiración lenta y profunda.', 'Rueda con movimientos muy cortos sobre la zona y mueve la pierna del lado trabajado.', 'Evita presionar sobre el abdomen alto o las costillas y detente si notas dolor punzante.']::text[], 'principiante', 'Libera el flexor de la cadera y alivia la tensión lumbar provocada por pasar muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4599'),
('73a364c8-154b-5817-a40c-878334a35f57', 'Rodillo para rotación de espalda alta de rodillas', ARRAY['Colócate de rodillas con el rodillo en horizontal delante y apoya una mano sobre él.', 'Lleva la otra mano detrás de la cabeza y abre el codo hacia el techo girando el tronco.', 'Mantén la cadera estable y respira al abrir el pecho, sin forzar el cuello.', 'Evita girar desde la zona lumbar y vuelve despacio a la posición inicial.']::text[], 'principiante', 'Mejora la rotación torácica y la movilidad de la espalda alta para press y remo más seguros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5388'),
('7db6bb64-ba00-5e47-8cf3-bd492bbf8ca8', 'Masaje con rodillo en el dorsal ancho', ARRAY['Túmbate de lado con el rodillo bajo la axila y el costado de la espalda.', 'Extiende el brazo por encima de la cabeza y rueda despacio desde la axila hacia la cintura.', 'Detente en los puntos tensos y respira profundo mientras mantienes la presión.', 'Evita presionar sobre las costillas flotantes y cambia de lado al terminar.']::text[], 'principiante', 'Relaja el dorsal y mejora la movilidad del hombro para dominadas, jalones y press.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2949'),
('4a1c482e-484f-58cb-8948-d4f9ef89fe6e', 'Rodillo para zona lumbar lateral acostado en el suelo', ARRAY['Túmbate de lado con el rodillo bajo la zona lumbar, ligeramente hacia el costado.', 'Apoya el antebrazo en el suelo y carga el peso de forma progresiva sobre la zona.', 'Rueda despacio arriba y abajo con movimientos cortos y controlados.', 'Evita presionar directamente sobre las vértebras y detente si notas dolor o hormigueo.']::text[], 'principiante', 'Descarga la musculatura lateral de la espalda baja y mejora la movilidad de la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5383'),
('ab236a46-f6db-5263-ace6-d2ea8b9c328b', 'Rodillo para espalda media en el suelo', ARRAY['Coloca el rodillo perpendicular a la columna a la altura de las escápulas y tumbate encima con las rodillas flexionadas.', 'Apoya los pies y eleva ligeramente la cadera para hacer presión controlada sobre la zona media.', 'Rueda despacio arriba y abajo sin llegar a las lumbares ni al cuello.', 'Respira de forma pausada y evita bloquear la respiración mientras ruedas.', 'No fuerces sobre puntos dolorosos: mantén la presión tolerable y detente si aparece dolor agudo.']::text[], 'principiante', 'Libera tensión en la espalda media y los romboides, mejorando la movilidad torácica y aliviando la rigidez tras horas de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5382'),
('d1ce2d4b-3107-581b-9ec8-1a1dd7f19fc5', 'Roll over a V sit', ARRAY['Túmbate boca arriba con los brazos estirados junto al cuerpo y las piernas juntas y elevadas.', 'Lleva las piernas por encima de la cabeza despegando la cadera del suelo de forma controlada.', 'Rueda hacia atrás y, al volver, sube el tronco y las piernas para formar una V.', 'Exhala al rodar y controla la bajada sin dejar caer el peso de golpe.', 'Evita arquear la zona lumbar al subir: mantén el abdomen activo en todo momento.']::text[], 'intermedio', 'Ejercicio de calistenia que fortalece el abdomen y los flexores de cadera, mejorando el control del core y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2572'),
('c759ff4f-5516-5798-b8fd-7e4d76f0e713', 'Rodillo para peroneos a una pierna de lado', ARRAY['Túmbate de lado con el rodillo bajo la parte externa de la pierna, desde debajo de la rodilla hasta el tobillo.', 'Apoya el peso sobre el antebrazo y la pierna de arriba para regular la presión.', 'Rueda lentamente a lo largo del peroneo sin llegar al hueso de la rodilla.', 'Mantén la respiración fluida y detente unos segundos en los puntos más tensos.', 'Evita presionar directamente sobre el peroné o zonas con dolor agudo.']::text[], 'principiante', 'Relaja los peroneos y la cara externa de la pierna, útil para prevenir molestias en tobillos y mejorar la propiocepción.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5397'),
('3c634b0c-9db8-57ef-a2cd-7a8dc9a23218', 'Estiramiento de paloma con rodillo', ARRAY['Coloca el rodillo en el suelo y adopta la postura de paloma con una pierna flexionada delante y la otra extendida atrás.', 'Apoya las manos en el suelo y desliza el rodillo bajo la cadera de la pierna flexionada.', 'Inclina el tronco hacia delante hasta notar un estiramiento suave en el glúteo.', 'Respira profundo y mantén la posición entre veinte y treinta segundos por lado.', 'No fuerces la rodilla ni rebotes: busca una tensión cómoda y constante.']::text[], 'principiante', 'Estira glúteos y flexores de cadera, liberando tensión en la cadera y mejorando la movilidad para sentarte con más comodidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5389'),
('bd64e9cd-2bb8-5fea-841e-b4163abeeaaa', 'Rodillo para hombro posterior en el suelo', ARRAY['Túmbate de lado con el rodillo bajo la parte posterior del hombro.', 'Apoya el antebrazo para controlar la presión y mantén el brazo relajado.', 'Rueda con movimientos cortos sobre el deltoides posterior sin llegar al cuello.', 'Respira con calma y evita presionar sobre la articulación directamente.', 'Detente si notas hormigueo o dolor punzante en el brazo.']::text[], 'principiante', 'Libera la parte posterior del hombro y la rotura del manguito, aliviando la tensión acumulada por malas posturas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5379'),
('ff8fff29-bbc2-5596-b143-109068889fab', 'Rodillo para cuádriceps en el suelo', ARRAY['Túmbate boca abajo con el rodillo bajo la cara externa del muslo.', 'Apoya los antebrazos y la pierna contraria para regular la presión.', 'Rueda desde encima de la rodilla hasta la cadera con movimientos lentos.', 'Mantén la respiración constante y haz pausas en los puntos tensos.', 'Evita rodar sobre la rodilla o la ingle y no apliques presión excesiva.']::text[], 'principiante', 'Relaja el vasto lateral y los cuádriceps, reduciendo tensión tras el ejercicio y mejorando la movilidad de la rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5393'),
('81f8fced-a46d-5f02-877f-4337f90a077c', 'Estiramiento de rotadores externos de cadera con pierna cruzada', ARRAY['Túmbate boca arriba con las rodillas flexionadas y cruza un tobillo sobre la rodilla contraria.', 'Lleva las manos tras el muslo de la pierna de apoyo y acerca las rodillas al pecho.', 'Mantén la zona lumbar pegada al suelo y nota el estiramiento en el glúteo.', 'Respira despacio y sostén entre veinte y treinta segundos por lado.', 'No tires del cuello ni rebotes: busca una tensión progresiva y cómoda.']::text[], 'principiante', 'Estira glúteos y extensores de cadera, aliviando la zona lumbar y mejorando la rotación de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3567'),
('0bbaa6ea-a699-519c-875a-e74d12d1a579', 'Rodillo para romboides', ARRAY['Coloca el rodillo en diagonal bajo una escápula y túmbate encima con las rodillas flexionadas.', 'Cruza los brazos o apóyalos para controlar la presión sobre la zona.', 'Rueda con movimientos pequeños sobre el romboides sin llegar al cuello.', 'Respira de forma pausada y mantén la presión tolerable.', 'Evita rodar sobre la columna directamente o zonas con dolor agudo.']::text[], 'principiante', 'Libera los romboides y la espalda alta, mejorando la postura y reduciendo la tensión entre las escápulas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5381'),
('0dfc9ed1-4052-5030-8ba4-de73d7cfe0b2', 'Rodillo para rotación posterior de hombro', ARRAY['Túmbate de lado con el rodillo bajo la parte posterior del hombro.', 'Coloca el brazo en rotación externa y apoya el antebrazo para controlar la presión.', 'Rueda despacio sobre el deltoides posterior con movimientos cortos.', 'Respira con calma y evita presionar sobre el cuello o la articulación.', 'Detente si aparece hormigueo o dolor punzante en el brazo.']::text[], 'principiante', 'Mejora la movilidad del hombro y relaja el manguito rotador, útil para prevenir molestias en el tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5380'),
('81b7c5a6-fc3d-5b05-8d85-4b412bef3a30', 'Rodillo para alcance de escápula', ARRAY['Túmbate boca arriba con el rodillo bajo la escápula y las rodillas flexionadas.', 'Extiende el brazo por encima de la cabeza buscando el alcance máximo sin dolor.', 'Rueda ligeramente el rodillo mientras el brazo se alarga y vuelve.', 'Respira profundo y coordina el movimiento con la exhalación.', 'No fuerces el hombro ni arquees la lumbar: mantén el abdomen activo.']::text[], 'principiante', 'Moviliza la escápula y la espalda alta, mejorando el control escapular y aliviando la rigidez cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5385'),
('5ac85e63-a75d-5d5d-ae04-857286a9b6b3', 'Masaje del tensor de la fascia lata', ARRAY['Túmbate de lado con el rodillo bajo la cadera, en la zona del tensor de la fascia lata.', 'Apoya el antebrazo y la pierna de arriba para regular la presión.', 'Rueda con movimientos lentos sobre la cara externa de la cadera.', 'Respira con calma y haz pausas breves en los puntos más tensos.', 'Evita presionar sobre el hueso de la cadera o zonas con dolor agudo.']::text[], 'principiante', 'Relaja el tensor de la fascia lata y la cadera, reduciendo tensión lateral y mejorando la movilidad de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4598'),
('4c6af2ed-8b34-560c-9b06-53e374482dd5', 'Rodillo para columna torácica', ARRAY['Coloca el rodillo perpendicular a la columna a la altura de las escápulas y túmbate encima.', 'Apoya los pies y eleva la cadera para hacer presión controlada sobre la zona torácica.', 'Rueda despacio arriba y abajo sin llegar a las lumbares ni al cuello.', 'Respira profundo y evita bloquear la respiración durante el movimiento.', 'No fuerces sobre puntos dolorosos: mantén una presión tolerable y constante.']::text[], 'principiante', 'Moviliza la columna torácica y la espalda alta, mejorando la extensión y aliviando la rigidez postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5384'),
('5cc3bc05-5c44-5667-82cd-b759224c7e4f', 'Rodillo para tibial anterior', ARRAY['Siéntate o túmbate con el rodillo bajo la espinilla, en la parte delantera de la pierna.', 'Apoya las manos para controlar la presión sobre el tibial anterior.', 'Rueda lentamente desde debajo de la rodilla hasta el tobillo.', 'Respira con calma y evita presionar directamente sobre el hueso.', 'Detente si notas dolor agudo o hormigueo en el pie.']::text[], 'principiante', 'Relaja el tibial anterior y la espinilla, ayudando a prevenir molestias por sobrecarga y mejorando la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5394'),
('b8562c3a-e6c6-5c92-81e9-9ea849b97511', 'Rodillo para tibial anterior a una pierna', ARRAY['Siéntate con una pierna extendida y coloca el rodillo bajo la espinilla de esa pierna.', 'Apoya las manos para regular la presión y mantén la otra pierna relajada.', 'Rueda despacio desde debajo de la rodilla hasta el tobillo.', 'Respira de forma pausada y evita presionar sobre el hueso.', 'Detente si aparece dolor agudo u hormigueo en el pie.']::text[], 'principiante', 'Libera el tibial anterior de una pierna, mejorando la movilidad del tobillo y aliviando la tensión en la espinilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5395'),
('df841556-4fa9-5a18-aa10-2a27db977d91', 'Roll up', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos extendidos por encima de la cabeza.', 'Sube los brazos y articula la columna vértebra a vértebra hasta sentarte.', 'Estira los brazos hacia delante y vuelve a bajar de forma controlada.', 'Exhala al subir e inhala al bajar, manteniendo el abdomen activo.', 'Evita tirar del cuello o usar impulso: controla cada vértebra del movimiento.']::text[], 'intermedio', 'Ejercicio de pilates que fortalece el abdomen y el core, mejorando la flexibilidad de la columna y el control postural.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2858'),
('d9711467-7f90-5fe1-80c4-134826a7d397', 'Masaje con rodillo en la espalda alta', ARRAY['Coloca el rodillo perpendicular a la columna, tumbado boca arriba con las rodillas flexionadas.', 'Apoya la espalda alta sobre el rodillo y cruza los brazos sobre el pecho.', 'Desplázate lentamente arriba y abajo para masajear la zona, sin llegar a las lumbares.', 'Respira de forma pausada y detente en los puntos más tensos unos segundos.', 'Evita arquear la zona lumbar en exceso y no ruedes directamente sobre las vértebras.']::text[], 'principiante', 'Libera tensión en la zona dorsal y los romboides, mejorando la movilidad y aliviando la rigidez tras horas de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3566'),
('4d952805-689b-57f9-a54c-f8814f924480', 'Flexión, depresión y retracción de hombro sentado a una pierna con balón', ARRAY['Siéntate sobre el balón con un pie apoyado y el otro elevado, manteniendo la espalda erguida.', 'Lleva los hombros hacia abajo y hacia atrás, juntando las escápulas sin subirlos.', 'Mantén la posición unos segundos mientras el core estabiliza el balón.', 'Respira con normalidad y evita encoger el cuello o perder el equilibrio.', 'Baja el pie y repite con la otra pierna.']::text[], 'principiante', 'Activa y estabiliza la cintura escapular trabajando el control del hombro sobre una base inestable.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '2991'),
('fabbc9e1-589e-5213-8aa3-638a761180f2', 'Estiramiento de espalda con rodillo', ARRAY['Comienza sentándote en el suelo con las piernas extendidas frente a ti.', 'Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos.', 'Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda.', 'Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda.', 'Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Relaja la musculatura paravertebral y abre la columna, aliviando la tensión acumulada en la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2208'),
('5cc1c857-bc71-53d1-8bbf-2cc7b71f780c', 'Sierra corporal con rodillo', ARRAY['Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta.', 'Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control.', 'Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el core y los abdominales con un movimiento de sierra que exige estabilidad y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2204'),
('272cdb84-0f60-5e0f-8273-dd1560d86fb6', 'Estiramiento de cadera y dorsales con rodillo', ARRAY['Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas.', 'Coloca las manos sobre el rodillo para mayor apoyo.', 'Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos.', 'Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira glúteos y dorsales, mejorando la movilidad de la cadera y la flexibilidad posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2205'),
('20d07ed2-58d2-509d-8f95-7b5aabd59c6c', 'Estiramiento de cadera con rodillo', ARRAY['Comienza sentándote en el suelo con las piernas extendidas frente a ti.', 'Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas.', 'Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte.', 'Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho.', 'Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos.', 'Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Libera tensión en glúteos y flexores de cadera, favoreciendo una movilidad más amplia.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2202'),
('073b120b-e7f7-5c15-8f17-eea0e4ff1994', 'Flexor depresor retractor de hombro sentado con rodillo', ARRAY['Siéntate sobre una superficie plana con las piernas extendidas frente a ti.', 'Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.', 'Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti.', 'Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Mejora el control escapular y la movilidad del hombro trabajando pectorales y deltoides.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2203'),
('27df7bb3-48ea-5df5-8519-faadeeba835c', 'Flexor depresor retractor de hombro sentado a una pierna con rodillo', ARRAY['Siéntate sobre una superficie plana con las piernas extendidas frente a ti.', 'Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.', 'Inclínate ligeramente hacia atrás y contrae los músculos del core.', 'Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos.', 'Baja lentamente el rodillo de nuevo hacia los muslos.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja la estabilidad del hombro y el core sobre una base inestable con una sola pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2209'),
('bfca2f01-9853-5439-80ad-4ea15d391301', 'Estiramiento lateral de dorsales con rodillo', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales.', 'Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Estira el dorsal ancho y la zona lateral del tronco, mejorando la amplitud del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2207'),
('371d7f2a-13dd-54b9-b55b-20a1d2707741', 'Rodar hacia atrás', ARRAY['Siéntate con las rodillas flexionadas y los pies apoyados, sujetando las piernas si lo necesitas.', 'Redondea la espalda y rueda hacia atrás vértebra a vértebra sin llegar a apoyar la cabeza.', 'Detente y vuelve a subir controlando el abdomen, sin usar impulso.', 'Exhala al rodar hacia atrás e inhala al subir.', 'Evita balancearte con el cuello o dejar caer el peso de golpe.']::text[], 'intermedio', 'Fortalece el abdomen y el control del core mediante un movimiento de rodamiento vertebral controlado.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2859'),
('dd9fae68-7f4e-5335-8825-7092ea82e86a', 'Puente rodante', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados a la anchura de la cadera.', 'Eleva la cadera formando una línea recta desde los hombros hasta las rodillas.', 'Rueda la columna hacia abajo lentamente, vértebra a vértebra, hasta apoyar la espalda.', 'Vuelve a subir activando glúteos y abdomen, sin arquear la lumbar.', 'Exhala al subir e inhala al bajar, evitando empujar con el cuello.']::text[], 'intermedio', 'Combina fuerza de glúteos y core con movilidad de columna en un puente dinámico y controlado.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '0679'),
('3ad634da-5742-5b53-a5b1-f70d2b249d86', 'Rollover', ARRAY['Túmbate boca arriba con los brazos estirados a los lados y las piernas juntas hacia arriba.', 'Eleva la cadera y lleva las piernas por encima de la cabeza sin cargar el cuello.', 'Detente cuando la espalda alta toque el suelo y controla el descenso vértebra a vértebra.', 'Exhala al subir las piernas e inhala al bajarlas despacio.', 'Evita usar impulso o balancearte; si notas tensión en el cuello, reduce el recorrido.']::text[], 'intermedio', 'Trabaja el abdomen y la flexibilidad de la columna llevando las piernas por encima de la cabeza con control.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2860'),
('d3dc150c-efe7-5f2f-9e27-c8cacac7cdd2', 'Abdominal en banco romano', ARRAY['Siéntate en el banco romano con los pies sujetos y las manos en el pecho o en la nuca.', 'Baja el tronco controlando el movimiento sin dejar caer el peso de golpe.', 'Sube flexionando el abdomen, sin tirar del cuello con las manos.', 'Exhala al subir e inhala al bajar, manteniendo un ritmo constante.', 'Evita arquear la espalda en exceso al final del recorrido.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con un recorrido amplio y controlado en banco inclinado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3329'),
('1acf1521-65d7-54d2-84dc-b896d1241f8d', 'Abdominal en silla romana', ARRAY['Colócate en la silla romana con los pies sujetos y la espalda apoyada.', 'Baja el tronco lentamente hasta donde controles, sin forzar la lumbar.', 'Sube flexionando el abdomen y mantén el cuello alineado con la columna.', 'Exhala al subir e inhala al bajar, sin usar impulso.', 'Evita tirar de la cabeza con las manos o balancearte para subir.']::text[], 'intermedio', 'Trabaja el abdomen y la zona lumbar con un movimiento de flexión controlado en silla inclinada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3942'),
('11a68cca-32fa-5334-bc96-638cbc2b9457', 'Trepa de cuerda', ARRAY['Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros.', 'Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti.', 'Flexiona ligeramente las rodillas y activa el core.', 'Comienza a subir por la cuerda alternando los movimientos de las manos.', 'Usa las piernas para ayudar en el movimiento ascendente.', 'Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda.', 'Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda, los antebrazos y los bíceps con un trabajo de tracción y agarre exigente.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0680'),
('1ab25e4f-3c55-5729-a211-c0ef93c2166a', 'Flexión con rotación de rodillas', ARRAY['Colócate de rodillas con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho flexionando los codos hasta rozar el suelo con el torso.', 'Empuja para subir y, al llegar arriba, gira un brazo hacia el techo abriendo el pecho.', 'Vuelve a la posición inicial y alterna el lado en cada repetición.', 'Evita hundir la cadera o girar el tronco antes de completar la subida.']::text[], 'intermedio', 'Fortalece pecho, tríceps y oblicuos mientras trabajas la estabilidad del core y la coordinación entre tren superior y rotación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0681'),
('c223aba1-52a5-5db0-b4d3-206c60f4706e', 'Estiramiento de abdomen con rotación', ARRAY['Túmbate boca arriba con los brazos extendidos y las piernas estiradas.', 'Flexiona una rodilla y llévala cruzada hacia el lado contrario del cuerpo.', 'Gira suavemente la parte superior del tronco hacia el lado de la rodilla flexionada.', 'Mantén la postura respirando despacio entre veinte y treinta segundos.', 'Evita tirar del cuello o forzar la rotación más allá de lo cómodo.']::text[], 'principiante', 'Relaja la musculatura abdominal y oblicua, mejora la movilidad de la columna y alivia tensiones tras entrenar el core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2111'),
('102ff491-6ad8-5095-87d4-f90b4851757f', 'Estiramiento de hombro con rotación', ARRAY['Coloca un brazo cruzado sobre el pecho a la altura del hombro.', 'Con la otra mano sujeta el codo y llévalo ligeramente hacia ti.', 'Gira el tronco y el hombro estirado hacia el lado contrario con suavidad.', 'Mantén la posición respirando profundo durante veinte segundos por lado.', 'Evita encoger el hombro o forzar el codo hacia abajo con brusquedad.']::text[], 'principiante', 'Libera tensión en el deltoides y la cápsula del hombro, mejorando la movilidad rotacional y previniendo molestias articulares.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1982'),
('d6e6378e-ce7e-5e28-8db9-1ecb49487aa1', 'Jacks con rotación', ARRAY['Empieza de pie con los pies juntos y los brazos pegados al cuerpo.', 'Salta abriendo piernas y brazos mientras giras el tronco hacia un lado.', 'Vuelve al centro y repite el salto girando hacia el lado contrario.', 'Mantén un ritmo constante y aterriza con las rodillas ligeramente flexionadas.', 'Evita bloquear las rodillas o girar solo con los brazos sin acompañar el tronco.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa oblicuos, gemelos y hombros con un ejercicio cardiovascular dinámico y coordinativo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0683'),
('781549ca-5b1b-5dc0-8724-be9903787efe', 'Estiramiento del manguito rotador', ARRAY['De pie, lleva un brazo cruzado delante del pecho con el codo ligeramente flexionado.', 'Con la mano libre presiona suavemente el codo hacia el cuerpo.', 'Gira el hombro estirado hacia dentro sin mover la escápula.', 'Mantén la tensión respirando despacio durante veinte segundos por lado.', 'Evita elevar el hombro o presionar el codo con demasiada fuerza.']::text[], 'principiante', 'Mejora la flexibilidad del deltoides posterior y los rotadores externos, reduciendo el riesgo de lesiones en el hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1984'),
('d0d96fd7-2aaa-5f4b-90cc-3abf7f6491f4', 'Extensión de espalda redondeada', ARRAY['Túmbate boca abajo con las manos apoyadas junto al pecho.', 'Redondea la espalda y empuja el suelo para elevar ligeramente el tronco.', 'Aprieta los glúteos y mantén la curvatura sin arquear la zona lumbar.', 'Baja despacio controlando el movimiento y repite sin rebotes.', 'Evita hiperextender el cuello o empujar con demasiada fuerza los brazos.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales mientras movilizas la zona lumbar con control, útil para fortalecer la cadena posterior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5471'),
('477c74bb-bd9c-563a-b710-70cfd54aeef4', 'Patada circular', ARRAY['Colócate de pie con una pierna adelantada y los brazos en guardia.', 'Gira la cadera y la pierna de golpeo describiendo un arco horizontal.', 'Impacta con el empeine o la espinilla a la altura de la cadera.', 'Recoge la pierna rápidamente y vuelve a la guardia.', 'Evita bloquear la rodilla o girar solo con la pierna sin acompañar la cadera.']::text[], 'intermedio', 'Trabaja glúteos, cuádriceps y core con un gesto explosivo de combate que mejora potencia, equilibrio y coordinación.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2308'),
('5dbc0c4d-1dc3-518a-844e-d83d26868a7f', 'Remo (en máquina de remo)', ARRAY['Siéntate con los pies sujetos y agarra el maneral con los brazos extendidos.', 'Empuja con las piernas y lleva el maneral hacia el abdomen.', 'Inclina ligeramente el tronco hacia atrás al final del tirón.', 'Recupera la posición inicial flexionando las rodillas y estirando los brazos.', 'Evita tirar solo con los brazos o redondear la espalda durante el recorrido.']::text[], 'principiante', 'Ejercicio cardiovascular completo que implica piernas, espalda y core, mejorando resistencia y coordinación del gesto de remada.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '1161'),
('9dfb8702-567f-5978-a543-dcfb0bc7b6c9', 'Postura del bote de remo', ARRAY['Siéntate con las piernas estiradas y la espalda recta.', 'Flexiona las rodillas y eleva los pies hasta formar una uve con el torso.', 'Extiende los brazos hacia delante paralelos al suelo.', 'Mantén la postura respirando profundo entre veinte y treinta segundos.', 'Evita redondear la espalda o encoger los hombros por la tensión.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejora el equilibrio y la concentración respiratoria en una postura de yoga activa.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4392'),
('c673e20c-04d5-5c6e-9ebd-d52cb0c293e0', 'Correr', ARRAY['Comienza de pie con los pies separados a la altura de la cadera.', 'Activa el core y mantén la parte superior del cuerpo relajada.', 'Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies.', 'Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada.', 'Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y fortalece piernas y core, siendo un ejercicio básico para la salud y la quema calórica.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0685'),
('0a550147-f100-588a-9734-71c5e01e77d6', 'Carrera con media flexión de rodillas', ARRAY['Trota unos pasos en el sitio para entrar en calor.', 'Flexiona las rodillas hasta media sentadilla manteniendo el pecho alto.', 'Empuja el suelo para volver a la posición erguida y sigue trotando.', 'Alterna el ritmo sin bloquear las rodillas en ningún momento.', 'Evita inclinar el tronco hacia delante o juntar las rodillas hacia dentro.']::text[], 'intermedio', 'Combina trabajo cardiovascular y fuerza de piernas, activando cuádriceps, glúteos y gemelos en un gesto dinámico y funcional.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3271'),
('8989351f-fb58-5719-8739-a9770b0f36a5', 'Carrera con salto', ARRAY['Trota suavemente en el sitio para coger ritmo.', 'Da un salto vertical impulsándote con ambos pies.', 'Aterriza con las rodillas ligeramente flexionadas y el torso erguido.', 'Encadena el salto con la carrera manteniendo un ritmo constante.', 'Evita aterrizar con las piernas rígidas o hacer ruido al caer.']::text[], 'intermedio', 'Aumenta la frecuencia cardíaca y la potencia de piernas, trabajando cuádriceps, gemelos y glúteos con un gesto explosivo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3269'),
('752eebbb-e3d3-5bd3-b82e-8f259ee4c2f8', 'Carrera con salto de tijera', ARRAY['Trota en el sitio con los brazos relajados.', 'Salta abriendo piernas y brazos en tijera.', 'Cierra el salto volviendo a la posición inicial.', 'Mantén un ritmo constante y aterriza con las rodillas flexionadas.', 'Evita encoger los hombros o perder el control del tronco durante el salto.']::text[], 'intermedio', 'Ejercicio cardiovascular que activa gemelos, hombros y glúteos, mejorando la coordinación y la resistencia en intervalos dinámicos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3270'),
('2af52639-0a73-5495-9061-d5af422d9feb', 'Carrera con salto de media sentadilla', ARRAY['Trota unos pasos para activar el cuerpo.', 'Flexiona las rodillas hasta media sentadilla y salta hacia arriba.', 'Aterriza suavemente con las rodillas alineadas con los pies.', 'Encadena el salto con la carrera manteniendo el ritmo.', 'Evita juntar las rodillas hacia dentro o aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Mejora la potencia y la resistencia cardiovascular, implicando cuádriceps, glúteos y gemelos en un gesto explosivo y funcional.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3272'),
('02c7e51e-e1ee-562a-b554-90ae564841b1', 'Correr en cinta', ARRAY['Sube a la cinta y colócate en el centro con la mirada al frente.', 'Empieza caminando y aumenta la velocidad progresivamente.', 'Corre con pasos cortos y apoyando el pie bajo el cuerpo.', 'Mantén los brazos relajados y la respiración constante.', 'Evita agarrarte a las barandillas o mirar hacia abajo durante la carrera.']::text[], 'principiante', 'Trabajo cardiovascular constante que fortalece piernas y glúteos, útil para mejorar resistencia y controlar el ritmo de carrera.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2197'),
('e6e6a91c-67d7-5df7-bf0b-10a62af763bf', 'Estiramiento del corredor', ARRAY['Ponte de pie con los pies separados a la altura de la cadera.', 'Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.', 'Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.', 'Coloca las manos sobre el muslo derecho para apoyarte.', 'Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.']::text[], 'principiante', 'Estira isquiotibiales, gemelos y cuádriceps en posición de zancada, aliviando la tensión tras correr.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1585'),
('3c2c98c4-b54b-5a6e-8e02-1de1c8704692', 'Corte con giro ruso', ARRAY['Colócate de pie con los pies a la anchura de las caderas y las manos juntas delante del pecho.', 'Da un paso y baja ligeramente las rodillas mientras giras el tronco hacia un lado con control.', 'Vuelve al centro y repite hacia el otro lado manteniendo el abdomen apretado.', 'Exhala en cada giro y evita mover solo los brazos: la rotación nace del tronco.', 'No dejes que las rodillas se hundan hacia dentro ni que la espalda se redondee.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con rotación dinámica, mejorando la fuerza del core y la coordinación entre tren superior e inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5938'),
('e63a9af8-e81c-556d-867c-1893b9589c41', 'Giro ruso con manos en el pecho', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los talones apoyados, manos cruzadas sobre el pecho.', 'Inclina el tronco ligeramente hacia atrás manteniendo la espalda recta y el pecho alto.', 'Gira el tronco hacia un lado y luego hacia el otro sin mover las caderas.', 'Exhala en cada rotación y evita tirar del cuello con las manos.', 'Si notas molestias lumbares, reduce la inclinación o apoya los pies más cerca del cuerpo.']::text[], 'intermedio', 'Fortalece abdomen, oblicuos y zona lumbar con rotaciones controladas, mejorando la estabilidad del core y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4646'),
('36c60e30-5a20-5072-90af-c054848245ad', 'Sentadilla con talones elevados y barra de seguridad', ARRAY['Coloca la barra de seguridad sobre los hombros y apoya los talones en una cuña o disco para elevarlos.', 'Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando rodillas y caderas manteniendo el pecho alto y la espalda neutra.', 'Empuja con los talones para subir y exhala al final del recorrido.', 'Evita que las rodillas se metan hacia dentro y no pierdas la curvatura lumbar al bajar.']::text[], 'intermedio', 'Potencia cuádriceps y glúteos con mayor rango de movimiento, útil para ganar fuerza y profundidad en la sentadilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4219'),
('df051626-c716-5acd-bb71-6a91ca7199d7', 'Buenos días con barra de seguridad', ARRAY['Coloca la barra de seguridad sobre los trapecios con los pies a la anchura de las caderas.', 'Con las rodillas ligeramente flexionadas, lleva las caderas hacia atrás inclinando el tronco.', 'Baja hasta notar tensión en los isquiotibiales sin redondear la espalda.', 'Sube empujando las caderas hacia delante y aprieta los glúteos arriba.', 'Evita arquear en exceso la lumbar al final del movimiento.']::text[], 'intermedio', 'Refuerza isquiotibiales, glúteos y zona lumbar mediante la bisagra de cadera, mejorando la fuerza posterior y la técnica del peso muerto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5911'),
('9c1aa1d6-db57-5ec6-bea9-2f4ae3a754e1', 'Postura del sabio Marichi I', ARRAY['Siéntate con una pierna estirada y flexiona la otra con el pie apoyado junto a la rodilla contraria.', 'Alarga la columna y gira el tronco hacia el lado de la rodilla flexionada.', 'Pasa el brazo por fuera de la rodilla y engancha las manos detrás de la espalda si puedes.', 'Respira profundo y mantén la torsión sin forzar el cuello.', 'Evita redondear la espalda: crece desde la coronilla en cada inhalación.']::text[], 'intermedio', 'Estira la columna y los isquiotibiales con una torsión sentada que mejora la movilidad espinal y la digestión.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6295'),
('f1c9fc10-f076-55d5-aae9-0beac29e3667', 'Zancada con press sobre la cabeza con balón medicinal', ARRAY['Sujeta el balón medicinal a la altura del pecho con los pies juntos.', 'Da un paso al frente y baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Desde la posición baja, empuja con la pierna delantera y eleva el balón sobre la cabeza.', 'Baja el balón al pecho y vuelve a la posición inicial para cambiar de pierna.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Combina piernas y hombros en un ejercicio global que mejora la coordinación, el equilibrio y la potencia del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1692'),
('dce735c7-e72a-5305-b180-c122c7f4f482', 'Lanzamiento de saco sobre el hombro', ARRAY['Coloca el saco de arena delante de ti con los pies a la anchura de los hombros.', 'Agarra el saco y realiza una bisagra de cadera manteniendo la espalda recta.', 'Tira del saco hacia arriba y llévalo sobre un hombro con un movimiento explosivo.', 'Deja que caiga al suelo y prepárate para repetir alternando hombros.', 'Evita redondear la espalda al recoger el saco: usa las piernas y las caderas.']::text[], 'intermedio', 'Ejercicio explosivo que trabaja glúteos, isquiotibiales y core, mejorando la potencia y la coordinación de todo el cuerpo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '10427'),
('e4fc2c2b-0942-5689-8493-bbcf7bd6fcd5', 'Sierra', ARRAY['Siéntate con las piernas abiertas y los brazos extendidos a la altura de los hombros.', 'Alarga la columna y gira el tronco hacia un lado llevando la mano hacia el pie contrario.', 'Realiza un movimiento de sierra con el torso mientras exhalas y vacías el aire.', 'Vuelve al centro inhalando y repite hacia el otro lado.', 'Evita redondear la espalda: mantén el pecho alto y el abdomen activo.']::text[], 'intermedio', 'Ejercicio de pilates que moviliza la columna y estira isquiotibiales y oblicuos, mejorando el control del core y la respiración.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2861'),
('e3ec4cd7-6b19-56ee-aa7e-690979eba5ca', 'Fondos escapulares', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas.', 'Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa trapecios y romboides con pequeños movimientos de escápulas en apoyo, mejorando el control del hombro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3012'),
('46f397e7-0921-58c4-8f7b-3399ace0b25a', 'Elevación y depresión de escápulas', ARRAY['Colócate de pie o sentado con los brazos relajados y la espalda recta.', 'Sube los hombros hacia las orejas como si quisieras tocarlas.', 'Baja los hombros con control alejándolos de las orejas.', 'Respira de forma fluida y evita encoger el cuello o sacar el pecho.', 'Realiza el movimiento lento y sin impulso para notar la escápula.']::text[], 'principiante', 'Mejora la movilidad y el control de los trapecios y la cintura escapular, útil para la postura y la salud del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3130'),
('921a774a-579b-57a3-8424-c65f6b572940', 'Retracción y protracción de escápulas', ARRAY['Colócate de pie o sentado con los brazos extendidos al frente a la altura de los hombros.', 'Junta las escápulas hacia atrás sin mover los codos.', 'Separa las escápulas hacia delante redondeando ligeramente la espalda alta.', 'Mantén el cuello relajado y respira con normalidad.', 'Evita encoger los hombros o mover los brazos durante el recorrido.']::text[], 'principiante', 'Trabaja la movilidad de la cintura escapular y la musculatura de la espalda alta, mejorando la postura y la estabilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3129'),
('d05521f8-d741-5665-807f-f5e510acbc2a', 'Balanceo en dominada escapular', ARRAY['Cuélgate de la barra con las palmas hacia delante y los brazos extendidos.', 'Activa las escápulas bajándolas y llevando el pecho hacia la barra.', 'Balancea el cuerpo suavemente mientras mantienes el control escapular.', 'Evita balancearte con impulso de piernas o perder la tensión en los hombros.', 'Respira de forma constante y baja con control al terminar.']::text[], 'intermedio', 'Fortalece dorsales y espalda alta con un balanceo controlado, mejorando el control escapular y la fuerza de agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10948'),
('a2136572-fefc-5ea1-a90c-fbe7acf541d9', 'Dominada escapular', ARRAY['Cuélgate de la barra con las palmas hacia delante y los brazos estirados.', 'Sin flexionar los codos, baja las escápulas y lleva el pecho ligeramente hacia arriba.', 'Mantén un segundo arriba apretando la espalda y baja con control.', 'Evita encoger los hombros hacia las orejas o usar impulso.', 'Respira exhalando al activar y inhalando al volver a colgarte.']::text[], 'intermedio', 'Activa dorsales y espalda alta desde el colgado, mejorando la estabilidad escapular y la base para dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11015'),
('543b9ae8-cd58-53af-ae52-3cd9eb46cd50', 'Deslizamiento de escápulas en la pared', ARRAY['Apoya la espalda y la cabeza en la pared con los brazos en forma de uve.', 'Desliza los brazos hacia arriba manteniendo las muñecas y los codos en contacto con la pared.', 'Baja despacio hasta la posición inicial controlando el movimiento.', 'Evita arquear la zona lumbar: mantén las costillas abajo y el abdomen firme.']::text[], 'principiante', 'Activa el serrato y los estabilizadores de la escápula para mejorar la movilidad y la postura del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2945'),
('246edd48-1901-5389-b168-03702d7c2100', 'Deslizamiento del nervio ciático', ARRAY['Túmbate boca arriba con una pierna estirada y la otra flexionada.', 'Lleva la rodilla hacia el pecho y extiende la pierna despacio mientras subes la punta del pie.', 'Alterna flexión y extensión del tobillo sin forzar el estiramiento.', 'Detente si notas hormigueo o dolor punzante y reduce la amplitud.']::text[], 'principiante', 'Moviliza el nervio ciático y estira la cadena posterior para aliviar tensión en isquios y zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11652'),
('2477afa7-7164-5e20-af4e-20aa76e991b2', 'Tijeras', ARRAY['Túmbate boca arriba con las piernas estiradas y las manos bajo la zona lumbar.', 'Eleva ligeramente el tronco y las piernas del suelo.', 'Cruza las piernas alternando arriba y abajo con movimientos cortos y controlados.', 'Mantén la zona lumbar pegada al suelo y respira de forma continua.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con un movimiento alterno que también activa isquios.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2862'),
('4845c5b5-02ec-5ad8-aa41-0ba4ec60755e', 'Estiramiento del escorpión', ARRAY['Túmbate boca abajo con los brazos extendidos en cruz.', 'Lleva una pierna estirada por detrás hacia el lado contrario buscando el suelo.', 'Gira la cabeza hacia el lado opuesto y mantén la posición sin forzar.', 'Vuelve despacio al centro y cambia de lado.']::text[], 'principiante', 'Estira el abdomen, los oblicuos y los flexores de cadera mientras moviliza la columna y la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4631'),
('0d7378d5-6e90-58ea-8c74-9a2288935990', 'Foca', ARRAY['Siéntate sobre los talones con el tronco erguido y las manos en el suelo.', 'Eleva el pecho y arquea ligeramente la espalda mientras llevas la cadera hacia delante.', 'Balancea el cuerpo adelante y atrás manteniendo el abdomen activo.', 'Evita forzar la zona lumbar: el movimiento debe ser suave y controlado.']::text[], 'intermedio', 'Fortalece el core y la zona lumbar con un movimiento de balanceo que también estira los flexores de cadera.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2877'),
('25ce3022-e865-5761-94b1-f415c1d1d7fb', 'Flexión de foca', ARRAY['Túmbate boca abajo con las manos bajo los hombros y los codos pegados al cuerpo.', 'Empuja el suelo para elevar el pecho manteniendo la cadera en el suelo.', 'Baja despacio hasta la posición inicial sin perder la alineación.', 'Evita encoger los hombros y mantén el cuello en línea con la columna.']::text[], 'intermedio', 'Fortalece pectorales, tríceps y hombros con una variante de flexión que también trabaja la espalda alta.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2944'),
('ded1b76e-8ac9-575d-80e0-75fc31b2cf90', 'Abdominal sentado con ocho piernas', ARRAY['Siéntate con las rodillas flexionadas y el tronco ligeramente inclinado atrás.', 'Eleva los pies y dibuja un ocho con las piernas de forma controlada.', 'Mantén el abdomen firme y la espalda recta durante todo el recorrido.', 'Evita tirar del cuello y respira de forma constante.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con un patrón de piernas en forma de ocho que mejora la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4022'),
('ad200770-5da4-5ebc-8064-cee2e75f36fe', 'Estiramiento dinámico alterno de pecho sentado', ARRAY['Siéntate erguido en la silla con los pies apoyados en el suelo.', 'Lleva un brazo hacia atrás abriendo el pecho y alterna con el otro.', 'Mantén el movimiento fluido y sin rebotes bruscos.', 'Evita encoger los hombros y mantén la respiración relajada.']::text[], 'principiante', 'Moviliza pectorales y hombros con un estiramiento alterno que mejora la flexibilidad del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8615'),
('481884e8-1c95-5425-8ef2-55b9f3660342', 'Extensión alterna de rodilla sentado', ARRAY['Siéntate erguido en la silla con los pies apoyados y las rodillas en ángulo recto.', 'Extiende una pierna hasta que quede recta y mantén un segundo.', 'Baja despacio y alterna con la otra pierna.', 'Evita bloquear la rodilla con fuerza y mantén el abdomen activo.']::text[], 'intermedio', 'Fortalece los cuádriceps y estabiliza la rodilla con un ejercicio sencillo y seguro en silla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8744'),
('030dd85c-5ac8-58ea-9955-f01e974074b5', 'Cruce de brazos y pecho afuera sentado', ARRAY['Siéntate erguido en la silla y cruza los brazos delante del pecho.', 'Abre los codos hacia atrás sacando pecho sin arquear la zona lumbar.', 'Mantén el estiramiento unos segundos respirando despacio.', 'Evita subir los hombros hacia las orejas.']::text[], 'principiante', 'Estira pectorales y hombros y abre el pecho para contrarrestar posturas encorvadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11006'),
('777f5e67-d9a5-5d0f-ac89-bc494ae0609a', 'Cruce de brazos sentado', ARRAY['Siéntate erguido en la silla con la espalda apoyada.', 'Cruza los brazos delante del pecho y lleva los codos hacia el lado contrario.', 'Mantén la posición sin rebotes y respira de forma relajada.', 'Evita girar el tronco en exceso y mantén la cadera estable.']::text[], 'principiante', 'Moviliza pectorales y hombros con un cruce suave que mejora la flexibilidad del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8619'),
('876536b5-c80a-57e0-bbcf-8d80abc8fb34', 'Contracción de espalda sentado', ARRAY['Siéntate erguido con los brazos relajados y los hombros hacia atrás.', 'Junta las escápulas como si sujetaras un lápiz entre ellas.', 'Mantén la contracción dos segundos y relaja despacio.', 'Evita encoger los hombros y no arquees la zona lumbar.']::text[], 'intermedio', 'Activa la espalda alta y los romboides para mejorar la postura y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5128'),
('7793f34e-9f9b-5503-b1ab-8315d364ad57', 'Bailarina sentado', ARRAY['Siéntate erguido en la silla con el abdomen activo.', 'Eleva un brazo por encima de la cabeza y llévalo hacia el lado contrario.', 'Acompaña el movimiento con una ligera inclinación del tronco.', 'Evita forzar el cuello y mantén los hombros lejos de las orejas.']::text[], 'principiante', 'Moviliza hombros y espalda alta con un gesto elegante que mejora la coordinación y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5134'),
('90c5fcf9-bf7d-54ac-993f-0ec172b4db5a', 'Elevación de brazos tras la espalda sentado', ARRAY['Siéntate erguido con las manos entrelazadas detrás de la espalda.', 'Eleva los brazos hacia atrás sin arquear la zona lumbar.', 'Mantén la contracción un segundo y baja despacio.', 'Evita encoger los hombros y mantén el cuello relajado.']::text[], 'intermedio', 'Fortalece la espalda alta y los deltoides posteriores con un gesto que mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5133'),
('1c994c16-2a40-56c9-b9c7-5786e0448d93', 'Abducción sentado con rodillas flexionadas', ARRAY['Siéntate erguido en la silla con las rodillas flexionadas y los pies juntos.', 'Abre las rodillas hacia los lados manteniendo los pies apoyados.', 'Mantén la apertura un segundo y cierra despacio.', 'Evita inclinar el tronco y mantén el abdomen firme.']::text[], 'intermedio', 'Fortalece abductores y glúteos con un movimiento controlado que mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11048'),
('eb25a67d-1eab-50e5-a521-7069c2c2e97d', 'Abducción sentado con rodillas flexionadas y pies sin tocar el suelo', ARRAY['Siéntate en el borde de una silla y sujétate a los lados para mantener el equilibrio.', 'Separa las rodillas hacia fuera sin mover los pies del suelo y mantén la espalda recta.', 'Aguanta un segundo arriba y baja las piernas de forma controlada sin dejar caer los pies.', 'Evita arquear la espalda o encoger los hombros al abrir las rodillas.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para estabilizar la cadera y mejorar el control postural en movimientos cotidianos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11049'),
('6b6f7f7d-0b21-564d-ba0c-3dae3a9ef866', 'Estiramiento de glúteo sentado', ARRAY['Siéntate en el borde de una silla con la espalda recta y los pies apoyados.', 'Cruza un tobillo sobre la rodilla contraria formando una figura de cuatro.', 'Inclina el tronco hacia delante desde la cadera hasta notar el estiramiento en el glúteo.', 'Respira despacio y evita forzar la rodilla o redondear la espalda.']::text[], 'principiante', 'Libera tensión en glúteos y flexores de cadera, aliviando la rigidez lumbar tras muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1937'),
('f6022f0c-2665-53d8-9224-acc815c07fad', 'Estiramiento de gemelos sentado', ARRAY['Siéntate en el borde de una silla o banco con los pies planos sobre el suelo.', 'Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.', 'Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Cambia de pierna y repite el estiramiento.']::text[], 'principiante', 'Relaja la musculatura de la pantorrilla y mejora la flexibilidad del tobillo para caminar y correr con soltura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1390'),
('95d9aca2-3943-563f-8e0c-d7c561f2acf7', 'Apertura de pecho sentado tipo almeja', ARRAY['Siéntate erguido en una silla con los brazos relajados a los lados.', 'Junta las escápulas y abre los codos hacia atrás como si abrieras una almeja.', 'Mantén la apertura unos segundos respirando profundo y sin sacar las costillas.', 'Evita echar el cuello hacia delante o arquear en exceso la zona lumbar.']::text[], 'principiante', 'Abre el pecho y moviliza los hombros, compensando la postura encorvada típica del estudio y las pantallas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5078'),
('99682cb7-35f1-5525-a1c6-9edd8ad681e3', 'Press de pecho sentado en silla', ARRAY['Siéntate erguido en una silla con los pies apoyados y los codos a la altura del pecho.', 'Empuja las manos hacia delante como si empujaras una pared invisible.', 'Extiende los brazos sin bloquear los codos y vuelve despacio al pecho.', 'Evita encoger los hombros o adelantar la cabeza durante el empuje.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros para empujar con fuerza y estabilidad desde una posición segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8618'),
('ae76a109-2443-537c-92aa-19b6acbc4a6b', 'Dominada supina sentado', ARRAY['Siéntate frente a una barra baja o agarra una superficie estable con las palmas hacia ti.', 'Tira del cuerpo hacia arriba flexionando los codos y llevando el pecho hacia las manos.', 'Baja de forma controlada hasta estirar los brazos sin perder la tensión.', 'Evita encoger los hombros o usar impulso del tronco para subir.']::text[], 'intermedio', 'Activa dorsales y bíceps con un tirón vertical adaptado, útil para progresar hacia dominadas completas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4781'),
('fe5256bc-f8b8-5fc3-9588-4d52ddef16cf', 'Dominada comando sentado', ARRAY['Siéntate frente a una barra o agarre estable con una mano delante y otra detrás.', 'Tira del cuerpo hacia un lado llevando el hombro hacia la mano que tira.', 'Baja despacio y alterna el lado en la siguiente repetición.', 'Evita girar el tronco con brusquedad o perder la alineación de la espalda.']::text[], 'intermedio', 'Refuerza dorsales y core con un tirón asimétrico que mejora la fuerza de agarre y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4782'),
('6e468631-45b3-5ea2-8b85-842a992f683f', 'Puñetazo cruzado sentado en silla', ARRAY['Siéntate erguido con los pies apoyados y las manos cerca del pecho.', 'Lanza un puñetazo cruzado hacia delante girando ligeramente el tronco.', 'Recoge la mano despacio y alterna el lado manteniendo la respiración.', 'Evita bloquear el codo o girar la cadera en exceso al golpear.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa pecho, hombros y oblicuos con un gesto explosivo y controlado.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '8424'),
('f716d543-8683-5147-8cb5-a1315d7aa052', 'Press de pecho declinado sentado en silla', ARRAY['Siéntate erguido con los codos a la altura del pecho y las manos juntas.', 'Empuja las manos hacia delante y ligeramente hacia abajo sin bloquear los codos.', 'Vuelve despacio al pecho manteniendo los hombros bajos y estables.', 'Evita adelantar la cabeza o perder la postura erguida al empujar.']::text[], 'intermedio', 'Enfoca la porción inferior del pectoral y los tríceps con un empuje descendente que protege el hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8620'),
('5e0ef5e5-7f05-55ef-a783-4bb0f3495862', 'Apertura de pecho con codos sentado en silla', ARRAY['Siéntate erguido con los codos flexionados a la altura de los hombros.', 'Junta los antebrazos delante del pecho y ábrelos hacia fuera con control.', 'Aprieta las escápulas al abrir y vuelve despacio al centro.', 'Evita subir los hombros o arquear la espalda durante la apertura.']::text[], 'intermedio', 'Trabaja pectorales y hombros con un movimiento de apertura que mejora la fuerza y la movilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8616'),
('9c12ace6-3509-5abc-852a-1e82ecfef5bc', 'Rotación externa sentado en silla', ARRAY['Siéntate erguido con los codos pegados al cuerpo y flexionados a 90 grados.', 'Gira los antebrazos hacia fuera sin separar los codos del torso.', 'Mantén un segundo al final y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o usar impulso para girar los brazos.']::text[], 'principiante', 'Fortalece el manguito rotador y los deltoides posteriores para estabilizar el hombro y prevenir molestias.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '8617'),
('3f28a525-afa0-594a-a587-c15a0cfeb96d', 'Círculo de pies sentado', ARRAY['Siéntate con los pies descalzos o con calzado ligero y las piernas relajadas.', 'Dibuja círculos lentos con el pie en un sentido durante varias repeticiones.', 'Cambia de sentido y repite con el otro pie manteniendo la respiración.', 'Evita hacer círculos rápidos o forzar el tobillo hasta el dolor.']::text[], 'principiante', 'Moviliza tobillos y pies para mejorar la circulación y la flexibilidad tras largos periodos de estudio sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10909'),
('117079ad-c342-5889-a9bc-099cc152dcf6', 'Flexión y extensión de cuello sentado', ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Baja la barbilla hacia el pecho despacio hasta notar el estiramiento.', 'Vuelve al centro y extiende suavemente la cabeza hacia atrás sin forzar.', 'Evita hacer movimientos bruscos o llevar el cuello más allá del rango cómodo.']::text[], 'principiante', 'Moviliza el cuello y relaja elevador de la escápula y trapecios para aliviar la tensión cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3441'),
('c7dbb614-356a-56dd-80b6-f45e78155ce1', 'Patada de aleteo sentado', ARRAY['Siéntate en el borde de una silla con la espalda recta y las manos sujetas a los lados.', 'Eleva ligeramente las piernas y alterna patadas pequeñas y rápidas.', 'Mantén el abdomen apretado y respira de forma constante.', 'Evita arquear la zona lumbar o dejar caer las piernas sin control.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un movimiento rítmico que mejora el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3962'),
('48c6473c-2201-5ca5-a4c7-9d38ea12e974', 'Deslizamiento de pies sentado', ARRAY['Siéntate con los pies apoyados y las piernas relajadas.', 'Desliza un pie hacia delante manteniendo el talón en el suelo.', 'Vuelve despacio a la posición inicial y alterna los pies.', 'Evita levantar el talón o hacer el movimiento con prisa.']::text[], 'principiante', 'Mejora la movilidad de tobillo y la activación de gemelos con un gesto suave y controlado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5481'),
('e9bd5c61-ff60-5c95-91c5-c958ca3fbe14', 'Estiramiento de antebrazos sentado', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Extiende un brazo al frente con la palma hacia arriba y estira los dedos hacia el suelo.', 'Con la otra mano, tira suavemente de los dedos hacia ti hasta notar el estiramiento.', 'Mantén la posición sin rebotes y respira despacio durante veinte o treinta segundos.', 'Evita forzar la muñeca hacia atrás; el estiramiento debe ser cómodo, nunca doloroso.']::text[], 'principiante', 'Relaja los flexores y extensores de la muñeca, alivia la tensión por teclado y mejora la movilidad de antebrazo y mano.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6763'),
('1f3a211b-bdae-58dd-93aa-9953a7a1224c', 'Estiramiento con flexión hacia delante sentado en silla', ARRAY['Siéntate en el borde de la silla con los pies apoyados y la espalda recta.', 'Inclina el tronco hacia delante desde la cadera, no desde la espalda.', 'Deja caer los brazos hacia los pies hasta notar tensión en la parte posterior del muslo.', 'Respira despacio y mantén entre veinte y treinta segundos sin rebotar.', 'Evita curvar la espalda en exceso; si molesta la lumbar, reduce la inclinación.']::text[], 'principiante', 'Estira los isquiotibiales y la zona lumbar, reduce la rigidez tras muchas horas sentado y mejora la flexibilidad posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8433'),
('5e0e7186-117e-5e07-8d64-a052f89e74ee', 'Enrollado hacia delante sentado en silla', ARRAY['Siéntate en el borde de la silla con la espalda recta y las manos en la nuca.', 'Enrolla la columna vértebra a vértebra hacia delante mientras espiras.', 'Baja solo hasta donde controles y siente cómo se activa el abdomen.', 'Sube despacio desenrollando la espalda y sin tirar del cuello con las manos.', 'Evita usar impulso; el movimiento debe ser lento y controlado.']::text[], 'intermedio', 'Trabaja el abdomen y la zona baja del core con un movimiento controlado que también moviliza la columna y los flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8434'),
('5b50e0a1-2f02-5695-b3bf-672f4cd05c37', 'Abdominal de rana de media a completa sentado', ARRAY['Siéntate con las plantas de los pies juntas y las rodillas abiertas hacia los lados.', 'Lleva las manos a la nuca y mantén el pecho abierto.', 'Sube el tronco hasta medio recorrido y luego completa la incorporación espirando.', 'Baja controlando el descenso sin dejarte caer de golpe.', 'Evita tirar del cuello; el impulso debe salir del abdomen.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con una variante que implica también la zona interna del muslo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7255'),
('ee59fb2d-3043-5750-bc63-d294aab89ef0', 'Estiramiento de glúteos sentado', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo.', 'Coloca la mano derecha en el suelo detrás de ti para apoyarte.', 'Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento.', 'Mantén el estiramiento durante 30 segundos a 1 minuto.', 'Cambia de lado y repite.']::text[], 'principiante', 'Libera tensión en glúteos y parte posterior del muslo, muy útil tras estar mucho tiempo sentado estudiando.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1424'),
('aa06827d-995c-52ce-943c-6d603d4ed67d', 'Estiramiento de ingle sentado', ARRAY['Siéntate en el suelo con las plantas de los pies juntas y las rodillas hacia los lados.', 'Sujeta los pies con las manos y mantén la espalda recta.', 'Acerca los talones al cuerpo hasta notar el estiramiento en la ingle.', 'Presiona suavemente las rodillas hacia el suelo sin forzar.', 'Respira despacio y evita rebotar o empujar con dolor.']::text[], 'principiante', 'Abre la zona de los aductores y la ingle, mejora la movilidad de cadera y previene molestias por posturas mantenidas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1169'),
('dad5c6db-5768-5c67-9dd4-b3de120e4448', 'Estiramiento de isquiotibiales sentado en silla', ARRAY['Siéntate en el borde de la silla y extiende una pierna al frente con el talón apoyado.', 'Mantén la espalda recta y la otra planta en el suelo.', 'Inclina el tronco hacia la pierna extendida hasta notar tensión detrás del muslo.', 'Mantén la posición respirando despacio unos veinte o treinta segundos.', 'Evita curvar la espalda; inclínate desde la cadera.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla, aliviando la rigidez típica de largas sesiones de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10462'),
('0cbda6e6-f753-5a1b-9073-f3a41267842e', 'Estiramiento de isquiotibiales sentado con silla', ARRAY['Siéntate en el borde de la silla con una pierna extendida y el talón en el suelo.', 'Flexiona ligeramente la rodilla de la pierna estirada para proteger la zona lumbar.', 'Lleva el pecho hacia el pie manteniendo la espalda larga.', 'Respira de forma pausada y mantén el estiramiento sin rebotes.', 'Evita bloquear la rodilla o forzar más allá de una tensión cómoda.']::text[], 'principiante', 'Mejora la flexibilidad de isquiotibiales y gemelos usando la silla como apoyo para una postura segura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7310'),
('373cd1da-3cd4-505f-bf56-58d18b03f1d3', 'Rotación externa de cadera sentado', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Abre una rodilla hacia fuera manteniendo el pie en el suelo.', 'Haz el movimiento de forma lenta y controlada hasta donde llegues sin dolor.', 'Vuelve a la posición inicial y repite alternando lados.', 'Evita compensar girando el tronco o levantando la cadera.']::text[], 'principiante', 'Gana movilidad en la cadera y activa los rotadores externos, mejorando la mecánica de sentadillas y zancadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6749'),
('ff12543e-0a6e-55e8-9c40-bef35412cd19', 'Estiramiento de rotadores externos y extensores de cadera sentado', ARRAY['Siéntate en el suelo con una pierna extendida y la otra cruzada por encima.', 'Gira el tronco hacia el lado de la pierna cruzada apoyando la mano detrás.', 'Mantén la espalda recta y siente el estiramiento en el glúteo.', 'Respira despacio y aguanta entre veinte y treinta segundos por lado.', 'Evita tirar con fuerza del cuello o girar de golpe.']::text[], 'principiante', 'Estira glúteos y extensores de cadera, alivia la tensión lumbar y mejora la rotación de la articulación.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1918'),
('bb996259-e2ac-52f6-92df-6ab94d67726c', 'Estiramiento de cadera sentado con la pierna contraria desde atrás', ARRAY['Siéntate en el suelo con una pierna extendida al frente.', 'Cruza la otra pierna por encima y apoya el pie en el suelo.', 'Abraza la rodilla cruzada y llévala hacia el pecho sin curvar la espalda.', 'Mantén la posición respirando despacio unos veinte o treinta segundos.', 'Evita forzar la rodilla o rebotar para ganar más rango.']::text[], 'principiante', 'Estira glúteos y flexores de cadera en una posición sentada que también libera la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1919'),
('a31cc392-deff-5895-843a-ca8d148db298', 'Estiramiento de cadera sentado con pierna ligeramente flexionada', ARRAY['Siéntate en el suelo con una pierna extendida y la otra ligeramente flexionada.', 'Inclina el tronco hacia la pierna extendida manteniendo la espalda larga.', 'Lleva el pecho hacia el muslo sin redondear la espalda.', 'Respira de forma pausada y mantén el estiramiento sin rebotes.', 'Evita forzar la rodilla o buscar dolor en la parte posterior del muslo.']::text[], 'principiante', 'Relaja glúteos e isquiotibiales con una variante suave que respeta la zona lumbar y mejora la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1938'),
('5792dfa3-2286-54ca-ab27-e7f53bad9e45', 'Elevación de piernas dentro y fuera sentado en el suelo', ARRAY['Siéntate en el suelo con las piernas extendidas y las manos apoyadas detrás.', 'Eleva las piernas y ábrelas hacia los lados de forma controlada.', 'Júntalas de nuevo al centro sin tocar el suelo con los pies.', 'Mantén el abdomen activo y espira al cerrar las piernas.', 'Evita arquear la lumbar; si molesta, flexiona un poco las rodillas.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera con un trabajo de core que también implica la zona interna del muslo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3509'),
('bd4a36c0-9ff5-5583-b36e-643acf98b580', 'Press de pecho inclinado sentado en silla', ARRAY['Siéntate en la silla con la espalda apoyada y las manos a la altura del pecho.', 'Empuja las manos hacia delante y arriba como si empujaras una pared invisible.', 'Extiende los brazos sin bloquear los codos y espira al empujar.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita encoger los hombros o arquear la espalda al empujar.']::text[], 'intermedio', 'Trabaja el pectoral superior, los tríceps y los hombros con un empuje que puedes hacer en casa sin material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8622'),
('add4dfb9-a22b-58d8-996d-e9ce35f0316b', 'Dominada isométrica sentado', ARRAY['Siéntate con la espalda recta y los brazos elevados por encima de la cabeza.', 'Imagina que agarras una barra y tira de los codos hacia abajo sin moverlos.', 'Mantén la tensión en la espalda y los omóplatos durante diez o veinte segundos.', 'Respira de forma continua sin aguantar la respiración.', 'Evita encoger el cuello o subir los hombros hacia las orejas.']::text[], 'intermedio', 'Activa la espalda y los bíceps manteniendo una tensión estática que mejora la fuerza de agarre y la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9317'),
('37a6a078-ca97-5d4c-a8bd-e00062e4da5e', 'Bajada de rodilla sentado', ARRAY['Siéntate en el suelo con la espalda recta y las plantas de los pies juntas.', 'Deja caer las rodillas hacia el suelo de forma lenta y controlada.', 'Mantén la posición entre quince y treinta segundos respirando con calma.', 'Evita forzar presionando con las manos si notas dolor en la ingle.']::text[], 'principiante', 'Moviliza aductores y flexores de cadera para ganar rango en la apertura de piernas y aliviar tensión en la ingle.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11654'),
('147f8691-6a64-564c-bf6e-525603600e95', 'Estiramiento de isquiotibiales y aductores sentado', ARRAY['Siéntate con una pierna estirada y la otra doblada con la planta apoyada en el muslo.', 'Inclina el tronco hacia la pierna estirada manteniendo la espalda larga.', 'Abre ligeramente la punta del pie para notar más el estiramiento.', 'Respira despacio y evita rebotar o curvar la zona lumbar.']::text[], 'principiante', 'Alarga la parte posterior del muslo y la cara interna de la pierna para mejorar la flexibilidad y reducir tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1914'),
('25267217-499f-5e36-9404-0f7cbfc14e13', 'Estiramiento de isquiotibiales sentado', ARRAY['Siéntate con una pierna estirada y la otra flexionada hacia dentro.', 'Lleva el pecho hacia la rodilla estirada sin redondear la espalda.', 'Mantén la posición veinte o treinta segundos respirando con calma.', 'Evita tirar con fuerza de la punta del pie para no sobrecargar el gemelo.']::text[], 'principiante', 'Estira la parte posterior del muslo y los gemelos para mejorar la flexibilidad y prevenir molestias en la espalda baja.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1915'),
('6a268d83-444c-5271-b242-f1268d0b66d7', 'Estiramiento de glúteo con rotación sentado', ARRAY['Siéntate con una rodilla flexionada y el pie apoyado por fuera de la otra pierna.', 'Gira el tronco hacia el lado de la rodilla elevada apoyando la mano detrás.', 'Mantén la pelvis estable y alarga la columna al girar.', 'Respira profundo y evita forzar el giro hasta sentir dolor.']::text[], 'principiante', 'Libera tensión en glúteos y zona lumbar mediante una rotación de tronco que también activa los oblicuos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1934'),
('f9d7bde3-85ba-5d01-8bcc-996b5f5e89d5', 'Estiramiento de glúteo con rodilla arriba sentado', ARRAY['Siéntate con la espalda recta y una rodilla elevada hacia el pecho.', 'Gira el tronco hacia el lado de la rodilla elevada sin mover las piernas.', 'Mantén el estiramiento quince o veinte segundos respirando despacio.', 'Evita encorvar la espalda o tirar de la rodilla con demasiada fuerza.']::text[], 'principiante', 'Relaja glúteos y oblicuos con una rotación suave que mejora la movilidad de la cadera y la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1933'),
('9a3628c7-8fa5-54ab-b0f0-09e7f232f1b0', 'Inclinación hacia atrás en silla', ARRAY['Siéntate en el borde de la silla con los pies apoyados y la espalda recta.', 'Inclina el tronco hacia atrás lentamente manteniendo el abdomen firme.', 'Vuelve a la posición inicial sin usar impulso y exhala al subir.', 'Evita arquear la zona lumbar o bajar más de lo que controlas.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera con un gesto controlado que mejora la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8423'),
('b5f0ba0e-faff-5363-a230-dbda2714fc03', 'Elevación de piernas sentado', ARRAY['Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo.', 'Coloca las manos a los lados del banco para apoyarte.', 'Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con un movimiento sencillo que puedes hacer en cualquier silla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0689'),
('057b2efd-1221-5dc1-899c-5f272b61308f', 'Estiramiento lumbar sentado', ARRAY['Siéntate en el borde de una silla con los pies planos sobre el suelo.', 'Coloca las manos sobre los muslos o a los lados de la silla para apoyarte.', 'Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta.', 'Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos.', 'Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.']::text[], 'principiante', 'Alivia la tensión de la espalda baja y los dorsales con una flexión suave que relaja toda la cadena posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0690'),
('585b0832-f87c-5147-bd14-d40d45438bdc', 'Estiramiento de tronco con flexión lateral sentado', ARRAY['Siéntate con las piernas cruzadas y la espalda recta.', 'Inclina el tronco hacia un lado llevando el brazo por encima de la cabeza.', 'Mantén la posición veinte segundos y cambia de lado respirando despacio.', 'Evita girar el tronco o levantar la cadera del suelo.']::text[], 'principiante', 'Estira la columna, la zona lumbar y los oblicuos para descargar la espalda tras muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1804'),
('38b22663-bff9-59e1-8a5c-914abb47ab33', 'Estiramiento lateral de tronco sentado', ARRAY['Siéntate con la espalda recta y los brazos relajados.', 'Inclínate hacia un lado deslizando la mano por la pierna.', 'Mantén el estiramiento sin rebotar y respira con calma.', 'Evita inclinarte hacia delante en lugar de hacia el lado.']::text[], 'principiante', 'Alarga oblicuos y dorsales con una flexión lateral que mejora la movilidad de la columna y libera tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2114'),
('7b8be77c-fd23-5d3d-8252-8eb95fc48856', 'Movilización del nervio mediano sentado', ARRAY['Siéntate con el brazo extendido y la palma de la mano hacia arriba.', 'Lleva la muñeca hacia atrás y el pulgar hacia fuera suavemente.', 'Inclina la cabeza hacia el lado contrario y vuelve despacio.', 'Evita mantener el estiramiento si notas hormigueo intenso o dolor.']::text[], 'principiante', 'Mejora la movilidad del nervio mediano y la flexibilidad de muñeca y antebrazo para prevenir molestias por teclado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11787'),
('286c00b5-de93-5a19-b021-14d60cd3d947', 'Flexión y extensión de cuello en silla', ARRAY['Siéntate erguido en la silla con los hombros relajados.', 'Baja la barbilla hacia el pecho lentamente y mantén dos segundos.', 'Lleva después la mirada hacia arriba sin forzar la nuca.', 'Evita hacer círculos completos o mover la cabeza con rapidez.']::text[], 'principiante', 'Moviliza el cuello y los elevadores de la escápula para aliviar la rigidez cervical típica del estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10555'),
('85014027-4d5d-57fe-9f78-5a28a7f589b1', 'Estiramiento lateral de cuello sentado', ARRAY['Siéntate con la espalda recta y los hombros bajos.', 'Inclina la cabeza hacia un lado llevando la oreja al hombro.', 'Puedes apoyar suavemente la mano para aumentar el estiramiento.', 'Evita levantar el hombro contrario o tirar con fuerza de la cabeza.']::text[], 'principiante', 'Relaja el elevador de la escápula y el trapecio para descargar la zona cervical y mejorar la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5195'),
('c9cd75a0-b690-5d27-9337-6c553202cb99', 'Toque de cuello sentado', ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Toca suavemente con los dedos la parte lateral del cuello.', 'Realiza pequeños movimientos de cabeza mientras mantienes el contacto.', 'Evita presionar fuerte o mover la cabeza con brusquedad.']::text[], 'principiante', 'Activa y relaja la musculatura cervical con toques suaves que mejoran la conciencia postural y reducen tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5131'),
('6b3491ee-514e-5255-8cce-53b70a274453', 'Balanceo abierto y por debajo en silla', ARRAY['Siéntate erguido en la silla con los brazos extendidos a los lados.', 'Abre los brazos y llévalos después por debajo del cuerpo cruzándolos.', 'Acompaña el movimiento con una ligera rotación del tronco.', 'Evita encoger los hombros o mover los brazos con impulso.']::text[], 'principiante', 'Moviliza hombros y pectorales con un balanceo de brazos que también activa oblicuos y dorsales.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8653'),
('363f164c-64e6-599c-a2e5-638876adc0a5', 'Estiramiento de pecho sentado con brazos rectos', ARRAY['Siéntate erguido en la silla con los pies apoyados en el suelo.', 'Entrelaza los dedos y sube los brazos rectos por encima de la cabeza.', 'Lleva ligeramente los brazos hacia atrás y abre el pecho sin arquear la zona lumbar.', 'Respira despacio y mantén el estiramiento entre veinte y treinta segundos.', 'Evita encoger los hombros hacia las orejas durante todo el estiramiento.']::text[], 'principiante', 'Abre el pecho y los hombros para contrarrestar horas encorvado frente al ordenador y mejorar la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8369'),
('895930ce-7058-5380-8c63-d8961ec065fe', 'Estiramiento de dorsal sentado en silla', ARRAY['Siéntate en el borde de la silla con la espalda recta.', 'Entrelaza los dedos y eleva los brazos estirados sobre la cabeza.', 'Inclínate un poco hacia un lado y siente cómo se estira el costado.', 'Mantén veinte segundos por cada lado respirando con calma.', 'No bloquees la respiración ni fuerces la zona lumbar.']::text[], 'principiante', 'Alarga la espalda y los dorsales, aliviando la tensión acumulada tras estudiar muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8431'),
('eff159f2-7b54-5027-acff-0ef015973d70', 'Extensión de tríceps sobre la cabeza sentado', ARRAY['Siéntate erguido con los pies bien apoyados y el core activo.', 'Sube los brazos y flexiona los codos llevando las manos detrás de la cabeza.', 'Estira los codos para subir las manos sin mover los brazos del sitio.', 'Baja despacio controlando el movimiento y mantén los codos cerca de la cabeza.', 'Evita arquear la espalda o abrir los codos hacia los lados.']::text[], 'intermedio', 'Fortalece los tríceps con el propio peso corporal, útil para empujar y estabilizar el brazo en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8654'),
('5535b2cc-94de-5b6f-8918-17e0b3f6bddc', 'Movilización de rótula sentado', ARRAY['Siéntate con la pierna estirada y el muslo relajado sobre la silla.', 'Coloca los dedos alrededor de la rótula sin presionar en exceso.', 'Desplaza la rótula suavemente hacia arriba, abajo y a los lados.', 'Haz movimientos lentos y sin dolor durante unos treinta segundos.', 'Detente si notas pinchazos o molestia aguda en la rodilla.']::text[], 'principiante', 'Mejora el deslizamiento de la rótula y la movilidad de la rodilla, ayudando a prevenir molestias al entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11651'),
('122a47a4-5fa3-532c-859c-b9777e39b0af', 'Aperturas de pecho sentado en silla', ARRAY['Siéntate erguido con los brazos flexionados a la altura del pecho.', 'Junta las manos delante del pecho como si fueras a aplaudir.', 'Aprieta el pecho al juntar las manos y mantén un segundo.', 'Abre los brazos despacio hasta notar estiramiento en el pecho y vuelve a cerrar.', 'Evita encoger los hombros o usar impulso con el tronco.']::text[], 'intermedio', 'Trabaja la musculatura pectoral y la parte frontal del hombro con un movimiento controlado y sin material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8621'),
('abdf87e9-f8f1-5feb-8f5d-bb6047835b77', 'Estiramiento del piriforme sentado', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda.', 'Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha.', 'Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.']::text[], 'principiante', 'Libera tensión en glúteos y zona profunda de la cadera, muy útil si pasas mucho tiempo sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2567'),
('32299848-be33-5f8a-a272-d8fcac450d37', 'Pronación y supinación del pie sentado', ARRAY['Siéntate y cruza el tobillo sobre la rodilla contraria.', 'Gira el pie hacia dentro y hacia fuera de forma lenta y controlada.', 'Haz diez repeticiones en cada dirección sin mover la rodilla.', 'Mantén el movimiento dentro de un rango cómodo y sin dolor.', 'Evita hacerlo rápido o con el pie en el aire sin control.']::text[], 'principiante', 'Gana movilidad en tobillo y pie y activa la musculatura de la pantorrilla para mejorar la estabilidad al caminar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10564'),
('6f15e4ef-6eb5-5f21-a787-f520ccff3fb2', 'Dominada sentado', ARRAY['Siéntate con la espalda recta y los brazos elevados por encima de la cabeza.', 'Imagina que agarras una barra y tira de los codos hacia abajo y atrás.', 'Aprieta los omóplatos al bajar los brazos y mantén un segundo.', 'Sube despacio hasta la posición inicial sin perder la postura.', 'Evita encoger los hombros o tirar con la zona lumbar.']::text[], 'intermedio', 'Refuerza dorsales y bíceps con el propio peso, mejorando la fuerza de tracción y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4785'),
('41b4a419-9177-5e78-b73f-f61d5fec21ef', 'Dominada sentado entre sillas', ARRAY['Coloca dos sillas estables a los lados y siéntate entre ellas.', 'Agarra el borde de cada silla con las palmas hacia dentro.', 'Tira del cuerpo hacia arriba flexionando los codos y aprieta la espalda.', 'Baja despacio hasta estirar los brazos sin soltar las sillas.', 'Comprueba que las sillas no se muevan antes de empezar.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps con una tracción vertical usando el peso corporal y apoyo estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3550'),
('6ce146de-712b-52e0-84db-ee13bd402875', 'Pulsos de contracción de espalda sentado', ARRAY['Siéntate erguido con los brazos relajados a los lados.', 'Junta los omóplatos como si quisieras sujetar un lápiz entre ellos.', 'Mantén la contracción dos segundos y suelta despacio.', 'Repite el pulso sin mover los hombros hacia arriba.', 'Evita sacar el pecho en exceso o arquear la espalda.']::text[], 'intermedio', 'Activa la espalda alta y los romboides para mejorar la postura y la estabilidad de los omóplatos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5132'),
('5290c301-d849-511a-9262-b97de9f095c1', 'Estiramiento de cuádriceps sentado', ARRAY['Siéntate en el borde de la silla con la espalda recta.', 'Flexiona una rodilla y lleva el pie hacia el glúteo.', 'Sujeta el tobillo con la mano y acerca el talón sin forzar.', 'Mantén veinte o treinta segundos y cambia de pierna.', 'Evita arquear la zona lumbar o tirar con fuerza del tobillo.']::text[], 'principiante', 'Estira la parte frontal del muslo y la cadera, aliviando la rigidez típica de estar sentado muchas horas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2100'),
('4011b280-ad4a-5488-8974-5b49a5074616', 'Movilización del nervio radial sentado', ARRAY['Siéntate con el brazo estirado a la altura del hombro.', 'Gira la palma hacia arriba y lleva la muñeca hacia abajo.', 'Gira la palma hacia abajo y sube la muñeca despacio.', 'Alterna los dos movimientos de forma suave y sin dolor.', 'Detente si notas hormigueo intenso o molestia en el brazo.']::text[], 'principiante', 'Mejora la movilidad del brazo y el antebrazo, reduciendo tensión en muñeca y codo tras escribir mucho.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11786'),
('2e7a6eef-3a6d-5e1e-8e78-7e02d5033b06', 'Estiramiento de romboides sentado', ARRAY['Siéntate erguido y cruza los brazos delante del pecho.', 'Agarra los hombros contrarios con las manos.', 'Redondea ligeramente la espalda alta y separa los omóplatos.', 'Mantén el estiramiento veinte segundos respirando despacio.', 'Evita tirar del cuello o bajar la cabeza en exceso.']::text[], 'principiante', 'Relaja la espalda alta y los omóplatos, ayudando a descargar la tensión de la zona entre los hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6774'),
('03834cd9-5e0f-55f7-8d04-0fcddc4469bc', 'Giros de boxeo sentado en silla', ARRAY['Siéntate en el borde de la silla con la espalda recta y el core activo.', 'Sube los puños a la altura de la barbilla.', 'Lanza golpes alternos al aire girando ligeramente el tronco.', 'Mantén un ritmo constante y respira de forma fluida.', 'Evita bloquear los codos o girar con demasiada fuerza la espalda.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa hombros y oblicuos con un movimiento dinámico y sencillo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '8634'),
('1cbc75f1-eae1-554c-8311-fdcac11ea3cf', 'Estiramiento de rotación sentado', ARRAY['Siéntate erguido con los pies apoyados y las manos en el regazo.', 'Gira el tronco hacia un lado sin mover la cadera.', 'Mantén la rotación veinte segundos respirando con calma.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita forzar el giro o tirar del cuello con la cabeza.']::text[], 'principiante', 'Moviliza la columna y estira oblicuos y zona lumbar, aliviando la rigidez de la espalda tras el estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5135'),
('8713aaa0-4e0e-55d2-b4c3-29382f124845', 'Remo sentado con toalla', ARRAY['Siéntate con la espalda recta y sujeta la toalla por los extremos con las manos a la altura del pecho.', 'Tira de la toalla hacia el pecho juntando los omóplatos mientras exhalas.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita encorvar la espalda o encoger los hombros al tirar.']::text[], 'intermedio', 'Fortalece la espalda y los bíceps tirando de la toalla; mejora la postura y la fuerza de tracción sin material.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3848'),
('e581d497-f702-5a10-ae76-7c29f1cab7b5', 'Estiramiento de hombro sentado', ARRAY['Siéntate erguido y entrelaza las manos detrás de la espalda.', 'Lleva los hombros hacia atrás y abajo sin forzar el cuello.', 'Mantén el estiramiento respirando despacio sin rebotar.', 'Evita sacar las costillas hacia delante o arquear la zona lumbar.']::text[], 'principiante', 'Estira la parte delantera del hombro y el pecho; alivia la tensión de quien pasa muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1975'),
('047db2e2-d289-50ce-be20-9726cfe19156', 'Estiramiento de hombro sentado con rodilla flexionada', ARRAY['Siéntate con una rodilla flexionada y la espalda recta.', 'Lleva el brazo hacia atrás y junta las manos detrás del cuerpo.', 'Abre el pecho y baja los hombros manteniendo la posición.', 'Respira con calma y evita tirar del cuello o forzar el hombro.']::text[], 'principiante', 'Estira el hombro y el pecho con una rodilla flexionada; mejora la movilidad y reduce la rigidez postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3564'),
('f92cb796-5a65-590a-bbde-bb846f60f983', 'Press de hombros sentado en silla', ARRAY['Siéntate con la espalda apoyada y los brazos flexionados a la altura de los hombros.', 'Empuja las manos hacia arriba hasta estirar los brazos sin bloquear del todo.', 'Baja despacio hasta la posición inicial mientras inspiras.', 'Evita arquear la espalda o encoger los hombros al empujar.']::text[], 'intermedio', 'Refuerza los hombros y los tríceps empujando hacia arriba; mejora la fuerza del tren superior sin pesas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '8633'),
('3e8d59ab-fece-589d-8d71-c392105a74fa', 'Toque de hombro sentado en silla', ARRAY['Siéntate erguido con las manos sobre los hombros.', 'Levanta una rodilla y toca con la mano contraria manteniendo el equilibrio.', 'Alterna los lados a un ritmo constante respirando de forma fluida.', 'Evita encorvar la espalda o balancear el tronco para tocar.']::text[], 'intermedio', 'Activa el core y los hombros con un movimiento dinámico; mejora la estabilidad y eleva la frecuencia cardiaca.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '8652'),
('8f1c818f-de4c-5f5c-af9b-21d43dc79fb4', 'Flexión lateral sentado en silla', ARRAY['Siéntate erguido con los pies apoyados y los brazos relajados.', 'Inclina el tronco hacia un lado deslizando la mano por la pierna.', 'Vuelve al centro y repite hacia el otro lado sin prisa.', 'Evita girar el tronco o forzar la inclinación más allá de lo cómodo.']::text[], 'principiante', 'Moviliza la columna y estira los oblicuos; mejora la flexibilidad lateral del tronco y alivia tensiones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8311'),
('2725b092-44bb-5bb7-95d9-091ec85537f3', 'Abdominal lateral sentado en la pared', ARRAY['Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti.', 'Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera.', 'Haz una pausa breve y luego vuelve a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja los oblicuos y el abdomen con un gesto corto; mejora el control del core desde sentado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0691'),
('e4441da0-1bc5-5657-bd4e-b3a812d38597', 'Abdominal sentado con elevación de piernas de lado a lado', ARRAY['Siéntate en el suelo con las rodillas flexionadas y el tronco ligeramente inclinado atrás.', 'Eleva los pies y lleva las piernas hacia un lado sin tocar el suelo.', 'Cambia de lado de forma controlada manteniendo el abdomen activo.', 'Evita tirar del cuello o redondear la espalda al girar.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos elevando las piernas; mejora el control del core y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3978'),
('6779a4dc-3244-51c4-b3c7-6d900286e10c', 'Inclinación de cuello de lado a lado sentado en silla', ARRAY['Siéntate erguido con los hombros relajados y la mirada al frente.', 'Inclina la cabeza hacia un hombro sin levantarlo.', 'Mantén unos segundos y cambia al otro lado despacio.', 'Evita girar la cabeza o tirar con la mano para forzar el estiramiento.']::text[], 'principiante', 'Moviliza el cuello y estira el elevador de la escápula; alivia la rigidez cervical por el estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10557'),
('a4637ce9-7872-5e5b-a8aa-a422a280024a', 'Giro de cuello de lado a lado sentado en silla', ARRAY['Siéntate erguido con los hombros bajos y relajados.', 'Gira la cabeza despacio hacia un lado hasta donde sea cómodo.', 'Vuelve al centro y repite hacia el otro lado sin prisa.', 'Evita movimientos bruscos o forzar el rango de giro.']::text[], 'principiante', 'Mejora la rotación cervical y relaja la musculatura del cuello; útil tras largas sesiones de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10556'),
('94991a55-2287-54d1-8f26-e2964223a211', 'Elevación de gemelos sentado a una pierna en silla', ARRAY['Siéntate con la espalda recta y una pierna estirada con el pie apoyado.', 'Eleva el talón empujando con la punta del pie y mantén arriba un instante.', 'Baja el talón despacio hasta el suelo y repite.', 'Evita mover la rodilla o hacer rebotes al subir y bajar.']::text[], 'intermedio', 'Fortalece los gemelos y el sóleo con una pierna; mejora la fuerza del tobillo y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11650'),
('5e312f51-ba1f-5c0b-982d-3c5c49f8a594', 'Círculo de pie sentado a una pierna', ARRAY['Siéntate y eleva un pie del suelo con la pierna relajada.', 'Dibuja círculos lentos con el pie en un sentido.', 'Cambia de sentido tras varias repeticiones.', 'Evita hacer círculos rápidos o forzar el tobillo.']::text[], 'principiante', 'Moviliza el tobillo y el pie con círculos suaves; mejora la circulación y la flexibilidad articular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10908'),
('54b7e0f3-53a7-53d8-abdf-a52651eb57e3', 'Movimiento de pie de lado a lado sentado a una pierna', ARRAY['Siéntate y levanta un pie manteniendo la pierna relajada.', 'Mueve el pie de lado a lado como un limpiaparabrisas.', 'Hazlo despacio y con control durante varias repeticiones.', 'Evita mover toda la pierna o forzar el tobillo.']::text[], 'principiante', 'Moviliza el tobillo y el pie de lado a lado; mejora la movilidad articular y la propiocepción.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10910'),
('f71a8717-deeb-54d6-a127-e53942a0e5b4', 'Medio círculo sentado a una pierna', ARRAY['Siéntate erguido y eleva una pierna con la rodilla flexionada.', 'Dibuja un medio círculo con la rodilla hacia fuera y vuelve.', 'Mantén el abdomen activo y la espalda recta.', 'Evita balancear el tronco o forzar la cadera.']::text[], 'principiante', 'Moviliza la cadera y activa los glúteos con un medio círculo; mejora la movilidad y el control del core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10745'),
('e4e780af-07a9-5cb4-81ce-363af3f5257b', 'Estiramiento de isquiotibiales sentado a una pierna', ARRAY['Siéntate con una pierna estirada y la otra flexionada.', 'Inclina el tronco hacia la pierna estirada con la espalda recta.', 'Mantén el estiramiento respirando despacio sin rebotar.', 'Evita redondear la espalda o forzar hasta sentir dolor.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla; mejora la flexibilidad y alivia la tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0692'),
('f553af9f-b9d6-56f5-8e24-8460d2875eb8', 'Flexión de rodilla abrazada sentado a una pierna', ARRAY['Siéntate en el borde de una silla con la espalda recta y los pies apoyados.', 'Lleva una rodilla hacia el pecho y abrázala con las manos sin redondear la espalda.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita tirar del cuello o forzar la lumbar; baja la pierna despacio y cambia de lado.']::text[], 'principiante', 'Moviliza los isquiosurales y la cadera llevando la rodilla al pecho para ganar rango y aliviar tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10541'),
('5713d841-987a-506b-b9cc-880c3b48554a', 'Flexión de rodilla abrazada sentado a una pierna con toalla', ARRAY['Siéntate con la espalda apoyada y pasa una toalla por la planta del pie.', 'Estira una pierna y tira suavemente de la toalla acercando el muslo al pecho.', 'Mantén la tensión veinte segundos sin bloquear la rodilla ni curvar la espalda.', 'Suelta poco a poco y repite con la otra pierna evitando rebotes.']::text[], 'principiante', 'Mejora la flexibilidad de isquiosurales y cadera usando una toalla para tirar con control.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10542'),
('ce013e65-712a-5ecd-b789-4dc65d6a1cc2', 'Extensión de rodilla sentado a una pierna', ARRAY['Siéntate en una silla con la espalda recta y los pies en el suelo.', 'Estira una pierna hasta que quede paralela al suelo y aprieta el cuádriceps.', 'Aguanta dos segundos arriba y baja lentamente sin dejar caer el pie.', 'Evita balancear la pierna o compensar con la cadera; hazlo despacio.']::text[], 'principiante', 'Fortalece el cuádriceps de forma controlada y sirve para readaptar la rodilla tras una lesión.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10537'),
('b8756b16-328f-5c56-afd9-5427326f0ff6', 'Flexión de rodilla sentado a una pierna', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Desliza un pie hacia atrás doblando la rodilla sin mover el muslo.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita levantar el talón o girar la cadera; mantén el ritmo lento.']::text[], 'principiante', 'Activa isquiosurales y glúteos con un gesto suave útil en la readaptación de la rodilla.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10534'),
('d4e2df72-a8f7-5216-954c-d9a4a61d554f', 'Elevación de una pierna sentado', ARRAY['Siéntate en el borde de una silla con la espalda recta y el abdomen activo.', 'Estira una pierna hacia delante hasta la altura de la cadera.', 'Mantén un segundo arriba y baja sin tocar el suelo.', 'Evita arquear la espalda o balancearte; respira de forma constante.']::text[], 'intermedio', 'Trabaja el cuádriceps y el control del core elevando una pierna desde sentado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8946'),
('11a0fe25-47eb-58b4-a2ed-6022991abbb1', 'Apretar los dedos de los pies sentado a una pierna', ARRAY['Siéntate con un pie apoyado y el otro elevado ligeramente.', 'Aprieta los dedos del pie elevado como si agarraras el suelo.', 'Mantén la presión tres segundos y relaja despacio.', 'Evita mover la rodilla o el tobillo; repite y cambia de pie.']::text[], 'principiante', 'Moviliza y activa la musculatura del pie y el tobillo para mejorar el apoyo y la propiocepción.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10912'),
('7217f66a-6ea9-5df3-825c-1a286193a975', 'Press de tibial sentado a una pierna', ARRAY['Siéntate con una pierna estirada y el talón apoyado.', 'Lleva la punta del pie hacia arriba contra una resistencia ligera.', 'Aprieta arriba un segundo y baja con control.', 'Evita mover la rodilla o compensar con la cadera; trabaja despacio.']::text[], 'intermedio', 'Refuerza el tibial anterior y la zona del tobillo para mejorar la estabilidad y el control del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10535'),
('fda5f0ef-6c37-58d9-951c-b579718c5eba', 'Press de dedos de los pies sentado a una pierna', ARRAY['Siéntate con un pie apoyado y el otro ligeramente elevado.', 'Presiona los dedos del pie elevado contra el suelo o una superficie firme.', 'Mantén la presión dos o tres segundos y suelta despacio.', 'Evita levantar el talón o girar el tobillo; repite y cambia de pie.']::text[], 'principiante', 'Activa la musculatura intrínseca del pie y el tobillo para ganar movilidad y fuerza en el apoyo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10920'),
('c93317f3-3a20-5e7a-ac2d-c94e1db5cea9', 'Mirada al cielo sentado', ARRAY['Siéntate con la espalda recta y los hombros relajados.', 'Gira la cabeza hacia un lado y luego mira hacia arriba con suavidad.', 'Mantén el estiramiento quince segundos sin forzar el cuello.', 'Evita encoger los hombros o tirar con la mano; vuelve despacio al centro.']::text[], 'principiante', 'Estira el elevador de la escápula y el cuello, aliviando la tensión cervical tras horas de estudio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5081'),
('19031e45-042c-5c86-8e41-7e6576217808', 'Estiramiento de pecho sentado en silla juntando los omóplatos', ARRAY['Siéntate en una silla con la espalda recta y los brazos relajados.', 'Junta los omóplatos llevando los codos ligeramente hacia atrás.', 'Abre el pecho y mantén la posición veinte segundos respirando hondo.', 'Evita sacar las costillas o encoger los hombros; suelta despacio.']::text[], 'principiante', 'Abre el pecho y estira los pectorales juntando las escápulas para contrarrestar posturas encorvadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10463'),
('bd1e4fde-30b9-54ab-83f4-d47925a109bb', 'Apretar los dedos de los pies sentado', ARRAY['Siéntate con los pies apoyados y la espalda recta.', 'Aprieta los dedos de ambos pies como si agarraras el suelo.', 'Mantén la presión tres segundos y relaja lentamente.', 'Evita levantar los talones o mover las rodillas; respira con calma.']::text[], 'principiante', 'Activa la musculatura del pie y el tobillo para mejorar el apoyo y la propiocepción sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10911'),
('89a78495-6685-52a8-987c-9b674672d25e', 'Estiramiento de gemelos sentado con pierna recta', ARRAY['Siéntate con una pierna estirada y el pie en flexión.', 'Lleva la punta del pie hacia ti hasta notar tensión en la pantorrilla.', 'Mantén el estiramiento veinte segundos sin bloquear la rodilla.', 'Evita redondear la espalda o rebotar; suelta despacio y cambia de pierna.']::text[], 'principiante', 'Estira gemelos y sóleo con la pierna estirada, mejorando la flexibilidad del tobillo y la pantorrilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0693'),
('9c09fcd1-82a4-5932-89cd-297c01a39c95', 'Press de tibial anterior sentado', ARRAY['Siéntate con los pies apoyados y las piernas relajadas.', 'Levanta las puntas de los pies hacia arriba contra una resistencia ligera.', 'Aprieta un segundo arriba y baja con control.', 'Evita mover las rodillas o compensar con la cadera; trabaja despacio.']::text[], 'intermedio', 'Fortalece el tibial anterior y el tobillo para mejorar la estabilidad y prevenir molestias en la espinilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6759'),
('bddaead9-c669-55c5-a908-706760467f3f', 'Estiramiento de extensores de los dedos y eversores del pie sentado', ARRAY['Siéntate y cruza un tobillo sobre la rodilla contraria.', 'Con la mano, lleva los dedos del pie hacia abajo y hacia dentro con suavidad.', 'Mantén el estiramiento quince segundos sin forzar.', 'Evita tirar bruscamente o mover la rodilla; suelta y cambia de pie.']::text[], 'principiante', 'Estira los extensores de los dedos y los eversores del pie para aliviar tensión en el dorso y el tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1963'),
('238b7a75-c38e-5603-b895-6e00489e8dfb', 'Estiramiento de extensores de los dedos e inversores del pie sentado', ARRAY['Siéntate y cruza un tobillo sobre la rodilla contraria.', 'Con la mano, lleva los dedos del pie hacia abajo y hacia fuera con suavidad.', 'Mantén el estiramiento quince segundos respirando con calma.', 'Evita forzar el tobillo o rebotar; suelta despacio y cambia de pie.']::text[], 'principiante', 'Estira los extensores de los dedos y los inversores del pie para mejorar la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1964'),
('61ef1758-cfa8-5bae-9138-0220d65ff157', 'Estiramiento de extensores de los dedos del pie sentado', ARRAY['Siéntate en una silla y cruza un tobillo sobre la rodilla contraria.', 'Con la mano, lleva los dedos del pie hacia abajo, como si los apuntaras hacia el suelo.', 'Mantén la presión suave entre 20 y 30 segundos sin rebotes.', 'Respira despacio y evita forzar el tobillo más allá de una molestia leve.']::text[], 'principiante', 'Relaja la parte superior del pie y la espinilla, mejorando la movilidad del tobillo y aliviando tensiones tras caminar o correr.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1962'),
('36aac679-b5ce-5b46-83d1-5a75f163f4dc', 'Estiramiento de flexores de los dedos y eversores del pie sentado', ARRAY['Siéntate y apoya el tobillo sobre la rodilla contraria.', 'Sujeta el pie y gira la planta hacia fuera mientras llevas los dedos hacia arriba.', 'Mantén la posición de 20 a 30 segundos con respiración tranquila.', 'Evita tirar solo de los dedos: el movimiento debe notarse en toda la planta.']::text[], 'principiante', 'Estira la planta y el borde externo del pie, útil para descargar la fascia y mejorar la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1966'),
('4c6595b4-9774-556b-9be5-5eeecd2cb189', 'Estiramiento de flexores de los dedos e inversores del pie sentado', ARRAY['Siéntate y cruza el tobillo sobre la rodilla opuesta.', 'Lleva la planta hacia dentro y estira los dedos hacia arriba con la mano.', 'Sostén el estiramiento entre 20 y 30 segundos sin rebotar.', 'No gires la rodilla hacia fuera; mantén la pierna relajada.']::text[], 'principiante', 'Trabaja la planta y el borde interno del pie, ayudando a prevenir sobrecargas y a ganar movilidad en el tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1967'),
('c083398c-3b89-57ad-b4a8-d2cd2eb8d34f', 'Estiramiento de flexores de los dedos del pie sentado', ARRAY['Siéntate y apoya el tobillo sobre la rodilla contraria.', 'Con la mano, lleva los dedos del pie hacia arriba hasta notar tensión en la planta.', 'Mantén de 20 a 30 segundos respirando con calma.', 'Evita apretar demasiado: debe ser un estiramiento cómodo, no doloroso.']::text[], 'principiante', 'Estira la planta del pie y los dedos, aliviando la tensión acumulada y mejorando el apoyo en la marcha.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1965'),
('44dc6d47-abac-50d5-b7ad-8688677dac10', 'Giro sentado en balón de estabilidad', ARRAY['Siéntate sobre el balón con los pies apoyados y la espalda erguida.', 'Cruza los brazos delante del pecho o junta las manos.', 'Gira el tronco despacio hacia un lado y luego hacia el otro.', 'Mantén la pelvis estable y evita mover solo los brazos.', 'Respira de forma continua y controla el ritmo del giro.']::text[], 'principiante', 'Activa el core y los oblicuos mientras moviliza la columna, mejorando el control postural y la estabilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0694'),
('697a62f9-3c89-5f73-ad0d-e6f1cc9a0c42', 'Movilización del nervio cubital sentado', ARRAY['Siéntate y extiende un brazo hacia el lado con la palma hacia arriba.', 'Flexiona el codo y lleva la mano hacia la oreja, manteniendo el hombro bajo.', 'Inclina la cabeza hacia el lado contrario y estira suavemente la muñeca.', 'Haz movimientos lentos y evita hormigueos fuertes; si aparecen, reduce el rango.']::text[], 'principiante', 'Mejora la movilidad del nervio cubital y la flexibilidad de la muñeca, útil ante tensión en antebrazo y mano.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11788'),
('73984199-e79a-5c53-97da-9ebc348299e5', 'Círculos de brazos con agarre inverso sentado en silla', ARRAY['Siéntate erguido con la espalda separada del respaldo.', 'Extiende los brazos a los lados con las palmas hacia arriba.', 'Dibuja círculos pequeños y lentos hacia delante y luego hacia atrás.', 'Mantén los hombros bajos y evita encogerlos durante el movimiento.']::text[], 'principiante', 'Moviliza el hombro y la cintura escapular, preparando la articulación y mejorando la circulación en la zona alta.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8655'),
('fa9d5ee2-d2ee-547f-a2e9-18d39b68c823', 'Giros erguidos sentado en silla', ARRAY['Siéntate erguido con los pies apoyados y las manos en la nuca o cruzadas al pecho.', 'Gira el tronco despacio hacia un lado sin mover la pelvis.', 'Vuelve al centro y repite hacia el otro lado.', 'Respira de forma fluida y evita tirar del cuello con las manos.']::text[], 'principiante', 'Moviliza la columna y activa oblicuos y core, mejorando la rotación del tronco y la postura sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8303'),
('9b3f3586-09e3-5812-9dfd-f770ecd9ad09', 'Secuencia de postura de ángulo amplio sentado', ARRAY['Siéntate en el suelo con las piernas extendidas formando un ángulo amplio.', 'Flexiona los pies y contrae los cuádriceps.', 'Coloca las manos en el suelo detrás de ti para apoyarte.', 'Manteniendo la espalda recta, inclínate hacia delante desde la cadera.', 'Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales.', 'Mantén esta posición durante unas cuantas respiraciones.', 'Libera lentamente el estiramiento y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira isquiotibiales, cuádriceps y gemelos con una secuencia de yoga sentado que mejora la flexibilidad de piernas.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1587'),
('a686528e-a246-5bef-a445-0cc8669b2905', 'Estiramiento de desviador cubital y flexor de muñeca sentado', ARRAY['Siéntate y extiende un brazo al frente con la palma hacia abajo.', 'Desvía la muñeca hacia el lado del meñique con ayuda de la otra mano.', 'Mantén de 20 a 30 segundos sin forzar la articulación.', 'Evita elevar el hombro y mantén el codo ligeramente flexionado.']::text[], 'principiante', 'Estira el antebrazo y la muñeca, aliviando la tensión por uso repetido del teclado o el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2093'),
('2175c922-b9aa-5843-9cc8-7e533079c740', 'Automasaje con rodillo en el tibial anterior', ARRAY['Coloca el rodillo en el suelo y apoya la espinilla sobre él.', 'Desplázate lentamente hacia delante y hacia atrás buscando puntos tensos.', 'Haz pausas de 20 a 30 segundos en las zonas más sensibles.', 'Evita presionar directamente sobre el hueso de la tibia.']::text[], 'principiante', 'Libera la tensión de la espinilla y el sóleo, mejorando la movilidad del tobillo y aliviando sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2994'),
('ec66d6d6-c86a-59a5-b9a5-ada0fbdf378d', 'Curl de pierna inverso autoasistido', ARRAY['Túmbate boca arriba con las piernas elevadas y las manos apoyadas.', 'Lleva los talones hacia los glúteos mientras elevas la cadera.', 'Baja despacio controlando el movimiento sin dejar caer la pelvis.', 'Mantén el abdomen activo y evita arquear la zona lumbar.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos con control, mejorando la fuerza posterior de la pierna sin material.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3507'),
('7ef845f3-9eb3-54dc-89aa-7e3ddb5dd755', 'Pullover invertido autoasistido', ARRAY['Colócate bajo una barra o agarre bajo con el cuerpo inclinado.', 'Con los brazos extendidos, tira del cuerpo hacia arriba llevando el pecho hacia las manos.', 'Baja despacio manteniendo el core activo y el cuerpo alineado.', 'Evita encoger los hombros y controla el descenso sin dejarte caer.']::text[], 'intermedio', 'Trabaja dorsales y espalda alta, mejorando la fuerza de tracción y el control escapular con el propio peso.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3499'),
('3a246752-8ca4-56fc-987a-e4074de6557b', 'Salto en media sentadilla', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.', 'Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso.', 'Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico que eleva la frecuencia cardíaca y potencia piernas y glúteos con un salto explosivo desde media flexión.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3222'),
('ad93846d-68be-5890-bd01-a997c1d398d0', 'Estiramiento de separación entre los dedos', ARRAY['Siéntate y apoya el pie sobre la rodilla contraria.', 'Introduce suavemente los dedos de la mano entre los dedos del pie.', 'Separa los dedos con cuidado y mantén de 15 a 20 segundos.', 'Evita forzar si notas pinchazos y suelta despacio al terminar.']::text[], 'principiante', 'Relaja los músculos entre los dedos del pie, mejorando la movilidad y aliviando tensiones por calzado ajustado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2103'),
('ae391a61-098e-5d2c-a2b6-71b5491f86fa', 'Estiramiento de separación de dedos', ARRAY['Extiende un brazo al frente con la palma hacia delante y los dedos juntos.', 'Separa los dedos todo lo que puedas hasta notar un estiramiento suave en la mano.', 'Mantén la posición entre 15 y 30 segundos respirando con normalidad.', 'Evita forzar la muñeca hacia atrás para no comprimir la articulación.', 'Relaja despacio y repite con la otra mano.']::text[], 'principiante', 'Estira antebrazos, manos y flexores de la muñeca para aliviar la tensión tras escribir o usar el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2097'),
('5961e3d0-3162-5a33-b58c-962155daafb4', 'Deslizamiento de serrato en la pared', ARRAY['Apoya los antebrazos en la pared con los codos a la altura de los hombros.', 'Desliza los antebrazos hacia arriba manteniendo el contacto con la pared.', 'Empuja ligeramente la pared al subir para activar el serrato.', 'Evita encoger los hombros hacia las orejas durante el recorrido.', 'Baja despacio y repite de forma controlada.']::text[], 'principiante', 'Activa el serrato anterior y mejora la movilidad escapular para un hombro más estable y funcional.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5025'),
('fdf48ceb-ab60-50c6-abd1-082d141ee207', 'Cambio de caja de espinillas', ARRAY['Siéntate con las rodillas flexionadas y las espinillas apoyadas en el suelo.', 'Gira las piernas hacia un lado llevando ambas rodillas al mismo lado.', 'Mantén la espalda erguida y siente el estiramiento en la cadera.', 'Cambia de lado de forma controlada sin usar las manos para impulsarte.', 'Evita redondear la espalda durante el cambio.']::text[], 'principiante', 'Moviliza caderas y glúteos y abre aductores e ingles para ganar rango en rotaciones y sentadillas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4608'),
('1e970ca2-21a6-5907-b5fa-a37a006c29bb', 'Carrera de paso corto', ARRAY['Busca un espacio abierto o una cinta de correr para realizar el ejercicio.', 'Ponte de pie con los pies separados a la altura de la cadera.', 'Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos.', 'Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido.', 'Continúa corriendo con pasos cortos durante la duración o distancia deseada.']::text[], 'intermedio', 'Trabajo cardiovascular de baja intensidad que activa piernas y mejora la resistencia con impacto reducido.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3656'),
('26b30206-da25-5f71-9c6e-d2eaad559c3d', 'Abducción de hombro', ARRAY['Colócate de pie con los brazos relajados junto al cuerpo.', 'Eleva un brazo lateralmente hasta la altura del hombro sin encogerlo.', 'Mantén el codo ligeramente estirado y el tronco estable.', 'Evita subir el hombro hacia la oreja durante el movimiento.', 'Baja despacio y alterna con el otro brazo.']::text[], 'principiante', 'Gana movilidad en el hombro y activa el deltoides para elevar el brazo sin compensaciones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2775'),
('e86208d7-9a0e-5d9c-b232-a8b8abce218d', 'Aducción de hombro', ARRAY['De pie, lleva un brazo estirado por delante del pecho.', 'Con la otra mano, empuja suavemente el codo hacia el cuerpo.', 'Mantén el hombro bajo, sin encogerlo hacia la oreja.', 'Siente el estiramiento en la parte posterior del hombro sin dolor.', 'Sostén unos segundos y cambia de brazo.']::text[], 'principiante', 'Mejora la movilidad del hombro y estira dorsal y pecho al llevar el brazo cruzado sobre el cuerpo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2776'),
('86722af7-fd5a-5bac-81bc-e2a1495d40ea', 'Estiramiento de aductores, elevadores y protractores del hombro', ARRAY['Lleva un brazo cruzado delante del pecho con la mano contraria.', 'Baja el hombro y separa la escápula de la oreja.', 'Inclina ligeramente el tronco para aumentar el estiramiento.', 'Respira despacio y mantén entre 20 y 30 segundos.', 'Evita tirar del codo con fuerza para no comprimir el hombro.']::text[], 'principiante', 'Libera tensión en hombros, trapecio y espalda alta tras sesiones de empuje o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1979'),
('47f00b58-064e-5202-a657-2606b6f1f66b', 'Estiramiento de aductores, protractores y elevadores del hombro', ARRAY['Cruza un brazo sobre el pecho y sujeta el codo con la mano contraria.', 'Empuja el brazo hacia ti sin elevar el hombro.', 'Mantén la cabeza alineada y el cuello relajado.', 'Respira con calma durante 20 o 30 segundos.', 'Suelta despacio y repite con el otro lado.']::text[], 'principiante', 'Relaja hombros y espalda alta, mejorando la postura y aliviando la rigidez cervical y escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2087'),
('cc4efd00-b08f-5ad6-8388-3f71afd1c36d', 'Puente de hombros', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Empuja con los talones y eleva la cadera hasta formar una línea recta.', 'Aprieta los glúteos arriba y evita arquear la zona lumbar.', 'Baja de forma controlada sin dejar caer la cadera de golpe.', 'Respira exhalando al subir y repite el movimiento.']::text[], 'intermedio', 'Fortalece glúteos e isquios y estabiliza el core, mejorando la extensión de cadera y la postura.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2863'),
('37bb1302-24c1-50e7-8896-4882dda1dba7', 'Círculo de hombros', ARRAY['De pie, con los brazos relajados y la espalda recta.', 'Dibuja círculos amplios con los hombros hacia delante.', 'Mantén el cuello suelto y evita mover los codos.', 'Cambia el sentido de giro tras varias repeticiones.', 'Respira de forma fluida durante todo el ejercicio.']::text[], 'principiante', 'Calienta y moviliza la cintura escapular para preparar hombros y espalda alta antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4395'),
('21a70f9e-15a4-53bc-b831-ea7e7c4fce9c', 'Extensión de hombro', ARRAY['De pie, con los brazos junto al cuerpo y el tronco erguido.', 'Lleva un brazo hacia atrás sin arquear la zona lumbar.', 'Mantén el codo estirado y el hombro bajo.', 'Evita girar el tronco para ganar recorrido.', 'Vuelve despacio y alterna con el otro brazo.']::text[], 'principiante', 'Moviliza el hombro hacia atrás y activa dorsal y tríceps para mejorar la extensión del brazo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2777'),
('c6c8de55-f792-56ab-8d73-94405fbca654', 'Estiramiento de extensores, aductores y retractores del hombro', ARRAY['Lleva un brazo por delante del pecho con la mano contraria en el codo.', 'Baja el hombro y separa la escápula de la oreja.', 'Ajusta la presión hasta notar un estiramiento cómodo.', 'Mantén la posición respirando con calma unos 20 segundos.', 'Suelta despacio y cambia de lado.']::text[], 'principiante', 'Estira hombro, tríceps y espalda alta para descargar la zona tras empujes o trabajo de brazos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1978'),
('2cf3f6fa-f2cf-59b4-b077-7ca1a5502252', 'Prueba de rotación externa de hombro', ARRAY['De pie, con el codo flexionado a 90 grados pegado al cuerpo.', 'Gira el antebrazo hacia fuera sin separar el codo del tronco.', 'Observa hasta dónde llega el movimiento sin dolor.', 'Evita compensar girando el tronco o elevando el hombro.', 'Vuelve a la posición inicial y compara con el otro lado.']::text[], 'principiante', 'Valora la movilidad rotacional del hombro y detecta restricciones en el manguito rotador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6790'),
('941da8da-b339-5ebe-9c6b-5373fc497c5d', 'Flexión de hombro', ARRAY['De pie, con los brazos junto al cuerpo y el core activo.', 'Eleva un brazo hacia delante hasta donde puedas sin dolor.', 'Mantén el codo estirado y el hombro bajo.', 'Evita arquear la espalda para subir más el brazo.', 'Baja despacio y alterna con el otro lado.']::text[], 'principiante', 'Mejora la movilidad del hombro al elevar el brazo y activa deltoides y pectoral superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2778'),
('1d20ed49-4350-5e8e-a7da-20994d45efa1', 'Flexión de hombro con la espalda contra la pared', ARRAY['Apoya la espalda y la cabeza en la pared con los pies algo adelantados.', 'Eleva los brazos hacia delante manteniendo el contacto con la pared.', 'Sube hasta donde puedas sin despegar la zona lumbar.', 'Evita encoger los hombros o sacar las costillas.', 'Baja despacio y repite de forma controlada.']::text[], 'principiante', 'Gana movilidad de hombro y control escapular manteniendo la espalda apoyada y el core activo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2931'),
('9d7462aa-0c5e-522b-9069-6a09edba2547', 'Dominada con agarre de hombros', ARRAY['Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera.', 'Cuélgate libremente con los brazos completamente extendidos.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda y los bíceps colgándote de la barra con las manos en línea de hombros para ganar fuerza vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1763'),
('3d506727-3f5b-59c1-9119-5e469e78ba7f', 'Prueba de rotación interna de hombro', ARRAY['Colócate de pie con el brazo pegado al cuerpo y el codo flexionado noventa grados.', 'Gira el antebrazo hacia dentro sin mover el codo ni el tronco.', 'Mantén la posición dos segundos y respira con normalidad.', 'Detente en cuanto notes tirantez o el hombro se levante.', 'Evita compensar girando la espalda o subiendo el hombro.']::text[], 'principiante', 'Valora la movilidad interna del hombro y detecta restricciones en el manguito rotador y la zona dorsal alta.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6791'),
('b490124d-aa31-5840-af0b-6dba4334e81a', 'Rotación externa de hombro', ARRAY['Pega el brazo al costado con el codo a noventa grados y el antebrazo hacia delante.', 'Gira el antebrazo hacia fuera manteniendo el codo fijo junto al cuerpo.', 'Aguanta un par de segundos arriba sin forzar.', 'Respira de forma pausada durante todo el recorrido.', 'No arquees la espalda ni separes el codo del tronco.']::text[], 'principiante', 'Mejora la movilidad externa del hombro y activa el manguito rotador para proteger la articulación.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2779'),
('0cde8b68-c17a-53dc-b340-da39a56b691f', 'Prueba de nivel de hombros', ARRAY['Siéntate o ponte de pie con la espalda recta y los brazos relajados.', 'Eleva los dos brazos a la vez hasta la altura de los hombros.', 'Observa si ambos quedan a la misma altura y sin tensión.', 'Baja despacio y repite el gesto con control.', 'Evita encoger el cuello o elevar un hombro más que el otro.']::text[], 'principiante', 'Comprueba la simetría y movilidad de ambos hombros, útil para detectar desequilibrios antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6792'),
('48890bc6-e309-5bcb-80ad-92d78138aed9', 'Rotación interna de hombro', ARRAY['Coloca el brazo pegado al cuerpo con el codo flexionado noventa grados.', 'Lleva el antebrazo hacia el abdomen girando desde el hombro.', 'Mantén el codo fijo y no muevas el tronco.', 'Aguanta la posición final dos segundos respirando tranquilo.', 'Detente si aparece dolor y evita forzar el rango.']::text[], 'principiante', 'Trabaja la rotación interna del hombro y la flexibilidad del manguito rotador y la zona pectoral.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2780'),
('0db1ce1d-1e66-5d1d-a36d-ef6f5c003a69', 'Press de hombros con banda', ARRAY['Pisa la banda con los pies a la anchura de los hombros y agarra los extremos a la altura de los hombros.', 'Empuja las manos hacia arriba hasta estirar los brazos sin bloquear del todo los codos.', 'Baja despacio controlando la banda hasta la altura de los hombros.', 'Exhala al empujar e inhala al bajar.', 'Evita arquear la espalda o encoger los hombros hacia las orejas.']::text[], 'principiante', 'Fortalece deltoides, tríceps y core mejorando el empuje vertical y la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0698'),
('3e313e13-d9b3-578d-be3c-8a9a92bda0a6', 'Postura sobre los hombros', ARRAY['Túmbate boca arriba con los brazos a los lados y las palmas en el suelo.', 'Eleva las piernas y el tronco apoyando el peso sobre los hombros y la espalda alta.', 'Sujeta la espalda con las manos y mantén el cuello libre de carga.', 'Respira despacio y mantén la postura el tiempo que controles.', 'Sal con cuidado bajando vértebra a vértebra y evita girar la cabeza.']::text[], 'intermedio', 'Postura de yoga que fortalece la espalda alta, el core y los hombros, y mejora la circulación.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1487'),
('582d788f-d635-5368-a7b2-cb536d3aa3ba', 'Estiramiento de hombro detrás de la espalda', ARRAY['Lleva un brazo por detrás de la espalda con la palma hacia fuera.', 'Con la otra mano empuja suavemente el codo hacia dentro.', 'Mantén el pecho abierto y los hombros bajos.', 'Respira profundo y sostén el estiramiento sin rebotes.', 'Evita forzar si notas pinchazo en la parte delantera del hombro.']::text[], 'principiante', 'Estira el hombro y el pecho, aliviando tensión tras sesiones de empuje o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1488'),
('38464454-a810-52b2-b874-51f14638efa7', 'Estiramiento de hombro con toalla detrás de la espalda', ARRAY['Sujeta una toalla por detrás de la espalda con una mano arriba y otra abajo.', 'Tira suavemente de la toalla con la mano de abajo para llevar el hombro de arriba hacia dentro.', 'Mantén la espalda recta y los hombros relajados.', 'Respira de forma pausada y sostén sin dolor.', 'Evita tirar en exceso o encoger el cuello.']::text[], 'principiante', 'Gana movilidad en el hombro y el manguito rotador usando una toalla como ayuda para estirar con control.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10932'),
('caf1deee-f669-5f2b-b2f9-739c2861475f', 'Toque al hombro', ARRAY['Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo.', 'Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda.', 'Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el core y los hombros manteniendo la plancha mientras alternas toques en cada hombro sin mover la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3699'),
('e11b6e92-a224-53d8-99ab-5991a409c9ea', 'Flexión con toque al hombro', ARRAY['Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo.', 'Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho.', 'Continúa alternando los toques de hombro en cada repetición de la flexión.', 'Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina el empuje de pecho y tríceps con la estabilidad del core al tocar el hombro contrario en cada repetición.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0699'),
('05d49bd9-dca2-5dec-b37d-f12e9e655435', 'Abducción transversal de hombro', ARRAY['Colócate de pie con los brazos extendidos hacia delante a la altura de los hombros.', 'Abre los brazos hacia los lados manteniendo los codos casi rectos.', 'Controla el movimiento sin encoger los hombros.', 'Respira con normalidad y vuelve despacio al centro.', 'Evita arquear la espalda o usar impulso.']::text[], 'principiante', 'Activa los deltoides posteriores y la espalda alta, mejorando la movilidad y estabilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2781'),
('a317ffa8-3710-5fa1-a9fd-36bcf58a4387', 'Aducción transversal de hombro', ARRAY['Extiende un brazo hacia el lado a la altura del hombro.', 'Lleva ese brazo por delante del pecho con la otra mano.', 'Mantén el hombro bajo y el tronco recto.', 'Sostén el estiramiento respirando despacio.', 'No fuerces el codo ni gires la espalda.']::text[], 'principiante', 'Estira y moviliza el pecho y la parte delantera del hombro, útil para compensar tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2782'),
('e2bc43a1-b22e-5b73-9a88-5d70143d274c', 'Extensión transversal de hombro', ARRAY['Ponte de pie con los brazos delante a la altura de los hombros.', 'Lleva los brazos hacia atrás abriendo el pecho sin arquear la espalda.', 'Junta ligeramente las escápulas al final del recorrido.', 'Vuelve al centro con control y respira con normalidad.', 'Evita echar el tronco hacia atrás o encoger el cuello.']::text[], 'principiante', 'Moviliza el hombro hacia atrás y activa la espalda alta y los deltoides posteriores.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2783'),
('2a0ad6d5-23f3-5cca-a3df-a3476f7ff924', 'Flexión transversal de hombro', ARRAY['Túmbate de lado con el brazo inferior estirado a la altura del hombro.', 'Lleva el brazo superior cruzando el pecho sin elevar el hombro.', 'Mantén el movimiento lento y controlado durante dos segundos.', 'Evita arquear la espalda o forzar el hombro hacia delante.']::text[], 'principiante', 'Moviliza el hombro y el pecho para ganar rango en el cruce del brazo y prevenir rigidez.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2784'),
('ab25c558-d1d4-5bde-8622-54476030a647', 'Dominada con agarre neutro a la anchura de los hombros', ARRAY['Cuélgate de la barra con las palmas enfrentadas y los brazos estirados.', 'Tira de los codos hacia abajo hasta que la barbilla pase la barra.', 'Baja despacio controlando el descenso sin dejarte caer.', 'Evita balancearte o encoger los hombros al iniciar el tirón.']::text[], 'intermedio', 'Fortalece dorsales y bíceps colgándote con las palmas enfrentadas a la anchura de los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5473'),
('9a640e1f-3075-56b3-88c0-0f8fbe48549f', 'Sentadilla shrimp', ARRAY['De pie sobre una pierna, lleva el pie libre detrás y agárralo con la mano.', 'Baja flexionando la rodilla de apoyo manteniendo el tronco erguido.', 'Desciende hasta donde controles y empuja para subir.', 'Evita que la rodilla se vaya hacia dentro o perder el equilibrio.']::text[], 'intermedio', 'Trabaja la fuerza unilateral de cuádriceps y glúteos con gran demanda de equilibrio y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3366'),
('136e3ec0-1233-580d-94b4-7c7d4b631328', 'Encogimiento en barras paralelas', ARRAY['Sujeta las paralelas con los brazos estirados y el cuerpo colgando.', 'Eleva los hombros hacia las orejas sin doblar los codos.', 'Mantén un segundo arriba y baja controlado.', 'Evita balancear el cuerpo o encoger solo un hombro.']::text[], 'intermedio', 'Fortalece los trapecios elevando los hombros con el peso del cuerpo sobre las paralelas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4176'),
('5ef5fe0f-df3e-5f05-93b3-a29571504521', 'Desplazamiento lateral', ARRAY['Adopta una postura atlética con rodillas ligeramente flexionadas.', 'Desplázate lateralmente con pasos cortos y rápidos.', 'Mantén el pecho arriba y los brazos activos.', 'Evita cruzar los pies o mirar al suelo.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la agilidad con desplazamientos rápidos de lado a lado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4257'),
('85e7c08b-e80d-50f4-902b-fbf530c29f68', 'Caminata lateral de oso', ARRAY['Colócate en cuadrupedia con las rodillas separadas del suelo.', 'Desplázate lateralmente moviendo mano y pie del mismo lado.', 'Mantén la espalda plana y las caderas bajas.', 'Evita elevar demasiado la cadera o dar pasos largos.']::text[], 'intermedio', 'Refuerza cuádriceps, hombros y core con un desplazamiento lateral en cuadrupedia baja.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3965'),
('e1d9d749-0d19-5f6c-a62e-7ee6bc854dfc', 'Sentadilla lateral en banco', ARRAY['Colócate de pie de lado a un banco a la altura de las rodillas.', 'Da un paso lateral y baja la cadera hacia el banco.', 'Empuja con la pierna de apoyo para volver de pie.', 'Evita dejar caer el peso o girar el tronco.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y aductores bajando lateralmente hacia un banco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4786'),
('174067ea-845a-5b83-80d9-e9e12a0b266e', 'Inclinación lateral en balón de estabilidad', ARRAY['Siéntate sobre el balón con los pies apoyados y la espalda recta.', 'Inclina el tronco hacia un lado manteniendo las caderas estables.', 'Vuelve al centro y cambia de lado.', 'Evita que el balón ruede o perder la alineación del tronco.']::text[], 'principiante', 'Refuerza oblicuos y zona lumbar inclinando el tronco sobre el balón con control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0700'),
('fe12a01c-bfff-537a-a08a-59b40a165c18', 'Puente lateral', ARRAY['Túmbate de lado apoyando el antebrazo bajo el hombro.', 'Eleva la cadera hasta formar una línea recta.', 'Mantén la posición respirando con normalidad.', 'Evita dejar caer la cadera o adelantar el hombro.']::text[], 'intermedio', 'Isométrico que fortalece oblicuos, glúteos y hombros manteniendo el cuerpo alineado de lado.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0706'),
('acd5f71c-bd42-5b7f-a8ef-33b126911060', 'Abducción de cadera en plancha lateral', ARRAY['Túmbate de lado con las piernas extendidas y una sobre la otra.', 'Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.', 'Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.', 'Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas.', 'Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Activa glúteo medio y oblicuos elevando la pierna superior durante la plancha lateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1774'),
('b3d58335-b41e-5eb4-9a83-86cf6339ebb2', 'Puente lateral con abducción de cadera (estrella)', ARRAY['Apóyate de lado sobre el antebrazo y eleva la cadera.', 'Separa la pierna superior del suelo formando una estrella.', 'Mantén la cadera alta y baja la pierna con control.', 'Evita rotar el tronco o perder la línea del cuerpo.']::text[], 'intermedio', 'Combina plancha lateral y elevación de pierna para glúteo medio, oblicuos y hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0703'),
('c6641ac7-62c7-5421-9d56-adfc144e7573', 'Puente lateral con balanceo de brazo y pierna', ARRAY['Colócate en plancha lateral con la cadera elevada.', 'Balancea el brazo superior y la pierna de arriba a la vez.', 'Vuelve al centro manteniendo la cadera alta.', 'Evita que la cadera caiga o el tronco rote.']::text[], 'intermedio', 'Reto de estabilidad que trabaja core, oblicuos y glúteos moviendo brazo y pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3584'),
('851ad993-6fc2-582f-a54c-2845f43799b6', 'Puente lateral con pierna flexionada', ARRAY['Túmbate de lado con la pierna inferior flexionada y el antebrazo apoyado.', 'Eleva la cadera hasta alinear hombro, cadera y rodilla.', 'Mantén la posición respirando de forma constante.', 'Evita adelantar el hombro o dejar caer la cadera.']::text[], 'intermedio', 'Versión accesible de la plancha lateral que fortalece oblicuos, glúteos y hombros.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '5047'),
('ca612970-3a38-5389-a4c1-7982d9bf9194', 'Puente lateral con piernas rectas', ARRAY['Apóyate de lado sobre el antebrazo con las piernas estiradas.', 'Eleva la cadera hasta formar una línea recta.', 'Aprieta glúteos y core para mantener la posición.', 'Evita que la cadera baje o el cuerpo se arquee.']::text[], 'intermedio', 'Plancha lateral avanzada que exige fuerza en oblicuos, glúteos y hombros con piernas estiradas.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4458'),
('cdc10ced-0d0d-5d09-b0cb-e244977ca546', 'Abdominal lateral', ARRAY['Túmbate de lado con las rodillas flexionadas y la cadera alineada con el tronco.', 'Coloca una mano en la sien y la otra apoyada en el suelo para estabilizarte.', 'Eleva el tronco acercando las costillas a la cadera y espira al subir.', 'Baja controlando el movimiento sin dejar caer la cabeza.', 'Evita tirar del cuello con la mano y mantén el movimiento lento.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos para ganar fuerza en el core y estabilidad en el tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0708'),
('d00ba920-e162-5e6d-9440-5e16c6bc9c39', 'Abdominal lateral con manos en el pecho', ARRAY['Túmbate de lado con las rodillas dobladas y las manos cruzadas sobre el pecho.', 'Mantén la cadera estable y el tronco alineado antes de empezar.', 'Eleva el torso lateralmente y espira al subir.', 'Baja despacio sin apoyar del todo para mantener la tensión.', 'No impulses con las piernas ni dejes que la cadera ruede hacia atrás.']::text[], 'intermedio', 'Fortalece oblicuos y core con las manos fijas en el pecho, evitando compensaciones del cuello.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4787'),
('29ba39b4-82e9-58d5-866c-87b655de34a0', 'Plancha con toque lateral al suelo', ARRAY['Colócate en plancha alta con manos bajo los hombros y cuerpo en línea recta.', 'Activa glúteos y abdomen para no hundir la cadera.', 'Levanta una mano y toca el suelo a un lado, luego vuelve a la plancha.', 'Alterna lados manteniendo la respiración constante.', 'Evita girar la cadera o perder la alineación al tocar el suelo.']::text[], 'intermedio', 'Refuerza el core y los oblicuos mientras trabajas estabilidad de hombros y glúteos en isométrico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8399'),
('32509588-429a-5494-897c-e75bc2266d20', 'Cadera de lado en paralelas', ARRAY['Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros.', 'Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos.', 'Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja oblicuos y flexores de cadera elevando las piernas lateralmente en suspensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0709'),
('6e6cddee-1e19-5f0a-bb10-c58ba243ca4f', 'Abducción de cadera lateral', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.', 'Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.', 'Repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa abductores y glúteos para mejorar la estabilidad de la cadera y la fuerza lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0710'),
('c9590bd4-b589-5726-9888-85efc28107f4', 'Salto lateral y subida al escalón', ARRAY['Colócate de pie junto a un escalón con los pies a la anchura de la cadera.', 'Salta lateralmente y sube al escalón apoyando el pie con seguridad.', 'Impulsa con la pierna de apoyo y aterriza con la rodilla ligeramente flexionada.', 'Mantén el tronco erguido y la mirada al frente durante el salto.', 'Evita aterrizar con la rodilla bloqueada o hacia dentro.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia cuádriceps y glúteos mejorando la explosividad y el equilibrio.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '2562'),
('5e548189-ec4d-5d0b-a53c-b1c559673c63', 'Salto lateral con giro', ARRAY['De pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta hacia un lado girando el tronco en el aire.', 'Aterriza suave con ambos pies y absorbe el impacto flexionando las rodillas.', 'Alterna la dirección del giro en cada repetición.', 'Evita girar solo con los brazos y mantén el abdomen activo.']::text[], 'intermedio', 'Mejora la potencia y la coordinación del core con un salto lateral que incluye rotación del tronco.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5124'),
('d6645eaa-495e-5af4-9149-6ebfb55e25df', 'Patada lateral', ARRAY['De pie con las manos en guardia y el peso sobre una pierna.', 'Eleva la pierna lateralmente extendiendo la rodilla con control.', 'Mantén el tronco erguido y el abdomen activo durante la patada.', 'Recoge la pierna despacio sin dejarla caer.', 'Evita inclinar el tronco hacia el lado contrario para no perder el equilibrio.']::text[], 'intermedio', 'Desarrolla abductores y glúteos con un gesto de combate que también exige control del core.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2307'),
('e2d29b97-3980-58d0-ba6e-db30f9bdfda8', 'Burpee con patada lateral', ARRAY['Desde de pie, baja a apoyar las manos y lleva los pies atrás a plancha.', 'Realiza una flexión y vuelve a recoger los pies hacia las manos.', 'Levántate y ejecuta una patada lateral con control.', 'Alterna la pierna de la patada en cada repetición.', 'Evita redondear la espalda al bajar y mantén un ritmo constante.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que combina fuerza de todo el cuerpo con una patada lateral explosiva.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3153'),
('e982335a-2234-54f6-983f-34ec241c6185', 'Patada lateral pasando por debajo', ARRAY['Colócate en cuadrupedia con las manos bajo los hombros.', 'Eleva una pierna y pásala por debajo del cuerpo hacia el lado contrario.', 'Extiende la pierna lateralmente sin perder la alineación del tronco.', 'Recoge la pierna y alterna lados con control.', 'Evita arquear la zona lumbar o girar la cadera en exceso.']::text[], 'intermedio', 'Trabaja el core y los oblicuos con un movimiento de patada que cruza por debajo del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6335'),
('306685f5-e454-5c1c-9731-a614a9c1c7a4', 'Estiramiento lateral de dorsal', ARRAY['De pie, eleva un brazo por encima de la cabeza.', 'Inclina el tronco hacia el lado contrario llevando la cadera hacia fuera.', 'Mantén la posición sintiendo el estiramiento en el costado.', 'Respira profundo y aguanta entre veinte y treinta segundos.', 'Evita rebotar o forzar la curvatura lumbar.']::text[], 'principiante', 'Estira el dorsal ancho y la zona lateral del tronco para aliviar tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1802');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('3bc80ffb-36ce-5b1c-a85b-1dde9621d977', 'Zancada lateral', ARRAY['De pie con los pies juntos y las manos en la cadera.', 'Da un paso amplio hacia un lado y flexiona esa rodilla.', 'Empuja la cadera atrás manteniendo la otra pierna estirada.', 'Vuelve al centro empujando con la pierna flexionada.', 'Evita que la rodilla pase por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y aductores mejorando la movilidad y la fuerza en el plano lateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2972'),
('6a1819c4-329e-5b01-bc25-9d242f097778', 'Estiramiento de aductores con zancada lateral', ARRAY['Abre las piernas en una zancada lateral amplia.', 'Flexiona una rodilla y lleva la cadera hacia atrás.', 'Mantén la otra pierna estirada sintiendo el estiramiento en la ingle.', 'Respira profundo y aguanta sin rebotar.', 'Evita forzar más de lo que permite tu flexibilidad.']::text[], 'principiante', 'Estira los aductores y la cara interna del muslo para mejorar la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1899'),
('6096230c-90aa-5fad-83a4-1a4b61413dbb', 'Estiramiento de zancada lateral', ARRAY['Siéntate o ponte de pie con las piernas bien abiertas.', 'Inclina el tronco hacia un lado flexionando esa rodilla.', 'Mantén la otra pierna estirada y el pie apuntando al frente.', 'Respira de forma pausada durante el estiramiento.', 'Evita curvar la espalda y baja solo hasta donde controles.']::text[], 'principiante', 'Relaja aductores e isquiotibiales con una postura lateral que mejora la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0711'),
('e7e53f2e-b7f5-5743-9e44-293859c6e330', 'Estiramiento de pecho acostado de lado', ARRAY['Túmbate de lado con el brazo inferior extendido hacia delante.', 'Flexiona la rodilla de arriba y apóyala para estabilizarte.', 'Gira el tronco suavemente hacia atrás abriendo el pecho.', 'Mantén la posición respirando profundo sin forzar.', 'Evita girar la cadera o levantar el hombro del suelo.']::text[], 'principiante', 'Estira el pectoral y la parte anterior del hombro para compensar la postura encorvada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '8289'),
('2585c0fd-8122-5823-a958-82936b6aade2', 'Almeja acostado de lado', ARRAY['Túmbate de lado con las rodillas flexionadas y los pies juntos, la cadera apilada.', 'Mantén los talones en contacto y abre la rodilla superior sin mover la pelvis.', 'Sube despacio, aguanta un segundo arriba y baja controlando.', 'Evita girar el tronco hacia atrás para abrir más la rodilla.', 'Respira de forma continua y no dejes caer la cadera en ningún momento.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para estabilizar la cadera y prevenir molestias en rodilla y lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2461'),
('2aecb289-474c-5747-8976-1c054a27996a', 'Elevación diagonal de pierna hacia atrás acostado de lado', ARRAY['Colócate de lado con las piernas estiradas y el cuerpo alineado.', 'Lleva la pierna superior hacia atrás y en diagonal, sin rotar la cadera.', 'Aprieta el glúteo arriba y baja la pierna con control.', 'Mantén el core firme para que la lumbar no se arquee.', 'Evita impulsarte con el tronco; el movimiento nace de la cadera.']::text[], 'intermedio', 'Activa el glúteo mayor y los isquios con un gesto diagonal que mejora la extensión de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6751'),
('7023cc73-0e09-52df-850f-cd3c2643119b', 'Rotación externa acostado de lado', ARRAY['Túmbate de lado con el codo pegado al costado y flexionado a 90 grados.', 'Gira el antebrazo hacia arriba manteniendo el codo fijo contra las costillas.', 'Sube despacio y baja aún más lento, sin mover el hombro.', 'Evita despegar el codo del cuerpo o encoger el hombro.', 'Usa un rango cómodo y respira con normalidad durante todo el recorrido.']::text[], 'principiante', 'Refuerza el manguito rotador y la parte posterior del hombro para estabilizar la articulación.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10933'),
('2af8d180-3e47-5bde-ba36-402323e163a4', 'Elevación de pies acostado de lado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva el pie inferior unos centímetros sin separar la pierna superior.', 'Sube despacio, aguanta arriba y baja con control.', 'Mantén el core activo para no balancear la cadera.', 'Evita arquear la lumbar o girar el tronco hacia atrás.']::text[], 'intermedio', 'Trabaja los aductores y la cara interna del muslo, mejorando la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0712'),
('6ddf8f14-2118-58e3-a4a4-3a474772858b', 'Estiramiento de costado en el suelo', ARRAY['Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza.', 'Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo.', 'Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble.', 'Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado.', 'Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo.', 'Repite del otro lado.']::text[], 'principiante', 'Estira el dorsal y la zona lateral del tronco, aliviando tensión tras el trabajo de espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1358'),
('0607e440-3687-52b4-a179-48bc121179ef', 'Aducción de cadera acostado de lado', ARRAY['Túmbate de lado con la pierna inferior estirada y la superior flexionada por delante.', 'Eleva la pierna inferior hacia el techo sin rotar la cadera.', 'Sube despacio, aprieta arriba y baja controlando el movimiento.', 'Mantén el tronco estable y el core activo.', 'Evita balancear la pelvis o usar impulso para subir la pierna.']::text[], 'intermedio', 'Fortalece los aductores y la cara interna del muslo, clave para la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5998'),
('73036bb9-905b-5fcb-86df-f4392d84e1a8', 'Rotación interna acostado de lado', ARRAY['Túmbate de lado con el codo pegado al costado y flexionado a 90 grados.', 'Gira el antebrazo hacia abajo manteniendo el codo fijo contra el cuerpo.', 'Baja despacio y vuelve con control, sin mover el hombro.', 'Evita despegar el codo o encoger el hombro hacia la oreja.', 'Trabaja en un rango cómodo y sin dolor, respirando con normalidad.']::text[], 'principiante', 'Trabaja el manguito rotador en rotación interna para recuperar movilidad y control del hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '7213'),
('f9ea8c4d-4d7d-55e9-969a-2c7e1edea3c8', 'Círculo de pierna acostado de lado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva la pierna superior y dibuja círculos pequeños y controlados.', 'Mantén el core activo y la cadera apilada durante todo el círculo.', 'Cambia de sentido tras varias repeticiones sin bajar la pierna.', 'Evita arquear la lumbar o girar el tronco hacia atrás.']::text[], 'intermedio', 'Mejora la movilidad y el control de la cadera trabajando abductores, glúteos y core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '3926'),
('dc0ee2c9-3471-53d5-992c-63c6a61c441e', 'Elevación de pierna acostado de lado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva la pierna superior hasta unos 45 grados sin rotar la cadera.', 'Sube despacio, aguanta un segundo y baja con control.', 'Mantén el core firme y el pie en posición neutra.', 'Evita impulsarte con el tronco o dejar caer la pierna de golpe.']::text[], 'intermedio', 'Fortalece abductores y glúteos para estabilizar la cadera y mejorar el control del miembro inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4051'),
('561d164f-a2ec-50a9-9a27-ebc80e44f574', 'Patada de rodilla hacia afuera acostado de lado', ARRAY['Túmbate de lado con las rodillas flexionadas y los pies juntos.', 'Abre la rodilla superior hacia arriba y hacia atrás en un gesto de patada.', 'Vuelve despacio a la posición inicial sin juntar del todo.', 'Mantén la pelvis estable y el core activo.', 'Evita girar el tronco o despegar la cadera del suelo.']::text[], 'intermedio', 'Activa abductores y glúteos con un gesto de rotación externa que mejora la estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4884'),
('18b85886-1157-586b-bf12-1e40fd71841a', 'Tijeras acostado de lado', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva ambas piernas y cruza una sobre la otra como unas tijeras.', 'Alterna el cruce de forma controlada sin tocar el suelo.', 'Mantén el core activo y la cadera apilada.', 'Evita arquear la lumbar o balancear el tronco.']::text[], 'intermedio', 'Trabaja abductores y oblicuos con un movimiento alterno que mejora la coordinación y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4882'),
('cbe80e9e-4f89-5c28-aff7-aa9adfd23469', 'Escalador lateral', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Lleva una rodilla hacia el codo del mismo lado y vuelve a la plancha.', 'Alterna los lados a un ritmo constante y controlado.', 'Mantén la cadera baja y el core firme sin hundir la lumbar.', 'Evita rebotar o perder la alineación de hombros y cadera.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja core y oblicuos con un movimiento dinámico y lateral.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5680'),
('1bf8a03c-ae05-5b75-8083-7a7b5fcca794', 'Elevación de pierna flexionada en plancha lateral', ARRAY['Colócate en plancha lateral apoyando el antebrazo y la rodilla inferior.', 'Eleva la pierna superior flexionada manteniendo la cadera alta.', 'Aprieta el glúteo arriba y baja con control.', 'Mantén el cuerpo alineado y el core activo.', 'Evita dejar caer la cadera o girar el tronco hacia el suelo.']::text[], 'intermedio', 'Refuerza el core y los oblicuos en isométrico mientras activa glúteos con la elevación de pierna.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6466'),
('54ea4192-47b3-50ca-b426-98ace9df6657', 'Plancha lateral, glúteos (control de técnica)', ARRAY['Colócate en plancha lateral con el antebrazo apoyado y el cuerpo alineado.', 'Aprieta los glúteos para mantener la cadera alta y estable.', 'Mantén la posición respirando de forma continua.', 'Evita dejar caer la cadera o adelantar los hombros.', 'Si pierdes la alineación, descansa y vuelve a colocarte.']::text[], 'intermedio', 'Isométrico que refuerza oblicuos y core, con control de glúteos para estabilizar la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2349'),
('1c6e0281-13bf-50bd-b4f1-8e3217c80313', 'Almeja en plancha lateral', ARRAY['Colócate en plancha lateral con las rodillas flexionadas y los pies juntos.', 'Abre la rodilla superior como una almeja sin mover la pelvis.', 'Sube despacio, aguanta arriba y baja con control.', 'Mantén la cadera alta y el core activo durante todo el movimiento.', 'Evita girar el tronco o dejar caer la cadera al abrir la rodilla.']::text[], 'intermedio', 'Combina isométrico lateral con abducción de cadera para trabajar oblicuos, glúteos y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9849'),
('6f09e317-3304-5800-ad1d-9ca86c9e7531', 'Aducción de cadera en plancha lateral', ARRAY['Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.', 'Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.', 'Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.', 'Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.', 'Baja lentamente la pierna de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece los aductores y el core mientras mantienes el equilibrio sobre un costado, mejorando la estabilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1775'),
('f5eee73f-f499-5986-8ccc-73786ef504ff', 'Elevación de pierna en plancha lateral', ARRAY['Colócate de lado apoyando el antebrazo bajo el hombro y las piernas estiradas.', 'Eleva la cadera hasta formar una línea recta desde la cabeza hasta los pies.', 'Sube la pierna superior sin rotar la cadera y baja con control.', 'Mantén la respiración fluida y evita que la cadera caiga hacia el suelo.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con una elevación controlada de la pierna superior, ganando estabilidad y control postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4863'),
('fd1ec57c-a3ab-5eed-9988-7eb3cb8d4b12', 'Abdominal oblicuo en plancha lateral', ARRAY['Apóyate de lado sobre el antebrazo con los pies apilados y la cadera elevada.', 'Lleva la mano libre hacia la cadera o el codo inferior flexionando el costado.', 'Vuelve a la posición inicial sin dejar caer la cadera.', 'Controla el tempo y evita rotar el tronco durante el recorrido.']::text[], 'intermedio', 'Activa los oblicuos y el abdomen con un movimiento de flexión lateral que refuerza la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4334'),
('5e7062a2-748f-5f2b-ae65-b9f829a7ec2e', 'Jalón en plancha lateral', ARRAY['Colócate en plancha lateral sobre el antebrazo con el cuerpo alineado.', 'Extiende el brazo libre hacia arriba y simula un jalón llevándolo hacia el pecho.', 'Mantén la cadera alta y el abdomen firme durante todo el movimiento.', 'Respira de forma constante y evita que el tronco gire.']::text[], 'intermedio', 'Combina isometría lateral con un tirón que activa el abdomen, los oblicuos y la musculatura estabilizadora del hombro.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '6026'),
('f8f99e51-18c3-5a36-8498-c04aa93e4b4b', 'Rotación en plancha lateral', ARRAY['Apóyate de lado sobre el antebrazo con las piernas estiradas y la cadera elevada.', 'Lleva el brazo libre hacia el techo y rota el tronco abriendo el pecho.', 'Vuelve a pasar el brazo por debajo del cuerpo sin perder la alineación.', 'Mantén la cadera estable y evita arquear la zona lumbar.']::text[], 'intermedio', 'Fortalece el core y los oblicuos con una rotación controlada que mejora la movilidad y estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4991'),
('7c3472a0-4987-5824-906f-884b24a337db', 'Elevación de deltoides con giro de brazo en plancha lateral', ARRAY['Colócate en plancha lateral sobre el antebrazo con el cuerpo en línea.', 'Eleva el brazo libre hacia arriba y gíralo suavemente hacia atrás.', 'Baja el brazo con control sin dejar caer la cadera.', 'Mantén el abdomen activo y evita rotar el tronco en exceso.']::text[], 'intermedio', 'Trabaja el abdomen, los oblicuos y el hombro con una elevación y giro que exige control y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7854'),
('53059017-ce19-5cd6-8080-498c266eb068', 'Plancha lateral con pierna elevada', ARRAY['Apóyate de lado sobre el antebrazo con los pies apilados.', 'Eleva la cadera y separa la pierna superior del suelo.', 'Mantén la línea recta desde la cabeza hasta los pies.', 'Respira con normalidad y evita que la cadera descienda.']::text[], 'intermedio', 'Incrementa la exigencia del core y los glúteos al mantener la pierna superior elevada durante la isometría lateral.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4907'),
('fa9f77ac-5173-54db-beba-b04a243ce907', 'Flexión lateral con toalla', ARRAY['Coloca la toalla en el suelo y apoya una mano sobre ella en posición de flexión.', 'Baja el pecho de forma controlada manteniendo el cuerpo alineado.', 'Empuja para volver arriba sin bloquear los codos.', 'Evita que la cadera se hunda o rote durante el movimiento.']::text[], 'intermedio', 'Refuerza el pecho, los tríceps y el core con una flexión lateral que añade inestabilidad mediante la toalla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3922'),
('7f200c05-808a-5ac6-b672-14c376067542', 'Desplazamiento lateral con rodillas altas', ARRAY['Adopta una postura erguida con los pies a la anchura de las caderas.', 'Desplázate lateralmente elevando las rodillas de forma alterna.', 'Mantén un ritmo constante y los brazos activos.', 'Evita cruzar los pies y aterriza suavemente con la planta completa.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la coordinación con desplazamientos laterales y rodillas elevadas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '7154'),
('42d38d0f-7c47-5c08-93bc-a8ad298ffd94', 'Carrera lateral de ida y vuelta', ARRAY['Marca dos puntos separados y colócate en uno de ellos.', 'Desplázate lateralmente hasta el otro punto y vuelve.', 'Mantén las rodillas ligeramente flexionadas y el tronco erguido.', 'Evita cruzar los pies y controla la frenada en cada cambio.']::text[], 'intermedio', 'Entrena el sistema cardiovascular y la agilidad con desplazamientos laterales rápidos de ida y vuelta.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3551'),
('a458f79d-46d8-5506-a838-ab2324aeb8b6', 'Abdominal lateral con incorporación', ARRAY['Túmbate de lado con las piernas flexionadas y el brazo apoyado.', 'Eleva el tronco hacia la cadera contrayendo el costado.', 'Baja con control sin dejarte caer.', 'Evita tirar del cuello y mantén el movimiento en el abdomen.']::text[], 'intermedio', 'Fortalece los oblicuos y el abdomen con una incorporación lateral que trabaja la flexión del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0718'),
('9a43227a-ce5f-5833-adfc-ac1e6bdc9d98', 'Abertura de piernas', ARRAY['Siéntate con las piernas abiertas y la espalda recta.', 'Inclínate lentamente hacia delante desde la cadera.', 'Mantén la posición sin rebotes y respira profundamente.', 'Evita forzar si notas dolor agudo en la ingle.']::text[], 'principiante', 'Estira los aductores y la cara interna del muslo, mejorando la movilidad de la cadera de forma progresiva.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3458'),
('c71d01a6-40e8-5e97-9d8d-18d0815b5122', 'Sentadilla dividida lateral', ARRAY['Coloca los pies bien separados con las puntas ligeramente hacia fuera.', 'Flexiona una rodilla llevando la cadera hacia ese lado.', 'Empuja con la pierna flexionada para volver al centro.', 'Mantén el tronco erguido y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y aductores con una sentadilla en posición lateral que mejora la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4788'),
('c6b5e022-adef-5223-b3f5-c93045bda3bd', 'Sentadilla lateral', ARRAY['Separa los pies ampliamente con las puntas hacia fuera.', 'Desplaza la cadera hacia un lado flexionando esa rodilla.', 'Mantén la otra pierna estirada y el tronco erguido.', 'Empuja para volver al centro y alterna lados sin perder el control.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y aductores con un desplazamiento lateral que mejora la fuerza y la movilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4789'),
('7b65a2d4-7de6-56bc-8d9c-29aa84f9dcea', 'Plancha frontal con paso lateral', ARRAY['Colócate en plancha sobre antebrazos con el cuerpo alineado.', 'Da un paso lateral con una mano y luego con la otra.', 'Mantén la cadera estable y el abdomen activo.', 'Evita hundir la zona lumbar mientras te desplazas.']::text[], 'intermedio', 'Refuerza el core y los hombros con una plancha que añade desplazamientos laterales para ganar estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3958'),
('643afb71-84c2-54af-a8be-1f447de4cb89', 'Remo con paso lateral para deltoide posterior', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y el tronco inclinado hacia delante.', 'Da un paso lateral mientras llevas los codos hacia atrás juntando las escápulas.', 'Vuelve al centro y repite hacia el otro lado manteniendo el abdomen firme.', 'Evita redondear la espalda o tirar con los brazos en lugar de con la espalda.']::text[], 'intermedio', 'Fortalece la espalda alta y los hombros posteriores mientras activa piernas y glúteos en un gesto dinámico.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6011'),
('854805d1-64c2-56aa-98d3-ecc196a3d20d', 'Abdominal con estiramiento lateral', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las manos detrás de la cabeza.', 'Eleva ligeramente el tronco y desplaza un brazo hacia el lado contrario estirando el costado.', 'Vuelve al centro y alterna hacia el otro lado sin tirar del cuello.', 'Espira al estirar y evita despegar la zona lumbar del suelo.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos combinando flexión y alargamiento del costado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0719'),
('f2257ec8-aeeb-5de4-96d9-b52560211127', 'Desplazamiento lateral sobre el cajón', ARRAY['Colócate junto al cajón con los pies a la anchura de las caderas.', 'Sube un pie sobre el cajón y desplaza el peso para apoyar el otro rápidamente.', 'Baja y repite hacia el otro lado manteniendo un ritmo constante.', 'Evita apoyar solo la punta del pie o mirar al suelo durante el movimiento.']::text[], 'intermedio', 'Mejora la coordinación y la resistencia cardiovascular con apoyos rápidos sobre el cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1588'),
('32bf39ff-8132-5fb6-bf82-72c89bbbfa0b', 'Salto de lado a lado', ARRAY['Colócate de pie con las rodillas ligeramente flexionadas y los brazos sueltos.', 'Salta hacia un lado cayendo sobre la parte delantera de los pies.', 'Amortigua la caída y salta de inmediato hacia el lado contrario.', 'Evita aterrizar con las piernas rígidas o juntar demasiado las rodillas.']::text[], 'intermedio', 'Activa los gemelos y tobillos con saltos laterales que mejoran la reactividad y el equilibrio.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5153'),
('e70768f3-69bd-508d-91d2-3f75886fa356', 'Salto lateral sobre el step', ARRAY['Sitúate junto al step con los pies juntos y las rodillas algo flexionadas.', 'Impulsa con ambos pies y salta lateralmente por encima del step.', 'Aterriza suavemente con las rodillas alineadas y amortigua el impacto.', 'Evita saltar sin mirar el obstáculo o caer con los pies demasiado juntos.']::text[], 'intermedio', 'Potencia piernas y glúteos con un salto explosivo que también exige control del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10732'),
('4b7113e6-4120-5cd9-aa9f-3d3ebcfeefff', 'Salto de cuerda de lado a lado', ARRAY['Sujeta la cuerda con las manos a la altura de las caderas y los codos cerca del cuerpo.', 'Salta girando la cuerda y desplázate ligeramente hacia un lado.', 'Mantén un ritmo constante alternando la dirección del desplazamiento.', 'Evita saltar demasiado alto o bloquear los hombros durante el ejercicio.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y la coordinación con desplazamientos laterales mientras saltas a la cuerda.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3675'),
('be31f799-00fd-57f5-80ff-2a7fbce3b256', 'Balanceo de piernas de lado a lado', ARRAY['Apóyate en una pared o barra y levanta una pierna del suelo.', 'Balancea la pierna de forma controlada de un lado a otro sin forzar.', 'Mantén el tronco erguido y la pierna de apoyo ligeramente flexionada.', 'Evita rebotar con fuerza o girar la cadera durante el balanceo.']::text[], 'principiante', 'Moviliza los aductores y la cadera preparando las piernas para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4630'),
('723107ed-aa1e-5f50-9176-c02ceab6e14d', 'Sentadilla de lateral a abierta', ARRAY['Colócate de pie con los pies juntos y los brazos delante del pecho.', 'Baja en sentadilla manteniendo las rodillas alineadas con los pies.', 'Sube y abre los pies para hacer una sentadilla más amplia.', 'Evita que las rodillas se metan hacia dentro o levantar los talones.']::text[], 'intermedio', 'Fortalece glúteos y muslos alternando una sentadilla estrecha con otra más amplia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4909'),
('f91e500a-80b9-5459-b038-8aacfa355321', 'Toque de punta de pie lateral', ARRAY['Siéntate o colócate de pie con las piernas estiradas y los brazos a los lados.', 'Inclina el tronco hacia un lado y toca la punta del pie con la mano.', 'Vuelve al centro y repite hacia el otro lado de forma controlada.', 'Evita curvar la espalda o rebotar para llegar más lejos.']::text[], 'principiante', 'Activa el abdomen y los oblicuos con un movimiento de flexión lateral controlado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3250'),
('7c999cc7-83e9-55e3-83cf-8cf7b05f0332', 'Giro lateral', ARRAY['Siéntate con las rodillas flexionadas y el tronco erguido.', 'Gira el tronco hacia un lado llevando las manos al costado.', 'Vuelve al centro y alterna hacia el otro lado sin mover las caderas.', 'Evita girar con impulso o perder la posición de la espalda.']::text[], 'intermedio', 'Trabaja la cintura y el core con rotaciones controladas que mejoran la movilidad del tronco.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2866'),
('326d61cc-0862-537d-b575-435c7b153e47', 'Toque lateral de ambas puntas de pie', ARRAY['Colócate de pie con las piernas estiradas y los brazos extendidos.', 'Inclínate hacia un lado y toca la punta del pie con ambas manos.', 'Vuelve al centro y repite hacia el otro lado sin rebotar.', 'Evita flexionar demasiado las rodillas o forzar la espalda baja.']::text[], 'principiante', 'Mejora la flexibilidad de isquiotibiales y la movilidad del tronco con toques alternos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3251'),
('73070a3b-6077-507e-95c9-be14a57cdf9e', 'Salto lateral al banco', ARRAY['Colócate junto al banco con las rodillas flexionadas y los brazos atrás.', 'Impulsa con ambos pies y salta lateralmente para subir al banco.', 'Aterriza suavemente con las rodillas alineadas y el tronco estable.', 'Evita saltar sin control o caer con las piernas rígidas.']::text[], 'intermedio', 'Desarrolla potencia en cuádriceps y glúteos con un salto lateral sobre el banco.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '2561'),
('fd0ebb0d-7739-57e1-9b24-21be2b301842', 'Estiramiento de muñeca con tracción lateral', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.', 'Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo.', 'Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho.', 'Mantén el estiramiento durante 15-30 segundos, luego suelta.', 'Repite del otro lado.']::text[], 'principiante', 'Alarga los flexores y extensores de la muñeca para aliviar tensión y mejorar la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0721'),
('4e6f4b33-f63f-5a54-b282-8c3f9a14b078', 'Dominada de lado a lado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado.', 'Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto.', 'Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda y los brazos con dominadas que desplazan el peso de un lado a otro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0720'),
('7bfb529b-62e6-5296-a712-b911a472f97e', 'Toque de pies de lado a lado', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.', 'Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado.', 'Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado.', 'Repite el movimiento de flexión lateral el número de repeticiones deseado.']::text[], 'principiante', 'Activa el abdomen y los oblicuos con flexiones laterales que también movilizan la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3213'),
('e4e44204-806c-5bd7-aa7b-02002630d913', 'Puente lateral con pierna', ARRAY['Túmbate de lado con el codo bajo el hombro y las rodillas flexionadas.', 'Eleva la cadera hasta formar una línea recta entre hombro, cadera y rodilla.', 'Extiende la pierna superior sin dejar caer la cadera.', 'Mantén la posición respirando con normalidad y baja con control.', 'Evita arquear la zona lumbar: aprieta el glúteo antes de subir.']::text[], 'intermedio', 'Fortalece glúteos y oblicuos manteniendo la cadera elevada sobre un solo pie, mejorando estabilidad y control lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0722'),
('d5e7790c-e3ce-5362-9796-56449a43d197', 'Elevaciones laterales verticales con piernas rectas', ARRAY['Túmbate de lado con el cuerpo alineado y las piernas estiradas.', 'Apoya el brazo inferior y eleva el torso hacia arriba con control.', 'Mantén las piernas juntas y el cuello en línea con la columna.', 'Baja lentamente sin dejarte caer y repite el movimiento.', 'Evita impulsarte con el brazo: el esfuerzo debe venir del abdomen.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos elevando el torso lateralmente con las piernas estiradas, mejorando el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0723'),
('7405d351-13d6-540a-95cb-f90d73f18a01', 'Elevaciones laterales verticales con giro', ARRAY['Túmbate de lado con las piernas estiradas y el cuerpo alineado.', 'Eleva el torso y gira el tronco hacia el suelo al subir.', 'Controla el giro sin mover las piernas de su posición.', 'Deshaz el giro al bajar y repite con ritmo constante.', 'Evita tirar del cuello: mantén la mirada al frente.']::text[], 'intermedio', 'Combina la elevación lateral del torso con una rotación que activa oblicuos y core, mejorando la fuerza rotacional.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0724'),
('7f2831c8-2f5f-5168-a2b2-ae2bf5a80e7c', 'Burpee silencioso', ARRAY['Desde de pie, baja en cuclillas y apoya las manos en el suelo.', 'Lleva los pies atrás a plancha y vuelve a traerlos sin saltar.', 'Levántate y salta suavemente, amortiguando con las rodillas.', 'Aterriza con las puntas de los pies para no hacer ruido.', 'Evita bloquear las rodillas al caer: flexiona ligeramente.']::text[], 'intermedio', 'Ejercicio cardiovascular completo que eleva la frecuencia cardíaca y trabaja piernas, pecho y core con un aterrizaje suave.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5039'),
('7df0157f-b5b2-59dc-ae2c-f6c133eebf95', 'Press de dedos a un brazo con pelota', ARRAY['Sujeta la pelota con la palma y los dedos de una mano.', 'Presiona con los dedos como si quisieras aplastarla.', 'Mantén la presión unos segundos y relaja despacio.', 'Repite de forma controlada sin mover la muñeca.', 'Evita apretar solo con la palma: usa también las puntas de los dedos.']::text[], 'intermedio', 'Refuerza antebrazos, manos y agarre presionando una pelota con los dedos de una mano, mejorando la fuerza de prensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '11791'),
('936542a3-f964-594c-85dc-38c0afebdf20', 'Elevación de pies a la barra colgado a un brazo', ARRAY['Cuélgate de la barra con un solo brazo y el cuerpo extendido.', 'Activa el hombro y el core antes de iniciar el movimiento.', 'Eleva las piernas rectas hasta tocar la barra con los pies.', 'Baja lentamente controlando el descenso y la respiración.', 'Evita balancearte: mantén el cuerpo quieto en cada repetición.']::text[], 'intermedio', 'Ejercicio avanzado de abdomen que eleva las piernas hasta la barra colgado de un brazo, exigiendo gran agarre y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11091'),
('704080ed-1a6e-5dda-ba50-a913d9817229', 'Estiramiento de dorsal a un brazo contra la pared', ARRAY['Apoya la palma de una mano en la pared a la altura del hombro.', 'Gira el tronco hacia el lado contrario sin mover el brazo.', 'Inclina el cuerpo hacia delante hasta notar el estiramiento.', 'Mantén la posición respirando profundo y cambia de lado.', 'Evita encoger el hombro: mantenlo bajo y relajado.']::text[], 'principiante', 'Estira el dorsal y el hombro apoyando un brazo en la pared, aliviando tensión tras el entrenamiento de espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7623'),
('13289b01-8495-5607-b5ba-05ffb9c4e8b8', 'Sentadilla con mancuerna sobre la cabeza a un brazo', ARRAY['Sujeta la mancuerna con un brazo extendido sobre la cabeza.', 'Separa los pies a la anchura de los hombros y activa el core.', 'Baja en sentadilla manteniendo el brazo vertical.', 'Empuja con los talones para subir sin perder la alineación.', 'Evita inclinar el tronco: mantén el peso centrado.']::text[], 'intermedio', 'Sentadilla unilateral con mancuerna sobre la cabeza que trabaja piernas y core, exigiendo estabilidad y equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5096'),
('d879efce-e17c-5416-9fd6-9c892d25647c', 'Flexión a un brazo de rodillas', ARRAY['Colócate en plancha sobre las rodillas con una mano en el suelo.', 'Mantén la otra mano en la espalda y el cuerpo alineado.', 'Baja el pecho flexionando el codo hasta rozar el suelo.', 'Empuja para subir controlando el movimiento y la respiración.', 'Evita abrir la cadera: mantén el core firme.']::text[], 'intermedio', 'Variante de flexión apoyada en las rodillas que trabaja pecho y tríceps con un solo brazo, desarrollando fuerza unilateral.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3002'),
('ad09eb34-8d49-58fd-9171-b854c5cb98ff', 'Flexión a un brazo sobre balón medicinal', ARRAY['Apoya una mano sobre el balón medicinal y la otra en el suelo.', 'Coloca el cuerpo en plancha con los pies separados.', 'Baja el pecho flexionando ambos codos con control.', 'Empuja para subir manteniendo el balón estable.', 'Evita que el balón ruede: aprieta el core y fija la muñeca.']::text[], 'intermedio', 'Flexión unilateral con la mano sobre un balón medicinal que añade inestabilidad y trabaja pecho, tríceps y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '4121'),
('70f2252d-67e8-534e-a329-cb16533a7f38', 'Flexión de escápula a un brazo', ARRAY['Colócate en plancha con un brazo y las rodillas apoyadas.', 'Sin doblar el codo, junta las escápulas y baja el pecho.', 'Empuja el suelo para separar las escápulas y volver.', 'Realiza el movimiento lento y controlado con la respiración.', 'Evita doblar el codo: el movimiento es solo del hombro.']::text[], 'intermedio', 'Movimiento de retracción escapular que activa el serrato anterior y estabiliza el hombro, útil como calentamiento.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2946'),
('9920dae8-3629-57a2-bd4d-fe670cda3361', 'Jalón dorsal lateral con brazo recto a un brazo', ARRAY['Colócate de lado a la polea y agarra el mango con una mano.', 'Con el brazo recto, lleva el mango hacia la cadera.', 'Mantén el codo extendido y el core activo durante el recorrido.', 'Vuelve despacio controlando la polea y repite.', 'Evita encoger el hombro: mantenlo bajo y alejado de la oreja.']::text[], 'principiante', 'Jalón en polea con brazo recto que aísla el dorsal y mejora la conexión mente-músculo en la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5844'),
('a1c9f376-2ea7-55d8-9033-73015febbc40', 'Zancada de reverencia', ARRAY['De pie, cruza una pierna por detrás de la otra.', 'Baja flexionando las rodillas manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el core activo y la mirada al frente.', 'Evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Zancada cruzada que trabaja glúteos y aductores, mejorando el equilibrio y la fuerza unilateral de las piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6318'),
('6cc78fcf-a608-5483-a31f-e88bdcca827f', 'Abdominal declinado sobre la cabeza con una mancuerna', ARRAY['Túmbate en el banco declinado con los pies fijados.', 'Sujeta la mancuerna con ambas manos sobre el pecho.', 'Sube el tronco y eleva la mancuerna por encima de la cabeza.', 'Baja con control hasta la posición inicial respirando.', 'Evita tirar del cuello: el movimiento nace del abdomen.']::text[], 'intermedio', 'Ejercicio de abdomen en banco declinado que eleva una mancuerna sobre la cabeza, trabajando rectos y flexores de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5237'),
('147b1a8d-d796-5ba0-80d6-03fe4744fb7c', 'Estiramiento de aquiles con caída de talón', ARRAY['Apoya la punta del pie en un escalón con el talón al aire.', 'Baja el talón lentamente hasta notar el estiramiento.', 'Mantén la posición unos segundos sin rebotar.', 'Sube despacio y repite con la otra pierna.', 'Evita forzar el tobillo: el estiramiento debe ser cómodo.']::text[], 'principiante', 'Estiramiento del tendón de Aquiles y gemelos que mejora la flexibilidad del tobillo y previene molestias en la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1886'),
('8dc643ab-daec-5b39-893b-356a79e90684', 'Estiramiento de gemelos con caída de talón', ARRAY['Coloca la punta del pie en un escalón o bordillo y sujétate para mantener el equilibrio.', 'Deja caer el talón lentamente hasta notar el estiramiento en la parte baja de la pierna.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita rebotar o forzar el tobillo más allá de una molestia leve.']::text[], 'principiante', 'Estira el gemelo y el sóleo, mejora la flexibilidad del tobillo y alivia la tensión tras correr o saltar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1925'),
('c9b643c2-d641-5351-a52b-f8ab9f809ff7', 'Estiramiento de cuádriceps inclinado hacia atrás a una pierna', ARRAY['De pie, sujeta el empeine de un pie con la mano del mismo lado.', 'Lleva la rodilla hacia atrás y empuja la cadera ligeramente hacia delante.', 'Mantén el equilibrio con el core activo y respira de forma pausada.', 'Evita arquear la zona lumbar en exceso mientras estiras.']::text[], 'principiante', 'Estira la parte frontal del muslo y el flexor de cadera, útil para mejorar la movilidad tras entrenar piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1955'),
('8bc47e67-55ef-52ee-8b21-fb57b1006aee', 'Puñetazo cruzado en equilibrio a una pierna', ARRAY['Levántate sobre una pierna con la rodilla ligeramente flexionada.', 'Lanza un puñetazo cruzado girando el tronco sin perder la verticalidad.', 'Vuelve al centro y alterna los brazos manteniendo la respiración.', 'Evita bloquear la rodilla de apoyo o inclinar el tronco hacia los lados.']::text[], 'intermedio', 'Trabaja el core y los oblicuos mientras entrenas el equilibrio y la coordinación sobre un solo pie.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '5975'),
('9f6f2d68-e87e-596f-aa0f-8e09b2911c50', 'Sentadilla a una pierna en banco', ARRAY['Siéntate en el borde de un banco con una pierna extendida al frente.', 'Baja y sube apoyándote solo en la pierna que queda en el suelo.', 'Controla el descenso y empuja con el talón al subir.', 'Evita dejar caer el peso o que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sola pierna, mejorando el equilibrio y la estabilidad de rodilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4790'),
('d1848518-9747-5864-b262-d5127a8493f6', 'Salto a una pierna sobre tabla', ARRAY['Colócate sobre una pierna frente a una tabla baja con el tronco erguido.', 'Salta hacia delante y aterriza sobre la misma pierna con la rodilla blanda.', 'Amortigua el impacto y mantén el equilibrio antes del siguiente salto.', 'Evita aterrizar con la rodilla rígida o hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia y reactividad en cuádriceps y gemelos con un salto explosivo a una sola pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4245'),
('48108127-b8cd-515c-801e-b2c232b53ac5', 'Peso muerto a una pierna con brazo y pierna extendidos', ARRAY['Apóyate en una pierna con la rodilla ligeramente flexionada.', 'Inclina el tronco hacia delante mientras extiendes la pierna libre hacia atrás.', 'Baja hasta notar el estiramiento en el isquiotibial y vuelve despacio.', 'Evita redondear la espalda o perder la horizontalidad de la cadera.']::text[], 'intermedio', 'Refuerza isquiotibiales y glúteos mientras trabajas el equilibrio y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2920'),
('3e38aeef-98c3-550b-8fed-befafcb40590', 'Salto al cajón a una pierna', ARRAY['Sitúate frente a un cajón bajo sobre una sola pierna.', 'Flexiona la rodilla y salta con fuerza para subir al cajón.', 'Aterriza suavemente con la misma pierna y recupera el equilibrio.', 'Evita saltar a una altura que no controles al aterrizar.']::text[], 'intermedio', 'Mejora la potencia de piernas y la explosividad con un salto unilateral al cajón.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5166'),
('5dee8509-ed2f-5265-831e-51351f3f3726', 'Puente a una pierna', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado.', 'Extiende la otra pierna y eleva la cadera apretando el glúteo.', 'Mantén la cadera alineada y baja de forma controlada.', 'Evita arquear la lumbar o dejar caer la cadera hacia un lado.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales con un puente unilateral que también exige estabilidad de core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0726'),
('24c9ccf5-8b30-5765-be33-2c10f549eed9', 'Puente a una pierna con flexión de cadera', ARRAY['Túmbate boca arriba con un pie apoyado y la otra pierna elevada.', 'Sube la cadera y lleva la rodilla libre hacia el pecho.', 'Baja la pierna y la cadera de forma controlada.', 'Evita perder la alineación de la cadera durante el movimiento.']::text[], 'intermedio', 'Combina activación de glúteo con control del core al elevar la cadera y flexionar la pierna libre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3583'),
('2f66a8fa-83a4-51ab-96d7-185e8316e65a', 'Puente a una pierna con pierna extendida', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Extiende una pierna recta hacia delante.', 'Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.', 'Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales con una variante unilateral que exige control y estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3645'),
('b5f392d7-4271-56d3-9d3c-b86962c77820', 'Patada al glúteo a una pierna', ARRAY['De pie sobre una pierna, mantén el tronco erguido.', 'Lleva el talón de la pierna libre hacia el glúteo con un gesto rápido.', 'Alterna las piernas manteniendo un ritmo constante y ligero.', 'Evita inclinar el tronco o perder el equilibrio al acelerar.']::text[], 'intermedio', 'Ejercicio pliométrico que activa isquiotibiales y mejora la coordinación al llevar el talón al glúteo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1589'),
('07b0ea2c-2039-591f-8914-be6f79449880', 'Salto de gemelos a una pierna', ARRAY['Colócate sobre una pierna con el tobillo firme.', 'Salta impulsándote con la punta del pie y aterriza suavemente.', 'Mantén las repeticiones rápidas y el tronco estable.', 'Evita aterrizar con el tobillo rígido o desviado.']::text[], 'intermedio', 'Desarrolla la potencia y elasticidad de gemelos y tobillo con saltos repetidos sobre una sola pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10754'),
('a9ecca7c-8fcc-5056-8d26-a60105b64bc7', 'Salto de gemelos a una pierna con apoyo en cajón', ARRAY['Apoya una mano en un cajón y colócate sobre una pierna.', 'Salta impulsándote con el gemelo y aterriza con control.', 'Mantén el apoyo ligero para no cargar el peso en la mano.', 'Evita rebotar sin control o perder la verticalidad del tobillo.']::text[], 'intermedio', 'Mejora la potencia del gemelo con saltos unilaterales apoyándote en un cajón para mantener el equilibrio.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10755'),
('11a9a2f0-eba3-5e31-8f8d-b090f37c0088', 'Elevación de gemelos a una pierna sobre mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano.', 'Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.', 'Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.', 'Repite el número de repeticiones deseado, luego cambia a la otra pierna.']::text[], 'intermedio', 'Fortalece gemelos y sóleo con una elevación unilateral que añade inestabilidad al apoyar el pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0727'),
('09fc3927-6957-5be3-9bab-4e851577c01b', 'Fondos a una pierna en el suelo', ARRAY['Siéntate en el suelo con las manos detrás y una pierna flexionada.', 'Eleva la cadera y flexiona los codos para bajar el cuerpo.', 'Empuja con los tríceps para volver arriba sin bloquear los codos.', 'Evita encoger los hombros o dejar caer la cadera.']::text[], 'intermedio', 'Trabaja tríceps y hombros con un fondo unilateral que también implica core y glúteos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4364'),
('2c50c3c4-5c15-59fa-a09b-f08854d7a5f7', 'Extensión a una pierna en balón de estabilidad', ARRAY['Colócate boca arriba con la espalda apoyada en el balón y los pies en el suelo.', 'Extiende una pierna mientras mantienes la otra flexionada y el tronco estable.', 'Sube y baja la pierna de forma controlada sin arquear la zona lumbar.', 'Evita balancear el balón: activa el abdomen durante todo el recorrido.', 'Respira de forma constante y cambia de pierna al terminar la serie.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos mientras el core y los flexores estabilizan la cadera sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0728'),
('6e48cf84-d3ba-5019-9ff0-ac4f63ab0fab', 'Toque de pie a una pierna', ARRAY['Apóyate sobre una pierna con la rodilla ligeramente flexionada.', 'Lleva la otra pierna hacia delante y toca el suelo con el pie sin cargar peso.', 'Vuelve a la posición inicial manteniendo la cadera estable.', 'No dejes que la rodilla de apoyo se vaya hacia dentro.', 'Controla el movimiento y respira con normalidad.']::text[], 'intermedio', 'Mejora el equilibrio y la fuerza del glúteo medio, con trabajo de isquiotibiales, cuádriceps y tobillos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1702'),
('80d17e4f-2197-5669-a436-b032a4aece9e', 'Puente de glúteos a una pierna con brazos en el pecho', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado, la otra pierna extendida.', 'Cruza los brazos sobre el pecho y aprieta el abdomen.', 'Empuja con el talón y eleva la cadera hasta alinear rodilla, cadera y hombro.', 'Baja despacio sin dejar caer la pelvis de golpe.', 'Evita arquear la espalda: el movimiento sale del glúteo.']::text[], 'intermedio', 'Aísla el glúteo y los isquiotibiales, exigiendo al core mantener la pelvis nivelada sin ayuda de los brazos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4791'),
('15634044-6f0a-56db-bbce-00be9c921a73', 'Puente de glúteos a una pierna con rotación externa', ARRAY['Túmbate boca arriba con una pierna flexionada y el pie apoyado.', 'Rota la rodilla de apoyo hacia fuera y mantén la otra pierna elevada.', 'Eleva la cadera apretando el glúteo sin perder la rotación.', 'Baja de forma controlada hasta rozar el suelo.', 'No dejes que la rodilla se vaya hacia dentro al subir.']::text[], 'intermedio', 'Trabaja el glúteo mayor y el rotador externo de cadera, mejorando la estabilidad de la pelvis en apoyo unipodal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5167'),
('1e0d3f2f-d3ae-5d19-93d4-55718565ba39', 'Puente de glúteos a una pierna con rodilla al pecho', ARRAY['Túmbate boca arriba con una pierna flexionada y el pie apoyado.', 'Eleva la cadera hasta alinear el cuerpo y lleva la rodilla libre al pecho.', 'Mantén la pelvis nivelada sin girar hacia un lado.', 'Baja la pierna y la cadera a la vez de forma controlada.', 'Evita tirar del cuello o arquear la lumbar.']::text[], 'intermedio', 'Combina extensión de cadera y flexión de rodilla para reforzar glúteos, isquiotibiales y core de forma dinámica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4044'),
('d668e8cc-9530-5848-9a89-506b397d717a', 'Puente de isquiotibiales a una pierna', ARRAY['Túmbate boca arriba con una pierna flexionada y el pie apoyado.', 'Extiende la otra pierna y mantén el talón en el suelo o elevado.', 'Empuja con el talón de apoyo y sube la cadera apretando el isquiotibial.', 'Baja despacio sin perder la tensión en la pierna extendida.', 'No dejes que la cadera se desnivele durante el movimiento.']::text[], 'intermedio', 'Refuerza los isquiotibiales y glúteos, mejorando la estabilidad posterior de la cadera y la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9359'),
('972f286e-5f38-5b3d-8cea-4a5a3db1d532', 'Sentadilla a una pierna con toque de talón', ARRAY['De pie sobre una pierna, lleva la otra ligeramente adelantada.', 'Desciende en sentadilla y toca el suelo con el talón de la pierna libre.', 'Empuja con la pierna de apoyo para volver arriba sin perder el equilibrio.', 'Mantén la rodilla alineada con el pie y el pecho erguido.', 'Evita colapsar la rodilla hacia dentro al subir.']::text[], 'intermedio', 'Desarrolla fuerza unilateral en cuádriceps y glúteos, con control del equilibrio y tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3494'),
('be773fa3-ea69-5b34-96be-4bb761e20b66', 'Puente de cadera a una pierna recta', ARRAY['Túmbate boca arriba con una pierna flexionada y la otra estirada.', 'Empuja con el talón y eleva la cadera manteniendo la pierna recta.', 'Aprieta el glúteo arriba y mantén la pelvis nivelada.', 'Baja despacio sin dejar caer la cadera.', 'No arquees la espalda al final del recorrido.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales con la pierna extendida, exigiendo control del core y la lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3435'),
('9e4db58c-52e4-5e8e-a334-588fba066e90', 'Salto con empuje de cadera a una pierna', ARRAY['Colócate en posición de puente con la espalda apoyada y una pierna flexionada.', 'Empuja con fuerza con el talón y extiende la cadera para despegar del suelo.', 'Aterriza con control flexionando ligeramente la rodilla.', 'Mantén el core activo y evita que la rodilla se vaya hacia dentro.', 'Haz pocas repeticiones y descansa entre series.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia glúteos y piernas, mejorando la explosividad y la estabilidad en un solo apoyo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4793'),
('2bb34550-f87e-5771-9733-e95e00f4ccd7', 'Empuje de cadera a una pierna', ARRAY['Túmbate boca arriba con la espalda apoyada y una pierna flexionada.', 'Eleva la cadera empujando con el talón hasta alinear el cuerpo.', 'Mantén la otra pierna elevada y la pelvis nivelada.', 'Baja de forma controlada sin apoyar del todo la cadera.', 'Evita arquear la lumbar o girar la pelvis.']::text[], 'intermedio', 'Fortalece glúteos e isquiotibiales en apoyo unipodal, mejorando la extensión de cadera y la estabilidad pélvica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4792'),
('a3871f43-167c-5524-88fd-2c02fdaa5a1e', 'Hip thrust a una pierna', ARRAY['Siéntate en el suelo con la espalda apoyada y una pierna flexionada.', 'Empuja con el talón y eleva la cadera hasta la extensión completa.', 'Aprieta el glúteo arriba y mantén el core activo.', 'Baja despacio sin perder la alineación de la pelvis.', 'No dejes que la rodilla se desplace hacia dentro.']::text[], 'intermedio', 'Trabaja el glúteo mayor y los isquiotibiales con extensión de cadera unilateral, mejorando la fuerza y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2071'),
('4e879d44-e6fa-5d15-9a8f-155f901d35ce', 'Saltitos a una pierna', ARRAY['Apóyate sobre una pierna con la rodilla ligeramente flexionada.', 'Realiza saltos pequeños y rápidos manteniendo el pie firme.', 'Aterriza con la rodilla alineada y el abdomen activo.', 'Evita saltar con la pierna rígida o caer de golpe.', 'Haz series cortas y cambia de pierna.']::text[], 'intermedio', 'Mejora la potencia y la rigidez del tobillo y la pierna, con trabajo de cuádriceps, gemelos y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5482'),
('72cac18c-5827-5356-a613-8026202a4802', 'Puente de glúteos con salto a una pierna', ARRAY['Túmbate boca arriba con una pierna flexionada y el pie apoyado.', 'Empuja con fuerza y salta extendiendo la cadera.', 'Aterriza con control y vuelve a la posición inicial.', 'Mantén el core activo y la rodilla alineada con el pie.', 'Evita aterrizar con la pierna bloqueada.']::text[], 'intermedio', 'Ejercicio explosivo que combina extensión de cadera y salto para potenciar glúteos, isquiotibiales y gemelos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4794'),
('b417d649-6b7c-5f54-8e90-2fdd9a607e33', 'Salto lateral a una pierna', ARRAY['Apóyate sobre una pierna con la rodilla ligeramente flexionada.', 'Salta hacia un lado y aterriza sobre la misma pierna.', 'Amortigua la caída flexionando la rodilla y el tobillo.', 'Mantén la rodilla alineada y el core activo.', 'Evita saltar demasiado lejos si pierdes el control.']::text[], 'intermedio', 'Desarrolla potencia lateral y estabilidad de tobillo y rodilla, con trabajo de cuádriceps, glúteos y gemelos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7455'),
('719f9db3-74e2-50b3-9c7f-da5b7ec26c90', 'Sentadilla a una pierna en cajón bajo', ARRAY['Colócate de pie frente a un cajón bajo con una pierna ligeramente adelantada.', 'Desciende de forma controlada hasta sentarte suavemente en el cajón.', 'Empuja con la pierna de apoyo para volver a la posición inicial.', 'Mantén la rodilla alineada con el pie y el pecho erguido.', 'Evita dejarte caer sobre el cajón sin control.']::text[], 'intermedio', 'Progresa hacia la sentadilla pistol trabajando cuádriceps y glúteos con apoyo y control del equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3493'),
('ca5aef38-7ea1-5bde-b80c-1020216e6e2b', 'Deslizamiento de plataforma a una pierna', ARRAY['Comienza de pie con un pie sobre una plataforma o tabla deslizante.', 'Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna.', 'Mantén el core activado y conserva una postura recta durante todo el movimiento.', 'Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial.', 'Repite el movimiento el número de repeticiones deseado y luego cambia de pierna.']::text[], 'intermedio', 'Fortalece los isquiotibiales con control excéntrico, mejorando la estabilidad de la rodilla y la fuerza del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0730'),
('b7e8721a-e679-5c9e-a9fd-acbd945e8834', 'Salto pogo a una pierna', ARRAY['Colócate de pie sobre una pierna con el pie apoyado y las rodillas ligeramente flexionadas.', 'Impulsa el cuerpo hacia arriba con un salto corto y rápido, manteniendo el tobillo rígido.', 'Aterriza sobre la punta del pie y rebota de inmediato sin dejar caer el talón.', 'Mantén el tronco erguido y la rodilla alineada con el pie durante todo el rebote.', 'Evita saltar demasiado alto: prioriza la frecuencia y el contacto breve con el suelo.']::text[], 'intermedio', 'Trabaja la reactividad y elasticidad de gemelos y tobillos, mejorando el rebote y la rigidez del pie en el apoyo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '11647'),
('92f48885-0702-50ce-9131-e385e5814dd6', 'Impulso a una pierna', ARRAY['Apóyate en una pierna con la rodilla ligeramente flexionada y el tronco erguido.', 'Carga el peso en la pierna de apoyo y flexiona la cadera y la rodilla para tomar impulso.', 'Empuja con fuerza contra el suelo extendiendo la pierna para despegar.', 'Aterriza suavemente sobre la misma pierna con la rodilla alineada con el pie.', 'Evita que la rodilla se vaya hacia dentro al empujar y al caer.']::text[], 'intermedio', 'Desarrolla la potencia del cuádriceps y la capacidad de empuje unilateral, útil para acelerar y saltar con una pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1591'),
('174da982-6ecd-516f-9750-e75ae5551d26', 'Sentadilla isométrica a una pierna en pared', ARRAY['Apoya la espalda contra la pared y eleva una pierna del suelo.', 'Desliza la espalda hacia abajo hasta que la rodilla de apoyo quede a unos 90 grados.', 'Mantén la posición con el tronco pegado a la pared y la rodilla alineada con el pie.', 'Respira de forma continua y aguanta el tiempo indicado sin bloquear la respiración.', 'Evita que la rodilla pase por delante de la punta del pie o que se abra hacia fuera.']::text[], 'intermedio', 'Refuerza el cuádriceps en isométrico unilateral, mejorando la resistencia y el control de la rodilla sin impacto.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '0731'),
('e8a3c55a-27ec-55ba-bd68-1f78ebc55632', 'Sentadilla a una pierna (pistol) masculino', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.', 'Levanta el pie derecho del suelo y extiéndelo hacia delante.', 'Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás.', 'Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo.', 'Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente.', 'Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'avanzado', 'Ejercicio de calistenia que exige fuerza, equilibrio y movilidad de cadera, rodilla y tobillo en una sola pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1759'),
('82e5e845-e627-5fdc-96a2-0e0dbadca546', 'Equilibrio a una pierna', ARRAY['Colócate de pie con los pies juntos y el tronco erguido.', 'Eleva una pierna flexionando la rodilla y mantén la mirada al frente.', 'Aguanta el equilibrio con el pie de apoyo firme y el abdomen activado.', 'Respira con normalidad y, si puedes, cierra los ojos para aumentar la dificultad.', 'Evita apoyar el pie elevado en el suelo o balancear el tronco para compensar.']::text[], 'intermedio', 'Mejora la propiocepción y la estabilidad del tobillo, la rodilla y la cadera, reduciendo el riesgo de esguinces.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3714'),
('623692d5-6806-5a07-b1d2-08baee46cada', 'Equilibrio a una pierna en bosu', ARRAY['Coloca el bosu con la cúpula hacia arriba y súbete con cuidado.', 'Apoya una sola pierna en el centro y eleva la otra flexionando la rodilla.', 'Mantén el tronco erguido y el abdomen activo mientras buscas el equilibrio.', 'Aguanta el tiempo indicado respirando con normalidad y con la mirada al frente.', 'Evita bloquear la rodilla o mover los brazos de forma brusca para compensar.']::text[], 'intermedio', 'Entrena la propiocepción sobre superficie inestable, reforzando tobillos, pies y core para un mejor control postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3715'),
('22eb9f4c-f980-574d-bce3-88f19624c53d', 'Subida al cajón a una pierna', ARRAY['Coloca un cajón estable frente a ti y apoya un pie entero encima.', 'Empuja con la pierna de arriba para subir el cuerpo sin impulsarte con la de abajo.', 'Extiende la cadera arriba y mantén el tronco erguido.', 'Baja de forma controlada con la misma pierna hasta tocar el suelo con la otra.', 'Evita empujar con el pie del suelo o dejar caer el cuerpo al bajar.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteo de forma unilateral, mejorando la potencia y la estabilidad para subir escalones.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0733'),
('4f6d750e-1609-5b75-bed5-c6254b087c7e', 'Subida al banco a una pierna', ARRAY['Colócate frente a un banco estable y apoya un pie entero encima.', 'Sube empujando con la pierna apoyada sin ayudarte de la pierna de abajo.', 'Extiende la cadera arriba y mantén la rodilla alineada con el pie.', 'Baja lentamente con la misma pierna hasta apoyar el pie libre en el suelo.', 'Evita inclinar el tronco en exceso o dejar caer el cuerpo al descender.']::text[], 'intermedio', 'Trabaja la fuerza unilateral de cuádriceps y glúteo con mayor rango, mejorando el control y la potencia de piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4795'),
('6828c72d-e9de-5807-bfe5-5537ee106449', 'Estiramiento de una pierna con rodilla flexionada', ARRAY['Túmbate boca arriba con la espalda apoyada y las rodillas flexionadas.', 'Eleva una pierna y sujétala por detrás del muslo con las manos.', 'Extiende la rodilla hasta notar un estiramiento suave en la parte posterior.', 'Mantén la otra pierna apoyada y la zona lumbar pegada al suelo.', 'Evita tirar con fuerza o levantar la cadera mientras respiras de forma pausada.']::text[], 'intermedio', 'Estiramiento de pilates que alarga la cadena posterior y los flexores de cadera, mejorando la movilidad y el control del core.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '4309'),
('79bd9b34-3863-5309-831b-cdea92918107', 'Salto de zancada a una pierna', ARRAY['Colócate en zancada con una pierna delante y otra detrás.', 'Flexiona las rodillas y salta con fuerza hacia arriba.', 'Aterriza sobre la misma pierna delantera con la rodilla alineada con el pie.', 'Amortigua la caída flexionando la cadera y la rodilla de forma controlada.', 'Evita que la rodilla se vaya hacia dentro o aterrizar con la pierna rígida.']::text[], 'intermedio', 'Ejercicio pliométrico que desarrolla potencia y estabilidad unilateral de cuádriceps y glúteo para saltos y cambios de ritmo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1592'),
('3860ac4b-239d-5c8b-b012-0829bf41a0d9', 'Empujes de cadera a una pierna', ARRAY['Túmbate boca arriba con una rodilla flexionada y el pie apoyado.', 'Extiende la otra pierna al frente o flexiónala hacia el pecho.', 'Empuja con el talón y eleva la cadera hasta alinear tronco y muslo.', 'Aprieta el glúteo arriba y baja de forma controlada sin apoyar del todo.', 'Evita arquear la zona lumbar o rotar la pelvis durante el movimiento.']::text[], 'intermedio', 'Fortalece el glúteo y los isquiotibiales de forma unilateral, mejorando la extensión de cadera y la estabilidad de la pelvis.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5774'),
('465f1558-9fc6-5888-b3ad-5df2b4557f38', 'Inclinación transversal a una pierna', ARRAY['Colócate de pie con los pies separados a la anchura de las caderas.', 'Da un paso cruzado por detrás con una pierna y apoya la punta.', 'Inclina el tronco hacia delante sobre la pierna delantera con la espalda recta.', 'Siente el estiramiento en la parte posterior y mantén la posición respirando.', 'Evita curvar la espalda o forzar la rodilla delantera más allá del pie.']::text[], 'principiante', 'Movilidad que estira isquiotibiales y glúteo con control del core, mejorando la flexibilidad y la estabilidad del apoyo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1703'),
('b84fc7db-de1b-5560-8732-b65a5ba52f85', 'Salto vertical a una pierna', ARRAY['Colócate de pie sobre una pierna con la rodilla ligeramente flexionada.', 'Flexiona la cadera y la rodilla para cargar y balancea los brazos hacia atrás.', 'Salta hacia arriba con fuerza extendiendo la pierna y los brazos.', 'Aterriza sobre la misma pierna con la rodilla alineada y amortiguando la caída.', 'Evita aterrizar con la pierna rígida o que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Desarrolla la potencia vertical unilateral de cuádriceps y glúteo, mejorando el salto y la estabilidad en el aterrizaje.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4254'),
('40a24f2c-a645-5e79-b415-16469c08dced', 'Puente de glúteo a una pierna recta', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Eleva la cadera hasta formar una línea recta entre hombros, cadera y rodillas.', 'Extiende una pierna sin bajar la cadera y mantén la posición apretando el glúteo.', 'Respira con normalidad y evita arquear la zona lumbar en exceso.', 'Baja la cadera de forma controlada y cambia de pierna.']::text[], 'intermedio', 'Fortalece glúteos y femorales manteniendo la cadera elevada, mejorando la estabilidad y el control del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '5198'),
('a3d498fd-bf9b-55f0-beb3-14d8a04340f6', 'Estiramiento de una pierna recta', ARRAY['Siéntate con una pierna extendida y la otra flexionada.', 'Alarga la columna y lleva el pecho hacia la pierna estirada.', 'Mantén el abdomen activo y la espalda larga, sin redondearla.', 'Respira despacio y evita tirar de la cabeza con las manos.', 'Cambia de pierna tras mantener el estiramiento.']::text[], 'intermedio', 'Estira isquiotibiales y flexores de cadera mientras activas el abdomen para mantener la columna estable.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '4310'),
('ffe91bb9-a747-58bb-b7db-fa4628c922cc', 'Sentadilla sentado', ARRAY['Colócate de pie frente a una silla con los pies a la anchura de la cadera.', 'Lleva la cadera hacia atrás y baja controlando hasta rozar el asiento.', 'Empuja con los talones para subir manteniendo el pecho alto.', 'Evita que las rodillas se metan hacia dentro al bajar.', 'Respira al subir y controla el descenso.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un patrón de sentadilla guiado, útil para aprender la técnica y ganar fuerza.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1593'),
('e9c9359a-b186-5441-8e91-9339147cc448', 'Abdominal con incorporación', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Activa el abdomen y sube el tronco sin tirar del cuello.', 'Llega arriba con control y evita impulsarte con las manos.', 'Baja despacio vertebra a vertebra mientras espiras.', 'Mantén la mirada al frente para no forzar la cervical.']::text[], 'intermedio', 'Refuerza el recto abdominal y los flexores de cadera, mejorando la fuerza del core en movimientos de flexión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0736'),
('316cb98c-c21c-5f91-9b98-a18b34ca55c2', 'Abdominal asistido con silla', ARRAY['Siéntate en el borde de una silla con los pies bien apoyados.', 'Sujétate ligeramente al asiento y reclina el tronco hacia atrás.', 'Sube activando el abdomen sin balancearte ni usar impulso.', 'Evita tirar del cuello y mantén el movimiento lento.', 'Respira al incorporarte y controla la bajada.']::text[], 'intermedio', 'Fortalece el abdomen con ayuda de una silla, ideal para progresar en la incorporación con menor esfuerzo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3389'),
('d5deed15-aa6b-54b0-87fb-ae77edc7746f', 'Giro con abducción alterna sentado en silla', ARRAY['Siéntate erguido en la silla con los pies apoyados y separados.', 'Abre una rodilla hacia fuera mientras giras el tronco suavemente.', 'Vuelve al centro y repite hacia el otro lado sin forzar.', 'Mantén la espalda recta y evita encorvarte al girar.', 'Respira de forma fluida durante todo el movimiento.']::text[], 'principiante', 'Mejora la movilidad de cadera y la rotación del tronco, activando abductores y oblicuos de forma suave.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8202'),
('3cb46c68-7ceb-5b22-9412-0b7e7e61474e', 'Giro alterno de rodilla a codo sentado', ARRAY['Siéntate en el borde de la silla con la espalda recta.', 'Lleva una rodilla hacia el codo contrario girando el tronco.', 'Vuelve al centro y alterna hacia el otro lado con control.', 'Evita tirar del cuello y mantén el abdomen activo.', 'Respira al girar y no uses impulso.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con rotación controlada, mejorando la coordinación y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7693'),
('f888c4b6-e4b6-5afa-bf60-17ab5b6708b4', 'Estiramiento de espalda sentado inclinado', ARRAY['Siéntate con las piernas extendidas o ligeramente flexionadas.', 'Inclina el tronco hacia delante desde la cadera con la espalda larga.', 'Deja caer los brazos y relaja el cuello sin forzar.', 'Respira despacio y evita rebotar en la posición.', 'Vuelve arriba lentamente.']::text[], 'principiante', 'Alivia la tensión de la espalda y la zona lumbar, mejorando la flexibilidad de la cadena posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1805'),
('f470fb00-5940-56ed-bb7d-3aa7133b96a0', 'Gato y vaca sentado en silla', ARRAY['Siéntate erguido en la silla con los pies apoyados.', 'Arquea la espalda hacia dentro mientras miras al frente.', 'Redondea la espalda llevando el mentón al pecho.', 'Alterna ambos movimientos de forma lenta y fluida.', 'Respira acompañando cada fase sin forzar.']::text[], 'principiante', 'Moviliza la columna y alivia la rigidez de la espalda, mejorando la flexibilidad y la conciencia postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11095'),
('fde178af-5956-52e1-99a8-28bf02f5f880', 'Estiramiento sentado con piernas cruzadas', ARRAY['Siéntate con las piernas cruzadas y la espalda recta.', 'Alarga los brazos hacia delante inclinando el tronco desde la cadera.', 'Mantén la espalda larga y evita redondearla en exceso.', 'Respira despacio y relaja los hombros.', 'Vuelve arriba lentamente.']::text[], 'principiante', 'Estira la espalda y los glúteos, liberando tensión en la zona lumbar y mejorando la movilidad de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1807'),
('ba932b3a-587b-55a3-8c92-8aa8d9e150c3', 'Estiramiento sentado con pies juntos', ARRAY['Siéntate con las plantas de los pies juntas y las rodillas hacia fuera.', 'Sujeta los pies y alarga el tronco hacia delante.', 'Inclínate desde la cadera sin forzar la espalda.', 'Respira despacio y evita empujar las rodillas hacia abajo con fuerza.', 'Vuelve arriba con control.']::text[], 'principiante', 'Estira aductores y espalda baja, mejorando la flexibilidad de la cadena posterior y la apertura de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1809'),
('dbdf68ba-c2c5-5f7e-b681-07f80eea9748', 'Elevación de piernas sentado en el suelo', ARRAY['Siéntate en el suelo con las piernas extendidas y el tronco ligeramente atrás.', 'Apoya las manos detrás para estabilizarte si lo necesitas.', 'Eleva las piernas manteniendo el abdomen activo.', 'Evita arquear la zona lumbar al subir.', 'Baja las piernas despacio y con control.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejorando el control del core en posición sentada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9487'),
('7e06abf6-006c-5ea9-8b7d-abced51e3634', 'Elevación de tibial sentado en el suelo', ARRAY['Siéntate en el suelo con las piernas extendidas.', 'Lleva las puntas de los pies hacia ti activando la espinilla.', 'Mantén la posición un instante y vuelve despacio.', 'Evita mover las rodillas y mantén el movimiento en el tobillo.', 'Respira con normalidad durante las repeticiones.']::text[], 'principiante', 'Refuerza el tibial anterior y mejora la movilidad del tobillo, útil para la estabilidad y la prevención de lesiones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9272'),
('bd6bbb59-29e8-5134-aa1a-c8bb750a2eb0', 'Estiramiento de glúteo con pie al pecho', ARRAY['Siéntate en el suelo con una pierna extendida.', 'Cruza el pie de la otra pierna sobre el muslo.', 'Lleva la rodilla hacia el pecho abrazándola con suavidad.', 'Mantén la espalda recta y evita forzar la cadera.', 'Respira despacio y cambia de lado.']::text[], 'principiante', 'Estira glúteos y zona lumbar, aliviando tensión y mejorando la flexibilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1940'),
('5410b907-1676-54eb-a51d-3ecda251a5a9', 'Sostén isométrico de curl de isquiotibiales sentado con balón', ARRAY['Siéntate en una silla y coloca el balón bajo los talones con las piernas estiradas.', 'Presiona el balón hacia el suelo como si quisieras flexionar las rodillas sin moverlo.', 'Mantén la tensión entre 15 y 30 segundos respirando de forma constante.', 'Evita arquear la espalda baja y mantén el abdomen activo durante todo el sostén.']::text[], 'principiante', 'Activa isquiotibiales y glúteos manteniendo el balón presionado, mejorando la estabilidad y fuerza del tren inferior.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10139'),
('75926d55-8f7c-588b-bd65-0ab47ab0d75b', 'Estiramiento lateral sentado', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Eleva un brazo por encima de la cabeza y inclínate suavemente hacia el lado contrario.', 'Mantén el estiramiento de 20 a 30 segundos sin rebotar y respirando profundo.', 'Evita girar el tronco o levantar la cadera del asiento.']::text[], 'principiante', 'Estira oblicuos y dorsales, aliviando la tensión del tronco y mejorando la movilidad lateral de la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2118'),
('832ff5d5-ca97-5651-bd81-1ac4dde25d5c', 'Estiramiento de extensores del tronco inferior sentado', ARRAY['Siéntate en el borde de la silla con los pies separados a la anchura de las caderas.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda lo más recta posible.', 'Deja caer los brazos hacia el suelo y mantén de 20 a 30 segundos.', 'Evita redondear en exceso la espalda o forzar la posición con rebotes.']::text[], 'principiante', 'Relaja la zona lumbar y los glúteos, reduciendo la rigidez tras periodos prolongados sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1803'),
('4166b1d7-a30c-5316-9f2b-3dc30f17c344', 'Estiramiento de flexión de cuello sentado', ARRAY['Siéntate erguido y lleva la barbilla hacia el pecho lentamente.', 'Coloca una mano sobre la cabeza y aplica una presión muy suave.', 'Mantén de 15 a 30 segundos respirando con calma.', 'Evita tirar con fuerza o hacer movimientos bruscos.']::text[], 'principiante', 'Estira el elevador de la escápula y la parte alta de la espalda, aliviando la tensión cervical.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1835'),
('733e73ea-7fd3-55f9-b302-280c958bc64c', 'Estiramiento externo de glúteo sentado a una pierna', ARRAY['Siéntate y cruza un tobillo sobre la rodilla contraria.', 'Inclina el tronco hacia delante manteniendo la espalda recta hasta notar el estiramiento.', 'Mantén de 20 a 30 segundos y cambia de pierna.', 'Evita presionar la rodilla cruzada hacia abajo con fuerza.']::text[], 'principiante', 'Estira el glúteo y la cadera, mejorando la movilidad y aliviando tensiones en la zona lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1951'),
('fa65edaa-e6dc-5d21-9701-0eeabda18c6c', 'Apretón de pecho en oración sentado en silla', ARRAY['Siéntate erguido y junta las palmas de las manos delante del pecho.', 'Presiona las palmas entre sí con fuerza moderada sin mover los codos.', 'Mantén la tensión de 15 a 30 segundos respirando con normalidad.', 'Evita encoger los hombros o bloquear la respiración.']::text[], 'intermedio', 'Activa pectorales y hombros de forma isométrica, mejorando la postura y la fuerza del tren superior.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '8200'),
('852045e4-e3ca-50ff-9431-fbadf04fdffe', 'Estiramiento rotacional de cadera sentado', ARRAY['Siéntate con la espalda recta y los pies apoyados.', 'Gira el tronco hacia un lado llevando la mano al respaldo de la silla.', 'Mantén la rotación de 20 a 30 segundos sin forzar y cambia de lado.', 'Evita mover las caderas o levantar los pies del suelo.']::text[], 'principiante', 'Estira glúteos y oblicuos mediante rotación, mejorando la movilidad de la cadera y la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1948'),
('19b54f63-68d2-53a3-b223-70c95f509864', 'Giro ruso sentado en silla', ARRAY['Siéntate en el borde de la silla con la espalda recta y los pies apoyados.', 'Junta las manos delante del pecho y gira el tronco hacia un lado.', 'Vuelve al centro y gira hacia el otro lado de forma controlada.', 'Evita balancear los brazos o redondear la espalda durante el giro.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con rotaciones controladas, mejorando la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8203'),
('818f06e1-78da-59f4-a683-66d124f9ea36', 'Aducción escapular sentado', ARRAY['Siéntate erguido con los brazos relajados a los lados.', 'Junta los omóplatos hacia atrás y hacia abajo como si sujetaras un lápiz entre ellos.', 'Mantén la contracción de 2 a 3 segundos y relaja lentamente.', 'Evita encoger los hombros hacia las orejas o arquear la espalda.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides, mejorando la postura y reduciendo la tensión cervical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '6913'),
('2e599be7-1181-5406-a462-3f9153305311', 'Estiramiento de hombros sentado en banco', ARRAY['Siéntate en el banco con la espalda recta.', 'Lleva un brazo cruzado delante del pecho y sujétalo con el otro brazo.', 'Mantén el estiramiento de 20 a 30 segundos y cambia de lado.', 'Evita tirar del codo con fuerza o girar el tronco.']::text[], 'principiante', 'Estira deltoides y pecho, aliviando la tensión del tren superior y mejorando la movilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1972'),
('afb153d9-396a-5f4f-8672-b885780b6647', 'Estiramiento lateral sentado alcanzando', ARRAY['Siéntate erguido y eleva un brazo por encima de la cabeza.', 'Inclínate hacia el lado contrario alargando el brazo lo máximo posible.', 'Mantén de 20 a 30 segundos respirando profundo y cambia de lado.', 'Evita inclinarte hacia delante o levantar la cadera del asiento.']::text[], 'principiante', 'Estira dorsales y oblicuos con un alcance lateral, mejorando la flexibilidad del tronco y la respiración.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1806'),
('28ac8398-fa81-563e-8e32-b03886a44ecb', 'Estiramiento sumo sentado con giro a la izquierda', ARRAY['Siéntate con las piernas abiertas y las rodillas ligeramente flexionadas.', 'Gira el tronco hacia la izquierda llevando la mano hacia el pie contrario.', 'Mantén de 20 a 30 segundos sin rebotar y respirando con calma.', 'Evita forzar la rotación o redondear la espalda.']::text[], 'principiante', 'Estira aductores y oblicuos con rotación, mejorando la movilidad de la cadera y la flexibilidad interna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3633'),
('c3e974e1-aaff-5e41-95f0-5d137896ef2f', 'Estiramiento de movilidad sumo sentado', ARRAY['Siéntate con las piernas abiertas y los pies apoyados.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Realiza movimientos suaves de balanceo durante 20 a 30 segundos.', 'Evita forzar la apertura de piernas o rebotar con brusquedad.']::text[], 'principiante', 'Mejora la movilidad de aductores y caderas, preparando el tren inferior para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3631'),
('4055f459-aaed-51e3-937a-e718f400973c', 'Estiramiento sumo sentado con giro a la derecha', ARRAY['Siéntate con las piernas abiertas y las rodillas ligeramente flexionadas.', 'Gira el tronco hacia la derecha llevando la mano hacia el pie contrario.', 'Mantén de 20 a 30 segundos sin rebotar y respirando con calma.', 'Evita forzar la rotación o redondear la espalda.']::text[], 'principiante', 'Estira aductores y oblicuos con rotación, mejorando la movilidad de la cadera y la flexibilidad interna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3632'),
('8122e423-efc4-5862-8f46-2debe41aa366', 'Estiramiento de movilidad sumo sentado con brazos arriba', ARRAY['Siéntate con las piernas abiertas y eleva los brazos por encima de la cabeza.', 'Inclina el tronco hacia delante manteniendo los brazos estirados.', 'Realiza movimientos suaves de balanceo durante 20 a 30 segundos.', 'Evita encoger los hombros o forzar la apertura de piernas.']::text[], 'principiante', 'Mejora la movilidad de aductores y hombros, activando la cadera y la parte alta del cuerpo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3634'),
('0793bf00-8330-5afd-96f6-e5f1ac4c0baa', 'Natación sentado en silla', ARRAY['Siéntate erguido en la silla con los pies apoyados y los brazos extendidos al frente.', 'Lleva un brazo hacia atrás como si nadaras mientras el otro avanza, alternando el movimiento.', 'Coordina la respiración con cada brazada, inspirando al abrir y espirando al cerrar.', 'Mantén el tronco estable y evita encoger los hombros hacia las orejas.']::text[], 'principiante', 'Moviliza hombros y zona alta de la espalda, mejorando la movilidad articular y la coordinación del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8197'),
('3f6ec3f1-0fd2-5439-b076-a1fe37467391', 'Estiramiento de aquiles sentado tirando de la punta', ARRAY['Siéntate en el suelo con una pierna extendida y la otra flexionada.', 'Coge la punta del pie extendido y tira suavemente hacia ti.', 'Mantén el estiramiento entre veinte y treinta segundos sin rebotes.', 'Respira de forma relajada y evita forzar hasta sentir dolor.']::text[], 'principiante', 'Estira el tendón de Aquiles y la pantorrilla, aliviando tensión y mejorando la flexibilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1889'),
('1587270e-78e5-5566-83ba-ae52468eb15e', 'Uppercut sentado en silla', ARRAY['Siéntate en el borde de la silla con la espalda recta y los puños a la altura del mentón.', 'Lanza un puñetazo ascendente girando el tronco y activando el abdomen.', 'Alterna los brazos con un ritmo controlado y expulsa el aire en cada golpe.', 'Evita arquear la espalda o balancear el cuerpo en exceso.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un gesto explosivo de boxeo que activa el core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7263'),
('efd7dcd5-0309-5170-817a-9cfaade60bb1', 'Estiramiento de aductores sentado con piernas abiertas', ARRAY['Siéntate en el suelo con las piernas abiertas en forma de uve.', 'Inclina el tronco hacia delante manteniendo la espalda recta.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'No rebotes ni fuerces las rodillas hacia el suelo.']::text[], 'principiante', 'Estira los aductores y la cara interna del muslo, mejorando la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1902'),
('1be7240b-077e-5f69-adf1-e1c3699f684b', 'Leñador sentado en silla', ARRAY['Siéntate erguido con los pies apoyados y las manos entrelazadas por encima de un hombro.', 'Lleva las manos en diagonal hacia la cadera contraria girando el tronco.', 'Controla el retorno a la posición inicial sin usar impulso.', 'Mantén el abdomen activo y evita mover las piernas.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos mediante un movimiento diagonal que activa todo el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8199'),
('9f5065e9-f7d9-5b36-a821-c4d5c084aa1a', 'Leñador sentado en balón de estabilidad', ARRAY['Siéntate sobre el balón con los pies firmes en el suelo y la espalda recta.', 'Junta las manos y llévalas en diagonal desde un hombro hasta la cadera opuesta.', 'Gira el tronco de forma controlada y vuelve despacio al inicio.', 'Evita que el balón ruede en exceso manteniendo el abdomen activo.']::text[], 'principiante', 'Refuerza el core y los oblicuos mientras el balón añade inestabilidad y exige más control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9025'),
('a3fb9402-0007-5b4d-9abb-06e8eaaaefce', 'Postura de yoga siddhasana', ARRAY['Siéntate en el suelo con las piernas cruzadas y un talón cerca del perineo.', 'Apoya el otro pie entre el muslo y la pantorrilla contraria.', 'Mantén la espalda erguida y las manos sobre las rodillas.', 'Respira lento y profundo, relajando los hombros y la mandíbula.']::text[], 'intermedio', 'Postura de meditación que abre las caderas y los aductores, favoreciendo la relajación y la concentración.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6878'),
('9eefc666-a5c9-54dc-ac30-c60b976883d9', 'Patinador', ARRAY['De pie, salta lateralmente sobre una pierna llevando la otra por detrás.', 'Aterriza con la rodilla ligeramente flexionada y el tronco estable.', 'Alterna los lados con un ritmo fluido y controlado.', 'Evita que la rodilla se hunda hacia dentro al aterrizar.']::text[], 'intermedio', 'Ejercicio pliométrico que fortalece glúteos y piernas mejorando el equilibrio y la potencia lateral.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3109'),
('227c0866-1eda-55b8-b427-603df985968b', 'Saltos de patinador', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho.', 'Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo.', 'Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo.', 'Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho.', 'Continúa alternando los lados, saltando y tocando el suelo con cada pierna.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabajo cardiovascular y pliométrico que activa piernas y glúteos con desplazamientos laterales.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3361'),
('0a87a5bd-a7e7-5919-bcbd-1e125532a622', 'Sentadilla patinador', ARRAY['De pie sobre una pierna, lleva la otra por detrás con la punta del pie apoyada.', 'Baja flexionando la rodilla de apoyo manteniendo el tronco erguido.', 'Sube empujando con el talón y controla el descenso.', 'Evita que la rodilla pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sentadilla a una pierna que mejora el equilibrio y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3367'),
('0cc3cb9e-aea1-55ec-abaf-f9d1c265836d', 'Ergómetro de esquí', ARRAY['Ajusta la altura del asiento y los apoyapiés a una posición cómoda.', 'Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.', 'Siéntate erguido con los pies planos sobre los apoyapiés.', 'Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados.', 'Activa los tríceps y empuja las asas hacia abajo, hacia los muslos.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Máquina de cardio que implica tríceps, hombros y espalda con un gesto de tracción continuo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2142'),
('3e3a8c7c-5f6a-590c-97cb-8c6f03c6a802', 'Paso de esquí', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Dobla ligeramente las rodillas y mantén la espalda recta.', 'Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.', 'Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.', 'Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio cardiovascular que activa piernas y glúteos simulando el movimiento del esquí de fondo.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3671'),
('3289a9b4-caf1-5a0c-907a-cd0a84840a9f', 'Skin the cat', ARRAY['Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado.', 'Activa el core y levanta las piernas, llevando las rodillas hacia el pecho.', 'Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos.', 'Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial.', 'Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Movilidad avanzada de hombros y espalda alta que exige control y fuerza del core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3304'),
('8c1f86a7-f4f6-5f63-978a-488a9398a1f5', 'Salto de cuerda con skip', ARRAY['Sujeta la cuerda con las manos a la altura de la cadera y los codos cerca del cuerpo.', 'Salta con un pequeño rebote mientras la cuerda pasa bajo los pies.', 'Mantén un ritmo constante y respira de forma regular.', 'Evita saltar demasiado alto o encoger los hombros.']::text[], 'intermedio', 'Cardio con cuerda que mejora la coordinación y activa pantorrillas, cuádriceps y hombros.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3676'),
('bda9755a-3042-50c8-b8f4-09eb81f228a9', 'Skips', ARRAY['De pie, eleva una rodilla a la altura de la cadera mientras el brazo contrario sube.', 'Alterna las piernas con un ritmo ligero y coordinado.', 'Mantén el tronco erguido y respira de forma constante.', 'Evita inclinarte hacia atrás o golpear el suelo con fuerza.']::text[], 'intermedio', 'Ejercicio cardiovascular que eleva la frecuencia cardíaca y activa piernas y core con un ritmo dinámico.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3199'),
('8f2b10d6-8884-5557-b612-6ba899b5b7f1', 'Prensa de piernas a 45 grados', ARRAY['Apoya la espalda completa en el respaldo y coloca los pies en la plataforma a la anchura de los hombros.', 'Baja la plataforma de forma controlada hasta que las rodillas lleguen a unos 90 grados sin despegar la zona lumbar.', 'Empuja con los talones y extiende las piernas sin bloquear del todo las rodillas.', 'Evita que las rodillas se metan hacia dentro durante el empuje.']::text[], 'intermedio', 'Trabaja cuádriceps con apoyo de glúteos y femorales, ideal para ganar fuerza y volumen en las piernas con carga controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2224'),
('b74743ff-8991-5681-8bbf-12cf59343839', 'Prensa de piernas a 45 grados con postura cerrada', ARRAY['Coloca los pies juntos en el centro de la plataforma y apoya bien la espalda en el respaldo.', 'Desciende la plataforma despacio manteniendo las rodillas alineadas con los pies.', 'Empuja con los talones hasta extender las piernas sin bloquear las rodillas.', 'No dejes que los talones se levanten ni que las rodillas se junten en exceso.']::text[], 'intermedio', 'Con los pies juntos, enfatiza el cuádriceps y la parte externa del muslo, útil para trabajar fuerza con mayor control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3616'),
('230640ee-a569-5ba2-9ca3-ae27e4b8ef22', 'Prensa a una pierna a 45 grados', ARRAY['Ajusta la máquina de trineo a un ángulo de 45 grados.', 'Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa.', 'Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti.', 'Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial.', 'Repite con la otra pierna.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteo y cuádriceps de forma unilateral, corrigiendo desequilibrios y mejorando la estabilidad de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1425'),
('108bae44-ff85-5e0a-a039-b7660757f5d8', 'Prensa de piernas a 45 grados con postura abierta', ARRAY['Coloca los pies anchos en la plataforma con las puntas ligeramente hacia fuera y apoya la espalda.', 'Baja la plataforma de forma controlada hasta notar el estiramiento en la parte interna del muslo.', 'Empuja con los talones extendiendo las piernas sin bloquear las rodillas.', 'Evita abrir demasiado las rodillas hacia fuera o perder el apoyo de los talones.']::text[], 'intermedio', 'Con los pies separados, incide más en aductores y glúteos, aportando fuerza y control en la parte interna del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3617'),
('254423c7-1b64-59aa-847b-97ce4b9e5ee3', 'Prensa de gemelos a 45 grados', ARRAY['Ajusta la máquina de trineo a un ángulo de 45 grados.', 'Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante.', 'Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el gemelo y el sóleo para ganar fuerza y volumen en la pantorrilla, con un rango de movimiento amplio y controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0738'),
('597b72f0-0fd1-59b9-9646-f551db2677d0', 'Prensa de piernas 45°', ARRAY['Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda.', 'Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.', 'Sujeta las asas a los lados del asiento para mayor estabilidad.', 'Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.', 'Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas.', 'Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio global de pierna que trabaja glúteos, cuádriceps y femorales, útil para cargar con seguridad y ganar fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0739'),
('010c8f56-a7d8-5105-88c6-4de612ac012c', 'Prensa de piernas 45° en trineo (vista trasera)', ARRAY['Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados.', 'Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa.', 'Sujeta las asas a los lados del asiento para mayor estabilidad.', 'Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa.', 'Haz una pausa por un momento en la posición completamente extendida.', 'Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de empuje que incide en glúteos y cuádriceps, ideal para fortalecer la pierna con un recorrido estable y seguro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1464'),
('88236f85-b0c3-5a4b-9edb-544e9b54a0dd', 'Prensa de piernas a 45 grados abierta', ARRAY['Ajusta la máquina de trineo a un ángulo de 45 grados.', 'Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.', 'Coloca los pies más separados que el ancho de los hombros.', 'Empuja contra la plataforma para extender las piernas y enderezar las rodillas.', 'Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Con los pies anchos, activa glúteos y aductores, mejorando la fuerza y el control en la parte interna de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0740'),
('43e8a7f9-1b9d-5cfd-8cd4-bceed2246c33', 'Prensa de piernas a 45° con postura cerrada en trineo', ARRAY['Coloca los pies juntos en el centro de la plataforma y apoya la espalda completa en el respaldo.', 'Desciende la plataforma despacio manteniendo las rodillas alineadas con los pies.', 'Empuja con los talones hasta extender las piernas sin bloquear las rodillas.', 'Evita que los talones se levanten o que las rodillas se junten demasiado.']::text[], 'intermedio', 'Con los pies juntos, focaliza el cuádriceps y la parte externa del muslo, útil para ganar fuerza con control del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1575'),
('267d914b-a7db-58cb-9327-10927d5709af', 'Press negativo alterno a una pierna', ARRAY['Coloca un pie en el centro de la plataforma y apoya la espalda en el respaldo.', 'Baja la plataforma muy despacio con una sola pierna hasta unos 90 grados de rodilla.', 'Empuja con el talón para volver arriba y alterna la pierna en la siguiente repetición.', 'Evita bajar rápido o despegar la zona lumbar del respaldo.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteo con una fase excéntrica lenta, mejorando el control y la fuerza unilateral de cada pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10198'),
('a67af54e-73b7-552f-8f3b-274b9dc9c0f2', 'Prensa de una pierna angulada', ARRAY['Apoya un pie en la plataforma con la rodilla alineada con el pie y la espalda bien pegada al respaldo.', 'Desciende la plataforma de forma controlada hasta notar el estiramiento en la pierna.', 'Empuja con el talón hasta extender la pierna sin bloquear la rodilla.', 'Evita que la rodilla se desvíe hacia dentro o que la cadera se levante.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteo de forma unilateral con un ángulo que aumenta la activación, corrigiendo desequilibrios entre piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6734'),
('aeb0658d-b6fe-5f0f-aa7f-9e757dbe5ec2', 'Prensa de gemelos en prensa de piernas', ARRAY['Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.', 'Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante.', 'Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos.', 'Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla la pantorrilla con carga controlada, útil para ganar fuerza y volumen en el gemelo y el sóleo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1391'),
('3a83f27a-be53-5a36-86e8-c4dbf6328c94', 'Sentadilla hack cerrada', ARRAY['Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo.', 'Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.', 'Sujeta las asas a los lados de la máquina para mayor estabilidad.', 'Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta.', 'Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y cuádriceps con los pies juntos, aportando fuerza y control en la parte externa del muslo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0741'),
('f3a2991a-9d89-598d-acfc-35638ef167b3', 'Elevación de gemelos inclinada hacia adelante', ARRAY['Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando.', 'Coloca las manos en las asas o a los lados de la máquina para apoyarte.', 'Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo.', 'Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Incide en el gemelo con una inclinación que aumenta el recorrido, mejorando fuerza y volumen de la pantorrilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0742'),
('52ce25db-2f81-59af-9324-83122f503b67', 'Sentadilla hack completa', ARRAY['Coloca los hombros bajo las almohadillas y los pies en la plataforma a la anchura de los hombros.', 'Desciende de forma controlada hasta que las rodillas lleguen a unos 90 grados o algo más.', 'Empuja con los talones para subir extendiendo las piernas sin bloquear las rodillas.', 'Evita despegar la espalda del respaldo o que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y femorales con un recorrido amplio, ideal para ganar fuerza y masa en las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1992'),
('29c7d5a2-7b05-5db9-9b13-8c4c15c6397a', 'Prensa de piernas con énfasis en glúteo', ARRAY['Coloca los pies altos en la plataforma y apoya bien la espalda en el respaldo.', 'Empuja con los talones mientras llevas las rodillas hacia el pecho sin despegar la zona lumbar.', 'Sube controlando dos segundos y evita bloquear las rodillas al final del recorrido.', 'Respira soltando el aire al empujar y coge aire al bajar.']::text[], 'intermedio', 'Trabaja glúteos con apoyo de cuádriceps e isquios, ideal para ganar fuerza y volumen en la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7593'),
('64ea0007-b6fe-52aa-8dba-14f73bf6ddb8', 'Sentadilla hack', ARRAY['Apoya la espalda completa en el respaldo y coloca los hombros bajo las almohadillas.', 'Baja flexionando rodillas y caderas hasta donde mantengas la espalda pegada al respaldo.', 'Empuja con los pies para subir sin bloquear del todo las rodillas.', 'Evita que los talones se levanten y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Enfocada en cuádriceps con ayuda de glúteos e isquios, perfecta para cargar las piernas con estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2345'),
('24f56ed8-1687-5f1c-9004-d2819f9b04c2', 'Prensa de gemelos acostado', ARRAY['Ajusta la máquina de trineo a un peso adecuado.', 'Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.', 'Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando.', 'Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.', 'Continúa empujando hasta que las pantorrillas estén completamente contraídas.', 'Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los gemelos con apoyo de isquios y glúteos, útil para mejorar fuerza y resistencia del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2334'),
('4d97f02a-de3b-554a-9d2f-7f81dcefda37', 'Sentadilla a una pierna acostado', ARRAY['Coloca un pie centrado en la plataforma y apoya la espalda en el respaldo.', 'Baja flexionando la rodilla de la pierna de trabajo sin dejar que se vaya hacia dentro.', 'Empuja con el pie para subir controlando el movimiento y sin bloquear la rodilla.', 'Mantén el core firme y evita que la cadera se desplace hacia un lado.']::text[], 'intermedio', 'Trabaja cuádriceps de forma unilateral con apoyo de glúteos y core, mejorando estabilidad y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10764'),
('d83e6396-0179-5c5c-b254-cc4b2af5525f', 'Sentadilla acostado en trineo', ARRAY['Ajusta la máquina de trineo a un peso adecuado.', 'Túmbate boca arriba en la máquina de trineo con los pies sobre la placa.', 'Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera.', 'Sujeta las asas de la máquina de trineo para mayor estabilidad.', 'Activa los glúteos y los músculos del core.', 'Empuja con los talones y extiende las piernas para levantar el trineo.', 'Baja el trineo de nuevo doblando las rodillas y las caderas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio de empuje que activa glúteos con ayuda de cuádriceps e isquios, fortaleciendo la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0744'),
('5ed1a3bd-0029-5901-bcff-06da9e609b36', 'Sentadilla hack a una pierna', ARRAY['Coloca un pie en el centro de la plataforma y apoya la espalda en el respaldo.', 'Baja controlando la rodilla de la pierna de trabajo sin que se vaya hacia dentro.', 'Empuja con el pie para subir sin bloquear la rodilla al final.', 'Mantén la cadera alineada y evita cargar más peso del que puedas controlar.']::text[], 'intermedio', 'Trabaja cuádriceps de forma unilateral con apoyo de glúteos y gemelos, mejorando fuerza y equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1579'),
('0017f233-7394-55d0-a1fb-9bd523bea8fc', 'Sentadilla hack inversa', ARRAY['Colócate de espaldas al respaldo con los pies en la plataforma y el torso apoyado.', 'Baja llevando la cadera hacia atrás mientras flexionas las rodillas.', 'Empuja con los talones para subir controlando el movimiento.', 'Evita redondear la espalda y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Variante que enfatiza glúteos e isquios con apoyo de cuádriceps, útil para trabajar la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1583'),
('4d31c933-ca3d-5359-9108-6be4db360ef7', 'Prensa lateral de piernas', ARRAY['Coloca los pies en la plataforma con una postura más abierta y lateral.', 'Empuja con los talones manteniendo la espalda apoyada en el respaldo.', 'Sube controlando y evita bloquear las rodillas al final del recorrido.', 'No dejes que las rodillas se vayan hacia dentro al empujar.']::text[], 'intermedio', 'Activa glúteos con apoyo de cuádriceps y aductores, útil para trabajar la cadera en un plano distinto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8660'),
('557f963f-6b2d-53c2-84cf-35e63d2e46f0', 'Prensa vertical de piernas', ARRAY['Apoya la espalda completa en el respaldo y coloca los pies en la plataforma.', 'Baja flexionando rodillas y caderas hasta donde mantengas la zona lumbar pegada.', 'Empuja con los pies para subir sin bloquear del todo las rodillas.', 'Evita que los talones se levanten y mantén el core activo.']::text[], 'intermedio', 'Ejercicio de empuje que trabaja cuádriceps con ayuda de glúteos e isquios, fortaleciendo las piernas con estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4327'),
('73e61691-f9cb-5bf1-ae32-a7fb447c5050', 'Sentadilla hack abierta', ARRAY['Coloca los pies más abiertos que la anchura de los hombros y apoya la espalda en el respaldo.', 'Baja flexionando rodillas y caderas manteniendo la espalda pegada al respaldo.', 'Empuja con los pies para subir sin bloquear las rodillas.', 'Evita que las rodillas se vayan hacia dentro al empujar.']::text[], 'intermedio', 'Enfocada en cuádriceps con apoyo de glúteos y aductores, ideal para trabajar las piernas con una postura amplia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4100'),
('7c1becfd-cd29-5243-8d75-3c4ec3a4816d', 'Mazo con martillo', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos.', 'Activa el core y mantén la espalda recta.', 'Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo.', 'Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el core y la fuerza de agarre con apoyo de hombros, útil para potencia y estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1496'),
('350d9ce6-f883-50a0-a378-b4f6adc1ea26', 'Estiramiento sleeper', ARRAY['Túmbate de lado con el brazo de abajo estirado hacia delante y el codo flexionado.', 'Presiona suavemente el antebrazo hacia el suelo hasta notar estiramiento en el hombro.', 'Mantén la posición sin forzar y respira de forma relajada.', 'Evita levantar el hombro del suelo o forzar el giro del brazo.']::text[], 'principiante', 'Estira el hombro y la parte posterior del deltoides, ayudando a mejorar movilidad y aliviar tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11374'),
('171c6eec-f042-5e89-93e9-63fdc309f86f', 'Curl de puente deslizante con toalla', ARRAY['Túmbate boca arriba con los talones sobre una toalla y las rodillas flexionadas.', 'Eleva la cadera y desliza los pies hacia delante controlando el movimiento.', 'Recoge los talones para volver a la posición inicial sin dejar caer la cadera.', 'Mantén el core activo y evita arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja isquios y glúteos con apoyo de la zona lumbar, mejorando fuerza y control de la cadena posterior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3498'),
('2197c03b-01c3-581a-90af-eb85201e34e7', 'Jalón deslizante en el suelo con toalla', ARRAY['Túmbate boca abajo con los brazos estirados y las manos sobre una toalla.', 'Desliza las manos hacia el cuerpo flexionando los codos y apretando los omóplatos.', 'Vuelve a estirar los brazos controlando el movimiento.', 'Evita levantar la cabeza o arquear la zona lumbar durante el recorrido.']::text[], 'intermedio', 'Activa dorsales con apoyo de espalda alta y core, útil para trabajar la tracción sin material de gimnasio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3497'),
('206c1a0b-d358-530c-b9c5-ba3365697b2d', 'Bird dog con deslizamiento de pierna', ARRAY['Colócate a cuatro patas con la espalda recta y el core activo.', 'Desliza una pierna hacia atrás mientras extiendes el brazo contrario.', 'Mantén la cadera nivelada y vuelve despacio a la posición inicial.', 'Evita arquear la zona lumbar o girar la cadera al estirar la pierna.']::text[], 'intermedio', 'Trabaja el core y la estabilidad lumbar con apoyo de glúteos y hombros, mejorando el control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4416'),
('fa83d910-9192-53c6-a7c9-a9b7ccc8ba03', 'Curl de femoral deslizante con toalla', ARRAY['Túmbate boca arriba con los talones sobre una toalla y las piernas estiradas.', 'Eleva la cadera y desliza los talones hacia el glúteo flexionando las rodillas.', 'Empuja con los talones para volver a estirar las piernas sin bajar la cadera.', 'Mantén el core activo y evita arquear la zona lumbar en exceso.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos deslizando los talones sobre una toalla, mejorando el control y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3395'),
('4fbc85fc-b1a3-5a47-88e1-0caee3256bd6', 'Estiramiento inclinándose hacia delante', ARRAY['Siéntate con las piernas estiradas o cruza una sobre la otra.', 'Inclina el tronco hacia delante llevando el pecho hacia las rodillas.', 'Alarga los brazos y respira profundo manteniendo el estiramiento.', 'Evita rebotar y no fuerces si notas dolor en la espalda baja.']::text[], 'principiante', 'Estira el dorsal ancho y la zona lumbar, aliviando tensión tras entrenamientos de espalda o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4312'),
('6655948c-a7a2-5b84-a77d-11edbec8bbf4', 'Encogimiento por detrás en Smith', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.', 'Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos.', 'Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta.', 'Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los trapecios elevando los hombros con la barra guiada por detrás del cuerpo para ganar masa en la zona alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0746'),
('c11d3b40-1161-5782-9537-05dab6e87410', 'Encogimiento tras la espalda con agarre ancho en Smith', ARRAY['Colócate de espaldas a la barra con las manos en agarre ancho por detrás.', 'Deja los brazos estirados y los hombros relajados al inicio.', 'Sube los hombros hacia las orejas sin doblar los codos.', 'Baja controlado y evita encoger el cuello o usar impulso.']::text[], 'intermedio', 'Trabaja los trapecios superiores con un agarre amplio detrás del cuerpo, mejorando la postura y la fuerza del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5225'),
('d976b7cc-62a0-5b72-aa81-b7dfec6a436a', 'Sentadilla completa con banda en Smith', ARRAY['Coloca la banda en la barra y pásala bajo los pies.', 'Sitúate bajo la barra con los pies al ancho de hombros.', 'Baja flexionando rodillas y cadera hasta una sentadilla profunda.', 'Empuja con los talones para subir manteniendo el pecho alto.', 'Evita que las rodillas se metan hacia dentro durante el recorrido.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con una sentadilla profunda guiada, añadiendo tensión de banda para más activación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4179'),
('114b0cd3-8164-516e-82e1-7c54cfa8b3ba', 'Press por detrás de la nuca en Smith', ARRAY['Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.', 'Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante.', 'Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los deltoides y tríceps empujando la barra guiada por detrás de la cabeza, con control y movilidad suficiente.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0747'),
('44dab70c-db64-5b02-a5f4-40b2a89236eb', 'Sentadilla al banco en Smith', ARRAY['Coloca el banco detrás de ti y la barra sobre los hombros.', 'Baja la cadera hacia el banco flexionando rodillas y cadera.', 'Rocza el banco suavemente y empuja con los talones para subir.', 'Mantén el core firme y evita desplomar la espalda al sentarte.']::text[], 'intermedio', 'Fortalece piernas y glúteos controlando la bajada hasta un banco, ideal para aprender el patrón de sentadilla con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11303'),
('be5c7d27-ad3c-5cb0-8078-335a56261912', 'Good morning con rodillas flexionadas en Smith', ARRAY['Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante.', 'Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.', 'Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos, isquiotibiales y zona lumbar inclinando el tronco con la barra guiada y las rodillas ligeramente flexionadas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0749'),
('498be101-70bb-5734-8e91-e81250e9a522', 'Remo inclinado con agarre estrecho pronado en Smith', ARRAY['Inclina el tronco con la barra sujeta en agarre estrecho pronado.', 'Mantén la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la barra hacia el abdomen juntando las escápulas.', 'Baja controlado sin perder la posición del tronco.', 'Evita redondear la espalda o usar impulso de cadera.']::text[], 'intermedio', 'Trabaja la espalda media y los dorsales con un tirón horizontal, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5316'),
('2ba13be5-272b-55d0-894a-b1b972384687', 'Remo inclinado en Smith', ARRAY['Configura la máquina Smith con la barra a la altura de la cadera.', 'Ponte de pie frente a la barra con los pies separados a la altura de los hombros.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Tira de la barra hacia la parte baja del pecho, juntando las escápulas.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la espalda alta y los bíceps tirando de la barra guiada hacia el abdomen con el tronco inclinado y estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1359'),
('b2a2cdfb-8523-5c01-9b1c-f98106cb27a4', 'Elevación de gemelos en Smith con bloque', ARRAY['Coloca la punta de los pies sobre un bloque bajo la barra.', 'Sujeta la barra y deja los talones colgando en el aire.', 'Sube los talones lo máximo posible y aprieta los gemelos.', 'Baja lento hasta estirar bien el tobillo.', 'Evita rebotar o doblar las rodillas para hacer impulso.']::text[], 'intermedio', 'Aísla los gemelos y sóleos elevando los talones sobre un bloque, mejorando la fuerza y el equilibrio del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1050'),
('1e7a678f-f281-5394-91e5-0cbb744cd864', 'Sentadilla en silla con Smith', ARRAY['Ajusta la altura de la barra de la máquina Smith a una posición cómoda.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.', 'Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Guía el patrón de sentadilla hasta tocar una silla para aprender la profundidad y ganar fuerza en piernas y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0750'),
('f67c93cb-0798-53bb-82f9-81f834961bfc', 'Zancada de reverencia en Smith', ARRAY['Colócate bajo la barra con un pie adelantado y el otro detrás cruzado.', 'Baja flexionando la rodilla delantera mientras la trasera se cruza.', 'Mantén el tronco erguido y la rodilla delantera alineada con el pie.', 'Empuja con la pierna delantera para volver arriba.', 'Evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Activa glúteos y aductores cruzando una pierna detrás, mejorando la estabilidad y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6606'),
('dc99b172-8318-5e5c-b2ae-dae732dc447d', 'Peso muerto en Smith', ARRAY['Configura la máquina Smith con la barra a la altura de la cadera.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros.', 'Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo.', 'Ponte de pie erguido, extendiendo por completo las caderas y las rodillas.', 'Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio global que fortalece glúteos, isquiotibiales y espalda baja levantando la barra guiada desde el suelo con bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0752'),
('96e3ea11-31fd-58bc-9dfd-0da1c62e88c7', 'Press de banca declinado en Smith', ARRAY['Ajusta el banco declinado al ángulo deseado.', 'Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca el trabajo en la porción inferior del pecho empujando la barra guiada desde un banco declinado, con tríceps y hombros como apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0753'),
('10e75df5-db73-57d4-9aec-665329510d67', 'Press declinado con agarre inverso en Smith', ARRAY['Ajusta la máquina Smith a una posición declinada.', 'Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.', 'Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.', 'Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la parte baja del pecho con un agarre que suma tensión al tríceps y al hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0754'),
('d25854d3-59a2-55bd-b505-f647ce6de7ac', 'Patada de burro en Smith', ARRAY['Colócate a cuatro apoyos frente a la barra guiada, con las manos en el suelo y una rodilla apoyada.', 'Apoya el pie libre en la barra o en el tope y mantén la espalda neutra sin arquear la lumbar.', 'Empuja la barra hacia atrás y arriba extendiendo la cadera hasta notar el glúteo contraído.', 'Baja controlando el movimiento sin dejar caer la cadera ni rotar la pelvis.', 'Evita balancear el tronco o usar impulso; exhala al empujar y sube con tempo lento.']::text[], 'intermedio', 'Aísla el glúteo en extensión de cadera y refuerza la estabilidad del core en apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6038'),
('60b41e33-c159-58bc-a7c9-e601b7857538', 'Curl arrastrado en Smith', ARRAY['Sitúate de pie frente a la barra guiada con los pies a la anchura de las caderas.', 'Agarra la barra en pronación con las manos algo más juntas que los hombros.', 'Sube la barra arrastrándola cerca del cuerpo, llevando los codos hacia atrás y arriba.', 'Aprieta el bíceps arriba un instante y baja controlando sin balancear el tronco.', 'Evita encoger los hombros o usar impulso de cadera; exhala al subir.']::text[], 'intermedio', 'Curl de bíceps con recorrido corto que enfatiza la parte alta del brazo y el antebrazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4546'),
('b6bda037-f822-582e-b63d-3c27f67547cd', 'Sentadilla dividida elevada en Smith', ARRAY['Coloca un pie delante sobre una plataforma elevada y el otro detrás, con la barra sobre los trapecios.', 'Mantén el tronco erguido y el core activo antes de iniciar el descenso.', 'Baja flexionando la rodilla delantera hasta que el muslo quede cerca de la horizontal.', 'Empuja con el talón delantero para subir sin bloquear la rodilla de golpe.', 'Evita que la rodilla delantera se vaya hacia dentro; inhala al bajar y exhala al subir.']::text[], 'intermedio', 'Trabaja el cuádriceps y el glúteo de forma unilateral con mayor rango y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9042'),
('638c44e2-07cb-51df-91a5-2f8dd5c9276b', 'Sentadilla Frankenstein en Smith', ARRAY['Coloca la barra en la máquina Smith a la altura del pecho y sujétala con los brazos extendidos al frente.', 'Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando caderas y rodillas manteniendo el pecho alto y la barra estable.', 'Sube empujando con los talones y aprieta el glúteo arriba sin perder la postura.', 'Evita inclinar el tronco hacia delante o dejar caer los codos; respira de forma constante.']::text[], 'intermedio', 'Sentadilla con barra adelantada que exige core y hombros para mantener el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1594'),
('44c607f1-0fd2-580d-bfd5-ac734a2cb445', 'Hip thrust de rana en Smith', ARRAY['Apoya la espalda alta en un banco y coloca la barra guiada sobre la cadera con una almohadilla.', 'Junta las plantas de los pies y abre las rodillas hacia fuera en posición de rana.', 'Empuja con los talones y sube la cadera hasta alinear tronco y muslos.', 'Aprieta el glúteo arriba un segundo y baja controlando sin perder la tensión.', 'Evita arquear la lumbar en exceso; exhala al subir y mantén el core firme.']::text[], 'intermedio', 'Empuje de cadera con rodillas abiertas que activa el glúteo y los aductores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6465'),
('2521b288-971e-5940-9dd6-a24a5bfd5239', 'Sentadilla dividida con pierna delantera elevada en Smith', ARRAY['Coloca el pie delantero sobre una plataforma y el trasero en el suelo, con la barra sobre los hombros.', 'Alinea la rodilla delantera con el pie y mantén el tronco erguido.', 'Baja de forma controlada hasta que la rodilla trasera se acerque al suelo.', 'Empuja con el talón delantero para volver arriba sin perder el equilibrio.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie; respira con ritmo.']::text[], 'intermedio', 'Variante unilateral que aumenta el rango del cuádriceps y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9041'),
('abe77814-9955-5b66-8e81-c5172f2867e0', 'Sentadilla frontal en Smith con agarre de cargada', ARRAY['Configura la máquina Smith con la barra a la altura de los hombros.', 'Ponte de pie frente a la barra con los pies separados a la altura de los hombros.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides.', 'Mantén el pecho elevado, la espalda recta y el core activado.', 'Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla.', 'Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Sentadilla frontal que carga el glúteo y el cuádriceps exigiendo un core muy estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1433'),
('fa1d462d-417c-5186-b589-d2974dd0449e', 'Buenos días en Smith desde los pasadores', ARRAY['Coloca la barra en los pasadores a la altura de la cadera y apóyala sobre los trapecios.', 'Separa los pies a la anchura de los hombros con las rodillas ligeramente flexionadas.', 'Lleva la cadera hacia atrás inclinando el tronco con la espalda recta hasta notar el estiramiento.', 'Vuelve empujando la cadera hacia delante y apretando el glúteo.', 'Evita redondear la espalda o bajar más de lo que controlas; inhala al bajar.']::text[], 'intermedio', 'Bisagra de cadera que fortalece isquios, glúteo y espalda baja con recorrido controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1519'),
('1f63c66c-aff8-51f7-94d7-696014cf8ccc', 'Sentadilla hack en Smith', ARRAY['Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.', 'Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.', 'Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte.', 'Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros.', 'Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta.', 'Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Sentadilla guiada que enfatiza glúteo y cuádriceps con la espalda apoyada y segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0755'),
('8b455ddb-58af-56c7-8ad2-ba9285b4f88b', 'Cargada desde colgado en Smith', ARRAY['Sujeta la barra guiada a la altura de los muslos con agarre prono y brazos extendidos.', 'Flexiona ligeramente las rodillas y lleva la cadera atrás manteniendo la espalda neutra.', 'Extiende con fuerza caderas y rodillas y encoge los hombros para acelerar la barra.', 'Recibe la barra arriba con los codos altos y las rodillas ligeramente flexionadas.', 'Evita tirar solo con los brazos; exhala en el tirón y controla la bajada.']::text[], 'avanzado', 'Movimiento explosivo de halterofilia que potencia trapecios, glúteo y coordinación general.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '5142'),
('1351c146-f81d-50ee-a4e9-66e56a4d1752', 'Press hexagonal en Smith', ARRAY['Túmbate en un banco plano bajo la barra guiada con dos mancuernas juntas a la altura del pecho.', 'Aprieta las mancuernas entre sí con las palmas enfrentadas y los codos cerca del torso.', 'Empuja hacia arriba manteniendo la presión entre las manos durante todo el recorrido.', 'Baja controlando hasta notar el estiramiento del pecho sin abrir los codos.', 'Evita bloquear los codos de golpe o perder la presión; exhala al empujar.']::text[], 'intermedio', 'Press de pecho con mancuernas juntas que suma tensión al tríceps y al pecho interno.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2919'),
('988a356c-cc01-53dc-bfa8-d718bfb650c7', 'Elevación de cadera en Smith', ARRAY['Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros.', 'Coloca las manos en la barra, un poco más separadas que el ancho de los hombros.', 'Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo.', 'Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.', 'Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Flexión de cadera colgado que trabaja el abdomen bajo y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0756'),
('40291836-bbaa-518d-8d89-0429f001cc05', 'Empuje de cadera en Smith', ARRAY['Apoya la espalda alta en un banco y coloca la barra guiada sobre la cadera con almohadilla.', 'Pies a la anchura de las caderas, plantas firmes y rodillas alineadas con los pies.', 'Empuja con los talones y sube la cadera hasta que tronco y muslos queden alineados.', 'Aprieta el glúteo arriba un instante y baja controlando sin apoyar del todo.', 'Evita hiperextender la lumbar o empujar con las puntas; exhala al subir.']::text[], 'intermedio', 'Hip thrust guiado que aísla el glúteo y refuerza isquios y core con gran carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3110'),
('56176fd1-2f33-59eb-8b5a-d4582ad64898', 'Press de banca inclinado con agarre cerrado en Smith', ARRAY['Ajusta el banco inclinado bajo la barra guiada y túmbate con los pies firmes en el suelo.', 'Agarra la barra con las manos a la anchura de los hombros o algo más juntas.', 'Baja la barra al pecho alto con los codos cerca del torso y las muñecas rectas.', 'Empuja hacia arriba extendiendo los codos sin bloquear de golpe.', 'Evita abrir los codos en exceso o rebotar en el pecho; exhala al empujar.']::text[], 'intermedio', 'Press inclinado con manos juntas que prioriza el tríceps y la parte alta del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10116'),
('2796e604-c4d2-59f4-9d91-b2a35abd453f', 'Press inclinado con agarre inverso en Smith', ARRAY['Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo.', 'Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.', 'Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros.', 'Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa por un momento cuando la barra esté justo por encima del pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja la parte superior del pecho con un agarre que reduce la tensión en el hombro y añade variedad al entrenamiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0758'),
('aa0513ea-4076-5b45-9b99-d043cf04556e', 'Elevaciones de hombros inclinadas en Smith', ARRAY['Ajusta la máquina Smith a una posición inclinada.', 'Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Mantén la espalda recta y el core activado.', 'Eleva la barra hacia el techo, guiando el movimiento con los codos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el serrato anterior y los deltoides para mejorar la estabilidad escapular y la movilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0759'),
('95ee6301-2241-5632-98be-722da557b076', 'Press JM en Smith', ARRAY['Túmbate en el banco con la barra alineada sobre el pecho y los codos pegados al torso.', 'Agarra la barra con las manos a la anchura de los hombros y desbloquéala.', 'Baja la barra hacia la parte baja del pecho manteniendo los codos cerca del cuerpo.', 'Empuja hacia arriba hasta extender los brazos sin bloquear del todo los codos.', 'Evita abrir los codos en exceso para no sobrecargar el hombro.']::text[], 'intermedio', 'Variante de press que carga el tríceps y el pecho con un recorrido corto y controlado para ganar fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9385'),
('7e5658cb-6e2e-5647-9a01-149a19870ac5', 'Empuje de cadera de rodillas en Smith', ARRAY['Colócate de rodillas frente a la barra del Smith con la espalda apoyada en el suelo o en un banco.', 'Apoya la barra sobre la cadera y sujétala con las manos para estabilizarla.', 'Empuja la cadera hacia arriba apretando los glúteos hasta alinear el cuerpo.', 'Baja de forma controlada sin dejar caer la cadera de golpe.', 'Evita arquear la zona lumbar en exceso; el movimiento sale del glúteo.']::text[], 'intermedio', 'Aísla el glúteo con un empuje de cadera desde el suelo, ideal para activar la cadena posterior sin cargar la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3874'),
('356ce686-7c65-51c0-962d-cdab564e91b2', 'Patada trasera de rodillas en Smith', ARRAY['Colócate a cuatro apoyos frente a la barra del Smith, con una pierna enganchada o apoyada en la barra.', 'Mantén la espalda neutra y el core activado durante todo el movimiento.', 'Empuja la pierna hacia atrás y arriba apretando el glúteo sin rotar la cadera.', 'Vuelve despacio a la posición inicial sin dejar caer la pierna.', 'Evita balancear el tronco o compensar con la lumbar.']::text[], 'intermedio', 'Trabaja el glúteo de forma aislada con una extensión de cadera que también activa isquios y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1183'),
('7d6fad5b-100f-538a-892f-d62a207717e5', 'Subida lateral al cajón en Smith', ARRAY['Colócate de lado junto a un cajón o banco con la barra del Smith a un lado para apoyarte.', 'Apoya un pie sobre el cajón con toda la planta y el otro en el suelo.', 'Empuja con la pierna de arriba para subir extendiendo la cadera y la rodilla.', 'Baja de forma controlada hasta tocar el suelo con el pie libre.', 'Evita impulsarte con la pierna de abajo; el trabajo lo hace la de arriba.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0884'),
('88bd67a6-2967-53ce-b80e-619ecae1dbf8', 'Prensa de piernas en Smith', ARRAY['Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda.', 'Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.', 'Sujeta las asas o los lados de la máquina para mayor estabilidad.', 'Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo.', 'Haz una pausa por un momento en la posición completamente extendida.', 'Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Carga glúteos y cuádriceps con un empuje de piernas guiado que permite mover bastante peso con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0760'),
('ee3c1264-390c-5bef-948f-c4046c36951d', 'Sentadilla con barra baja en Smith', ARRAY['Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.', 'Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.', 'Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte.', 'Respira profundamente y tensa el core.', 'Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.', 'Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.', 'Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Sentadilla con barra baja que enfatiza glúteos e isquios manteniendo el tronco más inclinado y estable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1434'),
('5e3cc6d3-96bd-5e14-88af-591638140380', 'Elevación acostado de lado en Smith (sobre la cadera)', ARRAY['Túmbate de lado con la cadera apoyada en el suelo y la barra del Smith sobre la cadera.', 'Sujeta la barra con la mano para controlarla y mantén el cuerpo alineado.', 'Eleva la cadera hacia arriba apretando el glúteo lateral sin rotar el tronco.', 'Baja despacio hasta apoyar de nuevo la cadera.', 'Evita arquear la espalda o empujar con la lumbar.']::text[], 'intermedio', 'Activa los abductores y el glúteo medio con una elevación lateral que mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0885'),
('98e6365b-ecb3-5a1f-b7bb-36463c775299', 'Curl de bíceps en Smith', ARRAY['Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.', 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.', 'Mantén los codos cerca de los costados y los brazos superiores quietos.', 'Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.', 'Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.', 'Inhala y baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps con un curl guiado que permite controlar bien el recorrido y añadir tensión constante.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1683'),
('1fb4a8d8-069c-50f2-a036-41d8c11667a8', 'Press de banca declinado con agarre cerrado en Smith', ARRAY['Ajusta el banco de la máquina Smith a una posición declinada.', 'Túmbate en el banco con los pies firmemente apoyados en el suelo.', 'Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.', 'Haz una pausa breve cuando la barra esté justo encima del pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Carga el tríceps con un press declinado de agarre cerrado que también implica pecho y hombros.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1625'),
('02636767-8f13-5840-af50-e24d14fba98b', 'Press de banca declinado invertido con agarre cerrado en Smith', ARRAY['Ajusta la máquina Smith a una posición declinada.', 'Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.', 'Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.', 'Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Variante invertida que trabaja el pecho con un agarre cerrado y un recorrido declinado controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1626'),
('3c309eee-53b5-55a4-8e25-33b777e00bd2', 'Remo cerrado en Smith', ARRAY['Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo.', 'Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros.', 'Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas.', 'Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece la espalda alta con un remo de agarre estrecho que también activa bíceps y deltoides posteriores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0761'),
('ee5ff978-3897-5e05-9649-3bb5414d956e', 'Remo a un brazo en Smith', ARRAY['Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.', 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo.', 'Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas.', 'Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia al otro brazo.']::text[], 'intermedio', 'Remo unilateral que trabaja la espalda alta y corrige desequilibrios entre lados con apoyo en la barra.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1360'),
('027cee86-9f69-52d1-b2b8-5d9110a2dcc7', 'Peso muerto a una pierna en Smith', ARRAY['Colócate de pie frente a la barra del Smith con una pierna ligeramente elevada del suelo.', 'Sujeta la barra con una mano y mantén la espalda recta y el core activado.', 'Inclina el tronco hacia delante llevando la cadera atrás mientras la pierna libre se extiende detrás.', 'Baja hasta notar el estiramiento del isquio y vuelve apretando el glúteo.', 'Evita redondear la espalda o perder el equilibrio; controla el tempo.']::text[], 'intermedio', 'Trabaja isquios y glúteos con un patrón unilateral que mejora el equilibrio y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0886'),
('88bec249-d50e-59ec-84c4-84823bfa3619', 'Elevación de gemelos a una pierna en Smith', ARRAY['Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina.', 'Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque.', 'Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos.', 'Sujeta la barra con las manos para mayor estabilidad.', 'Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba.', 'Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos con trabajo unilateral, mejorando el equilibrio y corrigiendo descompensaciones entre piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1393'),
('d50c3048-5f21-5188-9020-8911041c693f', 'Peso muerto desde rack en Smith', ARRAY['Coloca la barra del Smith a la altura de las rodillas y ajústala para que quede justo debajo de la cadera.', 'Ponte de pie con los pies a la anchura de los hombros y agarra la barra con las manos algo más abiertas que las piernas.', 'Empuja el suelo con los pies y extiende la cadera para subir la barra, manteniendo la espalda neutra y el pecho arriba.', 'Baja la barra de forma controlada hasta la posición inicial sin perder la tensión.', 'Evita redondear la zona lumbar o tirar con los brazos: el movimiento nace de la cadera.']::text[], 'intermedio', 'Trabaja glúteos y cadena posterior desde una altura parcial, útil para ganar fuerza en el bloqueo del peso muerto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4171'),
('8611646c-286b-5844-b811-76308e37c53a', 'Remo para deltoide posterior en Smith', ARRAY['Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.', 'Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas.', 'Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla la parte posterior del hombro y los romboides, equilibrando el desarrollo del tren superior y mejorando la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0762'),
('6e460f33-5b71-5436-ad8d-5f5b51394109', 'Zancada hacia atrás en Smith', ARRAY['Coloca la barra del Smith sobre los trapecios y ponte de pie con los pies a la anchura de la cadera.', 'Da un paso largo hacia atrás y baja la rodilla trasera hacia el suelo manteniendo el torso erguido.', 'Empuja con el pie delantero para volver a la posición inicial y repite con la otra pierna.', 'Mantén el core firme y evita que la rodilla delantera se vaya hacia dentro.', 'Respira al bajar y controla el descenso sin dejar caer el peso.']::text[], 'intermedio', 'Activa glúteos y cuádriceps con un patrón unilateral guiado, ideal para ganar fuerza y estabilidad en las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5825'),
('78aa7494-abf2-5e85-a411-a277ef0ea637', 'Elevación inversa de gemelos en Smith', ARRAY['Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.', 'Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.', 'Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.', 'Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado.', 'Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el tibial anterior y la parte frontal de la pierna, mejorando el equilibrio muscular y la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0763'),
('14d0b18a-f66a-50f6-8631-a353b51fcaff', 'Remo inclinado con agarre inverso en Smith', ARRAY['Configura la máquina Smith con la barra a la altura de la cadera.', 'Ponte de pie frente a la barra con los pies separados a la altura de los hombros.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.', 'Tira de la barra hacia la parte baja del pecho, juntando las escápulas.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza la espalda alta y los bíceps con un agarre que aumenta el recorrido y la activación del dorsal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1361'),
('1d5ce639-8318-5466-96a5-00d7ec893df0', 'Hiperextensión inversa en Smith', ARRAY['Colócate frente al Smith con las manos apoyadas en la barra a la altura de la cadera y el torso inclinado.', 'Mantén los pies juntos y las rodillas ligeramente flexionadas con la espalda neutra.', 'Eleva las piernas hacia atrás apretando los glúteos hasta que queden alineadas con el torso.', 'Baja las piernas de forma controlada sin balancearte ni arquear la lumbar.', 'Evita usar impulso: el movimiento debe salir del glúteo y el isquio.']::text[], 'intermedio', 'Fortalece glúteos e isquios con un movimiento de cadera que también descarga la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2745'),
('88c350c8-c496-5b08-9ded-cb7198fc7aca', 'Press con agarre inverso en Smith', ARRAY['Ajusta la altura de la barra de la máquina Smith a la altura del pecho.', 'Ponte de pie frente a la barra con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.', 'Da un paso atrás y colócate con una ligera flexión en las rodillas.', 'Mantén el pecho elevado y el core activado durante todo el ejercicio.', 'Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo.', 'Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfatiza la parte superior del pecho y el tríceps con un agarre que cambia el ángulo de trabajo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0764'),
('6d4317e0-007b-58ff-b97a-79d5d06cabb9', 'Elevación de gemelos sentado a una pierna en Smith', ARRAY['Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés.', 'Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él.', 'Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Aísla el sóleo con trabajo unilateral sentado, mejorando la resistencia y el control del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1395'),
('bf201174-b4ab-52c6-bcc3-5df2294da042', 'Press de hombros sentado en Smith', ARRAY['Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros.', 'Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.', 'Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo.', 'Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.', 'Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.', 'Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla la fuerza del deltoide y el tríceps con un recorrido guiado que permite cargar de forma segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0765'),
('2dc24cfa-07b8-5c42-9fc5-b448408e636a', 'Press de hombros a un brazo con agarre neutro en Smith', ARRAY['Siéntate en un banco dentro del Smith con la barra a la altura de los hombros y agarra con una mano y agarre neutro.', 'Aprieta el core y el glúteo para estabilizar el tronco antes de empujar.', 'Empuja la barra hacia arriba hasta extender el brazo sin bloquear del todo el codo.', 'Baja de forma controlada hasta la altura del hombro y repite.', 'Evita inclinarte hacia el lado contrario o arquear la espalda al empujar.']::text[], 'intermedio', 'Trabaja el hombro de forma unilateral con agarre neutro, exigiendo estabilidad al core y corrigiendo desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10863'),
('3c96875a-bfd7-516f-8687-9052a64b9440', 'Curl de muñeca sentado en Smith', ARRAY['Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo.', 'Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros.', 'Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen.', 'Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y la muñeca, mejorando el agarre y la resistencia en ejercicios de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1426'),
('e77b35d7-69ce-5d74-9caa-a1a0e72b927f', 'Press de hombros en Smith', ARRAY['Ajusta la altura del asiento y colócate en la máquina Smith con los pies separados a la altura de los hombros.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Levanta la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.', 'Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la altura de los hombros.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja deltoides y tríceps con un movimiento guiado que permite centrarse en la técnica y la carga.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0766'),
('6728d588-ecc1-5766-8b9d-f78e3f9ff3b5', 'Encogimientos de hombros en Smith', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.', 'Mantén los brazos rectos y los hombros relajados.', 'Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta.', 'Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los trapecios superiores, mejorando la fuerza del cuello y la estética de la parte alta de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0767'),
('275639b5-d8fc-51fd-8ccf-cb7e40c613b4', 'Remo inclinado a un brazo en Smith', ARRAY['Colócate de pie frente al Smith con una mano apoyada en la barra y el torso inclinado.', 'Agarra la barra con la otra mano y deja el brazo extendido con la espalda neutra.', 'Tira de la barra hacia la cadera llevando el codo hacia atrás y apretando el dorsal.', 'Baja de forma controlada hasta extender el brazo sin perder la posición del torso.', 'Evita girar el tronco o encoger el hombro al tirar.']::text[], 'intermedio', 'Aísla el dorsal de forma unilateral, corrigiendo desequilibrios y mejorando la conexión mente-músculo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3945'),
('aaca5188-3111-563f-884c-650466d7ed7e', 'Sentadilla búlgara en Smith', ARRAY['Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.', 'Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante.', 'Sujétate de la barra de la máquina Smith para mayor estabilidad.', 'Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.', 'Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con apoyo unilateral, mejorando fuerza y equilibrio de cada pierna por separado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0768'),
('b1a99a53-9339-53e1-9152-9e288106cd87', 'Zancada de sprint en Smith', ARRAY['Configura la máquina Smith con la barra a la altura de la cadera.', 'Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.', 'Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella.', 'Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.', 'Empuja con el talón izquierdo para volver a la posición inicial.', 'Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Potencia glúteos y piernas con un gesto explosivo unilateral, útil para aceleración y fuerza aplicada al sprint.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0769'),
('83b26a09-7520-583c-8941-8bff5efa8827', 'Sentadilla en Smith', ARRAY['Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla.', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.', 'Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.', 'Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.', 'Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte.', 'Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas.', 'Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.', 'Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos y piernas con trayectoria guiada, permitiendo cargar más y controlar mejor la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0770'),
('3acf489b-d7ce-5f93-b649-af100eb00db0', 'Empuje de cadera con piernas escalonadas en Smith', ARRAY['Apoya la espalda alta en el banco y coloca la barra sobre la cadera con una almohadilla.', 'Adelanta un pie y retrasa el otro, manteniendo ambos apoyados en el suelo.', 'Empuja con el talón del pie adelantado y extiende la cadera hasta alinear el tronco.', 'Aprieta el glúteo arriba un segundo y baja controlando el movimiento.', 'Evita arquear la zona lumbar en exceso: el movimiento sale de la cadera.']::text[], 'intermedio', 'Aísla glúteos con una pierna adelantada, aumentando la activación unilateral y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11053'),
('f313878e-a6cb-536a-83b4-f9f9d0c0ced9', 'Peso muerto rumano con postura escalonada en Smith', ARRAY['Sujeta la barra con las manos y coloca un pie adelantado y otro retrasado.', 'Con las rodillas ligeramente flexionadas, lleva la cadera atrás bajando la barra por las piernas.', 'Nota el estiramiento en los isquiotibiales sin redondear la espalda.', 'Sube empujando la cadera adelante y apretando el glúteo al final.', 'Evita bajar más de lo que tu flexibilidad permite: prioriza la espalda neutra.']::text[], 'intermedio', 'Estira y fortalece isquiotibiales y glúteos con una pierna adelantada, mejorando el control del bisagra de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8800'),
('3ae1e265-c5dc-5b95-88b6-c0cb4f93bc40', 'Curl de muñeca de pie por detrás en Smith', ARRAY['Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.', 'Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.', 'Mantén la espalda recta y los codos cerca del cuerpo.', 'Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza los flexores del antebrazo y la muñeca, mejorando el agarre y la resistencia en ejercicios de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0771'),
('fde64085-4a99-57b6-8f5e-2c2ea79d92f6', 'Press militar de pie por detrás de la cabeza en Smith', ARRAY['Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.', 'Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios.', 'Mantén el core activado y el pecho elevado durante todo el ejercicio.', 'Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo.', 'Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los hombros y el tríceps con recorrido guiado, incidiendo también en la espalda alta y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0772'),
('75d3cc1a-36a1-59b8-bc99-3b4d3d40203c', 'Elevación de gemelos de pie en Smith', ARRAY['Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra.', 'Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.', 'Coloca las manos sobre la barra para mayor estabilidad.', 'Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y sóleo en posición erguida, mejorando la fuerza y el volumen de la pantorrilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0773'),
('7fc4140a-b6fa-5ba3-a9ae-b797dcc6645b', 'Press de hombros de pie en Smith', ARRAY['Colócate bajo la barra con los pies al ancho de hombros y las manos algo más anchas que los hombros.', 'Desbloquea la barra y llévala a la altura de la barbilla con los codos por debajo.', 'Empuja hacia arriba hasta extender los brazos sin bloquear de golpe.', 'Baja controlando hasta la barbilla, inspirando al bajar y espirando al subir.', 'Evita arquear la espalda: mantén el core activo y las costillas abajo.']::text[], 'intermedio', 'Trabaja deltoides y tríceps empujando la barra guiada por encima de la cabeza, con buena estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1224'),
('26ae0eba-1eb3-5920-bec8-e6164dbbe968', 'Subida al banco en Smith', ARRAY['Coloca un banco frente a la barra y apoya un pie entero encima.', 'Sujeta la barra a los lados y sube empujando con la pierna del banco.', 'Extiende la cadera arriba sin ayudarte con impulso de la pierna de abajo.', 'Baja controlando hasta tocar el suelo con el pie libre.', 'Evita empujar con la pierna de abajo: todo el trabajo lo hace la de arriba.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un gesto unilateral, mejorando fuerza, equilibrio y control de la pierna de apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11879'),
('e0b2c672-b2bd-511d-9017-26988f38ab00', 'Peso muerto con piernas rígidas en Smith', ARRAY['Sujeta la barra con las manos y colócate con los pies al ancho de cadera.', 'Con las rodillas casi rectas, lleva la cadera atrás bajando la barra pegada a las piernas.', 'Detente cuando notes estiramiento en los isquiotibiales sin redondear la espalda.', 'Sube empujando la cadera adelante y apretando el glúteo arriba.', 'Evita flexionar demasiado las rodillas: el movimiento es de cadera, no de sentadilla.']::text[], 'intermedio', 'Estira y fortalece isquiotibiales y glúteos con rodillas casi extendidas, mejorando la cadena posterior y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1597'),
('72ce0cfa-79e0-53a3-b28b-09a22f88cdb2', 'Sentadilla sumo en silla en Smith', ARRAY['Coloca una silla detrás y apoya la barra en la espalda alta con los pies muy abiertos y punteras hacia fuera.', 'Desbloquea la barra y desciende controlando hasta tocar la silla con los glúteos.', 'Empuja con los talones y rodillas hacia fuera para subir.', 'Mantén el pecho alto y el core firme durante todo el recorrido.', 'Evita juntar las rodillas al subir: mantenlas alineadas con los pies.']::text[], 'intermedio', 'Activa glúteos y aductores con piernas abiertas y control de profundidad, ideal para trabajar la cadera con seguridad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6796'),
('50208ed0-9eb9-546e-bd16-55d789c39e05', 'Peso muerto sumo en Smith', ARRAY['Colócate con los pies muy abiertos y las puntas hacia fuera, agarrando la barra por dentro de las piernas.', 'Baja la cadera, saca pecho y mantén la espalda neutra antes de tirar.', 'Empuja el suelo con los pies y extiende cadera y rodillas a la vez.', 'Sube la barra pegada al cuerpo y aprieta el glúteo al final.', 'Evita redondear la espalda o tirar con los brazos: la fuerza sale de piernas y cadera.']::text[], 'intermedio', 'Trabaja glúteos, aductores e isquiotibiales con agarre amplio y piernas abiertas, mejorando la fuerza de la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7374'),
('1c353f21-6a9a-5e99-abf8-1d881aa058a6', 'Sentadilla sumo en Smith', ARRAY['Configura la máquina Smith con la barra a la altura de la cadera.', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.', 'Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros.', 'Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Incide en glúteos y aductores con piernas abiertas y trayectoria guiada, mejorando fuerza y control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3142'),
('14297fae-a222-5fcd-82c5-76697bb6a027', 'Elevación de puntas en Smith', ARRAY['Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo.', 'Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros.', 'Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde.', 'Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.', 'Activa el core y mantén la espalda recta durante todo el ejercicio.', 'Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los gemelos y la zona del tobillo, mejorando el empuje y la estabilidad en la carrera y el salto.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1396'),
('51506bc5-0310-5ebd-aef4-c450b291a38d', 'Sentadilla búlgara desde déficit en Smith', ARRAY['Coloca el pie trasero sobre un banco y el delantero sobre una superficie elevada, con la barra del Smith apoyada en la espalda.', 'Desbloquea la barra y desciende flexionando la rodilla delantera hasta que el muslo quede cerca de la horizontal.', 'Empuja con el talón del pie delantero para subir sin bloquear del todo la rodilla.', 'Inspira al bajar y espira al subir, manteniendo el torso erguido.', 'Evita que la rodilla delantera se vaya hacia dentro y no rebotes en el punto más bajo.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos de forma unilateral, mejorando fuerza, equilibrio y control de la pierna de apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11568'),
('ee9886e5-5d46-5b0e-a70c-fafb527d0d9f', 'Remo al mentón en Smith', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith.', 'Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.', 'Mantén la espalda recta y el core activado.', 'Tira de la barra hacia tu barbilla, guiando el movimiento con los codos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Desarrolla los deltoides y los trapecios, aportando fuerza y volumen a la parte superior de hombros y espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0775'),
('ea46a13a-ce38-5ebe-833a-02414150599b', 'Press de banca con agarre abierto en Smith', ARRAY['Ajusta el banco a una posición cómoda en la máquina Smith.', 'Túmbate en el banco con los pies planos sobre el suelo.', 'Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.', 'Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el pectoral con mayor amplitud de recorrido, implicando también tríceps y hombros en el empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1308'),
('c9312ee3-5579-5c24-884e-86a4e3820531', 'Press de banca declinado con agarre abierto en Smith', ARRAY['Ajusta el banco declinado al ángulo deseado.', 'Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.', 'Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.', 'Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera.', 'Haz una pausa breve cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfatiza la porción inferior del pectoral con un recorrido amplio, sumando tríceps y hombros al empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1309'),
('9483b99e-ba5e-5b38-96ad-dcdcf69525b8', 'Encogimientos con agarre abierto en Smith', ARRAY['Sitúate de pie frente a la barra del Smith a la altura de los muslos y agárrala con las manos más anchas que los hombros.', 'Desbloquea la barra y mantén los brazos estirados con los hombros relajados hacia abajo.', 'Sube los hombros hacia las orejas sin doblar los codos y mantén un instante arriba.', 'Baja de forma controlada hasta la posición inicial, espirando al subir.', 'Evita encoger el cuello o usar impulso con las piernas.']::text[], 'intermedio', 'Fortalece los trapecios y la parte alta de la espalda, mejorando la postura y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5223'),
('8931c1e0-4c25-5ba8-ab9d-1196285ed821', 'Sentadilla Zercher en Smith', ARRAY['Coloca la barra del Smith en el pliegue de los codos con los brazos flexionados y el torso erguido.', 'Desbloquea la barra y da un paso atrás para separar los pies a la anchura de los hombros.', 'Desciende flexionando rodillas y caderas manteniendo el pecho alto y la barra pegada al cuerpo.', 'Sube empujando con los talones y espirando, sin perder la curvatura lumbar.', 'Evita inclinarte demasiado hacia delante o dejar que los codos se abran en exceso.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con gran demanda de core y espalda alta, mejorando la fuerza global y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1598'),
('e011601d-3e77-5062-b126-58a00a15ca63', 'Jalón de arrancada', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.', 'Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono.', 'Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.', 'Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.', 'Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda.', 'Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas.', 'Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza.', 'Baja la barra de nuevo a la posición inicial invirtiendo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Desarrolla potencia y fuerza en piernas y cadena posterior, base del arrancado en halterofilia.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0776'),
('704d28aa-c575-5b0e-959f-e8b6845b16a1', 'Ángel de nieve boca abajo', ARRAY['Túmbate boca abajo con los brazos extendidos por encima de la cabeza y las palmas hacia el suelo.', 'Despega ligeramente el pecho y desliza los brazos hacia los lados hasta la altura de los hombros.', 'Continúa el movimiento llevando los codos hacia las costillas y vuelve a estirar los brazos.', 'Realiza el recorrido lento y controlado, respirando de forma fluida.', 'Evita arquear en exceso la zona lumbar o levantar demasiado la cabeza.']::text[], 'intermedio', 'Moviliza la columna y activa la espalda alta, hombros posteriores y glúteos para mejorar la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10045'),
('b7a1067d-f80c-5a50-a5e8-f28b8a16b4ba', 'Ángel de nieve boca arriba', ARRAY['Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas estiradas.', 'Presiona la zona lumbar contra el suelo y desliza los brazos hacia los lados hasta la altura de los hombros.', 'Continúa bajando los brazos junto al cuerpo y vuelve a subirlos por el mismo camino.', 'Mantén las costillas abajo y respira de forma constante durante todo el recorrido.', 'Evita despegar la lumbar del suelo o encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera, mejorando el control del core y la movilidad de hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10046'),
('11bf18a2-4d81-594c-9d41-1de4b07dae15', 'Rotación de tronco con mancuerna', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta.', 'Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces.', 'Regresa a la posición inicial y repite del otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos con rotación controlada, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0777'),
('a76c5b7f-062c-5837-b2bf-62c8ecd4c56d', 'Postura de la esfinge', ARRAY['Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.', 'Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.', 'Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.', 'Baja lentamente el pecho de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Estira la columna y abre el pecho, aliviando la tensión lumbar y mejorando la extensión torácica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1362'),
('450238c8-5465-5e2d-8951-02479628922b', 'Flexión tipo araña', ARRAY['Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo.', 'Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos.', 'Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y core con apoyo de brazos, mejorando la estabilidad y la coordinación del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0778'),
('ff744e05-3ee1-53bf-8a0d-8508d3f23eef', 'Escalador araña', ARRAY['Colócate en posición de plancha alta con las manos bajo los hombros y el cuerpo alineado.', 'Lleva una rodilla hacia el codo del mismo lado sin mover la cadera.', 'Vuelve a la posición inicial y alterna con la otra pierna a un ritmo controlado.', 'Mantén el abdomen apretado y respira de forma constante.', 'Evita elevar la cadera o dejar caer la zona lumbar.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con ritmo, mejorando la resistencia del core y la coordinación.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7463'),
('860784d4-aa1b-5555-8c75-3c5c36cc4f71', 'Plancha araña', ARRAY['Colócate en plancha alta con los codos ligeramente flexionados y el cuerpo en línea recta.', 'Lleva una rodilla hacia el codo del mismo lado manteniendo la cadera estable.', 'Vuelve a la posición inicial y repite con la otra pierna de forma controlada.', 'Mantén el abdomen apretado y respira con normalidad durante el ejercicio.', 'Evita rotar la cadera o hundir la zona lumbar.']::text[], 'intermedio', 'Refuerza el abdomen y los oblicuos en isométrico, mejorando la estabilidad del core y los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6092'),
('4fecb271-0323-5bef-9ab1-8404dff0a2e5', 'Patada trasera giratoria', ARRAY['Colócate de espaldas al objetivo con las rodillas ligeramente flexionadas y el peso en el pie de apoyo.', 'Gira el tronco y la cadera para lanzar la pierna hacia atrás extendiéndola con fuerza.', 'Mantén la mirada en el objetivo y el core activado durante todo el giro.', 'Recoge la pierna con control y vuelve a la posición inicial sin perder el equilibrio.', 'Evita bloquear la rodilla de la pierna de apoyo al extender la patada.']::text[], 'intermedio', 'Trabaja glúteos, isquiotibiales y core con rotación explosiva, mejorando potencia y control en movimientos de combate.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2310'),
('31a23355-b949-572c-89c6-c196c1c6f0a9', 'Patada de gancho giratoria', ARRAY['Adopta una postura de guardia con las rodillas flexionadas y el peso sobre el pie de apoyo.', 'Gira el cuerpo y lleva la pierna en trayectoria circular con la rodilla extendida al final.', 'Activa el core y mantén la mirada en el objetivo durante el giro.', 'Recoge la pierna con control y recupera la guardia sin dar la espalda.', 'Evita inclinar demasiado el tronco, que te hará perder el equilibrio.']::text[], 'intermedio', 'Desarrolla glúteos, isquiotibiales y core mediante un giro explosivo que mejora la coordinación y la potencia de piernas.', ARRAY['Acondicionamiento Metabólico', 'Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 7.8, 'combat', '2306'),
('7d62ce80-ab70-520e-bb3c-a2f6c41d8d77', 'Estiramiento de columna en balón', ARRAY['Siéntate sobre el balón y rueda hacia atrás hasta apoyar la espalda y la cabeza.', 'Abre los brazos en cruz y deja que la columna se extienda sobre el balón.', 'Respira profundo y mantén la posición entre veinte y treinta segundos.', 'Vuelve despacio rodando hacia delante y apoyando los pies.', 'Evita forzar el cuello; la cabeza debe descansar relajada sobre el balón.']::text[], 'principiante', 'Estira la columna y abre dorsales y hombros, aliviando la tensión acumulada por el estudio y las horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4314'),
('22a80a9c-5dee-52f5-8598-bcc46336f361', 'Extensión lumbar', ARRAY['Túmbate boca abajo con las manos apoyadas a la altura de los hombros.', 'Empuja suavemente el suelo y eleva el pecho mientras la pelvis permanece apoyada.', 'Respira de forma pausada y mantén la extensión sin dolor unos segundos.', 'Baja despacio hasta la posición inicial y repite el movimiento.', 'Evita arquear el cuello hacia atrás; mantén la mirada al suelo.']::text[], 'principiante', 'Moviliza la zona lumbar y activa glúteos, útil para contrarrestar la rigidez de estar muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2785'),
('48a6c79c-be6e-5da8-8894-ee71550b3c4b', 'Flexión lumbar', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Lleva las rodillas hacia el pecho y redondea suavemente la zona lumbar.', 'Mantén la posición unos segundos respirando con calma.', 'Baja las piernas despacio hasta apoyar los pies en el suelo.', 'Evita tirar del cuello con las manos; deja que el abdomen haga el trabajo.']::text[], 'principiante', 'Trabaja el abdomen y la zona lumbar con un movimiento suave que mejora la movilidad y alivia la rigidez de la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2786'),
('00a9a405-8aa0-5123-8901-583fc5c658e2', 'Flexión lateral lumbar', ARRAY['De pie con los pies a la anchura de las caderas y los brazos relajados.', 'Inclina el tronco hacia un lado deslizando la mano por la pierna.', 'Mantén la cadera estable y respira mientras sientes el estiramiento.', 'Vuelve al centro con control y repite hacia el otro lado.', 'Evita girar el tronco; el movimiento debe ser solo lateral.']::text[], 'principiante', 'Moviliza la columna y activa oblicuos y zona lumbar, mejorando la flexibilidad lateral y la estabilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2787'),
('d752e087-7130-54da-80a1-4c8994e84675', 'Rotación lumbar', ARRAY['Siéntate o ponte de pie con la espalda recta y el core activado.', 'Gira el tronco hacia un lado manteniendo la pelvis estable.', 'Mantén la rotación unos segundos respirando con calma.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita forzar el rango; gira solo hasta donde sea cómodo.']::text[], 'principiante', 'Mejora la movilidad rotacional de la columna y activa oblicuos y core, útil para prevenir molestias lumbares.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2788'),
('1de90702-3321-5e70-96f2-7a1bae088ce0', 'Estiramiento de columna en arco', ARRAY['Túmbate boca abajo con las manos apoyadas bajo los hombros.', 'Empuja el suelo y eleva el pecho arqueando suavemente la espalda.', 'Mantén la pelvis en el suelo y respira de forma pausada.', 'Sostén el estiramiento unos segundos y baja despacio.', 'Evita comprimir la zona lumbar; sube solo hasta donde sea cómodo.']::text[], 'principiante', 'Estira la columna y abre flexores de cadera y core, mejorando la extensión y contrarrestando la postura encorvada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3517'),
('0f44d061-2e33-51b9-b71b-7f849549b94f', 'Estiramiento de columna hacia delante', ARRAY['Siéntate con las piernas extendidas y la espalda recta.', 'Inclina el tronco hacia delante desde la cadera sin redondear la espalda.', 'Lleva las manos hacia los pies hasta donde llegues con comodidad.', 'Respira profundo y mantén el estiramiento unos segundos.', 'Evita rebotar; busca un estiramiento sostenido y sin dolor.']::text[], 'intermedio', 'Estira la cadena posterior y la columna, aliviando la tensión de isquiotibiales y zona lumbar tras el estudio.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '4315'),
('2742ff18-7a10-5aee-823b-bdf33335c767', 'Giro de columna', ARRAY['Siéntate con la espalda recta y las piernas cruzadas o extendidas.', 'Gira el tronco hacia un lado llevando las manos en la dirección del giro.', 'Mantén la pelvis estable y respira durante la rotación.', 'Vuelve al centro con control y repite hacia el otro lado.', 'Evita tirar con los brazos; el giro nace del tronco.']::text[], 'intermedio', 'Activa oblicuos y core mediante una rotación controlada que mejora la movilidad y la estabilidad del tronco.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2868'),
('4bd90887-9d0c-5686-9ca6-b16eff121358', 'Split jacks', ARRAY['De pie con los pies juntos y los brazos a los lados.', 'Salta abriendo las piernas y llevando los brazos por encima de la cabeza.', 'Vuelve a la posición inicial con otro salto y mantén un ritmo constante.', 'Aterriza con las rodillas ligeramente flexionadas para amortiguar.', 'Evita bloquear las rodillas al caer para proteger las articulaciones.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y hombros con un ejercicio cardiovascular dinámico y de bajo material.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3113'),
('f892c107-c284-50be-92e4-1fafdf2272fd', 'Salto dividido al cajón', ARRAY['Colócate frente al cajón en posición de zancada con una pierna adelantada.', 'Impulsa con ambas piernas y salta cambiando la posición de las piernas.', 'Aterriza suavemente sobre el cajón con las rodillas flexionadas.', 'Baja con control y repite el salto alternando la pierna adelantada.', 'Evita aterrizar con las piernas rígidas; amortigua siempre la caída.']::text[], 'intermedio', 'Potencia cuádriceps y glúteos con un salto pliométrico que mejora la explosividad y la coordinación de piernas.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3440'),
('29822975-86f6-5cb9-8de6-803c12d36971', 'Zancada alta de sprinter', ARRAY['Coloca una pierna adelantada con la rodilla flexionada y la trasera extendida.', 'Eleva el tronco y mantén el core activado con la mirada al frente.', 'Baja la rodilla trasera hacia el suelo sin tocarlo y vuelve a subir.', 'Respira de forma constante y mantén el equilibrio durante el movimiento.', 'Evita que la rodilla delantera sobrepase en exceso la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos en posición de zancada alta, mejorando la estabilidad y la potencia de la pierna adelantada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3482'),
('b8f1f133-2d4b-5402-afe5-72fba9851b62', 'Zancada baja de sprinter', ARRAY['Adopta una zancada amplia con la rodilla delantera flexionada.', 'Desciende la cadera acercando la rodilla trasera al suelo.', 'Mantén el tronco erguido y el core activado durante el descenso.', 'Empuja con la pierna delantera para volver a subir con control.', 'Evita inclinar el tronco hacia delante para no cargar la lumbar.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos en una zancada baja que mejora la fuerza y la movilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3481'),
('a58fbd08-c42f-515a-a4db-3e58035188d6', 'Sentadilla dividida', ARRAY['Da un paso al frente y coloca los pies a la anchura de las caderas.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el core activado y respira durante todo el movimiento.', 'Evita que la rodilla delantera se vaya hacia dentro al bajar.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sentadilla unilateral que mejora el equilibrio y la fuerza de cada pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0781'),
('a7e438c8-7fc1-5641-a373-56298df62a3a', 'Sentadilla dividida con elevación de talón', ARRAY['Coloca un pie delante y otro detrás, con el torso erguido y el core activado.', 'Baja flexionando la rodilla delantera hasta que el muslo quede casi paralelo al suelo.', 'Al subir, eleva el talón del pie delantero apoyándote en la punta y mantén un segundo arriba.', 'Baja el talón con control y repite sin perder la verticalidad del torso.', 'Evita que la rodilla delantera se vaya hacia dentro y no dejes caer el peso en el pie trasero.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras trabaja la pantorrilla y el sóleo, mejorando el equilibrio y la estabilidad del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8755'),
('3b435e66-1838-5138-8c1b-e4d5faf208cd', 'Sentadilla dividida con rodada', ARRAY['Adopta una posición de zancada con un pie delante y otro detrás, torso erguido.', 'Baja flexionando la rodilla delantera mientras llevas las manos hacia delante en una rodada controlada.', 'Mantén el core firme y la espalda neutra durante todo el descenso.', 'Empuja con el pie delantero para volver arriba y recoge las manos al pecho.', 'Evita redondear la espalda o perder el equilibrio por bajar demasiado rápido.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y core con un movimiento de rodada que añade control y estabilidad al tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3716'),
('bc82991b-7897-5bf9-bf2c-a96c8e17c05d', 'Sentadilla búlgara', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie.', 'Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta.', 'Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo.', 'Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.', 'Repite el número de repeticiones deseado y luego cambia de pierna y repite.']::text[], 'intermedio', 'Ejercicio unilateral que fortalece cuádriceps y glúteos, mejora el equilibrio y corrige descompensaciones entre piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2368'),
('daaf43d0-eca8-5d97-8e02-17b9ea83dce3', 'Elevación de gemelos a una pierna con piernas divididas', ARRAY['Coloca un pie delante y otro detrás, con el peso sobre la punta del pie delantero.', 'Eleva el talón delantero lo máximo posible manteniendo el equilibrio.', 'Aprieta la pantorrilla arriba durante un segundo y baja el talón con control.', 'Mantén el torso erguido y evita balancearte hacia los lados.', 'No rebotes en la parte baja para proteger el tendón de Aquiles.']::text[], 'intermedio', 'Aísla la pantorrilla y el sóleo en una sola pierna, mejorando la fuerza y estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10819'),
('cb684793-56a9-58b8-bc46-a2b71a0bd227', 'Estiramiento en split con rodado de columna', ARRAY['Siéntate con las piernas abiertas en split, una delante y otra detrás, con la espalda larga.', 'Inclínate suavemente hacia la pierna delantera hasta notar el estiramiento.', 'Rueda la columna vértebra a vértebra mientras respiras profundo.', 'Mantén el estiramiento sin forzar y cambia de lado.', 'Evita rebotar o redondear la espalda de golpe para no comprimir la zona lumbar.']::text[], 'principiante', 'Estira isquiotibiales y aductores mientras moviliza la columna, aliviando tensión en la espalda y la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11089'),
('4a5392b7-d7d4-5d80-8f99-c329c4a03e94', 'Flexión adelante con piernas abiertas (upavista konasana)', ARRAY['Siéntate con las piernas bien abiertas y la espalda erguida.', 'Inclínate hacia delante desde la cadera manteniendo la espalda larga.', 'Apoya las manos en el suelo o en las piernas y respira profundamente.', 'Mantén la posición sin rebotar y relaja los hombros.', 'Evita redondear la espalda o forzar la apertura de piernas más allá de tu rango.']::text[], 'principiante', 'Estira aductores e isquiotibiales y libera la zona lumbar, mejorando la flexibilidad de la cadera y la espalda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0958'),
('772cd37b-e9a3-5da1-bc0e-c9cbe368c197', 'Sprint', ARRAY['Colócate en posición de salida con el torso ligeramente inclinado y los brazos preparados.', 'Empuja con fuerza y acelera progresivamente durante los primeros metros.', 'Corre con zancada amplia, apoyando el pie bajo la cadera y brazos a 90 grados.', 'Respira de forma rítmica y mantén la mirada al frente.', 'Evita cruzar los brazos o aterrizar con el talón por delante para prevenir lesiones.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la potencia del tren inferior, activando glúteos, isquiotibiales y pantorrillas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '5216'),
('e4398ed8-2035-523a-933c-b52255789239', 'Sprint contra la pared', ARRAY['Apoya las manos en la pared e inclina el cuerpo hacia delante.', 'Eleva una rodilla a la altura de la cadera y alterna con la otra como si corrieras.', 'Mantén el core activo y la espalda recta durante todo el movimiento.', 'Aumenta la velocidad de las rodillas sin perder la postura.', 'Evita arquear la espalda o levantar los talones del suelo.']::text[], 'intermedio', 'Trabaja la potencia cardiovascular y los flexores de cadera con un sprint isométrico que mejora la técnica de carrera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '9040'),
('896a2e97-e97b-57a1-b496-2f028fb6ec3e', 'Abdominal de velocista', ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas flexionadas.', 'Lleva las manos a la nuca sin tirar del cuello.', 'Eleva el torso y acerca el codo a la rodilla contraria en un movimiento de tijera.', 'Alterna los lados manteniendo el core apretado y respirando de forma controlada.', 'Evita tirar del cuello o balancearte para no forzar la zona lumbar.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos con un movimiento dinámico que también activa los flexores de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3865'),
('a4269ea4-9d2b-5cd8-907c-d0648e555b55', 'Salto cuadrado', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta hacia delante, atrás y a los lados formando un cuadrado imaginario.', 'Aterriza suavemente con las rodillas flexionadas y el core activo.', 'Mantén un ritmo constante y respira de forma rítmica.', 'Evita aterrizar con las piernas rígidas para reducir el impacto en las articulaciones.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la potencia de piernas con saltos que activan pantorrillas, cuádriceps y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '0782'),
('33ef6f11-9481-59de-859d-0b0cf856c4db', 'Sentadilla', ARRAY['Separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja flexionando rodillas y caderas como si te sentaras en una silla.', 'Mantén el pecho erguido y la espalda neutra durante todo el descenso.', 'Empuja con los talones para volver arriba y aprieta los glúteos al final.', 'Evita que las rodillas se vayan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Ejercicio básico que fortalece cuádriceps, glúteos e isquiotibiales, mejorando la fuerza y estabilidad del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1197'),
('786c6b2c-3e10-52f3-b282-2e6f883e88e2', 'Sentadilla, espalda (control de técnica)', ARRAY['Coloca la barra sobre los trapecios y agarra con las manos a los lados.', 'Separa los pies a la anchura de los hombros y activa el core.', 'Baja flexionando rodillas y caderas manteniendo el pecho erguido y la espalda neutra.', 'Empuja con los talones para subir y bloquea las caderas al final.', 'Evita redondear la espalda o dejar que las rodillas se vayan hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y espalda baja con barra, incidiendo en la técnica y el control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2362'),
('c15b7064-6b43-587d-923e-3998421d4ae3', 'Elevación de gemelos en sentadilla mantenida', ARRAY['Baja a una sentadilla y mantén la posición con los muslos paralelos al suelo.', 'Eleva los talones lo máximo posible apoyándote en las puntas.', 'Aprieta la pantorrilla arriba un segundo y baja con control.', 'Mantén el torso erguido y el core activo durante todo el ejercicio.', 'Evita perder la posición de sentadilla o rebotar en los talones.']::text[], 'intermedio', 'Trabaja pantorrillas y sóleo en isométrico mientras mantiene cuádriceps y glúteos activos en sentadilla.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4160'),
('83e2ab67-9073-5734-b631-991cc2d54e63', 'Squat jack', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta abriendo las piernas y bajando a una sentadilla.', 'Salta de nuevo para cerrar las piernas y volver a la posición inicial.', 'Mantén el core activo y aterriza suavemente con las rodillas flexionadas.', 'Evita aterrizar con las piernas rígidas o perder la alineación de rodillas.']::text[], 'intermedio', 'Ejercicio pliométrico que combina sentadilla y salto, mejorando la potencia de piernas y la capacidad cardiovascular.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '7556');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('11b94acb-36ce-5a27-9014-7b448fe91e82', 'Sentadilla jacks', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta abriendo las piernas y bajando a una sentadilla.', 'Salta de nuevo para cerrar las piernas y volver a la posición inicial.', 'Mantén un ritmo constante y respira de forma rítmica.', 'Evita aterrizar con las piernas rígidas para reducir el impacto en las rodillas.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la potencia del tren inferior con saltos que activan cuádriceps, glúteos y pantorrillas.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0785'),
('9f7e55e8-5c3d-53ac-a489-83c94e8ae959', 'Envión en sentadilla', ARRAY['Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros.', 'Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies.', 'Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza.', 'Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás.', 'Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo.', 'Ponte de pie desde la posición dividida, juntando de nuevo los pies.', 'Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado.']::text[], 'avanzado', 'Movimiento de halterofilia que desarrolla potencia en piernas y core al recibir la barra en sentadilla tras un envión explosivo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '0786'),
('8beee719-e5a4-5e5a-af60-05b87633cd70', 'Sentadilla con rodillas en posición media', ARRAY['Coloca la barra sobre los trapecios y separa los pies a la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Desciende controlando la cadera hacia atrás y abajo mientras las rodillas siguen la línea de los pies.', 'Mantén las rodillas en posición media, sin colapsar hacia dentro, y el pecho alto durante todo el descenso.', 'Empuja con los talones para subir exhalando y evita bloquear las rodillas de golpe al final.']::text[], 'intermedio', 'Variante de control técnico que refuerza cuádriceps, glúteos y aductores manteniendo las rodillas alineadas durante todo el recorrido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2360'),
('0173a1bb-5bc7-54b0-b20d-4e69d07b8c12', 'Movilidad de sentadilla', ARRAY['Separa los pies a la anchura de los hombros y baja en sentadilla tan profundo como puedas sin dolor.', 'Sujeta los pies o los tobillos y empuja suavemente las rodillas hacia fuera con los codos.', 'Mantén la espalda recta y respira profundo mientras aguantas la posición entre veinte y treinta segundos.', 'Evita levantar los talones del suelo; si ocurre, reduce la profundidad o separa más los pies.']::text[], 'principiante', 'Prepara caderas, tobillos y aductores para sentadillas más profundas y seguras mejorando la movilidad articular sin carga.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2988'),
('b1ccdabc-da95-5ca3-a90e-22a30f0955d7', 'Giro de movilidad en sentadilla', ARRAY['Baja en sentadilla profunda con los pies algo separados y los talones apoyados.', 'Coloca una mano en la nuca y lleva el codo hacia la rodilla contraria girando el tronco.', 'Abre el pecho y mira hacia arriba al girar, respirando de forma lenta y controlada.', 'Alterna el giro hacia cada lado sin perder la posición de la cadera ni forzar la zona lumbar.']::text[], 'principiante', 'Moviliza la columna y las caderas girando el tronco desde una sentadilla profunda para mejorar la rotación torácica y la apertura de cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6139'),
('ffd71b1c-87e3-5db3-9dce-f104cc263fd5', 'Movilización de sentadilla', ARRAY['Colócate con los pies a la anchura de los hombros y las puntas ligeramente hacia fuera.', 'Baja despacio hasta donde puedas manteniendo los talones en el suelo y la espalda recta.', 'Aguanta abajo unos segundos y empuja las rodillas hacia fuera con los codos.', 'Sube controlando el movimiento y evita levantar los talones o redondear la espalda.']::text[], 'principiante', 'Mejora la movilidad de cadera, tobillos y columna, preparando el cuerpo para sentadillas profundas y reduciendo tensión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10551'),
('c0775b2c-b8ab-535b-bfc1-ad0e48f6db9d', 'Sentadilla con patada lateral', ARRAY['Separa los pies a la anchura de los hombros y baja en sentadilla con el pecho alto.', 'Al subir, extiende una pierna hacia el lado sin inclinar el tronco.', 'Vuelve al centro y repite con la otra pierna alternando.', 'Mantén el abdomen activo y evita perder el equilibrio o bloquear la rodilla de apoyo.']::text[], 'intermedio', 'Fortalece glúteos y piernas mientras trabajas el core y la estabilidad al extender la pierna de forma controlada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1400'),
('06bd4f60-c8d6-5d66-916e-f93e2606c5f5', 'Burpee sin flexión', ARRAY['Desde de pie, baja en sentadilla y apoya las manos en el suelo.', 'Lleva los pies atrás hasta la posición de plancha manteniendo el cuerpo alineado.', 'Recoge los pies hacia las manos y sube con un pequeño salto.', 'Respira de forma constante y evita hundir la cadera en la fase de plancha.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y trabaja piernas y core en un ejercicio cardiovascular intenso y funcional.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3705'),
('dabe5a54-09aa-578b-9ddc-842421551d55', 'Sentadilla en puntas de pie', ARRAY['Colócate de pie y elévate sobre las puntas de los pies.', 'Baja en sentadilla manteniendo los talones elevados y el tronco erguido.', 'Sube empujando con las puntas y controla el descenso.', 'Evita inclinarte hacia delante o perder el equilibrio; apóyate en una pared si lo necesitas.']::text[], 'intermedio', 'Trabaja cuádriceps y gemelos, mejorando el equilibrio y la fuerza en el tren inferior con apoyo en el antepié.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3927'),
('fddcf419-fb48-573a-95ec-22eebb5f06ab', 'Sentadilla con alcance sobre la cabeza', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo.', 'Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Combina fuerza de piernas con movilidad de hombros y control del core en un patrón global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1685'),
('359fa059-8b50-5297-93a7-96b94f93eaf5', 'Sentadilla con alcance sobre la cabeza y giro', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.', 'Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado.', 'Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto.', 'Continúa alternando los lados en cada repetición de la sentadilla.']::text[], 'intermedio', 'Añade rotación al patrón de sentadilla, mejorando movilidad torácica, coordinación y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1686'),
('93b4b6f1-feca-5c19-8cb8-3b76322eb65c', 'Sentadilla con salto y rodillas al pecho', ARRAY['Baja en sentadilla con los brazos atrás para coger impulso.', 'Salta con fuerza y lleva las rodillas hacia el pecho en el aire.', 'Aterriza con las rodillas ligeramente flexionadas y el pecho alto.', 'Amortigua el impacto y evita aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia piernas y core, mejorando la explosividad y la capacidad cardiovascular.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3706'),
('388bd1aa-af61-533c-97ed-8eb8e398e63c', 'Sentadilla con control de rodillas', ARRAY['Colócate con los pies a la anchura de los hombros y mirada al frente.', 'Baja empujando las rodillas en la misma dirección que las puntas de los pies.', 'Mantén los talones apoyados y el pecho alto durante todo el recorrido.', 'Evita que las rodillas se metan hacia dentro al subir.']::text[], 'intermedio', 'Enseña a alinear las rodillas durante la sentadilla, protegiendo articulaciones y mejorando la técnica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3001'),
('5a79a6ea-01d1-5dc9-9f23-701477f7db0d', 'Serrucho en balón de estabilidad', ARRAY['Apoya los antebrazos en el balón y extiende las piernas en plancha.', 'Mantén el cuerpo alineado y el abdomen activo.', 'Desplaza el balón hacia delante y hacia atrás con los antebrazos sin mover la cadera.', 'Evita arquear la zona lumbar o dejar caer la cadera.']::text[], 'principiante', 'Trabajo isométrico de abdomen y core que también exige estabilidad de hombros y control lumbar.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3861'),
('f4d0f68c-c5e5-5daa-8aa5-e078d0c34d5d', 'Abdominal en balón de estabilidad', ARRAY['Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Fortalece el recto abdominal con mayor rango de movimiento gracias a la superficie inestable del balón.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2297'),
('63d36cdc-c6a3-5be5-a152-df2753c3775c', 'Plancha frontal en balón de estabilidad', ARRAY['Apoya los antebrazos sobre el balón y extiende las piernas atrás.', 'Alinea cabeza, cadera y talones manteniendo el abdomen activo.', 'Aguanta la posición respirando de forma constante.', 'Evita hundir la cadera o elevar demasiado el glúteo.']::text[], 'principiante', 'Refuerza el core y los hombros en isométrico, mejorando la estabilidad y la postura gracias a la inestabilidad del balón.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1706'),
('98dcdb90-917d-511c-bb12-e1e2a622bd79', 'Hiperextensión inversa con balón de estabilidad', ARRAY['Túmbate boca abajo sobre el balón con el abdomen apoyado y sujétate al suelo con las manos.', 'Eleva las piernas juntas hasta alinear el cuerpo, apretando los glúteos arriba.', 'Baja las piernas con control sin arquear en exceso la zona lumbar.', 'Evita impulsarte con la espalda; el movimiento nace de la cadera.']::text[], 'principiante', 'Fortalece glúteos, isquiotibiales y zona lumbar, mejorando la extensión de cadera y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3178'),
('a27b69e3-79a8-5a3e-952b-009331e5c27d', 'Rodillo en balón de estabilidad', ARRAY['Colócate de rodillas con las manos sobre el balón y el core activo.', 'Rueda el balón hacia delante mientras estiras el cuerpo sin hundir la lumbar.', 'Vuelve tirando del abdomen y llevando el balón hacia las rodillas.', 'Mantén la espalda neutra y evita que la cadera se hunda.']::text[], 'principiante', 'Trabaja el abdomen y el core completo, ganando control y estabilidad en la extensión del cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2296'),
('7ef86132-9d7b-5cea-b568-5b41e8038d11', 'Rodillo abdominal de rodillas con balón', ARRAY['Arrodíllate frente al balón y apoya las manos sobre él con los brazos extendidos.', 'Rueda el balón hacia delante controlando la bajada de la cadera.', 'Vuelve a la posición inicial contrayendo el abdomen.', 'No dejes caer la cadera ni arquees la espalda en el recorrido.']::text[], 'principiante', 'Refuerza el abdomen y la zona lumbar, mejorando la estabilidad del core y la fuerza anti-extensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7019'),
('e09a2c15-ee4b-5280-948b-25d8bc59b38a', 'Rollout redondeado con balón de estabilidad', ARRAY['Apoya los antebrazos o las manos en el balón con las rodillas en el suelo.', 'Redondea la espalda y rueda el balón hacia delante lentamente.', 'Vuelve recogiendo el abdomen y redondeando aún más la columna.', 'Evita extender la lumbar; mantén la curvatura durante todo el recorrido.']::text[], 'principiante', 'Activa el abdomen y el core con una versión curvada que protege la lumbar y mejora el control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2937'),
('dbff6ef5-2ef7-5b7c-92d0-2c2eb37a6b0d', 'Sentadilla a una pierna en balón de estabilidad', ARRAY['Apoya un pie sobre el balón y el otro en el suelo, con el core activo.', 'Baja flexionando la rodilla de apoyo mientras controlas el balón.', 'Empuja para subir manteniendo la rodilla alineada con el pie.', 'Evita que el balón ruede sin control; baja despacio y con equilibrio.']::text[], 'principiante', 'Fortalece cuádriceps y glúteos con apoyo inestable, mejorando el equilibrio y la estabilidad de rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1695'),
('680465eb-3a71-54a3-a7d2-bd39be9e4c68', 'Puente de glúteos con piernas escalonadas', ARRAY['Túmbate boca arriba con una pierna flexionada y la otra algo más adelantada.', 'Eleva la cadera apretando el glúteo hasta alinear el cuerpo.', 'Baja con control sin apoyar del todo y repite.', 'Evita arquear la lumbar; el empuje sale del glúteo.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales de forma unilateral, mejorando la fuerza y la estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7418'),
('f5c9e7fd-ec0b-5c4b-944c-7cd172b04e0d', 'Puente lateral con piernas escalonadas', ARRAY['Colócate de lado apoyando el antebrazo y con una pierna adelantada.', 'Eleva la cadera formando una línea recta desde el hombro hasta el pie.', 'Mantén la posición respirando con normalidad.', 'Evita que la cadera caiga o que el hombro se hunda.']::text[], 'intermedio', 'Trabaja oblicuos y core lateral con una variante escalonada que exige más estabilidad y control.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4894'),
('f206a97d-0c71-5c4c-92bd-62407acd28c8', 'Salto de escalón', ARRAY['Colócate frente a un escalón con los pies a la anchura de las caderas.', 'Flexiona las rodillas y salta hacia arriba aterrizando suave sobre el escalón.', 'Baja con control y repite el gesto.', 'Aterriza con las rodillas alineadas y evita caer con las piernas rígidas.']::text[], 'intermedio', 'Desarrolla potencia de piernas y explosividad en cuádriceps y glúteos, mejorando el salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3720'),
('c9afe985-e503-544c-bb43-cfc4af254445', 'Subir escaleras', ARRAY['Colócate al pie de la escalera con la espalda recta y la mirada al frente.', 'Sube apoyando el pie completo en cada escalón.', 'Impulsa con la pierna de abajo sin inclinarte hacia delante.', 'Mantén un ritmo constante y respira de forma regular.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y la fuerza de piernas con un gesto funcional y accesible.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3009'),
('bf98c905-1262-503e-912d-8d3ba80c2445', 'Stalder press', ARRAY['Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza.', 'Flexiona ligeramente las rodillas y activa el core.', 'Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza.', 'Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps.', 'Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio avanzado de calistenia que fortalece tríceps, hombros y core con control y fuerza.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3291'),
('b2ba3028-0ecf-535f-827f-979de5e30545', 'Elevación de piernas en espaldera', ARRAY['Cuélgate de la espaldera con los brazos extendidos y el cuerpo estable.', 'Eleva las piernas juntas hasta la altura que controles.', 'Baja despacio sin balancearte.', 'Evita impulsarte con el balanceo; controla la bajada con el abdomen.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejorando el control del core colgado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11878'),
('8fcf0f0a-ae6f-57d5-9f10-3df276ad9e15', 'Flexión adelante de pie con piernas abiertas', ARRAY['De pie, abre las piernas más allá de la anchura de las caderas.', 'Inclínate hacia delante con la espalda recta y baja las manos.', 'Mantén el estiramiento respirando despacio sin rebotar.', 'Evita curvar la espalda; flexiona desde la cadera.']::text[], 'principiante', 'Estira aductores e isquiotibiales, mejorando la movilidad de la cadera y la flexibilidad posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0960'),
('f019494f-ee45-5187-a319-dcdab4bbb510', 'Giro abdominal de pie', ARRAY['De pie, con los pies a la anchura de las caderas y el core activo.', 'Gira el tronco hacia un lado y luego hacia el otro con control.', 'Acompaña el movimiento con los brazos relajados.', 'Evita girar solo con los brazos; la rotación nace del tronco.']::text[], 'principiante', 'Moviliza la columna y activa oblicuos, mejorando la rotación del tronco y la movilidad torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5126'),
('3cb91a1a-1af7-59c3-b193-8efca08a8a67', 'Estiramiento de rotación abdominal de pie', ARRAY['De pie, cruza un brazo por delante y gira el tronco suavemente.', 'Mantén el estiramiento sin forzar y respira despacio.', 'Cambia de lado de forma controlada.', 'Evita rebotar o girar en exceso; busca una tensión cómoda.']::text[], 'principiante', 'Estira oblicuos y core mediante rotación, aliviando tensión y mejorando la movilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2110'),
('cad4e3aa-915c-59a4-b854-6447e29ec9d0', 'Estiramiento de aquiles de pie', ARRAY['Apoya las manos en una pared y lleva un pie atrás con la rodilla estirada.', 'Empuja el talón hacia el suelo manteniendo el pie trasero recto.', 'Mantén el estiramiento respirando despacio.', 'Evita levantar el talón o girar el pie hacia fuera.']::text[], 'principiante', 'Estira el tendón de Aquiles y el sóleo, mejorando la flexibilidad del tobillo y previniendo molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1888'),
('7b992c5e-f7ab-5e78-a428-6535e79d3ed9', 'Círculos alternados con los brazos de pie', ARRAY['Colócate de pie con los pies a la anchura de las caderas y los brazos extendidos a los lados.', 'Dibuja círculos amplios con un brazo hacia delante mientras el otro descansa.', 'Cambia de brazo y alterna el sentido del giro cada pocas repeticiones.', 'Mantén el tronco estable y evita encoger los hombros hacia las orejas.', 'Respira de forma pausada y controla la velocidad en todo el recorrido.']::text[], 'principiante', 'Moviliza los hombros y la cintura escapular, preparando la articulación antes de entrenar y mejorando el rango de movimiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3259'),
('76c1b945-2c37-51cd-986d-7dc260b353da', 'Flexión alterna de hombro de pie con cuerda', ARRAY['Sujeta la cuerda por los extremos con las manos a la altura de la cintura.', 'Eleva un brazo hacia delante hasta la altura del hombro sin bloquear el codo.', 'Baja despacio y repite con el otro brazo de forma alterna.', 'Mantén el abdomen firme y evita arquear la zona lumbar.', 'Respira al subir el brazo y controla el descenso.']::text[], 'principiante', 'Trabaja la movilidad del hombro y la coordinación del tren superior, activando además el core y los antebrazos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9185'),
('123cdc0f-723b-50cb-a603-aee5c818db51', 'Ejercicio de tobillo y cadera de pie', ARRAY['De pie con los pies juntos, apóyate ligeramente en una pared si necesitas equilibrio.', 'Eleva una rodilla hacia delante mientras flexionas el tobillo del pie de apoyo.', 'Lleva la rodilla hacia fuera y vuelve al centro con control.', 'Alterna las piernas manteniendo el tronco erguido y sin balancearte.', 'Respira con normalidad y evita hacer el movimiento con prisa.']::text[], 'principiante', 'Activa tobillos, cadera y glúteos para mejorar la estabilidad y la movilidad del tren inferior antes de la actividad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '11289'),
('15067ebe-715f-5a24-bce3-b19a9f9d0864', 'Círculos de tobillo de pie', ARRAY['Apoya el peso en una pierna y eleva ligeramente el pie contrario del suelo.', 'Dibuja círculos amplios con la punta del pie en un sentido.', 'Cambia de sentido tras varias repeticiones y luego cambia de pierna.', 'Mantén el equilibrio con el tronco erguido y sin mover la cadera.', 'Respira de forma relajada y evita forzar el rango del tobillo.']::text[], 'principiante', 'Moviliza la articulación del tobillo y activa gemelos y tibiales, reduciendo el riesgo de esguinces en la práctica deportiva.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '8188'),
('1dacc44e-b0ae-5e7b-9ae7-207b5159dd46', 'Arquero de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo.', 'Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta.', 'Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco.', 'Mantén la posición por un momento y luego vuelve a la posición inicial.', 'Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'avanzado', 'Fortalece la espalda alta y los hombros mientras mejora la movilidad escapular y la coordinación del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3669'),
('b7919306-d03a-5d1e-bb53-d4a49c5f9a06', 'Círculos con los brazos de pie', ARRAY['Colócate de pie con los pies a la anchura de los hombros y los brazos extendidos.', 'Dibuja círculos amplios con ambos brazos a la vez hacia delante.', 'Cambia el sentido del giro tras varias repeticiones.', 'Mantén el abdomen firme y evita arquear la espalda.', 'Respira con normalidad y aumenta poco a poco el tamaño del círculo.']::text[], 'principiante', 'Calienta los hombros y la cintura escapular, mejorando la movilidad articular y la circulación antes del entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3258'),
('9680e501-be8a-5651-be48-5c63e52201cb', 'Lanzamiento de brazos de pie', ARRAY['De pie con los pies a la anchura de las caderas y los brazos relajados.', 'Lanza los brazos hacia delante y arriba de forma enérgica pero controlada.', 'Abre el pecho al subir y vuelve a la posición inicial con suavidad.', 'Evita arquear en exceso la zona lumbar durante el lanzamiento.', 'Respira al abrir el pecho y relaja los hombros al bajar.']::text[], 'principiante', 'Moviliza hombros y pecho con un gesto dinámico que activa la espalda alta y prepara el tren superior para el esfuerzo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3260'),
('2d3a993f-f4b1-5ec3-91a1-2f293c629309', 'Estiramiento de talón de Aquiles de pie hacia atrás', ARRAY['Apoya las manos en una pared y coloca un pie detrás del otro.', 'Mantén la pierna trasera extendida con el talón pegado al suelo.', 'Inclina el cuerpo hacia delante hasta notar el estiramiento en el gemelo.', 'Mantén la posición sin rebotar y respira de forma pausada.', 'Evita levantar el talón o girar la punta del pie hacia fuera.']::text[], 'principiante', 'Estira el tendón de Aquiles y el sóleo, mejorando la flexibilidad del tobillo y previniendo molestias en la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10922'),
('d5cd441c-7e22-5acd-b896-d3a67e0ea849', 'Extensión y flexión de espalda de pie', ARRAY['De pie con los pies a la anchura de las caderas y las manos en la cintura.', 'Arquea suavemente la espalda hacia atrás sin forzar el cuello.', 'Vuelve al centro y flexiona el tronco hacia delante con control.', 'Realiza el movimiento lento y evita rebotes bruscos.', 'Respira al flexionar y mantén el abdomen activo.']::text[], 'principiante', 'Moviliza la columna y activa la zona lumbar, el core y los glúteos, mejorando la flexibilidad y la conciencia postural.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3855'),
('7aba9944-5f26-58fd-91b9-997a09150799', 'Estiramiento de rotación de espalda de pie', ARRAY['De pie con los pies a la anchura de las caderas y los brazos relajados.', 'Gira el tronco hacia un lado manteniendo las caderas al frente.', 'Mantén el estiramiento unos segundos sin forzar el rango.', 'Vuelve al centro y repite hacia el otro lado.', 'Respira profundamente y evita girar también las rodillas.']::text[], 'principiante', 'Estira la columna y los oblicuos, liberando tensión en la espalda y mejorando la rotación torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1813'),
('ff4b7c86-baef-5ef0-be71-131e98987b90', 'Rotación de cadera en equilibrio de pie', ARRAY['Apóyate en una pared y levanta una rodilla hasta la altura de la cadera.', 'Dibuja círculos con la rodilla hacia fuera manteniendo el equilibrio.', 'Cambia de sentido y luego cambia de pierna.', 'Mantén el tronco erguido y evita inclinarte hacia los lados.', 'Respira con normalidad y controla la velocidad del círculo.']::text[], 'principiante', 'Mejora la movilidad de la cadera y el equilibrio, activando glúteos, core y tobillos de forma controlada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6750'),
('1e0e66a8-d4a1-54eb-a37d-e1c887639702', 'Estiramiento de cadera externa en equilibrio de pie', ARRAY['De pie, apóyate en una pared y cruza un tobillo por delante del otro.', 'Lleva la rodilla cruzada hacia el lado contrario con suavidad.', 'Mantén el estiramiento sin rebotar y con el tronco erguido.', 'Cambia de lado tras unos segundos.', 'Evita girar la cadera y respira de forma pausada.']::text[], 'principiante', 'Estira los abductores y glúteos, mejorando la movilidad lateral de la cadera y la estabilidad sobre un pie.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3473'),
('ede41d26-6bc4-5055-a75f-95395cdd5438', 'Press de pie por detrás de la nuca', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono.', 'Mantén la espalda recta y el core activado.', 'Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos.', 'Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los hombros y los tríceps con una variante de press que también implica la espalda alta y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0788'),
('6e05fa6c-d81f-5bb9-9a31-6ebc0218b2d8', 'Toque alterno de pies con inclinación de pie', ARRAY['De pie con los pies a la anchura de los hombros y los brazos extendidos.', 'Inclina el tronco hacia delante y toca el pie contrario con una mano.', 'Vuelve al centro y repite hacia el otro lado de forma alterna.', 'Flexiona las rodillas ligeramente y evita redondear en exceso la espalda.', 'Respira al bajar y controla el ritmo sin rebotes.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con un gesto dinámico que también implica isquiotibiales y zona lumbar.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10188'),
('9f422f0d-bc7f-5d73-a7e4-1c5db1ba5c36', 'Elevación de gemelos alternada de pie con rodilla flexionada y apoyo en silla', ARRAY['Apóyate en el respaldo de una silla y flexiona ligeramente las rodillas.', 'Eleva un talón hasta ponerte de puntillas sobre ese pie.', 'Baja despacio y repite con la otra pierna de forma alterna.', 'Mantén las rodillas flexionadas y el tronco erguido durante todo el movimiento.', 'Evita rebotar en la bajada y respira al subir.']::text[], 'intermedio', 'Fortalece gemelos y sóleo con una variante de rodilla flexionada que mejora la estabilidad del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9411'),
('6a6be373-349e-5ee0-a64d-8068a3f3f317', 'Elevación de gemelos de pie con rodilla flexionada y apoyo en silla', ARRAY['Colócate de pie detrás de una silla y apoya las manos en el respaldo para mantener el equilibrio.', 'Flexiona ligeramente las rodillas y mantén esa posición durante todo el movimiento.', 'Eleva los talones hasta ponerte de puntillas y aguanta un segundo arriba.', 'Baja los talones despacio controlando el descenso y sin dejarlos caer de golpe.', 'Evita arquear la espalda o bloquear las rodillas mientras subes.']::text[], 'intermedio', 'Fortalece el sóleo y la zona baja de la pierna, clave para la estabilidad del tobillo y la resistencia al caminar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9409'),
('6b1662fa-ed0b-5687-88c5-2722b4ba05e2', 'Ocho con rodilla flexionada de pie', ARRAY['Ponte de pie con los pies a la anchura de las caderas y el abdomen firme.', 'Eleva una rodilla a la altura de la cadera y empieza a dibujar un ocho con ella.', 'Mantén el tronco estable y realiza el recorrido de forma lenta y controlada.', 'Cambia de sentido y luego repite con la otra pierna.', 'Evita balancear la espalda o perder el equilibrio por ir demasiado rápido.']::text[], 'principiante', 'Moviliza la cadera y activa glúteos y core dibujando círculos amplios con la rodilla elevada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4944'),
('e2cf38ed-0cf9-5e00-b49d-21547b1bbd34', 'Estiramiento de aductores de pie con rodilla flexionada', ARRAY['Separa los pies y flexiona una rodilla mientras estiras la otra pierna hacia el lado.', 'Inclina el tronco hacia la pierna estirada manteniendo la espalda recta.', 'Nota el estiramiento en la cara interna del muslo y respira de forma profunda.', 'Mantén la posición sin rebotar y cambia de lado.', 'Evita forzar hacia delante con la espalda curvada.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, mejorando la movilidad de la cadera antes o después del entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1900'),
('2fc41d41-2cac-5218-8a43-246daaabe770', 'Círculo con elevación de gemelos de pie', ARRAY['Ponte de pie con los pies juntos y el cuerpo erguido.', 'Eleva los talones y, ya de puntillas, dibuja pequeños círculos con los tobillos.', 'Realiza el movimiento despacio sin bajar los talones durante el recorrido.', 'Cambia el sentido del círculo y repite.', 'Evita perder el equilibrio por moverte demasiado rápido.']::text[], 'intermedio', 'Combina fuerza de gemelos con movilidad de tobillo, mejorando el control y la estabilidad del pie.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4895'),
('19e702e8-3f14-55de-9829-5741dd8883d5', 'Estiramiento de gemelos de pie', ARRAY['Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo.', 'Coloca las manos sobre la pared o el objeto a la altura de los hombros.', 'Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo.', 'Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta.', 'Deberías sentir un estiramiento en el músculo de la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Repite con la otra pierna.']::text[], 'principiante', 'Alarga la musculatura del gemelo y la parte posterior de la pierna, aliviando la tensión tras caminar o correr.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1398'),
('78bf6a90-80e2-5fee-9819-4ecd04c63e91', 'Estiramiento de pecho de pie en espaldera', ARRAY['Colócate de espaldas a la espaldera y agarra un peldaño con una mano a la altura del hombro.', 'Da un paso adelante y gira ligeramente el tronco hacia el lado contrario.', 'Nota cómo se abre el pecho y mantén la respiración tranquila.', 'Sostén el estiramiento sin rebotar y cambia de lado.', 'Evita encoger el hombro o forzar el cuello.']::text[], 'principiante', 'Abre el pecho y los hombros, compensando posturas encorvadas y mejorando la movilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1783'),
('91ef239a-a116-5a25-82e9-00a9f572e1e0', 'Estiramiento de pecho de pie contra la puerta', ARRAY['Apoya el antebrazo en el marco de la puerta con el codo a la altura del hombro.', 'Gira el tronco suavemente hacia el lado contrario hasta notar la apertura del pecho.', 'Mantén la posición respirando de forma pausada.', 'Suelta despacio y repite con el otro brazo.', 'Evita adelantar el hombro o forzar el cuello.']::text[], 'principiante', 'Estira pectorales y hombros usando el marco de la puerta, ideal para contrarrestar horas de estudio sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5557'),
('6eb87150-a972-5330-8196-95fec0ecc068', 'Estiramiento de core de pie con piernas cruzadas', ARRAY['Cruza una pierna por delante de la otra y entrelaza las manos por encima de la cabeza.', 'Inclina el tronco hacia un lado manteniendo la cadera estable.', 'Nota el estiramiento en el costado y respira profundamente.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita girar el tronco o perder el equilibrio.']::text[], 'principiante', 'Estira la cadena lateral del tronco y la zona lumbar, aliviando tensiones por malas posturas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '9942'),
('39f6792d-53b3-5f00-8da7-2a845e3e06c9', 'Rotación externa detrás de la espalda de pie con toalla', ARRAY['Sujeta una toalla por detrás de la espalda con una mano arriba y otra abajo.', 'Tira suavemente de la toalla para rotar el hombro hacia fuera sin mover el codo.', 'Mantén el movimiento lento y controlado durante todo el recorrido.', 'Evita encoger el hombro o tirar con fuerza brusca.', 'Respira de forma constante y cambia de lado.']::text[], 'principiante', 'Refuerza el manguito rotador y la espalda alta, útil para recuperar estabilidad del hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10931'),
('24088452-55cb-5414-91ad-a5be4f46141d', 'Deslizamiento de rotación externa de pie con toalla', ARRAY['Coloca una toalla enrollada entre el codo y el costado.', 'Con el codo pegado al cuerpo, gira el antebrazo hacia fuera deslizando la toalla.', 'Mantén el codo fijo y realiza el movimiento despacio.', 'Vuelve a la posición inicial controlando el retorno.', 'Evita separar el codo del cuerpo o usar impulso.']::text[], 'principiante', 'Activa el manguito rotador y la espalda alta con un deslizamiento controlado para estabilizar el hombro.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10930'),
('da10ad03-9bd9-5886-bf7c-43932ef4fc7a', 'Postura del cuatro de pie', ARRAY['Ponte de pie y cruza un tobillo sobre la rodilla contraria formando un cuatro.', 'Flexiona ligeramente la pierna de apoyo y lleva la cadera hacia atrás.', 'Mantén la espalda recta y el abdomen activo.', 'Respira con calma y cambia de lado.', 'Evita redondear la espalda o forzar la rodilla.']::text[], 'intermedio', 'Mejora el equilibrio y la movilidad de cadera mientras estira glúteos y flexores.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5902'),
('57e55fba-6445-5980-b902-59d0f92db3a5', 'Elevación de tibial de pie con apoyo en pared', ARRAY['Apoya las manos en la pared y colócate de pie con los talones en el suelo.', 'Eleva la punta de los pies manteniendo los talones apoyados.', 'Aguanta un instante arriba y baja despacio.', 'Mantén las rodillas ligeramente flexionadas y el cuerpo erguido.', 'Evita balancearte o levantar los talones.']::text[], 'intermedio', 'Fortalece el tibial anterior y la zona delantera de la pierna, mejorando la estabilidad del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10859'),
('cadbdf5a-4c3a-5e18-8097-8e67f3b25d21', 'Activación de los músculos del pie de pie', ARRAY['Ponte de pie descalzo con el peso repartido entre ambos pies.', 'Intenta formar un arco con la planta sin levantar los dedos del suelo.', 'Mantén la activación unos segundos y relaja despacio.', 'Repite varias veces controlando la respiración.', 'Evita agarrar con los dedos o levantar el talón.']::text[], 'principiante', 'Despierta la musculatura intrínseca del pie y mejora el control y la estabilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '6775'),
('ce6c43d9-328c-510a-8de4-b5b2bae34fed', 'Flexión adelante de pie uttanasana', ARRAY['Ponte de pie con los pies a la anchura de las caderas y las rodillas ligeramente flexionadas.', 'Inclina el tronco hacia delante desde la cadera y deja caer los brazos.', 'Relaja el cuello y respira profundamente en la posición.', 'Sube despacio vértebra a vértebra al terminar.', 'Evita bloquear las rodillas o forzar si notas molestia en la espalda.']::text[], 'principiante', 'Estira isquiotibiales, gemelos y espalda baja, favoreciendo la relajación y la movilidad posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0959'),
('fd0226e6-06c2-5420-8a85-d7ac13b04945', 'Press deslizante con toalla de pie', ARRAY['Colócate de pie con los pies a la anchura de las caderas y sujeta la toalla con las dos manos frente al pecho.', 'Desliza las manos hacia delante manteniendo la presión sobre la toalla y los codos ligeramente flexionados.', 'Vuelve despacio a la posición inicial controlando el movimiento en todo momento.', 'Mantén el abdomen firme y evita arquear la espalda baja al empujar.']::text[], 'principiante', 'Trabaja el pecho y los hombros mientras deslizas las manos con una toalla, útil para readaptar el empuje de forma controlada.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10927'),
('6de96b02-6421-5d76-aad8-7a28827f6c72', 'Contracción de glúteos de pie', ARRAY['Ponte de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Aprieta los glúteos como si quisieras juntar los talones sin mover las piernas.', 'Mantén la contracción unos segundos respirando con normalidad.', 'Evita inclinar la pelvis hacia delante o bloquear la respiración.']::text[], 'intermedio', 'Activa los glúteos y los isquiotibiales de forma isométrica para mejorar la estabilidad de la cadera y la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '11653'),
('6c9a0d51-c439-5710-bcad-f790209938d9', 'Media flexión de pie', ARRAY['De pie con los pies juntos, alarga la espalda y lleva los brazos hacia arriba.', 'Baja el tronco flexionando la cadera con la espalda recta hasta donde puedas.', 'Respira despacio y mantén la posición sin rebotar.', 'Evita curvar la espalda o forzar más allá de una molestia leve.']::text[], 'intermedio', 'Estiramiento suave de isquiotibiales y espalda baja que mejora la flexibilidad posterior y alivia tensiones.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5903'),
('90a49cf7-9db7-5b56-8ef6-6e3f654035c7', 'Estiramiento de flexores de cadera en media rodilla', ARRAY['Arrodíllate sobre una rodilla con la otra pierna adelantada y el pie apoyado.', 'Aprieta el glúteo de la pierna retrasada y lleva la cadera hacia delante.', 'Mantén el tronco erguido y respira con calma durante el estiramiento.', 'Evita arquear la espalda baja o adelantar la rodilla delantera en exceso.']::text[], 'principiante', 'Estira los cuádriceps y los flexores de cadera para contrarrestar el tiempo sentado y mejorar la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11904'),
('eb02b8f1-1e3a-55a7-91dd-aa607e1cc41e', 'Estiramiento de isquiotibiales y gemelos con correa', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie.', 'Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta.', 'Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla.', 'Mantén el estiramiento durante 20-30 segundos.', 'Suelta el estiramiento y repite con la otra pierna.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Alarga la parte posterior de la pierna con ayuda de una correa, mejorando la flexibilidad de isquiotibiales y gemelos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1599'),
('bc119a44-655a-5adc-a0ab-d751decff6db', 'Estiramiento de isquiotibiales de pie', ARRAY['De pie, adelanta una pierna con el talón apoyado y la punta hacia arriba.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Nota el estiramiento en la parte posterior del muslo y respira despacio.', 'Evita redondear la espalda o forzar la rodilla de la pierna estirada.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla para ganar flexibilidad y reducir la rigidez tras el ejercicio.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0789'),
('b651a233-4c86-5d35-bbcd-d208aac20dec', 'Estiramiento de isquiotibiales y espalda de pie', ARRAY['De pie con los pies juntos, entrelaza las manos y estira los brazos hacia arriba.', 'Baja el tronco hacia delante flexionando la cadera con la espalda lo más recta posible.', 'Deja colgar los brazos y respira profundamente en la posición.', 'Evita rebotar o curvar la espalda de golpe al bajar.']::text[], 'principiante', 'Combina el alargamiento de la cadena posterior con la descompresión de la espalda baja para relajar tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '3630'),
('09b39114-40b5-5f03-b75d-753298d026ff', 'Posición de manos de pie', ARRAY['De pie, extiende los brazos al frente con los codos ligeramente flexionados.', 'Gira las palmas hacia arriba y hacia abajo alternando el movimiento con control.', 'Vuelve a la posición neutra con las palmas mirando al suelo entre repeticiones.', 'Evita mover los hombros o forzar la muñeca más allá de su rango cómodo.']::text[], 'principiante', 'Moviliza muñecas y antebrazos alternando pronación, supinación y posición neutra para prevenir molestias.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5286'),
('a55ba0ec-c197-5fc6-95da-680bf53d26dc', 'Estiramiento de aquiles con talón atrás', ARRAY['Apoya las manos en una pared y da un paso atrás con una pierna.', 'Mantén el talón trasero pegado al suelo y la rodilla estirada.', 'Inclina el cuerpo hacia la pared hasta notar el estiramiento en la pantorrilla.', 'Evita levantar el talón o girar la punta del pie hacia fuera.']::text[], 'principiante', 'Estira el tendón de Aquiles y la pantorrilla para mejorar la movilidad del tobillo y prevenir sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1887'),
('c70d4f7a-d4c4-5abf-9f62-086be8577a70', 'Estiramiento de isquiotibiales con pierna alta y rodilla flexionada', ARRAY['Apoya una pierna elevada sobre una superficie estable y flexiona ligeramente la rodilla.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Sostén la posición respirando despacio sin rebotar.', 'Evita curvar la espalda o elevar demasiado la pierna si notas tirantez.']::text[], 'principiante', 'Estira la parte posterior del muslo con la rodilla doblada, un ángulo que alivia la tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1912'),
('2fde44c6-89d3-5fe7-86eb-679c7ae57293', 'Abducción de cadera de pie', ARRAY['De pie, apóyate en una pared o silla para mantener el equilibrio.', 'Separa una pierna hacia el lado manteniéndola estirada y el tronco firme.', 'Baja la pierna despacio controlando el movimiento sin dejarla caer.', 'Evita inclinar el tronco hacia el lado contrario o girar la punta del pie.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para estabilizar la cadera y mejorar el equilibrio en movimientos diarios.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0791'),
('c6253860-913e-5822-a902-9d279819edca', 'Estiramiento de aducción de cadera de pie', ARRAY['De pie, separa las piernas y apoya las manos en las caderas.', 'Flexiona ligeramente una rodilla y desplaza el peso hacia ese lado.', 'Mantén la otra pierna estirada notando el estiramiento en la cara interna.', 'Evita rebotar o forzar la apertura más allá de una molestia leve.']::text[], 'principiante', 'Alarga los aductores y la cara interna del muslo para mejorar la movilidad de la cadera y prevenir tirones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1941'),
('18ea43cb-8496-5755-836c-ce1ab475565f', 'Aducción de cadera de pie', ARRAY['De pie, apóyate en una pared y separa ligeramente las piernas.', 'Lleva una pierna hacia dentro cruzando por delante de la otra con control.', 'Vuelve despacio a la posición inicial sin dejar caer la pierna.', 'Evita inclinar el tronco o girar la cadera durante el movimiento.']::text[], 'intermedio', 'Fortalece los aductores y la cara interna del muslo para mejorar la estabilidad y el control de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '5169'),
('716837cb-544c-5f15-a159-a3f509366b64', 'Círculo de cadera de pie', ARRAY['De pie con las manos en la cintura y los pies a la anchura de las caderas.', 'Dibuja círculos amplios con la cadera hacia un lado y luego hacia el otro.', 'Mantén las rodillas ligeramente flexionadas y respira con normalidad.', 'Evita mover solo la espalda o hacer círculos bruscos y pequeños.']::text[], 'principiante', 'Moviliza la cadera en todas las direcciones para calentar la articulación y mejorar la coordinación del tren inferior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3411'),
('027a39b4-adb9-5c30-b710-17c489ea9a99', 'Extensión de cadera de pie con rodilla flexionada', ARRAY['De pie, apóyate en una pared y flexiona una rodilla llevando el talón hacia el glúteo.', 'Lleva la pierna hacia atrás apretando el glúteo sin arquear la espalda.', 'Vuelve despacio a la posición inicial manteniendo el equilibrio.', 'Evita balancear la pierna o compensar inclinando el tronco hacia delante.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales para mejorar la extensión de cadera y la estabilidad del tren inferior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0792'),
('21473fdc-dbc4-5e4c-b6f1-cbf7733db298', 'Estiramiento de flexores de cadera de pie', ARRAY['Colócate de pie con una mano apoyada en la pared para mantener el equilibrio.', 'Lleva una pierna hacia atrás y aprieta el glúteo para retroceder la pelvis.', 'Mantén el tronco erguido y nota el estiramiento en la parte delantera de la cadera.', 'Respira despacio y aguanta entre veinte y treinta segundos.', 'Evita arquear la zona lumbar: mantén las costillas abajo y el abdomen activo.']::text[], 'principiante', 'Alivia la tensión acumulada en la parte delantera de la cadera y el muslo, útil tras muchas horas sentado estudiando.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1949'),
('05a0f392-9a2a-54c6-9a16-dd7e13ed491f', 'Estiramiento de aductores de pie con cadera hacia fuera', ARRAY['Separa los pies y apoya las manos en las caderas.', 'Desplaza la cadera hacia un lado mientras flexionas ligeramente esa rodilla.', 'Mantén la otra pierna estirada con el pie bien apoyado en el suelo.', 'Aguanta la posición respirando con calma y cambia de lado.', 'No fuerces hacia abajo: busca la tensión en la ingle sin rebotar.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, mejorando la movilidad de la cadera para sentadillas y zancadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1877'),
('6c4368ac-bde0-514c-8ba1-b87990665def', 'Estiramiento de banda iliotibial de pie', ARRAY['Cruza una pierna por detrás de la otra y apóyate en una pared.', 'Inclina el tronco hacia el lado de la pierna adelantada.', 'Empuja la cadera hacia fuera hasta notar tensión en el lateral del muslo.', 'Mantén la posición treinta segundos sin girar el tronco.', 'Evita curvar la espalda: inclínate desde la cadera y respira de forma constante.']::text[], 'principiante', 'Libera tensión en la parte externa del muslo y la cadera, ayudando a prevenir molestias en la rodilla.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1942'),
('bda64358-cbc6-5ec1-94b7-3f1501205bc0', 'Deslizamiento de rotación interna de pie con toalla', ARRAY['Sujeta una toalla enrollada con la mano y coloca el codo pegado al costado.', 'Flexiona el codo unos noventa grados con la palma hacia dentro.', 'Gira lentamente el antebrazo hacia el abdomen sin separar el codo del cuerpo.', 'Vuelve despacio a la posición inicial controlando el movimiento.', 'Evita compensar con el tronco: el movimiento debe salir solo del hombro.']::text[], 'principiante', 'Recupera movilidad y control del hombro en rotación interna, útil en la readaptación de lesiones.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10929'),
('49c620e6-85e8-50c5-ab34-99b4a3e948e1', 'Sostén isométrico de bíceps de pie', ARRAY['Colócate de pie con los brazos estirados y las palmas hacia delante.', 'Flexiona los codos hasta unos noventa grados y aprieta el bíceps.', 'Mantén la contracción sin mover los brazos durante veinte o treinta segundos.', 'Respira con normalidad sin aguantar la respiración.', 'Evita encoger los hombros o balancear el tronco para sostener la posición.']::text[], 'intermedio', 'Activa el bíceps y el antebrazo sin movimiento, mejorando la resistencia muscular y el control del codo.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10138'),
('0d19272f-764f-59b9-813a-a99f8083f7a8', 'Elevación de gemelos de pie con isométrico', ARRAY['Colócate de pie con los pies a la anchura de las caderas y las manos en la pared.', 'Elévate sobre las puntas de los pies hasta quedar bien alto.', 'Mantén la posición apretando los gemelos entre veinte y treinta segundos.', 'Baja despacio hasta apoyar los talones en el suelo.', 'Evita dejar caer los talones de golpe o perder el equilibrio.']::text[], 'intermedio', 'Fortalece gemelos y sóleo con una contracción sostenida que mejora la estabilidad del tobillo.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9310'),
('44feffc1-5e69-5a4d-af34-3af18bc186e2', 'Rotación externa isométrica de hombro de pie con toalla', ARRAY['Sujeta una toalla enrollada con el codo pegado al costado y flexionado noventa grados.', 'Empuja la toalla hacia fuera como si quisieras girar el antebrazo.', 'Mantén la tensión sin mover el brazo durante veinte segundos.', 'Respira con calma y relaja despacio al terminar.', 'Evita separar el codo del cuerpo o girar el tronco para hacer fuerza.']::text[], 'intermedio', 'Refuerza el manguito rotador y la parte posterior del hombro, clave para estabilizar la articulación.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10126'),
('75811156-711b-5692-b89e-d4b36c98b645', 'Rotación interna isométrica de hombro de pie contra la pared', ARRAY['Colócate de lado a la pared con el codo flexionado noventa grados.', 'Apoya el dorso de la mano o el antebrazo contra la pared.', 'Empuja la pared como si quisieras girar el brazo hacia dentro.', 'Mantén la presión constante unos veinte segundos sin moverte.', 'Evita encoger el hombro o inclinar el tronco al empujar.']::text[], 'intermedio', 'Activa el manguito rotador en rotación interna, mejorando la estabilidad y el control del hombro.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '9990'),
('6fb498a0-9b72-5f86-82e5-5eea121ed73a', 'Estiramiento de rodilla al pecho de pie', ARRAY['Colócate de pie y apóyate en una pared con una mano.', 'Flexiona una rodilla y llévala hacia el pecho con la mano libre.', 'Mantén la espalda recta y el abdomen activo mientras sujetas la pierna.', 'Aguanta veinte o treinta segundos respirando despacio y cambia de lado.', 'Evita redondear la espalda o tirar del cuello hacia abajo.']::text[], 'principiante', 'Estira glúteos y zona lumbar, aliviando la rigidez típica de estar mucho tiempo sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1811'),
('fefc7fc5-08bf-55b1-bd5d-d3b8301b9dae', 'Estiramiento de abdomen de pie inclinado hacia atrás', ARRAY['Colócate de pie con los pies a la anchura de las caderas.', 'Apoya las manos en la zona lumbar y lleva la pelvis hacia delante.', 'Inclina suavemente el tronco hacia atrás sin forzar la espalda.', 'Mantén la posición quince o veinte segundos respirando con calma.', 'Evita echar la cabeza atrás o buscar un rango excesivo que moleste.']::text[], 'principiante', 'Estira la musculatura abdominal y los flexores de cadera, mejorando la extensión de la columna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2108'),
('47572953-064f-5fbf-afac-86adfb147772', 'Círculo de pierna de pie', ARRAY['Apóyate en una pared y levanta una pierna ligeramente del suelo.', 'Dibuja círculos pequeños con la pierna manteniéndola estirada.', 'Realiza diez círculos en un sentido y diez en el contrario.', 'Mantén el tronco firme y el abdomen activo durante todo el movimiento.', 'Evita balancear la cadera o hacer círculos demasiado grandes al principio.']::text[], 'principiante', 'Mejora la movilidad de la cadera y activa abductores y glúteos con un movimiento controlado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4933'),
('70b09a77-6085-5dfd-8b17-0bdd7844e103', 'Estiramiento de abductores de pie con piernas cruzadas', ARRAY['Cruza una pierna por delante de la otra manteniendo los pies apoyados.', 'Inclina el tronco hacia el lado de la pierna cruzada.', 'Lleva la cadera hacia fuera hasta notar tensión en el lateral.', 'Aguanta treinta segundos sin rebotar y cambia de lado.', 'Evita flexionar demasiado las rodillas o perder el equilibrio.']::text[], 'principiante', 'Estira la parte externa de la cadera y el glúteo, útil para descargar la zona tras caminar o correr.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1878'),
('fa631b99-1c15-52a1-874b-9bb2dd43c61f', 'Estiramiento de cadera de pie con pierna apoyada', ARRAY['Apoya una pierna estirada sobre una superficie elevada a la altura de la cadera.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Nota el estiramiento en el glúteo y la parte posterior del muslo.', 'Mantén la posición treinta segundos respirando despacio.', 'Evita redondear la espalda o forzar más de lo que permite tu flexibilidad.']::text[], 'principiante', 'Estira glúteos y cadera aprovechando un apoyo elevado, ideal para después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1879'),
('2a59e8d9-3df5-5847-9e0b-383165efcb45', 'Deslizamiento de pierna de pie con toalla', ARRAY['Coloca un pie sobre una toalla en el suelo liso y apóyate en una pared.', 'Desliza la pierna hacia atrás manteniendo el peso en la pierna de apoyo.', 'Controla el movimiento sin dejar que la rodilla se hunda hacia dentro.', 'Vuelve despacio a la posición inicial y repite las repeticiones indicadas.', 'Evita arquear la lumbar o perder la alineación de la rodilla.']::text[], 'intermedio', 'Fortalece glúteos y estabilizadores de la cadera con un deslizamiento controlado que mejora el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4380'),
('61482501-e5c0-5662-aa37-865bad23b5d0', 'Estiramiento de cadera de pie con pierna recogida', ARRAY['De pie, apóyate en una pared y flexiona una rodilla llevándola hacia el pecho.', 'Sujeta la pierna con la mano y mantén el tronco erguido.', 'Aprieta suavemente la rodilla contra el pecho sin forzar.', 'Aguanta veinte o treinta segundos y cambia de lado.', 'Evita inclinarte hacia atrás o perder el equilibrio por tirar demasiado.']::text[], 'principiante', 'Libera tensión en glúteo y cadera con una recogida de pierna que también estira la parte posterior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1946'),
('0ff8a63d-19b0-5a39-8a6c-9caf9f9e1b10', 'Estiramiento de abductores de pie con pierna por debajo', ARRAY['Colócate de pie con los pies juntos y apoya una mano en la pared para mantener el equilibrio.', 'Cruza una pierna por detrás de la otra y baja la cadera hacia el lado de la pierna cruzada.', 'Mantén la posición entre veinte y treinta segundos respirando de forma lenta y constante.', 'Evita inclinar el tronco hacia delante y no fuerces la rodilla de apoyo.']::text[], 'principiante', 'Estira la cara externa de la cadera y el glúteo, mejorando la movilidad lateral y aliviando tensión acumulada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1881'),
('932b0965-ce4f-5c25-b743-2334819a94c6', 'Estiramiento de aductores de pie con pierna arriba', ARRAY['Apoya una mano en la pared y eleva un pie sobre una superficie estable a la altura de la cadera.', 'Gira el tronco hacia la pierna elevada hasta notar tensión en la cara interna del muslo.', 'Mantén la espalda recta y respira despacio durante veinte o treinta segundos.', 'No rebotes ni fuerces la rodilla elevada más allá de lo cómodo.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, útil para mejorar la movilidad de cadera antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1897'),
('7376e4d6-e6f3-5982-8c7d-329809280064', 'Estiramiento de isquiotibiales de pie con pierna arriba', ARRAY['Coloca un pie sobre una superficie elevada con la pierna casi extendida y la punta hacia arriba.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda recta.', 'Respira de forma pausada y mantén el estiramiento entre veinte y treinta segundos.', 'Evita curvar la espalda o bloquear la rodilla de la pierna elevada.']::text[], 'principiante', 'Estira la parte posterior del muslo y la pantorrilla, mejorando la flexibilidad y reduciendo tensión lumbar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1910'),
('0458a513-a7ab-54e4-8797-bcef4d0c1bf9', 'Salto largo de pie', ARRAY['Colócate de pie con los pies a la anchura de los hombros y los brazos atrás.', 'Flexiona rodillas y cadera y salta hacia delante con fuerza, llevando los brazos adelante.', 'Aterriza con las rodillas alineadas con los pies y amortigua el impacto flexionando.', 'Evita aterrizar con las piernas rígidas o con las rodillas hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia de piernas y cadera con un gesto explosivo que mejora el rendimiento en saltos y sprints.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1600'),
('79ecfdb0-7a4a-556e-8bea-474839566afb', 'Rotación de la parte baja del cuerpo de pie', ARRAY['De pie con los pies a la anchura de los hombros y las manos en la cintura.', 'Gira la cadera y la parte baja del tronco hacia un lado sin mover los pies.', 'Vuelve al centro y repite hacia el otro lado de forma lenta y controlada.', 'Evita girar solo con los brazos o forzar el rango lumbar.']::text[], 'principiante', 'Moviliza la zona lumbar y el core con un giro controlado que prepara la columna para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3407'),
('2035dc59-c6fe-541d-b07e-0e906fa2bb1a', 'Estiramiento de flexores laterales del tronco inferior de pie', ARRAY['De pie con los pies juntos, eleva un brazo por encima de la cabeza.', 'Inclina el tronco hacia el lado contrario manteniendo la cadera estable.', 'Mantén el estiramiento veinte o treinta segundos respirando con calma.', 'Evita rotar el tronco o inclinarte hacia delante.']::text[], 'principiante', 'Estira la musculatura lateral del tronco y la zona lumbar, mejorando la movilidad y aliviando rigidez.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2113'),
('a1225614-703c-5861-be21-32e364e3961b', 'Estiramiento de pecho de pie a un brazo', ARRAY['Apoya la palma de una mano en una pared a la altura del hombro.', 'Gira el tronco hacia el lado contrario hasta notar tensión en el pecho.', 'Mantén el hombro bajo y respira despacio durante veinte o treinta segundos.', 'Evita encoger el hombro o forzar la articulación hacia atrás.']::text[], 'principiante', 'Estira el pectoral y la parte anterior del hombro, útil para contrarrestar posturas encorvadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1058'),
('d3f64aed-66cd-5030-88be-8f1fdbc0a608', 'Círculos con un brazo de pie', ARRAY['De pie con el brazo extendido hacia un lado a la altura del hombro.', 'Dibuja círculos pequeños y ve ampliándolos de forma progresiva.', 'Realiza quince repeticiones en cada sentido sin mover el tronco.', 'Evita encoger el hombro o hacer círculos bruscos.']::text[], 'principiante', 'Moviliza el hombro y el manguito rotador, preparando la articulación para presses y elevaciones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3257'),
('3e9c8436-6ce2-5982-ae58-10d719bd4431', 'Estiramiento de cadera externa de pie', ARRAY['De pie, cruza una pierna por delante de la otra y apoya la mano en la pared.', 'Lleva la cadera hacia el lado de la pierna cruzada hasta notar tensión externa.', 'Mantén la posición veinte o treinta segundos respirando de forma constante.', 'Evita arquear la espalda o levantar el pie de apoyo.']::text[], 'principiante', 'Estira la cara externa de la cadera y el glúteo, mejorando la movilidad y reduciendo tensión en la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1947'),
('23ddfd34-2d66-5526-ab43-e628b3cf7d1b', 'Elevación pélvica de pie', ARRAY['De pie con los pies a la anchura de la cadera y las rodillas ligeramente flexionadas.', 'Contrae el glúteo y lleva la pelvis hacia delante sin mover el tronco.', 'Mantén dos segundos arriba y vuelve despacio a la posición neutra.', 'Evita arquear la zona lumbar o apretar en exceso las rodillas.']::text[], 'principiante', 'Activa glúteos y core con un gesto suave de retroversión, útil en readaptación y control postural.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '9890'),
('2b651b62-de8b-55a8-a6f6-099036cf54a9', 'Inclinación pélvica de pie', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Coloca las manos sobre las caderas o déjalas colgar a los lados.', 'Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.', 'Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Mejora el control de la pelvis y la movilidad de la columna, ayudando a encontrar la posición neutra.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1364'),
('188b22b4-5ea7-5b54-bbcd-75ef35b23264', 'Estiramiento de los músculos peroneos de pie', ARRAY['De pie, cruza una pierna por detrás y apoya la punta del pie en el suelo.', 'Inclina la cadera hacia el lado contrario hasta notar tensión en la cara externa de la pierna.', 'Mantén la posición veinte o treinta segundos respirando con calma.', 'Evita girar el pie hacia dentro o forzar el tobillo.']::text[], 'principiante', 'Estira la cara externa de la pierna y el tobillo, útil para prevenir tensiones en corredores.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6772'),
('c8210f1b-ab76-555c-bf72-72f4c38377ad', 'Phelps de pie', ARRAY['De pie con los brazos extendidos y las manos relajadas.', 'Lleva los brazos hacia atrás y adelante describiendo círculos amplios.', 'Coordina el movimiento con la respiración y repite diez o quince veces.', 'Evita encoger los hombros o mover la cadera en exceso.']::text[], 'principiante', 'Moviliza hombros y columna dorsal con un giro amplio que prepara el tren superior para entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3409'),
('06fcdbfb-cc8c-57d0-bbc8-2ca531486fb2', 'Press de disco de pie', ARRAY['De pie con los pies a la anchura de los hombros y el disco a la altura del pecho.', 'Empuja el disco por encima de la cabeza extendiendo los brazos sin arquear la espalda.', 'Baja el disco de forma controlada hasta el pecho y repite.', 'Evita bloquear la respiración o inclinarte hacia atrás al empujar.']::text[], 'intermedio', 'Fortalece hombros y tríceps con un press vertical que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1225'),
('9f89a2f7-021e-5d59-967f-7b8ae5273d80', 'Postura de pie (revisión de técnica) vista frontal', ARRAY['Colócate de pie con los pies a la anchura de la cadera y los brazos relajados.', 'Alinea orejas, hombros, cadera y tobillos y activa ligeramente el core.', 'Mantén la posición entre veinte y cuarenta segundos respirando con normalidad.', 'Evita bloquear las rodillas o adelantar la cabeza.']::text[], 'intermedio', 'Trabaja la conciencia postural y el control del core manteniendo una alineación correcta de pie.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3673'),
('dfca0778-f619-5413-930d-0fc025e70afd', 'Revisión de postura de pie', ARRAY['Colócate de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Mira de lado en un espejo y alinea orejas, hombros, caderas y tobillos.', 'Activa ligeramente el abdomen y los glúteos sin bloquear la respiración.', 'Mantén la posición entre veinte y treinta segundos respirando con normalidad.', 'Evita sacar el pecho en exceso o adelantar la cabeza.']::text[], 'intermedio', 'Comprueba la alineación de la columna y activa el core para corregir malos hábitos posturales.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3674'),
('4937e529-c946-50ba-9d2b-a8c2e95b6756', 'Estiramiento de aductores de pie', ARRAY['Apoya una pierna extendida sobre un banco o superficie a la altura de la cadera.', 'Mantén la otra pierna recta y el tronco erguido.', 'Inclina suavemente el tronco hacia la pierna elevada hasta notar tensión en la ingle.', 'Mantén entre veinte y treinta segundos sin rebotar y respira despacio.', 'Evita redondear la espalda o forzar más allá de una molestia leve.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle para mejorar la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1896'),
('c743c559-c81a-536b-a40f-6e35db2cdc75', 'Estiramiento de isquiotibiales con piernas cruzadas', ARRAY['Cruza una pierna por delante de la otra con los pies juntos.', 'Con las rodillas ligeramente flexionadas, inclina el tronco hacia abajo.', 'Deja caer los brazos y relaja el cuello mientras desciendes.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita bloquear las rodillas o curvar la espalda en exceso.']::text[], 'principiante', 'Alarga la parte posterior del muslo y la pantorrilla con un cruce que intensifica el estiramiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1917'),
('fcb58fca-eae7-5274-86bc-2862923993fe', 'Estiramiento de isquiotibiales de pie alcanzando hacia abajo', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Inclina el tronco hacia abajo dejando caer los brazos hacia el suelo.', 'Relaja el cuello y permite que la espalda se alargue de forma natural.', 'Mantén entre veinte y treinta segundos respirando despacio.', 'Evita rebotar o forzar hasta el punto de dolor.']::text[], 'principiante', 'Estira la parte posterior del muslo y la zona lumbar para aliviar tensión tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1916'),
('7bd81de2-93b4-55a6-bb80-1e34f19bad7f', 'Estiramiento de rotación de espalda con brazos arriba', ARRAY['De pie, eleva los brazos por encima de la cabeza con las manos entrelazadas.', 'Gira suavemente el tronco hacia un lado manteniendo las caderas al frente.', 'Sostén la rotación entre quince y veinte segundos sin forzar.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita mover las caderas o arquear la zona lumbar.']::text[], 'principiante', 'Moviliza la espalda y estira los dorsales y oblicuos para ganar amplitud en la rotación.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1796'),
('71126ddf-9afc-5995-8dce-0667eff2adea', 'Estiramiento rotacional de cadera', ARRAY['De pie, apoya una mano en una pared para mantener el equilibrio.', 'Flexiona una rodilla y lleva el pie hacia el glúteo.', 'Gira suavemente la cadera hacia dentro y hacia fuera sin mover el tronco.', 'Mantén la posición entre veinte y treinta segundos por cada lado.', 'Evita tirar del pie con fuerza o perder la verticalidad del tronco.']::text[], 'principiante', 'Libera tensión en glúteos y flexores de cadera mejorando la rotación de la pelvis.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1895'),
('1bc23bb5-df39-5740-9997-2c9bbef79df4', 'Rotación escapular de pie', ARRAY['Colócate de pie con los brazos relajados y la espalda recta.', 'Lleva los hombros hacia delante y hacia arriba dibujando un círculo.', 'Completa el círculo bajando y juntando las escápulas detrás.', 'Realiza diez repeticiones lentas en cada sentido respirando con calma.', 'Evita encoger el cuello o mover los codos.']::text[], 'principiante', 'Mejora la movilidad de la escápula y la zona dorsal alta para prevenir molestias cervicales.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '7232'),
('de049e5c-26e0-5978-bc19-548a6da0de45', 'Tijeras de pie', ARRAY['De pie, da un salto abriendo las piernas y cruzando los brazos al frente.', 'Salta de nuevo para volver a la posición inicial juntando los pies.', 'Aterriza con las rodillas ligeramente flexionadas y el abdomen activo.', 'Mantén un ritmo constante durante treinta segundos respirando de forma acompasada.', 'Evita aterrizar con las piernas rígidas o golpear con los talones.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y glúteos con un ejercicio pliométrico sencillo.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4328'),
('93f97d40-cc83-57ce-aef9-a53091a53934', 'Postura de la foca de pie', ARRAY['De pie, entrelaza las manos detrás de la espalda con los brazos estirados.', 'Abre el pecho y lleva los hombros hacia atrás y hacia abajo.', 'Eleva ligeramente la barbilla y alarga la columna hacia arriba.', 'Mantén entre veinte y treinta segundos respirando profundo.', 'Evita arquear en exceso la zona lumbar o encoger el cuello.']::text[], 'intermedio', 'Extiende la columna y abre el pecho para contrarrestar posturas encorvadas del estudio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4399'),
('8c7c8782-24bd-5284-bccd-e5ed1d49c643', 'Estiramiento de espinilla', ARRAY['De pie, apoya el empeine de un pie en el suelo detrás del otro.', 'Mantén las rodillas juntas y el tronco erguido.', 'Empuja suavemente la cadera hacia delante hasta notar tensión en la espinilla.', 'Mantén entre veinte y treinta segundos por cada pierna.', 'Evita levantar el talón del pie que estira.']::text[], 'principiante', 'Alivia la tensión en la parte delantera de la pierna y mejora la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1957'),
('fa1b83be-b5a2-5444-9baf-924779dd3411', 'Círculos de hombros', ARRAY['De pie, con los brazos relajados a los lados del cuerpo.', 'Dibuja círculos amplios con los hombros hacia delante de forma lenta.', 'Completa diez repeticiones y cambia el sentido hacia atrás.', 'Mantén el cuello relajado y la respiración constante.', 'Evita mover los codos o encoger los hombros hacia las orejas.']::text[], 'principiante', 'Calienta y moviliza la articulación del hombro y la cintura escapular antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3416'),
('038e350c-df56-5e5f-9967-4fcf4ccec250', 'Flexión lateral de pie', ARRAY['De pie, con los pies a la anchura de las caderas y los brazos relajados.', 'Desliza una mano por el lateral del muslo inclinando el tronco hacia ese lado.', 'Mantén la cadera estable y siente el estiramiento en el costado.', 'Vuelve al centro y repite hacia el otro lado de forma controlada.', 'Evita inclinarte hacia delante o girar el tronco.']::text[], 'principiante', 'Moviliza la columna lateral y estira oblicuos y dorsales para ganar flexibilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3253'),
('8effa8b0-002b-5ec3-8e20-457fc0d0890f', 'Abdominal lateral de pie', ARRAY['De pie, con las manos detrás de la cabeza y los codos abiertos.', 'Flexiona el tronco hacia un lado llevando el codo hacia la cadera.', 'Contrae el oblicuo al final del recorrido y vuelve despacio.', 'Realiza entre diez y quince repeticiones por cada lado.', 'Evita tirar del cuello con las manos o inclinarte hacia delante.']::text[], 'intermedio', 'Trabaja los oblicuos y la estabilidad del core con un movimiento controlado y sencillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4366'),
('c51d8875-0dd3-5dc7-bbd3-c710a6b724bf', 'Elevación lateral de pierna', ARRAY['De pie, apoya una mano en una pared para mantener el equilibrio.', 'Eleva una pierna hacia el lado manteniéndola recta y el tronco firme.', 'Sube hasta donde controles sin inclinar el cuerpo y baja despacio.', 'Realiza entre diez y quince repeticiones por cada lado.', 'Evita balancear la pierna o inclinar el tronco hacia el lado contrario.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para estabilizar la cadera y mejorar el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3929'),
('cf4e1093-a345-55ea-bc96-16ae509c5f77', 'Estiramiento lateral de cuello de pie', ARRAY['De pie, con los hombros relajados y la espalda recta.', 'Inclina la cabeza hacia un lado llevando la oreja al hombro.', 'Puedes apoyar suavemente la mano del mismo lado sin tirar.', 'Mantén entre veinte y treinta segundos y cambia de lado.', 'Evita girar la cabeza o elevar el hombro contrario.']::text[], 'principiante', 'Alivia la tensión del cuello y los trapecios acumulada por el estudio y las pantallas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7306'),
('3ac94c07-ad20-54d4-99c0-d269e76f41ea', 'Estiramiento de costado de pie con palo', ARRAY['Colócate de pie con los pies a la anchura de las caderas y sujeta el palo por encima de la cabeza con las manos separadas.', 'Inclina el tronco hacia un lado manteniendo la cadera estable y sin rotar.', 'Aguanta el estiramiento entre 20 y 30 segundos respirando con normalidad.', 'Evita arquear la espalda o echar el tronco hacia delante mientras te inclinas.']::text[], 'principiante', 'Estira la musculatura lateral del tronco y la espalda, mejorando la movilidad de la columna y aliviando tensiones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2120'),
('eb9ef43a-6bbb-56e6-acc7-8b5c45503f2d', 'Elevación de gemelos a una pierna en escalera', ARRAY['Apoya la punta de un pie en el borde de un escalón y deja el talón en el aire.', 'Empuja con la punta del pie para elevarte lo máximo posible y controla la bajada.', 'Baja el talón por debajo del escalón hasta notar estiramiento y vuelve a subir.', 'Evita rebotar o perder el equilibrio apoyándote en la pared si lo necesitas.']::text[], 'intermedio', 'Fortalece los gemelos y el sóleo de forma unilateral, mejorando el equilibrio y la estabilidad del tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5003'),
('46955de0-e670-5f0c-a42b-7f1be892d28c', 'Equilibrio con elevación de gemelos a una pierna', ARRAY['Colócate de pie sobre una pierna con el tronco erguido y la mirada al frente.', 'Elévate sobre la punta del pie de forma controlada y mantén un segundo arriba.', 'Baja el talón despacio sin apoyar la otra pierna en el suelo.', 'Evita inclinarte hacia los lados; fija la mirada en un punto para mantener el equilibrio.']::text[], 'intermedio', 'Trabaja la fuerza de gemelos y sóleo junto con el equilibrio monopodal, clave para la estabilidad del tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4796'),
('1e83e3cc-c7dc-5367-8cf2-7fe0fa8429d5', 'Elevación de gemelos a una pierna con apoyo', ARRAY['Apóyate con una mano en una pared o silla y levanta una pierna del suelo.', 'Elévate sobre la punta del pie de la pierna de apoyo hasta la máxima extensión.', 'Baja el talón lentamente controlando el movimiento durante dos o tres segundos.', 'Evita cargar el peso hacia el apoyo y mantén la cadera alineada con el pie.']::text[], 'intermedio', 'Refuerza gemelos y sóleo de forma unilateral con ayuda externa, ideal para progresar en fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3712'),
('beb7fc1c-bd04-5a69-b464-5f11a83a69c1', 'Balanceo de gemelos a una pierna', ARRAY['De pie sobre una pierna, apóyate ligeramente en una pared si lo necesitas.', 'Balancea el talón arriba y abajo con un ritmo suave y continuo.', 'Mantén la rodilla ligeramente flexionada y el tronco erguido.', 'Evita movimientos bruscos y no bloquees la respiración durante el balanceo.']::text[], 'principiante', 'Moviliza el tobillo y activa la musculatura de la pantorrilla, preparando la articulación para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10547'),
('081aa44c-20a4-56bb-9529-878c8deb8a1c', 'Elevación de gemelos concentrada a una pierna', ARRAY['Colócate de pie sobre una pierna con el tronco recto y las manos en la cintura.', 'Elévate sobre la punta del pie concentrando la tensión en el gemelo.', 'Mantén la posición alta un instante y baja el talón de forma lenta y controlada.', 'Evita balancear el cuerpo o ayudarte con impulso de la cadera.']::text[], 'intermedio', 'Aísla la pantorrilla en una sola pierna para ganar fuerza y control en el tobillo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10548'),
('347332ff-e9a2-5393-8b39-83cf4955febd', 'Curl femoral a una pierna de pie', ARRAY['Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.', 'Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla.', 'Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial.', 'Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Fortalece los isquiotibiales y glúteos de forma unilateral, mejorando la fuerza posterior del muslo y el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0795'),
('4601dd72-c3ec-571a-9a3c-85ada4fcfaf7', 'Toque de punta a una pierna adelante, atrás y a los lados', ARRAY['De pie sobre una pierna, mantén el tronco erguido y el abdomen activo.', 'Toca el suelo con la punta del pie libre delante, detrás y a cada lado.', 'Vuelve siempre al centro manteniendo el equilibrio sobre la pierna de apoyo.', 'Evita arquear la espalda o perder la alineación de la rodilla.']::text[], 'principiante', 'Mejora la movilidad de cadera y la estabilidad monopodal, activando glúteos, aductores y core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10748'),
('25c1d3b3-8d1e-59cb-974c-1799d05a4ffb', 'Patada al glúteo con rodilla alta a una pierna con apoyo', ARRAY['Apóyate en una pared o silla y mantén el tronco erguido.', 'Sube la rodilla hacia el pecho y después lleva el talón hacia el glúteo.', 'Realiza el movimiento de forma fluida alternando las fases sin perder el equilibrio.', 'Evita inclinar el tronco hacia delante o bloquear la respiración.']::text[], 'principiante', 'Moviliza la cadera y activa cuádriceps, isquiotibiales y glúteos, mejorando la coordinación y el rango de movimiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4653'),
('c853788e-4ffe-5c23-8d69-3cba4cc60f33', 'Círculo de cadera a una pierna con apoyo en silla', ARRAY['Apóyate en una silla con una mano y levanta una rodilla hacia el pecho.', 'Dibuja círculos amplios con la rodilla en ambos sentidos de forma controlada.', 'Mantén el tronco estable y el abdomen activo durante todo el recorrido.', 'Evita compensar con la espalda o hacer círculos demasiado rápidos.']::text[], 'principiante', 'Moviliza la cadera en todas sus direcciones, activando glúteos, flexores y aductores para ganar amplitud.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10517'),
('c9fd5e12-9b36-5d9b-9642-2cfad12ce3a6', 'Contracción-relajación de isquiotibiales con pierna recta en balón', ARRAY['Coloca el talón de una pierna recta sobre el balón y apoya las manos en la cadera.', 'Empuja el balón hacia el suelo contrayendo el isquiotibial durante unos segundos.', 'Relaja y lleva el tronco hacia delante manteniendo la pierna estirada.', 'Evita redondear la espalda o forzar el estiramiento más allá de lo cómodo.']::text[], 'principiante', 'Estira los isquiotibiales mediante tensión-relajación, ganando flexibilidad y reduciendo la rigidez posterior del muslo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1601'),
('a58aed9e-6fb0-561c-8e64-ea580f6e19d8', 'Face pull supino de pie con toallas', ARRAY['Sujeta una toalla tensa con ambas manos a la altura del pecho y los codos altos.', 'Tira de la toalla separando las manos hacia la cara mientras abres los codos.', 'Aprieta la espalda alta un instante y vuelve despacio a la posición inicial.', 'Evita encoger los hombros o arquear la zona lumbar al tirar.']::text[], 'intermedio', 'Refuerza deltoides posterior, trapecio y rotadores externos, mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7745'),
('dca4d054-6623-575f-8806-191aaa56a412', 'Elevación en t de pie', ARRAY['De pie con los brazos extendidos a los lados formando una T.', 'Aprieta las escápulas y eleva los brazos ligeramente manteniendo los codos rectos.', 'Mantén la posición unos segundos respirando de forma controlada.', 'Evita encoger el cuello o arquear la espalda al elevar los brazos.']::text[], 'intermedio', 'Fortalece la espalda alta y los deltoides posteriores, mejorando la postura y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3404'),
('4c6a9e0e-df67-53a8-b2c4-1e47a43628a9', 'Estiramiento del tibial anterior de pie', ARRAY['De pie, apoya el empeine de un pie en el suelo por detrás del cuerpo.', 'Lleva suavemente la cadera hacia delante hasta notar el estiramiento en la espinilla.', 'Mantén la posición entre 20 y 30 segundos respirando con normalidad.', 'Evita forzar el tobillo o levantar el talón del pie de apoyo.']::text[], 'principiante', 'Estira la parte anterior de la espinilla y el tobillo, aliviando tensiones y mejorando la movilidad del pie.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6773'),
('61e9055f-cf65-515e-b6ec-a66025fbf046', 'Elevación de tibial de pie apoyado en la pared', ARRAY['Apóyate con la espalda en la pared y separa los pies ligeramente.', 'Levanta las puntas de los pies manteniendo los talones en el suelo.', 'Baja las puntas despacio controlando el movimiento.', 'Evita balancear el cuerpo o apoyar el peso en la pared para impulsarte.']::text[], 'intermedio', 'Fortalece el tibial anterior y la musculatura del tobillo, mejorando la estabilidad y previniendo lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9803'),
('18d68ef7-7a46-5a5d-91dd-fe2d1520619c', 'Estiramiento de extensores de los dedos del pie de pie', ARRAY['Apoya el empeine del pie en el suelo con los dedos apuntando hacia atrás y el talón levantado.', 'Lleva suavemente la cadera hacia delante hasta notar el estiramiento en la parte superior del pie.', 'Mantén la posición entre veinte y treinta segundos respirando con calma.', 'Evita cargar peso de golpe sobre el empeine para no forzar la articulación.']::text[], 'principiante', 'Estira la parte superior del pie y la espinilla, alivia tensión tras caminar o correr y mejora la movilidad del tobillo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1958'),
('817ee111-ff86-560b-aefc-3db989d08f55', 'Estiramiento de flexores de los dedos del pie de pie', ARRAY['Coloca la punta de los dedos en el suelo con el talón elevado y el pie apoyado.', 'Inclina la rodilla hacia delante poco a poco hasta sentir tensión en la planta.', 'Mantén la posición unos veinte segundos sin rebotes y respirando de forma pausada.', 'Evita apoyar todo el peso corporal sobre los dedos para no sobrecargarlos.']::text[], 'principiante', 'Relaja la planta del pie y la fascia, mejora la movilidad de los dedos y previene molestias en el pie.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1968'),
('7cc3cfdb-87cf-50c5-9bd1-a5b0bae6bb49', 'Estiramiento de aquiles de pie con punta arriba', ARRAY['Apoya la punta del pie en un escalón o superficie elevada con el talón fuera.', 'Lleva el peso del cuerpo ligeramente hacia delante manteniendo la rodilla estirada.', 'Aguanta entre veinte y treinta segundos respirando con normalidad.', 'Evita rebotar o forzar el tobillo más allá de una tensión cómoda.']::text[], 'principiante', 'Estira el tendón de Aquiles y la zona posterior del tobillo, mejora la flexibilidad y reduce el riesgo de sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1885'),
('d51d4a22-d21a-5943-9d68-eb7143b62791', 'Estiramiento de gemelos de pie con punta arriba', ARRAY['Coloca la punta del pie en un escalón con el talón colgando y la rodilla estirada.', 'Inclina el cuerpo hacia delante hasta notar tensión en la pantorrilla.', 'Mantén la posición veinte o treinta segundos sin bloquear la respiración.', 'Evita arquear la espalda o levantar el talón durante el estiramiento.']::text[], 'principiante', 'Alarga el gemelo y el sóleo, mejora la flexibilidad del tobillo y ayuda a prevenir calambres y sobrecargas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1924'),
('efb42d79-c982-599b-b0ae-06ae2204be8a', 'Estiramiento de isquiotibiales de pie con punta arriba', ARRAY['Apoya el talón en un escalón bajo con la punta del pie hacia arriba y la pierna estirada.', 'Lleva la cadera hacia atrás y baja el tronco manteniendo la espalda recta.', 'Mantén la posición entre veinte y treinta segundos respirando despacio.', 'Evita redondear la espalda o forzar la rodilla para llegar más abajo.']::text[], 'principiante', 'Estira la parte posterior del muslo y la zona lumbar, mejora la flexibilidad y alivia la rigidez tras estar sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1909'),
('d29f9adb-4c1b-5dc6-98b4-4f314edd08a2', 'Giro de tronco de pie con balanceo de brazos', ARRAY['Colócate de pie con los pies a la anchura de las caderas y los brazos relajados.', 'Gira el tronco a un lado dejando que los brazos se balanceen de forma natural.', 'Alterna el giro a cada lado con un ritmo suave y controlado.', 'Evita mover solo los brazos sin rotar la columna o hacer giros bruscos.']::text[], 'principiante', 'Moviliza la columna y los oblicuos, activa la cintura y prepara el torso para el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9653'),
('88a228a8-42d2-544c-a10b-2d307af97dfc', 'Abdominal de pie con pie sobre toalla', ARRAY['Coloca una toalla en el suelo y apoya el pie sobre ella con el peso repartido.', 'Arquea ligeramente la planta contrayendo los dedos para arrastrar la toalla hacia ti.', 'Mantén el resto del cuerpo estable y respira con normalidad durante el movimiento.', 'Evita levantar el talón o girar la rodilla hacia dentro.']::text[], 'intermedio', 'Fortalece la planta del pie y el tobillo, mejora el equilibrio y la estabilidad del pie en apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9986'),
('9a79364e-a386-5f06-a2cf-24627666ee85', 'Flexión lateral doble de pie', ARRAY['Colócate de pie con los pies juntos y los brazos elevados por encima de la cabeza.', 'Inclina el tronco hacia un lado manteniendo la cadera estable.', 'Vuelve al centro y repite hacia el otro lado de forma controlada.', 'Evita girar el tronco o echar la cadera hacia fuera al inclinarte.']::text[], 'principiante', 'Moviliza la columna y estira los oblicuos y dorsales, mejora la flexibilidad lateral del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3254'),
('1cda3dc5-4552-5f81-9aea-35620c8501ca', 'Rotación de la parte alta del cuerpo de pie', ARRAY['Colócate de pie con los pies a la anchura de las caderas y las manos en el pecho.', 'Gira la parte alta del tronco hacia un lado sin mover la cadera.', 'Vuelve al centro y alterna hacia el otro lado con un ritmo lento.', 'Evita forzar el giro o mover las piernas durante la rotación.']::text[], 'principiante', 'Moviliza la columna dorsal y los oblicuos, mejora la rotación del torso y alivia la rigidez.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3408'),
('44f7db67-265f-5229-aad3-0d1ad54c562a', 'Elevación en w de pie', ARRAY['Colócate de pie con los brazos flexionados formando una w y los codos pegados al cuerpo.', 'Junta las escápulas llevando los codos hacia atrás sin subir los hombros.', 'Mantén la contracción un segundo y vuelve despacio a la posición inicial.', 'Evita encoger el cuello o arquear la espalda al juntar las escápulas.']::text[], 'intermedio', 'Activa la musculatura de la espalda alta y los rotadores, mejora la postura y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3405'),
('984cc0bc-e624-5ba4-8054-f09c2ca4016e', 'Deslizamiento de serrato en la pared de pie con toalla', ARRAY['Coloca una toalla en la pared y apoya los antebrazos sobre ella a la altura de los hombros.', 'Desliza los brazos hacia arriba manteniendo el contacto con la pared.', 'Empuja suavemente la pared al final del recorrido y vuelve despacio.', 'Evita sacar las costillas o arquear la zona lumbar durante el movimiento.']::text[], 'principiante', 'Activa el serrato anterior y estabiliza la escápula, mejora la movilidad del hombro y la postura.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 2.3, 'rehab', '10928'),
('bb1a3721-beab-5565-b99e-e86c7cc0ede9', 'Rotación de hombro de pie en la pared', ARRAY['Apoya el antebrazo en la pared con el codo a la altura del hombro.', 'Gira el brazo hacia fuera manteniendo el codo pegado a la pared.', 'Vuelve despacio a la posición inicial y repite de forma controlada.', 'Evita despegar el codo o encoger el hombro durante la rotación.']::text[], 'principiante', 'Moviliza el hombro y activa el manguito rotador, mejora la estabilidad y previene molestias articulares.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10937'),
('8a98c6ab-83e7-5e7a-b838-318bbb3a17a5', 'Media sentadilla con deslizamiento en la pared de pie', ARRAY['Apoya la espalda en la pared con los pies separados y algo adelantados.', 'Desliza la espalda hacia abajo hasta media sentadilla manteniendo las rodillas alineadas.', 'Empuja con los talones para volver arriba controlando el movimiento.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos, mejora el patrón de sentadilla y la estabilidad de rodillas y cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11316'),
('785f987b-3ced-5d5f-a0f8-bd93c7cf3098', 'Cuarto de sentadilla con deslizamiento en la pared de pie (sostén)', ARRAY['Apoya la espalda en la pared y desliza hasta un cuarto de sentadilla.', 'Mantén la posición con las rodillas alineadas con los pies y el peso en los talones.', 'Aguanta entre veinte y cuarenta segundos respirando de forma constante.', 'Evita bloquear la respiración o dejar que las rodillas se junten.']::text[], 'intermedio', 'Isométrico que activa cuádriceps y glúteos, mejora la resistencia muscular y la estabilidad de la rodilla.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10926'),
('95feea5c-1199-5afa-ae4f-87dec740e02e', 'Rodillo abdominal de pie', ARRAY['Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti.', 'Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado.', 'Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible.', 'Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y la zona lumbar con la rueda, exigiendo control y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0796'),
('8d29d392-8593-5d30-946e-43cf0b8cc8ef', 'Estiramiento de aductores de pie con rodillas abiertas', ARRAY['Separa bien los pies y gira las puntas ligeramente hacia fuera.', 'Flexiona las rodillas y empuja las caderas hacia abajo manteniendo la espalda recta.', 'Aguanta la posición respirando despacio entre veinte y treinta segundos.', 'Evita rebotar o forzar hacia abajo si notas pinchazos en la ingle.']::text[], 'principiante', 'Estira la cara interna del muslo y la ingle, mejorando la movilidad de la cadera y aliviando tensiones tras el entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1894'),
('a6c2e6d0-01c1-5e82-bce0-82b4ed7c56ba', 'Estiramiento de aductores de pie con piernas abiertas', ARRAY['Abre las piernas más allá del ancho de los hombros con los pies paralelos.', 'Inclina el tronco hacia un lado flexionando esa rodilla mientras la otra pierna queda estirada.', 'Mantén la espalda larga y respira de forma pausada durante el estiramiento.', 'No bloquees la rodilla de la pierna estirada ni curvas la espalda.']::text[], 'principiante', 'Trabaja la flexibilidad de los aductores y la ingle con las piernas extendidas, útil para ganar amplitud en sentadillas y zancadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1904'),
('6aceca8b-c87b-5478-9243-6feeb3a6ceea', 'Escurrir la toalla de pie', ARRAY['De pie, imagina que sujetas una toalla delante del pecho con ambas manos.', 'Gira el tronco como si escurrieras la toalla hacia un lado y luego hacia el otro.', 'Mantén las caderas estables y acompaña el movimiento con la respiración.', 'Evita tirar solo de los brazos: el giro debe nacer del abdomen.']::text[], 'principiante', 'Activa el core y los oblicuos con un gesto de rotación que también implica hombros y antebrazos.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3410'),
('671107c9-baaa-5147-be29-6bb444d2581e', 'Elevación en y de pie', ARRAY['De pie con los brazos relajados y el core activo.', 'Eleva los brazos en diagonal formando una Y por encima de la cabeza.', 'Baja despacio controlando el movimiento y sin encoger el cuello.', 'Evita arquear la espalda o subir los hombros hacia las orejas.']::text[], 'intermedio', 'Refuerza trapecios y deltoides posteriores con un gesto en forma de Y que mejora la postura y la salud del hombro.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3403'),
('1ef4dd92-8873-56bd-9f6d-7d013494c9a7', 'Salto estrella', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.', 'Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva.', 'Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo.', 'Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio pliométrico cardiovascular que activa piernas y glúteos, mejorando coordinación y resistencia.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3223'),
('0186c7e7-3870-5639-93ee-c1bf19e9f247', 'Abdominal estrella', ARRAY['Túmbate boca arriba con brazos y piernas extendidos formando una estrella.', 'Eleva a la vez brazos y piernas acercando manos y pies en el centro.', 'Baja despacio sin dejar caer los segmentos de golpe.', 'Evita tirar del cuello o arquear la zona lumbar al subir.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos con una variante exigente que también implica flexores de cadera y core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2889'),
('0f1341da-3b98-573d-9025-afed07b944f2', 'Contracción estática de glúteos', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Aprieta los glúteos como si quisieras juntar los talones sin mover las piernas.', 'Mantén la contracción entre cinco y diez segundos respirando con normalidad.', 'Evita arquear la lumbar: el esfuerzo debe notarse en el glúteo, no en la espalda.']::text[], 'intermedio', 'Activa los glúteos y los isquios sin movimiento, útil para tomar conciencia de la zona y estabilizar la cadera.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '11646'),
('5370da28-0cd0-5901-8d99-fb1ae076131e', 'Zancada estática', ARRAY['Da un paso al frente y baja la rodilla trasera hacia el suelo.', 'Mantén la rodilla delantera alineada con el pie y el tronco erguido.', 'Aguanta la posición respirando de forma constante.', 'Evita que la rodilla delantera pase muy por delante de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquios manteniendo la posición de zancada, mejorando el equilibrio y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4000'),
('3d24f01a-58a6-500c-892a-80419704762f', 'Posición estática tumbado boca arriba con almohadilla', ARRAY['Túmbate boca arriba con una almohadilla bajo la zona lumbar o cervical.', 'Apoya bien la espalda y deja los brazos relajados a los lados.', 'Respira despacio manteniendo el abdomen ligeramente activo.', 'Evita tensar el cuello o levantar la lumbar de la almohadilla.']::text[], 'intermedio', 'Relaja y estabiliza la columna en decúbito supino, favoreciendo la conciencia postural y el control del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3657'),
('ca5357ed-48ff-51e7-ad10-4f8389672dbe', 'Posición estática tumbado boca abajo', ARRAY['Túmbate boca abajo con los brazos junto al cuerpo o hacia delante.', 'Activa suavemente glúteos y core sin levantar el pecho del suelo.', 'Mantén la posición respirando con calma durante el tiempo indicado.', 'Evita arquear el cuello mirando hacia arriba.']::text[], 'intermedio', 'Trabaja la extensión de la columna y la estabilidad del core en decúbito prono, útil para la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3660'),
('f6f6255e-b01e-5645-add7-f840a7c155f2', 'Posición estática sentado de espaldas', ARRAY['Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Alarga la columna y activa ligeramente el abdomen.', 'Mantén los hombros relajados y respira de forma pausada.', 'Evita curvar la espalda o adelantar la cabeza.']::text[], 'intermedio', 'Estabiliza la columna y el core en sedestación, mejorando la postura y la conciencia corporal.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3661'),
('4ca0e030-b18d-58ed-b1c1-ea395ff45e8e', 'Posición estática sentado con la espalda en almohadilla', ARRAY['Siéntate con una almohadilla detrás de la espalda apoyando la zona lumbar.', 'Apoya los pies en el suelo y alarga el tronco.', 'Mantén el abdomen activo y respira con normalidad.', 'Evita hundirte en la almohadilla perdiendo la curva lumbar.']::text[], 'intermedio', 'Favorece la alineación de la columna y el control del core sentado con apoyo, ideal para trabajo postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3658'),
('c8fa18c9-efb1-50d2-9263-9b9e4dbbf223', 'Posición estática de pie', ARRAY['Colócate de pie con los pies al ancho de las caderas.', 'Reparte el peso por igual y alarga la columna hacia arriba.', 'Activa suavemente glúteos y abdomen mientras respiras.', 'Evita bloquear las rodillas o adelantar la cabeza.']::text[], 'intermedio', 'Mejora la alineación corporal y la estabilidad del core y glúteos manteniendo una postura erguida consciente.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3659'),
('9cebf3fe-dfb1-5718-afc6-6f094702c17e', 'Contracción estática de cuádriceps', ARRAY['Siéntate o túmbate con la pierna extendida.', 'Aprieta el cuádriceps como si quisieras estirar del todo la rodilla.', 'Mantén la contracción unos segundos respirando con normalidad.', 'Evita levantar el talón o forzar la rodilla en hiperextensión.']::text[], 'intermedio', 'Activa el cuádriceps sin movimiento, útil para la rehabilitación y la conciencia muscular del muslo.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '11645'),
('216515fc-7941-5af9-b528-98d921e2b364', 'Lanzamiento de brazos estático', ARRAY['De pie con el core activo y los brazos relajados.', 'Lanza los brazos hacia delante y hacia atrás con un movimiento controlado.', 'Acompaña el gesto con la respiración sin perder la postura.', 'Evita encoger los hombros o mover solo los codos.']::text[], 'principiante', 'Moviliza la parte alta de la espalda y los hombros con un gesto dinámico que activa también el core.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4942'),
('76310e3e-24b3-523c-8eda-eac1fa79e009', 'Carrera en bicicleta fija', ARRAY['Ajusta la altura y la posición del asiento para asegurar una alineación correcta.', 'Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.', 'Comienza a pedalear a un ritmo cómodo.', 'Mantén un ritmo constante y aumenta la resistencia según lo desees.', 'Activa los músculos del core para mantener la estabilidad y una postura correcta.', 'Continúa pedaleando durante la duración deseada de tu entrenamiento.', 'Disminuye gradualmente la resistencia y reduce la velocidad antes de detenerte por completo.', 'Estira las piernas y enfría después del entrenamiento.']::text[], 'principiante', 'Trabaja el sistema cardiovascular y la resistencia con las piernas en movimiento continuo, ideal para calentar o hacer cardio sin impacto.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2138'),
('fd5ef717-0c51-50ad-859d-9c7219816d54', 'Caminata en bicicleta fija', ARRAY['Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta.', 'Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles.', 'Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado.', 'Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas.', 'Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular.', 'Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia.', 'Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación.']::text[], 'principiante', 'Activa el corazón y las piernas a ritmo suave y constante, perfecta para calentar o recuperar sin castigar las articulaciones.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0798'),
('892069bb-fb9f-54ab-be0e-4105d3cfc3d2', 'Halo con mazo de acero', ARRAY['Sujeta el mazo por el mango con ambas manos y llévalo a la altura del pecho.', 'Dibuja un círculo amplio alrededor de la cabeza, pasando el peso cerca de la nuca.', 'Mantén el core apretado y la espalda recta durante todo el recorrido.', 'Controla el tempo y evita arquear la zona lumbar al pasar el mazo por detrás.']::text[], 'intermedio', 'Moviliza hombros y manguito rotador mientras el core estabiliza el peso, mejorando control y fuerza en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10411'),
('2d39a859-03eb-5c74-9145-04a382b7e2c1', 'Sentadilla con mazo de acero', ARRAY['Coloca el mazo sobre los hombros o con los brazos extendidos al frente.', 'Separa los pies a la anchura de los hombros y baja la cadera hacia atrás.', 'Desciende hasta que los muslos queden paralelos al suelo sin perder la espalda recta.', 'Empuja con los talones para subir y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos y core mientras el mazo en alto exige estabilidad y control postural en todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10410'),
('4a3308a2-1ce7-530e-87af-62d24be2889b', 'Paso lateral desde sentadilla', ARRAY['Baja a una sentadilla con los pies a la anchura de los hombros.', 'Desde abajo, da un paso lateral amplio con un pie y mantén el peso repartido.', 'Vuelve al centro y repite hacia el otro lado sin perder la posición baja.', 'Mantén el pecho alto y evita que la rodilla del pie que se mueve colapse hacia dentro.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con un trabajo lateral que activa aductores y flexores de cadera, mejorando estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8374'),
('df4c3003-1d13-5330-8648-c4c90df7d947', 'Subida de escalón', ARRAY['Ponte frente a un escalón bajo y estable.', 'Apoya un pie completo y sube empujando con esa pierna hasta extender la cadera.', 'Baja despacio controlando el movimiento y alterna las piernas.', 'No te impulses con la pierna de abajo y mantén el tronco erguido.']::text[], 'intermedio', 'Fortalece piernas y glúteos subiendo peldaños, un gesto funcional que mejora potencia y equilibrio en el día a día.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '11450'),
('0230c490-8dd9-5ba4-afbb-13fe210fa5af', 'Subida al cajón cruzada', ARRAY['Colócate de lado o frente a un cajón estable.', 'Sube apoyando un pie y lleva la rodilla contraria hacia el codo opuesto.', 'Gira el tronco de forma controlada sin perder el equilibrio.', 'Baja con control y alterna los lados evitando giros bruscos.']::text[], 'intermedio', 'Combina trabajo de piernas con rotación del tronco, activando oblicuos y mejorando coordinación y resistencia cardiovascular.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0799'),
('97ea3421-233e-5126-a2b0-b9f48793f7ff', 'Subida a la silla', ARRAY['Coloca una silla firme contra la pared para que no se mueva.', 'Apoya un pie entero en el asiento y empuja para subir extendiendo la cadera.', 'Mantén el tronco erguido y el core activo durante la subida.', 'Baja despacio y evita impulsarte con la pierna que queda en el suelo.']::text[], 'intermedio', 'Ejercicio funcional que fortalece cuádriceps, glúteos y gemelos usando una silla estable como apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3444'),
('265f7a97-c48c-56b8-b96e-7a8da5c2b521', 'Subida al cajón con giro de codo a rodilla', ARRAY['Sitúate frente a un cajón estable con los pies juntos.', 'Sube apoyando un pie y lleva la rodilla contraria hacia el codo opuesto.', 'Gira el tronco de forma fluida manteniendo el equilibrio sobre la pierna de apoyo.', 'Baja con control y alterna los lados sin acelerar en exceso.']::text[], 'intermedio', 'Trabaja piernas y oblicuos con un gesto cruzado que eleva la frecuencia cardiaca y mejora la coordinación global.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0800'),
('7e8f6553-2259-5486-995a-8d132e8ec053', 'Jalón con paso atrás', ARRAY['De pie, da un paso atrás mientras llevas los brazos hacia arriba como si agarraras una barra.', 'Tira de los codos hacia abajo y atrás juntando las escápulas.', 'Aterriza con control flexionando ligeramente la rodilla de atrás.', 'Evita encoger los hombros y mantén el core firme durante el tirón.']::text[], 'intermedio', 'Combina tirón de dorsal con desplazamiento, activando espalda, core y piernas en un gesto explosivo y coordinado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6017'),
('d53d7ad9-9138-5d95-b816-61f6bae4eb52', 'Sentadilla de descenso', ARRAY['De pie con los pies a la anchura de los hombros.', 'Baja la cadera despacio como si te sentaras, controlando el descenso.', 'Mantén el pecho alto y las rodillas alineadas con los pies.', 'Sube empujando con los talones y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un descenso controlado que mejora la estabilidad de rodilla y el control excéntrico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4256'),
('6f9fc80c-44f4-5608-a05a-d62f5fa4f44a', 'Isométrico de core asistido con palo', ARRAY['Sujeta el palo con ambas manos frente al pecho o apoyado en el suelo.', 'Activa el abdomen y mantén la posición isométrica sin mover la cadera.', 'Respira de forma continua sin bloquear el aire.', 'Evita arquear la zona lumbar y mantén el core apretado todo el tiempo.']::text[], 'intermedio', 'Activa abdomen y oblicuos manteniendo una posición estable con ayuda de un palo, mejorando control y resistencia del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '5399'),
('4a076810-fc7e-54c9-bd03-f83fca2f7529', 'Flexión de hombro de pie asistida con palo', ARRAY['De pie, sujeta el palo con ambas manos frente al cuerpo.', 'Eleva los brazos hacia delante y arriba guiando con el palo.', 'Sube hasta donde llegues sin dolor y mantén unos segundos.', 'Evita arquear la espalda y baja de forma controlada.']::text[], 'principiante', 'Mejora la movilidad del hombro guiando el brazo con un palo, liberando tensión y ganando rango de flexión.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9980'),
('047db6ce-978c-50a5-b51e-45568616b5ee', 'Rotación interna de hombro de pie asistida con palo', ARRAY['De pie, sujeta el palo por detrás de la espalda con ambas manos.', 'Lleva el palo hacia un lado para rotar el hombro hacia dentro.', 'Mantén el codo pegado al cuerpo y el tronco recto.', 'Trabaja dentro de un rango sin dolor y evita forzar la articulación.']::text[], 'principiante', 'Gana movilidad interna de hombro con ayuda del palo, mejorando el rango articular y la salud del manguito rotador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9989'),
('8cc3b9c3-58cc-578e-bb43-64c6563d5603', 'Estiramiento de dorsales con palo', ARRAY['Sujeta el palo con ambas manos por delante, a la altura de los hombros.', 'Empuja el palo hacia delante mientras redondeas ligeramente la espalda alta.', 'Mantén el estiramiento entre veinte y treinta segundos respirando despacio.', 'Evita encoger los hombros hacia las orejas durante todo el movimiento.']::text[], 'principiante', 'Alarga la musculatura de la espalda y abre los hombros, ideal para descargar tensión tras estudiar o entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5400'),
('a74839fd-39a5-5c41-9a43-95e0715ca138', 'Estiramiento de zancada con elevación sobre la cabeza y palo', ARRAY['Da un paso largo y baja la rodilla trasera hacia el suelo.', 'Sujeta el palo con las manos y elévalo por encima de la cabeza.', 'Aprieta el glúteo de la pierna de atrás y mantén veinte segundos.', 'No arquees la zona lumbar: mantén las costillas abajo y respira.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera mientras moviliza hombros, útil antes o después de piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5402'),
('95348c88-b481-5e40-809f-7b3f71f510d2', 'Elevación frontal acostado con palo', ARRAY['Túmbate boca arriba con el palo sujeto con ambas manos sobre el pecho.', 'Sube el palo hacia arriba hasta donde llegues sin dolor.', 'Baja despacio controlando el movimiento y sin despegar la espalda.', 'Evita compensar arqueando la lumbar o encogiendo los hombros.']::text[], 'principiante', 'Moviliza el hombro y activa el deltoides anterior con control, útil para calentar antes de empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10589'),
('0605967f-fd82-5129-b488-458ac7b0eba9', 'Estiramiento de tríceps acostado a un brazo con palo', ARRAY['Túmbate boca arriba con un brazo flexionado y la mano detrás de la cabeza.', 'Con la otra mano sujeta el palo y empuja suavemente el codo hacia abajo.', 'Mantén el estiramiento veinte segundos sin forzar y cambia de lado.', 'No eleves el hombro ni arquees la espalda para ganar recorrido.']::text[], 'principiante', 'Relaja el tríceps y la parte posterior del hombro, muy útil tras sesiones de empuje o muchas horas sentado.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10740'),
('9032783c-8ce0-5d79-951c-4150a1fb7830', 'Estiramiento de sentadilla sumo completa sobre la cabeza con palo', ARRAY['Separa los pies más que la anchura de los hombros con las puntas hacia fuera.', 'Baja en sentadilla profunda sujetando el palo por encima de la cabeza.', 'Mantén la espalda recta y empuja las rodillas hacia fuera.', 'No dejes que los talones se despeguen ni que la lumbar se curve.']::text[], 'principiante', 'Abre aductores y caderas mientras estira hombros, perfecto para mejorar la sentadilla profunda.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5407'),
('32aff829-96dd-5382-bb15-d87f4d43d5ce', 'Estiramiento de paso alrededor con palo', ARRAY['Sujeta el palo con las manos separadas y los brazos estirados.', 'Pasa el palo por delante y por detrás del cuerpo en círculo.', 'Hazlo despacio y sin dolor, respirando de forma continua.', 'Evita encoger los hombros o forzar si notas pinchazos.']::text[], 'principiante', 'Moviliza hombros y cintura escapular con un gesto circular, útil para soltar tensión del tren superior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5404'),
('cd9a9847-227c-560c-8c58-25d5fae502f6', 'Movilización de hombro en abducción con palo', ARRAY['Sujeta el palo con ambas manos delante del cuerpo.', 'Eleva el brazo afectado hacia el lado empujando con la otra mano.', 'Sube hasta donde llegues sin dolor y baja controlando.', 'No rotes el tronco ni eleves el hombro para compensar.']::text[], 'principiante', 'Gana rango en la elevación lateral del brazo y mejora la salud del hombro antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9184'),
('3679d380-99dd-5467-b087-c6ebce2b80ee', 'Movilización de hombro en abducción detrás de la espalda', ARRAY['Coloca el palo detrás de la espalda sujeto con ambas manos.', 'Lleva el brazo hacia el lado separándolo del cuerpo con ayuda del palo.', 'Mantén el codo cerca del tronco y sube sin dolor.', 'Evita arquear la espalda o forzar el hombro hacia arriba.']::text[], 'principiante', 'Mejora la rotación interna y la movilidad posterior del hombro, útil para press y dominadas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10935'),
('897606d6-785f-58a2-a6ae-ae5245e04e29', 'Rotación de hombro con palo sobre la cabeza', ARRAY['Sujeta el palo por encima de la cabeza con las manos separadas.', 'Rota los brazos llevando el palo hacia un lado y luego al otro.', 'Mantén los codos ligeramente flexionados y el core activo.', 'No dejes que la lumbar se arquee ni que los hombros suban.']::text[], 'principiante', 'Moviliza la cintura escapular en rotación, mejorando la coordinación y el rango del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10936'),
('52a3d57a-0b0b-5d33-a191-1d9aa1ad3dbd', 'Estiramiento de hombros con palo', ARRAY['Sujeta el palo por delante con las manos más anchas que los hombros.', 'Lleva el palo hacia delante y luego hacia arriba con suavidad.', 'Mantén el estiramiento veinte segundos respirando profundo.', 'Evita encoger el cuello o bloquear la respiración.']::text[], 'principiante', 'Relaja deltoides y pectoral, aliviando la tensión acumulada por apuntes y horas de ordenador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5401'),
('09fea0b8-5ac5-5072-aee6-cdfd9cac5329', 'Estiramiento de flexión lateral con palo', ARRAY['De pie, sujeta el palo por encima de la cabeza con ambas manos.', 'Inclínate hacia un lado manteniendo la cadera estable.', 'Aguanta veinte segundos y cambia de lado sin rebotar.', 'No rotes el tronco ni fuerces más allá de lo cómodo.']::text[], 'principiante', 'Estira oblicuos y costados, ayudando a liberar tensión lumbar y mejorar la movilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5405'),
('670b5d57-fb5d-5b4b-bba7-5aac941008f5', 'Estiramiento de flexión de lateral a frontal con palo', ARRAY['De pie con el palo sobre la cabeza, inclínate hacia un lado.', 'Lleva el palo al frente flexionando la cadera con la espalda recta.', 'Vuelve despacio al centro y repite hacia el otro lado.', 'Evita redondear la espalda o bloquear las rodillas.']::text[], 'principiante', 'Combina flexión lateral y frontal para movilizar la columna y estirar isquios y costados.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5406'),
('d2be9a07-d4e4-5fa3-a758-605cb631d50e', 'Elevación frontal de pie con palo', ARRAY['De pie, sujeta el palo delante de los muslos con ambas manos.', 'Eleva los brazos estirados hasta la altura de los hombros.', 'Baja despacio controlando el movimiento y sin balancearte.', 'No uses impulso de cadera ni encojas los hombros.']::text[], 'principiante', 'Moviliza y activa el deltoides anterior, útil como calentamiento para press y empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9187'),
('7f5c8d60-830b-5866-af9e-efe9a055dbd9', 'Movilización de hombro en extensión de pie con palo', ARRAY['De pie, sujeta el palo detrás del cuerpo con ambas manos.', 'Lleva los brazos hacia atrás y arriba sin forzar.', 'Mantén el pecho abierto y la mirada al frente.', 'Evita arquear la lumbar o sacar las costillas.']::text[], 'principiante', 'Mejora la extensión del hombro y abre el pecho, útil tras muchas horas con los brazos adelante.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9180'),
('fc5e58e8-dcef-55cb-b68b-bca6b63bb17d', 'Movilización de hombro en rotación externa de pie con palo', ARRAY['De pie, sujeta el palo con el codo pegado al costado y flexionado noventa grados.', 'Rota el antebrazo hacia fuera empujando con la otra mano.', 'Vuelve despacio al centro y repite sin soltar el codo.', 'No separes el codo del tronco ni gires el cuerpo.']::text[], 'principiante', 'Refuerza la movilidad rotatoria del hombro y activa el manguito rotador antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9181'),
('b0bb25c9-8736-5af7-a74f-375c0c1c5893', 'Estiramiento de giro de pie con palo', ARRAY['Colócate de pie con los pies a la anchura de las caderas y sujeta el palo sobre los hombros.', 'Gira el tronco despacio hacia un lado hasta notar el estiramiento, sin mover las caderas.', 'Mantén la posición entre 15 y 30 segundos respirando con calma.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita arquear la espalda o forzar el giro más allá de donde llegas cómodo.']::text[], 'principiante', 'Moviliza la columna y los oblicuos, alivia la rigidez del tronco y mejora la rotación torácica antes o después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5403'),
('f02a18b2-c1a5-5632-90e5-f075e5193357', 'Relajación del subescapular con palo', ARRAY['Sujeta el palo con ambas manos por delante del cuerpo, a la altura del pecho.', 'Lleva el brazo afectado hacia el hombro contrario con ayuda del palo, sin elevar el hombro.', 'Mantén el estiramiento suave entre 20 y 30 segundos sin dolor agudo.', 'Respira despacio y relaja el hombro en cada espiración.', 'Evita tirar en exceso o encoger el hombro hacia la oreja.']::text[], 'principiante', 'Libera tensión en el hombro y la rotura del manguito rotador, mejorando la movilidad y reduciendo molestias en la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6811'),
('59bfc3df-3a7f-53c0-87fd-b18856f16b20', 'Estiramiento de zancada con giro y palo', ARRAY['Da un paso largo hacia delante y baja la rodilla trasera hacia el suelo.', 'Sujeta el palo sobre los hombros y gira el tronco hacia el lado de la pierna adelantada.', 'Mantén la posición entre 20 y 30 segundos respirando con normalidad.', 'Vuelve al centro y cambia de pierna.', 'Evita que la rodilla delantera pase muy por delante del pie o que la espalda se arquee.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera mientras moviliza oblicuos y glúteos, útil para preparar el tren inferior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5408'),
('a0a4506c-e7d8-5b67-8bb4-fca95dde7efa', 'Maltesa abierta', ARRAY['Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta.', 'Separa bien las piernas, formando una posición a horcajadas.', 'Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo.', 'Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Isométrico avanzado de empuje que exige gran fuerza de core, hombros y pecho manteniendo el cuerpo en suspensión.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3314'),
('537f7691-7a87-5b7b-be79-dd614c4901ac', 'Planche abierta', ARRAY['Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados.', 'Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos.', 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.', 'Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Isométrico de calistenia que trabaja el core, hombros y tríceps manteniendo el cuerpo horizontal sobre las manos.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3298'),
('934a76db-72c0-5af8-9690-573ba86e6a6e', 'Postura del ángulo recto', ARRAY['Siéntate en el suelo con las piernas estiradas y separadas formando una V amplia.', 'Inclina el tronco hacia delante desde la cadera manteniendo la espalda lo más recta posible.', 'Lleva las manos hacia las piernas o el suelo según tu flexibilidad.', 'Mantén entre 30 y 60 segundos respirando despacio.', 'Evita redondear la espalda o rebotar para bajar más.']::text[], 'intermedio', 'Estiramiento de isquiotibiales y aductores que mejora la flexibilidad de la parte posterior de la pierna y la cadera.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4402'),
('ad1057c9-07d1-5b53-a229-adba42d55c16', 'Estiramiento de pecho con brazos rectos hacia atrás', ARRAY['De pie, entrelaza las manos detrás de la espalda con los brazos estirados.', 'Lleva los brazos hacia atrás y eleva ligeramente el pecho sin arquear la zona lumbar.', 'Mantén el estiramiento entre 20 y 30 segundos respirando con calma.', 'Relaja y repite si lo necesitas.', 'Evita sacar las costillas hacia delante o encoger los hombros.']::text[], 'principiante', 'Abre el pecho y los hombros, contrarrestando la postura encorvada y mejorando la movilidad de la cintura escapular.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1787'),
('e69802d3-99ea-51c3-8656-b73232894522', 'Curl de pierna a una pierna con cadera recta en balón', ARRAY['Túmbate boca abajo con las caderas sobre el balón y las manos apoyadas en el suelo.', 'Estira una pierna y apoya el empeine de la otra sobre el balón.', 'Flexiona la rodilla de apoyo llevando el talón hacia el glúteo y vuelve despacio.', 'Mantén la cadera recta y el abdomen activo durante todo el movimiento.', 'Evita arquear la lumbar o perder el equilibrio por mover la cadera.']::text[], 'principiante', 'Fortalece isquiotibiales y glúteos trabajando el control del core sobre el balón de estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9047'),
('b357475d-ef6d-5fe6-9f4e-e324da90786d', 'Bicho muerto con piernas rectas', ARRAY['Túmbate boca arriba con los brazos hacia el techo y las piernas estiradas.', 'Baja despacio un brazo y la pierna contraria sin despegar la lumbar del suelo.', 'Vuelve al centro y alterna el otro lado.', 'Respira de forma continua y mantén el abdomen activo.', 'Evita que la espalda baja se arquee o que los movimientos sean rápidos.']::text[], 'intermedio', 'Refuerza el core y la zona lumbar enseñando a mantener la estabilidad mientras se mueven brazos y piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4840'),
('d5a477dd-6c31-51d8-8ea4-dd709cd5c2d6', 'Puente de glúteos con pierna recta', ARRAY['Túmbate boca arriba con una rodilla flexionada y la otra pierna estirada.', 'Empuja con el pie apoyado y eleva la cadera hasta formar una línea recta.', 'Aprieta el glúteo arriba y baja despacio sin apoyar del todo.', 'Mantén la pierna estirada alineada con el tronco durante todo el movimiento.', 'Evita arquear la lumbar o girar la cadera hacia un lado.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales mejorando la extensión de cadera y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7419'),
('952acfbe-ff2c-5255-86d5-a16886a1ab2e', 'Puente de cadera con piernas rectas', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y piernas.', 'Mantén un segundo arriba apretando los glúteos y baja despacio.', 'Mantén el abdomen activo para no arquear la lumbar.', 'Evita separar los talones del suelo o perder la línea del cuerpo.']::text[], 'intermedio', 'Trabaja glúteos, isquiotibiales y core elevando la cadera con las piernas estiradas para ganar fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4255'),
('f0cb751c-5b92-5f69-87cb-52594b739851', 'Patada trasera con pierna recta (de rodillas)', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.', 'Estira una pierna y elévala hacia atrás hasta la altura de la cadera.', 'Aprieta el glúteo arriba y baja despacio sin tocar el suelo.', 'Mantén el abdomen activo y la espalda neutra durante todo el movimiento.', 'Evita arquear la lumbar o girar la cadera al subir la pierna.']::text[], 'intermedio', 'Aísla el glúteo y el isquiotibial trabajando la extensión de cadera con control y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3114'),
('2c79775e-7808-5f1a-93a9-3f93b1a6de74', 'Abductor de cadera externo con pierna recta', ARRAY['Túmbate de lado con las piernas rectas y apiladas una sobre la otra.', 'Coloca el brazo de abajo bajo la cabeza para apoyarte.', 'Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.', 'Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece los abductores y glúteos para mejorar la estabilidad de la cadera y prevenir molestias en la zona.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1427'),
('a19d08d5-3429-5110-a7e9-eb59a3eb6be2', 'Abdominal con piernas rectas', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos hacia delante o al pecho.', 'Sube el tronco despacio hasta sentarte, manteniendo las piernas en el suelo.', 'Baja de forma controlada sin dejarte caer de golpe.', 'Respira exhalando al subir e inhalando al bajar.', 'Evita tirar del cuello con las manos o usar impulso para subir.']::text[], 'intermedio', 'Trabaja el recto abdominal y los flexores de cadera subiendo el tronco con las piernas estiradas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4008'),
('9df11b90-8fd0-53ae-a04c-16406a0aaab1', 'Barra de Apolo', ARRAY['Colócate frente a la barra con los pies a la anchura de las caderas y agarra el eje grueso.', 'Baja las caderas, mantén la espalda recta y el pecho arriba antes de tirar.', 'Empuja con las piernas y extiende la cadera para levantar la barra pegada al cuerpo.', 'Bloquea arriba con los hombros y baja de forma controlada.', 'Evita redondear la espalda o tirar con los brazos antes que con las piernas.']::text[], 'intermedio', 'Ejercicio de strongman que exige gran fuerza de agarre, hombros y cadena posterior para levantar una barra gruesa.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2733'),
('c6688225-eccb-5916-a793-5406f83eccf8', 'Arrastre de cuerda mano sobre mano', ARRAY['Colócate de pie con los pies a la anchura de los hombros y agarra la cuerda con ambas manos.', 'Tira alternando mano sobre mano mientras llevas el peso hacia ti sin mover el torso.', 'Mantén el core firme y la espalda neutra durante todo el recorrido.', 'Evita encorvar la espalda o tirar solo con los brazos; usa también la espalda.']::text[], 'intermedio', 'Trabaja la espalda y el agarre tirando de una cuerda, mejorando la fuerza funcional y la resistencia de brazos y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2709'),
('2853f3a0-29dd-5fce-bd97-00726e80df76', 'Piedras de atlas', ARRAY['Colócate frente al peso con los pies abiertos y el pecho hacia delante.', 'Agarra el disco o piedra con ambas manos y pega el objeto al cuerpo.', 'Empuja con las piernas y extiende la cadera para levantarlo, manteniendo la espalda recta.', 'Evita redondear la espalda o tirar solo con los brazos al subir el peso.']::text[], 'intermedio', 'Levantar y cargar una piedra o disco pesado fortalece glúteos, isquios y espalda baja, mejorando la potencia y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2724'),
('037cc459-8124-5a0f-9a5a-13b90de13377', 'Paseo del granjero con barra', ARRAY['Agarra la barra con ambas manos y levántala extendiendo piernas y cadera.', 'Camina con pasos cortos y firmes manteniendo el pecho alto y los hombros atrás.', 'Respira con normalidad y no bloquees la respiración durante el recorrido.', 'Evita inclinarte hacia un lado o dejar caer los hombros al caminar.']::text[], 'intermedio', 'Caminar con una barra cargada fortalece el agarre, los trapecios y el core, mejorando la resistencia y la estabilidad general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2734'),
('56b2a2c2-4403-5704-a4cc-f08daff233eb', 'Volteo de coche', ARRAY['Colócate agachado frente al objeto con los pies firmes y las manos bien agarradas.', 'Empuja con las piernas y extiende la cadera para levantar un extremo del objeto.', 'Acompaña el movimiento con el torso y los brazos hasta completar el volteo.', 'Evita redondear la espalda o tirar solo con los brazos sin usar las piernas.']::text[], 'intermedio', 'Empujar y voltear un objeto pesado activa glúteos, piernas y espalda, desarrollando potencia y fuerza funcional en todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3317'),
('8de73d68-43f5-5987-adca-d52ff9bcf54e', 'Círculo de Conan', ARRAY['Agarra el disco con ambas manos y sujétalo delante del pecho.', 'Camina en círculo con pasos cortos manteniendo el torso erguido.', 'Mantén el core apretado y respira de forma constante durante el recorrido.', 'Evita inclinarte hacia atrás o dejar que el peso te desequilibre.']::text[], 'intermedio', 'Caminar en círculo con un peso delante fortalece la espalda, el core y los glúteos, mejorando la estabilidad y la resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2716'),
('3a9513c5-5990-5dfa-9f60-9b9b07a9c58a', 'Sostén en crucifijo', ARRAY['Sujeta un disco en cada mano con los brazos extendidos en cruz.', 'Mantén los hombros abajo y el core firme sin arquear la espalda.', 'Respira con normalidad y aguanta la posición el tiempo indicado.', 'Evita subir los hombros o bloquear la respiración durante el sostén.']::text[], 'intermedio', 'Mantener los brazos en cruz con peso fortalece los hombros, la espalda alta y el agarre, mejorando la resistencia isométrica.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2717'),
('7511a148-427d-58f8-9aec-c9fabd160f94', 'Peso muerto', ARRAY['Colócate con los pies a la anchura de la cadera y la barra pegada a las espinillas.', 'Agarra la barra y empuja el suelo con las piernas mientras extiendes la cadera.', 'Mantén la espalda recta y la barra cerca del cuerpo durante todo el recorrido.', 'Evita redondear la espalda o tirar con los brazos en lugar de con las piernas.']::text[], 'intermedio', 'Levantar la barra desde el suelo fortalece glúteos, isquios y espalda baja, mejorando la potencia y la fuerza general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2729'),
('289855b7-a82c-596f-aaff-856756a7dfe0', 'Cargada y envión a un brazo con mancuerna', ARRAY['Coloca la mancuerna entre los pies y agáchate con la espalda recta.', 'Tira de la mancuerna hacia el hombro con un movimiento rápido de piernas y cadera.', 'Extiende el brazo por encima de la cabeza con un empuje de piernas.', 'Evita redondear la espalda o perder el control de la mancuerna al subirla.']::text[], 'avanzado', 'Movimiento explosivo que trabaja hombros, piernas y core, mejorando la potencia y la coordinación de todo el cuerpo.', ARRAY['Potencia y Explosividad', 'Fuerza Máxima']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 6.0, 'olympic', '2732'),
('35b4f505-1b6f-55d4-a8a2-f06c10e41e7e', 'Dedos de Fingal', ARRAY['Colócate frente al objeto con los pies firmes y las manos preparadas.', 'Agarra el objeto y empuja con las piernas para levantarlo.', 'Acompaña el volteo con las manos y el torso hasta dejarlo caer.', 'Evita usar solo los brazos o perder el control del objeto al soltarlo.']::text[], 'intermedio', 'Voltear un objeto pesado con las manos fortalece antebrazos, agarre y muñecas, mejorando la fuerza de prensión y el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3306'),
('427088a2-a9d2-5bf4-9d15-fe8f1a561b6d', 'Sentadilla frontal al pecho', ARRAY['Sujeta el disco contra el pecho con ambas manos y los codos altos.', 'Baja flexionando rodillas y cadera manteniendo el pecho erguido.', 'Empuja con los talones para subir y aprieta el core durante todo el movimiento.', 'Evita inclinarte hacia delante o dejar que los codos bajen.']::text[], 'intermedio', 'Sentadilla con el peso al pecho que trabaja cuádriceps, glúteos y core, mejorando la fuerza y la estabilidad del torso.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2728'),
('55e8b0e2-6f56-5d06-b7a3-9a877ed75316', 'Sostén de Hércules', ARRAY['Sujeta el disco con ambas manos a la altura del pecho o por encima.', 'Mantén los hombros abajo y el core firme sin arquear la espalda.', 'Respira con normalidad y aguanta la posición el tiempo indicado.', 'Evita subir los hombros o bloquear la respiración durante el sostén.']::text[], 'intermedio', 'Mantener un peso en alto fortalece antebrazos, agarre y espalda alta, mejorando la resistencia isométrica y la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2726'),
('4afa3e27-8222-5980-8d5c-385ebf05d519', 'Piedras de Hood', ARRAY['Colócate frente al peso con los pies abiertos y el pecho hacia delante.', 'Agarra el disco con ambas manos y pégalo al cuerpo.', 'Empuja con las piernas y extiende la cadera para levantarlo, manteniendo la espalda recta.', 'Evita redondear la espalda o tirar solo con los brazos al subir el peso.']::text[], 'intermedio', 'Levantar y cargar un peso pesado fortalece glúteos, isquios y espalda baja, mejorando la potencia y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2722'),
('b83ce0f7-da81-5d30-9ba8-cc1110f28222', 'Cruz de Islandia', ARRAY['Sujeta un disco en cada mano con los brazos extendidos en cruz.', 'Mantén los hombros abajo y el core firme sin arquear la espalda.', 'Respira con normalidad y aguanta la posición el tiempo indicado.', 'Evita subir los hombros o bloquear la respiración durante el sostén.']::text[], 'intermedio', 'Sostener peso con los brazos en cruz fortalece hombros, espalda alta y agarre, mejorando la resistencia isométrica y la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2714'),
('3d53a90f-ec46-517b-b033-f7be45ee4afd', 'Press de bloque de hierro', ARRAY['Sujeta el disco a la altura del pecho con ambas manos y los codos altos.', 'Empuja el peso por encima de la cabeza extendiendo los brazos.', 'Mantén el core firme y la espalda recta durante todo el movimiento.', 'Evita arquear la espalda o bloquear la respiración al empujar.']::text[], 'intermedio', 'Empujar un peso por encima de la cabeza trabaja hombros, tríceps y core, mejorando la fuerza y la estabilidad del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2713'),
('72fe1d8f-312f-533d-999c-1f7d0706e4d6', 'Lanzamiento de barril', ARRAY['Colócate frente al barril con los pies firmes y las manos preparadas.', 'Agáchate y agarra el barril con ambas manos pegándolo al cuerpo.', 'Extiende piernas y cadera con fuerza para lanzarlo hacia arriba.', 'Evita redondear la espalda o lanzar solo con los brazos sin usar las piernas.']::text[], 'intermedio', 'Lanzar un objeto pesado por encima de la cabeza activa glúteos, piernas y espalda, desarrollando potencia y fuerza explosiva.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3307'),
('08ee7aa5-f496-5b29-ba9a-7a25d7a1c621', 'Carga de piedra', ARRAY['Colócate frente al peso con los pies a la anchura de los hombros y el pecho alto.', 'Agáchate empujando la cadera atrás y agarra el disco con fuerza.', 'Extiende las piernas y la cadera de golpe para subir el peso cerca del cuerpo.', 'Evita redondear la espalda: mantén el pecho arriba durante todo el recorrido.']::text[], 'intermedio', 'Fortalece glúteos, isquiotibiales y espalda baja al levantar y cargar peso desde el suelo, mejorando la potencia de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2721'),
('53e48135-5710-5abe-8e32-a7cb79ba2ca9', 'Levantamiento de tronco', ARRAY['Sujeta el disco a la altura del pecho con los codos bajo el peso.', 'Aprieta el core y los glúteos antes de iniciar el empuje.', 'Empuja el peso hacia arriba hasta extender los brazos, sin arquear la espalda.', 'Baja el peso de forma controlada hasta el pecho evitando dejarlo caer.']::text[], 'intermedio', 'Trabaja hombros, tríceps y espalda alta al empujar un peso desde el pecho hasta arriba, ganando fuerza de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2707'),
('602aaa55-ddc5-5be6-b577-9f2df1e56522', 'Mas wrestling', ARRAY['Agarra el disco con ambas manos y adopta una postura estable con las piernas abiertas.', 'Tira con fuerza manteniendo los codos cerca del cuerpo.', 'Aprieta el core y resiste la tracción del contrario sin perder la postura.', 'Evita tirar solo con los brazos: usa también espalda y piernas.']::text[], 'intermedio', 'Desarrolla la fuerza de agarre y antebrazos al tirar y resistir con las manos, útil para deportes de fuerza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2708'),
('12f4ccf2-6087-5737-931c-dea2065c6471', 'Escaleras de poder', ARRAY['Coloca el peso en una posición segura y sujétalo con firmeza.', 'Sube el primer escalón apoyando todo el pie y empuja con la pierna de abajo.', 'Mantén el pecho alto y el core apretado durante la subida.', 'Baja de forma controlada sin soltar el peso de golpe.']::text[], 'intermedio', 'Potencia cuádriceps y glúteos al subir escalones cargando peso, mejorando la fuerza de empuje de piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2725'),
('1c80fb49-443a-56b8-a0ba-c9466fb526d7', 'Caminata con saco de arena', ARRAY['Levanta el saco con la espalda recta y colócalo sobre los hombros o abrazado al pecho.', 'Camina con pasos cortos y firmes, manteniendo el pecho alto.', 'Aprieta el core y respira de forma constante durante el recorrido.', 'Evita inclinarte hacia delante: mantén el peso cerca del cuerpo.']::text[], 'intermedio', 'Refuerza la espalda, el core y los glúteos al caminar cargando peso, mejorando la estabilidad y la resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2712'),
('d4dd13d4-18d3-5b8c-87af-386d3d0f3743', 'Acarreo de escudo', ARRAY['Abraza el disco contra el pecho con los codos pegados al cuerpo.', 'Aprieta el core y camina con pasos cortos y controlados.', 'Mantén la espalda recta y la mirada al frente.', 'Evita arquear la espalda o inclinarte hacia atrás por el peso.']::text[], 'intermedio', 'Fortalece la espalda y el core al transportar un peso abrazado, mejorando la estabilidad y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2727'),
('9209ffe0-8c6f-5fe4-95fc-e1b82a915e26', 'Sentadilla con plataforma', ARRAY['Colócate sobre la plataforma con los pies a la anchura de los hombros.', 'Sujeta el disco al pecho y baja la cadera como en una sentadilla.', 'Empuja con los talones para subir manteniendo el pecho alto.', 'Evita que las rodillas se metan hacia dentro durante el movimiento.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con una sentadilla sobre plataforma, mejorando la fuerza y la profundidad del movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2720'),
('6deb056b-f421-54f4-b15a-b2ee679241c8', 'Acarreo de tronco', ARRAY['Levanta el peso con la espalda recta y colócalo sobre los hombros.', 'Aprieta el core y camina con pasos firmes y controlados.', 'Mantén el pecho alto y la mirada al frente durante el recorrido.', 'Evita girar el tronco bruscamente mientras cargas el peso.']::text[], 'intermedio', 'Fortalece la espalda, los trapecios y el core al transportar un peso largo, mejorando la estabilidad y la fuerza global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2715'),
('9527e6b7-def4-5f42-84cf-3cb17fa7a647', 'Volteo de neumático', ARRAY['Agáchate con la espalda recta y agarra el neumático por abajo.', 'Empuja con las piernas y la cadera para levantarlo, pegándolo al cuerpo.', 'Cuando esté alto, empuja con los brazos para voltearlo.', 'Evita redondear la espalda: usa las piernas para iniciar el movimiento.']::text[], 'intermedio', 'Potencia glúteos, piernas y espalda al voltear un neumático, mejorando la fuerza explosiva de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2730'),
('3d2a404e-3b09-5cf6-992d-2b48236f52ee', 'Arrastre de camión', ARRAY['Sujeta la cuerda con ambas manos y adopta una postura inclinada hacia delante.', 'Empuja con las piernas y camina hacia atrás tirando de la cuerda.', 'Mantén el core apretado y la espalda recta durante el arrastre.', 'Evita tirar solo con los brazos: usa piernas y cadera.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y agarre al tirar de una carga pesada, mejorando la fuerza de tracción y la resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2710'),
('8bf4c92c-e235-52c8-8bb0-2c5c3d111a1e', 'Press vikingo', ARRAY['Sujeta el peso a la altura del pecho con los codos hacia abajo.', 'Aprieta el core y empuja el peso hacia arriba y adelante.', 'Extiende los brazos sin arquear la espalda y baja de forma controlada.', 'Evita bloquear la respiración: exhala al empujar.']::text[], 'intermedio', 'Fortalece hombros, tríceps y pecho superior al empujar un peso en diagonal, mejorando la potencia de empuje.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2719'),
('96464f29-2e46-564d-b314-cffb39ea027e', 'Peso a altura', ARRAY['Sujeta el peso con ambas manos y adopta una postura estable.', 'Agáchate ligeramente y usa piernas y cadera para impulsar el peso hacia arriba.', 'Extiende los brazos y acompaña el movimiento con la mirada.', 'Evita lanzar solo con los brazos: usa todo el cuerpo.']::text[], 'intermedio', 'Desarrolla espalda alta, hombros y piernas al lanzar un peso hacia arriba, mejorando la potencia y la coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2731'),
('35ddf0f2-3e06-5d6b-8072-8e6e93d65e0b', 'Carretilla', ARRAY['Agarra la carretilla con ambas manos y adopta una postura inclinada.', 'Empuja con las piernas y camina hacia delante con pasos cortos.', 'Mantén el core apretado y la espalda recta durante el recorrido.', 'Evita bloquear los codos: mantén los brazos ligeramente flexionados.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y core al empujar una carga, mejorando la fuerza de empuje y la resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2723'),
('02651aff-0053-5a2a-b8ef-cfe5b080abfd', 'Caminata con yugo', ARRAY['Coloca la barra sobre los trapecios y sujétala con las manos.', 'Aprieta el core y camina con pasos cortos y firmes.', 'Mantén el pecho alto y la mirada al frente durante el recorrido.', 'Evita inclinarte hacia delante o perder la postura por el peso.']::text[], 'intermedio', 'Fortalece trapecios, core y piernas al caminar con una barra cargada sobre los hombros, mejorando la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2735'),
('408c3298-1cb0-5dd6-aebb-c1d406a4002d', 'Sentadilla sumo al aire', ARRAY['Separa los pies más allá de la anchura de los hombros con las puntas hacia fuera.', 'Baja la cadera manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Empuja con los talones para subir y aprieta los glúteos arriba.', 'Evita que las rodillas se metan hacia dentro durante el descenso.']::text[], 'intermedio', 'Activa glúteos, aductores y cuádriceps con una sentadilla de pies abiertos, mejorando la movilidad y la fuerza de piernas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4936'),
('36322159-3496-5608-a6b0-13469d02c30d', 'Jalón alto de peso muerto sumo', ARRAY['Coloca los pies más anchos que los hombros con las puntas hacia fuera y agarra la barra con las manos en pronación.', 'Empuja el suelo con los talones y extiende las caderas para subir la barra pegada al cuerpo.', 'Cuando la barra llegue a la altura del pecho, tira de los codos hacia arriba y hacia fuera para completar el jalón.', 'Baja la barra controlando el movimiento hasta las rodillas y luego flexiona las caderas para volver al inicio.', 'Evita redondear la espalda y no uses los brazos para tirar antes de extender las caderas.']::text[], 'intermedio', 'Trabaja glúteos, isquios y espalda alta con un tirón explosivo que mejora la potencia y la coordinación de todo el cuerpo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1199'),
('dbdf0b78-3008-58f9-8d95-c386fb40fcbb', 'Sentadilla sumo', ARRAY['Separa los pies más allá de la anchura de los hombros y gira las puntas hacia fuera unos 45 grados.', 'Baja las caderas hacia atrás y abajo manteniendo el pecho alto y las rodillas alineadas con los pies.', 'Empuja el suelo con los talones para subir y aprieta los glúteos al final del recorrido.', 'Evita que las rodillas se metan hacia dentro y no despegues los talones del suelo.']::text[], 'intermedio', 'Activa glúteos y aductores con una sentadilla de base amplia que mejora la fuerza y la movilidad de la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1064'),
('b0aa894f-6886-5ad2-9868-4814e2260c61', 'Sentadilla sumo con toque al suelo', ARRAY['Abre los pies más que los hombros con las puntas hacia fuera y mantén la espalda recta.', 'Baja en sentadilla sumo hasta que las manos puedan tocar el suelo delante de ti.', 'Toca el suelo con las yemas sin redondear la espalda y vuelve a subir empujando con los talones.', 'Controla el descenso y evita rebotar en la posición baja para proteger las rodillas.']::text[], 'intermedio', 'Combina la sentadilla sumo con un toque al suelo que aumenta el rango de movimiento y la movilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4417'),
('08de5eca-e2a1-5bb0-aa5e-e04581c04ea8', 'Saludo al sol A', ARRAY['Empieza de pie con las manos al pecho y lleva los brazos arriba al inhalar.', 'Exhala y baja en flexión de cadera con las rodillas ligeramente flexionadas.', 'Inhala para alargar la espalda y exhala para llevar las manos al suelo y avanzar a plancha.', 'Baja en cuatro apoyos, inhala para abrir el pecho y exhala para volver a perro boca abajo.', 'Camina o salta los pies hacia las manos y sube con la espalda recta; evita bloquear las rodillas.']::text[], 'intermedio', 'Secuencia de yoga que estira isquios y espalda mientras activa hombros y core en un flujo continuo.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5980'),
('84fa7913-2201-564f-8748-e527cd83113f', 'Saludo al sol B', ARRAY['Desde de pie, flexiona las rodillas y sube los brazos al inhalar.', 'Exhala y baja en sentadilla con las manos al suelo, manteniendo el pecho abierto.', 'Inhala para estirar la espalda y exhala para avanzar a plancha y bajar en cuatro apoyos.', 'Inhala para abrir el pecho, exhala a perro boca abajo y da un paso al frente para volver a subir.', 'Coordina cada movimiento con la respiración y evita perder la alineación de la espalda.']::text[], 'intermedio', 'Flujo de yoga más dinámico que fortalece cuádriceps y glúteos y mejora la movilidad de hombros y cadera.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5981'),
('63f644e5-d95e-5640-9e9a-8a0707c49d09', 'Superman', ARRAY['Túmbate boca abajo con los brazos extendidos al frente y las piernas estiradas.', 'Eleva a la vez brazos, pecho y piernas del suelo sin forzar el cuello.', 'Mantén la posición dos segundos apretando glúteos y espalda, respirando con normalidad.', 'Baja despacio y evita arquear en exceso la zona lumbar o levantar la cabeza.']::text[], 'intermedio', 'Fortalece la musculatura profunda de la espalda y los glúteos, mejorando la postura y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3436'),
('d410b1d3-27e2-590f-b32b-0eb0ebf99360', 'Estiramiento de pecho tipo superman', ARRAY['Túmbate boca abajo con un brazo extendido hacia el lado formando una T.', 'Gira el cuerpo suavemente hacia el lado del brazo estirado hasta notar tensión en el pecho.', 'Mantén el estiramiento entre veinte y treinta segundos respirando despacio.', 'Cambia de lado sin forzar y evita levantar el hombro del suelo.']::text[], 'principiante', 'Estira el pectoral y la parte delantera del hombro para compensar posturas encorvadas y mejorar la apertura torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '4825'),
('7744b811-91a6-5569-b6e3-cbd6217d671f', 'Pulso de superman', ARRAY['Túmbate boca abajo con brazos y piernas extendidos.', 'Eleva brazos, pecho y piernas y mantén la posición alta.', 'Haz pequeños pulsos hacia arriba sin bajar del todo, con un ritmo constante.', 'Mantén el cuello neutro y evita arquear la zona lumbar en exceso.']::text[], 'intermedio', 'Versión dinámica que activa espalda baja y glúteos con pequeños pulsos para ganar resistencia postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10345'),
('afbbeb34-f1f2-5154-b0f9-8187b98a8c6d', 'Flexión superman', ARRAY['Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.', 'Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente.', 'Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial.', 'Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Variante de flexión que suma trabajo de espalda baja y glúteos, fortaleciendo pecho y core de forma global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0803'),
('4be54fa0-2af6-5ada-9f78-37f83c780e16', 'Remo superman', ARRAY['Túmbate boca abajo con los brazos extendidos al frente y las palmas hacia el suelo.', 'Eleva ligeramente el pecho y lleva los codos hacia atrás pegados al cuerpo.', 'Aprieta los omóplatos al final del tirón y mantén un segundo.', 'Baja los brazos controlando y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Refuerza la espalda alta y los romboides con un tirón que mejora la postura y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4939'),
('254a5062-88a3-5905-af49-e70da4b2c9d6', 'Remo superman con toalla', ARRAY['Túmbate boca abajo y sujeta una toalla con ambas manos por los extremos.', 'Eleva el pecho y tira de la toalla hacia el pecho llevando los codos atrás.', 'Aprieta los omóplatos y mantén la tensión un segundo.', 'Baja despacio y evita levantar la cabeza o arquear la zona lumbar.']::text[], 'intermedio', 'Añade resistencia con una toalla para intensificar el trabajo de espalda alta y estabilidad de los omóplatos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3559'),
('6616fa7b-5862-589e-80a1-dbff4c605616', 'Superman a flexión', ARRAY['Túmbate boca abajo con brazos extendidos y piernas estiradas.', 'Eleva brazos y piernas en superman y mantén un instante.', 'Apoya las manos bajo los hombros y empuja para subir a plancha.', 'Haz una flexión controlada y vuelve a bajar al superman.', 'Mantén el core activo y evita que la cadera se hunda en la flexión.']::text[], 'intermedio', 'Encadena el superman con una flexión para trabajar espalda, pecho y core en un solo movimiento global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10050'),
('1f553ce6-ccf3-50b4-b442-0d26fa6041cb', 'Superman W', ARRAY['Túmbate boca abajo con los codos flexionados y las manos cerca de la cabeza formando una W.', 'Eleva el pecho y lleva los codos hacia atrás apretando los omóplatos.', 'Mantén la posición dos segundos sin levantar la cabeza.', 'Baja despacio y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Activa espalda alta y trapecios con los brazos en forma de W, mejorando la postura y la salud escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5049'),
('01857575-ffdd-561c-a6a9-d84208965453', 'Superman de W a Y', ARRAY['Túmbate boca abajo con los brazos en W y el pecho ligeramente elevado.', 'Desliza los brazos hacia delante hasta formar una Y manteniendo el pecho alto.', 'Vuelve a la posición W controlando el movimiento.', 'Mantén el cuello neutro y evita arquear la zona lumbar.']::text[], 'intermedio', 'Combina las posiciones W y Y para movilizar los omóplatos y reforzar la espalda alta y los trapecios.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5048'),
('369fa007-5880-5e38-a5d9-63d8b4e043ea', 'Remo invertido con agarre supino', ARRAY['Colócate bajo una barra baja o superficie estable y agárrala con las palmas hacia ti.', 'Cuelga con el cuerpo recto y los talones apoyados en el suelo.', 'Tira del pecho hacia la barra llevando los codos al cuerpo y aprieta los omóplatos.', 'Baja controlando hasta extender los brazos sin perder la línea del cuerpo.', 'Evita encoger los hombros o dejar caer la cadera durante el movimiento.']::text[], 'intermedio', 'Trabaja dorsales y bíceps con un tirón horizontal que mejora la fuerza de tracción y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5517'),
('0d30cb7b-6987-565c-88c9-aad8ddc218f7', 'Estiramiento colgado en barra con agarre supino', ARRAY['Agarra la barra con las palmas hacia ti, a la anchura de los hombros.', 'Cuélgate con los brazos estirados y deja que el peso del cuerpo estire los bíceps.', 'Respira despacio y mantén la posición entre veinte y treinta segundos.', 'Evita balancearte o encoger los hombros hacia las orejas.']::text[], 'principiante', 'Estira bíceps, antebrazos y dorsales colgándote de la barra, aliviando tensión y mejorando la movilidad del hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1818'),
('c88a9be2-bbd0-5b86-9324-fb8c8995ff46', 'Postura de giro espinal boca arriba', ARRAY['Túmbate boca arriba con los brazos en cruz y las palmas hacia el suelo.', 'Flexiona una rodilla y llévala cruzada hacia el lado contrario.', 'Gira la cabeza hacia el lado opuesto y mantén los hombros pegados al suelo.', 'Respira profundo y aguanta entre veinte y treinta segundos por lado.']::text[], 'intermedio', 'Moviliza la columna y estira oblicuos y glúteos, ideal para relajar la espalda tras estudiar o entrenar.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1491'),
('d14335b6-6151-5161-a728-1a62ad568388', 'Limpiaparabrisas boca arriba', ARRAY['Túmbate boca arriba con los brazos abiertos y las piernas elevadas.', 'Con las rodillas semiflexionadas, baja las piernas hacia un lado sin tocar el suelo.', 'Controla el movimiento y cambia de lado como un limpiaparabrisas.', 'Mantén la zona lumbar pegada al suelo y evita arquear la espalda.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un movimiento controlado de piernas que también moviliza la cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6705'),
('6a538a5e-9d1a-5fd7-b0e4-8fb316d0b198', 'Postura de parada de cabeza con apoyo', ARRAY['Coloca las manos entrelazadas en el suelo formando un triángulo y apoya la coronilla.', 'Sube las rodillas al pecho y eleva la cadera hasta alinear el cuerpo.', 'Extiende las piernas despacio manteniendo el core firme y la respiración constante.', 'Baja apoyando primero los pies y evita cargar el peso sobre la cabeza.']::text[], 'intermedio', 'Fortalece hombros, core y espalda alta mientras mejora el equilibrio y la conciencia corporal invertida.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6879'),
('eb7ce501-b7fb-5370-a153-a319d2c18afd', 'Estiramiento de flexor de cadera y cuádriceps de pie', ARRAY['Apóyate en una pared o silla para mantener el equilibrio.', 'Lleva un pie hacia atrás y flexiona la rodilla, agarrando el tobillo.', 'Empuja la cadera hacia delante y mantén las rodillas juntas.', 'Aguanta veinte segundos por lado sin arquear la zona lumbar.']::text[], 'principiante', 'Estira cuádriceps y flexores de cadera para mejorar la movilidad de la pierna y prevenir molestias lumbares.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1953'),
('4da8dc00-c1c6-5c9b-a446-aa5e1787f74d', 'Abdominal en suspensión', ARRAY['Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura.', 'Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti.', 'Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado.', 'Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen.', 'Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el abdomen y los oblicuos con un movimiento de extensión controlada que exige estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0805'),
('ef88ac92-3f51-5412-bac4-c4390af6dafe', 'Flexiones en suspensión', ARRAY['Busca un entrenador de suspensión y ajústalo a una altura adecuada.', 'Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono.', 'Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión.', 'Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas.', 'Empuja con el pecho y los brazos para volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con inestabilidad, mejorando la fuerza y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0806'),
('8173d545-de5b-5626-8d39-8363610abb5b', 'Abdominal reverso en suspensión', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica.', 'Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Enfoca la parte baja del abdomen y los flexores de cadera con un movimiento controlado y sin impacto.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0807'),
('eef2c2ed-eca3-5c56-b8ad-73c4ff117f13', 'Remo en suspensión', ARRAY['Coloca un entrenador de suspensión a una altura adecuada.', 'Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.', 'Sostén las asas con un agarre prono, con las palmas mirándose entre sí.', 'Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo.', 'Tira del pecho hacia las asas, apretando los omóplatos entre sí.', 'Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece espalda alta, bíceps y hombros mejorando la postura y la fuerza de tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0808'),
('62d03fd3-88f6-5709-9f6f-3947c47c3a87', 'Sentadilla búlgara en suspensión', ARRAY['Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros.', 'Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión.', 'Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie.', 'Empuja con el talón para regresar a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de pierna.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y femoral con una sentadilla unilateral que mejora el equilibrio y la fuerza.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0809'),
('683d7223-d5bc-50cd-a742-71479eeab606', 'Zancada de abducción con tirantes', ARRAY['Sujeta los tirantes con las manos y da un paso lateral amplio.', 'Flexiona la rodilla de la pierna que avanza manteniendo el pie firme.', 'Empuja con la pierna de apoyo para volver al centro controlando el movimiento.', 'Mantén el torso erguido y evita que la rodilla se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece abductores y glúteos con una zancada lateral que mejora la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1159'),
('cddc2690-beda-500e-a4c9-7d87cab5a731', 'Curl de brazos en suspensión', ARRAY['Agarra los tirantes con las palmas hacia arriba y los brazos estirados.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los hombros.', 'Sube controlando y baja despacio manteniendo la tensión.', 'Evita balancear el cuerpo o encoger los hombros durante el movimiento.']::text[], 'intermedio', 'Aísla bíceps y antebrazos con tensión constante, mejorando la fuerza de flexión del codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1070'),
('4c5084c5-3872-571e-9d25-7f3d2bbd44d2', 'Curl de brazos a las orejas en suspensión', ARRAY['Sujeta los tirantes con las palmas hacia arriba y los brazos extendidos.', 'Flexiona los codos llevando las manos hacia las orejas sin separar los codos.', 'Mantén el core firme y sube controlando la tensión.', 'Baja despacio sin dejar que los hombros se eleven.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos con un recorrido amplio que también exige estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1108'),
('d2d53de2-6d75-5f34-a229-e597fc3fa716', 'Remo invertido con rodillas flexionadas en suspensión', ARRAY['Sujeta los tirantes y colócate con el cuerpo inclinado y las rodillas flexionadas.', 'Tira de los tirantes llevando el pecho hacia las manos y juntando las escápulas.', 'Mantén el cuerpo alineado y el core activo durante todo el recorrido.', 'Baja controlando sin dejar caer los hombros hacia delante.']::text[], 'intermedio', 'Fortalece espalda alta, dorsales y bíceps con una tracción horizontal que mejora la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1071'),
('3dc406c7-f9c8-5203-98cc-29780fccddef', 'Curl de bíceps en suspensión', ARRAY['Agarra las asas con las palmas hacia arriba e inclínate hacia atrás manteniendo el cuerpo recto.', 'Flexiona los codos llevando las manos hacia la frente sin mover los hombros.', 'Baja despacio controlando la extensión y sin perder la tensión del TRX.', 'Evita echar el cuerpo atrás para ayudarte con la espalda.']::text[], 'intermedio', 'Trabaja los bíceps y antebrazos con tensión constante del TRX, mejorando fuerza y control del agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1109'),
('af56faf2-d80c-59bc-84a1-fe7ba2fa0ae1', 'Curl de bíceps con correas de suspensión', ARRAY['Sujeta las asas con las palmas hacia arriba y da un paso atrás inclinando el cuerpo.', 'Mantén el core firme y los codos pegados al torso durante todo el recorrido.', 'Flexiona los codos hasta acercar las manos a los hombros y baja controlando.', 'No dejes caer la cadera ni bloquees la respiración al subir.']::text[], 'intermedio', 'Fortalece bíceps, antebrazos y core con el cuerpo inclinado, exigiendo estabilidad constante.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6232'),
('426b8882-66bd-5bdf-9aaf-5a32d5ca375e', 'Sierra corporal en suspensión', ARRAY['Colócate en plancha con los pies en las asas y los antebrazos en el suelo.', 'Mantén el cuerpo alineado y desplázalo hacia delante y atrás con los hombros.', 'Realiza el movimiento lento y corto, sin arquear la zona lumbar.', 'Evita hundir la cadera y mantén la respiración constante.']::text[], 'intermedio', 'Trabaja el core y los hombros con un movimiento de balanceo que exige estabilidad y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1110'),
('9e83bde2-84d0-5bb5-a622-0d82a4bdb207', 'Elevación de gemelos en suspensión', ARRAY['Sujeta las asas y colócate de pie con el cuerpo ligeramente inclinado hacia atrás.', 'Eleva los talones lo máximo posible manteniendo las rodillas rectas.', 'Baja despacio hasta apoyar los talones sin perder la tensión.', 'Evita balancearte o usar los brazos para impulsarte.']::text[], 'intermedio', 'Refuerza gemelos y sóleo con el TRX, mejorando la estabilidad del tobillo y la fuerza del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1154'),
('1ede6cc9-815b-594a-8b7c-c73da5681810', 'Fondos de pecho en suspensión', ARRAY['Agarra las asas y colócate en suspensión con los brazos extendidos y el cuerpo inclinado.', 'Flexiona los codos bajando el pecho entre las manos sin perder la alineación.', 'Empuja hacia arriba hasta extender los brazos controlando el movimiento.', 'Evita encoger los hombros o dejar caer la cadera.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con el peso corporal, mejorando fuerza y estabilidad del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1072'),
('8a4c710c-7fa0-57a5-b07c-6275d942d2ef', 'Press de pecho con agarre cerrado en suspensión', ARRAY['Sujeta las asas con las palmas enfrentadas y el cuerpo inclinado hacia atrás.', 'Flexiona los codos acercando el pecho a las manos manteniendo el core firme.', 'Empuja hasta extender los brazos sin bloquear los codos con brusquedad.', 'Evita abrir los codos en exceso o perder la línea del cuerpo.']::text[], 'intermedio', 'Fortalece pectorales y tríceps con un agarre estrecho que aumenta la exigencia del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1111'),
('3382984e-9cc2-5104-bbb1-95b19beaba30', 'Face pull en suspensión', ARRAY['Sujeta las asas con las palmas hacia dentro y el cuerpo inclinado hacia atrás.', 'Tira de las asas hacia la cara separando las manos y abriendo los codos.', 'Aprieta los omóplatos al final y vuelve controlando la tensión.', 'Evita encoger los hombros o tirar con la espalda baja.']::text[], 'intermedio', 'Refuerza deltoides posterior, trapecio y rotadores externos, mejorando la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1113'),
('28abc125-2f3c-5c0c-9d89-cfff869e37b9', 'Apertura en suspensión', ARRAY['Colócate inclinado hacia atrás con los brazos extendidos y las palmas enfrentadas.', 'Abre los brazos en arco hasta sentir el estiramiento del pecho.', 'Cierra despacio apretando los pectorales sin bloquear los codos.', 'Evita arquear la espalda o perder la tensión del TRX.']::text[], 'intermedio', 'Aísla los pectorales con el TRX, mejorando la fuerza y el control del pecho en apertura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1074'),
('24927cb7-2cf5-5995-aac9-57281470edc1', 'Zancada con apertura posterior en suspensión', ARRAY['Sujeta las asas y da un paso atrás bajando la rodilla en zancada.', 'Al subir, abre los brazos hacia atrás apretando los omóplatos.', 'Mantén el torso erguido y el core firme durante todo el recorrido.', 'Evita adelantar la rodilla en exceso o perder el equilibrio.']::text[], 'intermedio', 'Combina piernas y deltoides posterior, trabajando fuerza, equilibrio y coordinación en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4094'),
('8e505641-5d3f-55a0-8688-981a4b9d45e8', 'Elevación frontal en suspensión', ARRAY['Sujeta las asas con las palmas hacia abajo y el cuerpo inclinado hacia atrás.', 'Eleva los brazos rectos hasta la altura de los hombros sin balancearte.', 'Baja despacio controlando la tensión del TRX.', 'Evita usar el impulso del cuerpo o encoger los hombros.']::text[], 'intermedio', 'Trabaja el deltoides anterior y el core con el TRX, mejorando la fuerza del hombro en flexión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1075'),
('6740a633-7698-5182-aa37-c0e63bc6922f', 'Flexión en pino en suspensión', ARRAY['Coloca los pies en las asas y las manos en el suelo en posición de pino.', 'Flexiona los codos bajando la cabeza hacia el suelo con control.', 'Empuja hasta extender los brazos manteniendo el core firme.', 'Evita arquear la espalda o perder la alineación vertical.']::text[], 'avanzado', 'Ejercicio avanzado que fortalece tríceps, hombros y core con el peso corporal en vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1115'),
('944375b5-0601-57c0-a2a6-dbfcac2bc67c', 'Parada de cabeza en suspensión', ARRAY['Sujeta las asas y apoya la cabeza en el suelo formando un triángulo con las manos.', 'Eleva las piernas despacio hasta quedar en vertical con el core firme.', 'Mantén la postura respirando con control y sin arquear la espalda.', 'Baja lentamente apoyando los pies para evitar caídas.']::text[], 'intermedio', 'Mejora la fuerza de hombros, core y equilibrio con una inversión controlada asistida por el TRX.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9704'),
('e5504585-48ef-5458-802a-7a63b24bd0cb', 'Bisagra de cadera en suspensión', ARRAY['Sujeta las asas y colócate de pie con los pies a la anchura de las caderas.', 'Lleva la cadera atrás bajando el torso con la espalda recta.', 'Empuja con los glúteos para volver arriba apretando al final.', 'Evita redondear la espalda o flexionar las rodillas en exceso.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales con el TRX, mejorando el patrón de bisagra y la fuerza posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1157'),
('3c9e19b4-7076-5866-8220-5512dbf970f2', 'Flexión inclinada en suspensión', ARRAY['Sujeta las asas y colócate inclinado con el cuerpo recto y los brazos extendidos.', 'Flexiona los codos bajando el pecho entre las manos.', 'Empuja hasta volver a la posición inicial manteniendo el core firme.', 'Evita dejar caer la cadera o adelantar la cabeza.']::text[], 'intermedio', 'Fortalece pectorales, tríceps y core con una flexión asistida que permite progresar en dificultad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1116'),
('f470e006-3914-5ef3-9384-70e5e7d6cd17', 'Sentadilla con salto en suspensión', ARRAY['Sujeta las asas y colócate de pie con los pies a la anchura de los hombros.', 'Baja en sentadilla y salta con fuerza extendiendo las piernas.', 'Aterriza con las rodillas ligeramente flexionadas y amortigua el impacto.', 'Evita caer con las piernas rígidas o perder el equilibrio.']::text[], 'intermedio', 'Ejercicio pliométrico que potencia cuádriceps, glúteos y gemelos mejorando la potencia del tren inferior.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1117'),
('1319c0c8-7d01-51ce-bb7f-9fed27581374', 'Zancada hacia atrás cruzada en suspensión', ARRAY['Colócate de espaldas al anclaje con los pies en los estribos y el cuerpo erguido.', 'Lleva una pierna atrás y crúzala por detrás de la pierna de apoyo mientras flexionas la rodilla delantera.', 'Empuja con el talón delantero para volver a la posición inicial controlando el movimiento.', 'Mantén el torso recto y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece glúteos y piernas mientras el cruce activa aductores y mejora el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1119'),
('b591d033-80e9-5ad1-8741-79d3ca8ab94b', 'Remo medio en suspensión', ARRAY['Agarra las asas y camina hacia atrás hasta inclinarte con el cuerpo recto y los brazos extendidos.', 'Tira de las asas hacia el pecho juntando las escápulas sin encoger los hombros.', 'Baja controlando hasta estirar los brazos del todo manteniendo el core firme.', 'Evita arquear la zona lumbar o tirar solo con los brazos.']::text[], 'intermedio', 'Trabaja la espalda alta y los romboides para mejorar la postura y compensar el encorvamiento típico de estudiar muchas horas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1120'),
('54ad8096-07cb-5929-b1e7-7cc74b2ca15d', 'Flexión con escalador en suspensión', ARRAY['Coloca los pies en los estribos en posición de plancha alta con las manos en el suelo.', 'Baja el pecho flexionando los codos y empuja para volver arriba.', 'Lleva una rodilla hacia el pecho y alterna como si corrieras en el sitio.', 'Mantén la cadera baja y el core apretado para no hundir la espalda.']::text[], 'intermedio', 'Combina empuje de pecho con trabajo de core y flexores de cadera, ideal para ganar coordinación y resistencia global.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1121'),
('d5901356-088e-51e1-8561-f3e22f3a8c50', 'Rodillo oblicuo en suspensión', ARRAY['De rodillas frente al anclaje, sujeta las asas con los brazos extendidos y el cuerpo inclinado.', 'Lleva las manos hacia un lado mientras giras ligeramente el tronco sin mover la cadera.', 'Vuelve al centro y repite hacia el otro lado controlando el descenso.', 'Evita hundir la lumbar: mantén el abdomen apretado todo el recorrido.']::text[], 'intermedio', 'Refuerza el abdomen y los oblicuos con un movimiento antirotación que protege la zona lumbar y mejora el control del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1122'),
('3083b373-d984-5d55-a96a-f7aa84ab59e0', 'Curl de bíceps a un brazo en suspensión', ARRAY['Sujeta un asa con una mano y camina hacia atrás hasta inclinarte con el brazo extendido.', 'Flexiona el codo llevando la mano hacia el hombro sin mover el tronco.', 'Baja despacio hasta estirar el brazo del todo manteniendo el cuerpo recto.', 'Evita girar el torso o encoger el hombro para no perder tensión.']::text[], 'intermedio', 'Aísla el bíceps y el antebrazo con un brazo mientras el core y los oblicuos estabilizan el cuerpo contra la rotación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1123'),
('12681e0f-d659-5042-840b-294a228b1e70', 'Press de pecho a un brazo en suspensión', ARRAY['De espaldas al anclaje, sujeta un asa con una mano y colócate inclinado con el brazo flexionado.', 'Empuja el asa hacia delante hasta estirar el brazo sin bloquear el codo.', 'Vuelve controlando el movimiento mientras mantienes el tronco firme.', 'Evita que la cadera gire o se hunda durante el empuje.']::text[], 'intermedio', 'Trabaja el pectoral y el tríceps de forma unilateral, con el core y los oblicuos resistiendo la rotación del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1124'),
('49265374-a0a4-5282-9020-235e399a7a56', 'Flexión a un brazo y una pierna en suspensión', ARRAY['Coloca un pie en el estribo y apoya una mano en el suelo en plancha.', 'Baja el pecho flexionando el codo y empuja para subir.', 'Mantén la cadera alineada con el hombro y el core apretado.', 'Si pierdes el equilibrio, reduce el rango o apoya la rodilla libre.']::text[], 'intermedio', 'Ejercicio avanzado que exige pecho, tríceps y core para mantener el cuerpo estable sobre un solo apoyo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1125'),
('b434dc2d-8465-530b-9513-90f0b0f8dcbd', 'Press de pecho a una pierna en suspensión', ARRAY['De espaldas al anclaje, apoya un pie en el estribo y sujeta las asas con las manos.', 'Inclínate hacia delante con el cuerpo recto y los brazos flexionados.', 'Empuja las asas hacia delante hasta estirar los brazos y vuelve despacio.', 'Evita que la cadera se hunda o que la rodilla de apoyo se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece el pectoral y el tríceps mientras el glúteo y el core estabilizan el cuerpo sobre una sola pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1126'),
('c816d601-1bfe-5ce7-9393-c7421b98e6bf', 'Péndulo en suspensión', ARRAY['De rodillas frente al anclaje, sujeta las asas con los brazos extendidos y el cuerpo inclinado.', 'Balancea las piernas hacia un lado y hacia el otro manteniendo el tronco firme.', 'Controla el ritmo sin dejar que la cadera se hunda.', 'Evita tirar con los brazos: el movimiento nace del core.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un balanceo controlado que mejora la estabilidad del tronco y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1156'),
('b3a98ac7-6119-5314-97e2-2b0823f73f0a', 'Dominada en suspensión', ARRAY['Agarra las asas y camina hacia atrás hasta inclinarte con los brazos extendidos.', 'Tira del cuerpo hacia las manos juntando las escápulas y flexionando los codos.', 'Baja controlando hasta estirar los brazos sin perder la tensión del core.', 'Evita encoger los hombros o balancear el cuerpo para subir.']::text[], 'intermedio', 'Potencia los dorsales y la espalda alta, mejorando la fuerza de tracción y la postura en estudiantes que pasan muchas horas sentados.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1127'),
('34589204-d79d-5b8c-b1a1-ff523f6f36bf', 'Flexión en suspensión', ARRAY['Coloca los pies en los estribos y apoya las manos en el suelo en plancha alta.', 'Baja el pecho flexionando los codos manteniendo el cuerpo recto.', 'Empuja para volver arriba sin bloquear los codos del todo.', 'Evita hundir la cadera o adelantar la cabeza durante el descenso.']::text[], 'intermedio', 'Fortalece pecho, tríceps y hombros con un empuje inestable que también activa el core para mantener el cuerpo alineado.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1128'),
('52d52d75-95f9-5460-b9e4-d2704ebe3728', 'Remo para deltoide posterior en suspensión', ARRAY['Agarra las asas con las palmas enfrentadas y camina hacia atrás hasta inclinarte.', 'Tira de las asas hacia fuera abriendo los codos a la altura de los hombros.', 'Junta las escápulas al final y baja controlando el movimiento.', 'Evita encoger el cuello o tirar con los brazos sin abrir los codos.']::text[], 'intermedio', 'Refuerza el deltoide posterior y la espalda alta, corrigiendo la postura y equilibrando el trabajo de empuje del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '9503'),
('b042bab0-5634-5512-9313-39dfb691f227', 'Zancada hacia atrás en suspensión', ARRAY['Colócate de espaldas al anclaje con un pie en el estribo y el otro adelantado.', 'Da un paso atrás flexionando la rodilla trasera mientras la delantera baja.', 'Empuja con el talón delantero para volver a la posición inicial.', 'Mantén el torso recto y evita que la rodilla delantera pase de la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con un paso atrás que mejora el equilibrio y la estabilidad de la rodilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1129'),
('32f6cb2c-64d9-54c2-bcc6-f640ac47f7bc', 'Apertura invertida en suspensión', ARRAY['De espaldas al anclaje, sujeta las asas con los brazos extendidos y el cuerpo inclinado.', 'Abre los brazos hacia los lados juntando las escápulas sin flexionar los codos.', 'Vuelve despacio al centro manteniendo el core firme.', 'Evita encoger los hombros o arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja la espalda alta y los deltoides posteriores con un movimiento de apertura que mejora la postura y la salud del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1130'),
('b95903bf-c64c-5d34-bf70-453b348b462e', 'Rodillo abdominal en suspensión', ARRAY['De rodillas frente al anclaje, sujeta las asas con los brazos extendidos.', 'Lleva las manos hacia delante estirando el cuerpo sin hundir la lumbar.', 'Vuelve tirando del abdomen y de los brazos hasta la posición inicial.', 'Evita arquear la espalda o dejar caer la cadera durante el recorrido.']::text[], 'intermedio', 'Trabaja el abdomen y el core con un movimiento de extensión que exige control y estabilidad de la zona lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4799'),
('882559ea-6287-5c89-9ab7-5ae8c668ebc6', 'Remo con correas de suspensión', ARRAY['Agarra las asas con los brazos estirados y el cuerpo inclinado hacia atrás, talones en el suelo.', 'Tira del pecho hacia las manos juntando las escápulas y mantén el cuerpo recto como una tabla.', 'Baja controlando hasta estirar los brazos sin perder la tensión del core.', 'Evita encoger los hombros o dejar caer la cadera durante el recorrido.']::text[], 'intermedio', 'Fortalece la espalda y los bíceps tirando del peso del cuerpo; mejora la postura y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6220'),
('412d67b5-8d52-5735-80f6-124b796088c1', 'Zancada lateral cruzada en suspensión', ARRAY['Sujeta las asas con los brazos flexionados y da un paso lateral cruzando una pierna por delante.', 'Flexiona la rodilla de la pierna que cruza y lleva la cadera hacia atrás manteniendo el pecho alto.', 'Empuja con el talón para volver al centro y controla el movimiento.', 'No dejes que la rodilla se meta hacia dentro ni que el tronco se desplome.']::text[], 'intermedio', 'Activa glúteos y aductores con un paso cruzado que mejora la estabilidad de cadera y el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1131');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('83d37c58-1b91-504a-a3dc-a5e8e6c2697b', 'Zancada lateral en suspensión', ARRAY['Agarra las asas y da un paso amplio hacia un lado con el pie firme.', 'Flexiona la rodilla de esa pierna llevando la cadera atrás, mientras la otra queda estirada.', 'Empuja con el talón para volver a la posición inicial con control.', 'Mantén la espalda recta y evita que la rodilla pase por delante de la punta del pie.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con un desplazamiento lateral que refuerza la fuerza unilateral y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1132'),
('abab2a5b-2bec-5763-960d-5a54be1640c8', 'Estiramiento lateral con tirantes', ARRAY['Sujeta las asas con una mano y separa los pies más allá del ancho de hombros.', 'Inclina el tronco hacia un lado dejando que la cadera se desplace y siente el estiramiento en la cara interna del muslo.', 'Respira profundo y mantén la posición sin rebotes.', 'Evita forzar hacia delante; el movimiento debe ser lateral y controlado.']::text[], 'principiante', 'Estira aductores e ingles con una tracción suave que mejora la movilidad de la cadera.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1158'),
('4d1c664e-43d5-5ef7-8bcf-fc01b500e91a', 'Remo a un brazo para deltoide posterior en suspensión', ARRAY['Agarra un asa con una mano y coloca el cuerpo inclinado con el brazo estirado.', 'Tira del codo hacia atrás y arriba llevando la mano hacia la cadera, con el hombro lejos de la oreja.', 'Baja despacio hasta estirar el brazo sin girar el tronco.', 'Evita rotar la cadera o encoger el hombro durante el tirón.']::text[], 'intermedio', 'Aísla el deltoide posterior y la espalda alta con un tirón unilateral que corrige desequilibrios.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1133'),
('766d15fb-d8ab-582e-ac33-e9f6d83e67ab', 'Peso muerto a una pierna en suspensión', ARRAY['Sujeta las asas con una mano y apoya el peso en la pierna contraria.', 'Lleva la cadera atrás mientras la pierna libre se eleva, manteniendo la espalda recta.', 'Baja hasta notar el estiramiento en el isquiotibial y vuelve empujando la cadera hacia delante.', 'No redondees la espalda ni pierdas la alineación de cadera y hombros.']::text[], 'intermedio', 'Refuerza isquiotibiales y glúteos con un patrón de bisagra a una pierna que mejora el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1155'),
('0d8503ec-f172-523c-9bc4-c246ed9d0ce7', 'Plancha a una pierna en suspensión', ARRAY['Coloca los pies en las correas y apoya los antebrazos en el suelo.', 'Eleva una pierna manteniendo el cuerpo alineado de cabeza a talón.', 'Aprieta glúteos y abdomen y respira de forma constante.', 'Evita que la cadera se hunda o se eleve demasiado.']::text[], 'intermedio', 'Fortalece el core y los glúteos con una plancha inestable que exige control antirotación.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1135'),
('10856cf7-9bed-5e2d-89a8-a7be28abf74a', 'Plancha a una pierna con brazos rectos en suspensión', ARRAY['Apoya las manos en el suelo con los pies en las correas y el cuerpo recto.', 'Levanta una pierna sin mover la cadera ni los hombros.', 'Mantén la mirada al suelo y respira con normalidad.', 'No bloquees la respiración ni dejes caer la cadera.']::text[], 'intermedio', 'Trabaja el core y los hombros con una plancha más exigente que añade inestabilidad y control.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1134'),
('8eedddbb-954f-56e6-bcb6-c4335e89398b', 'Sentadilla a una pierna en suspensión', ARRAY['Sujeta las asas con una mano y apoya el peso en una pierna.', 'Baja flexionando la rodilla y llevando la cadera atrás mientras la otra pierna se extiende.', 'Empuja con el talón para subir manteniendo el control.', 'Evita que la rodilla se vaya hacia dentro y no dejes que el tronco se desplome.']::text[], 'intermedio', 'Desarrolla fuerza unilateral en cuádriceps y glúteos con apoyo que mejora el equilibrio y la técnica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1136'),
('506e2c57-a115-5966-a375-9f32f0ce8d1c', 'Abdominal con incorporación en suspensión', ARRAY['Coloca los pies en las correas y túmbate con las rodillas flexionadas.', 'Incorpora el tronco activando el abdomen sin tirar del cuello.', 'Baja despacio controlando la fase excéntrica.', 'Evita impulsarte con los brazos o arquear la zona lumbar.']::text[], 'intermedio', 'Fortalece el recto abdominal y los flexores de cadera con una incorporación que exige control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1137'),
('82d67eac-a8da-57d8-b520-bcf7d3418320', 'Flexión spiderman en suspensión', ARRAY['Apoya las manos en el suelo con los pies en las correas y el cuerpo recto.', 'Baja el pecho flexionando los codos y lleva una rodilla hacia el codo del mismo lado.', 'Empuja para subir y devuelve la pierna a su sitio.', 'Mantén la cadera estable y evita que se hunda o rote en exceso.']::text[], 'intermedio', 'Trabaja pectorales y core con una flexión que suma rotación y control lumbo-pélvico.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1138'),
('5046766f-d848-5154-b78d-12b06a768282', 'Apertura dividida en suspensión', ARRAY['Sujeta las asas con los brazos estirados y el cuerpo inclinado hacia atrás.', 'Abre los brazos en cruz manteniendo una ligera flexión de codos.', 'Vuelve al centro controlando el movimiento sin dejar caer el cuerpo.', 'Evita encoger los hombros o arquear la espalda.']::text[], 'intermedio', 'Activa deltoides y pectorales con una apertura controlada que mejora la estabilidad del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1139'),
('6401a42d-cca0-5b20-a7e2-464a130ea0d8', 'Sprinter en suspensión', ARRAY['Sujeta las asas y adopta una posición de zancada con el peso en una pierna.', 'Empuja con fuerza para extender la cadera y llevar la rodilla contraria arriba.', 'Vuelve a la posición inicial con control y repite.', 'Evita perder la alineación del tronco o aterrizar con la rodilla bloqueada.']::text[], 'intermedio', 'Mejora la potencia de piernas y la coordinación con un gesto explosivo que imita la carrera.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '1140'),
('e7243593-e650-5aa2-8f51-92a4b3b25227', 'Sentadilla en suspensión', ARRAY['Sujeta las asas con los brazos estirados y los pies a la anchura de hombros.', 'Baja llevando la cadera atrás y flexionando las rodillas con el pecho alto.', 'Empuja con los talones para subir manteniendo la tensión.', 'No dejes que las rodillas se metan hacia dentro ni que la espalda se redondee.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una sentadilla asistida que mejora el patrón y el equilibrio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1143'),
('1d86559f-829e-5fe5-9dd1-ae2aba324c08', 'Sentadilla con brazos sobre la cabeza en suspensión', ARRAY['Sujeta las asas con los brazos extendidos por encima de la cabeza.', 'Baja en sentadilla manteniendo los brazos arriba y el tronco erguido.', 'Empuja con los talones para volver a subir sin perder la posición.', 'Evita arquear la zona lumbar o dejar que los brazos caigan hacia delante.']::text[], 'intermedio', 'Trabaja piernas y hombros con una sentadilla que exige movilidad torácica y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1141'),
('bdb99d09-7646-52af-8707-75aa6119628a', 'Salto en sentadilla con correas de suspensión', ARRAY['Agarra las correas con los brazos extendidos y colócate de pie con los pies a la anchura de los hombros.', 'Baja en sentadilla llevando la cadera atrás y manteniendo el pecho alto.', 'Impúlsate con fuerza para saltar mientras las correas te ayudan a mantener el equilibrio.', 'Aterriza con las rodillas ligeramente flexionadas y absorbe el impacto sin dejarlas caer hacia dentro.', 'Respira de forma controlada y evita saltar con la espalda curvada.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos y gemelos con potencia explosiva, mejorando la fuerza del tren inferior y la estabilidad del core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '6222'),
('5a56b7ab-5d8b-5d65-a608-c95ff9717979', 'Rodillo abdominal de pie en suspensión', ARRAY['Sujeta las correas con los brazos extendidos frente a ti y da un paso atrás para inclinarte.', 'Mantén el cuerpo recto y activa el abdomen antes de moverte.', 'Lleva las manos hacia delante y abajo de forma lenta, sin arquear la zona lumbar.', 'Vuelve a la posición inicial tirando de las correas con el core, no con los brazos.', 'Evita bloquear la respiración y no dejes que la cadera se hunda.']::text[], 'intermedio', 'Fortalece el abdomen profundo y los hombros, mejorando el control del core y la estabilidad en posición erguida.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1144'),
('5632ba96-2edc-5351-a202-5a2d0bf88d0b', 'Plancha estrella en suspensión', ARRAY['Colócate en plancha lateral con los pies en las correas y el codo apoyado en el suelo.', 'Eleva la cadera hasta formar una línea recta desde la cabeza hasta los pies.', 'Extiende el brazo libre hacia arriba y mantén la posición sin girar el tronco.', 'Aprieta glúteos y abdomen mientras respiras de forma pausada.', 'Evita dejar caer la cadera o adelantar el hombro de apoyo.']::text[], 'intermedio', 'Trabaja el abdomen, los oblicuos y los glúteos en isométrico, mejorando la estabilidad lateral y la resistencia del core.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1145'),
('8c8329f7-a5ee-5261-87ae-7f04e5ea0acc', 'Flexión estrella en suspensión', ARRAY['Coloca los pies en las correas y las manos en el suelo, en posición de flexión.', 'Abre las piernas en forma de estrella manteniendo el abdomen activo.', 'Baja el pecho hacia el suelo con los codos cerca del cuerpo.', 'Empuja para volver arriba sin hundir la cadera ni arquear la espalda.', 'Respira al subir y evita perder la alineación de la cabeza con la columna.']::text[], 'intermedio', 'Combina empuje y estabilidad, trabajando abdomen, pecho y tríceps para mejorar el control global del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1146'),
('5a27fb92-8d87-53c2-9749-5a0c3ee70cb9', 'Abdominal boca arriba en suspensión', ARRAY['Túmbate boca arriba con los talones en las correas y las rodillas flexionadas.', 'Activa el abdomen y pega la zona lumbar al suelo.', 'Eleva la cadera y lleva las rodillas hacia el pecho de forma controlada.', 'Baja lentamente sin dejar que los pies pierdan la tensión de las correas.', 'Evita tirar del cuello o arquear la espalda al subir.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera, mejorando la estabilidad del core en posición supina.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1147'),
('34fafdd3-9e9e-57ee-9561-deb9a6249e4c', 'Plancha boca arriba en suspensión', ARRAY['Túmbate boca arriba con los talones en las correas y los brazos junto al cuerpo.', 'Eleva la cadera hasta formar una línea recta desde los hombros hasta los pies.', 'Aprieta glúteos y abdomen sin arquear la zona lumbar.', 'Mantén la posición respirando de forma constante.', 'Evita dejar caer la cadera o encoger los hombros.']::text[], 'intermedio', 'Refuerza el abdomen, glúteos y zona lumbar en isométrico, mejorando la estabilidad posterior y la postura.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1148'),
('12d667fd-b1b1-5260-bd59-7a9cf8ad197f', 'Flexión con extensión de tríceps en suspensión', ARRAY['Sujeta las correas con las manos y colócate en posición de flexión inclinada.', 'Baja el pecho flexionando los codos cerca del cuerpo.', 'Al subir, extiende los codos con fuerza para activar el tríceps.', 'Mantén el abdomen firme y el cuerpo alineado durante todo el movimiento.', 'Evita abrir los codos o dejar caer la cadera.']::text[], 'intermedio', 'Trabaja tríceps, hombros y pecho, mejorando la fuerza de empuje y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1149'),
('f30e2a3b-4d91-5b92-ad6a-14e3d8a88342', 'Patada de tríceps en suspensión', ARRAY['Inclínate hacia delante sujetando las correas con los codos pegados al cuerpo.', 'Extiende los antebrazos hacia atrás hasta estirar los codos.', 'Aprieta el tríceps arriba y vuelve lentamente a la posición inicial.', 'Mantén la espalda recta y el abdomen activo.', 'Evita mover los hombros o balancear el tronco.']::text[], 'intermedio', 'Aísla el tríceps y estabiliza el hombro, mejorando la fuerza del brazo y el control postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1150'),
('389d3074-e2ec-5e3c-8714-5d2974d3a3a6', 'Giro lateral en suspensión', ARRAY['Sujeta las correas con ambas manos y da un paso atrás para inclinarte.', 'Gira el tronco hacia un lado manteniendo la cadera estable.', 'Vuelve al centro y repite hacia el otro lado de forma controlada.', 'Respira al girar y evita tirar solo con los brazos.', 'No dejes que la espalda se curve durante el giro.']::text[], 'intermedio', 'Trabaja abdomen y oblicuos con rotación controlada, mejorando la estabilidad del core y la movilidad torácica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1151'),
('516eecaf-8923-5613-b28a-d0b8dc9f7396', 'Giro hacia arriba en suspensión', ARRAY['Colócate inclinado sujetando las correas con los brazos extendidos.', 'Gira el tronco hacia arriba y hacia un lado mientras activas el abdomen.', 'Vuelve al centro y alterna el lado sin perder la tensión.', 'Mantén la cadera estable y respira de forma constante.', 'Evita arquear la espalda o tirar con los hombros.']::text[], 'intermedio', 'Fortalece abdomen y oblicuos con rotación ascendente, mejorando la coordinación y el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1152'),
('e4cb5667-84fa-53b7-bf36-f1e90c642f6a', 'Navaja con giro en suspensión', ARRAY['Túmbate boca arriba con los pies en las correas y los brazos extendidos.', 'Eleva las piernas y el tronco a la vez formando una navaja.', 'Añade un giro lateral controlado en la parte alta del movimiento.', 'Baja lentamente sin perder la tensión abdominal.', 'Evita tirar del cuello o dejar caer las piernas de golpe.']::text[], 'intermedio', 'Combina flexión de cadera y rotación, trabajando abdomen, oblicuos y flexores para mejorar la potencia del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1106'),
('66f370a1-e99a-557f-9dab-65678f0def0e', 'Estiramiento de espalda alta en suspensión', ARRAY['Sujeta las correas con ambas manos y da un paso atrás.', 'Inclina el tronco hacia delante dejando caer el pecho.', 'Lleva la cadera atrás y siente el estiramiento entre los omóplatos.', 'Mantén la posición respirando profundamente y sin forzar.', 'Evita curvar la zona lumbar o tirar en exceso de los brazos.']::text[], 'principiante', 'Estira la espalda alta, dorsales y romboides, aliviando la tensión y mejorando la movilidad de la columna torácica.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1153'),
('8ea7e601-d9c3-5632-83be-17f31f964ad5', 'Remo invertido con peso en suspensión', ARRAY['Colócate bajo las correas sujetándolas con las manos y el cuerpo recto.', 'Tira del pecho hacia las manos juntando los omóplatos.', 'Mantén el abdomen activo y los talones apoyados.', 'Baja de forma controlada sin perder la alineación.', 'Evita encoger los hombros o usar impulso con la cadera.']::text[], 'intermedio', 'Fortalece la espalda alta, dorsales y bíceps, mejorando la postura y la fuerza de tracción con carga adicional.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2834'),
('de89c1e0-f067-542b-88a7-794439fa4b44', 'Remo invertido con agarre abierto en suspensión', ARRAY['Sujeta las correas con las manos más separadas que los hombros.', 'Colócate inclinado con el cuerpo recto y los talones apoyados.', 'Tira del pecho hacia arriba llevando los codos hacia fuera.', 'Junta los omóplatos arriba y baja lentamente.', 'Evita adelantar la cabeza o perder la tensión del core.']::text[], 'intermedio', 'Trabaja dorsales y espalda alta con agarre amplio, mejorando la fuerza de tracción y la estabilidad escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4450'),
('0ec9c2ec-9c20-571e-a225-bd18ca386165', 'Elevación lateral en y en suspensión', ARRAY['Sujeta las correas con los brazos extendidos y el cuerpo ligeramente inclinado.', 'Eleva los brazos hacia los lados formando una Y con el cuerpo.', 'Sube hasta la altura de los hombros sin encoger el cuello.', 'Baja de forma controlada manteniendo la tensión.', 'Evita usar impulso o arquear la espalda.']::text[], 'intermedio', 'Trabaja el deltoides lateral y la espalda alta, mejorando la fuerza del hombro y la estabilidad postural.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1107'),
('2da467b9-835a-5c9d-8687-e3d3c70eb038', 'Dominada supina en suspensión', ARRAY['Agarra las asas en supinación y cuélgate con los brazos estirados y el cuerpo alineado.', 'Tira de las asas llevando el pecho hacia las manos mientras aprietas los omóplatos.', 'Baja controlando hasta estirar los brazos sin perder la tensión del core.', 'Evita balancearte o encoger los hombros; mantén el abdomen firme en todo el recorrido.']::text[], 'intermedio', 'Trabaja dorsal y bíceps colgándote del arnés; mejora tu fuerza de tracción y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5008'),
('86f82960-6961-56ae-b645-550ce88c876a', 'Curl martillo en suspensión', ARRAY['Colócate de espaldas al anclaje con las asas a la altura de la cadera y agarre neutro.', 'Flexiona los codos llevando las manos hacia los hombros sin mover los brazos.', 'Baja despacio hasta estirar los codos manteniendo la tensión.', 'Evita echar el torso atrás o encoger los hombros para no perder el trabajo del bíceps.']::text[], 'intermedio', 'Aísla bíceps y braquial con agarre neutro; refuerza la flexión del codo y los antebrazos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5007'),
('671aff9e-45cc-5669-8b07-55d4512e6b65', 'Corredor de isquiotibiales en suspensión', ARRAY['Túmbate boca arriba con los talones en las asas y las piernas semiflexionadas.', 'Eleva la cadera y alterna llevar una rodilla al pecho mientras la otra pierna empuja.', 'Mantén la cadera alta y el abdomen firme durante todo el movimiento.', 'Evita que la cadera caiga o que la zona lumbar se arquee en exceso.']::text[], 'intermedio', 'Activa isquiotibiales y glúteos con un patrón de carrera; mejora la fuerza posterior y el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1076'),
('c9d84876-bf2e-5503-a6ad-bbde4d73e8ec', 'Abducción de cadera en suspensión', ARRAY['Coloca un pie en el estribo y apóyate en la otra pierna con el cuerpo erguido.', 'Separa la pierna del arnés hacia fuera sin inclinar el tronco.', 'Vuelve despacio al centro manteniendo el abdomen activo.', 'Evita compensar con la cadera o el tronco; el movimiento debe salir del glúteo.']::text[], 'intermedio', 'Fortalece abductores y glúteo medio; mejora la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1077'),
('826622bb-5a20-5910-9d33-247fb84caaa7', 'Puente de cadera en suspensión', ARRAY['Túmbate boca arriba con los talones en las asas y las rodillas flexionadas.', 'Empuja con los talones y eleva la cadera hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba y baja controlando sin apoyar del todo.', 'Evita arquear la lumbar o empujar con los brazos para subir.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales elevando la cadera; refuerza la extensión de cadera y la estabilidad lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1078'),
('b733ee8b-a7c7-5386-bb85-731491270613', 'Hiperextensión en suspensión', ARRAY['Sujeta las asas con los brazos estirados y el cuerpo inclinado hacia atrás.', 'Lleva la cadera atrás y baja el tronco manteniendo la espalda neutra.', 'Extiende la cadera para volver arriba apretando glúteos e isquiotibiales.', 'Evita hiperextender la lumbar al final; detente cuando el cuerpo esté alineado.']::text[], 'intermedio', 'Refuerza la cadena posterior y los erectores espinales; mejora la extensión de cadera y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1079'),
('fdf381ac-9207-51e6-b4cf-d6648a6f231d', 'Estiramiento en polea en supinación', ARRAY['Agarra la empuñadura en supinación con el brazo estirado y el hombro relajado.', 'Gira el cuerpo o retrocede despacio hasta notar el estiramiento en el bíceps.', 'Mantén la posición sin rebotes y respira de forma pausada.', 'Evita forzar el codo o encoger el hombro; el estiramiento debe ser cómodo.']::text[], 'principiante', 'Estira bíceps y antebrazo con ayuda de la polea; alivia tensión y mejora la movilidad del codo y el hombro.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1819'),
('28679057-4beb-5f03-8f84-844aae8087d7', 'Remo invertido en suspensión', ARRAY['Cuélgate de las asas con el cuerpo recto y los talones apoyados en el suelo.', 'Tira del pecho hacia las manos juntando los omóplatos.', 'Baja controlando hasta estirar los brazos sin perder la línea del cuerpo.', 'Evita dejar caer la cadera o encoger los hombros al tirar.']::text[], 'intermedio', 'Trabaja espalda alta y romboides con tracción horizontal; mejora la postura y la fuerza de tirón.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1080'),
('62f64dd2-1f82-5ef2-a820-f96267a4e444', 'Navaja en suspensión', ARRAY['Coloca los pies en las asas en posición de plancha alta con el cuerpo alineado.', 'Lleva las rodillas hacia el pecho elevando la cadera.', 'Vuelve despacio a la plancha sin dejar caer la lumbar.', 'Evita balancearte o perder la alineación del tronco durante el movimiento.']::text[], 'intermedio', 'Trabaja abdomen y flexores de cadera llevando las rodillas al pecho; mejora el control del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1082'),
('35db375f-a0cd-5116-8fe9-0b77ee5df0f7', 'Navaja en pica en suspensión', ARRAY['Apoya los pies en las asas en plancha alta con los brazos firmes.', 'Eleva la cadera hacia arriba formando una pica mientras llevas las piernas atrás.', 'Baja controlando hasta volver a la plancha sin arquear la espalda.', 'Evita bloquear la respiración o perder la tensión del abdomen.']::text[], 'intermedio', 'Exige más al abdomen y hombros elevando la cadera en pica; mejora la fuerza del core y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1081'),
('7c97dabf-a63d-5ea0-9611-55b90937c96a', 'Curl de pierna en suspensión', ARRAY['Túmbate boca arriba con los talones en las asas y la cadera elevada.', 'Flexiona las rodillas llevando los talones hacia los glúteos.', 'Extiende las piernas despacio manteniendo la cadera alta.', 'Evita que la cadera caiga o que la lumbar se arquee durante el recorrido.']::text[], 'intermedio', 'Aísla isquiotibiales flexionando la rodilla contra el arnés; refuerza la cadena posterior y el control pélvico.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1083'),
('c79e495c-bea7-5f64-b574-f739b3ef353a', 'Escalador en suspensión', ARRAY['Coloca los pies en las asas en plancha alta con las manos firmes en el suelo.', 'Lleva una rodilla al pecho y alterna con la otra a ritmo controlado.', 'Mantén la cadera estable y el abdomen apretado en todo momento.', 'Evita elevar la cadera o perder la línea del cuerpo al acelerar.']::text[], 'intermedio', 'Combina core y hombros con un patrón dinámico de rodillas al pecho; mejora la resistencia y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1084'),
('e7c33de1-067c-50e9-bacc-9bfc56e3d990', 'Tirón potente en suspensión', ARRAY['Agarra las asas y colócate inclinado con los brazos estirados y el cuerpo firme.', 'Tira con fuerza llevando el pecho hacia las manos de forma explosiva.', 'Baja controlando hasta la posición inicial sin perder la tensión.', 'Evita usar impulso de cadera o encoger los hombros para completar el tirón.']::text[], 'intermedio', 'Trabaja dorsal y espalda alta con una tracción explosiva; desarrolla potencia y coordinación del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1086'),
('46785370-69e7-594a-bbc3-c13a156671f2', 'Pull through en suspensión', ARRAY['Colócate de espaldas al anclaje con las asas entre las piernas y el cuerpo inclinado.', 'Lleva la cadera atrás flexionando el tronco con la espalda neutra.', 'Extiende la cadera hacia delante apretando glúteos hasta quedar erguido.', 'Evita arquear la lumbar o tirar con los brazos en lugar de la cadera.']::text[], 'intermedio', 'Activa glúteos e isquiotibiales con extensión de cadera; mejora la potencia posterior y la estabilidad lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1087'),
('3dc4a69f-2b8e-5f37-8996-689f6eceebbf', 'Fondos de pecho autoasistidos en suspensión', ARRAY['Colócate de espaldas a las correas, agarra las asas a la altura del pecho y da un paso atrás con los pies en el suelo.', 'Inclina el cuerpo hacia delante y flexiona los codos bajando el pecho entre las manos.', 'Empuja con fuerza para volver arriba mientras sueltas aire, manteniendo el core firme.', 'Usa las piernas para asistirte lo justo y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Trabaja el pectoral y los tríceps con ayuda de las correas, ideal para progresar hacia fondos completos con control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1093'),
('55ef0090-6065-59aa-80b8-4bcfe35af7a5', 'Dominada autoasistida en suspensión', ARRAY['Agarra las asas con las palmas hacia delante y siéntate ligeramente con los pies apoyados.', 'Tira de los codos hacia las costillas elevando el pecho hacia las manos.', 'Baja de forma controlada hasta estirar los brazos sin perder la tensión del core.', 'Apóyate en las piernas solo lo necesario y evita balancear el cuerpo para subir.']::text[], 'intermedio', 'Refuerza dorsales y bíceps con asistencia de las piernas, perfecta para construir fuerza hacia la dominada libre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1094'),
('8995a239-a475-51cf-9699-ae3904476492', 'Fondos de tríceps autoasistidos en suspensión', ARRAY['Sujeta las asas con los brazos estirados y el cuerpo ligeramente inclinado hacia atrás.', 'Flexiona los codos hacia atrás manteniéndolos cerca del torso hasta notar el estiramiento.', 'Empuja para extender los brazos soltando el aire y sin bloquear los hombros.', 'Asiste con las piernas lo justo y evita abrir los codos hacia los lados.']::text[], 'intermedio', 'Enfoca el trabajo en el tríceps con apoyo de las piernas, útil para ganar fuerza en el fondo completo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1095'),
('2323c2b8-4e79-5feb-8a0e-a1acbe6db5fc', 'Rotación externa de hombro en suspensión', ARRAY['Colócate de lado a las correas con el codo pegado al cuerpo y flexionado a 90 grados.', 'Gira el antebrazo hacia fuera separándolo del abdomen sin mover el codo.', 'Vuelve despacio a la posición inicial controlando el retorno.', 'Mantén el hombro abajo y evita compensar girando el tronco.']::text[], 'intermedio', 'Fortalece el manguito rotador y la parte posterior del hombro, ayudando a estabilizar la articulación y prevenir lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1096'),
('c2d13adb-bd61-5772-b6e8-2465efab2600', 'Inclinación lateral en suspensión', ARRAY['De pie de lado a las correas, sujeta el asa con una mano y separa los pies a la anchura de las caderas.', 'Inclina el tronco hacia el lado contrario a la correa dejando que el peso caiga.', 'Vuelve a la vertical contrayendo el oblicuo y suelta el aire al subir.', 'Evita flexionar la cadera o encoger el hombro durante el recorrido.']::text[], 'intermedio', 'Trabaja la oblicuidad y el core con inclinaciones controladas, mejorando la estabilidad lateral del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1097'),
('2a3c0c8c-d565-5991-aed4-f3bc61a1a558', 'Puente lateral en suspensión', ARRAY['Colócate de lado con los pies en las asas y el codo apoyado en el suelo bajo el hombro.', 'Eleva la cadera formando una línea recta desde la cabeza hasta los pies.', 'Mantén la posición respirando con normalidad sin dejar caer la cadera.', 'Evita hundir el hombro o rotar el tronco hacia delante.']::text[], 'intermedio', 'Isométrico que refuerza oblicuos, core y hombros, mejorando la estabilidad lateral y la resistencia postural.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '1098'),
('2291115e-41b7-509e-8a98-225f454c498b', 'Sentadilla dividida a una pierna en suspensión', ARRAY['Coloca un pie en las asas por detrás y el otro adelantado, sujetando las correas con las manos.', 'Baja flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.', 'Empuja con la pierna delantera para subir soltando el aire.', 'Mantén el tronco erguido y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con apoyo de las correas, mejorando el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1100'),
('44fb29f0-62f3-5889-a668-cb586093e8ac', 'Curl de pierna con cadera recta en suspensión', ARRAY['Túmbate boca abajo con los pies en las asas y el cuerpo alineado.', 'Flexiona las rodillas llevando los talones hacia los glúteos sin mover la cadera.', 'Baja despacio controlando el retorno hasta estirar las piernas.', 'Evita arquear la zona lumbar elevando la cadera durante el movimiento.']::text[], 'intermedio', 'Aísla los isquiotibiales con la cadera extendida, mejorando la fuerza posterior del muslo y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1102'),
('56a828b6-7faa-5611-b716-9c93a3b61ef9', 'Sentadilla sumo en suspensión', ARRAY['Sujeta las asas con los brazos estirados y abre los pies más allá de la anchura de los hombros.', 'Baja la cadera hacia atrás con las puntas ligeramente hacia fuera.', 'Empuja con los talones para subir apretando los glúteos y suelta el aire.', 'Mantén la espalda recta y evita que las rodillas se junten al bajar.']::text[], 'intermedio', 'Activa glúteos y aductores con una postura amplia, mejorando la fuerza de la cadena posterior y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5004'),
('c835ae73-7b64-5e82-a367-f8243f0ad8db', 'Plancha frontal con correas de suspensión', ARRAY['Apoya los pies en las asas y colócate en posición de plancha con los codos bajo los hombros.', 'Alinea la cabeza, la cadera y los talones manteniendo el abdomen firme.', 'Respira con normalidad sin dejar caer la cadera ni elevar el glúteo.', 'Evita arquear la zona lumbar o adelantar la cabeza.']::text[], 'intermedio', 'Isométrico que refuerza el core, hombros y glúteos, mejorando la estabilidad global del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '7275'),
('2ada57cd-2e23-5197-975b-11af0f54f5e2', 'Estiramiento de dorsales con correas de suspensión', ARRAY['Sujeta las asas con ambas manos y da un paso atrás inclinando el tronco.', 'Lleva la cadera hacia atrás mientras estiras los brazos y dejas caer el pecho.', 'Mantén la posición respirando profundo sin forzar el rango.', 'Evita redondear la zona lumbar o encoger los hombros.']::text[], 'principiante', 'Estira dorsales y zona posterior del hombro, aliviando la tensión y mejorando la movilidad del tronco.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '7278'),
('38754f3a-b1f7-5bc5-8e55-29e7947826d1', 'Pike con correas de suspensión', ARRAY['Apoya los pies en las asas y colócate en plancha con los brazos estirados.', 'Eleva la cadera hacia arriba formando una V invertida mientras sueltas el aire.', 'Baja despacio controlando el retorno sin perder la tensión abdominal.', 'Evita flexionar los codos o dejar caer la cadera al bajar.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con elevación de cadera, mejorando la fuerza del core y los hombros.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7274'),
('b4165585-fbd1-5eda-b899-9d40bc82b4a6', 'Jalón potente en sentadilla con correas de suspensión', ARRAY['Sujeta las asas con los brazos estirados y los pies a la anchura de los hombros.', 'Baja en sentadilla mientras llevas los brazos atrás.', 'Sube con fuerza y tira de las asas hacia el pecho de forma explosiva.', 'Mantén la espalda neutra y evita tirar solo con los brazos sin usar las piernas.']::text[], 'intermedio', 'Combina piernas y espalda en un movimiento explosivo, mejorando la potencia y la coordinación global.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '7279'),
('48fa5dda-ca9d-5c69-925c-21dab2a3408d', 'Fondos de tríceps en suspensión', ARRAY['Sujeta las asas con los brazos estirados y el cuerpo ligeramente inclinado hacia atrás.', 'Flexiona los codos hacia atrás hasta que los brazos formen unos 90 grados.', 'Empuja para extender los brazos soltando el aire sin bloquear los hombros.', 'Evita abrir los codos hacia los lados y mantén el core firme.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombros con el peso corporal, mejorando la fuerza de empuje en suspensión.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1103'),
('a1604e6a-5617-5a28-a28b-cbc3d8cbd719', 'Extensión de tríceps en suspensión', ARRAY['Colócate de espaldas al anclaje con las asas a la altura del pecho y sujétalas con las palmas hacia abajo.', 'Inclina el cuerpo hacia delante manteniendo el torso recto y los codos pegados al cuerpo.', 'Flexiona los codos para bajar la cabeza y extiéndelos para volver, sin mover los hombros.', 'Evita abrir los codos hacia los lados y mantén el core activo durante todo el recorrido.']::text[], 'intermedio', 'Fortalece los tríceps y estabiliza hombros y core trabajando en cadena cerrada con el peso corporal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5876'),
('0bf8b702-d1e0-564a-a160-4266e63513ca', 'Giro en suspensión', ARRAY['Sujeta las asas con ambas manos y colócate de pie con los brazos extendidos frente a ti.', 'Inclínate ligeramente hacia atrás manteniendo el cuerpo en línea recta y el core activo.', 'Gira el tronco hacia un lado y luego hacia el otro sin mover las caderas.', 'Respira de forma constante y evita tirar con los brazos para no perder tensión en el abdomen.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos controlando la rotación del tronco contra la resistencia del arnés.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1105'),
('04fb6801-1ca8-5dea-96de-c296ad9f5436', 'Remo invertido con agarre supino en suspensión', ARRAY['Ajusta las asas a la altura de la cadera y sujétalas con las palmas hacia arriba.', 'Cuélgate con los brazos extendidos y el cuerpo recto desde la cabeza hasta los talones.', 'Tira de las asas llevando el pecho hacia ellas y junta las escápulas al final.', 'Baja de forma controlada sin dejar caer las caderas y evita encoger los hombros.']::text[], 'intermedio', 'Refuerza dorsales y bíceps con un tirón horizontal que también mejora la postura y el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5006'),
('5c54d2bb-ed09-5381-b6f0-19d99bef5fa0', 'Remo invertido con agarre abierto en suspensión en el suelo', ARRAY['Coloca las asas más abiertas que los hombros y túmbate debajo sujetándolas con agarre prono.', 'Extiende los brazos y mantén el cuerpo recto apoyado solo en los talones.', 'Tira del pecho hacia las asas llevando los codos hacia atrás y juntando las escápulas.', 'Baja despacio sin arquear la zona lumbar y evita adelantar la cabeza.']::text[], 'intermedio', 'Fortalece la espalda alta y los romboides con un tirón amplio que mejora la postura y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4451'),
('3276aba9-f41b-5b82-ac1d-76a90a8aeec2', 'Salto de cisne', ARRAY['Túmbate boca abajo con los brazos extendidos por delante y las piernas juntas.', 'Alarga el cuerpo y eleva a la vez brazos, pecho y piernas del suelo.', 'Mantén la mirada al suelo y separa los hombros de las orejas durante la elevación.', 'Baja de forma lenta y evita arquear en exceso el cuello o la zona lumbar.']::text[], 'intermedio', 'Moviliza la columna y activa glúteos e isquios con una extensión controlada en el suelo.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2869'),
('99599116-5574-501f-9504-ce4daf3616a7', 'Postura de la palmera al viento', ARRAY['De pie con los pies juntos, eleva los brazos por encima de la cabeza con las palmas enfrentadas.', 'Inclina el tronco hacia un lado manteniendo las caderas firmes y el abdomen activo.', 'Vuelve al centro y repite hacia el otro lado con un movimiento fluido y respirando.', 'Evita arquear la espalda o desplazar las caderas al inclinarte.']::text[], 'intermedio', 'Trabaja el abdomen y la estabilidad lateral del tronco con una inclinación controlada de pie.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4404'),
('e5c31329-e125-5c6e-b034-bf0d924399ea', 'Círculo de pierna de natación', ARRAY['Túmbate boca arriba con las piernas extendidas y los brazos junto al cuerpo.', 'Eleva una pierna y dibuja círculos pequeños manteniendo el abdomen firme.', 'Mantén la zona lumbar pegada al suelo y respira de forma constante.', 'Cambia de sentido y de pierna sin dejar que la cadera se balancee.']::text[], 'intermedio', 'Activa glúteos y flexores de cadera dibujando círculos controlados con la pierna en el suelo.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '6098'),
('7231fc01-4bcd-5c2c-a17a-5fc4e2c7d99f', 'Caderas de nadador', ARRAY['Túmbate boca abajo con los brazos extendidos por delante y las piernas juntas.', 'Eleva ligeramente el pecho y alterna brazos y piernas contrarios como si nadaras.', 'Mantén el cuello alineado con la columna y el abdomen activo.', 'Realiza el movimiento lento y controlado evitando arquear la zona lumbar.']::text[], 'intermedio', 'Fortalece la columna y la cadena posterior con un movimiento alterno que mejora la coordinación y la postura.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1612'),
('b2f1e4a4-4b62-5397-be59-13d49016dbeb', 'Patadas de nadador', ARRAY['Túmbate boca abajo con los brazos extendidos y la frente cerca del suelo.', 'Eleva ligeramente el pecho y da patadas alternas con las piernas sin tocar el suelo.', 'Mantén los glúteos activos y el cuello en línea con la columna.', 'Evita levantar demasiado las piernas o arquear la lumbar durante el movimiento.']::text[], 'intermedio', 'Trabaja la espalda y los glúteos con patadas alternas que activan la cadena posterior y el core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3227'),
('ffa32c54-be3d-5268-a5b8-9c63ab34a4e9', 'Nado', ARRAY['Túmbate boca abajo con los brazos extendidos por delante y las piernas juntas.', 'Eleva brazos, pecho y piernas del suelo manteniendo la mirada hacia abajo.', 'Alterna brazos y piernas contrarios con un ritmo constante y controlado.', 'Baja despacio y evita arquear el cuello o forzar la zona lumbar.']::text[], 'intermedio', 'Fortalece la columna y la cadena posterior con un movimiento alterno que mejora la coordinación y la estabilidad.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2870'),
('e7e066ae-5a58-5d6f-9506-b8bfb3132cec', 'Nado a cuatro apoyos', ARRAY['Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.', 'Extiende un brazo y la pierna contraria manteniendo la espalda recta.', 'Alterna lados con un ritmo controlado y el abdomen activo.', 'Evita balancear las caderas o arquear la lumbar al extender las extremidades.']::text[], 'intermedio', 'Activa la columna y el core con un movimiento alterno de brazos y piernas en cuadrupedia.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2880'),
('59d83693-6299-594f-bbdb-dc00297e8ffb', 'Natación estilo crol', ARRAY['Colócate en el agua con el cuerpo alineado y la cabeza en línea con la columna.', 'Bate las piernas de forma continua y alterna los brazos en ciclo completo.', 'Gira la cabeza para respirar hacia un lado sin levantar el cuello.', 'Mantén un ritmo constante y evita cruzar los brazos por delante de la línea media.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la resistencia trabajando hombros, dorsales y core en el agua.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '6944'),
('5a9e6afa-5703-556b-be28-ca6061396f65', 'Giro 360', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Mantén los brazos extendidos rectos frente a ti, paralelos al suelo.', 'Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces.', 'Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado.', 'Recuerda respirar durante todo el ejercicio.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca con un giro completo que también activa hombros y core.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3318'),
('ef4deb17-8bd3-59af-92f3-1d5bd296a751', 'Ejercicio en T', ARRAY['Coloca cuatro conos formando una T y sitúate en la base.', 'Corre hacia el cono central, desplázate lateralmente hasta cada extremo y vuelve al centro.', 'Regresa a la base corriendo hacia atrás con pasos cortos y controlados.', 'Mantén las rodillas alineadas con los pies y evita cruzar las piernas en los desplazamientos laterales.']::text[], 'intermedio', 'Mejora la agilidad y la coordinación con desplazamientos rápidos que activan piernas y glúteos.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5976'),
('0040b09c-1e4e-5e13-8a02-7f5336000d86', 'Puente de mesa', ARRAY['Siéntate en el suelo con las rodillas flexionadas y las manos apoyadas detrás de la cadera.', 'Empuja con manos y pies para elevar la cadera hasta formar una línea recta.', 'Aprieta los glúteos arriba y mantén el abdomen activo sin arquear la lumbar.', 'Baja de forma controlada y evita encoger los hombros o bloquear los codos.']::text[], 'intermedio', 'Fortalece glúteos e isquios con una extensión de cadera que también activa el core y los tríceps.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4800'),
('ee766879-ae15-58f3-be4a-26544be05fb1', 'Puente en mesa con patada', ARRAY['Siéntate en el suelo con las manos detrás y los pies apoyados, y eleva la cadera hasta formar una línea recta.', 'Extiende una pierna hacia delante sin dejar caer la cadera y vuelve a apoyarla con control.', 'Alterna las piernas manteniendo el abdomen firme y respirando de forma constante.', 'Evita arquear la zona lumbar: aprieta los glúteos y mantén las costillas abajo.']::text[], 'intermedio', 'Activa glúteos e isquios mientras el core y los hombros estabilizan la cadera elevada en cada extensión de pierna.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10057'),
('1193f33b-7e30-5af4-8c43-a5c10973173a', 'Rotación en puente de mesa', ARRAY['Colócate en puente de mesa con manos y pies apoyados y la cadera elevada.', 'Levanta un brazo y gíralo hacia el techo abriendo el pecho, sin mover la cadera.', 'Vuelve al centro y repite hacia el otro lado de forma alterna y lenta.', 'Mantén los glúteos activos y evita que la cadera se hunda al girar.']::text[], 'intermedio', 'Trabaja glúteos y oblicuos con control rotando el tronco en la posición de mesa, mejorando estabilidad y fuerza del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4801'),
('404b380d-a466-51e9-abea-34dcd63122fd', 'Teaser', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos hacia delante.', 'Sube el tronco y las piernas a la vez hasta formar una V, buscando el equilibrio.', 'Mantén la espalda larga y respira de forma pausada durante la subida y la bajada.', 'Evita tirar del cuello o redondear la espalda: controla el descenso vértebra a vértebra.']::text[], 'intermedio', 'Fortalece el abdomen y los flexores de cadera manteniendo el equilibrio sobre los isquiones con el tronco y las piernas elevados.', ARRAY['Estabilidad y Control Motor', 'Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['repeticiones']::text[], false, true, 3.0, 'pilates', '2871'),
('5910b6bb-df23-5579-aa2a-466f512df4bf', 'Prueba de Thomas frontal', ARRAY['Túmbate boca arriba en el borde de una superficie y abraza una rodilla al pecho.', 'Deja caer la otra pierna estirada y observa si el muslo se despega de la superficie.', 'Mantén la zona lumbar apoyada y respira con normalidad durante la valoración.', 'Evita compensar arqueando la espalda: si duele, no fuerces la pierna hacia abajo.']::text[], 'principiante', 'Evalúa la flexibilidad de cuádriceps y flexores de cadera tumbado, detectando acortamientos que afectan a la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6795'),
('be46774c-6c92-5dfe-8404-7fca2207f58d', 'Prueba de Thomas', ARRAY['Túmbate boca arriba con la cadera en el borde de una camilla o banco.', 'Abraza una rodilla al pecho y deja que la otra pierna cuelgue relajada.', 'Observa si el muslo baja hasta la horizontal y si la rodilla se extiende.', 'Evita empujar la pierna hacia abajo: deja que la gravedad actúe sin forzar.']::text[], 'principiante', 'Valora la flexibilidad de cuádriceps y flexores de cadera para detectar acortamientos que influyen en la postura y el rendimiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '6794'),
('725958fc-8d2d-5713-8972-c323aac6c56a', 'Puente torácico', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Apoya los brazos y eleva la cadera y la zona media del tronco hacia arriba.', 'Abre el pecho y lleva los omóplatos hacia abajo mientras respiras profundo.', 'Evita cargar el cuello: mantén la mirada al frente y no fuerces la lumbar.']::text[], 'principiante', 'Moviliza la columna torácica y abre el pecho, mejorando la extensión de la espalda con ayuda de glúteos y hombros.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4553'),
('8863098c-558a-5af5-85b3-380d8f7301f2', 'Postura de enhebrar la aguja', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Pasa un brazo por debajo del cuerpo y apoya el hombro y la sien en el suelo.', 'Mantén la cadera alta y respira profundo sintiendo el estiramiento entre los omóplatos.', 'Evita cargar el cuello: deja que la cabeza descanse sin empujar.']::text[], 'intermedio', 'Estira la espalda alta y los hombros, liberando tensión entre los omóplatos y mejorando la movilidad torácica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5904'),
('8e69c2e2-54d2-53a1-a979-4318a3cceadf', 'Fondos entre tres bancos', ARRAY['Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.', 'Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.', 'Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.', 'Empújate de vuelta hacia arriba hasta la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombros con el peso corporal, mejorando la fuerza de empuje en la parte superior del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1753'),
('b0a57adc-6f14-5644-a5dd-4553d7a66cba', 'Abducción del pulgar', ARRAY['Coloca la mano abierta sobre una superficie con la palma hacia arriba.', 'Separa el pulgar del resto de los dedos de forma lenta y controlada.', 'Mantén la posición un par de segundos y vuelve despacio al inicio.', 'Evita mover la muñeca o el codo: aísla el movimiento en el pulgar.']::text[], 'principiante', 'Moviliza el pulgar y fortalece antebrazo y mano, mejorando la estabilidad de la muñeca en agarres y gestos diarios.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '10032'),
('ae63da3c-bd2c-58fc-8812-7f15ca41fc50', 'Estiramiento de pulgar', ARRAY['Extiende un brazo al frente con la palma hacia arriba y la mano relajada.', 'Con la otra mano, lleva el pulgar suavemente hacia abajo y hacia fuera.', 'Mantén el estiramiento sin dolor durante unos segundos y respira.', 'Evita tirar con fuerza o rebotar: busca una tensión suave y constante.']::text[], 'principiante', 'Estira antebrazo y mano alargando los flexores del pulgar, aliviando tensión tras escribir o usar el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2094'),
('19ffaf4e-56f8-56df-be69-88a58fd3eefc', 'Estiramiento tibial en espaldera', ARRAY['Apoya la punta de un pie en la espaldera con el talón en el suelo.', 'Lleva la rodilla hacia delante suavemente hasta notar tensión en la espinilla.', 'Mantén la posición sin dolor y respira de forma pausada.', 'Evita levantar el talón o forzar el tobillo en exceso.']::text[], 'principiante', 'Estira la parte anterior de la pierna y el tobillo, aliviando la tensión tibial tras correr o caminar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1928'),
('83936104-196e-5289-8aeb-ee8280fd023e', 'Estiramiento tibial con rodilla semiflexionada', ARRAY['Apoya la punta del pie en el suelo o en una pared con el talón apoyado.', 'Flexiona ligeramente la rodilla y lleva la pelvis hacia delante con control.', 'Mantén la tensión suave en la espinilla y respira con normalidad.', 'Evita rebotar o cargar el peso en exceso sobre el tobillo.']::text[], 'principiante', 'Estira la espinilla y el sóleo con la rodilla ligeramente doblada, útil para aliviar tensión en la parte baja de la pierna.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1929'),
('4d933200-1bf6-5270-9fb1-61c5d8b4a1ff', 'Postura de curl del tigre', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Redondea la espalda llevando el pubis hacia el ombligo y la barbilla al pecho.', 'Mantén la contracción unos segundos y vuelve despacio a la posición neutra.', 'Evita bloquear los codos o cargar el cuello al redondear la espalda.']::text[], 'intermedio', 'Fortalece abdomen y zona lumbar con el redondeo controlado de la columna, mejorando el control del core.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5905'),
('b4c7f13b-6ee9-55e3-b4e5-070e961ba73e', 'Rodillo en antebrazo', ARRAY['Coloca el antebrazo sobre el rodillo con la palma hacia abajo.', 'Rueda despacio desde la muñeca hasta el codo buscando puntos de tensión.', 'Detente en las zonas sensibles y mantén la presión unos segundos.', 'Evita rodar sobre el codo o aplicar demasiada presión que cause dolor.']::text[], 'principiante', 'Libera tensión en antebrazo y muñeca con el rodillo, mejorando la movilidad y aliviando sobrecargas por agarre.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4220'),
('e7102f51-3404-5414-ae10-0aa2d2d87119', 'Rodillo en isquiotibiales', ARRAY['Siéntate con el rodillo bajo un muslo y apoya las manos detrás para sostenerte.', 'Desliza el rodillo desde justo debajo del glúteo hasta encima de la rodilla con presión cómoda.', 'Hazlo lento, unas diez pasadas por pierna, respirando de forma continua.', 'Detente en los puntos más sensibles y evita rodar directamente sobre la rodilla o el hueco poplíteo.']::text[], 'principiante', 'Libera tensión en la parte posterior del muslo y mejora la movilidad de la cadera antes o después de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4221'),
('f9b32656-2324-5623-a38f-012eb112f009', 'Rodillo en cuello', ARRAY['Túmbate boca arriba con el rodillo bajo la nuca y las rodillas flexionadas.', 'Gira la cabeza despacio de un lado a otro mientras mantienes una presión suave.', 'Respira profundo y mantén cada lado unos veinte segundos.', 'Evita presionar sobre la columna cervical y no fuerces el rango de giro.']::text[], 'principiante', 'Alivia la tensión del elevador de la escápula y la zona cervical, útil tras muchas horas de estudio o pantallas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4222'),
('ac2e6d38-1a06-5ffd-9de6-1237112e5dff', 'Rodillo en peroneos', ARRAY['Túmbate de lado con el rodillo bajo la parte externa de la pierna, justo bajo la rodilla.', 'Apoya el otro pie y el antebrazo para controlar la presión.', 'Desliza el rodillo desde debajo de la rodilla hasta el tobillo con movimientos lentos.', 'Evita rodar sobre el hueso del peroné y detente si notas dolor punzante.']::text[], 'principiante', 'Relaja la cara externa de la pierna y el tobillo, mejorando la movilidad y reduciendo tensión en la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4223'),
('948d1e96-ea83-5cc9-af28-5c0c3f494480', 'Fondos de tríceps en banco', ARRAY['Siéntate en el borde de un banco con las manos a los lados y desliza el cuerpo hacia delante.', 'Flexiona los codos hacia atrás hasta que los brazos formen unos noventa grados.', 'Empuja con las palmas para volver arriba sin bloquear del todo los codos.', 'Mantén los hombros abajo y evita encogerlos hacia las orejas durante el movimiento.']::text[], 'intermedio', 'Fortalece el tríceps y la estabilidad del hombro usando el peso corporal, útil para empujes y fondos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4407'),
('d6d46b3c-3275-5540-bf20-0c71a1c154d0', 'Postura del tigre', ARRAY['Colócate a cuatro patas con las manos bajo los hombros y las rodillas bajo la cadera.', 'Redondea la espalda y lleva una rodilla hacia el pecho sin apoyar el pie.', 'Estira esa pierna hacia atrás mientras alargas la columna y miras al frente.', 'Alterna lados con calma y evita arquear en exceso la zona lumbar.']::text[], 'intermedio', 'Moviliza la columna y activa el core y los glúteos en una postura de yoga dinámica y controlada.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4406'),
('3b9f2a57-333b-5592-9a2b-6241309fc3c9', 'Caminata en cuerda floja', ARRAY['Coloca una línea en el suelo o imagina una cuerda recta frente a ti.', 'Camina poniendo un pie justo delante del otro, como si anduvieras sobre una cuerda.', 'Mantén el core activo y la mirada al frente, no al suelo.', 'Evita balancear los brazos en exceso y camina lento para no perder el control.']::text[], 'principiante', 'Mejora el equilibrio y la propiocepción del tobillo y el pie, reforzando la estabilidad del tren inferior.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '5977'),
('be26f7cb-e1f8-5d3f-86f9-6a76a232414d', 'Volteo de llanta', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático.', 'Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla.', 'Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti.', 'Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo.', 'Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control.', 'Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio global de potencia que activa glúteos, isquiotibiales y core con una carga pesada e inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2459'),
('213aecde-8256-5bba-b851-cb0ebfcbb95f', 'Salto de puntillas', ARRAY['Colócate de pie con los pies a la anchura de la cadera y las rodillas ligeramente flexionadas.', 'Impúlsate con los tobillos para saltar lo más alto posible manteniendo las piernas casi rectas.', 'Aterriza suavemente sobre las puntas y amortigua con el tobillo.', 'Evita caer con las rodillas rígidas y mantén un ritmo controlado.']::text[], 'intermedio', 'Trabaja la reactividad y la fuerza elástica del gemelo y el tobillo con un gesto rápido y controlado.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '4904'),
('b8c45f16-1545-5c90-8924-12a0e660b257', 'Caminata lateral sobre puntas', ARRAY['Ponte de pie sobre las puntas de los pies con el core activo.', 'Da pasos laterales cortos y controlados sin bajar los talones.', 'Mantén el tronco erguido y la mirada al frente durante todo el recorrido.', 'Evita cruzar los pies o inclinarte hacia los lados para no perder el equilibrio.']::text[], 'intermedio', 'Refuerza gemelos y tobillos en el plano lateral, mejorando la estabilidad y la fuerza del pie.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10762'),
('9f9a00ed-a79d-54ec-995e-cbe46bbf6335', 'Sentadilla isométrica en la pared con toque de pies', ARRAY['Apoya la espalda en la pared y desliza hasta que los muslos queden paralelos al suelo.', 'Mantén las rodillas alineadas con los pies y la espalda pegada a la pared.', 'Levanta alternativamente las puntas de los pies sin mover la cadera.', 'Respira de forma continua y evita aguantar la respiración durante el sostén.']::text[], 'intermedio', 'Mantiene el cuádriceps bajo tensión y añade control del pie, mejorando la resistencia y la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0810'),
('1dc95318-3cef-5d95-a810-8cfb92164358', 'Caminata de puntillas', ARRAY['Ponte de pie y elévate sobre las puntas de los pies.', 'Camina hacia delante con pasos cortos manteniendo los talones elevados.', 'Mantén el core activo y el tronco erguido sin balancearte.', 'Evita apoyar los talones o caminar demasiado rápido para no perder el control.']::text[], 'intermedio', 'Fortalece gemelos y pies con un gesto sencillo que mejora la estabilidad del tobillo al caminar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4802'),
('07a9e95f-72b5-5000-b3ec-3d448541f30f', 'Sostén arriba en dominada', ARRAY['Súbete a la barra con un agarre prono y llévate hasta que la barbilla pase la barra.', 'Mantén los codos flexionados y los hombros activos, lejos de las orejas.', 'Aprieta la barra y sostén la posición el tiempo indicado respirando con control.', 'Evita balancearte o perder la tensión de la espalda durante el sostén.']::text[], 'intermedio', 'Refuerza la espalda y el agarre manteniendo la posición alta de la dominada de forma isométrica.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '4983'),
('c5b5fd1c-ebd4-5cd6-9272-6b740c4196a6', 'Empuje de trineo', ARRAY['Coloca las manos en las asas del trineo y adopta una postura inclinada con el core firme.', 'Empuja con las piernas dando pasos cortos y potentes sin bloquear los codos.', 'Mantén la espalda recta y la mirada al frente durante todo el recorrido.', 'Evita encorvar la zona lumbar o dar zancadas demasiado largas.']::text[], 'intermedio', 'Trabajo cardiovascular y de fuerza que implica piernas y core empujando una carga resistida.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '8702'),
('abf7cd5e-79d9-50b0-bdee-93182b010d3e', 'Estiramiento del soldado de juguete', ARRAY['Camina hacia delante y da una patada recta con una pierna intentando tocar la punta del pie.', 'Alterna las piernas de forma rítmica sin bloquear la rodilla de apoyo.', 'Mantén el tronco erguido y el core activo durante todo el movimiento.', 'Evita rebotar con fuerza o redondear la espalda al bajar la mano.']::text[], 'principiante', 'Estiramiento dinámico que moviliza isquiotibiales y cadera, ideal como calentamiento previo al entrenamiento.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '5978'),
('cfb50f74-62e5-54d6-be33-b7e0de4e5e3f', 'Zancada en plano transversal con mancuernas', ARRAY['Sujeta una mancuerna en cada mano y colócate de pie con los pies a la anchura de la cadera.', 'Da un paso en diagonal hacia atrás y flexiona las rodillas manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver al centro y alterna lados.', 'Evita que la rodilla delantera se meta hacia dentro y mantén el core activo.']::text[], 'intermedio', 'Trabaja glúteos y estabilidad de cadera en un plano rotacional, útil para deportes y prevención de lesiones.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1696'),
('eb9c2658-c388-5406-add9-23c788bd3308', 'Subida transversal al banco', ARRAY['Colócate de lado al banco con un pie encima y el otro en el suelo.', 'Empuja con la pierna de arriba para subir, llevando la rodilla contraria hacia arriba.', 'Baja controlando el movimiento hasta tocar el suelo con el pie libre.', 'Mantén el tronco erguido y evita girar la cadera hacia fuera.']::text[], 'intermedio', 'Fortalece glúteos y piernas al subir de lado, mejorando estabilidad y potencia para escaleras y arranques.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1602'),
('39d4b878-31d0-5b3a-a5a5-73960ffb77fb', 'Estiramiento de trapecio y cuello', ARRAY['Siéntate o ponte de pie con la espalda recta y los hombros relajados.', 'Inclina la cabeza hacia un lado llevando la oreja al hombro sin subir el hombro.', 'Ayúdate con la mano del mismo lado para aumentar suavemente el estiramiento.', 'Mantén veinte o treinta segundos respirando despacio y cambia de lado.', 'Evita tirar de la cabeza hacia delante ni forzar el cuello.']::text[], 'principiante', 'Relaja trapecios y cuello, aliviando tensión acumulada por estudiar o pasar horas frente al ordenador.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1791'),
('321fad1e-15be-5ea6-8294-3fea8057d029', 'Peso muerto con barra hexagonal y banda elástica', ARRAY['Coloca la banda bajo la barra hexagonal y pisa los extremos o engánchalos.', 'Agarra los manerales con la espalda recta y el pecho arriba.', 'Empuja el suelo con los pies y extiende la cadera hasta ponerte de pie.', 'Baja controlando la banda y mantén la barra cerca del cuerpo.', 'Evita redondear la espalda o tirar con los brazos.']::text[], 'intermedio', 'Trabaja glúteos e isquios con resistencia extra en la subida, ganando fuerza y potencia en el empuje de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4842'),
('e4ef9d49-f7c5-5605-a01d-c18a959ae3b5', 'Remo inclinado con barra hexagonal', ARRAY['Sujeta la barra hexagonal con las manos y flexiona la cadera hasta inclinar el tronco.', 'Mantén la espalda recta y las rodillas ligeramente flexionadas.', 'Tira de la barra hacia el abdomen juntando las escápulas.', 'Baja controlando el movimiento sin perder la posición del tronco.', 'Evita balancear el cuerpo o encoger los hombros al tirar.']::text[], 'intermedio', 'Refuerza la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción en el día a día.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4104'),
('4cfd1c3a-5405-5e3a-96e7-a7bb15a71423', 'Peso muerto con barra hexagonal', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y la barra hexagonal en el suelo frente a ti.', 'Flexiona las caderas y las rodillas para bajar y agarra las asas de la barra hexagonal con un agarre prono.', 'Mantén la espalda recta y el pecho elevado mientras comienzas a levantar la barra hexagonal del suelo extendiendo las caderas y las rodillas.', 'Al levantar, concéntrate en empujar con los talones y contraer los glúteos en la parte superior del movimiento.', 'Baja la barra hexagonal de nuevo al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos, isquios y espalda baja con un patrón de empuje más seguro para la columna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0811'),
('e71a4976-7a79-549e-98bc-3c51535d9a09', 'Peso muerto con barra hexagonal desde déficit', ARRAY['Colócate sobre una plataforma baja con la barra hexagonal delante.', 'Agarra los manerales con la espalda recta y el pecho arriba.', 'Empuja el suelo con los pies y extiende la cadera hasta ponerte de pie.', 'Baja controlando hasta tocar la plataforma sin redondear la espalda.', 'Evita perder la tensión del core o levantar los talones.']::text[], 'intermedio', 'Aumenta el rango de movimiento para trabajar glúteos e isquios con más intensidad y mejorar la fuerza inicial.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4105'),
('d9c46d54-a01f-5a68-8d8a-3d8235bbc43d', 'Paseo del granjero con barra hexagonal', ARRAY['Agarra la barra hexagonal con las manos y ponte de pie con la espalda recta.', 'Camina con pasos cortos y firmes manteniendo el tronco erguido.', 'Mantén los hombros atrás y el core activado durante todo el recorrido.', 'Respira de forma constante y evita inclinarte hacia los lados.', 'Suelta la barra con control al terminar el recorrido.']::text[], 'intermedio', 'Fortalece trapecios, agarre y core mientras caminas, mejorando la resistencia y la estabilidad general.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2912'),
('c5741835-8922-5704-bb35-ea0ed531d912', 'Sentadilla con salto con barra hexagonal', ARRAY['Sujeta la barra hexagonal con los brazos extendidos y los pies a la anchura de los hombros.', 'Flexiona rodillas y cadera para bajar manteniendo el pecho arriba.', 'Salta con fuerza extendiendo las piernas y aterriza con las rodillas flexionadas.', 'Amortigua el impacto y vuelve a la posición inicial con control.', 'Evita aterrizar con las piernas rígidas o perder la espalda recta.']::text[], 'intermedio', 'Desarrolla potencia de piernas con un salto explosivo, útil para deportes que requieren velocidad y salto.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '4166'),
('1cc53f53-8ad0-544c-8f10-fcc6c569d45c', 'Press militar con barra hexagonal', ARRAY['Sujeta la barra hexagonal a la altura de los hombros con los codos hacia delante.', 'Activa el core y empuja la barra hacia arriba hasta extender los brazos.', 'Baja controlando hasta la altura de los hombros sin arquear la espalda.', 'Respira al empujar y evita bloquear las rodillas o inclinarte atrás.']::text[], 'intermedio', 'Fortalece hombros y tríceps al empujar por encima de la cabeza, mejorando la fuerza de empuje vertical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7287'),
('66c55e2a-2744-57f3-b2ee-6725f8801ba3', 'Peso muerto rumano con postura dividida y barra hexagonal', ARRAY['Coloca un pie delante y otro detrás con la barra hexagonal sujeta con las manos.', 'Flexiona la cadera llevando el tronco hacia delante con la espalda recta.', 'Baja hasta notar el estiramiento en los isquios de la pierna delantera.', 'Vuelve arriba empujando la cadera hacia delante y cambia de pierna.', 'Evita redondear la espalda o bloquear la rodilla delantera.']::text[], 'intermedio', 'Estira y fortalece isquios y glúteos con una base más estable, mejorando el equilibrio y la fuerza unilateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3652'),
('3c7b1c04-af45-5174-aca9-0ad1c6f819f0', 'Sentadilla con barra hexagonal', ARRAY['Sujeta la barra hexagonal con los brazos extendidos y los pies a la anchura de los hombros.', 'Flexiona rodillas y cadera bajando con el pecho arriba y la espalda recta.', 'Baja hasta donde puedas mantener la técnica y empuja el suelo para subir.', 'Mantén los talones apoyados y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con una barra que facilita el equilibrio, ideal para ganar fuerza en las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5304'),
('c5393fcc-9e6e-551c-bb8d-8c5f514fef12', 'Encogimientos de pie con barra hexagonal', ARRAY['Sujeta la barra hexagonal con los brazos extendidos y los pies a la anchura de los hombros.', 'Sube los hombros hacia las orejas sin doblar los codos.', 'Mantén un segundo arriba y baja controlando el movimiento.', 'Evita girar los hombros o usar impulso con las piernas.']::text[], 'intermedio', 'Aísla los trapecios para ganar fuerza y volumen en la parte alta de la espalda y el cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4103'),
('841a12e1-b495-593b-a93c-825d0cb65a73', 'Postura del árbol vrksasana', ARRAY['Ponte de pie con la espalda recta y la mirada al frente.', 'Apoya la planta del pie en el gemelo o el muslo de la otra pierna.', 'Junta las manos delante del pecho y mantén la posición respirando despacio.', 'Fija la mirada en un punto para no perder el equilibrio.', 'Evita apoyar el pie directamente en la rodilla o inclinarte hacia un lado.']::text[], 'intermedio', 'Mejora el equilibrio y la estabilidad del core mientras fortalece glúteos y tobillos en una postura de yoga.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0961'),
('576a6018-a203-5c48-8e12-07b6c0b0874e', 'Postura del triángulo trikonasana', ARRAY['Ponte de pie con las piernas abiertas y los brazos en cruz.', 'Gira el pie delantero hacia fuera y lleva el tronco hacia ese lado.', 'Baja la mano hacia la espinilla o el suelo y extiende el otro brazo hacia arriba.', 'Mantén la mirada en la mano elevada y respira despacio.', 'Evita bloquear la rodilla delantera o redondear la espalda.']::text[], 'principiante', 'Estira isquios y costados mientras fortalece oblicuos y hombros, mejorando la flexibilidad y la postura.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0962'),
('dea82396-3b6e-5cde-aa50-1b1b981ea001', 'Fondos de tríceps', ARRAY['Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.', 'Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.', 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja tríceps con apoyo del propio peso y también pecho y hombros; sirve para ganar fuerza en empuje y brazos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0814'),
('0b4d4fb6-fcbd-503c-ad09-95bf986b3a04', 'Fondos de tríceps en paralelas altas', ARRAY['Colócate entre las barras con los brazos extendidos y el cuerpo ligeramente inclinado hacia delante.', 'Baja doblando los codos hasta que los hombros queden a la altura de los codos, sin forzar.', 'Empuja con las palmas para volver arriba controlando el movimiento.', 'Mantén el core activo y evita encoger los hombros hacia las orejas.']::text[], 'intermedio', 'Fortalece tríceps, pecho y hombros; ideal para ganar fuerza en empuje y dominar fondos completos.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8143'),
('f2c3b469-9917-5b49-94fd-c0ebcee97288', 'Estiramiento de tríceps en el suelo', ARRAY['Siéntate en el suelo con las manos apoyadas detrás y los dedos apuntando hacia atrás.', 'Desliza la cadera hacia delante hasta notar tensión en la parte posterior del brazo.', 'Mantén el pecho abierto y respira despacio sin rebotar.', 'Evita bloquear los codos o cargar demasiado peso sobre las muñecas.']::text[], 'principiante', 'Relaja tríceps, hombros y dorsales tras el entrenamiento, mejorando la movilidad del brazo por detrás de la cabeza.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1492'),
('4f8f86b8-4c07-554e-8421-6e0952817b70', 'Press de tríceps', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.', 'Extiende los brazos rectos frente a ti, paralelos al suelo.', 'Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados.', 'Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los tríceps con el peso corporal y algo de hombro, útil para mejorar el empuje y la estabilidad del brazo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0816'),
('72a8bddb-052b-59b9-a2ee-ec26013cb4c2', 'Estiramiento de tríceps', ARRAY['Ponte de pie o siéntate erguido con la espalda recta.', 'Extiende un brazo por encima de la cabeza, flexionándolo por el codo.', 'Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.', 'Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.', 'Suelta el estiramiento y repite con el otro brazo.']::text[], 'principiante', 'Estira el tríceps y parte del hombro para aliviar tensión tras el entrenamiento y mejorar la movilidad del brazo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0817'),
('e2b59b15-1cc9-5fd7-8c89-6233001c83ab', 'Estiramiento de tríceps contra la pared', ARRAY['Colócate de lado a la pared y apoya el codo y el antebrazo contra ella.', 'Gira el tronco suavemente hacia el lado contrario hasta notar el estiramiento.', 'Mantén la posición unos segundos respirando con calma.', 'Evita forzar el hombro o levantar el codo del apoyo.']::text[], 'principiante', 'Estira tríceps, hombros y dorsales usando la pared como apoyo para ganar movilidad del brazo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1829'),
('c256d62b-cc8d-5cf7-942c-a08cb42942b7', 'Abdominal encogido', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.', 'Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.', 'Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen con un encogimiento corto y controlado, implicando también los flexores de cadera para estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0871'),
('fd811d7d-9f7d-525b-a341-3439c12f18e5', 'Tuck planche en paralelas bajas', ARRAY['Agarra las paralelas bajas con los brazos extendidos y los hombros por delante de las manos.', 'Recoge las rodillas hacia el pecho manteniendo la espalda redondeada.', 'Inclina el peso hacia delante hasta que los pies se separen del suelo.', 'Aprieta el core y aguanta la posición sin hundir los hombros.']::text[], 'avanzado', 'Isométrico avanzado que fortalece hombros, core y tríceps para progresar hacia la plancha completa.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10989'),
('5209eaea-9d33-5ba8-b63a-cbbb7bd6d280', 'Abdominal encogido de pie', ARRAY['Ponte de pie con los pies a la anchura de las caderas y el core activo.', 'Lleva las rodillas hacia el pecho encogiendo el abdomen al exhalar.', 'Baja las piernas controlando el movimiento sin arquear la espalda.', 'Evita tirar del cuello o usar impulso de brazos.']::text[], 'intermedio', 'Trabaja abdomen y flexores de cadera elevando las rodillas de pie, útil para el core y la coordinación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3969'),
('d85cc209-7c0b-5819-a427-834f432a9cc0', 'Jalón al pecho con doble agarre paralelo', ARRAY['Ajusta la altura del asiento y colócate de frente a la máquina de cable.', 'Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros.', 'Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo.', 'Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral.', 'Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí.', 'Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.', 'Suelta lentamente las asas y vuelve a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Trabaja dorsales con apoyo de bíceps, romboides y deltoides posterior; sirve para ganar fuerza de tracción y amplitud de espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0818'),
('a3c6b806-6b6c-5835-af79-ad51b8131485', 'Abdominal con giro y piernas arriba', ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas flexionadas.', 'Eleva los hombros del suelo y lleva una mano hacia el pie contrario girando el tronco.', 'Vuelve al centro y alterna hacia el otro lado exhalando en cada giro.', 'Evita tirar del cuello o dejar caer la zona lumbar.']::text[], 'intermedio', 'Activa abdomen y oblicuos con las piernas elevadas, mejorando el control del core y la rotación.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5514'),
('0cba8592-7362-5ab8-8380-eca190c980e8', 'Elevación de cadera con giro', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Coloca las manos a los lados para mayor apoyo.', 'Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.', 'Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.', 'Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.', 'Continúa alternando los giros el número de repeticiones deseado.']::text[], 'intermedio', 'Activa glúteos con ayuda de oblicuos e isquios; mejora la extensión de cadera y el control rotacional del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1466'),
('b0375945-d80f-5d6d-ab07-a32a02c410b2', 'Flexión con giro', ARRAY['Colócate en posición de flexión con las manos bajo los hombros y el cuerpo alineado.', 'Baja el pecho doblando los codos y empuja para volver arriba.', 'Al subir, gira el tronco y eleva un brazo hacia el techo.', 'Baja el brazo y repite alternando lados sin hundir la cadera.']::text[], 'intermedio', 'Combina empuje de pecho y tríceps con rotación de oblicuos, mejorando fuerza y estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3964'),
('6e87a42a-7f22-5221-b0c2-2fa91cc416a1', 'Puente lateral con giro', ARRAY['Apóyate de lado sobre el antebrazo con los pies apilados y el cuerpo alineado.', 'Eleva la cadera formando una línea recta desde la cabeza a los pies.', 'Gira el tronco llevando el brazo libre hacia el techo y vuelve.', 'Evita dejar caer la cadera o encoger el hombro de apoyo.']::text[], 'intermedio', 'Refuerza oblicuos, core y hombros con un puente lateral dinámico que mejora la estabilidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0820'),
('000e545a-fd5e-5e70-a397-4acd0af47448', 'Sentadilla con giro', ARRAY['Ponte de pie con los pies a la anchura de los hombros y los brazos al frente.', 'Baja en sentadilla manteniendo el pecho alto y las rodillas alineadas.', 'Al subir, gira el tronco hacia un lado y vuelve al centro.', 'Alterna los lados y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos añadiendo rotación de oblicuos para mejorar movilidad y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0822'),
('d370d7bf-b1fe-5a0f-8516-756e35928168', 'Estiramiento con paso y giro', ARRAY['Da un paso largo hacia delante y baja la rodilla trasera hacia el suelo.', 'Gira el tronco hacia el lado de la pierna delantera llevando el brazo arriba.', 'Mantén la posición respirando y vuelve al centro.', 'Evita arquear la zona lumbar o forzar la rodilla delantera.']::text[], 'principiante', 'Moviliza cuádriceps, flexores de cadera y oblicuos con un paso y giro que prepara el cuerpo.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3956'),
('f7be909b-5272-54da-8985-ed3271cbb0f9', 'Superman con giro', ARRAY['Túmbate boca abajo con brazos y piernas extendidos y el cuello en línea con la espalda.', 'Eleva a la vez brazos y piernas del suelo sin forzar la lumbar.', 'Gira el tronco hacia un lado llevando el brazo hacia la cadera contraria y vuelve al centro.', 'Alterna el giro a cada lado manteniendo la respiración fluida.', 'Evita arquear en exceso el cuello mirando siempre al suelo.']::text[], 'intermedio', 'Fortalece la espalda baja, glúteos y oblicuos mientras mejora el control del core y la estabilidad del tronco.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4091'),
('0a01732a-c8a2-5f8e-a47e-ae152e45025f', 'Elevación con giro y vuelta', ARRAY['Túmbate boca arriba con las piernas elevadas y las rodillas ligeramente flexionadas.', 'Eleva el tronco llevando las manos hacia un lado de las piernas.', 'Gira el tronco hacia el otro lado de forma controlada y vuelve al centro.', 'Exhala al subir y gira, e inhala al bajar sin apoyar del todo la espalda.', 'Evita tirar del cuello con las manos y mantén el movimiento lento.']::text[], 'intermedio', 'Trabaja el abdomen y los oblicuos con un movimiento controlado que mejora la fuerza y la rotación del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7585'),
('103a3217-bb9c-5e5c-b469-77072adb950c', 'Postura de zancada con giro de pierna', ARRAY['Desde una zancada baja, apoya la rodilla trasera en el suelo y la delantera a 90 grados.', 'Gira el tronco hacia el lado de la pierna delantera apoyando la mano en el suelo.', 'Levanta la pierna trasera flexionada y sujétala con la mano libre si llegas.', 'Respira profundo y mantén la postura sin forzar la rodilla.', 'Evita perder el equilibrio girando el tronco demasiado rápido.']::text[], 'intermedio', 'Abre la cadera y estira los cuádriceps mientras activa oblicuos y glúteos para ganar movilidad y equilibrio.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5906'),
('587a6426-c0db-53fc-80df-20b8f2c581ea', 'Toque de ambas puntas de pie frontal', ARRAY['De pie con los pies juntos, brazos extendidos hacia arriba.', 'Baja el tronco llevando las manos hacia las puntas de los pies sin doblar las rodillas.', 'Exhala al bajar y sube despacio inhalando.', 'Evita rebotar al final del recorrido para no forzar la lumbar.', 'Mantén el cuello relajado y la mirada hacia abajo.']::text[], 'principiante', 'Mejora la flexibilidad de isquiotibiales y espalda baja mientras activa el abdomen en un gesto de movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3249'),
('3c76b84b-8343-5637-95da-3c1c8fee047d', 'Estiramiento de espalda colgado con dos manos', ARRAY['Agarra la espaldera con las dos manos a la altura que te permita colgarte.', 'Deja que el cuerpo cuelgue relajando los hombros y separando las escápulas.', 'Respira profundo y mantén el estiramiento sin balancearte.', 'Evita soltar de golpe o forzar si notas dolor en los hombros.', 'Baja con control apoyando los pies antes de soltar.']::text[], 'principiante', 'Estira dorsales, hombros y espalda alta colgándote de la espaldera para descomprimir la zona.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1799'),
('137d8be5-c0bc-5921-b542-61a031ce1fbf', 'Postura del bastón invertido a dos piernas', ARRAY['Túmbate boca arriba y apoya las manos junto a las orejas con los dedos hacia los hombros.', 'Empuja el suelo para elevar la cadera y apoyar la coronilla con control.', 'Extiende las piernas hacia arriba manteniendo los codos cerca de la cabeza.', 'Respira de forma constante y evita cargar el cuello.', 'Sal despacio bajando primero la espalda y luego la cadera.']::text[], 'intermedio', 'Fortalece la espalda, hombros y glúteos en una inversión que mejora la extensión y el control postural.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6302'),
('5a4160b4-114a-5ddd-b524-438672631900', 'Curl martillo con ambas piernas y toalla', ARRAY['Siéntate con las piernas flexionadas y pasa la toalla por debajo de los muslos.', 'Agarra los extremos con las palmas enfrentadas en posición de martillo.', 'Flexiona los codos tirando de la toalla mientras las piernas hacen resistencia.', 'Sube controlando y baja despacio sin perder la tensión.', 'Evita mover los hombros o balancear el tronco para no hacer trampa.']::text[], 'intermedio', 'Fortalece bíceps, braquial y antebrazos usando la resistencia de una toalla con las piernas.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3851'),
('2eba10b2-9464-564f-bf83-ecac333cc977', 'Curl de bíceps inverso con ambas piernas y toalla', ARRAY['Siéntate con las piernas flexionadas y la toalla pasada por debajo de los muslos.', 'Agarra los extremos con las palmas hacia abajo en agarre prono.', 'Flexiona los codos tirando de la toalla mientras las piernas resisten.', 'Sube y baja de forma lenta manteniendo las muñecas firmes.', 'Evita encoger los hombros o tirar con la espalda.']::text[], 'intermedio', 'Trabaja bíceps y antebrazos con agarre prono usando la toalla y las piernas como resistencia.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3850'),
('a4b0eab8-2d7a-52f0-b3ec-6c5b4c489f38', 'Trepa de dos cuerdas', ARRAY['Agarra una cuerda en cada mano con los brazos extendidos y los pies en el suelo.', 'Tira de una cuerda mientras subes el pie contrario y alterna el gesto.', 'Mantén el core activo y el cuerpo cerca de las cuerdas.', 'Respira de forma constante sin aguantar la respiración.', 'Evita balancearte o soltar una cuerda antes de asegurar el agarre.']::text[], 'intermedio', 'Desarrolla dorsales, bíceps y agarre en un ejercicio exigente que también activa el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '10439'),
('28388136-5bff-59b8-9096-73f4ec27ddf5', 'Salto de dos a una pierna', ARRAY['Colócate de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta hacia delante y aterriza sobre una sola pierna con la rodilla blanda.', 'Mantén el equilibrio un instante antes de volver a la posición inicial.', 'Alterna la pierna de aterrizaje en cada repetición.', 'Evita aterrizar con la rodilla bloqueada o hacia dentro.']::text[], 'intermedio', 'Mejora la potencia de piernas y la estabilidad al aterrizar sobre una sola pierna.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '10925'),
('314833f9-7443-5c90-86ec-dd7185ee8e79', 'Toque de dos pies', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.', 'Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.', 'Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'principiante', 'Moviliza la columna y estira isquiotibiales y glúteos con un gesto sencillo de flexión frontal.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3231'),
('5a5e62d0-9c02-5666-b2e2-be3c1b4e87e7', 'Dominada desigual', ARRAY['Agarra la barra con una mano en prono y la otra más alta o en supino.', 'Cuelga con los brazos extendidos y el core activo.', 'Tira para subir la barbilla por encima de la barra controlando el movimiento.', 'Baja despacio hasta extender los brazos sin soltar.', 'Evita balancearte o encoger los hombros al iniciar el tirón.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con un agarre asimétrico que corrige desequilibrios entre ambos lados.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6961'),
('67597e5b-d708-54ec-8124-19870796a3a7', 'Estiramiento de espalda alta', ARRAY['Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.', 'Extiende los brazos rectos frente a ti, paralelos al suelo.', 'Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo.', 'Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí.', 'Mientras elevas los brazos, aprieta los omóplatos entre sí.', 'Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite.']::text[], 'principiante', 'Relaja la musculatura de la espalda alta y los hombros para aliviar tensión acumulada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1365'),
('b9974c29-6810-5818-ba97-d3962f1ed81a', 'Perro boca arriba', ARRAY['Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.', 'Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.', 'Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.', 'Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.', 'Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Extiende la columna y abre el pecho y los hombros en una postura de yoga que mejora la movilidad.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '1366'),
('7a8601e7-76b5-5e24-977d-72eb0bfb6f00', 'V up', ARRAY['Túmbate boca arriba con brazos extendidos por encima de la cabeza y piernas estiradas.', 'Eleva a la vez tronco y piernas llevando las manos hacia los pies.', 'Forma una uve con el cuerpo y mantén un instante la posición.', 'Baja despacio sin apoyar del todo y repite con control.', 'Evita tirar del cuello o usar impulso para subir.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera elevando tronco y piernas a la vez en forma de uve.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '3622'),
('72fb55e0-c503-59e0-87b5-4b7d5cd4bfc7', 'Abdominal doble en v', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos extendidos por encima de la cabeza.', 'Sube a la vez el tronco y las piernas hasta tocarte los pies formando una V.', 'Baja despacio controlando el movimiento y sin dejar caer los pies de golpe.', 'Espira al subir e inspira al bajar, manteniendo el abdomen activo.', 'Evita tirar del cuello con las manos y no arquees la zona lumbar.']::text[], 'intermedio', 'Trabaja el recto abdominal y los flexores de cadera, mejorando la fuerza del core y la coordinación al subir piernas y tronco a la vez.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4002'),
('731746dc-890f-5c5b-a004-3cb6cf44cd51', 'V up y baja con balón de estabilidad', ARRAY['Túmbate con la espalda sobre el balón y sujeta el balón con las manos por encima de la cabeza.', 'Sube el tronco y las piernas a la vez llevando el balón hacia los pies.', 'Baja controlando el movimiento hasta estirarte de nuevo sobre el balón.', 'Espira al subir e inspira al bajar, manteniendo el abdomen firme.', 'Evita balancearte demasiado y no dejes que la lumbar se hunda.']::text[], 'principiante', 'Fortalece el abdomen y la zona baja del core con un apoyo inestable que exige más control y equilibrio en cada repetición.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2815'),
('f1133e3a-b992-510c-baf6-c4cbd3f330fb', 'Sostén en V', ARRAY['Siéntate con las piernas estiradas y el tronco ligeramente inclinado hacia atrás.', 'Eleva las piernas y los brazos hasta formar una V con el cuerpo.', 'Mantén la posición con la espalda recta y el abdomen apretado.', 'Respira de forma continua sin aguantar la respiración.', 'Evita redondear la espalda o dejar caer las piernas.']::text[], 'intermedio', 'Mantiene el abdomen y los flexores de cadera en tensión isométrica, mejorando la resistencia del core y la estabilidad del tronco.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '5344'),
('521e811f-6fb0-5211-9688-51be65a25909', 'Abdominal en v con palmada', ARRAY['Túmbate boca arriba con brazos y piernas estirados.', 'Sube tronco y piernas a la vez y da una palmada delante de los muslos.', 'Baja controlando el movimiento sin apoyar del todo los pies.', 'Espira al subir e inspira al bajar, manteniendo el ritmo.', 'Evita impulsarte con el cuello y no pierdas la tensión abdominal.']::text[], 'intermedio', 'Activa el abdomen y los flexores de cadera con un gesto explosivo que suma coordinación y potencia al trabajo del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4003'),
('10b7166b-27a0-52fb-9569-c99f05034b62', 'V-sit en el suelo', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.', 'Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas.', 'Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas.', 'Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Isométrico avanzado que exige fuerza y equilibrio del core, activando abdomen y flexores de cadera de forma sostenida.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '3420'),
('05f0b1b6-5535-5d98-ae80-ec453c7e21b3', 'Elevación de piernas en paralelas', ARRAY['Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto.', 'Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.', 'Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera colgado en paralelas, mejorando la fuerza del core y el control del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '0826'),
('3c187e52-cdfb-5a8f-b4f4-7bf4ca0c3c00', 'Escalador vertical', ARRAY['Colócate en posición de plancha con las manos bajo los hombros.', 'Lleva una rodilla hacia el pecho y vuelve a la posición inicial.', 'Alterna las piernas a un ritmo rápido y constante.', 'Mantén la cadera baja y el abdomen firme durante todo el ejercicio.', 'Evita elevar demasiado la cadera o perder la alineación del tronco.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca mientras activa core, cadera y cuádriceps, ideal para acondicionamiento cardiovascular y coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0827'),
('0a45b6b9-c189-587e-a262-3960db86ee62', 'Abdominal vertical', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Sube el tronco hacia las rodillas manteniendo la espalda recta.', 'Baja controlando el movimiento sin dejarte caer de golpe.', 'Espira al subir e inspira al bajar, con el abdomen activo.', 'Evita tirar del cuello con las manos y no encorves la espalda.']::text[], 'intermedio', 'Fortalece el recto abdominal y los oblicuos al incorporar el tronco, mejorando la fuerza del core y la estabilidad lumbar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5963'),
('ab0f1cc7-2be6-5764-92b4-c97b1a595784', 'Zancada sobre plataforma vibratoria', ARRAY['Colócate de pie sobre la plataforma con un pie delante y otro detrás.', 'Baja flexionando la rodilla delantera hasta unos 90 grados.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el tronco erguido y el abdomen activo durante todo el movimiento.', 'Evita que la rodilla delantera pase demasiado la punta del pie.']::text[], 'intermedio', 'Refuerza cuádriceps, glúteos e isquios con la inestabilidad de la plataforma, mejorando equilibrio y control postural.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2527'),
('2ef44c2b-cb2f-513a-9721-5a7af559019f', 'Plancha sobre plataforma vibratoria', ARRAY['Apoya antebrazos y pies sobre la plataforma en posición de plancha.', 'Alinea cabeza, cadera y talones en una línea recta.', 'Aprieta el abdomen y los glúteos para mantener la posición.', 'Respira con normalidad sin aguantar la respiración.', 'Evita hundir la cadera o elevar demasiado el trasero.']::text[], 'intermedio', 'Isométrico que activa el core, hombros y glúteos con una base inestable que incrementa la demanda de estabilidad.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '2526'),
('f8f066ad-7d05-584b-8007-4ced10aab165', 'De pie sobre plataforma vibratoria', ARRAY['Sube a la plataforma con los pies separados a la anchura de las caderas.', 'Flexiona ligeramente las rodillas y mantén el tronco erguido.', 'Aprieta el abdomen y reparte el peso entre ambos pies.', 'Respira con normalidad y mantén la posición el tiempo indicado.', 'Evita bloquear las rodillas o inclinarte hacia un lado.']::text[], 'principiante', 'Mejora el equilibrio y la activación de cuádriceps, gemelos y glúteos al mantener la postura sobre una superficie vibratoria.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2525'),
('e8484a08-2e04-5797-bda7-9a460dd7bb48', 'Vinyasa', ARRAY['Parte de posición de plancha con las manos bajo los hombros.', 'Baja el pecho flexionando los codos cerca del cuerpo.', 'Sube empujando con las manos y lleva el pecho hacia delante.', 'Eleva la cadera hacia el perro boca abajo y respira profundamente.', 'Evita dejar caer la cadera o bloquear los codos al bajar.']::text[], 'intermedio', 'Secuencia de yoga que fortalece tríceps, pecho y core mientras mejora la movilidad y la coordinación respiratoria.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5983'),
('f37abd78-4cd5-51bd-abb9-033d24eadb4d', 'Caminata', ARRAY['Camina con la espalda recta y la mirada al frente.', 'Balancea los brazos de forma natural acompañando el paso.', 'Apoya primero el talón y luego la punta del pie.', 'Mantén un ritmo constante y respira con normalidad.', 'Evita encorvarte o dar pasos demasiado cortos.']::text[], 'intermedio', 'Ejercicio cardiovascular de bajo impacto que activa piernas y glúteos, mejorando la resistencia y la salud general.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0828'),
('f47c1cd4-9bc8-5cbd-b866-a01125aecd7d', 'Caminata con patada', ARRAY['Camina con el tronco erguido y el abdomen activo.', 'Da un paso y, al apoyar, lanza una patada al frente con la otra pierna.', 'Alterna las piernas manteniendo un ritmo constante.', 'Respira con normalidad y mantén el equilibrio en cada patada.', 'Evita arquear la espalda o perder la postura al patear.']::text[], 'intermedio', 'Combina cardio y activación de isquios y cuádriceps, mejorando la coordinación y la resistencia de la pierna.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10749'),
('5903454a-5c23-581e-8308-48130f0498ca', 'Máquina de caminata ondulante', ARRAY['Sube a la elíptica y sujeta las asas con las manos.', 'Empieza a pedalear con un movimiento fluido y constante.', 'Mantén el tronco erguido y el abdomen activo.', 'Ajusta la resistencia para mantener una respiración controlada.', 'Evita apoyarte demasiado en las asas o encorvarte.']::text[], 'principiante', 'Ejercicio cardiovascular de bajo impacto que activa piernas y glúteos, mejorando la resistencia sin castigar las articulaciones.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2140'),
('cee0526f-c77a-5eb2-8d8e-e99c42290189', 'Caminar', ARRAY['Colócate de pie con la espalda recta y la mirada al frente.', 'Camina con paso natural apoyando primero el talón y luego la punta.', 'Mantén los hombros relajados y balancea los brazos con ritmo constante.', 'Respira de forma fluida y evita encorvar la espalda o mirar al suelo.']::text[], 'intermedio', 'Activa el sistema cardiovascular y tonifica piernas y glúteos, ideal para calentar o sumar actividad diaria.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2258'),
('4c2547ae-ef71-51a7-8b1c-76583b8aebda', 'Caminar hacia atrás en cinta', ARRAY['Sube a la cinta y selecciona una velocidad muy baja para empezar.', 'Agárrate a las barandillas y comienza a caminar de espaldas con pasos cortos.', 'Mantén el tronco erguido y la mirada al frente sin girar el cuello.', 'Aumenta la velocidad solo si controlas el paso y evita inclinarte hacia atrás.']::text[], 'principiante', 'Trabaja el sistema cardiovascular con un patrón inverso que activa cuádriceps, gemelos y glúteos.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '9608'),
('edbb3e70-a198-598e-a641-479edcb39ac2', 'Zancada caminando con rodillas altas', ARRAY['Ponte de pie con los pies separados a la altura de la cadera.', 'Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda.', 'Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados.', 'Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho.', 'Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada.', 'Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y fortalece piernas y glúteos combinando zancada y rodilla alta.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3655'),
('68c50d04-ac75-5d80-a14a-b2616de78fa6', 'Zancadas caminando', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada.', 'Mantén el torso erguido y la rodilla delantera alineada con el tobillo.', 'Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda.', 'Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece glúteos, cuádriceps e isquiotibiales mientras mejora el equilibrio y la estabilidad al avanzar.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1460'),
('b016e5aa-08d4-5bee-af52-90f86d893281', 'Caminata en cinta inclinada', ARRAY['Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada.', 'Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros.', 'Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta.', 'Activa los músculos del core y mantén la espalda recta durante todo el ejercicio.', 'Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular.', 'Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte.']::text[], 'principiante', 'Aumenta la intensidad cardiovascular y activa más glúteos y piernas al caminar cuesta arriba.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3666'),
('fe4d967a-0151-585f-98bb-d0e6f951725a', 'Caminata en escalera mecánica', ARRAY['Ajusta la máquina de escalones a un nivel cómodo.', 'Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte.', 'Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas.', 'Mantén una postura erguida y activa los músculos del core.', 'Continúa caminando durante la duración o distancia deseada.', 'Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio.', 'Recuerda enfriar y estirar después de completar el ejercicio.']::text[], 'intermedio', 'Eleva el pulso y trabaja piernas y glúteos simulando subir escaleras de forma continua.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2311'),
('f1797768-8937-5afe-bb09-a590e2ae6ff8', 'Caminar en cinta', ARRAY['Sube a la cinta y empieza a velocidad baja con la mirada al frente.', 'Camina con pasos naturales apoyando el pie completo en la banda.', 'Mantén el tronco erguido y los brazos relajados sin agarrarte.', 'Respira con normalidad y evita mirar al suelo o dar zancadas demasiado largas.']::text[], 'intermedio', 'Mejora la resistencia cardiovascular y activa piernas y glúteos con un ritmo controlado y seguro.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '2259'),
('528285ba-6481-5745-8c39-40d56b4d75c5', 'Estiramiento de dorsales caminando con las manos', ARRAY['Colócate de pie con los pies a la anchura de las caderas.', 'Flexiona el tronco y camina las manos hacia delante hasta apoyarlas en el suelo.', 'Empuja las caderas hacia atrás y alarga la espalda sintiendo el estiramiento.', 'Respira profundo y evita bloquear las rodillas o redondear la zona lumbar.']::text[], 'principiante', 'Estira dorsales y espalda alta, aliviando la tensión acumulada tras entrenar o estudiar muchas horas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '10590'),
('705cf151-5e51-5676-ab01-6ed6d5c9ba7a', 'Negativa de pino con apoyo en pared a tuck planche', ARRAY['Apoya las manos en el suelo cerca de la pared y sube a pino con los pies apoyados.', 'Mantén el core firme y los brazos extendidos antes de iniciar el descenso.', 'Baja despacio flexionando los codos hasta agrupar las rodillas hacia el pecho.', 'Controla el tempo en cada repetición y evita dejarte caer sin frenar.']::text[], 'avanzado', 'Fortalece hombros, tríceps y core controlando el descenso desde el pino hasta la plancha agrupada.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '10997'),
('e768dce4-cbb2-5d99-896e-3df81c372a33', 'Wall ball', ARRAY['Sujeta el balón a la altura del pecho con los pies a la anchura de los hombros.', 'Haz una sentadilla bajando las caderas por debajo de las rodillas.', 'Al subir, lanza el balón contra la pared con un impulso coordinado.', 'Recíbelo con las manos y encadena la siguiente repetición sin perder el ritmo.']::text[], 'intermedio', 'Ejercicio global que combina sentadilla y lanzamiento para trabajar piernas, hombros y core con intensidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2458'),
('a9edb965-db77-5fb4-a3fe-f645a3f88ea6', 'Círculos con balón en la pared', ARRAY['Apoya el balón en la pared a la altura del pecho con una mano.', 'Haz círculos lentos y controlados presionando el balón contra la pared.', 'Mantén el hombro bajo y el core activo durante todo el recorrido.', 'Cambia de sentido y de mano evitando encoger el cuello o perder el control.']::text[], 'principiante', 'Moviliza hombros y manguito rotador dibujando círculos controlados con el balón apoyado en la pared.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '0255'),
('a0f0d44b-cc4d-5851-aaa8-a6048d3b42ae', 'Sostén de pino con piernas divididas de cara a la pared', ARRAY['Colócate de cara a la pared y sube a pino con una pierna adelantada.', 'Apoya los talones en la pared y mantén los brazos extendidos.', 'Activa el core y respira de forma constante sin aguantar la respiración.', 'Evita arquear la espalda y baja con control al terminar el tiempo.']::text[], 'avanzado', 'Isométrico que fortalece hombros, tríceps y core mientras mejora el control del pino de cara a la pared.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '10998'),
('00a9de86-c4c3-5a5c-b58f-982840102f4d', 'Estiramiento de flexores en la pared', ARRAY['Apoya las palmas en la pared con los dedos apuntando hacia abajo.', 'Separa ligeramente los pies y lleva el peso hacia delante con suavidad.', 'Mantén el estiramiento sin dolor durante veinte o treinta segundos.', 'Respira despacio y evita forzar la muñeca o rebotar.']::text[], 'principiante', 'Estira muñecas y flexores de los dedos, útil tras sesiones de empuje o muchas horas tecleando.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '2092'),
('86e900a8-068f-557a-9391-1087552268e6', 'Toque de talón con presión en la pared', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados.', 'Presiona la zona lumbar contra el suelo y eleva ligeramente los hombros.', 'Lleva una mano hacia el talón del mismo lado y vuelve al centro.', 'Alterna lados sin arquear la espalda y espira al tocar el talón.']::text[], 'intermedio', 'Activa el abdomen y la zona baja del core con un movimiento controlado de toque de talón.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4096'),
('c9eef072-593e-5b1e-ad25-6694c510cd2e', 'Pulso en la pared', ARRAY['Apoya las manos en la pared a la altura del pecho con los codos flexionados.', 'Mantén el cuerpo alineado y los pies firmes en el suelo.', 'Haz pequeños pulsos acercando y alejando el pecho de la pared.', 'Mantén los codos cerca del cuerpo y evita encoger los hombros.']::text[], 'intermedio', 'Trabaja tríceps, pecho y hombros con pequeños pulsos controlados usando la pared como resistencia.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5174'),
('d16ae20c-2fb6-5b62-ac66-ae91ba8bc6a5', 'Sentadilla isométrica en pared con postura cerrada', ARRAY['Apoya toda la espalda en la pared y baja hasta que muslos y rodillas formen noventa grados.', 'Junta los pies y las rodillas, manteniendo el peso repartido en toda la planta.', 'Aguanta la posición respirando con normalidad sin contener el aire.', 'Evita que las rodillas se vayan hacia dentro o sobrepasen los pies.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos manteniendo la espalda apoyada, mejorando la resistencia muscular y la estabilidad de rodillas.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '7557'),
('6da6ec95-e4a9-5401-b478-c63acf0654cf', 'Sentadilla isométrica en pared desde déficit', ARRAY['Coloca los pies sobre una superficie elevada y apoya la espalda en la pared.', 'Desliza hasta que los muslos queden paralelos al suelo o algo más bajos.', 'Mantén el core activo y la respiración constante durante la espera.', 'No dejes que la zona lumbar se despegue de la pared.']::text[], 'intermedio', 'Trabaja cuádriceps y glúteos con mayor rango al colocar los pies elevados, aumentando la exigencia del isométrico.', ARRAY['Estabilidad y Control Motor', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['tiempo']::text[], false, true, 3.0, 'isometric', '7558'),
('a5563574-f8b5-5b3e-a2df-8baaf2d317da', 'Caminata de pared', ARRAY['Colócate boca abajo con los pies en la pared y las manos en el suelo.', 'Camina con las manos hacia atrás mientras subes los pies por la pared.', 'Llega a la vertical con el core firme y baja controlando el movimiento.', 'Evita arquear la espalda o perder la tensión abdominal en la subida.']::text[], 'intermedio', 'Refuerza hombros, tríceps y core elevando el cuerpo en vertical, mejorando la fuerza y el control del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5234'),
('1a3f275c-3cec-5584-a541-d6214765c596', 'Calentamiento en zancada', ARRAY['Da un paso amplio hacia delante y baja la rodilla trasera hacia el suelo.', 'Mantén el torso erguido y la rodilla delantera alineada con el pie.', 'Alterna las piernas a ritmo suave durante varias repeticiones.', 'Evita que la rodilla delantera se vaya hacia dentro.']::text[], 'principiante', 'Activa cuádriceps, glúteos y flexores de cadera preparando las piernas para el entrenamiento y mejorando la movilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '3465'),
('e25bd3b5-ba72-55da-9ed0-3b2cc1b98b5f', 'Postura del guerrero II', ARRAY['Separa bien los pies y gira el pie delantero hacia fuera con la rodilla flexionada.', 'Extiende los brazos en paralelo al suelo mirando por encima de la mano delantera.', 'Mantén el torso vertical y respira de forma profunda y constante.', 'Evita que la rodilla delantera sobrepase la punta del pie.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras abre caderas y hombros, mejorando la estabilidad y la resistencia en la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '4410'),
('4bb3aade-c2e6-557a-a738-584931eb29ef', 'Postura del guerrero III', ARRAY['Parte de pie y eleva una pierna hacia atrás inclinando el torso hacia delante.', 'Extiende los brazos al frente y mantén el cuerpo en línea recta.', 'Fija la mirada en un punto para mantener el equilibrio y respira.', 'Evita girar la cadera o perder la alineación de la espalda.']::text[], 'intermedio', 'Trabaja isquiotibiales, glúteos y core en equilibrio sobre una pierna, mejorando la estabilidad y el control postural.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '5907'),
('bce33f37-bd71-55fb-8669-7a4e565d4b0c', 'Postura del guerrero', ARRAY['Da un paso amplio hacia delante y flexiona la rodilla delantera.', 'Gira el torso y extiende los brazos en línea con los hombros.', 'Mantén la mirada al frente y respira con calma.', 'Evita inclinar el torso hacia delante o perder el apoyo del pie trasero.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos abriendo caderas y hombros, mejorando la estabilidad y la movilidad general.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '3471'),
('8772a001-6a4b-5db3-9047-5f4152bfbdeb', 'Postura del guerrero I', ARRAY['Da un paso largo hacia delante y flexiona la rodilla delantera.', 'Gira el pie trasero hacia fuera y eleva los brazos por encima de la cabeza.', 'Mantén la cadera cuadrada al frente y respira profundamente.', 'Evita arquear la zona lumbar o perder el equilibrio.']::text[], 'principiante', 'Estira y fortalece cuádriceps, glúteos y flexores de cadera, mejorando la apertura de cadera y la estabilidad.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0964'),
('fa2fcd74-a7df-56f7-a511-d0fd9b39fcd4', 'Postura del guerrero II virabhadrasana', ARRAY['Separa los pies y gira el pie delantero hacia fuera.', 'Flexiona la rodilla delantera y extiende los brazos en paralelo al suelo.', 'Mantén el torso erguido y la mirada sobre la mano delantera.', 'Evita que la rodilla delantera se desplace hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos abriendo caderas y hombros, mejorando la resistencia y la estabilidad en la postura.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '0963'),
('2fda9155-f0cd-5eab-bf22-29eb17029f19', 'Abdominal acostado con disco', ARRAY['Túmbate boca arriba con las rodillas flexionadas y el disco sobre el pecho.', 'Eleva el torso contrayendo el abdomen sin tirar del cuello.', 'Sube exhalando y baja controlando el movimiento.', 'Evita impulsarte con las piernas o arquear la zona lumbar.']::text[], 'intermedio', 'Trabaja el recto abdominal y el core con carga, aumentando la fuerza y el control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10710'),
('42b25748-3bdc-55a9-a532-05a1e50d29e7', 'Curl de bíceps de pie con disco', ARRAY['De pie, sujeta el disco con ambas manos frente a los muslos.', 'Flexiona los codos subiendo el disco hasta el pecho sin mover los hombros.', 'Baja controlando el movimiento y mantén los codos pegados al torso.', 'Evita balancear el cuerpo o usar impulso para subir.']::text[], 'intermedio', 'Fortalece bíceps y antebrazos con el disco, mejorando la fuerza y el control del tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6698'),
('9f262b0e-9ffc-5a6c-aad2-34deeecc711c', 'Torsión de manos de pie con disco', ARRAY['De pie, sujeta el disco con ambas manos a la altura del pecho.', 'Gira las manos como si quisieras torcer el disco hacia un lado y otro.', 'Mantén los codos pegados al cuerpo y los hombros relajados.', 'Evita mover el torso o usar demasiada velocidad.']::text[], 'intermedio', 'Refuerza antebrazos, muñecas y agarre con un movimiento de torsión, mejorando la fuerza funcional de la mano.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7055'),
('7d0420d2-c34c-5acf-81f4-07366b6b71d9', 'Carrera con mochila con peso', ARRAY['Ajusta bien la mochila al torso para que no rebote al correr.', 'Mantén el torso erguido y una zancada corta y controlada.', 'Respira de forma regular y ajusta el ritmo a tu nivel.', 'Evita inclinarte demasiado hacia delante o correr con la espalda encorvada.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la resistencia de piernas y core corriendo con carga adicional.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10677'),
('6d1ccdef-85b2-5efc-ac38-6e7d13cd867c', 'Caminata con mochila con peso', ARRAY['Coloca la mochila bien ajustada y camina con paso firme.', 'Mantén el torso erguido y los hombros relajados.', 'Respira con normalidad y mantén un ritmo constante.', 'Evita encorvar la espalda o dar pasos demasiado largos.']::text[], 'intermedio', 'Trabaja piernas y core con un esfuerzo cardiovascular moderado, mejorando la resistencia y la postura al caminar.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '10676'),
('d71e2894-4690-54ec-9841-a0d7b2e3ebb1', 'Buenos días con bolsa con peso', ARRAY['De pie con la bolsa sobre los hombros y las rodillas ligeramente flexionadas.', 'Lleva la cadera hacia atrás bajando el torso con la espalda recta.', 'Baja hasta notar el estiramiento en isquiotibiales y sube controlando.', 'Evita redondear la espalda o flexionar demasiado las rodillas.']::text[], 'intermedio', 'Fortalece isquiotibiales, glúteos y zona lumbar con una bisagra de cadera, mejorando la fuerza posterior y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8891'),
('47ba4b34-0bd6-5d5a-9401-70b5936df054', 'Zancada caminando con saco de peso', ARRAY['Coloca el saco sobre los hombros y da un paso al frente con el torso erguido.', 'Baja flexionando ambas rodillas hasta que la de atrás casi toque el suelo.', 'Empuja con la pierna delantera para avanzar y repite alternando piernas.', 'Mantén el core activo y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos mientras mejora el equilibrio y la estabilidad del core en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8701'),
('9160e8ce-f308-5908-b63d-a1d470565d52', 'Hiperextensión inversa con balón medicinal en GHD', ARRAY['Colócate boca abajo en el GHD sujetando el balón entre los pies.', 'Aprieta los glúteos y eleva las piernas hasta alinearlas con el tronco.', 'Baja con control sin dejar caer las piernas de golpe.', 'Evita arquear la zona lumbar en exceso; el movimiento nace del glúteo.']::text[], 'intermedio', 'Trabaja glúteos e isquiotibiales elevando las piernas contra resistencia, ideal para fortalecer la cadena posterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10861'),
('3832048d-50e2-534a-b441-c82adfa0a4b0', 'Fondos en banco con peso', ARRAY['Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.', 'Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps y suma trabajo de pecho y hombros, útil para ganar fuerza en empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '0830'),
('91a4a29e-1c15-5f37-8a1f-7056952a0a4b', 'Elevación de piernas en silla romana con peso', ARRAY['Apoya los antebrazos en la silla romana y sujeta el peso entre los pies.', 'Eleva las piernas rectas hasta la altura de la cadera sin balancearte.', 'Baja lentamente controlando el descenso y sin dejar caer las piernas.', 'Evita arquear la espalda; mantén la zona lumbar pegada al respaldo.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera con control, mejorando la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2127'),
('2e7416a9-721d-566a-b2a7-3aaffa22e0a1', 'Peso muerto sumo con cadenas', ARRAY['Coloca los pies anchos con las puntas hacia fuera y agarra la barra con las cadenas.', 'Baja la cadera, saca pecho y mantén la espalda neutra antes de tirar.', 'Empuja el suelo con los talones y extiende caderas y rodillas a la vez.', 'Evita redondear la espalda o juntar las rodillas al subir.']::text[], 'intermedio', 'Potencia glúteos y aductores con una variante de peso muerto que añade resistencia progresiva.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5910'),
('231ad9b3-bd2b-5730-adda-5f7187f2d152', 'Dominadas supinas con peso', ARRAY['Cuélgate de la barra con agarre supino y el peso sujeto en la cintura.', 'Tira de los codos hacia abajo llevando el pecho hacia la barra.', 'Sube controlando y baja hasta extender los brazos sin balancearte.', 'Evita encoger los hombros; inicia el movimiento desde la espalda.']::text[], 'intermedio', 'Desarrolla dorsales y bíceps con agarre supino, aumentando la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4102'),
('e0fcc542-20a0-531b-9305-fa0985a15a3c', 'Dominada supina con agarre cerrado en jaula de fondos', ARRAY['Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros.', 'Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados.', 'Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento.', 'Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja dorsales y bíceps con un agarre estrecho que intensifica la tracción.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '2987'),
('f4b9cfff-c84e-51fb-9795-e2192f31f1f9', 'Sentadilla cosaca con peso', ARRAY['Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera.', 'Sostén un peso frente al pecho con ambas manos.', 'Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta.', 'Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado.', 'Empuja con el talón de la pierna flexionada para volver a la posición inicial.', 'Repite con el otro lado, alternando entre las piernas.']::text[], 'intermedio', 'Mejora la movilidad de cadera y fortalece glúteos, cuádriceps y aductores en un patrón lateral.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3643'),
('a657125c-cf68-56dd-8445-b3c603ac68c3', 'Sentadilla patinador con contrapeso y peso', ARRAY['Sujeta el contrapeso al frente y apoya una pierna ligeramente detrás.', 'Desciende flexionando la pierna delantera mientras la trasera se desliza.', 'Empuja con la pierna de apoyo para volver arriba sin perder el equilibrio.', 'Evita que la rodilla delantera se vaya hacia dentro durante el descenso.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos en una sentadilla a una pierna que exige equilibrio y control.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4129'),
('d5e6dfd3-a810-5307-bd41-1244865dcbf2', 'Sentadilla con contrapeso y peso', ARRAY['Sujeta el contrapeso al frente con los brazos extendidos y los pies a la anchura de hombros.', 'Baja la cadera hacia atrás manteniendo el pecho alto y la espalda neutra.', 'Empuja con los talones para subir apretando glúteos al final.', 'Evita que las rodillas se junten o que los talones se despeguen del suelo.']::text[], 'intermedio', 'Refuerza cuádriceps y glúteos con un contrapeso que ayuda a mantener el torso erguido.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4128'),
('cf3ed103-6409-5224-ba40-117360542a60', 'Abdominal con peso', ARRAY['Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.', 'Sostén un disco de peso o una mancuerna sobre el pecho.', 'Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece el recto abdominal y los oblicuos añadiendo carga para aumentar la intensidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0832'),
('d81477de-dbc7-5e05-a9fd-3ad2b0d454f4', 'Bicho muerto con peso', ARRAY['Túmbate boca arriba con el peso en las manos y las piernas a 90 grados.', 'Extiende un brazo y la pierna contraria hacia el suelo sin arquear la espalda.', 'Vuelve al centro y repite con el lado opuesto de forma controlada.', 'Evita que la zona lumbar se despegue del suelo durante el movimiento.']::text[], 'intermedio', 'Mejora la estabilidad del core y la coordinación mientras protege la zona lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4127'),
('7dd58ce1-b8b4-5291-9491-91e226857b2f', 'Abdominal declinado con peso', ARRAY['Túmbate en el banco declinado con el peso sobre el pecho y los pies fijos.', 'Eleva el tronco flexionando el abdomen sin tirar del cuello.', 'Baja lentamente controlando el descenso hasta la posición inicial.', 'Evita impulsarte con las piernas o arquear la espalda al subir.']::text[], 'intermedio', 'Intensifica el trabajo del abdomen y los flexores de cadera gracias a la inclinación del banco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2130'),
('c7cf292a-c715-5b9b-945e-64fe47efed87', 'Elevación de gemelos burro con peso', ARRAY['Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando.', 'Sujétate de un objeto estable para mayor apoyo.', 'Eleva los talones tan alto como puedas extendiendo los tobillos.', 'Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los gemelos en estiramiento máximo, mejorando la fuerza y el tamaño de la pantorrilla.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0833'),
('c0b802ce-0ec7-5fc9-b2e2-ecb813f0165c', 'Flexiones con caída y peso', ARRAY['Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.', 'Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.', 'Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo.', 'Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo.', 'Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo.', 'Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha.', 'Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros con una variante explosiva que suma carga y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '1310'),
('4327e5b0-bd78-597f-9f50-5004089eb350', 'Elevación de rodillas tumbado con mancuerna', ARRAY['Túmbate boca arriba con la mancuerna sujeta entre los pies o sobre el abdomen, según te resulte más seguro.', 'Contrae el abdomen y eleva las rodillas hacia el pecho sin despegar la zona lumbar del suelo.', 'Baja las piernas de forma controlada sin dejar que toquen el suelo del todo.', 'Exhala al subir y evita arquear la espalda baja en ningún momento.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera, mejorando el control del core y la estabilidad pélvica.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8873'),
('310f424c-ef2a-50bd-9b47-09411ae7a2e4', 'Sentadilla en la pared con balón', ARRAY['Coloca el balón entre la espalda baja y la pared y apoya los pies al ancho de los hombros.', 'Desliza la espalda hacia abajo flexionando las rodillas hasta unos 90 grados.', 'Mantén las rodillas alineadas con los pies y el peso repartido en los talones.', 'Aguanta la posición respirando con normalidad y sube empujando con las piernas.']::text[], 'intermedio', 'Fortalece cuádriceps, glúteos e isquios mejorando la resistencia y la técnica de la sentadilla con apoyo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1603'),
('3fa20c56-2fb7-5240-ab4e-564597a26464', 'Abdominal con peso en el suelo con pies en banco', ARRAY['Túmbate boca arriba con los pies apoyados en el banco y las rodillas flexionadas.', 'Sujeta el peso sobre el pecho y pega la zona lumbar al suelo.', 'Eleva la parte alta de la espalda contrayendo el abdomen sin tirar del cuello.', 'Baja despacio controlando el movimiento y exhala al subir.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos con un rango controlado que reduce la tensión lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3282'),
('352c3441-2569-5e1c-a611-b5ca3e7b473c', 'Abdominal con giro y peso', ARRAY['Túmbate con los pies en el banco y sujeta el peso con las dos manos frente al pecho.', 'Eleva la parte alta de la espalda y gira el tronco hacia un lado con control.', 'Vuelve al centro y repite hacia el otro lado sin perder la tensión abdominal.', 'Evita tirar del cuello y mantén la zona lumbar pegada al suelo.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos, mejorando la rotación del tronco y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3283'),
('b1fe112d-144f-542d-9983-74f0f9341be4', 'Frog pump con peso', ARRAY['Túmbate boca arriba con las plantas de los pies juntas y las rodillas abiertas hacia fuera.', 'Coloca el peso sobre la cadera y apoya bien la zona lumbar.', 'Empuja con los talones y eleva la cadera contrayendo fuerte los glúteos.', 'Baja de forma controlada sin apoyar del todo la cadera y repite.']::text[], 'intermedio', 'Aísla los glúteos con las plantas de los pies juntas, activando también isquios y aductores.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3182'),
('2387336c-27a9-5020-af21-10b6c1767c99', 'Elevación frontal con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.', 'Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.', 'Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el deltoides anterior con apoyo de bíceps y antebrazos; sirve para fortalecer el hombro en elevación frontal.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0834'),
('23143a99-b616-5f2c-b63b-55b38c32c7a4', 'Ejercicio full can con peso', ARRAY['Sujeta el peso con la mano y coloca el brazo junto al cuerpo con el pulgar hacia arriba.', 'Eleva el brazo en diagonal hacia delante hasta la altura del hombro.', 'Mantén el codo ligeramente flexionado y el pulgar apuntando hacia arriba.', 'Baja despacio y evita encoger el hombro hacia la oreja.']::text[], 'intermedio', 'Refuerza el deltoides y el manguito rotador, útil para la salud del hombro y la estabilidad escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5818'),
('a49452d4-e968-5e21-abef-2cea2d8a485d', 'Sentadilla completa desde déficit con peso', ARRAY['Colócate de pie sobre una superficie elevada con los pies al ancho de los hombros.', 'Sujeta el peso y desciende flexionando rodillas y cadera hasta bajar del nivel de los pies.', 'Mantén el pecho alto y las rodillas alineadas con la punta de los pies.', 'Sube empujando con los talones y evita que la espalda se redondee.']::text[], 'intermedio', 'Trabaja cuádriceps, glúteos e isquios con mayor rango de recorrido, mejorando fuerza y movilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '7411'),
('7249b228-e802-5028-ba3b-87e5450c1711', 'Sentadilla completa con press sobre la cabeza y peso', ARRAY['De pie con el peso a la altura de los hombros y los pies al ancho de la cadera.', 'Baja en sentadilla manteniendo el pecho alto y el abdomen firme.', 'Al subir, empuja el peso sobre la cabeza extendiendo los brazos.', 'Baja el peso a los hombros con control y evita arquear la espalda al presionar.']::text[], 'intermedio', 'Ejercicio global que combina piernas, hombros y core, mejorando fuerza y coordinación en un solo movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5529'),
('f3c2f98e-3a95-5a0f-a7bb-d1cd4bf89254', 'Dominadas con agarre martillo en jaula de fondos', ARRAY['Cuélgate de la jaula con agarre neutro y los brazos completamente extendidos.', 'Tira de los codos hacia abajo llevando el pecho hacia la barra.', 'Mantén el core activo y evita balancearte con las piernas.', 'Baja de forma controlada hasta extender los brazos del todo.']::text[], 'intermedio', 'Fortalece dorsales y bíceps con un agarre neutro que reduce la tensión en hombros y muñecas.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '2986'),
('3c8982a2-4aba-5aea-825f-3608b47a1b15', 'Dominadas supinas colgado con peso', ARRAY['Cuélgate de la barra con las palmas hacia ti y los brazos extendidos.', 'Tira del cuerpo hacia arriba llevando el pecho a la barra.', 'Mantén los hombros activos y evita encogerlos hacia las orejas.', 'Baja despacio hasta la extensión completa sin soltar la tensión.']::text[], 'intermedio', 'Trabaja dorsales y bíceps con agarre supino, aumentando la fuerza de tracción y el control escapular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4181'),
('c4cd04dc-b006-56bc-b0d7-bddc0758ff33', 'Elevación de piernas y cadera colgado con peso', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.', 'Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.', 'Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el abdomen y los flexores de cadera con carga, implicando la zona lumbar para un core fuerte y estable.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '0866'),
('76aa26ea-d36c-5627-8914-2ac97ee8357f', 'Empuje de cadera con peso', ARRAY['Apoya la espalda alta en un banco y coloca el peso sobre la cadera.', 'Con los pies al ancho de los hombros, eleva la cadera hasta alinear tronco y muslos.', 'Aprieta los glúteos arriba y mantén el abdomen firme sin arquear la espalda.', 'Baja de forma controlada y evita empujar con la zona lumbar.']::text[], 'intermedio', 'Fortalece glúteos e isquios con un movimiento de extensión de cadera que mejora la potencia y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2754'),
('9cc0eed6-8f8c-52cf-ac72-713a24e17b99', 'Hiperextensión con peso', ARRAY['Colócate en el banco con la cadera apoyada y los pies bien sujetos.', 'Sujeta el peso contra el pecho y mantén la espalda neutra.', 'Baja el tronco controlando el movimiento sin redondear la espalda.', 'Sube hasta alinear el cuerpo y evita hiperextender la zona lumbar.']::text[], 'intermedio', 'Refuerza la musculatura lumbar, glúteos e isquios, mejorando la extensión de cadera y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5035'),
('fffaf5c1-3680-588e-bd7a-b94ac5c35509', 'Press svend inclinado con peso', ARRAY['Siéntate en un banco inclinado con el peso sujeto entre las palmas frente al pecho.', 'Junta las manos presionando el peso y extiende los brazos hacia delante.', 'Mantén la presión constante y el pecho alto durante todo el recorrido.', 'Vuelve despacio al pecho sin perder la tensión y evita encoger los hombros.']::text[], 'intermedio', 'Activa el pectoral superior y los hombros con una presión isométrica que mejora la conexión muscular.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5068'),
('2c048eb4-2f6e-5716-a375-782c6c170d35', 'Remo invertido con peso', ARRAY['Colócate bajo una barra fija y agárrala con las palmas hacia delante, con el cuerpo recto y los talones apoyados.', 'Tira del pecho hacia la barra juntando las escápulas y mantén el abdomen firme.', 'Baja controlando el movimiento hasta estirar los brazos sin perder la línea del cuerpo.', 'Evita encoger los hombros o arquear la zona lumbar durante la subida.']::text[], 'intermedio', 'Fortalece la espalda alta, los dorsales y los bíceps; mejora la postura y la tracción horizontal.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '1184'),
('b3afdcfb-8d8c-536c-9702-b415a5ce2d04', 'Dead bug con kettlebell', ARRAY['Túmbate boca arriba con la kettlebell sujeta con los brazos extendidos hacia el techo.', 'Estira una pierna y el brazo contrario sin que la lumbar se despegue del suelo.', 'Vuelve al centro y alterna el lado, respirando de forma pausada.', 'Evita arquear la espalda o mover la kettlebell fuera de la vertical.']::text[], 'intermedio', 'Trabaja el core profundo y los abdominales bajos, mejorando la estabilidad y el control lumbar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9517'),
('6e113306-09be-5548-9cdf-8d22439b4054', 'Paso de rodillas con balanceo y peso', ARRAY['Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta.', 'Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti.', 'Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos.', 'Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa los deltoides y el core con un gesto de empuje controlado y estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3641'),
('f7ee48ed-a124-5d33-91d0-75333a59bc41', 'Abdominal con extensión de piernas y peso', ARRAY['Túmbate boca arriba con el peso sobre el pecho y las piernas flexionadas.', 'Eleva el tronco mientras estiras las piernas sin apoyar los talones.', 'Baja despacio y vuelve a flexionar las piernas al mismo tiempo.', 'Evita tirar del cuello o despegar la lumbar del suelo.']::text[], 'intermedio', 'Refuerza los abdominales y los flexores de cadera, mejorando el control del tronco en el crunch.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0836'),
('f40d0570-37b2-57c7-b784-7d3f15046152', 'Abducción de cadera acostado con peso', ARRAY['Túmbate de lado con el peso sobre la pierna superior y el cuerpo alineado.', 'Eleva la pierna de arriba sin rotar la cadera ni inclinar el tronco.', 'Baja controlando el movimiento hasta casi tocar la otra pierna.', 'Evita balancear la pierna o compensar con la zona lumbar.']::text[], 'intermedio', 'Fortalece los abductores y los glúteos, mejorando la estabilidad de la cadera y la alineación de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0837'),
('e6f2a729-a5cc-564e-9d44-7edfa274e0dc', 'Extensión de cuello acostado con peso', ARRAY['Túmbate boca abajo con la frente apoyada y el peso sobre la parte posterior de la cabeza.', 'Extiende el cuello llevando la barbilla ligeramente hacia arriba sin forzar.', 'Baja despacio hasta la posición neutra manteniendo el resto del cuerpo relajado.', 'Evita hacer movimientos bruscos o cargar demasiado peso al inicio.']::text[], 'intermedio', 'Trabaja los trapecios y la musculatura posterior del cuello, mejorando la extensión cervical controlada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1042'),
('479f9e49-b8c5-5504-bf4c-372bea5a0fb5', 'Flexión de cuello acostado con peso', ARRAY['Túmbate boca arriba con el peso sobre la frente y el cuello en posición neutra.', 'Flexiona el cuello llevando la barbilla hacia el pecho de forma lenta.', 'Vuelve a la posición inicial controlando el descenso.', 'Evita despegar la cabeza del suelo de golpe o usar demasiado peso.']::text[], 'intermedio', 'Refuerza los flexores profundos del cuello y los trapecios, mejorando el control cervical anterior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1043'),
('58121c94-5d66-50e1-b71c-da24bd4e229d', 'Giro de cabeza y cuello acostado con peso', ARRAY['Túmbate boca arriba con el peso sobre la frente y los hombros relajados.', 'Gira la cabeza hacia un lado sin mover los hombros ni el tronco.', 'Vuelve al centro y repite hacia el otro lado despacio.', 'Evita forzar el rango o hacer giros rápidos con carga.']::text[], 'intermedio', 'Activa el elevador de la escápula y la musculatura cervical, mejorando la rotación controlada del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4432'),
('59f0ba68-6af4-5ee7-8f3c-84dd4b21f266', 'Movimiento de cuello de lado a lado acostado con peso', ARRAY['Túmbate boca arriba con el peso sobre la frente y el cuerpo relajado.', 'Inclina la cabeza hacia un lado sin elevar el hombro.', 'Vuelve al centro y alterna el lado con movimiento lento.', 'Evita tirar con el cuello o perder la posición neutra de los hombros.']::text[], 'intermedio', 'Trabaja el elevador de la escápula y los trapecios, mejorando la movilidad y el control lateral del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4431'),
('f64a72b6-ef63-5ae6-a2fa-eb11ccac64f0', 'Elevación lateral de cabeza acostado con peso (con arnés de cabeza)', ARRAY['Túmbate de lado con el arnés y el peso colocados y el cuello alineado con el tronco.', 'Eleva la cabeza hacia el hombro superior de forma lenta y controlada.', 'Baja despacio hasta la posición neutra sin dejar caer la cabeza.', 'Evita usar demasiado peso o mover el hombro para compensar.']::text[], 'intermedio', 'Fortalece el elevador de la escápula y los trapecios, mejorando la estabilidad lateral del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0838'),
('b69a98c8-1a75-50d2-845e-91c356a547e7', 'Elevación lateral de cuello acostado con peso', ARRAY['Túmbate de lado con el peso sobre la parte lateral de la cabeza y el cuerpo alineado.', 'Eleva la cabeza hacia el hombro superior sin mover el tronco.', 'Baja controlando el movimiento hasta la posición neutra.', 'Evita girar la cabeza o cargar más peso del que puedes controlar.']::text[], 'intermedio', 'Refuerza el elevador de la escápula y la musculatura lateral del cuello, mejorando el control cervical.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4429'),
('78cd671a-5177-5933-8bd0-0a14738976d9', 'Giro acostado con peso', ARRAY['Túmbate boca arriba con el peso sobre el pecho y las rodillas flexionadas.', 'Gira el tronco hacia un lado llevando las manos hacia el suelo sin despegar la lumbar.', 'Vuelve al centro y alterna el lado con movimiento controlado.', 'Evita tirar del cuello o usar impulso para girar.']::text[], 'intermedio', 'Trabaja los abdominales y los oblicuos, mejorando la rotación del tronco y la estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0839'),
('910b526b-0e2e-5d33-a81a-eb090d275703', 'Muscle up con peso', ARRAY['Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros.', 'Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho.', 'Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti.', 'Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento.', 'Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento.', 'Repite el número de repeticiones deseado.']::text[], 'avanzado', 'Ejercicio avanzado de calistenia que trabaja dorsales, bíceps y tríceps con gran demanda de fuerza y control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '3286'),
('c71061c6-118a-5e0a-82fb-80c3aa725b78', 'Dominada a una mano con peso', ARRAY['Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.', 'Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto.', 'Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Baja el cuerpo de nuevo a la posición inicial con control.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Ejercicio avanzado que exige gran fuerza de dorsales, bíceps y antebrazos, con control total del cuerpo.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '3290'),
('72054e76-a2ce-53b1-b7cf-802e9ebfb592', 'Empuje de cadera a una pierna con peso', ARRAY['Apoya la espalda alta en un banco con el peso sobre la cadera y una pierna flexionada.', 'Empuja la cadera hacia arriba apretando el glúteo sin arquear la lumbar.', 'Baja controlando el movimiento hasta casi tocar el suelo.', 'Evita rotar la cadera o compensar con la pierna contraria.']::text[], 'intermedio', 'Fortalece los glúteos y los isquios de forma unilateral, mejorando la estabilidad y la potencia de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1062'),
('fe91164d-f8be-5a6e-a5d1-c550474d5d31', 'Abdominal con peso sobre la cabeza en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza.', 'Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.', 'Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos con el apoyo inestable del balón, mejorando el control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0840'),
('a7ace7e6-ed6f-5bec-adc1-c42929ecbca2', 'Subida al cajón con press sobre la cabeza y peso', ARRAY['Coloca el pie completo sobre el cajón y sujeta el peso a la altura de los hombros.', 'Empuja con la pierna de arriba para subir y extiende el peso por encima de la cabeza al llegar arriba.', 'Baja el peso a los hombros y desciende el pie con control hasta el suelo.', 'Mantén el tronco erguido y evita empujar con la pierna de abajo para no perder el equilibrio.']::text[], 'intermedio', 'Combina fuerza de piernas y hombros en un gesto global que también exige estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4185'),
('4e254aa9-1f75-5719-a74e-1a801ba36d04', 'Inclinación lateral a 45 grados con disco', ARRAY['Sujeta el disco con una mano y apoya la otra en la cadera, con el tronco inclinado unos 45 grados.', 'Baja el disco hacia el lado de la pierna flexionando el tronco lateralmente, sin rotar.', 'Sube despacio hasta la posición inicial controlando el movimiento.', 'Evita tirar con el brazo o arquear la espalda; el movimiento nace del costado.']::text[], 'intermedio', 'Fortalece oblicuos y zona lumbar con un movimiento controlado que mejora la estabilidad lateral del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10875'),
('bc591556-c73e-5c28-8085-a2cad4ded2d5', 'Remo inclinado con disco', ARRAY['Con los pies a la anchura de las caderas, inclina el tronco hacia delante manteniendo la espalda recta y sujeta el disco con ambas manos.', 'Tira del disco hacia el abdomen juntando las escápulas.', 'Baja el disco de forma controlada hasta estirar los brazos.', 'Evita redondear la espalda o tirar con impulso de cadera.']::text[], 'intermedio', 'Refuerza la espalda alta y los dorsales, mejorando la postura y la fuerza de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3860'),
('1211119e-46ce-5ce2-8f26-da57e3b45d0d', 'Abdominal con disco con manos sobre la cabeza', ARRAY['Túmbate boca arriba con las rodillas flexionadas y sujeta el disco con las manos junto a la cabeza.', 'Eleva los hombros del suelo curvando el tronco y aprieta el abdomen al subir.', 'Baja despacio sin apoyar del todo la cabeza en el suelo.', 'Evita tirar del cuello con las manos o usar impulso para subir.']::text[], 'intermedio', 'Aumenta la carga del crunch clásico para trabajar el recto abdominal y la zona baja del abdomen.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10871'),
('51b6575b-9707-5792-9631-ddab0d2a56d4', 'Peso muerto con zancada atrás y press sobre la cabeza con disco', ARRAY['De pie con el disco a la altura del pecho, da un paso atrás y baja la rodilla hacia el suelo.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Lleva el disco por encima de la cabeza extendiendo los brazos y baja con control.', 'Mantén el abdomen apretado y evita que la rodilla delantera se vaya hacia dentro.']::text[], 'intermedio', 'Ejercicio global que trabaja glúteos, isquios y hombros, mejorando la coordinación y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10189'),
('b8e50380-ab1f-59cc-8d6f-8200e4b21ddc', 'Elevación lu con disco', ARRAY['Sujeta el disco con ambas manos delante de los muslos, con los codos ligeramente flexionados.', 'Eleva el disco hacia delante hasta la altura de los hombros.', 'Abre los brazos hacia los lados manteniendo la altura y vuelve al centro.', 'Baja el disco despacio sin balancear el tronco ni encoger los hombros.']::text[], 'intermedio', 'Trabaja el deltoides en dos planos, mejorando la fuerza y el control del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10114'),
('1de55ba6-68be-57f5-b331-367c1d925f38', 'Zancada frontal con disco sobre la cabeza y peso', ARRAY['De pie con el disco sobre la cabeza y los brazos extendidos, da un paso largo hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Evita que el disco se balancee o que la rodilla delantera pase muy por delante del pie.']::text[], 'intermedio', 'Combina fuerza de piernas y hombros, exigiendo estabilidad del core durante todo el movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9610'),
('0e741c4f-f48c-5e04-bbd7-c5c3b871a091', 'Marcha con disco sobre la cabeza', ARRAY['De pie con el disco sobre la cabeza y los brazos extendidos.', 'Eleva una rodilla hacia el pecho y baja el pie con control.', 'Alterna las piernas manteniendo el tronco firme y la mirada al frente.', 'Evita arquear la espalda o dejar que el disco se incline hacia un lado.']::text[], 'intermedio', 'Mejora la fuerza de piernas y la estabilidad del core mientras se mantiene una carga sobre la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5498'),
('9abe0058-b7aa-5900-9bfc-4a11822a9b02', 'Zancada inversa con disco sobre la cabeza', ARRAY['De pie con el disco sobre la cabeza y los brazos extendidos, da un paso hacia atrás.', 'Baja la rodilla trasera hacia el suelo sin inclinar el tronco.', 'Empuja con la pierna delantera para volver a la posición inicial.', 'Mantén el abdomen apretado y evita que el disco se desplace hacia delante.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos con una carga elevada que también trabaja hombros y core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11657'),
('36c2501a-9d87-55a6-8344-37e2c701eed4', 'Flexión con disco', ARRAY['Coloca el disco sobre la espalda alta y adopta la posición de plancha con las manos bajo los hombros.', 'Baja el pecho hacia el suelo manteniendo el cuerpo alineado.', 'Empuja para subir sin que el disco se mueva.', 'Evita que la cadera se hunda o que los codos se abran en exceso.']::text[], 'intermedio', 'Aumenta la intensidad de la flexión clásica para pecho, tríceps y estabilidad del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '8076'),
('76ce0ee9-3664-565e-86ab-d4936ab6149c', 'Sentadilla con disco al costado', ARRAY['Sujeta el disco con una mano a un lado del cuerpo y separa los pies a la anchura de los hombros.', 'Baja en sentadilla llevando la cadera atrás y manteniendo el pecho alto.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Evita inclinarte hacia el lado del disco o que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Trabaja piernas y core con una carga lateral que desafía el equilibrio y la estabilidad.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10097'),
('697c3441-85df-51c2-b42b-40925286e1a9', 'Vuelta al mundo de pie con disco', ARRAY['De pie con el disco sujeto con ambas manos delante de la cadera.', 'Dibuja un círculo amplio llevando el disco por un lado, arriba y por el otro lado.', 'Completa el círculo y cambia de sentido alternando las repeticiones.', 'Mantén el tronco quieto y evita arquear la espalda al pasar por arriba.']::text[], 'intermedio', 'Moviliza el hombro y fortalece el deltoides con un círculo controlado que también activa el core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6549'),
('84323c6e-7110-572d-8ac0-430bfa851d9f', 'Elevación frontal alta de pie con disco', ARRAY['Sujeta el disco con ambas manos delante de los muslos y mantén el abdomen apretado.', 'Eleva el disco hacia delante hasta por encima de la altura de los hombros.', 'Baja despacio controlando el descenso sin dejar caer el peso.', 'Evita balancear el tronco o encoger los hombros al subir.']::text[], 'intermedio', 'Refuerza la parte delantera del hombro y el pecho superior con un movimiento controlado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4847'),
('d995676f-d6a7-55aa-9b24-987738dc6447', 'Elevación lateral de pie con disco', ARRAY['De pie con el disco sujeto con una mano a un lado del cuerpo.', 'Eleva el brazo hacia el lado hasta la altura del hombro con el codo ligeramente flexionado.', 'Baja despacio sin dejar caer el peso de golpe.', 'Evita encoger el hombro o usar impulso del tronco para subir.']::text[], 'intermedio', 'Aísla el deltoides lateral para mejorar la amplitud y la forma del hombro.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6485'),
('5d0f465c-d1f2-54ba-b296-891cba800ffa', 'Curl de tibial anterior con disco', ARRAY['Siéntate en un banco con el disco apoyado sobre el empeine y los talones en el suelo.', 'Levanta la punta de los pies tirando del disco hacia arriba, sin mover las piernas.', 'Sube despacio y baja controlando el disco hasta rozar el suelo.', 'Evita dar tirones con la cadera y mantén la espalda recta durante todo el recorrido.']::text[], 'intermedio', 'Fortalece la parte delantera de la espinilla y el tobillo, ayudando a prevenir molestias y a estabilizar la pisada.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '6559'),
('ddbb4773-ace5-559a-8342-c01b4267932c', 'Dominadas con peso', ARRAY['Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales con ayuda de bíceps y antebrazos; sirve para ganar fuerza de tracción y masa en la espalda.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '0841'),
('c3cf8094-2c8e-5fda-9776-b2adea90f35c', 'Pullover con peso en balón de estabilidad', ARRAY['Apoya la espalda alta sobre el balón con los pies firmes en el suelo y sujeta el peso con las dos manos.', 'Lleva los brazos hacia atrás por encima de la cabeza sin arquear la zona lumbar.', 'Vuelve a subir el peso hasta la vertical apretando la espalda y el pecho.', 'Respira al bajar y evita bloquear la respiración en el punto más bajo.']::text[], 'intermedio', 'Trabaja la espalda y el pecho en estiramiento, mejorando la movilidad del hombro y la fuerza del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0842'),
('9864ed50-82ad-5be2-9b13-a457e868882b', 'Flexión con chaleco lastrado', ARRAY['Colócate el chaleco y apoya las manos algo más anchas que los hombros.', 'Mantén el cuerpo en línea recta desde la cabeza hasta los talones.', 'Baja el pecho hasta cerca del suelo y empuja para volver arriba.', 'Evita que la cadera se hunda o se eleve durante el movimiento.']::text[], 'intermedio', 'Refuerza pecho, tríceps y hombros con el peso extra del chaleco, aumentando la exigencia del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '3910'),
('f61c3a7a-3173-5ec9-9a08-ecd348b02a98', 'Reducción en triángulo con peso', ARRAY['Siéntate con las plantas de los pies juntas y sujeta el peso sobre las rodillas.', 'Aprieta las rodillas contra el peso y mantén la presión unos segundos.', 'Controla la apertura de las piernas sin dejar caer el peso de golpe.', 'Mantén la espalda erguida y evita encoger los hombros.']::text[], 'intermedio', 'Activa los aductores y la cara interna del muslo, mejorando la estabilidad de la cadera y la fuerza de agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0843'),
('990482f6-7a23-537b-8aa8-3595b411a64e', 'Círculos de brazos con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.', 'Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.', 'Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.', 'Continúa elevando los brazos hasta que queden paralelos al suelo.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja el deltoides con apoyo de tríceps y espalda alta; mejora la resistencia y estabilidad del hombro en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0844'),
('a55c87af-dbb1-5ef1-a3c3-0b4c9775c608', 'Giro ruso con peso', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.', 'Sostén un peso o un balón medicinal con ambas manos frente al pecho.', 'Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.', 'Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho.', 'Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos con apoyo lumbar; sirve para ganar fuerza rotacional y control del core.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0846'),
('13ad78ef-6980-5bf2-95fe-a63b18f8d687', 'Acarreo con saco de arena abrazado', ARRAY['Agarra el saco con los dos brazos pegados al pecho, como un abrazo.', 'Camina con pasos cortos manteniendo el tronco erguido y el abdomen apretado.', 'Respira de forma constante y evita arquear la espalda hacia atrás.', 'Suelta el saco con control al terminar el recorrido.']::text[], 'intermedio', 'Fortalece el core, la espalda y el agarre mientras caminas cargado, mejorando la resistencia y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10387'),
('d89ff91a-0fbe-5b77-a684-d07ee463d5bb', 'Peso muerto con saco de arena', ARRAY['Coloca los pies a la anchura de la cadera con el saco entre ellos.', 'Flexiona las rodillas y la cadera para agarrar el saco con la espalda recta.', 'Empuja con los talones y extiende las piernas hasta quedar de pie.', 'Baja el saco controlando el movimiento y evitando redondear la espalda.']::text[], 'intermedio', 'Trabaja glúteos, isquios y espalda baja, enseñando a levantar cargas del suelo con una técnica segura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10383'),
('373ca771-0955-58d4-93bd-39d22ec8ea1a', 'Zancada frontal con saco de arena', ARRAY['Sujeta el saco abrazado al pecho y da un paso largo hacia delante.', 'Baja la rodilla trasera hacia el suelo manteniendo el tronco erguido.', 'Empuja con el pie delantero para volver a la posición inicial.', 'Evita que la rodilla delantera se vaya hacia dentro y mantén el abdomen apretado.']::text[], 'intermedio', 'Fortalece cuádriceps y glúteos de forma unilateral, mejorando el equilibrio y la estabilidad de la cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '9940'),
('4971e33d-9242-568b-a6bb-9ee3009ef0a3', 'Press militar con saco de arena', ARRAY['Sujeta el saco a la altura del pecho con las manos firmes.', 'Empuja el saco por encima de la cabeza extendiendo los brazos.', 'Baja el saco con control hasta el pecho sin arquear la espalda.', 'Aprieta el abdomen y evita bloquear la respiración al empujar.']::text[], 'intermedio', 'Desarrolla hombros y tríceps, además de la estabilidad del core al empujar una carga inestable por encima de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10388'),
('7302ac05-7c0f-52e5-9677-cfb35a72a8c7', 'Peso muerto rumano con saco de arena', ARRAY['De pie con el saco delante de los muslos y las rodillas ligeramente flexionadas.', 'Lleva la cadera hacia atrás bajando el saco pegado a las piernas.', 'Nota el estiramiento en los isquios y vuelve arriba apretando glúteos.', 'Evita redondear la espalda y mantén el saco cerca del cuerpo.']::text[], 'intermedio', 'Trabaja isquios y glúteos con un movimiento de cadera, mejorando la fuerza posterior y la técnica de bisagra.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10730'),
('f0e78fd6-43d4-56ab-8d04-7969762d2b88', 'Remo con saco de arena', ARRAY['Inclina el tronco hacia delante con la espalda recta y sujeta el saco con las dos manos.', 'Tira del saco hacia el abdomen juntando las escápulas.', 'Baja el saco con control hasta estirar los brazos.', 'Evita balancear el tronco para ayudarte a subir el peso.']::text[], 'intermedio', 'Fortalece la espalda y los bíceps, mejorando la postura y la fuerza de tracción con una carga inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10389'),
('2049a072-fc8b-5ba9-871e-e32cb313017c', 'Carga al hombro con saco de arena', ARRAY['Coloca el saco en el suelo y agáchate con la espalda recta para agarrarlo.', 'Extiende las piernas y la cadera para levantarlo y súbelo hacia un hombro.', 'Acompaña el saco con las manos hasta apoyarlo sobre el hombro.', 'Baja el saco con control y evita girar la espalda de forma brusca.']::text[], 'intermedio', 'Trabaja glúteos, espalda y trapecios en un movimiento global de potencia y coordinación.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10385'),
('8f38d223-e6ea-5526-adc0-24ac0e789dc5', 'Sentadilla con saco de arena', ARRAY['Sujeta el saco abrazado al pecho con los pies a la anchura de los hombros.', 'Baja la cadera hacia atrás y abajo manteniendo el pecho alto.', 'Empuja con los talones para subir apretando glúteos.', 'Evita que las rodillas se metan hacia dentro y mantén el abdomen firme.']::text[], 'intermedio', 'Fortalece piernas y glúteos con una carga inestable que exige más trabajo del core y la espalda alta.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10384'),
('66714cfa-2dfd-51f7-a61e-4cf4b5da13e9', 'Curl de bíceps sentado con balón medicinal', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.', 'Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados.', 'Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros.', 'Haz una pausa breve en la parte alta, apretando los bíceps.', 'Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece los bíceps y los antebrazos, mejorando la fuerza de flexión del codo y el control postural al estar sentado.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0847'),
('1ee5b417-d85e-5901-aee9-0e3ea5e08041', 'Elevación de gemelos sentado con peso', ARRAY['Siéntate con la espalda recta y coloca el peso sobre las rodillas, con los pies apoyados y las puntas en el borde de un escalón.', 'Sube los talones todo lo posible apretando los gemelos y mantén un segundo arriba.', 'Baja los talones de forma lenta y controlada hasta notar el estiramiento, sin dejarlos caer de golpe.', 'Respira soltando el aire al subir y evita rebotar en la parte baja del recorrido.']::text[], 'intermedio', 'Trabaja los gemelos y el sóleo, mejorando la fuerza del tobillo y la estabilidad en la fase de empuje al caminar.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4155'),
('367948e8-c774-58e8-9db1-38e99daee1f4', 'Elevación de piernas sentado en el suelo con peso', ARRAY['Siéntate en el suelo con las piernas estiradas, sujeta el peso entre los tobillos y apoya las manos detrás.', 'Inclina ligeramente el tronco hacia atrás y eleva las piernas rectas hasta unos 45 grados.', 'Baja las piernas despacio sin tocar el suelo y mantén la zona lumbar pegada al suelo.', 'Evita arquear la espalda o tirar del cuello; respira de forma continua durante todo el recorrido.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera, mejorando el control del core y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5023'),
('76f85be9-bba3-5153-87d6-0407a262e274', 'Extensión de cuello sentado con arnés de cabeza', ARRAY['Siéntate erguido con el arnés colocado y el peso colgando por detrás de la cabeza.', 'Lleva la barbilla ligeramente hacia el pecho como posición de partida.', 'Extiende el cuello hacia atrás de forma lenta y controlada, sin forzar el rango final.', 'Vuelve despacio a la posición inicial y evita movimientos bruscos o cargas demasiado altas.']::text[], 'intermedio', 'Fortalece los extensores del cuello y la parte alta de la espalda, mejorando la postura cervical y la estabilidad de la cabeza.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0848'),
('4f71be0d-09ae-59df-b6df-587e45bc4ac2', 'Curl de muñeca neutro sentado con peso', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la muñeca en el borde, con la palma mirando hacia dentro.', 'Sujeta el peso y deja que la muñeca baje hasta notar estiramiento.', 'Flexiona la muñeca hacia arriba de forma controlada y mantén un segundo arriba.', 'Baja despacio sin balancear el brazo y evita usar impulso del hombro.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y la fuerza de agarre, útil para mejorar el rendimiento en ejercicios de tracción.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4154'),
('e19d8387-c550-5062-93e4-987f946a1798', 'Curl de muñeca inverso a un brazo sentado con peso', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la palma mirando hacia abajo.', 'Sujeta el peso con una mano y deja caer la muñeca hacia abajo.', 'Sube el dorso de la mano hacia arriba de forma lenta y controlada.', 'Baja despacio sin mover el codo y evita cargas que te obliguen a compensar con el hombro.']::text[], 'intermedio', 'Trabaja los extensores del antebrazo y la fuerza de agarre, ayudando a equilibrar la musculatura del brazo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4234'),
('b6595f01-6af8-5f00-97ce-43b83f1d7060', 'Curl de muñeca a un brazo sentado con peso', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la palma hacia arriba.', 'Sujeta el peso con una mano y deja que la muñeca baje hasta estirarse.', 'Flexiona la muñeca hacia arriba apretando el antebrazo y mantén un segundo.', 'Baja de forma lenta y evita balancear el brazo o despegar el codo del muslo.']::text[], 'intermedio', 'Fortalece los flexores del antebrazo y el agarre de forma unilateral, corrigiendo posibles desequilibrios entre brazos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4233'),
('e26c5f2f-d5e1-545e-b71a-f247231556d9', 'Curl de muñeca inverso sentado con peso', ARRAY['Siéntate con los antebrazos apoyados en los muslos y las palmas hacia abajo.', 'Sujeta el peso con ambas manos y deja caer las muñecas hacia abajo.', 'Sube el dorso de las manos de forma controlada hasta la extensión máxima.', 'Baja despacio sin despegar los antebrazos y evita usar impulso del cuerpo.']::text[], 'intermedio', 'Refuerza los extensores del antebrazo y la muñeca, mejorando la estabilidad y previniendo molestias en el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4232'),
('56c9eff5-048b-5955-8767-d935d23c1e3c', 'Elevación de gemelo sentado a una pierna con peso', ARRAY['Siéntate con la espalda recta y coloca el peso sobre la rodilla de la pierna que vas a trabajar.', 'Apoya la punta del pie en el borde de un escalón y deja el talón en el aire.', 'Sube el talón todo lo posible y mantén un segundo arriba apretando el gemelo.', 'Baja despacio hasta notar el estiramiento y evita rebotar o cargar el peso sobre la rodilla.']::text[], 'intermedio', 'Trabaja el gemelo y el sóleo de forma unilateral, mejorando la fuerza y el equilibrio de cada tobillo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '5484'),
('849da61e-ecc3-5f00-b75c-efe35fb160bd', 'Extensión de rodilla sentado a una pierna con peso', ARRAY['Siéntate en una silla con la espalda apoyada y coloca el peso sobre el tobillo o el empeine.', 'Extiende la rodilla hasta que la pierna quede recta, sin bloquearla con fuerza.', 'Mantén un segundo arriba apretando el cuádriceps y baja de forma lenta y controlada.', 'Evita balancear la pierna o usar impulso; respira soltando el aire al extender.']::text[], 'intermedio', 'Fortalece el cuádriceps de forma unilateral, mejorando la extensión de rodilla y la estabilidad de la pierna.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '10539'),
('fa18fee4-7c88-592d-b24f-38669bb22244', 'Supinación sentado con peso', ARRAY['Siéntate con el antebrazo apoyado en el muslo y la mano sujetando el peso en posición neutra.', 'Gira la palma hacia arriba de forma lenta, manteniendo el codo fijo.', 'Aguanta un segundo arriba y vuelve despacio a la posición neutra.', 'Evita mover el hombro o el codo y usa un peso que te permita controlar todo el recorrido.']::text[], 'intermedio', 'Fortalece los rotadores del antebrazo y los flexores de la muñeca, mejorando el control del giro de la mano.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4231'),
('1df36c1c-9891-5e07-b88f-3748d9e9ef38', 'Extensión de tríceps sentado con peso', ARRAY['Siéntate con la espalda recta y sujeta el peso con ambas manos por encima de la cabeza.', 'Baja el peso por detrás de la cabeza flexionando solo los codos, que deben apuntar al techo.', 'Extiende los codos para subir el peso sin mover los brazos ni arquear la espalda.', 'Evita abrir los codos hacia los lados y respira soltando el aire al extender.']::text[], 'intermedio', 'Trabaja el tríceps y la estabilidad del hombro, mejorando la fuerza para empujar y extender el codo.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4092'),
('7ec91dde-921b-5e63-9f5f-24844d548ffd', 'Giro sentado con peso en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.', 'Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho.', 'Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables.', 'Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.', 'Repite la rotación hacia el otro lado.', 'Continúa alternando lados durante el número de repeticiones deseado.']::text[], 'intermedio', 'Activa el abdomen y los oblicuos, mejorando la rotación del tronco y el control del core sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0849'),
('6df0c50e-5935-51bc-a8a3-2d97ab6b1520', 'Flexión lateral con peso en balón de estabilidad', ARRAY['Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo.', 'Sostén un peso en una mano y coloca la otra mano sobre la cadera.', 'Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta.', 'Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.', 'Repite el número de repeticiones deseado, luego cambia de lado.']::text[], 'intermedio', 'Fortalece los oblicuos y la zona lumbar, mejorando la estabilidad lateral del tronco y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0850'),
('c04c66fe-5300-54e3-8dc4-bc537d43966b', 'Abdominal lateral con peso', ARRAY['Túmbate de lado con las rodillas flexionadas y sujeta el peso junto a la cabeza o el hombro.', 'Eleva el tronco hacia el techo acercando las costillas a la cadera.', 'Baja de forma lenta y controlada sin dejarte caer.', 'Evita tirar del cuello con las manos y respira soltando el aire al subir.']::text[], 'intermedio', 'Trabaja los oblicuos y el core, mejorando la fuerza de flexión lateral y la estabilidad del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4158'),
('5ee29492-a4f7-50dc-b1c3-8bd38949b364', 'Elevación lateral de cuello tumbado de lado con peso', ARRAY['Túmbate de lado con la cabeza alineada con la columna y coloca el peso sobre la sien.', 'Sube la cabeza hacia el hombro contrario de forma lenta y controlada.', 'Baja con suavidad hasta la posición inicial sin dejar caer el peso.', 'Evita girar el cuello o usar impulso; el movimiento debe ser corto y preciso.']::text[], 'intermedio', 'Fortalece el elevador de la escápula y los músculos laterales del cuello, mejorando la estabilidad cervical y la postura.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4430'),
('6fac5b4a-b2c1-5bcf-a3c1-eebfd17eaa01', 'Sentadilla sissy con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.', 'Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda.', 'Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas.', 'Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el cuádriceps en un rango amplio y exige control de rodilla, glúteo y tobillo para mantener el equilibrio.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0851'),
('43d542c2-bd7c-55ba-825e-660c1668493f', 'Sentadilla con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.', 'Sostén un peso frente al pecho o sobre los hombros.', 'Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.', 'Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.', 'Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y piernas en un patrón básico de empuje, mejorando fuerza y estabilidad del tren inferior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0852'),
('becc3c79-a0a9-5c62-8898-1f0b9990c881', 'Salto con sentadilla y disco', ARRAY['Sujeta el disco contra el pecho y colócate con los pies a la anchura de los hombros.', 'Baja en sentadilla hasta unos 90 grados manteniendo el torso erguido.', 'Empuja con fuerza y salta lo más alto posible aterrizando con las rodillas flexionadas.', 'Amortigua el aterrizaje y evita que las rodillas se metan hacia dentro.']::text[], 'intermedio', 'Desarrolla potencia de piernas y explosividad con un salto vertical, implicando cuádriceps, glúteos y core.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones', 'peso']::text[], false, true, 8.0, 'plyometrics', '3876'),
('263417cb-1927-5311-8ec3-9d29c6b87aac', 'Abdominal con peso en balón de estabilidad', ARRAY['Siéntate sobre el balón con los pies apoyados y el peso en el pecho.', 'Recuéstate hacia atrás hasta notar el estiramiento del abdomen.', 'Sube el tronco contrayendo el abdomen y exhala al final del recorrido.', 'Evita tirar del cuello con las manos y mantén el movimiento lento.']::text[], 'principiante', 'Refuerza el recto abdominal y los oblicuos en un rango completo, mejorando el control del tronco sobre una superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '3332'),
('7ee0ee32-6d67-5a14-b128-d33153a0f551', 'Curl de pie con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.', 'Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros.', 'Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el bíceps y los antebrazos, mejorando la fuerza de flexión del codo y el control del agarre.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0853'),
('efdc1b41-b1af-5075-ba81-e155c8b2adb6', 'Extensión de cuello de pie con peso y arnés', ARRAY['Coloca el arnés en la cabeza y engancha el peso con la cadena.', 'De pie, con el torso erguido, inclina la cabeza hacia delante sin mover el tronco.', 'Extiende el cuello hacia atrás de forma lenta hasta la posición neutra.', 'Evita arquear la espalda o usar impulso; el rango debe ser corto y controlado.']::text[], 'intermedio', 'Fortalece los extensores cervicales y la parte alta de la espalda, mejorando la postura y la estabilidad del cuello.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '2410'),
('73a0e294-11e9-5acf-8be0-41485d77a54c', 'Press de hombros de pie con peso', ARRAY['De pie, con los pies a la anchura de los hombros, sujeta el peso a la altura de los hombros.', 'Empuja hacia arriba hasta extender los brazos sin bloquear del todo los codos.', 'Baja de forma controlada hasta la altura inicial y exhala al empujar.', 'Evita arquear la zona lumbar; aprieta el abdomen durante todo el movimiento.']::text[], 'intermedio', 'Fortalece los deltoides y tríceps en un empuje vertical, exigiendo estabilidad del core y de la espalda.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4175'),
('be8f337c-a3e5-5bcd-b2ef-2a3c8a67fd73', 'Giro de pie con peso', ARRAY['De pie, con los pies a la anchura de los hombros, sujeta el peso delante del pecho.', 'Gira el tronco hacia un lado de forma controlada sin mover las caderas.', 'Vuelve al centro y repite hacia el otro lado.', 'Evita usar impulso o girar solo los brazos; el movimiento nace del torso.']::text[], 'intermedio', 'Trabaja los oblicuos y la rotación del tronco, mejorando la fuerza y el control del core en movimiento.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0855'),
('51a0d0bb-a8ed-5018-9ce7-b475fac95bd3', 'Press de potencia sobre la cabeza con piedra', ARRAY['Sujeta la piedra a la altura del pecho con las manos firmes.', 'Flexiona ligeramente las rodillas y empuja la piedra sobre la cabeza con fuerza.', 'Extiende brazos y caderas de forma coordinada, exhalando al empujar.', 'Evita arquear la espalda en exceso; mantén el abdomen apretado durante el empuje.']::text[], 'intermedio', 'Desarrolla potencia de hombros y tríceps en un empuje vertical explosivo, implicando core y glúteos.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '11716'),
('8cf0ca9a-cff4-5305-ba3c-fc5bd267723e', 'Fondos con peso en barra recta', ARRAY['Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros en un empuje de fondos, mejorando la fuerza del tren superior.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.8, 'calisthenics', '3313'),
('304bf0df-a20e-57d1-b747-c7cfe8dc7b9b', 'Abdominal con toque de pies y piernas rectas con peso', ARRAY['Túmbate boca arriba con las piernas rectas y el peso en el pecho.', 'Eleva el tronco y lleva las manos hacia los pies sin doblar las rodillas.', 'Baja de forma lenta controlando el abdomen y exhala al subir.', 'Evita tirar del cuello o usar impulso; mantén el movimiento pausado.']::text[], 'intermedio', 'Refuerza el abdomen y los flexores de cadera con un movimiento de flexión que exige control del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '4101'),
('66cdf049-1f77-5260-ae39-036ddef24b0b', 'Zancada con estiramiento y peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros.', 'Da un paso adelante con el pie derecho, manteniendo la espalda recta.', 'Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo.', 'Empuja con el talón derecho para regresar a la posición inicial.', 'Repite con la pierna izquierda.', 'Continúa alternando las piernas durante el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja glúteos y piernas en un patrón de zancada, mejorando fuerza, equilibrio y movilidad de cadera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '3642'),
('1b2bf704-9fd1-557e-9465-e66d1811b876', 'Press Svend con peso', ARRAY['Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos.', 'Mantén los codos ligeramente flexionados y las palmas mirándose entre sí.', 'Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos.', 'Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla los pectorales juntando las manos bajo tensión, mejorando la conexión y el control del pecho.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '0856'),
('c0d89877-80c6-5354-98a3-ed6e84f759a2', 'Fondos de tríceps con peso en barras paralelas altas', ARRAY['Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos.', 'Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.', 'Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Aísla el tríceps en un empuje de fondos, mejorando la fuerza y el control del codo en el tren superior.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1767'),
('213d8ea8-172f-53f3-b75b-9b9d6717ebd0', 'Abdominal con giro y peso en banco', ARRAY['Túmbate en el banco con las rodillas flexionadas y sujeta el peso con las dos manos junto al pecho.', 'Eleva ligeramente el tronco y gira el torso hacia un lado llevando el peso hacia la cadera contraria.', 'Vuelve al centro con control y repite hacia el otro lado sin dejar caer la espalda.', 'Exhala al girar e inhala al volver, manteniendo el movimiento lento y sin tirones.', 'Evita tirar del cuello o usar impulso: el giro debe nacer del abdomen.']::text[], 'intermedio', 'Trabaja el recto abdominal y los oblicuos, mejorando la fuerza del core y la rotación controlada del tronco.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones', 'peso']::text[], false, true, 3.5, 'strength', '1188'),
('7c34c382-3984-54d9-bf44-2ff59c803773', 'Abdominal en V con peso sobre bosu', ARRAY['Siéntate sobre el bosu con el peso sujeto con las manos y las rodillas flexionadas.', 'Inclina el tronco atrás y eleva las piernas a la vez que subes el peso hacia ellas formando una V.', 'Baja despacio hasta la posición inicial sin apoyar los pies ni la espalda.', 'Exhala al subir e inhala al bajar, manteniendo el ombligo hacia dentro.', 'Evita arquear la zona lumbar o balancearte para ganar impulso.']::text[], 'intermedio', 'Activa el abdomen y la zona baja del core, mejorando la coordinación y el equilibrio sobre superficie inestable.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '1189'),
('3c03433d-26d6-5e06-ba21-071e04d2f96d', 'Postura de la rueda', ARRAY['Túmbate boca arriba con las rodillas flexionadas y las plantas de los pies apoyadas cerca de los glúteos.', 'Coloca las manos junto a las orejas con los dedos hacia los hombros y los codos apuntando arriba.', 'Empuja con pies y manos para elevar la cadera y la cabeza, estirando los brazos sin bloquear los codos.', 'Respira con calma y mantén la postura unos segundos antes de bajar despacio.', 'Evita abrir los codos hacia fuera o cargar el cuello: el peso debe repartirse entre manos y pies.']::text[], 'intermedio', 'Extiende la columna y abre el pecho, fortaleciendo glúteos, hombros y tríceps mientras mejora la movilidad torácica.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6297'),
('8eb69d77-25c8-5777-9f36-31707f1ed4be', 'Rueda abdominal', ARRAY['Arrodíllate en el suelo y coloca el rodillo frente a ti.', 'Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante.', 'Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído.', 'Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.', 'Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Refuerza el recto abdominal y la zona lumbar, mejorando la estabilidad del core y el control anti-extensión.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '0857'),
('9dc206d1-a834-5e40-9c5e-1366f2fc8f7e', 'Rueda abdominal con apoyo en la pared', ARRAY['Coloca la rueda en el suelo frente a una pared y arrodíllate con las manos en los mangos.', 'Rueda hacia delante hasta que la rueda toque la pared, manteniendo la espalda neutra.', 'Tira del abdomen para volver a la posición inicial sin arquear la zona lumbar.', 'Exhala al rodar hacia delante e inhala al regresar, con movimiento lento.', 'Evita hundir la cadera o dejar caer la cabeza: mantén el cuerpo alineado.']::text[], 'intermedio', 'Trabaja el abdomen, los dorsales y los hombros, controlando la extensión del core con ayuda de la pared.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '4093');
INSERT INTO ejercicios (id, nombre, instrucciones, dificultad, descripcion, finalidad, modalidad_entrenamiento, tipo_medicion, es_circuito, activo, valor_met, categoria, codigo_externo) VALUES
('7142a878-d190-562e-96ed-0e1647465e0b', 'Carrera en rueda', ARRAY['Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto.', 'Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos.', 'Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza.', 'Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Eleva la frecuencia cardíaca y activa piernas y core, mejorando la resistencia cardiovascular y la coordinación.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '3637'),
('248ab2cf-8f5c-57b8-ba09-4a771006b120', 'Sentadilla al aire abierta', ARRAY['Separa los pies más allá de la anchura de los hombros con las puntas ligeramente hacia fuera.', 'Baja la cadera llevando el peso a los talones y manteniendo el pecho alto.', 'Empuja el suelo para subir apretando los glúteos al final del recorrido.', 'Inhala al bajar y exhala al subir, controlando el ritmo.', 'Evita que las rodillas se metan hacia dentro o que los talones se levanten.']::text[], 'intermedio', 'Fortalece glúteos, cuádriceps y aductores, mejorando la estabilidad de cadera y la técnica de sentadilla.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4805'),
('67993dfd-b30c-5125-b5fb-94a4bccc21d1', 'Sentadilla al aire con banco ancho', ARRAY['Colócate de espaldas a un banco con los pies anchos y las puntas hacia fuera.', 'Baja la cadera hasta rozar el banco sin sentarte, manteniendo el pecho erguido.', 'Sube empujando con los talones y aprieta los glúteos arriba.', 'Inhala al bajar y exhala al subir, sin rebotar en el banco.', 'Evita inclinar el tronco en exceso o perder la alineación de rodillas.']::text[], 'intermedio', 'Activa glúteos, cuádriceps y aductores, mejorando la técnica de sentadilla con referencia de profundidad.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '9323'),
('2d675e35-25e8-567a-a0ae-6c8fbf30c858', 'Dominada supina agarre abierto', ARRAY['Cuelga de la barra con las palmas hacia ti y las manos más abiertas que los hombros.', 'Tira de los codos hacia abajo llevando el pecho hacia la barra sin balancearte.', 'Baja de forma controlada hasta estirar los brazos del todo.', 'Exhala al subir e inhala al bajar, manteniendo el core activo.', 'Evita encoger los hombros o usar impulso de piernas.']::text[], 'intermedio', 'Fortalece dorsales y bíceps, mejorando la fuerza de tracción y el control escapular en agarre amplio.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '8189'),
('b13629ab-fd86-5ad7-af12-bd1db165b5db', 'Puente de glúteos con pulso y piernas abiertas', ARRAY['Túmbate boca arriba con los pies anchos y las rodillas flexionadas.', 'Eleva la cadera hasta formar una línea recta con el tronco y aprieta los glúteos.', 'Haz pequeños pulsos arriba sin bajar del todo, manteniendo la tensión.', 'Exhala en cada pulso e inhala al finalizar, sin arquear la lumbar.', 'Evita empujar con la zona lumbar o abrir las rodillas en exceso.']::text[], 'intermedio', 'Activa glúteos, isquiotibiales y aductores, mejorando la fuerza de cadera y la estabilidad pélvica.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '5805'),
('74cd9462-d0f6-5f89-8cda-ef475421eaa4', 'Dominada con agarre abierto en jaula de fondos', ARRAY['Agarra los mangos de la jaula con las palmas hacia delante y las manos abiertas.', 'Tira del cuerpo hacia arriba llevando el pecho hacia los mangos sin balancearte.', 'Baja despacio hasta estirar los brazos y controlar los hombros.', 'Exhala al subir e inhala al bajar, manteniendo el core firme.', 'Evita encoger los hombros o usar impulso de piernas.']::text[], 'intermedio', 'Trabaja dorsales, bíceps y romboides, mejorando la fuerza de tracción y el control escapular.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1866'),
('0d2289d5-a342-5885-aec8-1ca452bf5fa2', 'Dominadas con agarre abierto', ARRAY['Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos más separadas que la anchura de los hombros.', 'Activa el core y junta los omóplatos.', 'Tira de tu cuerpo hacia arriba en dirección a la barra hasta que tu barbilla quede por encima de la barra.', 'Baja el cuerpo de nuevo a la posición inicial con control.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Fortalece dorsales, bíceps y antebrazos, mejorando la fuerza de tracción y la amplitud del agarre.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1429'),
('3ff06d7b-d233-5783-91c2-3f8e8b2f2c12', 'Dominada posterior con agarre abierto', ARRAY['Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros.', 'Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.', 'Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante.', 'Continúa subiendo hasta que la barbilla quede por encima de la barra.', 'Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Activa dorsales y bíceps con un patrón de tracción posterior, mejorando la fuerza de espalda y el control.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1367'),
('b6f5823f-e35f-5c1e-8453-d691904607a6', 'Flexiones con manos abiertas', ARRAY['Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros.', 'Mantén el cuerpo en línea recta de la cabeza a los pies.', 'Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.', 'Empuja con las palmas para extender los brazos y regresar a la posición inicial.', 'Repite el número de repeticiones deseado.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros, mejorando la fuerza de empuje y la estabilidad del core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1311'),
('ad30427c-4a01-5394-96e6-8497034cfda9', 'Flexión adelante con piernas muy abiertas', ARRAY['Separa los pies más que el ancho de los hombros y apunta las puntas ligeramente hacia fuera.', 'Inhala, alarga la columna y lleva las manos a las caderas.', 'Exhala y flexiona el tronco desde la cadera, bajando las manos al suelo o a un bloque.', 'Mantén las rodillas ligeramente flexionadas y evita redondear la espalda para forzar la bajada.', 'Respira despacio y aguanta entre 20 y 40 segundos sin rebotar.']::text[], 'principiante', 'Estira isquiotibiales, aductores y gemelos, y descarga la zona lumbar; ideal para ganar flexibilidad tras entrenar piernas.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '0965'),
('5dfd8690-0cf9-5e56-9c00-a7c07a9a4e81', 'Plancha ancha con toque lateral', ARRAY['Colócate en plancha con las manos algo más abiertas que los hombros y el cuerpo en línea recta.', 'Activa el abdomen y los glúteos para evitar que la cadera caiga.', 'Levanta una mano y toca suavemente el hombro contrario sin girar la cadera.', 'Vuelve a apoyar y alterna lados manteniendo la respiración constante.', 'Evita balancear el tronco o subir la cadera para compensar el movimiento.']::text[], 'intermedio', 'Refuerza el core y los oblicuos mientras estabilizas hombros y cadera en una posición isométrica exigente.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '7342'),
('d708fcfe-9ba6-5db9-bbc3-df71f9d09382', 'Flexiones abiertas en pared', ARRAY['Apoya las manos en la pared a la altura de los hombros, más abiertas que estos, y da un paso atrás.', 'Mantén el cuerpo recto y el abdomen activo durante todo el movimiento.', 'Flexiona los codos acercando el pecho a la pared, sin que la cadera se hunda.', 'Empuja para volver a la posición inicial exhalando al empujar.', 'Evita encoger los hombros o bloquear los codos de golpe al extender.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con una versión suave que permite aprender el patrón de empuje sin cargar mucho.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '2740'),
('635bf836-b8d3-51c2-90d2-fcfc5bacc428', 'Dominada sentado con agarre abierto', ARRAY['Siéntate frente a la barra o al soporte con las piernas estiradas y agarra la barra con las manos bien separadas.', 'Inicia el movimiento llevando los omóplatos hacia abajo y atrás antes de flexionar los codos.', 'Tira del cuerpo hacia arriba acercando el pecho a la barra sin encoger el cuello.', 'Baja de forma controlada hasta estirar los brazos del todo.', 'Evita usar impulso de piernas o balancear el tronco para subir.']::text[], 'intermedio', 'Fortalece dorsales, bíceps y agarre con una variante asistida que permite controlar la técnica de tracción vertical.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4806'),
('1f4f4cf1-607d-5c99-a29b-dc3cf8d70935', 'Sentadilla con salto de postura abierta a cerrada', ARRAY['Empieza de pie con los pies juntos y las rodillas ligeramente flexionadas.', 'Salta abriendo los pies a una postura ancha y aterriza amortiguando con las rodillas alineadas.', 'Salta de nuevo para volver a la postura cerrada, cayendo suave sobre las puntas.', 'Mantén el pecho alto y el abdomen activo en cada aterrizaje.', 'Evita caer con las rodillas hacia dentro o aterrizar con las piernas rígidas.']::text[], 'intermedio', 'Desarrolla potencia de piernas y coordinación alternando saltos con pies abiertos y juntos; mejora la explosividad.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5865'),
('ee168374-4d2f-5aa3-8579-e143f253b642', 'Rotación torácica con postura abierta', ARRAY['Colócate de pie con los pies más anchos que los hombros y las rodillas algo flexionadas.', 'Lleva las manos detrás de la cabeza o cruza los brazos delante del pecho.', 'Gira el tronco hacia un lado desde la zona dorsal, sin mover la cadera.', 'Vuelve al centro y repite hacia el otro lado respirando de forma fluida.', 'Evita forzar con la lumbar o girar solo los brazos sin acompañar el tronco.']::text[], 'principiante', 'Mejora la movilidad de la columna dorsal y la rotación del tronco, útil para aliviar tensión y rendir mejor en empujes.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '9246'),
('67fcf0bb-36c8-599c-a9b2-a619a775fd5b', 'Flexión de abierta a cerrada', ARRAY['Colócate en posición de flexión con las manos más abiertas que los hombros.', 'Baja el pecho de forma controlada manteniendo el cuerpo en línea.', 'Al subir, junta las manos para terminar en una flexión cerrada.', 'Vuelve a abrir las manos y repite alternando las posiciones.', 'Evita que la cadera suba o baje durante el cambio de manos.']::text[], 'intermedio', 'Trabaja pectorales, tríceps y hombros con un cambio de agarre que añade control y estabilidad al empuje.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '4807'),
('69fa1725-17d0-5ff5-9b3e-44122d70acb0', 'Sprints', ARRAY['Busca un espacio abierto o una pista para realizar el ejercicio.', 'Comienza de pie con los pies separados a la altura de los hombros.', 'Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas.', 'Continúa el sprint durante una distancia o periodo de tiempo específico.', 'Descansa y repite el número de repeticiones deseado.']::text[], 'intermedio', 'Mejora la capacidad cardiovascular y la potencia de piernas con carreras cortas a máxima intensidad.', ARRAY['Acondicionamiento Metabólico']::text[], 'aerobica', ARRAY['tiempo']::text[], false, true, 7.0, 'cardio', '0858'),
('01717d28-48ee-51ee-8947-d3bea7e55096', 'Limpiaparabrisas con pierna recta', ARRAY['Túmbate boca arriba con las piernas estiradas hacia el techo y los brazos abiertos en cruz.', 'Presiona la zona lumbar contra el suelo activando el abdomen.', 'Baja las piernas rectas hacia un lado sin tocar el suelo.', 'Sube al centro y baja hacia el otro lado de forma lenta y controlada.', 'Evita despegar la lumbar o usar impulso para mover las piernas.']::text[], 'intermedio', 'Fortalece el abdomen y los oblicuos con un movimiento controlado que también exige estabilidad de cadera.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '1249'),
('d7db933f-5f3a-5f71-b07d-cf53417f5798', 'El mejor estiramiento del mundo', ARRAY['Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.', 'Coloca las manos en el suelo a ambos lados de tu pie derecho.', 'Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.', 'Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.', 'Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.', 'Cambia de lado y repite el estiramiento con el pie izquierdo adelante.']::text[], 'principiante', 'Combina movilidad de cadera, isquiotibiales y columna en un solo movimiento para preparar el cuerpo antes de entrenar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1604'),
('091d003d-ac29-5669-8a88-699115b4be90', 'Estiramiento de hombro envolvente', ARRAY['Lleva un brazo cruzado delante del pecho a la altura del hombro.', 'Con la otra mano, agarra el codo o el brazo y llévalo suavemente hacia ti.', 'Mantén el hombro bajo y el cuello relajado mientras respiras despacio.', 'Aguanta entre 20 y 30 segundos y cambia de lado.', 'Evita tirar del codo hacia abajo o encoger el hombro estirado.']::text[], 'principiante', 'Estira el deltoides y la zona posterior del hombro, ayudando a descargar tensión tras empujes o tracciones.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1792'),
('c7135853-cc61-5666-8244-3f47a6eba8dd', 'Abducción de muñeca', ARRAY['Extiende un brazo al frente con la palma hacia abajo.', 'Mueve la mano hacia el lado del pulgar de forma suave y controlada.', 'Mantén el codo estirado y el antebrazo quieto durante el movimiento.', 'Aguanta unos segundos y vuelve al centro antes de repetir.', 'Evita forzar el ángulo o mover el hombro para ganar rango.']::text[], 'principiante', 'Mejora la movilidad de la muñeca y la flexibilidad de los antebrazos, útil antes de empujes y agarres.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '4938'),
('d0dec6fb-0178-5e08-b80e-a67092727220', 'Aducción de muñeca', ARRAY['Extiende un brazo al frente con la palma hacia abajo.', 'Lleva la mano hacia el lado del meñique de forma lenta y controlada.', 'Mantén el codo estirado y el antebrazo estable.', 'Aguanta unos segundos y vuelve al centro antes de repetir.', 'Evita rebotar o forzar el movimiento hasta sentir dolor.']::text[], 'principiante', 'Trabaja la movilidad lateral de la muñeca y la flexibilidad del antebrazo para prevenir molestias en agarres.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2789'),
('c4d4300f-3946-5838-8b0d-bbc698a540e1', 'Círculos de muñeca', ARRAY['Extiende los brazos rectos frente a ti.', 'Cierra ambas manos en un puño.', 'Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.', 'Continúa los círculos de muñeca el número de repeticiones deseado.']::text[], 'principiante', 'Activa y lubrica la articulación de la muñeca y el antebrazo, ideal como calentamiento antes de cargar.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '1428'),
('027dd1a0-cd3d-54b2-b6c9-280e93996bf8', 'Extensión de muñeca', ARRAY['Extiende un brazo al frente con la palma hacia abajo.', 'Lleva la mano hacia arriba doblando la muñeca sin mover el codo.', 'Usa la otra mano para acompañar suavemente el estiramiento.', 'Mantén unos segundos y vuelve despacio a la posición neutra.', 'Evita tirar con fuerza o levantar el hombro para ganar rango.']::text[], 'principiante', 'Mejora la movilidad de la muñeca y estira los flexores del antebrazo, útil tras sesiones de agarre o empuje.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2790'),
('d15c9f5e-89cc-5d6b-a20c-a84fc5856b29', 'Estiramiento de extensores de muñeca', ARRAY['Extiende el brazo hacia delante con la palma hacia el suelo.', 'Con la otra mano, agarra los dedos y flexiona la muñeca hacia abajo suavemente.', 'Mantén la posición entre 20 y 30 segundos sin rebotes.', 'Respira despacio y evita forzar el codo o el hombro.']::text[], 'principiante', 'Relaja la cara externa del antebrazo y alivia la tensión acumulada por escribir o usar el móvil.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '11383'),
('9dbaf985-8026-55d7-b2ac-297b688448e9', 'Flexión de muñeca', ARRAY['Apoya el antebrazo en el muslo con la palma hacia arriba y la mano fuera de la rodilla.', 'Deja caer la mano hacia abajo y luego flexiona la muñeca hacia arriba.', 'Realiza el movimiento lento y controlado, sin balanceos.', 'Evita mover el codo y mantén el antebrazo fijo durante todo el recorrido.']::text[], 'principiante', 'Moviliza la articulación de la muñeca y activa los flexores del antebrazo para ganar rango y control.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'mobility', '2791'),
('a18790e8-3c6b-59e7-af84-9f9d31a0a6b9', 'Estiramiento de flexores de muñeca', ARRAY['Extiende el brazo al frente con la palma hacia arriba.', 'Con la otra mano, tira de los dedos hacia el suelo suavemente.', 'Mantén el estiramiento unos 20 o 30 segundos sin dolor.', 'Respira con calma y evita bloquear el codo.']::text[], 'principiante', 'Estira la cara interna del antebrazo y las manos, útil tras sesiones de agarre o escalada.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1850'),
('f079767d-77df-5208-a404-48c34b7f878d', 'Flexión con muñecas completas', ARRAY['Colócate en plancha alta con las manos a la anchura de los hombros y los dedos abiertos.', 'Baja el pecho flexionando los codos cerca del cuerpo.', 'Empuja el suelo para volver arriba manteniendo el core firme.', 'Evita que la cadera caiga o que los codos se abran en exceso.']::text[], 'intermedio', 'Trabaja pecho, tríceps y hombros mientras exige estabilidad y fuerza a las muñecas y al core.', ARRAY['Fuerza Resistencia', 'Estabilidad y Control Motor']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.8, 'calisthenics', '6982'),
('89a91ffc-d152-570b-ada0-506f8849461c', 'Estiramiento de desviador radial y extensor de muñeca', ARRAY['Extiende el brazo con la palma hacia abajo.', 'Desvía la muñeca hacia el pulgar y flexiona los dedos con la otra mano.', 'Mantén la posición 20 o 30 segundos sin rebotes.', 'Respira de forma relajada y evita forzar el hombro.']::text[], 'principiante', 'Libera tensión en la zona radial del antebrazo y en los extensores, mejorando la movilidad de la muñeca.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1823'),
('e0b96497-e1c8-58c0-a0a3-ddc7ce621983', 'Estiramiento de desviador radial y flexor de muñeca', ARRAY['Extiende el brazo con la palma hacia arriba.', 'Desvía la muñeca hacia el pulgar y tira suavemente de los dedos.', 'Sostén el estiramiento entre 20 y 30 segundos.', 'Evita rebotes y mantén el codo ligeramente flexionado.']::text[], 'principiante', 'Estira la parte radial del antebrazo y los flexores, aliviando la rigidez tras el uso repetido de la mano.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1824'),
('235b2fd8-c63f-562d-a436-48229563f42c', 'Estiramiento de desviador cubital y extensor de muñeca', ARRAY['Extiende el brazo con la palma hacia abajo.', 'Desvía la muñeca hacia el meñique y flexiona los dedos con la otra mano.', 'Mantén la posición 20 o 30 segundos respirando con calma.', 'Evita forzar la articulación y no rebotes.']::text[], 'principiante', 'Relaja la zona cubital del antebrazo y los extensores, mejorando la flexibilidad de la muñeca.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1822'),
('f111ca84-e15a-5f4a-9a25-438faeb72b9a', 'Estiramiento de desviador cubital y flexor de muñeca', ARRAY['Extiende el brazo con la palma hacia arriba.', 'Desvía la muñeca hacia el meñique y tira suavemente de los dedos.', 'Sostén el estiramiento entre 20 y 30 segundos.', 'Mantén el hombro relajado y evita rebotes.']::text[], 'principiante', 'Estira la cara cubital del antebrazo y los flexores, útil para descargar la tensión de la mano.', ARRAY['Movilidad y Flexibilidad']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.3, 'stretching', '1825'),
('4254e138-79af-520c-b2d3-fa0d08842c99', 'Caminata lateral con banda en x', ARRAY['Coloca la banda por encima de las rodillas o en los tobillos, en posición de semiflexión.', 'Da pasos laterales cortos manteniendo la tensión de la banda.', 'Mantén las rodillas alineadas con los pies y el core firme.', 'Evita arrastrar los pies o juntar las rodillas al desplazarte.']::text[], 'principiante', 'Activa glúteo medio y abductores para estabilizar la cadera y prevenir lesiones en carrera.', ARRAY['Hipertrofia Muscular', 'Fuerza Resistencia']::text[], 'fuerza', ARRAY['repeticiones']::text[], false, true, 3.5, 'strength', '2926'),
('2b37483f-de27-5d42-93b4-8a93c5323f24', 'Ejercicio en X', ARRAY['Colócate de pie con una referencia delante y otra detrás en diagonal.', 'Desplázate rápido hacia delante y hacia atrás siguiendo la forma de una X.', 'Mantén las rodillas ligeramente flexionadas y los brazos activos.', 'Evita cruzar los pies de forma descontrolada y aterriza con suavidad.']::text[], 'intermedio', 'Mejora la coordinación y la capacidad cardiovascular con desplazamientos rápidos en diagonal.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '5979'),
('1976feb4-cefd-5cca-90ac-6950b0144a30', 'Postura de vajrasana', ARRAY['Arrodíllate con las rodillas juntas y los pies hacia atrás.', 'Siéntate sobre los talones manteniendo la espalda recta.', 'Apoya las manos en los muslos y respira lento y profundo.', 'Si notas molestia en rodillas o tobillos, coloca una manta o cojín bajo las piernas.']::text[], 'intermedio', 'Mejora la movilidad de tobillos y rodillas y favorece la relajación y la postura sentada.', ARRAY['Movilidad y Flexibilidad', 'Estabilidad y Control Motor']::text[], 'movilidad', ARRAY['tiempo']::text[], false, true, 2.5, 'yoga', '6444'),
('519adac4-282f-560b-977a-6c25a9e5141e', 'Saltos en zigzag', ARRAY['Coloca una línea imaginaria o referencia en zigzag delante de ti.', 'Salta de un lado a otro hacia delante con ambos pies a la vez.', 'Aterriza con las rodillas ligeramente flexionadas y el core activo.', 'Evita aterrizar con las piernas rígidas y mantén un ritmo constante.']::text[], 'intermedio', 'Desarrolla potencia, agilidad y capacidad cardiovascular con saltos laterales rápidos y controlados.', ARRAY['Potencia y Explosividad']::text[], 'metabolica', ARRAY['repeticiones']::text[], false, true, 8.0, 'plyometrics', '3198');

